server <- function(input, output, session) {
  
  # Set future.globals.maxSize to handle large function objects in parallel processing
  options(future.globals.maxSize = 3000 * 1024^2)  # 3000 MiB
  
  # Global UI plot resolution (120 DPI for sharper rendering on larger screens)
  UI_PLOT_RES <- 120

  # ---------------------------------------------------------------------------
  # Core reactive state (must be defined early)
  # ---------------------------------------------------------------------------
  multiomics <- reactiveValues(
    dataset1 = NULL,
    dataset2 = NULL,
    dataset3 = NULL,
    dataset1_samples = NULL,
    dataset2_samples = NULL,
    dataset3_samples = NULL,
    common_samples = NULL,
    sample_groups = NULL,
    sample_metadata = NULL,
    integration_results = NULL,
    model_loaded_from_file = FALSE,  # Track if current model was loaded from file
    loaded_analyses = list(),  # Store loaded saved analyses
    loaded_enrichments = list(),  # Store loaded enrichment results for pathway integration
    external_metadata = list(),  # Store external metadata files
    external_metadata_combined = NULL,  # Combined external metadata
    designated_metadata = NULL,  # Name of designated metadata analysis
    # MOFA-specific values
    mofa_umap = NULL,
    mofa_tsne = NULL,
    factor_names = NULL,
    view_names = NULL,
    pending_loaded_delete = NULL
  )

  saved_analyses <- reactiveValues(
    analyses_list = list(),  # List of saved analysis objects
    counter = 0  # Counter to trigger UI updates
  )

  mofa_metadata <- reactiveValues(
    data = NULL,
    full_metadata = NULL,
    sample_col_name = NA_character_,
    group_col_name = NA_character_,
    group_values = NULL,
    covariates = NULL,
    covariate_names = NULL,
    covariate_types = NULL
  )

  # Reactive values for MOFA tutorial state (CLL dataset)
  mofa_tutorial <- reactiveValues(
    active = FALSE,
    data = NULL,
    metadata = NULL,
    is_tutorial = FALSE,
    mofa_object = NULL,
    trained_model = NULL,
    factors = NULL,
    weights = NULL,
    variance_explained = NULL,
    variance_explained_total = NULL,
    views = NULL,
    common_samples = NULL
  )

  # Reactive values for MOFA clinical predictions
  mofa_predictions <- reactiveValues(
    rf_model = NULL,
    target_variable = NULL,
    predicted_values = NULL,
    prediction_source = NULL,  # "True" or "Predicted" indicator per sample
    factors_used = NULL,
    model_summary = NULL,
    results_df = NULL
  )

  # Helper: recompute common samples + sample metadata from all loaded analyses
  recompute_loaded_analyses_state <- function() {
    if (length(multiomics$loaded_analyses) > 1) {
      all_samples <- lapply(multiomics$loaded_analyses, function(x) x$samples)
      
      # Normalize sample names for comparison (trim whitespace, lowercase for matching)
      # but preserve original names in the result
      normalize_samples <- function(samples) {
        trimws(tolower(as.character(samples)))
      }
      
      # Find common samples using normalized names
      normalized_lists <- lapply(all_samples, normalize_samples)
      common_normalized <- Reduce(intersect, normalized_lists)
      
      # Map back to original names using the first dataset's original sample names
      if (length(common_normalized) > 0) {
        first_normalized <- normalize_samples(all_samples[[1]])
        first_originals <- all_samples[[1]]
        common_samples <- first_originals[match(common_normalized, first_normalized)]
      } else {
        common_samples <- character(0)
      }
      
      multiomics$common_samples <- if (length(common_samples) > 0) common_samples else NULL
    } else {
      multiomics$common_samples <- NULL
    }

    sample_metadata_list <- list()
    for (analysis_name in names(multiomics$loaded_analyses)) {
      analysis <- multiomics$loaded_analyses[[analysis_name]]
      if (!is.null(analysis$groups) && length(analysis$groups) > 0 &&
          !is.null(analysis$samples) && length(analysis$samples) > 0) {
        group_df <- data.frame(SampleID = analysis$samples, stringsAsFactors = FALSE)
        group_col_name <- paste0(analysis_name, "_Group")
        group_df[[group_col_name]] <- analysis$groups
        sample_metadata_list[[analysis_name]] <- group_df
      }
    }

    if (length(sample_metadata_list) == 0) {
      multiomics$sample_metadata <- NULL
      return(invisible(NULL))
    }

    combined_metadata <- sample_metadata_list[[1]]
    if (length(sample_metadata_list) > 1) {
      for (i in 2:length(sample_metadata_list)) {
        combined_metadata <- merge(combined_metadata, sample_metadata_list[[i]],
                                   by = "SampleID", all = TRUE)
      }
    }

    if (!is.null(multiomics$common_samples)) {
      combined_metadata <- combined_metadata[combined_metadata$SampleID %in% multiomics$common_samples, , drop = FALSE]
    }

    rownames(combined_metadata) <- combined_metadata$SampleID
    combined_metadata$SampleID <- NULL
    multiomics$sample_metadata <- combined_metadata

    # Ensure each external metadata file is represented in loaded_analyses so it appears
    # in the Loaded Analyses list (allow users to select it as designated metadata)
    if (!is.null(multiomics$external_metadata) && length(multiomics$external_metadata) > 0) {
      for (meta_key in names(multiomics$external_metadata)) {
        meta_analysis_name <- meta_key
        if (!(meta_analysis_name %in% names(multiomics$loaded_analyses))) {
          md <- multiomics$external_metadata[[meta_key]]
          samples_vec <- if ("SampleID" %in% colnames(md)) as.character(md$SampleID) else if (!is.null(rownames(md)) ) as.character(rownames(md)) else character(0)
          multiomics$loaded_analyses[[meta_analysis_name]] <- list(
            data = NULL,
            samples = samples_vec,
            features = 0,
            cleaned_molecules = NULL,
            accession_ids = NULL,
            omics_type = "metadata",
            groups = NULL,
            group_indices = NULL,
            metadata = md
          )
          # If no designated metadata set yet, default to the first external metadata file
          if (is.null(multiomics$designated_metadata)) {
            multiomics$designated_metadata <- meta_analysis_name
          }
        }
      }
    }

    multiomics$sample_metadata <- combined_metadata
    invisible(NULL)
  }

  # Observe changes to multiomics metadata sources and populate mofa_metadata
  observe({
    # Priority order:
    # 1) mofa_metadata$full_metadata (explicitly set)
    # 2) multiomics$sample_metadata (combined from loaded analyses)
    # 3) multiomics$external_metadata_combined (uploaded metadata files)
    md <- NULL

    if (!is.null(mofa_metadata$full_metadata) && nrow(mofa_metadata$full_metadata) > 0) {
      md <- mofa_metadata$full_metadata
    } else if (!is.null(multiomics$sample_metadata) && nrow(multiomics$sample_metadata) > 0) {
      md <- multiomics$sample_metadata
      # Ensure SampleID column exists
      if (!"SampleID" %in% colnames(md) && !is.null(rownames(md))) md$SampleID <- rownames(md)
    } else if (!is.null(multiomics$external_metadata_combined) && nrow(multiomics$external_metadata_combined) > 0) {
      md <- multiomics$external_metadata_combined
      if (!"SampleID" %in% colnames(md) && !is.null(rownames(md))) md$SampleID <- rownames(md)
    }

    if (!is.null(md) && nrow(md) > 0) {
      # Normalize: ensure SampleID column exists and rownames are set
      if (!"SampleID" %in% colnames(md) && !is.null(rownames(md))) {
        md$SampleID <- rownames(md)
      }
      if (!is.null(md$SampleID)) {
        rownames(md) <- as.character(md$SampleID)
      }

      mofa_metadata$full_metadata <- md
      mofa_metadata$sample_col_name <- "SampleID"
      mofa_metadata$data <- data.frame(SampleID = rownames(md), stringsAsFactors = FALSE)

      # Refresh covariates/groups immediately so all covariate-dependent tabs update
      tryCatch({
        refresh_mofa_metadata_from_selected_columns()
      }, error = function(e) NULL)
    } else {
      mofa_metadata$full_metadata <- NULL
      mofa_metadata$data <- NULL
      mofa_metadata$group_col_name <- NA
      mofa_metadata$group_values <- NULL
      mofa_metadata$covariates <- NULL
      mofa_metadata$covariate_names <- NULL
      mofa_metadata$covariate_types <- NULL
      mofa_metadata$covariate_expansion_map <- list()
    }
  })

  # Observer: when designated metadata changes, refresh MOFA metadata from the new source
  observeEvent(multiomics$designated_metadata, {
    designated_name <- multiomics$designated_metadata
    
    # If no designated metadata, clear MOFA metadata state
    if (is.null(designated_name) || !nzchar(designated_name)) {
      mofa_metadata$full_metadata <- NULL
      mofa_metadata$data <- NULL
      mofa_metadata$group_col_name <- NA
      mofa_metadata$group_values <- NULL
      mofa_metadata$covariates <- NULL
      mofa_metadata$covariate_names <- NULL
      mofa_metadata$covariate_types <- NULL
      mofa_metadata$covariate_expansion_map <- list()
      return()
    }
    
    # Get the metadata from the designated analysis
    if (designated_name %in% names(multiomics$loaded_analyses)) {
      analysis <- multiomics$loaded_analyses[[designated_name]]
      md <- analysis$metadata
      
      if (!is.null(md) && is.data.frame(md) && nrow(md) > 0) {
        # Ensure SampleID column exists
        if (!"SampleID" %in% colnames(md)) {
          if (!is.null(rownames(md)) && !all(rownames(md) == seq_len(nrow(md)))) {
            md$SampleID <- rownames(md)
          } else if (ncol(md) > 0) {
            # Use first column as SampleID if it looks like sample identifiers
            first_col <- names(md)[1]
            if (is.character(md[[first_col]]) || is.factor(md[[first_col]])) {
              md$SampleID <- as.character(md[[first_col]])
            }
          }
        }
        
        # Set rownames from SampleID if available
        if ("SampleID" %in% colnames(md)) {
          rownames(md) <- as.character(md$SampleID)
        }
        
        # Update mofa_metadata with the new metadata
        mofa_metadata$full_metadata <- md
        mofa_metadata$sample_col_name <- "SampleID"
        mofa_metadata$data <- data.frame(SampleID = if ("SampleID" %in% colnames(md)) md$SampleID else rownames(md), stringsAsFactors = FALSE)
        
        # Reset grouping and covariate selections to defaults
        mofa_metadata$group_col_name <- NA
        mofa_metadata$group_values <- NULL
        mofa_metadata$covariates <- NULL
        mofa_metadata$covariate_names <- NULL
        mofa_metadata$covariate_types <- NULL
        mofa_metadata$covariate_expansion_map <- list()
        
        # Reset the column selector inputs to trigger UI refresh
        tryCatch({
          updateSelectInput(session, "mofa_sample_id_col", selected = "SampleID")
          updateSelectInput(session, "mofa_group_col", selected = "")
        }, error = function(e) NULL)
        
        # Refresh metadata-dependent fields
        tryCatch({
          refresh_mofa_metadata_from_selected_columns()
        }, error = function(e) NULL)
        
        showNotification(
          paste0("Metadata source updated to '", designated_name, "'. Group and covariate selections have been reset."),
          type = "message",
          duration = 4
        )
      }
    } else if (designated_name %in% names(multiomics$external_metadata)) {
      # Handle external metadata entries
      md <- multiomics$external_metadata[[designated_name]]
      
      if (!is.null(md) && is.data.frame(md) && nrow(md) > 0) {
        if ("SampleID" %in% colnames(md)) {
          rownames(md) <- as.character(md$SampleID)
        }
        
        mofa_metadata$full_metadata <- md
        mofa_metadata$sample_col_name <- "SampleID"
        mofa_metadata$data <- data.frame(SampleID = if ("SampleID" %in% colnames(md)) md$SampleID else rownames(md), stringsAsFactors = FALSE)
        
        # Reset grouping and covariate selections
        mofa_metadata$group_col_name <- NA
        mofa_metadata$group_values <- NULL
        mofa_metadata$covariates <- NULL
        mofa_metadata$covariate_names <- NULL
        mofa_metadata$covariate_types <- NULL
        mofa_metadata$covariate_expansion_map <- list()
        
        tryCatch({
          updateSelectInput(session, "mofa_sample_id_col", selected = "SampleID")
          updateSelectInput(session, "mofa_group_col", selected = "")
        }, error = function(e) NULL)
        
        tryCatch({
          refresh_mofa_metadata_from_selected_columns()
        }, error = function(e) NULL)
        
        showNotification(
          paste0("Metadata source updated to '", designated_name, "'. Group and covariate selections have been reset."),
          type = "message",
          duration = 4
        )
      }
    }
  }, ignoreNULL = FALSE, ignoreInit = TRUE)

  # Helper: parse a tabular upload (CSV / TSV / XLSX) into a features x samples data frame or detect metadata
  parse_table_file <- function(path, filename) {
    fext <- tolower(tools::file_ext(filename))
    if (fext %in% c("xls", "xlsx")) {
      if (!requireNamespace("readxl", quietly = TRUE)) stop("Package 'readxl' required to read Excel files.")
      df <- as.data.frame(readxl::read_excel(path), stringsAsFactors = FALSE)
    } else {
      df <- utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
    }


    col_lower <- tolower(colnames(df))
    
    # STRICT FILENAME-BASED METADATA DETECTION
    # Check if filename contains 'metadata', 'meta_data', 'meta-data', 'sample_info', 'sampleinfo', etc.
    fname_lower <- tolower(tools::file_path_sans_ext(filename))
    is_metadata_file <- grepl("metadata|meta[_-]?data|sample[_-]?info|sampleinfo|sample[_-]?annotation", fname_lower)
    
    if (is_metadata_file) {
      # Try to find a sample identifier column
      sample_col_idx <- which(grepl("sample[_[:space:]]*id|^sample$|^id$|^name$|^sample[_-]?name$", col_lower, ignore.case = TRUE))
      if (length(sample_col_idx) > 0) {
        names(df)[sample_col_idx[1]] <- "SampleID"
      } else {
        # If no sample column found, use first column as SampleID
        names(df)[1] <- "SampleID"
      }
      return(list(is_metadata = TRUE, metadata = df))
    }

    # Legacy fallback: Detect metadata by column structure (a column named SampleID / sample_id / sample)
    # Only if file doesn't have 'metadata' in name but has proper metadata structure
    if (any(grepl("sample[_[:space:]]*id|^sample$", col_lower, ignore.case = TRUE))) {
      sample_col <- which(grepl("sample[_[:space:]]*id|^sample$", col_lower, ignore.case = TRUE))[1]
      names(df)[sample_col] <- "SampleID"
      return(list(is_metadata = TRUE, metadata = df))
    }

    # Standard assumption for external data files: first column = feature names, remaining columns = samples
    # This works for most omics data (glycomics, proteomics, metabolomics, etc.) where:
    # - Column 1: Feature identifiers (Molecule, Gene, Protein, m/z, etc.)
    # - Columns 2+: Sample data
    if (ncol(df) >= 2) {
      feature_names <- as.character(df[[1]])
      
      # Handle duplicate feature names
      if (any(duplicated(feature_names))) {
        feature_names <- make.unique(feature_names, sep = "_")
      }
      
      # Extract remaining columns as samples
      data_part <- df[, -1, drop = FALSE]
      
      # Try to coerce to numeric
      data_numeric <- tryCatch({
        as.data.frame(lapply(data_part, function(x) as.numeric(as.character(x))), 
                      stringsAsFactors = FALSE, check.names = FALSE)
      }, warning = function(w) {
        # If coercion produces NAs, it might not be a data matrix - return NULL to try other interpretations
        NULL
      }, error = function(e) {
        NULL
      })
      
      # Check if coercion produced a valid numeric matrix (allow some NAs from coercion but not too many)
      if (!is.null(data_numeric) && ncol(data_numeric) > 0) {
        total_cells <- nrow(data_numeric) * ncol(data_numeric)
        na_count <- sum(is.na(data_numeric))
        na_ratio <- na_count / total_cells
        
        # If less than 20% NAs (allowing for some missing data), treat as valid data matrix
        if (na_ratio < 0.2) {
          samples <- trimws(colnames(data_numeric))  # Normalize: trim whitespace
          features <- feature_names
          colnames(data_numeric) <- samples  # Update colnames to match normalized samples
          return(list(is_metadata = FALSE, data = data_numeric, samples = samples, features = features))
        }
      }
    }

    # Fallback: Try to interpret as data matrix without assuming first column is features
    # Case A: first column = feature names (non-numeric text), rest numeric
    if (ncol(df) >= 2 && !all(suppressWarnings(!is.na(as.numeric(as.character(df[[1]]))))) && all(sapply(df[-1], function(col) all(!is.na(suppressWarnings(as.numeric(as.character(col)))))))) {
      rownames(df) <- df[[1]]
      df <- df[,-1, drop = FALSE]
      data_mat <- as.data.frame(lapply(df, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE, check.names = FALSE)
      samples <- trimws(colnames(data_mat))  # Normalize: trim whitespace
      features <- rownames(data_mat)
      colnames(data_mat) <- samples  # Update colnames to match normalized samples
      return(list(is_metadata = FALSE, data = data_mat, samples = samples, features = features))
    }

    # Case B: all columns numeric -> columns are samples
    if (all(sapply(df, is.numeric))) {
      if (is.null(rownames(df)) || all(rownames(df) == "")) rownames(df) <- paste0("Feature_", seq_len(nrow(df)))
      data_mat <- as.data.frame(df, check.names = FALSE)
      samples <- trimws(colnames(data_mat))  # Normalize: trim whitespace
      features <- rownames(data_mat)
      data_mat <- as.data.frame(lapply(data_mat, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE, check.names = FALSE)
      colnames(data_mat) <- samples  # Update colnames to match normalized samples
      return(list(is_metadata = FALSE, data = data_mat, samples = samples, features = features))
    }

    # Case C: first column samples, numeric columns follow -> transpose
    if (ncol(df) >= 2 && any(sapply(df[-1], function(col) all(!is.na(suppressWarnings(as.numeric(as.character(col)))))))) {
      sample_ids <- trimws(as.character(df[[1]]))  # Normalize: trim whitespace
      numpart <- as.data.frame(df[,-1, drop = FALSE], stringsAsFactors = FALSE)
      numpart <- as.data.frame(lapply(numpart, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE)
      df_t <- as.data.frame(t(numpart), stringsAsFactors = FALSE)
      colnames(df_t) <- sample_ids
      if (is.null(rownames(df_t)) || all(rownames(df_t) == "")) rownames(df_t) <- paste0("Feature_", seq_len(nrow(df_t)))
      return(list(is_metadata = FALSE, data = df_t, samples = colnames(df_t), features = rownames(df_t)))
    }

    # Default: assume features in rows, samples in columns, try to parse
    if (ncol(df) >= 2) {
      # If first column looks like feature names (not all numeric), use it as rownames
      if (!all(suppressWarnings(!is.na(as.numeric(as.character(df[[1]])))))) {
        rownames(df) <- df[[1]]
        df <- df[,-1, drop = FALSE]
      }
      # Coerce all to numeric
      data_mat <- as.data.frame(lapply(df, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE, check.names = FALSE)
      samples <- trimws(colnames(data_mat))  # Normalize: trim whitespace
      features <- rownames(data_mat)
      if (is.null(features) || all(features == "")) {
        features <- paste0("Feature_", seq_len(nrow(data_mat)))
        rownames(data_mat) <- features
      }
      colnames(data_mat) <- samples  # Update colnames to match normalized samples
      return(list(is_metadata = FALSE, data = data_mat, samples = samples, features = features))
    }

    stop("Unable to interpret tabular file: ", filename)
  }
  
  # OPTIMIZATION #8: Initialize session-persistent metabolite cache
  # ============================================================================
  # Cache is stored in SQLite (metabolites.db) and automatically persists across app restarts
  # On startup, ensure database schema is created and indexed
  tryCatch({
    if (file.exists("metabolites.db")) {
      con <- DBI::dbConnect(RSQLite::SQLite(), "metabolites.db")
      
      # Verify cache table exists with proper schema
      existing_tables <- DBI::dbListTables(con)
      if ("cached_mappings" %in% existing_tables) {
        # Cache exists - it will be loaded on-demand when needed
        existing_rows <- DBI::dbGetQuery(con, "SELECT COUNT(*) as n FROM cached_mappings")$n
        if (is_omics_verbose()) {
          message(sprintf("[CACHE-INIT] Session startup: Found %d cached metabolite mappings", existing_rows))
        }
      } else {
        # Cache table doesn't exist yet - will be created on first metabolite resolution
        if (is_omics_verbose()) message("[CACHE-INIT] Session startup: Cache table will be created on first use")
      }
      
      # Ensure database indexes are in place for performance
      create_metabolite_indexes()
      
      DBI::dbDisconnect(con)
    }
  }, error = function(e) {
    message(sprintf("[CACHE-INIT] Warning: Could not initialize cache on startup: %s", e$message))
  })
  
  # ============================================================================
  # LOAD MODEL FUNCTIONALITY
  # ============================================================================
  
  # Load MOFA Model
  observeEvent(input$load_model_btn, {
    req(input$load_model_file)
    
    # Get the file path
    file_path <- input$load_model_file$datapath
    file_name <- input$load_model_file$name
    
    tryCatch({
      # Determine file type and load accordingly
      if (grepl("\\.rds$", file_name, ignore.case = TRUE)) {
        # Load RDS file
        loaded_model <- readRDS(file_path)
        
        # Validate the loaded model structure
        if (!is.list(loaded_model) || !("method" %in% names(loaded_model))) {
          stop("Invalid model file: missing required 'method' field")
        }
        
        if (loaded_model$method != "mofa") {
          stop("This RDS file does not contain a MOFA model")
        }
        
        # Set the integration results
        multiomics$integration_results <- loaded_model
        multiomics$model_loaded_from_file <- TRUE
        
        showNotification(
          paste("✓ MOFA model loaded successfully from", file_name),
          type = "message",
          duration = 5
        )
        
      } else if (grepl("\\.hdf5$", file_name, ignore.case = TRUE)) {
        # Load HDF5 file (MOFA only)
        if (!requireNamespace("MOFA2", quietly = TRUE)) {
          stop("MOFA2 package required to load HDF5 files")
        }
        
        # Load the MOFA model from HDF5
        mofa_model <- MOFA2::load_model(file_path)
        
        # Create integration results structure
        multiomics$integration_results <- list(
          method = "mofa",
          model = mofa_model,
          factors = MOFA2::get_factors(mofa_model, factors = "all")[[1]],
          variance_explained = MOFA2::get_variance_explained(mofa_model)$r2_per_factor,
          weights = MOFA2::get_weights(mofa_model, factors = "all"),
          views = MOFA2::views_names(mofa_model),
          common_samples = MOFA2::samples_names(mofa_model)
        )
        multiomics$model_loaded_from_file <- TRUE
        
        showNotification(
          paste("✓ MOFA model loaded successfully from", file_name),
          type = "message",
          duration = 5
        )
        
      } else {
        stop("Unsupported file format. Please select an .rds or .hdf5 file")
      }
      
    }, error = function(e) {
      showNotification(
        paste("Error loading model:", e$message),
        type = "error",
        duration = 8
      )
    })
  })
  
  # Load DIABLO Model
  observeEvent(input$load_diablo_model_btn, {
    req(input$load_diablo_model_file)
    
    # Get the file path
    file_path <- input$load_diablo_model_file$datapath
    file_name <- input$load_diablo_model_file$name
    
    tryCatch({
      # Load RDS file
      if (!grepl("\\.rds$", file_name, ignore.case = TRUE)) {
        stop("DIABLO models must be in RDS format")
      }
      
      loaded_model <- readRDS(file_path)
      
      # Validate the loaded model structure
      if (!is.list(loaded_model) || !("method" %in% names(loaded_model))) {
        stop("Invalid model file: missing required 'method' field")
      }
      
      if (loaded_model$method != "diablo") {
        stop("This RDS file does not contain a DIABLO model")
      }
      
      # Set the integration results
      multiomics$integration_results <- loaded_model
      multiomics$model_loaded_from_file <- TRUE
      
      showNotification(
        paste("✓ DIABLO model loaded successfully from", file_name),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(
        paste("Error loading DIABLO model:", e$message),
        type = "error",
        duration = 8
      )
    })
  })
  
  # Load Model Status UI
  output$load_model_status <- renderUI({
    req(multiomics$integration_results, multiomics$model_loaded_from_file)
    result <- multiomics$integration_results
    
    status_text <- switch(result$method,
                          mofa = "✓ MOFA model loaded successfully. Ready for analysis.",
                          diablo = "✓ DIABLO model loaded successfully. Ready for analysis.",
                          "Model loaded successfully."
    )
    
    div(style = "padding: 10px; background-color: var(--success-light); border-left: 4px solid var(--success-color); border-radius: 4px;",
