  # ANOVA Covariate Selection UI (shown when checkbox is checked)
  output$anova_covariate_selection_ui <- renderUI({
    sig_method <- input$sig_method %||% "wilcox"
    if (sig_method != "anova") return(NULL)
    if (!isTRUE(input$anova_include_covariates)) return(NULL)
    
