    sample_id_patterns <- c("^sampleid$", "^sample_id$", "^sample$", "^id$", "^rowname")
    exclude_mask <- sapply(tolower(meta_cols), function(col) {
      any(sapply(sample_id_patterns, function(pattern) grepl(pattern, col)))
    })
    
    # Also exclude _Group columns (following MOFA pattern)
    group_suffix_cols <- grep("_Group$", meta_cols, value = TRUE)
    exclude_mask <- exclude_mask | (meta_cols %in% group_suffix_cols)
    
    available_cols <- meta_cols[!exclude_mask]
    
    if (length(available_cols) == 0) {
      return(
        div(class = "alert alert-warning", style = "margin-top: 10px; padding: 10px;",
