      showNotification("Loading test data...", type = "message")
      
      # Mock the file upload input structure
      tmp_path <- tempfile(fileext = ".xlsx")
      file.copy(test_data_path, tmp_path)
      
      mock_file <- data.frame(
        name = "Time_Series_Test_Data_500_Features.xlsx",
        size = file.info(test_data_path)$size,
        type = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        datapath = tmp_path,
        stringsAsFactors = FALSE
      )
      
      current_data_file(mock_file)
      showNotification("Test data loaded successfully!", type = "message")
    } else {
      showNotification("Test data file not found.", type = "error")
    }
  })
  
