    }
  })
  
  # ============================================================================
  
  # Resolve a valid DPI value from the global input, falling back if the input is missing or invalid.
  get_safe_global_dpi <- function(default = 300) {
    dpi_val <- suppressWarnings(as.numeric(input$global_dpi))
    if (length(dpi_val) == 0 || is.na(dpi_val) || !is.finite(dpi_val) || dpi_val <= 0) {
      return(default)
    }
    dpi_val
  }
  
  # Resolve a valid image format from the global input, falling back if the input is missing or invalid.
  get_safe_global_image_format <- function(default = "png") {
    format_val <- input$global_image_format
    if (length(format_val) == 0 || is.na(format_val) || !(format_val %in% c("png", "svg"))) {
      return(default)
    }
    format_val
  }
  
  # Helper: resolve device for ggsave; prefer svglite when saving SVGs, fall back to grDevices::svg
  resolve_ggsave_device <- function(image_format) {
    if (missing(image_format) || is.null(image_format)) stop("image_format is required")
    image_format <- tolower(image_format)
    if (image_format == "svg") {
      # If svglite is available, use it for better SVG output; otherwise use base svg()
      if (requireNamespace("svglite", quietly = TRUE)) {
        return(svglite::svglite)
      } else {
        return(grDevices::svg)
      }
    }
    # For other formats, return the string so ggsave uses its internal device
    return(image_format)
  }

  # Helper: get the current UI output size for a plotOutput (in pixels).
  # This lets downloads match what the user sees (size + relative text scaling).
  get_ui_plot_dimensions_px <- function(session, output_id, default_width = 1000, default_height = 700) {
    if (missing(session) || is.null(session)) {
      return(list(width = default_width, height = default_height))
    }
    key_w <- paste0("output_", output_id, "_width")
    key_h <- paste0("output_", output_id, "_height")
    w <- suppressWarnings(as.numeric(session$clientData[[key_w]]))
    h <- suppressWarnings(as.numeric(session$clientData[[key_h]]))
    if (length(w) == 0 || is.na(w) || !is.finite(w) || w <= 0) w <- default_width
    if (length(h) == 0 || is.na(h) || !is.finite(h) || h <= 0) h <- default_height
    list(width = w, height = h)
  }

  # Helper: save a ggplot to disk using the same pixel dimensions Shiny uses in the UI.
  # For PNG, we use Cairo (like Shiny) for better rendering; fallback to base R.
  # For SVG, use svglite for better output.
  save_plot_like_ui <- function(plot_obj, file, session, output_id) {
    if (is.null(plot_obj)) return(invisible(NULL))
    dims <- get_ui_plot_dimensions_px(session, output_id)
    image_format <- get_safe_global_image_format()
    dpi <- get_safe_global_dpi()

    if (tolower(image_format) == "png") {
      # Use Cairo for PNG to match Shiny's renderPlot quality
      scale_factor <- dpi / 72
      width_px <- max(1, round(dims$width * scale_factor))
      height_px <- max(1, round(dims$height * scale_factor))
      if (requireNamespace("Cairo", quietly = TRUE)) {
        Cairo::CairoPNG(filename = file, width = width_px, height = height_px, res = dpi)
      } else {
        grDevices::png(filename = file, width = width_px, height = height_px, res = dpi)
      }
      on.exit(grDevices::dev.off(), add = TRUE)
      print(plot_obj)
      return(invisible(NULL))
    }

    # SVG: approximate UI size by converting pixels -> inches at 72 dpi.
    w_in <- dims$width / 72
    h_in <- dims$height / 72
    ggsave(
      filename = file,
      plot = plot_obj,
      device = resolve_ggsave_device("svg"),
      width = w_in,
      height = h_in,
      units = "in"
    )
    invisible(NULL)
  }

  # MOFA helper: mitigate slight text clipping on PNG devices by increasing lineheight and margins.
  mofa_text_fix_theme <- function() {
    ggplot2::theme(
      text = ggplot2::element_text(lineheight = 1.12),
      axis.text = ggplot2::element_text(lineheight = 1.12),
      legend.text = ggplot2::element_text(lineheight = 1.12),
      plot.margin = ggplot2::margin(6, 6, 6, 6)
    )
  }

  apply_mofa_text_fix <- function(p) {
    if (is.null(p)) return(p)
    if (inherits(p, "patchwork")) {
      return(p & mofa_text_fix_theme())
    }
    if (inherits(p, "ggplot")) {
      return(p + mofa_text_fix_theme())
    }
    p
  }

  # MOFA helper: normalize label whitespace (including non-breaking spaces) for robust matching.
  normalize_mofa_label <- function(x) {
    if (is.null(x)) return(x)
    x <- as.character(x)
    # Replace NBSP with regular space, then trim and collapse whitespace
    x <- gsub("\u00A0", " ", x, fixed = TRUE)
    x <- trimws(x)
    x <- gsub("\\s+", " ", x)
    x
  }

  # MOFA helper: escape a string for safe use in regex patterns.
  escape_regex <- function(x) {
    if (is.null(x)) return(x)
    x <- as.character(x)
    gsub("([][{}()+*^$|\\\\.?])", "\\\\\\\\1", x)
  }

  # MOFA helper: strip a trailing view suffix like "_CSF GPs" / "_CSF_GPs" from feature labels.
  # Uses the actual view names (and a couple of safe variants) rather than broad regex.
  strip_mofa_view_suffix <- function(labels, views) {
    labels <- normalize_mofa_label(labels)
    if (is.null(labels) || length(labels) == 0) return(labels)
    if (is.null(views) || length(views) == 0) return(labels)

    out <- labels
    views <- normalize_mofa_label(views)
    views <- views[!is.na(views) & views != ""]
    if (length(views) == 0) return(out)

    # Longest-first to avoid partial stripping when one view name is a suffix of another
    views <- views[order(nchar(views), decreasing = TRUE)]

    for (v in views) {
      v_space <- v
      v_us <- gsub("\\s+", "_", v)
      v_sanitized <- gsub("[^A-Za-z0-9]+", "_", v)

      candidates <- unique(c(v_space, v_us, v_sanitized))
      candidates <- candidates[!is.na(candidates) & candidates != ""]
      for (cand in candidates) {
        pat <- paste0("_", escape_regex(cand), "\\s*$")
        out <- gsub(pat, "", out, ignore.case = TRUE)
      }
    }

    # Cleanup leftovers after stripping
    out <- gsub("_+$", "", out)
    out <- trimws(out)
    out
  }

  # MOFA helper: update ggrepel labels in a plot by applying an optional mapping and stripping view suffixes.
  # Handles both geom_text_repel and geom_label_repel, and edits label text wherever it lives (layer$data or plot$data).
  strip_ggrepel_text_labels <- function(plot, views, mapping = NULL) {
    if (is.null(plot) || is.null(plot$layers)) return(plot)
    if (is.null(views) || length(views) == 0) return(plot)

    remap_labels <- function(x) {
      if (is.null(x)) return(x)
      x_chr <- as.character(x)
      if (!is.null(mapping) && length(mapping) > 0) {
        x_chr <- ifelse(x_chr %in% names(mapping), as.character(mapping[x_chr]), x_chr)
      }
      strip_mofa_view_suffix(x_chr, views)
    }

    is_repel_geom <- function(geom_obj) {
      if (is.null(geom_obj)) return(FALSE)
      inherits(geom_obj, "GeomTextRepel") || inherits(geom_obj, "GeomLabelRepel") || any(grepl("Repel", class(geom_obj)))
    }

    clean_df_cols <- function(df) {
      if (is.null(df) || !is.data.frame(df)) return(df)
      candidate_cols <- intersect(c("label", "Label", "feature", "Feature", "name"), colnames(df))
      for (cn in candidate_cols) {
        if (is.character(df[[cn]]) || is.factor(df[[cn]])) {
          df[[cn]] <- remap_labels(df[[cn]])
        }
      }
      df
    }

    for (i in seq_along(plot$layers)) {
      layer <- plot$layers[[i]]
      if (!is_repel_geom(layer$geom)) next

      # 1) If the repel layer has its own data, clean it.
      if (!is.null(layer$data) && is.data.frame(layer$data)) {
        plot$layers[[i]]$data <- clean_df_cols(layer$data)
      }

      # 2) If the layer maps label to a variable, clean that variable in the appropriate data.
      if (!is.null(layer$mapping) && !is.null(layer$mapping$label)) {
        label_expr <- as.character(layer$mapping$label)[1]
        label_var <- trimws(gsub("^~", "", label_expr))
        label_var <- gsub("`", "", label_var)

        if (!is.null(layer$data) && is.data.frame(layer$data) && label_var %in% colnames(layer$data)) {
          plot$layers[[i]]$data[[label_var]] <- remap_labels(layer$data[[label_var]])
        } else if (!is.null(plot$data) && is.data.frame(plot$data) && label_var %in% colnames(plot$data)) {
          plot$data[[label_var]] <- remap_labels(plot$data[[label_var]])
        }
      }
    }

    # As a final fallback, clean the plot-level data if it already contains a label column.
    if (!is.null(plot$data) && is.data.frame(plot$data)) {
      plot$data <- clean_df_cols(plot$data)
    }

    plot
  }
  
