  # Helper function to generate the grouping level toggle UI
  # This can be called from renderUI outputs in different tabs
  generate_grouping_level_toggle_ui <- function(id_prefix = "main") {
    # Only show if dual grouping is active
    if (!isTRUE(values$has_dual_grouping)) {
      return(NULL)
    }
    
    # Get current active level
    active_level <- values$active_grouping_level %||% "biological"
    
    # Get group counts for info display
    bio_count <- length(values$biological_unique_groups %||% character(0))
    exp_count <- length(values$experimental_unique_groups %||% character(0))
    
    div(
      class = "grouping-level-toggle-container",
      id = paste0(id_prefix, "_grouping_toggle"),
      
      span(class = "grouping-level-toggle-label",
           icon("layer-group"), "View Results By:"),
      
      div(class = "grouping-level-btn-group",
          
          # Biological Groups Button
          tags$button(
            id = paste0(id_prefix, "_btn_biological"),
            class = paste("grouping-level-btn biological", 
                          if(active_level == "biological") "active" else ""),
            onclick = sprintf("Shiny.setInputValue('%s_grouping_level', 'biological', {priority: 'event'})", id_prefix),
            icon("dna"), "Biological Groups"
          ),
          
          # Experimental Groups Button  
          tags$button(
            id = paste0(id_prefix, "_btn_experimental"),
            class = paste("grouping-level-btn experimental",
                          if(active_level == "experimental") "active" else ""),
            onclick = sprintf("Shiny.setInputValue('%s_grouping_level', 'experimental', {priority: 'event'})", id_prefix),
            icon("flask"), "Experimental Groups"
          )
      ),
      
      span(class = "grouping-level-info",
           icon("info-circle"),
           if(active_level == "biological") {
             paste0("Showing ", bio_count, " biological group(s)")
           } else {
             paste0("Showing ", exp_count, " experimental group(s)")
           }
      )
    )
  }
  
