  # ============================================================================
  # GROUPING LEVEL SWITCH OBSERVER
  # ============================================================================
  # When active_grouping_level changes and dual grouping is active,
  # swap the main reactive values to point to the appropriate level's data.
  # This ensures all existing visualization code works without modification.
  
  observeEvent(values$active_grouping_level, {
    if (!isTRUE(values$has_dual_grouping)) return()
    
    level <- values$active_grouping_level
    
    message("Updating main reactive values for grouping level: ", level)
    
    # Clear dimension reduction caches when grouping level changes
    values$pca_cache <- list()
    values$spca_cache <- list()
    values$pca_result <- NULL
    values$spca_result <- NULL
    
    if (level == "biological") {
      # Switch to biological grouping data
      if (!is.null(values$biological_unique_groups)) {
        values$unique_groups <- values$biological_unique_groups
      }
      if (!is.null(values$biological_group_column_indices)) {
        values$group_column_indices <- values$biological_group_column_indices
      }
      if (!is.null(values$biological_stat_results)) {
        values$stat_results <- values$biological_stat_results
      }
      if (!is.null(values$biological_pairwise_combinations)) {
        values$current_pairwise_combinations <- values$biological_pairwise_combinations
      }
      
      # Update UI group selectors
      if (!is.null(values$biological_unique_groups)) {
        bio_groups <- values$biological_unique_groups
        updateSelectizeInput(session, "group1", choices = bio_groups, selected = bio_groups[1])
        updateSelectizeInput(session, "group2", choices = bio_groups, 
                             selected = if(length(bio_groups) > 1) bio_groups[2] else bio_groups[1])
        updateSelectizeInput(session, "diffGroup1", choices = bio_groups, selected = bio_groups[1])
        updateSelectizeInput(session, "diffGroup2", choices = bio_groups,
                             selected = if(length(bio_groups) > 1) bio_groups[2] else bio_groups[1])
        updateSelectizeInput(session, "pcaGroup1", choices = bio_groups, selected = bio_groups[1])
        updateSelectizeInput(session, "pcaGroup2", choices = bio_groups,
                             selected = if(length(bio_groups) > 1) bio_groups[2] else bio_groups[1])
      }
      
      showNotification("Switched to Biological Groups view", type = "message", duration = 2)
      
    } else if (level == "experimental") {
      # Switch to experimental grouping data
      message("=== SWITCHING TO EXPERIMENTAL ===")
      message("  experimental_unique_groups: ", 
              if(is.null(values$experimental_unique_groups)) "NULL" else paste(values$experimental_unique_groups, collapse=", "))
      message("  experimental_stat_results: ", 
              if(is.null(values$experimental_stat_results)) "NULL" else paste(nrow(values$experimental_stat_results), "rows"))
      
      if (!is.null(values$experimental_unique_groups)) {
        values$unique_groups <- values$experimental_unique_groups
        values$unique_groups_original <- values$experimental_unique_groups  # Update original for pairwise generation
      }
      if (!is.null(values$experimental_group_column_indices)) {
        values$group_column_indices <- values$experimental_group_column_indices
      }
      if (!is.null(values$experimental_stat_results) &&
          !is_valid_stat_results(values$experimental_stat_results)) {
        message("  experimental_stat_results present but incomplete - discarding")
        values$experimental_stat_results <- NULL
      }
      if (!is.null(values$experimental_stat_results)) {
        values$stat_results <- values$experimental_stat_results
        message("  stat_results now has ", nrow(values$stat_results), " rows")
        message("  experimental stat_results columns: ", paste(colnames(values$experimental_stat_results), collapse=", "))
      } else {
        message("  WARNING: experimental_stat_results is NULL - do NOT update stat_results yet")
        message("  Experimental analysis will populate it during re-run")
        # Experimental analysis hasn't run yet - trigger it now
        if (!isTRUE(values$dual_analysis_in_progress)) {
          showNotification("Experimental grouping analysis not yet complete. Running now...", type = "warning", duration = 3)
          values$dual_analysis_in_progress <- TRUE
          values$dual_analysis_current_level <- "experimental"
          
          # Ensure experimental grouping values are set
          if (!is.null(values$experimental_unique_groups)) {
            values$unique_groups <- values$experimental_unique_groups
            values$unique_groups_original <- values$experimental_unique_groups
          }
          if (!is.null(values$experimental_group_column_indices)) {
            values$group_column_indices <- values$experimental_group_column_indices
          }
          if (!is.null(values$experimental_pairwise_combinations)) {
            values$current_pairwise_combinations <- values$experimental_pairwise_combinations
          }
          
          # Trigger re-analysis
          shinyjs::delay(200, {
            shinyjs::click("processBtn")
          })
          return()  # Exit early - don't show "switched" notification yet
        } else {
          showNotification("Experimental analysis is currently running. Please wait...", type = "message", duration = 3)
          return()
        }
      }
      if (!is.null(values$experimental_pairwise_combinations)) {
        values$current_pairwise_combinations <- values$experimental_pairwise_combinations
        message("  set current_pairwise_combinations to experimental: ", nrow(values$experimental_pairwise_combinations), " rows")
      } else {
        message("  experimental_pairwise_combinations is NULL, keeping current")
      }
      
      # Update UI group selectors
      if (!is.null(values$experimental_unique_groups)) {
        exp_groups <- values$experimental_unique_groups
        updateSelectizeInput(session, "group1", choices = exp_groups, selected = exp_groups[1])
        updateSelectizeInput(session, "group2", choices = exp_groups, 
                             selected = if(length(exp_groups) > 1) exp_groups[2] else exp_groups[1])
        updateSelectizeInput(session, "diffGroup1", choices = exp_groups, selected = exp_groups[1])
        updateSelectizeInput(session, "diffGroup2", choices = exp_groups,
                             selected = if(length(exp_groups) > 1) exp_groups[2] else exp_groups[1])
        updateSelectizeInput(session, "pcaGroup1", choices = exp_groups, selected = exp_groups[1])
        updateSelectizeInput(session, "pcaGroup2", choices = exp_groups,
                             selected = if(length(exp_groups) > 1) exp_groups[2] else exp_groups[1])
      }
      
      showNotification("Switched to Experimental Groups view", type = "message", duration = 2)
    }
  }, ignoreInit = TRUE)
  # ============================================================================
  # END GROUPING LEVEL SWITCH OBSERVER
  # ============================================================================
  
  # Helper function to get the current stat_results based on active grouping level
  # When dual grouping is active, each view must show only its own level's results;
  # the experimental stats table must never show biological results and vice versa.
  get_active_stat_results <- function() {
    if (!isTRUE(values$has_dual_grouping)) {
      return(values$stat_results)
    }
    
    if (values$active_grouping_level == "biological") {
      # Biological view: show only biological stat results
      if (!is.null(values$biological_stat_results) && is_valid_stat_results(values$biological_stat_results)) {
        return(values$biological_stat_results)
      }
      return(values$biological_stat_results %||% values$stat_results)
    } else {
      # Experimental view: show only experimental stat results; never fall back to
      # values$stat_results (which may hold biological data) so the experimental
      # stats table is never populated with biological results.
      if (!is.null(values$experimental_stat_results) && is_valid_stat_results(values$experimental_stat_results)) {
        return(values$experimental_stat_results)
      }
      return(data.frame(
        Feature = "(No data)",
        Info = "Experimental group statistics will appear here after you process data.",
        stringsAsFactors = FALSE
      ))
    }
  }
  
  # Helper function to get the current unique_groups based on active grouping level
  get_active_unique_groups <- function() {
    if (!isTRUE(values$has_dual_grouping)) {
      return(values$unique_groups)
    }
    
    if (values$active_grouping_level == "biological") {
      return(values$biological_unique_groups %||% values$unique_groups)
    } else {
      return(values$experimental_unique_groups %||% values$unique_groups)
    }
  }
  
  # Helper function to get the current group_column_indices based on active grouping level
  get_active_group_column_indices <- function() {
    if (!isTRUE(values$has_dual_grouping)) {
      return(values$group_column_indices)
    }
    
    if (values$active_grouping_level == "biological") {
      return(values$biological_group_column_indices %||% values$group_column_indices)
    } else {
      return(values$experimental_group_column_indices %||% values$group_column_indices)
    }
  }
  
  # Helper function to get the current pairwise_combinations based on active grouping level
  get_active_pairwise_combinations <- function() {
    if (!isTRUE(values$has_dual_grouping)) {
      return(values$current_pairwise_combinations)
    }
    
    if (values$active_grouping_level == "biological") {
