  # ============================================================================
  # DUAL GROUPING RE-ANALYSIS OBSERVER
  # ============================================================================
  # This observer triggers re-analysis when dual grouping requires a second pass
  # OR when the user requests re-analysis from the review modal
  observeEvent(values$dual_analysis_trigger_rerun, {
    message("=== DUAL ANALYSIS TRIGGER FIRED ===")
    message("  dual_analysis_trigger_rerun value: ", values$dual_analysis_trigger_rerun)
    message("  has_dual_grouping: ", values$has_dual_grouping)
    message("  dual_analysis_current_level: ", values$dual_analysis_current_level)
    message("  dual_analysis_in_progress: ", values$dual_analysis_in_progress)
    
    req(values$dual_analysis_trigger_rerun)
    req(isTRUE(values$has_dual_grouping))
    
    # CRITICAL: Prevent infinite loops - don't trigger if both analyses are already complete
    bio_complete <- !is.null(values$biological_stat_results) && 
                    is_valid_stat_results(values$biological_stat_results)
    exp_complete <- !is.null(values$experimental_stat_results) && 
                    is_valid_stat_results(values$experimental_stat_results)
    
    if (bio_complete && exp_complete && is.null(values$dual_analysis_current_level)) {
      message("=== SKIPPING TRIGGER: Both analyses already complete ===")
      values$dual_analysis_trigger_rerun <- NULL  # Clear trigger
      return()
    }
    
    current_level <- values$dual_analysis_current_level
    
    # CRITICAL: Only proceed if we have a valid current_level
    if (is.null(current_level)) {
      message("=== SKIPPING TRIGGER: current_level is NULL ===")
      values$dual_analysis_trigger_rerun <- NULL  # Clear trigger
      return()
    }
    
    # Small delay to allow UI to update
    shinyjs::delay(200, {
      message("=== INSIDE DELAY - About to click processBtn for ", current_level, " ===")
      # Double-check that we're still in a valid state before triggering
      if (isTRUE(values$dual_analysis_in_progress) && 
          !identical(current_level, values$dual_analysis_current_level)) {
        message("=== SKIPPING CLICK: State changed during delay ===")
        return()
      }
      
      if (current_level == "biological") {
        # First pass for biological level - trigger by clicking process button
        message("=== DUAL ANALYSIS RE-RUN: Starting biological level ===")
        shinyjs::click("processBtn")
      } else if (current_level == "experimental") {
        # Second pass for experimental level
        message("=== DUAL ANALYSIS RE-RUN: Starting experimental level ===")
        shinyjs::click("processBtn")
      } else {
        message("=== WARNING: current_level is neither biological nor experimental: ", current_level)
        values$dual_analysis_trigger_rerun <- NULL  # Clear invalid trigger
      }
    })
  }, ignoreInit = TRUE, ignoreNULL = TRUE)
  # ============================================================================
  # END DUAL GROUPING RE-ANALYSIS OBSERVER
  # ============================================================================
  
  # ============================================================================
  # DUAL ANALYSIS CACHE FUNCTIONS
  # ============================================================================
  # Generate cache key for dual analysis based on data and parameters
  generate_dual_analysis_cache_key <- function(grouping_level) {
    # Create a signature based on:
    # - Data signature (normalized_data)
    # - Analysis method (sig_method)
    # - Grouping level
    # - Unique groups for this level
    # - Pairwise combinations
    
    data_sig <- tryCatch({
      if (!is.null(values$normalized_data)) {
        digest::digest(values$normalized_data, algo = "xxhash64")
      } else {
        "no_data"
      }
    }, error = function(e) "error")
    
    method_sig <- input$sig_method %||% "none"
    
    groups_sig <- tryCatch({
      if (grouping_level == "biological") {
        digest::digest(values$biological_unique_groups, algo = "xxhash64")
      } else {
        digest::digest(values$experimental_unique_groups, algo = "xxhash64")
      }
    }, error = function(e) "no_groups")
    
    pairwise_sig <- tryCatch({
      if (grouping_level == "biological") {
        digest::digest(values$biological_pairwise_combinations, algo = "xxhash64")
      } else {
        digest::digest(values$experimental_pairwise_combinations, algo = "xxhash64")
      }
    }, error = function(e) "no_pairwise")
    
    # Include key analysis parameters
    params_sig <- tryCatch({
      params <- list(
        fc_threshold = input$fc_threshold,
        pval_threshold = input$pvalue_threshold,
        correction_method = input$correction_method,
        bootstrap_enabled = input$bootstrap_enabled
      )
      digest::digest(params, algo = "xxhash64")
    }, error = function(e) "no_params")
    
    paste(data_sig, method_sig, grouping_level, groups_sig, pairwise_sig, params_sig, sep = "_")
  }
  
  # Check if cached results exist for a grouping level
  get_cached_dual_analysis <- function(grouping_level) {
    cache_key <- generate_dual_analysis_cache_key(grouping_level)
    
    if (!is.null(values$dual_analysis_cache[[cache_key]])) {
      cached <- values$dual_analysis_cache[[cache_key]]
      if (is_valid_stat_results(cached)) {
        cat("Cache hit for", grouping_level, "grouping analysis\n")
        return(cached)
      }
      cat("Discarding cached", grouping_level, "results - stats incomplete\n")
    }
    
    return(NULL)
  }
  
  # Validate that a statistics table contains more than just the feature column
  is_valid_stat_results <- function(df) {
    if (is.null(df) || !is.data.frame(df)) {
      return(FALSE)
    }
    if (ncol(df) <= 1) {
      return(FALSE)
    }
    any(grepl("(_PValue$|_AdjPValue$|_FDR$|_FoldChange$|_Log2FC$|_Bootstrap_|Global|ANOVA)",
              colnames(df)))
  }

  # Store results in cache
  store_dual_analysis_cache <- function(grouping_level, results) {
    if (!is_valid_stat_results(results)) {
      cat("Skipping cache for", grouping_level, "- stats incomplete\n")
      return(invisible(NULL))
    }
    cache_key <- generate_dual_analysis_cache_key(grouping_level)
    values$dual_analysis_cache[[cache_key]] <- results
    cat("Cached results for", grouping_level, "grouping analysis\n")
  }
  
  # Clear dual analysis cache (called when data changes)
  clear_dual_analysis_cache <- function() {
    values$dual_analysis_cache <- list()
    values$dual_analysis_cache_signature <- NULL
    cat("Cleared dual analysis cache\n")
  }
