  get_safe_power_alpha <- function(default = 0.05) {
    alpha_val <- suppressWarnings(as.numeric(input$power_alpha))
    if (length(alpha_val) == 0 || is.na(alpha_val) || !is.finite(alpha_val) || alpha_val <= 0) {
      return(default)
    }
    alpha_val
  }
  
  get_safe_target_power <- function(default_pct = 80) {
    target_val <- suppressWarnings(as.numeric(input$power_target))
    if (length(target_val) == 0 || is.na(target_val) || !is.finite(target_val) || target_val <= 0) {
      return(default_pct)
    }
    target_val
  }
  
  get_target_power_fraction <- function(default_fraction = 0.8) {
    target_pct <- get_safe_target_power(default_fraction * 100)
    target_pct / 100
  }
  
  get_power_params <- function(default_target_pct = 80) {
    # Ensure we always work with a single, finite numeric sample size per group.
    current_n_vals <- suppressWarnings(as.numeric(values$power_current_n))
    current_n <- if (length(current_n_vals) >= 1) current_n_vals[1] else NA_real_
    if (is.na(current_n) || !is.finite(current_n) || current_n < 1) {
      current_n <- NA_real_
    }
    target_pct <- get_safe_target_power(default_target_pct)
    list(
      current_n = current_n,
      target_pct = target_pct,
      target_fraction = target_pct / 100
    )
  }
  
  # NOTE: The addResourcePath for "jibosky_assets" has been removed.
