  # --- RFE State Persistence (load) ---
  isolate({
    state_file <- file.path(getwd(), "rfe_state.rds")
    if (file.exists(state_file)) {
      saved <- try(readRDS(state_file), silent = TRUE)
      if (!inherits(saved, "try-error") && is.list(saved)) {
        if (!is.null(saved$rfe_problem_type)) updateSelectInput(session, "rfe_problem_type", selected = saved$rfe_problem_type)
        if (!is.null(saved$rfe_group_1)) updateSelectInput(session, "rfe_group_1", selected = saved$rfe_group_1)
        if (!is.null(saved$rfe_group_2)) updateSelectInput(session, "rfe_group_2", selected = saved$rfe_group_2)
        if (!is.null(saved$rfe_groups_multi)) updateSelectInput(session, "rfe_groups_multi", selected = saved$rfe_groups_multi)
        if (!is.null(saved$rfe_metric)) updateSelectInput(session, "rfe_metric", selected = saved$rfe_metric)
        if (!is.null(saved$rfe_subset_strategy)) updateSelectInput(session, "rfe_subset_strategy", selected = saved$rfe_subset_strategy)
      }
    }
  })
  
  # --- RFE State Persistence (save on change) ---
  observe({
    state <- list(
      rfe_problem_type = input$rfe_problem_type,
      rfe_group_1 = input$rfe_group_1,
      rfe_group_2 = input$rfe_group_2,
      rfe_groups_multi = input$rfe_groups_multi,
      rfe_metric = input$rfe_metric,
      rfe_subset_strategy = input$rfe_subset_strategy
    )
    state_file <- file.path(getwd(), "rfe_state.rds")
    try(saveRDS(state, state_file), silent = TRUE)
  })
  
  # --- Dynamic Metric Filtering ---
  observe({
    req(input$rfe_problem_type)
    # Base metric sets
    class_metrics <- c("Accuracy" = "Accuracy", "Kappa" = "Kappa", "ROC AUC" = "ROC", "Sensitivity" = "Sens", "Specificity" = "Spec", "Precision" = "Precision", "Recall" = "Recall", "F1 Score" = "F")
    regression_metrics <- c("RMSE" = "RMSE", "MAE" = "MAE", "Rsquared" = "Rsquared")
    # Decide set
    if (input$rfe_problem_type == "regression") {
      updateSelectInput(session, "rfe_metric", choices = regression_metrics, selected = if (input$rfe_metric %in% names(regression_metrics)) input$rfe_metric else "RMSE")
    } else {
      # Classification: filter out ROC/Sens/Spec if multiclass (no one-vs-rest expansion implemented)
      metrics <- class_metrics
      if (input$rfe_problem_type == "multiclass") {
        metrics <- metrics[!names(metrics) %in% c("ROC AUC", "Sensitivity", "Specificity")]
        if (input$rfe_metric %in% c("ROC", "Sens", "Spec")) {
          updateSelectInput(session, "rfe_metric", selected = "Accuracy")
        }
      }
      updateSelectInput(session, "rfe_metric", choices = metrics)
    }
  })
  
  # Debug function to validate group column indices
  validate_group_indices <- function() {
    if (is.null(values$group_column_indices) || is.null(values$normalized_data)) {
      return(FALSE)
    }
    
    max_col_index <- ncol(values$normalized_data)
    all_indices <- unlist(values$group_column_indices)
    
    if (any(is.na(all_indices)) || any(all_indices < 1) || any(all_indices > max_col_index)) {
      message(paste("Invalid group column indices detected.",
                    "Max column index:", max_col_index,
                    "Group indices range:", min(all_indices, na.rm = TRUE), "-", max(all_indices, na.rm = TRUE)))
      return(FALSE)
    }
    
    return(TRUE)
  }
  
