  # ==================== PAIRWISE ORDER REVIEW MODAL HANDLERS ====================
  
  # Function to extract actual pairwise comparisons from stat_results
  # Returns both traditional "GroupA vs GroupB" comparisons AND lmROTS/lmeROTS variable comparisons
  # Variable comparisons are represented with Group_2 = "[Variable]" as a special marker
  get_actual_pairwise_combinations <- function() {
    if (is.null(values$stat_results) || ncol(values$stat_results) == 0) {
      return(data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE))
    }
    
    # Extract column names that contain pairwise comparison results
    # Pattern: "GroupA vs GroupB_PValue" or "GroupA vs GroupB_AdjPValue" etc.
    col_names <- colnames(values$stat_results)
    
    # Find columns with "_PValue" suffix (not AdjPValue, just PValue)
    pvalue_cols <- grep("_PValue$", col_names, value = TRUE)
    
    # Extract comparison names by removing the "_PValue" suffix
    comparison_names <- gsub("_PValue$", "", pvalue_cols)
    
    # Also include post-hoc pairwise columns (e.g., "PostHoc_GroupA_vs_GroupB_AdjPValue")
    posthoc_cols <- grep("^PostHoc_.*_(AdjPValue|PValue)$", col_names, value = TRUE)
    if (length(posthoc_cols) > 0) {
      posthoc_names <- gsub("^PostHoc_", "", posthoc_cols)
      posthoc_names <- gsub("_(AdjPValue|PValue)$", "", posthoc_names)
      posthoc_names <- gsub("_vs_", " vs ", posthoc_names)
      comparison_names <- unique(c(comparison_names, posthoc_names))
    }
    
    # Parse comparison names to extract Group_1 and Group_2
    # Format: "GroupA vs GroupB" for pairwise, "lmROTS_VarName" or "lmeROTS_VarName" for variable
    comparisons_list <- lapply(comparison_names, function(comp_name) {
      # Check if this is an lmROTS/lmeROTS variable-based comparison
      if (grepl("^(lmROTS|lmeROTS)_", comp_name)) {
        # Variable comparison: use the full name as Group_1, "[Variable]" as marker for Group_2
        return(data.frame(Group_1 = comp_name, Group_2 = "[Variable]", stringsAsFactors = FALSE))
      }
      # Split by " vs " for traditional pairwise comparisons
      parts <- strsplit(comp_name, " vs ", fixed = TRUE)[[1]]
      if (length(parts) == 2) {
        return(data.frame(Group_1 = parts[1], Group_2 = parts[2], stringsAsFactors = FALSE))
      } else {
        return(NULL)
      }
    })
    
    # Remove NULL entries and combine into data frame
    comparisons_list <- comparisons_list[!sapply(comparisons_list, is.null)]
    
    if (length(comparisons_list) == 0) {
      return(data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE))
    }
    
    comparisons_df <- do.call(rbind, comparisons_list)
    rownames(comparisons_df) <- NULL
    
    return(comparisons_df)
  }
  
  # Helper to retrieve a reliable list of unique groups even when metadata is missing
  get_confirmed_group_list <- function() {
    sanitize <- function(x) {
      if (is.null(x)) return(character(0))
      x <- as.character(x)
      x <- trimws(x)
      x <- x[!is.na(x) & nzchar(x)]
      unique(x)
    }

    # Candidate sources ordered by reliability
    candidate_sources <- list(
      values$unique_groups_original,
      values$unique_groups,
      values$final_biological_groups,
      if (!is.null(values$mapping_df)) values$mapping_df$Biological_Group else NULL,
      if (!is.null(values$auto_mapping)) values$auto_mapping$biological else NULL
    )

    for (src in candidate_sources) {
      groups <- sanitize(src)
      if (length(groups) >= 2) {
        values$unique_groups_original <- groups
        return(groups)
      }
    }

    # Fall back to any non-empty candidate (even if single group) to preserve legacy behavior
    for (src in candidate_sources) {
      groups <- sanitize(src)
      if (length(groups) > 0) {
        if (is.null(values$unique_groups_original) || !identical(values$unique_groups_original, groups)) {
          values$unique_groups_original <- groups
        }
        return(groups)
      }
    }

    return(character(0))
  }

  # Function to generate all possible pairwise combinations from available groups
  get_all_possible_pairwise_combinations <- function() {
    # Use confirmed groups (before filtering by active comparisons) to get all possible combinations
    groups_to_use <- get_confirmed_group_list()

    if (length(groups_to_use) < 2) {
      return(data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE))
    }

    # Generate all unique pairwise combinations by iterating through groups in order
    # This preserves the original group order instead of alphabetical sorting
    combinations <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)

    for (i in 1:(length(groups_to_use) - 1)) {
      for (j in (i + 1):length(groups_to_use)) {
        combinations <- rbind(combinations, data.frame(
          Group_1 = groups_to_use[i],
          Group_2 = groups_to_use[j],
          stringsAsFactors = FALSE
        ))
      }
    }

    # Reset row names
    rownames(combinations) <- NULL

    return(combinations)
  }
  
  # Function to get pairwise combinations to use for analysis
  # Prioritizes current_pairwise_combinations (set by pre-analysis or review modal)
  # Falls back to generating all possible combinations
  get_pairwise_combinations_for_analysis <- function() {
    if (!is.null(values$current_pairwise_combinations) && nrow(values$current_pairwise_combinations) > 0) {
      # Use current_pairwise_combinations set by pre-analysis modal or review modal
      return(values$current_pairwise_combinations)
    } else {
      # Fall back to all possible combinations
      return(get_all_possible_pairwise_combinations())
    }
  }
  
  # Update dropdown choices when modal opens
  observeEvent(input$reviewPairwiseOrderBtn, {
    message("=== MODAL OPENING ===")
    
    # Preserve original groups if not already saved
    if (is.null(values$unique_groups_original)) {
      values$unique_groups_original <- values$unique_groups
      message("Saved original groups: ", paste(values$unique_groups_original, collapse = ", "))
    } else {
      message("Using existing original groups: ", paste(values$unique_groups_original, collapse = ", "))
    }
    
    # Debug stat_results
    if (is.null(values$stat_results)) {
      message("ERROR: values$stat_results is NULL")
    } else {
      message("values$stat_results has ", ncol(values$stat_results), " columns")
      pvalue_cols <- grep("_PValue$", colnames(values$stat_results), value = TRUE)
      message("Found ", length(pvalue_cols), " _PValue columns: ", paste(pvalue_cols, collapse = ", "))
    }
    
    # Check if dual grouping is active
    if (isTRUE(values$has_dual_grouping)) {
      message("=== DUAL GROUPING MODE - initializing biological and experimental combinations ===")
      
      # Initialize biological pairwise combinations from biological_stat_results
      if (!is.null(values$biological_stat_results)) {
        bio_pvalue_cols <- grep("_PValue$", colnames(values$biological_stat_results), value = TRUE)
        bio_combos <- data.frame(Group_1 = character(0), Group_2 = character(0))
        
        for (col in bio_pvalue_cols) {
          # Extract comparison name (e.g., "GroupA vs GroupB" from "GroupA vs GroupB_PValue")
          comparison_name <- gsub("_PValue$", "", col)
          parts <- strsplit(comparison_name, " vs ", fixed = TRUE)[[1]]
          if (length(parts) == 2) {
            bio_combos <- rbind(bio_combos, data.frame(Group_1 = parts[1], Group_2 = parts[2]))
          }
        }
        values$current_bio_pairwise_combinations <- bio_combos
        message("Initialized ", nrow(bio_combos), " biological combinations")
      } else {
        # Fall back to all biological group combinations (not only first pair)
        bio_groups <- values$biological_unique_groups
        if (!is.null(bio_groups) && length(bio_groups) >= 2) {
          bio_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
          for (i in 1:(length(bio_groups) - 1)) {
            for (j in (i + 1):length(bio_groups)) {
              bio_combos <- rbind(bio_combos, data.frame(Group_1 = bio_groups[i], Group_2 = bio_groups[j], stringsAsFactors = FALSE))
            }
          }
          values$current_bio_pairwise_combinations <- bio_combos
        } else {
          values$current_bio_pairwise_combinations <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
        }
      }
      
      # Initialize experimental pairwise combinations from experimental_stat_results
      if (!is.null(values$experimental_stat_results)) {
        exp_pvalue_cols <- grep("_PValue$", colnames(values$experimental_stat_results), value = TRUE)
        exp_combos <- data.frame(Group_1 = character(0), Group_2 = character(0))
        
        for (col in exp_pvalue_cols) {
          comparison_name <- gsub("_PValue$", "", col)
          parts <- strsplit(comparison_name, " vs ", fixed = TRUE)[[1]]
          if (length(parts) == 2) {
            exp_combos <- rbind(exp_combos, data.frame(Group_1 = parts[1], Group_2 = parts[2]))
          }
        }
        values$current_exp_pairwise_combinations <- exp_combos
        message("Initialized ", nrow(exp_combos), " experimental combinations")
      } else {
        # Fall back to all experimental group combinations (not only first pair)
        exp_groups <- values$experimental_unique_groups
        if (!is.null(exp_groups) && length(exp_groups) >= 2) {
          exp_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
          for (i in 1:(length(exp_groups) - 1)) {
            for (j in (i + 1):length(exp_groups)) {
              exp_combos <- rbind(exp_combos, data.frame(Group_1 = exp_groups[i], Group_2 = exp_groups[j], stringsAsFactors = FALSE))
            }
          }
          values$current_exp_pairwise_combinations <- exp_combos
        } else {
          values$current_exp_pairwise_combinations <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
        }
      }
      
      # Update UI triggers for dual grouping
      values$review_bio_ui_version <- (values$review_bio_ui_version %||% 0) + 1
      values$review_exp_ui_version <- (values$review_exp_ui_version %||% 0) + 1
      
    } else {
      # SINGLE GROUPING MODE: Use original logic
      # IMPORTANT: Preserve user's original pairwise selection if it exists
      # For ANOVA/Kruskal, the stat_results may not have PostHoc columns for all pairs
      # (only for features where the global test was significant p<0.05)
      # So we should NOT overwrite the user's selection with what's in stat_results
      
      if (!is.null(values$current_pairwise_combinations) && nrow(values$current_pairwise_combinations) > 0) {
        # Keep existing combinations - don't overwrite with stat_results extraction
        message("Preserving existing current_pairwise_combinations with ", nrow(values$current_pairwise_combinations), " rows")
        actual_comparisons <- values$current_pairwise_combinations
      } else {
        # No existing combinations, extract from stat_results
        actual_comparisons <- get_actual_pairwise_combinations()
        message("get_actual_pairwise_combinations() returned ", nrow(actual_comparisons), " rows")
      }
      
      # Debug: Show how many comparisons were found
      if (nrow(actual_comparisons) > 0) {
        message("Comparisons: ")
        for (i in 1:nrow(actual_comparisons)) {
          message("  ", i, ": ", actual_comparisons[i, "Group_1"], " vs ", actual_comparisons[i, "Group_2"])
        }
      }
      
      # Set the data - use a copy to ensure it's a new object
      values$current_pairwise_combinations <- as.data.frame(actual_comparisons)
      
      # CRITICAL: Use a numeric trigger that ALWAYS changes to force renderUI to execute
      values$pairwise_ui_version <- if(is.null(values$pairwise_ui_version)) 1 else values$pairwise_ui_version + 1
      
      message("Set values$current_pairwise_combinations with ", nrow(values$current_pairwise_combinations), " rows")
      message("Set values$pairwise_ui_version to ", values$pairwise_ui_version)
    }
    
    # Open the modal
    shinyBS::toggleModal(session, "pairwiseOrderModal", toggle = "open")
    message("=== MODAL OPENED ===")
  })
  
  # Handle Close button in modal
  observeEvent(input$closePairwiseModal, {
    shinyBS::toggleModal(session, "pairwiseOrderModal", toggle = "close")
  })
  
  # NOTE: Remove button handling is done in the observe block at line ~13120
  # This duplicate block was causing newly added comparisons to be immediately removed
  
  # Handle confirm button for pairwise order modal
  observeEvent(input$confirmPairwiseOrder, {
    
    # Check if dual grouping is active
    if (isTRUE(values$has_dual_grouping)) {
      # ==================== DUAL GROUPING MODE ====================
      message("=== CONFIRM PAIRWISE ORDER - DUAL GROUPING MODE ===")
      
      # Validate biological combinations
      bio_combos <- values$current_bio_pairwise_combinations
      if (!is.null(bio_combos) && nrow(bio_combos) > 0) {
        # Remove invalid combos
        bio_combos <- bio_combos[bio_combos$Group_1 != bio_combos$Group_2, , drop = FALSE]
        # Remove duplicates
        if (nrow(bio_combos) > 1) {
          bio_keys <- apply(bio_combos, 1, function(r) paste(sort(c(r["Group_1"], r["Group_2"])), collapse = "_"))
          bio_combos <- bio_combos[!duplicated(bio_keys), , drop = FALSE]
        }
        values$current_bio_pairwise_combinations <- bio_combos
      }
      
      # Validate experimental combinations
      exp_combos <- values$current_exp_pairwise_combinations
      if (!is.null(exp_combos) && nrow(exp_combos) > 0) {
        # Remove invalid combos
        exp_combos <- exp_combos[exp_combos$Group_1 != exp_combos$Group_2, , drop = FALSE]
        # Remove duplicates
        if (nrow(exp_combos) > 1) {
          exp_keys <- apply(exp_combos, 1, function(r) paste(sort(c(r["Group_1"], r["Group_2"])), collapse = "_"))
          exp_combos <- exp_combos[!duplicated(exp_keys), , drop = FALSE]
        }
        values$current_exp_pairwise_combinations <- exp_combos
      }
      
      # Check if at least one level has comparisons
      bio_has_combos <- !is.null(bio_combos) && nrow(bio_combos) > 0
      exp_has_combos <- !is.null(exp_combos) && nrow(exp_combos) > 0
      
      if (!bio_has_combos && !exp_has_combos) {
        showNotification("No valid comparisons to apply for either grouping level.", type = "warning")
        return()
      }
      
      # Store pairwise combinations for re-analysis
      values$biological_pairwise_combinations <- bio_combos
      values$experimental_pairwise_combinations <- exp_combos
      
      # Update the main current_pairwise_combinations to biological (active level)
      values$current_pairwise_combinations <- bio_combos
      
      # Clear caches to ensure fresh analysis
      values$dual_analysis_cache <- list()
      values$statistical_cache <- list()
      
      showNotification(
        paste0("Pairwise comparisons updated. ",
               if(bio_has_combos) paste0(nrow(bio_combos), " biological comparison(s)") else "",
               if(bio_has_combos && exp_has_combos) " and " else "",
               if(exp_has_combos) paste0(nrow(exp_combos), " experimental comparison(s)") else "",
               ". Please re-run your analysis to see changes."),
        type = "message", duration = 7
      )
      
      # Close the modal
      shinyBS::toggleModal(session, "pairwiseOrderModal", toggle = "close")
      return()
    }
    
    # ==================== SINGLE GROUPING MODE (original code) ====================
    # Collect edited values from the UI
    if (!is.null(values$current_pairwise_combinations) && nrow(values$current_pairwise_combinations) > 0) {
      # Update the data frame with edited values from selectInputs
      for (i in 1:nrow(values$current_pairwise_combinations)) {
        group1_input <- input[[paste0("edit_group1_", i)]]
        group2_input <- input[[paste0("edit_group2_", i)]]
        
        if (!is.null(group1_input) && !is.null(group2_input)) {
          values$current_pairwise_combinations[i, "Group_1"] <- group1_input
          values$current_pairwise_combinations[i, "Group_2"] <- group2_input
        }
      }
      
      # Remove any comparisons where Group_1 == Group_2
      values$current_pairwise_combinations <- values$current_pairwise_combinations[
        values$current_pairwise_combinations$Group_1 != values$current_pairwise_combinations$Group_2, , drop = FALSE
      ]
      
      # Remove duplicate comparisons (A vs B and B vs A are considered the same)
      if (nrow(values$current_pairwise_combinations) > 1) {
        # Create a normalized key for each comparison (always alphabetically sorted)
        comparison_keys <- apply(values$current_pairwise_combinations, 1, function(row) {
          groups <- sort(c(row["Group_1"], row["Group_2"]))
          paste(groups[1], groups[2], sep = "_")
        })
        
        # Keep only the first occurrence of each unique comparison
        unique_indices <- !duplicated(comparison_keys)
        
        if (sum(!unique_indices) > 0) {
          # Get the specific comparisons that were removed
          removed_comparisons <- values$current_pairwise_combinations[!unique_indices, , drop = FALSE]
          removed_list <- apply(removed_comparisons, 1, function(row) {
            paste0(row["Group_1"], " vs ", row["Group_2"])
          })
          if (!is.null(session)) {
            showNotification(
              paste0("Removed ", sum(!unique_indices), " duplicate comparison(s): ",
                     paste(removed_list, collapse = ", "),
                     ". Note: Reverse comparisons are considered duplicates."),
              type = "warning", duration = 7
            )
          }
        }
        
        values$current_pairwise_combinations <- values$current_pairwise_combinations[unique_indices, , drop = FALSE]
      }
      
      # Check if there are any comparisons left
      if (nrow(values$current_pairwise_combinations) == 0) {
        if (!is.null(session)) {
          showNotification("No valid comparisons to apply. Please add at least one comparison with different groups.",
                           type = "warning", duration = 5)
        }
        return()
      }
      
      # Regenerate statistical analysis with the new comparison list
      withProgress(message = "Regenerating statistical analysis...", value = 0, {
        tryCatch({
          # Get the original stat_results to preserve non-pairwise columns
          original_stat_results <- values$stat_results
          
          # Keep only the Feature column and any non-pairwise columns
          # Remove all pairwise comparison columns (those containing " vs ")
          pairwise_pattern <- " vs "
          non_pairwise_cols <- colnames(original_stat_results)[!grepl(pairwise_pattern, colnames(original_stat_results))]
          stat_results <- original_stat_results[, non_pairwise_cols, drop = FALSE]
          
          setProgress(0.3, detail = "Calculating new pairwise comparisons...")
          
          # Loop through the new comparison list and calculate statistics
          for (idx in 1:nrow(values$current_pairwise_combinations)) {
            group1 <- values$current_pairwise_combinations[idx, "Group_1"]
            group2 <- values$current_pairwise_combinations[idx, "Group_2"]
            
            # Skip lmROTS/lmeROTS variable comparisons - these are pre-computed and not recalculated
            if (group2 == "[Variable]") {
              next
            }
            
            comparison_name <- paste(group1, "vs", group2)
            
            # Find group indices
            group1_idx <- which(values$unique_groups == group1)
            group2_idx <- which(values$unique_groups == group2)
            
            if (length(group1_idx) == 0 || length(group2_idx) == 0) {
              next
            }
            
            # Get data for each group
            group1_columns <- values$group_column_indices[[group1_idx]]
            group2_columns <- values$group_column_indices[[group2_idx]]
            
            # Calculate p-values
            p_values <- apply(values$normalized_data, 1, function(row) {
              group1_data <- row[group1_columns]
              group2_data <- row[group2_columns]
              
              # Remove NAs
              group1_data <- group1_data[!is.na(group1_data)]
              group2_data <- group2_data[!is.na(group2_data)]
              
              # Check if we have enough data
              if (length(group1_data) >= 2 && length(group2_data) >= 2) {
                if (input$sig_method == "wilcox" || input$sig_method == "kruskal") {
                  tryCatch({
                    wilcox.test(group1_data, group2_data)$p.value
                  }, error = function(e) { NA })
                } else if (input$sig_method == "t.test" || input$sig_method == "anova") {
                  tryCatch({
                    t.test(group1_data, group2_data)$p.value
                  }, error = function(e) { NA })
                } else {
                  NA
                }
              } else {
                NA
              }
            })
            
            # Calculate fold change as Group2/Group1
            fold_changes <- apply(values$normalized_data, 1, function(row) {
              group1_mean <- mean(row[group1_columns], na.rm = TRUE)
              group2_mean <- mean(row[group2_columns], na.rm = TRUE)
              return(group2_mean / group1_mean)
            })
            
            # Calculate log2 fold change
            log2_fold_changes <- log2(fold_changes)
            log2_fold_changes[is.infinite(log2_fold_changes)] <- NA
            
            # Adjust p-values
            adjusted_p_values <- p.adjust(p_values, method = get_correction_method())
            
            # Add columns to results
            stat_results[[paste0(comparison_name, "_PValue")]] <- p_values
            stat_results[[paste0(comparison_name, "_AdjPValue")]] <- adjusted_p_values
            stat_results[[paste0(comparison_name, "_FoldChange")]] <- fold_changes
            stat_results[[paste0(comparison_name, "_Log2FC")]] <- log2_fold_changes
            
            setProgress(0.3 + (idx / nrow(values$current_pairwise_combinations)) * 0.6)
          }
          
          setProgress(0.9, detail = "Finalizing results...")
          
          # Update stat_results
          values$stat_results <- stat_results
          
          # Determine the unique groups used in pairwise comparisons
          groups_in_comparisons <- unique(c(values$current_pairwise_combinations$Group_1,
                                            values$current_pairwise_combinations$Group_2))

          # Keep original full list of unique groups in unique_groups_original if not already present
          if (is.null(values$unique_groups_original)) {
            values$unique_groups_original <- values$unique_groups
          }
          # NOTE: Do NOT overwrite values$unique_groups here (original groups should persist)
          # Instead store the active groups for this analysis separately so we can preserve
          # the full group set for subsequent analyses and UI updates.
          values$analysis_active_groups <- groups_in_comparisons
          
          setProgress(1.0, detail = "Complete!")
          
          # Show success message
          if (!is.null(session)) {
            showNotification(paste0("Statistical analysis regenerated with ", nrow(values$current_pairwise_combinations),
                                    " pairwise comparison(s). FC calculated as Group 2 / Group 1. Active groups updated to: ",
                                    paste(groups_in_comparisons, collapse = ", ")),
                             type = "message", duration = 5)
          }
          
        }, error = function(e) {
          if (!is.null(session)) {
            showNotification(paste("Error regenerating statistical analysis:", e$message),
                             type = "error", duration = 10)
          }
        })
      })
    } else {
      if (!is.null(session)) {
        showNotification("No pairwise comparisons to apply.", type = "warning", duration = 5)
      }
    }
    
    # Close the modal
    shinyBS::toggleModal(session, "pairwiseOrderModal", toggle = "close")
  })
  
  # ==================== END PAIRWISE ORDER REVIEW MODAL HANDLERS ====================
  
  # ==================== PAIRWISE ORDER MODAL CONTENT (DUAL GROUPING AWARE) ====================
  output$pairwiseOrderModalContent <- renderUI({
    # Check if dual grouping is active
    if (isTRUE(values$has_dual_grouping)) {
      # DUAL GROUPING MODE: Show two separate sections
      
      # Info alert for dual grouping
      dual_grouping_alert <- div(
        class = "alert alert-info", role = "alert",
        style = "margin-bottom: 15px; border-left: 4px solid #17a2b8;",
        icon("info-circle"),
        strong(" Dual-Level Grouping Detected: "),
        "You have both biological and experimental groups. Review the pairwise comparisons for each level below."
      )
      
      # Biological groups section
      bio_section <- div(
        style = "margin-bottom: 20px; padding: 15px; background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 100%); border-radius: 8px; border: 2px solid #1976d2;",
        h5(icon("dna"), " Biological Group Comparisons:", style = "font-weight: 600; margin-bottom: 15px; color: #0d47a1;"),
        div(style = "background: white; padding: 15px; border-radius: 6px; border: 1px solid #dee2e6;",
            # Header row
            fluidRow(style = "font-weight: 600; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 2px solid #1976d2;",
                     column(4, "Group 1 (Denominator)"),
                     column(4, "Group 2 (Numerator)"),
                     column(4, "Actions")
            ),
            uiOutput("currentBioPairwiseDisplay")
        ),
        div(style = "display: flex; gap: 10px; margin-top: 10px;",
            actionButton("reviewBioAddBtn", "Add Biological Comparison", icon = icon("plus"), class = "btn-primary btn-sm"),
            actionButton("reviewBioResetBtn", "Reset Biological", icon = icon("undo"), class = "btn-outline-primary btn-sm")
        )
      )
      
      # Experimental groups section
      exp_section <- div(
        style = "margin-bottom: 20px; padding: 15px; background: linear-gradient(135deg, #d7ccc8 0%, #bcaaa4 100%); border-radius: 8px; border: 2px solid #8d6e63;",
        h5(icon("flask"), " Experimental Group Comparisons:", style = "font-weight: 600; margin-bottom: 15px; color: #5d4037;"),
        div(style = "background: white; padding: 15px; border-radius: 6px; border: 1px solid #dee2e6;",
            # Header row
            fluidRow(style = "font-weight: 600; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 2px solid #8d6e63;",
                     column(4, "Group 1 (Denominator)"),
                     column(4, "Group 2 (Numerator)"),
                     column(4, "Actions")
            ),
            uiOutput("currentExpPairwiseDisplay")
        ),
        div(style = "display: flex; gap: 10px; margin-top: 10px;",
            actionButton("reviewExpAddBtn", "Add Experimental Comparison", icon = icon("plus"), class = "btn-info btn-sm"),
            actionButton("reviewExpResetBtn", "Reset Experimental", icon = icon("undo"), class = "btn-outline-info btn-sm")
        )
      )
      
      # Action buttons
      footer <- div(style = "display: flex; gap: 10px; justify-content: flex-end; margin-top: 20px;",
                    modalButton("Cancel"),
                    actionButton("confirmPairwiseOrder", "Confirm & Re-run Analysis", 
                                 icon = icon("check"), class = "btn-success")
      )
      
      return(tagList(dual_grouping_alert, bio_section, exp_section, footer))
      
    } else {
      # SINGLE GROUPING MODE: Show original UI
      standard_section <- div(style = "margin-bottom: 20px;",
        h5("Pairwise Comparisons to Analyze:", style = "font-weight: 600; margin-bottom: 15px;"),
        div(style = "background: #f8f9fa; padding: 15px; border-radius: 6px; border: 1px solid #dee2e6;",
            # Header row
            fluidRow(style = "font-weight: 600; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 2px solid #dee2e6;",
                     column(4, "Group 1 (Denominator)"),
                     column(4, "Group 2 (Numerator)"),
                     column(4, "Actions")
            ),
            uiOutput("currentPairwiseDisplay")
        )
      )
      
      # Add new comparison button
      add_buttons <- div(style = "display: flex; gap: 10px; margin-bottom: 20px;",
                         actionButton("addNewComparisonBtn", "Add New Comparison", icon = icon("plus"), class = "btn-primary btn-sm"),
                         actionButton("resetPairwiseOrderBtn", "Reset to Default", icon = icon("undo"), class = "btn-warning btn-sm"),
                         actionButton("clearAllPairwiseBtn", "Clear All", icon = icon("eraser"), class = "btn-outline-danger btn-sm")
      )
      
      # Action buttons
      footer <- div(style = "display: flex; gap: 10px; justify-content: flex-end; margin-top: 20px;",
                    modalButton("Cancel"),
                    actionButton("confirmPairwiseOrder", "Confirm & Re-run Analysis", 
                                 icon = icon("check"), class = "btn-success")
      )
      
      return(tagList(standard_section, add_buttons, footer))
    }
  })
  # Ensure pairwiseOrderModalContent is not suspended when hidden
  outputOptions(output, "pairwiseOrderModalContent", suspendWhenHidden = FALSE)
  
  # ==================== END PAIRWISE ORDER MODAL CONTENT ====================
  
  # Render the current pairwise comparisons as editable table
  output$currentPairwiseDisplay <- renderUI({
    # CRITICAL: Depend on the version trigger to force re-execution
    trigger_version <- values$pairwise_ui_version
    
    message("=== renderUI CALLED === (version: ", trigger_version, ")")
    message("current_pairwise_combinations: ",
            if(is.null(values$current_pairwise_combinations)) {
              "NULL"
            } else {
              paste(nrow(values$current_pairwise_combinations), "rows")
            })
    
    # Check if data exists
    if (is.null(values$current_pairwise_combinations) || nrow(values$current_pairwise_combinations) == 0) {
      message("Returning empty state message")
      return(div(style = "text-align: center; padding: 20px; color: #999; font-style: italic;",
                 "No pairwise comparisons available. Click 'Add New Comparison' to create one."))
    }
    
    message("Creating UI for ", nrow(values$current_pairwise_combinations), " comparisons")
    
    # Create a list of fluidRows, one for each comparison
    comparison_rows <- lapply(1:nrow(values$current_pairwise_combinations), function(i) {
      row <- values$current_pairwise_combinations[i, ]
      message("  Row ", i, ": ", row$Group_1, " vs ", row$Group_2)
      
      # Check if this is a lmROTS/lmeROTS variable comparison (Group_2 is "[Variable]")
      is_variable_comparison <- (row$Group_2 == "[Variable]")
      
      if (is_variable_comparison) {
        # Variable comparison: display as non-editable label (variable name is fixed from analysis)
        fluidRow(style = "margin-bottom: 10px; padding: 10px; background: #fff3e0; border-radius: 4px; border: 1px solid #ffb74d;",
                 column(8,
                        div(style = "padding: 8px; font-weight: bold; color: #e65100;",
                            icon("chart-line", style = "margin-right: 8px;"),
                            row$Group_1,
                            tags$small(style = "margin-left: 10px; color: #999;", "(Variable Effect)")
                        )
                 ),
                 column(4,
                        actionButton(
                          inputId = paste0("remove_comparison_", i),
                          label = NULL,
                          icon = icon("trash"),
                          class = "btn-danger btn-sm",
                          style = "width: 100%; margin-top: 0px;",
                          title = "Remove this comparison"
                        )
                 )
        )
      } else {
        # Standard pairwise comparison: two editable group dropdowns
        fluidRow(style = "margin-bottom: 10px; padding: 10px; background: white; border-radius: 4px; border: 1px solid #e9ecef;",
                 column(4,
                        selectInput(
                          inputId = paste0("edit_group1_", i),
                          label = NULL,
                          choices = values$unique_groups_original %||% values$unique_groups,
                          selected = row$Group_1,
                          width = "100%"
                        )
                 ),
                 column(4,
                        selectInput(
                          inputId = paste0("edit_group2_", i),
                          label = NULL,
                          choices = values$unique_groups_original %||% values$unique_groups,
                          selected = row$Group_2,
                          width = "100%"
                        )
                 ),
                 column(4,
                        actionButton(
