    comparison_rows <- lapply(1:nrow(combos), function(i) {
      row <- combos[i, ]
      fluidRow(style = "margin-bottom: 10px; padding: 10px; background: #d7ccc8; border-radius: 4px; border: 1px solid #a1887f;",
               column(4,
                      selectInput(
                        inputId = paste0("review_exp_group1_", i),
                        label = NULL,
                        choices = exp_groups,
                        selected = row$Group_1,
