      return()
    }
    
    # Generate all possible biological combinations
    all_bio_combos <- expand.grid(Group_1 = bio_groups, Group_2 = bio_groups, stringsAsFactors = FALSE)
    all_bio_combos <- all_bio_combos[all_bio_combos$Group_1 != all_bio_combos$Group_2, ]
    # Remove reverse duplicates
    all_bio_combos$key <- apply(all_bio_combos, 1, function(r) paste(sort(c(r["Group_1"], r["Group_2"])), collapse = "_"))
    all_bio_combos <- all_bio_combos[!duplicated(all_bio_combos$key), c("Group_1", "Group_2")]
    
    values$current_bio_pairwise_combinations <- all_bio_combos
    values$review_bio_ui_version <- (values$review_bio_ui_version %||% 0) + 1
    showNotification(paste0("Reset to ", nrow(all_bio_combos), " biological comparison(s)."), type = "message")
  })
  
