      if (!is.null(current_value)) {
        last_value <- values$review_bio_remove_states[[btn_name]]
        if (!is.null(last_value) && current_value > last_value && current_value > 0) {
          row_index <- as.numeric(gsub("review_bio_remove_", "", btn_name))
          if (row_index <= nrow(combos)) {
            values$current_bio_pairwise_combinations <- combos[-row_index, , drop = FALSE]
            values$review_bio_ui_version <- (values$review_bio_ui_version %||% 0) + 1
