        ),
        div(style = "display: flex; gap: 10px; justify-content: flex-end; margin-top: 20px;",
            actionButton("cancelPreAnalysisPairwise", "Cancel", icon = icon("times"), class = "btn-secondary"),
            actionButton("confirmPreAnalysisPairwise", "Proceed with Analysis", icon = icon("play"), class = "btn-success")
        )
      )
      
      return(tagList(info_alert, dual_grouping_alert, bio_section, exp_section, footer))
      
    } else {
      # SINGLE GROUPING MODE: Show original UI
      standard_section <- div(style = "margin-bottom: 20px;",
                              h5("Pairwise Comparisons to Analyze:", style = "font-weight: 600; margin-bottom: 15px;"),
                              div(style = "background: #f8f9fa; padding: 15px; border-radius: 6px; border: 1px solid #dee2e6;",
                                  # Header row
                                  fluidRow(style = "font-weight: 600; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 2px solid #dee2e6;",
                                           column(4, "Group 1 (Denominator)"),
                                           column(4, "Group 2 (Numerator)"),
                                           column(4, "Actions")
                                  ),
                                  uiOutput("preAnalysisPairwiseDisplay")
                              )
      )
      
      # Add new comparison button
      add_buttons <- div(style = "display: flex; gap: 10px; margin-bottom: 20px;",
                         actionButton("preAnalysisAddComparisonBtn", "Add Comparison", icon = icon("plus"), class = "btn-primary btn-sm"),
                         actionButton("preAnalysisResetBtn", "Reset to Default", icon = icon("undo"), class = "btn-warning btn-sm"),
                         actionButton("preAnalysisClearAllBtn", "Clear All", icon = icon("eraser"), class = "btn-outline-danger btn-sm")
      )
      
      # Skip and action buttons
      footer <- tagList(
        div(style = "margin-bottom: 15px;",
            checkboxInput("skipPairwiseSelection", 
                          "Don't show this dialog again for this session (use default comparisons)",
                          value = FALSE)
        ),
        div(style = "display: flex; gap: 10px; justify-content: flex-end; margin-top: 20px;",
            actionButton("cancelPreAnalysisPairwise", "Cancel", icon = icon("times"), class = "btn-secondary"),
            actionButton("confirmPreAnalysisPairwise", "Proceed with Analysis", icon = icon("play"), class = "btn-success")
        )
      )
      
      return(tagList(info_alert, standard_section, add_buttons, footer))
    }
  })
  
  # Render the pre-analysis pairwise comparisons display
  output$preAnalysisPairwiseDisplay <- renderUI({
    # Depend on the version trigger to force re-execution
    trigger_version <- values$preanalysis_pairwise_ui_version
    
    # Check if data exists
    if (is.null(values$preanalysis_pairwise_combinations) || nrow(values$preanalysis_pairwise_combinations) == 0) {
      return(div(style = "text-align: center; padding: 20px; color: #999; font-style: italic;",
                 "No pairwise comparisons available. Click 'Add Comparison' to create one."))
    }
    
    # Create a list of fluidRows, one for each comparison
    comparison_rows <- lapply(1:nrow(values$preanalysis_pairwise_combinations), function(i) {
      row <- values$preanalysis_pairwise_combinations[i, ]
      
      fluidRow(style = "margin-bottom: 10px; padding: 10px; background: white; border-radius: 4px; border: 1px solid #e9ecef;",
               column(4,
                      selectInput(
                        inputId = paste0("preanalysis_group1_", i),
                        label = NULL,
                        choices = values$unique_groups,
                        selected = row$Group_1,
                        width = "100%"
                      )
               ),
               column(4,
                      selectInput(
                        inputId = paste0("preanalysis_group2_", i),
                        label = NULL,
                        choices = values$unique_groups,
                        selected = row$Group_2,
                        width = "100%"
                      )
               ),
               column(4,
                      actionButton(
                        inputId = paste0("preanalysis_remove_", i),
                        label = NULL,
                        icon = icon("trash"),
                        class = "btn-danger btn-sm",
                        style = "width: 100%; margin-top: 0px;",
                        title = "Remove this comparison"
                      )
               )
      )
    })
    
    # Return all rows in a div
    do.call(tagList, comparison_rows)
  })
  # Ensure preAnalysisPairwiseDisplay is not suspended when hidden
  outputOptions(output, "preAnalysisPairwiseDisplay", suspendWhenHidden = FALSE)
  
  # ==================== DUAL GROUPING: Biological Pairwise Display ====================
  output$preAnalysisBioPairwiseDisplay <- renderUI({
