  # ==================== DUAL GROUPING: Add/Reset Button Handlers ====================
  
  # Add biological comparison
  observeEvent(input$preAnalysisBioAddBtn, {
    if (!isTRUE(values$has_dual_grouping)) return()
    
    bio_groups <- values$biological_unique_groups
    if (is.null(bio_groups) || length(bio_groups) < 2) {
      showNotification("Not enough biological groups for comparison.", type = "warning")
      return()
    }
    
    # Generate all possible bio combinations
    all_bio <- data.frame(
      Group_1 = character(0),
      Group_2 = character(0),
      stringsAsFactors = FALSE
    )
    for (i in 1:(length(bio_groups) - 1)) {
      for (j in (i + 1):length(bio_groups)) {
        all_bio <- rbind(all_bio, data.frame(
          Group_1 = bio_groups[i],
          Group_2 = bio_groups[j],
          stringsAsFactors = FALSE
        ))
      }
    }
    
    current <- values$preanalysis_bio_pairwise_combinations
    if (is.null(current)) current <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
    
    # Find available (order-insensitive; treat A vs B same as B vs A)
    pair_key <- function(g1, g2) {
      apply(cbind(as.character(g1), as.character(g2)), 1, function(x) {
        paste(sort(trimws(x)), collapse = "||")
      })
    }

    current_keys <- if (nrow(current) > 0) {
      pair_key(current$Group_1, current$Group_2)
    } else character(0)

    all_keys <- pair_key(all_bio$Group_1, all_bio$Group_2)
    available <- all_bio[!all_keys %in% current_keys, ]
    
    if (nrow(available) == 0) {
      showNotification("All biological comparisons have been added.", type = "warning")
      return()
    }
    
    values$preanalysis_bio_pairwise_combinations <- rbind(current, available[1, ])
    values$preanalysis_bio_ui_version <- (values$preanalysis_bio_ui_version %||% 0) + 1
    showNotification("Biological comparison added.", type = "message", duration = 2)
  })
  
  # Reset biological comparisons
  observeEvent(input$preAnalysisBioResetBtn, {
    if (!isTRUE(values$has_dual_grouping)) return()
    
    bio_groups <- values$biological_unique_groups
    if (is.null(bio_groups) || length(bio_groups) < 2) return()
    
    # Generate all possible bio combinations
    all_bio <- data.frame(
      Group_1 = character(0),
      Group_2 = character(0),
      stringsAsFactors = FALSE
    )
    for (i in 1:(length(bio_groups) - 1)) {
