  # Reset experimental comparisons
  observeEvent(input$preAnalysisExpResetBtn, {
    if (!isTRUE(values$has_dual_grouping)) return()
    
    exp_groups <- values$experimental_unique_groups
    if (is.null(exp_groups) || length(exp_groups) < 2) return()
    
    # Generate all possible exp combinations
    all_exp <- data.frame(
      Group_1 = character(0),
