    )
    for (i in 1:(length(exp_groups) - 1)) {
      for (j in (i + 1):length(exp_groups)) {
        all_exp <- rbind(all_exp, data.frame(
          Group_1 = exp_groups[i],
          Group_2 = exp_groups[j],
          stringsAsFactors = FALSE
        ))
      }
    }
    
    values$preanalysis_exp_pairwise_combinations <- all_exp
    values$preanalysis_exp_ui_version <- (values$preanalysis_exp_ui_version %||% 0) + 1
    showNotification(paste0("Reset experimental: ", nrow(all_exp), " comparison(s)."), type = "message", duration = 2)
  })

  # Clear experimental comparisons
  observeEvent(input$preAnalysisExpClearBtn, {
