  # ==================== END DUAL GROUPING BUTTON HANDLERS ====================
  
  # Handle changes to pre-analysis editable group selections
  observe({
    if (is.null(values$preanalysis_pairwise_combinations) || nrow(values$preanalysis_pairwise_combinations) == 0) {
      return()
    }
    
    # Get all edit inputs for pre-analysis modal
    edit_inputs <- grep("^preanalysis_group[12]_", names(input), value = TRUE)
    
    if (length(edit_inputs) > 0) {
      for (input_name in edit_inputs) {
        # Extract row index and group type from input name
        parts <- strsplit(input_name, "_")[[1]]
        row_index <- as.numeric(parts[3])
        group_type <- parts[2]  # "group1" or "group2"
        
        if (!is.null(input[[input_name]]) &&
            row_index <= nrow(values$preanalysis_pairwise_combinations)) {
          
          new_value <- input[[input_name]]
          column_name <- ifelse(group_type == "group1", "Group_1", "Group_2")
          
          # Update the data frame
          values$preanalysis_pairwise_combinations[row_index, column_name] <- new_value
        }
      }
    }
  })

  # Handle changes to biological editable group selections in pre-analysis modal
  observe({
    if (is.null(values$preanalysis_bio_pairwise_combinations) || nrow(values$preanalysis_bio_pairwise_combinations) == 0) {
      return()
    }

    # Get all biological edit inputs
    edit_inputs <- grep("^bio_group[12]_", names(input), value = TRUE)

    if (length(edit_inputs) > 0) {
      for (input_name in edit_inputs) {
        # Extract row index and group type from input name
        parts <- strsplit(input_name, "_")[[1]]
        row_index <- as.numeric(parts[3])
        group_type <- parts[2]  # "group1" or "group2"

        if (!is.null(input[[input_name]]) &&
            row_index <= nrow(values$preanalysis_bio_pairwise_combinations)) {

          new_value <- input[[input_name]]
          column_name <- ifelse(group_type == "group1", "Group_1", "Group_2")
          old_value <- values$preanalysis_bio_pairwise_combinations[row_index, column_name]

          # Skip no-op updates
          if (identical(as.character(new_value), as.character(old_value))) {
            next
          }

          # Validate candidate update (order-insensitive duplicate check)
          candidate <- values$preanalysis_bio_pairwise_combinations
          candidate[row_index, column_name] <- new_value
          pair_keys <- apply(cbind(as.character(candidate$Group_1), as.character(candidate$Group_2)), 1, function(x) {
            paste(sort(trimws(x)), collapse = "||")
          })

          if (any(duplicated(pair_keys))) {
            if (!is.null(session)) {
              updateSelectInput(session, input_name, selected = old_value)
              showNotification("Duplicate biological comparison not allowed (including reverse order).", type = "warning", duration = 3)
            }
            next
          }

          values$preanalysis_bio_pairwise_combinations <- candidate
        }
      }
    }
  })

