  # Handle remove buttons for pre-analysis modal
  observe({
    if (is.null(values$preanalysis_pairwise_combinations) || nrow(values$preanalysis_pairwise_combinations) == 0) {
      return()
    }
    
    # Get all remove buttons
    remove_btns <- grep("^preanalysis_remove_", names(input), value = TRUE)
    
    if (length(remove_btns) > 0) {
      # Initialize tracking if not exists
      if (is.null(values$preanalysis_remove_btn_states)) {
        values$preanalysis_remove_btn_states <- list()
      }
      
      for (btn_name in remove_btns) {
        current_value <- input[[btn_name]]
        
        if (!is.null(current_value)) {
          # Get the last known value for this button
          last_value <- values$preanalysis_remove_btn_states[[btn_name]]
          
          # Only process if the value has increased (actual click)
          if (!is.null(last_value) && current_value > last_value && current_value > 0) {
            # Extract row index
            row_index <- as.numeric(gsub("preanalysis_remove_", "", btn_name))
            
            if (row_index <= nrow(values$preanalysis_pairwise_combinations)) {
              # Remove the row
              values$preanalysis_pairwise_combinations <- values$preanalysis_pairwise_combinations[-row_index, ]
              
              # Increment UI version to trigger re-render
              values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
              
              if (!is.null(session)) {
                showNotification("Comparison removed.", type = "message", duration = 2)
              }
              
              # Clear all button states since UI will be re-rendered
              values$preanalysis_remove_btn_states <- list()
              break  # Only handle one button click per observation
            }
          }
          
          # Update the tracked state for this button
          values$preanalysis_remove_btn_states[[btn_name]] <- current_value
        }
      }
    }
  })
  
