  # Handle add new comparison button for pre-analysis modal
  observeEvent(input$preAnalysisAddComparisonBtn, {
    if (is.null(values$unique_groups) || length(values$unique_groups) < 2) {
      if (!is.null(session)) {
        showNotification("Not enough groups available for comparison.", type = "warning")
      }
      return()
    }
    
    # Find available combinations
    current_combinations <- if (!is.null(values$preanalysis_pairwise_combinations)) {
      values$preanalysis_pairwise_combinations
    } else {
      data.frame(Group_1 = character(0), Group_2 = character(0))
    }
    
    # Get all possible combinations
    all_possible <- get_all_possible_pairwise_combinations()
    
    # Find combinations not already selected
    if (nrow(current_combinations) > 0) {
      current_keys_forward <- paste(current_combinations$Group_1, current_combinations$Group_2, sep = "_")
      current_keys_reverse <- paste(current_combinations$Group_2, current_combinations$Group_1, sep = "_")
      current_keys_all <- c(current_keys_forward, current_keys_reverse)
      
      all_keys <- paste(all_possible$Group_1, all_possible$Group_2, sep = "_")
      
      available_combinations <- all_possible[!all_keys %in% current_keys_all, ]
    } else {
      available_combinations <- all_possible
    }
    
    if (nrow(available_combinations) == 0) {
      if (!is.null(session)) {
        showNotification("All possible pairwise combinations have been added.", type = "warning")
      }
      return()
    }
    
    # Add the first available combination
    new_combo <- available_combinations[1, ]
    
    if (is.null(values$preanalysis_pairwise_combinations)) {
      values$preanalysis_pairwise_combinations <- new_combo
    } else {
      values$preanalysis_pairwise_combinations <- rbind(values$preanalysis_pairwise_combinations, new_combo)
    }
    
    # Increment UI version to trigger re-render
    values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
    
    if (!is.null(session)) {
      showNotification("New comparison added.", type = "message", duration = 2)
    }
  })
  
  # Handle reset button for pre-analysis modal
  observeEvent(input$preAnalysisResetBtn, {
    # Get all possible combinations (default order)
    all_possible <- get_all_possible_pairwise_combinations()
    
    if (is.null(all_possible) || nrow(all_possible) == 0) {
      if (!is.null(session)) {
        showNotification("No groups available to create pairwise combinations.", type = "warning")
      }
      return()
    }
    
    # Reset to all possible combinations
    values$preanalysis_pairwise_combinations <- all_possible
    
    # Increment UI version to trigger re-render
    values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
    
    if (!is.null(session)) {
      showNotification(paste0("Reset to default: ", nrow(all_possible), " comparison(s)."), type = "message", duration = 2)
    }
  })
  
  # Handle Clear All button - remove all comparisons in pre-analysis modal (single grouping)
  observeEvent(input$preAnalysisClearAllBtn, {
    values$preanalysis_pairwise_combinations <- data.frame(
      Group_1 = character(0),
      Group_2 = character(0),
      stringsAsFactors = FALSE
    )
    
    # Increment UI version to trigger re-render
    values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
    
    if (!is.null(session)) {
      showNotification("Cleared all pairwise comparisons.", type = "message", duration = 2)
    }
  })
  
  # Handle cancel button for pre-analysis modal
  observeEvent(input$cancelPreAnalysisPairwise, {
    shinyBS::toggleModal(session, "preAnalysisPairwiseModal", toggle = "close")
    # Reset pending state
    values$pending_pairwise_confirmation <- FALSE
    showNotification("Analysis cancelled. You can reconfigure group mapping if needed.", type = "warning", duration = 3)
  })
  
  # Handle confirm button for pre-analysis pairwise modal - proceed with analysis
  observeEvent(input$confirmPreAnalysisPairwise, {
    # Handle DUAL GROUPING mode separately
    if (isTRUE(values$has_dual_grouping)) {
      # ==================== DUAL GROUPING: Collect biological comparisons ====================
      bio_combos <- values$preanalysis_bio_pairwise_combinations
      if (!is.null(bio_combos) && nrow(bio_combos) > 0) {
        # Update from UI
        for (i in 1:nrow(bio_combos)) {
          g1 <- input[[paste0("bio_group1_", i)]]
          g2 <- input[[paste0("bio_group2_", i)]]
          if (!is.null(g1) && !is.null(g2)) {
            bio_combos[i, "Group_1"] <- g1
            bio_combos[i, "Group_2"] <- g2
          }
        }
        # Remove same-group comparisons
        bio_combos <- bio_combos[bio_combos$Group_1 != bio_combos$Group_2, , drop = FALSE]
        # Remove duplicates
        if (nrow(bio_combos) > 1) {
          keys <- apply(bio_combos, 1, function(r) paste(sort(c(r["Group_1"], r["Group_2"])), collapse = "_"))
          bio_combos <- bio_combos[!duplicated(keys), , drop = FALSE]
        }
      }
      if (is.null(bio_combos) || nrow(bio_combos) == 0) {
        showNotification("No valid biological comparisons. Please add at least one.", type = "error", duration = 5)
        return()
      }
      values$biological_pairwise_combinations <- bio_combos
      
      # ==================== DUAL GROUPING: Collect experimental comparisons ====================
      exp_combos <- values$preanalysis_exp_pairwise_combinations
      if (!is.null(exp_combos) && nrow(exp_combos) > 0) {
        # Update from UI
        for (i in 1:nrow(exp_combos)) {
          g1 <- input[[paste0("exp_group1_", i)]]
          g2 <- input[[paste0("exp_group2_", i)]]
          if (!is.null(g1) && !is.null(g2)) {
            exp_combos[i, "Group_1"] <- g1
            exp_combos[i, "Group_2"] <- g2
          }
        }
        # Remove same-group comparisons
        exp_combos <- exp_combos[exp_combos$Group_1 != exp_combos$Group_2, , drop = FALSE]
        # Remove duplicates
        if (nrow(exp_combos) > 1) {
          keys <- apply(exp_combos, 1, function(r) paste(sort(c(r["Group_1"], r["Group_2"])), collapse = "_"))
          exp_combos <- exp_combos[!duplicated(keys), , drop = FALSE]
        }
      }
      if (is.null(exp_combos) || nrow(exp_combos) == 0) {
        showNotification("No valid experimental comparisons. Please add at least one.", type = "error", duration = 5)
        return()
      }
      values$experimental_pairwise_combinations <- exp_combos
      
      # For dual grouping, set the default/current to biological (as active level default)
      values$current_pairwise_combinations <- bio_combos
      values$selected_pairwise_for_analysis <- bio_combos
      
      # Store skip preference
      if (isTRUE(input$skipPairwiseSelection)) {
        values$skip_pairwise_selection <- TRUE
      }
      
      showNotification(
        sprintf("Dual grouping: %d biological + %d experimental comparison(s) configured.",
                nrow(bio_combos), nrow(exp_combos)),
        type = "message", duration = 4
      )
      
      # Close modal and proceed
      shinyBS::toggleModal(session, "preAnalysisPairwiseModal", toggle = "close")
      values$pairwise_selection_confirmed <- TRUE
      values$pending_pairwise_confirmation <- FALSE
      return()
    }
    
    # ==================== SINGLE GROUPING MODE (original logic) ====================
    # Collect edited values from the UI
    if (!is.null(values$preanalysis_pairwise_combinations) && nrow(values$preanalysis_pairwise_combinations) > 0) {
      # Update the data frame with edited values from selectInputs
      for (i in 1:nrow(values$preanalysis_pairwise_combinations)) {
        group1_input <- input[[paste0("preanalysis_group1_", i)]]
        group2_input <- input[[paste0("preanalysis_group2_", i)]]
        
        if (!is.null(group1_input) && !is.null(group2_input)) {
          values$preanalysis_pairwise_combinations[i, "Group_1"] <- group1_input
          values$preanalysis_pairwise_combinations[i, "Group_2"] <- group2_input
        }
      }
      
      # Remove any comparisons where Group_1 == Group_2
      values$preanalysis_pairwise_combinations <- values$preanalysis_pairwise_combinations[
        values$preanalysis_pairwise_combinations$Group_1 != values$preanalysis_pairwise_combinations$Group_2, , drop = FALSE
      ]
      
      # Remove duplicate comparisons
      if (nrow(values$preanalysis_pairwise_combinations) > 1) {
        comparison_keys <- apply(values$preanalysis_pairwise_combinations, 1, function(row) {
          groups <- sort(c(row["Group_1"], row["Group_2"]))
          paste(groups[1], groups[2], sep = "_")
        })
        
        unique_indices <- !duplicated(comparison_keys)
        
        if (sum(!unique_indices) > 0) {
          showNotification(paste0("Removed ", sum(!unique_indices), " duplicate comparison(s)."), type = "warning", duration = 3)
        }
        
        values$preanalysis_pairwise_combinations <- values$preanalysis_pairwise_combinations[unique_indices, , drop = FALSE]
      }
      
      # Check if there are any comparisons left
      if (nrow(values$preanalysis_pairwise_combinations) == 0) {
        showNotification("No valid comparisons selected. Please add at least one comparison.", type = "error", duration = 5)
        return()
      }
      
      # Set current_pairwise_combinations to the selected combinations
      # This ensures that the analysis will use only these comparisons
      values$current_pairwise_combinations <- values$preanalysis_pairwise_combinations
      
      # Store the selected pairwise combinations for use during analysis
      values$selected_pairwise_for_analysis <- values$preanalysis_pairwise_combinations
      
      # Store skip preference for this session
      if (isTRUE(input$skipPairwiseSelection)) {
        values$skip_pairwise_selection <- TRUE
      }
      
      showNotification(paste0("Proceeding with ", nrow(values$preanalysis_pairwise_combinations), " pairwise comparison(s)."), 
                       type = "message", duration = 3)
    } else {
      # If no comparisons, use all possible as default
      all_possible <- get_all_possible_pairwise_combinations()
      values$current_pairwise_combinations <- all_possible
      values$selected_pairwise_for_analysis <- all_possible
      showNotification(paste0("Using default: ", nrow(all_possible), " pairwise comparison(s)."), type = "message", duration = 3)
    }
    
    # Close the modal
    shinyBS::toggleModal(session, "preAnalysisPairwiseModal", toggle = "close")
    
    # Set flag to indicate pairwise selection is confirmed and analysis can proceed
    values$pairwise_selection_confirmed <- TRUE
    values$pending_pairwise_confirmation <- FALSE
  })
  
  # ==================== END PRE-ANALYSIS PAIRWISE SELECTION MODAL HANDLERS ====================
  
