  # Display annotation database status
  output$annotation_db_status_text <- renderText({
    if (exists(".annotation_cache", envir = .GlobalEnv)) {
      loaded_orgs <- get("loaded_organisms", envir = .GlobalEnv$.annotation_cache, inherits = FALSE)
      failed_orgs <- get("failed_organisms", envir = .GlobalEnv$.annotation_cache, inherits = FALSE)
      
      status_text <- paste("Annotation Database Status:\n")
      
      if (length(loaded_orgs) > 0) {
        status_text <- paste0(status_text, "? Pre-loaded: ", paste(loaded_orgs, collapse = ", "), "\n")
      }
      
      if (length(failed_orgs) > 0) {
        status_text <- paste0(status_text, "? On-demand: ", paste(failed_orgs, collapse = ", "), "\n")
      }
      
      if (length(loaded_orgs) == 0 && length(failed_orgs) == 0) {
        status_text <- paste0(status_text, "? All databases will be loaded on-demand\n")
      }
      
      return(status_text)
    } else {
      return("? Annotation Database Status:\nAll databases will be loaded on-demand")
    }
  })
  
