  ensure_directory <- function(dir_name) {
    # Create directory if it doesn't exist
    if (!dir.exists(dir_name)) {
      dir.create(dir_name, recursive = TRUE, showWarnings = FALSE)
      
      # Check if creation was successful
      if (!dir.exists(dir_name)) {
        # If creation failed, try using a different location
        alt_dir <- file.path(tempdir(), dir_name)
        dir.create(alt_dir, recursive = TRUE, showWarnings = FALSE)
        if (!is.null(session)) {
          showNotification(paste("Couldn't create directory in working folder. Using temporary directory:", alt_dir),
                           type = "warning", duration = 10)
        }
        return(alt_dir)
      }
    }
    return(dir_name)
  }
  
  `%||%` <- function(x, y) {
    if (is.null(x)) y else x
  }
  
  # Helper function to create proper group labels based on actual column assignments
  # This fixes the issue where samples are not arranged strictly according to groups in raw data
  create_proper_group_labels <- function(unique_groups, group_column_indices) {
    all_columns <- unlist(group_column_indices)
    group_labels <- character(length(all_columns))
    
    for (i in seq_along(unique_groups)) {
      group_name <- unique_groups[i]
      group_cols <- group_column_indices[[i]]
      # Find which positions in all_columns correspond to this group
      group_positions <- which(all_columns %in% group_cols)
      group_labels[group_positions] <- group_name
    }
    
    return(group_labels)
  }

  # Helper to preserve group order from mapping modal (not alphabetical)
  get_group_order_for_plot <- function(target_groups = NULL) {
    order <- NULL
    if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
      if (values$active_grouping_level == "biological") {
        order <- input$bio_levels
        if (is.null(order) || length(order) == 0) {
          order <- values$biological_unique_groups %||% unique(values$final_biological_groups)
        }
      } else {
        order <- input$exp_levels
        if (is.null(order) || length(order) == 0) {
          order <- values$experimental_unique_groups %||% unique(values$final_experimental_groups)
        }
      }
    } else {
      order <- input$bio_levels
      if (is.null(order) || length(order) == 0) {
        order <- values$unique_groups %||% unique(values$final_biological_groups)
      }
    }

    if (is.null(order)) order <- character(0)
    order <- as.character(order)

    if (!is.null(target_groups) && length(target_groups) > 0) {
      target_groups <- as.character(target_groups)
      ordered <- order[order %in% target_groups]
      missing <- target_groups[!(target_groups %in% ordered)]
      order <- c(ordered, missing)
    }

    if (length(order) == 0 && !is.null(target_groups) && length(target_groups) > 0) {
      order <- unique(as.character(target_groups))
    }

    unique(order)
  }
  
  # Helper function to flexibly match group column names in metadata
  # Handles variants like: Biological_Group, Biological_Groups, BiologicalGroup, Biological Group, Bio Group, BioGroup, etc.
  find_group_column <- function(colnames_vec, group_type = "biological") {
    lower_colnames <- tolower(colnames_vec)
    
    if (group_type == "biological") {
      # Match variations of biological group column
      patterns <- c(
        "^biological\\s*groups?$",  # Biological Group(s)
        "^biologicalgroup(s)?$",    # BiologicalGroup(s)
        "^bio\\s*group(s)?$",       # Bio Group(s)
        "^biogroup(s)?$",           # BioGroup(s)
        "^biology\\s*group(s)?$",   # Biology Group(s)
        "biological.*group|bio.*group"  # Any combo with biological or bio
      )
    } else if (group_type == "experimental") {
      # Match variations of experimental group column
      patterns <- c(
        "^experimental\\s*groups?$",  # Experimental Group(s)
        "^experimentalgroup(s)?$",    # ExperimentalGroup(s)
        "^exp\\s*group(s)?$",         # Exp Group(s)
        "^expgroup(s)?$",             # ExpGroup(s)
        "^experiment\\s*group(s)?$",  # Experiment Group(s)
        "experimental.*group|exp.*group"  # Any combo with experimental or exp
      )
    } else {
      return(NA_integer_)
    }
    
    # Try to match patterns
    for (pattern in patterns) {
      matches <- which(grepl(pattern, lower_colnames, ignore.case = TRUE))
      if (length(matches) > 0) {
        return(matches[1])  # Return first match
      }
    }
    
    return(NA_integer_)  # No match found
  }

