  # Enhanced hierarchical grouping detection from sample names
  # Returns:
  # - biological: character vector (len = length(sample_names)) of primary groups (e.g., Control, Disease)
  # - experimental: character vector of secondary groups (e.g., Control_12h, Disease_24h)
  # - delimiter: one of underscore|dot|hyphen|none
  # - method: detection strategy description
  # - is_complex: TRUE if experimental groups add meaningful substructure beyond biological
  # - tokens: list of character vectors per sample (split by delimiter if any)
  detect_hierarchical_groups <- function(sample_names) {
    if (length(sample_names) == 0) {
      return(list(
        biological = character(0),
        experimental = character(0),
        delimiter = "none",
        method = "none",
        is_complex = FALSE,
        tokens = replicate(0, character(0), simplify = FALSE)
      ))
    }
    # Supported delimiters: underscore, dot, hyphen
    delims <- c("_", "\\.", "-")
    delim_names <- c("underscore", "dot", "hyphen")
    best <- list(score = -1, primary = NULL, secondary = NULL, delim = "none", method = "fallback")
    
    # Try each delimiter that appears in names
    for (i in seq_along(delims)) {
      delim <- delims[i]
      delim_name <- delim_names[i]
      actual <- gsub("\\\\", "", delim)
      if (!any(grepl(delim, sample_names))) next
      
      split_names <- strsplit(sample_names, actual, fixed = FALSE)
      max_parts <- max(lengths(split_names))
      
      # evaluate 1..min(4, max_parts) as candidate primary levels
      for (parts in 1:min(4, max_parts)) {
        primary <- vapply(split_names, function(p) paste(p[seq_len(min(length(p), parts))], collapse = actual), character(1))
        uniq <- unique(primary)
        # scoring: avoid 1 group, avoid all-unique
        if (length(uniq) == 1 || length(uniq) == length(sample_names)) {
          score <- 0
        } else {
          sz <- table(primary)
          min_sz <- min(sz)
          max_sz <- max(sz)
          balance <- if (max_sz > 0) 1 - (max_sz - min_sz)/max_sz else 0
          replication <- min(min_sz/2, 1) # prefer >=2 replicates
          n_groups <- length(uniq)
          group_span <- ifelse(n_groups >= 2 && n_groups <= 12, 1, 0.5)
          score <- 0.4*balance + 0.4*replication + 0.2*group_span
        }
        if (score > best$score) {
          best$score <- score
          best$primary <- primary
          best$delim <- delim_name
          best$method <- paste0("multi_level_", parts, "_parts")
          # propose secondary = primary with one more token (if exists)
          if (parts < max_parts) {
            secondary <- vapply(split_names, function(p) paste(p[seq_len(min(length(p), parts+1))], collapse = actual), character(1))
          } else {
            secondary <- primary
          }
          best$secondary <- secondary
        }
      }
    }
    
    # Fallback if nothing matched (no delimiters) OR if best score is too low
    # For simple experiments like normal.1, disease.2, extract biological groups by removing delimiter+number
    if (is.null(best$primary) || best$score < 0.3) {
      # Try removing trailing delimiter+digits pattern for biological groups
      primary <- stringr::str_replace(sample_names, "([_\\.\\-])\\d+$", "")
      # If that didn't create meaningful groups, try removing just trailing digits
      if (length(unique(primary)) == length(sample_names) || length(unique(primary)) == 1) {
        primary <- stringr::str_replace(sample_names, "\\d+$", "")
      }
      # If still no groups, use the full names
      if (length(unique(primary)) == 1) {
        primary <- sample_names
      }
      secondary <- primary
      return(list(
        biological = primary,
        experimental = secondary,
        delimiter = "pattern_based",
        method = "delimiter_number_removal",
        is_complex = FALSE,
        tokens = lapply(sample_names, function(x) x)
      ))
    }
    
    # If secondary provides no extra structure, keep it equal to primary
    is_complex <- length(unique(best$secondary)) > length(unique(best$primary)) &&
      length(unique(best$secondary)) < length(sample_names)
    
    # Reconstruct token list for reference
    actual_delim <- switch(best$delim, underscore = "_", dot = ".", hyphen = "-", "_")
    tokens <- strsplit(sample_names, actual_delim, fixed = TRUE)
    
    list(
      biological = best$primary,
      experimental = if (is_complex) best$secondary else best$primary,
      delimiter = best$delim,
      method = best$method,
      is_complex = is_complex,
      tokens = tokens
    )
  }
  
  # Helper function to parse MOFA metadata file with flexible column name matching
  parse_mofa_metadata <- function(file_path) {
    tryCatch({
      # Read file - detect format and read accordingly
      file_ext <- tolower(tools::file_ext(file_path))
      
      metadata <- if (file_ext == "xlsx") {
        # Read XLSX file
        if (!requireNamespace("readxl", quietly = TRUE)) {
          return(list(success = FALSE, message = "readxl package required to read .xlsx files. Install with: install.packages('readxl')"))
        }
        readxl::read_excel(file_path, col_types = "text")  # Read as text to preserve formats
      } else {
        # Read CSV/TSV
        read.csv(file_path, stringsAsFactors = FALSE, check.names = FALSE,
                 sep = if (grepl("\\.tsv$", file_path, ignore.case = TRUE)) "\t" else ",")
      }
      
      if (nrow(metadata) == 0) {
        return(list(success = FALSE, message = "Metadata file is empty"))
      }
      
      col_names <- colnames(metadata)
      
      # Find SampleID column (required)
      sample_col <- which(tolower(col_names) == "sampleid")
      if (length(sample_col) == 0) {
        # Try without exact match
        sample_col <- which(grepl("sample", tolower(col_names), ignore.case = TRUE))[1]
        if (is.na(sample_col)) {
          return(list(success = FALSE, message = "Cannot find 'SampleID' column. Please ensure metadata has a column named 'SampleID' (or similar)"))
        }
      }
      
      sample_col <- sample_col[1]
      sample_col_name <- col_names[sample_col]
      
      # Find Biological Group column (optional)
      bio_col_idx <- find_group_column(col_names, "biological")
      bio_col <- if (!is.na(bio_col_idx)) col_names[bio_col_idx] else NA
      
      # Find Experimental Group column (optional)
      exp_col_idx <- find_group_column(col_names, "experimental")
      exp_col <- if (!is.na(exp_col_idx)) col_names[exp_col_idx] else NA
      
      # Get sample IDs
      sample_ids <- metadata[[sample_col]]
      
      # Get groups if available
      bio_groups <- if (!is.na(bio_col) && bio_col %in% colnames(metadata)) {
        metadata[[bio_col]]
      } else {
        NULL
      }
      
      exp_groups <- if (!is.na(exp_col) && exp_col %in% colnames(metadata)) {
        metadata[[exp_col]]
      } else {
        NULL
      }
      
      # Extract additional covariates (columns not used for groups)
      excluded_cols <- c("SampleID", sample_col)
      if (!is.na(bio_col)) excluded_cols <- c(excluded_cols, bio_col)
      if (!is.na(exp_col)) excluded_cols <- c(excluded_cols, exp_col)
      
      covariate_cols <- col_names[!(col_names %in% excluded_cols)]
      
      # Detect covariate data types
      covariate_types <- setNames(rep("unknown", length(covariate_cols)), covariate_cols)
      for (col in covariate_cols) {
        col_data <- metadata[[col]]
        # Try to convert to numeric
        numeric_test <- suppressWarnings(as.numeric(col_data))
        if (sum(!is.na(numeric_test)) / length(col_data) > 0.8) {
          covariate_types[col] <- "numeric"
        } else {
          covariate_types[col] <- "categorical"
        }
      }
      
      return(list(
        success = TRUE,
        sample_ids = sample_ids,
        sample_col_name = sample_col_name,
        biological_groups = bio_groups,
        biological_col_name = if (!is.na(bio_col)) bio_col else "Not found",
        experimental_groups = exp_groups,
        experimental_col_name = if (!is.na(exp_col)) exp_col else "Not found",
        covariates = if (length(covariate_cols) > 0) metadata[covariate_cols] else NULL,
        covariate_names = covariate_cols,
        covariate_types = covariate_types,
        full_metadata = metadata,
        message = paste(
          "Found", length(sample_ids), "samples.",
          if (!is.na(bio_col)) paste("Biological groups found:", paste(unique(bio_groups), collapse = ", ")) else "",
          if (!is.na(exp_col)) paste("Experimental groups found:", paste(unique(exp_groups), collapse = ", ")) else "",
          if (length(covariate_cols) > 0) paste("Covariates found:", paste(covariate_cols, collapse = ", ")) else ""
        )
      ))
    }, error = function(e) {
      list(success = FALSE, message = paste("Error reading metadata file:", conditionMessage(e)))
    })
  }
  
  # Covariate association testing function
  correlate_factors_with_covariates <- function(factors_df, covariates_df, covariate_types,
                                                correction_method = "BH") {
    tryCatch({
      if (is.null(factors_df) || nrow(factors_df) == 0) {
        return(list(success = FALSE, message = "No factors available"))
      }
      if (is.null(covariates_df) || ncol(covariates_df) == 0) {
        return(list(success = FALSE, message = "No covariates available"))
      }
      
      factor_cols <- colnames(factors_df)
      covariate_cols <- colnames(covariates_df)
      
      # Initialize results matrix
      p_values <- matrix(1.0, nrow = length(factor_cols), ncol = length(covariate_cols),
                         dimnames = list(factor_cols, covariate_cols))
      correlations <- matrix(0, nrow = length(factor_cols), ncol = length(covariate_cols),
                             dimnames = list(factor_cols, covariate_cols))
      
      # Test each factor-covariate pair
      for (f in factor_cols) {
        factor_values <- as.numeric(factors_df[[f]])
        
        for (c in covariate_cols) {
          cov_data <- covariates_df[[c]]
          cov_type <- covariate_types[c]
          
          if (cov_type == "numeric") {
            # For numeric covariates: Pearson correlation test
            cov_numeric <- suppressWarnings(as.numeric(cov_data))
            valid_idx <- !is.na(factor_values) & !is.na(cov_numeric)
            
            if (sum(valid_idx) > 2) {
              cor_test <- cor.test(factor_values[valid_idx], cov_numeric[valid_idx],
                                   method = "pearson")
              p_values[f, c] <- cor_test$p.value
              correlations[f, c] <- cor_test$estimate
            }
          } else {
            # For categorical covariates: Kruskal-Wallis test
            valid_idx <- !is.na(factor_values) & !is.na(cov_data)
            
            if (sum(valid_idx) > 2) {
              groups <- unique(cov_data[valid_idx])
              if (length(groups) > 1) {
                group_data <- split(factor_values[valid_idx], cov_data[valid_idx])
                kw_test <- kruskal.test(group_data)
                p_values[f, c] <- kw_test$p.value
                
                # Calculate effect size (eta-squared)
                grand_mean <- mean(factor_values[valid_idx])
                between_ss <- sum(sapply(group_data, function(x) length(x) * (mean(x) - grand_mean)^2))
                total_ss <- sum((factor_values[valid_idx] - grand_mean)^2)
                correlations[f, c] <- sqrt(between_ss / total_ss)
              }
            }
          }
        }
      }
      
      # Apply multiple testing correction
      p_values_flat <- as.numeric(p_values)
      p_adj <- p.adjust(p_values_flat, method = correction_method)
      p_adj_matrix <- matrix(p_adj, nrow = nrow(p_values), ncol = ncol(p_values),
                             dimnames = dimnames(p_values))
      
      return(list(
        success = TRUE,
        p_values = p_values,
        p_values_adjusted = p_adj_matrix,
        correlations = correlations,
        correction_method = correction_method
      ))
    }, error = function(e) {
      list(success = FALSE, message = paste("Error in correlation analysis:", conditionMessage(e)))
    })
  }

  # Helper: safely merge per-sample metadata into an existing MOFA object
  safe_merge_samples_metadata <- function(mofa_model, new_metadata_df) {
    if (is.null(new_metadata_df) || nrow(new_metadata_df) == 0) return(mofa_model)

    current <- tryCatch(MOFA2::samples_metadata(mofa_model), error = function(e) NULL)

    # If current metadata is empty, try to construct a sample order from factors if available
    if (is.null(current) || nrow(current) == 0) {
      sample_order <- tryCatch({
        if (!is.null(MOFA2::factors(mofa_model))) as.character(MOFA2::factors(mofa_model)$Sample) else NULL
      }, error = function(e) NULL)
      current <- data.frame(sample = sample_order, stringsAsFactors = FALSE)
    }

    if (!"sample" %in% colnames(current)) {
      current$sample <- if (!is.null(rownames(current)) && all(nzchar(rownames(current)))) rownames(current) else as.character(seq_len(nrow(current)))
    }

    # Ensure new_metadata_df has a proper 'sample' column
    if (!"sample" %in% colnames(new_metadata_df)) stop("New metadata must include a 'sample' column")
    new_metadata_df <- as.data.frame(new_metadata_df, stringsAsFactors = FALSE)
    new_metadata_df <- new_metadata_df[!is.na(new_metadata_df$sample) & nzchar(new_metadata_df$sample), , drop = FALSE]
    if (any(duplicated(new_metadata_df$sample))) new_metadata_df <- new_metadata_df[!duplicated(new_metadata_df$sample), , drop = FALSE]

    match_idx <- match(current$sample, new_metadata_df$sample)
    cols_to_add <- setdiff(colnames(new_metadata_df), c("sample"))
    for (col_name in cols_to_add) {
      current[[col_name]] <- new_metadata_df[[col_name]][match_idx]
    }

    MOFA2::samples_metadata(mofa_model) <- current
    mofa_model
  }
  
