        input$proteomics_plot_type == "gseaplot2") {
      shinyjs::show("gseaplot2_controls")
    } else {
      shinyjs::hide("gseaplot2_controls")
    }
    
    # Show/hide Manhattan plot controls based on tool and plot type
    if (input$proteomics_tool == "gprofiler" &&
        !is.null(input$proteomics_plot_type) &&
        input$proteomics_plot_type == "manhattan") {
      shinyjs::show("manhattan_plot_controls")
    } else {
      shinyjs::hide("manhattan_plot_controls")
    }
    
    # Show/hide topGO GOGraph controls based on tool and plot type
    if (input$proteomics_tool == "topgo" &&
        !is.null(input$proteomics_plot_type) &&
        input$proteomics_plot_type == "gograph") {
      shinyjs::show("topgo_gograph_controls")
    } else {
      shinyjs::hide("topgo_gograph_controls")
    }
  })
  
  # Update MSigDB subcategories based on selected category
  # Use debounce to reduce frequency of expensive msigdbr calls
  msigdb_category_debounced <- debounce(reactive({
    list(
      category = input$proteomics_cp_msigdb_category,
      organism = input$proteomics_organism,
      tool = input$proteomics_tool,
      analysis = input$proteomics_cp_analysis
    )
  }), 500) # 500ms delay
  
  observe({
    inputs <- msigdb_category_debounced()
    
    # Only run if MSigDB is selected and inputs are available
    if (!is.null(inputs$category) &&
        !is.null(inputs$tool) &&
        !is.null(inputs$analysis) &&
        inputs$tool == "clusterprofiler" &&
        inputs$analysis == "msigdb") {
      
      tryCatch({
        # Get available subcategories for the selected category
        if (requireNamespace("msigdbr", quietly = TRUE)) {
          organism_code <- switch(inputs$organism,
                                  hsapiens = "Homo sapiens",
                                  mmusculus = "Mus musculus",
                                  rnorvegicus = "Rattus norvegicus",
                                  dmelanogaster = "Drosophila melanogaster",
                                  drerio = "Danio rerio",
                                  athaliana = "Arabidopsis thaliana",
                                  scerevisiae = "Saccharomyces cerevisiae",
                                  ecoli = "Escherichia coli"
          )
          
          # Get all MSigDB gene sets for the selected category and organism (optimized query)
          msigdb_data <- msigdbr::msigdbr(species = organism_code, category = inputs$category)
          
          # Get unique subcategories
          subcategories <- unique(msigdb_data$gs_subcat)
          subcategories <- subcategories[!is.na(subcategories) & subcategories != ""]
          
          # Create choices list
          if (length(subcategories) > 0) {
            choices <- c("All" = "", setNames(subcategories, subcategories))
          } else {
            choices <- c("All" = "")
          }
          
          updateSelectInput(session, "proteomics_cp_msigdb_subcategory", choices = choices)
        }
      }, error = function(e) {
        # If there's an error, just show "All"
        updateSelectInput(session, "proteomics_cp_msigdb_subcategory", choices = c("All" = ""))
      })
    }
  })
  
