      "KEGG Module - ORA" = "kegg_module",
      "Reactome Pathway - ORA" = "reactome",
      "Disease Ontology - ORA" = "do",
      "Pathway Commons - ORA" = "pathwaycommons",
      "WikiPathways - ORA" = "wikipathways",
      "MSigDB - ORA" = "msigdb",
      "Gene Ontology (GO) - GSEA" = "gsea_go",
      "KEGG Pathway - GSEA" = "gsea_kegg",
      "KEGG Module - GSEA" = "gsea_kegg_module",
      "Reactome Pathway - GSEA" = "gsea_reactome",
      "Pathway Commons - GSEA" = "gsea_pathwaycommons",
      "WikiPathways - GSEA" = "gsea_wikipathways",
      "MSigDB - GSEA" = "gsea_msigdb"
    )

    if (identical(input$proteomics_source, "intersection")) {
      # Intersection lists have no fold-change; disable all GSEA options
      ora_only <- cp_analysis_choices_full[!grepl("^gsea_", unname(cp_analysis_choices_full))]
      selected_ora <- if (!is.null(input$proteomics_cp_analysis) && input$proteomics_cp_analysis %in% unname(ora_only)) {
        input$proteomics_cp_analysis
      } else {
        unname(ora_only)[1]
      }
      updateSelectInput(session, "proteomics_cp_analysis", choices = ora_only, selected = selected_ora)

      # Keep full tool list available, just with GSEA analyses removed
      restore_selected <- if (!is.null(input$proteomics_tool) && input$proteomics_tool %in% unname(full_tool_choices)) {
        input$proteomics_tool
      } else {
        "gprofiler"
      }
      updateSelectInput(session, "proteomics_tool", choices = full_tool_choices, selected = restore_selected)

      showNotification("GSEA is disabled for Intersection source because no fold changes are available.", type = "warning", duration = 5)

    } else if (identical(input$proteomics_source, "mofa_factor")) {
      updateSelectInput(
        session,
        "proteomics_tool",
        choices = c("ClusterProfiler" = "clusterprofiler"),
        selected = "clusterprofiler"
      )

      gsea_only <- cp_analysis_choices_full[grepl("^gsea_", unname(cp_analysis_choices_full))]
      selected_gsea <- if (!is.null(input$proteomics_cp_analysis) && input$proteomics_cp_analysis %in% unname(gsea_only)) {
        input$proteomics_cp_analysis
      } else {
        unname(gsea_only)[1]
      }
      updateSelectInput(session, "proteomics_cp_analysis", choices = gsea_only, selected = selected_gsea)

      # Ensure MOFA block is shown when selected
      shinyjs::show("proteomics_mofa_block")
      shinyjs::runjs("$('#proteomics_mofa_block').show();")
    } else {
      # Ensure MOFA block is hidden when not selected
      shinyjs::hide("proteomics_mofa_block")
      shinyjs::runjs("$('#proteomics_mofa_block').hide();")

      # Restore full tool list when leaving MOFA mode
      restore_selected <- if (!is.null(input$proteomics_tool) && input$proteomics_tool %in% unname(full_tool_choices)) {
        input$proteomics_tool
      } else {
        "gprofiler"
      }
      updateSelectInput(session, "proteomics_tool", choices = full_tool_choices, selected = restore_selected)

      # Restore full analysis list (only relevant when ClusterProfiler is selected)
      restore_cp_selected <- if (!is.null(input$proteomics_cp_analysis) && input$proteomics_cp_analysis %in% unname(cp_analysis_choices_full)) {
