  get_correction_method <- function() {
    if(input$sig_method %in% c("anova", "kruskal")) {
      # For ANOVA or Kruskal-Wallis tests, return a valid p.adjust method
      # based on the selected posthoc method    +
      posthoc_to_adjust <- list(
        "tukey" = "none",     # Tukey already adjusts p-values
        "dunn" = "none",      # Dunn's test can include adjustment
        "bonferroni" = "bonferroni",
        "holm" = "holm",
        "BH" = "BH",
        "BY" = "BY",
        "none" = "none",
        "dunnett" = "none",   # Dunnett already adjusts p-values
        "scheffe" = "none",   # Scheff  already adjusts p-values
        "games_howell" = "none" # Games-Howell already adjusts p-values
      )
      
      # Return the mapped adjustment method or default to "none" if not found
      return(posthoc_to_adjust[[input$posthoc_method]] %||% "none")
    } else if(input$sig_method == "limma") {
      # Limma handles its own p-value adjustment with topTable
      return("BH")  # Limma uses BH correction by default
    } else if(input$sig_method == "deseq2") {
      # DESeq2 handles its own p-value adjustment
      return("BH")  # DESeq2 uses BH correction by default
    } else if(input$sig_method == "edger") {
      # edgeR: default to BH when computing adjusted p-values for display
      return("BH")
    } else {
      # For other tests (t-test, wilcox), use the selected FDR method
      return(input$fdr_method)
    }
  }
  
  # Add a helper function to get color palettes - SINGLE IMPLEMENTATION
  get_color_palette <- function(palette_name, n) {
    dimred_base <- c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
                     "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf")
    shuffle <- !(palette_name %in% c("dimred_default", "default"))
    palette <- switch(palette_name,
                      "dimred_default" = {
                        if (n <= length(dimred_base)) {
                          dimred_base[seq_len(n)]
                        } else {
                          grDevices::colorRampPalette(dimred_base)(n)
                        }
                      },
                      "default" = scales::hue_pal()(n),
                      
                      # viridis palettes
                      "viridis" = viridisLite::viridis(n),
                      "plasma" = viridisLite::plasma(n),
                      "magma" = viridisLite::magma(n),
                      "inferno" = viridisLite::inferno(n),
                      "cividis" = viridisLite::cividis(n),
                      
                      # RColorBrewer palettes
                      "Set1" = {
                        if (n <= 9) {
                          RColorBrewer::brewer.pal(max(3, n), "Set1")[1:n]
                        } else {
                          grDevices::colorRampPalette(RColorBrewer::brewer.pal(9, "Set1"))(n)
                        }
                      },
                      "Set2" = {
                        if (n <= 8) {
                          RColorBrewer::brewer.pal(max(3, n), "Set2")[1:n]
                        } else {
                          grDevices::colorRampPalette(RColorBrewer::brewer.pal(8, "Set2"))(n)
                        }
                      },
                      "Set3" = {
                        if (n <= 12) {
                          RColorBrewer::brewer.pal(max(3, n), "Set3")[1:n]
                        } else {
                          grDevices::colorRampPalette(RColorBrewer::brewer.pal(12, "Set3"))(n)
                        }
                      },
                      "Pastel1" = {
                        if (n <= 9) {
                          RColorBrewer::brewer.pal(max(3, n), "Pastel1")[1:n]
                        } else {
                          grDevices::colorRampPalette(RColorBrewer::brewer.pal(9, "Pastel1"))(n)
                        }
                      },
                      "Dark2" = {
                        if (n <= 8) {
                          RColorBrewer::brewer.pal(max(3, n), "Dark2")[1:n]
                        } else {
                          grDevices::colorRampPalette(RColorBrewer::brewer.pal(8, "Dark2"))(n)
                        }
                      },
                      
                      # Custom palettes
                      "Metro" = c("#3F51B5", "#FF4081", "#4CAF50", "#FF9800",
                                  "#9C27B0", "#00BCD4", "#607D8B", "#795548",
                                  "#E64A19")[1:min(n, 9)],
                      
                      "Sunset" = c("#FF8A65", "#FFD54F", "#A1887F", "#81C784",
                                   "#64B5F6", "#E040FB", "#4DB6AC", "#D4E157",
                                   "#F4511E")[1:min(n, 9)],
                      
                      "Ocean" = c("#00838F", "#304FFE", "#009688", "#7986CB",
                                  "#00ACC1", "#5C6BC0", "#00BCD4", "#3949AB",
                                  "#0091EA")[1:min(n, 9)],
                      
                      "Forest" = c("#388E3C", "#7CB342", "#558B2F", "#689F38",
                                   "#33691E", "#9CCC65", "#8BC34A", "#2E7D32",
                                   "#64DD17")[1:min(n, 9)],
                      
                      "Berry" = c("#8E24AA", "#6A1B9A", "#9C27B0", "#AB47BC",
                                  "#4A148C", "#BA68C8", "#CE93D8", "#7B1FA2",
                                  "#D500F9")[1:min(n, 9)],
                      
                      "Citrus" = c("#FF6F00", "#FF8F00", "#FFAB00", "#FFC107",
                                   "#E65100", "#FFD740", "#FFCA28", "#F57F17",
                                   "#FFEA00")[1:min(n, 9)],
                      
                      "Stone" = c("#424242", "#616161", "#757575", "#9E9E9E",
                                  "#212121", "#BDBDBD", "#EEEEEE", "#546E7A",
                                  "#263238")[1:min(n, 9)],
                      
                      "Candy" = c("#E91E63", "#D81B60", "#F06292", "#EC407A",
                                  "#880E4F", "#F48FB1", "#F8BBD0", "#C2185B",
                                  "#AD1457")[1:min(n, 9)],
                      
                      "Skyline" = c("#0277BD", "#0288D1", "#039BE5", "#03A9F4",
                                    "#01579B", "#29B6F6", "#4FC3F7", "#026AA7",
                                    "#00B0FF")[1:min(n, 9)],
                      
                      "rainbow" = rainbow(n),
                      
                      # Default fallback
                      scales::hue_pal()(n)
    )
    
    if (length(palette) > 1 && shuffle) {
      set.seed(123) # For reproducibility
      palette <- sample(palette)
    }
    
    return(palette)
  }
  
