  # Cache helper functions for Data tab operations
  create_cache_key <- function(...) {
    # Create a unique key based on input parameters
    params <- list(...)
    # Convert to character and create hash
    key_string <- paste(sapply(params, function(x) {
      if (is.null(x)) return("NULL")
      if (is.data.frame(x) || is.matrix(x)) return(digest::digest(x))
      return(as.character(x))
    }), collapse = "_")
    return(digest::digest(key_string))
  }
  
  # Dynamic UI for plot types based on statistical method
  output$viz_plot_type_ui <- renderUI({
    # Get current statistical method
    current_method <- input$sig_method %||% "none"
    
    # Base plot types available for all methods
    base_choices <- c("Histogram" = "hist",
                      "Q-Q Plot" = "qq",
                      "Density Plot" = "density",
                      "Box Plot" = "boxplot",
                      "Correlation Heatmap" = "corr")
    
    # Method-specific enhanced plot types
    if (current_method %in% c("edger", "limma_voom")) {
      # edgeR and limma-voom specific plots
      method_choices <- c("MDS Plot" = "mds",
                          "Mean-Variance Plot" = "meanvar",
                          "Library Size Distribution" = "libsize",
                          "BCV Plot" = "bcv")
      
      if (current_method == "edger") {
        # Add QL Dispersion Plot only when QLF test is selected
        edger_test <- input$edger_test %||% "qlf"
        if (edger_test == "qlf") {
          method_choices <- c(method_choices,
                              "QL Dispersion Plot" = "ql_disp")
        }
      }
      
      method_choices <- c(method_choices, "Sample Distance Heatmap" = "sample_dist")
      
      if (current_method == "limma_voom") {
        method_choices <- c(method_choices,
                            "Voom Precision Weights" = "voom_weights",
                            "Model Residuals" = "residuals")
      }
      
      all_choices <- c(base_choices, method_choices)
      default_choice <- "mds"  # Default to MDS for count data methods
      
    } else if (current_method == "deseq2") {
      # DESeq2 specific plots
      method_choices <- c("PCA Plot" = "pca",
                          "Dispersion Plot" = "dispersion",
                          "MA Plot (Size Factors)" = "ma_sizefactors",
                          "Mean-SD Plot" = "meansd_plot",
                          "Count Outliers" = "count_outliers",
                          "MA Plot (p-values)" = "ma_pvalues",
                          "Cook's Distance" = "cooks",
                          "Sample Distance Heatmap" = "sample_dist")
      
      all_choices <- c(base_choices, method_choices)
      default_choice <- "pca"  # Default to PCA for DESeq2
      
    } else {
      # Default choices for other methods
      all_choices <- base_choices
      default_choice <- "hist"
    }
    
    selectInput("viz_plot_type", "Plot Type",
                choices = all_choices,
                selected = default_choice)
  })
  
  get_from_cache <- function(cache_list, key) {
    if (key %in% names(cache_list)) {
      cat("Cache hit for key:", substr(key, 1, 8), "...\n")
      return(cache_list[[key]])
    }
    cat("Cache miss for key:", substr(key, 1, 8), "...\n")
    return(NULL)
  }
  
  store_in_cache <- function(cache_list, key, value) {
    if (is.null(cache_list)) cache_list <- list()
    cache_list[[key]] <- value
    cat("Stored in cache with key:", substr(key, 1, 8), "... Cache now has", length(cache_list), "items\n")
    # Trigger cache update counter for reactivity
    values$cache_update_counter <- (values$cache_update_counter %||% 0) + 1
    return(cache_list)
  }
  # Helper function to force cache status update
  update_cache_status <- function() {
    values$cache_update_counter <- (values$cache_update_counter %||% 0) + 1
  }

  # Centralized helper to clear all analysis caches
  clear_analysis_caches <- function(reason = NULL) {
    values$pca_cache <- list()
    values$spca_cache <- list()
    values$processing_cache <- list()
    values$statistical_cache <- list()
    values$normalization_cache <- list()
    values$imputation_cache <- list()
    values$batch_correction_cache <- list()
    values$metabolomics_cache <- list()
    values$dual_analysis_cache <- list()
    values$dual_analysis_cache_signature <- NULL
    values$cache_update_counter <- 0

    # Also reset domain-specific caches
    clear_id_conversion_cache(trigger_update = trigger_id_cache_update)
    update_cache_status()

    if (!is.null(reason) && nzchar(reason)) {
      cat(sprintf("Cleared all analysis caches (%s)\n", reason))
    } else {
      cat("Cleared all analysis caches\n")
    }
  }
  
  # =========================================================================
  # COMPREHENSIVE STATE CLEANUP FOR NEW DATA RUNS
  # This function resets ALL dual grouping state and stat results to ensure

  # a clean slate between different experiment types (simple vs complex)
  # =========================================================================
  reset_dual_grouping_state <- function(reason = NULL) {
    # Reset dual grouping flag and active level
    values$has_dual_grouping <- FALSE
    values$active_grouping_level <- "biological"
    
    # Clear biological grouping data
    values$biological_groups <- NULL
    values$biological_unique_groups <- NULL
    values$biological_group_column_indices <- NULL
    values$biological_stat_results <- NULL
    values$biological_pairwise_combinations <- NULL
    values$biological_normalized_data <- NULL
    
    # Clear experimental grouping data
    values$experimental_groups <- NULL
    values$experimental_unique_groups <- NULL
    values$experimental_group_column_indices <- NULL
    values$experimental_stat_results <- NULL
    values$experimental_pairwise_combinations <- NULL
    values$experimental_normalized_data <- NULL
    
    # Clear pre-analysis dual grouping pairwise selections
    values$preanalysis_bio_pairwise_combinations <- NULL
    values$preanalysis_exp_pairwise_combinations <- NULL
    values$preanalysis_bio_ui_version <- 0
    values$preanalysis_exp_ui_version <- 0
    
    # Clear dual analysis execution tracking
    values$dual_analysis_in_progress <- FALSE
    values$dual_analysis_current_level <- NULL
    values$dual_analysis_trigger_rerun <- NULL
    
    # Clear main stat results to prevent contamination
    values$stat_results <- NULL
    
    # Clear main grouping state
    values$unique_groups <- NULL
    values$unique_groups_original <- NULL
    values$group_column_indices <- NULL
    
    # Clear final group assignments
    values$final_biological_groups <- NULL
    values$final_experimental_groups <- NULL
    
    # Clear pairwise combinations
    values$pairwise_order <- NULL
    values$current_pairwise_combinations <- NULL
    values$selected_pairwise_for_analysis <- NULL
    values$preanalysis_pairwise_combinations <- NULL
    values$pending_pairwise_confirmation <- FALSE
    values$pairwise_selection_confirmed <- FALSE
    values$skip_pairwise_selection <- FALSE
    
    # Clear distribution analysis custom state
    values$dist_group_order_custom <- NULL
    values$dist_group_order_base_groups <- NULL
    values$dist_stat_comparisons_custom <- NULL
      values$pca_group_order_custom <- NULL
      values$pca_group_order_base_groups <- NULL
    
    # Clear mapping state (but not seen_datasets to preserve user history)
    values$mapping_df <- NULL
    values$mapping_confirmed <- FALSE
    values$mapping_initial_state <- NULL
    values$auto_mapping <- NULL
    
    # CRITICAL: Clear dual analysis cache to prevent restoring stale results
    # This is essential to prevent state contamination when switching between
    # simple and complex experiments back-to-back
    values$dual_analysis_cache <- list()
    values$dual_analysis_cache_signature <- NULL
    
    # Clear any cached analysis state that could cause contamination
    values$analysis_has_run <- FALSE
    values$last_analysis_type <- NULL
    
    if (!is.null(reason) && nzchar(reason)) {
      cat(sprintf("Reset dual grouping state and cleared stat results (%s)\n", reason))
    } else {
      cat("Reset dual grouping state and cleared stat results\n")
    }
  }
