  # Proteomics cache helper functions
  create_proteomics_plot_cache_key <- function(tool, plot_type, enrichment_results, num_terms, fold_change_data, color_theme, highlight_terms = NULL) {
    # Create a cache key based on plot parameters
    enrichment_hash <- if (!is.null(enrichment_results)) {
      # Handle topGO objects differently since they can't be converted to data.frame
      if (tool == "topgo" && inherits(enrichment_results, "topGOdata")) {
        # For topGO objects, create a hash based on the object's structure
        digest::digest(list(class(enrichment_results), length(enrichment_results)), algo = "xxhash64")
      } else {
        digest::digest(enrichment_results, algo = "xxhash64")
      }
    } else {
      "NULL"
    }
    
    # Check if GSEA for automatic fold change usage
    is_gsea <- FALSE
    if (!is.null(enrichment_results) && tool != "topgo") {
      # Only try to convert to data.frame for non-topGO objects
      tryCatch({
        enrichment_df_check <- as.data.frame(enrichment_results)
        is_gsea <- "NES" %in% colnames(enrichment_df_check)
      }, error = function(e) {
        is_gsea <- FALSE
      })
    }
    
    fold_change_hash <- if (!is.null(fold_change_data) && is_gsea) {
      digest::digest(fold_change_data, algo = "xxhash64")
    } else {
      "NULL"
    }
    
    # Include highlight terms for g:Profiler Manhattan plots
    highlight_hash <- if (tool == "gprofiler" && plot_type == "manhattan" && !is.null(highlight_terms)) {
      digest::digest(highlight_terms, algo = "xxhash64")
    } else {
      "NULL"
    }
    
    key_string <- paste(tool, plot_type, enrichment_hash, num_terms, is_gsea, fold_change_hash, color_theme, highlight_hash, sep = "_")
    return(digest::digest(key_string, algo = "xxhash64"))
  }
  
  get_proteomics_plot_from_cache <- function(cache_key) {
