  }
  
  clear_proteomics_plot_cache <- function() {
    proteomics_values$current_plots <- list()
    proteomics_values$network_plots <- list()
    proteomics_values$enrichment_cache <- list()
    update_cache_status()
    cat("Proteomics caches cleared\n")
  }
  
  # Enrichment results cache helper functions
  create_enrichment_cache_key <- function(tool, gene_list, organism, analysis_params, tool_specific_params) {
    # Create a cache key based on enrichment analysis parameters
    gene_list_hash <- digest::digest(sort(gene_list), algo = "xxhash64")
    analysis_params_hash <- digest::digest(analysis_params, algo = "xxhash64")
    tool_params_hash <- digest::digest(tool_specific_params, algo = "xxhash64")
    
    key_string <- paste(tool, gene_list_hash, organism, analysis_params_hash, tool_params_hash, sep = "_")
    return(digest::digest(key_string, algo = "xxhash64"))
  }
  
  get_enrichment_from_cache <- function(cache_key) {
    return(get_from_cache(proteomics_values$enrichment_cache, cache_key))
  }
  
  store_enrichment_in_cache <- function(cache_key, enrichment_results, fold_change_data = NULL, original_fold_change_data = NULL) {
    cache_object <- list(
      enrichment_results = enrichment_results,
      fold_change_data = fold_change_data,
      original_fold_change_data = original_fold_change_data,
      pathview_gene_data = proteomics_values$pathview_gene_data,  # Use the properly formatted pathview data
      timestamp = Sys.time()
    )
    proteomics_values$enrichment_cache <- store_in_cache(proteomics_values$enrichment_cache, cache_key, cache_object)
  }
  
  # Helper function to get number of rows from different enrichment result types
  get_enrichment_results_nrow <- function(enrichment_results, tool) {
    if (is.null(enrichment_results)) {
      return(0)
    }
    
    if (tool == "topgo") {
      # topGO results have a table component
      if (!is.null(enrichment_results$table)) {
        return(nrow(enrichment_results$table))
      }
    } else if (tool == "gprofiler") {
      # g:Profiler results have a result component
      if (!is.null(enrichment_results$result)) {
        return(nrow(enrichment_results$result))
      }
    } else {
      # For other tools, try to coerce to data.frame
      tryCatch({
        return(nrow(as.data.frame(enrichment_results)))
      }, error = function(e) {
        return(0)
      })
    }
    
    return(0)
  }
  
  # Internal normalization function that performs the actual normalization
  perform_normalization_internal <- function(data, method, log2_before = FALSE, log2_after = FALSE, sum_as_percent = FALSE) {
    cat("Computing normalization (cache miss) - method:", method, "\n")
    
    # Apply log2 transformation before normalization if requested
    if (log2_before) {
      data <- data %>%
        mutate(across(everything(), ~ log2(. + 1)))
    }
    
    # Perform normalization based on method
    if (method == "sum") {
      normalized_data <- data %>%
        mutate(across(everything(), ~ if(sum(., na.rm = TRUE) == 0) NA else . / sum(., na.rm = TRUE)))
      if (isTRUE(sum_as_percent)) {
        normalized_data <- normalized_data %>%
          mutate(across(everything(), ~ . * 100))
      }
    } else if (method == "log2") {
      normalized_data <- data %>%
        mutate(across(everything(), ~ log2(. + 1)))
    } else if (method == "zscore") {
      # Z-score normalization with error handling
      normalized_data <- tryCatch({
        cat("Debug Z-score: Starting Z-score normalization\n")
        cat("Debug Z-score: Input data class:", class(data), "\n")
        cat("Debug Z-score: Input data dimensions:", dim(data), "\n")
        
        # Perform Z-score normalization (scale each row/sample)
        normalized_matrix <- t(scale(t(data)))
        
        cat("Debug Z-score: Normalized matrix class:", class(normalized_matrix), "\n")
        cat("Debug Z-score: Normalized matrix dimensions:", dim(normalized_matrix), "\n")
        
        # Convert back to data frame to maintain consistency with other methods
        result <- as.data.frame(normalized_matrix)
        
        # Preserve row and column names
        rownames(result) <- rownames(data)
        colnames(result) <- colnames(data)
        
        # Ensure the result is a proper data frame
        if (!is.data.frame(result)) {
          result <- as.data.frame(result)
          cat("Debug Z-score: Additional conversion to data frame performed\n")
        }
        
        cat("Debug Z-score: Final data class:", class(result), "\n")
        cat("Debug Z-score: Final data dimensions:", dim(result), "\n")
        cat("Debug Z-score: Z-score normalization completed successfully\n")
        
        result
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in Z-score normalization:", e$message), type = "error")
        cat("Error in Z-score normalization:", e$message, "\n")
        data
      })
    } else if (method == "median") {
      # Median normalization with better error handling
      normalized_data <- tryCatch({
        result <- data
        for (col in 1:ncol(data)) {
          col_data <- data[, col]
          # Ensure data is numeric and handle any conversion issues
          if (any(!is.na(col_data))) {
            # Calculate median of non-NA values
            col_median <- median(col_data, na.rm = TRUE)
            if (!is.na(col_median) && col_median > 0) {
              result[, col] <- col_data / col_median
            }
          }
        }
        result
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in median normalization:", e$message), type = "error")
        data
      })
    } else if (method == "quantile") {
      # Quantile normalization using preprocessCore
      normalized_data <- tryCatch({
        # Convert to matrix and ensure it's numeric
        data_for_quantile <- as.matrix(data)
        has_na <- is.na(data_for_quantile)
        
        if(any(has_na)) {
          if(input$missing_value_strategy != "impute") {
            if (!is.null(session)) showNotification(paste("Quantile normalization requires complete data.",
                                   "Please select 'Impute missing values' in preprocessing options or remove every row with missing values before proceeding."),
                             type = "error", duration = 10)
            return(data)  # Return original data without normalization
          }
          
          if (!is.null(session)) showNotification("Using selected imputation method before quantile normalization.", type = "message")
          # imputation will have been performed in preprocessing step
        }
        
        # Apply quantile normalization (only reaches here if no NAs or imputation is selected)
        normalized_matrix <- preprocessCore::normalize.quantiles(data_for_quantile)
        colnames(normalized_matrix) <- colnames(data)
        rownames(normalized_matrix) <- rownames(data)
        
        # Restore NAs if configured to keep missing values
        if(input$missing_value_strategy == "remove" && any(has_na)) {
          normalized_matrix[has_na] <- NA
        }
        
        as.data.frame(normalized_matrix)
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in quantile normalization:", e$message), type = "error")
        data
      })
    } else if (method == "pqn") {
      # Probabilistic Quotient Normalization (PQN)
      normalized_data <- tryCatch({
        cat("Debug PQN: Starting PQN normalization\n")
        
        # Convert to matrix and ensure it's numeric
        data_for_pqn <- as.matrix(data)
        
        # Check for missing values - PQN requires complete data for proper reference calculation
        has_na <- is.na(data_for_pqn)
        if(any(has_na)) {
          if (!is.null(session)) showNotification(paste("PQN normalization requires complete data for optimal results.",
                                 "Please handle missing values using the Missing Value Handling options before applying PQN normalization."),
                           type = "error", duration = 10)
          return(data)  # Return original data without normalization
        }
        
        # Step 1: Calculate reference spectrum (median of all samples)
        reference_spectrum <- apply(data_for_pqn, 1, function(x) median(x, na.rm = TRUE))
        
        # Step 2: Calculate quotients for each sample relative to reference
        quotients_matrix <- matrix(NA, nrow = nrow(data_for_pqn), ncol = ncol(data_for_pqn))
        
        for(j in 1:ncol(data_for_pqn)) {
          sample_data <- data_for_pqn[, j]
          # Calculate quotients, avoiding division by zero only
          quotients <- ifelse(reference_spectrum > 0,
                              sample_data / reference_spectrum,
                              NA)
          quotients_matrix[, j] <- quotients
        }
        
        # Step 3: Calculate probabilistic quotient (median of quotients) for each sample
        normalization_factors <- apply(quotients_matrix, 2, function(x) median(x, na.rm = TRUE))
        
        # Handle cases where normalization factor is invalid
        normalization_factors[is.na(normalization_factors) | normalization_factors <= 0] <- 1
        
        # Step 4: Normalize each sample by its normalization factor
        normalized_matrix <- sweep(data_for_pqn, 2, normalization_factors, "/")
        
        # Convert back to data frame
        result <- as.data.frame(normalized_matrix)
        colnames(result) <- colnames(data)
        rownames(result) <- rownames(data)
        
        cat("Debug PQN: PQN normalization completed successfully\n")
        cat("Debug PQN: Normalization factors:", paste(round(normalization_factors, 4), collapse = ", "), "\n")
        
        result
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in PQN normalization:", e$message), type = "error")
        cat("Error in PQN normalization:", e$message, "\n")
        data
      })
    } else if (method == "vsn") {
      # Variance stabilizing normalization with better error handling
      normalized_data <- tryCatch({
        # Convert to matrix and ensure it's numeric
        data_for_vsn <- as.matrix(data)
        
        # Replace any infinite values
        data_for_vsn[is.infinite(data_for_vsn)] <- NA
        
        # Handle missing values - VSN often can't handle NAs well
        if(any(is.na(data_for_vsn))) {
          if(input$missing_value_strategy != "impute") {
            if (!is.null(session)) showNotification(paste("VSN normalization requires complete data.",
                                   "Please select 'Impute missing values' in preprocessing options or remove every row with missing values before proceeding."),
                             type = "error", duration = 10)
            return(data)  # Return original data without normalization
          }
          
          if (!is.null(session)) showNotification("Using selected imputation method before VSN normalization.", type = "message")
          # imputation will have been performed in preprocessing step
        }
        
        # Apply VSN transformation
        vsn_result <- vsn::justvsn(data_for_vsn)
        result <- as.data.frame(vsn_result)
        colnames(result) <- colnames(data)
        result
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in VSN normalization:", e$message), type = "error")
        data
      })
    } else if (method == "cyclic_loess") {
      # Cyclic Loess normalization using limma
      normalized_data <- tryCatch({
        # Convert to matrix and ensure it's numeric
        data_for_loess <- as.matrix(data)
        has_na <- is.na(data_for_loess)
        
        # Handle missing values before normalization
        if(any(has_na)) {
          if(input$missing_value_strategy != "impute") {
            if (!is.null(session)) showNotification(paste("Cyclic loess normalization requires complete data.",
                                   "Please select 'Impute missing values' in preprocessing options or remove every row with missing values before proceeding."),
                             type = "error", duration = 10)
            return(data)  # Return original data without normalization
          }
          
          if (!is.null(session)) showNotification("Using selected imputation method before cyclic loess normalization.",
                           type = "message", duration = 5)
          # imputation will have been performed in preprocessing step
        }
        
        # Check if limma is loaded
        if(!requireNamespace("limma", quietly = TRUE)) {
          library(limma)
        }
        
        # Apply cyclic loess normalization
        normalized_matrix <- limma::normalizeCyclicLoess(data_for_loess, method = "fast")
        colnames(normalized_matrix) <- colnames(data)
        rownames(normalized_matrix) <- rownames(data)
        
        # Restore NAs if they were in original data
        if(any(has_na)) {
          normalized_matrix[has_na] <- NA
        }
        
        as.data.frame(normalized_matrix)
      }, error = function(e) {
        if (!is.null(session)) showNotification(paste("Error in cyclic loess normalization:", e$message), type = "error")
        data
      })
    } else {
      normalized_data <- data
    }
    
    # Apply log2 transformation after normalization if requested
    if (log2_after) {
      tryCatch({
        # Ensure dplyr is loaded for mutate function
        if (!requireNamespace("dplyr", quietly = TRUE)) {
          library(dplyr, quietly = TRUE)
        }
        
        # Debug output
        cat("Debug log2: Applying log2 transformation after normalization\n")
        cat("Debug log2: Class of normalized_data before conversion:", class(normalized_data), "\n")
        cat("Debug log2: Dimensions:", dim(normalized_data), "\n")
        
        # Ensure normalized_data is a data frame before using mutate
        if (!is.data.frame(normalized_data)) {
          normalized_data <- as.data.frame(normalized_data)
          cat("Debug log2: Converted to data frame, new class:", class(normalized_data), "\n")
        }
        
        # Apply log2 transformation using dplyr::mutate to avoid namespace conflicts
        normalized_data <- normalized_data %>%
          dplyr::mutate(dplyr::across(dplyr::everything(), ~ log2(. + 1)))
        
        cat("Debug log2: Log2 transformation completed successfully\n")
        
      }, error = function(e) {
        showNotification(paste("Error in log2 transformation:", e$message), type = "error")
        cat("Error in log2 transformation:", e$message, "\n")
        cat("Debug: normalized_data class:", class(normalized_data), "\n")
        cat("Debug: normalized_data structure:", str(normalized_data), "\n")
        
        # Fallback method: apply log2 transformation without dplyr
        tryCatch({
          cat("Debug log2: Attempting fallback method without dplyr\n")
          # Convert to matrix, apply log2, then back to data frame
          data_matrix <- as.matrix(normalized_data)
          data_matrix <- log2(data_matrix + 1)
          normalized_data <- as.data.frame(data_matrix)
          cat("Debug log2: Fallback method successful\n")
          
        }, error = function(e2) {
          cat("Error in fallback log2 transformation:", e2$message, "\n")
          if (!is.null(session)) showNotification(paste("Failed to apply log2 transformation. Using data without log2 transformation."), type = "warning")
        })
      })
    }
    
    return(normalized_data)
  }
  
  # Cache-aware wrapper functions for data processing operations
  perform_cached_normalization <- function(data, method, log2_before = FALSE, log2_after = FALSE, sum_as_percent = FALSE) {
    cache_key <- create_cache_key(data, method, log2_before, log2_after, sum_as_percent)
    
    cached_result <- get_from_cache(values$normalization_cache, cache_key)
    if (!is.null(cached_result)) {
      cat("Using cached normalization result\n")
      return(cached_result)
    }
    
    # Perform actual normalization
    result <- perform_normalization_internal(data, method, log2_before, log2_after, sum_as_percent)
    
    # Store in cache
    values$normalization_cache <- store_in_cache(values$normalization_cache, cache_key, result)
    
    return(result)
  }
  
  perform_cached_imputation <- function(data, method, params = list(), by_group = FALSE, group_info = NULL) {
    cache_key <- create_cache_key(data, method, params, by_group, group_info)
    
    cached_result <- get_from_cache(values$imputation_cache, cache_key)
    if (!is.null(cached_result)) {
      return(cached_result)
    }
    
    # Perform actual imputation
    result <- perform_imputation(data, method, params, by_group, group_info)
    
    # Store in cache
    values$imputation_cache <- store_in_cache(values$imputation_cache, cache_key, result)
    
    return(result)
  }
  
  perform_cached_batch_correction <- function(data, batch_info, method, group_info = NULL) {
    cache_key <- create_cache_key(data, batch_info, method, group_info)
    
    cached_result <- get_from_cache(values$batch_correction_cache, cache_key)
    if (!is.null(cached_result)) {
      return(cached_result)
    }
    
    # Perform robust batch correction with automatic fallback
    result <- perform_robust_batch_correction(data, batch_info, method, group_info)
    
    # Store in cache (whether successful or not, to avoid repeated failures)
    values$batch_correction_cache <- store_in_cache(values$batch_correction_cache, cache_key, result)
    
    return(result)
  }
  
  perform_cached_statistical_analysis <- function(data, method, group_info, ...) {
    cache_key <- create_cache_key(data, method, group_info, ...)
    
    cached_result <- get_from_cache(values$statistical_cache, cache_key)
    if (!is.null(cached_result)) {
      return(cached_result)
    }
    
    # Perform actual statistical analysis
    result <- perform_statistical_analysis_internal(data, method, group_info, ...)
    
    # Store in cache
    values$statistical_cache <- store_in_cache(values$statistical_cache, cache_key, result)
    
    return(result)
  }
  
