  # Helper Function to get indices of features to use for downstream analysis
  get_selected_feature_indices <- function() {
    # Since the dropdown now contains the filtered features,
    # we just need to return all available molecule indices
    # The actual filtering is handled by the dropdown selection
    seq_along(values$cleaned_molecules)
  }
  
  # Centralized function to get feature indices based on feature_source selection
  get_feature_indices_by_source <- function(feature_source, comparison_name = NULL) {
    if (is.null(feature_source) || feature_source == "all") {
      return(seq_along(values$cleaned_molecules))
    }
    feature_source_idx <- switch(feature_source,
                                 "pca" = {
                                   # Prefer globally selected PCA features if available (now stored as indices)
                                   if (!is.null(values$pca_top_features) && length(values$pca_top_features) > 0) {
                                     # values$pca_top_features now contains indices directly
                                     return(values$pca_top_features)
                                   }
                                   # When PCA is explicitly selected as feature source, get PCA features directly
                                   # First try to get from stored PCA result
                                   pca_result <- values$pca_result
                                   
                                   # If no global PCA result, try context-specific
                                   if (is.null(pca_result)) {
                                     context_key <- get_current_context_key(comparison_name)
                                     pca_result <- get_pca_result(context_key)
                                   }
                                   
                                   # If we have a PCA result and user has specified top N features
                                   if (!is.null(pca_result) && !is.null(input$pca_top_features) &&
                                       !is.na(input$pca_top_features) && input$pca_top_features > 0) {
                                     tryCatch({
                                       # Get the ranking method, default to "overall" if not available
                                       ranking_method <- if (!is.null(input$pca_feature_ranking)) input$pca_feature_ranking else "overall"
                                       
                                       # Get top PCA features directly
                                       top_features_df <- get_top_pca_features(pca_result, values$cleaned_molecules, input$pca_top_features, ranking_method)
                                       
                                       if (!is.null(top_features_df) && nrow(top_features_df) > 0) {
                                         pca_feature_indices <- as.integer(top_features_df$Feature_ID)
                                         return(pca_feature_indices)
                                       }
                                     }, error = function(e) {
                                       # Silent error handling
                                     })
                                   }
                                   
                                   # Default to all features if PCA not available or error occurred
                                   seq_along(values$cleaned_molecules)
                                 },
                                 "ml" = {
                                   if (!is.null(values$selected_features$features) &&
                                       values$selected_features$source == "ML") {
                                     # For ML features, we need to convert feature names back to indices
                                     feature_names <- values$selected_features$features
                                     ml_feature_indices <- which(values$cleaned_molecules %in% feature_names)
                                     return(ml_feature_indices)
                                   } else {
                                     seq_along(values$cleaned_molecules)  # Default to all if ML not available
                                   }
                                 },
                                 seq_along(values$cleaned_molecules)  # Default to all
    )
    
    return(feature_source_idx)
  }
  
  # Helper function to get available feature names based on source
  get_available_feature_names <- function(feature_source, comparison_name = "All Groups") {
    if (is.null(values$cleaned_molecules) || length(values$cleaned_molecules) == 0) {
      return(character(0))
    }
    
    tryCatch({
      # Get feature indices based on the selected source
      feature_indices <- get_feature_indices_by_source(feature_source, comparison_name)
      
      # Convert indices to feature names
      if (length(feature_indices) > 0 && all(feature_indices <= length(values$cleaned_molecules))) {
        return(values$cleaned_molecules[feature_indices])
      } else {
        return(values$cleaned_molecules)  # Fallback to all features
      }
    }, error = function(e) {
      cat("Error in get_available_feature_names:", e$message, "\n")
      return(values$cleaned_molecules)  # Fallback to all features on error
    })
  }
  
  # Helper function to merge new statistical results with existing bootstrap columns
  merge_bootstrap_columns <- function(new_stat_results) {
    # If no existing stat_results, just return the new results
    if (is.null(values$stat_results)) {
      return(new_stat_results)
    }
    
    # Find bootstrap columns in existing results
    bootstrap_columns <- grep("^Bootstrap_|_Bootstrap_", colnames(values$stat_results), value = TRUE)
    
    # If no bootstrap columns exist, just return new results
    if (length(bootstrap_columns) == 0) {
      return(new_stat_results)
    }
    
    # Merge bootstrap columns into new results
    # Ensure both dataframes have the same number of rows
    if (nrow(values$stat_results) == nrow(new_stat_results)) {
      for (col in bootstrap_columns) {
        new_stat_results[[col]] <- values$stat_results[[col]]
      }
    }
    
    return(new_stat_results)
  }
  
  # Function to rename samples based on group names
  rename_samples <- function(names_vec) {
    # Check if the names already have the pattern "Group_Number"
    already_formatted <- grepl("_\\d+$", names_vec)
    
    # For names that already have the pattern, keep them as is
    output <- names_vec
    
    # Process only the names that don't have the pattern
    if (any(!already_formatted)) {
      # Remove any trailing dots and numbers (e.g. convert "Control...2" to "Control")
      base_names <- sub("\\.+[0-9]+$", "", names_vec)
      
      # Initialize group counters
      group_counter <- list()
      
      # Process each name
      for(i in seq_along(names_vec)) {
        # Skip names that already have the "_Number" pattern
        if (already_formatted[i]) next
        
        group <- base_names[i]
        # Use the group name as is (with spaces) as the key in the counter
        group_counter[[group]] <- if(is.null(group_counter[[group]])) 1 else group_counter[[group]] + 1
        output[i] <- paste0(group, "_", group_counter[[group]])
      }
    }
    
    return(output)
  }
  
  preserve_group_names <- function(names_vector) {
    # Replace any periods that R automatically converted from spaces back to spaces
    # This handles cases where R already converted spaces to periods
    names_vector <- gsub("\\.", " ", names_vector)
    
    # Also check original group names and restore any that match after conversion
    if (!is.null(values$unique_groups_original)) {
      for (i in seq_along(names_vector)) {
        # Check if this name exists in the original list after period conversion
        period_version <- gsub(" ", ".", names_vector[i])
        original_match <- which(gsub(" ", ".", values$unique_groups_original) == period_version)
        if (length(original_match) > 0) {
          names_vector[i] <- values$unique_groups_original[original_match[1]]
        }
      }
    }
    
    return(names_vector)
  }
  
  # Helper function to get corrected column names consistently across the app
  get_corrected_column_names <- function(original_names) {
    # Handle NULL or empty input
    if (is.null(original_names) || length(original_names) == 0) {
      return(character(0))
    }
    
    # Remove any NA values from original_names
    original_names <- original_names[!is.na(original_names)]
    if (length(original_names) == 0) {
      return(character(0))
    }
    
    # If we have stored corrected sample names, try to use them intelligently
    if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) > 0) {
      # If lengths match exactly, use the corrected names directly
      if (length(values$corrected_sample_names) == length(original_names)) {
        return(values$corrected_sample_names)
      }
      
      # If lengths don't match, try to map by position within the normalized data
      if (!is.null(values$normalized_data)) {
        all_column_names <- colnames(values$normalized_data)
        
        # Find which positions in the full data correspond to our original_names
        matching_positions <- match(original_names, all_column_names)
        
        # If we can find matches and they're within the corrected names range
        valid_matches <- !is.na(matching_positions) & matching_positions <= length(values$corrected_sample_names)
        
        if (all(valid_matches)) {
          return(values$corrected_sample_names[matching_positions])
        }
      }
    }
    
    # Otherwise, fall back to the existing rename_samples logic
    tryCatch({
      renamed <- rename_samples(original_names)
      return(preserve_group_names(renamed))
    }, error = function(e) {
      # If all else fails, return the original names
      warning("Error in get_corrected_column_names: ", e$message, ". Returning original names.")
      return(original_names)
    })
  }
  
  # Helper function to handle batch correction results consistently
  handle_batch_correction_result <- function(batch_result, original_data, context = "batch correction") {
    if (is.list(batch_result) && !is.null(batch_result$success)) {
      if (batch_result$success) {
        return(list(
          data = batch_result$data,
          success = TRUE,
          notification = list(
            message = paste(stringr::str_to_title(context), "completed using", batch_result$method_used, "method"),
            type = "message",
            duration = 5
          )
        ))
      } else {
        return(list(
          data = original_data,
          success = FALSE,
          notification = list(
            message = paste(stringr::str_to_title(context), "failed:", batch_result$message, "\nUsing original data."),
            type = "warning",
            duration = 10
          )
        ))
      }
    } else {
      # Legacy format - assume it's the corrected data
      return(list(
        data = batch_result,
        success = TRUE,
        notification = list(
          message = paste(stringr::str_to_title(context), "completed successfully"),
          type = "message",
          duration = 5
        )
      ))
    }
  }
  
  # Function to validate batch correction inputs and provide early warnings
  validate_batch_correction_inputs <- function(data, batch_info, group_info = NULL) {
    validation_results <- list(valid = TRUE, warnings = c(), errors = c())
    
    # Check data format
    if(!is.matrix(data) && !is.data.frame(data)) {
      validation_results$errors <- c(validation_results$errors,
                                     "Data must be a matrix or data.frame")
      validation_results$valid <- FALSE
    }
    
    # Check for missing values
    if(anyNA(data)) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Data contains missing values - these will be imputed")
    }
    
    # Check batch info
    if(is.null(batch_info)) {
      validation_results$errors <- c(validation_results$errors,
                                     "Batch information is required for batch correction")
      validation_results$valid <- FALSE
    } else {
      # Check batch info length
      if(length(batch_info) != ncol(data)) {
        validation_results$errors <- c(validation_results$errors,
                                       paste("Batch info length (", length(batch_info),
                                             ") doesn't match number of samples (", ncol(data), ")"))
        validation_results$valid <- FALSE
      }
      
      # Check number of unique batches
      unique_batches <- length(unique(batch_info))
      if(unique_batches < 2) {
        validation_results$errors <- c(validation_results$errors,
                                       paste("Need at least 2 batches for correction, found:", unique_batches))
        validation_results$valid <- FALSE
      }
      
      # Check batch sizes
      batch_sizes <- table(batch_info)
      min_batch_size <- min(batch_sizes)
      if(min_batch_size < 2) {
        validation_results$warnings <- c(validation_results$warnings,
                                         paste("Some batches have fewer than 2 samples (min:", min_batch_size,
                                               ") - this may cause instability"))
      }
    }
    
    # Check group info if provided
    if(!is.null(group_info)) {
      if(length(group_info) != ncol(data)) {
        validation_results$errors <- c(validation_results$errors,
                                       paste("Group info length (", length(group_info),
                                             ") doesn't match number of samples (", ncol(data), ")"))
        validation_results$valid <- FALSE
      }
      
      # Check for confounding
      if(validation_results$valid && !is.null(batch_info)) {
        confounding_check <- check_batch_confounding(batch_info, group_info)
        if(isTRUE(confounding_check$perfect_confounding)) {
          validation_results$errors <- c(validation_results$errors,
                                         "Perfect confounding detected - batch correction impossible")
          validation_results$valid <- FALSE
        } else if(isTRUE(confounding_check$partial_confounding)) {
          validation_results$warnings <- c(validation_results$warnings,
                                           "Partial confounding detected - results may be unreliable")
        }
      }
    }
    
    # Check data dimensions
    if(nrow(data) < 10) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Very few features detected - batch correction may not be effective")
    }
    
    if(ncol(data) < 6) {
      validation_results$warnings <- c(validation_results$warnings,
                                       "Very few samples detected - batch correction may be unstable")
    }
    
    return(validation_results)
  }
  
  # Function to provide recommendations for handling confounding issues
  provide_confounding_recommendations <- function(confounding_check, method) {
    recommendations <- c()
    
    if(isTRUE(confounding_check$perfect_confounding)) {
      recommendations <- c(recommendations,
                           "\n=== PERFECT CONFOUNDING DETECTED ===",
                           "Each batch contains samples from only one biological group.",
                           "This makes batch correction impossible as batch and biological effects cannot be distinguished.",
                           "\nIMMEDIATE ACTIONS:",
                           "1. STOP current analysis - results will be unreliable",
                           "2. Review experimental design",
                           "3. Consider collecting additional samples with proper randomization",
                           "\nALTERNATIVE APPROACHES:",
                           "  Analyze each batch separately (lose power but maintain validity)",
                           "  Use batch as a blocking factor in statistical models",
                           "  Report results stratified by batch",
                           "  Consider meta-analysis approaches if batches represent different studies"
      )
    } else if(isTRUE(confounding_check$partial_confounding)) {
      recommendations <- c(recommendations,
                           "\n=== PARTIAL CONFOUNDING DETECTED ===",
                           "Some biological groups appear in only some batches.",
                           "\nRECOMMENDATIONS:",
                           "  ComBat may still work but with reduced effectiveness",
                           "  Consider limma's removeBatchEffect with careful interpretation",
                           "  Include batch as covariate in downstream statistical models",
                           "  Report potential confounding in results"
      )
    }
    
    if(isTRUE(confounding_check$severe_imbalance)) {
      recommendations <- c(recommendations,
                           "\n=== SEVERE SAMPLE IMBALANCE ===",
                           "Some batch-group combinations have very few samples.",
                           "\nRECOMMENDATIONS:",
                           "  Results may be unstable for underrepresented combinations",
                           "  Consider grouping similar conditions if scientifically justified",
                           "  Use bootstrap or permutation approaches for validation",
                           "  Report sample sizes per group in results"
      )
    }
    
    # Method-specific recommendations
    method_recommendations <- switch(method,
                                     "combat" = c(
                                       "\n=== ComBat (Parametric) Recommendations ===",
                                       "  Works best with balanced designs",
                                       "  May fail with perfect confounding",
                                       "  Consider non-parametric version if parametric fails",
                                       "  Requires sufficient samples per batch-group combination"
                                     ),
                                     "combat_nonpar" = c(
                                       "\n=== ComBat (Non-parametric) Recommendations ===",
                                       "  More robust to distributional assumptions",
                                       "  Requires at least 3 samples per batch",
                                       "  May handle some confounding better than parametric",
                                       "  Slower but more conservative approach"
                                     ),
                                     "limma" = c(
                                       "\n=== limma removeBatchEffect Recommendations ===",
                                       "  Fails completely with perfect confounding",
                                       "  Requires full-rank design matrix",
                                       "  Good for moderate confounding scenarios",
                                       "  Fast and widely used method"
                                     ),
                                     "sva" = c(
                                       "\n=== SVA Recommendations ===",
                                       "  Designed to detect unknown sources of variation",
                                       "  May identify additional confounders beyond batch",
                                       "  Requires sufficient sample size and complexity",
                                       "  Good when batch effects are not the only concern"
                                     ),
                                     c("\n=== General Recommendations ===",
                                       "  Consider alternative batch correction methods",
                                       "  Evaluate if batch correction is necessary",
                                       "  Include batch as covariate in statistical models")
    )
    
    recommendations <- c(recommendations, method_recommendations)
    
    if(length(recommendations) > 0) {
      message(paste(recommendations, collapse = "\n"))
    }
  }
  
  # Function to check for confounding between batch and biological groups
  check_batch_confounding <- function(batch_info, group_info = NULL, covariates = NULL) {
    confounding_issues <- list()
    
    if(!is.null(group_info)) {
      # Convert to factors for analysis
      batch_factor <- as.factor(batch_info)
      group_factor <- as.factor(group_info)
      
      # Create contingency table
      contingency_table <- table(batch_factor, group_factor)
      
      # Check for perfect confounding (batch completely confounded with groups)
      batch_levels <- nlevels(batch_factor)
      group_levels <- nlevels(group_factor)
      
      # Perfect confounding check
      if(batch_levels == group_levels) {
        # Check if each batch has only one group
        batch_group_pairs <- apply(contingency_table, 1, function(x) sum(x > 0))
        if(all(batch_group_pairs == 1)) {
          confounding_issues$perfect_confounding <- TRUE
          confounding_issues$message <- paste("CRITICAL: Perfect confounding detected!",
                                              "Each batch contains only one biological group.",
                                              "Batch correction cannot distinguish between batch and biological effects.",
                                              "Consider alternative study design or methods.")
        }
      }
      
      # Partial confounding check (some groups missing from some batches)
      groups_per_batch <- apply(contingency_table, 1, function(x) sum(x > 0))
      batches_per_group <- apply(contingency_table, 2, function(x) sum(x > 0))
      
      if(any(groups_per_batch == 1) || any(batches_per_group == 1)) {
        confounding_issues$partial_confounding <- TRUE
        confounding_issues$message <- c(confounding_issues$message,
                                        paste("WARNING: Partial confounding detected!",
                                              "Some biological groups appear in only one batch,",
                                              "or some batches contain only one group.",
                                              "This may reduce batch correction effectiveness."))
      }
      
      # Check for severe imbalance
      min_samples_per_cell <- min(contingency_table[contingency_table > 0])
      max_samples_per_cell <- max(contingency_table)
      if(min_samples_per_cell == 1 || (max_samples_per_cell / min_samples_per_cell) > 10) {
        confounding_issues$severe_imbalance <- TRUE
        confounding_issues$message <- c(confounding_issues$message,
                                        paste("WARNING: Severe sample imbalance detected!",
                                              "Some batch-group combinations have very few samples.",
                                              "This may affect batch correction stability."))
      }
      
      # Store contingency table for reference
      confounding_issues$contingency_table <- contingency_table
    }
    
    # Check for rank deficiency in design matrix
    if(!is.null(group_info)) {
      tryCatch({
        mod_matrix <- model.matrix(~ group_info)
        if(qr(mod_matrix)$rank < ncol(mod_matrix)) {
          confounding_issues$rank_deficient <- TRUE
          confounding_issues$message <- c(confounding_issues$message,
                                          "WARNING: Design matrix is rank deficient. This may cause batch correction to fail.")
        }
      }, error = function(e) {
        confounding_issues$design_error <- TRUE
        confounding_issues$message <- c(confounding_issues$message,
                                        paste("ERROR: Cannot create design matrix:", e$message))
      })
    }
    
    return(confounding_issues)
  }
  
  # Wrapper function to perform batch correction with automatic fallback
  perform_robust_batch_correction <- function(data, batch_info, method = "combat",
                                              group_info = NULL, covariates = NULL) {
    
    # Validate inputs first
    validation <- validate_batch_correction_inputs(data, batch_info, group_info)
    
    # Report validation results
    if(length(validation$warnings) > 0) {
      for(warning_msg in validation$warnings) {
        warning(warning_msg)
      }
    }
    
    if(!validation$valid) {
      # Return error result instead of stopping the app
      error_msg <- paste("Batch correction input validation failed:\n",
                         paste(validation$errors, collapse = "\n"))
      message(error_msg)
      
      # Return list with error information
      return(list(
        success = FALSE,
        error = TRUE,
        message = error_msg,
        data = data,  # Return original data
        method_used = "none"
      ))
    }
    
    # Define method priority for fallback
    method_fallbacks <- list(
      "combat" = c("combat_nonpar", "limma", "sva"),
      "combat_nonpar" = c("combat", "limma", "sva"),
      "limma" = c("combat_nonpar", "combat", "sva"),
      "sva" = c("limma", "combat_nonpar", "combat")
    )
    
    methods_to_try <- c(method, method_fallbacks[[method]])
    
    for(current_method in methods_to_try) {
      message("\n=== Attempting batch correction with method: ", current_method, " ===")
      
      tryCatch({
        result <- perform_batch_correction(data, batch_info, current_method,
                                           group_info, covariates)
        
        # If we get here without error, return success
        if(current_method != method) {
          message("SUCCESS: Fallback method '", current_method, "' completed successfully")
          # Only show notification in Shiny context
          if(exists("showNotification")) {
            showNotification(paste("Batch correction completed using fallback method:", current_method),
                             type = "warning", duration = 5)
          }
        }
        
        return(list(
          success = TRUE,
          error = FALSE,
          message = paste("Batch correction completed successfully using", current_method),
          data = result,
          method_used = current_method
        ))
        
      }, error = function(e) {
        message("FAILED: Method '", current_method, "' failed with error: ", e$message)
        
        # If this was the last method to try, return error result
        if(current_method == methods_to_try[length(methods_to_try)]) {
          error_msg <- paste("All batch correction methods failed. Last error:", e$message,
                             "\n\nConsider:\n",
                             "1. Checking for perfect confounding between batch and groups\n",
                             "2. Ensuring adequate sample sizes per batch-group combination\n",
                             "3. Analyzing data without batch correction\n",
                             "4. Using batch as a covariate in downstream analysis")
          
          return(list(
            success = FALSE,
            error = TRUE,
            message = error_msg,
            data = data,  # Return original data
            method_used = "none",
            attempted_methods = methods_to_try,
            last_error = e$message
          ))
        }
      })
    }
  }
  
  # Function to perform batch correction using various methods
  perform_batch_correction <- function(data, batch_info, method = "combat",
                                       group_info = NULL, covariates = NULL,
                                       run_order = NULL, qc_samples = NULL,
                                       internal_standards = NULL) {
    
    # Check required inputs
    if(is.null(batch_info) || length(unique(batch_info)) < 2) {
      warning("Batch correction requires at least two distinct batches")
      return(data)
    }
    
    # Ensure data is a matrix
    data <- as.matrix(data)
    
    # Make batch info a factor
    batch_info <- as.factor(batch_info)
    
    # Convert group_info to factor if provided
    if(!is.null(group_info)) {
      group_info <- as.factor(group_info)
    }
    
    # Check for confounding issues
    confounding_check <- check_batch_confounding(batch_info, group_info, covariates)
    
    # Handle confounding issues
    if(length(confounding_check) > 0) {
      # Print all messages
      if(!is.null(confounding_check$message)) {
        for(msg in confounding_check$message) {
          message(msg)
        }
      }
      
      # Provide detailed recommendations
      provide_confounding_recommendations(confounding_check, method)
      
      # If perfect confounding, throw error that will be caught by wrapper
      if(isTRUE(confounding_check$perfect_confounding)) {
        stop("Perfect confounding detected: Each batch contains only samples from one biological group. ",
             "Batch correction cannot distinguish between batch and biological effects. ",
             "Consider: (1) Analyzing each batch separately, (2) Using batch as covariate in statistical models, ",
             "(3) Collecting additional samples with proper randomization.")
      }
      
      # Print contingency table if available
      if(!is.null(confounding_check$contingency_table)) {
        message("\nSample distribution across batches and groups:")
        print(confounding_check$contingency_table)
      }
    }
    
    # Apply different batch correction methods
    corrected_data <- switch(
      tolower(method),
      
      # ComBat method from sva package (parametric)
      "combat" = {
        if(!requireNamespace("sva", quietly = TRUE)) {
          install.packages("sva", quiet = TRUE)
        }
        
        tryCatch({
          # Create model matrix for ComBat
          if(!is.null(group_info)) {
            mod <- model.matrix(~ group_info)
            
            # Check if design matrix is full rank
            if(qr(mod)$rank < ncol(mod)) {
              warning("Design matrix is not full rank. This may indicate confounding issues.")
              # Try with intercept only
              message("Attempting ComBat with intercept-only model due to rank deficiency...")
              mod <- model.matrix(~ 1, data = data.frame(x = 1:ncol(data)))
            }
          } else {
            mod <- model.matrix(~ 1, data = data.frame(x = 1:ncol(data)))
          }
          
          # Check for sufficient samples per batch-group combination
          if(!is.null(group_info)) {
            batch_group_table <- table(batch_info, group_info)
            min_samples <- min(batch_group_table[batch_group_table > 0])
            if(min_samples < 2) {
              warning("Some batch-group combinations have fewer than 2 samples. ComBat may be unstable.")
            }
          }
          
          # Apply ComBat with parametric adjustment
          message("Applying ComBat (parametric) batch correction...")
          combat_data <- sva::ComBat(
            dat = data,
            batch = batch_info,
            mod = mod,
            par.prior = TRUE,
            mean.only = FALSE
          )
          
          message("ComBat batch correction completed successfully")
          return(combat_data)
          
        }, error = function(e) {
          error_msg <- e$message
          
          # Provide specific guidance for common ComBat errors
          if(grepl("singular|rank|matrix", error_msg, ignore.case = TRUE)) {
            stop("ComBat failed due to singular design matrix. This usually indicates:\n",
                 "1. Perfect confounding between batch and biological groups\n",
                 "2. Insufficient samples per batch-group combination\n",
                 "3. Linear dependency in the design matrix\n",
                 "Solutions:\n",
                 "- Try ComBat non-parametric method\n",
                 "- Use limma's removeBatchEffect instead\n",
                 "- Check sample distribution across batches and groups\n",
                 "Original error: ", error_msg)
          } else if(grepl("length|dimension", error_msg, ignore.case = TRUE)) {
            stop("ComBat failed due to dimension mismatch:\n",
                 "- Check that batch_info length matches number of samples\n",
                 "- Ensure no missing values in batch or group information\n",
                 "Original error: ", error_msg)
          } else {
            stop("ComBat batch correction failed: ", error_msg, "\n",
                 "Try alternative methods like:\n",
                 "- ComBat non-parametric\n",
                 "- limma's removeBatchEffect\n",
                 "- SVA surrogate variable analysis")
          }
        })
      },
      
      # ComBat non-parametric method from sva package
      "combat_nonpar" = {
        if(!requireNamespace("sva", quietly = TRUE)) {
          install.packages("sva", quiet = TRUE)
        }
        
        tryCatch({
          # Create model matrix for ComBat
          if(!is.null(group_info)) {
            mod <- model.matrix(~ group_info)
            
            # Check if design matrix is full rank
            if(qr(mod)$rank < ncol(mod)) {
              warning("Design matrix is not full rank. Using intercept-only model for non-parametric ComBat.")
              mod <- model.matrix(~ 1, data = data.frame(x = 1:ncol(data)))
            }
          } else {
            mod <- model.matrix(~ 1, data = data.frame(x = 1:ncol(data)))
          }
          
          # Check for sufficient samples per batch for non-parametric method
          batch_counts <- table(batch_info)
          if(any(batch_counts < 3)) {
            warning("Some batches have fewer than 3 samples. Non-parametric ComBat may be unstable.")
          }
          
          # Apply ComBat with non-parametric adjustment
          message("Applying ComBat (non-parametric) batch correction...")
          combat_data <- sva::ComBat(
            dat = data,
            batch = batch_info,
            mod = mod,
            par.prior = FALSE,  # Non-parametric adjustment
            mean.only = FALSE
          )
          
          message("ComBat non-parametric batch correction completed successfully")
          return(combat_data)
          
        }, error = function(e) {
          error_msg <- e$message
          
          # Provide specific guidance for non-parametric ComBat errors
          if(grepl("singular|rank|matrix", error_msg, ignore.case = TRUE)) {
            stop("ComBat non-parametric failed due to design matrix issues:\n",
                 "1. Perfect confounding detected between batch and groups\n",
                 "2. Insufficient sample diversity within batches\n",
                 "3. Try parametric ComBat or limma's removeBatchEffect\n",
                 "Original error: ", error_msg)
          } else if(grepl("empirical", error_msg, ignore.case = TRUE)) {
            stop("ComBat non-parametric failed during empirical Bayes estimation:\n",
                 "- This often occurs with small batch sizes or extreme confounding\n",
                 "- Try parametric ComBat instead\n",
                 "- Consider using limma's removeBatchEffect\n",
                 "Original error: ", error_msg)
          } else {
            stop("ComBat non-parametric batch correction failed: ", error_msg, "\n",
                 "Alternative approaches:\n",
                 "- Use parametric ComBat\n",
                 "- Try limma's removeBatchEffect\n",
                 "- Consider SVA for surrogate variable analysis")
          }
        })
      },
      
      # limma's removeBatchEffect
      "limma" = {
        # First check if limma is available
        if(!requireNamespace("limma", quietly = TRUE)) {
          message("Installing limma package from Bioconductor...")
          if(!requireNamespace("BiocManager", quietly = TRUE)) {
            install.packages("BiocManager", quiet = TRUE)
          }
          BiocManager::install("limma", update = FALSE, ask = FALSE)
          if(!requireNamespace("limma", quietly = TRUE)) {
            warning("Failed to install limma package. Returning original data.")
            return(data)
          }
        }
        
        # Load the limma package explicitly
        library(limma)
        
        message("Starting limma batch correction...")
        
        # Design matrix for biological groups
        design <- NULL
        if(!is.null(group_info)) {
          # Ensure group_info is a factor with proper levels
          group_info <- as.factor(group_info)
          # Create design matrix with no intercept
          tryCatch({
            design <- model.matrix(~ 0 + group_info)
            colnames(design) <- levels(group_info)
            message("Created design matrix with dimensions: ", nrow(design), "x", ncol(design))
          }, error = function(e) {
            warning(paste("Failed to create design matrix for limma:", e$message))
            design <- NULL
          })
        } else {
          # Create a default design with intercept only if no group_info provided
          message("No group information provided, using default design")
          design <- matrix(1, ncol(data), 1)
          colnames(design) <- "Intercept"
        }
        
        # Apply limma's removeBatchEffect with enhanced error handling
        limma_data <- tryCatch({
          # Ensure batch_info is properly formatted
          batch_info_factor <- as.factor(batch_info)
          
          # Print debug information
          message("- Data dimensions: ", nrow(data), "x", ncol(data))
          message("- Number of batches: ", length(levels(batch_info_factor)))
          message("- Batch levels: ", paste(levels(batch_info_factor), collapse=", "))
          
          # Check for confounding issues specific to limma
          if(!is.null(design) && !is.null(group_info)) {
            # Check if design matrix is full rank
            if(qr(design)$rank < ncol(design)) {
              stop("Design matrix is rank deficient. This indicates perfect confounding between ",
                   "batch and biological groups. limma's removeBatchEffect cannot proceed.\n",
                   "Solutions:\n",
                   "1. Ensure each biological group appears in multiple batches\n",
                   "2. Try ComBat methods which may handle some confounding\n",
                   "3. Analyze each batch separately")
            }
            
            # Check sample distribution
            if(!is.null(group_info)) {
              batch_group_table <- table(batch_info_factor, group_info)
              zero_cells <- sum(batch_group_table == 0)
              total_cells <- length(batch_group_table)
              
              if(zero_cells > (total_cells * 0.5)) {
                warning("More than 50% of batch-group combinations are empty. ",
                        "This indicates severe confounding that may affect results.")
              }
            }
          }
          
          # Handle missing values if present
          has_na <- anyNA(data)
          if(has_na) {
            message("Warning: Data contains missing values. Imputing with column means.")
            # Simple imputation for missing values
            data_for_correction <- data
            for(j in 1:ncol(data)) {
              col_mean <- mean(data[,j], na.rm = TRUE)
              na_idx <- is.na(data[,j])
              if(any(na_idx)) {
                data_for_correction[na_idx, j] <- col_mean
              }
            }
          } else {
            data_for_correction <- data
          }
          
          # Apply removeBatchEffect
          message("Applying limma removeBatchEffect...")
          corrected <- removeBatchEffect(
            x = data_for_correction,
            batch = batch_info_factor,
            design = design
          )
          
          # Restore missing values if they were present
          if(has_na) {
            corrected[is.na(data)] <- NA
          }
          
          message("Batch correction completed successfully")
          return(corrected)
        }, error = function(e) {
          error_msg <- e$message
          
          # Provide specific guidance for limma errors
          if(grepl("singular|rank|matrix", error_msg, ignore.case = TRUE)) {
            stop("limma removeBatchEffect failed due to singular design matrix:\n",
                 "1. Perfect confounding between batch and biological groups detected\n",
                 "2. Design matrix is not full rank\n",
                 "3. Each biological group may be present in only one batch\n",
                 "Solutions:\n",
                 "- Redesign experiment to include each group in multiple batches\n",
                 "- Try ComBat methods (may handle some confounding scenarios)\n",
                 "- Consider analyzing each batch separately\n",
                 "Original error: ", error_msg)
          } else if(grepl("dimension|length", error_msg, ignore.case = TRUE)) {
            stop("limma removeBatchEffect failed due to dimension mismatch:\n",
                 "- Check that batch information matches number of samples\n",
                 "- Ensure design matrix dimensions are correct\n",
                 "- Verify no missing values in batch or group factors\n",
                 "Original error: ", error_msg)
          } else if(grepl("factor|level", error_msg, ignore.case = TRUE)) {
            stop("limma removeBatchEffect failed due to factor level issues:\n",
                 "- Check that batch and group factors have valid levels\n",
                 "- Ensure no empty factor levels\n",
                 "- All samples should belong to defined batches and groups\n",
                 "Original error: ", error_msg)
          } else {
            warning(paste("limma batch correction failed:", error_msg,
                          "\nTrying alternative approaches or returning original data"))
            return(data)
          }
        })
        
        return(limma_data)
      },
      
      # SVA (Surrogate Variable Analysis)
      "sva" = {
        # Install and load required packages
        if(!requireNamespace("sva", quietly = TRUE)) {
          message("Installing sva package...")
          if(!requireNamespace("BiocManager", quietly = TRUE)) {
            install.packages("BiocManager", quiet = TRUE)
          }
          BiocManager::install("sva", update = FALSE, ask = FALSE)
        }
        
        if(!requireNamespace("limma", quietly = TRUE)) {
          message("Installing limma package...")
          if(!requireNamespace("BiocManager", quietly = TRUE)) {
            install.packages("BiocManager", quiet = TRUE)
          }
          BiocManager::install("limma", update = FALSE, ask = FALSE)
        }
        
        message("Starting SVA batch correction...")
        
        # Store original dimensions and names
        orig_rownames <- rownames(data)
        orig_colnames <- colnames(data)
        
        # Handle missing values (SVA doesn't handle NAs well)
        has_na <- anyNA(data)
        if(has_na) {
          message("Imputing missing values for SVA analysis")
          # Impute missing values with row means
          data_no_na <- data
          for(i in 1:nrow(data)) {
            row_mean <- mean(data[i,], na.rm = TRUE)
            na_idx <- is.na(data[i,])
            data_no_na[i, na_idx] <- row_mean
          }
        } else {
          data_no_na <- data
        }
        
        # Transpose data for SVA (SVA expects samples as rows)
        data_t <- t(data_no_na)
        
        # Create model matrices
        # Full model with biological variables (if provided)
        if(!is.null(group_info)) {
          group_info_factor <- as.factor(group_info)
          message("Creating full model with ", length(levels(group_info_factor)), " groups")
          mod <- stats::model.matrix(~ group_info_factor)
        } else {
          # If no group info, use just intercept model
          message("No group information provided, using intercept-only model")
          mod <- stats::model.matrix(~ 1, data = data.frame(x = rep(1, ncol(data))))
        }
        
        # Create null model (for SVA)
        mod0 <- stats::model.matrix(~ 1, data = data.frame(x = rep(1, ncol(data))))
        
        tryCatch({
          # Check for confounding issues before SVA
          if(!is.null(group_info)) {
            # Check design matrix rank
            if(qr(mod)$rank < ncol(mod)) {
              warning("Design matrix is rank deficient. SVA may not work properly with perfect confounding.")
            }
            
            # Check sample sizes
            group_sizes <- table(group_info)
            if(any(group_sizes < 3)) {
              warning("Some groups have fewer than 3 samples. SVA results may be unreliable.")
            }
          }
          
          # Determine number of surrogate variables
          message("Estimating number of surrogate variables...")
          n_sv <- tryCatch({
            sva::num.sv(data_t, mod, method = "be")
          }, error = function(e) {
            warning("Failed to estimate number of SVs using 'be' method. Trying 'leek' method.")
            tryCatch({
              sva::num.sv(data_t, mod, method = "leek")
            }, error = function(e2) {
              warning("Both methods failed. Using default of 1 SV.")
              return(1)
            })
          })
          
          if(is.na(n_sv) || n_sv < 1) {
            n_sv <- 1
            message("Could not determine optimal number of SVs, defaulting to 1")
          } else {
            message("Estimated ", n_sv, " surrogate variables")
          }
          
          # Check if we have enough degrees of freedom
          total_samples <- ncol(data)
          model_df <- ncol(mod)
          if((model_df + n_sv) >= total_samples) {
            n_sv <- max(1, total_samples - model_df - 1)
            message("Reducing number of SVs to ", n_sv, " due to insufficient degrees of freedom")
          }
          
          # Compute surrogate variables
          message("Computing surrogate variables...")
          svobj <- sva::sva(data_t, mod, mod0, n.sv = n_sv)
          
          # Apply batch correction
          message("Applying batch correction with SVA...")
          # SVA = corrected data = original data - SV effect
          # Use limma's removeBatchEffect with SVs as covariates
          corrected_t <- limma::removeBatchEffect(data_t, covariates = svobj$sv, design = mod)
          
          # Transpose back to original format
          corrected <- t(corrected_t)
          rownames(corrected) <- orig_rownames
          colnames(corrected) <- orig_colnames
          
          # Restore NAs if they were present
          if(has_na) {
            message("Restoring original NA pattern...")
            corrected[is.na(data)] <- NA
          }
          
          message("SVA batch correction completed successfully")
          return(corrected)
        }, error = function(e) {
          error_msg <- e$message
          
          # Provide specific guidance for SVA errors
          if(grepl("singular|rank", error_msg, ignore.case = TRUE)) {
            stop("SVA failed due to singular matrix issues:\n",
                 "1. Perfect confounding between batch and biological variables\n",
                 "2. Insufficient sample diversity for surrogate variable detection\n",
                 "3. Model matrices may be rank deficient\n",
                 "Solutions:\n",
                 "- Try ComBat or limma methods instead\n",
                 "- Ensure adequate sample sizes per group (>3)\n",
                 "- Check for complete confounding between batches and groups\n",
                 "Original error: ", error_msg)
          } else if(grepl("num.sv|surrogate", error_msg, ignore.case = TRUE)) {
            stop("SVA failed during surrogate variable estimation:\n",
                 "- Unable to identify hidden batch effects\n",
                 "- This may indicate no significant batch effects present\n",
                 "- Or severe confounding prevents detection\n",
                 "Solutions:\n",
                 "- Try other batch correction methods\n",
                 "- Check if batch correction is actually needed\n",
                 "- Verify experimental design\n",
                 "Original error: ", error_msg)
          } else if(grepl("dimension|length", error_msg, ignore.case = TRUE)) {
            stop("SVA failed due to data dimension issues:\n",
                 "- Check data matrix dimensions and sample matching\n",
                 "- Ensure no missing values after imputation\n",
                 "- Verify batch and group information alignment\n",
                 "Original error: ", error_msg)
          } else {
            warning("SVA batch correction failed: ", error_msg,
                    "\nTrying fallback to original data")
            return(data)
          }
        })
      },
      
      # DESeq2 internal batch correction
      "deseq2" = {
        # For DESeq2, we just return the original data since batch correction
        # is handled internally during DESeq2 analysis by including batch in the design formula
        message("DESeq2 batch correction will be applied during statistical analysis")
        return(data)
      },
      # edgeR internal batch handling (design includes batch factor)
      "edger" = {
        message("edgeR batch handling will be applied during statistical analysis via design (~ batch + group)")
        return(data)
      },
      
      # Default: return original data with warning
      {
        warning("Unrecognized batch correction method: ", method, ". Returning original data.")
        return(data)
      }
    )
    
    return(corrected_data)
  }
  
  # ==================== QC-BASED SIGNAL DRIFT CORRECTION FUNCTIONS ====================
  
 # Function to identify QC samples from sample names or metadata
  identify_qc_samples <- function(sample_names, method = "auto", 
                                  pattern = "QC|[Pp]ool|[Pp]ooled|NIST|[Bb]lank",
                                  metadata_column = NULL) {
    
    n_samples <- length(sample_names)
    qc_indices <- integer(0)
    
    if (method == "auto" || method == "pattern") {
      # Use regex pattern matching
      qc_matches <- grepl(pattern, sample_names, ignore.case = TRUE)
      qc_indices <- which(qc_matches)
    } else if (method == "metadata" && !is.null(metadata_column)) {
      # Use metadata column
      if (is.logical(metadata_column)) {
        qc_indices <- which(metadata_column)
      } else if (is.numeric(metadata_column)) {
        qc_indices <- which(metadata_column == 1)
      } else {
        # Check for QC-related text values
        qc_values <- c("qc", "true", "yes", "1", "pool", "pooled", "quality control")
        qc_indices <- which(tolower(as.character(metadata_column)) %in% qc_values)
      }
    }
    
    # Return results
    list(
      qc_indices = qc_indices,
      qc_names = sample_names[qc_indices],
      biological_indices = setdiff(1:n_samples, qc_indices),
      biological_names = sample_names[setdiff(1:n_samples, qc_indices)],
      n_qc = length(qc_indices),
      n_biological = n_samples - length(qc_indices)
    )
  }
  
  # Function to calculate run order from various sources
  determine_run_order <- function(sample_names, method = "column_order",
                                  metadata_column = NULL, pattern = NULL) {
    
    n_samples <- length(sample_names)
    
    if (method == "column_order") {
      # Use column position as run order
      return(1:n_samples)
    } else if (method == "metadata" && !is.null(metadata_column)) {
      # Use metadata column (ensure numeric)
      run_order <- as.numeric(as.character(metadata_column))
      if (any(is.na(run_order))) {
        warning("Some run order values could not be converted to numeric. Using column order.")
        return(1:n_samples)
      }
      return(run_order)
    } else if (method == "names" && !is.null(pattern)) {
      # Extract from sample names using regex
      run_order <- rep(NA, n_samples)
      for (i in 1:n_samples) {
        match <- regmatches(sample_names[i], regexec(pattern, sample_names[i], perl = TRUE))
        if (length(match[[1]]) > 1) {
          run_order[i] <- as.numeric(match[[1]][2])
        }
      }
      if (all(is.na(run_order))) {
        warning("Could not extract run order from sample names. Using column order.")
        return(1:n_samples)
      }
      # Fill in any NAs with interpolation
      if (any(is.na(run_order))) {
        warning("Some run orders could not be extracted. Filling with sequential values.")
        na_idx <- which(is.na(run_order))
        non_na_order <- run_order[!is.na(run_order)]
        run_order[na_idx] <- max(non_na_order) + seq_along(na_idx)
      }
      return(run_order)
    }
    
    # Default fallback
    return(1:n_samples)
  }
  
  # QC-RLSC (QC Robust Loess Signal Correction) implementation
  perform_qc_rlsc <- function(data, qc_indices, run_order, span = 0.75, 
                               per_batch = FALSE, batch_info = NULL) {
    
    # Validate inputs
    if (length(qc_indices) < 3) {
      stop("QC-RLSC requires at least 3 QC samples for reliable LOESS fitting.")
    }
    
    # Ensure data is matrix
    data <- as.matrix(data)
    n_features <- nrow(data)
    n_samples <- ncol(data)
    
    # Initialize corrected data matrix
    corrected_data <- data
    models <- list()
    
    # Get QC run orders and biological sample orders
    qc_run_order <- run_order[qc_indices]
    bio_indices <- setdiff(1:n_samples, qc_indices)
    bio_run_order <- run_order[bio_indices]
    
    message(sprintf("Applying QC-RLSC correction with span=%.2f...", span))
    message(sprintf("  - %d QC samples, %d biological samples", length(qc_indices), length(bio_indices)))
    
    if (per_batch && !is.null(batch_info)) {
      # Apply correction within each batch separately
      batches <- unique(batch_info)
      for (batch in batches) {
        batch_mask <- batch_info == batch
        batch_qc_idx <- intersect(qc_indices, which(batch_mask))
        
        if (length(batch_qc_idx) >= 3) {
          batch_bio_idx <- setdiff(which(batch_mask), batch_qc_idx)
          batch_qc_order <- run_order[batch_qc_idx]
          batch_bio_order <- run_order[batch_bio_idx]
          
          for (i in 1:n_features) {
            qc_values <- data[i, batch_qc_idx]
            
            # Skip if all QC values are NA or constant
            if (all(is.na(qc_values)) || sd(qc_values, na.rm = TRUE) == 0) {
              next
            }
            
            # Fit LOESS model to QC samples
            tryCatch({
              loess_fit <- loess(qc_values ~ batch_qc_order, span = span, degree = 2)
              
              # Predict correction factors for all samples in batch
              qc_pred <- predict(loess_fit, newdata = batch_qc_order)
              bio_pred <- predict(loess_fit, newdata = batch_bio_order)
              
              # Calculate median of QC values for reference
              qc_median <- median(qc_values, na.rm = TRUE)
              
              # Apply correction: corrected = original * (qc_median / predicted)
              corrected_data[i, batch_qc_idx] <- data[i, batch_qc_idx] * (qc_median / qc_pred)
              corrected_data[i, batch_bio_idx] <- data[i, batch_bio_idx] * (qc_median / bio_pred)
              
            }, error = function(e) {
              # If LOESS fails, use median normalization
              corrected_data[i, batch_mask] <<- data[i, batch_mask] * 
                (median(data[i, batch_qc_idx], na.rm = TRUE) / mean(data[i, batch_qc_idx], na.rm = TRUE))
            })
          }
        } else {
          warning(sprintf("Batch %s has fewer than 3 QC samples. Using simple median normalization.", batch))
        }
      }
    } else {
      # Apply correction to all samples together
      for (i in 1:n_features) {
        qc_values <- data[i, qc_indices]
        
        # Skip if all QC values are NA or constant
        if (all(is.na(qc_values)) || length(unique(qc_values[!is.na(qc_values)])) < 2) {
          next
        }
        
        tryCatch({
          # Fit LOESS model to QC samples
          loess_fit <- loess(qc_values ~ qc_run_order, span = span, degree = 2,
                             control = loess.control(surface = "direct"))
          
          # Store model for visualization
          models[[i]] <- loess_fit
          
          # Predict for all samples
          all_pred <- predict(loess_fit, newdata = run_order)
          
          # Calculate QC median for reference
          qc_median <- median(qc_values, na.rm = TRUE)
          
          # Apply correction
          correction_factors <- qc_median / all_pred
          correction_factors[is.na(correction_factors) | is.infinite(correction_factors)] <- 1
          corrected_data[i, ] <- data[i, ] * correction_factors
          
        }, error = function(e) {
          # Fallback to simple median normalization for this feature
          qc_mean <- mean(qc_values, na.rm = TRUE)
          qc_median <- median(qc_values, na.rm = TRUE)
          if (qc_mean != 0) {
            corrected_data[i, ] <<- data[i, ] * (qc_median / qc_mean)
          }
        })
        
        # Progress message every 500 features
        if (i %% 500 == 0) {
          message(sprintf("  Processed %d/%d features...", i, n_features))
        }
      }
    }
    
    message("QC-RLSC correction completed.")
    
    return(list(
      corrected_data = corrected_data,
      models = models,
      method = "qc_rlsc"
    ))
  }
  
  # QC-SVR (Support Vector Regression) correction
  perform_qc_svr <- function(data, qc_indices, run_order, kernel = "radial", cost = 1) {
    
    # Check for e1071 package
    if (!requireNamespace("e1071", quietly = TRUE)) {
      stop("Package 'e1071' is required for SVR correction. Please install it.")
    }
    
    # Validate inputs
    if (length(qc_indices) < 3) {
      stop("QC-SVR requires at least 3 QC samples.")
    }
    
    data <- as.matrix(data)
    n_features <- nrow(data)
    n_samples <- ncol(data)
    
    corrected_data <- data
    models <- list()
    
    qc_run_order <- run_order[qc_indices]
    
    message(sprintf("Applying QC-SVR correction (kernel=%s, cost=%.2f)...", kernel, cost))
    
    for (i in 1:n_features) {
      qc_values <- data[i, qc_indices]
      
      # Skip if constant or all NA
      if (all(is.na(qc_values)) || sd(qc_values, na.rm = TRUE) == 0) {
        next
      }
      
      tryCatch({
        # Fit SVR model
        train_df <- data.frame(value = qc_values, order = qc_run_order)
        svr_fit <- e1071::svm(value ~ order, data = train_df, 
                              type = "eps-regression",
                              kernel = kernel, cost = cost)
        
        models[[i]] <- svr_fit
        
        # Predict for all samples
        all_df <- data.frame(order = run_order)
        all_pred <- predict(svr_fit, newdata = all_df)
        
        # Apply correction
        qc_median <- median(qc_values, na.rm = TRUE)
        correction_factors <- qc_median / all_pred
        correction_factors[is.na(correction_factors) | is.infinite(correction_factors)] <- 1
        corrected_data[i, ] <- data[i, ] * correction_factors
        
      }, error = function(e) {
        # Fallback
        qc_mean <- mean(qc_values, na.rm = TRUE)
        qc_median <- median(qc_values, na.rm = TRUE)
        if (qc_mean != 0) {
          corrected_data[i, ] <<- data[i, ] * (qc_median / qc_mean)
        }
      })
      
      if (i %% 500 == 0) {
        message(sprintf("  Processed %d/%d features...", i, n_features))
      }
    }
    
    message("QC-SVR correction completed.")
    
    return(list(
      corrected_data = corrected_data,
      models = models,
      method = "qc_svr"
    ))
  }
  
  # SERRF (Sample-specific Error Removal by Random Forest) correction
  perform_serrf <- function(data, qc_indices, run_order, ntrees = 500, batch_info = NULL) {
    
    # Check for randomForest package
    if (!requireNamespace("randomForest", quietly = TRUE)) {
      stop("Package 'randomForest' is required for SERRF correction. Please install it.")
    }
    
    if (length(qc_indices) < 5) {
      stop("SERRF requires at least 5 QC samples for reliable random forest fitting.")
    }
    
    data <- as.matrix(data)
    n_features <- nrow(data)
    n_samples <- ncol(data)
    
    corrected_data <- data
    
    # Prepare QC data
    qc_data <- data[, qc_indices, drop = FALSE]
    qc_run_order <- run_order[qc_indices]
    
    message(sprintf("Applying SERRF correction with %d trees...", ntrees))
    
    for (i in 1:n_features) {
      target_values <- qc_data[i, ]
      
      # Skip if constant or all NA
      if (all(is.na(target_values)) || sd(target_values, na.rm = TRUE) == 0) {
        next
      }
      
      # Create predictor matrix from other features' QC values
      # Use top correlated features as predictors (max 50)
      other_features <- setdiff(1:n_features, i)
      
      if (length(other_features) > 50) {
        # Select most correlated features
        correlations <- sapply(other_features, function(j) {
          cor(target_values, qc_data[j, ], use = "pairwise.complete.obs")
        })
        correlations[is.na(correlations)] <- 0
        top_idx <- order(abs(correlations), decreasing = TRUE)[1:50]
        predictor_features <- other_features[top_idx]
      } else {
        predictor_features <- other_features
      }
      
      tryCatch({
        # Create training data
        train_x <- t(qc_data[predictor_features, , drop = FALSE])
        train_x <- cbind(train_x, run_order = qc_run_order)
        if (!is.null(batch_info)) {
          train_x <- cbind(train_x, batch = as.numeric(as.factor(batch_info[qc_indices])))
        }
        train_y <- target_values
        
        # Remove rows with NA
        complete_mask <- complete.cases(train_x) & !is.na(train_y)
        if (sum(complete_mask) < 3) next
        
        train_x <- train_x[complete_mask, , drop = FALSE]
        train_y <- train_y[complete_mask]
        
        # Fit random forest
        rf_fit <- randomForest::randomForest(
          x = train_x, y = train_y,
          ntree = ntrees, importance = FALSE
        )
        
        # Predict for all samples
        all_x <- t(data[predictor_features, , drop = FALSE])
        all_x <- cbind(all_x, run_order = run_order)
        if (!is.null(batch_info)) {
          all_x <- cbind(all_x, batch = as.numeric(as.factor(batch_info)))
        }
        
        all_pred <- predict(rf_fit, newdata = all_x)
        
        # Apply correction
        qc_median <- median(target_values, na.rm = TRUE)
        correction_factors <- qc_median / all_pred
        correction_factors[is.na(correction_factors) | is.infinite(correction_factors)] <- 1
        corrected_data[i, ] <- data[i, ] * correction_factors
        
      }, error = function(e) {
        # Fallback to median normalization
        qc_mean <- mean(target_values, na.rm = TRUE)
        qc_median <- median(target_values, na.rm = TRUE)
        if (qc_mean != 0) {
          corrected_data[i, ] <<- data[i, ] * (qc_median / qc_mean)
        }
      })
      
      if (i %% 100 == 0) {
        message(sprintf("  Processed %d/%d features...", i, n_features))
      }
    }
    
    message("SERRF correction completed.")
    
    return(list(
      corrected_data = corrected_data,
      method = "serrf"
    ))
  }
  
  # Cubic Spline Interpolation correction
  perform_spline_correction <- function(data, qc_indices, run_order, df = 5) {
    
    if (length(qc_indices) < 4) {
      stop("Spline correction requires at least 4 QC samples.")
    }
    
    data <- as.matrix(data)
    n_features <- nrow(data)
    n_samples <- ncol(data)
    
    corrected_data <- data
    models <- list()
    
    qc_run_order <- run_order[qc_indices]
    
    # Adjust df based on number of QC samples
    effective_df <- min(df, length(qc_indices) - 2)
    
    message(sprintf("Applying cubic spline correction (df=%d)...", effective_df))
    
    for (i in 1:n_features) {
      qc_values <- data[i, qc_indices]
      
      if (all(is.na(qc_values)) || sd(qc_values, na.rm = TRUE) == 0) {
        next
      }
      
      tryCatch({
        # Fit smoothing spline
        spline_fit <- smooth.spline(qc_run_order, qc_values, df = effective_df)
        
        models[[i]] <- spline_fit
        
        # Predict for all samples
        all_pred <- predict(spline_fit, run_order)$y
        
        # Apply correction
        qc_median <- median(qc_values, na.rm = TRUE)
        correction_factors <- qc_median / all_pred
        correction_factors[is.na(correction_factors) | is.infinite(correction_factors)] <- 1
        corrected_data[i, ] <- data[i, ] * correction_factors
        
      }, error = function(e) {
        qc_mean <- mean(qc_values, na.rm = TRUE)
        qc_median <- median(qc_values, na.rm = TRUE)
        if (qc_mean != 0) {
          corrected_data[i, ] <<- data[i, ] * (qc_median / qc_mean)
        }
      })
      
      if (i %% 500 == 0) {
        message(sprintf("  Processed %d/%d features...", i, n_features))
      }
    }
    
    message("Spline correction completed.")
    
    return(list(
      corrected_data = corrected_data,
      models = models,
      method = "spline"
    ))
  }
  
  # Simple Median QC Normalization
  perform_median_qc_normalization <- function(data, qc_indices) {
    
    if (length(qc_indices) < 2) {
      stop("Median QC normalization requires at least 2 QC samples.")
    }
    
    data <- as.matrix(data)
    n_features <- nrow(data)
    n_samples <- ncol(data)
    
    corrected_data <- data
    
    message("Applying median QC normalization...")
    
    # Calculate QC medians and means for each feature
    qc_data <- data[, qc_indices, drop = FALSE]
    qc_medians <- apply(qc_data, 1, median, na.rm = TRUE)
    qc_means <- apply(qc_data, 1, mean, na.rm = TRUE)
    
    # Calculate correction factors
    correction_factors <- qc_medians / qc_means
    correction_factors[is.na(correction_factors) | is.infinite(correction_factors)] <- 1
    
    # Apply correction to all samples
    for (j in 1:n_samples) {
      corrected_data[, j] <- data[, j] * correction_factors
    }
    
    message("Median QC normalization completed.")
    
    return(list(
      corrected_data = corrected_data,
      method = "median_qc"
    ))
  }
  
  # Main QC drift correction dispatcher
  perform_qc_drift_correction <- function(data, qc_indices, run_order, 
                                           method = "qc_rlsc", 
                                           span = 0.75,
                                           kernel = "radial",
                                           cost = 1,
                                           ntrees = 500,
                                           df = 5,
                                           per_batch = FALSE,
                                           batch_info = NULL) {
    
    # Validate inputs
    if (is.null(qc_indices) || length(qc_indices) == 0) {
      stop("No QC samples identified. Please check QC sample identification settings.")
    }
    
    if (is.null(run_order)) {
      run_order <- 1:ncol(data)
    }
    
    # Dispatch to appropriate method
    result <- switch(
      method,
      "qc_rlsc" = perform_qc_rlsc(data, qc_indices, run_order, span, per_batch, batch_info),
      "qc_svr" = perform_qc_svr(data, qc_indices, run_order, kernel, cost),
      "serrf" = perform_serrf(data, qc_indices, run_order, ntrees, batch_info),
      "spline" = perform_spline_correction(data, qc_indices, run_order, df),
      "median_qc" = perform_median_qc_normalization(data, qc_indices),
      {
        warning("Unknown QC drift correction method: ", method, ". Using QC-RLSC.")
        perform_qc_rlsc(data, qc_indices, run_order, span, per_batch, batch_info)
      }
    )
    
    return(result)
  }
  
  # Calculate QC RSD (Relative Standard Deviation) metrics
  calculate_qc_rsd <- function(data, qc_indices) {
    
    if (length(qc_indices) < 2) {
      return(NULL)
    }
    
    qc_data <- data[, qc_indices, drop = FALSE]
    
    # Calculate RSD for each feature
    rsd <- apply(qc_data, 1, function(x) {
      x <- x[!is.na(x)]
      if (length(x) < 2 || mean(x) == 0) return(NA)
      (sd(x) / mean(x)) * 100
    })
    
    return(rsd)
  }
  
  # Calculate drift correction quality metrics
  calculate_drift_metrics <- function(data_before, data_after, qc_indices, run_order) {
    
    rsd_before <- calculate_qc_rsd(data_before, qc_indices)
    rsd_after <- calculate_qc_rsd(data_after, qc_indices)
    
    # Remove NAs for comparison
    valid_idx <- !is.na(rsd_before) & !is.na(rsd_after)
    rsd_before_valid <- rsd_before[valid_idx]
    rsd_after_valid <- rsd_after[valid_idx]
    
    # Calculate metrics
    metrics <- list(
      # RSD statistics
      median_rsd_before = median(rsd_before, na.rm = TRUE),
      median_rsd_after = median(rsd_after, na.rm = TRUE),
      mean_rsd_before = mean(rsd_before, na.rm = TRUE),
      mean_rsd_after = mean(rsd_after, na.rm = TRUE),
      
      # Improvement metrics
      rsd_reduction_pct = if(length(rsd_before_valid) > 0) {
        ((median(rsd_before_valid) - median(rsd_after_valid)) / median(rsd_before_valid)) * 100
      } else NA,
      
      pct_features_improved = if(length(rsd_before_valid) > 0) {
        sum(rsd_after_valid < rsd_before_valid) / length(rsd_before_valid) * 100
      } else NA,
      
      # Features meeting quality thresholds
      pct_rsd_under_20_before = sum(rsd_before < 20, na.rm = TRUE) / sum(!is.na(rsd_before)) * 100,
      pct_rsd_under_20_after = sum(rsd_after < 20, na.rm = TRUE) / sum(!is.na(rsd_after)) * 100,
      pct_rsd_under_30_before = sum(rsd_before < 30, na.rm = TRUE) / sum(!is.na(rsd_before)) * 100,
      pct_rsd_under_30_after = sum(rsd_after < 30, na.rm = TRUE) / sum(!is.na(rsd_after)) * 100,
      
      # Drift magnitude (correlation of PC1 with run order)
      drift_score_before = calculate_drift_score(data_before, qc_indices, run_order),
      drift_score_after = calculate_drift_score(data_after, qc_indices, run_order),
      
      # Raw RSD vectors
      rsd_before = rsd_before,
      rsd_after = rsd_after
    )
    
    return(metrics)
  }
  
  # Calculate drift magnitude score
  calculate_drift_score <- function(data, qc_indices, run_order) {
    tryCatch({
      # PCA on QC samples only
      qc_data <- data[, qc_indices, drop = FALSE]
      qc_run_order <- run_order[qc_indices]
      
      # Remove features with no variance
      valid_features <- apply(qc_data, 1, function(x) sd(x, na.rm = TRUE) > 0)
      qc_data_valid <- qc_data[valid_features, , drop = FALSE]
      
      if (nrow(qc_data_valid) < 2 || ncol(qc_data_valid) < 2) {
        return(NA)
      }
      
      # Handle missing values
      qc_data_valid[is.na(qc_data_valid)] <- rowMeans(qc_data_valid, na.rm = TRUE)[row(qc_data_valid)[is.na(qc_data_valid)]]
      
      # PCA
      pca_result <- prcomp(t(qc_data_valid), scale. = TRUE)
      
      # Correlation of PC1 with run order
      pc1_cor <- abs(cor(pca_result$x[, 1], qc_run_order, use = "pairwise.complete.obs"))
      
      return(round(pc1_cor * 100, 1))
    }, error = function(e) {
      return(NA)
    })
  }
  
  # ==================== END QC-BASED SIGNAL DRIFT CORRECTION FUNCTIONS ====================
  
  # Batch correction visualization and metrics
  observe({
    req(values$normalized_data, input$batch_correction_enabled == "yes", values$metadata)
    
    # Extract batch information
    req(input$batch_column)
    batch_info <- values$metadata[[input$batch_column]]
    
    # Shared typography controls for all batch correction plots
    title_size <- if(!is.null(input$batch_title_size)) input$batch_title_size else 14
    axis_title_size <- if(!is.null(input$batch_axis_title_size)) input$batch_axis_title_size else 12
    axis_text_size <- if(!is.null(input$batch_axis_text_size)) input$batch_axis_text_size else 10
    legend_text_size <- if(!is.null(input$batch_legend_text_size)) input$batch_legend_text_size else 12
    
    # Get original data before batch correction (if available) or use raw data
    original_data <- if(!is.null(values$data_before_batch_correction)) {
      values$data_before_batch_correction
    } else {
      values$normalized_data  # This may not be ideal as it might already be batch-corrected
    }
    
    # Generate PCA plots for before/after comparison
    output$batch_correction_plot <- renderPlot({ 
      # Generate PCAs for both datasets
      pca_before <- prcomp(t(original_data), scale. = TRUE)
      pca_after <- prcomp(t(values$normalized_data), scale. = TRUE)
      
      # Create data frames for plotting
      pca_before_df <- data.frame(
        PC1 = pca_before$x[,1],
        PC2 = pca_before$x[,2],
        Batch = batch_info,
        Dataset = "Before Correction"
      )
      
      pca_after_df <- data.frame(
        PC1 = pca_after$x[,1],
        PC2 = pca_after$x[,2],
        Batch = batch_info,
        Dataset = "After Correction"
      )
      
      # Combine data frames
      combined_df <- rbind(pca_before_df, pca_after_df)

      # Reorder Dataset factor to show "Before Correction" first
      combined_df$Dataset <- factor(combined_df$Dataset, levels = c("Before Correction", "After Correction"))

      # Extract explained variance percentages
      var_before <- round(pca_before$sdev^2 / sum(pca_before$sdev^2) * 100, 1)
      var_after <- round(pca_after$sdev^2 / sum(pca_after$sdev^2) * 100, 1)

      # Create PCA plot
      if(input$batch_viz_color_by == "batch" || input$batch_viz_color_by == "both") {
        p <- ggplot(combined_df, aes(x = PC1, y = PC2, color = Batch)) +
          geom_point(size = 3, alpha = 0.8) +
          facet_wrap(~Dataset, scales = "free") +
          labs(
            title = "PCA Before and After Batch Correction",
            x = paste0("PC1 (", var_before[1], "% / ", var_after[1], "%)"),
            y = paste0("PC2 (", var_before[2], "% / ", var_after[2], "%)"),
            subtitle = paste("Method:", input$batch_correction_method)
          ) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = legend_text_size, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            plot.subtitle = element_text(face = "bold"),
            strip.text = element_text(face = "bold"),
            text = element_text(face = "bold"),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = "bottom"
          )
      } else if(input$batch_viz_color_by == "group" && !is.null(input$group_column) &&
                input$group_column %in% colnames(values$metadata)) {
        # Color by experimental group instead
        group_info <- values$metadata[[input$group_column]]
        combined_df$Group <- rep(group_info, 2)

        p <- ggplot(combined_df, aes(x = PC1, y = PC2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          facet_wrap(~Dataset, scales = "free") +
          labs(
            title = "PCA Before and After Batch Correction",
            x = paste0("PC1 (", var_before[1], "% / ", var_after[1], "%)"),
            y = paste0("PC2 (", var_before[2], "% / ", var_after[2], "%)"),
            subtitle = paste("Method:", input$batch_correction_method)
          ) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = legend_text_size, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            plot.subtitle = element_text(face = "bold"),
            strip.text = element_text(face = "bold"),
            text = element_text(face = "bold"),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = "bottom"
          )
      }

      # Store the plot for download
      values$batch_correction_plot_obj <- p

      return(p)
    }, res = UI_PLOT_RES)

    # Generate correlation heatmaps
    output$batch_correction_corr_heatmap <- renderPlot({ 
      # Calculate correlation matrices
      cor_before <- cor(original_data, use = "pairwise.complete.obs")
      cor_after <- cor(values$normalized_data, use = "pairwise.complete.obs")
      
      # Prepare batches for annotation
      batches <- batch_info
      
      # Generate heatmaps using ComplexHeatmap
      if(requireNamespace("ComplexHeatmap", quietly = TRUE)) {
        # Create top annotation based on batches
        # Check if RColorBrewer is available for colors
        if(requireNamespace("RColorBrewer", quietly = TRUE)) {
          batch_colors <- colorRampPalette(RColorBrewer::brewer.pal(8, "Dark2"))(length(unique(batches)))
        } else {
          # Fallback to default colors if RColorBrewer not available
          batch_colors <- rainbow(length(unique(batches)))
        }

        ha <- ComplexHeatmap::HeatmapAnnotation(
          Batch = batches,
          col = list(Batch = setNames(batch_colors, unique(batches)))
        )
        
        # Create heatmaps
        h1 <- ComplexHeatmap::Heatmap(
          cor_before, name = "Correlation\nBefore",
          top_annotation = ha,
          column_title = "Before Correction",
          clustering_method_columns = "ward.D2",
          clustering_method_rows = "ward.D2",
          show_row_names = FALSE,
          show_column_names = FALSE
        )
        
        h2 <- ComplexHeatmap::Heatmap(
          cor_after, name = "Correlation\nAfter",
          top_annotation = ha,
          column_title = "After Correction",
          clustering_method_columns = "ward.D2",
          clustering_method_rows = "ward.D2",
          show_row_names = FALSE,
          show_column_names = FALSE
        )
        
        # Draw heatmaps side by side
        ComplexHeatmap::draw(h1 + h2)
      } else {
        # Fallback using pheatmap
        grid.arrange(
          pheatmap(cor_before, main = "Before Correction", silent = TRUE)[[4]],
          pheatmap(cor_after, main = "After Correction", silent = TRUE)[[4]],
          ncol = 2
        )
      }
    }, res = UI_PLOT_RES)
    
    # Generate Relative Log Expression (RLE) plots
    output$batch_correction_rle <- renderPlot({ 
      # Calculate median expression for each row
      row_medians_before <- apply(original_data, 1, median, na.rm = TRUE)
      row_medians_after <- apply(values$normalized_data, 1, median, na.rm = TRUE)
      
      # Calculate RLE values (ensure matrices for consistent melt columns)
      rle_before <- sweep(as.matrix(original_data), 1, row_medians_before, "-")
      rle_after <- sweep(as.matrix(values$normalized_data), 1, row_medians_after, "-")
      
      # Preserve dimnames
      rownames(rle_before) <- rownames(original_data)
      colnames(rle_before) <- colnames(original_data)
      rownames(rle_after) <- rownames(values$normalized_data)
      colnames(rle_after) <- colnames(values$normalized_data)
      
      # Convert to long format for plotting and standardize column names
      rle_before_long <- reshape2::melt(rle_before)
      rle_after_long <- reshape2::melt(rle_after)
      colnames(rle_before_long) <- c("Feature", "Sample", "value")
      colnames(rle_after_long) <- c("Feature", "Sample", "value")
      
      # Add dataset and batch information
      rle_before_long$Dataset <- "Before Correction"
      rle_after_long$Dataset <- "After Correction"
      
      # Map Batch to Sample via join to avoid recycling/length issues
      batch_map_before <- data.frame(Sample = colnames(original_data), Batch = as.character(batch_info), stringsAsFactors = FALSE)
      batch_map_after <- data.frame(Sample = colnames(values$normalized_data), Batch = as.character(batch_info), stringsAsFactors = FALSE)

      # Ensure Batch column exists and add it safely
      rle_before_long <- tryCatch({
        dplyr::left_join(rle_before_long, batch_map_before, by = "Sample")
      }, error = function(e) {
        # Fallback: add Batch column directly
        rle_before_long$Batch <- rep(as.character(batch_info), each = nrow(original_data))
        rle_before_long
      }, res = UI_PLOT_RES)

      rle_after_long <- tryCatch({
        dplyr::left_join(rle_after_long, batch_map_after, by = "Sample")
      }, error = function(e) {
        # Fallback: add Batch column directly
        rle_after_long$Batch <- rep(as.character(batch_info), each = nrow(values$normalized_data))
        rle_after_long
      }, res = UI_PLOT_RES)

      # Combine data
      rle_combined <- rbind(rle_before_long, rle_after_long)

      # Ensure facet order: Before first, After second
      rle_combined$Dataset <- factor(rle_combined$Dataset, levels = c("Before Correction", "After Correction"))

      # Validate data exists
      if(nrow(rle_combined) == 0) {
        return(ggplot() + annotate("text", x = 0.5, y = 0.5, label = "No data to plot RLE.") + theme_void())
      }
      
      # Create plot
      p <- ggplot(rle_combined, aes(x = Sample, y = value, fill = Batch)) +
        geom_boxplot(outlier.size = 0.5) +
        facet_wrap(~Dataset, scales = "free_x") +
        labs(
          title = "Relative Log Expression (RLE) Before and After Batch Correction",
          x = "Sample",
          y = "RLE Value"
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5, size = axis_text_size, face = "bold", color = "black"),
          plot.title = element_text(face = "bold", hjust = 0.5, size = title_size),
          axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
          legend.text = element_text(size = legend_text_size, face = "bold"),
          legend.title = element_blank(),
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          strip.text = element_text(face = "bold"),
          legend.position = "bottom"
        )
      
      return(p)
    }, res = UI_PLOT_RES)
    
    # Generate boxplots by batch
    output$batch_correction_boxplot <- renderPlot({ 
      # Convert to long format for plotting
      data_before_long <- reshape2::melt(original_data)
      data_after_long <- reshape2::melt(values$normalized_data)
      
      # Add dataset and batch information
      data_before_long$Dataset <- "Before Correction"
      data_after_long$Dataset <- "After Correction"
      data_before_long$Batch <- rep(batch_info, each = nrow(original_data))
      data_after_long$Batch <- rep(batch_info, each = nrow(values$normalized_data))
      
      # Combine data
      data_combined <- rbind(data_before_long, data_after_long)
      # Ensure facet order: Before first, After second
      data_combined$Dataset <- factor(data_combined$Dataset, levels = c("Before Correction", "After Correction"))
      
      # Create plot
      p <- ggplot(data_combined, aes(x = Batch, y = value, fill = Batch)) +
        geom_boxplot(outlier.size = 0.5) +
        facet_wrap(~Dataset) +
        labs(
          title = "Distribution Before and After Batch Correction",
          y = "Value"
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          axis.text.x = element_text(angle = 45, hjust = 1, size = axis_text_size, face = "bold", color = "black"),
          plot.title = element_text(face = "bold", hjust = 0.5, size = title_size),
          axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
          legend.text = element_text(size = legend_text_size, face = "bold"),
          legend.title = element_blank(),
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          strip.text = element_text(face = "bold"),
          legend.position = "bottom"
        )
      
      return(p)
    }, res = UI_PLOT_RES)
    
    # Calculate batch effect metrics
    output$batch_correction_metrics <- renderTable({
      # Calculate batch effect size metric (avg difference between batches / total variation)
      calc_batch_effect_size <- function(data, batches) {
        batch_means <- sapply(split(data.frame(t(data)), batches), colMeans, na.rm = TRUE)
        overall_means <- rowMeans(data, na.rm = TRUE)
        batch_effect <- mean(apply(batch_means, 1, function(x) sd(x, na.rm = TRUE) / sd(overall_means, na.rm = TRUE)), na.rm = TRUE)
        return(batch_effect)
      }
      
      # Calculate CV between batches
      calc_cv_between_batches <- function(data, batches) {
        batch_means <- sapply(split(data.frame(t(data)), batches), colMeans, na.rm = TRUE)
        cv <- mean(apply(batch_means, 1, function(x) sd(x, na.rm = TRUE) / mean(x, na.rm = TRUE)), na.rm = TRUE) * 100
        return(cv)
      }
      
      # Calculate within-batch correlation
      calc_within_batch_corr <- function(data, batches) {
        corr_sum <- 0
        count <- 0
        
        for(batch in unique(batches)) {
          batch_data <- data[, batches == batch, drop = FALSE]
          if(ncol(batch_data) > 1) {
            batch_corr <- cor(batch_data, use = "pairwise.complete.obs")
            batch_corr_values <- batch_corr[upper.tri(batch_corr)]
            if(length(batch_corr_values) > 0) {
              corr_sum <- corr_sum + sum(batch_corr_values, na.rm = TRUE)
              count <- count + length(batch_corr_values)
            }
          }
        }
        
        return(if(count > 0) corr_sum / count else NA)
      }
      
      # Calculate metrics
      metrics <- data.frame(
        Metric = c("Batch Effect Size", "CV Between Batches (%)", "Within-Batch Correlation"),
        Before = c(
          calc_batch_effect_size(original_data, batch_info),
          calc_cv_between_batches(original_data, batch_info),
          calc_within_batch_corr(original_data, batch_info)
        ),
        After = c(
          calc_batch_effect_size(values$normalized_data, batch_info),
          calc_cv_between_batches(values$normalized_data, batch_info),
          calc_within_batch_corr(values$normalized_data, batch_info)
        )
      )
      
      # Add improvement percentage
      metrics$Improvement <- ifelse(metrics$Metric == "Within-Batch Correlation",
                                    (metrics$After - metrics$Before) / abs(metrics$Before) * 100,
                                    (metrics$Before - metrics$After) / metrics$Before * 100)
      
      # Format metrics for display
      metrics$Before <- round(metrics$Before, 4)
      metrics$After <- round(metrics$After, 4)
      metrics$Improvement <- round(metrics$Improvement, 2)
      metrics$Improvement <- paste0(metrics$Improvement, "%")
      
      return(metrics)
    })
  })
  
  # Reactive output to check if batch info is available in metadata sheet
  output$batch_info_in_metadata <- reactive({
    if (!is.null(values$metadata) && nrow(values$metadata) > 0) {
      # Check for common batch column names
      batch_column_names <- c("Batch", "batch", "Batch_ID", "batch_id", "BatchID", "batchid", 
                             "Processing_Batch", "processing_batch", "Run", "run", "Plate", "plate")
      
      # Check if any of these columns exist in metadata
      available_batch_cols <- batch_column_names[batch_column_names %in% colnames(values$metadata)]
      
      if (length(available_batch_cols) > 0) {
        # Return the first available batch column name
        return(available_batch_cols[1])
      }
    }
    return(NULL)
  })
  
  # Returns all comparison names (pairwise "A vs B" and lmROTS/lmeROTS variable names)
  # for use in dropdowns and downstream tabs.
  get_available_comparison_names <- function() {
    sr <- get_active_stat_results()
    if (is.null(sr) || ncol(sr) == 0) return(character(0))
    pvalue_cols <- grep("_PValue$", colnames(sr), value = TRUE)
    if (length(pvalue_cols) == 0) return(character(0))
    comparison_names <- gsub("_PValue$", "", pvalue_cols)
    # Pairwise: "GroupA vs GroupB"; variable: "lmROTS_Group", "lmeROTS_Age", etc.
    pairwise <- comparison_names[grepl(" vs ", comparison_names, fixed = TRUE)]
    variable <- comparison_names[grepl("^(lmROTS|lmeROTS)_", comparison_names)]
    unique(c(pairwise, variable))
  }

  get_appropriate_pvalue_column <- function(comparison_name) {
    # lmROTS/lmeROTS variable-style comparison (no " vs "): column is <name>_PValue
    if (!grepl(" vs ", comparison_name, fixed = TRUE)) {
      sr <- values$stat_results
      if (!is.null(sr)) {
        pcol <- paste0(comparison_name, "_PValue")
        if (pcol %in% colnames(sr)) return(pcol)
      }
      return(NULL)
    }
    # Special handling for global comparisons
    if (comparison_name == "Global" || comparison_name == "All_Groups") {
      # Check for various global p-value column names in a specific order
      global_column_options <- c(
        "ANOVA_AdjustedPValue",
        "KW_AdjustedPValue",
        "Limma_Global_AdjPValue",
        "DESeq2_Global_AdjPValue",
        "ANOVA_PValue",
        "KW_PValue",
        "Limma_Global_PValue",
        "DESeq2_Global_PValue",
        "edgeR_Global_PValue",
        "LimmaVoom_Global_PValue"
      )
      
      # Return the first matching column
      for (col_name in global_column_options) {
        if (!is.null(values$stat_results) && col_name %in% colnames(values$stat_results)) {
          return(col_name)
        }
      }
      
      # If no match found, try any column with Global + PValue/AdjPValue
      if (!is.null(values$stat_results)) {
        global_candidates <- grep("Global.*(AdjPValue|PValue|pvalue)",
                                  colnames(values$stat_results),
                                  value = TRUE,
                                  ignore.case = TRUE)
        if (length(global_candidates) > 0) {
          return(global_candidates[1])
        }
      }

      # If no match found, return a default
      return("ANOVA_AdjustedPValue")  # Default, even if not found
    }
    
    # Normal handling for pairwise comparisons
    groups <- unlist(strsplit(comparison_name, " vs "))
    if(length(groups) != 2) {
      message("Invalid comparison name format: ", comparison_name)
      return(NULL)
    }
    
    # Try both order possibilities for the comparison
    comparison_alt <- paste(groups[2], "vs", groups[1])
    comparison_name_us <- gsub(" vs ", "_vs_", comparison_name, fixed = TRUE)
    comparison_alt_us <- gsub(" vs ", "_vs_", comparison_alt, fixed = TRUE)
    
    # First, check if this is a ROTS result - if so, prioritize PValue (not FDR)
    # For ROTS analysis specifically, use p-values instead of FDR for filtering
    rots_p_value_col <- paste0(comparison_name, "_PValue")
    rots_p_value_col_alt <- paste0(comparison_alt, "_PValue")
    
    # If there's a FDR column, this indicates we're using ROTS
    rots_fdr_col <- paste0(comparison_name, "_FDR")
    rots_fdr_col_alt <- paste0(comparison_alt, "_FDR")
    
    if (!is.null(values$stat_results)) {
      if (rots_p_value_col %in% colnames(values$stat_results) &&
          (rots_fdr_col %in% colnames(values$stat_results) || # Look for explicit FDR column
           paste0(comparison_name, "_ROTS_R") %in% colnames(values$stat_results))) { # Or check for ROTS_R marker
        return(rots_p_value_col) # For ROTS, return PValue column
      }
      if (rots_p_value_col_alt %in% colnames(values$stat_results) &&
          (rots_fdr_col_alt %in% colnames(values$stat_results) ||
           paste0(comparison_alt, "_ROTS_R") %in% colnames(values$stat_results))) {
        return(rots_p_value_col_alt) # For ROTS with reversed comparison, return PValue column
      }
    }
    # Define list of possible p-value column patterns to check (for non-ROTS analyses)
    possible_columns <- c(
      paste0(comparison_name, "_AdjPValue"),
      paste0(comparison_alt, "_AdjPValue"),
      paste0(comparison_name, "_AdjustedPValue"),
      paste0(comparison_alt, "_AdjustedPValue"),
      paste0(comparison_name, "_Bootstrap_AdjPValue"),
      paste0(comparison_alt, "_Bootstrap_AdjPValue"),
      paste0("PostHoc_", comparison_name, "_AdjPValue"),
      paste0("PostHoc_", comparison_alt, "_AdjPValue"),
      paste0("PostHoc_", comparison_name_us, "_AdjPValue"),
      paste0("PostHoc_", comparison_alt_us, "_AdjPValue"),
      paste0("PostHoc_", comparison_name),  # Fallback for old naming
      paste0("PostHoc_", comparison_alt),   # Fallback for old naming
      paste0("PostHoc_", comparison_name_us),
      paste0("PostHoc_", comparison_alt_us),
      paste0(comparison_name, "_PValue"),
      paste0(comparison_alt, "_PValue"),
      paste0(comparison_name, "_Bootstrap_PValue"),
      paste0(comparison_alt, "_Bootstrap_PValue")
    )
    
    # Check if we're using ANOVA/Kruskal with post-hoc tests available
    if (input$sig_method %in% c("anova", "kruskal") &&
        input$posthoc_method != "none") {
      posthoc_col <- paste0("PostHoc_", comparison_name, "_AdjPValue")
      posthoc_col_alt <- paste0("PostHoc_", comparison_alt, "_AdjPValue")
      posthoc_col_us <- paste0("PostHoc_", comparison_name_us, "_AdjPValue")
      posthoc_col_alt_us <- paste0("PostHoc_", comparison_alt_us, "_AdjPValue")
      
      if (!is.null(values$stat_results) && posthoc_col %in% colnames(values$stat_results)) {
        return(posthoc_col)
      } else if (!is.null(values$stat_results) && posthoc_col_alt %in% colnames(values$stat_results)) {
        return(posthoc_col_alt)
      } else if (!is.null(values$stat_results) && posthoc_col_us %in% colnames(values$stat_results)) {
        return(posthoc_col_us)
      } else if (!is.null(values$stat_results) && posthoc_col_alt_us %in% colnames(values$stat_results)) {
        return(posthoc_col_alt_us)
      }
    }
    
    # If bootstrap is enabled, prioritize bootstrap results
    if (input$bootstrap_enabled == "yes") {
      bootstrap_col <- paste0(comparison_name, "_Bootstrap_AdjPValue")
      bootstrap_col_alt <- paste0(comparison_alt, "_Bootstrap_AdjPValue")
      
      if (!is.null(values$stat_results) && bootstrap_col %in% colnames(values$stat_results)) {
        return(bootstrap_col)
      } else if (!is.null(values$stat_results) && bootstrap_col_alt %in% colnames(values$stat_results)) {
        return(bootstrap_col_alt)
      }
    }
    
    # Try all possible column patterns in order
    for (col in possible_columns) {
      if (!is.null(values$stat_results) && col %in% colnames(values$stat_results)) {
        message("Found matching p-value column: ", col)
        return(col)
      }
    }
    
    # Last resort: check if any column contains both group names
    if (!is.null(values$stat_results)) {
      adj_cols <- grep("AdjPValue|AdjustedPValue|adj\\.P\\.Val|FDR", colnames(values$stat_results), value = TRUE)
      for (col in adj_cols) {
        if (all(sapply(groups, function(g) grepl(g, col, fixed = TRUE)))) {
          message("Found column containing both group names: ", col)
          return(col)
        }
      }
      
      # Try raw p-value columns as final fallback
      pval_cols <- grep("PValue|p\\.value|pval", colnames(values$stat_results), value = TRUE, ignore.case = TRUE)
      for (col in pval_cols) {
        if (all(sapply(groups, function(g) grepl(g, col, fixed = TRUE)))) {
          message("Falling back to raw p-value column containing both group names: ", col)
          return(col)
        }
      }
    }
    
    # If we still haven't found a match, return the default pattern
    message("Falling back to default p-value column: ", paste0(comparison_name, "_AdjPValue"))
    return(paste0(comparison_name, "_AdjPValue"))
  }
  
  # Function to calculate and add fold change columns for post-hoc comparisons
  # Helper function to check if data is log-scale
  is_data_log_scale <- function() {
    # Data is log-scale if any of these are true:
    # 1. Log2 before normalization is applied
    # 2. Log2 after normalization is applied
    # 3. VSN (variance stabilizing normalization - log-like) is selected
    # NOTE: Cyclic LOESS does NOT inherently apply log transformation - it depends on log2 timing
    is_log2_before <- identical(input$log2_norm_timing, "before")
    is_log2_after <- identical(input$log2_norm_timing, "after")
    is_vsn_method <- (input$normalization == "vsn")
    
    return(is_log2_before || is_log2_after || is_vsn_method)
  }
  
  add_posthoc_fold_changes <- function(stat_results) {
    # Get all groups from your reactive values (assumed set during data processing)
    groups <- values$unique_groups
    
    # Determine pairwise combinations to use (prioritize current_pairwise_combinations from pre-analysis modal)
    if (!is.null(values$current_pairwise_combinations) && nrow(values$current_pairwise_combinations) > 0) {
      # Use current_pairwise_combinations set by pre-analysis modal or review modal
      combinations_list <- lapply(seq_len(nrow(values$current_pairwise_combinations)), function(i) {
        c(values$current_pairwise_combinations[i, "Group_1"], values$current_pairwise_combinations[i, "Group_2"])
      })
    } else if (!is.null(values$pairwise_order) && nrow(values$pairwise_order) > 0) {
      # Fallback to pairwise_order (legacy support)
      combinations_list <- lapply(seq_len(nrow(values$pairwise_order)), function(i) {
        values$pairwise_order[i, ]
      })
    } else {
      # Use default combn order
      combinations_list <- combn(groups, 2, simplify = FALSE)
    }
    
    # Loop over all pairwise combinations
    for(i in seq_along(combinations_list)) {
      pair <- combinations_list[[i]]
      grp1 <- as.character(pair[1])
      grp2 <- as.character(pair[2])
      
      # Use new naming without the "PostHoc_" prefix
      fc_col_name <- paste0("FC_", grp1, "_vs_", grp2)
      log2fc_col_name <- paste0("Log2FC_", grp1, "_vs_", grp2)
      
      # Only compute if not already present
      if(!(fc_col_name %in% colnames(stat_results))) {
        # Get indices for each group
        grp1_idx <- which(groups == grp1)
        grp2_idx <- which(groups == grp2)
        
        if (length(grp1_idx) > 0 && length(grp2_idx) > 0) {
          cols1 <- values$group_column_indices[[grp1_idx]]
          cols2 <- values$group_column_indices[[grp2_idx]]
          
          # Compute means across each group (row-wise)
          mean1 <- rowMeans(values$normalized_data[, cols1, drop = FALSE], na.rm = TRUE)
          mean2 <- rowMeans(values$normalized_data[, cols2, drop = FALSE], na.rm = TRUE)
          
          # Compute fold change and log2 fold change
          # When data is log-scale: log2_fc = mean2 - mean1 (subtraction in log scale)
          # When data is NOT log-scale: log2_fc = log2(mean2 / mean1) (division then log)
          if (is_data_log_scale()) {
            # Data is already in log scale, so fold change is just subtraction
            log2_fc <- mean2 - mean1
            fc <- 2^log2_fc  # Convert back to linear scale for display if needed
          } else {
            # Data is in linear scale, calculate normal fold change
            fc <- mean2 / mean1
            log2_fc <- log2(fc)
          }
          log2_fc[is.infinite(log2_fc)] <- NA
          
          # Add new columns with the new naming convention
          stat_results[[fc_col_name]] <- fc
          stat_results[[log2fc_col_name]] <- log2_fc
        }
      }
    }
    return(stat_results)
  }
  
  get_foldchange_column <- function(comparison_name) {
    # lmROTS/lmeROTS variable-style comparison (no " vs "): use _Coef as effect size
    if (!grepl(" vs ", comparison_name, fixed = TRUE)) {
      sr <- values$stat_results
      if (!is.null(sr)) {
        ccol <- paste0(comparison_name, "_Coef")
        if (ccol %in% colnames(sr)) return(ccol)
      }
      return(NULL)
    }
    # Extract group names from comparison name
    groups <- unlist(strsplit(comparison_name, " vs "))
    if(length(groups) != 2) {
      message("Invalid comparison name format: ", comparison_name)
      return(NULL)
    }
    
    # Create alternative comparison name (reversed order)
    comparison_alt <- paste(groups[2], "vs", groups[1])
    comparison_name_us <- gsub(" vs ", "_vs_", comparison_name, fixed = TRUE)
    comparison_alt_us <- gsub(" vs ", "_vs_", comparison_alt, fixed = TRUE)
    
    # For direct lookups, try all these naming patterns in order of preference
    direct_patterns <- c(
      paste0(comparison_name, "_Log2FC"),
      paste0(comparison_alt, "_Log2FC"),
      paste0(comparison_name, "_Bootstrap_Log2FC"),
      paste0(comparison_alt, "_Bootstrap_Log2FC"),
      paste0("PostHoc_", comparison_name, "_Log2FC"),
      paste0("PostHoc_", comparison_alt, "_Log2FC"),
      paste0("Log2FC_", comparison_name_us),
      paste0("Log2FC_", comparison_alt_us),
      paste0(comparison_name, "_FoldChange"),
      paste0(comparison_alt, "_FoldChange")
    )
    
    # Check each direct pattern
    for(pattern in direct_patterns) {
      if(!is.null(values$stat_results) && pattern %in% colnames(values$stat_results)) {
        if(grepl(comparison_alt, pattern, fixed=TRUE) || grepl(comparison_alt_us, pattern, fixed=TRUE)) {
          message("Found reversed fold change column: ", pattern, " (will negate values)")
          # Important: we're returning the column name with a special marker to indicate it's reversed
          return(paste0("REVERSED:", pattern))
        } else {
          message("Found fold change column: ", pattern)
          return(pattern)
        }
      }
    }
    
    # Check any column containing "Log2FC" and both group names in any order
    if(!is.null(values$stat_results)) {
      fc_cols <- grep("Log2FC|logFC", colnames(values$stat_results), value = TRUE)
      for(col in fc_cols) {
        # Check if column contains both group names in any order
        if(all(sapply(groups, function(g) grepl(g, col, fixed = TRUE)))) {
          message("Found column containing both group names: ", col)
          
          # Check if the order is reversed
          if(grepl(paste0(groups[2], ".*", groups[1]), col)) {
            return(paste0("REVERSED:", col))
          } else {
            return(col)
          }
        }
      }
      
      # Also try fold change columns
      fc_cols <- grep("FoldChange|fold.change", colnames(values$stat_results), value = TRUE, ignore.case = TRUE)
      for(col in fc_cols) {
        if(all(sapply(groups, function(g) grepl(g, col, fixed = TRUE)))) {
          message("Found fold change column containing both group names: ", col)
          
          # Check if the order is reversed
          if(grepl(paste0(groups[2], ".*", groups[1]), col)) {
            return(paste0("REVERSED:", col))
          } else {
            return(col)
          }
        }
      }
    }
    # Return NULL if no fold change column is found (do NOT calculate on the fly)
    message("No existing fold change column found for ", comparison_name)
    return(NULL)
  }
  
  # Post-hoc test functions
  perform_tukey_test <- function(values, groups) {
    tryCatch({
      # Convert to proper format for TukeyHSD
      df <- data.frame(value = values, group = factor(groups))
      
      # Try agricolae HSD.test first
      if (requireNamespace("agricolae", quietly = TRUE)) {
        aov_result <- aov(value ~ group, data = df)
        hsd_result <- agricolae::HSD.test(aov_result, "group")
        
        if (!is.null(hsd_result$comparison) && nrow(hsd_result$comparison) > 0) {
          # Extract pairwise comparisons and p-values
          comparison_names <- paste0(hsd_result$comparison$trt1, "_vs_", hsd_result$comparison$trt2)
          p_values <- hsd_result$comparison$pvalue
          
          return(list(
            p_values = p_values,
            comparison_names = comparison_names
          ))
        }
      }
      
      # Fallback to base R TukeyHSD if agricolae fails
      aov_result <- aov(value ~ group, data = df)
      tukey_result <- TukeyHSD(aov_result)
      
      if (!is.null(tukey_result$group)) {
        p_values <- tukey_result$group[, "p adj"]
        comparison_names <- gsub("-", "_vs_", names(p_values))
        
        return(list(
          p_values = as.numeric(p_values),
          comparison_names = comparison_names
        ))
      }
      
      return(NULL)
    }, error = function(e) {
      message("Error in Tukey test: ", e$message)
      return(NULL)
    })
  }
  
  perform_dunnett_test <- function(values, groups) {
    tryCatch({
      # Convert groups to factor and determine control group (first level)
      groups_factor <- factor(groups)
      control_group <- levels(groups_factor)[1]
      
      # Try using multcomp package for Dunnett's test
      if (requireNamespace("multcomp", quietly = TRUE)) {
        df <- data.frame(value = values, group = groups_factor)
        aov_result <- aov(value ~ group, data = df)
        
        # Create contrast matrix for Dunnett's test (all groups vs control)
        dunnett_contrasts <- multcomp::glht(aov_result, linfct = multcomp::mcp(group = "Dunnett"))
        dunnett_summary <- summary(dunnett_contrasts)
        
        if (!is.null(dunnett_summary$test$pvalues)) {
          # Extract comparison names and p-values
          comparison_names <- names(dunnett_summary$test$coefficients)
          comparison_names <- gsub(" - ", "_vs_", comparison_names)
          p_values <- dunnett_summary$test$pvalues
          
          return(list(
            p_values = as.numeric(p_values),
            comparison_names = comparison_names
          ))
        }
      }
      
      # Fallback: Use agricolae for Dunnett's test
      if (requireNamespace("agricolae", quietly = TRUE)) {
        df <- data.frame(value = values, group = groups_factor)
        aov_result <- aov(value ~ group, data = df)
        dunnett_result <- agricolae::dunnett.test(aov_result, "group", alpha = 0.05)
        
        if (!is.null(dunnett_result$comparison) && nrow(dunnett_result$comparison) > 0) {
          comparison_names <- paste0(dunnett_result$comparison$trt1, "_vs_", dunnett_result$comparison$trt2)
          p_values <- dunnett_result$comparison$pvalue
          
          return(list(
            p_values = p_values,
            comparison_names = comparison_names
          ))
        }
      }
      
      return(NULL)
    }, error = function(e) {
      message("Error in Dunnett's test: ", e$message)
      return(NULL)
    })
  }
  
  perform_scheffe_test <- function(values, groups) {
    tryCatch({
      df <- data.frame(value = values, group = factor(groups))
      
      # Try agricolae scheffe.test first
      if (requireNamespace("agricolae", quietly = TRUE)) {
        aov_result <- aov(value ~ group, data = df)
        scheffe_result <- agricolae::scheffe.test(aov_result, "group")
        
        if (!is.null(scheffe_result$comparison) && nrow(scheffe_result$comparison) > 0) {
          comparison_names <- paste0(scheffe_result$comparison$trt1, "_vs_", scheffe_result$comparison$trt2)
          p_values <- scheffe_result$comparison$pvalue
          
          return(list(
            p_values = p_values,
            comparison_names = comparison_names
          ))
        }
      }
      
      # Manual fallback: Perform Scheff  correction on pairwise t-tests
      group_levels <- levels(factor(groups))
      n_groups <- length(group_levels)
      
      if (n_groups < 2) return(NULL)
      
      # Get all pairwise combinations
      pairs <- combn(group_levels, 2, simplify = FALSE)
      p_values <- numeric(length(pairs))
      comparison_names <- character(length(pairs))
      
      # Run ANOVA to get MSE and degrees of freedom
      aov_result <- aov(value ~ group, data = df)
      anova_summary <- summary(aov_result)
      mse <- anova_summary[[1]]["Residuals", "Mean Sq"]
      df_error <- anova_summary[[1]]["Residuals", "Df"]
      
      for (i in 1:length(pairs)) {
        group1 <- pairs[[i]][1]
        group2 <- pairs[[i]][2]
        
        group1_data <- values[groups == group1]
        group2_data <- values[groups == group2]
        
        if (length(group1_data) > 0 && length(group2_data) > 0) {
          # Perform t-test
          t_result <- t.test(group1_data, group2_data, var.equal = TRUE)
          
          # Apply Scheff  correction
          # Scheff  critical value = sqrt((k-1) * F_critical)
          f_critical <- qf(0.95, n_groups - 1, df_error)
          scheffe_critical <- sqrt((n_groups - 1) * f_critical)
          
          # Convert t-statistic to Scheff -adjusted p-value
          t_stat <- abs(t_result$statistic)
          scheffe_p <- 2 * (1 - pt(t_stat / scheffe_critical, df_error))
          
          p_values[i] <- min(scheffe_p, 1.0)  # Ensure p-value doesn't exceed 1
          comparison_names[i] <- paste0(group1, "_vs_", group2)
        } else {
          p_values[i] <- NA
          comparison_names[i] <- paste0(group1, "_vs_", group2)
        }
      }
      
      # Remove NA values
      valid_indices <- !is.na(p_values)
      if (any(valid_indices)) {
        return(list(
          p_values = p_values[valid_indices],
          comparison_names = comparison_names[valid_indices]
        ))
      }
      
      return(NULL)
    }, error = function(e) {
      message("Error in Scheff  test: ", e$message)
      return(NULL)
    })
  }
  
  perform_games_howell_test <- function(values, groups) {
    tryCatch({
      # Games-Howell test for unequal variances
      if (requireNamespace("rstatix", quietly = TRUE)) {
        df <- data.frame(value = values, group = factor(groups))
        gh_result <- rstatix::games_howell_test(df, value ~ group)
        
        if (!is.null(gh_result) && nrow(gh_result) > 0) {
          comparison_names <- paste0(gh_result$group1, "_vs_", gh_result$group2)
          p_values <- gh_result$p.adj
          
          return(list(
            p_values = p_values,
            comparison_names = comparison_names
          ))
        }
      }
      
      # Manual Games-Howell implementation as last resort
      group_levels <- levels(factor(groups))
      n_groups <- length(group_levels)
      
      if (n_groups < 2) return(NULL)
      
      pairs <- combn(group_levels, 2, simplify = FALSE)
      p_values <- numeric(length(pairs))
      comparison_names <- character(length(pairs))
      
      for (i in 1:length(pairs)) {
        group1 <- pairs[[i]][1]
        group2 <- pairs[[i]][2]
        
        group1_data <- values[groups == group1]
        group2_data <- values[groups == group2]
        
        if (length(group1_data) > 1 && length(group2_data) > 1) {
          # Calculate means, variances, and sample sizes
          mean1 <- mean(group1_data, na.rm = TRUE)
          mean2 <- mean(group2_data, na.rm = TRUE)
          var1 <- var(group1_data, na.rm = TRUE)
          var2 <- var(group2_data, na.rm = TRUE)
          n1 <- length(group1_data)
          n2 <- length(group2_data)
          
          # Games-Howell test statistic
          se <- sqrt((var1/n1) + (var2/n2))
          t_stat <- abs(mean1 - mean2) / se
          
          # Welch-Satterthwaite degrees of freedom
          df <- ((var1/n1) + (var2/n2))^2 / ((var1/n1)^2/(n1-1) + (var2/n2)^2/(n2-1))
          
          # Calculate p-value with Tukey adjustment
          q_stat <- t_stat * sqrt(2)  # Convert to studentized range statistic
          p_val <- 1 - ptukey(q_stat, n_groups, df)
          
          p_values[i] <- min(p_val, 1.0)
          comparison_names[i] <- paste0(group1, "_vs_", group2)
        } else {
          p_values[i] <- NA
          comparison_names[i] <- paste0(group1, "_vs_", group2)
        }
      }
      
      # Remove NA values
      valid_indices <- !is.na(p_values)
      if (any(valid_indices)) {
        return(list(
          p_values = p_values[valid_indices],
          comparison_names = comparison_names[valid_indices]
        ))
      }
      
      return(NULL)
    }, error = function(e) {
      message("Error in Games-Howell test: ", e$message)
      return(NULL)
    })
  }
  
  # Observer to update batch column dropdown when data file is uploaded
  # This runs BEFORE processing to populate the batch column immediately
  observeEvent(current_data_file(), {
    req(current_data_file())

    # Reset metadata on every new upload to avoid stale state
    values$metadata <- NULL
    values$metadata_bio_group_col <- NULL
    values$metadata_exp_group_col <- NULL
    
    tryCatch({
      # Read the Excel file to check for Sheet 2 metadata
      if (!grepl("\\.csv$", tolower(current_data_file()$name))) {
        sheet_names <- readxl::excel_sheets(current_data_file()$datapath)
        if (length(sheet_names) >= 2) {
          # Try to read the second sheet as metadata
          metadata_sheet <- readxl::read_excel(current_data_file()$datapath, sheet = 2, .name_repair = "minimal")

          # Store it immediately so downstream UI (lmROTS/lmeROTS) can use it
          values$metadata <- as.data.frame(metadata_sheet)
          
          # Check if it looks like metadata
          metadata_cols <- tolower(colnames(metadata_sheet))
          if (any(grepl("sample", metadata_cols)) &&
              (any(grepl("biological.*group|bio.*group", metadata_cols)) ||
               any(grepl("experimental.*group|exp.*group", metadata_cols)))) {

            # Store detected group column names for later use
            bio_idx <- find_group_column(colnames(values$metadata), "biological")
            exp_idx <- find_group_column(colnames(values$metadata), "experimental")
            if (!is.na(bio_idx)) values$metadata_bio_group_col <- colnames(values$metadata)[bio_idx]
            if (!is.na(exp_idx)) values$metadata_exp_group_col <- colnames(values$metadata)[exp_idx]
            
            # Get batch column options
            meta_columns <- colnames(metadata_sheet)
            exclude_patterns <- c("sampleid", "sample_id", "sample", "group", "condition", "treatment", "biological", "experimental")
            exclude_mask <- sapply(tolower(meta_columns), function(col) {
              any(sapply(exclude_patterns, function(pattern) grepl(pattern, col)))
            })
            batch_column_options <- meta_columns[!exclude_mask]
            
            # If no options left after filtering, show all columns except SampleID
            if (length(batch_column_options) == 0) {
              batch_column_options <- meta_columns[tolower(meta_columns) != "sampleid"]
            }
            
            # Update batch_column dropdown immediately
            if (length(batch_column_options) > 0) {
              updateSelectInput(session, "batch_column",
                                choices = batch_column_options,
                                selected = if("batch" %in% tolower(batch_column_options))
                                  batch_column_options[grep("batch", tolower(batch_column_options))[1]] else batch_column_options[1])
            }
          } else {
            # Metadata sheet exists but doesn't match expected patterns; keep it available anyway.
            showNotification(
              paste("Loaded sheet 2 ('", sheet_names[2], "') as metadata, but required columns were not auto-detected.",
                    "If needed, adjust column names (e.g., Sample, Biological_Group)."),
              type = "warning", duration = 6
            )
          }
        }
      }
    }, error = function(e) {
      # Silently fail - this is just for early population of batch column
      message("Note: Could not pre-populate batch column from Sheet 2: ", e$message)
    })
  })
  
  # Process data with priority handling
  observeEvent(input$processBtn, {
    # Detect internal dual-analysis re-run to avoid state resets
    is_dual_rerun <- isTRUE(values$has_dual_grouping) &&
      isTRUE(values$dual_analysis_in_progress) &&
      !is.null(values$dual_analysis_current_level)
    
    # Clear the data tab active flag to allow normal operations during processing
    values$data_tab_active <- FALSE
    
    # Reset imputation statistics when processing new data
    values$imputation_stats <- NULL
    
    # Reset ROC/PR analysis results when processing new data
    values$roc_results <- NULL
    values$roc_data <- NULL
    values$roc_plot_obj <- NULL
    
    # Hide the Review Pairwise Order button until analysis is complete
    shinyjs::hide("reviewPairwiseOrderBtn")
    values$pr_plot_obj <- NULL
    values$combined_plot_obj <- NULL
    
    if (is.null(current_data_file())) {
      showNotification("Error: Please upload a data input Excel file before proceeding.", type = "error", duration = 10)
      return()
    }
    req(current_data_file())

    if (!is_dual_rerun) {
      # Always reset caches before each processing run to avoid stale state
      clear_analysis_caches("process button run")
      
      # CRITICAL: Reset ALL dual analysis tracking state to ensure clean slate
      # This prevents state contamination when switching between simple/complex experiments
      values$stat_results <- NULL
      values$biological_stat_results <- NULL
      values$experimental_stat_results <- NULL
      values$dual_analysis_in_progress <- FALSE
      values$dual_analysis_current_level <- NULL
      values$dual_analysis_trigger_rerun <- NULL
      values$dual_analysis_cache <- list()
      values$dual_analysis_cache_signature <- NULL
      
      # Reset dual grouping flag - will be properly set during processing based on data
      # Don't reset has_dual_grouping here as it will be determined by the mapping
      # But DO reset the active level to ensure consistent starting point
      values$active_grouping_level <- "biological"
      
      # Ensure pairwise combinations are explicitly defined for every run
      pairs_to_use <- values$selected_pairwise_for_analysis
      if (is.null(pairs_to_use) || (is.data.frame(pairs_to_use) && nrow(pairs_to_use) == 0)) {
        pairs_to_use <- get_all_possible_pairwise_combinations()
        values$selected_pairwise_for_analysis <- pairs_to_use
      }
      values$current_pairwise_combinations <- pairs_to_use
    } else {
      message("Dual analysis re-run detected; preserving dual grouping state and pairwise selections")
    }
    
    # Do NOT reset mapping here. Mapping is handled on file upload or via the Review button.
    
    # Check if deduplication was already applied - use that data instead of re-reading file
    # This ensures duplicates resolved in the modal are respected during processing
    if (isTRUE(values$deduplication_applied) && !is.null(values$original_unfiltered_data)) {
      # Use the already-deduplicated data
      df <- values$original_unfiltered_data
      
      # If it has a Feature column from earlier processing, restructure it
      if ("Feature" %in% colnames(df) && colnames(df)[1] == "Feature") {
        # Data is already in expected format
        message("Using deduplicated data from previous processing")
      }
    } else {
      # Read Excel/CSV file with custom name repair
      if (grepl("\\.csv$", tolower(current_data_file()$name))) {
        df <- read.csv(current_data_file()$datapath, check.names = FALSE, stringsAsFactors = FALSE)
      } else {
        df <- read_excel(current_data_file()$datapath, .name_repair = "minimal")
      
      # Check for a second sheet that might contain metadata
      tryCatch({
        sheet_names <- readxl::excel_sheets(current_data_file()$datapath)
        if (length(sheet_names) >= 2) {
          # Try to read the second sheet as metadata
          metadata_sheet <- readxl::read_excel(current_data_file()$datapath, sheet = 2, .name_repair = "minimal")

          # Always store Sheet 2 so lmROTS/lmeROTS and other UI can use it.
          values$metadata <- as.data.frame(metadata_sheet)
          showNotification(
            paste("Loaded sheet 2 as metadata:", sheet_names[2], "(", nrow(metadata_sheet), "rows )"),
            type = "message", duration = 5
          )

          # Try to detect group columns (best-effort)
          bio_idx <- find_group_column(colnames(values$metadata), "biological")
          exp_idx <- find_group_column(colnames(values$metadata), "experimental")
          if (!is.na(bio_idx)) values$metadata_bio_group_col <- colnames(values$metadata)[bio_idx]
          if (!is.na(exp_idx)) values$metadata_exp_group_col <- colnames(values$metadata)[exp_idx]

          # Update batch_column dropdown with metadata columns
          meta_columns <- colnames(values$metadata)

          # Exclude SampleID and group-related columns from batch_column options
          exclude_patterns <- c("sampleid", "sample_id", "sample", "group", "condition", "treatment", "biological", "experimental")
          exclude_mask <- sapply(tolower(meta_columns), function(col) {
            any(sapply(exclude_patterns, function(pattern) grepl(pattern, col)))
          })
          batch_column_options <- meta_columns[!exclude_mask]

          # If no options left after filtering, show all columns except SampleID
          if (length(batch_column_options) == 0) {
            batch_column_options <- meta_columns[tolower(meta_columns) != "sampleid"]
          }

          # Update batch_column dropdown
          updateSelectInput(session, "batch_column",
                            choices = batch_column_options,
                            selected = if("batch" %in% tolower(batch_column_options))
                              batch_column_options[grep("batch", tolower(batch_column_options))[1]] else if(length(batch_column_options) > 0) batch_column_options[1] else NULL)
        }
      }, error = function(e) {
        # Silently ignore if second sheet can't be read
      })
      }  # Close the else block for Excel reading
    }  # Close the outer else block for deduplication check
    
    # IMPORTANT: Save the ORIGINAL df before ANY column exclusion happens
    # This ensures we can always access Gene/Accession ID columns even if they're excluded from analysis
    df_original_before_exclusion <- df
    
    # NEW: Remove ignored columns if specified
    if (!is.null(values$ignore_columns) && length(values$ignore_columns) > 0) {
      # Get column indices to keep (excluding ignored ones)
      all_cols <- seq_len(ncol(df))
      cols_to_keep <- setdiff(all_cols, values$ignore_columns)
      
      if (length(cols_to_keep) >= 2) {  # Need at least feature column + 1 data column
        original_ncol <- ncol(df)
        df <- df[, cols_to_keep, drop = FALSE]
        
        # Adjust feature_name_column and accession_id_column indices after exclusion
        # Count how many ignored columns come before each index
        if (!is.null(values$feature_name_column)) {
          ignored_before_feature <- sum(values$ignore_columns < values$feature_name_column)
          values$feature_name_column_adjusted <- values$feature_name_column - ignored_before_feature
        }
        if (!is.null(values$accession_id_column) && 
            (is.numeric(values$accession_id_column) && all(values$accession_id_column > 0)) &&
            all(values$accession_id_column <= ncol(df))) {
          # Handle multiple accession ID columns - adjust each one separately
          ignored_before_accession <- sapply(values$accession_id_column, 
                                             function(col) sum(values$ignore_columns < col))
          values$accession_id_column_adjusted <- as.integer(values$accession_id_column - ignored_before_accession)
        } else {
          values$accession_id_column_adjusted <- values$accession_id_column
        }
        
        showNotification(paste("Excluded", length(values$ignore_columns),
                               "column(s) from analysis -", ncol(df), "columns remaining"),
                         type = "message", duration = 4)
      } else {
        showNotification("Cannot ignore columns: would leave insufficient data columns",
                         type = "warning", duration = 5)
        values$feature_name_column_adjusted <- values$feature_name_column
        values$accession_id_column_adjusted <- values$accession_id_column
      }
    } else {
      # No columns ignored, use original indices
      values$feature_name_column_adjusted <- values$feature_name_column
      values$accession_id_column_adjusted <- values$accession_id_column
    }
    
    # NEW: Reorder dataframe to move feature column to position 1 if it's not already there
    if (!is.null(values$feature_name_column_adjusted) && values$feature_name_column_adjusted > 1) {
      feature_col_idx <- values$feature_name_column_adjusted
      
      # Build new column order: feature column first, then all others
      new_col_order <- c(feature_col_idx, setdiff(seq_len(ncol(df)), feature_col_idx))
      
      # Reorder dataframe
      df <- df[, new_col_order, drop = FALSE]
      
      # Reorder accession column indices if they exist (handle multiple columns)
      if (!is.null(values$accession_id_column_adjusted) && length(values$accession_id_column_adjusted) > 0) {
        # Handle both single and multiple accession ID columns
        old_positions <- values$accession_id_column_adjusted
        new_positions <- sapply(old_positions, function(pos) which(new_col_order == pos))
        # Only keep those that exist in the reordered dataframe
        new_positions <- new_positions[!is.na(new_positions)]
        if (length(new_positions) > 0) {
          values$accession_id_column_adjusted <- as.integer(new_positions)
        } else {
          values$accession_id_column_adjusted <- NULL
        }
      }
      # Update feature column to position 1
      values$feature_name_column_adjusted <- 1
    }
    
    # Optional: handle transposed input (samples in rows, features in columns)
    if (isTRUE(input$data_samples_are_rows)) {
      if (ncol(df) < 2) {
        showNotification("Uploaded file must have at least two columns when 'samples are rows' is enabled.", type = "error", duration = 10)
        return()
      }
      sample_ids <- as.character(df[[1]])
      data_mat  <- as.data.frame(t(df[, -1, drop = FALSE]), check.names = FALSE, stringsAsFactors = FALSE)
      colnames(data_mat) <- sample_ids
      feature_names <- colnames(df)[-1]
      df <- cbind(Feature = feature_names, data_mat)
    }
    
    # NEW: Custom NA values handling (only if checkbox is enabled)
    if (isTRUE(input$enable_custom_na) && !is.null(input$custom_na_values) && nchar(input$custom_na_values) > 0) {
      custom_na_list <- trimws(strsplit(input$custom_na_values, ",")[[1]])
      custom_na_list <- custom_na_list[custom_na_list != ""]  # Remove empty strings
      
      if (length(custom_na_list) > 0 && ncol(df) > 1) {
        data_only <- df[, -1, drop = FALSE]
        for (na_val in custom_na_list) {
          data_only[data_only == na_val] <- NA
        }
        df <- cbind(df[1], data_only)
        showNotification(paste("Converted", length(custom_na_list), "custom NA values:",
                               paste(custom_na_list, collapse = ", ")),
                         type = "message", duration = 5)
      }
    }
    
    # NEW: Clean feature identifiers
    if (isTRUE(input$clean_feature_ids)) {
      original_features <- df[[1]]
      cleaned_features <- gsub(" OS=.*$", "", original_features)  # Remove OS= suffixes
      cleaned_features <- trimws(cleaned_features)  # Trim whitespace
      df[[1]] <- cleaned_features
      
      # Report cleaning stats
      cleaned_count <- sum(original_features != cleaned_features)
      if (cleaned_count > 0) {
        showNotification(paste("Cleaned", cleaned_count, "feature identifiers"),
                         type = "message", duration = 4)
      }
    }
    
    # Custom logic to handle duplicate column names while preserving original numbers
    col_names <- colnames(df)
    if (length(col_names) > 1) {
      # Skip the first column (gene/feature names)
      sample_cols <- col_names[-1]
      
      # Check for duplicates and add numbering only where needed
      fixed_sample_cols <- character(length(sample_cols))
      
      for (i in seq_along(sample_cols)) {
        current_name <- sample_cols[i]
        
        # Count how many times this exact name appears
        same_name_indices <- which(sample_cols == current_name)
        
        if (length(same_name_indices) > 1) {
          # Multiple columns with same name - add sequential numbering
          position_in_group <- which(same_name_indices == i)
          fixed_sample_cols[i] <- paste0(current_name, "_", position_in_group)
        } else {
          # Unique name - keep as is
          fixed_sample_cols[i] <- current_name
        }
      }
      
      # Apply the fixed names
      colnames(df) <- c(col_names[1], fixed_sample_cols)
      
      # Store the corrected sample column names for use throughout the app
      values$corrected_sample_names <- fixed_sample_cols
      
      # CRITICAL: Update mapping_df Sample names to match the renamed columns
      # This ensures the mapping aligns with the actual data column names after renaming
      if (!is.null(values$mapping_df) && nrow(values$mapping_df) > 0) {
        old_sample_names <- sample_cols  # Original names before renaming
        new_sample_names <- fixed_sample_cols  # Names after renaming
        
        # Only update if the mapping_df has the same number of samples as the data columns
        if (nrow(values$mapping_df) == length(new_sample_names)) {
          # Direct positional mapping - each row in mapping_df corresponds to each column
          values$mapping_df$Sample <- new_sample_names
        } else {
          # Try to match by position where possible
          # First, find which old names are in mapping_df
          mapping_old_names <- values$mapping_df$Sample
          for (i in seq_along(old_sample_names)) {
            if (i <= nrow(values$mapping_df) && 
                !is.na(mapping_old_names[i]) && 
                mapping_old_names[i] == old_sample_names[i]) {
              values$mapping_df$Sample[i] <- new_sample_names[i]
            }
          }
        }
      }
    } else {
      # If no duplicates found, still store the original sample column names
      values$corrected_sample_names <- col_names[-1]
    }
    
    # NEW: Treat zeros as NA before any missing-value logic (optional)
    if (isTRUE(input$data_treat_zeros_as_na) && ncol(df) > 1) {
      data_only <- df[, -1, drop = FALSE]
      suppressWarnings({
        data_num <- lapply(data_only, function(x) as.numeric(as.character(x)))
        data_num <- as.data.frame(data_num, check.names = FALSE, stringsAsFactors = FALSE)
      })
      data_num[data_num == 0] <- NA
      df <- cbind(df[1], data_num)
    }
    
    # Automatic numeric data validation (excludes feature names and ID column, handles custom NAs)
    if (ncol(df) > 1) {
      # Determine which columns to validate (exclude feature names and accession ID column)
      cols_to_validate <- seq_len(ncol(df))[-1]  # Exclude feature names column (column 1)
      
      # Also exclude accession ID column if specified
      if (!is.null(values$accession_id_column) && 
          (is.numeric(values$accession_id_column) && all(values$accession_id_column > 0)) &&
          all(values$accession_id_column <= ncol(df))) {
        cols_to_validate <- setdiff(cols_to_validate, values$accession_id_column)
      }
      
      if (length(cols_to_validate) == 0) {
        # No columns left to validate
      } else {
        data_only <- df[, cols_to_validate, drop = FALSE]
        validation_issues <- character(0)
        
        # Get list of custom NA values for proper exclusion (only if checkbox is enabled)
        custom_na_list <- character(0)
        if (isTRUE(input$enable_custom_na) && !is.null(input$custom_na_values) && nchar(input$custom_na_values) > 0) {
          custom_na_list <- trimws(strsplit(input$custom_na_values, ",")[[1]])
          custom_na_list <- custom_na_list[custom_na_list != ""]
        }
        
        for (col_idx in seq_len(ncol(data_only))) {
          col_name <- colnames(data_only)[col_idx]
          col_data <- data_only[[col_idx]]
          
          # Try numeric conversion
          suppressWarnings({
            numeric_data <- as.numeric(as.character(col_data))
          })
          
          # Identify problematic values (excluding legitimate NAs and custom NA values)
          original_nas <- is.na(col_data)
          conversion_nas <- is.na(numeric_data) & !original_nas
          
          if (sum(conversion_nas) > 0) {
            # Get the actual problematic values
            problematic_values <- col_data[conversion_nas]
            problematic_values <- problematic_values[!is.na(problematic_values)]
            
            # Exclude custom NA values and common NA representations from error reporting
            common_na_values <- c("", " ", "NA", "N/A", "na", "n/a", "#N/A", "NULL", "null")
            all_na_values <- c(custom_na_list, common_na_values)
            
            # Filter out values that should be treated as NA
            actual_errors <- problematic_values[!problematic_values %in% all_na_values]
            
            # Only report if there are actual non-NA, non-numeric values
            if (length(actual_errors) > 0) {
              validation_issues <- c(validation_issues,
                                     paste0(col_name, ": ", length(actual_errors), " invalid values (",
                                            paste(head(actual_errors, 3), collapse = ", "),
                                            if(length(actual_errors) > 3) "..." else "", ")"))
            }
          }
        }
        
        # Only show notification if there are actual validation errors
        if (length(validation_issues) > 0) {
          showNotification(HTML(paste("Data validation failed - non-numeric values found:<br>",
                                      paste(validation_issues, collapse = "<br>"))),
                           type = "error", duration = 15)
        }
      }
    }
    
    # Store raw data
    values$raw_data <- df
    
    # Store the missing value strategy for later use
    values$missing_value_strategy <- input$missing_value_strategy
    
    # Extract molecule names (first column)
    values$molecules <- df[[1]]
    
    # Extract data (all columns except the first and accession column if present)
    cols_to_exclude <- 1  # Always exclude feature names column

    # Use adjusted accession indices (post ignore-column removal) to avoid off-by-one drops
    accession_cols_for_exclusion <- values$accession_id_column_adjusted
    if (is.null(accession_cols_for_exclusion)) {
      accession_cols_for_exclusion <- values$accession_id_column
    }

    if (!is.null(accession_cols_for_exclusion) && 
        (is.numeric(accession_cols_for_exclusion) && all(accession_cols_for_exclusion > 0)) &&
        all(accession_cols_for_exclusion <= ncol(df))) {
      cols_to_exclude <- c(cols_to_exclude, accession_cols_for_exclusion)
    }
    data <- df[, -cols_to_exclude, drop = FALSE]
    
    # Store original unfiltered data for Raw Data tab and missing value analysis
    # Only overwrite if deduplication was NOT already applied (preserve deduplicated data)
    if (!isTRUE(values$deduplication_applied)) {
      values$original_unfiltered_data <- data.frame(
        Feature = values$molecules,
        data,
        check.names = FALSE,
        stringsAsFactors = FALSE
      )
    }
    
    data_filtered <- data
    molecules_filtered <- values$molecules

    # IMPORTANT: Do NOT extract ID columns yet - wait until AFTER row filtering
    # Store the ORIGINAL df (before column exclusion) for later extraction after rows are filtered
    # We saved this as df_original_before_exclusion at the start of data processing
    id_candidates <- NULL
    
    # First, remove rows that are completely missing (all NAs)
    all_na_rows <- rowSums(!is.na(data_filtered)) == 0
    if (any(all_na_rows)) {
      # Store info about removed features with all NAs
      values$removed_all_na_features <- molecules_filtered[all_na_rows]
      values$all_na_removal_count <- sum(all_na_rows)
      
      # Remove rows with all NAs from the data
      data_filtered <- data_filtered[!all_na_rows, ]
      molecules_filtered <- molecules_filtered[!all_na_rows]
      if (!is.null(id_candidates)) {
        id_candidates <- id_candidates[!all_na_rows, , drop = FALSE]
      }
      
      # Notification about removed rows
      showNotification(paste(sum(all_na_rows), "rows with all missing values (100% NAs) were removed during processing."),
                       type = "warning", duration = 7)
    }
    
    # Silent check: Remove rows with empty feature names (empty strings)
    empty_feature_rows <- is.na(molecules_filtered) | 
                          trimws(as.character(molecules_filtered)) == "" |
                          is.null(molecules_filtered)
    if (any(empty_feature_rows)) {
      # Store info about removed empty features
      empty_count <- sum(empty_feature_rows)
      values$removed_empty_features <- molecules_filtered[empty_feature_rows]
      values$empty_feature_removal_count <- empty_count
      
      # Remove rows with empty feature names
      data_filtered <- data_filtered[!empty_feature_rows, ]
      molecules_filtered <- molecules_filtered[!empty_feature_rows]
      if (!is.null(id_candidates)) {
        id_candidates <- id_candidates[!empty_feature_rows, , drop = FALSE]
      }
      
      # Notify user about empty feature removal
      showNotification(paste(empty_count, "row(s) with empty feature names were removed during validation."),
                       type = "warning", duration = 7)
    }
    
    # EARLY GROUP MAPPING GATING: require confirmation for unseen datasets before any processing
    {
      header_groups <- colnames(df)[-1]
      cleaned_sample_cols <- stringr::str_replace(header_groups, "\\.\\.\\..*$", "")
      # Stable signature based on cleaned header names - only set if not already set
      if (is.null(values$current_dataset_sig)) {
        values$current_dataset_sig <- tryCatch({ digest::digest(cleaned_sample_cols, algo = "xxhash64") },
                                               error = function(e) digest::digest(paste(Sys.time(), runif(1)), algo = "xxhash64"))
      }
      seen_map <- values$seen_datasets[[values$current_dataset_sig]]
      if (is.null(seen_map)) {
        # Check if mapping was already confirmed in this session (reprocessing same dataset)
        if (isTruthy(values$mapping_confirmed) && !is.null(values$final_biological_groups)) {
          # Silently use the previously confirmed mapping
          # No action needed - mapping is already stored in values$final_biological_groups and values$final_experimental_groups
        } else {
          # First time seeing this dataset - require confirmation
          det_early <- detect_hierarchical_groups(cleaned_sample_cols)
          values$mapping_df <- data.frame(
            Sample = cleaned_sample_cols,
            Biological_Group = det_early$biological,
            Experimental_Group = det_early$experimental,
            stringsAsFactors = FALSE
          )
          values$auto_mapping <- det_early
          values$final_biological_groups <- NULL
          values$final_experimental_groups <- NULL
          values$mapping_confirmed <- FALSE
          showNotification("Mapping not confirmed. Please use 'Review Group Mapping'.", type = "error", duration = 8)
          return(invisible(NULL))
        }
      } else {
        # Use stored mapping from previous processing
        values$final_biological_groups <- seen_map$biological
        values$final_experimental_groups <- seen_map$experimental
        values$mapping_confirmed <- TRUE
      }
    }
    
    # Align columns with confirmed mapping to exclude ignored metadata from downstream stats
    if (!is.null(values$mapping_df) && nrow(values$mapping_df) > 0) {
      # Filter mapping_df to only include rows with valid Biological_Group assignments
      valid_mapping_rows <- !is.na(values$mapping_df$Biological_Group) & 
                           trimws(as.character(values$mapping_df$Biological_Group)) != ""
      if (any(valid_mapping_rows, na.rm = TRUE)) {
        values$mapping_df <- values$mapping_df[valid_mapping_rows, , drop = FALSE]
      } else {
        # No valid mappings, skip alignment
        values$mapping_df <- NULL
      }
    }
    
    if (!is.null(values$mapping_df) && nrow(values$mapping_df) > 0) {
      mapping_samples <- values$mapping_df$Sample
      current_samples <- colnames(data_filtered)
      matched_idx <- match(mapping_samples, current_samples)
      valid_mask <- !is.na(matched_idx)
      if (any(!valid_mask)) {
        missing_samples <- mapping_samples[!valid_mask]
        showNotification(
          paste("Skipping mapped columns not present in data:", paste(head(missing_samples, 5), collapse = ", "),
                if(length(missing_samples) > 5) paste("... and", length(missing_samples) - 5, "more") else ""),
          type = "warning", duration = 6
        )
      }
      matched_idx <- matched_idx[valid_mask]
      if (length(matched_idx) == 0) {
        # Enhanced error reporting for debugging
        cat("DEBUG: No mapped samples remained after exclusions\n")
        cat("DEBUG: Mapping samples:", paste(head(mapping_samples, 10), collapse = ", "), "\n")
        cat("DEBUG: Current data columns:", paste(head(current_samples, 10), collapse = ", "), "\n")
        cat("DEBUG: Total mapping samples:", length(mapping_samples), "\n")
        cat("DEBUG: Total data columns:", length(current_samples), "\n")

        # Try to fall back to auto-detection if mapping completely fails
        showNotification("No mapped sample columns remained after exclusions. Attempting to use auto-detected groups instead.", type = "warning", duration = 8)

        # Clear the failed mapping and trigger auto-detection
        values$mapping_df <- NULL
        values$final_biological_groups <- NULL
        values$final_experimental_groups <- NULL
        values$mapping_confirmed <- FALSE

        # Re-run auto-detection
        header_groups <- colnames(data_filtered)
        cleaned_sample_cols <- stringr::str_replace(header_groups, "\\.\\.\\..*$", "")
        det_fallback <- detect_hierarchical_groups(cleaned_sample_cols)
        values$auto_mapping <- det_fallback
        values$mapping_df <- data.frame(
          Sample = cleaned_sample_cols,
          Biological_Group = det_fallback$biological,
          Experimental_Group = det_fallback$experimental,
          stringsAsFactors = FALSE
        )
        values$final_biological_groups <- det_fallback$biological
        values$final_experimental_groups <- det_fallback$experimental
        values$mapping_confirmed <- TRUE

        showNotification("Switched to auto-detected groups. Please review and confirm the mapping if needed.", type = "message", duration = 6)

        # Re-align with auto-detected mapping
        mapping_samples <- values$mapping_df$Sample
        matched_idx <- match(mapping_samples, current_samples)
        valid_mask <- !is.na(matched_idx)
        matched_idx <- matched_idx[valid_mask]

        if (length(matched_idx) == 0) {
          showNotification("Auto-detection also failed. Please check your data format and column names.", type = "error", duration = 10)
          return(invisible(NULL))
        }
      }
      
      # Reorder column-dependent objects to match the filtered dataset
      values$mapping_df <- values$mapping_df[valid_mask, , drop = FALSE]
      data_filtered <- data_filtered[, matched_idx, drop = FALSE]
      
      if (!is.null(values$original_unfiltered_data) && ncol(values$original_unfiltered_data) > 1) {
        keep_cols <- c(1, matched_idx + 1)
        values$original_unfiltered_data <- values$original_unfiltered_data[, keep_cols, drop = FALSE]
      }
      
      df_sample_names <- colnames(df)[-1]
      df_keep_idx <- match(colnames(data_filtered), df_sample_names)
      if (all(!is.na(df_keep_idx))) {
        df <- df[, c(1, df_keep_idx + 1), drop = FALSE]
      }
      
      if (!is.null(values$final_biological_groups) && length(values$final_biological_groups) == length(mapping_samples)) {
        values$final_biological_groups <- values$final_biological_groups[valid_mask]
      }
      if (!is.null(values$final_experimental_groups) && length(values$final_experimental_groups) == length(mapping_samples)) {
        values$final_experimental_groups <- values$final_experimental_groups[valid_mask]
      }
      
      values$corrected_sample_names <- colnames(data_filtered)
    }
    
    # Add additional step to remove rows with =20% missing values within any group
    # Build grouping information (biological) conservatively to avoid confusion
    # IMPORTANT: Use the actual data column names, not the original df column names
    # This ensures group_column_indices correctly map to the filtered data columns
    header_groups <- colnames(data_filtered)
    cleaned_sample_cols <- str_replace(header_groups, "\\.\\.\\..*$", "")
    
    # Determine biological labels to use for grouping (confirmed mapping if available)
    if (!is.null(values$final_biological_groups) && length(values$final_biological_groups) == length(cleaned_sample_cols)) {
      group_names_for_grouping <- values$final_biological_groups
    } else {
      # Use auto-detection locally without committing to app state
      det_local <- detect_hierarchical_groups(cleaned_sample_cols)
      group_names_for_grouping <- det_local$biological
    }
    unique_groups <- unique(group_names_for_grouping)
    
    # Identify columns belonging to each biological group (local to this observer)
    group_column_indices <- lapply(unique_groups, function(g) which(group_names_for_grouping == g))
    
    # Missing value handling logic
    if (input$missing_value_strategy == "remove") {
      # Current threshold-based removal
      threshold <- input$na_threshold / 100
      
      # Check within groups if requested
      if (input$check_within_groups) {
        rows_to_remove <- c()
        for (g in seq_along(group_column_indices)) {
          group_cols <- group_column_indices[[g]]
          if (length(group_cols) > 0) {
            # Calculate percentage of missing values per row within this group
            # Use data_filtered which only contains sample columns (not metadata columns)
            group_missing_percentage <- rowMeans(is.na(data_filtered[, group_cols, drop = FALSE]))
            # Find rows exceeding threshold within this group
            group_rows_to_remove <- which(group_missing_percentage > threshold)
            rows_to_remove <- union(rows_to_remove, group_rows_to_remove)
          }
        }
        
        if (length(rows_to_remove) > 0) {
          # Store info about removed features BEFORE removing them
          values$removed_features <- molecules_filtered[rows_to_remove]
          
          data_filtered <- data_filtered[-rows_to_remove, ]
          molecules_filtered <- molecules_filtered[-rows_to_remove]
          if (!is.null(id_candidates)) {
            id_candidates <- id_candidates[-rows_to_remove, , drop = FALSE]
          }
          
          values$removal_reason <- paste("Missing values >", threshold*100, "% within groups")
          
          # Notification about removed rows
          showNotification(paste(length(rows_to_remove), "rows with >", threshold*100, "% missing values within at least one group were removed."),
                           type = "warning", duration = 7)
        } else {
          # If no rows to remove, keep current data_filtered (already aligned to sample columns only)
          # data_filtered and molecules_filtered are already set correctly
        }
      } else {
        # If not checking within groups, use overall threshold
        # Use data_filtered which only contains sample columns (not metadata columns)
        row_missing_percentage <- rowMeans(is.na(data_filtered))
        rows_to_remove <- which(row_missing_percentage > threshold)
        
        if (length(rows_to_remove) > 0) {
          # Store info about removed features BEFORE removing them
          values$removed_features <- molecules_filtered[rows_to_remove]
          
          data_filtered <- data_filtered[row_missing_percentage <= threshold, ]
          molecules_filtered <- molecules_filtered[row_missing_percentage <= threshold]
          if (!is.null(id_candidates)) {
            id_candidates <- id_candidates[row_missing_percentage <= threshold, , drop = FALSE]
          }
          
          values$removal_reason <- paste("Missing values >", threshold*100, "%")
        }
      }
    } else {
      # Imputation approach
      # First check if pre-filtering is enabled
      if (input$filter_before_impute) {
        # Apply pre-filtering before imputation
        threshold <- input$impute_na_threshold / 100
        
        # Check within groups if requested
        if (input$impute_check_within_groups) {
          rows_to_remove <- c()
          for (g in seq_along(group_column_indices)) {
            group_cols <- group_column_indices[[g]]
            if (length(group_cols) > 0) {
              # Calculate percentage of missing values per row within this group
              group_missing_percentage <- rowMeans(is.na(data_filtered[, group_cols, drop = FALSE]))
              # Find rows exceeding threshold within this group
              group_rows_to_remove <- which(group_missing_percentage > threshold)
              rows_to_remove <- union(rows_to_remove, group_rows_to_remove)
            }
          }
          
          if (length(rows_to_remove) > 0) {
            # Store info about removed features BEFORE removing them
            values$removed_features <- molecules_filtered[rows_to_remove]
            
            data_filtered <- data_filtered[-rows_to_remove, ]
            molecules_filtered <- molecules_filtered[-rows_to_remove]
            if (!is.null(id_candidates)) {
              id_candidates <- id_candidates[-rows_to_remove, , drop = FALSE]
            }
            
            values$removal_reason <- paste("Pre-filtering: Missing values >", threshold*100, "% within groups before imputation")
            
            # Notification about removed rows
            showNotification(paste(length(rows_to_remove), "rows with >", threshold*100, "% missing values within at least one group were removed before imputation."),
                             type = "warning", duration = 7)
          }
        } else {
          # If not checking within groups, use overall threshold
          row_missing_percentage <- rowMeans(is.na(data_filtered))
          rows_to_remove <- which(row_missing_percentage > threshold)
          
          if (length(rows_to_remove) > 0) {
            # Store info about removed features BEFORE removing them
            values$removed_features <- molecules_filtered[rows_to_remove]
            
            data_filtered <- data_filtered[-rows_to_remove, ]
            molecules_filtered <- molecules_filtered[-rows_to_remove]
            if (!is.null(id_candidates)) {
              id_candidates <- id_candidates[-rows_to_remove, , drop = FALSE]
            }
            
            values$removal_reason <- paste("Pre-filtering: Missing values >", threshold*100, "% before imputation")
            
            # Notification about removed rows
            showNotification(paste(length(rows_to_remove), "rows with >", threshold*100, "% missing values were removed before imputation."),
                             type = "warning", duration = 7)
          }
        }
      }
      
      # Create parameters for imputation
      imputation_params <- list()
      if (input$imputation_method == "knn") {
        imputation_params$k <- input$knn_k
      } else if (input$imputation_method == "min") {
        imputation_params$fraction <- input$min_fraction
      } else if (input$imputation_method == "minprob") {
        imputation_params$shift <- input$minprob_shift
        imputation_params$scale <- input$minprob_scale
      }
      
      # Get group information for group-wise imputation
      group_info <- NULL
      if (input$impute_by_group) {
        # Extract group information from column names
        if (length(values$unique_groups) > 0) {
          cleaned_sample_cols <- str_replace(colnames(data_filtered), "\\.\\.\\..*$", "")
          # Extract group names by removing delimiter + number pattern (for grouping logic only)
          group_names_for_grouping <- str_replace(cleaned_sample_cols, "([_\\.\\-])\\d+$", "")
          group_info <- group_names_for_grouping
        }
      }
      
      # Store data before imputation for accurate statistics and comparison
      data_before_imputation <- data_filtered
      values$data_before_imputation <- data_before_imputation
      missing_before_imputation <- sum(is.na(data_before_imputation))
      
      # Perform cached imputation
      data_filtered <- perform_cached_imputation(
        data = data_filtered,
        method = input$imputation_method,
        params = imputation_params,
        by_group = input$impute_by_group,
        group_info = group_info
      )
      
      # Calculate accurate imputation statistics
      missing_after_imputation <- sum(is.na(data_filtered))
      imputed_count <- missing_before_imputation - missing_after_imputation
      
      # Store data after imputation but before normalization for comparison
      values$data_after_imputation <- data_filtered
      
      # Store imputation statistics
      values$imputation_stats <- list(
        method = input$imputation_method,
        imputed_count = imputed_count,
        missing_before = missing_before_imputation,
        missing_after = missing_after_imputation,
        features_imputed = sum(rowSums(is.na(data_before_imputation)) > rowSums(is.na(data_filtered))),
        samples_imputed = sum(colSums(is.na(data_before_imputation)) > colSums(is.na(data_filtered))),
        params = imputation_params
      )
      
      # Log imputation info
      values$imputation_applied <- TRUE
      values$imputation_method <- input$imputation_method
      values$imputation_by_group <- input$impute_by_group
      values$filter_before_impute <- input$filter_before_impute
      if (input$filter_before_impute) {
        values$impute_na_threshold <- input$impute_na_threshold
        values$impute_check_within_groups <- input$impute_check_within_groups
      }
    }
    
    # NOW extract ID columns AFTER all row filtering is complete
    # This ensures id_candidates aligns with the filtered molecules_filtered list
    # Use df_original_before_exclusion which has ALL original columns (even excluded ones)
    cat("DEBUG: Extracting ID columns AFTER row filtering\n")
    cat("  molecules_filtered length:", length(molecules_filtered), "\n")
    cat("  values$accession_id_column (original):", if (is.null(values$accession_id_column)) "NULL" else paste(values$accession_id_column, collapse=", "), "\n")
    cat("  values$accession_id_column_adjusted:", if (is.null(values$accession_id_column_adjusted)) "NULL" else paste(values$accession_id_column_adjusted, collapse=", "), "\n")
    cat("  df_original_before_exclusion dimensions:", nrow(df_original_before_exclusion), "x", ncol(df_original_before_exclusion), "\n")
    cat("  df_original_before_exclusion column names:", paste(colnames(df_original_before_exclusion), collapse=", "), "\n")
    
    # Use original accession_id_column (not adjusted) since we're using the full unmodified df
    id_columns_to_use <- values$accession_id_column
    
    # Debug: Check what's actually in the ID columns
    id_columns_are_empty <- FALSE
    if (!is.null(id_columns_to_use) && length(id_columns_to_use) > 0) {
      total_non_empty <- 0
      for (idx in id_columns_to_use) {
        if (idx <= ncol(df_original_before_exclusion)) {
          col_data <- df_original_before_exclusion[[idx]]
          col_name <- colnames(df_original_before_exclusion)[idx]
          non_na_count <- sum(!is.na(col_data) & col_data != "")
          cat("  Column", idx, " (", col_name, "):", non_na_count, "non-empty values out of", nrow(df_original_before_exclusion), "\n")
          total_non_empty <- total_non_empty + non_na_count
          if (non_na_count > 0) {
            cat("    First few non-NA values:", paste(head(col_data[col_data != ""], 5), collapse=", "), "\n")
          }
        }
      }
      # If ALL designated ID columns are completely empty, mark for fallback
      if (total_non_empty == 0) {
        id_columns_are_empty <- TRUE
        cat("  WARNING: All designated ID columns are completely empty!\n")
      }
    }
    
    if (!id_columns_are_empty &&
        !is.null(id_columns_to_use) &&
        is.numeric(id_columns_to_use) &&
        all(id_columns_to_use > 0) &&
        all(id_columns_to_use <= ncol(df_original_before_exclusion))) {
      cat("DEBUG: ID column extraction checks PASSED - extracting IDs\n")
      # Extract from the ORIGINAL unfiltered df, then subset to matching rows
      id_candidates_full <- df_original_before_exclusion[, id_columns_to_use, drop = FALSE]
      
      # Match molecules_filtered against the original feature list to get correct row indices
      original_molecules <- values$molecules  # This is the original unfiltered list
      row_indices_to_keep <- match(molecules_filtered, original_molecules)
      
      cat("  Original rows before filtering:", nrow(id_candidates_full), "\n")
      cat("  Rows to keep after filtering:", length(row_indices_to_keep), "\n")
      cat("  NAs in row_indices_to_keep:", sum(is.na(row_indices_to_keep)), "\n")
      
      # Remove NA indices (shouldn't happen, but safety check)
      valid_indices <- !is.na(row_indices_to_keep)
      keep_idx <- row_indices_to_keep[valid_indices]
      # Ensure indices are within the valid row range
      if (length(keep_idx) > 0) {
        keep_idx <- keep_idx[keep_idx >= 1 & keep_idx <= nrow(id_candidates_full)]
      }
      if (length(keep_idx) == 0) {
        # Nothing valid to extract
        id_candidates_full <- id_candidates_full[0, , drop = FALSE]
      } else {
        id_candidates_full <- id_candidates_full[keep_idx, , drop = FALSE]
      }

      # Convert to character (safe even if empty)
      id_candidates <- as.data.frame(lapply(id_candidates_full, as.character),
                                     check.names = FALSE, stringsAsFactors = FALSE)

      cat("  Final id_candidates dimensions:", nrow(id_candidates), "x", ncol(id_candidates), "\n")
      if (ncol(id_candidates) >= 1 && nrow(id_candidates) > 0) {
        cat("  First few values of column 1:", paste(head(id_candidates[[1]], 5), collapse=", "), "\n")
      } else {
        cat("  id_candidates is empty or has no columns\n")
      }
      if (ncol(id_candidates) >= 2 && nrow(id_candidates) > 0) {
        cat("  First few values of column 2:", paste(head(id_candidates[[2]], 5), collapse=", "), "\n")
      }
    } else if (id_columns_are_empty) {
      cat("DEBUG: Designated ID columns are empty - falling back to feature names\n")
      showNotification(
        "WARNING: Designated Gene/Accession ID columns are empty. Using feature names (Proteins) for enrichment analysis instead.",
        type = "warning", duration = 6
      )
      id_candidates <- NULL  # Will trigger fallback to feature names
    } else {
      cat("DEBUG: ID column extraction checks FAILED or no columns designated\n")
      id_candidates <- NULL
    }
    
    # Clean molecule names
    values$cleaned_molecules <- gsub(" OS=.*$", "", molecules_filtered)

    # Ensure metabolomics ID columns line up with the final filtered feature set
    # If mapping has already been performed earlier (before filtering), subset the
    # stored ID columns so they align with the filtered features shown in the UI.
    if (!is.null(values$metabolomics_id_columns) && !is.null(values$metabolomics_mapping)) {
      tryCatch({
        mapping_clean_names <- values$metabolomics_mapping$clean_names
        # Find mapping indices for the filtered features
        idx_map <- match(values$cleaned_molecules, mapping_clean_names)

        if (all(!is.na(idx_map))) {
          # Perfect match — subset ID columns into same order as filtered features
          values$metabolomics_id_columns <- values$metabolomics_id_columns[idx_map, , drop = FALSE]
        } else if (any(!is.na(idx_map))) {
          # Partial match — keep the ones we have and warn briefly
          valid <- which(!is.na(idx_map))
          values$metabolomics_id_columns <- values$metabolomics_id_columns[idx_map[valid], , drop = FALSE]
        } else {
          # No matches — clear metabolomics id columns to avoid showing misleading/empty columns
          values$metabolomics_id_columns <- NULL
        }
      }, error = function(e) {
        warning("Failed to align metabolomics ID columns to filtered features: ", e$message)
        values$metabolomics_id_columns <- NULL
      })
    }
    
    # Build enrichment IDs for downstream enrichment.
    # Use primary designated ID column first; fill missing IDs from secondary columns.
    # IMPORTANT: Compare id_candidates to molecules_filtered (not values$cleaned_molecules which hasn't been set yet)
    if (!is.null(id_candidates) && nrow(id_candidates) == length(molecules_filtered) && ncol(id_candidates) > 0) {
      cat("DEBUG: Extracting enrichment IDs from", ncol(id_candidates), "columns\n")
      cat("  id_candidates dimensions:", nrow(id_candidates), "x", ncol(id_candidates), "\n")
      cat("  molecules_filtered length:", length(molecules_filtered), "\n")
      cat("  First few rows of id_candidates:\n")
      print(head(id_candidates))
      
      ids <- rep(NA_character_, nrow(id_candidates))
      for (j in seq_len(ncol(id_candidates))) {
        col_ids <- trimws(as.character(id_candidates[[j]]))
        need <- is.na(ids) | ids == ""
        ok <- !is.na(col_ids) & nzchar(col_ids)
        ids[need & ok] <- col_ids[need & ok]
        
        cat("  Column", j, ":", sum(ok), "non-empty values\n")
      }
      values$accession_ids <- ids

      n_ok <- sum(!is.na(values$accession_ids) & nzchar(values$accession_ids))
      showNotification(
        paste0("Enrichment IDs loaded from designated column(s) for ", n_ok, " / ", length(values$accession_ids), " features"),
        type = "message", duration = 4
      )
    } else {
      # No designated ID columns available (or unexpected mismatch): fall back to feature names.
      # This preserves existing app behavior for datasets without mapping.
      cat("DEBUG: ID extraction check failed.\n")
      cat("  id_candidates is null:", is.null(id_candidates), "\n")
      if (!is.null(id_candidates)) {
        cat("  nrow(id_candidates):", nrow(id_candidates), "vs length(molecules_filtered):", length(molecules_filtered), "\n")
        cat("  ncol(id_candidates):", ncol(id_candidates), "\n")
      }
      # Set accession_ids to molecules_filtered (which will become cleaned_molecules)
      values$accession_ids <- molecules_filtered
    }
    
    # Prepare raw data (filtered but not normalized)
    # Ensure data_filtered is properly converted to a data frame before using mutate
    data_filtered <- as.data.frame(data_filtered) %>%
      dplyr::mutate(across(everything(), ~ as.numeric(as.character(.))))
    
    # Set feature names as rownames so they propagate through normalization and downstream processing
    # This ensures QC tabs and other UI elements show feature names instead of numeric indices
    # Use make.unique as a safety net in case any duplicates remain after deduplication
    if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) == nrow(data_filtered)) {
      rownames(data_filtered) <- make.unique(values$cleaned_molecules)
    }
    
    # Store raw data for DESeq2 (before normalization)
    # DESeq2 requires raw count data and performs its own internal normalization
    # Keep feature names as the first column for UI tables and downstream helpers
    values$raw_data <- data.frame(
      Feature = values$cleaned_molecules,
      data_filtered,
      check.names = FALSE,
      stringsAsFactors = FALSE
    )
    
    # Debug: Check raw data storage
    cat("Debug: Storing raw data with dimensions:", dim(data_filtered), "\n")
    cat("Debug: Raw data missing values:", sum(is.na(data_filtered)), "\n")
    
    # Use cache-aware normalization function for other methods
    log2_before <- identical(input$log2_norm_timing, "before")
    log2_after <- identical(input$log2_norm_timing, "after")
    sum_as_percent <- isTRUE(input$sum_norm_percentage)
    normalized_data <- perform_cached_normalization(data_filtered, input$normalization, log2_before, log2_after, sum_as_percent)
    
    # Check if batch correction is enabled
    if (input$batch_correction_enabled == "yes") {
      # Validate batch column is selected BEFORE attempting batch correction
      if (is.null(input$batch_column) || !nzchar(input$batch_column)) {
        showNotification("Error: Batch correction enabled but NO BATCH COLUMN SELECTED. Please select a batch column from the metadata sheet.",
                         type = "error", duration = 10)
        return()
      }
      
      # Validate that metadata sheet exists with batch column
      if (is.null(values$metadata) || !input$batch_column %in% colnames(values$metadata)) {
        showNotification("Error: Batch column not found in metadata sheet. Please ensure your Excel file has sheet 2 with sample metadata including a batch column.",
                         type = "error", duration = 10)
        return()
      }
      
      # Store data before batch correction for comparison
      values$data_before_batch_correction <- normalized_data
      
      # Show progress message
      withProgress(message = "Applying batch correction...", {
        setProgress(0.2, detail = "Reading metadata")
        
        # Get batch information from metadata sheet
        batch_info <- values$metadata[[input$batch_column]]
        message("Using batch information from metadata sheet (sheet 2)")
        showNotification("Using batch information from metadata sheet (sheet 2)",
                         type = "message", duration = 3)
        
        # Check that we have batch info for all samples
        if (length(batch_info) != ncol(normalized_data)) {
          showNotification("Metadata rows don't match sample count. Batch correction skipped.",
                           type = "error", duration = 10)
          return()
        }
        
        # Validate that selected batch column has at least 2 distinct batches
        unique_batches <- length(unique(as.character(batch_info[!is.na(batch_info)])))
        if (unique_batches < 2) {
          showNotification(paste("Error: Batch column must contain at least 2 distinct batch values. Found only", unique_batches, "unique batch."),
                           type = "error", duration = 10)
          return()
        }
        
        setProgress(0.4, detail = "Preparing correction parameters")
        
        # Extract group information for batch correction
        # Uses user's confirmed biological groupings from data upload mapping modal
        group_info <- NULL
        if (!is.null(values$final_biological_groups)) {
          # Use user's confirmed biological groupings from mapping modal
          group_info <- values$final_biological_groups
          message("Using confirmed biological groupings for batch correction (", length(unique(group_info)), " groups)")
          showNotification("Using confirmed biological groupings for batch correction",
                           type = "message", duration = 3)
        } else {
          message("No group information available - batch correction will use intercept-only model")
          showNotification("Warning: No group information available. Batch correction may remove biological variation.",
                           type = "warning", duration = 5)
        }
        
        setProgress(0.6, detail = "Applying batch correction")
        
        # Apply cached batch correction
        batch_result <- perform_cached_batch_correction(
          data = normalized_data,
          batch_info = batch_info,
          method = input$batch_correction_method,
          group_info = group_info
        )
        
        setProgress(0.9, detail = "Finalizing correction")
        
        # Handle batch correction result using helper function
        result_info <- handle_batch_correction_result(batch_result, normalized_data, "batch correction")
        normalized_data <- as.data.frame(result_info$data)
        
        # Show notification
        showNotification(result_info$notification$message,
                         type = result_info$notification$type,
                         duration = result_info$notification$duration)
      })
    }
    
    # ==================== QC-BASED SIGNAL DRIFT CORRECTION ====================
    # Apply QC-based drift correction if enabled
    if (isTRUE(input$qc_drift_enabled == "yes")) {
      withProgress(message = "Applying QC-based drift correction...", value = 0.5, {
        
        tryCatch({
          # Get sample names
          sample_names <- colnames(normalized_data)
          
          # Identify QC samples
          qc_method <- input$qc_identification_method %||% "auto"
          qc_pattern <- input$qc_sample_pattern %||% "QC|[Pp]ool|[Pp]ooled|NIST|[Bb]lank"
          
          if (qc_method == "metadata" && !is.null(values$metadata) && !is.null(input$qc_sample_column)) {
            metadata_col <- values$metadata[[input$qc_sample_column]]
            qc_result <- identify_qc_samples(sample_names, method = "metadata", 
                                             metadata_column = metadata_col)
          } else {
            qc_result <- identify_qc_samples(sample_names, method = qc_method, pattern = qc_pattern)
          }
          
          # Store QC information
          values$qc_sample_indices <- qc_result$qc_indices
          values$qc_sample_names <- qc_result$qc_names
          values$biological_sample_indices <- qc_result$biological_indices
          values$biological_sample_names <- qc_result$biological_names
          
          # Check minimum QC samples
          min_qc <- input$qc_min_samples %||% 3
          if (length(qc_result$qc_indices) < min_qc) {
            showNotification(
              sprintf("Insufficient QC samples detected (%d found, %d required). Skipping drift correction.",
                      length(qc_result$qc_indices), min_qc),
              type = "warning", duration = 8
            )
          } else {
            setProgress(0.6, detail = "Determining run order")
            
            # Determine run order
            run_order_method <- input$run_order_source %||% "column_order"
            
            if (run_order_method == "metadata" && !is.null(values$metadata) && !is.null(input$run_order_column)) {
              metadata_col <- values$metadata[[input$run_order_column]]
              run_order <- determine_run_order(sample_names, method = "metadata", 
                                               metadata_column = metadata_col)
            } else if (run_order_method == "names") {
              pattern <- input$run_order_pattern %||% "(?:run|inj|order)[_-]?(\\d+)"
              run_order <- determine_run_order(sample_names, method = "names", pattern = pattern)
            } else {
              run_order <- 1:length(sample_names)
            }
            
            values$run_order <- run_order
            
            setProgress(0.7, detail = "Applying drift correction")
            
            # Store data before correction for visualization
            values$data_before_drift_correction <- as.matrix(normalized_data)
            
            # Get correction parameters
            drift_method <- input$qc_drift_method %||% "qc_rlsc"
            span <- input$qc_loess_span %||% 0.75
            kernel <- input$qc_svr_kernel %||% "radial"
            cost <- input$qc_svr_cost %||% 1
            ntrees <- input$qc_serrf_ntrees %||% 500
            df_spline <- input$qc_spline_df %||% 5
            per_batch <- input$qc_correct_per_batch %||% FALSE
            
            # Get batch info if per-batch correction is enabled
            batch_info_qc <- NULL
            if (per_batch && !is.null(input$qc_batch_column) && !is.null(values$metadata)) {
              batch_info_qc <- values$metadata[[input$qc_batch_column]]
            }
            
            # Apply drift correction
            drift_result <- perform_qc_drift_correction(
              data = as.matrix(normalized_data),
              qc_indices = qc_result$qc_indices,
              run_order = run_order,
              method = drift_method,
              span = span,
              kernel = kernel,
              cost = cost,
              ntrees = ntrees,
              df = df_spline,
              per_batch = per_batch,
              batch_info = batch_info_qc
            )
            
            setProgress(0.85, detail = "Calculating quality metrics")
            
            # Store corrected data
            values$drift_corrected_data <- drift_result$corrected_data
            values$drift_correction_models <- drift_result$models %||% list()
            
            # Calculate quality metrics
            values$qc_rsd_before <- calculate_qc_rsd(values$data_before_drift_correction, qc_result$qc_indices)
            values$qc_rsd_after <- calculate_qc_rsd(drift_result$corrected_data, qc_result$qc_indices)
            values$qc_drift_metrics <- calculate_drift_metrics(
              values$data_before_drift_correction, 
              drift_result$corrected_data,
              qc_result$qc_indices,
              run_order
            )
            
            setProgress(0.95, detail = "Finalizing")
            
            # Optionally exclude QC samples from normalized data for downstream analysis
            if (isTRUE(input$qc_exclude_from_analysis)) {
              # Use corrected data but exclude QC samples
              bio_indices <- qc_result$biological_indices
              normalized_data <- as.data.frame(drift_result$corrected_data[, bio_indices, drop = FALSE])
              
              showNotification(
                sprintf("QC drift correction applied successfully using %s. %d QC samples excluded from downstream analysis.",
                        switch(drift_method,
                               "qc_rlsc" = "QC-RLSC (LOESS)",
                               "qc_svr" = "QC-SVR",
                               "serrf" = "SERRF",
                               "spline" = "Spline",
                               "median_qc" = "Median QC",
                               drift_method),
                        length(qc_result$qc_indices)),
                type = "message", duration = 6
              )
            } else {
              # Use all samples with correction applied
              normalized_data <- as.data.frame(drift_result$corrected_data)
              
              showNotification(
                sprintf("QC drift correction applied successfully using %s. QC samples retained in dataset.",
                        switch(drift_method,
                               "qc_rlsc" = "QC-RLSC (LOESS)",
                               "qc_svr" = "QC-SVR",
                               "serrf" = "SERRF",
                               "spline" = "Spline",
                               "median_qc" = "Median QC",
                               drift_method)),
                type = "message", duration = 6
              )
            }
            
            # Enable drift correction flag
            values$qc_drift_enabled <- TRUE
          }
          
        }, error = function(e) {
          showNotification(
            paste("Error during QC drift correction:", e$message),
            type = "error", duration = 10
          )
          message("QC drift correction error: ", e$message)
        })
      })
    } else {
      # Reset drift correction state if disabled
      values$qc_drift_enabled <- FALSE
      values$data_before_drift_correction <- NULL
      values$drift_corrected_data <- NULL
    }
    # ==================== END QC-BASED SIGNAL DRIFT CORRECTION ====================
    
    # Store normalized data and raw data, then apply corrected column names
    values$normalized_data <- normalized_data
    
    # Mark that analysis has been run (for conditional Save Analysis UI)
    values$analysis_has_run <- TRUE
    
    # Apply the corrected column names to both normalized_data and raw_data to keep them in sync
    # Exclude both Feature column (index 1) and Accession column if present
    df_cols_to_use <- seq_len(ncol(df))
    if (!is.null(values$accession_id_column) && 
        (is.numeric(values$accession_id_column) && all(values$accession_id_column > 0))) {
      # Exclude feature column and accession column
      df_cols_to_use <- setdiff(df_cols_to_use, c(1, values$accession_id_column))
    } else {
      # Only exclude feature column
      df_cols_to_use <- df_cols_to_use[-1]
    }
    
    if (ncol(values$normalized_data) == length(df_cols_to_use)) {
      # Ensure column names from corrected df are applied to normalized_data (only sample columns)
      corrected_names <- colnames(df)[df_cols_to_use]
      colnames(values$normalized_data) <- corrected_names
      
      # Also apply same column names to raw_data if it exists
      if (!is.null(values$raw_data)) {
        # If raw_data already includes a Feature column, only rename sample cols (2..n)
        if (ncol(values$raw_data) == length(corrected_names) + 1) {
          colnames(values$raw_data)[-1] <- corrected_names
        } else if (ncol(values$raw_data) == length(corrected_names)) {
          # If Feature column is missing for any reason, add it back and then rename
          values$raw_data <- cbind(Feature = values$cleaned_molecules, values$raw_data)
          colnames(values$raw_data)[-1] <- corrected_names
        }
      }
      
      # Also apply same column names to original_unfiltered_data
      if (!is.null(values$original_unfiltered_data)) {
        # If original_unfiltered_data already includes a Feature column, only rename sample cols (2..n)
        if (ncol(values$original_unfiltered_data) == length(corrected_names) + 1) {
          colnames(values$original_unfiltered_data)[-1] <- corrected_names
        } else if (ncol(values$original_unfiltered_data) == length(corrected_names)) {
          # If Feature column is missing for any reason, add it back and then rename
          values$original_unfiltered_data <- cbind(Feature = values$molecules, values$original_unfiltered_data)
          colnames(values$original_unfiltered_data)[-1] <- corrected_names
        }
      }
      
      # Update the stored corrected sample names to match the data structure
      values$corrected_sample_names <- corrected_names
    }
    
    # Build a stable dataset signature based only on cleaned sample headers
    # This keeps mapping tied to sample naming, regardless of cell values
    values$current_dataset_sig <- tryCatch({
      digest::digest(colnames(data_filtered), algo = "xxhash64")
    }, error = function(e) digest::digest(Sys.time(), algo = "xxhash64"))
    
    # Detect groups (enhanced hierarchical detection)
    # IMPORTANT: Use normalized_data column names to ensure indices match the actual data
    # This accounts for excluded columns (like accession IDs)
    header_groups <- colnames(values$normalized_data)
    exclude_cols <- c("Fold_Change", "Log2_FC", "P_Value", "Adjusted_P_Value")
    sample_cols <- setdiff(header_groups, exclude_cols)
    
    # Clean sample names: only remove Excel's duplicate format (e.g., "Control...1")
    cleaned_sample_cols <- str_replace(sample_cols, "\\.\\.\\..*$", "")
    
    # Enhanced hierarchical detection on cleaned names
    det <- detect_hierarchical_groups(cleaned_sample_cols)
    values$auto_mapping <- det
    
    # Build preliminary biological/experimental labels
    bio_labels <- det$biological
    exp_labels <- det$experimental
    
    # Use confirmed mapping if available (mapping was already verified at start of function)
    if (!is.null(values$final_biological_groups) && length(values$final_biological_groups) == length(cleaned_sample_cols)) {
      bio_labels <- values$final_biological_groups
      exp_labels <- values$final_experimental_groups
    }
    
    # Store the working mapping
    values$final_biological_groups <- bio_labels
    values$final_experimental_groups <- exp_labels
    
    # Derive unique groups and indices from biological groups
    values$unique_groups <- unique(bio_labels)
    values$unique_groups_original <- values$unique_groups
    
    # Create group column indices with validation
    group_column_indices <- lapply(values$unique_groups, function(g) {
      indices <- which(bio_labels == g)
      # Validate indices against normalized data if available
      if (!is.null(values$normalized_data)) {
        max_col_index <- ncol(values$normalized_data)
        valid_indices <- indices[indices > 0 & indices <= max_col_index]
        if (length(valid_indices) != length(indices)) {
          warning(paste("Some column indices for group", g, "are out of bounds.",
                        "Using", length(valid_indices), "out of", length(indices), "columns."))
        }
        return(valid_indices)
      }
      return(indices)
    })
    
    values$group_column_indices <- group_column_indices
    
    # Validate that all groups have at least one valid column
    empty_groups <- sapply(values$group_column_indices, length) == 0
    if (any(empty_groups)) {
      empty_group_names <- values$unique_groups[empty_groups]
      warning(paste("The following groups have no valid columns:",
                    paste(empty_group_names, collapse = ", ")))
    }
    
    # Update group selection dropdowns (include lmROTS/lmeROTS variable names when present)
    g1_choices <- values$unique_groups
    tryCatch({
      av <- get_available_comparison_names()
      vv <- av[grepl("^(lmROTS|lmeROTS)_", av)]
      if (length(vv) > 0) g1_choices <- c(g1_choices, vv)
    }, error = function(e) NULL)
    updateSelectizeInput(session, "group1", choices = g1_choices, selected = g1_choices[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "group2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    
    # Update feature selection dropdown - only if NOT on Distribution Analysis tab
    # (Distribution Analysis tab has its own observer that handles filtered features)
    if (is.null(input$current_tab) || input$current_tab != "Distribution Analysis") {
      updateSelectizeInput(session, "featureSelect", choices = values$cleaned_molecules)
    }
    
    # Update PCA group selections
    updateSelectizeInput(session, "pcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "pcaGroup2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    
    # Update differential analysis selections
    updateSelectizeInput(session, "diffGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "diffGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
    
    # Observer to update feature selection dropdown based on feature source in Distribution Analysis
    observe({
      req(values$cleaned_molecules, input$dist_feature_source)
      
      # Add reactive dependencies for PCA and ML features
      input$pca_top_features
      input$pca_feature_ranking
      input$dist_label_type  # Add dependency on label type
      values$selected_features
      values$pca_result
      
      # Only update if we're on the Distribution Analysis tab
      if (!is.null(input$current_tab) && input$current_tab == "Distribution Analysis") {
        
        # Get available features based on the selected source
        available_features <- get_available_feature_names(input$dist_feature_source, "All Groups")
        
        # If no features available from the selected source, show a notification
        if (length(available_features) == 0) {
          # Reset to "all" features and show notification
          updateSelectInput(session, "dist_feature_source", selected = "all")
          showNotification(
            paste("No features available from",
                  switch(input$dist_feature_source,
                         "pca" = "PCA analysis",
                         "ml" = "ML feature selection",
                         "selected source"),
                  "- reverting to all features"),
            type = "warning"
          )
          available_features <- values$cleaned_molecules
        }
        
        # Determine if using IDs or feature names
        use_ids_for_dropdown <- !is.null(input$dist_label_type) &&
          input$dist_label_type == "ids" &&
          !is.null(values$accession_ids) &&
          length(values$accession_ids) == length(values$cleaned_molecules)
        
        # Convert feature names to IDs if needed
        if (use_ids_for_dropdown) {
          # Map feature names to IDs
          feature_indices <- match(available_features, values$cleaned_molecules)
          available_labels <- values$accession_ids[feature_indices]
        } else {
          available_labels <- available_features
        }
        
        # Update the dropdown with filtered features/IDs
        updateSelectizeInput(session, "featureSelect",
                             choices = available_labels,
                             selected = if(length(available_labels) > 0) available_labels[1] else NULL)
      }
    })
    
    # Also update when switching TO the Distribution Analysis tab
    observeEvent(input$current_tab, {
      if (input$current_tab == "Distribution Analysis" && !is.null(values$cleaned_molecules)) {
        
        # Get available features based on the selected source
        available_features <- get_available_feature_names(input$dist_feature_source %||% "all", "All Groups")
        
        # Determine if using IDs or feature names
        use_ids_for_dropdown <- !is.null(input$dist_label_type) &&
          input$dist_label_type == "ids" &&
          !is.null(values$accession_ids) &&
          length(values$accession_ids) == length(values$cleaned_molecules)
        
        # Convert feature names to IDs if needed
        if (use_ids_for_dropdown) {
          feature_indices <- match(available_features, values$cleaned_molecules)
          available_labels <- values$accession_ids[feature_indices]
        } else {
          available_labels <- available_features
        }
        
        # Update the dropdown with filtered features/IDs
        updateSelectizeInput(session, "featureSelect",
                             choices = available_labels,
                             selected = if(length(available_labels) > 0) available_labels[1] else NULL)
      }
    })
    
    # Reactive expression for normalized data table
    normalizedDataReactive <- reactive({
      req(values$normalized_data, values$cleaned_molecules)
      
      # Note: Removed dependencies on values$processed_data, values$group_assignments,
      # input$normalization_method, input$scaling_method to allow loading from files
      # These will naturally trigger updates when the workflow runs
      values$imputation_method
      
      normalized_df <- values$normalized_data
      
      # Build result dataframe with proper column structure
      if (!is.null(values$metabolomics_id_columns) &&
          nrow(values$metabolomics_id_columns) == nrow(normalized_df)) {
        # Include individual metabolomics ID columns
        result_df <- data.frame(
          Feature = values$cleaned_molecules,
          stringsAsFactors = FALSE
        )
        # Add individual ID columns
        result_df <- cbind(result_df, values$metabolomics_id_columns)
        # Add normalized data columns
        result_df <- cbind(result_df, normalized_df)
        
        # Rename sample columns (start after Feature and ID columns)
        n_id_cols <- ncol(values$metabolomics_id_columns)
        n_data_cols <- ncol(normalized_df)
        if (ncol(result_df) > (1 + n_id_cols) && n_data_cols > 0) {
          if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == n_data_cols) {
            colnames(result_df)[(2 + n_id_cols):ncol(result_df)] <- values$corrected_sample_names
          } else if (!is.null(colnames(normalized_df)) && length(colnames(normalized_df)) == n_data_cols) {
            colnames(result_df)[(2 + n_id_cols):ncol(result_df)] <- colnames(normalized_df)
          }
        }
      } else if (!is.null(values$accession_ids) &&
          length(values$accession_ids) == nrow(normalized_df) &&
          !is.null(values$accession_id_column) &&
          is.numeric(values$accession_id_column) && length(values$accession_id_column) == 1 && values$accession_id_column > 0) {
        # Include single ID column (for non-metabolomics data)
        result_df <- data.frame(
          Feature = values$cleaned_molecules,
          ID = values$accession_ids,
          stringsAsFactors = FALSE
        )
        # Add normalized data columns
        result_df <- cbind(result_df, normalized_df)
        
        # Rename sample columns (start at column 3, after Feature and ID)
        # Ensure we only rename the actual data columns
        n_data_cols <- ncol(normalized_df)
        if (ncol(result_df) > 2 && n_data_cols > 0) {
          if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == n_data_cols) {
            colnames(result_df)[3:ncol(result_df)] <- values$corrected_sample_names
          } else if (!is.null(colnames(normalized_df)) && length(colnames(normalized_df)) == n_data_cols) {
            colnames(result_df)[3:ncol(result_df)] <- colnames(normalized_df)
          }
        }
      } else {
        # No ID column
        result_df <- data.frame(Feature = values$cleaned_molecules, stringsAsFactors = FALSE)
        result_df <- cbind(result_df, normalized_df)
        
        # Rename sample columns (start at column 2, after Feature)
        n_data_cols <- ncol(normalized_df)
        if (ncol(result_df) > 1 && n_data_cols > 0) {
          if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == n_data_cols) {
            colnames(result_df)[2:ncol(result_df)] <- values$corrected_sample_names
          } else if (!is.null(colnames(normalized_df)) && length(colnames(normalized_df)) == n_data_cols) {
            colnames(result_df)[2:ncol(result_df)] <- colnames(normalized_df)
          }
        }
      }
      
      return(result_df)
    })
    
    # Render normalized data table - always show values$normalized_data (now set by workflow or DESeq2 transform)
    # Use a reactive that doesn't have req() to ensure table renders even on initial load
    output$normalizedDataTable <- DT::renderDataTable({
      # Only render if we have data, otherwise return empty dataframe
      if (is.null(values$normalized_data) || is.null(values$cleaned_molecules)) {
        # Return empty placeholder dataframe to ensure table renders
        return(data.frame(Feature = character(0), stringsAsFactors = FALSE))
      }
      
      DT::datatable(normalizedDataReactive(),
                    options = list(pageLength = 10, scrollX = TRUE, dom = 'tip'),
                    rownames = FALSE)
    })
    
    # Make normalized data table available even when the UI is not visible
    outputOptions(output, "normalizedDataTable", suspendWhenHidden = FALSE)
    
    # Force normalized data table to update when data changes (even when tab is hidden)
    observe({
      # Monitor key data changes - these trigger when data is updated
      values$normalized_data
      values$cleaned_molecules
      values$corrected_sample_names
      values$accession_ids
      values$accession_id_column
      values$metabolomics_id_columns
      
      # Update table using proxy when data changes
      if (!is.null(values$normalized_data) && !is.null(values$cleaned_molecules)) {
        tryCatch({
          proxy <- DT::dataTableProxy("normalizedDataTable")
          DT::replaceData(proxy, normalizedDataReactive(), resetPaging = FALSE, rownames = FALSE)
        }, error = function(e) {
          # If proxy update fails, it means table hasn't been rendered yet, which is fine
          NULL
        })
      }
    })
    
    # Recompute DESeq2 transformed data when the user changes the transformation (no DE run needed)
    observeEvent(input$deseq2_transform, {
      req(input$sig_method == "deseq2", values$dds, values$cleaned_molecules)
      try({
        choice <- input$deseq2_transform %||% "vst"
        if (choice == "vst") {
          vsd <- DESeq2::vst(values$dds, blind = TRUE)
          mat <- SummarizedExperiment::assay(vsd)
        } else if (choice == "rlog") {
          rld <- DESeq2::rlog(values$dds, blind = TRUE)
          mat <- SummarizedExperiment::assay(rld)
        } else {
          mat <- DESeq2::counts(values$dds, normalized = TRUE)
          mat <- log2(mat + 1)
        }
        rownames(mat) <- make.unique(values$cleaned_molecules)
        values$normalized_data <- as.data.frame(mat)
        if (!is.null(values$corrected_sample_names) &&
            length(values$corrected_sample_names) == ncol(values$normalized_data)) {
          colnames(values$normalized_data) <- values$corrected_sample_names
        }
      }, silent = TRUE)
    })
    
    # Handle external batch correction settings changes for DESeq2 (visualization-only)
    observeEvent(list(
      input$viz_batch_enable,
      input$viz_batch_method
    ), {
      req(input$sig_method == "deseq2")
      req(!is.null(values$dds))
      req(!is.null(values$cleaned_molecules))
      
      # Recompute DESeq2 transformed data with/without external batch correction
      tryCatch({
        choice <- input$deseq2_transform %||% "vst"
        
        # Compute base transformed data
        if (choice == "vst") {
          vsd <- DESeq2::vst(values$dds, blind = TRUE)
          mat <- SummarizedExperiment::assay(vsd)
        } else if (choice == "rlog") {
          rld <- DESeq2::rlog(values$dds, blind = TRUE)
          mat <- SummarizedExperiment::assay(rld)
        } else {
          mat <- log2(DESeq2::counts(values$dds, normalized = TRUE) + 1)
        }
        
        rownames(mat) <- make.unique(values$cleaned_molecules)
        transformed_data <- as.data.frame(mat)
        
        # Apply external batch correction if enabled (visualization-only)
        if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
          # Validate metadata and batch column
          if (is.null(values$metadata) || is.null(input$batch_column) || !nzchar(input$batch_column) || !(input$batch_column %in% colnames(values$metadata))) {
            showNotification("Batch info not available for visualization correction. Using uncorrected transformed data.", type = "warning", duration = 5)
          } else {
            # Get group info from DESeq2 object
            groups <- values$dds$condition  # Assuming condition is the main factor
            # Align batch info by position
            md <- values$metadata
            if (nrow(md) >= length(groups)) {
              candidate <- md[[input$batch_column]]
              if (!is.null(candidate) && length(candidate) >= length(groups)) {
                viz_batch <- factor(candidate[seq_along(groups)])
                if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                  # Preserve pre-correction matrix for comparison plots
                  values$data_before_batch_correction <- transformed_data
                  # Use selected external method for visualization-only correction
                  viz_method <- input$viz_batch_method %||% "combat"
                  # Apply cached batch correction to the transformed matrix
                  batch_result <- tryCatch({
                    perform_cached_batch_correction(
                      data = as.matrix(transformed_data),
                      batch_info = viz_batch,
                      method = viz_method,
                      group_info = groups
                    )
                  }, error = function(e) {
                    list(success = FALSE, error = TRUE, message = e$message, data = transformed_data)
                  })
                  
                  # Handle batch correction result using helper function
                  result_info <- handle_batch_correction_result(batch_result, transformed_data,
                                                                paste("visualization batch correction for DESeq2", choice, "data"))
                  transformed_data <- as.data.frame(result_info$data)
                  
                  # Show notification
                  showNotification(result_info$notification$message,
                                   type = result_info$notification$type,
                                   duration = result_info$notification$duration)
                }
              }
            }
          }
        }
        
        # Update normalized_data with the recomputed transformed matrix
        values$normalized_data <- transformed_data
        
        # Keep corrected sample names if previously set
        if (!is.null(values$corrected_sample_names) &&
            length(values$corrected_sample_names) == ncol(values$normalized_data)) {
          colnames(values$normalized_data) <- values$corrected_sample_names
        }
        
      }, error = function(e) {
        showNotification(paste("Error updating DESeq2 external batch correction:", e$message), type = "error", duration = 5)
      })
    }, ignoreInit = TRUE)
    
    # Handle external batch correction settings changes for limma-voom (visualization-only)
    observeEvent(list(
      input$viz_batch_enable,
      input$viz_batch_method
    ), {
      req(input$sig_method == "limma_voom")
      req(!is.null(values$limma_voom_state$v))
      req(!is.null(values$limma_voom_state$groups))
      
      # Recompute only the logCPM matrix with/without external batch correction
      tryCatch({
        v <- values$limma_voom_state$v
        groups <- values$limma_voom_state$groups
        prior_count <- input$limma_voom_prior_count %||% 0.5
        
        # Extract counts from voom object and compute logCPM
        counts_mat <- v$targets$lib.size  # Get library sizes
        # Reconstruct approximate counts from voom E values for logCPM calculation
        # Use the original DGEList approach for consistency
        if (!is.null(values$raw_data)) {
          raw_df <- values$raw_data
          if (ncol(raw_df) > 1) {
            first_col_name <- colnames(raw_df)[1]
            if (!is.numeric(raw_df[[1]]) || first_col_name %in% c("Feature","Molecule","Gene","ID")) {
              raw_df <- raw_df[, -1, drop = FALSE]
            }
          }
          mat <- as.matrix(raw_df)
          if (any(!is.finite(mat))) mat[!is.finite(mat)] <- 0
          if (any(mat < 0, na.rm = TRUE)) mat[mat < 0] <- 0
          mat <- round(mat)
          storage.mode(mat) <- "integer"
          rownames(mat) <- make.unique(values$cleaned_molecules)
          
          # Create DGEList for logCPM calculation
          norm_method <- values$limma_voom_state$norm_method
          y_temp <- edgeR::DGEList(counts = mat, group = groups)
          if (!is.null(norm_method) && tolower(norm_method) == "none") {
            y_temp$samples$norm.factors <- rep(1, nrow(y_temp$samples))
          } else {
            y_temp <- edgeR::calcNormFactors(y_temp, method = norm_method)
          }
          
          logCPM_matrix <- edgeR::cpm(y_temp, log = TRUE, prior.count = prior_count)
          colnames(logCPM_matrix) <- values$corrected_sample_names %||% colnames(logCPM_matrix)
          
          # Apply external batch correction if enabled (visualization-only)
          if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
            # Validate metadata and batch column
            if (is.null(values$metadata) || is.null(input$batch_column) || !nzchar(input$batch_column) || !(input$batch_column %in% colnames(values$metadata))) {
              showNotification("Batch info not available for visualization correction. Using uncorrected logCPM.", type = "warning", duration = 5)
            } else {
              # Align batch info by position
              md <- values$metadata
              if (nrow(md) >= length(groups)) {
                candidate <- md[[input$batch_column]]
                if (!is.null(candidate) && length(candidate) >= length(groups)) {
                  viz_batch <- factor(candidate[seq_along(groups)])
                  if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                    # Preserve pre-correction matrix for comparison plots
                    values$data_before_batch_correction <- logCPM_matrix
                    # Use selected external method for visualization-only correction
                    viz_method <- input$viz_batch_method %||% "combat"
                    # Apply cached batch correction to the logCPM matrix
                    batch_result <- tryCatch({
                      perform_cached_batch_correction(
                        data = as.matrix(logCPM_matrix),
                        batch_info = viz_batch,
                        method = viz_method,
                        group_info = groups
                      )
                    }, error = function(e) {
                      list(success = FALSE, error = TRUE, message = e$message, data = logCPM_matrix)
                    })
                    
                    # Handle batch correction result using helper function
                    result_info <- handle_batch_correction_result(batch_result, logCPM_matrix,
                                                                  "visualization batch correction for limma-voom logCPM")
                    logCPM_matrix <- result_info$data
                    
                    # Show notification
                    showNotification(result_info$notification$message,
                                     type = result_info$notification$type,
                                     duration = result_info$notification$duration)
                  }
                }
              }
            }
          }
          
          # Update normalized_data with the recomputed logCPM matrix
          values$normalized_data <- as.data.frame(logCPM_matrix)
        }
        
      }, error = function(e) {
        showNotification(paste("Error updating limma-voom external batch correction:", e$message), type = "error", duration = 5)
      })
    }, ignoreInit = TRUE)
    
    # Recompute limma-voom logCPM display when prior count changes without re-running stats
    observeEvent(input$limma_voom_prior_count, {
      req(input$sig_method == "limma_voom")
      state <- values$limma_voom_state
      req(!is.null(state))
      
      prior_cnt <- as.numeric(input$limma_voom_prior_count %||% 0.5)
      
      # Reconstruct logCPM from raw data using cached parameters
      tryCatch({
        if (!is.null(values$raw_data)) {
          raw_df <- values$raw_data
          if (ncol(raw_df) > 1) {
            first_col_name <- colnames(raw_df)[1]
            if (!is.numeric(raw_df[[1]]) || first_col_name %in% c("Feature","Molecule","Gene","ID")) {
              raw_df <- raw_df[, -1, drop = FALSE]
            }
          }
          mat <- as.matrix(raw_df)
          if (any(!is.finite(mat))) mat[!is.finite(mat)] <- 0
          if (any(mat < 0, na.rm = TRUE)) mat[mat < 0] <- 0
          mat <- round(mat)
          storage.mode(mat) <- "integer"
          rownames(mat) <- make.unique(values$cleaned_molecules)
          
          groups <- state$groups
          norm_method <- state$norm_method
          y_temp <- edgeR::DGEList(counts = mat, group = groups)
          if (!is.null(norm_method) && tolower(norm_method) == "none") {
            y_temp$samples$norm.factors <- rep(1, nrow(y_temp$samples))
          } else {
            y_temp <- edgeR::calcNormFactors(y_temp, method = norm_method)
          }
          
          lcpm <- edgeR::cpm(y_temp, log = TRUE, prior.count = prior_cnt)
          new_norm <- as.data.frame(lcpm)
          
          # Keep corrected sample names if previously set
          if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(new_norm)) {
            colnames(new_norm) <- values$corrected_sample_names
          }
          
          # Reapply visualization-only external batch correction if enabled
          if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
            if (!is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && (input$batch_column %in% colnames(values$metadata))) {
              md <- values$metadata
              if (nrow(md) >= length(groups)) {
                candidate <- md[[input$batch_column]]
                if (!is.null(candidate) && length(candidate) >= length(groups)) {
                  viz_batch <- factor(candidate[seq_along(groups)])
                  if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                    values$data_before_batch_correction <- new_norm
                    viz_method <- input$viz_batch_method %||% "combat"
                    batch_result <- tryCatch({
                      perform_cached_batch_correction(
                        data = as.matrix(new_norm),
                        batch_info = viz_batch,
                        method = viz_method,
                        group_info = groups
                      )
                    }, error = function(e) {
                      list(success = FALSE, error = TRUE, message = e$message, data = new_norm)
                    })
                    
                    # Handle batch correction result
                    if (is.list(batch_result) && !is.null(batch_result$success)) {
                      if (batch_result$success) {
                        new_norm <- as.data.frame(batch_result$data)
                        if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(new_norm)) {
                          colnames(new_norm) <- values$corrected_sample_names
                        }
                      }
                    } else {
                      # Legacy format - assume it's the corrected data
                      new_norm <- as.data.frame(batch_result)
                      if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(new_norm)) {
                        colnames(new_norm) <- values$corrected_sample_names
                      }
                    }
                  }
                }
              }
            }
          }
          
          values$normalized_data <- new_norm
        }
      }, error = function(e) {
        showNotification(paste("Error updating limma-voom prior count:", e$message), type = "error", duration = 5)
      })
    }, ignoreInit = TRUE)
    
    # Recompute edgeR logCPM display when prior count changes without re-running stats
    observeEvent(input$edger_prior_count, {
      req(input$sig_method == "edger")
      state <- values$edger_state
      req(!is.null(state), !is.null(state$y))
      
      prior_cnt <- as.numeric(input$edger_prior_count %||% 1)
      lcpm <- try(edgeR::cpm(state$y, log = TRUE, prior.count = prior_cnt), silent = TRUE)
      if (inherits(lcpm, "try-error")) return()
      
      new_norm <- as.data.frame(lcpm)
      # Keep corrected sample names if previously set
      if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(new_norm)) {
        colnames(new_norm) <- values$corrected_sample_names
      }
      
      # Reapply visualization-only external batch correction if enabled for edgeR
      if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
        if (!is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && (input$batch_column %in% colnames(values$metadata))) {
          md <- values$metadata
          groups <- state$groups
          if (nrow(md) >= length(groups)) {
            candidate <- md[[input$batch_column]]
            if (!is.null(candidate) && length(candidate) >= length(groups)) {
              viz_batch <- factor(candidate[seq_along(groups)])
              if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                values$data_before_batch_correction <- new_norm
                viz_method <- input$viz_batch_method %||% "combat"
                corrected <- try(perform_cached_batch_correction(
                  data = as.matrix(new_norm),
                  batch_info = viz_batch,
                  method = viz_method,
                  group_info = groups
                ), silent = TRUE)
                if (!inherits(corrected, "try-error")) {
                  new_norm <- as.data.frame(corrected)
                  if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(new_norm)) {
                    colnames(new_norm) <- values$corrected_sample_names
                  }
                }
              }
            }
          }
        }
      }
      
      values$normalized_data <- new_norm
    }, ignoreInit = TRUE)
    
    # Clear caches when switching away from methods
    observeEvent(input$sig_method, {
      if (!is.null(input$sig_method)) {
        if (input$sig_method != "edger") {
          values$edger_state <- list()
        }
        if (input$sig_method != "limma_voom") {
          values$limma_voom_state <- list()
        }
      }
    }, ignoreInit = TRUE)
    
    # Handle external batch correction settings changes for edgeR (visualization-only)
    observeEvent(list(
      input$viz_batch_enable,
      input$viz_batch_method
    ), {
      req(input$sig_method == "edger")
      req(!is.null(values$edger_state$y))
      req(!is.null(values$edger_state$groups))
      
      # Recompute only the logCPM matrix with/without external batch correction
      tryCatch({
        y <- values$edger_state$y
        groups <- values$edger_state$groups
        prior_count <- input$edger_prior_count %||% 2
        
        # Compute base logCPM
        logCPM_matrix <- edgeR::cpm(y, log = TRUE, prior.count = prior_count)
        colnames(logCPM_matrix) <- values$corrected_sample_names %||% colnames(logCPM_matrix)
        
        # Apply external batch correction if enabled (visualization-only)
        if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
          # Validate metadata and batch column
          if (is.null(values$metadata) || is.null(input$batch_column) || !nzchar(input$batch_column) || !(input$batch_column %in% colnames(values$metadata))) {
            showNotification("Batch info not available for visualization correction. Using uncorrected logCPM.", type = "warning", duration = 5)
          } else {
            # Align batch info by position
            md <- values$metadata
            if (nrow(md) >= length(groups)) {
              candidate <- md[[input$batch_column]]
              if (!is.null(candidate) && length(candidate) >= length(groups)) {
                viz_batch <- factor(candidate[seq_along(groups)])
                if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                  # Preserve pre-correction matrix for comparison plots
                  values$data_before_batch_correction <- logCPM_matrix
                  # Use selected external method for visualization-only correction
                  viz_method <- input$viz_batch_method %||% "combat"
                  # Apply cached batch correction to the logCPM matrix
                  corrected <- try(perform_cached_batch_correction(
                    data = as.matrix(logCPM_matrix),
                    batch_info = viz_batch,
                    method = viz_method,
                    group_info = groups
                  ), silent = FALSE)
                  if (inherits(corrected, "try-error")) {
                    error_msg <- attr(corrected, "condition")$message %||% "Unknown error"
                    showNotification(paste("Visualization batch correction failed with", viz_method, "method:", error_msg), type = "warning", duration = 8)
                  } else {
                    logCPM_matrix <- corrected
                    showNotification(paste("External batch correction applied to visualization using", viz_method, "method"), type = "message", duration = 3)
                  }
                }
              }
            }
          }
        }
        
        # Update normalized_data with the recomputed logCPM matrix
        values$normalized_data <- logCPM_matrix
        
      }, error = function(e) {
        showNotification(paste("Error updating external batch correction:", e$message), type = "error", duration = 5)
      })
    }, ignoreInit = TRUE)
    
    # Show success message
    showNotification("Data loaded successfully!", type = "message")
    
    # Perform bootstrapping if enabled
    if (input$bootstrap_enabled == "yes") {
      
      # Exclude methods that are incompatible with bootstrap (these methods hide bootstrap settings in UI)
      incompatible_methods <- c("rots", "limma", "deseq2", "edger", "limma_voom")
      if (input$sig_method %in% incompatible_methods) {
        method_names <- c("rots" = "ROTS", "limma" = "Limma", "deseq2" = "DESeq2", "edger" = "edgeR")
        method_name <- method_names[input$sig_method]
        showNotification(paste0(method_name, " is not compatible with bootstrap analysis. Bootstrap has been skipped."),
                         type = "warning", duration = 8)
        return(NULL)
      }
      
      withProgress(message = "Performing bootstrap analysis...", {
        
        # Ensure required packages are available
        if (!requireNamespace("ggplot2", quietly = TRUE)) {
          showNotification("ggplot2 package is required for bootstrap analysis. Please install it.",
                           type = "error", duration = 10)
          return(NULL)
        }
        
        if (!requireNamespace("gridExtra", quietly = TRUE)) {
          showNotification("gridExtra package is required for bootstrap plots. Please install it.",
                           type = "error", duration = 10)
          return(NULL)
        }
        
        # Convert confidence level to numeric
        conf_level <- as.numeric(input$bootstrap_ci)
        
        # Number of bootstrap replicates
        n_replicates <- input$bootstrap_replicates
        
        # Set seed for reproducibility if specified by user
        if (!is.null(input$bootstrap_seed) && !is.na(input$bootstrap_seed)) {
          set.seed(input$bootstrap_seed)
          message("Using random seed: ", input$bootstrap_seed)
        }
        
        # Determine if we should use parallel processing
        use_parallel <- input$bootstrap_parallel
        n_cores <- if(use_parallel) min(input$bootstrap_cores, parallel::detectCores()) else 1
        
        if (use_parallel) {
          message("Using parallel processing with ", n_cores, " cores")
          if (!requireNamespace("BiocParallel", quietly = TRUE)) {
            message("Installing BiocParallel package...")
            if(!requireNamespace("BiocManager", quietly = TRUE)) {
              install.packages("BiocManager")
            }
            BiocManager::install("BiocParallel", update = FALSE)
          }
          library(BiocParallel)
          bp_param <- MulticoreParam(workers = n_cores)
        }
        # Create matrices to store bootstrap results
        bootstrap_pvals <- matrix(NA, nrow = length(values$cleaned_molecules), ncol = n_replicates)
        bootstrap_fcs <- matrix(NA, nrow = length(values$cleaned_molecules), ncol = n_replicates)
        
        # Show method-specific information
        method_info <- switch(input$sig_method,
                              "wilcox" = "Wilcoxon rank-sum tests",
                              "t.test" = "Student's t-tests",
                              "anova" = "Analysis of Variance (ANOVA)",
                              "kruskal" = "Kruskal-Wallis tests",
                              "limma" = "Linear Models for Microarray (limma)",
                              "deseq2" = "Differential Expression with DESeq2",
                              "Unknown method"
        )
        showNotification(paste("Bootstrap analysis using", method_info, "with", n_replicates, "replicates..."),
                         type = "message", duration = 5)
        # Validate method compatibility with available groups
        n_groups <- length(values$unique_groups)
        if (input$sig_method %in% c("anova", "kruskal", "limma", "deseq2") && n_groups < 2) {
          showNotification("Multi-group methods (ANOVA, Kruskal-Wallis, Limma, DESeq2) require at least 2 groups.",
                           type = "error", duration = 8)
          return(NULL)
        }
        
        if (input$sig_method %in% c("wilcox", "t.test") && n_groups < 2) {
          showNotification("Pairwise methods (Wilcoxon, t-test) require at least 2 groups.",
                           type = "error", duration = 8)
          return(NULL)
        }
        # Additional validation for limma
        if (input$sig_method == "limma") {
          if (!requireNamespace("limma", quietly = TRUE)) {
            showNotification("limma package is required for limma bootstrap analysis. Please install it from Bioconductor.",
                             type = "error", duration = 10)
            return(NULL)
          }
          
          # Check if we have enough samples per group for limma
          min_samples_per_group <- min(sapply(values$group_column_indices, length))
          if (min_samples_per_group < 2) {
            showNotification("Error: Limma bootstrap requires at least 2 samples per group. Consider using Wilcoxon or t-test for smaller datasets.",
                             type = "error", duration = 10)
            return(NULL)
          }
        }
        
        # Additional validation for DESeq2
        if (input$sig_method == "deseq2") {
          if (!requireNamespace("DESeq2", quietly = TRUE)) {
            showNotification("DESeq2 package is required for DESeq2 bootstrap analysis. Please install it from Bioconductor.",
                             type = "error", duration = 10)
            return(NULL)
          }
          
          # Check if we have enough samples per group for DESeq2
          min_samples_per_group <- min(sapply(values$group_column_indices, length))
          if (min_samples_per_group < 2) {
            showNotification("Error: DESeq2 bootstrap requires at least 2 samples per group. Consider using Wilcoxon or t-test for smaller datasets.",
                             type = "error", duration = 10)
            return(NULL)
          }
          
          # Check if data contains count-like data (non-negative integers or close to it)
          sample_data <- values$normalized_data[1:min(100, nrow(values$normalized_data)), ]
          non_negative_check <- all(sample_data >= 0, na.rm = TRUE)
          if (!non_negative_check) {
            showNotification("Warning: DESeq2 is designed for count data (non-negative values). Your data may contain negative values. Consider using limma instead.",
                             type = "warning", duration = 10)
          }
        }
        if (input$sig_method == "anova") {
          min_samples_per_group <- min(sapply(values$group_column_indices, length))
          total_samples <- sum(sapply(values$group_column_indices, length))
          if (min_samples_per_group < 2 || total_samples < 4) {
            showNotification("Error: ANOVA bootstrap requires at least 2 samples per group and 4 total samples. Consider using Wilcoxon or t-test for smaller datasets.",
                             type = "error", duration = 10)
            return(NULL)
          }
        }
        
        # Additional validation for Kruskal-Wallis
        if (input$sig_method == "kruskal") {
          min_samples_per_group <- min(sapply(values$group_column_indices, length))
          total_samples <- sum(sapply(values$group_column_indices, length))
          if (min_samples_per_group < 2 || total_samples < 4) {
            showNotification("Error: Kruskal-Wallis bootstrap requires at least 2 samples per group and 4 total samples. Consider using Wilcoxon for pairwise comparisons.",
                             type = "error", duration = 10)
            return(NULL)
          }
        }
        # Function to perform a single bootstrap iteration
        perform_bootstrap <- function(b) {
          # Create bootstrap indices for resampling
          bootstrap_indices <- list()
          
          # Ensure we have valid group information
          if (is.null(values$group_column_indices) || length(values$group_column_indices) < 2) {
            return(list(p_vals = rep(NA, length(values$cleaned_molecules)),
                        fcs = rep(NA, length(values$cleaned_molecules))))
          }
          
          # Different resampling strategies
          bootstrap_strategy <- input$bootstrap_strategy
          if (is.null(bootstrap_strategy)) bootstrap_strategy <- "standard"
          
          if (bootstrap_strategy == "standard") {
            # Standard approach: Simple random sampling with replacement within each group
            for (g in seq_along(values$group_column_indices)) {
              group_columns <- values$group_column_indices[[g]]
              if (length(group_columns) > 0) {
                bootstrap_indices[[g]] <- sample(group_columns, length(group_columns), replace = TRUE)
              }
            }
          }
          else if (bootstrap_strategy == "stratified") {
            # Stratified approach: Maintain proportional representation within each group
            for (g in seq_along(values$group_column_indices)) {
              group_columns <- values$group_column_indices[[g]]
              if (length(group_columns) > 0) {
                # Calculate proportions of each sample in original data
                sample_props <- table(factor(group_columns, levels = group_columns))
                sample_props <- sample_props / sum(sample_props)
                
                # Sample with these proportions
                bootstrap_indices[[g]] <- sample(group_columns, length(group_columns),
                                                 replace = TRUE, prob = sample_props)
              }
            }
          }
          else if (bootstrap_strategy == "balanced") {
            # Balanced approach: Equal probability for each unique sample
            for (g in seq_along(values$group_column_indices)) {
              group_columns <- values$group_column_indices[[g]]
              if (length(group_columns) > 0) {
                # Ensure unique samples have equal probability
                unique_cols <- unique(group_columns)
                selected_cols <- sample(unique_cols, length(group_columns), replace = TRUE)
                bootstrap_indices[[g]] <- selected_cols
              }
            }
          }
          # Initialize results for this bootstrap replicate
          b_pvals <- rep(NA, length(values$cleaned_molecules))
          b_fcs <- rep(NA, length(values$cleaned_molecules))
          
          # Ensure we have bootstrap indices for at least 2 groups
          if (length(bootstrap_indices) < 2) {
            return(list(p_vals = b_pvals, fcs = b_fcs))
          }
          # Calculate p-values for this bootstrap sample
          for (i in 1:nrow(values$normalized_data)) {
            tryCatch({
              # Extract data for feature i
              feature_data <- values$normalized_data[i, ]
              
              # Get bootstrap data for each group
              bootstrap_data <- list()
              for (g in seq_along(bootstrap_indices)) {
                if (length(bootstrap_indices[[g]]) > 0) {
                  bootstrap_data[[g]] <- as.numeric(feature_data[bootstrap_indices[[g]]])
                }
              }
              
              # Only proceed if we have enough valid data
              if (length(bootstrap_data) >= 2) {
                # Check minimum sample sizes per group
                valid_groups <- sapply(bootstrap_data, function(x) sum(!is.na(x)) >= 2)
                
                if (sum(valid_groups) >= 2) {              # Calculate p-value based on the selected statistical method
                  if (input$sig_method == "wilcox") {
                    # Pairwise Wilcoxon test (use first 2 groups)
                    if (length(bootstrap_data) >= 2) {
                      tryCatch({
                        p_val <- wilcox.test(bootstrap_data[[1]], bootstrap_data[[2]])$p.value
                        if (!is.na(p_val) && is.finite(p_val)) {
                          b_pvals[i] <- p_val
                        }
                      }, error = function(e) {
                        # Silently continue on error for this feature
                      })
                    }
                  }
                  else if (input$sig_method == "t.test") {
                    # Pairwise t-test (use first 2 groups)
                    if (length(bootstrap_data) >= 2) {
                      tryCatch({
                        p_val <- t.test(bootstrap_data[[1]], bootstrap_data[[2]])$p.value
                        if (!is.na(p_val) && is.finite(p_val)) {
                          b_pvals[i] <- p_val
                        }
                      }, error = function(e) {
                        # Silently continue on error for this feature
                      })
                    }
                  }else if (input$sig_method == "anova") {
                    # ANOVA for multiple groups
                    if (length(bootstrap_data) >= 2) {
                      # Prepare data for ANOVA
                      all_values <- c()
                      all_groups <- c()
                      
                      for (g in seq_along(bootstrap_data)) {
                        group_data <- bootstrap_data[[g]][!is.na(bootstrap_data[[g]])]
                        if (length(group_data) >= 2) {  # Require at least 2 samples per group for ANOVA
                          all_values <- c(all_values, group_data)
                          all_groups <- c(all_groups, rep(paste0("Group", g), length(group_data)))
                        }
                      }
                      
                      if (length(unique(all_groups)) >= 2 && length(all_values) >= 4) {  # Require minimum 4 total samples
                        tryCatch({
                          anova_df <- data.frame(value = all_values, group = factor(all_groups))
                          anova_result <- summary(aov(value ~ group, data = anova_df))
                          p_val <- anova_result[[1]]$`Pr(>F)`[1]
                          if (!is.na(p_val) && is.finite(p_val)) {
                            b_pvals[i] <- p_val
                          }
                        }, error = function(e) {
                          # No fallback - let ANOVA fail properly
                        })
                      }
                    }
                  }              else if (input$sig_method == "kruskal") {
                    # Kruskal-Wallis for multiple groups (keep original requirements since it worked)
                    if (length(bootstrap_data) >= 2) {
                      # Prepare data for Kruskal-Wallis
                      all_values <- c()
                      all_groups <- c()
                      
                      for (g in seq_along(bootstrap_data)) {
                        group_data <- bootstrap_data[[g]][!is.na(bootstrap_data[[g]])]
                        if (length(group_data) >= 2) {  # Keep original requirement: at least 2 samples per group
                          all_values <- c(all_values, group_data)
                          all_groups <- c(all_groups, rep(paste0("Group", g), length(group_data)))
                        }
                      }
                      
                      if (length(unique(all_groups)) >= 2 && length(all_values) >= 4) {  # Keep original requirement: minimum 4 total samples
                        tryCatch({
                          kw_result <- kruskal.test(all_values ~ factor(all_groups))
                          p_val <- kw_result$p.value
                          if (!is.na(p_val) && is.finite(p_val)) {
                            b_pvals[i] <- p_val
                          }
                        }, error = function(e) {
                          # No fallback - let Kruskal-Wallis fail properly
                        })
                      }
                    }
                  }              else if (input$sig_method == "limma") {
                    # Limma analysis (requires specific setup)
                    if (length(bootstrap_data) >= 2) {
                      # Prepare data for limma
                      sample_names <- c()
                      sample_groups <- c()
                      sample_values <- c()
                      
                      for (g in seq_along(bootstrap_data)) {
                        group_data <- bootstrap_data[[g]][!is.na(bootstrap_data[[g]])]
                        if (length(group_data) >= 2) {  # Require at least 2 samples per group for proper Limma analysis
                          sample_values <- c(sample_values, group_data)
                          group_name <- if(g <= length(values$unique_groups)) values$unique_groups[g] else paste0("Group", g)
                          sample_groups <- c(sample_groups, rep(group_name, length(group_data)))
                          sample_names <- c(sample_names, paste0("S", length(sample_names) + 1:length(group_data)))
                        }
                      }
                      
                      if (length(unique(sample_groups)) >= 2 && length(sample_values) >= 4) {  # Require minimum 4 total samples
                        if (requireNamespace("limma", quietly = TRUE)) {
                          tryCatch({
                            # Create design matrix for limma
                            group_factor <- factor(sample_groups)
                            design_matrix <- model.matrix(~ group_factor)
                            
                            # Ensure design matrix has proper column names
                            if (ncol(design_matrix) > 1) {
                              colnames(design_matrix)[1] <- "Intercept"
                              for (j in 2:ncol(design_matrix)) {
                                colnames(design_matrix)[j] <- paste0("Group", j-1)
                              }
                            }
                            
                            # Limma expects a matrix with features as rows, samples as columns
                            # For bootstrap, we're analyzing one feature at a time
                            data_matrix <- matrix(sample_values, nrow = 1)
                            colnames(data_matrix) <- sample_names
                            # Preserve real feature name if available
                            if (!is.null(values$cleaned_molecules) && i <= length(values$cleaned_molecules)) {
                              rownames(data_matrix) <- values$cleaned_molecules[i]
                            } else {
                              rownames(data_matrix) <- paste0("Feature_", i)
                            }
                            
                            # Fit limma model
                            fit <- limma::lmFit(data_matrix, design_matrix)
                            fit <- limma::eBayes(fit)
                            
                            # Get appropriate p-value
                            if (ncol(fit$coefficients) > 1) {
                              # For multiple groups, test overall F-statistic
                              if (!is.null(fit$F.p.value) && length(fit$F.p.value) > 0) {
                                p_val <- fit$F.p.value[1]
                              } else {
                                # Fallback: use the first contrast p-value
                                p_val <- fit$p.value[1, 2]
                              }
                            } else {
                              # For single contrast, use t-test p-value
                              p_val <- fit$p.value[1, 1]
                            }
                            
                            if (!is.na(p_val) && is.finite(p_val)) {
                              b_pvals[i] <- p_val
                            }
                          }, error = function(e) {
                            # No fallback - let Limma fail properly if there are issues
                          })
                        }
                      }
                    }
                  } else if (input$sig_method == "deseq2") {
                    # DESeq2 analysis for count data
                    if (length(bootstrap_data) >= 2) {
                      # Prepare data for DESeq2
                      sample_names <- c()
                      sample_groups <- c()
                      sample_values <- c()
                      
                      for (g in seq_along(bootstrap_data)) {
                        group_data <- bootstrap_data[[g]][!is.na(bootstrap_data[[g]])]
                        if (length(group_data) >= 2) {  # Require at least 2 samples per group for DESeq2
                          sample_values <- c(sample_values, group_data)
                          group_name <- if(g <= length(values$unique_groups)) values$unique_groups[g] else paste0("Group", g)
                          sample_groups <- c(sample_groups, rep(group_name, length(group_data)))
                          sample_names <- c(sample_names, paste0("S", length(sample_names) + 1:length(group_data)))
                        }
                      }
                      
                      if (length(unique(sample_groups)) >= 2 && length(sample_values) >= 4) {  # Require minimum 4 total samples
                        if (requireNamespace("DESeq2", quietly = TRUE)) {
                          tryCatch({
                            # Prepare count data - DESeq2 expects non-negative integers
                            # Round values and ensure they are non-negative
                            count_data <- pmax(0, round(sample_values))
                            
                            # Create count matrix (features x samples)
                            count_matrix <- matrix(count_data, nrow = 1)
                            colnames(count_matrix) <- sample_names
                            if (!is.null(values$cleaned_molecules) && i <= length(values$cleaned_molecules)) {
                              rownames(count_matrix) <- values$cleaned_molecules[i]
                            } else {
                              rownames(count_matrix) <- paste0("Feature_", i)
                            }
                            
                            # Create sample metadata
                            sample_metadata <- data.frame(
                              condition = factor(sample_groups),
                              row.names = sample_names
                            )
                            
                            # Create DESeq2 dataset (include batch in design when applicable)
                            use_batch_in_deseq2 <- FALSE
                            if (identical(input$batch_correction_enabled, "yes")) {
                              sample_names <- colnames(count_matrix)
                              batch_vec <- NULL
                              # 1) Use pre-aligned batch vector if available
                              if (!is.null(values$batch_info) && length(values$batch_info) == length(sample_names)) {
                                batch_vec <- values$batch_info
                              }
                              # 2) If batch correction works via position matching, do the same
                              if (is.null(batch_vec) && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                                md <- values$metadata
                                batch_column_data <- md[[input$batch_column]]
                                if (length(batch_column_data) == length(sample_names)) {
                                  batch_vec <- batch_column_data
                                }
                              }
                              # 3) Map via user-selected metadata ID and batch columns
                              if (is.null(batch_vec) && !is.null(values$metadata)) {
                                md <- values$metadata
                                id_col_name <- NULL
                                batch_col_name <- NULL
                                if (!is.null(input$metadata_id_col) && nzchar(input$metadata_id_col) && input$metadata_id_col %in% colnames(md)) {
                                  id_col_name <- input$metadata_id_col
                                }
                                if (!is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(md)) {
                                  batch_col_name <- input$batch_column
                                } else if (!is.null(input$metadata_batch_col) && nzchar(input$metadata_batch_col) && input$metadata_batch_col %in% colnames(md)) {
                                  batch_col_name <- input$metadata_batch_col
                                }
                                if (!is.null(id_col_name) && !is.null(batch_col_name)) {
                                  key <- as.character(md[[id_col_name]])
                                  batch_map <- stats::setNames(md[[batch_col_name]], key)
                                  batch_vec <- unname(batch_map[sample_names])
                                }
                              }
                              # 4) Fallbacks: rownames or common ID columns
                              if (is.null(batch_vec) && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                                md <- values$metadata
                                if (!is.null(rownames(md)) && all(sample_names %in% rownames(md))) {
                                  batch_vec <- md[sample_names, input$batch_column]
                                } else {
                                  id_cols <- intersect(colnames(md), c("Sample", "SampleID", "sample", "sample_id"))
                                  if (length(id_cols) > 0) {
                                    key <- as.character(md[[id_cols[1]]])
                                    batch_map <- stats::setNames(md[[input$batch_column]], key)
                                    batch_vec <- unname(batch_map[sample_names])
                                  }
                                }
                              }
                              # Validate and attach
                              if (!is.null(batch_vec)) {
                                batch_fac <- as.factor(batch_vec)
                                if (length(stats::na.omit(unique(batch_fac))) >= 2) {
                                  sample_metadata$batch <- batch_fac
                                  cond_batches <- tapply(sample_metadata$batch, sample_metadata$condition, function(b) length(unique(b)))
                                  batch_conds <- tapply(sample_metadata$condition, sample_metadata$batch, function(c) length(unique(c)))
                                  confounded <- all(cond_batches == 1, na.rm = TRUE) && all(batch_conds == 1, na.rm = TRUE)
                                  if (isTRUE(confounded)) {
                                    showNotification("Warning: Batch and condition are perfectly confounded. Proceeding without batch in DESeq2 design.", type = "warning", duration = 8)
                                    sample_metadata$batch <- NULL
                                  } else {
                                    use_batch_in_deseq2 <- TRUE
                                  }
                                } else {
                                  showNotification("Batch column has fewer than 2 levels for the selected samples. Ignoring batch in DESeq2 design.", type = "message", duration = 6)
                                }
                              } else {
                                showNotification("Could not align batch metadata to sample names. Ignoring batch for DESeq2.", type = "warning", duration = 8)
                              }
                            }
                            
                            dds <- if (isTRUE(use_batch_in_deseq2) && "batch" %in% colnames(sample_metadata)) {
                              DESeq2::DESeqDataSetFromMatrix(
                                countData = count_matrix,
                                colData = sample_metadata,
                                design = ~ batch + condition
                              )
                            } else {
                              DESeq2::DESeqDataSetFromMatrix(
                                countData = count_matrix,
                                colData = sample_metadata,
                                design = ~ condition
                              )
                            }
                            
                            # Run DESeq2 analysis
                            dds <- DESeq2::DESeq(dds,
                                                 test = input$deseq2_test %||% "Wald",
                                                 fitType = input$deseq2_fitType %||% "parametric",
                                                 quiet = TRUE)
                            
                            # Get results
                            if (length(unique(sample_groups)) == 2) {
                              # Pairwise comparison
                              res <- DESeq2::results(dds,
                                                     alpha = input$deseq2_alpha %||% 0.05,
                                                     independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                                     cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
                              p_val <- res$pvalue[1]
                            } else {
                              # Multi-group comparison - use likelihood ratio test
                              res <- DESeq2::results(dds,
                                                     alpha = input$deseq2_alpha %||% 0.05,
                                                     independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                                     cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
                              p_val <- res$pvalue[1]
                            }
                            
                            if (!is.na(p_val) && is.finite(p_val)) {
                              b_pvals[i] <- p_val
                            }
                          }, error = function(e) {
                            # DESeq2 failed - this can happen with bootstrap resampling
                            # due to lack of variance or other issues
                          })
                        }
                      }
                    }
                  }              # Calculate fold change - use standard pairwise approach for all methods
                  # Only calculate fold changes for pairwise comparisons (first two groups)
                  if (length(bootstrap_data) >= 2) {
                    # Always use the first two groups for fold change calculation
                    # This provides interpretable fold changes even for multi-group statistical tests
                    mean1 <- mean(bootstrap_data[[1]], na.rm = TRUE)
                    mean2 <- mean(bootstrap_data[[2]], na.rm = TRUE)
                    
                    if (!is.na(mean1) && !is.na(mean2)) {
                      # Calculate fold change based on data scale
                      # When data is log-scale: fc = mean2 - mean1 (subtraction in log space)
                      # When data is linear: fc = mean2 / mean1 (division, then logged later)
                      if (is_data_log_scale()) {
                        fc <- mean2 - mean1
                      } else {
                        # For linear scale, only calculate if mean1 > 0
                        if (mean1 > 0) {
                          fc <- mean2 / mean1
                        } else {
                          fc <- NA
                        }
                      }
                      if (!is.na(fc)) {
                        b_fcs[i] <- fc
                      }
                    }
                  }
                }
              }
            }, error = function(e) {
              # Silently continue on error for this feature
            })
          }
          
          return(list(p_vals = b_pvals, fcs = b_fcs))
        }
        
        # Perform bootstrap analysis (parallel or sequential)
        if (use_parallel) {
          # Parallel implementation
          progress_step <- max(1, floor(n_replicates/10))  # Update progress every ~10% of work
          
          # Split replicates into chunks for better progress reporting
          chunk_size <- max(10, floor(n_replicates/20))
          chunk_indices <- split(1:n_replicates, ceiling(seq_along(1:n_replicates)/chunk_size))
          
          for (chunk_idx in seq_along(chunk_indices)) {
            current_chunk <- chunk_indices[[chunk_idx]]
            
            # Run this chunk in parallel
            chunk_results <- bplapply(current_chunk, function(b) {
              # Process this bootstrap replicate
              return(perform_bootstrap(b))
            }, BPPARAM = bp_param)
            
            # Combine results from this chunk
            for (i in seq_along(chunk_results)) {
              b <- current_chunk[i]
              bootstrap_pvals[, b] <- chunk_results[[i]]$p_vals
              bootstrap_fcs[, b] <- chunk_results[[i]]$fcs
            }
            
            # Update progress after each chunk
            setProgress(value = max(current_chunk)/n_replicates,
                        detail = paste0("Completed ", max(current_chunk), " of ", n_replicates, " replicates"))
          }
        } else {
          # Sequential implementation
          for (b in 1:n_replicates) {
            result <- perform_bootstrap(b)
            bootstrap_pvals[, b] <- result$p_vals
            bootstrap_fcs[, b] <- result$fcs
            
            # Update progress
            if (b %% 10 == 0 || b == n_replicates) {
              setProgress(value = b/n_replicates,
                          detail = paste0("Completed ", b, " of ", n_replicates, " replicates"))
            }
          }
        }
        # Calculate bootstrap confidence intervals for p-values
        bootstrap_results <- data.frame(
          Feature = values$cleaned_molecules,
          Original_PValue = NA,  # Will fill this later from values$stat_results if available
          Bootstrap_Median_PValue = apply(bootstrap_pvals, 1, median, na.rm = TRUE),
          Bootstrap_Lower_CI = apply(bootstrap_pvals, 1, quantile, probs = (1-conf_level)/2, na.rm = TRUE),
          Bootstrap_Upper_CI = apply(bootstrap_pvals, 1, quantile, probs = 1-(1-conf_level)/2, na.rm = TRUE),
          Bootstrap_Significant = FALSE,
          Bootstrap_Median_FC = apply(bootstrap_fcs, 1, median, na.rm = TRUE),
          Bootstrap_FC_Lower_CI = apply(bootstrap_fcs, 1, quantile, probs = (1-conf_level)/2, na.rm = TRUE),
          Bootstrap_FC_Upper_CI = apply(bootstrap_fcs, 1, quantile, probs = 1-(1-conf_level)/2, na.rm = TRUE),
          Bootstrap_Strategy = input$bootstrap_strategy
        )
        
        # Add original p-values from values$stat_results if available
        if (!is.null(values$stat_results)) {
          # Find the column containing p-values
          p_value_col <- grep("PValue$", colnames(values$stat_results), value = TRUE)[1]
          if (!is.na(p_value_col)) {
            bootstrap_results$Original_PValue <- values$stat_results[[p_value_col]]
          }
        }
        
        # Determine significance based on the bootstrap distribution
        bootstrap_results$Bootstrap_Significant <- bootstrap_results$Bootstrap_Upper_CI < 0.05
        # Store bootstrap results    values$bootstrap_results <- bootstrap_results
        values$bootstrap_pvals_matrix <- bootstrap_pvals
        values$bootstrap_fcs_matrix <- bootstrap_fcs      # Debug: Check if fold changes were calculated
        valid_fcs <- sum(!is.na(bootstrap_fcs))
        valid_pvals <- sum(!is.na(bootstrap_pvals))
        total_elements <- nrow(bootstrap_pvals) * ncol(bootstrap_pvals)
        message("Bootstrap analysis completed. Valid p-values: ", valid_pvals, ", Valid fold changes: ", valid_fcs, " out of ", total_elements, " total elements")
        # Check if bootstrap analysis actually worked
        if (valid_pvals == 0) {
          error_msg <- paste0("Bootstrap analysis failed to calculate any p-values using ", input$sig_method, ". ")
          
          if (input$sig_method == "anova") {
            error_msg <- paste0(error_msg, "ANOVA requires at least 2 samples per group and 4 total samples. Consider using Wilcoxon or t-test for smaller datasets.")
          } else if (input$sig_method == "limma") {
            error_msg <- paste0(error_msg, "Limma requires at least 2 samples per group and 4 total samples. Consider using Wilcoxon or t-test for smaller datasets.")
          } else if (input$sig_method == "deseq2") {
            error_msg <- paste0(error_msg, "DESeq2 requires at least 2 samples per group and 4 total samples. Also ensure data contains count-like values (non-negative). Consider using limma or t-test for non-count data.")
          } else if (input$sig_method == "kruskal") {
            error_msg <- paste0(error_msg, "Kruskal-Wallis requires at least 2 samples per group and 4 total samples. Consider using Wilcoxon for pairwise comparisons.")
          } else if (input$sig_method %in% c("wilcox", "t.test")) {
            error_msg <- paste0(error_msg, "Pairwise tests require at least 2 groups with sufficient data. Check that your groups have adequate sample sizes.")
          } else {
            error_msg <- paste0(error_msg, "Please check your data and try a different statistical method.")
          }
          
          showNotification(error_msg, type = "error", duration = 15)
          return(NULL)
        } else if (valid_pvals < (total_elements * 0.1)) {
          # Warning if less than 10% of p-values were calculated
          showNotification(paste0("Warning: Only ", valid_pvals, " out of ", total_elements, " bootstrap p-values were calculated (",
                                  round(valid_pvals/total_elements*100, 1), "%). This may indicate data quality issues."),
                           type = "warning", duration = 10)
        } else {
          # Success message
          success_rate <- round(valid_pvals/total_elements*100, 1)
          showNotification(paste0("Bootstrap analysis completed successfully. Calculated ", valid_pvals, " p-values (", success_rate, "% success rate)."),
                           type = "message", duration = 5)
        }
        if (valid_fcs == 0) {
          showNotification("Warning: No fold changes were calculated during bootstrap analysis. This may occur with insufficient data.",
                           type = "warning", duration = 10)
          
          # Standard fallback: calculate pairwise fold changes between first two groups
          if (length(values$group_column_indices) >= 2) {
            message("Attempting fallback pairwise fold change calculation...")
            
            # Use traditional fold change between first two groups for all methods
            group1_cols <- values$group_column_indices[[1]]
            group2_cols <- values$group_column_indices[[2]]
            
            if (length(group1_cols) > 0 && length(group2_cols) > 0) {
              fallback_fcs <- rep(NA, nrow(values$normalized_data))
              
              for (f in 1:nrow(values$normalized_data)) {
                group1_data <- values$normalized_data[f, group1_cols]
                group2_data <- values$normalized_data[f, group2_cols]
                
                group1_mean <- mean(group1_data, na.rm = TRUE)
                group2_mean <- mean(group2_data, na.rm = TRUE)
                
                if (!is.na(group1_mean) && !is.na(group2_mean) && group1_mean > 0) {
                  # Calculate as Group2/Group1 to match documentation
                  fallback_fcs[f] <- group2_mean / group1_mean
                }
              }
              
              message("Calculated standard pairwise fold changes between first two groups")
              
              # Replace the bootstrap_fcs matrix with replicated fallback values
              if (sum(!is.na(fallback_fcs)) > 0) {
                bootstrap_fcs <- matrix(rep(fallback_fcs, n_replicates),
                                        nrow = length(fallback_fcs),
                                        ncol = n_replicates)
                values$bootstrap_fcs_matrix <- bootstrap_fcs
                message("Fallback fold changes calculated for ", sum(!is.na(fallback_fcs)), " features")
                
                # Also update the bootstrap results
                if (exists("bootstrap_results")) {
                  bootstrap_results$Bootstrap_Median_FC <- fallback_fcs
                  bootstrap_results$Bootstrap_FC_Lower_CI <- fallback_fcs  # For fallback, CI = median
                  bootstrap_results$Bootstrap_FC_Upper_CI <- fallback_fcs
                  values$bootstrap_results <- bootstrap_results
                }
              }
            }
          }
        }
        
        values$bootstrap_params <- list(
          seed = input$bootstrap_seed,
          strategy = input$bootstrap_strategy,
          replicates = n_replicates,
          confidence_level = conf_level,
          parallel = use_parallel,
          cores = if(use_parallel) n_cores else NA
        )
        
        # Add bootstrap results to statistics table
        if (!is.null(values$stat_results)) {
          values$stat_results$Bootstrap_Median_PValue <- bootstrap_results$Bootstrap_Median_PValue
          values$stat_results$Bootstrap_Lower_CI <- bootstrap_results$Bootstrap_Lower_CI
          values$stat_results$Bootstrap_Upper_CI <- bootstrap_results$Bootstrap_Upper_CI
          values$stat_results$Bootstrap_Significant <- bootstrap_results$Bootstrap_Significant
          values$stat_results$Bootstrap_Strategy <- bootstrap_results$Bootstrap_Strategy
          
          # For Bootstrap_Log2FC:
          # If data is log-scale, Bootstrap_Median_FC is already log-scale difference (log2)
          # If data is linear-scale, Bootstrap_Median_FC is ratio, so we need to log it
          if (is_data_log_scale()) {
            values$stat_results$Bootstrap_Log2FC <- bootstrap_results$Bootstrap_Median_FC
          } else {
            values$stat_results$Bootstrap_Log2FC <- log2(bootstrap_results$Bootstrap_Median_FC)
          }
        }
        # Update the feature selection dropdown for bootstrap plots
        updateSelectInput(session, "bootstrap_feature",
                          choices = values$cleaned_molecules,
                          selected = values$cleaned_molecules[1])
      })
    }
    
    # Refresh Bootstrap plots when statistical results are updated (outside of bootstrap analysis)
    observe({
      # Watch for changes in statistical results to refresh Bootstrap tab
      req(values$stat_results)
      
      # Only update if bootstrap results exist and bootstrap is enabled
      if (!is.null(values$bootstrap_results) &&
          !is.null(input$bootstrap_enabled) &&
          input$bootstrap_enabled == "yes") {
        
        # Update the feature selection dropdown for bootstrap plots
        updateSelectInput(session, "bootstrap_feature",
                          choices = values$cleaned_molecules,
                          selected = if(!is.null(input$bootstrap_feature) &&
                                        input$bootstrap_feature %in% values$cleaned_molecules) {
                            input$bootstrap_feature
                          } else {
                            values$cleaned_molecules[1]
                          })
      }
    })
    
    # Bootstrap distribution plot - make it reactive to stat_results changes
    output$bootstrapDistPlot <- renderPlot({ 
      req(values$bootstrap_pvals_matrix, values$stat_results)  # Add stat_results dependency
      
      tryCatch({
        # Calculate median p-values for each feature
        medians <- apply(values$bootstrap_pvals_matrix, 1, median, na.rm = TRUE)
        
        # Create a data frame for plotting
        plot_data <- data.frame(
          Feature = values$cleaned_molecules,
          Median_PValue = medians,
          Original_PValue = if(exists("bootstrap_results")) bootstrap_results$Original_PValue else NA,
          Significant = if(exists("bootstrap_results")) bootstrap_results$Bootstrap_Significant else FALSE
        )
        
        # Remove rows with NA values for Median_PValue
        plot_data <- plot_data[!is.na(plot_data$Median_PValue), ]
        
        if (nrow(plot_data) == 0) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5, label = "No bootstrap data available for plotting") +
                   theme_void())
        }
        
        # Create the visualization with strategy information
        bootstrap_strategy <- if(!is.null(input$bootstrap_strategy)) input$bootstrap_strategy else "standard"
        
        ggplot(plot_data, aes(x = reorder(Feature, -Median_PValue), y = Median_PValue,
                              fill = Significant)) +
          geom_bar(stat = "identity") +
          geom_point(aes(y = Original_PValue), color = "black", size = 2) +
          scale_fill_manual(values = c("TRUE" = "#1B9E77", "FALSE" = "#D95F02")) +
          labs(title = paste("Bootstrap Median P-values (Top", min(50, nrow(plot_data)), "Features)"),
               subtitle = paste0(conf_level*100, "% CI, ", n_replicates, " replicates, ",
                                 "Strategy: ", bootstrap_strategy,
                                 if(use_parallel) paste0(", Parallel: ", n_cores, " cores") else ""),
               x = "Feature",
               y = "P-value") +
          geom_hline(yintercept = 0.05, linetype = "dashed", color = "red") +
          theme_minimal() +
          theme(axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5, size = 8),
                plot.title = element_text(hjust = 0.5),
                plot.subtitle = element_text(hjust = 0.5),
                legend.position = "top")
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("Error creating bootstrap plot:", e$message)) +
          theme_void()
      })
    }, res = UI_PLOT_RES)
    
    # Update the feature-specific bootstrap plot - make it reactive to stat_results changes
    output$bootstrapFeaturePlot <- renderPlot({ 
      # First check if required data exists
      validate(
        need(input$bootstrap_feature, "Please select a feature to view"),
        need(values$bootstrap_pvals_matrix, "Bootstrap data not available"),
        need(values$bootstrap_fcs_matrix, "Bootstrap fold change data not available")
      )
      
      # Add dependency on stat_results to refresh when statistics change
      req(values$stat_results)
      
      # Check if bootstrap fold change matrix has any valid data
      if (all(is.na(values$bootstrap_fcs_matrix))) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No fold change data available.\nThis may occur with multi-group analyses or\nwhen statistical tests don't support fold changes.\nP-value bootstrap data is still available in the Statistics Results tab.",
                          hjust = 0.5, vjust = 0.5, size = 4) +
                 theme_void() +
                 theme(plot.margin = ggplot2::margin(20, 20, 20, 20)))
      }
      
      # Safe feature lookup with better error handling
      feature_idx <- which(values$cleaned_molecules == input$bootstrap_feature)
      
      if (length(feature_idx) == 0 || feature_idx > nrow(values$bootstrap_pvals_matrix)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5, label = "Selected feature not found in bootstrap data") +
                 theme_void())
      }
      # Safely extract data
      tryCatch({
        p_values <- values$bootstrap_pvals_matrix[feature_idx, ]
        p_values <- p_values[!is.na(p_values)]
        
        fold_changes <- values$bootstrap_fcs_matrix[feature_idx, ]
        fold_changes <- fold_changes[!is.na(fold_changes)]
        
        # Check if we have any valid data
        if (length(p_values) == 0 && length(fold_changes) == 0) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5, label = "No bootstrap data available for this feature") +
                   theme_void())
        }
        
        # Get log2 fold changes
        log2_fold_changes <- log2(fold_changes)
        log2_fold_changes <- log2_fold_changes[is.finite(log2_fold_changes)]
        
        # Create plots only if we have data
        plots_to_arrange <- list()
        
        if (length(p_values) > 0) {
          p1 <- ggplot(data.frame(p_value = p_values), aes(x = p_value)) +
            geom_histogram(fill = "#78B7C5", color = "white", bins = 30) +
            geom_vline(xintercept = median(p_values, na.rm = TRUE),
                       color = "#FF4136", linewidth = 1.5) +
            geom_vline(xintercept = quantile(p_values,
                                             probs = c((1-conf_level)/2, 1-(1-conf_level)/2),
                                             na.rm = TRUE),
                       color = "#0074D9", linetype = "dashed", linewidth = 1) +
            annotate("text", x = median(p_values, na.rm = TRUE), y = Inf,
                     label = paste("Median:", round(median(p_values, na.rm = TRUE), 4)),
                     vjust = 2, hjust = 1.1, color = "#FF4136", fontface = "bold") +
            labs(title = paste0("P-value Distribution for ", input$bootstrap_feature),
                 subtitle = paste0("Strategy: ", if(!is.null(input$bootstrap_strategy)) input$bootstrap_strategy else "standard"),
                 x = "P-value", y = "Count") +
            theme_minimal() +
            theme(
              plot.title = element_text(face = "bold", hjust = 0.5),
              plot.subtitle = element_text(hjust = 0.5, face = "italic"),
              axis.title = element_text(face = "bold")
            )
          plots_to_arrange <- append(plots_to_arrange, list(p1))
        }
        
        if (length(log2_fold_changes) > 0) {
          p2 <- ggplot(data.frame(log2_fc = log2_fold_changes), aes(x = log2_fc)) +
            geom_histogram(fill = "#E6A0C4", color = "white", bins = 30) +
            geom_vline(xintercept = median(log2_fold_changes, na.rm = TRUE),
                       color = "#FF4136", linewidth = 1.5) +
            geom_vline(xintercept = quantile(log2_fold_changes,
                                             probs = c((1-conf_level)/2, 1-(1-conf_level)/2),
                                             na.rm = TRUE),
                       color = "#0074D9", linetype = "dashed", linewidth = 1) +
            annotate("text", x = median(log2_fold_changes, na.rm = TRUE), y = Inf,
                     label = paste("Median:", round(median(log2_fold_changes, na.rm = TRUE), 4)),
                     vjust = 2, hjust = if(median(log2_fold_changes, na.rm = TRUE) > 0) 1.1 else -0.1,
                     color = "#FF4136", fontface = "bold") +
            labs(title = paste0("Log2 FC Distribution for ", input$bootstrap_feature),
                 subtitle = paste0(conf_level*100, "% Confidence Interval"),
                 x = "Log2 Fold Change", y = "Count") +
            theme_minimal() +
            theme(
              plot.title = element_text(face = "bold", hjust = 0.5),
              plot.subtitle = element_text(hjust = 0.5, face = "italic"),
              axis.title = element_text(face = "bold")
            )
          plots_to_arrange <- append(plots_to_arrange, list(p2))
        }
        
        # Arrange plots side by side if we have any plots
        if (length(plots_to_arrange) > 0) {
          gridExtra::grid.arrange(grobs = plots_to_arrange, ncol = min(2, length(plots_to_arrange)))
        } else {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5, label = "No valid bootstrap data for plotting") +
            theme_void()
        }
        
      }, error = function(e) {
        # Catch-all error handler
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("Error analyzing bootstrap data:", e$message)) +
          theme_void()
      })
    })
  })
  
  output$groupSummaryTable <- DT::renderDataTable({
    req(values$unique_groups, values$group_column_indices)
    
    # If enhanced mapping is available, provide both biological and experimental summaries
    if (!is.null(values$final_biological_groups) && !is.null(values$final_experimental_groups)) {
      bio <- values$final_biological_groups
      exp <- values$final_experimental_groups
      samples <- colnames(values$normalized_data) %||% values$corrected_sample_names %||% character(length(bio))
      # Biological summary
      bio_levels <- unique(bio)
      bio_counts <- sapply(bio_levels, function(g) sum(bio == g))
      # Experimental summary
      exp_levels <- unique(exp)
      exp_counts <- sapply(exp_levels, function(g) sum(exp == g))
      # Compose a combined table
      group_summary <- rbind(
        data.frame(Type = "Biological", Group = bio_levels, Samples = as.integer(bio_counts), stringsAsFactors = FALSE),
        data.frame(Type = "Experimental", Group = exp_levels, Samples = as.integer(exp_counts), stringsAsFactors = FALSE)
      )
      DT::datatable(group_summary, options = list(pageLength = 10, dom = 'tip'), rownames = FALSE)
    } else {
      group_summary <- data.frame(
        Group = values$unique_groups,
        Samples = sapply(values$group_column_indices, length),
        stringsAsFactors = FALSE
      )
      DT::datatable(group_summary, options = list(dom = 't'), rownames = FALSE)
    }
  })
  
  # Build duplicate handling modal
  build_duplicate_handling_modal <- function(duplicate_feature_names) {
    header <- div(class = "mlfs-card-header",
                  h4(icon("exclamation-triangle", class = "mlfs-feature-icon"), "Duplicate Feature Names Detected"))

    # Create summary of duplicates
    num_duplicates <- length(duplicate_feature_names)
    duplicate_list <- paste(duplicate_feature_names, collapse = ", ")

    summary <- div(class = "alert alert-warning",
                   HTML(sprintf("<b>Warning:</b> Found %d duplicate feature name(s): %s<br><br>
                                <b>How would you like to handle these duplicates?</b>",
                                num_duplicates, duplicate_list)))

    body <- div(class = "duplicate-handling-container",
                header, summary,

                # Duplicate handling options
                tags$hr(),
                helpText(icon("question-circle"), "Choose how to resolve duplicate feature names:"),
                fluidRow(
                  column(12,
                         radioButtons(
                           "duplicate_handling_choice",
                           "",
                           choices = c(
                             "Keep first occurrence only" = "first",
                             "Remove all duplicates" = "remove_all",
                             "Consolidate by summing values" = "sum",
                             "Add number suffixes (e.g., Feature_1, Feature_2)" = "suffix"
                           ),
                           selected = "first"
                         ),
                  )
                )
    )

    footer <- tagList(
      modalButton("Cancel Upload"),
      actionButton("duplicate_confirm", "Apply Resolution", icon = icon("check"), class = "btn-primary")
    )
    modalDialog(body, footer = footer, size = "m", easyClose = FALSE)
  }

  # Build mapping modal
  build_group_mapping_modal <- function(mapping_df, det, data_columns = NULL, is_metabolomics_data = FALSE) {
    # Add defensive checks for parameters
    if (is.null(det) || is.null(mapping_df)) {
      return(modalDialog(
        h4("Error: Data not initialized properly"),
        p("Please upload your data again."),
        easyClose = FALSE
      ))
    }
    
    # Ensure is_metabolomics_data is a logical scalar
    if (!is.logical(is_metabolomics_data) || length(is_metabolomics_data) == 0) {
      is_metabolomics_data <- FALSE
    }
    
    header <- div(class = "mlfs-card-header",
                  h4(icon("tags", class = "mlfs-feature-icon"), "Configure Data Columns & Group Mapping"))
    summary <- div(class = "alert alert-info",
                   HTML(sprintf("<b>Detected:</b> %s delimiter; method: %s; Complex experiment: <b>%s</b>.<br>Biological groups will drive analyses; experimental groups are available for time/dose facets.",
                                det$delimiter, det$method, ifelse(det$is_complex, "Yes", "No"))))
    
    # Auto-detect feature name and accession ID columns
    auto_feature_col <- 1  # Default to first column
    auto_accession_col <- NULL
    
    if (!is.null(data_columns) && length(data_columns) > 0) {
      # Try to detect feature name column
      feature_patterns <- c("feature", "gene", "protein", "metabolite", "compound", "analyte",
                            "name", "id", "symbol", "glycan", "lipid")
      for (i in seq_along(data_columns)) {
        if (any(sapply(feature_patterns, function(p) grepl(p, data_columns[i], ignore.case = TRUE)))) {
          auto_feature_col <- i
          break
        }
      }
      
      # Try to detect accession ID column
      accession_patterns <- c("accession", "uniprot", "entrez", "ensembl", "refseq",
                              "gene_id", "protein_id", "glycan_id", "compound_id", "pubchem")
      
      # For metabolomics data, prioritize metabolite ID columns
      # Ensure is_metabolomics_data is checked safely
      if (isTRUE(is_metabolomics_data)) {
        accession_patterns <- c("kegg", "chebi", "hmdb", "pubchem", "lipidmaps", "metabolite_id", 
                                "compound_id", "accession", "uniprot", "entrez", "ensembl", "refseq",
                                "gene_id", "protein_id", "glycan_id")
      }
      
      for (i in seq_along(data_columns)) {
        if (any(sapply(accession_patterns, function(p) grepl(p, data_columns[i], ignore.case = TRUE)))) {
          auto_accession_col <- i
          break
        }
      }
      
      # If no accession column detected, check if second column looks like IDs
      if (is.null(auto_accession_col) && length(data_columns) >= 2) {
        # If feature column is 1, check if column 2 might be accession
        if (auto_feature_col == 1 && length(data_columns) >= 2) {
          col2_name <- tolower(data_columns[2])
          if (grepl("id|acc|code|number", col2_name)) {
            auto_accession_col <- 2
          }
        }
      }
      
      # For metabolomics data, if still no ID column found, try to detect metabolite-specific patterns
      if (isTRUE(is_metabolomics_data) && is.null(auto_accession_col)) {
        metabolite_id_patterns <- c("kegg", "chebi", "hmdb", "pubchem", "lipidmaps", "c[0-9]+", "hmdb[0-9]+")
        for (i in seq_along(data_columns)) {
          col_name <- tolower(data_columns[i])
          # Check if column name contains metabolite ID patterns
          if (any(sapply(metabolite_id_patterns, function(p) grepl(p, col_name)))) {
            auto_accession_col <- i
            break
          }
          # Also check sample data in the column to see if it looks like metabolite IDs
          if (!is.null(values$original_unfiltered_data) && i <= ncol(values$original_unfiltered_data)) {
            sample_values <- na.omit(values$original_unfiltered_data[1:min(5, nrow(values$original_unfiltered_data)), i])
            if (length(sample_values) > 0) {
              sample_str <- paste(sample_values, collapse = " ")
              if (grepl("C[0-9]{5}|HMDB[0-9]{5}|CHEBI:[0-9]+|LMFA[0-9]+", sample_str)) {
                auto_accession_col <- i
                break
              }
            }
          }
        }
      }
    }
    
    body <- div(class = "group-mapping-container",
                header, summary,
                
                # Column Configuration Section
                tags$hr(),
                helpText(icon("table"), " Step 1: Specify data column roles (for enrichment analysis and feature identification)."),
                fluidRow(
                  column(4,
                         selectInput(
                           "feature_name_column",
                           "Feature Name Column",
                           choices = if(!is.null(data_columns)) setNames(seq_along(data_columns), data_columns) else c("Column 1" = 1),
                           selected = auto_feature_col,
                           width = "100%"
                         ),
                         helpText("Column containing primary feature names/identifiers")
                  ),
                  column(4,
                         selectizeInput(
                           "accession_id_column",
                           "Accession/ID Columns (for enrichment)",
                           choices = c("None (use feature names)" = 0,
                                       if(!is.null(data_columns)) setNames(seq_along(data_columns), data_columns) else c("Column 1" = 1)),
                           selected = if(!is.null(auto_accession_col)) auto_accession_col else 0,
                           multiple = TRUE,
                           options = list(placeholder = "Select one or more ID columns"),
                           width = "100%"
                         ),
                         helpText("Columns with UniProt, Entrez, KEGG, HMDB, or other database IDs. Multiple columns supported for different ID types.")
                  ),
                  column(4,
                         selectizeInput(
                           "ignore_columns",
                           "Ignore/Exclude Columns",
                           choices = if(!is.null(data_columns)) setNames(seq_along(data_columns), data_columns) else NULL,
                           selected = NULL,
                           multiple = TRUE,
                           options = list(placeholder = "Select columns to ignore"),
                           width = "100%"
                         ),
                         helpText("Columns to exclude from analysis (e.g., notes, descriptions)")
                  )
                ),
                
                # Group Mapping Section
                tags$hr(),
                helpText(icon("users"), " Step 2: Define biological and experimental group levels, then assign samples in the table below."),
                helpText(icon("exclamation-triangle", style="color: orange;"), HTML("<strong>Important:</strong> Manual edits in the table below override metadata. Changes here take precedence over automatically detected groupings.")),
                fluidRow(
                  column(6,
                         selectizeInput(
                           "bio_levels", "Biological group levels",
                           choices = unique(mapping_df$Biological_Group),
                           selected = unique(mapping_df$Biological_Group),
                           multiple = TRUE,
                           options = list(create = TRUE, persist = FALSE, placeholder = "Add or edit biological groups")
                         )
                  ),
                  column(6,
                         selectizeInput(
                           "exp_levels", "Experimental group levels",
                           choices = unique(mapping_df$Experimental_Group),
                           selected = unique(mapping_df$Experimental_Group),
                           multiple = TRUE,
                           options = list(create = TRUE, persist = FALSE, placeholder = "Add or edit experimental groups")
                         )
                  )
                ),
                tags$hr(),
                helpText(icon("pencil"), " Step 3: Assign each sample to the appropriate Biological and Experimental group. Edit the table directly to override metadata values."),
                div(class = "group-mapping-table",
                    rhandsontable::rHandsontableOutput("mapping_table", width = "100%", height = 500)
                )
    )
    footer <- tagList(
      modalButton("Cancel"),
      actionButton("mapping_reset", "Reset", icon = icon("undo"), class = "btn-secondary"),
      actionButton("mapping_confirm", "Confirm Mapping", icon = icon("check"), class = "btn-primary")
    )
    modalDialog(body, footer = footer, size = "l", easyClose = FALSE)
  }
  
  # Open mapping modal on demand (if data already loaded)
  observeEvent(input$open_mapping_modal, {
    # Build mapping from best available source so the button works at any time
    # Determine sample names from multiple fallbacks
    samples <- NULL
    if (!is.null(values$mapping_df) && !is.null(values$mapping_df$Sample)) {
      samples <- values$mapping_df$Sample
    } else if (!is.null(values$pending_sample_names)) {
      samples <- values$pending_sample_names
    } else if (!is.null(values$corrected_sample_names)) {
      samples <- values$corrected_sample_names
    } else if (!is.null(values$normalized_data)) {
      samples <- colnames(values$normalized_data)
    } else if (!is.null(values$original_unfiltered_data)) {
      # Use raw header columns (excluding feature column)
      cols <- colnames(values$original_unfiltered_data)
      if (!is.null(cols) && length(cols) > 1) samples <- cols[-1]
    }
    req(!is.null(samples), length(samples) > 0)
    
    # Prefer showing the latest confirmed/edited mapping if available
    if (!is.null(values$mapping_df) && nrow(values$mapping_df) == length(samples)) {
      df_map <- values$mapping_df
      # Sanitize any missing/blank group entries from earlier runs
      if (!"Biological_Group" %in% colnames(df_map)) df_map$Biological_Group <- rep("Unknown", nrow(df_map))
      if (!"Experimental_Group" %in% colnames(df_map)) df_map$Experimental_Group <- rep("None", nrow(df_map))
      bio_blank <- is.na(df_map$Biological_Group) | trimws(as.character(df_map$Biological_Group)) == ""
      exp_blank <- is.na(df_map$Experimental_Group) | trimws(as.character(df_map$Experimental_Group)) == ""
      if (any(bio_blank)) df_map$Biological_Group[bio_blank] <- "Unknown"
      if (any(exp_blank)) df_map$Experimental_Group[exp_blank] <- "None"
      det <- values$auto_mapping %||% detect_hierarchical_groups(samples)
    } else if (!is.null(values$final_biological_groups) &&
               length(values$final_biological_groups) == length(samples)) {
      df_map <- data.frame(
        Sample = samples,
        Biological_Group = values$final_biological_groups,
        Experimental_Group = values$final_experimental_groups,
        stringsAsFactors = FALSE
      )
      det <- values$auto_mapping %||% detect_hierarchical_groups(samples)
    } else {
      # Fall back to auto-detected mapping
      det <- detect_hierarchical_groups(samples)
      # Prefill Biological_Group with a safe default when detection yields blanks
      bio_tokens <- det$biological
      if (is.null(bio_tokens) ||
          length(bio_tokens) != length(samples) ||
          all(is.na(bio_tokens) | trimws(as.character(bio_tokens)) == "")) {
        bio_tokens <- rep("Unknown", length(samples))
      }
      # If simple design or experimental tokens are empty, prefill Experimental_Group with a default
      exp_tokens <- det$experimental
      if (!isTRUE(det$is_complex) ||
          is.null(exp_tokens) ||
          length(exp_tokens) != length(samples) ||
          all(is.na(exp_tokens) | trimws(as.character(exp_tokens)) == "")) {
        exp_tokens <- rep("None", length(samples))
      }
      df_map <- data.frame(
        Sample = samples,
        Biological_Group = bio_tokens,
        Experimental_Group = exp_tokens,
        stringsAsFactors = FALSE
      )
    }
    
    # Store and open modal
    values$mapping_df <- df_map
    values$auto_mapping <- det
    # Capture initial mapping state for reset (per modal open)
    values$mapping_initial_state <- list(
      df = df_map,
      bio_levels = unique(df_map$Biological_Group),
      exp_levels = unique(df_map$Experimental_Group)
    )
    
    # Try to read column names from the data file for column selection
    data_columns <- NULL
    if (!is.null(current_data_file())) {
      tryCatch({
        if (grepl("\\.csv$", tolower(current_data_file()$name))) {
          df_head <- utils::read.csv(current_data_file()$datapath, nrows = 1, check.names = FALSE, stringsAsFactors = FALSE)
        } else {
          df_head <- readxl::read_excel(current_data_file()$datapath, .name_repair = "minimal", n_max = 1)
        }
        data_columns <- colnames(df_head)
      }, error = function(e) NULL)
    }
    
    showModal(build_group_mapping_modal(df_map, det, data_columns, input$is_metabolomics_data))
    
    # Initialize level lists on open
    # Filter mapping_df to exclude metadata columns before populating group levels
    filtered_map_df <- df_map
    
    # Get columns to exclude from mapping (but wait for inputs to be available)
    if (!is.null(input$feature_name_column) || !is.null(input$accession_id_column) || !is.null(input$ignore_columns)) {
      cols_to_exclude <- c()
      if (!is.null(input$feature_name_column) && as.integer(input$feature_name_column) > 0) {
        cols_to_exclude <- c(cols_to_exclude, as.integer(input$feature_name_column))
      }
      if (!is.null(input$accession_id_column) && length(input$accession_id_column) > 0) {
        id_cols <- as.integer(input$accession_id_column[input$accession_id_column != "0"])
        if (length(id_cols) > 0) {
          cols_to_exclude <- c(cols_to_exclude, id_cols)
        }
      }
      if (!is.null(input$ignore_columns) && length(input$ignore_columns) > 0) {
        cols_to_exclude <- c(cols_to_exclude, as.integer(input$ignore_columns))
      }
      
      cols_to_exclude <- unique(cols_to_exclude)

      # Convert column indices into row indices to prevent name-based misalignment
      if (length(cols_to_exclude) > 0 && nrow(filtered_map_df) > 0) {
        excluded_rows <- as.integer(cols_to_exclude) - 1
        excluded_rows <- excluded_rows[excluded_rows >= 1 & excluded_rows <= nrow(filtered_map_df)]
        if (length(excluded_rows) > 0) {
          filtered_map_df <- filtered_map_df[-excluded_rows, , drop = FALSE]
        }
      }
    }
    
    updateSelectizeInput(session, "bio_levels",
                         choices = unique(filtered_map_df$Biological_Group),
                         selected = unique(filtered_map_df$Biological_Group), server = TRUE)
    updateSelectizeInput(session, "exp_levels",
                         choices = unique(filtered_map_df$Experimental_Group),
                         selected = unique(filtered_map_df$Experimental_Group), server = TRUE)
  })
  
  # Automatically prompt for mapping confirmation when a new, unseen dataset is uploaded
  observeEvent(current_data_file(), {
    req(current_data_file())
    
    # Reset analysis flag when new file is uploaded
    values$analysis_has_run <- FALSE
    
    # Reset deduplication flag when new file is uploaded
    values$deduplication_applied <- FALSE
    
    # Reset column selections when new file is uploaded to prevent misalignment
    # This ensures old column indices don't get applied to new file structure
    values$accession_id_column <- NULL
    values$feature_name_column <- NULL
    values$ignore_columns <- NULL
    
    # CRITICAL: Reset all dual grouping state to ensure clean slate between runs
    # This prevents state contamination when switching between simple and complex experiments
    reset_dual_grouping_state("new data file uploaded")
    
    # Also clear analysis caches to prevent stale results
    clear_analysis_caches("new data file uploaded")
    
    # Try to read only headers to avoid heavy processing
    df_head <- tryCatch({
      if (grepl("\\.csv$", tolower(current_data_file()$name))) {
        utils::read.csv(current_data_file()$datapath, nrows = 1, check.names = FALSE, stringsAsFactors = FALSE)
      } else {
        readxl::read_excel(current_data_file()$datapath, .name_repair = "minimal", n_max = 1)
      }
    }, error = function(e) NULL)
    if (is.null(df_head)) return()
    
    # Also read the full data for immediate display in Raw Data tab
    full_df <- tryCatch({
      if (grepl("\\.csv$", tolower(current_data_file()$name))) {
        utils::read.csv(current_data_file()$datapath, check.names = FALSE, stringsAsFactors = FALSE)
      } else {
        readxl::read_excel(current_data_file()$datapath, .name_repair = "minimal")
      }
    }, error = function(e) NULL)
    
    # Store the full data for immediate display
    if (!is.null(full_df)) {
      values$original_unfiltered_data <- full_df
    }
    
    header_groups <- colnames(df_head)[-1]
    if (length(header_groups) == 0) return()
    cleaned_sample_cols <- stringr::str_replace(header_groups, "\\.\\.\\..*$", "")
    values$pending_sample_names <- cleaned_sample_cols
    
    # Check for metadata sheet if Excel file
    metadata_from_sheet <- NULL
    if (!grepl("\\.csv$", tolower(current_data_file()$name))) {
      tryCatch({
        sheet_names <- readxl::excel_sheets(current_data_file()$datapath)
        if (length(sheet_names) >= 2) {
          metadata_sheet <- readxl::read_excel(current_data_file()$datapath, sheet = 2, .name_repair = "minimal")
          metadata_cols <- tolower(colnames(metadata_sheet))
          
          # Check if it looks like metadata using flexible column matching
          has_sample <- any(grepl("^sample$|sample$", metadata_cols))
          has_bio_group <- !is.na(find_group_column(colnames(metadata_sheet), "biological"))
          has_exp_group <- !is.na(find_group_column(colnames(metadata_sheet), "experimental"))
          
          if (has_sample && (has_bio_group || has_exp_group)) {
            metadata_from_sheet <- as.data.frame(metadata_sheet)
            
            showNotification(paste("Found metadata sheet:", sheet_names[2],
                                   "with", nrow(metadata_sheet), "samples"),
                             type = "message", duration = 4)
          }
        }
      }, error = function(e) {
        # Silently ignore
      })
    }
    
    det <- detect_hierarchical_groups(cleaned_sample_cols)
    
    # Stable signature based only on cleaned header names
    values$current_dataset_sig <- tryCatch({
      digest::digest(cleaned_sample_cols, algo = "xxhash64")
    }, error = function(e) digest::digest(paste(Sys.time(), runif(1)), algo = "xxhash64"))
    
    # If unseen, open modal immediately and set mapping_df
    if (is.null(values$seen_datasets[[values$current_dataset_sig]])) {
      # Try to use metadata sheet first if available
      if (!is.null(metadata_from_sheet)) {
        # Match samples from data columns to metadata using flexible column matching
        sample_col_idx <- which(grepl("^sample$|sample$", tolower(colnames(metadata_from_sheet))))[1]
        bio_col_idx <- find_group_column(colnames(metadata_from_sheet), "biological")
        exp_col_idx <- find_group_column(colnames(metadata_from_sheet), "experimental")
        
        if (!is.na(sample_col_idx)) {
          metadata_samples <- as.character(metadata_from_sheet[[sample_col_idx]])
          
          # Try to match cleaned sample names with metadata
          bio_tokens <- rep("Unknown", length(cleaned_sample_cols))
          exp_tokens <- rep("None", length(cleaned_sample_cols))
          
          for (i in seq_along(cleaned_sample_cols)) {
            match_idx <- which(metadata_samples == cleaned_sample_cols[i])[1]
            if (!is.na(match_idx)) {
              if (!is.na(bio_col_idx)) {
                bio_tokens[i] <- as.character(metadata_from_sheet[[bio_col_idx]][match_idx])
              }
              if (!is.na(exp_col_idx)) {
                exp_tokens[i] <- as.character(metadata_from_sheet[[exp_col_idx]][match_idx])
              }
            }
          }
          
          values$mapping_df <- data.frame(
            Sample = cleaned_sample_cols,
            Biological_Group = bio_tokens,
            Experimental_Group = exp_tokens,
            stringsAsFactors = FALSE
          )
          
          showNotification("Group mapping loaded from metadata sheet!",
                           type = "message", duration = 4)
        } else {
          # Metadata doesn't have proper Sample column, fall back to detection
          metadata_from_sheet <- NULL
        }
      }
      
      # If no metadata or it didn't work, use automatic detection
      if (is.null(metadata_from_sheet)) {
        bio_tokens <- det$biological
        if (is.null(bio_tokens) ||
            length(bio_tokens) != length(cleaned_sample_cols) ||
            all(is.na(bio_tokens) | trimws(as.character(bio_tokens)) == "")) {
          bio_tokens <- rep("Unknown", length(cleaned_sample_cols))
        }
        
        exp_tokens <- det$experimental
        if (!isTRUE(det$is_complex) ||
            is.null(exp_tokens) ||
            length(exp_tokens) != length(cleaned_sample_cols) ||
            all(is.na(exp_tokens) | trimws(as.character(exp_tokens)) == "")) {
          exp_tokens <- rep("None", length(cleaned_sample_cols))
        }
        
        values$mapping_df <- data.frame(
          Sample = cleaned_sample_cols,
          Biological_Group = bio_tokens,
          Experimental_Group = exp_tokens,
          stringsAsFactors = FALSE
        )
      }
      
      values$auto_mapping <- det
      values$final_biological_groups <- NULL
      values$final_experimental_groups <- NULL
      values$mapping_confirmed <- FALSE
      
      # Get full column names for column selection
      data_columns <- colnames(df_head)
      
      # NOTE: Duplicate feature check is now performed AFTER group mapping is confirmed
      # This allows users to select the correct feature column before deduplication
      # See the mapping_confirm observeEvent handler for the duplicate check logic
      
      # Capture initial mapping state for reset (per modal open)
      values$mapping_initial_state <- list(
        df = values$mapping_df,
        bio_levels = unique(values$mapping_df$Biological_Group),
        exp_levels = unique(values$mapping_df$Experimental_Group)
      )
      # Get is_metabolomics_data with safe default
      is_metabo <- isTRUE(input$is_metabolomics_data)
      showModal(build_group_mapping_modal(values$mapping_df, det, data_columns, is_metabo))
      updateSelectizeInput(session, "bio_levels", choices = unique(values$mapping_df$Biological_Group), selected = unique(values$mapping_df$Biological_Group), server = TRUE)
      updateSelectizeInput(session, "exp_levels", choices = unique(values$mapping_df$Experimental_Group), selected = unique(values$mapping_df$Experimental_Group), server = TRUE)
    } else {
      # Dataset has been seen before - restore the mapping silently
      seen_map <- values$seen_datasets[[values$current_dataset_sig]]
      
      # Re-extract biological and experimental groups for current dataset to ensure correct length
      # This is necessary because different datasets may have different numbers of samples
      bio_tokens <- det$biological
      if (!isTRUE(det$is_complex) ||
          is.null(bio_tokens) ||
          length(bio_tokens) != length(cleaned_sample_cols) ||
          all(is.na(bio_tokens) | trimws(as.character(bio_tokens)) == "")) {
        bio_tokens <- rep("None", length(cleaned_sample_cols))
      }
      
      exp_tokens <- det$experimental
      if (!isTRUE(det$is_complex) ||
          is.null(exp_tokens) ||
          length(exp_tokens) != length(cleaned_sample_cols) ||
          all(is.na(exp_tokens) | trimws(as.character(exp_tokens)) == "")) {
        exp_tokens <- rep("None", length(cleaned_sample_cols))
      }
      
      values$final_biological_groups <- bio_tokens
      values$final_experimental_groups <- exp_tokens
      values$mapping_confirmed <- TRUE
      values$auto_mapping <- det
      
      # Also restore the mapping_df for consistency with current dataset size
      values$mapping_df <- data.frame(
        Sample = cleaned_sample_cols,
        Biological_Group = bio_tokens,
        Experimental_Group = exp_tokens,
        stringsAsFactors = FALSE
      )
      
      # Display raw data table with fade transition from splash image
      # Using absolute positioning, so no need to set display block
      # Just add fade classes to trigger CSS transitions
      shinyjs::delay(50, {
        shinyjs::addClass(id = "rawDataSplash", class = "fade-out")
        shinyjs::addClass(id = "rawDataTableWrapper", class = "fade-in")
      })
      
      showNotification("Dataset recognized. Previous group mapping restored.", type = "message", duration = 3)
    }
  })
  
  # Render mapping table inside modal
  output$mapping_table <- rhandsontable::renderRHandsontable({
    req(values$mapping_df)
    
    # Filter out samples that correspond to feature/accession/ignored columns
    filtered_mapping <- values$mapping_df
    
    # Get columns to exclude from mapping
    cols_to_exclude <- c()
    if (!is.null(input$feature_name_column) && as.integer(input$feature_name_column) > 0) {
      cols_to_exclude <- c(cols_to_exclude, as.integer(input$feature_name_column))
    }
    if (!is.null(input$accession_id_column) && length(input$accession_id_column) > 0) {
      id_cols <- as.integer(input$accession_id_column[input$accession_id_column != "0"])
      if (length(id_cols) > 0) {
        cols_to_exclude <- c(cols_to_exclude, id_cols)
      }
    }
    if (!is.null(input$ignore_columns) && length(input$ignore_columns) > 0) {
      cols_to_exclude <- c(cols_to_exclude, as.integer(input$ignore_columns))
    }
    
    # Remove duplicates and sort
    cols_to_exclude <- unique(cols_to_exclude)
    
    # Only show sample columns (exclude metadata columns)
    # Columns in the Excel: 1=feature, 2+ could be accession/ID columns, rest are samples
    # Use row indices instead of names to avoid duplicate-name collisions
    if (length(cols_to_exclude) > 0 && nrow(filtered_mapping) > 0) {
      excluded_rows <- as.integer(cols_to_exclude) - 1
      excluded_rows <- excluded_rows[excluded_rows >= 1 & excluded_rows <= nrow(filtered_mapping)]
      if (length(excluded_rows) > 0) {
        filtered_mapping <- filtered_mapping[-excluded_rows, , drop = FALSE]
      }
    }
    
    # Wait briefly for level inputs to be available after modal opens
    bio_levels <- input$bio_levels
    exp_levels <- input$exp_levels
    if (is.null(bio_levels) && is.null(exp_levels)) {
      bio_levels <- unique(filtered_mapping$Biological_Group)
      exp_levels <- unique(filtered_mapping$Experimental_Group)
    } else {
      if (is.null(bio_levels) || length(bio_levels) == 0) bio_levels <- unique(filtered_mapping$Biological_Group)
      if (is.null(exp_levels) || length(exp_levels) == 0) exp_levels <- unique(filtered_mapping$Experimental_Group)
    }
    
    rhandsontable::rhandsontable(filtered_mapping, rowHeaders = NULL, stretchH = "all", width = "100%") %>%
      rhandsontable::hot_col("Sample", readOnly = TRUE) %>%
      rhandsontable::hot_col("Biological_Group", type = "dropdown", source = bio_levels) %>%
      rhandsontable::hot_col("Experimental_Group", type = "dropdown", source = exp_levels)
  })
  # Keep table rendering even if modal toggles visibility
  outputOptions(output, "mapping_table", suspendWhenHidden = FALSE)
  
  # Update group levels when column selections change (to exclude metadata columns)
  observeEvent(c(input$feature_name_column, input$accession_id_column, input$ignore_columns), {
    req(values$mapping_df)
    
    # Filter mapping_df to exclude metadata columns
    filtered_map_df <- values$mapping_df
    
    cols_to_exclude <- c()
    if (!is.null(input$feature_name_column) && as.integer(input$feature_name_column) > 0) {
      cols_to_exclude <- c(cols_to_exclude, as.integer(input$feature_name_column))
    }
    if (!is.null(input$accession_id_column) && length(input$accession_id_column) > 0) {
      id_cols <- as.integer(input$accession_id_column[input$accession_id_column != "0"])
      if (length(id_cols) > 0) {
        cols_to_exclude <- c(cols_to_exclude, id_cols)
      }
    }
    if (!is.null(input$ignore_columns) && length(input$ignore_columns) > 0) {
      cols_to_exclude <- c(cols_to_exclude, as.integer(input$ignore_columns))
    }
    
    cols_to_exclude <- unique(cols_to_exclude)
    
    if (length(cols_to_exclude) > 0 && nrow(filtered_map_df) > 0) {
      excluded_rows <- as.integer(cols_to_exclude) - 1
      excluded_rows <- excluded_rows[excluded_rows >= 1 & excluded_rows <= nrow(filtered_map_df)]
      if (length(excluded_rows) > 0) {
        filtered_map_df <- filtered_map_df[-excluded_rows, , drop = FALSE]
      }
    }
    
    # Update the group level choices in Step 2
    updateSelectizeInput(session, "bio_levels",
                         choices = unique(filtered_map_df$Biological_Group),
                         selected = unique(filtered_map_df$Biological_Group),
                         server = TRUE)
    updateSelectizeInput(session, "exp_levels",
                         choices = unique(filtered_map_df$Experimental_Group),
                         selected = unique(filtered_map_df$Experimental_Group),
                         server = TRUE)
  }, ignoreInit = TRUE)
  
  # Reset mapping to auto-detected
  observeEvent(input$mapping_reset, {
    # Reset to the mapping state that was loaded when the modal opened
    if (!is.null(values$mapping_initial_state) && !is.null(values$mapping_initial_state$df)) {
      values$mapping_df <- values$mapping_initial_state$df
      updateSelectizeInput(session, "bio_levels",
                           choices = values$mapping_initial_state$bio_levels,
                           selected = values$mapping_initial_state$bio_levels,
                           server = TRUE)
      updateSelectizeInput(session, "exp_levels",
                           choices = values$mapping_initial_state$exp_levels,
                           selected = values$mapping_initial_state$exp_levels,
                           server = TRUE)
      values$mapping_df <- values$mapping_df
      return()
    }
    # Fallback to auto-detected mapping if no initial state is available
    req(values$auto_mapping)
    samples <- values$mapping_df$Sample
    det <- values$auto_mapping
    # Prefill biological groups; if detection is empty, use a placeholder
    bio_tokens <- det$biological
    if (is.null(bio_tokens) ||
        length(bio_tokens) != length(samples) ||
        all(is.na(bio_tokens) | trimws(as.character(bio_tokens)) == "")) {
      bio_tokens <- rep("Unknown", length(samples))
    }
    values$mapping_df$Biological_Group <- bio_tokens
    # Prefill experimental groups; for simple designs, use a default placeholder
    exp_tokens <- det$experimental
    if (!isTRUE(det$is_complex) ||
        is.null(exp_tokens) ||
        length(exp_tokens) != length(samples) ||
        all(is.na(exp_tokens) | trimws(as.character(exp_tokens)) == "")) {
      exp_tokens <- rep("None", length(samples))
    }
    values$mapping_df$Experimental_Group <- exp_tokens
    # Reset the level lists to the detected unique values
    updateSelectizeInput(session, "bio_levels", choices = unique(values$mapping_df$Biological_Group), selected = unique(values$mapping_df$Biological_Group), server = TRUE)
    updateSelectizeInput(session, "exp_levels", choices = unique(values$mapping_df$Experimental_Group), selected = unique(values$mapping_df$Experimental_Group), server = TRUE)
    # Trigger re-render
    values$mapping_df <- values$mapping_df
  })
  
  # Handle duplicate resolution choice
  observeEvent(input$duplicate_confirm, {
    req(values$original_data_with_duplicates, input$duplicate_handling_choice)
    
    # Get the original data with duplicates
    full_df <- values$original_data_with_duplicates
    choice <- input$duplicate_handling_choice
    
    # Validate that we have data
    if (is.null(full_df) || nrow(full_df) == 0 || ncol(full_df) == 0) {
      showNotification("Error: No data available for deduplication.", type = "error", duration = 5)
      return()
    }
    
    # Use the user-selected feature column (stored during mapping_confirm)
    # If not set, fall back to column 1 for backward compatibility
    feature_col_idx <- values$duplicate_feature_column_idx %||% 1
    
    # Validate feature column index
    if (feature_col_idx < 1 || feature_col_idx > ncol(full_df)) {
      showNotification(paste("Error: Invalid feature column index", feature_col_idx), type = "error", duration = 5)
      return()
    }
    
    # Apply the chosen duplicate resolution method using the correct feature column
    if (choice == "first") {
      # Keep first occurrence only
      tryCatch({
        full_df <- full_df[!duplicated(full_df[[feature_col_idx]]), ]
        showNotification("Kept first occurrence of each duplicate feature.", type = "message", duration = 3)
      }, error = function(e) {
        showNotification(paste("Error in 'keep first' method:", e$message), type = "error", duration = 5)
        return()
      })
    } else if (choice == "remove_all") {
      # Remove all duplicates
      tryCatch({
        duplicate_names <- unique(full_df[[feature_col_idx]][duplicated(full_df[[feature_col_idx]])])
        full_df <- full_df[!full_df[[feature_col_idx]] %in% duplicate_names, ]
        showNotification("Removed all duplicate features.", type = "message", duration = 3)
      }, error = function(e) {
        showNotification(paste("Error in 'remove all' method:", e$message), type = "error", duration = 5)
        return()
      })
    } else if (choice == "sum") {
      # Consolidate by summing values using the user-selected feature column
      tryCatch({
        feature_col <- full_df[[feature_col_idx]]
        
        # Get all column indices except the feature column
        other_col_indices <- setdiff(seq_len(ncol(full_df)), feature_col_idx)
        data_cols <- full_df[, other_col_indices, drop = FALSE]
        
        # Group by feature name and sum numeric columns
        summed_data <- aggregate(data_cols, by = list(Feature = feature_col), FUN = function(x) {
          if (is.numeric(x)) sum(x, na.rm = TRUE) else x[1]  # Sum numeric, keep first for non-numeric
        })
        
        # Reconstruct the data frame with feature column in the correct position
        feature_col_name <- colnames(full_df)[feature_col_idx]
        result_df <- summed_data
        colnames(result_df)[1] <- feature_col_name
        
        # Reorder columns to put feature column back in original position
        if (feature_col_idx > 1) {
          # Feature column was not first, need to reorder
          new_order <- c(2:feature_col_idx, 1, (feature_col_idx + 1):ncol(result_df))
          new_order <- new_order[new_order <= ncol(result_df)]
          result_df <- result_df[, new_order, drop = FALSE]
        }
        
        full_df <- result_df
        showNotification("Consolidated duplicate features by summing values.", type = "message", duration = 3)
      }, error = function(e) {
        showNotification(paste("Error in 'sum' method:", e$message), type = "error", duration = 5)
        return()
      })
    } else if (choice == "suffix") {
      # Add number suffixes to duplicates
      tryCatch({
        # Validate feature column index
        if (is.null(feature_col_idx) || length(feature_col_idx) != 1 ||
            is.na(feature_col_idx) || feature_col_idx < 1 || feature_col_idx > ncol(full_df)) {
          showNotification("Error: Invalid feature column selection for suffix method.", type = "error", duration = 5)
          return()
        }

        feature_col <- as.character(full_df[[feature_col_idx]])
        
        # Remove empty strings from feature_col for counting duplicates
        # but keep track of which ones were empty
        empty_indices <- is.na(feature_col) | (!is.na(feature_col) & trimws(feature_col) == "")
        non_empty_col <- feature_col
        non_empty_col[empty_indices] <- NA_character_
        
        feature_counts <- table(non_empty_col, useNA = "no")
        
        # Check if we have any valid features
        if (length(feature_counts) == 0) {
          showNotification("Error: No valid features found for suffix method.", type = "error", duration = 5)
          return()
        }
        
        new_feature_col <- character(length(feature_col))
        counters <- list()  # Track current counter for each feature name
        
        for (i in seq_along(feature_col)) {
          name <- feature_col[i]
          
          # Skip NA and empty values - keep as is
          if (is.na(name) || (!is.na(name) && trimws(name) == "")) {
            new_feature_col[i] <- name
            next
          }
          
          # Get the count for this name
          name_count <- feature_counts[name]
          
          # Check if this name exists in feature_counts and has count > 1
          if (length(name_count) == 0 || is.na(name_count) || !is.finite(name_count)) {
            # Name not found or count is NA, keep as is
            new_feature_col[i] <- name
            next
          }
          
          # If this feature appears more than once, add suffix
          if (name_count > 1) {
            if (!(name %in% names(counters))) {
              counters[[name]] <- 1
            } else {
              counters[[name]] <- counters[[name]] + 1
            }
            new_feature_col[i] <- paste0(name, "_", counters[[name]])
          } else {
            # Feature doesn't have duplicates, keep as is
            new_feature_col[i] <- name
          }
        }
        
        # Replace the feature column with the renamed version
        full_df[[feature_col_idx]] <- new_feature_col
        
        # Special handling for metabolomics search names: exclude suffixes
        if (input$is_metabolomics_data) {
          # Store original names without suffixes for search purposes
          original_search_names <- sapply(new_feature_col, function(name) {
            # Remove suffix if it exists (everything after last underscore followed by digits)
            sub("_[0-9]+$", "", name)
          })
          values$metabolomics_search_names <- original_search_names
          showNotification("Added number suffixes to duplicate features. Metabolomics search names exclude suffixes.", type = "message", duration = 4)
        } else {
          showNotification("Added number suffixes to duplicate features.", type = "message", duration = 3)
        }
      }, error = function(e) {
        showNotification(paste("Error in 'add suffixes' method:", e$message), type = "error", duration = 5)
        return()
      })
    }
    
    # Update the stored data
    values$original_unfiltered_data <- full_df
    values$original_data_with_duplicates <- NULL  # Clear the duplicate data
    values$duplicate_feature_names <- NULL
    values$duplicate_feature_column_idx <- NULL  # Clear the feature column index
    values$deduplication_applied <- TRUE  # Flag that deduplication was completed
    
    # Remove the modal
    removeModal()
    
    # =========================================================================
    # RESUME MAPPING CONFIRMATION AFTER DUPLICATE HANDLING
    # =========================================================================
    # Since duplicate handling now happens AFTER the group mapping modal,
    # we need to continue with the rest of the mapping confirmation process
    # instead of showing the group mapping modal again
    
    if (isTRUE(values$pending_mapping_confirmed)) {
      # Restore the pending mapping state and trigger continuation
      map_df <- values$pending_mapping_df
      values$pending_mapping_df <- NULL
      values$pending_mapping_confirmed <- NULL
      
      # Trigger the rest of the mapping_confirm logic by simulating a click
      # We use shinyjs to programmatically click the confirm button
      # But since we're in a different observer, we'll just set a flag
      values$resume_after_dedup <- TRUE
      
      # Also store the mapping data for continuation
      values$mapping_df <- map_df
    } else {
      # Fallback for backward compatibility: show group mapping modal
      # This handles cases where duplicate handling was triggered before group mapping
      data_columns <- colnames(full_df)
      showModal(build_group_mapping_modal(values$mapping_df, values$auto_mapping, data_columns, input$is_metabolomics_data))
      updateSelectizeInput(session, "bio_levels", choices = unique(values$mapping_df$Biological_Group), selected = unique(values$mapping_df$Biological_Group), server = TRUE)
      updateSelectizeInput(session, "exp_levels", choices = unique(values$mapping_df$Experimental_Group), selected = unique(values$mapping_df$Experimental_Group), server = TRUE)
    }
  })
  
  # =========================================================================
  # OBSERVER TO CONTINUE MAPPING AFTER DUPLICATE RESOLUTION
  # =========================================================================
  observeEvent(values$resume_after_dedup, {
    req(isTRUE(values$resume_after_dedup))
    values$resume_after_dedup <- FALSE  # Reset the flag
    
    map_df <- values$mapping_df
    req(!is.null(map_df), nrow(map_df) > 0)
    
    # Continue with the rest of the mapping_confirm logic
    # The duplicate handling is already done at this point
    # We need to finalize the mapping and proceed with data processing
    
    # Store final groups from the mapping table
    values$final_biological_groups <- as.character(map_df$Biological_Group)
    values$final_experimental_groups <- as.character(map_df$Experimental_Group)
    values$mapping_confirmed <- TRUE
    
    # Show notification about successful duplicate resolution and mapping
    showNotification("Duplicate features resolved. Group mapping confirmed.", type = "message", duration = 3)
    
    # Trigger data processing by invalidating caches
    values$pca_cache <- list()
    values$spca_cache <- list()
    values$processing_cache <- list()
    values$statistical_cache <- list()
    values$dual_analysis_cache <- list()
    
    # Build group indices from biological labels
    bio_labels <- values$final_biological_groups
    bio_unique <- unique(bio_labels)
    values$unique_groups <- bio_unique
    values$unique_groups_original <- values$unique_groups
    
    # Create group column indices
    values$group_column_indices <- lapply(values$unique_groups, function(g) {
      which(bio_labels == g)
    })
    
    # Update UI selections (include lmROTS/lmeROTS variable names when present)
    g1_choices <- values$unique_groups
    tryCatch({
      av <- get_available_comparison_names()
      vv <- av[grepl("^(lmROTS|lmeROTS)_", av)]
      if (length(vv) > 0) g1_choices <- c(g1_choices, vv)
    }, error = function(e) NULL)
    updateSelectizeInput(session, "group1", choices = g1_choices, selected = g1_choices[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "group2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    updateSelectizeInput(session, "pcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "pcaGroup2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    updateSelectizeInput(session, "diffGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "diffGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
    
    # Display raw data table
    shinyjs::delay(50, {
      shinyjs::addClass(id = "rawDataSplash", class = "fade-out")
      shinyjs::addClass(id = "rawDataTableWrapper", class = "fade-in")
    })
    
    # Persist mapping for this dataset
    if (!is.null(values$current_dataset_sig)) {
      values$seen_datasets[[values$current_dataset_sig]] <- list(
        biological = values$final_biological_groups,
        experimental = values$final_experimental_groups
      )
    }
    
    # =========================================================================
    # DUAL GROUPING LEVEL DETECTION AND SETUP (after dedup)
    # =========================================================================
    # Check if biological and experimental groups are meaningfully different
    exp_labels <- values$final_experimental_groups
    
    exp_unique <- unique(exp_labels)
    
    # Determine if dual grouping should be enabled
    bio_has_groups <- length(bio_unique) >= 2
    exp_has_groups <- length(exp_unique) >= 2
    groups_are_different <- !setequal(bio_unique, exp_unique) || !all(bio_labels == exp_labels)
    
    # Exclude trivial experimental groups like "None", "NA", "All"
    trivial_exp <- length(exp_unique) == 1 && tolower(trimws(exp_unique[1])) %in% c("none", "na", "", "all", "n/a")
    
    was_dual_grouping <- isTRUE(values$has_dual_grouping)
    
    if (bio_has_groups && exp_has_groups && groups_are_different && !trivial_exp) {
      # Enable dual grouping
      values$has_dual_grouping <- TRUE
      values$active_grouping_level <- "biological"  # Default to biological
      
      if (!was_dual_grouping) {
        # Reset pairwise selection state when switching from simple to dual grouping
        values$pairwise_order <- NULL
        values$skip_pairwise_selection <- FALSE
        values$pairwise_selection_confirmed <- FALSE
        values$selected_pairwise_for_analysis <- NULL
        values$current_pairwise_combinations <- NULL
        values$preanalysis_pairwise_combinations <- NULL
        values$preanalysis_bio_pairwise_combinations <- NULL
        values$preanalysis_exp_pairwise_combinations <- NULL
        values$pending_pairwise_confirmation <- FALSE
        values$biological_pairwise_combinations <- NULL
        values$experimental_pairwise_combinations <- NULL
      }
      
      # Store biological grouping data
      values$biological_groups <- bio_labels
      values$biological_unique_groups <- bio_unique
      values$biological_group_column_indices <- lapply(bio_unique, function(g) {
        indices <- which(bio_labels == g)
        # Validate indices
        if (!is.null(values$normalized_data)) {
          max_col_index <- ncol(values$normalized_data)
          valid_indices <- indices[indices > 0 & indices <= max_col_index]
          return(valid_indices)
        }
        return(indices)
      })
      
      # Store experimental grouping data
      values$experimental_groups <- exp_labels
      values$experimental_unique_groups <- exp_unique
      values$experimental_group_column_indices <- lapply(exp_unique, function(g) {
        indices <- which(exp_labels == g)
        # Validate indices
        if (!is.null(values$normalized_data)) {
          max_col_index <- ncol(values$normalized_data)
          valid_indices <- indices[indices > 0 & indices <= max_col_index]
          return(valid_indices)
        }
        return(indices)
      })
      
      message(sprintf("Dual grouping enabled: %d biological groups, %d experimental groups",
                      length(bio_unique), length(exp_unique)))
      showNotification(
        sprintf("Dual grouping detected: %d biological groups, %d experimental groups. Use toggle buttons to switch views.",
                length(bio_unique), length(exp_unique)),
        type = "message", duration = 5
      )
    } else {
      # Single grouping mode (use biological groups as default)
      values$has_dual_grouping <- FALSE
      values$active_grouping_level <- "biological"
      
      # COMPREHENSIVE cleanup of ALL dual grouping data to prevent state contamination
      # This is critical when switching from complex to simple experiments
      values$biological_groups <- NULL
      values$experimental_groups <- NULL
      values$biological_unique_groups <- NULL
      values$experimental_unique_groups <- NULL
      values$biological_group_column_indices <- NULL
      values$experimental_group_column_indices <- NULL
      values$biological_stat_results <- NULL
      values$experimental_stat_results <- NULL
      values$biological_pairwise_combinations <- NULL
      values$experimental_pairwise_combinations <- NULL
      values$biological_normalized_data <- NULL
      values$experimental_normalized_data <- NULL
      
      # Clear dual analysis tracking state
      values$dual_analysis_in_progress <- FALSE
      values$dual_analysis_current_level <- NULL
      values$dual_analysis_trigger_rerun <- NULL
      
      # Clear dual analysis cache to prevent restoration of stale results
      values$dual_analysis_cache <- list()
      values$dual_analysis_cache_signature <- NULL
      
      # Clear pre-analysis dual grouping pairwise selections
      values$preanalysis_bio_pairwise_combinations <- NULL
      values$preanalysis_exp_pairwise_combinations <- NULL
      values$pairwise_selection_confirmed <- FALSE
      values$skip_pairwise_selection <- FALSE
      values$selected_pairwise_for_analysis <- NULL
      values$current_pairwise_combinations <- NULL
      
      message("Single grouping mode (first section): cleared all dual grouping state")
    }
    # =========================================================================
    # END DUAL GROUPING LEVEL DETECTION
    # =========================================================================
    
    # =========================================================================
    # SHOW PRE-ANALYSIS PAIRWISE SELECTION MODAL (matching mapping_confirm flow)
    # =========================================================================
    # Show pre-analysis pairwise selection modal if there are 2+ groups
    # and the user hasn't chosen to skip this step
    if (length(values$unique_groups) >= 2 && !isTRUE(values$skip_pairwise_selection)) {
      # Generate default pairwise combinations
      all_possible <- get_all_possible_pairwise_combinations()
      
      if (!is.null(all_possible) && nrow(all_possible) > 0) {
        # Initialize the pre-analysis pairwise combinations
        values$preanalysis_pairwise_combinations <- all_possible
        values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
        values$pending_pairwise_confirmation <- TRUE
        
        # Initialize dual grouping pairwise combinations if dual grouping is active
        if (isTRUE(values$has_dual_grouping)) {
          # Generate biological group pairwise combinations
          bio_groups <- values$biological_unique_groups
          if (!is.null(bio_groups) && length(bio_groups) >= 2) {
            bio_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
            for (i in 1:(length(bio_groups) - 1)) {
              for (j in (i + 1):length(bio_groups)) {
                bio_combos <- rbind(bio_combos, data.frame(
                  Group_1 = bio_groups[i], Group_2 = bio_groups[j], stringsAsFactors = FALSE))
              }
            }
            values$preanalysis_bio_pairwise_combinations <- bio_combos
            values$preanalysis_bio_ui_version <- (values$preanalysis_bio_ui_version %||% 0) + 1
          }
          
          # Generate experimental group pairwise combinations
          exp_groups <- values$experimental_unique_groups
          if (!is.null(exp_groups) && length(exp_groups) >= 2) {
            exp_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
            for (i in 1:(length(exp_groups) - 1)) {
              for (j in (i + 1):length(exp_groups)) {
                exp_combos <- rbind(exp_combos, data.frame(
                  Group_1 = exp_groups[i], Group_2 = exp_groups[j], stringsAsFactors = FALSE))
              }
            }
            values$preanalysis_exp_pairwise_combinations <- exp_combos
            values$preanalysis_exp_ui_version <- (values$preanalysis_exp_ui_version %||% 0) + 1
          }
          
          showNotification("Dual grouping detected. Configure comparisons for both grouping levels.", type = "message", duration = 4)
        } else {
          showNotification("Deduplication complete. Configure pairwise comparisons for analysis.", type = "message", duration = 3)
        }
        
        # Open the pre-analysis pairwise selection modal
        shinyBS::toggleModal(session, "preAnalysisPairwiseModal", toggle = "open")
      } else {
        # Only one group or no valid combinations, proceed directly
        showNotification("Deduplication complete. Raw data displayed.", type = "message", duration = 5)
      }
    } else {
      # Skip pairwise selection (either user preference or only one group)
      if (length(values$unique_groups) >= 2) {
        # Set default pairwise combinations for analysis
        values$selected_pairwise_for_analysis <- get_all_possible_pairwise_combinations()
        values$pairwise_selection_confirmed <- TRUE
      }
      showNotification("Deduplication complete. Raw data displayed.", type = "message", duration = 5)
    }
  })
  
  # Confirm mapping and resume processing if pending
  observeEvent(input$mapping_confirm, {
    # Capture edits
    tbl <- input$mapping_table
    if (!is.null(tbl)) {
      values$mapping_df <- rhandsontable::hot_to_r(tbl)
    }
    map_df <- values$mapping_df
    req(!is.null(map_df), nrow(map_df) > 0)
    
    # Store column selections for later use
    values$feature_name_column <- as.integer(input$feature_name_column %||% 1)
    # Handle multiple ID columns - filter out 0 ("None") selection
    id_cols <- input$accession_id_column %||% 0
    values$accession_id_column <- if (!is.null(id_cols) && length(id_cols) > 0) {
      as.integer(id_cols[id_cols != "0"])
    } else {
      NULL
    }
    values$ignore_columns <- if(!is.null(input$ignore_columns)) as.integer(input$ignore_columns) else NULL
    
    # Remove accession columns from mapping if selected (use adjusted indices to avoid name shifts)
    if (!is.null(values$accession_id_column) && !is.null(values$raw_data)) {
      acc_cols <- as.integer(values$accession_id_column)
      if (!is.null(values$ignore_columns) && length(values$ignore_columns) > 0) {
        acc_cols <- acc_cols - vapply(acc_cols, function(ac) sum(values$ignore_columns < ac), integer(1))
      }
      acc_cols <- acc_cols[acc_cols > 0 & acc_cols <= ncol(values$raw_data)]
      values$accession_id_column_adjusted <- acc_cols

      if (length(acc_cols) > 0) {
        accession_names <- colnames(values$raw_data)[acc_cols]
        map_df <- map_df[!map_df$Sample %in% accession_names, , drop = FALSE]
        values$mapping_df <- map_df
      }
    }

    
    # =========================================================================
    # CHECK FOR DUPLICATE FEATURE NAMES USING USER-SELECTED FEATURE COLUMN
    # =========================================================================
    # This check happens AFTER the user has selected the correct feature column
    # instead of assuming column 1 is the feature column
    
    feature_col_idx <- values$feature_name_column
    if (!is.null(values$original_unfiltered_data) && 
        feature_col_idx > 0 && 
        feature_col_idx <= ncol(values$original_unfiltered_data)) {
      
      feature_values <- values$original_unfiltered_data[[feature_col_idx]]
      duplicate_features <- duplicated(feature_values)
      
      if (any(duplicate_features)) {
        # Store original data and mapping info for duplicate handling
        values$original_data_with_duplicates <- values$original_unfiltered_data
        values$duplicate_feature_names <- unique(feature_values[duplicate_features])
        values$duplicate_feature_column_idx <- feature_col_idx
        
        # Store the mapping confirmation state to resume after duplicate handling
        values$pending_mapping_df <- map_df
        values$pending_mapping_confirmed <- TRUE
        
        # Close the group mapping modal and show duplicate handling modal
        removeModal()
        showModal(build_duplicate_handling_modal(values$duplicate_feature_names))
        return()  # Exit early, wait for user's duplicate handling choice
      }
    }
    # =========================================================================
    # END DUPLICATE CHECK
    # =========================================================================
    
    # OPTIMIZATION #6: Check if metabolomics data and pre-warm cache if needed
    # Use the column information user already specified
    feature_col_name <- NULL
    id_col_names <- NULL
    
    # Get column names from original data
    if (!is.null(values$original_unfiltered_data) && ncol(values$original_unfiltered_data) > 0) {
      all_cols <- colnames(values$original_unfiltered_data)
      
      # Get feature column name
      feature_idx <- as.integer(input$feature_name_column %||% 1)
      if (feature_idx > 0 && feature_idx <= length(all_cols)) {
        feature_col_name <- all_cols[feature_idx]
      }
      
      # Get ID column names (multiple)
      id_indices <- values$accession_id_column
      if (!is.null(id_indices) && length(id_indices) > 0) {
        id_col_names <- all_cols[id_indices[id_indices > 0 & id_indices <= length(all_cols)]]
      }
    }
    
    # Detect if this is metabolomics data based on user's selections
    is_metab <- detect_metabolomics_data(
      feature_col_name = feature_col_name,
      id_col_name = if (!is.null(id_col_names)) id_col_names[1] else NULL,
      data_columns = if (!is.null(values$original_unfiltered_data)) colnames(values$original_unfiltered_data) else NULL
    )
    
    if (is_metab && !file.exists("metabolites.db")) {
      # Pre-warm cache for metabolomics workflow
      if (is_omics_verbose()) message("[OPTIMIZATION #6] Detected metabolomics workflow - pre-warming cache...")
      initialize_default_cache()
    }
    
    # Show notification about column selections
    if (!is.null(input$feature_name_column)) {
      col_msg <- paste0("Feature column: ", input$feature_name_column)
      if (!is.null(values$accession_id_column) && length(values$accession_id_column) > 0) {
        col_msg <- paste0(col_msg, " | ID columns: ", paste(values$accession_id_column, collapse = ", "))
      } else {
        col_msg <- paste0(col_msg, " | ID columns: Using feature names")
      }
      if (!is.null(values$ignore_columns) && length(values$ignore_columns) > 0) {
        col_msg <- paste0(col_msg, " | Ignored ", length(values$ignore_columns), " column(s)")
      }
      showNotification(col_msg, type = "message", duration = 5)
    }
    
    # Normalize empty experimental groups so blank entries behave like "None"
    if (!"Experimental_Group" %in% colnames(map_df)) {
      map_df$Experimental_Group <- rep("None", nrow(map_df))
    } else {
      exp_values <- as.character(map_df$Experimental_Group)
      exp_blank <- is.na(exp_values) | trimws(exp_values) == ""
      if (all(exp_blank)) {
        exp_values <- rep("None", length(exp_values))
      } else if (any(exp_blank)) {
        exp_values[exp_blank] <- "None"
      }
      map_df$Experimental_Group <- exp_values
    }

    # Validate that mapped values are within the declared levels
    declared_bio <- input$bio_levels
    declared_exp <- input$exp_levels

    # Get the actual groups used in the mapping table (after any user edits)
    used_bio <- unique(as.character(map_df$Biological_Group))
    used_exp <- unique(as.character(map_df$Experimental_Group))

    # If no levels declared, use what's actually in the table
    if (is.null(declared_bio) || length(declared_bio) == 0) declared_bio <- used_bio
    if (is.null(declared_exp) || length(declared_exp) == 0) declared_exp <- used_exp

    # Check for groups used in table but not declared
    missing_bio <- setdiff(used_bio, declared_bio)
    missing_exp <- setdiff(used_exp, declared_exp)

    if (length(missing_bio) > 0 || length(missing_exp) > 0) {
      msg <- paste0(
        if (length(missing_bio) > 0) paste0("Biological groups used in table but not listed: ", paste(missing_bio, collapse = ", ")) else NULL,
        if (length(missing_bio) > 0 && length(missing_exp) > 0) "; " else NULL,
        if (length(missing_exp) > 0) paste0("Experimental groups used in table but not listed: ", paste(missing_exp, collapse = ", ")) else NULL
      )
      showNotification(paste("Please add all groups used in the table to the level lists, or update the table to use declared groups.", msg), type = "error", duration = 8)
      return()
    }

    # =========================================================================
    # USER MANUAL EDITS IN THE MAPPING TABLE SUPERSEDE METADATA
    # =========================================================================
    # The mapping_df already contains any manual edits made by the user in the handsontable
    # These edits take precedence over the original metadata values
    # No additional processing needed - the table edits are already captured in map_df

    values$final_biological_groups <- as.character(map_df$Biological_Group)
    values$final_experimental_groups <- as.character(map_df$Experimental_Group)
    values$mapping_confirmed <- TRUE
    
    # =========================================================================
    # EXTRACT ID COLUMNS FOR METABOLOMICS
    # =========================================================================
    # If user specified ID columns, extract them for use in metabolomics mapping
    if (!is.null(values$accession_id_column) && length(values$accession_id_column) > 0 && 
        !is.null(values$original_unfiltered_data)) {
      
      tryCatch({
        all_cols <- colnames(values$original_unfiltered_data)
        feature_idx <- values$feature_name_column
        
        # Get feature names (first column typically)
        if (feature_idx > 0 && feature_idx <= ncol(values$original_unfiltered_data)) {
          feature_names <- as.character(values$original_unfiltered_data[[feature_idx]])
          
          # Create a data frame to store ID mappings
          id_mapping_df <- data.frame(
            feature_name = feature_names,
            stringsAsFactors = FALSE
          )
          
          # Extract each ID column
          for (id_col_idx in values$accession_id_column) {
            if (id_col_idx > 0 && id_col_idx <= length(all_cols)) {
              col_name <- all_cols[id_col_idx]
              col_data <- as.character(values$original_unfiltered_data[[id_col_idx]])
              
              # Try to detect what type of ID this column contains
              detected_type <- NULL
              sample_values <- head(col_data[col_data != "" & !is.na(col_data)], 10)
              
              if (length(sample_values) > 0) {
                sample_str <- paste(sample_values, collapse = " ")
                
                # Pattern matching for ID types
                if (grepl("C[0-9]{5}", sample_str)) {
                  detected_type <- "KEGG_ID"
                } else if (grepl("HMDB[0-9]{7}", sample_str)) {
                  detected_type <- "HMDB_ID"
                } else if (grepl("CHEBI:[0-9]+", sample_str)) {
                  detected_type <- "ChEBI_ID"
                } else if (grepl("^[0-9]+$", sample_str) && grepl("pubchem|cid", tolower(col_name))) {
                  detected_type <- "PubChem_CID"
                } else if (grepl("LM[A-Z]{2}[0-9]{8}", sample_str)) {
                  detected_type <- "LipidMaps_ID"
                } else if (grepl("kegg", tolower(col_name))) {
                  detected_type <- "KEGG_ID"
                } else if (grepl("hmdb", tolower(col_name))) {
                  detected_type <- "HMDB_ID"
                } else if (grepl("chebi", tolower(col_name))) {
                  detected_type <- "ChEBI_ID"
                } else if (grepl("lipid", tolower(col_name))) {
                  detected_type <- "LipidMaps_ID"
                }
              }
              
              # Use detected type or fallback to column name
              if (!is.null(detected_type)) {
                id_mapping_df[[detected_type]] <- col_data
                message(sprintf("Detected %s column: %s", detected_type, col_name))
              } else {
                # Store with sanitized column name
                safe_col_name <- gsub("[^A-Za-z0-9_]", "_", col_name)
                id_mapping_df[[safe_col_name]] <- col_data
                message(sprintf("Stored ID column as: %s", safe_col_name))
              }
            }
          }
          
          # Store for metabolomics use
          values$metabolite_id_columns_from_data <- id_mapping_df
          
          message(sprintf("Extracted %d ID columns for metabolomics mapping", 
                         ncol(id_mapping_df) - 1))
          
          # Update metab_id_type dropdown with actual column names
          if (ncol(id_mapping_df) > 1) {
            # Create choices list with Compound Name + actual ID columns
            id_choices <- c("Compound Name" = "name")
            
            for (col in names(id_mapping_df)) {
              if (col != "molecule_name") {
                # Use column name as both label and value
                id_choices[[col]] <- col
              }
            }
            
            updateSelectInput(session, "metab_id_type",
                            choices = id_choices,
                            selected = "name")
            
            showNotification(
              paste("Input ID Type updated with your ID columns:", 
                    paste(names(id_choices)[-1], collapse = ", ")),
              type = "message",
              duration = 5
            )
          }
        }
      }, error = function(e) {
        message("Error extracting ID columns: ", e$message)
        values$metabolite_id_columns_from_data <- NULL
      })
    } else {
      values$metabolite_id_columns_from_data <- NULL
    }
    
    removeModal()
    
    # =========================================================================
    # DUAL GROUPING LEVEL DETECTION AND SETUP
    # =========================================================================
    # Check if biological and experimental groups are meaningfully different
    # Dual grouping is enabled when:
    # 1. Both have more than one unique level
    # 2. The sets of groups are not identical
    # 3. The sample-to-group mapping is different
    
    bio_labels <- values$final_biological_groups
    exp_labels <- values$final_experimental_groups
    
    bio_unique <- unique(bio_labels)
    exp_unique <- unique(exp_labels)
    
    # Determine if dual grouping should be enabled
    bio_has_groups <- length(bio_unique) >= 2
    exp_has_groups <- length(exp_unique) >= 2
    groups_are_different <- !setequal(bio_unique, exp_unique) || !all(bio_labels == exp_labels)
    
    # Exclude trivial experimental groups like "None", "NA", "All"
    trivial_exp <- length(exp_unique) == 1 && tolower(trimws(exp_unique[1])) %in% c("none", "na", "", "all", "n/a")
    
    was_dual_grouping <- isTRUE(values$has_dual_grouping)
    
    if (bio_has_groups && exp_has_groups && groups_are_different && !trivial_exp) {
      # Enable dual grouping
      values$has_dual_grouping <- TRUE
      values$active_grouping_level <- "biological"  # Default to biological
      
      if (!was_dual_grouping) {
        # Reset pairwise selection state when switching from simple to dual grouping
        values$pairwise_order <- NULL
        values$skip_pairwise_selection <- FALSE
        values$pairwise_selection_confirmed <- FALSE
        values$selected_pairwise_for_analysis <- NULL
        values$current_pairwise_combinations <- NULL
        values$preanalysis_pairwise_combinations <- NULL
        values$preanalysis_bio_pairwise_combinations <- NULL
        values$preanalysis_exp_pairwise_combinations <- NULL
        values$pending_pairwise_confirmation <- FALSE
        values$biological_pairwise_combinations <- NULL
        values$experimental_pairwise_combinations <- NULL
      }
      
      # Store biological grouping data
      values$biological_groups <- bio_labels
      values$biological_unique_groups <- bio_unique
      values$biological_group_column_indices <- lapply(bio_unique, function(g) {
        indices <- which(bio_labels == g)
        # Validate indices
        if (!is.null(values$normalized_data)) {
          max_col_index <- ncol(values$normalized_data)
          valid_indices <- indices[indices > 0 & indices <= max_col_index]
          return(valid_indices)
        }
        return(indices)
      })
      
      # Store experimental grouping data
      values$experimental_groups <- exp_labels
      values$experimental_unique_groups <- exp_unique
      values$experimental_group_column_indices <- lapply(exp_unique, function(g) {
        indices <- which(exp_labels == g)
        # Validate indices
        if (!is.null(values$normalized_data)) {
          max_col_index <- ncol(values$normalized_data)
          valid_indices <- indices[indices > 0 & indices <= max_col_index]
          return(valid_indices)
        }
        return(indices)
      })
      
      message(sprintf("Dual grouping enabled: %d biological groups, %d experimental groups",
                      length(bio_unique), length(exp_unique)))
      showNotification(
        sprintf("Dual grouping detected: %d biological groups, %d experimental groups. Use toggle buttons to switch views.",
                length(bio_unique), length(exp_unique)),
        type = "message", duration = 5
      )
    } else {
      # Single grouping mode (use biological groups as default)
      values$has_dual_grouping <- FALSE
      values$active_grouping_level <- "biological"
      
      # COMPREHENSIVE cleanup of ALL dual grouping data to prevent state contamination
      # This is critical when switching from complex to simple experiments
      values$biological_groups <- NULL
      values$experimental_groups <- NULL
      values$biological_unique_groups <- NULL
      values$experimental_unique_groups <- NULL
      values$biological_group_column_indices <- NULL
      values$experimental_group_column_indices <- NULL
      values$biological_stat_results <- NULL
      values$experimental_stat_results <- NULL
      values$biological_pairwise_combinations <- NULL
      values$experimental_pairwise_combinations <- NULL
      values$biological_normalized_data <- NULL
      values$experimental_normalized_data <- NULL
      
      # Clear dual analysis tracking state
      values$dual_analysis_in_progress <- FALSE
      values$dual_analysis_current_level <- NULL
      values$dual_analysis_trigger_rerun <- NULL
      
      # Clear dual analysis cache to prevent restoration of stale results
      values$dual_analysis_cache <- list()
      values$dual_analysis_cache_signature <- NULL
      
      # Clear pre-analysis dual grouping pairwise selections
      values$preanalysis_bio_pairwise_combinations <- NULL
      values$preanalysis_exp_pairwise_combinations <- NULL
      values$pairwise_selection_confirmed <- FALSE
      values$skip_pairwise_selection <- FALSE
      values$selected_pairwise_for_analysis <- NULL
      values$current_pairwise_combinations <- NULL
      
      message("Single grouping mode (second section): cleared all dual grouping state")
    }
    # =========================================================================
    # END DUAL GROUPING LEVEL DETECTION
    # =========================================================================
    
    # Build group indices from biological labels and update UI selections
    # (This continues to use biological groups as the primary grouping)
    values$unique_groups <- bio_unique
    values$unique_groups_original <- values$unique_groups
    
    # Create group column indices with validation
    values$group_column_indices <- lapply(values$unique_groups, function(g) {
      indices <- which(bio_labels == g)
      # Validate indices against normalized data if available
      if (!is.null(values$normalized_data)) {
        max_col_index <- ncol(values$normalized_data)
        valid_indices <- indices[indices > 0 & indices <= max_col_index]
        if (length(valid_indices) != length(indices)) {
          warning(paste("Some column indices for group", g, "are out of bounds.",
                        "Using", length(valid_indices), "out of", length(indices), "columns."))
        }
        return(valid_indices)
      }
      return(indices)
    })
    
    # Validate that all groups have at least one valid column
    empty_groups <- sapply(values$group_column_indices, length) == 0
    if (any(empty_groups)) {
      empty_group_names <- values$unique_groups[empty_groups]
      showNotification(paste("Warning: The following groups have no valid columns:",
                             paste(empty_group_names, collapse = ", ")),
                       type = "warning", duration = 8)
    }
    
    # Update selection inputs immediately (include lmROTS/lmeROTS variable names when present)
    g1_choices <- values$unique_groups
    tryCatch({
      av <- get_available_comparison_names()
      vv <- av[grepl("^(lmROTS|lmeROTS)_", av)]
      if (length(vv) > 0) g1_choices <- c(g1_choices, vv)
    }, error = function(e) NULL)
    updateSelectizeInput(session, "group1", choices = g1_choices, selected = g1_choices[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "group2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    updateSelectizeInput(session, "pcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    if (length(values$unique_groups) > 1) {
      updateSelectizeInput(session, "pcaGroup2", choices = values$unique_groups, selected = values$unique_groups[2])
    }
    updateSelectizeInput(session, "diffGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "diffGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
    
    # Invalidate caches so analyses recompute with the confirmed mapping
    values$pca_cache <- list()
    values$spca_cache <- list()
    values$processing_cache <- list()
    values$statistical_cache <- list()
    values$dual_analysis_cache <- list()  # Clear dual analysis cache when mapping changes
    update_cache_status()
    
    # Persist mapping for this dataset signature to allow skipping confirmation next time
    if (!is.null(values$current_dataset_sig)) {
      values$seen_datasets[[values$current_dataset_sig]] <- list(
        biological = values$final_biological_groups,
        experimental = values$final_experimental_groups,
        levels = list(
          biological = input$bio_levels,
          experimental = input$exp_levels
        )
      )
    }
    
    # Display raw data table with fade transition from splash image
    # Using absolute positioning, so no need to set display block
    # Just add fade classes to trigger CSS transitions
    shinyjs::delay(50, {
      shinyjs::addClass(id = "rawDataSplash", class = "fade-out")
      shinyjs::addClass(id = "rawDataTableWrapper", class = "fade-in")
    })
    
    # Show pre-analysis pairwise selection modal if there are 2+ groups
    # and the user hasn't chosen to skip this step
    if (length(values$unique_groups) >= 2 && !isTRUE(values$skip_pairwise_selection)) {
      # Generate default pairwise combinations
      all_possible <- get_all_possible_pairwise_combinations()
      
      if (!is.null(all_possible) && nrow(all_possible) > 0) {
        # Initialize the pre-analysis pairwise combinations
        values$preanalysis_pairwise_combinations <- all_possible
        values$preanalysis_pairwise_ui_version <- (values$preanalysis_pairwise_ui_version %||% 0) + 1
        values$pending_pairwise_confirmation <- TRUE
        
        # Initialize dual grouping pairwise combinations if dual grouping is active
        if (isTRUE(values$has_dual_grouping)) {
          # Generate biological group pairwise combinations
          bio_groups <- values$biological_unique_groups
          if (!is.null(bio_groups) && length(bio_groups) >= 2) {
            bio_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
            for (i in 1:(length(bio_groups) - 1)) {
              for (j in (i + 1):length(bio_groups)) {
                bio_combos <- rbind(bio_combos, data.frame(
                  Group_1 = bio_groups[i], Group_2 = bio_groups[j], stringsAsFactors = FALSE))
              }
            }
            values$preanalysis_bio_pairwise_combinations <- bio_combos
            values$preanalysis_bio_ui_version <- (values$preanalysis_bio_ui_version %||% 0) + 1
          }
          
          # Generate experimental group pairwise combinations
          exp_groups <- values$experimental_unique_groups
          if (!is.null(exp_groups) && length(exp_groups) >= 2) {
            exp_combos <- data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
            for (i in 1:(length(exp_groups) - 1)) {
              for (j in (i + 1):length(exp_groups)) {
                exp_combos <- rbind(exp_combos, data.frame(
                  Group_1 = exp_groups[i], Group_2 = exp_groups[j], stringsAsFactors = FALSE))
              }
            }
            values$preanalysis_exp_pairwise_combinations <- exp_combos
            values$preanalysis_exp_ui_version <- (values$preanalysis_exp_ui_version %||% 0) + 1
          }
          
          showNotification("Dual grouping detected. Configure comparisons for both grouping levels.", type = "message", duration = 4)
        } else {
          showNotification("Group mapping confirmed. Configure pairwise comparisons for analysis.", type = "message", duration = 3)
        }
        
        # Open the pre-analysis pairwise selection modal
        shinyBS::toggleModal(session, "preAnalysisPairwiseModal", toggle = "open")
      } else {
        # Only one group or no valid combinations, proceed directly
        showNotification("Group mapping confirmed. Raw data displayed.", type = "message", duration = 5)
      }
    } else {
      # Skip pairwise selection (either user preference or only one group)
      if (length(values$unique_groups) >= 2) {
        # Set default pairwise combinations for analysis
        values$selected_pairwise_for_analysis <- get_all_possible_pairwise_combinations()
        values$pairwise_selection_confirmed <- TRUE
      }
      showNotification("Group mapping confirmed. Raw data displayed.", type = "message", duration = 5)
    }
  })
  
  # Missing values visualization
  output$missingValuePlot <- renderPlot({ 
    req(values$original_unfiltered_data)
    
    # Use original unfiltered data for missing value visualization
    data <- values$original_unfiltered_data[, -1]  # Exclude first column (feature names)
    missing_matrix <- is.na(data)
    
    # Create a multi-panel visualization
    par(mfrow = c(2, 2))
    
    # 1. Heatmap of missing values
    image(t(!missing_matrix),
          main = "Missing Value Pattern",
          xlab = "Features",
          ylab = "Samples",
          col = c("red", "white"))
    
    # 2. Bar plot of missing values per sample
    sample_missing <- colSums(missing_matrix) / nrow(missing_matrix) * 100
    barplot(sample_missing,
            main = "% Missing Values per Sample",
            ylab = "% Missing",
            xlab = "",
            names.arg = 1:ncol(data),
            las = 2,
            cex.names = 0.7,
            col = "steelblue")
    if (!is.null(input$na_threshold)) {
      abline(h = input$na_threshold, col = "red", lty = 2)
    }
    
    # 3. Bar plot of missing values per feature
    feature_missing <- rowSums(missing_matrix) / ncol(missing_matrix) * 100
    # Sort by percentage missing
    sorted_idx <- order(feature_missing, decreasing = TRUE)
    top_n <- min(50, length(sorted_idx))  # Show top 50 features with most missing values
    
    barplot(feature_missing[sorted_idx[1:top_n]],
            main = "% Missing Values per Feature (Top 50)",
            ylab = "% Missing",
            xlab = "",
            names.arg = 1:top_n,
            col = "darkgreen",
            las = 2)
    if (!is.null(input$na_threshold)) {
      abline(h = input$na_threshold, col = "red", lty = 2)
    }
    
    # 4. Histogram of missing value percentages across features
    hist(feature_missing,
         main = "Distribution of Missing Values",
         xlab = "% Missing per Feature",
         ylab = "Count",
         breaks = 20,
         col = "orange")
    if (!is.null(input$na_threshold)) {
      abline(v = input$na_threshold, col = "red", lty = 2)
    }
  })
  
  # Make missing value plot available even when the UI is not visible
  outputOptions(output, "missingValuePlot", suspendWhenHidden = FALSE)
  
  output$rowSplitControls <- renderUI({
    req(values$cleaned_molecules)
    
    numericInput("row_split_groups", "Number of Row Clusters:",
                 value = 3, min = 2, max = 10, step = 1)
  })
  
  # Generate heatmap - Optimized for tab-specific execution with Data tab priority
  observeEvent({
    # Always watch for statistical results changes, even when not on Heatmaps tab
    list(
      input$current_tab,
      values$stat_results,  # Always watch for stat changes
      if (length(input$current_tab) > 0 && input$current_tab == "Heatmaps") {
        list(
          values$normalized_data, values$unique_groups, values$group_column_indices,
          input$heatmapType, input$group1, input$group2,
          input$heatmap_feature_source, input$pca_top_features,
          input$pca_feature_ranking, input$pvalue_cutoff,
          input$logfc_cutoff, input$use_top_features, input$top_features_count,
          input$clustering_distance, input$clustering_method,
          input$row_clustering, input$col_clustering, input$show_row_names,
          input$show_col_names, input$color_palette,
          # Add statistical method dependencies
          input$sig_method, input$posthoc_method, input$bootstrap_enabled,
          # Add selected features dependency
          values$selected_features
        )
      }
    )
  }, {
    # Pause heavy heatmap operations if Data tab is active (priority loading)
    if (isTRUE(values$data_tab_active)) {
      return()
    }
    
    # Only run heatmap generation when user is on the Heatmaps tab
    req(length(input$current_tab) > 0 && input$current_tab == "Heatmaps")
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    req(input$heatmapType)
    
    # Require statistical results for filtering (both pairwise and all groups need this)
    req(values$stat_results)
    
    # Only require group inputs for pairwise analysis
    if (input$heatmapType == "pairwise") {
      req(input$group1)
      is_variable_comparison <- grepl("^(lmROTS|lmeROTS)_", input$group1 %||% "")
      if (!is_variable_comparison) req(input$group2)
    }
    # Skip pairwise-specific validation for "All Groups"
    if (input$heatmapType == "pairwise") {
      is_variable_comparison <- grepl("^(lmROTS|lmeROTS)_", input$group1 %||% "")
      if (!is_variable_comparison) {
        if (length(values$unique_groups) < 2 || input$group1 == input$group2) {
          showNotification("Pairwise comparison requires at least two distinct groups.
                         The current dataset contains only one group or identical groups were selected.",
                           type = "warning", duration = 5)
          return(NULL)
        }
      }
      
      if (is_variable_comparison) {
        # lmROTS/lmeROTS variable comparison: use variable name as comparison, all samples
        comparison_name <- input$group1
        p_value_column <- get_appropriate_pvalue_column(comparison_name)
        fc_column_result <- get_foldchange_column(comparison_name)
        fdr_column <- paste0(comparison_name, "_FDR")
        if (!is.null(values$stat_results) && !(fdr_column %in% colnames(values$stat_results)))
          fdr_column <- NULL
        is_reversed <- FALSE
        fc_column <- if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
          is_reversed <- TRUE
          sub("^REVERSED:", "", fc_column_result)
        } else fc_column_result
        if (is.null(values$stat_results) || is.null(p_value_column) || !(p_value_column %in% colnames(values$stat_results)) ||
            is.null(fc_column) || !(fc_column %in% colnames(values$stat_results))) {
          showNotification(paste("No precomputed statistics found for", comparison_name, "."), type = "error")
          values$heatmap_data <- NULL
          values$column_split <- NULL
          return()
        }
        p_values <- values$stat_results[[p_value_column]]
        log2_fc <- values$stat_results[[fc_column]]
        if (is_reversed) log2_fc <- -log2_fc
        fdr_values <- if (!is.null(fdr_column)) values$stat_results[[fdr_column]] else NULL
        if (!is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          filter_idx <- !is.na(p_values) & p_values < input$pvalue_cutoff &
            !is.na(fdr_values) & fdr_values < input$fdr_cutoff &
            !is.na(log2_fc) & abs(log2_fc) >= (input$fc_cutoff %||% input$logfc_cutoff %||% 0)
        } else {
          filter_idx <- !is.na(p_values) & p_values < input$pvalue_cutoff &
            !is.na(log2_fc) & abs(log2_fc) >= (input$fc_cutoff %||% input$logfc_cutoff %||% 0)
        }
        significant_idx <- which(filter_idx)
        if (!is.null(input$heatmap_feature_source) && input$heatmap_feature_source != "all") {
          feature_source_idx <- get_feature_indices_by_source(input$heatmap_feature_source, comparison_name)
          significant_idx <- intersect(significant_idx, feature_source_idx)
        }
        if (length(significant_idx) == 0) {
          showNotification("No features meet the selected significance thresholds.", type = "warning")
          values$heatmap_data <- NULL
          values$column_split <- NULL
          return()
        }
        all_columns <- seq_len(ncol(values$normalized_data))
        heatmap_data <- values$normalized_data[significant_idx, all_columns, drop = FALSE]
        if (!is.null(input$heatmap_label_type) && input$heatmap_label_type == "ids" &&
            !is.null(values$accession_ids) && length(values$accession_ids) >= max(significant_idx)) {
          rownames(heatmap_data) <- make.unique(values$accession_ids[significant_idx])
        } else {
          rownames(heatmap_data) <- make.unique(values$cleaned_molecules[significant_idx])
        }
        values$heatmap_data <- heatmap_data
        values$column_split <- NULL
        return()
      }
      
      # Pairwise: groups from unique_groups
      group1_idx <- which(values$unique_groups == input$group1)
      if (length(group1_idx) == 0) return(NULL)
      group2_idx <- which(values$unique_groups == input$group2)
      if (length(group2_idx) == 0) return(NULL)
      
      group1_columns <- values$group_column_indices[[group1_idx]]
      group2_columns <- values$group_column_indices[[group2_idx]]
      
      # Get data for selected groups
      data1 <- values$normalized_data[, group1_columns, drop = FALSE]
      data2 <- values$normalized_data[, group2_columns, drop = FALSE]
      
      # Get comparison name for accessing precomputed statistics
      comparison_name <- paste(input$group1, "vs", input$group2)
      
      # IMPORTANT: Fold change interpretation
      # For comparison "Group1 vs Group2":
      # - Positive log2FC means higher expression in Group1
      # - Negative log2FC means higher expression in Group2
      # This follows the convention: log2(Group1/Group2)      # Always use the helper functions for p-value and fold change
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Determine fdr_column specifically for ROTS, checking both orders
      fdr_values <- NULL
      fdr_column <- NULL
      if (input$sig_method == "rots" && !is.null(values$stat_results)) {
        comparison_parts    <- strsplit(comparison_name, " vs ")[[1]]
        comparison_name_alt <- paste(rev(comparison_parts), collapse = " vs ")
        fdr_direct_name     <- paste0(comparison_name, "_FDR")
        fdr_alt_name        <- paste0(comparison_name_alt, "_FDR")
        
        if (fdr_direct_name %in% colnames(values$stat_results)) {
          fdr_column <- fdr_direct_name
        } else if (fdr_alt_name %in% colnames(values$stat_results)) {
          fdr_column <- fdr_alt_name
        }
        # Now actually grab the FDR vector if we found a column
        if (!is.null(fdr_column)) {
          fdr_values <- values$stat_results[[fdr_column]]
        }
      }
      # Handle reversed fold change columns
      is_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_column <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Use precomputed statistics if available
      if (!is.null(values$stat_results) &&
          !is.null(p_value_column) && p_value_column %in% colnames(values$stat_results) &&
          !is.null(fc_column) && fc_column %in% colnames(values$stat_results)) {
        
        # Use precomputed values for p-values and fold changes
        p_values <- values$stat_results[[p_value_column]]
        log2_fc <- values$stat_results[[fc_column]]
        # IMPORTANT: Fold change interpretation for "Group1 vs Group2":
        # - Positive log2FC means higher expression in Group1
        # - Negative log2FC means higher expression in Group2
        if (is_reversed) log2_fc <- -log2_fc
        
        # Create filter_idx based on method
        if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          # For ROTS, use both p-value and FDR columns with their respective thresholds
          fdr_values <- values$stat_results[[fdr_column]]
          filter_idx <- !is.na(p_values) &
            p_values < input$pvalue_cutoff &
            !is.na(fdr_values) &
            fdr_values < input$fdr_cutoff &
            !is.na(log2_fc) &
            abs(log2_fc) >= input$fc_cutoff        } else {
              # For non-ROTS methods or ROTS without a found FDR column, use p-value and FC
              filter_idx <- !is.na(p_values) &
                p_values < input$pvalue_cutoff &
                !is.na(log2_fc) &
                abs(log2_fc) >= input$fc_cutoff
            }
        # Now use the filter_idx to get significant indices
        significant_idx <- which(filter_idx)
        # Apply feature source filtering
        if (!is.null(input$heatmap_feature_source) && input$heatmap_feature_source != "all") {
          feature_source_idx <- get_feature_indices_by_source(input$heatmap_feature_source, comparison_name)
          # Intersect significant indices with feature source indices
          significant_idx <- intersect(significant_idx, feature_source_idx)
        }
      } else {
        showNotification(paste("No precomputed statistics found for", comparison_name,
                               ". Please run the statistical analysis in the Data tab first."),
                         type = "error")
        values$heatmap_data <- NULL
        values$column_split <- NULL
        return()
      }
      
      # Check if any features pass the thresholds
      if (length(significant_idx) == 0) {
        showNotification("No features meet the selected significance thresholds.", type = "warning")
        values$heatmap_data <- NULL
        values$column_split <- NULL
        return()
      }
      
      # Prepare the heatmap data using the significant indices
      # Note: Data order matches the comparison direction (Group1 samples, then Group2 samples)
      heatmap_data <- cbind(data1[significant_idx, , drop = FALSE],
                            data2[significant_idx, , drop = FALSE])
      
      # Set row names based on label type selection
      if (!is.null(input$heatmap_label_type) && input$heatmap_label_type == "ids" &&
          !is.null(values$accession_ids) && length(values$accession_ids) >= max(significant_idx)) {
        rownames(heatmap_data) <- make.unique(values$accession_ids[significant_idx])
      } else {
        rownames(heatmap_data) <- make.unique(values$cleaned_molecules[significant_idx])
      }
      
      colnames(heatmap_data) <- get_corrected_column_names(colnames(heatmap_data))
      
      # Create a column split vector for annotation - ensure correct group assignment
      # This creates labels that match the data order: Group1 samples first, then Group2 samples
      column_split <- c(rep(input$group1, length(group1_columns)),
                        rep(input$group2, length(group2_columns)))      # Store indices and statistics for the table outputs
      values$significant_idx_pairwise <- significant_idx
      values$adjusted_p_values_pairwise <- p_values[significant_idx]
      values$log2fc_pairwise <- log2_fc[significant_idx]
      
      # For ROTS, also store FDR values
      if (input$sig_method == "rots" &&
          !is.null(fdr_column) &&
          !is.null(values$stat_results) &&
          fdr_column %in% colnames(values$stat_results)) {
        values$fdr_values_pairwise <- values$stat_results[[fdr_column]][significant_idx]
      }
      
      # Z-score normalize the rows for visualization
      heatmap_data <- t(scale(t(heatmap_data)))
      # Save values in reactive object for use by heatmap renderers
      values$heatmap_data <- heatmap_data
      values$column_split <- column_split
    } # End pairwise heatmap condition
  })
  
  # Secondary heatmap observer
  observe({
    # Only run if we have the required data
    req(values$normalized_data, values$cleaned_molecules,
        values$unique_groups, values$group_column_indices)
    # Make this reactive to these key inputs
    input$heatmapType
    input$group1
    input$group2
    input$heatmap_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    input$pvalue_cutoff
    input$fdr_cutoff
    input$fc_cutoff
    
    # Add ML features dependency
    values$selected_features
    
    # Add PCA results dependency
    values$pca_result
    
    if (input$heatmapType == "pairwise") {
      is_variable_comp <- grepl("^(lmROTS|lmeROTS)_", input$group1 %||% "")
      if (is_variable_comp) {
        comparison_name <- input$group1
        p_value_column <- get_appropriate_pvalue_column(comparison_name)
        fc_column_result <- get_foldchange_column(comparison_name)
        fc_column <- if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) sub("^REVERSED:", "", fc_column_result) else fc_column_result
        if (is.null(values$stat_results) || is.null(p_value_column) || !(p_value_column %in% colnames(values$stat_results)) ||
            is.null(fc_column) || !(fc_column %in% colnames(values$stat_results))) return(NULL)
        p_values <- values$stat_results[[p_value_column]]
        log2_fc <- values$stat_results[[fc_column]]
        if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) log2_fc <- -log2_fc
        fdr_column <- paste0(comparison_name, "_FDR")
        if (input$sig_method == "rots" && fdr_column %in% colnames(values$stat_results)) {
          fdr_vals <- values$stat_results[[fdr_column]]
          filter_idx <- !is.na(p_values) & p_values < input$pvalue_cutoff & !is.na(fdr_vals) & fdr_vals < input$fdr_cutoff & !is.na(log2_fc) & abs(log2_fc) >= input$fc_cutoff
        } else {
          filter_idx <- !is.na(p_values) & p_values < input$pvalue_cutoff & !is.na(log2_fc) & abs(log2_fc) >= input$fc_cutoff
        }
        significant_idx <- which(filter_idx)
        if (length(significant_idx) == 0) return(NULL)
        all_cols <- seq_len(ncol(values$normalized_data))
        values$significant_idx_pairwise <- significant_idx
        values$adjusted_p_values_pairwise <- p_values[significant_idx]
        values$log2fc_pairwise <- log2_fc[significant_idx]
        if (input$sig_method == "rots" && fdr_column %in% colnames(values$stat_results)) {
          values$fdr_values_pairwise <- values$stat_results[[fdr_column]][significant_idx]
        }
        return()
      }
      # For pairwise heatmap: get indices and data from the two selected groups
      group1_idx <- which(values$unique_groups == input$group1)
      if (length(group1_idx) == 0) return(NULL)
      group1_columns <- values$group_column_indices[[group1_idx]]
      
      group2_idx <- which(values$unique_groups == input$group2)
      if (length(group2_idx) == 0) return(NULL)
      group2_columns <- values$group_column_indices[[group2_idx]]
      
      max_col_index <- ncol(values$normalized_data)
      valid_group1_columns <- group1_columns[group1_columns > 0 & group1_columns <= max_col_index]
      if (length(valid_group1_columns) == 0) {
        showNotification("No valid columns found for Group 1. Please check your group assignments.", type = "error")
        return(NULL)
      }
      if (length(valid_group1_columns) != length(group1_columns)) {
        warning(paste("Some Group 1 column indices are out of bounds. Using", length(valid_group1_columns), "out of", length(group1_columns), "columns."))
        group1_columns <- valid_group1_columns
      }
      valid_group2_columns <- group2_columns[group2_columns > 0 & group2_columns <= max_col_index]
      if (length(valid_group2_columns) == 0) {
        showNotification("No valid columns found for Group 2. Please check your group assignments.", type = "error")
        return(NULL)
      }
      if (length(valid_group2_columns) != length(group2_columns)) {
        warning(paste("Some Group 2 column indices are out of bounds. Using", length(valid_group2_columns), "out of", length(group2_columns), "columns."))
        group2_columns <- valid_group2_columns
      }
      
      data1 <- values$normalized_data[, group1_columns, drop = FALSE]
      data2 <- values$normalized_data[, group2_columns, drop = FALSE]
      
      comparison_name <- paste(input$group1, "vs", input$group2)
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Handle reversed fold change columns
      is_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_column <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Use precomputed statistics if available
      if (!is.null(values$stat_results) &&
          p_value_column %in% colnames(values$stat_results) &&
          fc_column %in% colnames(values$stat_results)) {
        
        # Use precomputed values for p-values and fold changes
        p_values <- values$stat_results[[p_value_column]]
        log2_fc <- values$stat_results[[fc_column]]
        if (is_reversed) log2_fc <- -log2_fc
        
        # Create a consistent filtering approach for all statistical methods
        # First, always create a filter based on p-value and fold change
        filter_idx <- !is.na(p_values) &
          p_values < input$pvalue_cutoff &
          !is.na(log2_fc) &
          abs(log2_fc) >= input$fc_cutoff
        
        # If ROTS is selected and FDR column exists, apply additional FDR filter
        if (input$sig_method == "rots") {
          # Check both directions for FDR column
          fdr_column <- paste0(comparison_name, "_FDR")
          alt_comparison <- paste(input$group2, "vs", input$group1)
          alt_fdr_column <- paste0(alt_comparison, "_FDR")
          
          # Find which FDR column exists
          if (fdr_column %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[fdr_column]]
            # Add FDR constraint to the filter
            filter_idx <- filter_idx & !is.na(fdr_values) & fdr_values < input$fdr_cutoff
          } else if (alt_fdr_column %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[alt_fdr_column]]
            # Add FDR constraint to the filter
            filter_idx <- filter_idx & !is.na(fdr_values) & fdr_values < input$fdr_cutoff        } else {
              message("No FDR column found for ROTS results: ", fdr_column, " or ", alt_fdr_column)
              # If no FDR column is found, use the existing filter based on p-value and fold change
            }      }
        # Now use the filter_idx to get significant indices
        significant_idx <- which(filter_idx)
        # Apply feature source filtering
        if (!is.null(input$heatmap_feature_source) && input$heatmap_feature_source != "all") {
          feature_source_idx <- get_feature_indices_by_source(input$heatmap_feature_source, comparison_name)
          # Intersect significant indices with feature source indices
          significant_idx <- intersect(significant_idx, feature_source_idx)
        }
        
        # Check if we found any significant features
        if (length(significant_idx) == 0) {
          values$heatmap_data <- NULL
          values$column_split <- NULL
          showNotification("No features meet the significance thresholds.", type = "warning")
          return()
        }
        
        # Prepare heatmap data from significant features
        heatmap_data <- cbind(data1[significant_idx, , drop = FALSE],
                              data2[significant_idx, , drop = FALSE])
        
        # Set row names based on label type selection
        if (!is.null(input$heatmap_label_type) && input$heatmap_label_type == "ids" &&
            !is.null(values$accession_ids) && length(values$accession_ids) >= max(significant_idx)) {
          rownames(heatmap_data) <- make.unique(values$accession_ids[significant_idx])
        } else {
          rownames(heatmap_data) <- make.unique(values$cleaned_molecules[significant_idx])
        }
        
        # Rename the sample columns using corrected names
        colnames(heatmap_data) <- get_corrected_column_names(colnames(heatmap_data))
        
        # Create a column split vector for annotation
        column_split <- c(rep(input$group1, length(group1_columns)),
                          rep(input$group2, length(group2_columns)))
        
        # Store the significant indices for the table
        values$significant_idx_pairwise <- significant_idx
        values$adjusted_p_values_pairwise <- p_values[significant_idx]
        values$log2fc_pairwise <- log2_fc[significant_idx]
        
        # Store FDR values if available (for ROTS)
        if (input$sig_method == "rots" && exists("fdr_values")) {
          values$fdr_values_pairwise <- fdr_values[significant_idx]
        }
      } else {
        return()
      }
      
    } else {
      # For an "all groups" heatmap - modify this section similarly
      all_columns <- unlist(values$group_column_indices)
      
      # Validate that all_columns are valid indices for the normalized data
      if (is.null(values$normalized_data) || is.null(all_columns) || length(all_columns) == 0) {
        values$heatmap_data <- NULL
        values$column_split <- NULL
        showNotification("No data available for heatmap generation.", type = "error")
        return()
      }
      
      # Check if all column indices are within the bounds of the data
      max_col_index <- ncol(values$normalized_data)
      valid_columns <- all_columns[all_columns > 0 & all_columns <= max_col_index]
      
      if (length(valid_columns) == 0) {
        values$heatmap_data <- NULL
        values$column_split <- NULL
        showNotification("No valid columns found for heatmap generation. Please check your group assignments.", type = "error")
        return()
      }
      
      if (length(valid_columns) != length(all_columns)) {
        warning(paste("Some column indices are out of bounds. Using", length(valid_columns), "out of", length(all_columns), "columns."))
        all_columns <- valid_columns
      }
      
      all_data <- values$normalized_data[, all_columns, drop = FALSE]    # Use global p-values if available
      p_value_column <- get_appropriate_pvalue_column("Global")
      
      # Early check: if statistical results not available, show error and return
      if (is.null(values$stat_results) || is.null(p_value_column) || !(p_value_column %in% colnames(values$stat_results))) {
        values$heatmap_data <- NULL
        values$column_split <- NULL
        return()
      }
      
      # Process global p-values (we know they exist now)
      adjusted_p_values_all <- values$stat_results[[p_value_column]]
      
      # Get potential FDR column for ROTS
      fdr_column <- NULL
      if (input$sig_method == "rots" && "Global_FDR" %in% colnames(values$stat_results)) {
        fdr_column <- "Global_FDR"
      }
      
      # First filter by p-value
      significant_idx_all <- which(adjusted_p_values_all < input$pvalue_cutoff)
      
      # Apply FDR filter for ROTS if available
      if (input$sig_method == "rots" && !is.null(fdr_column)) {
        fdr_values <- values$stat_results[[fdr_column]]
        significant_idx_all <- which(adjusted_p_values_all < input$pvalue_cutoff &
                                       fdr_values < input$fdr_cutoff)
      }
      
      # If fold change threshold is set, also filter by maximum fold change
      if (!is.null(input$fc_cutoff) && !is.na(input$fc_cutoff) && input$fc_cutoff > 0) {
        # Use precomputed Log2FC values from statistical results instead of calculating on-the-fly
        max_log2fc <- numeric(nrow(values$normalized_data))
        max_log2fc[] <- 0  # Initialize with zeros
        
        # Extract maximum absolute Log2FC from existing statistical results columns
        if (!is.null(values$stat_results)) {
          log2fc_columns <- grep("_Log2FC$", colnames(values$stat_results), value = TRUE)
          
          if (length(log2fc_columns) > 0) {
            # Calculate maximum absolute Log2FC across all pairwise comparisons
            for (col in log2fc_columns) {
              log2fc_values <- values$stat_results[[col]]
              # Handle reversed columns
              if (grepl("^REVERSED:", col)) {
                log2fc_values <- -log2fc_values
              }
              max_log2fc <- pmax(max_log2fc, abs(log2fc_values), na.rm = TRUE)
            }
          } else {
            # Fallback: if no Log2FC columns found, skip fold change filtering
            message("No Log2FC columns found in statistical results. Skipping fold change filtering.")
            max_log2fc[] <- input$fc_cutoff  # Set to threshold so all features pass
          }
        } else {
          # No statistical results available - skip fold change filtering
          message("No statistical results available. Skipping fold change filtering.")
          max_log2fc[] <- input$fc_cutoff  # Set to threshold so all features pass
        }
        
        # Combined filtering by p-value, FDR (if ROTS), AND max log2FC from statistical results
        if (input$sig_method == "rots" && !is.null(fdr_column)) {
          significant_idx_all <- which(adjusted_p_values_all < input$pvalue_cutoff &
                                         fdr_values < input$fdr_cutoff &
                                         max_log2fc >= input$fc_cutoff)        } else {
                                           significant_idx_all <- which(adjusted_p_values_all < input$pvalue_cutoff &
                                                                          max_log2fc >= input$fc_cutoff)
                                         }          # Apply feature source filtering
        if (!is.null(input$heatmap_feature_source) && input$heatmap_feature_source != "all") {
          feature_source_idx <- get_feature_indices_by_source(input$heatmap_feature_source, "All Groups")
          # Intersect significant indices with feature source indices
          significant_idx_all <- intersect(significant_idx_all, feature_source_idx)
        }
      }
      
      if (length(significant_idx_all) == 0) {
        values$heatmap_data <- NULL
        values$column_split <- NULL
        showNotification("No features meet the significance thresholds.", type = "warning")
        return()
      }
      
      heatmap_data <- all_data[significant_idx_all, , drop = FALSE]
      
      # Set row names based on label type selection
      if (!is.null(input$heatmap_label_type) && input$heatmap_label_type == "ids" &&
          !is.null(values$accession_ids) && length(values$accession_ids) >= max(significant_idx_all)) {
        rownames(heatmap_data) <- make.unique(values$accession_ids[significant_idx_all])
      } else {
        rownames(heatmap_data) <- make.unique(values$cleaned_molecules[significant_idx_all])
      }
      
      # Rename sample columns with the corrected names function
      colnames(heatmap_data) <- get_corrected_column_names(colnames(heatmap_data))
      column_split <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
      column_split <- column_split[1:ncol(heatmap_data)]
      
      # Store the significant indices and related values for the table
      values$significant_idx_all <- significant_idx_all
      values$adjusted_p_values_all <- adjusted_p_values_all[significant_idx_all]
      
      # Store max log2FC values if they were calculated
      if (exists("max_log2fc")) {
        values$max_log2fc_all <- max_log2fc[significant_idx_all]
      }
      # Store FDR values if available (for ROTS)
      if (input$sig_method == "rots" && !is.null(fdr_column)) {
        fdr_values <- values$stat_results[[fdr_column]]
        values$fdr_values_all <- fdr_values[significant_idx_all]
      }
    }
    
    # Z-score normalize the feature rows for visualization
    heatmap_data <- t(scale(t(heatmap_data)))
    
    # Store values in reactive object
    values$heatmap_data <- heatmap_data
    values$column_split <- column_split
  })
  
  # Dynamic heatmap sizing utilities and containers
  compute_heatmap_height_px <- reactive({
    req(values$heatmap_data)
    n_rows <- nrow(values$heatmap_data)
    row_px <- switch(input$heatmap_cell_size,
                     "Small" = 6,
                     "Compact" = 10,
                     "Medium" = 16,
                     "Large" = 22,
                     14)
    # Overhead for title, legend at bottom, and column labels at top
    overhead <- switch(input$heatmap_cell_size,
                       "Small" = 250,
                       "Compact" = 300,
                       "Medium" = 380,
                       "Large" = 450,
                       330)
    h <- n_rows * row_px + overhead
    h <- max(600, min(round(h), 6000))
    h
  })
  
  output$interactiveHeatmapContainer <- renderUI({
    req(values$heatmap_data)
    plotlyOutput("interactiveHeatmap", height = paste0(compute_heatmap_height_px(), "px"))
  })
  
  output$staticHeatmapContainer <- renderUI({
    req(values$heatmap_data)
    plotOutput("staticHeatmap", height = paste0(compute_heatmap_height_px(), "px"))
  })
  
  # Static Heatmap Renderer
  output$staticHeatmap <- renderPlot({ 
    # Validate required data is available
    req(values$heatmap_data, values$column_split)
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$heatmap_title_size)) input$heatmap_title_size else 14
    row_label_size <- if(!is.null(input$heatmap_row_label_size)) input$heatmap_row_label_size else 10
    col_label_size <- if(!is.null(input$heatmap_col_label_size)) input$heatmap_col_label_size else 10
    legend_text_size <- if(!is.null(input$heatmap_legend_text_size)) input$heatmap_legend_text_size else 12
    
    # Define color function for the heatmap
    col_fun <- circlize::colorRamp2(c(-2, 0, 2), c(input$lowColor, input$midColor, input$highColor))
    
    # Define row split based on data
    row_split <- if(nrow(values$heatmap_data) < 2) NULL else 2

    # Compute left padding for long row names to prevent truncation
    row_label_width_mm <- 0
    if (isTRUE(input$show_row_names)) {
      row_names <- rownames(values$heatmap_data)
      if (!is.null(row_names) && length(row_names) > 0) {
        row_label_width_mm <- tryCatch({
          grid::convertWidth(
            ComplexHeatmap::max_text_width(row_names,
                                           gp = grid::gpar(fontsize = row_label_size, fontface = "bold")),
            "mm",
            valueOnly = TRUE
          )
        }, error = function(e) 0)
      }
    }
    
    # Fix spaces in column_split by creating a named factor with proper labels
    clean_splits <- values$column_split
    split_levels <- unique(clean_splits)
    original_labels <- preserve_group_names(split_levels)  # Apply preserve_group_names to restore spaces
    names(split_levels) <- original_labels  # Preserve original labels as names
    fixed_column_split <- factor(clean_splits, levels = split_levels)
    
    # Handle the Small size option with proper top annotations
    if(input$heatmap_cell_size == "Small") {
      # Create the annotation first
      column_labels <- ComplexHeatmap::HeatmapAnnotation(
        Group = ComplexHeatmap::anno_block(
          gp = grid::gpar(fill = rainbow(length(unique(fixed_column_split)))),
          labels = original_labels,  # Use preserved labels that contain spaces
          labels_gp = grid::gpar(fontsize = col_label_size, fontface = "bold"),
          height = unit(3, "mm")
        ),
        show_legend = FALSE,
        height = unit(5, "mm")
      )
      # Create heatmap with top_annotation
      ht <- ComplexHeatmap::Heatmap(
        values$heatmap_data,
        name = "Z-score",
        cluster_rows = input$cluster_rows,
        cluster_columns = input$cluster_cols,
        show_row_names = FALSE,
        show_column_names = FALSE,
        column_names_side = "top",
        rect_gp = grid::gpar(col = "black"),
        row_dend_reorder = FALSE,
        column_title = ifelse(input$heatmapType == "pairwise",
                              ifelse(grepl("^(lmROTS|lmeROTS)_", input$group1 %||% ""),
                                     paste(input$group1, "Heatmap"),
                                     paste(input$group1, "vs", input$group2, "Heatmap")),
                              "Heatmap of All Groups"),
        column_title_gp = grid::gpar(fontface = "bold", fontsize = title_size),
        heatmap_legend_param = list(
          title = NULL,
          legend_width = switch(input$heatmap_cell_size,
                                "Small" = unit(1, "in"),
                                "Compact" = unit(2, "in"),
                                "Medium" = unit(3, "in"),
                                "Large" = unit(4, "in"),
                                unit(3, "in")),
          grid_height = unit(0.05, "in"),
          direction = "horizontal",
          labels_gp = grid::gpar(fontface = "bold", fontsize = legend_text_size)
        ),
        col = col_fun,
        na_col = input$naColor %||% "gray",
        row_split = row_split,
        column_split = fixed_column_split,  # Use the fixed factor here
        row_names_gp = grid::gpar(fontsize = 0),
        column_names_gp = grid::gpar(fontsize = 0),
        row_title = NULL,
        top_annotation = column_labels,
        row_gap = unit(1, "mm"),
        column_gap = unit(1, "mm"),
        border = FALSE
      )
    } else {
      # For larger sizes, we need to fix column_split differently
      ht <- ComplexHeatmap::Heatmap(
        values$heatmap_data,
        name = "Z-score",
        cluster_rows = input$cluster_rows,
        cluster_columns = input$cluster_cols,
        show_row_names = ifelse(input$heatmap_cell_size %in% c("Compact"), FALSE, input$show_row_names),
        show_column_names = TRUE,
        column_names_side = "top",
        rect_gp = grid::gpar(col = "black"),
        row_dend_reorder = FALSE,
        column_title = ifelse(input$heatmapType == "pairwise",
                              ifelse(grepl("^(lmROTS|lmeROTS)_", input$group1 %||% ""),
                                     paste(input$group1, "Heatmap"),
                                     paste(input$group1, "vs", input$group2, "Heatmap")),
                              "Heatmap of All Groups"),
        column_title_gp = grid::gpar(fontface = "bold", fontsize = title_size),
        heatmap_legend_param = list(
          title = NULL,
          legend_width = switch(input$heatmap_cell_size,
                                "Small" = unit(1, "in"),
                                "Compact" = unit(2, "in"),
                                "Medium" = unit(3, "in"),
                                "Large" = unit(4, "in"),
                                unit(3, "in")),
          grid_height = unit(0.05, "in"),
          direction = "horizontal",
          labels_gp = grid::gpar(fontface = "bold", fontsize = legend_text_size)
        ),
        col = col_fun,
        na_col = input$naColor %||% "gray",
        row_split = row_split,
        column_split = fixed_column_split,  # Use the fixed factor here
        row_names_gp = grid::gpar(fontsize = row_label_size, fontface = "bold"),
        column_names_gp = grid::gpar(fontsize = col_label_size, fontface = "bold"),
        row_title = NULL,
        show_row_dend = TRUE,
        row_gap = unit(1, "mm"),
        column_gap = unit(1, "mm"),
        border = FALSE
      )
      
      # Add explicit column labels using the original strings for larger sizes
      ht@column_title_param$labels_row <- original_labels
    }
    
    # Store the heatmap object for download (like PCA)
    values$heatmap_obj <- ht
    
    # Draw the heatmap with extra padding to prevent label truncation
    right_pad_mm <- switch(input$heatmap_cell_size,
                           "Medium" = 15,
                           "Large" = 20,
                           5)
    left_pad_mm <- max(5, row_label_width_mm + 5)
    ComplexHeatmap::draw(
      ht,
      heatmap_legend_side = "bottom",
      padding = unit(c(5, right_pad_mm, 5, left_pad_mm), "mm")
    )
  },
  height = function() {
    if (is.null(values$heatmap_data)) return(600)
    compute_heatmap_height_px()
  },
  width = function() {
    if (is.null(values$heatmap_data)) return(800)
    n_cols <- ncol(values$heatmap_data)
    n_rows <- nrow(values$heatmap_data)
    col_px <- switch(input$heatmap_cell_size,
                     "Small" = 8,
                     "Compact" = 12,
                     "Medium" = 18,
                     "Large" = 24,
                     14)
    # Calculate left margin for row labels (if shown) and dendrogram
    left_margin <- 150  # Base margin for dendrogram
    if (isTRUE(input$show_row_names) && !input$heatmap_cell_size %in% c("Small", "Compact")) {
      # Estimate character width based on longest row name
      max_chars <- max(nchar(rownames(values$heatmap_data)), na.rm = TRUE)
      left_margin <- left_margin + max_chars * 7  # ~7px per character
    }
    # Right margin for legend and group labels
    right_margin <- switch(input$heatmap_cell_size,
                           "Small" = 120,
                           "Compact" = 150,
                           "Medium" = 200,
                           "Large" = 250,
                           170)
    w <- n_cols * col_px + left_margin + right_margin
    w <- max(900, min(round(w), 3000))
    w
  }
  , res = UI_PLOT_RES)
  
  # Interactive Heatmap Renderer
  output$interactiveHeatmap <- renderPlotly({
    # Validate required data is available
    req(values$heatmap_data, values$column_split)
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$heatmap_title_size)) input$heatmap_title_size else 14
    row_label_size <- if(!is.null(input$heatmap_row_label_size)) input$heatmap_row_label_size else 10
    col_label_size <- if(!is.null(input$heatmap_col_label_size)) input$heatmap_col_label_size else 10
    legend_text_size <- if(!is.null(input$heatmap_legend_text_size)) input$heatmap_legend_text_size else 12
    
    # Create a data frame for plotly heatmap
    plot_data <- as.data.frame(as.table(as.matrix(values$heatmap_data)))
    colnames(plot_data) <- c("Row", "Column", "Value")
    
    # Add group information for hover text
    plot_data$Group <- values$column_split[as.numeric(plot_data$Column)]
    
    # Create colors that match the static heatmap
    colors <- colorRampPalette(c(input$lowColor, input$midColor, input$highColor))(100)
    
    # Create the heatmap
    p <- plotly::plot_ly(
      data = plot_data,
      x = ~Column,
      y = ~Row,
      z = ~Value,
      type = "heatmap",
      colorscale = list(
        c(0, input$lowColor),
        c(0.5, input$midColor),
        c(1, input$highColor)
      ),
      hoverinfo = "text",
      text = ~paste(
        "Feature:", Row, "<br>",
        "Sample:", Column, "<br>",
        "Group:", Group, "<br>",
        "Value:", round(Value, 3)
      )
    ) %>%
      layout(
        title = list(
          text = ifelse(input$heatmapType == "pairwise",
                        paste(input$group1, "vs", input$group2, "Heatmap"),
                        "Heatmap of All Groups"),
          font = list(size = title_size)
        ),
        xaxis = list(
          title = "",
          showgrid = FALSE,
          tickfont = list(size = col_label_size)
        ),
        yaxis = list(
          title = "",
          showgrid = FALSE,
          autorange = "reversed", # To match the ComplexHeatmap orientation
          tickfont = list(size = row_label_size)
        ),
        margin = list(
          l = {
            max_label_chars <- tryCatch(max(nchar(rownames(values$heatmap_data)), na.rm = TRUE), error = function(e) 0)
            max(60, min(400, max_label_chars * 6))
          },
          r = 20,
          t = 60,
          b = 60
        ),
        height = compute_heatmap_height_px()
      )
    
    return(p)
  })
  
  # Helper function to compute dynamic canvas size for downloads (matches UI sizing)
  compute_download_canvas_size <- function(heatmap_data, cell_size, dpi) {
    if (is.null(heatmap_data)) return(list(width = 10 * dpi, height = 8 * dpi))
    
    n_rows <- nrow(heatmap_data)
    n_cols <- ncol(heatmap_data)
    
    # Height calculation (matching UI logic)
    row_px <- switch(cell_size,
                     "Small" = 3,      # ~0.8 mm per row (reduced from 4)
                     "Compact" = 6,    # ~1.5 mm per row (reduced from 8)
                     "Medium" = 9,     # ~2.5 mm per row (reduced from 12)
                     "Large" = 14,     # ~4 mm per row (reduced from 19)
                     9)
    height_overhead <- switch(cell_size,
                              "Small" = 5000,
                              "Compact" = 5000,
                              "Medium" = 5000,
                              "Large" = 6000,
                              5000)
    height_px <- max(400, n_rows * row_px + height_overhead)
    
    # Width calculation (matching UI logic)
    col_px <- switch(cell_size,
                     "Small" = 4,    # ~1 mm per column (reduced from 6)
                     "Compact" = 6,  # ~1.5 mm per column (reduced from 8)
                     "Medium" = 10,  # ~2.5 mm per column (reduced from 14)
                     "Large" = 16,   # ~4 mm per column (reduced from 22)
                     10)
    width_overhead <- switch(cell_size,
                             "Small" = 5000,
                             "Compact" = 5000,
                             "Medium" = 6000,    # More space for long feature names
                             "Large" = 6000,     # Even more space for long feature names
                             5000)
    width_px <- max(800, n_cols * col_px + width_overhead)
    
    # Convert pixels to inches for PNG device
    width_inches <- width_px / dpi
    height_inches <- height_px / dpi
    
    # Apply reasonable limits to prevent extremely large files
    width_inches <- min(width_inches, 50)   # Max 50 inches wide
    height_inches <- min(height_inches, 50) # Max 50 inches tall
    
    return(list(width = width_inches * dpi, height = height_inches * dpi))
  }
  
  # Download Heatmap button handler
  output$downloadHeatmapBtn <- downloadHandler(
    filename = function() {
      if (input$heatmapType == "pairwise") {
        paste0(input$group1, "_vs_", input$group2, "_Heatmap_",
               format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
      } else {
        paste0("All_Groups_Heatmap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
      }
    },
    content = function(file) {
      # Get the user-specified DPI and image format
      dpi <- get_safe_global_dpi()
      image_format <- get_safe_global_image_format()
      
      # Enhanced validation and error handling
      if (is.null(values$heatmap_obj)) {
        showNotification("No heatmap available. Generate a heatmap first.", type = "error")
        return(NULL)
      }
      
      # Calculate dynamic canvas size based on actual data dimensions (matches UI sizing)
      canvas_size <- compute_download_canvas_size(values$heatmap_data, input$heatmap_cell_size, dpi)
      
      # Create the file using dynamic canvas size that matches UI
      tryCatch({
        if (image_format == "png") {
          png(file, width = canvas_size$width, height = canvas_size$height, res = dpi)
        } else if (image_format == "svg") {
          svg(file, width = canvas_size$width / dpi, height = canvas_size$height / dpi)
        }
        
        # Use the stored heatmap object (like PCA) instead of recreating
        row_label_size <- if(!is.null(input$heatmap_row_label_size)) input$heatmap_row_label_size else 10
        show_row_labels <- isTRUE(input$show_row_names) && !input$heatmap_cell_size %in% c("Small", "Compact")
        row_label_width_mm <- 0
        if (show_row_labels) {
          row_names <- rownames(values$heatmap_data)
          if (!is.null(row_names) && length(row_names) > 0) {
            row_label_width_mm <- tryCatch({
              grid::convertWidth(
                ComplexHeatmap::max_text_width(row_names,
                                               gp = grid::gpar(fontsize = row_label_size, fontface = "bold")),
                "mm",
                valueOnly = TRUE
              )
            }, error = function(e) 0)
          }
        }
        right_pad_mm <- switch(input$heatmap_cell_size,
                               "Medium" = 15,
                               "Large" = 20,
                               5)
        left_pad_mm <- max(5, row_label_width_mm + 5)
        ComplexHeatmap::draw(
          values$heatmap_obj,
          heatmap_legend_side = "bottom",
          padding = unit(c(5, right_pad_mm, 5, left_pad_mm), "mm")
        )
        dev.off()
        
        # Show success notification
        showNotification("Heatmap successfully downloaded!", type = "message")
      }, error = function(e) {
        # Handle any errors in plot generation
        message("Error downloading heatmap: ", e$message)
        showNotification(paste("Error downloading heatmap:", e$message), type = "error")
      })
    }
  )
  
  # Observer to update featureSelect dropdown based on feature_source selection - Optimized for Distribution Analysis tab with Data tab priority
  observeEvent({
    list(
      input$current_tab,
      if (length(input$current_tab) > 0 && input$current_tab == "Distribution Analysis") {
        list(
          input$dist_feature_source,
          input$dist_label_type,
          input$pca_top_features,
          input$pca_feature_ranking,
          input$pvalue_cutoff,
          input$fdr_cutoff,
          input$fc_cutoff,
          values$pca_result,
          values$selected_features,
          values$cleaned_molecules,  # Add dependency on cleaned_molecules
          values$accession_ids,      # Add dependency on IDs
          values$stat_results       # Add dependency on statistical results
        )
      }
    )
  }, {
    # Pause heavy distribution operations if Data tab is active (priority loading)
    if (isTRUE(values$data_tab_active)) {
      return()
    }
    
    # Only run when on Distribution Analysis tab
    req(length(input$current_tab) > 0 && input$current_tab == "Distribution Analysis")
    req(values$cleaned_molecules)
    
    # Use centralized function to get feature indices
    feature_indices <- get_feature_indices_by_source(input$dist_feature_source, "All Groups")
    
    # Determine which labels to use based on radio button selection
    use_ids <- !is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
      !is.null(values$accession_ids) && length(values$accession_ids) >= max(feature_indices)
    
    # Get the corresponding feature names or IDs
    if (use_ids) {
      feature_labels <- values$accession_ids[feature_indices]
    } else {
      feature_labels <- values$cleaned_molecules[feature_indices]
    }
    
    feature_choices <- setNames(feature_labels, feature_labels)
    
    # Determine which feature should be selected
    # If there's a currently selected feature, try to keep it
    selected_feature <- NULL
    if (!is.null(input$featureSelect) && any(input$featureSelect != "")) {
      current_selection <- input$featureSelect
      
      # Try to find the currently selected feature in the new choices
      # This handles switching between names and IDs for the same feature
      if (all(current_selection %in% feature_choices)) {
        # Direct match - feature is still available with same label
        selected_feature <- current_selection
      } else if (any(current_selection %in% feature_choices)) {
        # Partial match
        selected_feature <- current_selection[current_selection %in% feature_choices]
      } else {
        # Feature label might have changed (e.g., switched from name to ID or vice versa)
        # Get the index of the currently selected feature
        current_idx <- get_feature_index_from_label(current_selection)
        if (!is.null(current_idx) && current_idx %in% feature_indices) {
          # Feature is in the current selection, find its new label
          feature_pos <- which(feature_indices == current_idx)
          if (length(feature_pos) > 0) {
            selected_feature <- feature_labels[feature_pos[1]]
          }
        }
      }
    }
    
    # Default to first feature if no selection can be maintained
    if (is.null(selected_feature)) {
      selected_feature <- if(length(feature_choices) > 0) feature_choices[1] else NULL
    }
    
    # Update the dropdown with filtered features only
    updateSelectInput(
      session, "featureSelect",
      choices = feature_choices,
      selected = selected_feature
    )
  })
  
  # Observer to clear PCA results when scale setting changes (for lazy recomputation)
  observeEvent(input$pcaScale, {
    # Clear stored PCA results so they get recomputed with new scale setting
    if (!is.null(values$pca_results_context)) {
      values$pca_results_context <- list()
    }
    # Also clear the global PCA result  values$pca_result <- NULL
  })
  
  # Keep global PCA features in sync when Top N or Ranking changes while checkbox is on
  observeEvent(list(input$pca_top_features, input$pca_feature_ranking), {
    if (isTRUE(input$use_pca_features)) {
      # Reuse the same logic as the checkbox observer to refresh global features
      try({
        pca_result <- NULL
        pca_result <- pca_result_for_current_context()
        if (is.null(pca_result)) pca_result <- values$pca_result
        if (!is.null(pca_result) && !is.null(input$pca_top_features) && !is.na(input$pca_top_features) && input$pca_top_features > 0) {
          top_features_df <- get_top_pca_features(pca_result, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
          if (!is.null(top_features_df) && nrow(top_features_df) > 0) {
            values$pca_top_features <- as.integer(top_features_df$Feature_ID)
            # Store names as well for robust downstream matching even if molecule order changes
            values$pca_top_feature_names <- as.character(top_features_df$Feature)
          }
        }
      }, silent = TRUE)
    }
  }, ignoreInit = TRUE)
  
  # Helper function to find feature index from either molecule name or accession ID
  get_feature_index_from_label <- function(label) {
    # Try matching molecule name first
    feature_idx <- which(values$cleaned_molecules == label)
    if (length(feature_idx) > 0) {
      return(feature_idx[1])
    }
    
    # If not found, try matching against IDs
    if (!is.null(values$accession_ids)) {
      feature_idx <- which(values$accession_ids == label)
      if (length(feature_idx) > 0) {
        return(feature_idx[1])
      }
    }
    
    return(NULL)
  }

  # Distribution plot border styling helper
  get_distribution_border_theme <- function() {
    border_thick <- if (!is.null(input$dist_border_thickness)) input$dist_border_thickness else 0.6
    
    if (isTRUE(input$dist_remove_top_right_border)) {
      return(theme(
        panel.border = element_blank(),
        axis.line = element_blank(),
        axis.line.x.bottom = element_line(color = "black", linewidth = border_thick),
        axis.line.y.left = element_line(color = "black", linewidth = border_thick),
        axis.line.x.top = element_blank(),
        axis.line.y.right = element_blank()
      ))
    }

    theme(panel.border = element_rect(color = "black", fill = NA, linewidth = border_thick))
  }
  
  # Generate distribution plot
  generate_dist_plot <- reactive({
    req(values$normalized_data, input$featureSelect, values$unique_groups, values$group_column_indices)
    
    # Check if there are any valid features after filtering
    if (is.null(values$normalized_data) || nrow(values$normalized_data) == 0 || 
        is.null(values$cleaned_molecules) || length(values$cleaned_molecules) == 0) {
      return(NULL)
    }
    
    # Check if statistical results are available
    if (is.null(values$stat_results)) {
      showNotification("Please run statistical analysis in the Data tab first", type = "warning")
      return(NULL)
    }
    # Use centralized function to get feature indices based on feature source
    selected_idx <- get_feature_indices_by_source(input$dist_feature_source, "All Groups")
    
    # Find the actual feature index in the original dataset
    # Handle both molecule names and accession IDs
    feature_idx <- which(values$cleaned_molecules == input$featureSelect)
    
    # If not found in molecule names, try matching against IDs
    if (length(feature_idx) == 0 && !is.null(values$accession_ids)) {
      feature_idx <- which(values$accession_ids == input$featureSelect)
    }
    
    if (length(feature_idx) == 0) {
      showNotification("Selected feature not found in the data", type = "error")
      return(NULL)
    }
    
    feature_data <- values$normalized_data[feature_idx, ]
    
    # Get the proper column order and corresponding data
    all_columns <- unlist(values$group_column_indices)
    feature_data_reordered <- feature_data[all_columns]
    sample_names_reordered <- colnames(values$normalized_data)[all_columns]
    
    # Create cleaned sample names using corrected names function
    cleaned_sample_names <- get_corrected_column_names(sample_names_reordered)
    
    # Create data frame for plotting
    plot_df <- data.frame(
      Value = as.numeric(feature_data_reordered),
      Group = create_proper_group_labels(values$unique_groups, values$group_column_indices),
      Sample = cleaned_sample_names,
      stringsAsFactors = FALSE
    )
    plot_df$Feature_Name <- input$featureSelect
    plot_df$Feature_Index <- feature_idx[1]  # Ensure single value
    values$current_dist_data <- plot_df
    # Filter NA values but preserve Feature_Index
    saved_feature_idx <- plot_df$Feature_Index[1]
    plot_df <- plot_df[!is.na(plot_df$Value), ]
    # Re-assign in case factor conversion dropped it
    if (nrow(plot_df) > 0) {
      plot_df$Feature_Index <- saved_feature_idx
    }

    # Apply manual group ordering based on user selection
    current_groups <- preserve_group_names(get_active_unique_groups() %||% values$unique_groups)
    available_groups <- unique(plot_df$Group)
    # Use stored custom order if available, falling back to input then data order
    manual_order <- values$dist_group_order_custom
    if (is.null(manual_order) || length(manual_order) == 0) {
      manual_order <- input$dist_group_order
    }
    if (is.null(manual_order) || length(manual_order) == 0) {
      group_levels <- current_groups
    } else {
      group_levels <- manual_order
    }
    group_levels <- group_levels[group_levels %in% available_groups]
    # Add only truly new groups (not ones the user removed)
    base_groups <- values$dist_group_order_base_groups %||% character()
    new_groups <- setdiff(available_groups, base_groups)
    new_groups <- new_groups[new_groups %in% available_groups & !(new_groups %in% group_levels)]
    group_levels <- c(group_levels, new_groups)
    if (length(group_levels) == 0) {
      group_levels <- available_groups
    }
    # Remove groups that were explicitly removed from the order
    plot_df <- plot_df[plot_df$Group %in% group_levels, , drop = FALSE]
    if (nrow(plot_df) == 0) {
      showNotification("No data available after applying group order selection.", type = "warning")
      return(NULL)
    }
    plot_df$Group <- factor(plot_df$Group, levels = group_levels)
    
    # Set color palette
    n_groups <- length(group_levels %||% values$unique_groups)
    colors <- if (input$palette == "dimred_default") {
      get_color_palette("dimred_default", n_groups)
    } else if (input$palette == "default") {
      get_color_palette("default", n_groups)
    } else if (input$palette %in% c("viridis", "plasma")) {
      viridis::viridis_pal(option = input$palette)(n_groups)
    } else {
      get_color_palette(input$palette, n_groups)
    }
    if (!is.null(group_levels) && length(colors) >= length(group_levels)) {
      names(colors) <- group_levels
    }
    
    # Create plot based on plot type
    plot_obj <- switch(input$plotType,
                       "Boxplot" = create_boxplot(plot_df, colors),
                       "Violin" = create_violin_plot(plot_df, colors),
                       "Ridgeline" = create_ridgeline_plot(plot_df, colors),
                       "Swarm" = create_swarm_plot(plot_df, colors),
                       "Strip" = create_strip_plot(plot_df, colors),
                       create_boxplot(plot_df, colors)
    )
    
    # Wrap long title names onto multiple lines
    title_size <- if (!is.null(input$dist_title_size)) as.numeric(input$dist_title_size) else 14
    wrap_width <- max(15, round(45 * (14 / title_size)))
    current_title <- input$featureSelect[1]  # single feature when called from generate_dist_plot
    wrapped_title <- paste(strwrap(current_title, width = wrap_width), collapse = "\n")
    plot_obj <- plot_obj + ggplot2::ggtitle(wrapped_title)
    
    # Add statistical annotations if requested
    if (input$showStats && length(unique(plot_df$Group)) >= 2) {
      # Use input$sig_method directly from the data processing tab
      plot_obj <- add_stat_annotations(plot_obj, plot_df, input$sig_method)
    }
    
    # --- ROTS FDR edge case handling for Distribution Analysis ---
    # If ROTS is selected, use FDR cutoff for significance
    if (input$sig_method == "rots" && "FDR" %in% colnames(values$stat_results)) {
      fdr_col <- NULL
      # Try to find the correct FDR column for this feature
      for (g1 in values$unique_groups) {
        for (g2 in values$unique_groups) {
          if (g1 != g2) {
            possible_col <- paste0(g1, "vs", g2, "_FDR")
            if (possible_col %in% colnames(values$stat_results)) {
              fdr_col <- possible_col
              break
            }
          }
        }
        if (!is.null(fdr_col)) break
      }
      if (!is.null(fdr_col)) {
        fdr_val <- values$stat_results[feature_idx, fdr_col]
        pval_col <- get_appropriate_pvalue_column(fdr_col)
        pval_val <- values$stat_results[feature_idx, pval_col]
        # You can use input$dist_fdr_cutoff here for any downstream logic or display
        # Example: is_significant <- !is.na(pval_val) && pval_val < input$pvalue_cutoff && !is.na(fdr_val) && fdr_val < input$dist_fdr_cutoff
      }
    }
    
    # Calculate statistics using precomputed values from stat_results
    calculate_distribution_stats(plot_df, input$sig_method)
    
    shinyjs::enable("downloadDistPlot")
    return(plot_obj)
  })
  
  # Helper: build a single distribution plot for a given feature name
  # Reuses the same create_boxplot / create_violin_plot / etc. functions
  # so every grid cell inherits the user's font-size, colour palette, jitter,
  # show-points and y-scale settings exactly.
  build_single_dist_plot <- function(feature_name, show_y_axis_label = TRUE) {
    # Resolve feature index
    feature_idx <- which(values$cleaned_molecules == feature_name)
    if (length(feature_idx) == 0 && !is.null(values$accession_ids)) {
      feature_idx <- which(values$accession_ids == feature_name)
    }
    if (length(feature_idx) == 0) return(NULL)
    
    feature_data <- values$normalized_data[feature_idx, ]
    all_columns  <- unlist(values$group_column_indices)
    feature_data_reordered <- feature_data[all_columns]
    sample_names_reordered <- colnames(values$normalized_data)[all_columns]
    cleaned_sample_names   <- get_corrected_column_names(sample_names_reordered)
    
    plot_df <- data.frame(
      Value  = as.numeric(feature_data_reordered),
      Group  = create_proper_group_labels(values$unique_groups, values$group_column_indices),
      Sample = cleaned_sample_names,
      stringsAsFactors = FALSE
    )
    plot_df$Feature_Name  <- feature_name
    plot_df$Feature_Index <- feature_idx[1]
    
    saved_feature_idx <- plot_df$Feature_Index[1]
    plot_df <- plot_df[!is.na(plot_df$Value), ]
    if (nrow(plot_df) > 0) plot_df$Feature_Index <- saved_feature_idx
    if (nrow(plot_df) == 0) return(NULL)
    
    # ---- group ordering (same logic as generate_dist_plot) ----
    current_groups  <- preserve_group_names(get_active_unique_groups() %||% values$unique_groups)
    available_groups <- unique(plot_df$Group)
    manual_order <- values$dist_group_order_custom
    if (is.null(manual_order) || length(manual_order) == 0) manual_order <- input$dist_group_order
    if (is.null(manual_order) || length(manual_order) == 0) {
      group_levels <- current_groups
    } else {
      group_levels <- manual_order
    }
    group_levels <- group_levels[group_levels %in% available_groups]
    base_groups  <- values$dist_group_order_base_groups %||% character()
    new_groups   <- setdiff(available_groups, base_groups)
    new_groups   <- new_groups[new_groups %in% available_groups & !(new_groups %in% group_levels)]
    group_levels <- c(group_levels, new_groups)
    if (length(group_levels) == 0) group_levels <- available_groups
    plot_df <- plot_df[plot_df$Group %in% group_levels, , drop = FALSE]
    if (nrow(plot_df) == 0) return(NULL)
    plot_df$Group <- factor(plot_df$Group, levels = group_levels)
    
    # ---- colour palette ----
    n_groups <- length(group_levels)
    colors <- if (input$palette == "dimred_default") {
      get_color_palette("dimred_default", n_groups)
    } else if (input$palette == "default") {
      get_color_palette("default", n_groups)
    } else if (input$palette %in% c("viridis", "plasma")) {
      viridis::viridis_pal(option = input$palette)(n_groups)
    } else {
      get_color_palette(input$palette, n_groups)
    }
    if (length(colors) >= length(group_levels)) names(colors) <- group_levels
    
    # ---- create the plot using the same helpers as single-feature mode ----
    plot_obj <- switch(input$plotType,
      "Boxplot"   = create_boxplot(plot_df, colors),
      "Violin"    = create_violin_plot(plot_df, colors),
      "Ridgeline" = create_ridgeline_plot(plot_df, colors),
      "Swarm"     = create_swarm_plot(plot_df, colors),
      "Strip"     = create_strip_plot(plot_df, colors),
      create_boxplot(plot_df, colors)
    )
    
    # ---- Wrap long title text onto multiple lines ----
    title_size <- if (!is.null(input$dist_title_size)) as.numeric(input$dist_title_size) else 14
    # Estimate ~35 chars per line at default size; scale inversely with font size
    wrap_width <- max(15, round(35 * (14 / title_size)))
    wrapped_title <- paste(strwrap(feature_name, width = wrap_width), collapse = "\n")
    plot_obj <- plot_obj + ggplot2::ggtitle(wrapped_title)
    
    # Remove y-axis label for non-left plots in grid
    if (!isTRUE(show_y_axis_label)) {
      plot_obj <- plot_obj +
        labs(y = NULL) +
        theme(axis.title.y = element_blank(), axis.title.y.right = element_blank())
    }
    
    # ---- stat annotations ----
    if (isTRUE(input$showStats) && length(unique(plot_df$Group)) >= 2) {
      plot_obj <- add_stat_annotations(plot_obj, plot_df, input$sig_method)
    }
    
    plot_obj
  }
  
  # Helper: build the grid arrangeGrob object for multiple features
  build_dist_grid <- function(features) {
    n_cols <- input$dist_grid_cols %||% 2
    plot_list <- list()
    for (i in seq_along(features)) {
      col_idx <- ((i - 1) %% n_cols) + 1
      show_y_axis <- col_idx == 1
      plot_i <- tryCatch(build_single_dist_plot(features[i], show_y_axis_label = show_y_axis), error = function(e) NULL)
      if (!is.null(plot_i)) {
        plot_list[[length(plot_list) + 1]] <- plot_i
      }
    }
    if (length(plot_list) == 0) return(NULL)
    gridExtra::arrangeGrob(grobs = plot_list, ncol = n_cols)
  }
  
  # Use the reactive in the output
  output$distPlot <- renderPlot({ 
    req(input$featureSelect)
    selected_features <- input$featureSelect
    
    # Single feature: original behaviour
    if (length(selected_features) == 1) {
      values$dist_plot <- generate_dist_plot()
      values$dist_plot_is_grid <- FALSE
      return(values$dist_plot)
    }
    
    # Multiple features: grid layout
    grid_obj <- build_dist_grid(selected_features)
    if (!is.null(grid_obj)) {
      values$dist_plot <- grid_obj
      values$dist_plot_is_grid <- TRUE
      grid::grid.draw(grid_obj)
    } else {
      values$dist_plot <- NULL
      values$dist_plot_is_grid <- FALSE
      return(NULL)
    }
  }, height = function() {
    selected_features <- input$featureSelect
    if (is.null(selected_features) || length(selected_features) <= 1) {
      return(input$plotHeight)
    }
    # Each row gets the full user-specified height
    n_cols <- input$dist_grid_cols %||% 2
    n_rows <- ceiling(length(selected_features) / n_cols)
    return(input$plotHeight * n_rows)
  }, width = function() input$plotWidth, res = UI_PLOT_RES)
  
  # Create Box Plot
  create_boxplot <- function(plot_df, colors) {
    # Group ordering is already applied in generate_dist_plot via factor levels
    # Just ensure we preserve the factor levels
    if (!is.factor(plot_df$Group)) {
      plot_df$Group <- preserve_group_names(plot_df$Group)
    }
    
    # Determine display label based on dist_label_type
    display_label <- input$featureSelect
    if (!is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
        !is.null(values$accession_ids) && length(values$accession_ids) > 0) {
      # Find the index of the selected feature using helper function
      feature_idx <- get_feature_index_from_label(input$featureSelect)
      if (!is.null(feature_idx) && feature_idx <= length(values$accession_ids)) {
        display_label <- values$accession_ids[feature_idx]
      }
    }
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$dist_title_size)) input$dist_title_size else 14
    axis_title_size <- if(!is.null(input$dist_axis_title_size)) input$dist_axis_title_size else 12
    axis_text_size <- if(!is.null(input$dist_axis_text_size)) input$dist_axis_text_size else 10
    legend_text_size <- if(!is.null(input$dist_legend_text_size)) input$dist_legend_text_size else 12
    jitter_size <- if(!is.null(input$dist_jitter_size)) input$dist_jitter_size else 2
    
    # Determine y-axis label based on scaling
    y_scale <- input$dist_y_scale %||% "linear"
    y_label <- switch(y_scale,
                      "log2" = "Normalized abundance (log2)",
                      "log10" = "Normalized abundance (log10)",
                      "Normalized abundance")
    
    p <- ggplot(plot_df, aes(x = factor(Group), y = Value, fill = factor(Group))) +
      geom_boxplot(outlier.shape = if(input$showPoints) 19 else NA) +
      labs(title = paste(display_label),
           x = NULL, y = y_label) +
      scale_fill_manual(values = colors) +
      theme_minimal(base_size = 14) +
      theme(
        plot.title = element_text(hjust = 0.5, size = title_size, face = "bold"),
        axis.title.x = element_blank(),
        axis.title.y = element_text(size = axis_title_size, face = "bold", color = "black"),
        axis.line = element_line(color = "black"),
        axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
        axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold", color = "black", size = axis_text_size,
           margin = margin(t = -2, unit = "pt")),
        axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(r = -2, unit = "pt")),
        axis.ticks = element_line(color = "black", size = 0.5),
        axis.ticks.length = unit(0.2, "cm"),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 0.6),
        legend.position = "none",
        panel.background = element_rect(fill = "white", color = NA),
        plot.background = element_rect(fill = "white", color = NA)
      )
    
    # Apply y-axis scaling based on user selection
    if (y_scale == "log2") {
      p <- p + scale_y_continuous(trans = "log2", labels = scales::label_scientific(digits = 1))
    } else if (y_scale == "log10") {
      p <- p + scale_y_continuous(trans = "log10", labels = scales::label_scientific(digits = 1))
    }
    
    # Add individual points if requested
    if(input$showPoints) {
      p <- p + ggbeeswarm::geom_beeswarm(alpha = 0.6, color = "black", size = jitter_size)
    }
    
    p <- p + get_distribution_border_theme()

    # Add statistical annotations using the selected test and post-hoc method
    return(p)
  }
  
  # Create Violin Plot
  create_violin_plot <- function(plot_df, colors) {
