        axis.line = element_line(color = "black"),
        axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
        axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold", color = "black", size = axis_text_size,
           margin = margin(t = -2, unit = "pt")),
        axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(r = -2, unit = "pt")),
        axis.ticks = element_line(color = "black", size = 0.5),
        axis.ticks.length = unit(0.2, "cm"),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 0.6),
        legend.position = "none",
        panel.background = element_rect(fill = "white", color = NA),
        plot.background = element_rect(fill = "white", color = NA)
      )
    
    # Apply y-axis scaling based on user selection
    if (y_scale == "log2") {
      p <- p + scale_y_continuous(trans = "log2", labels = scales::label_scientific(digits = 1))
    } else if (y_scale == "log10") {
      p <- p + scale_y_continuous(trans = "log10", labels = scales::label_scientific(digits = 1))
    }
    
    # Add points if requested
    if(input$showPoints) {
      p <- p + ggbeeswarm::geom_beeswarm(alpha = 0.6, color = "black", size = jitter_size)
    }
    
    # Add boxplot inside the violin
    # p <- p + geom_boxplot(width = 0.1, alpha = 0.2, outlier.shape = NA)

    p <- p + get_distribution_border_theme()

    return(p)
  }
  
  # Create Ridgeline Plot
  create_ridgeline_plot <- function(plot_df, colors) {
    # Make sure ggridges is available
    if(!requireNamespace("ggridges", quietly = TRUE)) {
      install.packages("ggridges")
      library(ggridges)
    } else {
      library(ggridges)
    }
    
    # Determine display label based on dist_label_type
    display_label <- input$featureSelect
    if (!is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
        !is.null(values$accession_ids) && length(values$accession_ids) > 0) {
      # Find the index of the selected feature using helper function
      feature_idx <- get_feature_index_from_label(input$featureSelect)
      if (!is.null(feature_idx) && feature_idx <= length(values$accession_ids)) {
        display_label <- values$accession_ids[feature_idx]
      }
    }
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$dist_title_size)) input$dist_title_size else 14
    axis_title_size <- if(!is.null(input$dist_axis_title_size)) input$dist_axis_title_size else 12
    axis_text_size <- if(!is.null(input$dist_axis_text_size)) input$dist_axis_text_size else 10
    legend_text_size <- if(!is.null(input$dist_legend_text_size)) input$dist_legend_text_size else 12
    jitter_size <- if(!is.null(input$dist_jitter_size)) input$dist_jitter_size else 2
    
    p <- ggplot(plot_df, aes(x = Value, y = Group, fill = Group)) +
      ggridges::geom_density_ridges(
        alpha = 0.8,
        scale = 0.9,
        jittered_points = input$showPoints,
        point_alpha = ifelse(input$showPoints, 0.3, 0),
        point_size = ifelse(input$showPoints, jitter_size * 0.2, 0),
        quantile_lines = TRUE,
        quantiles = 2
      ) +
      scale_fill_manual(values = colors) +
      labs(
        title = paste(display_label),
        x = "Normalized abundance",
        y = NULL
      ) +
      theme_minimal(base_size = 14) +
      theme(
        plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
        legend.position = "right",
        legend.title = element_blank(),
        legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        axis.title.x = element_text(size = axis_title_size, face = "bold", color = "black"),
        axis.line = element_line(color = "black"),
        axis.title.y = element_blank(),
        axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
        axis.text.x = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(t = -2, unit = "pt")),
        axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(r = -2, unit = "pt")),
        panel.border = element_rect(color = "black", fill = NA, size = 0.6),
      )
    
    # Apply x-axis scaling based on user selection (for ridgeline, it's the x-axis)
    y_scale <- input$dist_y_scale %||% "linear"
    if (y_scale == "log2") {
      p <- p + scale_x_continuous(trans = "log2", labels = scales::label_scientific(digits = 1))
    } else if (y_scale == "log10") {
      p <- p + scale_x_continuous(trans = "log10", labels = scales::label_scientific(digits = 1))
    }
    
    p <- p + get_distribution_border_theme()

    return(p)
  }
  
  # Update create_swarm_plot function with error bar control
  create_swarm_plot <- function(plot_df, colors) {
    # Check if ggbeeswarm is available, but don't try to install it automatically
    if(!requireNamespace("ggbeeswarm", quietly = TRUE)) {
      # Return a message plot instead of trying to install the package
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Package 'ggbeeswarm' is required for swarm plots.\nPlease install it manually.",
                        hjust = 0.5, size = 6) +
               theme_void())
    }
    
    # Determine display label based on dist_label_type
    display_label <- input$featureSelect
    if (!is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
        !is.null(values$accession_ids) && length(values$accession_ids) > 0) {
      # Find the index of the selected feature using helper function
      feature_idx <- get_feature_index_from_label(input$featureSelect)
      if (!is.null(feature_idx) && feature_idx <= length(values$accession_ids)) {
        display_label <- values$accession_ids[feature_idx]
      }
    }
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$dist_title_size)) input$dist_title_size else 14
    axis_title_size <- if(!is.null(input$dist_axis_title_size)) input$dist_axis_title_size else 12
    axis_text_size <- if(!is.null(input$dist_axis_text_size)) input$dist_axis_text_size else 10
    legend_text_size <- if(!is.null(input$dist_legend_text_size)) input$dist_legend_text_size else 12
    jitter_size <- if(!is.null(input$dist_jitter_size)) input$dist_jitter_size else 2
    
    # If we get here, ggbeeswarm is available
    # Determine y scale for computing stats
    y_scale <- input$dist_y_scale %||% "linear"
    p <- ggplot(plot_df, aes(x = Group, y = Value, color = Group)) +
      ggbeeswarm::geom_beeswarm(
        alpha = 0.8,
        size = jitter_size,
        cex = 1.5
      ) +
      scale_color_manual(values = colors) +
      labs(
        title = paste(display_label),
        x = NULL,
        y = "Normalized abundance"
      ) +
      theme_minimal(base_size = 14) +
      theme(
        plot.title = element_text(hjust = 0.5, size = title_size, face = "bold"),
        axis.title.x = element_blank(),
        axis.title.y = element_text(size = axis_title_size, face = "bold", color = "black"),
        axis.line = element_line(color = "black"),
        axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
        axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold", color = "black", size = axis_text_size,
           margin = margin(t = -2, unit = "pt")),
        axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(r = -2, unit = "pt")),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 0.6),
        legend.position = "none",
        panel.background = element_rect(fill = "white", color = NA),
        plot.background = element_rect(fill = "white", color = NA)
      )
    
    # Apply y-axis scaling based on user selection
    if (y_scale == "log2") {
      p <- p + scale_y_continuous(trans = "log2", labels = scales::label_scientific(digits = 1))
    } else if (y_scale == "log10") {
      p <- p + scale_y_continuous(trans = "log10", labels = scales::label_scientific(digits = 1))
    }
    
    # Add error bars conditionally
    if(input$showStats && input$showErrorBars) {
      p <- p + stat_summary(
        fun.data = function(x) {
          if (y_scale == "linear") {
            mean_val <- mean(x, na.rm = TRUE)
            se <- sd(x, na.rm = TRUE) / sqrt(length(x))
            ymin <- mean_val - 1.96 * se
            ymax <- mean_val + 1.96 * se
          } else {
            # compute CI in log space and back-transform to avoid negative values
            pos <- x[x > 0]
            if (length(pos) == 0) {
              # fallback to original method if all values are non-positive
              mean_val <- mean(x, na.rm = TRUE)
              se <- sd(x, na.rm = TRUE) / sqrt(length(x))
              ymin <- pmax(mean_val - 1.96 * se, 1e-8)
              ymax <- mean_val + 1.96 * se
            } else {
              logx <- log10(pos)
              mean_log <- mean(logx, na.rm = TRUE)
              se_log <- sd(logx, na.rm = TRUE) / sqrt(length(logx))
              mean_val <- 10 ^ mean_log
              ymin <- 10 ^ (mean_log - 1.96 * se_log)
              ymax <- 10 ^ (mean_log + 1.96 * se_log)
            }
          }
          data.frame(y = mean_val, ymin = pmax(ymin, 1e-8), ymax = ymax)
        },
        geom = "errorbar",
        width = 0.2,
        linewidth = 1,
        color = "black"
      )
    }
    
    p <- p + get_distribution_border_theme()

    return(p)
  }
  
  # Update create_strip_plot function with error bar control
  create_strip_plot <- function(plot_df, colors) {
    # Determine display label based on dist_label_type
    display_label <- input$featureSelect
    if (!is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
        !is.null(values$accession_ids) && length(values$accession_ids) > 0) {
      # Find the index of the selected feature using helper function
      feature_idx <- get_feature_index_from_label(input$featureSelect)
      if (!is.null(feature_idx) && feature_idx <= length(values$accession_ids)) {
        display_label <- values$accession_ids[feature_idx]
      }
    }
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$dist_title_size)) input$dist_title_size else 14
    axis_title_size <- if(!is.null(input$dist_axis_title_size)) input$dist_axis_title_size else 12
    axis_text_size <- if(!is.null(input$dist_axis_text_size)) input$dist_axis_text_size else 10
    legend_text_size <- if(!is.null(input$dist_legend_text_size)) input$dist_legend_text_size else 12
    jitter_size <- if(!is.null(input$dist_jitter_size)) input$dist_jitter_size else 2
    
    # Determine y-axis label based on scaling
    y_scale <- input$dist_y_scale %||% "linear"
    y_label <- switch(y_scale,
                      "log2" = "Normalized abundance (log2)",
                      "log10" = "Normalized abundance (log10)",
                      "Normalized abundance")
    
    p <- ggplot(plot_df, aes(x = Group, y = Value, color = Group)) +
      ggbeeswarm::geom_beeswarm(
        alpha = 0.7,
        size = jitter_size
      ) +
      scale_color_manual(values = colors) +
      labs(
        title = paste(display_label),
        x = NULL,
        y = y_label
      ) +
      theme_minimal(base_size = 14) +
      theme(
        plot.title = element_text(hjust = 0.5, size = title_size, face = "bold"),
        axis.title.x = element_blank(),
        axis.title.y = element_text(size = axis_title_size, face = "bold", color = "black"),
        axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
        axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1, face = "bold", color = "black", size = axis_text_size,
           margin = margin(t = -2, unit = "pt")),
        axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black",
           margin = margin(r = -2, unit = "pt")),
        axis.ticks = element_line(color = "black", size = 0.5),
        axis.ticks.length = unit(0.2, "cm"),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 0.6),
        legend.position = "none",
        panel.background = element_rect(fill = "white", color = NA),
        plot.background = element_rect(fill = "white", color = NA)
      )
    
    # Apply y-axis scaling based on user selection
    if (y_scale == "log2") {
      p <- p + scale_y_continuous(trans = "log2", labels = scales::label_scientific(digits = 1))
    } else if (y_scale == "log10") {
      p <- p + scale_y_continuous(trans = "log10", labels = scales::label_scientific(digits = 1))
    }
    
    # Determine y scale for computing stats
    y_scale <- input$dist_y_scale %||% "linear"

    # Add summary statistics (mean + CI) if both showStats and showErrorBars are TRUE
    if(input$showStats && input$showErrorBars) {
      p <- p + stat_summary(
        fun.data = function(x) {
          if (y_scale == "linear") {
            mean_val <- mean(x, na.rm = TRUE)
            se <- sd(x, na.rm = TRUE) / sqrt(length(x))
            ymin <- mean_val - 1.96 * se
            ymax <- mean_val + 1.96 * se
          } else {
            pos <- x[x > 0]
            if (length(pos) == 0) {
              mean_val <- mean(x, na.rm = TRUE)
              se <- sd(x, na.rm = TRUE) / sqrt(length(x))
              ymin <- pmax(mean_val - 1.96 * se, 1e-8)
              ymax <- mean_val + 1.96 * se
            } else {
              logx <- log10(pos)
              mean_log <- mean(logx, na.rm = TRUE)
              se_log <- sd(logx, na.rm = TRUE) / sqrt(length(logx))
              mean_val <- 10 ^ mean_log
              ymin <- 10 ^ (mean_log - 1.96 * se_log)
              ymax <- 10 ^ (mean_log + 1.96 * se_log)
            }
          }
          data.frame(y = mean_val, ymin = pmax(ymin, 1e-8), ymax = ymax)
        },
        geom = "errorbar",
        width = 0.2,
        linewidth = 1,
        color = "black"
      )
    }
    
    p <- p + get_distribution_border_theme()

    return(p)
  }
  
  # Add statistical annotations
  add_stat_annotations <- function(plot_obj, plot_df, test_method) {
    # Guard: ensure plot_obj is a ggplot object
    if (!inherits(plot_obj, "ggplot")) {
      message("add_stat_annotations: plot_obj is not a ggplot object; returning original object")
      return(plot_obj)
    }
    # Get the selected post-hoc method
    posthoc_method <- input$posthoc_method
    
    # Check if we have at least 2 groups
    if (length(unique(plot_df$Group)) < 2) {
      return(plot_obj)  # Return plot without annotations if only one group
    }
    
    # Get feature name and index
    feature_name <- unique(plot_df$Feature_Name)
    feature_idx <- unique(plot_df$Feature_Index)[1]
    
    # Determine y scale and plot type early so we can use them in messages/operators
    y_scale <- input$dist_y_scale %||% "linear"
    is_ridgeline <- identical(input$plotType, "Ridgeline")
    message("Statistical annotation search for feature: ", feature_name)
    # Debug info: y_scale and is_ridgeline (commented out) - enable for deep debugging if needed
    # message("add_stat_annotations: y_scale = ", y_scale, "; is_ridgeline = ", is_ridgeline)
    
    # Get all possible group comparisons
    # Get all possible group comparisons using ORIGINAL group names for stat lookup
    # Don't use the display group names (which may have been modified by preserve_group_names)
    # Instead, match them back to original group names for stat column lookup
    group_levels <- unique(plot_df$Group)
    # Convert to character in case it's a factor
    group_levels <- as.character(group_levels)
    comparisons <- combn(group_levels, 2, simplify = FALSE)

    # Filter comparisons based on user selection (if provided)
    # Prefer persisted custom selection so explicit "none selected" is respected
    # even when the input temporarily evaluates to NULL during re-render.
    selected_comparisons <- values$dist_stat_comparisons_custom
    if (is.null(selected_comparisons)) {
      selected_comparisons <- input$dist_stat_comparisons
    }

    # Explicitly cleared comparisons: draw no significance annotations
    if (!is.null(selected_comparisons) && length(selected_comparisons) == 0) {
      return(plot_obj)
    }

    # Check both forward and reverse orders since group reordering changes comparison order
    if (!is.null(selected_comparisons) && length(selected_comparisons) > 0) {
      comparisons <- Filter(function(comp) {
        comp_label_forward <- paste(comp[1], "vs", comp[2])
        comp_label_reverse <- paste(comp[2], "vs", comp[1])
        comp_label_forward %in% selected_comparisons || comp_label_reverse %in% selected_comparisons
      }, comparisons)
    }
    
    # Helper function to convert display group name back to original format for stat lookup
    # This handles the preserve_group_names transformation
    to_original_format <- function(name) {
      # If we have original group names stored, use them for stat lookup
      if (!is.null(values$unique_groups)) {
        # Try exact match first
        if (name %in% values$unique_groups) {
          return(name)
        }
        # Try matching with space/underscore conversions
        for (orig_name in values$unique_groups) {
          if (gsub("\\s+", "_", orig_name) == gsub("\\s+", "_", name)) {
            return(orig_name)
          }
        }
      }
      # Fallback: return as-is
      return(name)
    }
    
    # Calculate the maximum y-value for positioning the annotations
    # Respect plot type and scale: ridgeline plots use the x-axis for values
    value_axis <- if (is_ridgeline) "x" else "y"
    max_y <- max(plot_df$Value, na.rm = TRUE)
    # For log scales, ensure we have a positive max to compute multiplicative spacing
    y_scale <- input$dist_y_scale %||% "linear"
    if (y_scale != "linear") {
      max_y_pos <- max(plot_df$Value[plot_df$Value > 0], na.rm = TRUE)
      if (is.na(max_y_pos) || is.infinite(max_y_pos)) {
        # fallback to raw max if no positive values found
        max_y_pos <- max_y
      }
      max_y <- max_y_pos
    }
    
    # First pass: check if any annotations will be added
    has_annotations <- FALSE
    annotations_to_add <- list()
    
    for (comp in comparisons) {
      # Create comparison name using ORIGINAL group names for stat lookup
      orig_comp_1 <- to_original_format(comp[1])
      orig_comp_2 <- to_original_format(comp[2])
      comparison_name <- paste(orig_comp_1, "vs", orig_comp_2)
      comparison_name_us <- paste(gsub(" ", "_", orig_comp_1), "vs", gsub(" ", "_", orig_comp_2))
      
      # Use the common function to get appropriate p-value column
      p_value_col <- get_appropriate_pvalue_column(comparison_name)
      if (is.null(p_value_col) && !identical(comparison_name_us, comparison_name)) {
        p_value_col <- get_appropriate_pvalue_column(comparison_name_us)
      }
      
      # Check if the column exists and get the value
      if (!is.null(values$stat_results) && !is.null(p_value_col) && p_value_col %in% colnames(values$stat_results)) {
        p_value <- values$stat_results[feature_idx, p_value_col]
        
        # Check for FDR when ROTS is used
        use_fdr_filter <- input$sig_method == "rots"
        fdr_passes <- TRUE  # Default to passing FDR filter
        
        if (use_fdr_filter) {
          # Derive comparison base from the p-value column to ensure consistent naming
          comparison_base <- sub("_(AdjPValue|AdjustedPValue|Bootstrap_AdjPValue|PValue|Bootstrap_PValue)$", "", p_value_col)
          fdr_col <- paste0(comparison_base, "_FDR")
          if (fdr_col %in% colnames(values$stat_results)) {
            fdr_value <- values$stat_results[feature_idx, fdr_col]
            fdr_threshold <- input$dist_fdr_cutoff %||% input$fdr_cutoff %||% 0.05
            fdr_passes <- !is.na(fdr_value) && fdr_value < fdr_threshold
          }
        }
        
        # Check if this annotation will be displayed
        if (!is.na(p_value) && p_value < 0.05 && fdr_passes) {
          has_annotations <- TRUE
          annotations_to_add[[length(annotations_to_add) + 1]] <- list(
            comp = comp,
            p_value = p_value,
            p_value_col = p_value_col
          )
        }
      }
    }
    
    # If no annotations will be added, return the plot without modifications
    if (!has_annotations) {
      return(plot_obj)
    }
    
    # Calculate appropriate starting heights and spacing based on number of actual annotations
    num_annotations <- length(annotations_to_add)
    # Provide different spacing strategies for linear vs log scales
    if (y_scale == "linear") {
      height_step <- 0.1 * max_y  # Spacing between annotation bars (linear additive)
      # Dynamically calculate expansion needed based on number of annotations
      # Each annotation needs approximately 0.1 * max_y of space, plus 0.05 for the first one
      expansion_needed <- 1.05 + (num_annotations - 1) * 0.1
    } else {
      # For log scales, use multiplicative spacing so vertical deltas remain visible
      height_step_factor <- input$dist_annotation_spacing %||% 1.10  # User-configurable multiplicative step
      # Expansion is multiplicative in log space: raise factor to number of annotations
      expansion_needed <- 1.05 * (height_step_factor ^ (num_annotations - 1))
      # Add a small top buffer (3%) so the topmost annotation doesn't touch the top border on log scales
      annotation_top_buffer <- 0.03
      expansion_needed <- expansion_needed * (1 + annotation_top_buffer)
      height_step <- height_step_factor
    }
    
    # Only add plot margin expansion if annotations will actually be displayed
    # For log scales make sure lower bound is positive to avoid log10 issues
    if (y_scale != "linear") {
      min_y_pos <- min(plot_df$Value[plot_df$Value > 0], na.rm = TRUE)
      if (is.na(min_y_pos) || is.infinite(min_y_pos)) min_y_pos <- 1e-8
    } else {
      min_y_pos <- min(plot_df$Value, na.rm = TRUE)
    }
    if (is_ridgeline) {
      plot_obj <- plot_obj +
        expand_limits(x = c(min_y_pos * 0.9, max_y * expansion_needed)) +
        coord_cartesian(clip = "off") +
        get_distribution_border_theme()
    } else {
      plot_obj <- plot_obj +
        expand_limits(y = c(min_y_pos * 0.9, max_y * expansion_needed)) +
        coord_cartesian(clip = "off") +
        get_distribution_border_theme()
    }
    
    # Add the filtered significance annotations
    for (i in seq_along(annotations_to_add)) {
      anno <- annotations_to_add[[i]]
      comp <- anno$comp
      p_value <- anno$p_value
      p_value_col <- anno$p_value_col
      
      # Calculate axis position (y for most plots, x for ridgeline) with buffer
      # For linear scales we add an additive step; for log scales use multiplicative steps
      if (y_scale == "linear") {
        axis_position <- max_y * 1.03 + (i - 1) * height_step
      } else {
        axis_position <- max_y * (1.03 * (height_step ^ (i - 1)))
      }
      if (is_ridgeline) {
        x_position <- axis_position
        # Map group names to numeric or factor positions for y
        group_levels <- unique(plot_df$Group)
        # Fallback if group levels are not found
        g1_idx <- which(group_levels == comp[1])
        g2_idx <- which(group_levels == comp[2])
        if (length(g1_idx) == 0) g1_idx <- 1
        if (length(g2_idx) == 0) g2_idx <- 2
        y_position <- mean(c(g1_idx, g2_idx))
      } else {
        y_position <- axis_position
      }
      
      # message("Adding annotation for: ", paste(comp[1], "vs", comp[2]), "; y_position(computed) = ", axis_position)
      
      sig_symbol <- ifelse(p_value < 0.001, "***",
                           ifelse(p_value < 0.01, "**", "*"))
      
      # Bootstrap indicator - color blue if using bootstrap
      use_bootstrap_color <- grepl("Bootstrap", p_value_col)
      sig_color <- if(use_bootstrap_color) "#287BDE" else "black"
      
      if (!is_ridgeline) {
        # For log scales, convert the data-space y_position into transformed scale units
        y_position_to_use <- y_position
        if (y_scale == "log10") {
          # Use log10 transformed coordinate so it matches other layers that are transformed
          y_position_to_use <- log10(y_position)
        } else if (y_scale == "log2") {
          y_position_to_use <- log2(y_position)
        }
        # message("add_stat_annotations: adding geom_signif with y_position_to_use=", y_position_to_use)
        plot_obj <- plot_obj +
          ggsignif::geom_signif(
          comparisons = list(c(comp[1], comp[2])),
          annotations = sig_symbol,
          y_position = y_position_to_use,
          tip_length = 0.005,  # Very short tips for minimal spacing
          textsize = 9,
          vjust = 0.5,  # Positive value pushes star down toward bracket line
          fontface = "bold",
          color = sig_color,
          margin_top = 0
        )
      } else {
        # Add ridgeline-specific annotation: a vertical segment + label
        # Use annotate/geom_segment to place labels and a short connector between ridge lines
        plot_obj <- plot_obj +
          annotate("text", x = x_position, y = y_position, label = sig_symbol, color = sig_color, fontface = "bold", size = 4)
        plot_obj <- plot_obj +
          geom_segment(aes(x = x_position, xend = x_position, y = g1_idx + 0.2, yend = g2_idx - 0.2), color = sig_color, linewidth = 0.6, inherit.aes = FALSE)
      }
    }
    
    return(plot_obj)
  }
  
  # Calculate statistics for the data table and statistics panel
  calculate_distribution_stats <- function(plot_df, test_method) {
    # Feature name and index for looking up precomputed stats
    feature_name <- input$featureSelect
    feature_idx <- which(values$cleaned_molecules == feature_name)
    
    # Calculate summary statistics by group
    summary_stats <- plot_df %>%
      dplyr::group_by(Group) %>%
      dplyr::summarise(
        N = n(),
        Mean = mean(Value, na.rm = TRUE),
        SD = sd(Value, na.rm = TRUE),
        SEM = SD/sqrt(N),
        Median = median(Value, na.rm = TRUE),
        Q1 = quantile(Value, 0.25, na.rm = TRUE),
        Q3 = quantile(Value, 0.75, na.rm = TRUE),
        Min = min(Value, na.rm = TRUE),
        Max = max(Value, na.rm = TRUE),
        CV = (SD/Mean) * 100
      )
    
    # Store for data table
    values$dist_summary_stats <- summary_stats
    
    # Look up statistical test results from precomputed statistics
    test_results <- NULL
    groups <- unique(plot_df$Group)
    
    if(length(groups) >= 2) {
      if(length(groups) == 2) {
        # For pairwise comparison
        comparison_name <- paste(groups[1], "vs", groups[2])
        
        # Get the appropriate p-value and fold change columns
        p_value_column <- get_appropriate_pvalue_column(comparison_name)
        fc_column <- get_foldchange_column(comparison_name)
        
        # Check if precomputed stats are available
        if(!is.null(values$stat_results) && p_value_column %in% colnames(values$stat_results)) {
          # Get precomputed p-value and fold change
          p_value <- values$stat_results[feature_idx, p_value_column]
          
          # Get fold change if available
          fc <- if(fc_column %in% colnames(values$stat_results)) {
            values$stat_results[feature_idx, fc_column]
          } else {
            NA
          }
          
          # Create test results object
          if(grepl("wilcox", p_value_column, ignore.case = TRUE)) {
            test_results <- list(
              method = "Wilcoxon rank sum test (precomputed)",
              overall = list(p.value = p_value, statistic = NA, fold_change = fc),
              posthoc = NULL
            )
          } else {
            test_results <- list(
              method = "t-test (precomputed)",
              overall = list(p.value = p_value, statistic = NA, fold_change = fc),
              posthoc = NULL
            )
          }
        }
      } else if(test_method == "anova") {
        # For ANOVA
        if(!is.null(values$stat_results) && "ANOVA_AdjustedPValue" %in% colnames(values$stat_results)) {
          p_value <- values$stat_results[feature_idx, "ANOVA_AdjustedPValue"]
          
          test_results <- list(
            method = "One-way ANOVA (precomputed)",
            overall = list(p.value = p_value),
            posthoc = NULL
          )
          
          # Check for post-hoc test results
          if(!is.null(values$stat_results$PostHoc_Method) &&
             values$stat_results$PostHoc_Method[feature_idx] != "N/A") {
            
            posthoc_results <- list()
            
            # Look for post-hoc columns for this feature
            for(i in 1:(length(groups)-1)) {
              for(j in (i+1):length(groups)) {
                posthoc_col <- paste0(groups[i], " vs ", groups[j], "_PostHoc_PValue")
                if(posthoc_col %in% colnames(values$stat_results)) {
                  posthoc_p <- values$stat_results[feature_idx, posthoc_col]
                  if(!is.na(posthoc_p)) {
                    posthoc_results[[paste(groups[i], "vs", groups[j])]] <- posthoc_p
                  }
                }
              }
            }
            
            if(length(posthoc_results) > 0) {
              test_results$posthoc <- posthoc_results
            }
          }
        }
      } else if(test_method == "kw") {
        # For Kruskal-Wallis
        if(!is.null(values$stat_results) && "KW_AdjustedPValue" %in% colnames(values$stat_results)) {
          p_value <- values$stat_results[feature_idx, "KW_AdjustedPValue"]
          
          test_results <- list(
            method = "Kruskal-Wallis test (precomputed)",
            overall = list(p.value = p_value),
            posthoc = NULL
          )
          
          # Check for post-hoc test results
          if(!is.null(values$stat_results$PostHoc_Method) &&
             values$stat_results$PostHoc_Method[feature_idx] != "N/A") {
            
            posthoc_results <- list()
            
            # Look for post-hoc columns for this feature
            for(i in 1:(length(groups)-1)) {
              for(j in (i+1):length(groups)) {
                posthoc_col <- paste0(groups[i], " vs ", groups[j], "_PostHoc_PValue")
                if(posthoc_col %in% colnames(values$stat_results)) {
                  posthoc_p <- values$stat_results[feature_idx, posthoc_col]
                  if(!is.na(posthoc_p)) {
                    posthoc_results[[paste(groups[i], "vs", groups[j])]] <- posthoc_p
                  }
                }
              }
            }
            
            if(length(posthoc_results) > 0) {
              test_results$posthoc <- posthoc_results
            }
          }
        }
      }
    }
    
    # Store test results
    values$dist_test_results <- test_results
    
    # Generate statistics output text
    stats_text <- paste0(
      "Summary Statistics for ", input$featureSelect, "\n",
      "========================================\n\n"
    )
    
    # Add summary stats table
    stats_text <- paste0(
      stats_text,
      "Group-wise Summary:\n",
      "-------------------\n"
    )
    
    # Format stats table
    for(i in 1:nrow(summary_stats)) {
      group <- summary_stats$Group[i]
      stats_text <- paste0(
        stats_text,
        group, ":\n",
        "  N = ", summary_stats$N[i], "\n",
        "  Mean   SD = ", round(summary_stats$Mean[i], 3), "   ", round(summary_stats$SD[i], 3), "\n",
        "  SEM = ", round(summary_stats$SEM[i], 3), "\n",
        "  Median (Q1-Q3) = ", round(summary_stats$Median[i], 3), " (",
        round(summary_stats$Q1[i], 3), "-", round(summary_stats$Q3[i], 3), ")\n",
        "  Range = ", round(summary_stats$Min[i], 3), " to ", round(summary_stats$Max[i], 3), "\n",
        "  CV = ", round(summary_stats$CV[i], 2), "%\n\n"
      )
    }
    
    # Add statistical test results if available
    if(!is.null(test_results)) {
      stats_text <- paste0(
        stats_text,
        "Statistical Tests (Precomputed):\n",
        "-------------------\n",
        "Test method: ", test_results$method, "\n\n"
      )
      
      # Overall test results
      if(!is.null(test_results$overall$p.value)) {
        p_value <- test_results$overall$p.value
        stats_text <- paste0(
          stats_text,
          "Overall test p-value: ", format.pval(p_value, digits = 3), "\n"
        )
        
        # Add FDR information when ROTS is used and pairwise comparison
        if(test_method == "rots" && length(groups) == 2) {
          comparison_name <- paste(groups[1], "vs", groups[2])
          fdr_col <- paste0(comparison_name, "_FDR")
          if(fdr_col %in% colnames(values$stat_results)) {
            fdr_value <- values$stat_results[feature_idx, fdr_col]
            fdr_threshold <- input$dist_fdr_cutoff %||% input$fdr_cutoff %||% 0.05
            fdr_sig_text <- if(!is.na(fdr_value) && fdr_value < fdr_threshold) " *" else ""
            stats_text <- paste0(
              stats_text,
              "FDR: ", format.pval(fdr_value, digits = 3), fdr_sig_text, "\n",
              "FDR threshold: ", fdr_threshold, "\n"
            )
          }
        }
        
        if(!is.null(test_results$overall$fold_change)) {
          fc <- test_results$overall$fold_change
          stats_text <- paste0(
            stats_text,
            "Fold change (log2): ", round(fc, 3), "\n"
          )
        }
        
        stats_text <- paste0(stats_text, "\n")
      }
      
      # Post-hoc results if available
      if(!is.null(test_results$posthoc) && length(test_results$posthoc) > 0) {
        stats_text <- paste0(
          stats_text,
          "Post-hoc test results:\n"
        )
        
        for(comp in names(test_results$posthoc)) {
          p_val <- test_results$posthoc[[comp]]
          
          # Check FDR for ROTS when showing post-hoc results
          show_significant <- p_val < 0.05
          if(test_method == "rots") {
            fdr_col <- paste0(comp, "_FDR")
            if(fdr_col %in% colnames(values$stat_results)) {
              fdr_value <- values$stat_results[feature_idx, fdr_col]
              fdr_threshold <- input$dist_fdr_cutoff %||% input$fdr_cutoff %||% 0.05
              show_significant <- show_significant && (!is.na(fdr_value) && fdr_value < fdr_threshold)
            }
          }
          
          stats_text <- paste0(
            stats_text,
            comp, ": p = ", format.pval(p_val, digits = 3),
            if(show_significant) " *" else "", "\n"
          )
        }
        
        stats_text <- paste0(stats_text, "\n")
      }
    } else {
      stats_text <- paste0(
        stats_text,
        "Statistical Tests:\n",
        "-------------------\n",
        "No precomputed statistics found for this feature or comparison.\n",
        "Please run the statistical analysis in the Data tab first.\n\n"
      )
    }
    
    # Additional normality assessment (keep this as it's just calculating on current data, not statistical testing)
    stats_text <- paste0(
      stats_text,
      "\nNormality Assessment:\n",
      "----------------------\n"
    )
    
    # Check normality for the selected feature using Shapiro-Wilk test
    feature_data <- plot_df$Value
    
    # Only perform test if we have 3-5000 samples
    if(length(feature_data) >= 3 && length(feature_data) <= 5000) {
      sw_test <- shapiro.test(feature_data)
      
      stats_text <- paste0(
        stats_text,
        "Shapiro-Wilk normality test for selected feature:\n",
        "W = ", round(sw_test$statistic, 3),
        ", p = ", format.pval(sw_test$p.value, digits = 3),
        if(sw_test$p.value < 0.05) " (data may not be normally distributed)" else " (data appears normally distributed)",
        "\n\n"
      )
    } else if(length(feature_data) > 5000) {
      # For large datasets, sample 5000 points
      sample_data <- sample(feature_data, 5000)
      sw_test <- shapiro.test(sample_data)
      
      stats_text <- paste0(
        stats_text,
        "Shapiro-Wilk normality test for selected feature (5000 sampled points):\n",
        "W = ", round(sw_test$statistic, 3),
        ", p = ", format.pval(sw_test$p.value, digits = 3),
        if(sw_test$p.value < 0.05) " (data may not be normally distributed)" else " (data appears normally distributed)",
        "\n\n"
      )
    } else {
      stats_text <- paste0(
        stats_text,
        "Shapiro-Wilk normality test for selected feature:\n",
        "Insufficient data for normality test (n < 3)\n\n"
      )
    }
    # Update the statistical output
    output$distStats <- renderText({
      stats_text
    })
    
    # Cache status output for Data tab
    output$cache_status <- renderText({
      # Check if cache lists are initialized
      if (is.null(values$processing_cache)) {
        return("Cache system initializing...")
      }
      
      # Add reactive dependency on cache update counter to ensure updates
      update_counter <- values$cache_update_counter %||% 0
      
      # Add reactive dependency on ID cache trigger
      id_cache_trigger <- values$id_cache_trigger %||% 0
      
      # Also invalidate every 2 seconds to ensure we catch ID cache changes
      invalidateLater(2000)
      
      # Explicit reactive dependencies to trigger updates
      values$processing_cache
      values$statistical_cache
      values$normalization_cache
      values$imputation_cache
      values$batch_correction_cache
      values$pca_cache
      values$spca_cache
      
      # Add reactive dependencies for proteomics caches (with safety checks)
      if (exists("proteomics_values") && !is.null(proteomics_values)) {
        proteomics_values$current_plots
        proteomics_values$network_plots
        proteomics_values$enrichment_cache
      }
      
      # Make it reactive to all cache changes
      processing_count <- length(values$processing_cache %||% list())
      statistical_count <- length(values$statistical_cache %||% list())
      normalization_count <- length(values$normalization_cache %||% list())
      imputation_count <- length(values$imputation_cache %||% list())
      batch_correction_count <- length(values$batch_correction_cache %||% list())
      pca_count <- length(values$pca_cache %||% list())
      spca_count <- length(values$spca_cache %||% list())
      
      # Add proteomics cache counts (with safety checks)
      proteomics_plot_count <- 0
      proteomics_network_count <- 0
      proteomics_enrichment_count <- 0
      
      if (exists("proteomics_values") && !is.null(proteomics_values)) {
        proteomics_plot_count <- length(proteomics_values$current_plots %||% list())
        proteomics_network_count <- length(proteomics_values$network_plots %||% list())
        proteomics_enrichment_count <- length(proteomics_values$enrichment_cache %||% list())
      }
      
      # Add ID conversion cache count
      id_cache_stats <- get_id_cache_stats()
      id_conversion_count <- id_cache_stats$entries
      
      total_count <- processing_count + statistical_count + normalization_count +
        imputation_count + batch_correction_count + pca_count + spca_count +
        proteomics_plot_count + proteomics_network_count + proteomics_enrichment_count +
        id_conversion_count
      
      if (total_count == 0) {
        return(paste0("Cache empty - no cached results (Updates: ", update_counter, ", ID Trigger: ", id_cache_trigger, ")"))
      }
      
      paste0("Cache status: ", total_count, " items cached (Updates: ", update_counter, ", ID Trigger: ", id_cache_trigger, ") | ",
             "Processing: ", processing_count, " | ",
             "Statistical: ", statistical_count, " | ",
             "Normalization: ", normalization_count, " | ",
             "Imputation: ", imputation_count, " | ",
             "Batch Correction: ", batch_correction_count, " | ",
             "PCA: ", pca_count, " | ",
             "sPCA: ", spca_count, " | ",
             "Proteomics Plots: ", proteomics_plot_count, " | ",
             "Network Plots: ", proteomics_network_count, " | ",
             "Enrichment: ", proteomics_enrichment_count, " | ",
             "ID Conversions: ", id_conversion_count)
    })
    
    # Observer for manual cache clearing
    observeEvent(input$clear_all_caches, {
      clear_analysis_caches("manual clear request")
      
      # Clear proteomics cache (uses separate reactiveValues store)
      clear_proteomics_plot_cache()
      
      showNotification("All caches cleared successfully", type = "message", duration = 3)
      cat("Manual cache clear requested - all caches cleared\n")
    })
    
    # Update the data table
    output$distDataTable <- DT::renderDataTable({
      req(values$current_dist_data)
      
      # Create a display-friendly version of the data
      display_df <- values$current_dist_data
      
      # Rename columns for better display
      colnames(display_df) <- c("Measurement Value", "Group", "Sample Name", "Feature", "Feature Index")
      
      # Reorder columns for better presentation
      display_df <- display_df[, c("Sample Name", "Group", "Measurement Value", "Feature", "Feature Index")]
      
      # Round numeric values for better display
      if ("Measurement Value" %in% colnames(display_df)) {
        display_df[["Measurement Value"]] <- round(display_df[["Measurement Value"]], 4)
      }
      
      DT::datatable(
        display_df,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          autoWidth = TRUE,
          columnDefs = list(
            list(visible = FALSE, targets = c(4))  # Hide Feature Index column (0-based indexing)
          )
        ),
        rownames = FALSE,
        caption = paste("Data for", input$featureSelect)
      ) %>%
        DT::formatStyle(
          "Group",
          backgroundColor = DT::styleEqual(
            unique(display_df$Group),
            rainbow(length(unique(display_df$Group)), alpha = 0.3)
          )
        )
    })
  }
  
  # Generate all distribution plots
  # Generate all distribution plots - changed to downloadHandler for directory selection
  output$generateAllDistPlots <- downloadHandler(
    filename = function() {
      paste0("Distribution_Plots_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".zip")
    },
    content = function(file) {
      req(values$normalized_data, values$cleaned_molecules,
          values$unique_groups, values$group_column_indices)
      
      # Check if statistical results are available
      if(is.null(values$stat_results)) {
        showNotification("Please run statistical analysis in the Data tab first", type = "warning")
        return(NULL)
      }
      
      # Create temporary directory for plots
      temp_dir <- tempdir()
      plot_dir <- file.path(temp_dir, paste0("Distribution_Plots_", format(Sys.time(), "%Y%m%d_%H%M%S")))
      dir.create(plot_dir, showWarnings = FALSE, recursive = TRUE)
      
      withProgress(message = "Generating distribution plots", value = 0, {
        # Get selected features first
        selected_idx <- get_feature_indices_by_source(input$dist_feature_source, "All Groups")
        n_features <- length(selected_idx)
        
        # Check if any features are available
        if (n_features == 0) {
          showNotification(
            paste("No features available from",
                  switch(input$dist_feature_source,
                         "pca" = "PCA analysis",
                         "ml" = "ML feature selection",
                         "all" = "all features",
                         "selected source"),
                  "- please check your feature source selection"),
            type = "error"
          )
          return(NULL)
        }
        
        # Get plot type and color settings
        plot_type <- input$plotType
        palette <- input$palette
        show_points <- input$showPoints
        show_stats <- input$showStats
        
        # Counter for tracking progress
        plots_generated <- 0
        feature_counter <- 0
        
        # Process each feature
        for (i in selected_idx) {
          feature_counter <- feature_counter + 1
          feature <- values$cleaned_molecules[i]
          
          setProgress(feature_counter / n_features, detail = paste("Processing", feature))
          
          tryCatch({
            # Extract data for the feature
            feature_data <- values$normalized_data[i, ]
            
            # Get the proper column order and corresponding data
            all_columns <- unlist(values$group_column_indices)
            feature_data_reordered <- feature_data[all_columns]
            sample_names_reordered <- colnames(values$normalized_data)[all_columns]
            
            # Create cleaned sample names using corrected names function
            cleaned_sample_names <- get_corrected_column_names(sample_names_reordered)
            
            # Create data frame for plotting - IMPORTANT: Add Feature_Name and Feature_Index for annotations
            plot_df <- data.frame(
              Value = as.numeric(feature_data_reordered),
              Group = create_proper_group_labels(values$unique_groups, values$group_column_indices),
              Sample = cleaned_sample_names,
              Feature_Name = feature,
              Feature_Index = i,
              stringsAsFactors = FALSE
            )
            
            # Remove NA values
            plot_df <- plot_df[!is.na(plot_df$Value), ]
            
            # Skip if not enough data
            if(nrow(plot_df) < 3) {
              next
            }
            
            # Apply manual group ordering based on user selection
            current_groups <- preserve_group_names(get_active_unique_groups() %||% values$unique_groups)
            available_groups <- unique(plot_df$Group)
            # Use stored custom order if available, falling back to input then data order
            manual_order <- values$dist_group_order_custom
            if (is.null(manual_order) || length(manual_order) == 0) {
              manual_order <- input$dist_group_order
            }
            if (is.null(manual_order) || length(manual_order) == 0) {
              group_levels <- current_groups
            } else {
              group_levels <- manual_order
            }
            group_levels <- group_levels[group_levels %in% available_groups]
            # Add only truly new groups (not ones the user removed)
            base_groups <- values$dist_group_order_base_groups %||% character()
            new_groups <- setdiff(available_groups, base_groups)
            new_groups <- new_groups[new_groups %in% available_groups & !(new_groups %in% group_levels)]
            group_levels <- c(group_levels, new_groups)
            if (length(group_levels) == 0) {
              group_levels <- available_groups
            }
            # Remove groups that were explicitly removed from the order
            plot_df <- plot_df[plot_df$Group %in% group_levels, , drop = FALSE]
            if (nrow(plot_df) == 0) {
              next
            }
            plot_df$Group <- factor(plot_df$Group, levels = group_levels)
            
            # Set color palette
            n_groups <- length(group_levels %||% values$unique_groups)
            colors <- if (palette == "dimred_default") {
              get_color_palette("dimred_default", n_groups)
            } else if (palette == "default") {
              get_color_palette("default", n_groups)
            } else if (palette %in% c("viridis", "plasma")) {
              viridis::viridis_pal(option = palette)(n_groups)
            } else {
              get_color_palette(palette, n_groups)
            }
            if (!is.null(group_levels) && length(colors) >= length(group_levels)) {
              names(colors) <- group_levels
            }
            
            # Create plot based on plot type
            plot_obj <- switch(plot_type,
                               "Boxplot" = create_boxplot(plot_df, colors),
                               "Violin" = create_violin_plot(plot_df, colors),
                               "Ridgeline" = create_ridgeline_plot(plot_df, colors),
                               #"Raincloud" = create_raincloud_plot(plot_df, colors),
                               "Swarm" = create_swarm_plot(plot_df, colors),
                               "Strip" = create_strip_plot(plot_df, colors),
                               # Default to boxplot if an invalid type is selected
                               create_boxplot(plot_df, colors)
            )
            
            # Add statistical annotations if requested and there are at least 2 groups
            if(show_stats && length(unique(plot_df$Group)) >= 2) {
              # Add annotations using precomputed stats - plot_df now has Feature_Name and Feature_Index
              plot_obj <- add_stat_annotations(plot_obj, plot_df, input$sig_method)
            }
            
            # Update title with feature name
            plot_obj <- plot_obj + labs(title = feature)
            
            # Get plot dimensions from UI inputs, convert from pixels to inches
            plot_width <- (input$plotWidth %||% 500) / 100  # Convert pixels to inches
            plot_height <- (input$plotHeight %||% 500) / 100  # Convert pixels to inches
            
            # Save the plot
            file_name <- file.path(plot_dir, paste0(gsub("[^a-zA-Z0-9]", "_", feature), "_", plot_type, ".", get_safe_global_image_format()))
            # Apply current border style consistently for exported files
            export_plot <- plot_obj + get_distribution_border_theme()
            ggsave(file_name, export_plot, width = plot_width, height = plot_height, dpi = 300, device = resolve_ggsave_device(get_safe_global_image_format()))
            
            # Increment counter
            plots_generated <- plots_generated + 1
            
          }, error = function(e) {
            message(paste("Error generating plot for", feature, ":", e$message))
          })
        }
        
        # Create ZIP file
        if (plots_generated > 0) {
          setProgress(1, detail = "Creating ZIP file...")
          
          # Get list of files - match the current image format
          image_format <- get_safe_global_image_format()
          pattern <- paste0("\\.", image_format, "$")
          plot_files <- list.files(plot_dir, full.names = TRUE, pattern = pattern)
          
          # Create ZIP file
          zip::zip(zipfile = file, files = basename(plot_files), root = plot_dir)
          
          # Show completion message
          showNotification(paste0(plots_generated, " distribution plots generated and saved to ZIP file!"),
                           type = "message", duration = 5)
        } else {
          showNotification("No plots were generated. Please check your data and settings.",
                           type = "error", duration = 5)
        }
      })
    }
  )
  
  # Download distribution plot
  output$downloadDistPlot <- downloadHandler(
    filename = function() {
      features <- input$featureSelect
      if (length(features) > 1) {
        name_part <- paste0("Grid_", length(features), "_features")
      } else {
        name_part <- gsub("[^a-zA-Z0-9]", "_", features)
      }
      paste0("Distribution_Plot_", name_part, "_",
             input$plotType, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(values$dist_plot)
      
      dpi          <- get_safe_global_dpi()
      image_format <- get_safe_global_image_format()
      plot_width   <- (input$plotWidth %||% 800) / 100   # px -> inches
      
      selected_features <- input$featureSelect
      is_grid <- isTRUE(values$dist_plot_is_grid) && length(selected_features) > 1
      
      if (is_grid) {
        # Grid download: height = per-plot height * number of rows
        n_cols  <- input$dist_grid_cols %||% 2
        n_rows  <- ceiling(length(selected_features) / n_cols)
        plot_height <- (input$plotHeight %||% 600) / 100 * n_rows
        
        device_fn <- resolve_ggsave_device(image_format)
        # arrangeGrob is a grob, use ggsave's ability to handle it
        ggsave(file, values$dist_plot, width = plot_width, height = plot_height,
               dpi = dpi, device = device_fn)
      } else {
        # Single plot download
        plot_height <- (input$plotHeight %||% 600) / 100
        ggsave(file, values$dist_plot, width = plot_width, height = plot_height,
               dpi = dpi, device = resolve_ggsave_device(image_format))
      }
    }
  )
  
  # Disable download button initially
  observe({
    shinyjs::toggleState("downloadDistPlot", !is.null(values$dist_plot))
