  # Helper function to get custom colors for PCA
  get_pca_colors <- function() {
    if (is.null(values$unique_groups)) {
      return(NULL)
    }
    
    # If custom colors are enabled, use the custom color inputs
    if (isTRUE(input$pca_custom_colors)) {
      colors <- sapply(seq_along(values$unique_groups), function(i) {
        color_input <- input[[paste0("pca_color_", i)]]
        if (is.null(color_input)) {
          default_colors <- c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
                              "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf")
          return(default_colors[((i - 1) %% length(default_colors)) + 1])
        }
        return(color_input)
      })
    } else {
      # Use consistent dimred default colors even when custom colors are disabled
      default_colors <- c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
                          "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf")
      colors <- sapply(seq_along(values$unique_groups), function(i) {
        return(default_colors[((i - 1) %% length(default_colors)) + 1])
      })
    }
    
    names(colors) <- values$unique_groups
    return(colors)
  }
  
# Helper function to calculate optimal legend grid layout
get_legend_grid_layout <- function(n_items) {
  n_items <- max(1, n_items %||% 1)
  
  if (n_items < 4) {
    # For 1-3 items, use single row
    return(list(nrow = 1, ncol = n_items))
  }
  
  # For 4+ items, make grid as square as possible
  sqrt_n <- sqrt(n_items)
  nrows <- floor(sqrt_n)
  if (nrows == 0) {
    nrows <- 1
  }
  ncols <- ceiling(n_items / nrows)
  
  # Ensure we don't exceed reasonable limits
  if (ncols > 4) {
    ncols <- 4
    nrows <- ceiling(n_items / ncols)
  }
  
  return(list(nrow = nrows, ncol = ncols))
}
  
  # Helper function to get custom colors for sPCA
  get_spca_colors <- function() {
    if (is.null(values$unique_groups)) {
      return(NULL)
    }
    
    # If custom colors are enabled, use the custom color inputs
    if (isTRUE(input$spca_custom_colors)) {
      colors <- sapply(seq_along(values$unique_groups), function(i) {
        color_input <- input[[paste0("spca_color_", i)]]
        if (is.null(color_input)) {
          default_colors <- c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
                              "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf")
          return(default_colors[((i - 1) %% length(default_colors)) + 1])
        }
        return(color_input)
      })
    } else {
      # Use consistent dimred default colors even when custom colors are disabled
      default_colors <- c("#1f77b4", "#ff7f0e", "#2ca02c", "#d62728", "#9467bd",
                          "#8c564b", "#e377c2", "#7f7f7f", "#bcbd22", "#17becf")
      colors <- sapply(seq_along(values$unique_groups), function(i) {
        return(default_colors[((i - 1) %% length(default_colors)) + 1])
      })
    }
    
    names(colors) <- values$unique_groups
    return(colors)
  }
  
  # Generate PCA with Data tab priority
  observe({
    # Explicitly depend on current_tab to ensure observer re-triggers when returning to Dimensionality Reduction tab
    current_tab <- input$current_tab
    
    # Only run PCA computations when the Dimensionality Reduction tab is active
    if (is.null(current_tab) || current_tab != "Dimensionality Reduction") {
      return()
    }
    # Pause heavy PCA operations if Data tab is active (priority loading)
    if (isTRUE(values$data_tab_active)) {
      return()
    }
    
    # Explicitly depend on active_grouping_level to trigger re-computation when it changes
    grouping_level <- values$active_grouping_level %||% "single"
    
    req(values$normalized_data, values$unique_groups, values$group_column_indices,
        input$pcaType)
    
    # Create cache key based on critical parameters
    cache_key <- paste(
      input$pcaType,
      if(input$pcaType == "pairwise") paste(input$pcaGroup1, input$pcaGroup2, sep="_") else "all_groups",
      input$pcaScale,
      input$pca_feature_source,
      input$pca_top_features,
      input$pca_feature_ranking,
      values$active_grouping_level %||% "single",
      digest::digest(values$normalized_data, algo = "md5"),
      sep = "_"
    )
    
    # Check if we have cached results
    if (!is.null(values$pca_cache[[cache_key]])) {
      cat("Using cached PCA result\n")
      cached_result <- values$pca_cache[[cache_key]]
      values$pca_result <- cached_result$pca_result
      values$pca_data <- cached_result$pca_data
      values$pca_labels <- cached_result$pca_labels
      values$comparison_name <- cached_result$comparison_name
      return()
    }
    
    # Validate current inputs to prevent unnecessary recalculation
    current_inputs <- list(
      pcaType = input$pcaType,
      pcaGroup1 = input$pcaGroup1,
      pcaGroup2 = input$pcaGroup2,
      pcaScale = input$pcaScale,
      pca_feature_source = input$pca_feature_source,
      pca_top_features = input$pca_top_features,
      pca_feature_ranking = input$pca_feature_ranking
    )
    
    # Skip execution if inputs haven't changed significantly
    if (!is.null(values$last_pca_inputs) && identical(current_inputs, values$last_pca_inputs)) {
      return()
    }
    
    isolate({
      values$last_pca_inputs <- current_inputs
    })
    
    withProgress(message = "Generating PCA...", {
      tryCatch({
        # Get feature indices based on selected source
        feature_indices <- get_feature_indices_by_source(input$pca_feature_source %||% "all", "All Groups")
        
        # Apply feature filtering
        if (!is.null(feature_indices) && length(feature_indices) > 0) {
          pca_data <- values$normalized_data[feature_indices, , drop = FALSE]
          feature_names <- values$cleaned_molecules[feature_indices]
        } else {
          pca_data <- values$normalized_data
          feature_names <- values$cleaned_molecules
        }
        
        if (input$pcaType == "pairwise") {
          # Pairwise PCA
          req(input$pcaGroup1, input$pcaGroup2)
          
          if (input$pcaGroup1 == input$pcaGroup2) {
            showNotification("Please select two different groups for pairwise PCA", type = "warning")
            return()
          }
          
          # Get group indices
          group1_idx <- which(values$unique_groups == input$pcaGroup1)
          group2_idx <- which(values$unique_groups == input$pcaGroup2)
          
          if (length(group1_idx) == 0 || length(group2_idx) == 0) {
            showNotification("Invalid group selection", type = "error")
            return()
          }
          
          # Extract data for selected groups
          group1_columns <- values$group_column_indices[[group1_idx]]
          group2_columns <- values$group_column_indices[[group2_idx]]
          
          # Combine data from both groups
          selected_data <- pca_data[, c(group1_columns, group2_columns), drop = FALSE]
          
          # Create group labels
          group_labels <- c(
            rep(input$pcaGroup1, length(group1_columns)),
            rep(input$pcaGroup2, length(group2_columns))
          )
          
          # Check minimum feature count
          if (nrow(selected_data) < 2) {
            showNotification("Not enough features for PCA analysis. Consider improving data preprocessing in the Missing Value Handling step.", type = "error")
            return()
          }
          
          # Transpose for PCA (samples as rows, features as columns)
          pca_input <- t(selected_data)
          
          # Check minimum sample count
          if (nrow(pca_input) < 2) {
            showNotification("Not enough samples for PCA analysis. Consider improving data preprocessing in the Missing Value Handling step.", type = "error")
            return()
          }
          
          # Perform PCA - let R handle missing values gracefully
          tryCatch({
            pca_result <- prcomp(pca_input, scale. = input$pcaScale %||% TRUE, na.action = na.omit)
          }, error = function(e) {
            showNotification(paste("PCA analysis failed:", e$message, ". Consider improving data preprocessing in the Missing Value Handling step."), type = "error")
            return()
          })
          
          # Store results
          values$pca_result <- pca_result
          values$pca_data <- pca_input
          values$pca_labels <- group_labels
          values$comparison_name <- paste(input$pcaGroup1, "vs", input$pcaGroup2)
          
        } else {
          # All groups analysis - use data as processed by the pipeline
          all_data <- pca_data
          
          # Transpose for PCA (samples as rows, features as columns)
          pca_input <- t(all_data)
          
          # Create group labels for all samples - use the active grouping level
          if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
            if (values$active_grouping_level == "biological") {
              all_group_labels <- create_proper_group_labels(values$biological_unique_groups, values$biological_group_column_indices)
            } else {
              all_group_labels <- create_proper_group_labels(values$experimental_unique_groups, values$experimental_group_column_indices)
            }
          } else {
            all_group_labels <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
          }
          
          # Basic validation - ensure we have minimum required dimensions
          if (nrow(pca_input) < 2) {
            showNotification("Not enough samples for PCA analysis. Minimum 2 samples required.", type = "error")
            return()
          }
          
          if (ncol(pca_input) < 2) {
            showNotification("Not enough features for PCA analysis. Minimum 2 features required.", type = "error")
            return()
          }
          
          # Perform PCA - let R handle missing values gracefully
          tryCatch({
            pca_result <- prcomp(pca_input, scale. = input$pcaScale %||% TRUE, na.action = na.omit)
          }, error = function(e) {
            showNotification(paste("PCA analysis failed:", e$message, ". Consider improving data preprocessing in the Missing Value Handling step."), type = "error")
            return()
          })
          
          # Store results
          values$pca_result <- pca_result
          values$pca_data <- pca_input
          values$pca_labels <- all_group_labels
          values$comparison_name <- "All Groups"
        }
        
        # Cache results
        values$pca_cache[[cache_key]] <- list(
          pca_result = values$pca_result,
          pca_data = values$pca_data,
          pca_labels = values$pca_labels,
          comparison_name = values$comparison_name
        )
        
        showNotification("PCA analysis completed successfully", type = "message")
        
      }, error = function(e) {
        showNotification(paste("PCA analysis failed:", e$message), type = "error")
        values$pca_result <- NULL
      })
    })
  })
  
  # Trigger PCA computation when switching to Dimensionality Reduction tab if not yet computed
  observeEvent(input$current_tab, {
    if (identical(input$current_tab, "Dimensionality Reduction")) {
      # Check if PCA computation is needed (All Groups mode and no result yet)
      if (identical(input$pcaType, "all") && 
          is.null(values$pca_result) &&
          !is.null(values$normalized_data) &&
          !is.null(values$unique_groups) &&
          !is.null(values$group_column_indices)) {
        # Trigger the main PCA observer by invalidating cache
        values$pca_cache <- list()
      }
    }
  })
  
  # Populate feature selector when data loads
  observeEvent(values$cleaned_molecules, {
    req(values$cleaned_molecules)
    
    # Update the feature selector with available features
    feature_choices <- as.list(values$cleaned_molecules)
    names(feature_choices) <- values$cleaned_molecules
    
    updateSelectizeInput(session, "viz_selected_feature",
                        choices = feature_choices,
                        selected = if(length(values$cleaned_molecules) > 0) values$cleaned_molecules[1] else NULL)
  }, ignoreNULL = TRUE)
  
  # Show/hide feature selector based on plot type
  observeEvent(input$viz_plot_type, {
    # Show feature selector only for plot types that support per-feature analysis
    if (input$viz_plot_type %in% c("hist", "density", "qq")) {
      shinyjs::show("viz_feature_select_options")
    } else {
      shinyjs::hide("viz_feature_select_options")
    }
  })
  
  # Auto-refresh PCA when new normalized data is loaded
  observeEvent(list(values$normalized_data, input$pca_group_order, input$pcaType, values$active_grouping_level), {
    req(values$normalized_data)
    # Clear existing PCA cache and result
    values$pca_cache <- list()
    values$pca_result <- NULL
    values$pca_data <- NULL
    values$pca_labels <- NULL
    values$comparison_name <- NULL
    
    # Automatically recompute All Groups PCA (pairwise is computed on-the-fly in the plot code)
    if (!is.null(input$pcaType) && identical(input$pcaType, "all")) {
      # Resolve active grouping structures
      if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
        if (values$active_grouping_level == "biological") {
          active_groups <- values$biological_unique_groups
          active_indices <- values$biological_group_column_indices
        } else {
          active_groups <- values$experimental_unique_groups
          active_indices <- values$experimental_group_column_indices
        }
      } else {
        active_groups <- values$unique_groups
        active_indices <- values$group_column_indices
      }

      active_groups <- preserve_group_names(active_groups %||% character())
      selected_groups <- input$pca_group_order
      if (is.null(selected_groups) || length(selected_groups) == 0) {
        active_pairwise <- get_active_pairwise_combinations()
        if (!is.null(active_pairwise) && nrow(active_pairwise) > 0) {
          pairwise_groups <- unique(c(as.character(active_pairwise$Group_1), as.character(active_pairwise$Group_2)))
          pairwise_groups <- preserve_group_names(pairwise_groups)
          selected_groups <- pairwise_groups[pairwise_groups %in% active_groups]
          if (length(selected_groups) < 2) {
            selected_groups <- active_groups
          }
        } else {
          selected_groups <- active_groups
        }
      } else {
        selected_groups <- preserve_group_names(selected_groups)
      }
      selected_groups <- selected_groups[selected_groups %in% active_groups]

      if (length(selected_groups) >= 2 && !is.null(active_indices)) {
        selected_col_indices <- unlist(active_indices[active_groups %in% selected_groups], use.names = FALSE)
        selected_col_indices <- sort(unique(as.integer(selected_col_indices)))
        selected_col_indices <- selected_col_indices[selected_col_indices >= 1 & selected_col_indices <= ncol(values$normalized_data)]

        if (length(selected_col_indices) >= 2) {
          pca_input <- tryCatch(t(values$normalized_data[, selected_col_indices, drop = FALSE]), error = function(e) NULL)
          all_group_labels <- tryCatch(create_proper_group_labels(active_groups, active_indices), error = function(e) NULL)
          if (!is.null(all_group_labels)) {
            all_group_labels <- preserve_group_names(all_group_labels)
            all_group_labels <- all_group_labels[selected_col_indices]
            if (!is.null(pca_input) && nrow(pca_input) >= 2 && ncol(pca_input) >= 2 && length(all_group_labels) == nrow(pca_input)) {
              tryCatch({
                pca_res <- prcomp(pca_input, scale. = input$pcaScale %||% TRUE, na.action = na.omit)
                values$pca_result <- pca_res
                values$pca_data <- pca_input
                values$pca_labels <- all_group_labels
                values$comparison_name <- "All Groups"
                # Store in cache under a simple auto key so downstream components remain compatible
                auto_key <- paste0("auto_all_", nrow(pca_input), "x", ncol(pca_input), "_scale_", as.character(input$pcaScale %||% TRUE), "_grouping_", values$active_grouping_level %||% "single", "_selected_", paste(selected_groups, collapse = "|"))
                values$pca_cache[[auto_key]] <- list(
                  pca_result = values$pca_result,
                  pca_data = values$pca_data,
                  pca_labels = values$pca_labels,
                  comparison_name = values$comparison_name
                )
              }, error = function(e) {
              })
            }
          }
        }
      }
    }
    # Minor reactive flag to force any dependent UI to re-evaluate
    values$pca_autorefresh <- Sys.time()
  }, ignoreNULL = TRUE)
  
  # PCA Plot Output
  output$pcaPlot <- renderPlot({ 
    req(values$normalized_data, values$unique_groups)
    
    # Check if there are any valid features after filtering
    if (is.null(values$normalized_data) || nrow(values$normalized_data) == 0 || 
        is.null(values$cleaned_molecules) || length(values$cleaned_molecules) == 0) {
      return(ggplot() + 
               annotate("text", x = 0.5, y = 0.5, 
                        label = "No valid features available after filtering. Please check your data.", 
                        size = 6) + 
               theme_void())
    }
    
    available_groups <- preserve_group_names(get_active_unique_groups() %||% values$unique_groups)
    selected_pca_groups <- input$pca_group_order
    if (is.null(selected_pca_groups) || length(selected_pca_groups) == 0) {
      active_pairwise <- get_active_pairwise_combinations()
      if (!is.null(active_pairwise) && nrow(active_pairwise) > 0) {
        pairwise_groups <- unique(c(as.character(active_pairwise$Group_1), as.character(active_pairwise$Group_2)))
        pairwise_groups <- preserve_group_names(pairwise_groups)
        selected_pca_groups <- pairwise_groups[pairwise_groups %in% available_groups]
        if (length(selected_pca_groups) < 2) {
          selected_pca_groups <- available_groups
        }
      } else {
        selected_pca_groups <- available_groups
      }
    } else {
      selected_pca_groups <- preserve_group_names(selected_pca_groups)
    }
    selected_pca_groups <- selected_pca_groups[selected_pca_groups %in% available_groups]
    
    # Get font sizes from inputs or use defaults (ensure numeric)
    title_size <- as.numeric(if(!is.null(input$pca_title_size) && is.numeric(input$pca_title_size)) input$pca_title_size else 14)
    axis_title_size <- as.numeric(if(!is.null(input$pca_axis_title_size) && is.numeric(input$pca_axis_title_size)) input$pca_axis_title_size else 12)
    axis_text_size <- as.numeric(if(!is.null(input$pca_axis_text_size) && is.numeric(input$pca_axis_text_size)) input$pca_axis_text_size else 10)
    legend_text_size <- as.numeric(if(!is.null(input$pca_legend_text_size) && is.numeric(input$pca_legend_text_size)) input$pca_legend_text_size else 12)
    jitter_size <- as.numeric(if(!is.null(input$pca_jitter_size) && is.numeric(input$pca_jitter_size)) input$pca_jitter_size else 2)
    
    if (input$pcaType == "pairwise") {
      # Generate grid of pairwise PCA plots - only for comparisons in current_pairwise_combinations
      req(values$unique_groups, length(values$unique_groups) >= 2)

      # Use active-level pairwise combinations (mirrors Differential Analysis behavior)
      active_pairwise <- get_active_pairwise_combinations()
      if (is.null(active_pairwise) || nrow(active_pairwise) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No pairwise comparisons available for PCA. Please configure comparisons in the Statistical Analysis tab.",
                          size = 5) +
                 theme_void())
      }

      if (length(selected_pca_groups) >= 2) {
        active_pairwise <- active_pairwise[
          active_pairwise$Group_1 %in% selected_pca_groups & active_pairwise$Group_2 %in% selected_pca_groups,
          , drop = FALSE
        ]
      }

      if (is.null(active_pairwise) || nrow(active_pairwise) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No pairwise PCA plots for currently selected groups.",
                          size = 5) +
                 theme_void())
      }

      pairwise_plots <- list()

      # De-duplicate pairwise combinations while preserving order
      combos_df <- active_pairwise
      if (!is.null(combos_df) && nrow(combos_df) > 1) {
        combo_keys <- apply(combos_df[, c("Group_1", "Group_2"), drop = FALSE], 1, function(row) {
          groups <- sort(c(as.character(row["Group_1"]), as.character(row["Group_2"])))
          paste(groups[1], groups[2], sep = "__")
        })
        combos_df <- combos_df[!duplicated(combo_keys), , drop = FALSE]
      }
      
      # Convert the pairwise combinations data frame to a list format
      group_combinations <- lapply(1:nrow(combos_df), function(i) {
        c(combos_df[i, "Group_1"],
          combos_df[i, "Group_2"])
      })

      for (combo_idx in seq_along(group_combinations)) {
        group1 <- group_combinations[[combo_idx]][1]
        group2 <- group_combinations[[combo_idx]][2]

        # Find indices for these groups
        group1_idx <- which(values$unique_groups == group1)
        group2_idx <- which(values$unique_groups == group2)

        if (length(group1_idx) == 0 || length(group2_idx) == 0) next

        # Get indices for the two groups being compared
        group1_cols <- values$group_column_indices[[group1_idx]]
        group2_cols <- values$group_column_indices[[group2_idx]]
        # Preserve original data order among selected columns
        selected_cols <- sort(c(group1_cols, group2_cols))

        # Skip if too few samples
        if (length(selected_cols) < 2) next
          
          # Get data for this comparison
          pca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
          # Map each selected column to its originating group
          groups_subset <- vapply(selected_cols, function(ci) {
            if (ci %in% group1_cols) group1 else group2
          }, character(1))
          
          # Run PCA
          tryCatch({
            pairwise_pca <- prcomp(pca_data_subset, scale = input$pcaScale)
            
            # Create PCA plot for this pair
            pc_scores <- as.data.frame(pairwise_pca$x)
            group_levels <- get_group_order_for_plot(c(group1, group2))
            pc_scores$Group <- factor(preserve_group_names(groups_subset), levels = group_levels)
            
            # Add sample labels if requested
            if (input$pca_show_outlier_labels) {
              pc_scores$SampleLabels <- NA_character_
              original_sample_names <- rownames(pca_data_subset)
              cleaned_sample_names <- get_corrected_column_names(original_sample_names)
              
              # Determine outliers within each group separately using PC1/PC2 Mahalanobis distance.
              # Use the exact threshold used by ggplot2::stat_ellipse(type = "t")
              conf_level <- input$ellipseLevel %||% 0.95
              conf_level <- min(max(conf_level, 0.5), 0.999)
              outlier_idx <- integer(0)
              
              for (grp in unique(as.character(pc_scores$Group))) {
                grp_idx <- which(as.character(pc_scores$Group) == grp)
                if (length(grp_idx) == 0) next
                
                grp_xy <- as.matrix(pc_scores[grp_idx, c("PC1", "PC2"), drop = FALSE])
                valid_rows <- apply(grp_xy, 1, function(v) all(is.finite(v)))
                if (sum(valid_rows) < 3) next
                
                grp_idx_valid <- grp_idx[valid_rows]
                grp_xy <- grp_xy[valid_rows, , drop = FALSE]
                
                # Use MASS::cov.trob to match ggplot2::stat_ellipse(type = "t") robust covariance
                cov_est <- tryCatch({
                  MASS::cov.trob(grp_xy)
                }, error = function(e) {
                  list(cov = stats::cov(grp_xy), center = colMeans(grp_xy))
                })
                
                cov_mat <- cov_est$cov
                center_pt <- cov_est$center
                
                if (any(!is.finite(cov_mat))) next
                
                # Calculate Mahalanobis distance (squared)
                md2 <- tryCatch({
                  stats::mahalanobis(
                    x = grp_xy,
                    center = center_pt,
                    cov = cov_mat + diag(1e-8, 2)
                  )
                }, error = function(e) rep(0, nrow(grp_xy)))
                
                # Match ggplot2's stat_ellipse(type = "t") threshold EXACTLY
                n <- nrow(grp_xy)
                md_threshold <- 2 * stats::qf(conf_level, 2, n - 1)
                
                grp_outlier_pos <- which(md2 > md_threshold)
                if (length(grp_outlier_pos) > 0) {
                  outlier_idx <- c(outlier_idx, grp_idx_valid[grp_outlier_pos])
                }
              }
              
              outlier_idx <- sort(unique(outlier_idx))
              if (length(outlier_idx) > 0) {
                pc_scores$SampleLabels[outlier_idx] <- cleaned_sample_names[outlier_idx]
              }
            } else if (input$showPCALabels) {
              original_sample_names <- rownames(pca_data_subset)
              cleaned_sample_names <- get_corrected_column_names(original_sample_names)
              pc_scores$SampleLabels <- cleaned_sample_names
            }
            
            # Calculate variance explained
            variance_explained <- summary(pairwise_pca)$importance[2, ] * 100
            pc1_var <- round(variance_explained[1], 1)
            pc2_var <- round(variance_explained[2], 1)
            
            # Create plot with consistent styling
            if(input$showSampleCounts) {
              counts <- table(pc_scores$Group)
              new_labels <- paste0(names(counts), " (n=", counts, ")")
              ordered_levels <- levels(pc_scores$Group)
              
              pair_plot <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 2, alpha = 0.8) +
                labs(
                  title = paste(group1, "vs", group2),
                  x = paste0("PC1 (", pc1_var, "%)"),
                  y = paste0("PC2 (", pc2_var, "%)")
                )
              
              # Apply custom colors if enabled
              custom_colors <- get_pca_colors()
              if (!is.null(custom_colors)) {
                pairwise_colors <- custom_colors[ordered_levels]
                pair_plot <- pair_plot +
                  scale_color_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
                  scale_fill_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
              } else {
                pair_plot <- pair_plot +
                  scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
                  scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
              }
              
              pair_plot <- pair_plot +
                ggprism::theme_prism(base_size = 10) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.5),
                  axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
                  axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = legend_text_size, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
                  panel.border = element_rect(color = "black", fill = NA, size = 0.5),
                  legend.position = ifelse(input$pcaGridLegend, "bottom", "none"),
                  plot.margin = ggplot2::margin(t = 15, r = 15, b = 15, l = 15, unit = "pt")
                )
            } else {
              pair_plot <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 2, alpha = 0.8) +
                labs(
                  title = paste(group1, "vs", group2),
                  x = paste0("PC1 (", pc1_var, "%)"),
                  y = paste0("PC2 (", pc2_var, "%)")
                )
              
              # Apply custom colors if enabled
              custom_colors <- get_pca_colors()
              ordered_levels <- levels(pc_scores$Group)
              if (!is.null(custom_colors)) {
                pairwise_colors <- custom_colors[ordered_levels]
                pair_plot <- pair_plot +
                  scale_color_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels) +
                  scale_fill_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels)
              } else {
                pair_plot <- pair_plot +
                  scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels) +
                  scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels)
              }
              
              pair_plot <- pair_plot +
                ggprism::theme_prism(base_size = 10) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.5),
                  axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
                  axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = legend_text_size, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
                  panel.border = element_rect(color = "black", fill = NA, size = 0.5),
                  legend.position = ifelse(input$pcaGridLegend, "bottom", "none"),
                  plot.margin = ggplot2::margin(t = 15, r = 15, b = 15, l = 15, unit = "pt")
                )
            }
            
            # Add sample labels if requested
            if ("SampleLabels" %in% names(pc_scores) && any(!is.na(pc_scores$SampleLabels))) {
              label_data <- pc_scores[!is.na(pc_scores$SampleLabels) & pc_scores$SampleLabels != "", , drop = FALSE]
              pair_plot <- pair_plot + ggrepel::geom_text_repel(
                data = label_data,
                aes(label = SampleLabels),
                size = input$pca_pairwise_label_size %||% 2.5,
                box.padding = 0.4,
                point.padding = 0.25,
                segment.color = "grey50",
                max.overlaps = 50,
                fontface = "bold",
                inherit.aes = TRUE,
                show.legend = FALSE
              )
            }
            
            # Add ellipses if requested
            if (input$addEllipses) {
              # Check if ellipses are possible (need at least 3 points per group)
              ellipse_possible <- all(table(groups_subset) >= 3)
              if (ellipse_possible) {
                pair_plot <- pair_plot + stat_ellipse(
                  aes(fill = Group),
                  geom = "polygon",
                  alpha = 0.2,
                  level = input$ellipseLevel,
                  show.legend = FALSE
                )
              }
            }
            
            pairwise_plots[[length(pairwise_plots) + 1]] <- pair_plot
            
          }, error = function(e) {
            # Skip failed PCAs
          })
        }

      if (length(pairwise_plots) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No valid pairwise comparisons available for PCA",
                          size = 6) +
                 theme_void())
      }
      
      # Arrange plots in grid
      grid_cols <- input$pcaGridCols %||% 2
      grid_plot <- patchwork::wrap_plots(pairwise_plots, ncol = grid_cols)
      
      # Store the grid plot for download
      values$pca_grid_obj <- grid_plot
      values$pca_grid_count <- length(pairwise_plots)
      
      # Clear hover data for grid mode (hover not supported on patchwork grids)
      values$pca_hover_data <- NULL
      
      return(grid_plot)
      
    } else {
      # Single PCA plot for all groups
      if (length(selected_pca_groups) < 2) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Select at least 2 groups to run All Groups PCA.",
                          size = 6) +
                 theme_void())
      }

      if (is.null(values$pca_result)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "PCA calculation failed. Please process data first.",
                          size = 6) +
                 theme_void())
      }
      
      # Extract PC scores from the PCA result
      pc_scores <- as.data.frame(values$pca_result$x)
      
      # Add group information and labels
      group_levels <- get_group_order_for_plot(unique(values$pca_labels))
      pc_scores$Group <- factor(preserve_group_names(values$pca_labels), levels = group_levels)
      
      # Always add sample names for hover tooltip
      pc_scores$Sample <- get_corrected_column_names(rownames(values$pca_data))
      if (length(pc_scores$Sample) != nrow(pc_scores)) {
        pc_scores$Sample <- paste0("Sample_", 1:nrow(pc_scores))
      }
      
      # Store hover data for tooltip
      values$pca_hover_data <- pc_scores[, c("PC1", "PC2", "Group", "Sample"), drop = FALSE]
      
      # Add sample labels if requested
      if (input$pca_show_outlier_labels) {
        pc_scores$SampleLabels <- NA_character_
        conf_level <- input$ellipseLevel %||% 0.95
        conf_level <- min(max(conf_level, 0.5), 0.999)
        outlier_idx <- integer(0)
        
        for (grp in unique(as.character(pc_scores$Group))) {
          grp_idx <- which(as.character(pc_scores$Group) == grp)
          if (length(grp_idx) == 0) next
          
          grp_xy <- as.matrix(pc_scores[grp_idx, c("PC1", "PC2"), drop = FALSE])
          valid_rows <- apply(grp_xy, 1, function(v) all(is.finite(v)))
          if (sum(valid_rows) < 3) next
          
          grp_idx_valid <- grp_idx[valid_rows]
          grp_xy <- grp_xy[valid_rows, , drop = FALSE]
          
          cov_est <- tryCatch({
            MASS::cov.trob(grp_xy)
          }, error = function(e) {
            list(cov = stats::cov(grp_xy), center = colMeans(grp_xy))
          })
          
          if (any(!is.finite(cov_est$cov))) next
          
          md2 <- tryCatch({
            stats::mahalanobis(
              x = grp_xy,
              center = cov_est$center,
              cov = cov_est$cov + diag(1e-8, 2)
            )
          }, error = function(e) rep(0, nrow(grp_xy)))
          
          n_points <- nrow(grp_xy)
          md_threshold <- 2 * stats::qf(conf_level, 2, n_points - 1)
          
          grp_outlier_pos <- which(md2 > md_threshold)
          if (length(grp_outlier_pos) > 0) {
            outlier_idx <- c(outlier_idx, grp_idx_valid[grp_outlier_pos])
          }
        }
        
        outlier_idx <- sort(unique(outlier_idx))
        if (length(outlier_idx) > 0) {
          pc_scores$SampleLabels[outlier_idx] <- pc_scores$Sample[outlier_idx]
        }
      } else if(input$showPCALabels) {
        pc_scores$SampleLabels <- pc_scores$Sample
      }
      
      # Calculate variance explained
      variance_explained <- summary(values$pca_result)$importance[2, ] * 100
      pc1_var <- round(variance_explained[1], 1)
      pc2_var <- round(variance_explained[2], 1)
      
      n_groups <- length(unique(pc_scores$Group))
      show_pca_legend <- isTRUE(input$pcaGridLegend %||% TRUE)
      legend_position <- if (show_pca_legend) "bottom" else "none"
      
      # Create base plot (either with sample counts or without)
      if(input$showSampleCounts) {
        counts <- table(pc_scores$Group)
        new_labels <- paste0(names(counts), " (n=", counts, ")")
        ordered_levels <- levels(pc_scores$Group)
        
        # Create plot with sample counts
        p <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(
            title = values$comparison_name %||% "PCA Analysis",
            x = paste0("PC1 (", pc1_var, "%)"),
            y = paste0("PC2 (", pc2_var, "%)")
          )
        
        # Apply custom colors if enabled
        custom_colors <- get_pca_colors()
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p +
            scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        } else {
          p <- p +
            scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        }
        
        p <- p +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = legend_text_size, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = legend_position
          )
      } else {
        p <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(
            title = values$comparison_name %||% "PCA Analysis",
            x = paste0("PC1 (", pc1_var, "%)"),
            y = paste0("PC2 (", pc2_var, "%)")
          )
        
        # Apply custom colors if enabled
        custom_colors <- get_pca_colors()
        ordered_levels <- levels(pc_scores$Group)
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p +
            scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels)
        } else {
          p <- p +
            scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels)
        }
        
        p <- p +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = legend_text_size, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = legend_position,
            plot.margin = ggplot2::margin(t = 10, r = 10, b = 10, l = 10, unit = "pt")  # Extra bottom margin for legend
          )
      }
      
      # Add sample labels if requested
      if ("SampleLabels" %in% names(pc_scores) && any(!is.na(pc_scores$SampleLabels))) {
        label_data <- pc_scores[!is.na(pc_scores$SampleLabels) & pc_scores$SampleLabels != "", , drop = FALSE]
        p <- p + ggrepel::geom_text_repel(
          data = label_data,
          aes(label = SampleLabels),
          size = input$pca_sample_label_size %||% 3.5,
          box.padding = 0.5,
          point.padding = 0.3,
          segment.color = "grey50",
          max.overlaps = 50,
          fontface = "bold",
          inherit.aes = TRUE,
          show.legend = FALSE
        )
      }
      
      # Add confidence ellipses if requested
      if(input$addEllipses) {
        ellipse_possible <- all(table(values$pca_labels) >= 3)
        if (ellipse_possible) {
          p <- p + stat_ellipse(
            aes(fill = Group),
            geom = "polygon",
            alpha = 0.2,
            level = input$ellipseLevel,
            show.legend = FALSE
          )
        }
      }
      
      if (show_pca_legend && n_groups > 0) {
        legend_layout <- get_legend_grid_layout(n_groups)
        legend_guide <- guide_legend(
          nrow = legend_layout$nrow,
          ncol = legend_layout$ncol,
          byrow = TRUE
        )
        p <- p + guides(color = legend_guide, fill = legend_guide)
      }
      
      # Add persistent clicked sample labels (these appear in downloads)
      clicked <- values$pca_clicked_samples
      if (length(clicked) > 0 && "Sample" %in% names(pc_scores)) {
        label_data <- pc_scores[pc_scores$Sample %in% clicked, , drop = FALSE]
        if (nrow(label_data) > 0) {
          p <- p + ggrepel::geom_label_repel(
            data = label_data,
            aes(x = PC1, y = PC2, label = Sample),
            size = input$pca_sample_label_size %||% 3.5,
            fontface = "bold",
            color = "black",
            fill = "white",
            box.padding = 0.5,
            point.padding = 0.3,
            segment.color = "grey40",
            segment.size = 0.5,
            max.overlaps = 50,
            show.legend = FALSE,
            inherit.aes = FALSE
          )
        }
      }
      
      # Store the plot for both single plot view and download
      values$pca_plot_obj <- p
      values$pca_grid_obj <- p  # For "All Groups", the grid object is the same as the single plot
      return(p)
    }
  },
  height = function() {
    if (input$pcaType == "pairwise") {
      # Calculate grid height
      n_groups <- length(values$unique_groups) %||% 0
      n_plots <- if (!is.null(values$pca_grid_count)) values$pca_grid_count else if (n_groups < 2) 0 else n_groups * (n_groups - 1) / 2
      grid_cols <- input$pcaGridCols %||% 2
      n_rows <- ceiling(n_plots / grid_cols)
      grid_height <- input$pcaGridHeight %||% 400
      max(300, n_rows * grid_height)
    } else {
      input$pcaAllHeight %||% 600
    }
  },
  width = function() {
    if (input$pcaType == "pairwise") {
      grid_cols <- input$pcaGridCols %||% 2
      grid_width <- input$pcaGridWidth %||% 400
      grid_cols * grid_width
    } else {
      input$pcaAllWidth %||% 800
    }
  }
  )
  
  # PCA hover tooltip - shows sample name when hovering over a point
  output$pcaPlot_tooltip <- renderUI({
    hover <- input$pcaPlot_hover
    if (is.null(hover) || is.null(values$pca_hover_data)) return(NULL)
    
    point <- nearPoints(values$pca_hover_data, hover, xvar = "PC1", yvar = "PC2",
                        threshold = 10, maxpoints = 1)
    if (nrow(point) == 0) return(NULL)
    
    left_px <- hover$coords_css$x
    top_px <- hover$coords_css$y
    
    div(
      style = paste0(
        "position: absolute; z-index: 100; pointer-events: none; ",
        "background: rgba(0,0,0,0.8); color: white; padding: 6px 10px; ",
        "border-radius: 4px; font-size: 12px; font-weight: bold; ",
        "left: ", left_px + 12, "px; top: ", top_px + 12, "px;"
      ),
      tags$span(point$Sample[1]),
      tags$br(),
      tags$span(style = "font-weight: normal; font-size: 11px; color: #ccc;",
                paste0("Group: ", point$Group[1]))
    )
  })
  
  # PCA click-to-label: toggle persistent sample labels on the plot
  observeEvent(input$pcaPlot_click, {
    click <- input$pcaPlot_click
    if (is.null(click) || is.null(values$pca_hover_data)) return()
    
    point <- nearPoints(values$pca_hover_data, click, xvar = "PC1", yvar = "PC2",
                        threshold = 10, maxpoints = 1)
    if (nrow(point) == 0) return()
    
    sample_name <- point$Sample[1]
    current <- values$pca_clicked_samples %||% character(0)
    
    if (sample_name %in% current) {
      # Remove if already selected (toggle off)
      values$pca_clicked_samples <- setdiff(current, sample_name)
    } else {
      # Add to selection
      values$pca_clicked_samples <- c(current, sample_name)
    }
  })
  
  # Clear all PCA clicked labels
  observeEvent(input$clearPCALabelsBtn, {
    values$pca_clicked_samples <- character(0)
  })
  
  output$pcaFeaturesContributionPlot <- renderPlot({ 
    # Use context-aware PCA result so switching Analysis type or groups updates this plot
    pca_ctx <- NULL
    safe_pca <- NULL
    # Guard against transient invalid pairwise selection
    try(pca_ctx <- pca_result_for_current_context(), silent = TRUE)
    if (is.null(pca_ctx)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Feature contribution plot unavailable: PCA calculation failed.\nTry selecting different groups or features with more variation.",
                 size = 6, hjust = 0.5) +
        theme_void() +      theme(plot.margin = ggplot2::margin(25, 25, 25, 25))
    } else {
      safe_pca <- pca_ctx
      top_features_df <- get_top_pca_features(safe_pca, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
      
      # Remove any rows with NA Feature names
      top_features_df <- top_features_df[!is.na(top_features_df$Feature), ]
      
      if (nrow(top_features_df) == 0) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "No features available for contribution plot.",
                   size = 6, hjust = 0.5) +
          theme_void() +
          theme(plot.margin = ggplot2::margin(25, 25, 25, 25))    } else {
            # Determine if we're showing all features or top N
            total_features <- nrow(safe_pca$rotation)
            showing_all <- (is.null(input$pca_top_features) || is.na(input$pca_top_features) ||
                              length(input$pca_top_features) == 0 ||
                              input$pca_top_features >= total_features)
            # Get the ranking method display name
            ranking_names <- c(
              "overall" = "Overall Contribution",
              "pc1" = "PC1 Contribution",
              "pc2" = "PC2 Contribution",
              "pc1_pc2" = "PC1 + PC2 Combined"
            )
            ranking_display <- ranking_names[input$pca_feature_ranking]
            
            plot_title <- if (showing_all) {
              paste0("All ", nrow(top_features_df), " PCA Feature Contributions (", ranking_display, ")")
            } else {
              paste0("Top ", nrow(top_features_df), " PCA Feature Contributions (", ranking_display, ")")
            }
            
            p <- ggplot(top_features_df, aes(x = reorder(Feature, Ranking_Score), y = Ranking_Score)) +
              geom_col(fill = "#3498db") +
              coord_flip() +
              labs(title = plot_title,
                   x = "Feature", y = ranking_display) +
              theme_minimal(base_size = 14) +
              theme(
                plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                axis.text = element_text(size = 12, face = "bold", color = "black"),
                axis.title = element_text(size = 13, face = "bold", color = "black"),
                panel.grid = element_blank(),
                panel.border = element_rect(color = "black", fill = NA, size = 1)
              )
            values$pca_features_contrib_plot_obj <- p  # Store for download
            return(p)
          }
    }
  })
  
  # Generate loadings plot
  output$loadingsPlot <- renderPlot({ 
    # Use context-aware PCA result
    safe_pca <- NULL
    try(safe_pca <- pca_result_for_current_context(), silent = TRUE)
    if (is.null(safe_pca)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Loadings plot unavailable: PCA calculation failed.\nTry selecting different groups or features with more variation.",
                 size = 6, hjust = 0.5) +
        theme_void() +
        theme(plot.margin = ggplot2::margin(25, 25, 25, 25))
    } else {    # Get the top N features based on their selected ranking method
      top_features_df <- get_top_pca_features(safe_pca, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
      
      # Remove rows with NA Feature names
      top_features_df <- top_features_df[!is.na(top_features_df$Feature), ]
      
      if (nrow(top_features_df) == 0) {
        # No valid features - show error message
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Loadings plot unavailable: No valid features found.\nTry selecting different groups or features.",
                          size = 6, hjust = 0.5) +
                 theme_void())
      }
      
      top_features <- top_features_df$Feature_ID
      
      # Get the rotation matrix
      rotation <- safe_pca$rotation
      
      # Ensure all feature indices are valid (within bounds of rotation matrix)
      valid_indices <- as.numeric(top_features)
      valid_indices <- valid_indices[!is.na(valid_indices) & valid_indices > 0 & valid_indices <= nrow(rotation)]
      
      if (length(valid_indices) == 0) {
        # No valid indices - show error message
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Loadings plot unavailable: No valid features found.\nTry selecting different groups or features.",
                          size = 6, hjust = 0.5) +
                 theme_void())
      }
      
      # Filter the rotation matrix to include only valid top features
      filtered_rotation <- rotation[valid_indices, , drop = FALSE]
      
      # Create a dataframe for plotting
      loadings_df <- as.data.frame(filtered_rotation)
      # Use feature names from top_features_df, but only for valid indices
      feature_names_for_valid <- top_features_df$Feature[match(valid_indices, as.numeric(top_features_df$Feature_ID))]
      loadings_df$Feature <- feature_names_for_valid
      
      # Calculate contribution for color gradient
      loadings_df$contrib <- rowSums(loadings_df[, 1:2]^2)
      
      # Create custom loadings plot using ggplot2 instead of factoextra
      p <- ggplot(loadings_df, aes(x = PC1, y = PC2, color = contrib, label = Feature)) +
        geom_segment(aes(x = 0, y = 0, xend = PC1, yend = PC2),
                     arrow = arrow(length = unit(0.2, "cm")), alpha = 0.8) +
        ggrepel::geom_text_repel(size = 3.5, show.legend = FALSE,
                                 fontface = "bold", box.padding = 0.5,
                                 point.padding = 0.3, segment.color = "grey50") +
        scale_color_gradient2(low = "#2E86AB", mid = "#F6C85F", high = "#F26419",
                              name = "Contribution",
                              midpoint = mean(loadings_df$contrib)) +
        labs(
          title = paste0("PCA Loadings Plot - Top ", nrow(loadings_df), " Features (PC1 vs PC2)"),
          x = paste0("PC1 (", round(100 * safe_pca$sdev[1]^2 / sum(safe_pca$sdev^2), 1), "%)"),
          y = paste0("PC2 (", round(100 * safe_pca$sdev[2]^2 / sum(safe_pca$sdev^2), 1), "%)")
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          axis.text = element_text(size = 12, face = "bold", color = "black"),
          axis.title = element_text(size = 13, face = "bold", color = "black"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          legend.position = "right",
          legend.title = element_text(face = "bold"),
          legend.text = element_text(face = "bold")
        ) +
        coord_fixed() +
        geom_hline(yintercept = 0, linetype = "dashed", color = "gray50") +
        geom_vline(xintercept = 0, linetype = "dashed", color = "gray50")
      
      values$loadings_plot_obj <- p
      return(p)
    }
  })
  
  # Generate variance explained plot
  output$variancePlot <- renderPlot({ 
    # Use context-aware PCA result
    safe_pca <- NULL
    try(safe_pca <- pca_result_for_current_context(), silent = TRUE)
    # Check if PCA calculation failed
    if (is.null(safe_pca)) {
      # Return a simple plot with error message
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Variance plot unavailable: PCA calculation failed.\nTry selecting different groups or features with more variation.",
                 size = 6, hjust = 0.5) +
        theme_void() +
        theme(plot.margin = ggplot2::margin(25, 25, 25, 25))
    } else {
      # Calculate variance explained with cumulative variance
      variance_explained <- (safe_pca$sdev^2) / sum(safe_pca$sdev^2) * 100
      
      # Create data frame for plotting
      variance_df <- data.frame(
        PC = factor(paste0("PC", 1:length(variance_explained)),
                    levels = paste0("PC", 1:length(variance_explained))),
        Variance = variance_explained,
        Cumulative = cumsum(variance_explained)
      )
      
      # Create combined variance plot with cumulative line
      p_var <- ggplot(variance_df) +
        geom_col(aes(x = PC, y = Variance), fill = "steelblue", alpha = 0.8) +
        geom_line(aes(x = PC, y = Cumulative, group = 1),
                  color = "#e74c3c", size = 1.5) +
        geom_point(aes(x = PC, y = Cumulative),
                   color = "#e74c3c", size = 3) +
        scale_y_continuous(name = "Variance Explained (%)",
                           expand = expansion(mult = c(0, 0.1)),
                           sec.axis = sec_axis(~., name = "Cumulative Variance (%)")) +
        ggprism::theme_prism(base_size = 12) +
        labs(title = "Variance Explained by Principal Components",
             x = "Principal Component") +
        theme(
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          axis.text = element_text(size = 14, face = "bold"),
          axis.title = element_text(size = 14, face = "bold"),
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          text = element_text(face = "bold"),
          axis.text.x = element_text(angle = 45, hjust = 1)
        )
      
      values$variance_plot_obj <- p_var
      return(p_var)
    }
  })
  
  # Download PCA button
  output$downloadPCABtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      active_tab <- input$pcaTabset
      if (is.null(active_tab) || active_tab == "pcaPlotTab") {
        if (input$pcaType == "pairwise" && !is.null(input$pcaGroup1) && !is.null(input$pcaGroup2)) {
          paste0(input$pcaGroup1, "_vs_", input$pcaGroup2, "_PCA_",
                 format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
        } else {
          paste0("All_Groups_PCA_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
        }
      } else if (active_tab == "loadingsTab") {
        paste0("PCA_Loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else if (active_tab == "varianceTab") {
        paste0("PCA_Variance_Explained_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else if (active_tab == "Feature Contributions") {
        paste0("PCA_Feature_Contributions_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else {
        paste0("PCA_Plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      }
    },
    content = function(file) {
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      format <- get_safe_global_image_format()
      active_tab <- input$pcaTabset
      tryCatch({
        if (is.null(active_tab) || active_tab == "pcaPlotTab") {
          if (input$pcaType == "pairwise") {
            # Check if specific groups are selected for single plot download
            if (!is.null(input$pcaGroup1) && !is.null(input$pcaGroup2) &&
                input$pcaGroup1 != input$pcaGroup2) {
              # Generate single pairwise plot for selected groups for download
              req(values$normalized_data, values$unique_groups, values$group_column_indices)
              
              group1_idx <- which(values$unique_groups == input$pcaGroup1)
              group2_idx <- which(values$unique_groups == input$pcaGroup2)
              
              group1_cols <- values$group_column_indices[[group1_idx]]
              group2_cols <- values$group_column_indices[[group2_idx]]
              selected_cols <- sort(c(group1_cols, group2_cols))
              
              if (length(selected_cols) >= 3) {
                pca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
                groups_subset <- vapply(selected_cols, function(ci) {
                  if (ci %in% group1_cols) input$pcaGroup1 else input$pcaGroup2
                }, character(1))
                
                pairwise_pca <- prcomp(pca_data_subset, scale = input$pcaScale)
                
                pc_scores <- as.data.frame(pairwise_pca$x)
                pc_scores$Group <- preserve_group_names(groups_subset)
                
                # Add sample labels if requested
                if(input$showPCALabels) {
                  pc_scores$SampleLabels <- get_corrected_column_names(rownames(pca_data_subset))
                }
                
                # Calculate variance explained
                variance_explained <- summary(pairwise_pca)$importance[2, ] * 100
                pc1_var <- round(variance_explained[1], 1)
                pc2_var <- round(variance_explained[2], 1)
                
                # Create base plot with sample counts if requested
                if(input$showSampleCounts) {
                  counts <- table(groups_subset)
                  new_labels <- paste0(names(counts), " (n=", counts, ")")
                  
                  single_plot <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
                    geom_point(size = 3, alpha = 0.8) +
                    labs(
                      title = paste(input$pcaGroup1, "vs", input$pcaGroup2),
                      x = paste0("PC1 (", pc1_var, "%)"),
                      y = paste0("PC2 (", pc2_var, "%)")
                    )
                  
                  # Apply custom colors if enabled
                  custom_colors <- get_pca_colors()
                  if (!is.null(custom_colors)) {
                    pairwise_colors <- custom_colors[names(custom_colors) %in% unique(groups_subset)]
                    single_plot <- single_plot +
                      scale_color_manual(name = NULL, values = pairwise_colors, labels = new_labels) +
                      scale_fill_manual(name = NULL, values = pairwise_colors, labels = new_labels)
                  } else {
                    single_plot <- single_plot +
                      scale_color_discrete(name = NULL, labels = new_labels) +
                      scale_fill_discrete(name = NULL, labels = new_labels)
                  }
                  
                  single_plot <- single_plot +
                    ggprism::theme_prism(base_size = 14) +
                    theme(
                      panel.grid = element_blank(),
                      axis.line = element_line(color = "black", size = 0.8),
                      axis.text = element_text(size = 14, face = "bold", color = "black"),
                      axis.title = element_text(size = 14, face = "bold", color = "black"),
                      axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                      legend.text = element_text(size = 12, face = "bold"),
                      legend.title = element_blank(),
                      plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      legend.position = ifelse(input$pcaGridLegend %||% TRUE, "bottom", "none")
                    )
                } else {
                  single_plot <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
                    geom_point(size = 3, alpha = 0.8) +
                    labs(
                      title = paste(input$pcaGroup1, "vs", input$pcaGroup2),
                      x = paste0("PC1 (", pc1_var, "%)"),
                      y = paste0("PC2 (", pc2_var, "%)")
                    )
                  
                  # Apply custom colors if enabled
                  custom_colors <- get_pca_colors()
                  if (!is.null(custom_colors)) {
                    pairwise_colors <- custom_colors[names(custom_colors) %in% unique(groups_subset)]
                    single_plot <- single_plot +
                      scale_color_manual(name = NULL, values = pairwise_colors) +
                      scale_fill_manual(name = NULL, values = pairwise_colors)
                  } else {
                    single_plot <- single_plot +
                      scale_color_discrete(name = NULL) +
                      scale_fill_discrete(name = NULL)
                  }
                  
                  single_plot <- single_plot +
                    ggprism::theme_prism(base_size = 14) +
                    theme(
                      panel.grid = element_blank(),
                      axis.line = element_line(color = "black", size = 0.8),
                      axis.text = element_text(size = 14, face = "bold", color = "black"),
                      axis.title = element_text(size = 14, face = "bold", color = "black"),
                      axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                      legend.text = element_text(size = 12, face = "bold"),
                      legend.title = element_blank(),
                      plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      legend.position = ifelse(input$pcaGridLegend %||% TRUE, "bottom", "none")
                    )
                }
                
                # Add sample labels if requested
                if(input$showPCALabels) {
                  single_plot <- single_plot + ggrepel::geom_text_repel(
                    aes(label = SampleLabels),
                    size = input$pca_sample_label_size %||% 3.5,
                    box.padding = 0.5,
                    point.padding = 0.3,
                    segment.color = "grey50",
                    max.overlaps = 20,
                    fontface = "bold"
                  )
                }
                
                # Add ellipses if requested
                if (input$addEllipses) {
                  single_plot <- single_plot + stat_ellipse(
                    aes(fill = Group),
                    geom = "polygon",
                    alpha = 0.2,
                    level = input$ellipseLevel,
                    show.legend = FALSE
                  )
                }
                
                ggsave(file,
                       plot = single_plot,
                       width = max(6, (input$pcaGridWidth %||% 400) / 100),
                       height = max(6, (input$pcaGridHeight %||% 400) / 100),
                       dpi = dpi,
                       device = resolve_ggsave_device(format),
                       units = "in")
              }
            } else {
              # Download the grid plot if no specific groups selected
              req(values$pca_grid_obj)
              ggsave(file,
                     plot = values$pca_grid_obj,
                     width = (input$pcaGridWidth %||% 400) * (input$pcaGridCols %||% 2) / 100,
                     height = {
                       n_groups <- length(values$unique_groups) %||% 0
                       n_plots <- if (n_groups < 2) 0 else n_groups * (n_groups - 1) / 2
                       grid_cols <- input$pcaGridCols %||% 2
                       n_rows <- ceiling(n_plots / grid_cols)
                       grid_height <- input$pcaGridHeight %||% 400
                       max(300, n_rows * grid_height) / 100
                     },
                     dpi = dpi,
                     device = resolve_ggsave_device(format),
                     units = "in")
            }
          } else {
            # Download single plot for all groups mode
            req(values$pca_plot_obj)
            ggsave(file,
                   plot = values$pca_plot_obj,
                   width = max(6, input$pcaAllWidth / 100),
                   height = max(6, input$pcaAllHeight / 100),
                   dpi = dpi,
                   device = resolve_ggsave_device(format),
                   units = "in")
          }
        } else if (active_tab == "loadingsTab") {
          req(values$loadings_plot_obj)
          ggsave(file,
                 plot = values$loadings_plot_obj,
                 width = 10,
                 height = 8,
                 dpi = dpi,
                 device = resolve_ggsave_device(format),
                 units = "in")
        } else if (active_tab == "varianceTab") {
          req(values$variance_plot_obj)
          ggsave(file,
                 plot = values$variance_plot_obj,
                 width = 10,
                 height = 6,
                 dpi = dpi,
                 device = resolve_ggsave_device(format),
                 units = "in")
        } else if (active_tab == "Feature Contributions") {
          req(values$pca_features_contrib_plot_obj)
          ggsave(file,
                 plot = values$pca_features_contrib_plot_obj,
                 width = 10,
                 height = 8,
                 dpi = dpi,
                 device = resolve_ggsave_device(format),
                 units = "in")
        }
        showNotification("PCA plot downloaded successfully!", type = "message")
      }, error = function(e) {
        showNotification(paste("Error downloading plot:", e$message), type = "error")
      })
    }
  )
  
  # Individual download handlers for PCA Variance, Loadings, and Feature Contributions
  output$downloadPCAVarianceBtn <- downloadHandler(
    filename = function() {
      format <- input$global_format %||% "png"
      paste0("PCA_Variance_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$variance_plot_obj)
      format <- input$global_format %||% "png"
      dpi <- input$global_dpi %||% 300
      ggsave(file, plot = values$variance_plot_obj, width = 10, height = 6, dpi = dpi,
             device = resolve_ggsave_device(format), units = "in")
      showNotification("Variance plot downloaded!", type = "message")
    }
  )
  
  output$downloadPCALoadingsBtn <- downloadHandler(
    filename = function() {
      format <- input$global_format %||% "png"
      paste0("PCA_Loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$loadings_plot_obj)
      format <- input$global_format %||% "png"
      dpi <- input$global_dpi %||% 300
      ggsave(file, plot = values$loadings_plot_obj, width = 10, height = 8, dpi = dpi,
             device = resolve_ggsave_device(format), units = "in")
      showNotification("Loadings plot downloaded!", type = "message")
    }
  )
  
  output$downloadPCAContribBtn <- downloadHandler(
    filename = function() {
      format <- input$global_format %||% "png"
      paste0("PCA_FeatureContributions_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$pca_features_contrib_plot_obj)
      format <- input$global_format %||% "png"
      dpi <- input$global_dpi %||% 300
      ggsave(file, plot = values$pca_features_contrib_plot_obj, width = 10, height = 8, dpi = dpi,
             device = resolve_ggsave_device(format), units = "in")
      showNotification("Feature contributions plot downloaded!", type = "message")
    }
  )
  
  # Generate all PCA plots
  observeEvent(input$generateAllPCABtn, {
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    
    # Create directory for PCA plots
    dir.create("PCA_Plots", showWarnings = FALSE)
    
    # Progress bar
    progress <- shiny::Progress$new()
    on.exit(progress$close())
    
    # Set dpi
    dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
    
    # Calculate total number of plots (all types: scores, loadings, variance, feature contributions)
    n_groups <- length(values$unique_groups)
    n_pairs <- n_groups * (n_groups - 1) / 2
    total_plots <- (n_pairs + 1) * 4  # 4 types of plots for all groups + each pairwise comparison
    
    plot_count <- 0
    
    # Generate ALL types of PCA plots regardless of active tab
    progress$set(message = "Generating all PCA plots", value = 0)
    
    # ==================== ALL GROUPS PCA ====================
    progress$set(value = plot_count / total_plots, detail = "Processing all groups PCA")
    
    # Run PCA on all groups data
    all_groups_pca_data <- t(values$normalized_data)
    all_groups_groups <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
    all_groups_pca <- prcomp(all_groups_pca_data, scale = input$pcaScale)
    values$pca_result <- all_groups_pca
    store_pca_result("all_groups", all_groups_pca)
    
    # 1. PCA Score Plot
    pca_plot <- generate_pca_plot(all_groups_pca, all_groups_groups,
                                  input$addEllipses, input$ellipseLevel,
                                  input$showPCALabels, input$showSampleCounts,
                                  rownames(all_groups_pca_data))
    
    ggsave("PCA_Plots/All_Groups_PCA_Scores.png",
           pca_plot,
           width = max(6, input$pca_width / 100),
           height = max(6, input$pca_height / 100),
           dpi = dpi)
    plot_count <- plot_count + 1
    progress$set(value = plot_count / total_plots)
    
    # 2. Loadings Plot
    progress$set(value = plot_count / total_plots, detail = "Processing all groups loadings")
    
    top_n_features <- if (is.null(input$pca_top_features) || is.na(input$pca_top_features) || length(input$pca_top_features) == 0) {
      nrow(all_groups_pca$rotation)
    } else {
      min(input$pca_top_features, nrow(all_groups_pca$rotation))
    }
    tryCatch({
      # Use the same logic as GUI to generate loadings plot
      top_features_df <- get_top_pca_features(all_groups_pca, values$cleaned_molecules, top_n_features, input$pca_feature_ranking)
      top_features <- top_features_df$Feature_ID
      
      # Get the rotation matrix
      rotation <- all_groups_pca$rotation
      
      # Filter the rotation matrix to include only top features
      filtered_rotation <- rotation[as.numeric(top_features), , drop = FALSE]
      
      # Create a dataframe for plotting
      loadings_df <- as.data.frame(filtered_rotation)
      loadings_df$Feature <- top_features
      
      # Calculate contribution for color gradient
      loadings_df$contrib <- rowSums(loadings_df[, 1:2]^2)
      
      # Create custom loadings plot using ggplot2 (same as GUI)
      loadings_plot <- ggplot(loadings_df, aes(x = PC1, y = PC2, color = contrib, label = Feature)) +
        geom_segment(aes(x = 0, y = 0, xend = PC1, yend = PC2),
                     arrow = arrow(length = unit(0.2, "cm")), alpha = 0.8) +
        ggrepel::geom_text_repel(size = 3.5, show.legend = FALSE,
                                 fontface = "bold", box.padding = 0.5,
                                 point.padding = 0.3, segment.color = "grey50") +
        scale_color_gradient2(low = "#2E86AB", mid = "#F6C85F", high = "#F26419",
                              name = "Contribution",
                              midpoint = mean(loadings_df$contrib)) +
        labs(
          title = paste0("PCA Loadings Plot - Top ", nrow(loadings_df), " Features (PC1 vs PC2)"),
          x = paste0("PC1 (", round(100 * all_groups_pca$sdev[1]^2 / sum(all_groups_pca$sdev^2), 1), "%)"),
          y = paste0("PC2 (", round(100 * all_groups_pca$sdev[2]^2 / sum(all_groups_pca$sdev^2), 1), "%)")
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          axis.text = element_text(size = 12, face = "bold", color = "black"),
          axis.title = element_text(size = 13, face = "bold", color = "black"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          legend.position = "right",
          legend.title = element_text(face = "bold"),
          legend.text = element_text(face = "bold")
        ) +
        coord_fixed() +
        geom_hline(yintercept = 0, linetype = "dashed", color = "gray50") +
        geom_vline(xintercept = 0, linetype = "dashed", color = "gray50")
      
      ggsave("PCA_Plots/All_Groups_PCA_Loadings.png",
             loadings_plot,
             width = 10, height = 8, dpi = dpi)
      
    }, error = function(e) {
      showNotification(paste("Error generating all groups loadings plot:", e$message), type = "warning")
    })
    plot_count <- plot_count + 1
    progress$set(value = plot_count / total_plots)
    
    # 3. Variance Explained Plot
    progress$set(value = plot_count / total_plots, detail = "Processing all groups variance")
    
    tryCatch({
      variance_explained <- (all_groups_pca$sdev^2) / sum(all_groups_pca$sdev^2) * 100
      
      variance_df <- data.frame(
        PC = factor(paste0("PC", 1:length(variance_explained)),
                    levels = paste0("PC", 1:length(variance_explained))),
        Variance = variance_explained,
        Cumulative = cumsum(variance_explained)
      )
      
      variance_plot <- ggplot(variance_df) +
        geom_col(aes(x = PC, y = Variance), fill = "#3498db", alpha = 0.8) +
        geom_line(aes(x = PC, y = Cumulative, group = 1),
                  color = "#e74c3c", size = 1.5) +
        geom_point(aes(x = PC, y = Cumulative),
                   color = "#e74c3c", size = 3) +
        scale_y_continuous(name = "Variance Explained (%)",
                           expand = expansion(mult = c(0, 0.1)),
                           sec.axis = sec_axis(~., name = "Cumulative Variance (%)")) +
        ggprism::theme_prism() +
        labs(title = "PCA Variance Explained",
             x = "Principal Component") +
        theme(
          axis.text.x = element_text(angle = 45, hjust = 1),
          plot.title = element_text(hjust = 0.5)
        )
      
      ggsave("PCA_Plots/All_Groups_PCA_Variance.png",
             variance_plot,
             width = 10, height = 6, dpi = dpi)
      
    }, error = function(e) {
      showNotification(paste("Error generating all groups variance plot:", e$message), type = "warning")
    })
    plot_count <- plot_count + 1
    progress$set(value = plot_count / total_plots)
    
    # 4. Feature Contributions Plot
    progress$set(value = plot_count / total_plots, detail = "Processing all groups feature contributions")
    
    tryCatch({
      top_features_df <- get_top_pca_features(all_groups_pca, values$cleaned_molecules, top_n_features, input$pca_feature_ranking)
      
      total_features_all_groups <- nrow(all_groups_pca$rotation)
      showing_all_features <- (is.null(input$pca_top_features) || is.na(input$pca_top_features) ||
                                 length(input$pca_top_features) == 0 ||
                                 input$pca_top_features >= total_features_all_groups)
      
      feature_contrib_title <- if (showing_all_features) {
        paste0("All ", nrow(top_features_df), " PCA Feature Contributions")
      } else {
        paste0("Top ", nrow(top_features_df), " PCA Feature Contributions")
      }
      
      feature_contrib_plot <- ggplot(top_features_df, aes(x = reorder(Feature, Overall_Contribution), y = Overall_Contribution)) +
        geom_col(fill = "#3498db") +
        coord_flip() +
        labs(title = feature_contrib_title,
             x = "Feature", y = "Overall Contribution") +
        theme_minimal(base_size = 14) +
        theme(
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          axis.text = element_text(size = 12, face = "bold", color = "black"),
          axis.title = element_text(size = 13, face = "bold", color = "black"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1)
        )
      
      ggsave("PCA_Plots/All_Groups_PCA_Feature_Contributions.png",
             feature_contrib_plot,
             width = 10, height = 8, dpi = dpi)
      
    }, error = function(e) {
      showNotification(paste("Error generating all groups feature contributions:", e$message), type = "warning")
    })
    plot_count <- plot_count + 1
    progress$set(value = plot_count / total_plots)
    
    # ==================== PAIRWISE PCA COMPARISONS ====================
    # Loop through all pairwise comparisons
    for (i in 1:(n_groups - 1)) {
      for (j in (i+1):n_groups) {
        comparison_name <- paste(values$unique_groups[i], "vs", values$unique_groups[j])
        
        # Get indices for the two groups being compared
        group1_cols <- values$group_column_indices[[i]]
        group2_cols <- values$group_column_indices[[j]]
        selected_cols <- sort(c(group1_cols, group2_cols))
        
        # Skip if too few samples
        if (length(selected_cols) < 2) {
          showNotification(paste("Skipping", comparison_name, "- too few samples for PCA"), type = "warning")
          plot_count <- plot_count + 4  # Skip all 4 plot types
          progress$set(value = plot_count / total_plots)
          next
        }
        
        # Get data for this comparison
        pca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
        groups_subset <- vapply(selected_cols, function(ci) {
          if (ci %in% group1_cols) values$unique_groups[i] else values$unique_groups[j]
        }, character(1))
        
        # Run PCA
        tryCatch({
          pairwise_pca <- prcomp(pca_data_subset, scale = input$pcaScale)
          context_key <- paste(values$unique_groups[i], "vs", values$unique_groups[j])
          store_pca_result(context_key, pairwise_pca)
          
          # 1. PCA Score Plot
          progress$set(value = plot_count / total_plots,
                       detail = paste("Processing", comparison_name, "scores"))
          
          pca_plot_pair <- generate_pca_plot(pairwise_pca, groups_subset,
                                             input$addEllipses, input$ellipseLevel,
                                             input$showPCALabels, input$showSampleCounts,
                                             rownames(pca_data_subset))
          
          pair_filename <- paste0("PCA_Plots/", values$unique_groups[i], "_vs_",
                                  values$unique_groups[j], "_PCA_Scores.png")
          
          ggsave(pair_filename,
                 pca_plot_pair,
                 width = max(6, input$pca_width / 100),
                 height = max(6, input$pca_height / 100),
                 dpi = dpi)
          plot_count <- plot_count + 1
          progress$set(value = plot_count / total_plots)
          
          # 2. Loadings Plot
          progress$set(value = plot_count / total_plots,
                       detail = paste("Processing", comparison_name, "loadings"))
          
          # Use the same logic as GUI to generate loadings plot
          top_features_df_pair <- get_top_pca_features(pairwise_pca, values$cleaned_molecules, top_n_features, input$pca_feature_ranking)
          top_features_pair <- top_features_df_pair$Feature_ID
          
          # Get the rotation matrix
          rotation_pair <- pairwise_pca$rotation
          
          # Filter the rotation matrix to include only top features
          filtered_rotation_pair <- rotation_pair[as.numeric(top_features_pair), , drop = FALSE]
          
          # Create a dataframe for plotting
          loadings_df_pair <- as.data.frame(filtered_rotation_pair)
          loadings_df_pair$Feature <- top_features_pair
          
          # Calculate contribution for color gradient
          loadings_df_pair$contrib <- rowSums(loadings_df_pair[, 1:2]^2)
          
          # Create custom loadings plot using ggplot2 (same as GUI)
          loadings_plot_pair <- ggplot(loadings_df_pair, aes(x = PC1, y = PC2, color = contrib, label = Feature)) +
            geom_segment(aes(x = 0, y = 0, xend = PC1, yend = PC2),
                         arrow = arrow(length = unit(0.2, "cm")), alpha = 0.8) +
            ggrepel::geom_text_repel(size = 3.5, show.legend = FALSE,
                                     fontface = "bold", box.padding = 0.5,
                                     point.padding = 0.3, segment.color = "grey50") +
            scale_color_gradient2(low = "#2E86AB", mid = "#F6C85F", high = "#F26419",
                                  name = "Contribution",
                                  midpoint = mean(loadings_df_pair$contrib)) +
            labs(
              title = paste0(comparison_name, " - PCA Loadings Plot - Top ", nrow(loadings_df_pair), " Features (PC1 vs PC2)"),
              x = paste0("PC1 (", round(100 * pairwise_pca$sdev[1]^2 / sum(pairwise_pca$sdev^2), 1), "%)"),
              y = paste0("PC2 (", round(100 * pairwise_pca$sdev[2]^2 / sum(pairwise_pca$sdev^2), 1), "%)")
            ) +
            ggprism::theme_prism(base_size = 14) +
            theme(
              plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
              axis.text = element_text(size = 12, face = "bold", color = "black"),
              axis.title = element_text(size = 13, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(color = "black", fill = NA, size = 1),
              legend.position = "right",
              legend.title = element_text(face = "bold"),
              legend.text = element_text(face = "bold")
            ) +
            coord_fixed() +
            geom_hline(yintercept = 0, linetype = "dashed", color = "gray50") +
            geom_vline(xintercept = 0, linetype = "dashed", color = "gray50")
          
          loadings_filename <- paste0("PCA_Plots/", values$unique_groups[i], "_vs_",
                                      values$unique_groups[j], "_PCA_Loadings.png")
          ggsave(loadings_filename, loadings_plot_pair, width = 10, height = 8, dpi = dpi)
          plot_count <- plot_count + 1
          progress$set(value = plot_count / total_plots)
          
          # 3. Variance Plot
          progress$set(value = plot_count / total_plots,
                       detail = paste("Processing", comparison_name, "variance"))
          
          variance_explained_pair <- (pairwise_pca$sdev^2) / sum(pairwise_pca$sdev^2) * 100
          
          variance_df_pair <- data.frame(
            PC = factor(paste0("PC", 1:length(variance_explained_pair)),
                        levels = paste0("PC", 1:length(variance_explained_pair))),
            Variance = variance_explained_pair,
            Cumulative = cumsum(variance_explained_pair)
          )
          
          variance_plot_pair <- ggplot(variance_df_pair) +
            geom_col(aes(x = PC, y = Variance), fill = "#3498db", alpha = 0.8) +
            geom_line(aes(x = PC, y = Cumulative, group = 1),
                      color = "#e74c3c", size = 1.5) +
            geom_point(aes(x = PC, y = Cumulative),
                       color = "#e74c3c", size = 3) +
            scale_y_continuous(name = "Variance Explained (%)",
                               expand = expansion(mult = c(0, 0.1)),
                               sec.axis = sec_axis(~., name = "Cumulative Variance (%)")) +
            ggprism::theme_prism() +
            labs(title = paste0(comparison_name, " - Variance Explained"),
                 x = "Principal Component") +
            theme(
              axis.text.x = element_text(angle = 45, hjust = 1),
              plot.title = element_text(hjust = 0.5)
            )
          
          variance_filename <- paste0("PCA_Plots/", values$unique_groups[i], "_vs_",
                                      values$unique_groups[j], "_PCA_Variance.png")
          ggsave(variance_filename, variance_plot_pair, width = 10, height = 6, dpi = dpi)
          plot_count <- plot_count + 1
          progress$set(value = plot_count / total_plots)
          
          # 4. Feature Contributions Plot
          progress$set(value = plot_count / total_plots,
                       detail = paste("Processing", comparison_name, "feature contributions"))
          
          # Reuse top_features_df_pair from loadings calculation above
          
          total_features_pairwise <- nrow(pairwise_pca$rotation)
          showing_all_pairwise <- (is.null(input$pca_top_features) || is.na(input$pca_top_features) ||
                                     length(input$pca_top_features) == 0 ||
                                     input$pca_top_features >= total_features_pairwise)
          
          pairwise_title <- if (showing_all_pairwise) {
            paste0(comparison_name, " - All ", nrow(top_features_df_pair), " PCA Feature Contributions")
          } else {
            paste0(comparison_name, " - Top ", nrow(top_features_df_pair), " PCA Feature Contributions")
          }
          
          feature_contrib_plot_pair <- ggplot(top_features_df_pair, aes(x = reorder(Feature, Overall_Contribution), y = Overall_Contribution)) +
            geom_col(fill = "#3498db") +
            coord_flip() +
            labs(title = pairwise_title,
                 x = "Feature", y = "Overall Contribution") +
            theme_minimal(base_size = 14) +
            theme(
              plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
              axis.text = element_text(size = 12, face = "bold", color = "black"),
              axis.title = element_text(size = 13, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(color = "black", fill = NA, size = 1)
            )
          
          pair_contrib_filename <- paste0("PCA_Plots/", values$unique_groups[i], "_vs_", values$unique_groups[j], "_PCA_Feature_Contributions.png")
          ggsave(pair_contrib_filename, feature_contrib_plot_pair, width = 10, height = 8, dpi = dpi)
          plot_count <- plot_count + 1
          progress$set(value = plot_count / total_plots)
          
        }, error = function(e) {
          showNotification(paste("Error processing", comparison_name, "-", e$message), type = "error")
          plot_count <- plot_count + 4  # Skip remaining plots for this comparison
          progress$set(value = plot_count / total_plots)
        })
      }
    }
    
    showNotification(paste0("All PCA plots generated successfully! Generated ", plot_count, " plots in the PCA_Plots directory."), type = "message")
  })
  
  # Helper function to generate PCA plots
  generate_pca_plot <- function(pca_result, group_labels, add_ellipses = TRUE, ellipse_level = 0.95,
                                show_labels = FALSE, show_counts = TRUE, sample_names = NULL) {
    # Extract PC scores from the PCA result
    pc_scores <- as.data.frame(pca_result$x)
    
    # Calculate explained variance
    variance_explained <- (pca_result$sdev^2) / sum(pca_result$sdev^2) * 100
    pc1_variance <- round(variance_explained[1], 2)
    pc2_variance <- round(variance_explained[2], 2)
    
    # Get jitter size from inputs (default to 3 if not available)
    # This allows the size to be controlled from the UI
    pca_point_size <- as.numeric(if(!is.null(input$pca_jitter_size) && is.numeric(input$pca_jitter_size)) input$pca_jitter_size else 3)
    
    # Preserve original group names (spaces, etc.)
    group_labels <- preserve_group_names(group_labels)
    
    # Add group information
    pc_scores$Group <- factor(group_labels)
    
    # Add cleaned sample names if provided
    if(!is.null(sample_names)) {
      pc_scores$Sample <- get_corrected_column_names(sample_names)
    } else {
      pc_scores$Sample <- get_corrected_column_names(rownames(pc_scores))
    }
    
    # Create base plot
    if(show_counts) {
      counts <- table(group_labels)
      new_labels <- paste0(names(counts), " (n=", counts, ")")
      
      # Create plot with sample counts
      p <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
        geom_point(size = pca_point_size) +
        labs(
          title = paste("Principal Component Analysis"),
          x = paste0("PC1 (", pc1_variance, "%)"),
          y = paste0("PC2 (", pc2_variance, "%)")
        ) +
        scale_color_discrete(name = NULL, labels = new_labels) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          axis.text = element_text(size = 14, face = "bold", color = "black"),
          axis.title = element_text(size = 14, face = "bold", color = "black"),
          legend.text = element_text(size = 14, face = "bold"),
          legend.position = "bottom",
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          plot.subtitle = element_text(face = "bold"),
          strip.text = element_text(face = "bold"),
          text = element_text(face = "bold"),
          panel.border = element_rect(color = "black", fill = NA, size = 1)
        )
    } else {
      p <- ggplot(pc_scores, aes(x = PC1, y = PC2, color = Group)) +
        geom_point(size = pca_point_size) +
        labs(
          title = paste("Principal Component Analysis"),
          x = paste0("PC1 (", pc1_variance, "%)"),
          y = paste0("PC2 (", pc2_variance, "%)")      ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          axis.text = element_text(size = 14, face = "bold", color = "black"),
          axis.title = element_text(size = 14, face = "bold", color = "black"),
          legend.text = element_text(size = 14, face = "bold"),
          legend.position = "bottom",
          plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
          plot.subtitle = element_text(face = "bold"),
          strip.text = element_text(face = "bold"),
          text = element_text(face = "bold"),
          panel.border = element_rect(color = "black", fill = NA, size = 1)
        )
    }
    
    # Add confidence ellipses if requested AND possible
    # Check if each group has enough points for an ellipse (at least 3 points needed)
    if(add_ellipses) {
      can_add_ellipse <- all(table(group_labels) >= 3)
      if(can_add_ellipse) {
        p <- p + stat_ellipse(
          aes(fill = Group),
          geom = "polygon",
          alpha = 0.2,
          level = ellipse_level,
          show.legend = FALSE
        )
      }
    }
    
    # Add sample labels if requested
    if(show_labels) {
      # Add cleaned sample names as labels with repulsion to avoid overlap
      p <- p + ggrepel::geom_text_repel(
        aes(label = Sample),
        size = input$pca_sample_label_size %||% 3.5,
        box.padding = 0.5,
        point.padding = 0.3,
        segment.color = "grey50",
        max.overlaps = 20
      )
    }
    
    return(p)
  }
  
  # Download PCA feature contributions
  output$downloadPCAFeaturesBtn <- downloadHandler(
    filename = function() {
      if (input$pcaType == "pairwise") {
        paste0(input$pcaGroup1, "_vs_", input$pcaGroup2, "_PCA_Top_Features_",
               format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
      } else {
        paste0("All_Groups_PCA_Top_Features_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
      }
    },
    content = function(file) {
      # Check if PCA was performed successfully
      if (is.null(values$pca_result)) {
        showNotification("No PCA results available. Run PCA first.", type = "error")
        return()
      }
      
      # Create workbook
      wb <- createWorkbook()
      
      # Add worksheet for top features
      addWorksheet(wb, "Top PCA Features")
      # Use the same helper as the table and plot for consistency
      top_features <- get_top_pca_features(values$pca_result, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
      result_df <- top_features
      
      # Write features data
      writeData(wb, "Top PCA Features", result_df)
      
      # Add summary sheet with PCA variance explained
      addWorksheet(wb, "PCA Summary")
      variance_explained <- (values$pca_result$sdev^2) / sum(values$pca_result$sdev^2) * 100
      summary_df <- data.frame(
        PC = paste0("PC", 1:length(variance_explained)),
        Variance_Explained = variance_explained,
        Cumulative_Variance = cumsum(variance_explained)
      )
      writeData(wb, "PCA Summary", summary_df)
      
      # Add analysis parameters sheet
      addWorksheet(wb, "Analysis Parameters")
      if (input$pcaType == "pairwise") {
        param_df <- data.frame(
          Parameter = c("Analysis Type", "Group 1", "Group 2", "Top Features Selected",
                        "Add Confidence Ellipses", "Ellipse Confidence Level", "Scale Data"),
          Value = c("Pairwise", input$pcaGroup1, input$pcaGroup2, input$pca_top_features,
                    as.character(input$addEllipses), paste0(input$ellipseLevel*100, "%"),
                    as.character(input$pcaScale))
        )
      } else {
        param_df <- data.frame(
          Parameter = c("Analysis Type", "Top Features Selected",
                        "Add Confidence Ellipses", "Ellipse Confidence Level", "Scale Data"),
          Value = c("All Groups", input$pca_top_features,
                    as.character(input$addEllipses), paste0(input$ellipseLevel*100, "%"),
                    as.character(input$pcaScale))
        )
      }
      writeData(wb, "Analysis Parameters", param_df)
      
      # Save workbook
      saveWorkbook(wb, file, overwrite = TRUE)
      showNotification("PCA top features downloaded successfully!", type = "message")
    }
  )
  
  output$pcaResultsTable <- DT::renderDataTable({
    # Use context-aware PCA result for the table
    safe_pca <- NULL
    try(safe_pca <- pca_result_for_current_context(), silent = TRUE)
    req(safe_pca)
    top_features <- get_top_pca_features(safe_pca, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
    
    # Remove any rows with NA Feature names (shouldn't happen with our fix, but safety check)
    top_features <- top_features[!is.na(top_features$Feature), ]
    
    if (nrow(top_features) == 0) {
      # Return empty datatable if no valid features
      empty_df <- data.frame(Feature = character(0))
      return(DT::datatable(empty_df, options = list(pageLength = 15, scrollX = TRUE)))
    }
    
    DT::datatable(
      top_features,
      options = list(pageLength = 15, scrollX = TRUE, autoWidth = TRUE),
      rownames = FALSE
    ) %>%
      DT::formatRound(columns = c(3:ncol(top_features)), digits = 4)
  })
  
  # Helper: Get top N PCA features by overall contribution
  get_top_pca_features <- function(pca_result, molecules, n = 30, ranking_method = "overall") {
    loadings <- pca_result$rotation
    contributions <- as.data.frame(loadings)
    
    # Calculate different ranking metrics
    contributions$Overall_Contribution <- rowSums(loadings^2)
    contributions$PC1_Contribution <- abs(loadings[, 1])
    contributions$PC2_Contribution <- abs(loadings[, 2])
    contributions$PC1_PC2_Combined <- abs(loadings[, 1]) + abs(loadings[, 2])
    
    # Sort based on the selected ranking method
    if (ranking_method == "overall") {
      contributions <- contributions[order(-contributions$Overall_Contribution), ]
      sort_col <- "Overall_Contribution"
    } else if (ranking_method == "pc1") {
      contributions <- contributions[order(-contributions$PC1_Contribution), ]
      sort_col <- "PC1_Contribution"
    } else if (ranking_method == "pc2") {
      contributions <- contributions[order(-contributions$PC2_Contribution), ]
      sort_col <- "PC2_Contribution"
    } else if (ranking_method == "pc1_pc2") {
      contributions <- contributions[order(-contributions$PC1_PC2_Combined), ]
      sort_col <- "PC1_PC2_Combined"
    } else {
      # Default to overall if unknown method
      contributions <- contributions[order(-contributions$Overall_Contribution), ]
      sort_col <- "Overall_Contribution"
    }
    
    # If n is NULL, NA, or empty, use all features
    if (is.null(n) || is.na(n) || length(n) == 0) {
      top_n <- nrow(contributions)
    } else {
      top_n <- min(n, nrow(contributions))
    }
    
    numeric_ids <- as.integer(rownames(contributions)[1:top_n])
    
    # Ensure all indices are valid (within bounds of molecules vector)
    valid_indices <- numeric_ids[!is.na(numeric_ids) & numeric_ids > 0 & numeric_ids <= length(molecules)]
    
    if (length(valid_indices) == 0) {
      # Fallback: use rownames as feature names if numeric indices fail
      orig_names <- rownames(contributions)[1:top_n]
    } else {
      orig_names <- molecules[valid_indices]
      # Ensure we still have the correct number of features
      if (length(orig_names) < top_n) {
        # Pad with remaining rownames if needed
        missing_indices <- setdiff(1:top_n, match(valid_indices, numeric_ids))
        if (length(missing_indices) > 0) {
          orig_names <- c(orig_names, rownames(contributions)[missing_indices])
        }
      }
    }
    
    result_df <- data.frame(
      Feature_ID = rownames(contributions)[1:top_n],
      Feature = orig_names,
      Overall_Contribution = contributions$Overall_Contribution[1:top_n],
      PC1_Contribution = contributions$PC1_Contribution[1:top_n],
      PC2_Contribution = contributions$PC2_Contribution[1:top_n],
      PC1_PC2_Combined = contributions$PC1_PC2_Combined[1:top_n],
      Ranking_Score = contributions[[sort_col]][1:top_n],
      stringsAsFactors = FALSE
    )
    
    # Add PC columns (limit to first 10 PCs)
    pc_cols <- min(10, ncol(loadings))
    for (i in 1:pc_cols) {
      result_df[[paste0("PC", i)]] <- contributions[1:top_n, i]
    }
    result_df
  }
  
  # Helper functions for context-specific PCA management
  store_pca_result <- function(context_key, pca_result) {
    values$pca_results_context[[context_key]] <- pca_result
  }
  
  get_pca_result <- function(context_key) {
    values$pca_results_context[[context_key]]
  }
  
  # Get the appropriate context key for current comparison
  get_current_context_key <- function(comp_input = NULL) {
    if (is.null(comp_input) || comp_input == "All Groups") {
      return("all_groups")
    } else {
      # For pairwise comparisons, return the comparison name
      return(comp_input)
    }
  }
  
  # Get top PCA features for specific context (context-aware with lazy loading)
  get_top_pca_features_context <- function(context_key, molecules, n = 30, ranking_method = "overall") {
    # First try to get existing PCA result
    pca_result <- get_pca_result(context_key)
    
    # If not found, compute it on-demand
    if (is.null(pca_result)) {
      pca_result <- ensure_pca_result(context_key)
    }
    
    # Fallback to global PCA result if context-specific still not available
    if (is.null(pca_result)) {
      pca_result <- values$pca_result
    }
    
    if (is.null(pca_result)) {
      return(NULL)
    }
    
    return(get_top_pca_features(pca_result, molecules, n, ranking_method))
  }
  
  # Function to ensure PCA result exists for a specific context (using same logic as PCA tab)
  ensure_pca_result <- function(context) {
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    
    # Check if PCA result already exists for this context
    existing_pca <- get_pca_result(context)
    if (!is.null(existing_pca)) {
      return(existing_pca)
    }
    
    tryCatch({
      # Get PCA scale setting (default to TRUE if not available)
      scale_data <- if (!is.null(input$pcaScale)) input$pcaScale else TRUE
      # Prepare data exactly like the PCA tab does
      if (context == "all_groups") {
        # Replicate "All groups" logic from PCA tab
        all_columns <- unlist(values$group_column_indices)
        all_data <- values$normalized_data[, all_columns, drop = FALSE]
        
        # Transpose for PCA
        pca_data <- t(all_data)
        pca_data[is.infinite(pca_data)] <- NA
        
        # Create proper group labels based on actual column assignments
        pca_labels <- character(length(all_columns))
        for (i in seq_along(values$unique_groups)) {
          group_name <- values$unique_groups[i]
          group_cols <- values$group_column_indices[[i]]
          # Find which positions in all_columns correspond to this group
          group_positions <- which(all_columns %in% group_cols)
          pca_labels[group_positions] <- group_name
        }
        pca_labels <- pca_labels[1:nrow(pca_data)]
        
      } else {
        # Parse pairwise context (e.g., "Group1 vs Group2")
        groups <- strsplit(context, " vs ")[[1]]
        if (length(groups) != 2) {
          return(NULL)
        }
        
        # Replicate pairwise logic from PCA tab
        group1_idx <- which(values$unique_groups == groups[1])
        group2_idx <- which(values$unique_groups == groups[2])
        
        if (length(group1_idx) != 1 || length(group2_idx) != 1) {
          return(NULL)
        }
        
        # Extract data for the selected groups
        group1_columns <- values$group_column_indices[[group1_idx]]
        group2_columns <- values$group_column_indices[[group2_idx]]
        
        data1 <- values$normalized_data[, group1_columns, drop = FALSE]
        data2 <- values$normalized_data[, group2_columns, drop = FALSE]
        
        # Combine data for PCA
        pca_data <- rbind(t(data1), t(data2))
        pca_data[is.infinite(pca_data)] <- NA
        
        # Create group labels for PCA points
        pca_labels <- c(
          rep(groups[1], nrow(t(data1))),
          rep(groups[2], nrow(t(data2)))
        )
      }
      
      # Apply the same data cleaning as PCA tab
      
      # Step 1: Remove completely empty rows
      if (any(is.na(pca_data))) {
        row_na_count <- rowSums(is.na(pca_data))
        complete_na_rows <- which(row_na_count == ncol(pca_data))
        
        if (length(complete_na_rows) > 0) {
          pca_data <- pca_data[-complete_na_rows, , drop = FALSE]
          if (!is.null(pca_labels)) {
            pca_labels <- pca_labels[-complete_na_rows]
          }
        }
        
        # Step 2: Remove rows with >30% missing values within any group
        if (!is.null(pca_labels) && length(unique(pca_labels)) > 1) {
          groups_unique <- unique(pca_labels)
          rows_to_remove <- c()
          
          for (group in groups_unique) {
            group_indices <- which(pca_labels == group)
            
            for (i in 1:nrow(pca_data)) {
              group_nas <- sum(is.na(pca_data[i, group_indices]))
              group_na_percent <- group_nas / length(group_indices)
              
              if (group_na_percent > 0.3) {
                rows_to_remove <- c(rows_to_remove, i)
              }
            }
          }
          
          if (length(rows_to_remove) > 0) {
            rows_to_remove <- unique(rows_to_remove)
            if (length(rows_to_remove) < nrow(pca_data)) {
              pca_data <- pca_data[-rows_to_remove, , drop = FALSE]
              if (!is.null(pca_labels)) {
                pca_labels <- pca_labels[-rows_to_remove]
              }
            }
          }
        }
      }
      
      # Check if we have enough data
      if (nrow(pca_data) < 2) {
        return(NULL)
      }
      
      # Set pca_data_imputed to pca_data initially
      pca_data_imputed <- pca_data
      
      # Apply the same PCA calculation logic as PCA tab
      pca_result <- NULL
      
      # First try with NA handling
      tryCatch({
        # Check for zero/near-zero variance columns
        column_vars <- apply(pca_data_imputed, 2, var, na.rm = TRUE)
        zero_var_cols <- which(column_vars < 1e-10 | is.na(column_vars))
        
        if (length(zero_var_cols) > 0) {
          filtered_pca_data <- pca_data_imputed[, -zero_var_cols, drop = FALSE]
          
          if (ncol(filtered_pca_data) < 2) {
            return(NULL)
          }
          
          pca_result <- prcomp(filtered_pca_data, scale. = scale_data, na.action = na.omit)
        } else {
          pca_result <- prcomp(pca_data_imputed, scale. = scale_data, na.action = na.omit)
        }
      }, error = function(e) {
        # If PCA with NAs fails, remove rows with NAs
        tryCatch({
          pca_data_imputed <- na.omit(pca_data)
          
          if (nrow(pca_data_imputed) < 2) {
            return(NULL)
          }
          
          pca_result <- prcomp(pca_data_imputed, scale. = scale_data)
        }, error = function(e2) {
          return(NULL)
        })
      })
      
      # Store and return the result
      if (!is.null(pca_result)) {
        store_pca_result(context, pca_result)
        
        # For backward compatibility, also store global result for "all_groups"
        if (context == "all_groups") {
          values$pca_result <- pca_result
        }
        
        return(pca_result)
      }
      
      return(NULL)
      
    }, error = function(e) {
      showNotification(paste("Error computing PCA result for", context, ":", e$message), type = "warning")
      return(NULL)
    })
  }
  
  # --- PCA context helpers to keep all PCA views in sync with Analysis type/group selection ---
  pca_current_context_key <- reactive({
    req(input$pcaType)
    if (input$pcaType == "pairwise") {
      req(input$pcaGroup1, input$pcaGroup2)
      if (identical(input$pcaGroup1, input$pcaGroup2)) return(NULL)
      paste(input$pcaGroup1, "vs", input$pcaGroup2)
    } else {
      "all_groups"
    }
  })
  
  pca_result_for_current_context <- reactive({
    ctx <- pca_current_context_key()
    req(ctx)
    # Try to get a cached/computed result first
    res <- get_pca_result(ctx)
    if (is.null(res)) {
      # Compute on-demand using the same logic as PCA tab
      res <- ensure_pca_result(ctx)
    }
    req(res)
    res
  })
  
  # Observer to update selected features when "Use Top N PCA features" is toggled
  observeEvent(input$use_pca_features, {
    if (isTRUE(input$use_pca_features)) {
      # Ensure we have the required inputs
      if (is.null(input$pca_top_features) || is.na(input$pca_top_features) || input$pca_top_features <= 0) {
        showNotification("Please specify the number of top PCA features first.", type = "warning")
        return()
      }
      
      # Get the current PCA result
      pca_result <- NULL
      tryCatch({
        pca_result <- pca_result_for_current_context()
      }, error = function(e) {
        # Fallback to global PCA result
        pca_result <- values$pca_result
      })
      
      if (is.null(pca_result)) {
        showNotification("Please run PCA analysis first.", type = "warning")
        return()
      }
      
      # Get top features using the selected ranking method
      top_features_df <- get_top_pca_features(pca_result, values$cleaned_molecules, input$pca_top_features, input$pca_feature_ranking)
      
      if (nrow(top_features_df) > 0) {
        # Store the feature indices globally for use by other tabs (use Feature_ID which are the indices)
        values$pca_top_features <- as.integer(top_features_df$Feature_ID)
        # Also store names for robust matching across tabs (indices can become stale after filtering)
        values$pca_top_feature_names <- as.character(top_features_df$Feature)
        
        # Get ranking method display name
        ranking_names <- c(
          "overall" = "Overall Contribution",
          "pc1" = "PC1 Contribution",
          "pc2" = "PC2 Contribution",
          "pc1_pc2" = "PC1 + PC2 Combined"
        )
        ranking_display <- ranking_names[input$pca_feature_ranking]
        
        showNotification(paste("Made", length(values$pca_top_features), "top PCA features global using", ranking_display, "ranking."), type = "message")
        
        # Auto-switch downstream Feature Set selectors to PCA
        suppressWarnings({
          try(updateSelectInput(session, "heatmap_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "dist_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "diff_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "intersection_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "roc_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "proteomics_feature_source", selected = "pca"), silent = TRUE)
          try(updateSelectInput(session, "feature_source", selected = "pca"), silent = TRUE)
        })
      } else {
        showNotification("No PCA features available. Please check your PCA settings.", type = "warning")
      }
    } else {
      # Clear global PCA features when checkbox is unchecked
      values$pca_top_features <- NULL
      values$pca_top_feature_names <- NULL
      
      # Switch downstream Feature Set selectors back to All
      suppressWarnings({
        try(updateSelectInput(session, "heatmap_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "dist_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "diff_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "intersection_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "roc_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "proteomics_feature_source", selected = "all"), silent = TRUE)
        try(updateSelectInput(session, "feature_source", selected = "all"), silent = TRUE)
      })
    }
  })
  
  # UMAP plot with parameters
  output$umapPlot <- renderPlot({ 
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    if (!requireNamespace("umap", quietly = TRUE)) {
      install.packages("umap")
    }
    library(umap)
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$umap_title_size)) input$umap_title_size else 14
    axis_title_size <- if(!is.null(input$umap_axis_title_size)) input$umap_axis_title_size else 12
    axis_text_size <- if(!is.null(input$umap_axis_text_size)) input$umap_axis_text_size else 10
    legend_text_size <- if(!is.null(input$umap_legend_text_size)) input$umap_legend_text_size else 12
    
    # Get user-specified parameters
    n_neighbors <- input$umap_n_neighbors
    min_dist <- input$umap_min_dist
    spread <- input$umap_spread
    do_scale <- input$umap_scale
    withProgress(message = "Calculating UMAP...", {
      # Prepare data
      data_mat <- t(values$normalized_data)
      # Use active grouping level if dual grouping is available
      if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
        if (values$active_grouping_level == "biological") {
          group_labels <- create_proper_group_labels(values$biological_unique_groups, values$biological_group_column_indices)
        } else {
          group_labels <- create_proper_group_labels(values$experimental_unique_groups, values$experimental_group_column_indices)
        }
      } else {
        group_labels <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
      }
      
      # Clean data - handle NAs and infinite values
      data_mat[is.na(data_mat)] <- 0
      data_mat[is.infinite(data_mat)] <- 0
      
      # Set UMAP configuration
      umap_config <- umap::umap.defaults
      umap_config$n_neighbors <- n_neighbors
      umap_config$min_dist <- min_dist
      umap_config$spread <- spread
      
      # Run UMAP
      tryCatch({
        umap_res <- umap::umap(data_mat, config = umap_config, scale = do_scale)
        
        # Get original sample names and use corrected names
        original_sample_names <- rownames(data_mat)
        cleaned_sample_names <- get_corrected_column_names(original_sample_names)
        
        # Create data frame for plotting
        df <- data.frame(UMAP1 = umap_res$layout[,1],
             UMAP2 = umap_res$layout[,2],
             Group = preserve_group_names(group_labels),
             Sample = cleaned_sample_names)
        group_levels <- get_group_order_for_plot(unique(group_labels))
        df$Group <- factor(df$Group, levels = group_levels)
        
        # Create plot
        p <- ggplot(df, aes(x = UMAP1, y = UMAP2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(title = "UMAP Visualization",
               subtitle = paste0("n_neighbors = ", n_neighbors,
                                 ", min_dist = ", min_dist,
                                 ", spread = ", spread)) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            plot.subtitle = element_text(hjust = 0.5),
            panel.grid = element_blank(),
            legend.title = element_blank(),
            legend.position = "bottom",
            legend.text = element_text(size = legend_text_size, face = "bold"),
            axis.text = element_text(face = "bold", size = axis_text_size),
            axis.title = element_text(face = "bold", size = axis_title_size)
          )
        
        # Apply grid layout to legend if 4+ groups
        if (length(unique(df$Group)) >= 4) {
          legend_layout <- get_legend_grid_layout(length(unique(df$Group)))
          p <- p + guides(color = guide_legend(nrow = legend_layout$nrow, ncol = legend_layout$ncol))
        }
        
        # Add ellipses if requested and possible
        if (input$umap_add_ellipses) {
          # Check if we have enough points per group for ellipses
          group_counts <- table(df$Group)
          can_add_ellipse <- all(group_counts >= 3)
          
          if (can_add_ellipse) {
            p <- p + stat_ellipse(
              aes(fill = Group),
              geom = "polygon",
              alpha = 0.2,
              level = input$ellipseLevel,
              show.legend = FALSE
            )
          }
        }
        
        # Add sample labels if requested
        if (input$umap_show_labels) {
          p <- p + ggrepel::geom_text_repel(
            aes(label = Sample),
            size = 3.5,
            box.padding = 0.5,
            point.padding = 0.3,
            segment.color = "grey50",
            max.overlaps = 20
          )
        }
        
        # Store the plot for download
        values$umap_plot_obj <- p
        
        return(p)
        
      }, error = function(e) {
        # Return error message as plot
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("UMAP calculation failed:", e$message),
                   hjust = 0.5) +
          theme_void()
        return(p)
      })
    })
  }, height = function() input$umap_height %||% 600, width = function() input$umap_width %||% 800, res = UI_PLOT_RES)
  
  # t-SNE plot with parameters
  output$tsnePlot <- renderPlot({ 
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    if (!requireNamespace("Rtsne", quietly = TRUE)) {
      install.packages("Rtsne")
    }
    library(Rtsne)
    
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$tsne_title_size)) input$tsne_title_size else 14
    axis_title_size <- if(!is.null(input$tsne_axis_title_size)) input$tsne_axis_title_size else 12
    axis_text_size <- if(!is.null(input$tsne_axis_text_size)) input$tsne_axis_text_size else 10
    legend_text_size <- if(!is.null(input$tsne_legend_text_size)) input$tsne_legend_text_size else 12
    
    # Get user-specified parameters
    perplexity <- min(input$tsne_perplexity, nrow(t(values$normalized_data)) - 1)
    max_iter <- input$tsne_max_iter
    theta <- input$tsne_theta
    seed_val <- input$tsne_seed
    do_scale <- input$tsne_scale
    withProgress(message = "Calculating t-SNE...", {
      # Prepare data
      data_mat <- t(values$normalized_data)
      
      # Support dual grouping - use appropriate group level if dual grouping is enabled
      if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
        if (values$active_grouping_level == "biological") {
          group_labels <- create_proper_group_labels(values$biological_unique_groups, values$biological_group_column_indices)
        } else {
          group_labels <- create_proper_group_labels(values$experimental_unique_groups, values$experimental_group_column_indices)
        }
      } else {
        group_labels <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
      }
      
      # Clean data - handle NAs and infinite values
      data_mat[is.na(data_mat)] <- 0
      data_mat[is.infinite(data_mat)] <- 0
      
      # Run t-SNE
      tryCatch({
        set.seed(seed_val)
        tsne_res <- Rtsne::Rtsne(
          data_mat,
          dims = 2,
          perplexity = perplexity,
          max_iter = max_iter,
          theta = theta,
          pca_scale = do_scale,
          verbose = FALSE
        )
        
        # Get original sample names and use corrected names
        original_sample_names <- rownames(data_mat)
        cleaned_sample_names <- get_corrected_column_names(original_sample_names)
        
        # Create data frame for plotting
        df <- data.frame(tSNE1 = tsne_res$Y[,1],
             tSNE2 = tsne_res$Y[,2],
             Group = preserve_group_names(group_labels),
             Sample = cleaned_sample_names)
        group_levels <- get_group_order_for_plot(unique(group_labels))
        df$Group <- factor(df$Group, levels = group_levels)
        
        # Create plot
        p <- ggplot(df, aes(x = tSNE1, y = tSNE2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(title = "t-SNE Visualization",
               subtitle = paste0("perplexity = ", perplexity,
                                 ", iterations = ", max_iter,
                                 ", theta = ", theta)) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            plot.subtitle = element_text(hjust = 0.5),
            panel.grid = element_blank(),
            legend.title = element_blank(),
            legend.position = "bottom",
            legend.text = element_text(size = legend_text_size, face = "bold"),
            axis.text = element_text(face = "bold", size = axis_text_size),
            axis.title = element_text(face = "bold", size = axis_title_size)
          )
        
        # Apply grid layout to legend if 4+ groups
        if (length(unique(df$Group)) >= 4) {
          legend_layout <- get_legend_grid_layout(length(unique(df$Group)))
          p <- p + guides(color = guide_legend(nrow = legend_layout$nrow, ncol = legend_layout$ncol))
        }
        
        # Add ellipses if requested and possible
        if (input$tsne_add_ellipses) {
          # Check if we have enough points per group for ellipses
          group_counts <- table(df$Group)
          can_add_ellipse <- all(group_counts >= 3)
          
          if (can_add_ellipse) {
            p <- p + stat_ellipse(
              aes(fill = Group),
              geom = "polygon",
              alpha = 0.2,
              level = input$ellipseLevel,
              show.legend = FALSE
            )
          }
        }
        
        # Add sample labels if requested
        if (input$tsne_show_labels) {
          p <- p + ggrepel::geom_text_repel(
            aes(label = Sample),
            size = 3.5,
            box.padding = 0.5,
            point.padding = 0.3,
            segment.color = "grey50",
            max.overlaps = 20
          )
        }
        
        # Store the plot for download
        values$tsne_plot_obj <- p
        
        return(p)
        
      }, error = function(e) {
        # Return error message as plot
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("t-SNE calculation failed:", e$message),
                   hjust = 0.5) +
          theme_void()
        return(p)
      })
    })
  }, height = function() input$tsne_height %||% 600, width = function() input$tsne_width %||% 800, res = UI_PLOT_RES)
  
  # Add these download handlers to the server section
  
  # Download UMAP Plot
  output$downloadUMAPBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("UMAP_Plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$umap_plot_obj)
      
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, as.numeric(input$global_dpi))
      format <- get_safe_global_image_format()
      
      # Save the plot
      ggsave(file,
             plot = values$umap_plot_obj,
             width = input$umap_width / 100,
             height = input$umap_height / 100,
             dpi = dpi,
             device = resolve_ggsave_device(format),
             units = "in")
      
      showNotification("UMAP plot downloaded successfully!", type = "message")
    }
  )
  
  # Download t-SNE Plot
  output$downloadTSNEBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("tSNE_Plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$tsne_plot_obj)
      
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, as.numeric(input$global_dpi))
      format <- get_safe_global_image_format()
      
      # Save the plot
      ggsave(file,
             plot = values$tsne_plot_obj,
             width = input$tsne_width / 100,
             height = input$tsne_height / 100,
             dpi = dpi,
             device = resolve_ggsave_device(format),
             units = "in")
      
      showNotification("t-SNE plot downloaded successfully!", type = "message")
    }
  )
  # Differential Analysis - Server Code - Optimized for tab-specific execution with Data tab priority
  observeEvent({
    # Primary trigger: only when on Differential Analysis tab AND dependencies change
    list(
      input$current_tab,
      if (length(input$current_tab) > 0 && input$current_tab == "Differential Analysis") {
        list(
          values$normalized_data, values$cleaned_molecules,
          values$unique_groups, values$group_column_indices,
          input$diffGroup1, input$diffGroup2,
          input$diff_feature_source,
          input$pca_top_features, input$pca_feature_ranking,
          values$stat_results, input$diff_pval_cutoff, input$diff_fdr_cutoff,
          input$diff_fc_cutoff, input$sig_method
        )
      }
    )
  }, {
    # Pause heavy differential analysis operations if Data tab is active (priority loading)
    if (isTRUE(values$data_tab_active)) {
      return()
    }
    # Only proceed if we have the necessary data AND we're on the Differential Analysis tab
    req(length(input$current_tab) > 0 && input$current_tab == "Differential Analysis")
    req(values$normalized_data, values$cleaned_molecules,
        values$unique_groups, values$group_column_indices,
        input$diffGroup1, input$diffGroup2)
    
    # Check if both groups are the same
    if (input$diffGroup1 == input$diffGroup2) {
      # Show notification when identical groups are selected
      showNotification("Pairwise comparison requires at least two distinct groups.
                     The current dataset contains only one group or identical groups were selected.",
                       type = "warning", duration = 5)
      # Clear any existing plots/data to avoid showing stale results
      output$diffMAPlotGrid <- renderPlot({ 
        plot.new()
        title("Please select two different groups for comparison", line = 0)
      }, res = UI_PLOT_RES)
      output$diffVolcanoPlotGrid <- renderPlot({ 
        plot.new()
        title("Please select two different groups for comparison", line = 0)
      }, res = UI_PLOT_RES)
      output$diffResultsTable <- DT::renderDataTable({ DT::datatable(data.frame()) })
      output$diffSummary <- renderPrint({ cat("No comparison available. Please select two different groups.") })
      return()
    }
    
    # Get group indices
    group1_idx <- which(values$unique_groups == input$diffGroup1)
    if (length(group1_idx) == 0) {
      #showNotification("Selected group 1 not found in unique_groups.", type = "error")
      return(NULL)
    }
    
    group2_idx <- which(values$unique_groups == input$diffGroup2)
    if (length(group2_idx) == 0) {
      #showNotification("Selected group 2 not found in unique_groups.", type = "error")
      return(NULL)
    }
    
    # Extract data for the selected groups
    group1_columns <- values$group_column_indices[[group1_idx]]
    group2_columns <- values$group_column_indices[[group2_idx]]
    
    # Define the comparison name
    comparison_name <- paste(input$diffGroup1, "vs", input$diffGroup2)
    
    # Get appropriate p-value and fold change columns
    p_value_column <- get_appropriate_pvalue_column(comparison_name)
    fc_column_result <- get_foldchange_column(comparison_name)
    
    # Check if fold change column result contains the REVERSED marker
    is_reversed <- FALSE
    if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
      is_reversed <- TRUE
      # Extract the actual column name by removing the REVERSED: prefix
      fc_column <- gsub("^REVERSED:", "", fc_column_result)
    } else {
      fc_column <- fc_column_result
    }
    
    if (!is.null(values$stat_results) && !is.null(fc_column) &&
        p_value_column %in% colnames(values$stat_results) &&
        fc_column %in% colnames(values$stat_results)) {
      
      # Get group indices
      group1_idx <- which(values$unique_groups == input$diffGroup1)
      group2_idx <- which(values$unique_groups == input$diffGroup2)
      
      # Get group means for MA plot x-axis
      data1 <- values$normalized_data[, values$group_column_indices[[group1_idx]], drop = FALSE]
      data2 <- values$normalized_data[, values$group_column_indices[[group2_idx]], drop = FALSE]
      
      # Ensure all vectors have the same length before proceeding
      if (nrow(data1) != length(values$cleaned_molecules) ||
          nrow(data2) != length(values$cleaned_molecules)) {
        showNotification("Dimension mismatch between data matrices and feature names.", type = "error")
        return(NULL)
      }
      
      mean_group1 <- rowMeans(data1, na.rm = TRUE)
      mean_group2 <- rowMeans(data2, na.rm = TRUE)
      
      # Use precomputed adjusted p-values
      adjusted_p_values <- values$stat_results[[p_value_column]]
      
      # Apply feature source filtering first
      feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
      if (!is.null(input$diff_feature_source) && input$diff_feature_source != "all") {
        comparison_name <- paste(input$diffGroup1, "vs", input$diffGroup2)
        feature_indices <- get_feature_indices_by_source(input$diff_feature_source, comparison_name)
        
        # Filter all data vectors to selected features
        if (length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
          mean_group1 <- mean_group1[feature_indices]
          mean_group2 <- mean_group2[feature_indices]
          adjusted_p_values <- adjusted_p_values[feature_indices]
        }
      }
      
      # Calculate fold change as Group2/Group1 after filtering
      # When data is log-scale: log2_fc = mean2 - mean1 (subtraction in log scale)
      # When data is NOT log-scale: log2_fc = log2(mean2 / mean1) (division then log)
      if (is_data_log_scale()) {
        log2_fc <- mean_group2 - mean_group1
      } else {
        log2_fc <- log2(mean_group2 / mean_group1)
      }
      
      # Calculate mean intensity
      mean_intensity <- (mean_group1 + mean_group2) / 2
      
    } else {
      # Instead of falling back to manual calculation, show a notification and exit
      showNotification(paste("Required precomputed statistics not found for", comparison_name,
                             ". Please run the statistical analysis in the Data tab first."),
                       type = "error", duration = 10)
      return()
    }
    # Create data frame ensuring all vectors are the same length
    diff_data <- tryCatch({
      # Use filtered feature names and data
      selected_features <- if (exists("feature_indices") && length(feature_indices) > 0 &&
                               length(feature_indices) < length(values$cleaned_molecules)) {
        values$cleaned_molecules[feature_indices]
      } else {
        values$cleaned_molecules
      }
      
      data.frame(
        Feature = selected_features,
        Mean = mean_intensity,
        Log2FC = log2_fc,
        AdjustedPValue = adjusted_p_values,
        Group1Mean = mean_group1,
        Group2Mean = mean_group2,
        stringsAsFactors = FALSE
      )
    }, error = function(e) {
      showNotification(paste("Error creating differential analysis data frame:", e$message), type = "error")
      return(NULL)
    })
    
    if (is.null(diff_data)) return(NULL)
    
    # Remove rows with NA values that would cause plotting issues
    diff_data <- diff_data[!is.na(diff_data$Log2FC) & !is.na(diff_data$AdjustedPValue), ]
    # FDR handling for ROTS
    fdr_values <- NULL
    if (input$sig_method == "rots") {
      # Check both possible orders for comparison name
      comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
      fdr_direct_name <- paste0(comparison_name, "_FDR")
      fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
      
      if (!is.null(values$stat_results)) {
        if (fdr_direct_name %in% colnames(values$stat_results)) {
          fdr_column <- fdr_direct_name
          fdr_values_full <- values$stat_results[[fdr_column]]
          
          # Apply feature filtering to FDR values if needed
          if (exists("feature_indices") && length(feature_indices) > 0 &&
              length(feature_indices) < length(values$cleaned_molecules)) {
            fdr_values <- fdr_values_full[feature_indices]
          } else {
            fdr_values <- fdr_values_full
          }
          
          # Filter out NA values to match diff_data
          good_indices <- which(!is.na(diff_data$Log2FC) & !is.na(diff_data$AdjustedPValue))
          if (length(fdr_values) >= max(good_indices)) {
            fdr_values <- fdr_values[good_indices]
            
            # Only add if lengths now match
            if (length(fdr_values) == nrow(diff_data)) {
              diff_data$FDR <- fdr_values
            }
          }
        } else if (fdr_alt_name %in% colnames(values$stat_results)) {
          fdr_column <- fdr_alt_name
          fdr_values_full <- values$stat_results[[fdr_column]]
          
          # Apply feature filtering to FDR values if needed
          if (exists("feature_indices") && length(feature_indices) > 0 &&
              length(feature_indices) < length(values$cleaned_molecules)) {
            fdr_values <- fdr_values_full[feature_indices]
          } else {
            fdr_values <- fdr_values_full
          }
          
          # Filter out NA values to match diff_data
          good_indices <- which(!is.na(diff_data$Log2FC) & !is.na(diff_data$AdjustedPValue))
          if (length(fdr_values) >= max(good_indices)) {
            fdr_values <- fdr_values[good_indices]
            
            # Only add if lengths now match
            if (length(fdr_values) == nrow(diff_data)) {
              diff_data$FDR <- fdr_values
            }
          }
        }
      }
    }
    
    # Modify the part that classifies significance based on thresholds
    tryCatch({
      diff_data$Significance <- "Not Significant"
      
      if (input$sig_method == "rots" && "FDR" %in% colnames(diff_data)) {
        # Require all three: FC, p-val, and FDR
        diff_data$Significance[diff_data$Log2FC > input$diff_fc_cutoff &
                                 diff_data$AdjustedPValue < input$diff_pval_cutoff &
                                 diff_data$FDR < input$diff_fdr_cutoff] <- "Upregulated"
        
        diff_data$Significance[diff_data$Log2FC < -input$diff_fc_cutoff &
                                 diff_data$AdjustedPValue < input$diff_pval_cutoff &
                                 diff_data$FDR < input$diff_fdr_cutoff] <- "Downregulated"
      } else {
        # For non-ROTS: just FC and p-value
        diff_data$Significance[diff_data$Log2FC > input$diff_fc_cutoff &
                                 diff_data$AdjustedPValue < input$diff_pval_cutoff] <- "Upregulated"
        
        diff_data$Significance[diff_data$Log2FC < -input$diff_fc_cutoff &
                                 diff_data$AdjustedPValue < input$diff_pval_cutoff] <- "Downregulated"
      }
      
      # Store results
      values$diff_data <- diff_data
      
      # Count significant features
      upregulated_count <- sum(diff_data$Significance == "Upregulated", na.rm = TRUE)
      downregulated_count <- sum(diff_data$Significance == "Downregulated", na.rm = TRUE)
      nonsig_count <- sum(diff_data$Significance == "Not Significant", na.rm = TRUE)
      
      values$diff_summary <- list(
        upregulated = upregulated_count,
        downregulated = downregulated_count,
        nonsignificant = nonsig_count,
        total = nrow(diff_data)
      )
    }, error = function(e) {
      # showNotification(paste("Error classifying differentially expressed features:", e$message,
      #                        "\nThis is often due to excessive missing values or insufficient data."),
      #                  type = "error", duration = 10)
      
      # Create an empty results structure to avoid further errors
      values$diff_data <- data.frame(
        Feature = character(0),
        Mean = numeric(0),
        Log2FC = numeric(0),
        AdjustedPValue = numeric(0),
        Group1Mean = numeric(0),
        Group2Mean = numeric(0),
        Significance = character(0)
      )
      
      values$diff_summary <- list(
        upregulated = 0,
        downregulated = 0,
        nonsignificant = 0,
        total = 0
      )
    })
    # Display summary statistics
    output$diffSummary <- renderPrint({
      cat("Comparison:", input$diffGroup1, "vs", input$diffGroup2, "\n\n")
      cat("Summary Statistics:\n")
      cat("- Upregulated features:", sum(diff_data$Significance == "Upregulated"), "\n")
      cat("- Downregulated features:", sum(diff_data$Significance == "Downregulated"), "\n")
      cat("- Non-significant features:", sum(diff_data$Significance == "Not Significant"), "\n")
      cat("- Total features analyzed:", nrow(diff_data), "\n\n")
      
      cat("Threshold Settings:\n")
      cat("- Log2 fold change threshold:", input$diff_fc_cutoff, "\n")
      
      # Display either FDR or p-value threshold depending on which was used
      if (input$sig_method == "rots" && "FDR" %in% colnames(diff_data)) {
        cat("- FDR threshold:", input$diff_fdr_cutoff, "\n")
        cat("- Statistical method: ROTS (using FDR for filtering)\n")
      } else {
        cat("- Adjusted p-value threshold:", input$diff_pval_cutoff, "\n")
        cat("- Statistical method:", input$sig_method, "\n")
      }
    })
    
    # Display results table (only significant features)
    output$diffResultsTable <- DT::renderDataTable({
      # Ensure we have differential analysis data
      if (is.null(values$diff_data) || nrow(values$diff_data) == 0) {
        return(DT::datatable(data.frame(Message = "No differential analysis results available. Please run the analysis first."), options = list(dom = 't')))
      }
      
      # Filter to show only significant features (exclude "Not Significant")
      filtered_diff_data <- values$diff_data %>%
        dplyr::filter(Significance != "Not Significant")
      
      # Check if there are any significant features
      if (nrow(filtered_diff_data) == 0) {
        return(DT::datatable(data.frame(Message = "No significant features found with current thresholds. Please adjust your significance criteria."), options = list(dom = 't')))
      }
      
      # Prepare results table with conditional columns for FDR
      if(input$sig_method == "rots" && "FDR" %in% colnames(filtered_diff_data)) {
        # Include FDR column for ROTS
        results_table <- filtered_diff_data %>%
          dplyr::select(Feature, Group1Mean, Group2Mean, Log2FC, AdjustedPValue, FDR, Significance) %>%
          dplyr::rename(
            !!paste0(input$diffGroup1, " Mean") := Group1Mean,
            !!paste0(input$diffGroup2, " Mean") := Group2Mean,
            `log2 Fold Change` = Log2FC,
            `Adjusted P-value` = AdjustedPValue
          ) %>%
          dplyr::arrange(FDR)
      } else {
        # Standard table without FDR column
        results_table <- filtered_diff_data %>%
          dplyr::select(Feature, Group1Mean, Group2Mean, Log2FC, AdjustedPValue, Significance) %>%
          dplyr::rename(
            !!paste0(input$diffGroup1, " Mean") := Group1Mean,
            !!paste0(input$diffGroup2, " Mean") := Group2Mean,
            `log2 Fold Change` = Log2FC,
            `Adjusted P-value` = AdjustedPValue
          ) %>%
          dplyr::arrange(`Adjusted P-value`)
      }
      
      DT::datatable(
        results_table,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          autoWidth = TRUE
        ),
        rownames = FALSE
      ) %>%
        DT::formatRound(columns = c(2:ncol(results_table)), digits = 6) %>%
        DT::formatStyle(
          'Significance',
          backgroundColor = DT::styleEqual(
            c("Upregulated", "Downregulated", "Not Significant"),
            c(input$diff_upreg_color, input$diff_downreg_color, "#FFFFFF")
          ),
          fontWeight = DT::styleEqual(
            c("Upregulated", "Downregulated"),
            c("bold", "bold")
          )
        )
    })
    
    # Generate cached MA plots for grid (only when data changes)
    generate_ma_grid_plots <- reactive({
      # Add explicit reactive dependencies
      input$diff_label_type
      input$diff_label_features
      input$diff_max_labels
      input$diff_fc_cutoff
      input$diff_pval_cutoff
      input$diff_fdr_cutoff
      input$diff_feature_source
      
      # Check if statistical results exist
      if (is.null(values$stat_results)) {
        return(NULL)
      }
      
      # Use pairwise combinations from the modal (if available)
      # Only show plots for comparisons that were explicitly set by the user
      if (is.null(values$current_pairwise_combinations) || nrow(values$current_pairwise_combinations) == 0) {
        return(NULL)
      }
      
      # De-duplicate pairwise combinations while preserving order
      combos_df <- values$current_pairwise_combinations
      if (!is.null(combos_df) && nrow(combos_df) > 1) {
        combo_keys <- apply(combos_df[, c("Group_1", "Group_2"), drop = FALSE], 1, function(row) {
          groups <- sort(c(as.character(row["Group_1"]), as.character(row["Group_2"])))
          paste(groups[1], groups[2], sep = "__")
        })
        combos_df <- combos_df[!duplicated(combo_keys), , drop = FALSE]
      }
      
      # Convert the pairwise combinations data frame to a list format
      group_combinations <- lapply(1:nrow(combos_df), function(i) {
        c(combos_df[i, "Group_1"],
          combos_df[i, "Group_2"])
      })
      
      if (length(group_combinations) == 0) {
        return(NULL)
      }
      
      # Create individual MA plots for each comparison
      ma_plots <- list()
      
      for (i in seq_along(group_combinations)) {
        group1 <- as.character(group_combinations[[i]][1])
        group2 <- as.character(group_combinations[[i]][2])
        
        # Handle lmROTS/lmeROTS variable comparisons (marked with "[Variable]" in Group_2)
        # MA plots require actual sample data from two groups - skip variable comparisons
        is_variable_comparison <- (group2 == "[Variable]")
        if (is_variable_comparison) {
          # Skip MA plots for variable comparisons - they don't have group-based sample data
          # Use volcano plots instead for lmROTS/lmeROTS results
          next
        }
        
        comparison_name <- paste(group1, "vs", group2)
        
        # Get appropriate columns
        p_value_column <- get_appropriate_pvalue_column(comparison_name)
        fc_column_result <- get_foldchange_column(comparison_name)
        
        # Check if fold change column result contains the REVERSED marker
        is_reversed <- FALSE
        if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
          is_reversed <- TRUE
          fc_column <- gsub("^REVERSED:", "", fc_column_result)
        } else {
          fc_column <- fc_column_result
        }
        
        # Check if required columns exist
        if (is.null(p_value_column) || is.null(fc_column) ||
            !p_value_column %in% colnames(values$stat_results) ||
            !fc_column %in% colnames(values$stat_results)) {
          
          # Skip this comparison - don't create placeholder plot
          # This matches behavior of Welch t-test and Mann-Whitney where we only show
          # plots for comparisons with actual statistical results
          next
        }
        
        # Apply feature source filtering
        feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
        if (!is.null(input$diff_feature_source) && input$diff_feature_source != "all") {
          feature_indices <- get_feature_indices_by_source(input$diff_feature_source, comparison_name)
        }
        
        # Get group indices and calculate means (filtered by feature source)
        group1_idx <- which(values$unique_groups == group1)
        group2_idx <- which(values$unique_groups == group2)
        
        data1 <- values$normalized_data[feature_indices, values$group_column_indices[[group1_idx]], drop = FALSE]
        data2 <- values$normalized_data[feature_indices, values$group_column_indices[[group2_idx]], drop = FALSE]
        
        mean_group1 <- rowMeans(data1, na.rm = TRUE)
        mean_group2 <- rowMeans(data2, na.rm = TRUE)
        mean_intensity <- (mean_group1 + mean_group2) / 2
        
        # Calculate fold change as Group2/Group1
        # When data is log-scale: log2_fc = mean2 - mean1 (subtraction in log scale)
        # When data is NOT log-scale: log2_fc = log2(mean2 / mean1) (division then log)
        if (is_data_log_scale()) {
          log2_fc <- mean_group2 - mean_group1
        } else {
          log2_fc <- log2(mean_group2 / mean_group1)
        }
        
        # Get statistical p-values (filtered by feature source)
        adjusted_p_values <- values$stat_results[[p_value_column]][feature_indices]
        
        # Get FDR values if ROTS is selected and FDR column exists
        fdr_values <- NULL
        if (input$sig_method == "rots") {
          # Check both possible orders for comparison name
          comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
          fdr_direct_name <- paste0(comparison_name, "_FDR")
          fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
          
          if (fdr_direct_name %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[fdr_direct_name]][feature_indices]
          } else if (fdr_alt_name %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[fdr_alt_name]][feature_indices]
          }
        }
        
        # Create data frame
        plot_data <- data.frame(
          Mean = mean_intensity,
          Log2FC = log2_fc,
          AdjustedPValue = adjusted_p_values,
          stringsAsFactors = FALSE
        )
        
        # Add FDR column if available
        if (!is.null(fdr_values)) {
          plot_data$FDR <- fdr_values
        }
        
        # Add Feature column for labels
        plot_data$Feature <- values$cleaned_molecules[feature_indices]
        
        # Add ID column if available
        if (!is.null(values$accession_ids) && length(values$accession_ids) >= length(feature_indices)) {
          plot_data$ID <- values$accession_ids[feature_indices]
        }
        
        # Remove rows with missing values
        plot_data <- plot_data[complete.cases(plot_data[, c("Mean", "Log2FC", "AdjustedPValue")]), ]
        
        if (nrow(plot_data) == 0) {
          ma_plots[[i]] <- ggplot() +
            geom_text(aes(x = 0.5, y = 0.5), label = "No valid data", hjust = 0.5, vjust = 0.5) +
            labs(title = comparison_name) +
            theme_void()
          next
        }
        
        # Classify significance with proper FDR handling for ROTS
        plot_data$Significance <- "Not Significant"
        
        # Create dynamic label for significant but no FC based on threshold
        sig_no_fc_label <- paste0("-", input$diff_fc_cutoff, "\u2264log2FC\u2264", input$diff_fc_cutoff)
        
        if (input$sig_method == "rots" && "FDR" %in% colnames(plot_data)) {
          # For ROTS: require all three cutoffs (FC, p-value, and FDR)
          plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff] <- "Upregulated"
          plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff] <- "Downregulated"
          # Classify significant by p-value and FDR but without FC cutoff
          plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff &
                                   abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                   plot_data$Significance == "Not Significant"] <- sig_no_fc_label
        } else {
          # For non-ROTS methods: use only FC and p-value cutoffs
          plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Upregulated"
          plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Downregulated"
          # Classify significant by p-value but without FC cutoff
          plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                   plot_data$Significance == "Not Significant"] <- sig_no_fc_label
        }
        
        # Count significant features
        up_count <- sum(plot_data$Significance == "Upregulated", na.rm = TRUE)
        down_count <- sum(plot_data$Significance == "Downregulated", na.rm = TRUE)
        sig_no_fc_count <- sum(plot_data$Significance == sig_no_fc_label, na.rm = TRUE)
        
        # Create named vector for colors with dynamic label
        color_values <- c(
          "Not Significant" = input$diff_nonsig_color,
          "Upregulated" = input$diff_upreg_color,
          "Downregulated" = input$diff_downreg_color
        )
        color_values[sig_no_fc_label] <- input$diff_sig_no_fc_color
        
        # Determine legend layout based on number of significance categories
        # When FC cutoff is 0, only 3 categories exist (Upregulated, Downregulated, Not Significant)
        # When FC cutoff > 0, 4 categories exist (including sig_no_fc_label)
        legend_layout <- if (input$diff_fc_cutoff == 0) {
          guide_legend(nrow = 1)  # 1 row for 3 items
        } else {
          guide_legend(nrow = 2)  # 2 rows for 4 items
        }
        
        # Get font sizes from inputs or use defaults (coerced to numeric)
        title_size <- suppressWarnings(as.numeric(input$diff_title_size))
        if (is.na(title_size)) title_size <- 14
        axis_title_size <- suppressWarnings(as.numeric(input$diff_axis_title_size))
        if (is.na(axis_title_size)) axis_title_size <- 12
        axis_text_size <- suppressWarnings(as.numeric(input$diff_axis_text_size))
        if (is.na(axis_text_size)) axis_text_size <- 10
        legend_text_size <- suppressWarnings(as.numeric(input$diff_legend_text_size))
        if (is.na(legend_text_size)) legend_text_size <- 12
        count_label_size <- suppressWarnings(as.numeric(input$diff_count_label_size))
        if (is.na(count_label_size)) count_label_size <- 5
        jitter_size <- suppressWarnings(as.numeric(input$diff_jitter_size))
        if (is.na(jitter_size)) jitter_size <- 2
        
        # Create base MA plot (without legend settings - will be applied later)
        ma_plot <- ggplot(plot_data, aes(x = Mean, y = Log2FC, color = Significance)) +
          geom_point(size = jitter_size, alpha = 0.8) +
          scale_color_manual(values = color_values) +
          guides(color = legend_layout) +
          geom_hline(yintercept = 0, linetype = "dashed", color = "black") +
          geom_hline(yintercept = c(input$diff_fc_cutoff, -input$diff_fc_cutoff),
                     linetype = "dotted", color = input$diff_fc_line_color) +
          # Add count labels
          annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                   y = max(plot_data$Log2FC) * 0.85,
                   label = paste(up_count),
                   hjust = 0.5,
                   color = input$diff_upreg_color,
                   size = count_label_size,
                   fontface = "bold",
                   label.padding = unit(0.3, "lines")) +
          annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                   y = min(plot_data$Log2FC) * 0.85,
                   label = paste(down_count),
                   hjust = 0.5,
                   color = input$diff_downreg_color,
                   size = count_label_size,
                   fontface = "bold",
                   label.padding = unit(0.3, "lines"))
        
        # Add sig_no_fc count label if there are any such features
        if (sig_no_fc_count > 0) {
          ma_plot <- ma_plot +
            annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                     y = 0,
                     label = paste(sig_no_fc_count),
                     hjust = 0.5,
                     color = input$diff_sig_no_fc_color,
                     size = count_label_size,
                     fontface = "bold",
                     label.padding = unit(0.3, "lines"))
        }
        
        ma_plot <- ma_plot +
          labs(
            title = comparison_name,
            x = "Mean Expression (A)",
            y = "log2 Fold Change (M)"
          ) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            axis.title = element_text(size = axis_title_size),
            axis.text = element_text(size = axis_text_size),
            plot.margin = unit(c(50, 10, 10, 10), "pt"),
            legend.title = element_blank(),
            legend.text = element_text(size = legend_text_size)
          )
        # Add feature names if option is selected
        if(!is.null(input$diff_label_type) && input$diff_label_type != "none") {
          # Determine which features to label based on user selection
          if(!is.null(input$diff_label_features) && input$diff_label_features == "significant") {
            # Only label significant features
            label_data <- plot_data[plot_data$Significance != "Not Significant", ]
          } else if(!is.null(input$diff_label_features) && input$diff_label_features == "top") {
            # Label top n features by significance, but only among significant features
            significant_data <- plot_data[plot_data$Significance != "Not Significant", ]
            if (nrow(significant_data) > 0) {
              top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(significant_data)) else 10
              label_data <- significant_data[order(significant_data$AdjustedPValue), ][1:min(top_n, nrow(significant_data)), ]
            } else {
              label_data <- data.frame()
            }
          } else if(!is.null(input$diff_label_features) && input$diff_label_features == "all") {
            # Label all features (no limit)
            label_data <- plot_data
          } else {
            # Default: Label top features (with limit)
            top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(plot_data)) else 10
            label_data <- plot_data[1:min(top_n, nrow(plot_data)), ]
          }
          
          # Add labels using ggrepel for better layout
          if(nrow(label_data) > 0) {
            # Determine which label to use based on radio button selection
            use_ids <- input$diff_label_type == "ids" && "ID" %in% colnames(label_data)
            label_column <- if(use_ids) "ID" else "Feature"
            
            ma_plot <- ma_plot +
              ggrepel::geom_text_repel(
                data = label_data,
                aes(label = .data[[label_column]]),
                size = 2.5,
                box.padding = 0.3,
                point.padding = 0.1,
                force = 1,
                segment.color = "gray50",
                max.overlaps = 15
              )
          }
        }
        
        ma_plots[[i]] <- ma_plot
      }
      
      return(ma_plots)
    })    # Super fast MA plot grid renderer (optimized for layout-only changes)
    output$diffMAPlotGrid <- renderPlot({ 
      ma_plots <- generate_ma_grid_plots()
      
      if (!is.null(ma_plots)) {
        ma_plots <- Filter(Negate(is.null), ma_plots)
      }
      
      if (is.null(ma_plots) || length(ma_plots) == 0) {
        plot.new()
        title(main = "No statistical results available.\nPlease run statistical analysis in the Data tab first.",
              cex.main = 1.2, col.main = "red")
        return()
      }
      
      values$diff_ma_grid_count <- length(ma_plots)
      
      # Apply legend settings to all plots quickly (this is fast)
      show_legend <- if(!is.null(input$diffGridLegend)) input$diffGridLegend else FALSE
      
      if (!show_legend) {
        # Quick legend removal
        ma_plots <- lapply(ma_plots, function(p) {
          p + theme(legend.position = "none")
        })
      } else {
        # Show legends at bottom
        ma_plots <- lapply(ma_plots, function(p) {
          p + theme(legend.position = "bottom")
        })
      }
      
      # Arrange plots in grid (this is very fast)
      grid_cols <- if(!is.null(input$diffGridCols)) input$diffGridCols else 2
      grid_plot <- gridExtra::grid.arrange(grobs = ma_plots, ncol = grid_cols,
                                           top = grid::textGrob(
                                             paste0("MA Plots - All Pairwise Comparisons\n",
                                                    "Log2FC cutoff:  ", input$diff_fc_cutoff,
                                                    " | p-value cutoff: ", input$diff_pval_cutoff,
                                                    if(input$sig_method == "rots" && !is.null(input$diff_fdr_cutoff))
                                                      paste0(" | FDR cutoff: ", input$diff_fdr_cutoff) else "",
                                                    if(!is.null(input$diff_feature_source) && input$diff_feature_source != "all")
                                                      paste0(" | Features: ", switch(input$diff_feature_source,
                                                                                     "pca" = "PCA Selected",
                                                                                     "ml" = "ML Selected",
                                                                                     "All")) else "",
                                                    if(input$bootstrap_enabled == "yes") " | Bootstrap Statistics" else ""),
                                             gp = grid::gpar(fontsize = 14, fontface = "bold")
                                           ))
      values$diff_ma_grid_obj <- grid_plot
      return(grid_plot)
    }, height = function() {
      n_plots <- if (!is.null(values$diff_ma_grid_count)) values$diff_ma_grid_count else if (is.null(values$current_pairwise_combinations)) 0
      else nrow(values$current_pairwise_combinations)
      grid_cols <- if(!is.null(input$diffGridCols)) input$diffGridCols else 2
      n_rows <- ceiling(n_plots / grid_cols)
      grid_height <- if(!is.null(input$diffGridHeight)) input$diffGridHeight else 400
      max(300, n_rows * grid_height)
    }, width = function() {
      grid_cols <- if(!is.null(input$diffGridCols)) input$diffGridCols else 2
      grid_width <- if(!is.null(input$diffGridWidth)) input$diffGridWidth else 400
      grid_cols * grid_width
    }, res = UI_PLOT_RES)
    
    # Generate cached volcano plots for grid (only when data changes)
    generate_volcano_grid_plots <- reactive({
      # Add explicit reactive dependencies
      input$diff_label_type
      input$diff_label_features
      input$diff_max_labels
      input$diff_fc_cutoff
      input$diff_pval_cutoff
      input$diff_fdr_cutoff
      input$diff_feature_source
      
      # Check if statistical results exist
      if (is.null(values$stat_results)) {
        return(NULL)
      }
      
      # Use pairwise combinations from the modal (if available)
      # Only show plots for comparisons that were explicitly set by the user
      if (is.null(values$current_pairwise_combinations) || nrow(values$current_pairwise_combinations) == 0) {
        return(NULL)
      }
      
      # De-duplicate pairwise combinations while preserving order
      combos_df <- values$current_pairwise_combinations
      if (!is.null(combos_df) && nrow(combos_df) > 1) {
        combo_keys <- apply(combos_df[, c("Group_1", "Group_2"), drop = FALSE], 1, function(row) {
          groups <- sort(c(as.character(row["Group_1"]), as.character(row["Group_2"])))
          paste(groups[1], groups[2], sep = "__")
        })
        combos_df <- combos_df[!duplicated(combo_keys), , drop = FALSE]
      }

      # Convert the pairwise combinations data frame to a list format
      group_combinations <- lapply(1:nrow(combos_df), function(i) {
        c(combos_df[i, "Group_1"],
          combos_df[i, "Group_2"])
      })
      
      if (length(group_combinations) == 0) {
        return(NULL)
      }
      
      # Create individual volcano plots for each comparison
      volcano_plots <- list()
      
      for (i in seq_along(group_combinations)) {
        group1 <- as.character(group_combinations[[i]][1])
        group2 <- as.character(group_combinations[[i]][2])
        
        # Handle lmROTS/lmeROTS variable comparisons (marked with "[Variable]" in Group_2)
        # For these, the comparison_name IS the variable name (e.g., "lmROTS_Age"), not "Group1 vs Group2"
        is_variable_comparison <- (group2 == "[Variable]")
        if (is_variable_comparison) {
          comparison_name <- group1  # e.g., "lmROTS_Age"
        } else {
          comparison_name <- paste(group1, "vs", group2)
        }
        
        # Get appropriate columns
        p_value_column <- get_appropriate_pvalue_column(comparison_name)
        fc_column_result <- get_foldchange_column(comparison_name)
        
        # Check if fold change column result contains the REVERSED marker
        is_reversed <- FALSE
        if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
          is_reversed <- TRUE
          fc_column <- gsub("^REVERSED:", "", fc_column_result)
        } else {
          fc_column <- fc_column_result
        }
        
        # Check if required columns exist
        if (is.null(p_value_column) || is.null(fc_column) ||
            !p_value_column %in% colnames(values$stat_results) ||
            !fc_column %in% colnames(values$stat_results)) {
          
          # Skip this comparison - don't create placeholder plot
          # This matches behavior of Welch t-test and Mann-Whitney where we only show
          # plots for comparisons with actual statistical results
          next
        }
        
        # Apply feature source filtering
        feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
        if (!is.null(input$diff_feature_source) && input$diff_feature_source != "all") {
          feature_indices <- get_feature_indices_by_source(input$diff_feature_source, comparison_name)
        }
        
        # Get statistical data (filtered by feature source)
        log2_fc <- values$stat_results[[fc_column]][feature_indices]
        if (is_reversed) {
          log2_fc <- -log2_fc
        }
        adjusted_p_values <- values$stat_results[[p_value_column]][feature_indices]
        
        # Get FDR values if ROTS is selected and FDR column exists
        fdr_values <- NULL
        if (input$sig_method == "rots") {
          # Check both possible orders for comparison name
          comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
          fdr_direct_name <- paste0(comparison_name, "_FDR")
          fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
          
          if (fdr_direct_name %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[fdr_direct_name]][feature_indices]
          } else if (fdr_alt_name %in% colnames(values$stat_results)) {
            fdr_values <- values$stat_results[[fdr_alt_name]][feature_indices]
          }
        }
        
        # Create data frame
        plot_data <- data.frame(
          Log2FC = log2_fc,
          AdjustedPValue = adjusted_p_values,
          stringsAsFactors = FALSE
        )
        
        # Add FDR column if available
        if (!is.null(fdr_values)) {
          plot_data$FDR <- fdr_values
        }
        
        # Add Feature column for labels
        plot_data$Feature <- values$cleaned_molecules[feature_indices]
        
        # Add ID column if available
        if (!is.null(values$accession_ids) && length(values$accession_ids) >= length(feature_indices)) {
          plot_data$ID <- values$accession_ids[feature_indices]
        }
        
        # Remove rows with missing values
        plot_data <- plot_data[complete.cases(plot_data[, c("Log2FC", "AdjustedPValue")]), ]

        # Prevent -log10(0) = Inf by replacing zero or negative p-values with a small positive value
        # Use the smallest positive p-value in the dataset if available, otherwise use a tiny default
        if (all(is.na(plot_data$AdjustedPValue) | plot_data$AdjustedPValue <= 0)) {
          plot_data$AdjustedPValue <- pmax(plot_data$AdjustedPValue, 1e-300)
        } else {
          min_pos <- min(plot_data$AdjustedPValue[plot_data$AdjustedPValue > 0], na.rm = TRUE)
          if (is.finite(min_pos) && min_pos > 0) {
            plot_data$AdjustedPValue[plot_data$AdjustedPValue <= 0] <- min_pos
          } else {
            plot_data$AdjustedPValue[plot_data$AdjustedPValue <= 0] <- 1e-300
          }
        }

        # Compute negative log10 p-values for plotting and determine axis top limit dynamically
        plot_data$NegLogAdjP <- -log10(plot_data$AdjustedPValue)
        max_y <- max(plot_data$NegLogAdjP, na.rm = TRUE)
        # Provide a small expansion above the max to avoid clipping by titles/annotations
        pad_ratio <- 0.08
        if (!is.finite(max_y) || is.na(max_y) || max_y <= 0) {
          top_y <- 1
        } else if (max_y < 5) {
          # Small absolute padding for small y values
          top_y <- max_y + 0.5
        } else {
          # Relative padding for large y values
          top_y <- max_y * (1 + pad_ratio)
        }
        
        if (nrow(plot_data) == 0) {
          volcano_plots[[i]] <- ggplot() +
            geom_text(aes(x = 0.5, y = 0.5), label = "No valid data", hjust = 0.5, vjust = 0.5) +
            labs(title = comparison_name) +
            theme_void()
          next
        }
        
        # Classify significance with proper FDR handling for ROTS
        plot_data$Significance <- "Not Significant"
        
        # Create dynamic label for significant but no FC based on threshold
        sig_no_fc_label <- paste0("-", input$diff_fc_cutoff, "\u2264log2FC\u2264", input$diff_fc_cutoff)
        
        if (input$sig_method == "rots" && "FDR" %in% colnames(plot_data)) {
          # For ROTS: require all three cutoffs (FC, p-value, and FDR)
          plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff] <- "Upregulated"
          plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff] <- "Downregulated"
          # Classify significant by p-value and FDR but without FC cutoff
          plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   plot_data$FDR < input$diff_fdr_cutoff &
                                   abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                   plot_data$Significance == "Not Significant"] <- sig_no_fc_label
        } else {
          # For non-ROTS methods: use only FC and p-value cutoffs
          plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Upregulated"
          plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                   plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Downregulated"
          # Classify significant by p-value but without FC cutoff
          plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                   abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                   plot_data$Significance == "Not Significant"] <- sig_no_fc_label
        }
        
        # Count significant features
        up_count <- sum(plot_data$Significance == "Upregulated", na.rm = TRUE)
        down_count <- sum(plot_data$Significance == "Downregulated", na.rm = TRUE)
        sig_no_fc_count <- sum(plot_data$Significance == sig_no_fc_label, na.rm = TRUE)
        
        # Create named vector for colors with dynamic label
        color_values <- c(
          "Not Significant" = input$diff_nonsig_color,
          "Upregulated" = input$diff_upreg_color,
          "Downregulated" = input$diff_downreg_color
        )
        color_values[sig_no_fc_label] <- input$diff_sig_no_fc_color
        
        # Determine legend layout based on number of significance categories
        # When FC cutoff is 0, only 3 categories exist (Upregulated, Downregulated, Not Significant)
        # When FC cutoff > 0, 4 categories exist (including sig_no_fc_label)
        legend_layout <- if (input$diff_fc_cutoff == 0) {
          guide_legend(nrow = 1)  # 1 row for 3 items
        } else {
          guide_legend(nrow = 2)  # 2 rows for 4 items
        }
        
        # Determine y-axis label based on FDR correction method
        y_axis_label <- if (input$sig_method == "rots") {
          "-log10(Adjusted p-value)"  # ROTS always has built-in FDR
        } else if (input$fdr_method == "none") {
          "-log10(p-value)"  # No FDR correction applied
        } else {
          "-log10(Adjusted p-value)"  # FDR correction applied
        }
        
        # Get font sizes from inputs or use defaults (coerced to numeric)
        title_size <- suppressWarnings(as.numeric(input$diff_title_size))
        if (is.na(title_size)) title_size <- 14
        axis_title_size <- suppressWarnings(as.numeric(input$diff_axis_title_size))
        if (is.na(axis_title_size)) axis_title_size <- 12
        axis_text_size <- suppressWarnings(as.numeric(input$diff_axis_text_size))
        if (is.na(axis_text_size)) axis_text_size <- 10
        legend_text_size <- suppressWarnings(as.numeric(input$diff_legend_text_size))
        if (is.na(legend_text_size)) legend_text_size <- 12
        count_label_size <- suppressWarnings(as.numeric(input$diff_count_label_size))
        if (is.na(count_label_size)) count_label_size <- 5
        jitter_size <- suppressWarnings(as.numeric(input$diff_jitter_size))
        if (is.na(jitter_size)) jitter_size <- 2
        
        # Create base volcano plot (without legend settings - will be applied later)
        # Use precomputed NegLogAdjP and set y limits to add margin for tall volcanoes
        volcano_plot <- ggplot(plot_data, aes(x = Log2FC, y = NegLogAdjP, color = Significance)) +
          geom_point(size = jitter_size, alpha = 0.8) +
          scale_color_manual(values = color_values) +
          guides(color = legend_layout) +
          geom_vline(xintercept = c(-input$diff_fc_cutoff, input$diff_fc_cutoff),
                     linetype = "dotted", color = input$diff_fc_line_color) +
          geom_hline(yintercept = -log10(input$diff_pval_cutoff),
                     linetype = "dotted", color = input$diff_pval_line_color) +        # Add count labels like in single plots
          annotate("label", x = -max(abs(plot_data$Log2FC)) * 0.6,
                   y = top_y * 0.9,
                   label = paste(down_count),
                   hjust = 0.5,
                   color = input$diff_downreg_color,
                   size = count_label_size,
                   fontface = "bold",
                   label.padding = unit(0.3, "lines")) +
          annotate("label", x = max(abs(plot_data$Log2FC)) * 0.6,
                   y = top_y * 0.9,
                   label = paste(up_count),
                   hjust = 0.5,
                   color = input$diff_upreg_color,
                   size = count_label_size,
                   fontface = "bold",
                   label.padding = unit(0.3, "lines"))
        
        # Add sig_no_fc count label if there are any such features
        if (sig_no_fc_count > 0) {
          volcano_plot <- volcano_plot +
            annotate("label", x = 0,
                     y = top_y * 0.9,
                     label = paste(sig_no_fc_count),
                     hjust = 0.5,
                     color = input$diff_sig_no_fc_color,
                     size = count_label_size,
                     fontface = "bold")
        }
        
        # Use appropriate x-axis label: "Coefficient" for lmROTS/lmeROTS, "log2 Fold Change" otherwise
        x_axis_label <- if (is_variable_comparison) "Coefficient" else "log2 Fold Change"
        
        volcano_plot <- volcano_plot +
          labs(
            title = comparison_name,
            x = x_axis_label,
            y = y_axis_label
          ) +
          scale_y_continuous(limits = c(0, top_y), expand = expansion(mult = c(0, 0.02))) +
          scale_x_continuous(expand = expansion(mult = 0.12)) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
            axis.title = element_text(size = axis_title_size),
            axis.text = element_text(size = axis_text_size),
            plot.margin = unit(c(50, 10, 10, 10), "pt"),
            legend.title = element_blank(),
            legend.text = element_text(size = legend_text_size)
          )
        
        # Add feature names if option is selected
        if(!is.null(input$diff_label_type) && input$diff_label_type != "none") {
          # Determine which features to label based on user selection
          if(!is.null(input$diff_label_features) && input$diff_label_features == "significant") {
            # Only label significant features
            label_data <- plot_data[plot_data$Significance != "Not Significant", ]
          } else if(!is.null(input$diff_label_features) && input$diff_label_features == "top") {
            # Label top n features by significance, but only among significant features
            significant_data <- plot_data[plot_data$Significance != "Not Significant", ]
            if (nrow(significant_data) > 0) {
              top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(significant_data)) else 10
              label_data <- significant_data[order(significant_data$AdjustedPValue), ][1:min(top_n, nrow(significant_data)), ]
            } else {
              label_data <- data.frame()
            }
          } else if(!is.null(input$diff_label_features) && input$diff_label_features == "all") {
            # Label all features (no limit)
            label_data <- plot_data
          } else {
            # Default: Label top features (with limit)
            top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(plot_data)) else 10
            label_data <- plot_data[1:min(top_n, nrow(plot_data)), ]
          }
          
          # Add labels using ggrepel for better layout
          if(nrow(label_data) > 0) {
            # Determine which label to use based on radio button selection
            use_ids <- input$diff_label_type == "ids" && "ID" %in% colnames(label_data)
            label_column <- if(use_ids) "ID" else "Feature"
            
            volcano_plot <- volcano_plot +
              ggrepel::geom_text_repel(
                data = label_data,
                aes(label = .data[[label_column]]),
                size = 2.5,
                box.padding = 0.3,
                point.padding = 0.1,
                force = 1,
                segment.color = "gray50",
                max.overlaps = 15
              )
          }
        }
        
        volcano_plots[[i]] <- volcano_plot
      }
      
      return(volcano_plots)
    })
    
    # Fast volcano plot grid renderer (only applies layout changes)
    output$diffVolcanoPlotGrid <- renderPlot({ 
      volcano_plots <- generate_volcano_grid_plots()
      
      if (!is.null(volcano_plots)) {
        volcano_plots <- Filter(Negate(is.null), volcano_plots)
      }
      
      if (is.null(volcano_plots) || length(volcano_plots) == 0) {
        plot.new()
        title(main = "No statistical results available.\nPlease run statistical analysis in the Data tab first.",
              cex.main = 1.2, col.main = "red")
        return()
      }
      
      values$diff_volcano_grid_count <- length(volcano_plots)
      
      # Apply legend settings to all plots quickly
      show_legend <- if(!is.null(input$diffVolcanoGridLegend)) input$diffVolcanoGridLegend else FALSE
      
      if (!show_legend) {
        # Quick legend removal
        volcano_plots <- lapply(volcano_plots, function(p) {
          p + theme(legend.position = "none")
        })
      } else {
        # Show legends at bottom
        volcano_plots <- lapply(volcano_plots, function(p) {
          p + theme(legend.position = "bottom")
        })
      }      # Arrange plots in grid (this is very fast)
      grid_cols <- if(!is.null(input$diffVolcanoGridCols)) input$diffVolcanoGridCols else 2
      grid_plot <- gridExtra::grid.arrange(grobs = volcano_plots, ncol = grid_cols,
                                           top = grid::textGrob(
                                             paste0("Volcano Plots - All Pairwise Comparisons\n",
                                                    "Log2FC cutoff:  ", input$diff_fc_cutoff,
                                                    " | p-value cutoff: ", input$diff_pval_cutoff,
                                                    if(input$sig_method == "rots" && !is.null(input$diff_fdr_cutoff))
                                                      paste0(" | FDR cutoff: ", input$diff_fdr_cutoff) else "",
                                                    if(!is.null(input$diff_feature_source) && input$diff_feature_source != "all")
                                                      paste0(" | Features: ", switch(input$diff_feature_source,
                                                                                     "pca" = "PCA Selected",
                                                                                     "ml" = "ML Selected",
                                                                                     "All")) else "",
                                                    if(input$bootstrap_enabled == "yes") " | Bootstrap Statistics" else ""),
                                             gp = grid::gpar(fontsize = 14, fontface = "bold")
                                           ))
      values$diff_volcano_grid_obj <- grid_plot
      return(grid_plot)
    }, height = function() {
      n_plots <- if (!is.null(values$diff_volcano_grid_count)) values$diff_volcano_grid_count else if (is.null(values$current_pairwise_combinations)) 0
      else nrow(values$current_pairwise_combinations)
      grid_cols <- if(!is.null(input$diffVolcanoGridCols)) input$diffVolcanoGridCols else 2
      n_rows <- ceiling(n_plots / grid_cols)
      grid_height <- if(!is.null(input$diffVolcanoGridHeight)) input$diffVolcanoGridHeight else 400
      max(300, n_rows * grid_height)
    }, width = function() {
      grid_cols <- if(!is.null(input$diffVolcanoGridCols)) input$diffVolcanoGridCols else 2
      grid_width <- if(!is.null(input$diffVolcanoGridWidth)) input$diffVolcanoGridWidth else 400
      grid_cols * grid_width
    }, res = UI_PLOT_RES)
    
    # Download handlers for Differential Analysis tab - Grid plots only
    
    # Optimized MA Grid download handler (uses cached plots)
    output$downloadDiffMAGridBtn <- downloadHandler(
      filename = function() {
        format <- get_safe_global_image_format()
        paste0("All_Comparisons_MA_Grid_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      },
      content = function(file) {
        req(values$diff_ma_grid_obj)
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Calculate grid dimensions using current settings
        n_plots <- if (!is.null(values$diff_ma_grid_count)) values$diff_ma_grid_count else if (is.null(values$current_pairwise_combinations)) 0
        else nrow(values$current_pairwise_combinations)
        grid_cols <- if(!is.null(input$diffGridCols)) input$diffGridCols else 2
        n_rows <- ceiling(n_plots / grid_cols)
        
        # Get user-specified dimensions or use defaults
        plot_width <- if(!is.null(input$diffGridWidth)) input$diffGridWidth else 400
        plot_height <- if(!is.null(input$diffGridHeight)) input$diffGridHeight else 400
        # Save the cached grid plot directly
        ggsave(file,
               plot = values$diff_ma_grid_obj,
               width = (plot_width * grid_cols) / 72,
               height = (plot_height * n_rows) / 72,
               units = "in",
               dpi = dpi,
               device = resolve_ggsave_device(format))
        showNotification("MA grid plot downloaded successfully!", type = "message")
      }
    )
    
    # Optimized Volcano Grid download handler (uses cached plots)
    output$downloadDiffVolcanoGridBtn <- downloadHandler(
      filename = function() {
        format <- get_safe_global_image_format()
        paste0("All_Comparisons_Volcano_Grid_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      },
      content = function(file) {
        req(values$diff_volcano_grid_obj)
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Calculate grid dimensions using current settings
        n_plots <- if (!is.null(values$diff_volcano_grid_count)) values$diff_volcano_grid_count else if (is.null(values$current_pairwise_combinations)) 0
        else nrow(values$current_pairwise_combinations)
        grid_cols <- if(!is.null(input$diffVolcanoGridCols)) input$diffVolcanoGridCols else 2
        n_rows <- ceiling(n_plots / grid_cols)
        
        # Get user-specified dimensions or use defaults
        plot_width <- if(!is.null(input$diffVolcanoGridWidth)) input$diffVolcanoGridWidth else 400
        plot_height <- if(!is.null(input$diffVolcanoGridHeight)) input$diffVolcanoGridHeight else 400
        
        # Save the cached grid plot directly
        ggsave(file,
               plot = values$diff_volcano_grid_obj,
               width = (plot_width * grid_cols) / 72,
               height = (plot_height * n_rows) / 72,
               units = "in",
               dpi = dpi,
               device = resolve_ggsave_device(format))
        
        showNotification("Volcano grid plot downloaded successfully!", type = "message")
      }
    )
    
    # Single plot generators for selected pairwise comparison
    # Generate single MA plot for selected groups
    generate_single_ma_plot <- reactive({
      req(values$stat_results, input$diffGroup1, input$diffGroup2)
      
      if (input$diffGroup1 == input$diffGroup2) {
        return(NULL)
      }
      
      comparison_name <- paste(input$diffGroup1, "vs", input$diffGroup2)
      
      # Get appropriate columns using the same functions as grid plots
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Check if fold change column result contains the REVERSED marker
      is_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_column <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Check if required columns exist
      if (is.null(p_value_column) || is.null(fc_column) ||
          !p_value_column %in% colnames(values$stat_results) ||
          !fc_column %in% colnames(values$stat_results)) {
        return(NULL)
      }
      
      # Apply feature source filtering
      feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
      if (!is.null(input$diff_feature_source) && input$diff_feature_source != "all") {
        feature_indices <- get_feature_indices_by_source(input$diff_feature_source, comparison_name)
      }
      
      # Get group indices and calculate means (filtered by feature source)
      group1_idx <- which(values$unique_groups == input$diffGroup1)
      group2_idx <- which(values$unique_groups == input$diffGroup2)
      
      data1 <- values$normalized_data[feature_indices, values$group_column_indices[[group1_idx]], drop = FALSE]
      data2 <- values$normalized_data[feature_indices, values$group_column_indices[[group2_idx]], drop = FALSE]
      
      mean_group1 <- rowMeans(data1, na.rm = TRUE)
      mean_group2 <- rowMeans(data2, na.rm = TRUE)
      mean_intensity <- (mean_group1 + mean_group2) / 2
      
      # Calculate fold change based on data scale
      # When data is log-scale: log2_fc = mean_group2 - mean_group1 (subtraction in log space)
      # When data is linear: log2_fc = log2(mean_group2 / mean_group1) (log of division)
      if (is_data_log_scale()) {
        log2_fc <- mean_group2 - mean_group1
      } else {
        log2_fc <- log2(mean_group2 / mean_group1)
      }
      
      # Get statistical p-values (filtered by feature source)
      adjusted_p_values <- values$stat_results[[p_value_column]][feature_indices]
      
      # Get FDR values if ROTS is selected and FDR column exists
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        # Check both possible orders for comparison name
        comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
        fdr_direct_name <- paste0(comparison_name, "_FDR")
        fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
        
        if (fdr_direct_name %in% colnames(values$stat_results)) {
          fdr_values <- values$stat_results[[fdr_direct_name]][feature_indices]
        } else if (fdr_alt_name %in% colnames(values$stat_results)) {
          fdr_values <- values$stat_results[[fdr_alt_name]][feature_indices]
        }
      }
      
      # Prepare plot data
      plot_data <- data.frame(
        Mean = mean_intensity,
        Log2FC = log2_fc,
        AdjustedPValue = adjusted_p_values,
        stringsAsFactors = FALSE
      )
      
      # Add FDR column if available
      if (!is.null(fdr_values)) {
        plot_data$FDR <- fdr_values
      }
      
      # Add Feature column for labels
      plot_data$Feature <- values$cleaned_molecules[feature_indices]
      
      # Add ID column if available
      if (!is.null(values$accession_ids) && length(values$accession_ids) >= length(feature_indices)) {
        plot_data$ID <- values$accession_ids[feature_indices]
      }
      
      # Remove rows with missing values
      plot_data <- plot_data[complete.cases(plot_data[, c("Mean", "Log2FC", "AdjustedPValue")]), ]
      
      if (nrow(plot_data) == 0) {
        return(NULL)
      }
      
      # Classify significance with proper FDR handling for ROTS
      plot_data$Significance <- "Not Significant"
      
      # Create dynamic label for significant but no FC based on threshold
      sig_no_fc_label <- paste0("-", input$diff_fc_cutoff, "\u2264log2FC\u2264", input$diff_fc_cutoff)
      
      if (input$sig_method == "rots" && "FDR" %in% colnames(plot_data)) {
        # For ROTS: require all three cutoffs (FC, p-value, and FDR)
        plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff] <- "Upregulated"
        plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff] <- "Downregulated"
        # Classify significant by p-value and FDR but without FC cutoff
        plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff &
                                 abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                 plot_data$Significance == "Not Significant"] <- sig_no_fc_label
      } else {
        # For non-ROTS methods: use only FC and p-value cutoffs
        plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Upregulated"
        plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Downregulated"
        # Classify significant by p-value but without FC cutoff
        plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                 plot_data$Significance == "Not Significant"] <- sig_no_fc_label
      }
      
      # Count up/down regulated features
      up_count <- sum(plot_data$Significance == "Upregulated", na.rm = TRUE)
      down_count <- sum(plot_data$Significance == "Downregulated", na.rm = TRUE)
      sig_no_fc_count <- sum(plot_data$Significance == sig_no_fc_label, na.rm = TRUE)
      
      # Create named vector for colors with dynamic label
      color_values <- c(
        "Upregulated" = input$diff_upreg_color,
        "Downregulated" = input$diff_downreg_color,
        "Not Significant" = input$diff_nonsig_color
      )
      color_values[sig_no_fc_label] <- input$diff_sig_no_fc_color
      
      # Determine legend layout based on number of significance categories
      # When FC cutoff is 0, only 3 categories exist (Upregulated, Downregulated, Not Significant)
      # When FC cutoff > 0, 4 categories exist (including sig_no_fc_label)
      legend_layout <- if (input$diff_fc_cutoff == 0) {
        guide_legend(nrow = 1)  # 1 row for 3 items
      } else {
        guide_legend(nrow = 2)  # 2 rows for 4 items
      }
      
      # Get font sizes from inputs or use defaults (coerced to numeric)
      title_size <- suppressWarnings(as.numeric(input$diff_title_size))
      if (is.na(title_size)) title_size <- 14
      axis_title_size <- suppressWarnings(as.numeric(input$diff_axis_title_size))
      if (is.na(axis_title_size)) axis_title_size <- 12
      axis_text_size <- suppressWarnings(as.numeric(input$diff_axis_text_size))
      if (is.na(axis_text_size)) axis_text_size <- 10
      legend_text_size <- suppressWarnings(as.numeric(input$diff_legend_text_size))
      if (is.na(legend_text_size)) legend_text_size <- 12
      count_label_size <- suppressWarnings(as.numeric(input$diff_count_label_size))
      if (is.na(count_label_size)) count_label_size <- 5
      jitter_size <- suppressWarnings(as.numeric(input$diff_jitter_size))
      if (is.na(jitter_size)) jitter_size <- 2
      
      # Create MA plot
      ma_plot <- ggplot(plot_data, aes(x = Mean, y = Log2FC)) +
        geom_point(aes(color = Significance), alpha = 0.7, size = jitter_size) +
        scale_color_manual(values = color_values) +
        guides(color = legend_layout) +
        geom_hline(yintercept = c(-input$diff_fc_cutoff, input$diff_fc_cutoff),
                   linetype = "dashed", color = input$diff_fc_line_color) +
        # Add count labels
        annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                 y = max(plot_data$Log2FC) * 0.85,
                 label = paste(up_count),
                 hjust = 0.5,
                 color = input$diff_upreg_color,
                 size = count_label_size,
                 fontface = "bold",
                 label.padding = unit(0.3, "lines")) +
        annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                 y = min(plot_data$Log2FC) * 0.85,
                 label = paste(down_count),
                 hjust = 0.5,
                 color = input$diff_downreg_color,
                 size = count_label_size,
                 fontface = "bold",
                 label.padding = unit(0.3, "lines"))
      
      # Add sig_no_fc count label if there are any such features
      if (sig_no_fc_count > 0) {
        ma_plot <- ma_plot +
          annotate("label", x = min(plot_data$Mean) + (max(plot_data$Mean) - min(plot_data$Mean)) * 0.12,
                   y = 0,
                   label = paste(sig_no_fc_count),
                   hjust = 0.5,
                   color = input$diff_sig_no_fc_color,
                   size = count_label_size,
                   fontface = "bold",
                   label.padding = unit(0.3, "lines"))
      }
      
      ma_plot <- ma_plot +
        labs(
          title = paste(comparison_name),
          x = "Mean Expression (A)",
          y = "log2 Fold Change (M)"
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
          axis.title = element_text(size = axis_title_size),
          axis.text = element_text(size = axis_text_size),
          plot.margin = unit(c(50, 10, 10, 10), "pt"),
          legend.title = element_blank(),
          legend.text = element_text(size = legend_text_size),
          legend.position = "bottom"
        )    # Add feature names if option is selected
      if(!is.null(input$diff_label_type) && input$diff_label_type != "none") {
        # Determine which features to label
        if(!is.null(input$diff_label_features) && input$diff_label_features == "significant") {
          label_data <- plot_data[plot_data$Significance != "Not Significant", ]
        } else if(!is.null(input$diff_label_features) && input$diff_label_features == "top") {
          # Label top n features by significance, but only among significant features
          significant_data <- plot_data[plot_data$Significance != "Not Significant", ]
          if (nrow(significant_data) > 0) {
            top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(significant_data)) else 10
            label_data <- significant_data[order(significant_data$AdjustedPValue), ][1:min(top_n, nrow(significant_data)), ]
          } else {
            label_data <- data.frame()
          }
        } else if(!is.null(input$diff_label_features) && input$diff_label_features == "all") {
          # Label all features (no limit)
          label_data <- plot_data
        } else {
          # Default: Label top features (with limit)
          top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(plot_data)) else 10
          label_data <- plot_data[1:min(top_n, nrow(plot_data)), ]
        }
        
        if(nrow(label_data) > 0) {
          # Determine which label to use based on radio button selection
          use_ids <- input$diff_label_type == "ids" && "ID" %in% colnames(label_data)
          label_column <- if(use_ids) "ID" else "Feature"
          
          ma_plot <- ma_plot +
            ggrepel::geom_text_repel(
              data = label_data,
              aes(label = .data[[label_column]]),
              size = 2.5,
              box.padding = 0.3,
              point.padding = 0.1,
              force = 1,
              segment.color = "gray50",
              max.overlaps = 15
            )
        }
      }
      
      return(ma_plot)
    })
    # Generate single Volcano plot for selected groups
    generate_single_volcano_plot <- reactive({
      req(values$stat_results, input$diffGroup1, input$diffGroup2)
      
      if (input$diffGroup1 == input$diffGroup2) {
        return(NULL)
      }
      
      comparison_name <- paste(input$diffGroup1, "vs", input$diffGroup2)
      
      # Get appropriate columns using the same functions as grid plots
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Check if fold change column result contains the REVERSED marker
      is_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_column <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Check if required columns exist
      if (is.null(p_value_column) || is.null(fc_column) ||
          !p_value_column %in% colnames(values$stat_results) ||
          !fc_column %in% colnames(values$stat_results)) {
        return(NULL)
      }
      
      # Apply feature source filtering
      feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
      if (!is.null(input$diff_feature_source) && input$diff_feature_source != "all") {
        feature_indices <- get_feature_indices_by_source(input$diff_feature_source, comparison_name)
      }
      
      # Get statistical data and apply reversal before filtering
      log2_fc <- values$stat_results[[fc_column]]
      if (is_reversed) {
        log2_fc <- -log2_fc
      }
      adjusted_p_values <- values$stat_results[[p_value_column]]
      
      # Apply feature filtering after reversal
      log2_fc <- log2_fc[feature_indices]
      adjusted_p_values <- adjusted_p_values[feature_indices]
      
      # Get FDR values if ROTS is selected and FDR column exists
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        # Check both possible orders for comparison name
        comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
        fdr_direct_name <- paste0(comparison_name, "_FDR")
        fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
        
        if (fdr_direct_name %in% colnames(values$stat_results)) {
          fdr_values <- values$stat_results[[fdr_direct_name]][feature_indices]
        } else if (fdr_alt_name %in% colnames(values$stat_results)) {
          fdr_values <- values$stat_results[[fdr_alt_name]][feature_indices]
        }
      }
      
      # Prepare plot data
      plot_data <- data.frame(
        Log2FC = log2_fc,
        AdjustedPValue = adjusted_p_values,
        stringsAsFactors = FALSE
      )
      
      # Add FDR column if available
      if (!is.null(fdr_values)) {
        plot_data$FDR <- fdr_values
      }
      
      # Add Feature column for labels
      plot_data$Feature <- values$cleaned_molecules[feature_indices]
      
      # Add ID column if available
      if (!is.null(values$accession_ids) && length(values$accession_ids) >= length(feature_indices)) {
        plot_data$ID <- values$accession_ids[feature_indices]
      }
      
      # Remove rows with missing values
      plot_data <- plot_data[complete.cases(plot_data[, c("Log2FC", "AdjustedPValue")]), ]

      # Prevent -log10(0) = Inf by replacing zero or negative p-values with a small positive value
      if (all(is.na(plot_data$AdjustedPValue) | plot_data$AdjustedPValue <= 0)) {
        plot_data$AdjustedPValue <- pmax(plot_data$AdjustedPValue, 1e-300)
      } else {
        min_pos <- min(plot_data$AdjustedPValue[plot_data$AdjustedPValue > 0], na.rm = TRUE)
        if (is.finite(min_pos) && min_pos > 0) {
          plot_data$AdjustedPValue[plot_data$AdjustedPValue <= 0] <- min_pos
        } else {
          plot_data$AdjustedPValue[plot_data$AdjustedPValue <= 0] <- 1e-300
        }
      }

      # Compute negative log10 p-values and determine top y-axis limit
      plot_data$NegLogAdjP <- -log10(plot_data$AdjustedPValue)
      max_y <- max(plot_data$NegLogAdjP, na.rm = TRUE)
      pad_ratio <- 0.08
      if (!is.finite(max_y) || is.na(max_y) || max_y <= 0) {
        top_y <- 1
      } else if (max_y < 5) {
        top_y <- max_y + 0.5
      } else {
        top_y <- max_y * (1 + pad_ratio)
      }
      
      if (nrow(plot_data) == 0) {
        return(NULL)
      }
      
      # Classify significance with proper FDR handling for ROTS
      plot_data$Significance <- "Not Significant"
      
      # Create dynamic label for significant but no FC based on threshold
      sig_no_fc_label <- paste0("-", input$diff_fc_cutoff, "\u2264log2FC\u2264", input$diff_fc_cutoff)
      
      if (input$sig_method == "rots" && "FDR" %in% colnames(plot_data)) {
        # For ROTS: require all three cutoffs (FC, p-value, and FDR)
        plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff] <- "Upregulated"
        plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff] <- "Downregulated"
        # Classify significant by p-value and FDR but without FC cutoff
        plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 plot_data$FDR < input$diff_fdr_cutoff &
                                 abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                 plot_data$Significance == "Not Significant"] <- sig_no_fc_label
      } else {
        # For non-ROTS methods: use only FC and p-value cutoffs
        plot_data$Significance[plot_data$Log2FC > input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Upregulated"
        plot_data$Significance[plot_data$Log2FC < -input$diff_fc_cutoff &
                                 plot_data$AdjustedPValue < input$diff_pval_cutoff] <- "Downregulated"
        # Classify significant by p-value but without FC cutoff
        plot_data$Significance[plot_data$AdjustedPValue < input$diff_pval_cutoff &
                                 abs(plot_data$Log2FC) <= input$diff_fc_cutoff &
                                 plot_data$Significance == "Not Significant"] <- sig_no_fc_label
      }
      
      # Count up/down regulated features
      up_count <- sum(plot_data$Significance == "Upregulated", na.rm = TRUE)
      down_count <- sum(plot_data$Significance == "Downregulated", na.rm = TRUE)
      sig_no_fc_count <- sum(plot_data$Significance == sig_no_fc_label, na.rm = TRUE)
      
      # Create named vector for colors with dynamic label
      color_values <- c(
        "Upregulated" = input$diff_upreg_color,
        "Downregulated" = input$diff_downreg_color,
        "Not Significant" = input$diff_nonsig_color
      )
      color_values[sig_no_fc_label] <- input$diff_sig_no_fc_color
      
      # Determine legend layout based on number of significance categories
      # When FC cutoff is 0, only 3 categories exist (Upregulated, Downregulated, Not Significant)
      # When FC cutoff > 0, 4 categories exist (including sig_no_fc_label)
      legend_layout <- if (input$diff_fc_cutoff == 0) {
        guide_legend(nrow = 1)  # 1 row for 3 items
      } else {
        guide_legend(nrow = 2)  # 2 rows for 4 items
      }
      
      # Determine y-axis label based on FDR correction method
      y_axis_label <- if (input$sig_method == "rots") {
        "-log10(Adjusted p-value)"  # ROTS always has built-in FDR
      } else if (input$fdr_method == "none") {
        "-log10(p-value)"  # No FDR correction applied
      } else {
        "-log10(Adjusted p-value)"  # FDR correction applied
      }
      
      # Get font sizes from inputs or use defaults (coerced to numeric)
      title_size <- suppressWarnings(as.numeric(input$diff_title_size))
      if (is.na(title_size)) title_size <- 14
      axis_title_size <- suppressWarnings(as.numeric(input$diff_axis_title_size))
      if (is.na(axis_title_size)) axis_title_size <- 12
      axis_text_size <- suppressWarnings(as.numeric(input$diff_axis_text_size))
      if (is.na(axis_text_size)) axis_text_size <- 10
      legend_text_size <- suppressWarnings(as.numeric(input$diff_legend_text_size))
      if (is.na(legend_text_size)) legend_text_size <- 12
      count_label_size <- suppressWarnings(as.numeric(input$diff_count_label_size))
      if (is.na(count_label_size)) count_label_size <- 5
      jitter_size <- suppressWarnings(as.numeric(input$diff_jitter_size))
      if (is.na(jitter_size)) jitter_size <- 2
      
      # Create Volcano plot
      volcano_plot <- ggplot(plot_data, aes(x = Log2FC, y = NegLogAdjP)) +
        geom_point(aes(color = Significance), alpha = 0.7, size = jitter_size) +
        scale_color_manual(values = color_values) +
        guides(color = legend_layout) +
        geom_vline(xintercept = c(-input$diff_fc_cutoff, input$diff_fc_cutoff),
                   linetype = "dashed", color = input$diff_fc_line_color) +
        geom_hline(yintercept = -log10(input$diff_pval_cutoff),
                   linetype = "dotted", color = input$diff_pval_line_color) +      # Add count labels
        annotate("label", x = -max(abs(plot_data$Log2FC)) * 0.6,
           y = top_y * 0.9,
                 label = paste(down_count),
                 hjust = 0.5,
                 color = input$diff_downreg_color,
                 size = count_label_size,
                 fontface = "bold",
                 label.padding = unit(0.3, "lines")) +
        annotate("label", x = max(abs(plot_data$Log2FC)) * 0.6,
           y = top_y * 0.9,
                 label = paste(up_count),
                 hjust = 0.5,
                 color = input$diff_upreg_color,
                 size = count_label_size,
                 fontface = "bold",
                 label.padding = unit(0.3, "lines"))
      
      # Add sig_no_fc count label if there are any such features
      if (sig_no_fc_count > 0) {
        volcano_plot <- volcano_plot +
          annotate("label", x = 0,
                   y = top_y * 0.9,
                   label = paste(sig_no_fc_count),
                   hjust = 0.5,
                   color = input$diff_sig_no_fc_color,
                   size = count_label_size,
                   fontface = "bold")
      }
      
        volcano_plot <- volcano_plot +
        labs(
          title = paste(comparison_name),
          x = "log2 Fold Change",
          y = y_axis_label
        ) +
          scale_y_continuous(limits = c(0, top_y), expand = expansion(mult = c(0, 0.02))) +
          scale_x_continuous(expand = expansion(mult = 0.12)) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
          axis.title = element_text(size = axis_title_size),
          axis.text = element_text(size = axis_text_size),
          plot.margin = unit(c(50, 10, 10, 10), "pt"),
          legend.title = element_blank(),
          legend.text = element_text(size = legend_text_size),
          legend.position = "bottom"
        )
      # Add feature names if option is selected
      if(!is.null(input$diff_label_type) && input$diff_label_type != "none") {
        # Determine which features to label
        if(!is.null(input$diff_label_features) && input$diff_label_features == "significant") {
          label_data <- plot_data[plot_data$Significance != "Not Significant", ]
        } else if(!is.null(input$diff_label_features) && input$diff_label_features == "top") {
          # Label top n features by significance, but only among significant features
          significant_data <- plot_data[plot_data$Significance != "Not Significant", ]
          if (nrow(significant_data) > 0) {
            top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(significant_data)) else 10
            label_data <- significant_data[order(significant_data$AdjustedPValue), ][1:min(top_n, nrow(significant_data)), ]
          } else {
            label_data <- data.frame()
          }
        } else if(!is.null(input$diff_label_features) && input$diff_label_features == "all") {
          # Label all features (no limit)
          label_data <- plot_data
        } else {
          # Default: Label top features (with limit)
          top_n <- if(!is.null(input$diff_max_labels)) min(input$diff_max_labels, nrow(plot_data)) else 10
          label_data <- plot_data[1:min(top_n, nrow(plot_data)), ]
        }
        
        if(nrow(label_data) > 0) {
          # Determine which label to use based on radio button selection
          use_ids <- input$diff_label_type == "ids" && "ID" %in% colnames(label_data)
          label_column <- if(use_ids) "ID" else "Feature"
          
          volcano_plot <- volcano_plot +
            ggrepel::geom_text_repel(
              data = label_data,
              aes(label = .data[[label_column]]),
              size = 2.5,
              box.padding = 0.3,
              point.padding = 0.1,
              force = 1,
              segment.color = "gray50",
              max.overlaps = 15
            )
        }
      }
      
      return(volcano_plot)
    })
    
    # Single plot outputs
    
    # Single MA Plot output
    output$diffSingleMAPlot <- renderPlot({ 
      ma_plot <- generate_single_ma_plot()
      
      if (is.null(ma_plot)) {
        plot.new()
        title(main = "Please select different groups for comparison\nor run statistical analysis first.",
              cex.main = 1.2, col.main = "red")
        return()
      }
      
      return(ma_plot)
    }, res = UI_PLOT_RES)
    
    # Single Volcano Plot output
    output$diffSingleVolcanoPlot <- renderPlot({ 
      volcano_plot <- generate_single_volcano_plot()
      
      if (is.null(volcano_plot)) {
        plot.new()
        title(main = "Please select different groups for comparison\nor run statistical analysis first.",
              cex.main = 1.2, col.main = "red")
        return()
      }
      
      return(volcano_plot)
    }, res = UI_PLOT_RES)
    
    # Single plot download handlers
    
    # Download single MA plot
    output$downloadDiffMABtn <- downloadHandler(
      filename = function() {
        format <- get_safe_global_image_format()
        paste0(input$diffGroup1, "_vs_", input$diffGroup2, "_MA_Plot_",
               format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      },
      content = function(file) {
        ma_plot <- generate_single_ma_plot()
        req(ma_plot)
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Save the plot
        ggsave(file,
               plot = ma_plot,
               width = input$diff_width,
               height = input$diff_height,
               dpi = dpi,
               device = resolve_ggsave_device(format))
        
        showNotification("Single MA plot downloaded successfully!", type = "message")
      }
    )
    
    # Download single Volcano plot
    output$downloadDiffVolcanoBtn <- downloadHandler(
      filename = function() {
        format <- get_safe_global_image_format()
        paste0(input$diffGroup1, "_vs_", input$diffGroup2, "_Volcano_Plot_",
               format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      },
      content = function(file) {
        volcano_plot <- generate_single_volcano_plot()
        req(volcano_plot)
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Save the plot
        ggsave(file,
               plot = volcano_plot,
               width = input$diff_width,
               height = input$diff_height,
               dpi = dpi,
               device = resolve_ggsave_device(format))
        showNotification("Single Volcano plot downloaded successfully!", type = "message")
      }
    )
    
    # Download differential analysis results data
    output$downloadDiffDataBtn <- downloadHandler(
      filename = function() {
        paste0(input$diffGroup1, "_vs_", input$diffGroup2, "_Differential_Analysis_Results_",
               format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
      },
      content = function(file) {
        req(values$diff_data)
        
        # Prepare the results table
        results_table <- values$diff_data %>%
          dplyr::select(Feature, Group1Mean, Group2Mean, Log2FC,
                        AdjustedPValue, if(input$sig_method == "rots" && "FDR" %in% colnames(values$diff_data)) FDR else NULL,
                        Significance) %>%
          dplyr::rename(
            !!paste0(input$diffGroup1, " Mean") := Group1Mean,
            !!paste0(input$diffGroup2, " Mean") := Group2Mean,
            `log2 Fold Change` = Log2FC,
            `Adjusted P-value` = AdjustedPValue
          ) %>%
          # Sort by FDR instead of adjusted p-value when ROTS is used and FDR is available
          arrange(if(input$sig_method == "rots" && "FDR" %in% colnames(values$diff_data)) FDR else `Adjusted P-value`)
        
        # Create a workbook with multiple sheets
        wb <- openxlsx::createWorkbook()
        
        # Add results sheet
        openxlsx::addWorksheet(wb, "Differential_Analysis_Results")
        openxlsx::writeData(wb, "Differential_Analysis_Results", results_table)
        
        # Add summary sheet
        openxlsx::addWorksheet(wb, "Analysis_Summary")
        summary_data <- data.frame(
          Parameter = c("Comparison", "Statistical Method", "Log2 Fold Change Threshold",
                        "P-value Threshold", if(input$sig_method == "rots" && "FDR" %in% colnames(values$diff_data)) "FDR Threshold" else NULL,
                        "Upregulated Features", "Downregulated Features", "Non-significant Features", "Total Features"),
          Value = c(paste(input$diffGroup1, "vs", input$diffGroup2),
                    input$sig_method,
                    input$diff_fc_cutoff,
                    input$diff_pval_cutoff,
                    if(input$sig_method == "rots" && "FDR" %in% colnames(values$diff_data)) input$diff_fdr_cutoff else NULL,
                    sum(values$diff_data$Significance == "Upregulated", na.rm = TRUE),
                    sum(values$diff_data$Significance == "Downregulated", na.rm = TRUE),
                    sum(values$diff_data$Significance == "Not Significant", na.rm = TRUE),
                    nrow(values$diff_data))
        )
        openxlsx::writeData(wb, "Analysis_Summary", summary_data)
        
        # Save the workbook
        openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
        
        showNotification("Differential analysis results downloaded successfully!", type = "message")
      }
    )
    
  }) # Close the main Differential Analysis observeEvent
  
  # Intersection Analysis - Server Code - Optimized for tab-specific execution
  observeEvent({
    # Primary trigger: only when on Intersection Analysis tab AND dependencies change
    list(
      input$current_tab,
      if (length(input$current_tab) > 0 && input$current_tab == "Intersection Analysis") {
        list(
          values$normalized_data, values$cleaned_molecules,
          values$unique_groups, values$group_column_indices, input$intersection_sets,
          input$intersection_source,
          # React to up/down toggles and thresholds
          input$intersection_include_up, input$intersection_include_down,
          input$intersection_pval_cutoff, input$intersection_fc_cutoff, input$intersection_fdr_cutoff,
          input$bootstrap_enabled,
          if (input$intersection_source == "pairwise") {            list(input$intersection_feature_source,
                                                                         input$pca_top_features, input$pca_feature_ranking,
                                                                         values$stat_results)
          }
        )
      }
    )
  }, {
    req(length(input$current_tab) > 0 && input$current_tab == "Intersection Analysis")
    req(values$normalized_data, values$cleaned_molecules,
        values$unique_groups, values$group_column_indices, input$intersection_sets)
    
    # Validate number of sets
    if (length(input$intersection_sets) < 2) {
      return()
    }
    
    # Progress indicator
    withProgress(message = paste0("Generating ",
                                  ifelse(length(input$intersection_sets) <= 5, "Venn diagram", "UpSet plot"),
                                  "..."), {
                                    
                                    # Storage for sets and their data
                                    intersection_sets <- list()
                                    set_names <- character()
                                    empty_set_names <- character()  # To track which sets are empty
                                    
                                    # Process each selected comparison
                                    for (i in seq_along(input$intersection_sets)) {
                                      setProgress(i / length(input$intersection_sets), detail = paste("Processing set", i))
                                      
                                      comparison_name <- input$intersection_sets[i]
                                      comparison <- values$intersection_comparisons[[comparison_name]]
                                      is_variable_comparison <- !is.null(comparison$variable)
                                      group1 <- if (is_variable_comparison) NULL else comparison$group1
                                      group2 <- if (is_variable_comparison) NULL else comparison$group2
                                      
                                      # Check if bootstrap is enabled and bootstrap statistics are available
                                      use_bootstrap <- (input$bootstrap_enabled == "yes" &&
                                                          !is.null(values$stat_results) &&
                                                          paste0(comparison_name, "_Bootstrap_AdjPValue") %in% colnames(values$stat_results) &&
                                                          paste0(comparison_name, "_Bootstrap_Log2FC") %in% colnames(values$stat_results))
                                      
                                      # Get the appropriate p-value and fold change columns using our improved functions
                                      p_value_column <- get_appropriate_pvalue_column(comparison_name)
                                      fc_column <- get_foldchange_column(comparison_name)
                                      
                                      # Debug information
                                      cat("Intersection analysis debug for", comparison_name, ":\n")
                                      cat("- P-value column:", p_value_column, "\n")
                                      cat("- Fold change column:", fc_column, "\n")
                                      if (!is.null(values$stat_results)) {
                                        cat("- Available columns:", paste(colnames(values$stat_results), collapse = ", "), "\n")
                                        cat("- Number of rows in stat_results:", nrow(values$stat_results), "\n")
                                      } else {
                                        cat("- stat_results is NULL\n")
                                      }
                                      
                                      # Initialize an empty vector for significant features
                                      significant_features <- character()
                                      
                                      # Check if the required columns exist
                                      if(!is.null(values$stat_results) &&
                                         p_value_column %in% colnames(values$stat_results) &&
                                         fc_column %in% colnames(values$stat_results)) {
                                        # Get the precomputed values
                                        adjusted_p_values <- values$stat_results[[p_value_column]]
                                        log2_fc <- values$stat_results[[fc_column]]
                                        
                                        # Debug: show basic stats about the data
                                        cat("- Adjusted p-values summary: min=", min(adjusted_p_values, na.rm=TRUE),
                                            ", max=", max(adjusted_p_values, na.rm=TRUE),
                                            ", length=", length(adjusted_p_values), "\n")
                                        cat("- Log2 FC summary: min=", min(log2_fc, na.rm=TRUE),
                                            ", max=", max(log2_fc, na.rm=TRUE),
                                            ", length=", length(log2_fc), "\n")
                                        cat("- Thresholds: p-value <=", input$intersection_pval_cutoff,
                                            ", |FC| >=", input$intersection_fc_cutoff, "\n")
                                        
                                        # Debug: Show filtering mode
                                        if (input$intersection_include_up && input$intersection_include_down) {
                                          cat("- Using magnitude filtering (both up and down selected)\n")
                                        } else if (input$intersection_include_up) {
                                          cat("- Using directional filtering (up-regulated only)\n")
                                        } else if (input$intersection_include_down) {
                                          cat("- Using directional filtering (down-regulated only)\n")
                                        } else {
                                          cat("- WARNING: No direction selected (neither up nor down)\n")
                                        }
                                        
                                        # Apply feature source filtering (only for pairwise source)
                                        feature_indices <- seq_along(values$cleaned_molecules)  # Default to all features
                                        feature_molecules <- values$cleaned_molecules  # Default to all molecules
                                        if (input$intersection_source == "pairwise" &&
                                            !is.null(input$intersection_feature_source) && input$intersection_feature_source != "all") {    feature_indices <- get_feature_indices_by_source(input$intersection_feature_source, comparison_name)
                                            
                                            # Filter statistical data and molecules to selected features
                                            if (length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
                                              adjusted_p_values <- adjusted_p_values[feature_indices]
                                              log2_fc <- log2_fc[feature_indices]
                                              feature_molecules <- values$cleaned_molecules[feature_indices]
                                            }
                                        }
                                        # Collect features based on thresholds and direction
                                        # If both up and down are selected, use magnitude filtering
                                        # If only one direction selected, use directional filtering
                                        if (input$intersection_include_up && input$intersection_include_down) {
                                          # Use magnitude filtering (absolute value)
                                          if (input$sig_method == "rots") {
                                            fdr_col <- paste0(comparison_name, "_FDR")
                                            if (!is_variable_comparison && !is.null(group1) && !is.null(group2)) {
                                              alt_fdr_col <- paste0(group2, "_vs_", group1, "_FDR")
                                              if (!fdr_col %in% colnames(values$stat_results) && alt_fdr_col %in% colnames(values$stat_results)) {
                                                fdr_col <- alt_fdr_col
                                              }
                                            }
                                            if (fdr_col %in% colnames(values$stat_results)) {
                                              # Get FDR values and filter them if feature filtering is applied
                                              fdr_vals_full <- values$stat_results[[fdr_col]]
                                              if (input$intersection_source == "pairwise" &&
                                                  !is.null(input$intersection_feature_source) && input$intersection_feature_source != "all" &&
                                                  length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
                                                fdr_vals <- fdr_vals_full[feature_indices]
                                              } else {
                                                fdr_vals <- fdr_vals_full
                                              }
                                              
                                              sig_idx <- which(
                                                abs(log2_fc) >= input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff &
                                                  fdr_vals < input$intersection_fdr_cutoff
                                              )
                                            } else {
                                              sig_idx <- which(
                                                abs(log2_fc) >= input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff
                                              )
                                            }
                                          } else {
                                            sig_idx <- which(
                                              abs(log2_fc) >= input$intersection_fc_cutoff &
                                                adjusted_p_values < input$intersection_pval_cutoff
                                            )
                                          }
                                          
                                          if (length(sig_idx) > 0) {
                                            significant_features <- c(significant_features, feature_molecules[sig_idx])
                                          }
                                        } else if (input$intersection_include_up) {
                                          # Directional filtering - up only
                                          if (input$sig_method == "rots") {
                                            fdr_col <- paste0(comparison_name, "_FDR")
                                            alt_fdr_col <- paste0(group2, "_vs_", group1, "_FDR")
                                            if (!fdr_col %in% colnames(values$stat_results) && alt_fdr_col %in% colnames(values$stat_results)) {
                                              fdr_col <- alt_fdr_col
                                            }
                                            
                                            if (fdr_col %in% colnames(values$stat_results)) {
                                              # Get FDR values and filter them if feature filtering is applied
                                              fdr_vals_full <- values$stat_results[[fdr_col]]
                                              if (input$intersection_source == "pairwise" &&
                                                  !is.null(input$intersection_feature_source) && input$intersection_feature_source != "all" &&
                                                  length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
                                                fdr_vals <- fdr_vals_full[feature_indices]
                                              } else {
                                                fdr_vals <- fdr_vals_full
                                              }
                                              
                                              up_idx <- which(
                                                log2_fc > input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff &
                                                  fdr_vals < input$intersection_fdr_cutoff
                                              )
                                            } else {
                                              up_idx <- which(
                                                log2_fc > input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff
                                              )
                                            }
                                          } else {
                                            up_idx <- which(
                                              log2_fc > input$intersection_fc_cutoff &
                                                adjusted_p_values < input$intersection_pval_cutoff
                                            )
                                          }
                                          
                                          if (length(up_idx) > 0) {
                                            significant_features <- c(significant_features, feature_molecules[up_idx])
                                          }
                                        }
                                        if (input$intersection_include_down && !input$intersection_include_up) {
                                          # Directional filtering - down only
                                          if (input$sig_method == "rots") {
                                            fdr_col <- paste0(comparison_name, "_FDR")
                                            alt_fdr_col <- paste0(group2, "_vs_", group1, "_FDR")
                                            if (!fdr_col %in% colnames(values$stat_results) && alt_fdr_col %in% colnames(values$stat_results)) {
                                              fdr_col <- alt_fdr_col
                                            }
                                            if (fdr_col %in% colnames(values$stat_results)) {
                                              # Get FDR values and filter them if feature filtering is applied
                                              fdr_vals_full <- values$stat_results[[fdr_col]]
                                              if (input$intersection_source == "pairwise" &&
                                                  !is.null(input$intersection_feature_source) && input$intersection_feature_source != "all" &&
                                                  length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
                                                fdr_vals <- fdr_vals_full[feature_indices]
                                              } else {
                                                fdr_vals <- fdr_vals_full
                                              }
                                              
                                              down_idx <- which(
                                                log2_fc < -input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff &
                                                  fdr_vals < input$intersection_fdr_cutoff
                                              )
                                            } else {
                                              down_idx <- which(
                                                log2_fc < -input$intersection_fc_cutoff &
                                                  adjusted_p_values < input$intersection_pval_cutoff
                                              )
                                            }
                                          } else {
                                            down_idx <- which(
                                              log2_fc < -input$intersection_fc_cutoff &
                                                adjusted_p_values < input$intersection_pval_cutoff
                                            )
                                          }
                                          
                                          if (length(down_idx) > 0) {
                                            significant_features <- c(significant_features, feature_molecules[down_idx])
                                          }
                                        }
                                        
                                        # Notify user about which statistics are being used
                                        if(use_bootstrap && i == 1) {
                                          showNotification("Using bootstrap statistics for intersection analysis", type = "message")
                                        } else if(grepl("^PostHoc_", p_value_column) && i == 1) {
                                          showNotification("Using post-hoc test statistics for intersection analysis", type = "message")
                                        }
                                      } else {
                                        # Show error if statistics not available
                                        showNotification(paste("Required statistics not found for", comparison_name,
                                                               ". Please run statistical analysis first."), type = "error")
                                      }
                                      
                                      # Debug: Show results of filtering
                                      cat("- Features found after filtering:", length(significant_features), "\n")
                                      if (length(significant_features) > 0) {
                                        cat("- First few features:", head(significant_features, 3), "\n")
                                      }
                                      
                                      # Check if this set has any significant features
                                      if (length(significant_features) == 0) {
                                        empty_set_names <- c(empty_set_names, comparison_name)
                                      } else {
                                        # Validate that the significant features exist in the original data universe
                                        # - Use union of possible name sources (normalized rownames + cleaned_molecules)
                                        # - Case-insensitive and trimmed matching to be robust to formatting
                                        if (!is.null(values$normalized_data) || !is.null(values$cleaned_molecules)) {
                                          source_names <- character(0)
                                          if (!is.null(values$normalized_data) && !is.null(rownames(values$normalized_data))) {
                                            source_names <- c(source_names, rownames(values$normalized_data))
                                          }
                                          if (!is.null(values$cleaned_molecules)) {
                                            source_names <- c(source_names, values$cleaned_molecules)
                                          }
                                          source_names <- unique(na.omit(as.character(source_names)))
                                          
                                          if (length(source_names) > 0) {
                                            # Clean and match (case-insensitive)
                                            significant_features_clean <- trimws(as.character(significant_features))
                                            source_names_clean <- trimws(as.character(source_names))
                                            sig_lower <- tolower(significant_features_clean)
                                            src_lower <- tolower(source_names_clean)
                                            
                                            keep_idx <- sig_lower %in% src_lower
                                            valid_features <- significant_features_clean[keep_idx]
                                            
                                            # Debug: show validation effect
                                            cat("- After existence validation, kept:", length(valid_features), "of", length(significant_features_clean), "features\n")
                                            if (length(valid_features) > 0) {
                                              cat("- Valid feature examples:", head(valid_features, 3), "\n")
                                            }
                                            
                                            if (length(valid_features) != length(significant_features_clean)) {
                                              missing_count <- length(significant_features_clean) - length(valid_features)
                                              # Only show warning if more than 10% of features are missing
                                              if (missing_count > max(1, 0.1 * length(significant_features_clean))) {
                                                showNotification(paste("Warning: Some features in", comparison_name,
                                                                       "were not found in the original data and will be excluded from intersection analysis.",
                                                                       "Missing:", missing_count, "out of", length(significant_features_clean)),
                                                                 type = "warning")
                                              }
                                              significant_features <- valid_features
                                            } else {
                                              significant_features <- significant_features_clean
                                            }
                                          }
                                        }
                                        
                                        # Only add non-empty sets to our analysis
                                        if (length(significant_features) > 0) {
                                          cat("- Found", length(significant_features), "significant features for", comparison_name, "\n")
                                          intersection_sets <- c(intersection_sets, list(unique(significant_features)))
                                          set_names <- c(set_names, comparison_name)
                                        } else {
                                          # If we had features before validation but lost all due to naming mismatches, optionally keep them
                                          # This fallback prevents false negatives blocking the analysis
                                          # Note: we rely on earlier debug to show pre-validation counts
                                          if (exists("significant_features_clean") && length(significant_features_clean) > 0 && length(intersection_sets) < 2) {
                                            showNotification(paste("Relaxed matching used for", comparison_name, "due to name mismatches; including pre-validation features for plotting only."), type = "warning")
                                            cat("- Using pre-validation features as fallback for", comparison_name, " (count:", length(significant_features_clean), ")\n")
                                            intersection_sets <- c(intersection_sets, list(unique(significant_features_clean)))
                                            set_names <- c(set_names, comparison_name)
                                          } else {
                                            cat("- No significant features found for", comparison_name, "\n")
                                            empty_set_names <- c(empty_set_names, comparison_name)
                                          }
                                        }
                                      }
                                    }
                                    
                                    # Show warning about empty sets, but continue with available data
                                    if (length(empty_set_names) > 0) {
                                      showNotification(paste("Some sets have no significant features with current thresholds:",
                                                             paste(empty_set_names, collapse=", "),
                                                             ". Proceeding with available data."),
                                                       type = "warning")
                                    }
                                    
                                    # Check if we have at least 2 non-empty sets to continue
                                    cat("Final summary: Total sets with features =", length(intersection_sets), "\n")
                                    if (length(intersection_sets) >= 1) {
                                      for (i in seq_along(intersection_sets)) {
                                        cat("- Set", i, "(", set_names[i], "):", length(intersection_sets[[i]]), "features\n")
                                      }
                                    }
                                    
                                    if (length(intersection_sets) < 2) {
                                      showNotification("Not enough sets with significant features. Please adjust thresholds.",
                                                       type = "error")
                                      return()
                                    }
                                    
                                    # Store for later use
                                    values$intersection_sets <- intersection_sets
                                    values$intersection_set_names <- set_names
                                    
                                    setProgress(0.7, detail = "Creating visualization")
                                    # Generate the appropriate visualization based on number of sets
                                    if (length(intersection_sets) <= 5) {
                                      # Generate Venn diagram
                                      venn_colors <- c(input$venn_color1, input$venn_color2, input$venn_color3,
                                                       input$venn_color4, input$venn_color5)[1:length(intersection_sets)]
                                      
                                      # Create the Venn diagram
                                      venn_diagram <- VennDiagram::venn.diagram(
                                        x = intersection_sets,
                                        category.names = set_names,
                                        filename = NULL,
                                        fill = venn_colors,
                                        alpha = 0.5,
                                        cex = 1.5,
                                        cat.cex = 0.8,
                                        cat.fontfamily = "Arial",
                                        fontfamily = "Arial",
                                        cat.dist = 0.1,
                                        margin = 0.15
                                      )
                                      
                                      # Store the venn diagram
                                      values$intersection_venn_diagram <- venn_diagram
                                    } else {
                                      # Generate UpSet plot (for more than 5 sets)
                                      
                                      setProgress(0.8, detail = "Creating binary matrix...")
                                      
                                      # Get all unique features across all sets
                                      all_unique_features <- unique(unlist(intersection_sets, use.names = FALSE))
                                      
                                      # Create binary matrix for UpSet plot
                                      binary_matrix <- data.frame(matrix(0, nrow = length(all_unique_features),
                                                                         ncol = length(intersection_sets)))
                                      rownames(binary_matrix) <- all_unique_features
                                      colnames(binary_matrix) <- set_names
                                      
                                      # Fill binary matrix
                                      for (feature in all_unique_features) {
                                        for (i in seq_along(intersection_sets)) {
                                          binary_matrix[feature, i] <- ifelse(feature %in% intersection_sets[[i]], 1, 0)
                                        }
                                      }
                                      
                                      # Store binary matrix for later use
                                      values$intersection_binary_matrix <- binary_matrix
                                      
                                      setProgress(0.85, detail = "Generating UpSet plot...")
                                      
                                      # Generate the UpSet plot directly here
                                      tryCatch({
                                        # Filter based on minimum set size
                                        set_sizes <- colSums(binary_matrix)
                                        min_size <- max(1, input$upset_min_size %||% 3)
                                        sets_to_include <- names(set_sizes)[set_sizes >= min_size]
                                        
                                        if (length(sets_to_include) > 0) {
                                          # Filter the matrix to include only sets meeting the minimum size
                                          filtered_matrix <- binary_matrix[, sets_to_include, drop = FALSE]
                                          
                                          # Create the UpSet plot with current parameters
                                          if (requireNamespace("UpSetR", quietly = TRUE)) {
                                            upset_plot <- UpSetR::upset(filtered_matrix,
                                                                        sets = sets_to_include,
                                                                        order.by = "freq",
                                                                        decreasing = TRUE,
                                                                        show.numbers = "yes",
                                                                        text.scale = input$upset_text_scale %||% 1.3,
                                                                        point.size = 3.5,
                                                                        line.size = 1.5,
                                                                        main.bar.color = input$upset_main_bar %||% "#1f77b4",
                                                                        sets.bar.color = input$upset_sets_bar %||% "#ff7f0e",
                                                                        matrix.color = input$upset_matrix %||% "#2ca02c",
                                                                        nintersects = input$upset_nintersects %||% 30,
                                                                        mb.ratio = c(0.7, 0.3))
                                            
                                            # Store the plot object
                                            values$intersection_plot_obj <- upset_plot
                                            
                                            showNotification("UpSet plot generated successfully!", type = "message")
                                          } else {
                                            showNotification("UpSetR package not available. Please install it.", type = "error")
                                          }
                                        } else {
                                          showNotification("No sets meet the minimum size criteria for UpSet plot", type = "warning")
                                        }
                                      }, error = function(e) {
                                        showNotification(paste("Error generating UpSet plot:", e$message), type = "error")
                                      })
                                    }
                                    
                                    setProgress(0.9, detail = "Calculating intersections")
                                    
                                    # Compute comparison results
                                    comparison_results <- list()
                                    
                                    # Union of all sets
                                    comparison_results[["Union"]] <- Reduce(union, intersection_sets)
                                    
                                    # Overall intersection of all sets
                                    comparison_results[["Intersection_All_Sets"]] <- Reduce(intersect, intersection_sets)
                                    
                                    # Pairwise intersections between sets
                                    for (i in seq_along(intersection_sets)) {
                                      for (j in seq_along(intersection_sets)) {
                                        if (i < j) { # Ensure i < j to avoid duplicates or self-comparison
                                          pairwise_name <- paste("Intersection", set_names[i], "&", set_names[j], sep = "_")
                                          comparison_results[[pairwise_name]] <- intersect(intersection_sets[[i]], intersection_sets[[j]])
                                        }
                                      }
                                    }
                                    
                                    # Unique elements for each set
                                    for (i in seq_along(intersection_sets)) {
                                      # Elements in the current set
                                      current_set <- intersection_sets[[i]]
                                      # Union of all other sets
                                      other_sets <- unlist(intersection_sets[-i], use.names = FALSE)
                                      # Unique elements: in current set but not in any other set
                                      unique_elements <- setdiff(current_set, other_sets)
                                      # Name the result using the set name
                                      comparison_results[[paste0("Unique_", set_names[i])]] <- unique_elements
                                    }
                                    
                                    # Store comparison results
                                    values$intersection_comparison_results <- comparison_results
                                    
                                    # Display comparison results table
                                    output$intersectionResultsTable <- DT::renderDataTable({
                                      req(values$intersection_comparison_results)
                                      
                                      # Transform list to a more tabular format
                                      result_data <- data.frame(
                                        Comparison = character(),
                                        Features = character(),
                                        Count = integer(),
                                        stringsAsFactors = FALSE
                                      )
                                      
                                      for (name in names(values$intersection_comparison_results)) {
                                        features <- values$intersection_comparison_results[[name]]
                                        if (length(features) > 0) {
                                          result_data <- rbind(
                                            result_data,
                                            data.frame(
                                              Comparison = name,
                                              Features = paste(features, collapse = ", "),
                                              Count = length(features),
                                              stringsAsFactors = FALSE
                                            )
                                          )
                                        } else {
                                          result_data <- rbind(
                                            result_data,
                                            data.frame(
                                              Comparison = name,
                                              Features = "None",
                                              Count = 0,
                                              stringsAsFactors = FALSE
                                            )
                                          )
                                        }
                                      }
                                      
                                      DT::datatable(
                                        result_data,
                                        options = list(
                                          pageLength = 15,
                                          scrollX = TRUE,
                                          autoWidth = TRUE
                                        ),
                                        rownames = FALSE
                                      )
                                    })
                                    
                                    # Update intersection info text with info about excluded sets
                                    output$intersectionTypeInfo <- renderText({
                                      num_sets <- length(intersection_sets)
                                      if (num_sets < 2) {
                                        return("<div class='alert alert-warning'>Not enough sets with significant features</div>")
                                      } else if (num_sets <= 5) {
                                        if (length(empty_set_names) > 0) {
                                          return(paste("<div class='alert alert-info'>Displaying Venn diagram with", num_sets,
                                                       "sets. Some sets were excluded due to lack of significant features.</div>"))
                                        } else {
                                          return(paste("<div class='alert alert-info'>Displaying Venn diagram with", num_sets, "sets</div>"))
                                        }
                                      } else {
                                        if (length(empty_set_names) > 0) {
                                          return(paste("<div class='alert alert-info'>Displaying UpSet plot with", num_sets,
                                                       "sets. Some sets were excluded due to lack of significant features.</div>"))
                                        } else {
                                          return(paste("<div class='alert alert-info'>Displaying UpSet plot with", num_sets, "sets</div>"))
                                        }
                                      }
                                    })
                                  })
  })
  
  # Intersection Analysis - Auto-analyze manual file uploads
  observeEvent(input$intersection_file, {
    req(input$intersection_file)
    req(input$intersection_source == "manual")  # Only for manual uploads
    
    # Show progress indicator
    withProgress(message = "Analyzing intersection data...", {
      
      setProgress(0.2, detail = "Reading file")
      
      # Read the Excel file
      tryCatch({
        file_data <- readxl::read_excel(input$intersection_file$datapath)
        
        # Check if file format is valid
        if (ncol(file_data) < 2) {
          showNotification("File must contain at least two columns (sets)", type = "error")
          return(NULL)
        }
        
        # Process each column as a set
        intersection_sets <- list()
        set_names <- colnames(file_data)
        
        setProgress(0.4, detail = "Processing sets")
        
        # Extract features from each column/set
        for (i in 1:ncol(file_data)) {
          col_values <- file_data[[i]]
          # Remove NA and empty values
          valid_values <- col_values[!is.na(col_values) & col_values != ""]
          intersection_sets[[i]] <- as.character(valid_values)
        }
        
        # Check if any sets are empty
        empty_sets <- sapply(intersection_sets, length) == 0
        if (any(empty_sets)) {
          showNotification("Some columns in your file have no valid data", type = "warning")
          # Remove empty sets
          intersection_sets <- intersection_sets[!empty_sets]
          set_names <- set_names[!empty_sets]
        }
        
        # Ensure we have at least 2 non-empty sets
        if (length(intersection_sets) < 2) {
          showNotification("At least two columns with data are required", type = "error")
          return(NULL)
        }
        
        # Store for later use
        values$intersection_sets <- intersection_sets
        values$intersection_set_names <- set_names
        values$manual_sets_count <- length(intersection_sets) # Store set count for manual mode
        
        setProgress(0.6, detail = "Generating visualization")
        
        # Generate the appropriate visualization based on number of sets
        if (length(intersection_sets) <= 5) {
          # Ensure list names use real comparison names so categories are labeled correctly
          names(intersection_sets) <- set_names
          
          if ((input$venn_engine %||% "ggVennDiagram") == "ggVennDiagram") {
            if (requireNamespace("ggVennDiagram", quietly = TRUE)) {
              count_size <- input$venn_count_size %||% 16
              label_size <- input$venn_label_size %||% 12
              venn_plot <- ggVennDiagram::ggVennDiagram(intersection_sets, label = "count", label_size = count_size * 0.35,
                                                        label_alpha = 0, category.names = set_names) +
                ggplot2::scale_fill_gradient(low = "#F7FBFF", high = "#6BAED6") +
                ggplot2::theme_void() +
                ggplot2::theme(
                  legend.position = "none",
                  text = ggplot2::element_text(size = label_size, face = "bold"),
                  plot.margin = ggplot2::margin(20, 40, 20, 40, "pt")
                ) +
                ggplot2::scale_x_continuous(expand = ggplot2::expansion(mult = 0.2)) +
                ggplot2::scale_y_continuous(expand = ggplot2::expansion(mult = 0.2))
              
              values$intersection_venn_plot <- venn_plot
            } else {
              showNotification("ggVennDiagram not installed; falling back to VennDiagram.", type = "warning")
              venn_colors <- c(input$venn_color1, input$venn_color2, input$venn_color3,
                               input$venn_color4, input$venn_color5)[1:length(intersection_sets)]
              cex_val <- (input$venn_count_size %||% 16) / 10
              cat_cex_val <- (input$venn_label_size %||% 12) / 10
              venn_diagram <- VennDiagram::venn.diagram(
                x = intersection_sets,
                category.names = set_names,
                filename = NULL,
                fill = venn_colors,
                alpha = 0.5,
                cex = cex_val,
                cat.cex = cat_cex_val,
                cat.fontfamily = "Arial",
                cat.fontface = "bold",  # Bold category names
                fontfamily = "Arial",
                fontface = "bold",     # Bold count numbers
                cat.dist = 0.1,
                margin = 0.15,         # Increased margin for longer names
                output = TRUE
              )
              values$intersection_venn_diagram <- venn_diagram
            }
          } else {
            # Explicit VennDiagram selection
            venn_colors <- c(input$venn_color1, input$venn_color2, input$venn_color3,
                             input$venn_color4, input$venn_color5)[1:length(intersection_sets)]
            cex_val <- (input$venn_count_size %||% 16) / 10
            cat_cex_val <- (input$venn_label_size %||% 12) / 10
            venn_diagram <- VennDiagram::venn.diagram(
              x = intersection_sets,
              category.names = set_names,
              filename = NULL,
              fill = venn_colors,
              alpha = 0.5,
              cex = cex_val,
              cat.cex = cat_cex_val,
              cat.fontfamily = "Arial",
              fontfamily = "Arial",
              cat.dist = 0.1,
              margin = 0.1,
              output = TRUE
            )
            values$intersection_venn_diagram <- venn_diagram
          }
          
        } else {
          # Generate UpSet plot (for more than 5 sets)
          setProgress(0.8, detail = "Creating binary matrix...")
          
          # Get all unique features across all sets
          all_unique_features <- unique(unlist(intersection_sets, use.names = FALSE))
          
          # Create binary matrix for UpSet plot
          binary_matrix <- data.frame(matrix(0, nrow = length(all_unique_features),
                                             ncol = length(intersection_sets)))
          rownames(binary_matrix) <- all_unique_features
          colnames(binary_matrix) <- set_names
          
          # Fill binary matrix
          for (feature in all_unique_features) {
            for (i in seq_along(intersection_sets)) {
              binary_matrix[feature, i] <- ifelse(feature %in% intersection_sets[[i]], 1, 0)
            }
          }
          
          # Store binary matrix for later use
          values$intersection_binary_matrix <- binary_matrix
        }
        
        # Update the info display
        output$intersectionTypeInfo <- renderText({
          if(input$intersection_source == "manual") {
            num_sets <- values$manual_sets_count
            if(num_sets <= 5) {
              return(paste("<div class='alert alert-info'>Displaying Venn diagram with", num_sets, "sets from uploaded file</div>"))
            } else {
              return(paste("<div class='alert alert-info'>Displaying UpSet plot with", num_sets, "sets from uploaded file</div>"))
            }
          } else {
            num_sets <- length(input$intersection_sets)
            if(num_sets == 0) {
              return("<div class='alert alert-warning'>Please select at least 2 comparisons</div>")
            } else if(num_sets <= 5) {
              return(paste("<div class='alert alert-info'>Displaying Venn diagram with", num_sets, "sets</div>"))
            } else {
              return(paste("<div class='alert alert-info'>Displaying UpSet plot with", num_sets, "sets</div>"))
            }
          }
        })
        
        setProgress(0.9, detail = "Calculating intersections")
        
        # Calculate and display intersections
        comparison_results <- list()
        
        # Union of all sets
        comparison_results[["Union"]] <- Reduce(union, intersection_sets)
        
        # Overall intersection of all sets
        comparison_results[["Intersection_All_Sets"]] <- Reduce(intersect, intersection_sets)
        
        # Pairwise intersections between sets
        for (i in seq_along(intersection_sets)) {
          for (j in seq_along(intersection_sets)) {
            if (i < j) { # Ensure i < j to avoid duplicates or self-comparison
              pairwise_name <- paste("Intersection", set_names[i], "&", set_names[j], sep = "_")
              comparison_results[[pairwise_name]] <- intersect(intersection_sets[[i]], intersection_sets[[j]])
            }
          }
        }
        
        # Unique elements for each set - make sure this is always calculated
        for (i in seq_along(intersection_sets)) {
          # Elements in the current set
          current_set <- intersection_sets[[i]]
          # Union of all other sets
          other_sets <- unlist(intersection_sets[-i], use.names = FALSE)
          # Unique elements: in current set but not in any other set
          unique_elements <- setdiff(current_set, other_sets)
          # Name the result using the set name
          comparison_results[[paste0("Unique_", set_names[i])]] <- unique_elements
        }
        
        # For UpSet plots with many sets, add additional set-specific intersections
        if (length(intersection_sets) > 5) {
          # Add selected multi-set intersections (e.g., A n B n C but not D)
          # This helps with understanding complex set relationships
          if (length(intersection_sets) <= 7) {  # Only do this for manageable number of sets
            # Get all 3-way intersections for sets up to 7
            for (i in 1:(length(intersection_sets)-2)) {
              for (j in (i+1):(length(intersection_sets)-1)) {
                for (k in (j+1):length(intersection_sets)) {
                  int_name <- paste("Intersection", set_names[i], "&", set_names[j], "&", set_names[k], sep = "_")
                  three_way_int <- Reduce(intersect, intersection_sets[c(i, j, k)])
                  comparison_results[[int_name]] <- three_way_int
                }
              }
            }
          }
        }
        
        # Store comparison results
        values$intersection_comparison_results <- comparison_results
        
        showNotification("Intersection analysis completed!", type = "message")
        
      }, error = function(e) {
        showNotification(paste("Error analyzing file:", e$message), type = "error")
      })
    })
  })
  
  # Reactive expression to collect all paste set data
  intersection_paste_data <- reactive({
    req(input$intersection_source == "manual")
    req(input$intersection_manual_input_type == "paste")
    
    num_sets <- values$intersection_paste_sets_count
    
    # Collect data from all sets
    sets_data <- list()
    set_names <- character()
    
    for(i in 1:num_sets) {
      name_input <- input[[paste0("intersection_set_name_", i)]]
      features_input <- input[[paste0("intersection_set_features_", i)]]
      
      # Skip if inputs are not yet available
      if(is.null(name_input) || is.null(features_input)) return(NULL)
      
      # Skip empty sets
      if(trimws(name_input) == "" || trimws(features_input) == "") next
      
      # Process features (split by newlines, trim, remove empty)
      features <- strsplit(features_input, "\n")[[1]]
      features <- trimws(features)
      features <- features[features != ""]
      
      if(length(features) > 0) {
        sets_data[[length(sets_data) + 1]] <- features
        set_names <- c(set_names, trimws(name_input))
      }
    }
    
    if(length(sets_data) < 2) return(NULL)
    
    list(sets = sets_data, names = set_names)
  })
  
  # Handle pasted intersection data
  observeEvent(intersection_paste_data(), {
