  # Initialize plot cache for intersection analysis
  intersection_plot_cache <- reactiveVal(list())
  
  # Reactive plot rendering for intersection analysis with caching
  observeEvent({
    # Create a reactive list of all inputs that should trigger plot regeneration
    list(
      values$intersection_sets,
      values$intersection_set_names,
      input$venn_engine,
      input$venn_count_size,
      input$venn_label_size,
      input$intersection_include_up,
      input$intersection_include_down,
      input$intersection_pval_cutoff,
      input$intersection_fc_cutoff,
      input$intersection_fdr_cutoff,
      input$upset_min_size,
      input$upset_nintersects,
      input$upset_text_scale,
      input$upset_label_size,
      input$upset_main_bar,
      input$upset_sets_bar,
      input$upset_matrix,
      input$venn_color1,
      input$venn_color2,
      input$venn_color3,
      input$venn_color4,
      input$venn_color5,
      input$bootstrap_enabled,
      input$intersection_source,
      input$intersection_feature_source
    )
  }, {
    # Only proceed if we have intersection data
    if (is.null(values$intersection_sets) || is.null(values$intersection_set_names)) {
      return()
    }
    
    # Create cache key based on current settings and data
    if (!requireNamespace("digest", quietly = TRUE)) {
      install.packages("digest")
    }
    data_hash <- digest::digest(list(values$intersection_sets, values$intersection_set_names), algo = "md5")
    cache_key <- paste(
      data_hash,
      length(values$intersection_sets),
      input$venn_engine %||% "ggVennDiagram",
      input$venn_count_size %||% 16,
      input$venn_label_size %||% 12,
      input$intersection_include_up %||% TRUE,
      input$intersection_include_down %||% TRUE,
      input$intersection_pval_cutoff %||% 0.05,
      input$intersection_fc_cutoff %||% 1,
      input$intersection_fdr_cutoff %||% 0.1,
      input$upset_min_size %||% 3,
      input$upset_nintersects %||% 30,
      input$upset_text_scale %||% 1.3,
      input$upset_label_size %||% 12,
      input$upset_main_bar %||% "#1f77b4",
      input$upset_sets_bar %||% "#ff7f0e",
      input$upset_matrix %||% "#2ca02c",
      input$venn_color1 %||% "#FF6B6B",
      input$venn_color2 %||% "#4ECDC4",
      input$venn_color3 %||% "#45B7D1",
      input$venn_color4 %||% "#96CEB4",
      input$venn_color5 %||% "#FFEAA7",
      input$bootstrap_enabled %||% "no",
      input$intersection_source %||% "pairwise",
      input$intersection_feature_source %||% "all",
      sep = "_"
    )
    
    # Check if plot exists in cache
    current_cache <- intersection_plot_cache()
    if (cache_key %in% names(current_cache)) {
      # Use cached plot
      if (length(values$intersection_sets) <= 5) {
        cached_obj <- current_cache[[cache_key]]
        # Clear both then set based on type
        values$intersection_venn_plot <- NULL
        values$intersection_venn_diagram <- NULL
        if (inherits(cached_obj, "ggplot")) {
          values$intersection_venn_plot <- cached_obj
        } else {
          values$intersection_venn_diagram <- cached_obj
        }
      } else {
        values$intersection_plot_obj <- current_cache[[cache_key]]
      }
      # Show notification that cached plot is being used
      showNotification("Using cached plot (no recalculation needed)", type = "message", duration = 2)
      return()
    }
    
    # Limit cache size to prevent memory issues (keep last 10 plots)
    if (length(current_cache) >= 10) {
      # Remove oldest cache entry
      current_cache <- current_cache[-1]
    }
    
    # Generate new plot if not cached
    intersection_sets <- values$intersection_sets
    set_names <- values$intersection_set_names
    
    if (length(intersection_sets) <= 5) {
      # Venn diagram for 5 or fewer sets
      # Clear prior objects when regenerating
      values$intersection_venn_plot <- NULL
      values$intersection_venn_diagram <- NULL
      names(intersection_sets) <- set_names
      if ((input$venn_engine %||% "ggVennDiagram") == "ggVennDiagram") {
        if (requireNamespace("ggVennDiagram", quietly = TRUE)) {
          count_size <- input$venn_count_size %||% 16
          label_size <- input$venn_label_size %||% 12
          venn_plot <- ggVennDiagram::ggVennDiagram(intersection_sets, label = "count", label_size = count_size * 0.35,
                                                    label_alpha = 0, category.names = set_names)
          
          # Apply custom styling to the Venn diagram
          venn_plot <- venn_plot +
            ggplot2::scale_fill_gradient(low = "#F7FBFF", high = "#6BAED6") +
            ggplot2::theme_void() +
            ggplot2::theme(
              legend.position = "none",
              plot.margin = ggplot2::margin(20, 40, 20, 40, "pt")  # top, right, bottom, left
            )
          
          # Modify the category (set) label sizes by updating the geom_text layers
          for (i in seq_along(venn_plot$layers)) {
            if (inherits(venn_plot$layers[[i]]$geom, "GeomText")) {
              venn_plot$layers[[i]]$aes_params$size <- label_size / 3  # Convert to ggplot2 size units
            }
          }
          
          venn_plot <- venn_plot +
            # Expand plot margins to prevent label cutoff
            ggplot2::scale_x_continuous(expand = ggplot2::expansion(mult = 0.2)) +
            ggplot2::scale_y_continuous(expand = ggplot2::expansion(mult = 0.2))
          
          current_cache[[cache_key]] <- venn_plot
          intersection_plot_cache(current_cache)
          values$intersection_venn_plot <- venn_plot
          showNotification("Venn diagram generated and cached", type = "message", duration = 2)
        } else {
          showNotification("ggVennDiagram not installed; falling back to VennDiagram.", type = "warning")
          venn_colors <- c(input$venn_color1 %||% "#FF6B6B",
                           input$venn_color2 %||% "#4ECDC4",
                           input$venn_color3 %||% "#45B7D1",
                           input$venn_color4 %||% "#96CEB4",
                           input$venn_color5 %||% "#FFEAA7")[1:length(intersection_sets)]
          cex_val <- (input$venn_count_size %||% 16) / 10
          cat_cex_val <- (input$venn_label_size %||% 12) / 10
          venn_diagram <- VennDiagram::venn.diagram(
            x = intersection_sets,
            category.names = set_names,
            filename = NULL,
            fill = venn_colors,
            alpha = 0.5,
            cex = cex_val,
            cat.cex = cat_cex_val,
            cat.fontfamily = "Arial",
            cat.fontface = "bold",  # Bold category names
            fontfamily = "Arial",
            fontface = "bold",     # Bold count numbers
            cat.dist = 0.1,
            margin = 0.15,         # Increased margin for longer names
            output = TRUE
          )
          current_cache[[cache_key]] <- venn_diagram
          intersection_plot_cache(current_cache)
          values$intersection_venn_diagram <- venn_diagram
          showNotification("Venn diagram generated and cached (fallback)", type = "message", duration = 2)
        }
      } else {
        venn_colors <- c(input$venn_color1 %||% "#FF6B6B",
                         input$venn_color2 %||% "#4ECDC4",
                         input$venn_color3 %||% "#45B7D1",
                         input$venn_color4 %||% "#96CEB4",
                         input$venn_color5 %||% "#FFEAA7")[1:length(intersection_sets)]
        cex_val <- (input$venn_count_size %||% 16) / 10
        cat_cex_val <- (input$venn_label_size %||% 12) / 10
        venn_diagram <- VennDiagram::venn.diagram(
          x = intersection_sets,
          category.names = set_names,
          filename = NULL,
          fill = venn_colors,
          alpha = 0.5,
          cex = cex_val,
          cat.cex = cat_cex_val,
          cat.fontfamily = "Arial",
          cat.fontface = "bold",  # Bold category names
          fontfamily = "Arial",
          fontface = "bold",     # Bold count numbers
          cat.dist = 0.1,
          margin = 0.15,         # Increased margin for longer names
          output = TRUE
        )
        current_cache[[cache_key]] <- venn_diagram
        intersection_plot_cache(current_cache)
        values$intersection_venn_diagram <- venn_diagram
        showNotification("Venn diagram generated and cached (VennDiagram)", type = "message", duration = 2)
      }
      
    } else {
      # UpSet plot for more than 5 sets
      # Get all unique features across all sets
      all_unique_features <- unique(unlist(intersection_sets, use.names = FALSE))
      
      # Create binary matrix for UpSet plot
      binary_matrix <- data.frame(matrix(0, nrow = length(all_unique_features),
                                         ncol = length(intersection_sets)))
      rownames(binary_matrix) <- all_unique_features
      colnames(binary_matrix) <- set_names
      
      # Fill binary matrix
      for (feature in all_unique_features) {
        for (i in seq_along(intersection_sets)) {
          binary_matrix[feature, i] <- ifelse(feature %in% intersection_sets[[i]], 1, 0)
        }
      }
      
      # Store binary matrix for later use
      values$intersection_binary_matrix <- binary_matrix
      
      # Filter based on minimum set size
      set_sizes <- colSums(binary_matrix)
      sets_to_include <- names(set_sizes)[set_sizes >= (input$upset_min_size %||% 3)]
      
      if (length(sets_to_include) > 0) {
        # Filter the matrix to include only sets meeting the minimum size
        filtered_matrix <- binary_matrix[, sets_to_include, drop = FALSE]
        
        # Create the UpSet plot with current parameters
        upset_plot <- UpSetR::upset(filtered_matrix,
                                    sets = sets_to_include,
                                    order.by = "freq",
                                    decreasing = TRUE,
                                    show.numbers = "yes",
                                    text.scale = input$upset_text_scale %||% 1.3,
                                    point.size = 3.5,
                                    line.size = 1.5,
                                    main.bar.color = input$upset_main_bar %||% "#1f77b4",
                                    sets.bar.color = input$upset_sets_bar %||% "#ff7f0e",
                                    matrix.color = input$upset_matrix %||% "#2ca02c",
                                    nintersects = input$upset_nintersects %||% 30,
                                    mb.ratio = c(0.7, 0.3))
        
        # Add subtitle for bootstrap and feature set usage
        subtitle_parts <- character()
        
        if ((input$bootstrap_enabled %||% "no") == "yes") {
          subtitle_parts <- c(subtitle_parts, "Using bootstrap statistics")
        }
        
        if ((input$intersection_source %||% "pairwise") == "pairwise" &&
            !is.null(input$intersection_feature_source) &&
            (input$intersection_feature_source %||% "all") != "all") {
          feature_set_text <- switch(input$intersection_feature_source,
                                     "pca" = "PCA Features",
                                     "ml" = "ML Features",
                                     "All Features")
          subtitle_parts <- c(subtitle_parts, paste("Feature Set:", feature_set_text))
        }
        
        if (length(subtitle_parts) > 0) {
          upset_plot <- upset_plot +
            labs(subtitle = paste(subtitle_parts, collapse = " | ")) +
            theme(plot.subtitle = element_text(face = "italic", hjust = 0.5))
        }
        
        # Cache and store the plot
        current_cache[[cache_key]] <- upset_plot
        intersection_plot_cache(current_cache)
        values$intersection_plot_obj <- upset_plot
        
        # Notify user that plot was generated and cached
        showNotification("UpSet plot generated and cached", type = "message", duration = 2)
      }
    }
  }, ignoreNULL = FALSE, ignoreInit = FALSE)
  
  # Reactive Venn plot rendering
  output$vennPlot <- renderPlot({ 
    # Add explicit reactive dependencies to trigger on filter changes
    input$venn_color1
    input$venn_color2
    input$venn_color3
    input$venn_color4
    input$venn_color5
    input$bootstrap_enabled
    input$venn_engine
    input$venn_count_size
    input$venn_label_size
    
    # Add dependencies for manual uploads
    values$intersection_comparison_results
    values$manual_sets_count
    
    # Prefer ggVennDiagram plot if available
    if (!is.null(values$intersection_venn_plot)) {
      label_size <- input$venn_label_size %||% 12
      p <- values$intersection_venn_plot +
        ggplot2::theme(
          text = ggplot2::element_text(size = label_size, face = "bold"),
          plot.margin = ggplot2::margin(20, 40, 20, 40, "pt")
        )
      if ((input$bootstrap_enabled %||% "no") == "yes") {
        p <- p + ggplot2::labs(subtitle = "Using bootstrap statistics") +
          ggplot2::theme(plot.subtitle = ggplot2::element_text(face = "italic", hjust = 0.5))
      }
      return(p)
    }
    
    # Fallback to grid grob
    req(values$intersection_venn_diagram)
    grid::grid.newpage()
    grid::grid.draw(values$intersection_venn_diagram)
    if ((input$bootstrap_enabled %||% "no") == "yes") {
      grid::grid.text("Using bootstrap statistics", x = 0.5, y = 0.02,
                      gp = grid::gpar(fontface = "italic", fontsize = 10))
    }
  })
  
  # Reactive UpSet plot rendering
  output$upsetPlot <- renderPlot({ 
    # Add explicit reactive dependencies to trigger on filter changes
    input$upset_min_size
    input$upset_nintersects
    input$upset_text_scale
    input$upset_label_size
    input$upset_main_bar
    input$upset_sets_bar
    input$upset_matrix
    
    # Add dependencies for manual uploads
    values$intersection_comparison_results
    values$manual_sets_count
    
    req(values$intersection_binary_matrix)
    
    # Filter the binary matrix based on set size
    binary_matrix <- values$intersection_binary_matrix
    set_sizes <- colSums(binary_matrix)
    sets_to_include <- names(set_sizes)[set_sizes >= (input$upset_min_size %||% 3)]
    
    # If no sets meet the minimum size criteria, show a message
    if (length(sets_to_include) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "No sets meet the minimum size criteria",
                        size = 8) +
               theme_void())
    }
    
    # Return the cached/stored plot object
    if (!is.null(values$intersection_plot_obj)) {
      return(values$intersection_plot_obj)
    } else {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Plot not available",
                        size = 8) +
               theme_void())
    }
  })
  
  # Download intersection plot
  output$downloadIntersectionPlotBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      if(length(input$intersection_sets) <= 5) {
        paste0("Venn_Diagram_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else {
        paste0("UpSet_Plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      }
    },
    content = function(file) {
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      format <- get_safe_global_image_format()
      
      if(length(input$intersection_sets) <= 5) {
        # Save Venn diagram
        if (!is.null(values$intersection_venn_plot)) {
          label_size <- input$venn_label_size %||% 12
          ggsave(file,
                 plot = values$intersection_venn_plot +
                   ggplot2::theme(
                     text = ggplot2::element_text(size = label_size, face = "bold"),
                     plot.margin = ggplot2::margin(20, 40, 20, 40, "pt")
                   ),
                 width = 8, height = 8, units = "in", dpi = dpi, device = resolve_ggsave_device(format))
        } else {
          req(values$intersection_venn_diagram)
          if (format == "png") {
            png(file, width = 8, height = 8, units = "in", res = dpi)
            grid::grid.draw(values$intersection_venn_diagram)
            dev.off()
          } else if (format == "svg") {
            svg(file, width = 8, height = 8)
            grid::grid.draw(values$intersection_venn_diagram)
            dev.off()
          } else {
            # Fallback to PNG if format is invalid
            png(file, width = 8, height = 8, units = "in", res = dpi)
            grid::grid.draw(values$intersection_venn_diagram)
            dev.off()
          }
        }
      } else {
        # Save UpSet plot
        req(values$intersection_plot_obj)
        if (format == "png") {
          png(file, width = 12, height = 8, units = "in", res = dpi)
          print(values$intersection_plot_obj)
          dev.off()
        } else if (format == "svg") {
          svg(file, width = 12, height = 8)
          print(values$intersection_plot_obj)
          dev.off()
        } else {
          # Fallback to PNG if format is invalid
          png(file, width = 12, height = 8, units = "in", res = dpi)
          print(values$intersection_plot_obj)
          dev.off()
        }
      }
    }
  )
  
  # Display comparison results table - updated for consistent visualization of unique elements
  output$intersectionResultsTable <- DT::renderDataTable({
    req(values$intersection_comparison_results)
    
    # Transform list to a more tabular format
    result_data <- data.frame(
      Comparison = character(),
      Features = character(),
      Count = integer(),
      stringsAsFactors = FALSE
    )
    
    # Process results in a specific order for better organization
    
    # First add Union and full intersection
    base_comparisons <- c("Union", "Intersection_All_Sets")
    for (name in base_comparisons) {
      if (name %in% names(values$intersection_comparison_results)) {
        features <- values$intersection_comparison_results[[name]]
        result_data <- rbind(
          result_data,
          data.frame(
            Comparison = name,
            Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
            Count = length(features),
            stringsAsFactors = FALSE
          )
        )
      }
    }
    
    # Then add unique elements for each set
    unique_comparisons <- grep("^Unique_", names(values$intersection_comparison_results), value = TRUE)
    for (name in unique_comparisons) {
      features <- values$intersection_comparison_results[[name]]
      result_data <- rbind(
        result_data,
        data.frame(
          Comparison = name,
          Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
          Count = length(features),
          stringsAsFactors = FALSE
        )
      )
    }
    
    # Finally add all other intersections
    other_comparisons <- setdiff(names(values$intersection_comparison_results),
                                 c(base_comparisons, unique_comparisons))
    for (name in other_comparisons) {
      features <- values$intersection_comparison_results[[name]]
      result_data <- rbind(
        result_data,
        data.frame(
          Comparison = name,
          Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
          Count = length(features),
          stringsAsFactors = FALSE
        )
      )
    }
    
    DT::datatable(
      result_data,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        autoWidth = TRUE
      ),
      rownames = FALSE
    )
  })
  
  # Download intersection data
  output$downloadIntersectionDataBtn <- downloadHandler(
    filename = function() {
      paste0("Intersection_Analysis_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(values$intersection_comparison_results)
      
      # Create workbook
      wb <- createWorkbook()
      
      # Add sheet for intersection results
      addWorksheet(wb, "Intersection Results")
      
      # Transform list to a more tabular format
      result_data <- data.frame(
        Comparison = character(),
        Features = character(),
        Count = integer(),
        stringsAsFactors = FALSE
      )
      
      # Process results in a specific order for better organization
      # First add Union and full intersection
      base_comparisons <- c("Union", "Intersection_All_Sets")
      for (name in base_comparisons) {
        if (name %in% names(values$intersection_comparison_results)) {
          features <- values$intersection_comparison_results[[name]]
          result_data <- rbind(
            result_data,
            data.frame(
              Comparison = name,
              Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
              Count = length(features),
              stringsAsFactors = FALSE
            )
          )
        }
      }
      
      # Then add unique elements for each set
      unique_comparisons <- grep("^Unique_", names(values$intersection_comparison_results), value = TRUE)
      for (name in unique_comparisons) {
        features <- values$intersection_comparison_results[[name]]
        result_data <- rbind(
          result_data,
          data.frame(
            Comparison = name,
            Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
            Count = length(features),
            stringsAsFactors = FALSE
          )
        )
      }
      
      # Finally add all other intersections
      other_comparisons <- setdiff(names(values$intersection_comparison_results),
                                   c(base_comparisons, unique_comparisons))
      for (name in other_comparisons) {
        features <- values$intersection_comparison_results[[name]]
        result_data <- rbind(
          result_data,
          data.frame(
            Comparison = name,
            Features = ifelse(length(features) > 0, paste(features, collapse = ", "), "None"),
            Count = length(features),
            stringsAsFactors = FALSE
          )
        )
      }
      
      # Write data to workbook
      writeData(wb, "Intersection Results", result_data)
      
      # Add parameters sheet
      addWorksheet(wb, "Parameters")
      if (input$intersection_source == "pairwise") {
        param_data <- data.frame(
          Parameter = c("Data Source", "Visualization Type", "Number of Sets",
                        "P-value Cutoff", "Log2FC Cutoff",
                        "Include Up-regulated", "Include Down-regulated",
                        "Bootstrap Used", "Analysis Date"),
          Value = c(
            "Pairwise Comparisons",
            ifelse(length(values$intersection_set_names) <= 5, "Venn Diagram", "UpSet Plot"),
            length(values$intersection_set_names),
            input$intersection_pval_cutoff,
            input$intersection_fc_cutoff,
            input$intersection_include_up,
            input$intersection_include_down,
            input$bootstrap_enabled == "yes",
            format(Sys.time(), "%Y-%m-%d %H:%M:%S")
          ),
          stringsAsFactors = FALSE
        )
      } else {
        param_data <- data.frame(
          Parameter = c("Data Source", "Visualization Type", "Number of Sets",
                        "Analysis Date"),
          Value = c(
            "Manual Upload",
            ifelse(values$manual_sets_count <= 5, "Venn Diagram", "UpSet Plot"),
            values$manual_sets_count,
            format(Sys.time(), "%Y-%m-%d %H:%M:%S")
          ),
          stringsAsFactors = FALSE
        )
      }
      
      writeData(wb, "Parameters", param_data)
      
      # Save workbook
      saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  # Generate Raw Data Table with priority loading
  output$rawDataTable <- DT::renderDataTable({
    req(values$original_unfiltered_data)
    
    raw_df <- values$original_unfiltered_data
    
    # Add ID column if available and different from feature names
    if (!is.null(values$metabolomics_id_columns) &&
        nrow(values$metabolomics_id_columns) == nrow(raw_df)) {
      # For metabolomics data, add individual ID columns
      raw_df <- data.frame(
        Feature = raw_df[[1]],
        values$metabolomics_id_columns,
        raw_df[, -1, drop = FALSE],
        check.names = FALSE,
        stringsAsFactors = FALSE
      )
      # Adjust sample column start to account for ID columns
      sample_col_start <- 1 + ncol(values$metabolomics_id_columns) + 1
    } else if (!is.null(values$accession_ids) &&
        length(values$accession_ids) == nrow(raw_df) &&
        !is.null(values$accession_id_column) &&
        (is.numeric(values$accession_id_column) && all(values$accession_id_column > 0))) {
      # Insert IDs as second column (renamed to support various ID types: accession, glycan, etc.)
      raw_df <- data.frame(
        Feature = raw_df[[1]],
        ID = values$accession_ids,
        raw_df[, -1, drop = FALSE],
        check.names = FALSE,
        stringsAsFactors = FALSE
      )
      sample_col_start <- 3
    } else {
      sample_col_start <- 2
    }
    if(ncol(raw_df) >= sample_col_start) {
      colnames(raw_df)[sample_col_start:ncol(raw_df)] <- get_corrected_column_names(colnames(raw_df)[sample_col_start:ncol(raw_df)])
    }
    
    # Fast rendering options for large datasets
    DT::datatable(
      raw_df,
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        dom = 'tip',
        deferRender = TRUE,  # Fast rendering for large datasets
        processing = FALSE,  # Disable processing indicator for speed
        searchHighlight = FALSE  # Disable search highlighting for performance
      ),
      rownames = FALSE
    )
  })
  
  # Force raw data table to update when data is loaded (e.g., from save/load)
  observe({
    # Monitor for data loading (when original_unfiltered_data changes)
    values$original_unfiltered_data
    
    # Use a proxy to update the table if it exists
    if (!is.null(values$original_unfiltered_data)) {
      tryCatch({
        proxy <- DT::dataTableProxy("rawDataTable")
        # Invalidate to force re-render
        DT::reloadData(proxy, resetPaging = TRUE)
      }, error = function(e) {
        # If proxy update fails, it means table hasn't been rendered yet, which is fine
        NULL
      })
    }
  })
  
  # Download Example Data File
  output$download_example_data <- downloadHandler(
    filename = function() {
      "Time_Series_Test_Data_500_Features.xlsx"
    },
    content = function(file) {
      # Copy the example data file from sample_data folder
      source_file <- "sample_data/Time_Series_Test_Data_500_Features.xlsx"
      if (file.exists(source_file)) {
        file.copy(source_file, file)
      } else {
        showNotification("Example data file not found. Please contact support.", type = "error")
      }
    }
  )
  
  # Download Batch Metadata Example File
  output$download_batch_metadata <- downloadHandler(
    filename = function() {
      "Batch_Metadata_Example.xlsx"
    },
    content = function(file) {
      # Copy the batch metadata example file from sample_data folder
      source_file <- "sample_data/Batch_Metadata_Example.xlsx"
      if (file.exists(source_file)) {
        file.copy(source_file, file)
      } else {
        showNotification("Batch metadata example file not found. Please contact support.", type = "error")
      }
    }
  )
  
  # Download Results Button - downloadNormalizedBtn handler
  output$downloadNormalizedBtn <- downloadHandler(
    filename = function() {
      paste0("Normalized_Data_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(values$normalized_data, values$cleaned_molecules)
      
      # Create workbook
      wb <- createWorkbook()
      addWorksheet(wb, "Normalized Data")
      
      # Prepare data for export - include ID column if available
      if (!is.null(values$metabolomics_id_columns) &&
          nrow(values$metabolomics_id_columns) == nrow(values$normalized_data)) {
        # For metabolomics data, include individual ID columns
        export_data <- data.frame(
          Feature = values$cleaned_molecules,
          values$metabolomics_id_columns,
          values$normalized_data,
          check.names = FALSE,
          stringsAsFactors = FALSE
        )
      } else if (!is.null(values$accession_ids) &&
          length(values$accession_ids) == length(values$cleaned_molecules) &&
          !is.null(values$accession_id_column) &&
          (is.numeric(values$accession_id_column) && all(values$accession_id_column > 0))) {
        export_data <- data.frame(
          Feature = values$cleaned_molecules,
          ID = values$accession_ids,
          values$normalized_data,
          check.names = FALSE,
          stringsAsFactors = FALSE
        )
      } else {
        export_data <- cbind(Feature = values$cleaned_molecules, values$normalized_data)
      }
      
      # Write data to workbook
      writeData(wb, "Normalized Data", export_data)
      
      # Add statistical analysis worksheet if we have group data
      if (!is.null(values$unique_groups) && length(values$unique_groups) >= 2) {
        addWorksheet(wb, "Statistical Analysis")
        
        # Use values$stat_results directly to ensure all statistical results are included
        if (!is.null(values$stat_results)) {
          writeData(wb, "Statistical Analysis", values$stat_results)
          
          # Add method-specific parameter sheets based on the statistical method used
          if (input$sig_method == "rots") {
            # Add a metadata sheet with ROTS parameters
            addWorksheet(wb, "ROTS Parameters")
            rots_mode <- input$rots_mode %||% "standard"

            if (rots_mode == "lmrots") {
              method_label <- "Linear Model-based ROTS (lmROTS)"
              export_B <- ifelse(!is.null(input$lmrots_B) && !is.na(input$lmrots_B), input$lmrots_B, 100)
              export_K <- ifelse(!is.null(input$lmrots_K) && !is.na(input$lmrots_K), input$lmrots_K, "Auto")
              export_seed <- ifelse(!is.null(input$lmrots_seed) && !is.na(input$lmrots_seed), input$lmrots_seed, "Auto")
              export_ref_var <- ifelse(!is.null(input$lmrots_reference_var) && nzchar(input$lmrots_reference_var),
                                       input$lmrots_reference_var, "Auto")
              export_ref_level <- ifelse(!is.null(input$lmrots_reference_level) && nzchar(input$lmrots_reference_level),
                                         input$lmrots_reference_level, "Auto")
            } else if (rots_mode == "lmerots") {
              method_label <- "Linear Mixed-Effects ROTS (lmeROTS)"
              export_B <- ifelse(!is.null(input$lmerots_B) && !is.na(input$lmerots_B), input$lmerots_B, 100)
              export_K <- ifelse(!is.null(input$lmerots_K) && !is.na(input$lmerots_K), input$lmerots_K, "Auto")
              export_seed <- ifelse(!is.null(input$lmerots_seed) && !is.na(input$lmerots_seed), input$lmerots_seed, "Auto")
              export_ref_var <- ifelse(!is.null(input$lmerots_reference_var) && nzchar(input$lmerots_reference_var),
                                       input$lmerots_reference_var, "Auto")
              export_ref_level <- ifelse(!is.null(input$lmerots_reference_level) && nzchar(input$lmerots_reference_level),
                                         input$lmerots_reference_level, "Auto")
            } else {
              method_label <- "Reproducibility-Optimized Test Statistic (ROTS)"
              export_B <- ifelse(!is.null(input$rots_B), input$rots_B, 1000)
              export_K <- ifelse(!is.null(input$rots_K) && !is.na(input$rots_K), input$rots_K, "Auto")
              export_seed <- ifelse(!is.null(input$rots_seed) && !is.na(input$rots_seed), input$rots_seed, 123)
              export_ref_var <- "N/A"
              export_ref_level <- "N/A"
            }

            rots_params <- data.frame(
              Parameter = c("Method", "Number of Permutations (B)",
                            "Top Features (K)", "Random Seed",
                            "Reference Variable", "Reference Level"),
              Value = c(method_label, export_B, export_K, export_seed,
                        export_ref_var, export_ref_level)
            )
            writeData(wb, "ROTS Parameters", rots_params)
          }
          else if (input$sig_method == "limma") {
            # Add a metadata sheet with limma parameters
            addWorksheet(wb, "Limma Parameters")
            limma_trend_param <- if (input$limma_trend == "auto") TRUE else as.logical(input$limma_trend)
            limma_robust_param <- isTRUE(input$limma_robust)
            limma_params <- data.frame(
              Parameter = c("Method", "Trend", "Robust"),
              Value = c(
                "Linear Models for Microarray/RNA-Seq Data",
                as.character(limma_trend_param),
                as.character(limma_robust_param)
              )
            )
            writeData(wb, "Limma Parameters", limma_params)
          }
        }
      }
      
      # Add bootstrap results if available
      if (!is.null(values$bootstrap_results) && input$bootstrap_enabled == "yes") {
        # Add bootstrap results to workbook
        addWorksheet(wb, "Bootstrap Results")
        
        # Add confidence level and replicates info to the worksheet
        conf_level <- as.numeric(input$bootstrap_ci)
        n_replicates <- input$bootstrap_replicates
        
        writeData(wb, "Bootstrap Results", data.frame(
          Parameter = c("Confidence Level", "Number of Replicates",
                        "Strategy", "Random Seed"),
          Value = c(paste0(conf_level*100, "%"),
                    n_replicates,
                    input$bootstrap_strategy,
                    ifelse(!is.null(input$bootstrap_seed) && !is.na(input$bootstrap_seed),
                           input$bootstrap_seed, "Auto"))
        ), startRow = 1)
        
        # Add a blank row
        writeData(wb, "Bootstrap Results", data.frame(" " = ""), startRow = 4)
        
        # Write the bootstrap results
        writeData(wb, "Bootstrap Results", values$bootstrap_results, startRow = 6)
        
        # Apply formatting
        addStyle(wb, "Bootstrap Results", createStyle(textDecoration = "bold"),
                 rows = 6, cols = 1:ncol(values$bootstrap_results))
        addStyle(wb, "Bootstrap Results", createStyle(textDecoration = "bold"),
                 rows = 1, cols = 1:2)
      }
      
      # Save workbook
      saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  # Update ROC group selections when data is processed
  observe({
    req(values$unique_groups)
    updateSelectizeInput(session, "rocGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "rocGroup2", choices = values$unique_groups, selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
  })  # ROC group and molecule dropdown observers - Optimized for tab-specific execution
  observeEvent({
    # Only trigger when on ROC/PR Analysis tab AND relevant data changes
    list(
      input$current_tab,
      input$processBtn,  # Add processBtn to refresh when new data is processed
      if (length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis") values$unique_groups
    )
  }, {
    req(length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis")
    req(values$unique_groups)
    updateSelectizeInput(session, "rocGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "rocGroup2", choices = values$unique_groups, selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
  })
  # ROC molecule selection observer - Optimized for tab-specific execution
  observeEvent({
    # Only trigger when on ROC/PR Analysis tab AND feature set dependencies change
    list(
      input$current_tab,
      input$processBtn,  # Add processBtn to refresh when new data is processed
      if (length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis") {        list(
        input$roc_feature_source,
        input$roc_label_type,
        input$pca_top_features,
        input$pca_feature_ranking,
        values$cleaned_molecules,
        values$accession_ids,
        values$pca_result,
        values$selected_features
      )
      }
    )
  }, {
    req(length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis")
    
    # Get available molecule indices based on feature source
    available_indices <- get_feature_indices_by_source(input$roc_feature_source %||% "all", "All Groups")
    
    # Determine which labels to use based on radio button selection
    use_ids <- !is.null(input$roc_label_type) && input$roc_label_type == "ids" &&
      !is.null(values$accession_ids) && length(values$accession_ids) >= max(available_indices)
    
    # Get the corresponding labels
    if (use_ids) {
      available_molecules <- values$accession_ids[available_indices]
    } else {
      available_molecules <- values$cleaned_molecules[available_indices]
    }
    
    req(available_molecules)
    
    updateSelectizeInput(session, "rocSelectedMolecules",
                         choices = available_molecules,
                         selected = NULL,
                         server = TRUE)
  })
  
  # Make ROC generation reactive (replacing the button) - Optimized for tab-specific execution
  observeEvent({
    # Primary trigger: only when on ROC/PR Analysis tab AND dependencies change
    list(
      input$current_tab,
      input$processBtn,  # Add processBtn to refresh when new data is processed
      if (length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis") {
        list(
          values$normalized_data, values$cleaned_molecules,          input$rocGroup1, input$rocGroup2,
          input$rocPvalCutoff, input$rocLogFCCutoff,          values$stat_results, input$roc_feature_source,
          input$pca_top_features, input$pca_feature_ranking,
          input$rocUseSelectedMolecules, input$rocSelectedMolecules,
          input$sig_method, input$roc_fdr_cutoff, input$roc_label_type
        )
      }
    )
  }, {
    # Only run ROC analysis when user is on the ROC/PR Analysis tab
    req(length(input$current_tab) > 0 && input$current_tab == "ROC/PR Analysis")
    
    req(values$normalized_data, values$cleaned_molecules,
        input$rocGroup1, input$rocGroup2,
        input$rocPvalCutoff, input$rocLogFCCutoff,
        values$stat_results, input$roc_feature_source)
    # Add PCA-related dependencies when PCA feature set is selected
    if (!is.null(input$roc_feature_source) && input$roc_feature_source == "pca") {
      req(input$pca_top_features, input$pca_feature_ranking)
    }
    
    # Extract selected groups
    group1 <- input$rocGroup1
    group2 <- input$rocGroup2
    
    # Check if groups are different
    if(group1 == group2) {
      return(NULL)
    }
    
    # Identify column indices for each group
    group1_idx <- which(values$unique_groups == group1)
    group2_idx <- which(values$unique_groups == group2)
    
    if(length(group1_idx) == 0 || length(group2_idx) == 0) {
      return(NULL)
    }
    group1_cols <- values$group_column_indices[[group1_idx]]
    group2_cols <- values$group_column_indices[[group2_idx]]
    
    # Get comparison name for accessing statistics
    comparison_name <- paste(group1, "vs", group2)
    
    # Initialize variables for molecule selection
    selected_molecules <- NULL
    selected_indices <- NULL
    
    # First, get the feature set indices to use (PCA, ML, or all features)
    available_feature_indices <- get_feature_indices_by_source(input$roc_feature_source %||% "all", comparison_name)
    
    # If no features are available from the selected set, return NULL
    if(is.null(available_feature_indices) || length(available_feature_indices) == 0) {
      return(NULL)
    }
    
    available_features <- values$cleaned_molecules[available_feature_indices]
    
    # Apply molecule selection based on UI choices
    if(input$rocUseSelectedMolecules) {
      # Use user-selected molecules, but only those in the available feature set
      if(length(input$rocSelectedMolecules) == 0) {
        return(NULL)
      }
      
      # Check if IDs are being used in the dropdown
      use_ids <- !is.null(input$roc_label_type) && input$roc_label_type == "ids" &&
        !is.null(values$accession_ids) && length(values$accession_ids) >= max(available_feature_indices)
      
      if (use_ids) {
        # Map selected IDs back to feature names
        selected_id_indices <- which(values$accession_ids %in% input$rocSelectedMolecules)
        selected_molecules <- values$cleaned_molecules[selected_id_indices]
      } else {
        selected_molecules <- input$rocSelectedMolecules
      }
      
      selected_molecules <- intersect(selected_molecules, available_features)
      if(length(selected_molecules) == 0) {
        return(NULL)
      }
      selected_indices <- which(values$cleaned_molecules %in% selected_molecules)
    } else {
      
      # Apply p-value, FDR, and fold change filters using pre-calculated statistics
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Check if fold change column result contains the REVERSED marker
      is_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        # Extract the actual column name by removing the REVERSED: prefix
        fc_column <- gsub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Check if statistics are available
      if (is.null(values$stat_results) ||
          is.null(p_value_column) || is.null(fc_column) ||
          length(p_value_column) != 1 || length(fc_column) != 1 ||
          is.na(p_value_column) || is.na(fc_column) ||
          !p_value_column %in% colnames(values$stat_results) ||
          !fc_column %in% colnames(values$stat_results)) {
        return(NULL)
      }
      
      # Add ROTS FDR handling with tracking for reversed comparisons
      fdr_values <- NULL
      fdr_column <- NULL
      is_fdr_reversed <- FALSE
      if (input$sig_method == "rots") {
        # Check both possible orders for comparison name
        comparison_name_alt <- paste(rev(unlist(strsplit(comparison_name, " vs "))), collapse = " vs ")
        fdr_direct_name <- paste0(comparison_name, "_FDR")
        fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
        
        if (!is.null(values$stat_results)) {
          if (fdr_direct_name %in% colnames(values$stat_results)) {
            fdr_column <- fdr_direct_name
            fdr_values <- values$stat_results[[fdr_column]]
            is_fdr_reversed <- FALSE
          } else if (fdr_alt_name %in% colnames(values$stat_results)) {
            fdr_column <- fdr_alt_name
            fdr_values <- values$stat_results[[fdr_column]]
            is_fdr_reversed <- TRUE
          }
        }
      }
      
      # Get the precomputed values
      p_values <- values$stat_results[[p_value_column]]
      log2_fc <- values$stat_results[[fc_column]]
      
      # If fold change values come from reversed comparison, negate them
      if (is_reversed) {
        log2_fc <- -log2_fc
      }      # For ROTS with FDR available, apply all three cutoffs simultaneously
      if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
        # filter on p-value, FDR and log2FC together
        filter_idx <- !is.na(p_values) &
          !is.na(fdr_values) &
          !is.na(log2_fc) &
          p_values <= input$rocPvalCutoff &
          fdr_values <= input$roc_fdr_cutoff &
          abs(log2_fc) >= input$rocLogFCCutoff
        values$roc_using_fdr <- TRUE
        values$is_fdr_reversed <- is_fdr_reversed
      } else {
        # standard filter for non-ROTS or missing FDR
        filter_idx <- !is.na(p_values) &
          !is.na(log2_fc) &
          p_values <= input$rocPvalCutoff &
          abs(log2_fc) >= input$rocLogFCCutoff
        values$roc_using_fdr <- FALSE
        values$is_fdr_reversed <- FALSE
      }
      
      # Get significant indices
      significant_idx <- which(filter_idx)
      
      # Intersect significant indices with feature source indices (like other tabs)
      selected_indices <- intersect(significant_idx, available_feature_indices)
      
      if(length(selected_indices) == 0) {
        return(NULL)
      }
      
      # store filtered molecules & FDR column for the results table
      values$roc_filtered_molecules <- data.frame(
        Molecule = values$cleaned_molecules[selected_indices],
        FDR = if (values$roc_using_fdr) fdr_values[selected_indices] else NA,
        stringsAsFactors = FALSE
      )
      
      selected_molecules <- values$cleaned_molecules[selected_indices]
    }
    # Check if we have molecules to analyze
    if(length(selected_indices) == 0) {
      return(NULL)
    }
    
    # Store the filtered molecules for download
    values$roc_filtered_molecules <- data.frame(
      Molecule = values$cleaned_molecules[selected_indices],
      stringsAsFactors = FALSE
    )
    
    # Create data in long format for better ROC calculation
    withProgress(message = "Calculating ROC curves...", {
      # Create data container
      data_long <- data.frame(
        Molecule = character(),
        Value = numeric(),
        GroupLabel = character(),
        stringsAsFactors = FALSE
      )
      
      # Store molecule indices for later ID lookup
      molecule_indices <- selected_indices
      names(molecule_indices) <- values$cleaned_molecules[selected_indices]
      values$roc_molecule_indices <- molecule_indices
      
      # Fill data_long with values
      for(i in seq_along(selected_indices)) {
        molecule_idx <- selected_indices[i]
        molecule_name <- values$cleaned_molecules[molecule_idx]
        molecule_data <- values$normalized_data[molecule_idx, , drop = TRUE]
        
        # Process group 1
        for(col in group1_cols) {
          if(!is.na(molecule_data[col])) {
            data_long <- rbind(data_long, data.frame(
              Molecule = molecule_name,
              Value = as.numeric(molecule_data[col]),
              GroupLabel = group1,
              stringsAsFactors = FALSE
            ))
          }
        }
        
        # Process group 2
        for(col in group2_cols) {
          if(!is.na(molecule_data[col])) {
            data_long <- rbind(data_long, data.frame(
              Molecule = molecule_name,
              Value = as.numeric(molecule_data[col]),
              GroupLabel = group2,
              stringsAsFactors = FALSE
            ))
          }
        }
        
        setProgress(i/length(selected_indices),
                    detail = paste("Processing", i, "of", length(selected_indices)))
      }
      
      # Determine regulation status for each molecule
      regulation_status <- data.frame(
        Molecule = character(),
        Regulation = character(),
        stringsAsFactors = FALSE
      )
      
      # Function to determine if a molecule is upregulated or downregulated
      classify_regulation <- function(molecule_data) {
        control_values <- molecule_data$Value[molecule_data$GroupLabel == group1]
        case_values <- molecule_data$Value[molecule_data$GroupLabel == group2]
        if(length(control_values) == 0 || length(case_values) == 0) return("Unknown")
        control_mean <- mean(control_values, na.rm = TRUE)
        case_mean <- mean(case_values, na.rm = TRUE)
        if(is.nan(control_mean) || is.nan(case_mean)) return("Unknown")
        return(ifelse(case_mean > control_mean, "Upregulated", "Downregulated"))
      }
      
      for(mol in unique(data_long$Molecule)) {
        mol_data <- data_long[data_long$Molecule == mol, ]
        reg <- classify_regulation(mol_data)
        regulation_status <- rbind(regulation_status,
                                   data.frame(Molecule = mol,
                                              Regulation = reg,
                                              stringsAsFactors = FALSE))
      }
      
      # Function to calculate ROC and AUC for a single molecule considering regulation
      calc_ROC_AUC <- function(molecule_data, regulation) {
        tryCatch({
          if(regulation == "Upregulated") {
            roc_obj <- pROC::roc(molecule_data$GroupLabel, molecule_data$Value,
                                 levels = c(group1, group2), direction = "<", quiet = TRUE)
          } else if(regulation == "Downregulated") {
            roc_obj <- pROC::roc(molecule_data$GroupLabel, -molecule_data$Value,
                                 levels = c(group1, group2), direction = "<", quiet = TRUE)
          } else {
            return(NULL)
          }
          auc_value <- pROC::auc(roc_obj)
          return(list(roc = roc_obj, auc = auc_value))
        }, error = function(e) NULL)
      }
      
      # Function to calculate PR curve and AUPRC for a single molecule
      calc_PR_curve <- function(molecule_data, regulation) {
        tryCatch({
          # Create binary response
          y_true <- ifelse(molecule_data$GroupLabel == group2, 1, 0)
          
          # Get predictions based on regulation
          if(regulation == "Upregulated") {
            y_score <- molecule_data$Value
          } else if(regulation == "Downregulated") {
            y_score <- -molecule_data$Value
          } else {
            return(NULL)
          }
          
          # Sort by score descending for PR curve calculation
          ord <- order(y_score, decreasing = TRUE)
          y_true_sorted <- y_true[ord]
          y_score_sorted <- y_score[ord]
          
          # Calculate precision and recall at different thresholds
          n_pos <- sum(y_true_sorted)
          n_total <- length(y_true_sorted)
          
          if(n_pos == 0) return(NULL)
          
          # Calculate cumulative true positives and false positives
          tp <- cumsum(y_true_sorted)
          fp <- cumsum(1 - y_true_sorted)
          
          # Calculate precision and recall
          precision <- tp / (tp + fp)
          recall <- tp / n_pos
          
          # Add points at (0,1) and (1, n_pos/n_total) for complete curve
          precision <- c(1, precision, n_pos/n_total)
          recall <- c(0, recall, 1)
          
          # Calculate AUPRC using trapezoidal rule
          auprc <- sum(diff(recall) * (precision[-1] + precision[-length(precision)]) / 2)
          
          return(list(
            precision = precision,
            recall = recall,
            auprc = auprc,
            thresholds = c(Inf, y_score_sorted, -Inf)
          ))
        }, error = function(e) NULL)
      }
      
      # Calculate ROC and PR curves for each molecule
      roc_results <- list()
      
      for(i in seq_along(unique(data_long$Molecule))) {
        mol <- unique(data_long$Molecule)[i]
        setProgress(0.5 + i/(2*length(unique(data_long$Molecule))),
                    detail = paste("Calculating curves for", mol))
        
        mol_data <- data_long[data_long$Molecule == mol, ]
        reg <- regulation_status$Regulation[regulation_status$Molecule == mol]
        
        roc_auc <- calc_ROC_AUC(mol_data, reg)
        pr_curve <- calc_PR_curve(mol_data, reg)
        
        if(!is.null(roc_auc) && !is.null(pr_curve)) {
          roc_results[[length(roc_results) + 1]] <- list(
            molecule = mol,
            roc = roc_auc$roc,
            auc = roc_auc$auc,
            pr = pr_curve,
            auprc = pr_curve$auprc,
            regulation = reg
          )
        } else if(!is.null(roc_auc)) {
          # Keep ROC-only results for backwards compatibility
          roc_results[[length(roc_results) + 1]] <- list(
            molecule = mol,
            roc = roc_auc$roc,
            auc = roc_auc$auc,
            pr = NULL,
            auprc = NA,
            regulation = reg
          )
        }
      }
      
      # Calculate combined model if we have more than one molecule
      if(length(roc_results) > 1) {
        setProgress(0.9, detail = "Calculating combined model")
        
        # Prepare data for logistic regression considering regulation
        combined_data <- data_long %>%
          left_join(regulation_status, by = "Molecule") %>%
          mutate(
            corrected_value = ifelse(Regulation == "Downregulated", -Value, Value)
          )
        
        # Convert to wide format for logistic regression
        wide_data <- combined_data %>%
          group_by(Molecule, GroupLabel) %>%
          summarise(mean_value = mean(corrected_value, na.rm = TRUE), .groups = 'drop') %>%
          tidyr::pivot_wider(names_from = Molecule, values_from = mean_value, values_fill = 0) %>%
          mutate(Class = if_else(GroupLabel == group2, 1, 0)) %>%
          dplyr::select(-GroupLabel)
        
        # Check if we have sufficient data for logistic regression
        if(length(unique(wide_data$Class)) >= 2) {
          # Fit the model
          tryCatch({
            combined_model <- glm(Class ~ ., data = wide_data, family = binomial)
            combined_pred <- predict(combined_model, type = "response")
            combined_roc <- pROC::roc(wide_data$Class, combined_pred, quiet = TRUE)
            
            # Calculate combined PR curve
            combined_pr <- calc_PR_curve(
              data.frame(
                GroupLabel = ifelse(wide_data$Class == 1, group2, group1),
                Value = combined_pred,
                stringsAsFactors = FALSE
              ),
              "Upregulated"
            )
            
            # Add combined model to results if no individual molecule has AUC = 1
            if(!any(sapply(roc_results, function(x) x$auc == 1))) {
              roc_results[[length(roc_results) + 1]] <- list(
                molecule = "Combined",
                roc = combined_roc,
                auc = pROC::auc(combined_roc),
                pr = combined_pr,
                auprc = if(!is.null(combined_pr)) combined_pr$auprc else NA,
                regulation = "Combined"
              )
            }
          }, error = function(e) {
            message("Error in combined model: ", e$message)
          })
        }
      }
      
      # Determine which labels to use based on radio button selection
      use_ids <- !is.null(input$roc_label_type) && input$roc_label_type == "ids" &&
        !is.null(values$accession_ids) && !is.null(values$roc_molecule_indices)
      
      # Prepare data for plotting
      plot_data <- data.frame(
        FPR = numeric(),
        TPR = numeric(),
        Molecule = character(),
        AUC = numeric(),
        Regulation = character(),
        stringsAsFactors = FALSE
      )
      
      # Separate combined results from individual results
      combined_result <- NULL
      individual_results <- list()
      for(result in roc_results) {
        if(result$molecule == "Combined") {
          combined_result <- result
        } else {
          individual_results[[length(individual_results) + 1]] <- result
        }
      }
      
      # Process individual results first
      for(result in individual_results) {
        # Get the label (ID or feature name)
        mol_label <- result$molecule
        if (use_ids && mol_label != "Combined") {
          mol_idx <- values$roc_molecule_indices[[mol_label]]
          if (!is.null(mol_idx) && mol_idx <= length(values$accession_ids)) {
            mol_label <- values$accession_ids[mol_idx]
          }
        }
        
        plot_data <- rbind(plot_data, data.frame(
          FPR = 1 - result$roc$specificities,
          TPR = result$roc$sensitivities,
          Molecule = paste0(sprintf("%.2f", result$auc), " - ", mol_label),
          AUC = as.numeric(result$auc),
          Regulation = result$regulation,
          stringsAsFactors = FALSE
        ))
      }
      
      # Add combined result last if it exists
      if(!is.null(combined_result)) {
        plot_data <- rbind(plot_data, data.frame(
          FPR = 1 - combined_result$roc$specificities,
          TPR = combined_result$roc$sensitivities,
          Molecule = paste0(sprintf("%.2f", combined_result$auc), " - ", combined_result$molecule),
          AUC = as.numeric(combined_result$auc),
          Regulation = combined_result$regulation,
          stringsAsFactors = FALSE
        ))
      }
      
      # Create results table
      results_table <- data.frame(
        Molecule = sapply(roc_results, function(x) {
          mol_label <- x$molecule
          if (use_ids && mol_label != "Combined") {
            mol_idx <- values$roc_molecule_indices[[mol_label]]
            if (!is.null(mol_idx) && mol_idx <= length(values$accession_ids)) {
              mol_label <- values$accession_ids[mol_idx]
            }
          }
          mol_label
        }),
        AUC = sapply(roc_results, function(x) sprintf("%.3f", as.numeric(x$auc))),
        AUPRC = sapply(roc_results, function(x) {
          if(is.null(x$auprc) || is.na(x$auprc)) {
            "N/A"
          } else {
            sprintf("%.3f", as.numeric(x$auprc))
          }
        }),
        Regulation = sapply(roc_results, function(x) x$regulation),
        stringsAsFactors = FALSE
      )
      
      # Sort by AUC descending
      results_table <- results_table[order(-as.numeric(results_table$AUC)), ]
      
      # Store results for download
      values$roc_results <- results_table
      values$roc_data <- roc_results
      
      # Generate the plot with the selected color palette
      output$rocPlot <- renderPlot({ 
        # Ensure reactivity to analysis parameter changes
        input$roc_label_type
        input$rocPvalCutoff
        input$rocLogFCCutoff
        input$rocColorPalette
        input$rocLineThickness
        input$rocLegendFontSize
        input$roc_title_size
        input$roc_axis_title_size
        input$roc_axis_text_size
        input$rocShowCombined
        
        # Get selected palette
        selected_palette <- input$rocColorPalette
        
        # Generate colors based on selected palette with proper handling of palette sizes
        if(selected_palette %in% c("viridis", "plasma", "inferno", "magma", "cividis")) {
          # Use viridis palettes
          color_palette <- viridis::viridis_pal(option = selected_palette)(length(unique(plot_data$Molecule)))
        } else {
          # Use RColorBrewer palettes with proper handling for palette size limits
          max_colors_in_palette <- switch(selected_palette,
                                          "Set1" = 9,
                                          "Set2" = 8,
                                          "Set3" = 12,
                                          "Dark2" = 8,
                                          "Paired" = 12,
                                          "Spectral" = 11,
                                          9)  # Default fallback
          
          n_needed_colors <- length(unique(plot_data$Molecule))
          base_colors <- RColorBrewer::brewer.pal(min(max_colors_in_palette,
                                                      min(max_colors_in_palette, n_needed_colors)),
                                                  selected_palette)
          
          # Extend if needed
          if(n_needed_colors > length(base_colors)) {
            color_palette <- colorRampPalette(base_colors)(n_needed_colors)
          } else {
            color_palette <- base_colors[1:n_needed_colors]
          }
        }
        
        # Filter plot_data based on Show Combined ROC checkbox
        plot_data_filtered <- plot_data
        if (!isTRUE(input$rocShowCombined)) {
          plot_data_filtered <- subset(plot_data, !grepl("Combined", Molecule, ignore.case = TRUE))
        }
        
        # Ensure factor order with Combined last
        molecule_levels <- unique(plot_data_filtered$Molecule)
        # Separate combined from others
        combined_levels <- grep("Combined", molecule_levels, value = TRUE)
        other_levels <- setdiff(molecule_levels, combined_levels)
        # Order: other molecules first, then combined
        ordered_levels <- c(other_levels, combined_levels)
        plot_data_filtered$Molecule <- factor(plot_data_filtered$Molecule, levels = ordered_levels)
        
        p <- ggplot(plot_data_filtered, aes(x = FPR, y = TPR, color = Molecule)) +
          geom_path(size = input$rocLineThickness) +
          geom_abline(intercept = 0, slope = 1, linetype = "dashed", color = "grey50", size = 1) +
          scale_color_manual(values = color_palette) +
          labs(
            x = "1 - Specificity",
            y = "Sensitivity",
            title = paste(group1, "vs", group2),
            subtitle = paste0("p-value cutoff: ", input$rocPvalCutoff,
                              ", log2FC cutoff: ", input$rocLogFCCutoff)
          ) +
          theme_linedraw(base_size = 12) +
          theme(
            legend.position = c(0.97, 0.03),
            legend.justification = c(1, 0),
            legend.text = element_text(size = input$rocLegendFontSize, face = "bold"),
            plot.title = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size),
            plot.subtitle = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size - 2),
            legend.title = element_blank(),
            panel.grid = element_blank(),
            axis.text = element_text(face = "bold", size = input$roc_axis_text_size),
            axis.title = element_text(face = "bold", size = input$roc_axis_title_size),
            legend.background = element_rect(fill = "white", color = "black", size = 0.5),
            legend.margin = unit(c(3, 3, 3, 3), "pt"),
            plot.margin = unit(c(0.5, 0.5, 0.5, 0.5), "pt")
          )
        
        # Save for download
        values$roc_plot_obj <- p
        
        return(p)
      }, res = UI_PLOT_RES)
      
      # Generate PR curve plot
      output$prPlot <- renderPlot({ 
        # Ensure reactivity to analysis parameter changes
        input$roc_label_type
        input$rocPvalCutoff
        input$rocLogFCCutoff
        input$rocColorPalette
        input$rocLineThickness
        input$rocLegendFontSize
        input$roc_title_size
        input$roc_axis_title_size
        input$roc_axis_text_size
        input$rocShowCombined
        
        req(values$roc_data)
        
        # Determine which labels to use based on radio button selection
        use_ids <- !is.null(input$roc_label_type) && input$roc_label_type == "ids" &&
          !is.null(values$accession_ids) && !is.null(values$roc_molecule_indices)
        
        # Prepare PR curve data
        pr_plot_data <- data.frame(
          Recall = numeric(),
          Precision = numeric(),
          Molecule = character(),
          AUPRC = numeric(),
          Regulation = character(),
          stringsAsFactors = FALSE
        )
        
        for(result in values$roc_data) {
          if(!is.null(result$pr)) {
            # Get the label (ID or feature name)
            mol_label <- result$molecule
            if (use_ids && mol_label != "Combined") {
              mol_idx <- values$roc_molecule_indices[[mol_label]]
              if (!is.null(mol_idx) && mol_idx <= length(values$accession_ids)) {
                mol_label <- values$accession_ids[mol_idx]
              }
            }
            
            pr_plot_data <- rbind(pr_plot_data, data.frame(
              Recall = result$pr$recall,
              Precision = result$pr$precision,
              Molecule = paste0(sprintf("%.3f", result$auprc), " - ", mol_label),
              AUPRC = as.numeric(result$auprc),
              Regulation = result$regulation,
              stringsAsFactors = FALSE
            ))
          }
        }
        
        # Get selected palette (same as ROC plot)
        selected_palette <- input$rocColorPalette
        
        # Generate colors based on selected palette
        if(selected_palette %in% c("viridis", "plasma", "inferno", "magma", "cividis")) {
          color_palette <- viridis::viridis_pal(option = selected_palette)(length(unique(pr_plot_data$Molecule)))
        } else {
          max_colors_in_palette <- switch(selected_palette,
                                          "Set1" = 9, "Set2" = 8, "Set3" = 12,
                                          "Dark2" = 8, "Paired" = 12, "Spectral" = 11, 9)
          n_needed_colors <- length(unique(pr_plot_data$Molecule))
          base_colors <- RColorBrewer::brewer.pal(min(max_colors_in_palette,
                                                      min(max_colors_in_palette, n_needed_colors)),
                                                  selected_palette)
          if(n_needed_colors > length(base_colors)) {
            color_palette <- colorRampPalette(base_colors)(n_needed_colors)
          } else {
            color_palette <- base_colors[1:n_needed_colors]
          }
        }
        
        # Filter data based on Show Combined checkbox
        pr_plot_data_filtered <- pr_plot_data
        if (!isTRUE(input$rocShowCombined)) {
          pr_plot_data_filtered <- subset(pr_plot_data, !grepl("Combined", Molecule, ignore.case = TRUE))
        }
        
        # Ensure factor order with Combined last
        molecule_levels <- unique(pr_plot_data_filtered$Molecule)
        # Separate combined from others
        combined_levels <- grep("Combined", molecule_levels, value = TRUE)
        other_levels <- setdiff(molecule_levels, combined_levels)
        # Order: other molecules first, then combined
        ordered_levels <- c(other_levels, combined_levels)
        pr_plot_data_filtered$Molecule <- factor(pr_plot_data_filtered$Molecule, levels = ordered_levels)
        
        if(nrow(pr_plot_data_filtered) == 0) {
          # If no PR data available, show message
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "No PR curve data available\n(requires binary classification)",
                     size = 6, hjust = 0.5, vjust = 0.5) +
            theme_void()
        } else {
          # Calculate baseline precision (random classifier)
          baseline_precision <- 0.5  # Assuming balanced classes; could be adjusted based on actual class distribution
          
          p <- ggplot(pr_plot_data_filtered, aes(x = Recall, y = Precision, color = Molecule)) +
            geom_path(size = input$rocLineThickness) +
            geom_hline(yintercept = baseline_precision, linetype = "dashed", color = "grey50", size = 1) +
            scale_color_manual(values = color_palette) +
            labs(
              x = "Recall (Sensitivity)",
              y = "Precision (PPV)",
              title = paste("PR Curves:", group1, "vs", group2),
              subtitle = paste0("p-value cutoff: ", input$rocPvalCutoff,
                                ", log2FC cutoff: ", input$rocLogFCCutoff)
            ) +
            theme_linedraw(base_size = 12) +
            theme(
              legend.position = c(0.03, 0.03),
              legend.justification = c(0, 0),
              legend.text = element_text(size = input$rocLegendFontSize, face = "bold"),
              plot.title = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size),
              plot.subtitle = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size - 2),
              legend.title = element_blank(),
              panel.grid = element_blank(),
              axis.text = element_text(face = "bold", size = input$roc_axis_text_size),
              axis.title = element_text(face = "bold", size = input$roc_axis_title_size),
              legend.background = element_rect(fill = "white", color = "black", size = 0.5),
              legend.margin = unit(c(3, 3, 3, 3), "pt"),
              plot.margin = unit(c(0.5, 0.5, 0.5, 0.5), "pt")
            )
        }
        
        # Save for download
        values$pr_plot_obj <- p
        
        return(p)
      }, res = UI_PLOT_RES)
      
      # Generate combined ROC/PR plot
      output$combinedPlot <- renderPlot({ 
        # Ensure reactivity to analysis parameter changes
        input$rocPvalCutoff
        input$rocLogFCCutoff
        input$rocColorPalette
        input$rocLineThickness
        input$rocLegendFontSize
        input$roc_title_size
        input$roc_axis_title_size
        input$roc_axis_text_size
        input$rocShowCombined
        
        req(values$roc_data)
        
        # Create ROC plot
        roc_plot_data <- data.frame(
          FPR = numeric(),
          TPR = numeric(),
          Molecule = character(),
          AUC = numeric(),
          Regulation = character(),
          stringsAsFactors = FALSE
        )
        
        for(result in values$roc_data) {
          roc_plot_data <- rbind(roc_plot_data, data.frame(
            FPR = 1 - result$roc$specificities,
            TPR = result$roc$sensitivities,
            Molecule = paste0(sprintf("%.3f", result$auc), " - ", result$molecule),
            AUC = as.numeric(result$auc),
            Regulation = result$regulation,
            stringsAsFactors = FALSE
          ))
        }
        
        # Get selected palette
        selected_palette <- input$rocColorPalette
        
        # Generate colors based on selected palette
        if(selected_palette %in% c("viridis", "plasma", "inferno", "magma", "cividis")) {
          color_palette <- viridis::viridis_pal(option = selected_palette)(length(unique(roc_plot_data$Molecule)))
        } else {
          max_colors_in_palette <- switch(selected_palette,
                                          "Set1" = 9, "Set2" = 8, "Set3" = 12,
                                          "Dark2" = 8, "Paired" = 12, "Spectral" = 11, 9)
          n_needed_colors <- length(unique(roc_plot_data$Molecule))
          base_colors <- RColorBrewer::brewer.pal(min(max_colors_in_palette,
                                                      min(max_colors_in_palette, n_needed_colors)),
                                                  selected_palette)
          if(n_needed_colors > length(base_colors)) {
            color_palette <- colorRampPalette(base_colors)(n_needed_colors)
          } else {
            color_palette <- base_colors[1:n_needed_colors]
          }
        }
        
        # Filter data based on Show Combined checkbox
        roc_plot_data_filtered <- roc_plot_data
        if (!isTRUE(input$rocShowCombined)) {
          roc_plot_data_filtered <- subset(roc_plot_data, !grepl("Combined", Molecule, ignore.case = TRUE))
        }
        
        # Create ROC plot
        roc_plot <- ggplot(roc_plot_data_filtered, aes(x = FPR, y = TPR, color = Molecule)) +
          geom_path(size = input$rocLineThickness) +
          geom_abline(intercept = 0, slope = 1, linetype = "dashed", color = "grey50", size = 1) +
          scale_color_manual(values = color_palette) +
          labs(
            x = "False Positive Rate",
            y = "True Positive Rate",
            title = "ROC Curves"
          ) +
          theme_linedraw(base_size = 10) +
          theme(
            legend.position = "bottom",
            legend.text = element_text(size = input$rocLegendFontSize, face = "bold"),
            plot.title = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size),
            legend.title = element_blank(),
            panel.grid = element_blank(),
            axis.text = element_text(face = "bold", size = input$roc_axis_text_size),
            axis.title = element_text(face = "bold", size = input$roc_axis_title_size),
            legend.background = element_rect(fill = "white", color = "black", size = 0.5),
            legend.margin = unit(c(3, 3, 3, 3), "pt")
          ) +
          guides(color = guide_legend(ncol = 2))
        
        # Create PR plot data
        pr_plot_data <- data.frame(
          Recall = numeric(),
          Precision = numeric(),
          Molecule = character(),
          AUPRC = numeric(),
          Regulation = character(),
          stringsAsFactors = FALSE
        )
        
        for(result in values$roc_data) {
          if(!is.null(result$pr)) {
            pr_plot_data <- rbind(pr_plot_data, data.frame(
              Recall = result$pr$recall,
              Precision = result$pr$precision,
              Molecule = paste0(sprintf("%.3f", result$auprc), " - ", result$molecule),
              AUPRC = as.numeric(result$auprc),
              Regulation = result$regulation,
              stringsAsFactors = FALSE
            ))
          }
        }
        
        # Filter PR data based on Show Combined checkbox
        pr_plot_data_filtered <- pr_plot_data
        if (!isTRUE(input$rocShowCombined)) {
          pr_plot_data_filtered <- subset(pr_plot_data, !grepl("Combined", Molecule, ignore.case = TRUE))
        }
        
        if(nrow(pr_plot_data_filtered) == 0) {
          # If no PR data available, show message
          pr_plot <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "No PR curve data available\n(requires binary classification)",
                     size = 4, hjust = 0.5, vjust = 0.5) +
            labs(title = "PR Curves") +
            theme_void() +
            theme(plot.title = element_text(hjust = 0.5, face = "bold", size = 12))
        } else {
          # Calculate baseline precision (random classifier)
          baseline_precision <- 0.5  # Assuming balanced classes
          
          pr_plot <- ggplot(pr_plot_data_filtered, aes(x = Recall, y = Precision, color = Molecule)) +
            geom_path(size = input$rocLineThickness) +
            geom_hline(yintercept = baseline_precision, linetype = "dashed", color = "grey50", size = 1) +
            scale_color_manual(values = color_palette[1:length(unique(pr_plot_data_filtered$Molecule))]) +
            labs(
              x = "Recall (Sensitivity)",
              y = "Precision (PPV)",
              title = "PR Curves"
            ) +
            theme_linedraw(base_size = 10) +
            theme(
              legend.position = "bottom",
              legend.text = element_text(size = input$rocLegendFontSize, face = "bold"),
              plot.title = element_text(hjust = 0.5, face = "bold", size = input$roc_title_size),
              legend.title = element_blank(),
              panel.grid = element_blank(),
              axis.text = element_text(face = "bold", size = input$roc_axis_text_size),
              axis.title = element_text(face = "bold", size = input$roc_axis_title_size),
              legend.background = element_rect(fill = "white", color = "black", size = 0.5),
              legend.margin = unit(c(3, 3, 3, 3), "pt")
            ) +
            guides(color = guide_legend(ncol = 2))
        }
        
        # Arrange plots side by side using gridExtra
        combined_plot <- gridExtra::grid.arrange(
          roc_plot, pr_plot,
          ncol = 2,
          top = grid::textGrob(paste("Combined ROC/PR Analysis:", group1, "vs", group2),
                               gp = grid::gpar(fontsize = input$roc_title_size, fontface = "bold"))
        )
        
        # Save for download (create a combined plot object)
        values$combined_plot_obj <- combined_plot
        
        return(combined_plot)
      }, res = UI_PLOT_RES)
      
      # Display results table
      output$rocTable <- DT::renderDataTable({
        req(values$roc_results)
        
        # Create base results table
        results_table <- values$roc_results
        
        # Add FDR column if using ROTS with FDR values
        if (!is.null(values$roc_using_fdr) && values$roc_using_fdr && !is.null(values$roc_filtered_molecules$FDR)) {
          # Check if the FDR values were from a reversed comparison
          if (!is.null(values$is_fdr_reversed) && values$is_fdr_reversed) {
            # Add a note in the column name about reversed comparison
            results_table$FDR <- values$roc_filtered_molecules$FDR
            names(results_table)[names(results_table) == "FDR"] <- "FDR (rev)"
          } else {
            results_table$FDR <- values$roc_filtered_molecules$FDR
          }
          
          # Move FDR column right after AUC
          col_order <- c("Molecule", "AUC",
                         if (values$is_fdr_reversed) "FDR" else "FDR",
                         "Regulation")
          results_table <- results_table[, col_order]
        }
        
        DT::datatable(
          results_table,
          options = list(pageLength = 10, scrollX = TRUE),
          rownames = FALSE
        ) %>%
          DT::formatStyle(
            "AUC",
            background = styleColorBar(c(0.5, 1), "lightblue"),
            fontWeight = "bold"
          )
      })
      
      # PR Table output
      output$prTable <- DT::renderDataTable({
        req(values$roc_results)
        
        # Create PR-focused results table
        results_table <- values$roc_results
        
        # Filter to show only molecules with AUPRC values
        pr_results <- results_table[results_table$AUPRC != "N/A", ]
        
        if(nrow(pr_results) > 0) {
          # Add FDR column if using ROTS with FDR values
          if (!is.null(values$roc_using_fdr) && values$roc_using_fdr && !is.null(values$roc_filtered_molecules$FDR)) {
            pr_results$FDR <- values$roc_filtered_molecules$FDR[match(pr_results$Molecule, values$roc_filtered_molecules$Molecule)]
          }
          
          DT::datatable(
            pr_results,
            options = list(pageLength = 10, scrollX = TRUE),
            rownames = FALSE
          ) %>%
            DT::formatStyle(
              "AUPRC",
              background = styleColorBar(c(0, 1), "lightgreen"),
              fontWeight = "bold"
            )
        } else {
          DT::datatable(
            data.frame(Message = "No PR curve data available. Requires binary classification with sufficient positive/negative cases."),
            options = list(pageLength = 10, scrollX = TRUE),
            rownames = FALSE
          )
        }
      })
      
      # Combined Table output
      output$combinedTable <- DT::renderDataTable({
        req(values$roc_results)
        
        # Create combined results table
        results_table <- values$roc_results
        
        # Add FDR column if using ROTS with FDR values
        if (!is.null(values$roc_using_fdr) && values$roc_using_fdr && !is.null(values$roc_filtered_molecules$FDR)) {
          results_table$FDR <- values$roc_filtered_molecules$FDR
        }
        
        DT::datatable(
          results_table,
          options = list(pageLength = 10, scrollX = TRUE),
          rownames = FALSE
        ) %>%
          DT::formatStyle(
            "AUC",
            background = styleColorBar(c(0.5, 1), "lightblue"),
            fontWeight = "bold"
          ) %>%
          DT::formatStyle(
            "AUPRC",
            background = styleColorBar(c(0, 1), "lightgreen"),
            fontWeight = "bold"
          )
      })
      showNotification("ROC analysis completed successfully!", type = "message")
    })
  })
  
  # Download ROC Plot
  output$downloadRocPlotBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0(input$rocGroup1, "_vs_", input$rocGroup2, "_ROC_Plot_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$roc_plot_obj)
      # Use user-specified width and height from the ROC tab
      width <- ifelse(is.null(input$rocWidth), 8, input$rocWidth)
      height <- ifelse(is.null(input$rocHeight), 6, input$rocHeight)
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      format <- get_safe_global_image_format()
      ggsave(file, plot = values$roc_plot_obj, width = width, height = height, dpi = dpi, device = resolve_ggsave_device(format))
    }
  )
  
  # Download ROC Data
  output$downloadRocDataBtn <- downloadHandler(
    filename = function() {
      paste0(input$rocGroup1, "_vs_", input$rocGroup2, "_ROC_Analysis_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(values$roc_results)
      wb <- createWorkbook()
      
      # 1) ROC Results
      addWorksheet(wb, "ROC Results")
      writeData(wb, "ROC Results", values$roc_results)
      
      addWorksheet(wb, "Analysis Parameters")
      if (isTRUE(values$roc_using_fdr)) {
        param_data <- data.frame(
          Parameter = c(
            "Control Group","Case Group",
            "p-value Cutoff","FDR Cutoff","Log2FC Cutoff",
            "Show Combined ROC","Selected Molecules",
            "Molecules Used","Statistical Method","Analysis Date"
          ),
          Value = c(
            input$rocGroup1, input$rocGroup2,
            input$rocPvalCutoff, input$roc_fdr_cutoff, input$rocLogFCCutoff,
            input$rocShowCombined,
            if (input$rocUseSelectedMolecules) length(input$rocSelectedMolecules) else "All",
            nrow(values$roc_results),
            "ROTS", format(Sys.time(), "%Y-%m-%d %H:%M:%S")
          ),
          stringsAsFactors = FALSE
        )
      } else {
        param_data <- data.frame(
          Parameter = c(
            "Control Group","Case Group",
            "p-value Cutoff","Log2FC Cutoff",
            "Show Combined ROC","Selected Molecules",
            "Molecules Used","Statistical Method","Analysis Date"
          ),
          Value = c(
            input$rocGroup1, input$rocGroup2,
            input$rocPvalCutoff, input$rocLogFCCutoff,
            input$rocShowCombined,
            if (input$rocUseSelectedMolecules) length(input$rocSelectedMolecules) else "All",
            nrow(values$roc_results),
            input$sig_method, format(Sys.time(), "%Y-%m-%d %H:%M:%S")
          ),
          stringsAsFactors = FALSE
        )
      }
      writeData(wb, "Analysis Parameters", param_data)
      # If user selected specific molecules, add sheet with the list
      if (input$rocUseSelectedMolecules && length(input$rocSelectedMolecules) > 0) {
        addWorksheet(wb, "Selected Molecules")
        writeData(wb, "Selected Molecules", data.frame(Molecule = input$rocSelectedMolecules))
      }
      
      # Add sheet for detailed ROC data
      if (length(values$roc_data) > 0) {
        addWorksheet(wb, "Detailed ROC Data")
        
        # Combine detailed data from all ROC objects
        detailed_data <- data.frame(
          Molecule = character(),
          Specificity = numeric(),
          Sensitivity = numeric(),
          Threshold = numeric(),
          stringsAsFactors = FALSE
        )
        
        for (roc_item in values$roc_data) {
          molecule_data <- data.frame(
            Molecule = rep(roc_item$molecule, length(roc_item$roc$specificities)),
            Specificity = roc_item$roc$specificities,
            Sensitivity = roc_item$roc$sensitivities,
            Threshold = roc_item$roc$thresholds
          )
          detailed_data <- rbind(detailed_data, molecule_data)
        }
        
        # Add combined model if available
        if (!is.null(values$combined_roc)) {
          combined_data <- data.frame(
            Molecule = rep("Combined Model", length(values$combined_roc$specificities)),
            Specificity = values$combined_roc$specificities,
            Sensitivity = values$combined_roc$sensitivities,
            Threshold = values$combined_roc$thresholds
          )
          detailed_data <- rbind(detailed_data, combined_data)
        }
        
        writeData(wb, "Detailed ROC Data", detailed_data)
      }
      saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
