  # Add this to the server function after the processBtn observer
  # Calculate and display statistics results
  observeEvent(input$processBtn, {
    # Common observer for all pairwise selection updates
    observe({
      req(values$unique_groups)
      
      # Build extended choices that include lmROTS/lmeROTS variable comparisons when available
      # These allow users to select variable-based comparisons in volcano/MA/diff plots
      extended_choices <- values$unique_groups
      tryCatch({
        av <- get_available_comparison_names()
        vv <- av[grepl("^(lmROTS|lmeROTS)_", av)]
        if (length(vv) > 0) extended_choices <- c(values$unique_groups, vv)
      }, error = function(e) NULL)
      
      # Update Heatmap group selections (include lmROTS/lmeROTS variables)
      updateSelectizeInput(session, "group1", choices = extended_choices,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "group2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Update PCA group selections (no variable comparisons - PCA is sample-based)
      updateSelectizeInput(session, "pcaGroup1", choices = values$unique_groups,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "pcaGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Update MA Plot group selections (include lmROTS/lmeROTS variables in group1)
      updateSelectizeInput(session, "maGroup1", choices = extended_choices,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "maGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Update Volcano Plot group selections (include lmROTS/lmeROTS variables in group1)
      updateSelectizeInput(session, "volcanoGroup1", choices = extended_choices,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "volcanoGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Update Differential Analysis tab group selections (include lmROTS/lmeROTS variables in group1)
      updateSelectizeInput(session, "diffGroup1", choices = extended_choices,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "diffGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Update ROC/PR Analysis group selections (no variable comparisons - ROC needs real groups)
      updateSelectizeInput(session, "rocGroup1", choices = values$unique_groups,
                           selected = values$unique_groups[1])
      updateSelectizeInput(session, "rocGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
    })
    
    # Set up intersection analysis options based on available comparisons
    output$intersection_set_selection <- renderUI({
      req(values$normalized_data)
      
      # Use pairwise combinations from the modal (if available)
      # Only show comparisons that were explicitly set by the user
      if (is.null(values$current_pairwise_combinations) || nrow(values$current_pairwise_combinations) == 0) {
        return(div(
          style = "padding: 15px; background-color: #fff3cd; border: 1px solid #ffc107; border-radius: 4px; margin: 10px 0;",
          icon("exclamation-triangle", style = "color: #856404; margin-right: 8px;"),
          span("No pairwise comparisons available. Please configure comparisons in the Statistical Analysis tab first.",
               style = "color: #856404;")
        ))
      }
      
      # Build comparisons from current_pairwise_combinations
      comparisons <- list()
      for (i in 1:nrow(values$current_pairwise_combinations)) {
        group1 <- values$current_pairwise_combinations[i, "Group_1"]
        group2 <- values$current_pairwise_combinations[i, "Group_2"]
        
        # Handle lmROTS/lmeROTS variable comparisons (marked with "[Variable]" in Group_2)
        if (group2 == "[Variable]") {
          comparison_name <- group1  # e.g., "lmROTS_Age"
        } else {
          comparison_name <- paste(group1, "vs", group2)
        }
        comparisons[[comparison_name]] <- list(group1 = group1, group2 = group2)
      }
      
      # Store comparisons for intersection analysis
      values$intersection_comparisons <- comparisons
      
      # Create checkboxes for each comparison
      comparison_names <- names(comparisons)
      
      # Default selection: select first few comparisons (capped at 5)
      default_selected <- comparison_names[1:min(5, length(comparison_names))]
      
      checkboxGroupInput("intersection_sets", "Select Comparisons",
                         choices = comparison_names,
                         selected = default_selected)
    })
    
    # Observer for adding intersection sets
    observeEvent(input$add_intersection_set, {
      values$intersection_paste_sets_count <- values$intersection_paste_sets_count + 1
    })
    
    # Observers for removing intersection sets (dynamic observers for each set)
    observe({
      num_sets <- values$intersection_paste_sets_count
      if(num_sets > 2) {  # Only create observers for sets that can be removed
        for(i in 3:num_sets) {
          local({
            local_i <- i
            observeEvent(input[[paste0("remove_intersection_set_", local_i)]], {
              # Remove the set by shifting all subsequent sets down
              values$intersection_paste_sets_count <- values$intersection_paste_sets_count - 1
              
              # Note: The UI will automatically update due to the reactive renderUI
              # The input values will be preserved for the remaining sets
            }, ignoreInit = TRUE)
          })
        }
      }
    })
    
    req(values$normalized_data, values$cleaned_molecules, values$unique_groups, values$group_column_indices)
    
    # ============================================================================
    # DUAL GROUPING ANALYSIS - Initialize tracking for first run
    # ============================================================================
    # If dual grouping is enabled and this is the first run (not a re-run),
    # mark it as biological analysis
    if (isTRUE(values$has_dual_grouping) && is.null(values$dual_analysis_current_level)) {
      # This is the first analysis run - use biological grouping
      values$dual_analysis_in_progress <- TRUE
      values$dual_analysis_current_level <- "biological"
      
      # Check if we have cached results for biological grouping
      cached_bio_results <- get_cached_dual_analysis("biological")
      cached_exp_results <- get_cached_dual_analysis("experimental")
      
      if (!is.null(cached_bio_results) && !is.null(cached_exp_results)) {
        # Both results are cached - use them directly
        showNotification("Using cached dual analysis results", type = "message", duration = 3)
        
        values$biological_stat_results <- cached_bio_results
        values$experimental_stat_results <- cached_exp_results
        
        # Set current results based on active level
        if (values$active_grouping_level == "biological") {
          values$stat_results <- cached_bio_results
          values$unique_groups <- values$biological_unique_groups
          values$group_column_indices <- values$biological_group_column_indices
          values$current_pairwise_combinations <- values$biological_pairwise_combinations
        } else {
          values$stat_results <- cached_exp_results
          values$unique_groups <- values$experimental_unique_groups
          values$group_column_indices <- values$experimental_group_column_indices
          values$current_pairwise_combinations <- values$experimental_pairwise_combinations
        }
        
        # Clear dual analysis flags
        values$dual_analysis_in_progress <- FALSE
        values$dual_analysis_current_level <- NULL
        
        # Show the Review Pairwise Order button
        shinyjs::show("reviewPairwiseOrderBtn")
        
        showNotification("Dual-level analysis loaded from cache! Use toggle buttons to switch views.", 
                         type = "message", duration = 5)
        return()  # Skip re-running analysis
      }
      
      # Check if only biological is cached
      if (!is.null(cached_bio_results)) {
        showNotification("Using cached Biological Groups results. Running Experimental Groups analysis...", 
                         type = "message", duration = 3)
        values$biological_stat_results <- cached_bio_results
        
        # Skip to experimental analysis
        values$dual_analysis_current_level <- "experimental"
        values$unique_groups <- values$experimental_unique_groups
        values$group_column_indices <- values$experimental_group_column_indices
        values$current_pairwise_combinations <- values$experimental_pairwise_combinations
      } else {
        # No cache - run biological analysis first
        # Ensure we're using biological grouping values
        if (!is.null(values$biological_unique_groups)) {
          values$unique_groups <- values$biological_unique_groups
          values$group_column_indices <- values$biological_group_column_indices
          if (!is.null(values$biological_pairwise_combinations)) {
            values$current_pairwise_combinations <- values$biological_pairwise_combinations
          }
        }
        
        showNotification("Dual grouping detected. Running analysis for Biological Groups first...", 
                         type = "message", duration = 4)
      }
    } else if (isTRUE(values$has_dual_grouping) && values$dual_analysis_current_level == "experimental") {
      # This is the experimental re-run - check cache first
      cached_exp_results <- get_cached_dual_analysis("experimental")
      
      if (!is.null(cached_exp_results)) {
        showNotification("Using cached Experimental Groups results", type = "message", duration = 3)
        values$experimental_stat_results <- cached_exp_results
        
        # Clear flags and restore active level
        values$dual_analysis_current_level <- NULL
        values$dual_analysis_in_progress <- FALSE
        
        # Restore based on active level
        if (values$active_grouping_level == "biological") {
          values$stat_results <- values$biological_stat_results
          values$unique_groups <- values$biological_unique_groups
          values$group_column_indices <- values$biological_group_column_indices
          values$current_pairwise_combinations <- values$biological_pairwise_combinations
        } else {
          values$stat_results <- cached_exp_results
          values$unique_groups <- values$experimental_unique_groups
          values$group_column_indices <- values$experimental_group_column_indices
          values$current_pairwise_combinations <- values$experimental_pairwise_combinations
        }
        
        shinyjs::show("reviewPairwiseOrderBtn")
        showNotification("Dual-level analysis complete (with cache)! Use toggle buttons to switch views.", 
                         type = "message", duration = 5)
        return()  # Skip re-running analysis
      }

      # No cached experimental results - ensure we analyze using experimental grouping
      if (!is.null(values$experimental_unique_groups)) {
        values$unique_groups <- values$experimental_unique_groups
        values$unique_groups_original <- values$experimental_unique_groups
      }
      if (!is.null(values$experimental_group_column_indices)) {
        values$group_column_indices <- values$experimental_group_column_indices
      }
      if (!is.null(values$experimental_pairwise_combinations) &&
          nrow(values$experimental_pairwise_combinations) > 0) {
        values$current_pairwise_combinations <- values$experimental_pairwise_combinations
      }
    }
    # ============================================================================
    # END DUAL GROUPING ANALYSIS INITIALIZATION
    # ============================================================================
    
    # Add check for single group case before trying to perform pairwise statistics
    if (length(values$unique_groups) == 1) {
      # For single-group datasets, create a simplified statistics table
      stat_results <- data.frame(
        Feature = values$cleaned_molecules,
        stringsAsFactors = FALSE
      )
      
      # Add ID column if available
      if (!is.null(values$accession_ids) &&
          length(values$accession_ids) == length(values$cleaned_molecules) &&
          !is.null(values$accession_id_column) &&
          is.numeric(values$accession_id_column) && length(values$accession_id_column) == 1 && values$accession_id_column > 0) {
        stat_results$ID <- values$accession_ids
      }
      
      # Add statistics
      stat_results$Group <- values$unique_groups[1]
      stat_results$Mean <- apply(values$normalized_data, 1, mean, na.rm = TRUE)
      stat_results$SD <- apply(values$normalized_data, 1, sd, na.rm = TRUE)
      stat_results$CV <- apply(values$normalized_data, 1, function(x) sd(x, na.rm = TRUE)/mean(x, na.rm = TRUE))
      
      values$stat_results <- merge_bootstrap_columns(stat_results)
      
      # Show notification about single group
      showNotification("Dataset contains only one group. Statistical analysis between groups is not available.",
                       type = "warning", duration = 10)
    } else {
      # Original code for statistical analysis between multiple groups
      # Create statistical results dataframe
      stat_results <- data.frame(
        Feature = values$cleaned_molecules,
        stringsAsFactors = FALSE
      )
      
      # Add ID column if available
      if (!is.null(values$accession_ids) &&
          length(values$accession_ids) == length(values$cleaned_molecules) &&
          !is.null(values$accession_id_column) &&
          is.numeric(values$accession_id_column) && length(values$accession_id_column) == 1 && values$accession_id_column > 0) {
        stat_results$ID <- values$accession_ids
      }
      
      # Check if bootstrap is enabled
      if (input$bootstrap_enabled == "yes") {
        message("  [ANALYSIS] bootstrap_enabled is YES, entering bootstrap code")
        # Show progress
        withProgress(message = "Calculating bootstrap statistics...", {
          # Get pairwise combinations to use (respects pre-analysis modal selection)
          pairwise_combinations <- get_pairwise_combinations_for_analysis()
          n_comparisons <- nrow(pairwise_combinations)
          
          # For pairwise comparisons, use bootstrap statistics
          for (comp_idx in seq_len(n_comparisons)) {
            group1 <- pairwise_combinations[comp_idx, "Group_1"]
            group2 <- pairwise_combinations[comp_idx, "Group_2"]
            comparison_name <- paste(group1, "vs", group2)
            
            setProgress(value = comp_idx / n_comparisons,
                        detail = paste("Processing", comparison_name))
            
            # Find group indices
            group1_idx <- which(values$unique_groups == group1)
            group2_idx <- which(values$unique_groups == group2)
            
            if (length(group1_idx) == 0 || length(group2_idx) == 0) {
              next  # Skip if groups not found
            }
            
            # Get data for each group
            group1_columns <- values$group_column_indices[[group1_idx]]
            group2_columns <- values$group_column_indices[[group2_idx]]
              
              # Create matrices to store bootstrap results
              n_features <- nrow(values$normalized_data)
              n_replicates <- input$bootstrap_replicates
              
              bootstrap_pvals <- matrix(NA, nrow = n_features, ncol = n_replicates)
              bootstrap_fcs <- matrix(NA, nrow = n_features, ncol = n_replicates)
              
              # Run bootstrap replicates
              for (b in 1:n_replicates) {
                # Resample with replacement
                sampled_group1_columns <- sample(group1_columns, length(group1_columns), replace = TRUE)
                sampled_group2_columns <- sample(group2_columns, length(group2_columns), replace = TRUE)
                
                # Calculate bootstrap p-values and fold changes for each feature
                for (f in 1:n_features) {
                  feature_data <- values$normalized_data[f, ]
                  
                  group1_data <- feature_data[sampled_group1_columns]
                  group2_data <- feature_data[sampled_group2_columns]
                  
                  # Remove NAs
                  group1_data <- group1_data[!is.na(group1_data)]
                  group2_data <- group2_data[!is.na(group2_data)]
                  
                  # Calculate p-value if we have enough data
                  if (length(group1_data) >= 2 && length(group2_data) >= 2) {
                    # Use the selected statistical test
                    if (input$sig_method == "wilcox") {
                      test_result <- tryCatch({
                        wilcox.test(group1_data, group2_data)$p.value
                      }, error = function(e) { NA })
                    } else if (input$sig_method == "t.test") {
                      test_result <- tryCatch({
                        t.test(group1_data, group2_data)$p.value
                      }, error = function(e) { NA })
                    } else if (input$sig_method == "kruskal") {
                      test_result <- tryCatch({
                        kruskal.test(list(group1_data, group2_data))$p.value
                      }, error = function(e) { NA })
                    } else {
                      test_result <- NA
                    }
                    
                    bootstrap_pvals[f, b] <- test_result
                    
                    # Calculate fold change as Group2/Group1
                    group1_mean <- mean(group1_data, na.rm = TRUE)
                    group2_mean <- mean(group2_data, na.rm = TRUE)
                    if (!is.na(group1_mean) && !is.na(group2_mean) && group1_mean > 0) {
                      bootstrap_fcs[f, b] <- group2_mean / group1_mean
                    }
                  }
                }
              }
              
              # Calculate bootstrap statistics
              conf_level <- as.numeric(input$bootstrap_ci)
              
              # Calculate median p-values and confidence intervals
              median_pvals <- apply(bootstrap_pvals, 1, median, na.rm = TRUE)
              lower_ci_pvals <- apply(bootstrap_pvals, 1, function(x) quantile(x, (1-conf_level)/2, na.rm = TRUE))
              upper_ci_pvals <- apply(bootstrap_pvals, 1, function(x) quantile(x, 1-(1-conf_level)/2, na.rm = TRUE))
              
              # Calculate median fold changes
              median_fcs <- apply(bootstrap_fcs, 1, median, na.rm = TRUE)
              log2_median_fcs <- log2(median_fcs)
              log2_median_fcs[is.infinite(log2_median_fcs)] <- NA
              
              # Store bootstrap results in stat_results
              stat_results[[paste0(comparison_name, "_Bootstrap_PValue")]] <- median_pvals
              stat_results[[paste0(comparison_name, "_Bootstrap_LowerCI")]] <- lower_ci_pvals
              stat_results[[paste0(comparison_name, "_Bootstrap_UpperCI")]] <- upper_ci_pvals
              stat_results[[paste0(comparison_name, "_Bootstrap_FoldChange")]] <- median_fcs
              stat_results[[paste0(comparison_name, "_Bootstrap_Log2FC")]] <- log2_median_fcs
              
              # Adjust bootstrap p-values
              bootstrap_adjusted_pvals <- p.adjust(median_pvals, method = get_correction_method())
              stat_results[[paste0(comparison_name, "_Bootstrap_AdjPValue")]] <- bootstrap_adjusted_pvals
            }
        })
      } else {
        # Use regular statistical testing when bootstrap is not enabled
        if (length(values$unique_groups) > 2 && input$sig_method == "anova") {
          # Check if covariates should be included (ANCOVA)
          use_covariates <- isTRUE(input$anova_include_covariates)
          covariates <- if (use_covariates) input$anova_covariates %||% NULL else NULL
          use_type3 <- if (use_covariates) isTRUE(input$anova_type3) else FALSE
          
          # Validate metadata if covariates are requested
          if (use_covariates && (is.null(covariates) || length(covariates) == 0)) {
            showNotification("Please select at least one adjustment variable for ANCOVA.", type = "error")
            return(NULL)
          }
          
          if (use_covariates && (is.null(values$metadata) || nrow(values$metadata) == 0)) {
            showNotification("ANCOVA requires sample metadata with covariates. Please upload data with a metadata sheet.", type = "error")
            return(NULL)
          }
          
          # Show progress
          progress_msg <- if (use_covariates) "Calculating ANCOVA statistics..." else "Calculating ANOVA statistics..."
          withProgress(message = progress_msg, value = 0, {
            
            # Prepare data matrix and metadata if using covariates
            if (use_covariates) {
              setProgress(0.05, detail = "Preparing metadata...")
              
              # Prepare data matrix
              data_matrix <- as.matrix(values$normalized_data)
              sample_names <- colnames(data_matrix)
              
              # Try to find matching column in metadata for sample IDs (following lmROTS pattern)
              meta_sample_col <- NULL
              for (col in colnames(values$metadata)) {
                if (tolower(col) %in% c("sampleid", "sample_id", "sample", "id")) {
                  meta_sample_col <- col
                  break
                }
              }
              
              if (is.null(meta_sample_col)) {
                if (!is.null(rownames(values$metadata)) && all(rownames(values$metadata) != seq_len(nrow(values$metadata)))) {
                  meta_samples <- rownames(values$metadata)
                } else {
                  meta_samples <- as.character(values$metadata[, 1])
                  meta_sample_col <- colnames(values$metadata)[1]
                }
              } else {
                meta_samples <- as.character(values$metadata[[meta_sample_col]])
              }
              
              # Match samples
              matched_idx <- match(sample_names, meta_samples)
              if (any(is.na(matched_idx))) {
                unmatched <- sample_names[is.na(matched_idx)]
                message("Warning: Some samples in data not found in metadata: ", paste(head(unmatched, 5), collapse = ", "))
                
                valid_samples <- !is.na(matched_idx)
                if (sum(valid_samples) < 3) {
                  showNotification("Too few matching samples between data and metadata. Please check sample naming.", type = "error")
                  return(NULL)
                }
                
                data_matrix <- data_matrix[, valid_samples, drop = FALSE]
                matched_idx <- matched_idx[valid_samples]
                sample_names <- sample_names[valid_samples]
              }
              
              # Reorder metadata to match data columns
              metadata_ordered <- values$metadata[matched_idx, , drop = FALSE]
              rownames(metadata_ordered) <- colnames(data_matrix)
              
              # Use auto-detected groups from column headers
              group_labels <- factor(create_proper_group_labels(values$unique_groups, values$group_column_indices))
              all_sample_indices <- unlist(values$group_column_indices)
              valid_sample_mask <- all_sample_indices %in% which(!is.na(match(colnames(values$normalized_data), sample_names)))
              if (sum(valid_sample_mask) < length(group_labels)) {
                group_labels <- group_labels[valid_sample_mask]
              }
              
              # Extract selected adjustment variables and infer variable types
              covariate_data <- metadata_ordered[, covariates, drop = FALSE]
              covariate_types <- setNames(rep("categorical", length(covariates)), covariates)

              for (col in colnames(covariate_data)) {
                raw_vals <- covariate_data[[col]]
                raw_chr <- trimws(as.character(raw_vals))
                raw_non_empty <- raw_chr[!is.na(raw_chr) & nzchar(raw_chr)]
                is_numeric_like <- is.numeric(raw_vals) ||
                  (length(raw_non_empty) > 0 && all(!is.na(suppressWarnings(as.numeric(raw_non_empty)))))

                if (is_numeric_like) {
                  covariate_data[[col]] <- suppressWarnings(as.numeric(raw_chr))
                  covariate_types[[col]] <- "numeric"
                } else {
                  raw_chr[raw_chr == ""] <- NA_character_
                  covariate_data[[col]] <- as.factor(raw_chr)
                  covariate_types[[col]] <- "categorical"
                }
              }
              
              # Check for missing values in covariates
              covariate_complete <- complete.cases(covariate_data)
              if (sum(covariate_complete) < length(group_labels)) {
                n_missing <- sum(!covariate_complete)
                showNotification(paste0("Warning: ", n_missing, " samples have missing covariate values and will be excluded."), 
                                 type = "warning", duration = 5)
                data_matrix <- data_matrix[, covariate_complete, drop = FALSE]
                group_labels <- group_labels[covariate_complete]
                covariate_data <- covariate_data[covariate_complete, , drop = FALSE]
              }
              
              # Track selected adjustment variable types for output metadata
              covariate_method_terms <- paste0(covariates, " [", unname(covariate_types[covariates]), "]")
              
              # For Type III SS, load car package
              if (use_type3) {
                if (!requireNamespace("car", quietly = TRUE)) {
                  install.packages("car")
                }
              }
              
              # For post-hoc EMMs, load emmeans package
              if (length(unique(group_labels)) > 2 && input$posthoc_method != "none") {
                if (!requireNamespace("emmeans", quietly = TRUE)) {
                  install.packages("emmeans")
                }
              }
            }
            
            # Prepare column to store ANOVA/ANCOVA p-values and adjusted p-values
            if (use_covariates) {
              stat_results$ANCOVA_PValue <- NA
              stat_results$ANCOVA_AdjustedPValue <- NA
              stat_results$ANCOVA_FStatistic <- NA
              stat_results$ANCOVA_Method <- paste0("ANCOVA with adjustment variables: ", paste(covariate_method_terms, collapse = ", "))
            } else {
              stat_results$ANOVA_PValue <- NA
              stat_results$ANOVA_AdjustedPValue <- NA
            }
            
            # Create a column to store post-hoc method used
            stat_results$PostHoc_Method <- ifelse(input$posthoc_method == "none", "N/A", input$posthoc_method)

            # Pre-create post-hoc columns for ANCOVA so downstream tabs/export always see expected fields.
            # Feature-level post-hoc assignment will fill these with p-values where available.
            if (use_covariates && input$posthoc_method != "none" && length(unique(group_labels)) > 1) {
              ancova_groups <- levels(as.factor(group_labels))
              if (length(ancova_groups) > 1) {
                ancova_pairs <- combn(ancova_groups, 2, simplify = FALSE)
                for (pair in ancova_pairs) {
                  pair_name <- paste0(pair[1], "_vs_", pair[2])
                  col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                  if (!(col_name %in% colnames(stat_results))) {
                    stat_results[[col_name]] <- NA_real_
                  }
                }
              }
            }
            
            # Loop through each feature
            n_features <- if (use_covariates) nrow(data_matrix) else length(values$cleaned_molecules)
            for (i in 1:n_features) {
              setProgress(0.1 + (0.8 * i / n_features),
                          detail = paste("Analyzing feature", i, "of", n_features))
              
              if (use_covariates) {
                # ANCOVA implementation
                tryCatch({
                  # Prepare data frame for this feature
                  feature_values <- as.numeric(data_matrix[i, ])
                  
                  # Skip if insufficient non-NA values
                  if (sum(!is.na(feature_values)) < 3) next
                  
                  ancova_df <- data.frame(
                    feature_value = feature_values,
                    Group = group_labels
                  )
                  # Add covariate columns
                  for (cov in covariates) {
                    ancova_df[[cov]] <- covariate_data[[cov]]
                  }
                  
                  # Remove rows with NA
                  ancova_df <- ancova_df[complete.cases(ancova_df), ]
                  
                  if (nrow(ancova_df) < 3) next
                  
                  ancova_df$Group <- droplevels(as.factor(ancova_df$Group))
                  if (nlevels(ancova_df$Group) < 2) next

                  # Keep only informative covariates after NA filtering
                  valid_covariates <- c()
                  for (cov in covariates) {
                    if (!(cov %in% colnames(ancova_df))) next
                    cov_vals <- ancova_df[[cov]]

                    if (is.factor(cov_vals)) {
                      ancova_df[[cov]] <- droplevels(cov_vals)
                      if (nlevels(ancova_df[[cov]]) >= 2) {
                        valid_covariates <- c(valid_covariates, cov)
                      }
                    } else {
                      if (length(unique(cov_vals[!is.na(cov_vals)])) >= 2) {
                        valid_covariates <- c(valid_covariates, cov)
                      }
                    }
                  }

                  # Fit ANCOVA model using robust term construction (handles spaces/special chars)
                  ancova_formula <- stats::reformulate(
                    termlabels = c("Group", valid_covariates),
                    response = "feature_value"
                  )
                  ancova_model <- lm(ancova_formula, data = ancova_df)
                  
                  # Extract p-value for Group effect
                  if (use_type3) {
                    # Type III SS using car::Anova
                    type3_result <- car::Anova(ancova_model, type = 3)
                    group_row <- which(rownames(type3_result) == "Group")
                    if (length(group_row) > 0) {
                      stat_results$ANCOVA_PValue[i] <- type3_result[group_row, "Pr(>F)"]
                      stat_results$ANCOVA_FStatistic[i] <- type3_result[group_row, "F value"]
                    }
                  } else {
                    # Type II SS (default anova)
                    anova_result <- anova(ancova_model)
                    group_row <- which(rownames(anova_result) == "Group")
                    if (length(group_row) > 0) {
                      stat_results$ANCOVA_PValue[i] <- anova_result[group_row, "Pr(>F)"]
                      stat_results$ANCOVA_FStatistic[i] <- anova_result[group_row, "F value"]
                    }
                  }
                  
                  # Post-hoc on estimated marginal means (EMMs) = covariate-adjusted group means.
                  # All ANCOVA post-hoc tests use EMMs, not raw means, so comparisons are conditional on the covariates.
                  if (input$posthoc_method != "none" && 
                      !is.na(stat_results$ANCOVA_PValue[i]) && stat_results$ANCOVA_PValue[i] < 0.05) {
                    
                    tryCatch({
                      emm <- emmeans::emmeans(ancova_model, "Group")
                      
                      if (input$posthoc_method == "dunnett") {
                        # Dunnett: each group vs reference (first level), on EMMs
                        dunnett_contr <- emmeans::contrast(emm, method = "trt.vs.ctrl")
                        dunnett_summary <- summary(dunnett_contr, adjust = "dunnett")
                        pairs_summary <- dunnett_summary
                      } else {
                        # Tukey, Bonferroni, Holm, Sidak, BH, Scheffé; Games-Howell not defined for EMMs -> use Tukey
                        adjust_method <- switch(input$posthoc_method,
                                                "tukey" = "tukey",
                                                "bonferroni" = "bonferroni",
                                                "holm" = "holm",
                                                "sidak" = "sidak",
                                                "BH" = "BH",
                                                "scheffe" = "scheffe",
                                                "tukey")
                        pairs_result <- pairs(emm, adjust = adjust_method)
                        pairs_summary <- summary(pairs_result)
                      }
                      
                      for (j in seq_len(nrow(pairs_summary))) {
                        contrast_name <- as.character(pairs_summary$contrast[j])
                        pair_name <- gsub(" - ", "_vs_", contrast_name)
                        pair_name <- gsub("^Group", "", pair_name)
                        pair_name <- gsub("_vs_Group", "_vs_", pair_name)
                        
                        col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                        if (!(col_name %in% colnames(stat_results))) {
                          stat_results[[col_name]] <- NA
                        }
                        stat_results[i, col_name] <- pairs_summary$p.value[j]
                      }
                    }, error = function(e) {
                      message("Post-hoc failed for feature ", i, ": ", e$message)
                    })
                  }
                  
                }, error = function(e) {
                  message("Error in ANCOVA for feature ", i, ": ", e$message)
                })
              } else {
                # Standard ANOVA implementation
                # Get all data for this feature across groups
                feature_data <- list()
                for (g in 1:length(values$unique_groups)) {
                  group_cols <- values$group_column_indices[[g]]
                  feature_data[[g]] <- as.numeric(values$normalized_data[i, group_cols])
                }
                
                # Remove NAs and check if enough data
                feature_data <- lapply(feature_data, function(x) x[!is.na(x)])
                if (any(sapply(feature_data, length) < 2)) next
                
                # Run ANOVA
                tryCatch({
                  anova_data <- unlist(feature_data)
                  anova_groups <- rep(values$unique_groups, sapply(feature_data, length))
                  anova_result <- summary(aov(anova_data ~ anova_groups))
                  stat_results$ANOVA_PValue[i] <- anova_result[[1]]$`Pr(>F)`[1]
                # Run post-hoc test if ANOVA is significant AND posthoc_method is not "none"
                if (stat_results$ANOVA_PValue[i] < 0.05 && input$posthoc_method != "none") {
                  # Create a data frame for post-hoc tests
                  posthoc_df <- data.frame(
                    value = anova_data,
                    group = factor(anova_groups)
                  )
                  
                  # Run selected post-hoc test
                  
                  posthoc_result <- switch(
                    input$posthoc_method,
                    "tukey" = {
                      if (!requireNamespace("multcomp", quietly = TRUE)) {
                        install.packages("multcomp")
                        library(multcomp)
                      }
                      tryCatch({
                        model <- aov(value ~ group, data = posthoc_df)
                        tukey <- multcomp::glht(model, linfct = multcomp::mcp(group = "Tukey"))
                        tukey_summary <- summary(tukey)
                        
                        # Extract p-values and comparison names
                        pairwise_p <- tukey_summary$test$pvalues
                        comparison_names <- rownames(tukey_summary$linfct)
                        # Clean up comparison names - multcomp uses different format
                        names(pairwise_p) <- gsub(" - ", "_vs_", comparison_names)
                        
                        # Store all pairwise p-values as separate columns
                        for (pair_name in names(pairwise_p)) {
                          col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                          if (!(col_name %in% colnames(stat_results))) {
                            stat_results[[col_name]] <- NA
                          }
                          stat_results[i, col_name] <- pairwise_p[pair_name]
                        }
                        pairwise_p
                      }, error = function(e) {                # Fallback to TukeyHSD if multcomp fails
                        tryCatch({
                          model <- aov(value ~ group, data = posthoc_df)
                          tukey_result <- TukeyHSD(model)
                          p_values <- tukey_result$group[, "p adj"]
                          names(p_values) <- gsub("-", "_vs_", names(p_values))
                          
                          # Store all pairwise p-values as separate columns
                          for (pair_name in names(p_values)) {
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[pair_name]
                          }
                          p_values
                        }, error = function(e2) {
                          showNotification(paste("Tukey HSD failed:", e2$message), type = "warning")
                          NULL
                        })
                      })
                    },
                    "bonferroni" = {
                      pw_result <- pairwise.t.test(posthoc_df$value, posthoc_df$group,
                                                   p.adjust.method = "bonferroni")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },
                    "holm" = {
                      pw_result <- pairwise.t.test(posthoc_df$value, posthoc_df$group,
                                                   p.adjust.method = "holm")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },
                    "BH" = {
                      pw_result <- pairwise.t.test(posthoc_df$value, posthoc_df$group,
                                                   p.adjust.method = "BH")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },
                    "sidak" = {
                      pw_result <- pairwise.t.test(posthoc_df$value, posthoc_df$group,
                                                   p.adjust.method = "none")
                      p_values <- pw_result$p.value
                      
                      # Apply Sidak adjustment manually
                      n_comparisons <- sum(!is.na(p_values))
                      if (n_comparisons > 0) {
                        # Sidak adjustment: p_adj = 1 - (1 - p)^n
                        p_values <- 1 - (1 - p_values)^n_comparisons
                        p_values[p_values > 1] <- 1  # Cap at 1
                      }
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },
                    "dunnett" = {
                      if (!requireNamespace("multcomp", quietly = TRUE)) {
                        showNotification("multcomp package required for Dunnett's test", type = "warning")
                        NULL
                      } else {
                        tryCatch({
                          model <- aov(value ~ group, data = posthoc_df)
                          # For Dunnett's test, the first level is typically the control
                          # Ensure groups are factors with proper levels
                          posthoc_df$group <- factor(posthoc_df$group)
                          model <- aov(value ~ group, data = posthoc_df)
                          dunnett_test <- multcomp::glht(model, linfct = multcomp::mcp(group = "Dunnett"))
                          dunnett_summary <- summary(dunnett_test)
                          
                          # Extract p-values and comparison names
                          pairwise_p <- dunnett_summary$test$pvalues
                          comparison_names <- rownames(dunnett_summary$linfct)
                          
                          # Clean up comparison names
                          names(pairwise_p) <- gsub(" - ", "_vs_", comparison_names)
                          
                          # Store all pairwise p-values as separate columns
                          for (pair_name in names(pairwise_p)) {
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- pairwise_p[pair_name]
                          }
                          pairwise_p
                        }, error = function(e) {
                          showNotification(paste("Dunnett's test failed:", e$message), type = "warning")
                          NULL
                        })
                      }
                    },
                    "scheffe" = {
                      if (!requireNamespace("agricolae", quietly = TRUE)) {
                        showNotification("agricolae package required for Scheff 's test", type = "warning")
                        NULL
                      } else {
                        tryCatch({
                          model <- aov(value ~ group, data = posthoc_df)
                          scheffe_result <- agricolae::scheffe.test(model, "group", alpha = 0.05)
                          
                          # Extract p-values from scheffe result - agricolae has different structure
                          if ("groups" %in% names(scheffe_result) && "comparison" %in% names(scheffe_result)) {
                            # Try to get pairwise comparisons
                            comparisons <- scheffe_result$comparison
                            if (is.data.frame(comparisons) && "pvalue" %in% colnames(comparisons)) {
                              p_values <- comparisons$pvalue
                              names(p_values) <- gsub(" - ", "_vs_", rownames(comparisons))
                            } else {
                              # Fallback: perform manual pairwise Scheff  comparisons
                              group_levels <- levels(posthoc_df$group)
                              n_groups <- length(group_levels)
                              comparisons_list <- list()
                              p_values <- numeric()
                              names_list <- character()
                              
                              for (i in 1:(n_groups-1)) {
                                for (j in (i+1):n_groups) {
                                  group1_data <- posthoc_df$value[posthoc_df$group == group_levels[i]]
                                  group2_data <- posthoc_df$value[posthoc_df$group == group_levels[j]]
                                  
                                  # Perform Scheff  test manually using F-statistic
                                  n1 <- length(group1_data)
                                  n2 <- length(group2_data)
                                  mean_diff <- mean(group1_data, na.rm = TRUE) - mean(group2_data, na.rm = TRUE)
                                  
                                  # Get MSE from ANOVA
                                  mse <- summary(model)[[1]]["Residuals", "Mean Sq"]
                                  se_diff <- sqrt(mse * (1/n1 + 1/n2))
                                  
                                  # Scheff  critical value
                                  f_stat <- (mean_diff / se_diff)^2
                                  df1 <- n_groups - 1
                                  df2 <- summary(model)[[1]]["Residuals", "Df"]
                                  critical_f <- (df1) * qf(0.95, df1, df2)
                                  
                                  p_val <- 1 - pf(f_stat / df1, df1, df2)
                                  
                                  p_values <- c(p_values, p_val)
                                  names_list <- c(names_list, paste0(group_levels[i], "_vs_", group_levels[j]))
                                }
                              }
                              names(p_values) <- names_list
                            }
                          } else {
                            # Alternative approach - use pairwise comparisons with Scheff  adjustment
                            group_levels <- levels(posthoc_df$group)
                            n_groups <- length(group_levels)
                            p_values <- numeric()
                            names_list <- character()
                            
                            for (i in 1:(n_groups-1)) {
                              for (j in (i+1):n_groups) {
                                group1_data <- posthoc_df$value[posthoc_df$group == group_levels[i]]
                                group2_data <- posthoc_df$value[posthoc_df$group == group_levels[j]]
                                
                                # Simple t-test and then apply Scheff  correction
                                t_result <- t.test(group1_data, group2_data)
                                raw_p <- t_result$p.value
                                
                                # Scheff  adjustment: multiply by (k-1) where k is number of groups
                                scheffe_p <- min(1, raw_p * (n_groups - 1))
                                
                                p_values <- c(p_values, scheffe_p)
                                names_list <- c(names_list, paste0(group_levels[i], "_vs_", group_levels[j]))
                              }
                            }
                            names(p_values) <- names_list
                          }
                          
                          # Store all pairwise p-values as separate columns
                          for (pair_name in names(p_values)) {
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[pair_name]
                          }
                          p_values
                        }, error = function(e) {
                          showNotification(paste("Scheff 's test failed:", e$message), type = "warning")
                          NULL
                        })
                      }
                    },
                    "games_howell" = {
                      if (!requireNamespace("PMCMRplus", quietly = TRUE)) {
                        showNotification("PMCMRplus package required for Games-Howell test", type = "warning")
                        NULL
                      } else {
                        gh_result <- PMCMRplus::gamesHowellTest(posthoc_df$value, posthoc_df$group)
                        p_values <- gh_result$p.value

                        # Convert matrix to named vector for storage
                        for (row_idx in 1:nrow(p_values)) {
                          for (col_idx in 1:ncol(p_values)) {
                            if (!is.na(p_values[row_idx, col_idx])) {
                              pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                              col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                              if (!(col_name %in% colnames(stat_results))) {
                                stat_results[[col_name]] <- NA
                              }
                              stat_results[i, col_name] <- p_values[row_idx, col_idx]
                            }
                          }
                        }
                        p_values
                      }
                    },
                    # Default to Tukey if something goes wrong
                    {
                      if (!requireNamespace("multcomp", quietly = TRUE)) {
                        install.packages("multcomp")
                        library(multcomp)
                      }
                      tryCatch({
                        model <- aov(value ~ group, data = posthoc_df)
                        tukey <- multcomp::glht(model, linfct = multcomp::mcp(group = "Tukey"))
                        tukey_summary <- summary(tukey)
                        
                        # Extract p-values and comparison names
                        pairwise_p <- tukey_summary$test$pvalues
                        comparison_names <- rownames(tukey_summary$linfct)
                        
                        # Clean up comparison names
                        names(pairwise_p) <- gsub(" - ", "_vs_", comparison_names)
                        # Store all pairwise p-values as separate columns
                        for (pair_name in names(pairwise_p)) {
                          col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                          if (!(col_name %in% colnames(stat_results))) {
                            stat_results[[col_name]] <- NA
                          }
                          stat_results[i, col_name] <- pairwise_p[pair_name]
                        }
                        pairwise_p
                      }, error = function(e) {
                        # Final fallback to base TukeyHSD
                        tryCatch({
                          model <- aov(value ~ group, data = posthoc_df)
                          tukey_result <- TukeyHSD(model)
                          p_values <- tukey_result$group[, "p adj"]
                          names(p_values) <- gsub("-", "_vs_", names(p_values))
                          # Store all pairwise p-values as separate columns
                          for (pair_name in names(p_values)) {
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[pair_name]
                          }
                          p_values
                        }, error = function(e2) {
                          showNotification("All post-hoc test methods failed", type = "error")
                          NULL
                        })
                      })
                    }
                  )
                }
              }, error = function(e) {
                message("Error in ANOVA for feature ", values$cleaned_molecules[i], ": ", e$message)
              })
            }
            }
            
            # Adjust p-values using BH correction for omnibus ANOVA/ANCOVA test
            if (use_covariates) {
              stat_results$ANCOVA_AdjustedPValue <- p.adjust(stat_results$ANCOVA_PValue,
                                                            method = "BH")
            } else {
              stat_results$ANOVA_AdjustedPValue <- p.adjust(stat_results$ANOVA_PValue,
                                                            method = "BH")
            }
            stat_results <- add_posthoc_fold_changes(stat_results)
            
            # Show completion notification
            if (use_covariates) {
              sig_count <- sum(stat_results$ANCOVA_AdjustedPValue < 0.05, na.rm = TRUE)
              showNotification(
                HTML(paste0("<b>ANCOVA analysis complete!</b><br>",
                          "Covariates: ", paste(covariates, collapse = ", "), "<br>",
                          "Significant features (FDR < 0.05): ", sig_count)),
                type = "message",
                duration = 8
              )
            }
          })
        }
        else if (length(values$unique_groups) > 1 && input$sig_method == "limma") {
          withProgress(message = "Calculating Limma statistics...", {
            expr_matrix <- as.matrix(values$normalized_data)
            rownames(expr_matrix) <- make.unique(values$cleaned_molecules)
            # Create design matrix for limma
            group_factors <- factor(create_proper_group_labels(values$unique_groups, values$group_column_indices))
            design <- model.matrix(~0 + group_factors)
            colnames(design) <- make.names(levels(group_factors))
            
            # Fit the linear model
            setProgress(0.3, detail = "Fitting linear models...")
            fit <- limma::lmFit(expr_matrix, design)
            limma_trend_param <- if (input$limma_trend == "auto") TRUE else as.logical(input$limma_trend)
            limma_robust_param <- isTRUE(input$limma_robust)
            
            # Create column to store limma results
            stat_results$Limma_Method <- "Linear Models for Microarray/RNA-Seq Data"
            
            # Add the global F-test across all groups
            if (length(values$unique_groups) > 2) {
              # Run global F-test across all groups
              setProgress(0.5, detail = "Calculating global F-test...")
              
              # Apply eBayes with error handling
              f_test <- tryCatch({
                limma::eBayes(fit, robust = limma_robust_param, trend = limma_trend_param)
              }, error = function(e) {
                # Handle the error gracefully
                showNotification(paste("Error in limma::eBayes: ",
                                       " Skipping global F-test. This is often due to excessive missing values in the dataset. Please remove rows with excessive missing values or perform imputation."),
                                 type = "error", duration = 10)
                return(NULL)
              })
              
              # If eBayes was successful, extract and add results
              if (!is.null(f_test)) {
                # Extract the global F-test p-values
                global_results <- limma::topTable(f_test, number = Inf, sort.by = "none")
                
                # Add global F-test p-values to stat_results
                stat_results$Limma_Global_PValue <- global_results$P.Value
                stat_results$Limma_Global_AdjPValue <- global_results$adj.P.Val
                stat_results$Limma_Global_FStatistic <- global_results$F
                
                # Add additional identifiers to make clear these are global tests
                stat_results$Limma_Global_Test <- "ANOVA-like F-test across all groups"
              } else {
                # If eBayes failed, add NA columns
                stat_results$Limma_Global_PValue <- NA
                stat_results$Limma_Global_AdjPValue <- NA
                stat_results$Limma_Global_FStatistic <- NA
                stat_results$Limma_Global_Test <- "ANOVA-like F-test across all groups"
              }
            }
            
            # Continue with pairwise comparisons
            setProgress(0.7, detail = "Calculating pairwise contrasts...")
            
            # Resolve contrast type and build comparison list
            contrast_type <- input$limma_contrast_type %||% "pairwise"
            if (contrast_type == "all_vs_reference") {
              ref <- input$limma_reference_group
              ug <- values$unique_groups
              if (!length(ref) || !ref %in% ug) ref <- ug[1]
              others <- setdiff(ug, ref)
              pairwise_combinations <- if (length(others) > 0) {
                data.frame(Group_1 = ref, Group_2 = others, stringsAsFactors = FALSE)
              } else {
                data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
              }
            } else {
              pairwise_combinations <- get_pairwise_combinations_for_analysis()
            }
            
            if (nrow(pairwise_combinations) > 0) {
              setProgress(0.5, detail = "Calculating pairwise comparisons...")
              contrast_formulas <- character()
              comparison_names <- character()
              for (comp_idx in seq_len(nrow(pairwise_combinations))) {
                group1 <- pairwise_combinations[comp_idx, "Group_1"]
                group2 <- pairwise_combinations[comp_idx, "Group_2"]
                comparison_names <- c(comparison_names, paste(group1, "vs", group2))
                contrast_formulas <- c(contrast_formulas,
                  paste0(make.names(group2), "-", make.names(group1)))
              }
              contrast_matrix <- limma::makeContrasts(
                contrasts = contrast_formulas,
                levels = design
              )
              contrast_fit <- limma::contrasts.fit(fit, contrast_matrix)
              contrast_fit <- tryCatch({
                limma::eBayes(contrast_fit, robust = limma_robust_param, trend = limma_trend_param)
              }, error = function(e) {
                showNotification(paste("Error in limma::eBayes (pairwise): ", e$message,
                                       " Skipping pairwise comparisons. This is often due to excessive missing values. Please remove rows with excessive missing values or perform imputation."),
                                 type = "error", duration = 10)
                return(NULL)
              })
              if (!is.null(contrast_fit)) {
                n_comparisons <- length(comparison_names)
                for (comp_idx in seq_len(n_comparisons)) {
                  setProgress(0.6 + (comp_idx / n_comparisons) * 0.3,
                              detail = paste("Processing comparison", comp_idx))
                  comparison_name <- comparison_names[comp_idx]
                  limma_results <- limma::topTable(contrast_fit, coef = comp_idx, number = Inf, sort.by = "none")
                  stat_results[[paste0(comparison_name, "_PValue")]] <- limma_results$P.Value
                  stat_results[[paste0(comparison_name, "_AdjPValue")]] <- limma_results$adj.P.Val
                  stat_results[[paste0(comparison_name, "_Log2FC")]] <- limma_results$logFC
                }
              } else {
                for (comparison_name in comparison_names) {
                  stat_results[[paste0(comparison_name, "_PValue")]] <- NA
                  stat_results[[paste0(comparison_name, "_AdjPValue")]] <- NA
                  stat_results[[paste0(comparison_name, "_Log2FC")]] <- NA
                }
              }
            }
            
            # Add extra metadata for limma results
            stat_results$Limma_Parameter_Trend <- limma_trend_param
            stat_results$Limma_Parameter_Robust <- limma_robust_param
            
            # Store the statistical results
            values$stat_results <- merge_bootstrap_columns(stat_results)
          })
        }
        else if (length(values$unique_groups) > 1 && input$sig_method == "deseq2") {
          withProgress(message = "Calculating DESeq2 statistics...", {
            # Check if DESeq2 is available
            if (!requireNamespace("DESeq2", quietly = TRUE)) {
              showNotification("DESeq2 package is required but not available. Please install it from Bioconductor.",
                               type = "error", duration = 10)
              return()
            }
            
            # Check if required data is available
            if (is.null(values$raw_data) || is.null(values$cleaned_molecules)) {
              showNotification("No data available for DESeq2 analysis. Please process your data first.",
                               type = "error", duration = 10)
              return()
            }
            
            # Additional data validation
            if (nrow(values$raw_data) == 0) {
              showNotification("No features available for DESeq2 analysis. Data may have been completely filtered out.",
                               type = "error", duration = 10)
              return()
            }
            
            if (ncol(values$raw_data) == 0) {
              showNotification("No samples available for DESeq2 analysis. Data may have been completely filtered out.",
                               type = "error", duration = 10)
              return()
            }
            
            # Check for excessive missing values
            missing_proportion <- sum(is.na(values$raw_data)) / (nrow(values$raw_data) * ncol(values$raw_data))
            if (missing_proportion > 0.9) {
              showNotification(paste("Warning: High proportion of missing values (",
                                     round(missing_proportion * 100, 1),
                                     "%) in raw data. DESeq2 analysis may fail."),
                               type = "warning", duration = 8)
            }
            
            # Inform user that DESeq2 uses raw count data
            showNotification("DESeq2 analysis using raw count data (before normalization) with internal DESeq2 normalization.",
                             type = "message", duration = 5)
            
            # Initialize statistical results dataframe
            stat_results <- data.frame(
              Feature = values$cleaned_molecules,
              stringsAsFactors = FALSE
            )
            # Make rownames unique to avoid duplicate rownames error
            rownames(stat_results) <- make.unique(values$cleaned_molecules)
            
            # Prepare count matrix - DESeq2 expects integer counts from RAW data (not normalized)
            count_matrix <- tryCatch({
              # Use RAW data for DESeq2 - it will perform its own normalization
              if (is.null(values$raw_data)) {
                stop("Raw data is NULL")
              }
              
              # Check raw data dimensions
              cat("Debug: Raw data dimensions:", dim(values$raw_data), "\n")
              cat("Debug: Raw data class:", class(values$raw_data), "\n")
              cat("Debug: Raw data typeof:", typeof(values$raw_data), "\n")
              
              if (nrow(values$raw_data) == 0 || ncol(values$raw_data) == 0) {
                stop("Raw data matrix has zero dimensions: ", nrow(values$raw_data), " x ", ncol(values$raw_data))
              }
              
              # Use only numeric sample columns; drop first column if it contains feature labels
              raw_df_for_counts <- values$raw_data
              if (ncol(raw_df_for_counts) > 1) {
                first_col_name <- colnames(raw_df_for_counts)[1]
                if (!is.numeric(raw_df_for_counts[[1]]) || first_col_name %in% c("Feature","Molecule","Gene","ID")) {
                  raw_df_for_counts <- raw_df_for_counts[, -1, drop = FALSE]
                }
              }
              temp_matrix <- as.matrix(raw_df_for_counts)
              cat("Debug: Converted matrix dimensions:", dim(temp_matrix), "\n")
              cat("Debug: Matrix class:", class(temp_matrix), "\n")
              cat("Debug: Matrix nrow:", nrow(temp_matrix), "\n")
              cat("Debug: Matrix ncol:", ncol(temp_matrix), "\n")
              
              # Check for non-numeric values
              if (!is.numeric(temp_matrix)) {
                stop("Raw data contains non-numeric values. Matrix type: ", typeof(temp_matrix))
              }
              
              # Validate matrix dimensions are proper numbers
              n_rows <- nrow(temp_matrix)
              n_cols <- ncol(temp_matrix)
              
              if (is.null(n_rows) || is.null(n_cols) || !is.numeric(n_rows) || !is.numeric(n_cols)) {
                stop("Matrix dimensions are invalid. nrow: ", n_rows, ", ncol: ", n_cols)
              }
              
              if (n_rows == 0 || n_cols == 0) {
                stop("Matrix has zero dimensions: ", n_rows, " x ", n_cols)
              }
              
              # IMPORTANT: Avoid using pmax/round here because they drop matrix dims.
              # Clamp negatives in-place to preserve dimensions
              if (any(temp_matrix < 0, na.rm = TRUE)) {
                neg_before <- sum(temp_matrix < 0, na.rm = TRUE)
                temp_matrix[temp_matrix < 0] <- 0
                cat("Debug: Replaced ", neg_before, " negative values with 0 (pre int conversion)\n", sep="")
              }
              # Defer rounding to the protected integer conversion block below to keep a single rounding step
              
              # Convert to integer matrix - simplified defensive approach
              tryCatch({
                orig_dims <- dim(temp_matrix)
                if (is.null(orig_dims) || length(orig_dims) != 2) {
                  # Attempt fallback reconstruction if dimensions dropped (e.g., accidental vector coercion)
                  vec_len <- length(temp_matrix)
                  if (!is.null(n_rows) && !is.null(n_cols) && n_rows * n_cols == vec_len) {
                    cat("Debug: Fallback reconstructing matrix with dims ", n_rows, "x", n_cols, " from length ", vec_len, "\n", sep="")
                    temp_matrix <- matrix(temp_matrix, nrow = n_rows, ncol = n_cols, byrow = FALSE)
                    orig_dims <- dim(temp_matrix)
                  } else {
                    stop("Input object lost dimensions before conversion")
                  }
                }
                orig_rownames <- rownames(temp_matrix)
                orig_colnames <- colnames(temp_matrix)
                
                cat("Debug(DESeq2 count prep): pre-int class=", paste(class(temp_matrix), collapse=","),
                    " typeof=", typeof(temp_matrix),
                    " dims=", paste(orig_dims, collapse="x"), "\n", sep="")
                
                # If somehow not numeric (should already be), attempt coercion safely
                if (!is.numeric(temp_matrix)) {
                  cat("Debug: Non-numeric matrix encountered; coercing columns to numeric\n")
                  suppressWarnings({
                    temp_matrix <- apply(temp_matrix, 2, function(col) {
                      if (is.factor(col)) col <- as.character(col)
                      out <- suppressWarnings(as.numeric(col))
                      out
                    })
                  })
                  temp_matrix <- as.matrix(temp_matrix)
                }
                
                # Replace non-finite values
                nf <- which(!is.finite(temp_matrix))
                if (length(nf) > 0) {
                  temp_matrix[nf] <- 0
                  cat("Debug: Replaced ", length(nf), " non-finite values with 0\n", sep="")
                }
                
                # Zero any negatives (counts cannot be negative)
                negN <- sum(temp_matrix < 0, na.rm = TRUE)
                if (negN > 0) {
                  temp_matrix[temp_matrix < 0] <- 0
                  cat("Debug: Set ", negN, " negative entries to 0\n", sep="")
                }
                
                # Round and convert in-place
                temp_matrix <- round(temp_matrix, 0)
                storage.mode(temp_matrix) <- "integer"
                
                # Restore names (apply may drop them)
                if (!is.null(orig_rownames)) rownames(temp_matrix) <- orig_rownames
                if (!is.null(orig_colnames)) colnames(temp_matrix) <- orig_colnames
                
                new_dims <- dim(temp_matrix)
                if (is.null(new_dims) || any(new_dims != orig_dims)) {
                  stop("Dimension mismatch after integer coercion. Original: ",
                       paste(orig_dims, collapse="x"), " Current: ", paste(new_dims, collapse="x"))
                }
                if (!is.integer(temp_matrix)) {
                  stop("Post-conversion matrix is not integer mode")
                }
                cat("Debug: Integer conversion OK dims=", paste(new_dims, collapse="x"), "\n", sep="")
              }, error = function(e) {
                stop("Failed to convert to integer matrix: ", e$message,
                     ". Matrix dims: ", n_rows, "x", n_cols)
              })
              
              if (nrow(temp_matrix) == 0 || ncol(temp_matrix) == 0) {
                stop("Processed matrix has zero dimensions: ", nrow(temp_matrix), " x ", ncol(temp_matrix))
              }
              
              # Additional validation for DESeq2 requirements
              if (any(is.na(temp_matrix))) {
                showNotification("Warning: NA values found in count matrix. DESeq2 may fail.",
                                 type = "warning", duration = 5)
              }
              
              temp_matrix
            }, error = function(e) {
              showNotification(paste("Error creating count matrix for DESeq2:", e$message),
                               type = "error", duration = 10)
              return(NULL)
            })
            
            if (is.null(count_matrix)) return()
            
            # Set rownames after confirming matrix is valid
            rownames(count_matrix) <- make.unique(values$cleaned_molecules)
            
            # Check for negative values and warn user
            if (any(values$raw_data < 0, na.rm = TRUE)) {
              showNotification("Warning: DESeq2 expects non-negative count data. Negative values have been set to 0.",
                               type = "warning", duration = 8)
            }
            
            # Create sample metadata (condition + optional batch)
            sample_groups <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
            sample_metadata <- data.frame(
              condition = factor(sample_groups),
              row.names = colnames(count_matrix)
            )
            
            # Attach batch column from metadata when enabled and available
            use_batch_in_deseq2 <- FALSE
            if (identical(input$batch_correction_enabled, "yes")) {
              sample_names <- colnames(count_matrix)
              batch_vec <- NULL
              
              cat("Debug: DESeq2 batch alignment attempt\n")
              cat("Debug: Sample names from count_matrix:", paste(sample_names[1:min(5, length(sample_names))], collapse=", "), "...\n")
              cat("Debug: values$batch_info length:", if(!is.null(values$batch_info)) length(values$batch_info) else "NULL", "\n")
              
              # 1) If a pre-aligned batch vector exists, use it (same logic as batch correction)
              if (!is.null(values$batch_info) && length(values$batch_info) == length(sample_names)) {
                batch_vec <- values$batch_info
                cat("Debug: Using pre-aligned values$batch_info\n")
              }
              
              # 2) If batch correction works via position matching (not name matching), do the same
              if (is.null(batch_vec) && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                md <- values$metadata
                batch_column_data <- md[[input$batch_column]]
                if (length(batch_column_data) == length(sample_names)) {
                  batch_vec <- batch_column_data
                  cat("Debug: Using position-based batch alignment (same as batch correction)\n")
                }
              }
              
              # 3) Try metadata ID/batch column mapping
              if (is.null(batch_vec) && !is.null(values$metadata)) {
                md <- values$metadata
                id_col_name <- NULL
                batch_col_name <- NULL
                # Prefer explicit selections from the UI when present
                if (!is.null(input$metadata_id_col) && nzchar(input$metadata_id_col) && input$metadata_id_col %in% colnames(md)) {
                  id_col_name <- input$metadata_id_col
                }
                if (!is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(md)) {
                  batch_col_name <- input$batch_column
                } else if (!is.null(input$metadata_batch_col) && nzchar(input$metadata_batch_col) && input$metadata_batch_col %in% colnames(md)) {
                  batch_col_name <- input$metadata_batch_col
                }
                if (!is.null(id_col_name) && !is.null(batch_col_name)) {
                  key <- as.character(md[[id_col_name]])
                  batch_map <- stats::setNames(md[[batch_col_name]], key)
                  batch_vec <- unname(batch_map[sample_names])
                  cat("Debug: Attempted mapping via metadata ID/batch columns\n")
                }
              }
              
              # 4) Fallbacks: rownames or common ID columns
              if (is.null(batch_vec) && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                md <- values$metadata
                if (!is.null(rownames(md)) && all(sample_names %in% rownames(md))) {
                  batch_vec <- md[sample_names, input$batch_column]
                  cat("Debug: Using metadata rownames\n")
                } else {
                  id_cols <- intersect(colnames(md), c("Sample", "SampleID", "sample", "sample_id"))
                  if (length(id_cols) > 0) {
                    key <- as.character(md[[id_cols[1]]])
                    batch_map <- stats::setNames(md[[input$batch_column]], key)
                    batch_vec <- unname(batch_map[sample_names])
                    cat("Debug: Using common ID columns fallback\n")
                  }
                }
              }
              
              # Validate and attach
              if (!is.null(batch_vec)) {
                cat("Debug: Batch vector obtained, length:", length(batch_vec), "unique values:", length(unique(batch_vec[!is.na(batch_vec)])), "\n")
                batch_fac <- as.factor(batch_vec)
                if (length(stats::na.omit(unique(batch_fac))) >= 2) {
                  sample_metadata$batch <- batch_fac
                  cond_batches <- tapply(sample_metadata$batch, sample_metadata$condition, function(b) length(unique(b)))
                  batch_conds <- tapply(sample_metadata$condition, sample_metadata$batch, function(c) length(unique(c)))
                  confounded <- all(cond_batches == 1, na.rm = TRUE) && all(batch_conds == 1, na.rm = TRUE)
                  if (isTRUE(confounded)) {
                    showNotification("Warning: Batch and condition are perfectly confounded. Proceeding without batch in DESeq2 design.", type = "warning", duration = 8)
                    sample_metadata$batch <- NULL
                  } else {
                    use_batch_in_deseq2 <- TRUE
                    cat("Debug: Successfully added batch to DESeq2 design\n")
                  }
                } else {
                  showNotification("Batch column has fewer than 2 levels for the selected samples. Ignoring batch in DESeq2 design.", type = "message", duration = 6)
                }
              } else {
                cat("Debug: Failed to obtain batch vector\n")
                showNotification("Could not align batch metadata to sample names. Ignoring batch for DESeq2.", type = "warning", duration = 8)
              }
            }
            
            shiny::setProgress(0.3, detail = "Creating DESeq2 dataset...")
            
            # Create DESeq2 dataset (include batch in design when applicable)
            dds <- tryCatch({
              if (isTRUE(use_batch_in_deseq2) && "batch" %in% colnames(sample_metadata)) {
                DESeq2::DESeqDataSetFromMatrix(
                  countData = count_matrix,
                  colData = sample_metadata,
                  design = ~ batch + condition
                )
              } else {
                DESeq2::DESeqDataSetFromMatrix(
                  countData = count_matrix,
                  colData = sample_metadata,
                  design = ~ condition
                )
              }
            }, error = function(e) {
              showNotification(paste("Error creating DESeq2 dataset:", e$message), type = "error", duration = 10)
              return(NULL)
            })
            
            if (is.null(dds)) return()
            
            shiny::setProgress(0.5, detail = "Running DESeq2 analysis...")
            
            # Run DESeq2 analysis
            dds <- tryCatch({
              DESeq2::DESeq(dds,
                            test = input$deseq2_test %||% "Wald",
                            fitType = input$deseq2_fitType %||% "parametric",
                            quiet = TRUE)
            }, error = function(e) {
              showNotification(paste("Error in DESeq2 analysis:", e$message), type = "error", duration = 10)
              return(NULL)
            })
            
            if (is.null(dds)) return()
            
            # Save dds for later use (e.g., normalized counts and transformations)
            values$dds <- dds
            
            # Compute user-selected DESeq2 transformed data for downstream use and display
            # This does NOT affect the DESeq2 statistical run (which uses raw counts in dds)
            tryCatch({
              transform_choice <- input$deseq2_transform %||% "vst"
              if (transform_choice == "vst") {
                vsd <- DESeq2::vst(dds, blind = TRUE)
                trans_mat <- SummarizedExperiment::assay(vsd)
              } else if (transform_choice == "rlog") {
                rld <- DESeq2::rlog(dds, blind = TRUE)
                trans_mat <- SummarizedExperiment::assay(rld)
              } else {
                # log2(normalized_counts + 1)
                norm_counts <- DESeq2::counts(dds, normalized = TRUE)
                trans_mat <- log2(norm_counts + 1)
              }
              # Ensure transformed matrix has feature rows matching cleaned_molecules
              rownames(trans_mat) <- make.unique(values$cleaned_molecules)
              values$normalized_data <- as.data.frame(trans_mat)
              # Keep column names in sync with the app's corrected sample names if available
              if (!is.null(values$corrected_sample_names) &&
                  length(values$corrected_sample_names) == ncol(values$normalized_data)) {
                colnames(values$normalized_data) <- values$corrected_sample_names
              }
              showNotification(paste("DESeq2", toupper(transform_choice), "transformation applied for downstream analyses."),
                               type = "message", duration = 5)
            }, error = function(e) {
              showNotification(paste("Warning: Failed to apply selected DESeq2 transformation:", e$message,
                                     "Using default DESeq2 normalized counts for display."),
                               type = "warning", duration = 8)
              # Fallback to normalized counts table without transformation
              vals <- try(DESeq2::counts(dds, normalized = TRUE), silent = TRUE)
              if (!inherits(vals, "try-error")) {
                rownames(vals) <- make.unique(values$cleaned_molecules)
                values$normalized_data <- as.data.frame(vals)
              }
            })
            
            # Create column to store DESeq2 method info
            stat_results$DESeq2_Method <- paste("Differential Expression Analysis,",
                                                input$deseq2_test %||% "Wald", "test")
            stat_results$DESeq2_FitType <- input$deseq2_fitType %||% "parametric"
            
            # Global test for multiple groups (LRT)
            if (length(values$unique_groups) > 2) {
              shiny::setProgress(0.6, detail = "Calculating global test...")
              
              # Run likelihood ratio test for global effect
              dds_lrt <- tryCatch({
                # Reduced model (no condition effect)
                dds_reduced <- DESeq2::DESeq(dds, test = "LRT", reduced = ~ 1, quiet = TRUE)
                dds_reduced
              }, error = function(e) {
                showNotification(paste("Error in DESeq2 global test:", e$message), type = "warning", duration = 8)
                return(NULL)
              })
              
              if (!is.null(dds_lrt)) {
                global_results <- DESeq2::results(dds_lrt,
                                                  alpha = input$deseq2_alpha %||% 0.05,
                                                  independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                                  cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
                
                # Add global test results
                stat_results$DESeq2_Global_PValue <- global_results$pvalue
                stat_results$DESeq2_Global_AdjPValue <- global_results$padj
                stat_results$DESeq2_Global_LFC <- global_results$log2FoldChange
                stat_results$DESeq2_Global_Test <- "Likelihood Ratio Test across all groups"
              } else {
                # If global test failed, add NA columns
                stat_results$DESeq2_Global_PValue <- NA
                stat_results$DESeq2_Global_AdjPValue <- NA
                stat_results$DESeq2_Global_LFC <- NA
                stat_results$DESeq2_Global_Test <- "Likelihood Ratio Test across all groups"
              }
            }
            
            # Pairwise comparisons
            shiny::setProgress(0.7, detail = "Calculating pairwise comparisons...")
            
            if (length(values$unique_groups) == 2) {
              # Simple two-group comparison
              group1 <- values$unique_groups[1]
              group2 <- values$unique_groups[2]
              comparison_name <- paste(group1, "vs", group2)
              
              # Get results for this comparison
              deseq_results <- tryCatch({
                DESeq2::results(dds,
                                contrast = c("condition", group2, group1),
                                alpha = input$deseq2_alpha %||% 0.05,
                                independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
              }, error = function(e) {
                showNotification(paste("Error in DESeq2 pairwise comparison:", e$message), type = "warning", duration = 8)
                return(NULL)
              })
              
              if (!is.null(deseq_results)) {
                # Add results to stat_results
                stat_results[[paste0(comparison_name, "_PValue")]] <- deseq_results$pvalue
                stat_results[[paste0(comparison_name, "_AdjPValue")]] <- deseq_results$padj
                stat_results[[paste0(comparison_name, "_Log2FC")]] <- deseq_results$log2FoldChange
                stat_results[[paste0(comparison_name, "_BaseMean")]] <- deseq_results$baseMean
              } else {
                # If comparison failed, add NA columns
                stat_results[[paste0(comparison_name, "_PValue")]] <- NA
                stat_results[[paste0(comparison_name, "_AdjPValue")]] <- NA
                stat_results[[paste0(comparison_name, "_Log2FC")]] <- NA
                stat_results[[paste0(comparison_name, "_BaseMean")]] <- NA
              }
            } else {
              # Multiple group comparisons - use selected pairwise combinations
              pairwise_combinations <- get_pairwise_combinations_for_analysis()
              n_comparisons <- nrow(pairwise_combinations)
              
              for (comp_idx in seq_len(n_comparisons)) {
                shiny::setProgress(0.7 + (comp_idx / n_comparisons) * 0.2,
                                   detail = paste("Processing comparison", comp_idx, "of", n_comparisons))
                
                group1 <- pairwise_combinations[comp_idx, "Group_1"]
                group2 <- pairwise_combinations[comp_idx, "Group_2"]
                comparison_name <- paste(group1, "vs", group2)
                
                # Get results for this pairwise comparison
                deseq_results <- tryCatch({
                  DESeq2::results(dds,
                                  contrast = c("condition", group2, group1),
                                  alpha = input$deseq2_alpha %||% 0.05,
                                  independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                  cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
                }, error = function(e) {
                  showNotification(paste("Error in DESeq2 comparison", comparison_name, ":", e$message),
                                   type = "warning", duration = 5)
                  return(NULL)
                })
                
                if (!is.null(deseq_results)) {
                  # Add results to stat_results
                  stat_results[[paste0(comparison_name, "_PValue")]] <- deseq_results$pvalue
                  stat_results[[paste0(comparison_name, "_AdjPValue")]] <- deseq_results$padj
                  stat_results[[paste0(comparison_name, "_Log2FC")]] <- deseq_results$log2FoldChange
                  stat_results[[paste0(comparison_name, "_BaseMean")]] <- deseq_results$baseMean
                } else {
                  # If comparison failed, add NA columns
                  stat_results[[paste0(comparison_name, "_PValue")]] <- NA
                  stat_results[[paste0(comparison_name, "_AdjPValue")]] <- NA
                  stat_results[[paste0(comparison_name, "_Log2FC")]] <- NA
                  stat_results[[paste0(comparison_name, "_BaseMean")]] <- NA
                }
              }
            }
            
            # Add DESeq2 parameters to results
            stat_results$DESeq2_Alpha <- input$deseq2_alpha %||% 0.05
            stat_results$DESeq2_IndependentFiltering <- input$deseq2_independent_filtering %||% TRUE
            stat_results$DESeq2_CooksCutoff <- input$deseq2_cooksCutoff %||% TRUE
            
            # Store DESeq2 results objects for visualization purposes
            if (length(values$unique_groups) == 2) {
              # Store the single pairwise comparison result
              group1 <- values$unique_groups[1]
              group2 <- values$unique_groups[2]
              deseq_results <- tryCatch({
                DESeq2::results(dds,
                                contrast = c("condition", group2, group1),
                                alpha = input$deseq2_alpha %||% 0.05,
                                independentFiltering = input$deseq2_independent_filtering %||% TRUE,
                                cooksCutoff = if(input$deseq2_cooksCutoff %||% TRUE) TRUE else FALSE)
              }, error = function(e) NULL)
              
              if (!is.null(deseq_results)) {
                values$deseq2_results <- deseq_results
              }
            }
            
            # Store the statistical results
            values$stat_results <- merge_bootstrap_columns(stat_results)
          })
        }
        else if (length(values$unique_groups) > 2 && input$sig_method == "kruskal") {
          # Show progress
          withProgress(message = "Calculating Kruskal-Wallis statistics...", {
            # Prepare column to store Kruskal-Wallis p-values and adjusted p-values
            stat_results$KW_PValue <- NA
            stat_results$KW_AdjustedPValue <- NA
            
            # Create a column to store post-hoc method used
            stat_results$PostHoc_Method <- ifelse(input$posthoc_method == "none", "N/A", input$posthoc_method)
            
            # Loop through each feature
            for (i in 1:length(values$cleaned_molecules)) {
              setProgress(i / length(values$cleaned_molecules),
                          detail = paste("Processing", values$cleaned_molecules[i]))
              
              # Get data for all groups for this feature
              feature_data <- list()
              for (g in 1:length(values$unique_groups)) {
                group_cols <- values$group_column_indices[[g]]
                group_data <- as.numeric(values$normalized_data[i, group_cols])
                feature_data[[g]] <- group_data[!is.na(group_data)]
              }
              
              # Check if we have sufficient data
              if (any(sapply(feature_data, length) < 2)) {
                stat_results$KW_PValue[i] <- NA
                next
              }
              
              # Run Kruskal-Wallis test
              tryCatch({
                # Create data for KW test
                all_data <- unlist(feature_data)
                all_groups <- factor(rep(values$unique_groups, sapply(feature_data, length)))
                
                # Run test
                kw_result <- kruskal.test(all_data ~ all_groups)
                stat_results$KW_PValue[i] <- kw_result$p.value
                
                # Only run post-hoc tests if the global test is significant AND posthoc_method is not "none"
                if (kw_result$p.value < 0.05 && input$posthoc_method != "none") {
                  # Create a data frame for post-hoc tests
                  posthoc_df <- data.frame(
                    value = all_data,
                    group = factor(all_groups)
                  )
                  
                  # Run selected post-hoc test
                  posthoc_result <- switch(
                    input$posthoc_method,            "dunn" = {
                      if (!requireNamespace("dunn.test", quietly = TRUE)) {
                        install.packages("dunn.test")
                        library(dunn.test)
                      }
                      dunn_result <- dunn.test::dunn.test(posthoc_df$value, posthoc_df$group,
                                                          method = get_correction_method())
                      
                      # Store pairwise comparisons in separate columns
                      pairwise_pairs <- dunn_result$comparisons
                      pairwise_p <- dunn_result$P.adjusted
                      
                      for (j in 1:length(pairwise_pairs)) {
                        pair_name <- gsub(" - ", "_vs_", pairwise_pairs[j])
                        col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                        if (!(col_name %in% colnames(stat_results))) {
                          stat_results[[col_name]] <- NA
                        }
                        stat_results[i, col_name] <- pairwise_p[j]
                      }
                      pairwise_p
                    },            "bonferroni" = {
                      pw_result <- pairwise.wilcox.test(posthoc_df$value, posthoc_df$group,
                                                        p.adjust.method = "bonferroni")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },            "holm" = {
                      pw_result <- pairwise.wilcox.test(posthoc_df$value, posthoc_df$group,
                                                        p.adjust.method = "holm")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values            },
                    "BH" = {
                      pw_result <- pairwise.wilcox.test(posthoc_df$value, posthoc_df$group,
                                                        p.adjust.method = "BH")
                      p_values <- pw_result$p.value
                      
                      # Convert matrix to named vector for storage
                      for (row_idx in 1:nrow(p_values)) {
                        for (col_idx in 1:ncol(p_values)) {
                          if (!is.na(p_values[row_idx, col_idx])) {
                            pair_name <- paste0(rownames(p_values)[row_idx], "_vs_", colnames(p_values)[col_idx])
                            col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                            if (!(col_name %in% colnames(stat_results))) {
                              stat_results[[col_name]] <- NA
                            }
                            stat_results[i, col_name] <- p_values[row_idx, col_idx]
                          }
                        }
                      }
                      p_values
                    },
                    # Default to Dunn's test if something goes wrong
                    {
                      if (!requireNamespace("dunn.test", quietly = TRUE)) {
                        install.packages("dunn.test")
                        library(dunn.test)
                      }
                      dunn_result <- dunn.test::dunn.test(posthoc_df$value, posthoc_df$group,
                                                          method = get_correction_method())
                      
                      # Store pairwise comparisons in separate columns
                      pairwise_pairs <- dunn_result$comparisons
                      pairwise_p <- dunn_result$P.adjusted
                      for (j in 1:length(pairwise_pairs)) {
                        pair_name <- gsub(" - ", "_vs_", pairwise_pairs[j])
                        col_name <- paste0("PostHoc_", pair_name, "_AdjPValue")
                        if (!(col_name %in% colnames(stat_results))) {
                          stat_results[[col_name]] <- NA
                        }
                        stat_results[i, col_name] <- pairwise_p[j]
                      }
                      pairwise_p
                    }
                  )
                }
              }, error = function(e) {
                message("Error in Kruskal-Wallis for feature ", values$cleaned_molecules[i], ": ", e$message)
              })
            }
            
            # Adjust p-values using BH correction for omnibus Kruskal-Wallis test
            stat_results$KW_AdjustedPValue <- p.adjust(stat_results$KW_PValue,
                                                       method = "BH")
            stat_results <- add_posthoc_fold_changes(stat_results)
          })
        }
        else if (length(values$unique_groups) > 1 && input$sig_method == "edger") {
          withProgress(message = "Calculating edgeR statistics...", {
            if (!requireNamespace("edgeR", quietly = TRUE)) {
              showNotification("edgeR package is required but not available. Please install it from Bioconductor.", type = "error", duration = 10)
              return()
            }
            
            # Validate raw count data
            if (is.null(values$raw_data) || is.null(values$cleaned_molecules)) {
              showNotification("No data available for edgeR analysis. Please process your data first.", type = "error", duration = 10)
              return()
            }
            if (nrow(values$raw_data) == 0 || ncol(values$raw_data) == 0) {
              showNotification("Raw data is empty for edgeR.", type = "error", duration = 10)
              return()
            }
            
            # Build count matrix from raw_data (drop feature column if present)
            raw_df <- values$raw_data
            if (ncol(raw_df) > 1) {
              first_col_name <- colnames(raw_df)[1]
              if (!is.numeric(raw_df[[1]]) || first_col_name %in% c("Feature","Molecule","Gene","ID")) {
                raw_df <- raw_df[, -1, drop = FALSE]
              }
            }
            mat <- as.matrix(raw_df)
            # Replace non-finite with 0 and clamp negatives
            if (any(!is.finite(mat))) mat[!is.finite(mat)] <- 0
            if (any(mat < 0, na.rm = TRUE)) mat[mat < 0] <- 0
            # Round to integers as counts
            mat <- round(mat)
            # Validate count matrix before integer coercion
            if (anyNA(mat)) {
              showNotification("edgeR requires complete count data. Missing values were found after preprocessing. Please impute/remove missing values or use a non-count method (e.g., limma/voom).",
                               type = "error", duration = 10)
              return()
            }
            max_count <- suppressWarnings(max(mat, na.rm = TRUE))
            if (is.finite(max_count) && max_count > .Machine$integer.max) {
              showNotification(paste0("edgeR requires integer counts within 32-bit range. Max value detected: ",
                                      format(max_count, scientific = TRUE),
                                      ". Consider using limma/voom or rescaling your data."),
                               type = "error", duration = 12)
              return()
            }
            suppressWarnings(storage.mode(mat) <- "integer")
            if (anyNA(mat)) {
              showNotification("edgeR could not coerce counts to integer without introducing NAs. Please check for extremely large values or non-count data.",
                               type = "error", duration = 10)
              return()
            }
            rownames(mat) <- make.unique(values$cleaned_molecules)
            
            # Group and optional batch
            groups <- factor(create_proper_group_labels(values$unique_groups, values$group_column_indices))
            design <- NULL
            batch_fac <- NULL
            if (identical(input$batch_correction_enabled, "yes") && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
              md <- values$metadata
              # Prefer position-based alignment like other methods
              if (nrow(md) >= length(groups)) {
                candidate <- md[[input$batch_column]]
                if (!is.null(candidate) && length(candidate) >= length(groups)) {
                  batch_fac <- factor(candidate[seq_along(groups)])
                  if (length(stats::na.omit(unique(batch_fac))) < 2) batch_fac <- NULL
                }
              }
            }
            
            # Create DGEList and normalize
            y <- edgeR::DGEList(counts = mat, group = groups)
            norm_method <- input$edger_norm_method %||% "TMM"
            if (!is.null(norm_method) && tolower(norm_method) == "none") {
              # Skip normalization: set normalization factors to 1
              if (is.null(y$samples$norm.factors) || any(!is.finite(y$samples$norm.factors))) {
                y$samples$norm.factors <- rep(1, nrow(y$samples))
              } else {
                y$samples$norm.factors[] <- 1
              }
            } else {
              y <- tryCatch({ edgeR::calcNormFactors(y, method = norm_method) }, error = function(e) {
                showNotification(paste("edgeR calcNormFactors failed:", e$message, "Falling back to TMM."), type = "warning", duration = 8)
                edgeR::calcNormFactors(y, method = "TMM")
              })
            }
            
            # Design matrix
            if (!is.null(batch_fac)) {
              design <- stats::model.matrix(~ batch_fac + groups)
              colnames(design) <- make.names(colnames(design))
            } else {
              design <- stats::model.matrix(~ 0 + groups)
              colnames(design) <- make.names(levels(groups))
            }
            
            # Estimate dispersion
            robust_flag <- isTRUE(input$edger_robust %||% TRUE)
            y <- edgeR::estimateDisp(y, design = design, robust = robust_flag)
            fit <- edgeR::glmFit(y, design = design)
            
            # Initialize results frame
            stat_results <- data.frame(Feature = rownames(mat), stringsAsFactors = FALSE)
            rownames(stat_results) <- rownames(mat)
            stat_results$edgeR_NormMethod <- norm_method
            stat_results$edgeR_Robust <- robust_flag
            stat_results$edgeR_Test <- input$edger_test %||% "qlf"
            stat_results$edgeR_BatchEnabled <- !is.null(batch_fac)
            stat_results$edgeR_BatchColumn <- if (!is.null(batch_fac)) as.character(input$batch_column) else NA_character_
            
            # Cache edgeR state for fast display-only recomputation later
            values$edger_state <- list(
              y = y,
              design = design,
              groups = groups,
              norm_method = norm_method,
              robust = robust_flag
            )
            
            # Use logCPM matrix for downstream normalized_data visualization (display-only)
            prior_cnt <- as.numeric(input$edger_prior_count %||% 1)
            lcpm <- edgeR::cpm(values$edger_state$y, log = TRUE, prior.count = prior_cnt)
            values$normalized_data <- as.data.frame(lcpm)
            # Keep sample names corrected if available
            if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(values$normalized_data)) {
              colnames(values$normalized_data) <- values$corrected_sample_names
            }
            
            # Apply initial external batch correction if enabled
            # (Subsequent changes will be handled by the observeEvent to avoid full re-runs)
            if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
              # Apply external batch correction immediately during initial analysis
              if (!is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                md <- values$metadata
                if (nrow(md) >= length(groups)) {
                  candidate <- md[[input$batch_column]]
                  if (!is.null(candidate) && length(candidate) >= length(groups)) {
                    viz_batch <- factor(candidate[seq_along(groups)])
                    if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                      values$data_before_batch_correction <- values$normalized_data
                      viz_method <- input$viz_batch_method %||% "combat"
                      corrected <- try(perform_cached_batch_correction(
                        data = as.matrix(values$normalized_data),
                        batch_info = viz_batch,
                        method = viz_method,
                        group_info = groups
                      ), silent = TRUE)
                      if (!inherits(corrected, "try-error")) {
                        values$normalized_data <- as.data.frame(corrected)
                        if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(values$normalized_data)) {
                          colnames(values$normalized_data) <- values$corrected_sample_names
                        }
                        showNotification(paste("Initial external batch correction applied using", viz_method), type = "message", duration = 3)
                      }
                    }
                  }
                }
              }
            }
            
            # Global test for multi-group when using QLF/LRT
            if (length(values$unique_groups) > 2 && (input$edger_test %||% "qlf") %in% c("qlf","lrt")) {
              setProgress(0.5, detail = "Calculating edgeR global test...")
              if (grepl("^qlf$", input$edger_test %||% "qlf")) {
                qlf <- edgeR::glmQLFit(y, design = design, robust = robust_flag)
                qlf_res <- edgeR::glmQLFTest(qlf)
                stat_results$edgeR_Global_PValue <- qlf_res$table$PValue
                stat_results$edgeR_Global_LogFC <- qlf_res$table$logFC
                # Store QLF fit object for visualization
                values$edger_qlf <- qlf
              } else {
                lrt <- edgeR::glmLRT(fit)
                stat_results$edgeR_Global_PValue <- lrt$table$PValue
                stat_results$edgeR_Global_LogFC <- lrt$table$logFC
              }
            }
            
            # Pairwise comparisons
            setProgress(0.7, detail = "Calculating edgeR pairwise comparisons...")
            
            # Get pairwise combinations to use (respects pre-analysis modal selection)
            pairwise_combinations <- get_pairwise_combinations_for_analysis()
            n_comparisons <- nrow(pairwise_combinations)
            
            for (comp_idx in seq_len(n_comparisons)) {
              g1 <- pairwise_combinations[comp_idx, "Group_1"]
              g2 <- pairwise_combinations[comp_idx, "Group_2"]
              comp_name <- paste(g1, "vs", g2)
                
                if (is.null(batch_fac) && length(values$unique_groups) == 2 && (input$edger_test %||% "qlf") == "exact") {
                  # Exact test for simple two-group design without batch
                  et <- edgeR::exactTest(y, pair = c(g1, g2))
                  tab <- et$table
                } else {
                  # GLM contrast for g2 - g1
                  if (is.null(batch_fac)) {
                    # For ~0+groups design, columns are group levels
                    # Use the actual factor levels from the groups factor
                    group_levels <- levels(groups)
                    g1_level <- group_levels[group_levels == g1][1]  # Find exact match
                    g2_level <- group_levels[group_levels == g2][1]  # Find exact match
                    
                    if (!is.na(g1_level) && !is.na(g2_level)) {
                      # Use make.names on the actual levels to match design column names
                      g1_col <- make.names(g1_level)
                      g2_col <- make.names(g2_level)
                      cm <- limma::makeContrasts(contrasts = paste0(g2_col, "-", g1_col), levels = design)
                    } else {
                      # Fallback to exactTest if levels don't match
                      showNotification(paste("Warning: Could not match group levels for", comp_name, "- using exactTest instead"),
                                       type = "warning", duration = 5)
                      et <- edgeR::exactTest(y, pair = c(g1, g2))
                      tab <- et$table
                    }
                    
                    if (exists("cm") && !is.null(cm)) {
                      if (grepl("^qlf$", input$edger_test %||% "qlf")) {
                        qlf <- edgeR::glmQLFit(y, design = design, robust = robust_flag)
                        q <- edgeR::glmQLFTest(qlf, contrast = cm)
                        tab <- q$table
                        # Store QLF fit object for visualization (pairwise)
                        if (comp_idx == 1) { # Store from first pairwise comparison
                          values$edger_qlf <- qlf
                        }
                      } else if (grepl("^lrt$", input$edger_test %||% "qlf")) {
                        lr <- edgeR::glmLRT(fit, contrast = cm)
                        tab <- lr$table
                      } else {
                        et <- edgeR::exactTest(y, pair = c(g1, g2))
                        tab <- et$table
                      }
                    }
                  } else {
                    # For ~batch+groups design, find the correct group coefficient names
                    # The design matrix has columns like: "(Intercept)", "batch_fac...", "groups..."
                    design_colnames <- colnames(design)
                    group_levels <- levels(groups)
                    
                    # For ~ batch + groups design, group coefficients are relative to the reference level
                    # Only non-reference levels get explicit columns
                    reference_level <- group_levels[1]  # First level is reference
                    
                    # Find which design columns correspond to each group
                    g1_col <- NULL
                    g2_col <- NULL
                    
                    # Handle reference level (no explicit column, represented by intercept)
                    if (g1 == reference_level) {
                      g1_col <- "(Intercept)"  # Reference level
                    } else {
                      expected_col <- paste0("groups", make.names(g1))
                      if (expected_col %in% design_colnames) {
                        g1_col <- expected_col
                      }
                    }
                    
                    if (g2 == reference_level) {
                      g2_col <- "(Intercept)"  # Reference level
                    } else {
                      expected_col <- paste0("groups", make.names(g2))
                      if (expected_col %in% design_colnames) {
                        g2_col <- expected_col
                      }
                    }
                    
                    # Create contrast for Group2/Group1 calculation
                    if (!is.null(g1_col) && !is.null(g2_col)) {
                      if (g1_col == "(Intercept)" && g2_col == "(Intercept)") {
                        # Both are reference level - this shouldn't happen in pairwise comparison
                        showNotification(paste("Error: Both groups are reference level for", comp_name),
                                         type = "error", duration = 5)
                        next
                      } else if (g1_col == "(Intercept)") {
                        # g1 is reference, g2 is not: for g2/g1, use g2_col
                        cm <- limma::makeContrasts(contrasts = g2_col, levels = design)
                      } else if (g2_col == "(Intercept)") {
                        # g2 is reference, g1 is not: for g2/g1, use -g1_col
                        cm <- limma::makeContrasts(contrasts = paste0("-", g1_col), levels = design)
                      } else {
                        # Neither is reference: contrast is g2_col - g1_col for Group2/Group1
                        cm <- limma::makeContrasts(contrasts = paste0(g2_col, "-", g1_col), levels = design)
                      }
                      
                      # Run GLM test with batch correction
                      if (grepl("^qlf$", input$edger_test %||% "qlf")) {
                        qlf <- edgeR::glmQLFit(y, design = design, robust = robust_flag)
                        q <- edgeR::glmQLFTest(qlf, contrast = cm)
                        tab <- q$table
                      } else if (grepl("^lrt$", input$edger_test %||% "qlf")) {
                        lr <- edgeR::glmLRT(fit, contrast = cm)
                        tab <- lr$table
                      } else {
                        # For batch designs, we must use GLM methods, not exactTest
                        showNotification("exactTest cannot be used with batch correction. Using QLF instead.",
                                         type = "warning", duration = 5)
                        qlf <- edgeR::glmQLFit(y, design = design, robust = robust_flag)
                        q <- edgeR::glmQLFTest(qlf, contrast = cm)
                        tab <- q$table
                      }
                    } else {
                      # This is a real error - batch correction requires GLM
                      showNotification(paste("Error: Cannot create batch-corrected contrast for", comp_name,
                                             ". Available design columns:", paste(design_colnames, collapse=", ")),
                                       type = "error", duration = 10)
                      next  # Skip this comparison
                    }
                  }
                }
                
                # Populate results
                stat_results[[paste0(comp_name, "_PValue")]] <- tab$PValue
                stat_results[[paste0(comp_name, "_AdjPValue")]] <- p.adjust(tab$PValue, method = get_correction_method())
                # Log2FC in edgeR is typically provided; ensure name
                lfc <- if (!is.null(tab$logFC)) tab$logFC else log2(tab$FoldChange)
                stat_results[[paste0(comp_name, "_Log2FC")]] <- lfc
            }
            
            values$stat_results <- merge_bootstrap_columns(stat_results)
          })
        }
        else if (length(values$unique_groups) > 1 && input$sig_method == "limma_voom") {
          withProgress(message = "Calculating limma-voom statistics...", {
            if (!requireNamespace("limma", quietly = TRUE)) {
              showNotification("limma package is required but not available. Please install it from Bioconductor.", type = "error", duration = 10)
              return()
            }
            if (!requireNamespace("edgeR", quietly = TRUE)) {
              showNotification("edgeR package is required for normalization but not available. Please install it from Bioconductor.", type = "error", duration = 10)
              return()
            }
            
            # Validate raw count data
            if (is.null(values$raw_data) || is.null(values$cleaned_molecules)) {
              showNotification("No data available for limma-voom analysis. Please process your data first.", type = "error", duration = 10)
              return()
            }
            if (nrow(values$raw_data) == 0 || ncol(values$raw_data) == 0) {
              showNotification("Raw data is empty for limma-voom.", type = "error", duration = 10)
              return()
            }
            
            # Build count matrix from raw_data (drop feature column if present)
            raw_df <- values$raw_data
            if (ncol(raw_df) > 1) {
              first_col_name <- colnames(raw_df)[1]
              if (!is.numeric(raw_df[[1]]) || first_col_name %in% c("Feature","Molecule","Gene","ID")) {
                raw_df <- raw_df[, -1, drop = FALSE]
              }
            }
            mat <- as.matrix(raw_df)
            # Replace non-finite with 0 and clamp negatives
            if (any(!is.finite(mat))) mat[!is.finite(mat)] <- 0
            if (any(mat < 0, na.rm = TRUE)) mat[mat < 0] <- 0
            # Round to integers as counts
            mat <- round(mat)
            # Validate count matrix before integer coercion
            if (anyNA(mat)) {
              showNotification("limma-voom requires complete count data. Missing values were found after preprocessing. Please impute/remove missing values or use a non-count method.",
                               type = "error", duration = 10)
              return()
            }
            max_count <- suppressWarnings(max(mat, na.rm = TRUE))
            if (is.finite(max_count) && max_count > .Machine$integer.max) {
              showNotification(paste0("limma-voom requires integer counts within 32-bit range. Max value detected: ",
                                      format(max_count, scientific = TRUE),
                                      ". Consider using limma on transformed data or rescaling your counts."),
                               type = "error", duration = 12)
              return()
            }
            suppressWarnings(storage.mode(mat) <- "integer")
            if (anyNA(mat)) {
              showNotification("limma-voom could not coerce counts to integer without introducing NAs. Please check for extremely large values or non-count data.",
                               type = "error", duration = 10)
              return()
            }
            rownames(mat) <- make.unique(values$cleaned_molecules)
            
            # Group and optional batch
            groups <- factor(create_proper_group_labels(values$unique_groups, values$group_column_indices))
            design <- NULL
            batch_fac <- NULL
            if (identical(input$batch_correction_enabled, "yes") && !is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
              md <- values$metadata
              if (nrow(md) >= length(groups)) {
                candidate <- md[[input$batch_column]]
                if (!is.null(candidate) && length(candidate) >= length(groups)) {
                  batch_fac <- factor(candidate[seq_along(groups)])
                  if (length(stats::na.omit(unique(batch_fac))) < 2) batch_fac <- NULL
                }
              }
            }
            
            # Create DGEList and normalize
            y <- edgeR::DGEList(counts = mat, group = groups)
            norm_method <- input$limma_voom_norm_method %||% "TMM"
            if (!is.null(norm_method) && tolower(norm_method) == "none") {
              y$samples$norm.factors <- rep(1, nrow(y$samples))
            } else {
              y <- tryCatch({ edgeR::calcNormFactors(y, method = norm_method) }, error = function(e) {
                showNotification(paste("calcNormFactors failed:", e$message, "Falling back to TMM."), type = "warning", duration = 8)
                edgeR::calcNormFactors(y, method = "TMM")
              })
            }
            
            # Design matrix
            if (!is.null(batch_fac)) {
              design <- stats::model.matrix(~ batch_fac + groups)
              colnames(design) <- make.names(colnames(design))
            } else {
              design <- stats::model.matrix(~ 0 + groups)
              colnames(design) <- make.names(levels(groups))
            }
            
            # voom transformation and trend setting
            trend_option <- input$limma_voom_trend %||% "auto"
            if (trend_option == "auto") {
              # For RNA-seq with voom, trend is usually FALSE since voom handles mean-variance relationship
              trend_val <- FALSE
            } else {
              trend_val <- as.logical(trend_option)
            }
            
            use_weights <- isTRUE(input$limma_voom_weights)
            robust_flag <- isTRUE(input$limma_voom_robust)
            
            v <- limma::voom(y, design = design, plot = FALSE, span = 0.5, save.plot = FALSE,
                             normalize.method = "none", weights = if(use_weights) NULL else NULL)
            
            # Fit linear model
            fit <- limma::lmFit(v, design, weights = if(use_weights) limma::arrayWeights(v$E, design) else NULL)
            
            # Store limma-voom state for caching
            values$limma_voom_state <- list(
              y = y,  # DGEList object for BCV plots
              v = v,  # Voom result object for precision weights
              design = design,
              groups = groups,
              norm_method = norm_method,
              robust = robust_flag,
              use_weights = use_weights,
              fit = fit  # Fitted model for residuals
            )
            
            # Create logCPM for visualization
            prior_count <- input$limma_voom_prior_count %||% 0.5
            lcpm <- edgeR::cpm(y, log = TRUE, prior.count = prior_count)
            values$normalized_data <- as.data.frame(lcpm)
            if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(values$normalized_data)) {
              colnames(values$normalized_data) <- values$corrected_sample_names
            }
            
            # Apply initial external batch correction if enabled
            if (identical(input$batch_correction_enabled, "yes") && isTRUE(input$viz_batch_enable)) {
              if (!is.null(values$metadata) && !is.null(input$batch_column) && nzchar(input$batch_column) && input$batch_column %in% colnames(values$metadata)) {
                md <- values$metadata
                if (nrow(md) >= length(groups)) {
                  candidate <- md[[input$batch_column]]
                  if (!is.null(candidate) && length(candidate) >= length(groups)) {
                    viz_batch <- factor(candidate[seq_along(groups)])
                    if (length(stats::na.omit(unique(viz_batch))) >= 2) {
                      values$data_before_batch_correction <- values$normalized_data
                      viz_method <- input$viz_batch_method %||% "combat"
                      corrected <- try(perform_cached_batch_correction(
                        data = as.matrix(values$normalized_data),
                        batch_info = viz_batch,
                        method = viz_method,
                        group_info = groups
                      ), silent = TRUE)
                      if (!inherits(corrected, "try-error")) {
                        values$normalized_data <- as.data.frame(corrected)
                        if (!is.null(values$corrected_sample_names) && length(values$corrected_sample_names) == ncol(values$normalized_data)) {
                          colnames(values$normalized_data) <- values$corrected_sample_names
                        }
                        showNotification(paste("Initial external batch correction applied using", viz_method), type = "message", duration = 3)
                      }
                    }
                  }
                }
              }
            }
            
            # Statistical testing
            stat_results <- data.frame(Feature = values$cleaned_molecules, stringsAsFactors = FALSE)
            
            # Add ID column if available
            if (!is.null(values$accession_ids) &&
                length(values$accession_ids) == length(values$cleaned_molecules) &&
                !is.null(values$accession_id_column) &&
                is.numeric(values$accession_id_column) && length(values$accession_id_column) == 1 && values$accession_id_column > 0) {
              stat_results$ID <- values$accession_ids
            }
            
            # Global test for multi-group when using F-test
            if (length(values$unique_groups) > 2) {
              setProgress(0.5, detail = "Calculating limma-voom global test...")
              fit2 <- limma::eBayes(fit, trend = trend_val, robust = robust_flag)
              
              # F-test for overall differences across groups
              if (!is.null(batch_fac)) {
                # For batch design, test the group coefficients
                group_coefs <- grep("^groups", colnames(design), value = TRUE)
                if (length(group_coefs) > 1) {
                  topfit <- limma::topTable(fit2, coef = group_coefs, number = Inf, sort.by = "none")
                  stat_results$LimmaVoom_Global_PValue <- topfit$P.Value
                  stat_results$LimmaVoom_Global_FValue <- topfit$F
                }
              } else {
                # For no-batch design, use overall F-test
                topfit <- limma::topTable(fit2, number = Inf, sort.by = "none")
                stat_results$LimmaVoom_Global_PValue <- topfit$P.Value
                stat_results$LimmaVoom_Global_FValue <- topfit$F
              }
            }
            
            # Pairwise comparisons
            setProgress(0.8, detail = "Calculating pairwise comparisons...")
            
            # Resolve contrast type and build comparison list
            contrast_type_voom <- input$limma_voom_contrast_type %||% "pairwise"
            if (contrast_type_voom == "all_vs_reference") {
              ref_voom <- input$limma_voom_reference_group
              ug_voom <- values$unique_groups
              if (!length(ref_voom) || !ref_voom %in% ug_voom) ref_voom <- ug_voom[1]
              others_voom <- setdiff(ug_voom, ref_voom)
              pairwise_combinations <- if (length(others_voom) > 0) {
                data.frame(Group_1 = ref_voom, Group_2 = others_voom, stringsAsFactors = FALSE)
              } else {
                data.frame(Group_1 = character(0), Group_2 = character(0), stringsAsFactors = FALSE)
              }
            } else {
              pairwise_combinations <- get_pairwise_combinations_for_analysis()
            }
            n_comparisons <- nrow(pairwise_combinations)
            
            for (comp_idx in seq_len(n_comparisons)) {
              g1 <- pairwise_combinations[comp_idx, "Group_1"]
              g2 <- pairwise_combinations[comp_idx, "Group_2"]
              comp_name <- paste(g1, "vs", g2)
                
                # Create contrast using the same robust method as edgeR
                if (!is.null(batch_fac)) {
                  # For ~batch+groups design, find the correct group coefficient names
                  # The design matrix has columns like: "(Intercept)", "batch_fac...", "groups..."
                  design_colnames <- colnames(design)
                  group_levels <- levels(groups)
                  
                  # For ~ batch + groups design, group coefficients are relative to the reference level
                  # Only non-reference levels get explicit columns
                  reference_level <- group_levels[1]  # First level is reference
                  
                  # Find which design columns correspond to each group
                  g1_col <- NULL
                  g2_col <- NULL
                  
                  # Handle reference level (no explicit column, represented by intercept)
                  if (g1 == reference_level) {
                    g1_col <- "(Intercept)"  # Reference level
                  } else {
                    expected_col <- paste0("groups", make.names(g1))
                    if (expected_col %in% design_colnames) {
                      g1_col <- expected_col
                    }
                  }
                  
                  if (g2 == reference_level) {
                    g2_col <- "(Intercept)"  # Reference level
                  } else {
                    expected_col <- paste0("groups", make.names(g2))
                    if (expected_col %in% design_colnames) {
                      g2_col <- expected_col
                    }
                  }
                  
                  # Create contrast for Group2/Group1 calculation
                  if (!is.null(g1_col) && !is.null(g2_col)) {
                    if (g1_col == "(Intercept)" && g2_col == "(Intercept)") {
                      # Both are reference level - this shouldn't happen in pairwise comparison
                      showNotification(paste("Error: Both groups are reference level for", comp_name),
                                       type = "error", duration = 5)
                      next
                    } else if (g1_col == "(Intercept)") {
                      # g1 is reference, g2 is not: for g2/g1, use g2_col
                      cont_str <- g2_col
                    } else if (g2_col == "(Intercept)") {
                      # g2 is reference, g1 is not: for g2/g1, use -g1_col
                      cont_str <- paste0("-", g1_col)
                    } else {
                      # Neither is reference: contrast is g2_col - g1_col for Group2/Group1
                      cont_str <- paste0(g2_col, "-", g1_col)
                    }
                    
                    cm <- limma::makeContrasts(contrasts = cont_str, levels = design)
                  } else {
                    # This is a real error - batch correction requires valid contrasts
                    showNotification(paste("Error: Cannot create batch-corrected contrast for", comp_name,
                                           ". Available design columns:", paste(design_colnames, collapse=", ")),
                                     type = "error", duration = 10)
                    next  # Skip this comparison
                  }
                } else {
                  # For ~0+groups design, find the correct group coefficient names
                  design_colnames <- colnames(design)
                  group_levels <- levels(groups)
                  
                  g1_col <- NULL
                  g2_col <- NULL
                  
                  # Find columns that match our groups
                  # Try both "groups" prefix and direct group names
                  for (level in group_levels) {
                    # First try with "groups" prefix
                    expected_col_with_prefix <- paste0("groups", make.names(level))
                    # Then try direct group name
                    expected_col_direct <- make.names(level)
                    
                    if (expected_col_with_prefix %in% design_colnames) {
                      if (level == g1) g1_col <- expected_col_with_prefix
                      if (level == g2) g2_col <- expected_col_with_prefix
                    } else if (expected_col_direct %in% design_colnames) {
                      if (level == g1) g1_col <- expected_col_direct
                      if (level == g2) g2_col <- expected_col_direct
                    }
                  }
                  
                  if (!is.null(g1_col) && !is.null(g2_col)) {
                    cont_str <- paste0(g2_col, "-", g1_col)
                    cm <- limma::makeContrasts(contrasts = cont_str, levels = design)
                  } else {
                    # Error case - cannot find the expected columns
                    showNotification(paste("Error: Cannot create contrast for", comp_name,
                                           ". Available design columns:", paste(design_colnames, collapse=", ")),
                                     type = "error", duration = 10)
                    next  # Skip this comparison
                  }
                }
                
                # Fit contrasts
                fit2 <- limma::contrasts.fit(fit, cm)
                fit2 <- limma::eBayes(fit2, trend = trend_val, robust = robust_flag)
                
                # Extract results
                results <- limma::topTable(fit2, number = Inf, sort.by = "none")
                
                # Store results
                pvalue_col <- paste0(comp_name, "_PValue")
                adjp_col <- paste0(comp_name, "_AdjustedPValue")
                fc_col <- paste0(comp_name, "_Log2FC")
                t_col <- paste0(comp_name, "_t")
                b_col <- paste0(comp_name, "_B")
                
                stat_results[[pvalue_col]] <- results$P.Value
                stat_results[[adjp_col]] <- results$adj.P.Val
                stat_results[[fc_col]] <- results$logFC
                stat_results[[t_col]] <- results$t
                stat_results[[b_col]] <- results$B
            }
            
            values$stat_results <- stat_results
          })
        }
        else if (input$sig_method == "rots") {
          # Check if using lmROTS or standard ROTS
          rots_mode <- input$rots_mode %||% "standard"
          
          if (rots_mode == "lmrots") {
            # =================================================================
            # lmROTS - Linear Model-based ROTS
            # =================================================================
            withProgress(message = "Running lmROTS analysis...", value = 0, {
              # Ensure ROTS package is loaded
              if (!requireNamespace("ROTS", quietly = TRUE)) {
                showNotification("Installing ROTS package...", type = "message", duration = 3)
                if (!requireNamespace("BiocManager", quietly = TRUE)) {
                  install.packages("BiocManager")
                }
                BiocManager::install("ROTS", ask = FALSE)
              }
              library(ROTS)
              
              # Validate metadata is available
              if (is.null(values$metadata) || nrow(values$metadata) == 0) {
                showNotification("lmROTS requires sample metadata. Please upload data with a metadata sheet.", type = "error")
                return(NULL)
              }
              
              # Get selected design variables
              design_vars <- input$lmrots_design_vars
              if (is.null(design_vars) || length(design_vars) == 0) {
                showNotification("Please select at least one design variable for the lmROTS formula.", type = "error")
                return(NULL)
              }
              
              # Build formula string (without dependent variable, as per lmROTS documentation)
              formula_str <- paste(design_vars, collapse = " + ")
              message("lmROTS formula: ", formula_str)
              
              # Get lmROTS parameters
              B_val <- if (!is.null(input$lmrots_B) && !is.na(input$lmrots_B)) input$lmrots_B else 100
              K_val <- if (!is.null(input$lmrots_K) && !is.na(input$lmrots_K)) input$lmrots_K else NULL
              seed_val <- if (!is.null(input$lmrots_seed) && !is.na(input$lmrots_seed)) input$lmrots_seed else NULL
              
              # Get parallel processing settings
              use_parallel <- isTRUE(input$lmrots_parallel)
              n_cores <- if (use_parallel && !is.null(input$lmrots_cores)) {
                min(input$lmrots_cores, parallel::detectCores())
              } else {
                1
              }
              
              # Create BiocParallel backend if parallel processing is enabled
              if (use_parallel) {
                BPPARAM <- BiocParallel::SnowParam(workers = n_cores, stop.on.error = FALSE)
                message("lmROTS using parallel processing with ", n_cores, " cores")
              } else {
                BPPARAM <- BiocParallel::SerialParam()
              }
              
              setProgress(0.1, detail = "Preparing data matrices...")
              
              # Prepare data matrix (genes as rows, samples as columns)
              data_matrix <- as.matrix(values$normalized_data)
              n_features <- nrow(data_matrix)
              min_valid_k <- 6L
              
              # ROTS optimizeModel uses k.test values >= 5 and filters with k < K.
              # If K <= 5 (or default floor(n/4) is too small), internal optimization can fail.
              if (n_features < min_valid_k) {
                showNotification(
                  paste0("lmROTS requires at least ", min_valid_k,
                         " features after filtering. Current feature count: ", n_features,
                         ". Increase retained features or choose another method."),
                  type = "error",
                  duration = 10
                )
                return(NULL)
              }
              
              if (is.null(K_val) || is.na(K_val)) {
                K_val <- max(floor(n_features / 4), min_valid_k)
              }
              K_val <- as.integer(round(K_val))
              if (K_val < min_valid_k) {
                message("lmROTS: K value ", K_val, " is too small; adjusting to ", min_valid_k)
                K_val <- min_valid_k
              }
              if (K_val > n_features) {
                message("lmROTS: K value ", K_val, " exceeds feature count; adjusting to ", n_features)
                K_val <- n_features
              }
              
              # Prepare metadata (ensure samples match columns of data)
              # Need to match sample order between data columns and metadata rows
              sample_names <- colnames(data_matrix)
              
              # Try to find matching column in metadata
              meta_sample_col <- NULL
              for (col in colnames(values$metadata)) {
                if (tolower(col) %in% c("sampleid", "sample_id", "sample", "id")) {
                  meta_sample_col <- col
                  break
                }
              }
              
              if (is.null(meta_sample_col)) {
                # Assume rownames or first column are sample identifiers
                if (!is.null(rownames(values$metadata)) && all(rownames(values$metadata) != seq_len(nrow(values$metadata)))) {
                  meta_samples <- rownames(values$metadata)
                } else {
                  meta_samples <- as.character(values$metadata[, 1])
                  meta_sample_col <- colnames(values$metadata)[1]
                }
              } else {
                meta_samples <- as.character(values$metadata[[meta_sample_col]])
              }
              
              # Match samples
              matched_idx <- match(sample_names, meta_samples)
              if (any(is.na(matched_idx))) {
                # Try alternative matching (partial, case-insensitive)
                unmatched <- sample_names[is.na(matched_idx)]
                message("Warning: Some samples in data not found in metadata: ", paste(head(unmatched, 5), collapse = ", "))
                
                # Remove unmatched samples
                valid_samples <- !is.na(matched_idx)
                if (sum(valid_samples) < 3) {
                  showNotification("Too few matching samples between data and metadata. Please check sample naming.", type = "error")
                  return(NULL)
                }
                
                data_matrix <- data_matrix[, valid_samples, drop = FALSE]
                matched_idx <- matched_idx[valid_samples]
              }
              
              # Reorder metadata to match data columns
              metadata_ordered <- values$metadata[matched_idx, , drop = FALSE]
              rownames(metadata_ordered) <- colnames(data_matrix)
              
              # Extract only the columns needed for the formula
              metadata_for_lmrots <- metadata_ordered[, design_vars, drop = FALSE]
              
              # Convert factor columns properly
              for (col in colnames(metadata_for_lmrots)) {
                if (is.character(metadata_for_lmrots[[col]])) {
                  col_vals <- trimws(as.character(metadata_for_lmrots[[col]]))
                  col_vals[col_vals == ""] <- NA_character_
                  metadata_for_lmrots[[col]] <- as.factor(col_vals)
                }
              }

              # Apply explicit reference level for selected categorical variable, when provided
              selected_ref_var <- input$lmrots_reference_var
              selected_ref_level <- input$lmrots_reference_level
              if (!is.null(selected_ref_var) && nzchar(selected_ref_var) &&
                  selected_ref_var %in% colnames(metadata_for_lmrots)) {
                ref_vals <- trimws(as.character(metadata_for_lmrots[[selected_ref_var]]))
                ref_vals[ref_vals == ""] <- NA_character_
                metadata_for_lmrots[[selected_ref_var]] <- as.factor(ref_vals)

                ref_levels <- levels(metadata_for_lmrots[[selected_ref_var]])
                if (!is.null(selected_ref_level) && nzchar(selected_ref_level) &&
                    selected_ref_level %in% ref_levels) {
                  metadata_for_lmrots[[selected_ref_var]] <-
                    stats::relevel(metadata_for_lmrots[[selected_ref_var]], ref = selected_ref_level)
                  message("lmROTS reference set: ", selected_ref_var, " = ", selected_ref_level)
                }
              }
              
              setProgress(0.2, detail = "Running lmROTS (this may take a while)...")
              
              tryCatch({
                # Set seed for reproducibility
                if (!is.null(seed_val)) set.seed(seed_val)
                
                # Run lmROTS
                lmrots_result <- ROTS::lmROTS(
                  formula = formula_str,
                  data = data_matrix,
                  metadata = as.data.frame(metadata_for_lmrots),
                  B = B_val,
                  K = K_val,
                  seed = seed_val,
                  BPPARAM = BPPARAM
                )
                
                setProgress(0.8, detail = "Processing results...")
                
                # lmROTS returns a regROTS object which is a list of results per variable
                # Process results for each variable in the formula
                
                # Initialize stat_results if not exists
                if (!"ID" %in% colnames(stat_results)) {
                  stat_results$ID <- rownames(data_matrix)
                }
                
                # Get the variable names from the result
                result_vars <- names(lmrots_result)
                
                for (var_name in result_vars) {
                  var_result <- lmrots_result[[var_name]]
                  
                  # Skip if not a valid result object
                  if (is.null(var_result) || is.null(var_result$d)) next
                  
                  # Create column names with variable prefix
                  var_prefix <- paste0("lmROTS_", var_name)
                  
                  pvalue_col <- paste0(var_prefix, "_PValue")
                  fdr_col <- paste0(var_prefix, "_FDR")
                  d_col <- paste0(var_prefix, "_d")
                  coef_col <- paste0(var_prefix, "_Coef")
                  r_col <- paste0(var_prefix, "_R")
                  z_col <- paste0(var_prefix, "_Z")
                  
                  # Store results
                  stat_results[[pvalue_col]] <- var_result$pvalue
                  stat_results[[fdr_col]] <- var_result$FDR
                  stat_results[[d_col]] <- var_result$d
                  stat_results[[r_col]] <- var_result$R
                  stat_results[[z_col]] <- var_result$Z
                  
                  # Store coefficients if available
                  if (!is.null(var_result$coef)) {
                    stat_results[[coef_col]] <- var_result$coef
                  }
                  
                  # Report results
                  pass_count <- sum(var_result$FDR < 0.05, na.rm = TRUE)
                  message(paste0(var_name, ": ", pass_count, " features with FDR < 0.05"))
                }
                
                # Store lmROTS-specific metadata
                values$lmrots_result <- lmrots_result
                values$lmrots_formula <- formula_str
                values$lmrots_variables <- result_vars
                
                setProgress(1, detail = "Complete!")
                
                showNotification(
                  HTML(paste0("<b>lmROTS analysis complete!</b><br>",
                              "Formula: ~ ", formula_str, "<br>",
                              "Variables analyzed: ", paste(result_vars, collapse = ", "))),
                  type = "message",
                  duration = 8
                )
                
              }, error = function(e) {
                showNotification(paste("Error in lmROTS analysis:", e$message), type = "error", duration = 10)
                message("lmROTS error: ", e$message)
              })
              
              values$stat_results <- stat_results
            })
          } else if (rots_mode == "lmerots") {
            # =================================================================
            # lmeROTS - Linear Mixed-Effects Model-based ROTS
            # =================================================================
            withProgress(message = "Running lmeROTS analysis...", value = 0, {
              # Ensure ROTS package is loaded
              if (!requireNamespace("ROTS", quietly = TRUE)) {
                showNotification("Installing ROTS package...", type = "message", duration = 3)
                if (!requireNamespace("BiocManager", quietly = TRUE)) {
                  install.packages("BiocManager")
                }
                BiocManager::install("ROTS", ask = FALSE)
              }
              library(ROTS)
              
              # Validate metadata is available
              if (is.null(values$metadata) || nrow(values$metadata) == 0) {
                showNotification("lmeROTS requires sample metadata. Please upload data with a metadata sheet.", type = "error")
                return(NULL)
              }
              
              # Get selected fixed effects variables
              fixed_vars <- input$lmerots_fixed_vars
              random_effects <- trimws(input$lmerots_random_effects)
              
              if ((is.null(fixed_vars) || length(fixed_vars) == 0) && 
                  (is.null(random_effects) || nchar(random_effects) == 0)) {
                showNotification("Please specify at least one fixed effect or random effect for the lmeROTS formula.", type = "error")
                return(NULL)
              }
              
              # Build formula string
              formula_parts <- c()
              if (!is.null(fixed_vars) && length(fixed_vars) > 0) {
                formula_parts <- c(formula_parts, paste(fixed_vars, collapse = " + "))
              }
              if (!is.null(random_effects) && nchar(random_effects) > 0) {
                formula_parts <- c(formula_parts, random_effects)
              }
              formula_str <- paste(formula_parts, collapse = " + ")
              message("lmeROTS formula: ", formula_str)
              
              # Get lmeROTS parameters
              B_val <- if (!is.null(input$lmerots_B) && !is.na(input$lmerots_B)) input$lmerots_B else 100
              K_val <- if (!is.null(input$lmerots_K) && !is.na(input$lmerots_K)) input$lmerots_K else NULL
              seed_val <- if (!is.null(input$lmerots_seed) && !is.na(input$lmerots_seed)) input$lmerots_seed else NULL
              
              # Get parallel processing settings
              use_parallel <- isTRUE(input$lmerots_parallel)
              n_cores <- if (use_parallel && !is.null(input$lmerots_cores)) {
                min(input$lmerots_cores, parallel::detectCores())
              } else {
                1
              }
              
              # Create BiocParallel backend if parallel processing is enabled
              if (use_parallel) {
                BPPARAM <- BiocParallel::SnowParam(workers = n_cores, stop.on.error = FALSE)
                message("lmeROTS using parallel processing with ", n_cores, " cores")
              } else {
                BPPARAM <- BiocParallel::SerialParam()
              }
              
              setProgress(0.1, detail = "Preparing data matrices...")
              
              # Prepare data matrix (genes as rows, samples as columns)
              data_matrix <- as.matrix(values$normalized_data)
              n_features <- nrow(data_matrix)
              min_valid_k <- 6L
              
              # lmeROTS shares the same optimizeModel constraints as lmROTS.
              if (n_features < min_valid_k) {
                showNotification(
                  paste0("lmeROTS requires at least ", min_valid_k,
                         " features after filtering. Current feature count: ", n_features,
                         ". Increase retained features or choose another method."),
                  type = "error",
                  duration = 10
                )
                return(NULL)
              }
              
              if (is.null(K_val) || is.na(K_val)) {
                K_val <- max(floor(n_features / 4), min_valid_k)
              }
              K_val <- as.integer(round(K_val))
              if (K_val < min_valid_k) {
                message("lmeROTS: K value ", K_val, " is too small; adjusting to ", min_valid_k)
                K_val <- min_valid_k
              }
              if (K_val > n_features) {
                message("lmeROTS: K value ", K_val, " exceeds feature count; adjusting to ", n_features)
                K_val <- n_features
              }
              
              # Prepare metadata (ensure samples match columns of data)
              # Need to match sample order between data columns and metadata rows
              sample_names <- colnames(data_matrix)
              
              # Try to find matching column in metadata
              meta_sample_col <- NULL
              for (col in colnames(values$metadata)) {
                if (tolower(col) %in% c("sampleid", "sample_id", "sample", "id")) {
                  meta_sample_col <- col
                  break
                }
              }
              
              if (is.null(meta_sample_col)) {
                # Assume rownames or first column are sample identifiers
                if (!is.null(rownames(values$metadata)) && all(rownames(values$metadata) != seq_len(nrow(values$metadata)))) {
                  meta_samples <- rownames(values$metadata)
                } else {
                  meta_samples <- as.character(values$metadata[, 1])
                  meta_sample_col <- colnames(values$metadata)[1]
                }
              } else {
                meta_samples <- as.character(values$metadata[[meta_sample_col]])
              }
              
              # Match samples
              matched_idx <- match(sample_names, meta_samples)
              if (any(is.na(matched_idx))) {
                # Try alternative matching (partial, case-insensitive)
                unmatched <- sample_names[is.na(matched_idx)]
                message("Warning: Some samples in data not found in metadata: ", paste(head(unmatched, 5), collapse = ", "))
                
                # Remove unmatched samples
                valid_samples <- !is.na(matched_idx)
                if (sum(valid_samples) < 3) {
                  showNotification("Too few matching samples between data and metadata. Please check sample naming.", type = "error")
                  return(NULL)
                }
                
                data_matrix <- data_matrix[, valid_samples, drop = FALSE]
                matched_idx <- matched_idx[valid_samples]
              }
              
              # Reorder metadata to match data columns
              metadata_ordered <- values$metadata[matched_idx, , drop = FALSE]
              rownames(metadata_ordered) <- colnames(data_matrix)
              
              # Extract all columns that might be needed for the formula
              # (both fixed effects and random effects variables)
              all_formula_vars <- unique(c(fixed_vars, 
                                           gsub(".*\\|([^)]+).*", "\\1", 
                                                unlist(strsplit(random_effects, "\\+")))))
              all_formula_vars <- trimws(all_formula_vars[all_formula_vars != ""])
              
              # Keep only variables that exist in metadata
              all_formula_vars <- intersect(all_formula_vars, colnames(metadata_ordered))
              
              metadata_for_lmerots <- metadata_ordered[, all_formula_vars, drop = FALSE]
              
              # Convert character columns to factors
              for (col in colnames(metadata_for_lmerots)) {
                if (is.character(metadata_for_lmerots[[col]])) {
                  col_vals <- trimws(as.character(metadata_for_lmerots[[col]]))
                  col_vals[col_vals == ""] <- NA_character_
                  metadata_for_lmerots[[col]] <- as.factor(col_vals)
                }
              }

              # Apply explicit reference level for selected categorical fixed-effect variable, when provided
              selected_ref_var <- input$lmerots_reference_var
              selected_ref_level <- input$lmerots_reference_level
              if (!is.null(selected_ref_var) && nzchar(selected_ref_var) &&
                  selected_ref_var %in% colnames(metadata_for_lmerots)) {
                ref_vals <- trimws(as.character(metadata_for_lmerots[[selected_ref_var]]))
                ref_vals[ref_vals == ""] <- NA_character_
                metadata_for_lmerots[[selected_ref_var]] <- as.factor(ref_vals)

                ref_levels <- levels(metadata_for_lmerots[[selected_ref_var]])
                if (!is.null(selected_ref_level) && nzchar(selected_ref_level) &&
                    selected_ref_level %in% ref_levels) {
                  metadata_for_lmerots[[selected_ref_var]] <-
                    stats::relevel(metadata_for_lmerots[[selected_ref_var]], ref = selected_ref_level)
                  message("lmeROTS reference set: ", selected_ref_var, " = ", selected_ref_level)
                }
              }
              
              # Validate random effects have sufficient levels
              if (!is.null(random_effects) && nchar(random_effects) > 0) {
                # Extract random effects variable names
                random_vars <- gsub(".*\\|([^)]+).*", "\\1", 
                                    unlist(strsplit(random_effects, "\\+")))
                random_vars <- trimws(random_vars)
                
                for (rv in random_vars) {
                  if (rv %in% colnames(metadata_for_lmerots)) {
                    n_levels <- length(unique(metadata_for_lmerots[[rv]]))
                    if (n_levels < 2) {
                      showNotification(paste0("Random effect variable '", rv, 
                                              "' must have at least 2 levels. Found: ", n_levels), 
                                       type = "error")
                      return(NULL)
                    }
                    message("Random effect '", rv, "' has ", n_levels, " levels")
                  }
                }
              }
              
              setProgress(0.2, detail = "Running lmeROTS (this may take a while)...")
              
              tryCatch({
                # Set seed for reproducibility
                if (!is.null(seed_val)) set.seed(seed_val)
                
                # Run lmeROTS
                lmerots_result <- ROTS::lmeROTS(
                  formula = formula_str,
                  data = data_matrix,
                  metadata = as.data.frame(metadata_for_lmerots),
                  B = B_val,
                  K = K_val,
                  seed = seed_val,
                  BPPARAM = BPPARAM
                )
                
                setProgress(0.8, detail = "Processing results...")
                
                # lmeROTS returns a regROTS object which is a list of results per variable
                # Process results for each variable in the formula
                
                # Initialize stat_results if not exists
                if (!"ID" %in% colnames(stat_results)) {
                  stat_results$ID <- rownames(data_matrix)
                }
                
                # Get the variable names from the result
                result_vars <- names(lmerots_result)
                
                for (var_name in result_vars) {
                  var_result <- lmerots_result[[var_name]]
                  
                  # Skip if not a valid result object
                  if (is.null(var_result) || is.null(var_result$d)) next
                  
                  # Create column names with variable prefix
                  var_prefix <- paste0("lmeROTS_", var_name)
                  
                  pvalue_col <- paste0(var_prefix, "_PValue")
                  fdr_col <- paste0(var_prefix, "_FDR")
                  d_col <- paste0(var_prefix, "_d")
                  coef_col <- paste0(var_prefix, "_Coef")
                  r_col <- paste0(var_prefix, "_R")
                  z_col <- paste0(var_prefix, "_Z")
                  
                  # Store results
                  stat_results[[pvalue_col]] <- var_result$pvalue
                  stat_results[[fdr_col]] <- var_result$FDR
                  stat_results[[d_col]] <- var_result$d
                  stat_results[[r_col]] <- var_result$R
                  stat_results[[z_col]] <- var_result$Z
                  
                  # Store coefficients if available
                  if (!is.null(var_result$coef)) {
                    stat_results[[coef_col]] <- var_result$coef
                  }
                  
                  # Report results
                  pass_count <- sum(var_result$FDR < 0.05, na.rm = TRUE)
                  message(paste0(var_name, ": ", pass_count, " features with FDR < 0.05"))
                }
                
                # Store lmeROTS-specific metadata
                values$lmerots_result <- lmerots_result
                values$lmerots_formula <- formula_str
                values$lmerots_variables <- result_vars
                
                setProgress(1, detail = "Complete!")
                
                showNotification(
                  HTML(paste0("<b>lmeROTS analysis complete!</b><br>",
                              "Formula: ~ ", formula_str, "<br>",
                              "Variables analyzed: ", paste(result_vars, collapse = ", "))),
                  type = "message",
                  duration = 8
                )
                
              }, error = function(e) {
                showNotification(paste("Error in lmeROTS analysis:", e$message), type = "error", duration = 10)
                message("lmeROTS error: ", e$message)
              })
              
              values$stat_results <- stat_results
            })
          } else {
            # =================================================================
            # Standard ROTS (two-group pairwise comparisons)
            # =================================================================
          withProgress(message = "Running ROTS analysis...", value = 0, {
            # Ensure ROTS is loaded
            if (!requireNamespace("ROTS", quietly = TRUE)) {
              install.packages("ROTS")
              library(ROTS)
            }
            
            # Get parameters
            B_val <- if (!is.null(input$rots_B)) input$rots_B else 1000
            K_val <- if (!is.null(input$rots_K) && !is.na(input$rots_K)) input$rots_K else NULL
            seed_val <- if (!is.null(input$rots_seed) && !is.na(input$rots_seed)) input$rots_seed else 123
            
            # Get parallel processing option
            use_parallel <- FALSE  # Default to FALSE as ROTS has issues with BiocParallel
            n_cores <- 1  # Default to 1 core
            
            # Check if parallel processing is requested
            if (input$rots_parallel) {
              # Inform user that parallel processing is not supported
              # showNotification("Parallel processing with BiocParallel is not supported for ROTS.
              #                   Using single-core processing instead.",
              #                  type = "warning",
              #                  duration = 5)
            }
            
            # Detect available cores, but don't use them for ROTS
            available_cores <- parallel::detectCores()
            
            # Get pairwise combinations to use (respects pre-analysis modal selection)
            pairwise_combinations <- get_pairwise_combinations_for_analysis()
            message("=== PAIRWISE COMBINATIONS FOR ANALYSIS ===")
            message("  nrow(pairwise_combinations): ", nrow(pairwise_combinations))
            if (nrow(pairwise_combinations) > 0) {
              message("  first few combinations: ", paste(head(pairwise_combinations$Group_1, 3), "vs", head(pairwise_combinations$Group_2, 3)))
            }
            n_comparisons <- nrow(pairwise_combinations)
            comp_counter <- 0
            
            # Pre-check for insufficient data across all comparisons
            insufficient_data_summary <- list()
            
            # First, scan all pairwise comparisons to collect insufficient data information
            for (comp_idx in seq_len(n_comparisons)) {
              g1 <- pairwise_combinations[comp_idx, "Group_1"]
              g2 <- pairwise_combinations[comp_idx, "Group_2"]
              
              # Find group indices
              group1_idx <- which(values$unique_groups == g1)
              group2_idx <- which(values$unique_groups == g2)
              
              if (length(group1_idx) == 0 || length(group2_idx) == 0) next
              
              group1_cols <- values$group_column_indices[[group1_idx]]
              group2_cols <- values$group_column_indices[[group2_idx]]
              data1 <- values$normalized_data[, group1_cols, drop = FALSE]
              data2 <- values$normalized_data[, group2_cols, drop = FALSE]
              
              # Identify rows with sufficient non-missing values in each group
              enough_data_group1 <- rowSums(!is.na(data1)) >= 2
              enough_data_group2 <- rowSums(!is.na(data2)) >= 2
              
              # Count features with insufficient data in each group
              insufficient_group1 <- sum(!enough_data_group1)
              insufficient_group2 <- sum(!enough_data_group2)
              
              # Store in summary if there are any insufficient features
              if(insufficient_group1 > 0 || insufficient_group2 > 0) {
                comparison_name <- paste(g1, "vs", g2)
                insufficient_data_summary[[comparison_name]] <- list(
                  group1_name = g1,
                  group2_name = g2,
                  group1_insufficient = insufficient_group1,
                  group2_insufficient = insufficient_group2,
                  total_invalid = sum(!(enough_data_group1 & enough_data_group2))
                )
              }
            }
            
            # Display a consolidated notification about insufficient data if needed
            if(length(insufficient_data_summary) > 0) {
              # Build a consolidated message about all comparisons with issues
              message_parts <- c("ROTS analysis found features with insufficient data (less than 2 non-missing values):")
              
              for(comp_name in names(insufficient_data_summary)) {
                summary_item <- insufficient_data_summary[[comp_name]]
                message_parts <- c(message_parts,
                                   paste0(comp_name, ": ",
                                          "Group '", summary_item$group1_name, "': ", summary_item$group1_insufficient, " features, ",
                                          "Group '", summary_item$group2_name, "': ", summary_item$group2_insufficient, " features ",
                                          "(", summary_item$total_invalid, " total invalid features)"))
              }
              
              message_parts <- c(message_parts, "Please either remove these features or impute the missing values.")
              
              # Show a consolidated notification
              showNotification(
                HTML(paste0("<b>ROTS Analysis Data Warning</b><br>",
                            paste(message_parts, collapse = "<br>"))),
                type = "warning",
                duration = 15
              )
            }
            
            # Loop through each pairwise comparison
            for (comp_idx in seq_len(n_comparisons)) {
              comp_counter <- comp_counter + 1
              
              g1 <- pairwise_combinations[comp_idx, "Group_1"]
              g2 <- pairwise_combinations[comp_idx, "Group_2"]
              
              setProgress(comp_counter / n_comparisons,
                          detail = paste("Analyzing", g1, "vs", g2))
              
              # Find group indices
              group1_idx <- which(values$unique_groups == g1)
              group2_idx <- which(values$unique_groups == g2)
              
              if (length(group1_idx) == 0 || length(group2_idx) == 0) next
              
              # Get group indices and data
              group1_cols <- values$group_column_indices[[group1_idx]]
              group2_cols <- values$group_column_indices[[group2_idx]]
              
              data1 <- values$normalized_data[, group1_cols, drop = FALSE]
              data2 <- values$normalized_data[, group2_cols, drop = FALSE]
              
              # Run ROTS with error handling
              tryCatch({
                # Identify rows with sufficient non-missing values in each group
                enough_data_group1 <- rowSums(!is.na(data1)) >= 2
                enough_data_group2 <- rowSums(!is.na(data2)) >= 2
                
                comparison_name <- paste(g1, "vs", g2)
                  
                  # If this is a comparison with insufficient data (already reported in the summary),
                  # we'll continue with the valid rows, but won't show an error again
                  valid_rows <- which(enough_data_group1 & enough_data_group2)
                  
                  if(length(valid_rows) == 0) {
                    # If no valid rows, we'll add NA columns but skip ROTS analysis
                    # This comparison's issue was already reported in the summary notification
                    mean1 <- rowMeans(data1, na.rm = TRUE)
                    mean2 <- rowMeans(data2, na.rm = TRUE)
                    
                    # Calculate fold change based on data scale
                    if (is_data_log_scale()) {
                      log2_fc <- mean2 - mean1
                    } else {
                      log2_fc <- log2(mean2 / mean1)
                    }
                    log2_fc[is.infinite(log2_fc)] <- NA
                    
                    # Add NA columns to maintain consistent structure
                    pvalue_col <- paste0(comparison_name, "_PValue")
                    fdr_col <- paste0(comparison_name, "_FDR")
                    fc_col <- paste0(comparison_name, "_Log2FC")
                    rots_d_col <- paste0(comparison_name, "_ROTS_d")
                    rots_r_col <- paste0(comparison_name, "_ROTS_R")
                    z_col <- paste0(comparison_name, "_ROTS_Z")  # New column for Z score
                    
                    stat_results[[pvalue_col]] <- rep(NA, nrow(values$normalized_data))
                    stat_results[[fdr_col]] <- rep(NA, nrow(values$normalized_data))
                    stat_results[[fc_col]] <- log2_fc
                    stat_results[[rots_d_col]] <- rep(NA, nrow(values$normalized_data))
                    stat_results[[rots_r_col]] <- rep(NA, nrow(values$normalized_data))
                    stat_results[[z_col]] <- rep(NA, nrow(values$normalized_data))  # Initialize Z score column with NAs
                    
                    next
                  }
                  
                  # Filter data to only include rows with sufficient data
                  filtered_data1 <- data1[valid_rows, , drop = FALSE]
                  filtered_data2 <- data2[valid_rows, , drop = FALSE]
                  
                  # Create data matrix and group vector for ROTS
                  data_matrix <- cbind(filtered_data1, filtered_data2)
                  group_vector <- c(rep(1, ncol(data1)), rep(2, ncol(data2)))
                  
                  # Set seed for reproducibility
                  set.seed(seed_val)
                  
                  # Create ROTS options
                  rots_opts <- list(B = B_val, K = K_val, paired = FALSE,
                                    log = FALSE, progress = FALSE) # Don't use ROTS's own progress bar
                  
                  # Add parallel param if using parallel
                  if (use_parallel) {
                    rots_opts$nCores <- n_cores
                  }
                  
                  # Run ROTS
                  rots_result <- do.call(ROTS::ROTS, c(list(data = data_matrix,
                                                            groups = group_vector),
                                                       rots_opts))
                  
                  # Create column names
                  pvalue_col <- paste0(comparison_name, "_PValue")
                  fdr_col <- paste0(comparison_name, "_FDR")
                  fc_col <- paste0(comparison_name, "_Log2FC")
                  rots_d_col <- paste0(comparison_name, "_ROTS_d")
                  rots_r_col <- paste0(comparison_name, "_ROTS_R")
                  z_col <- paste0(comparison_name, "_ROTS_Z")  # New column for Z score
                  
                  # Calculate log2 fold change based on data scale
                  mean1 <- rowMeans(data1, na.rm = TRUE)
                  mean2 <- rowMeans(data2, na.rm = TRUE)
                  
                  # When data is log-scale: log2_fc = mean2 - mean1 (subtraction in log space)
                  # When data is linear: log2_fc = log2(mean2 / mean1) (log of division)
                  if (is_data_log_scale()) {
                    log2_fc <- mean2 - mean1
                  } else {
                    log2_fc <- log2(mean2 / mean1)
                  }
                  log2_fc[is.infinite(log2_fc)] <- NA
                  
                  # Add columns to stat_results
                  stat_results[[pvalue_col]] <- rep(NA, nrow(values$normalized_data))
                  stat_results[[fdr_col]] <- rep(NA, nrow(values$normalized_data))
                  stat_results[[fc_col]] <- log2_fc
                  stat_results[[rots_d_col]] <- rep(NA, nrow(values$normalized_data))
                  stat_results[[rots_r_col]] <- rep(NA, nrow(values$normalized_data))
                  stat_results[[z_col]] <- rep(NA, nrow(values$normalized_data))  # Initialize Z score column
                  
                  # Fill in results only for valid rows
                  stat_results[[pvalue_col]][valid_rows] <- rots_result$pvalue
                  stat_results[[fdr_col]][valid_rows] <- rots_result$FDR
                  stat_results[[rots_d_col]][valid_rows] <- rots_result$d
                  stat_results[[rots_r_col]][valid_rows] <- rots_result$R
                  stat_results[[z_col]][valid_rows] <- rots_result$Z  # Store the Z score
                  
                  # Report feature counts that pass threshold (for user info)
                  pass_count <- sum(rots_result$FDR < 0.05, na.rm = TRUE)
                  message(paste0(comparison_name, ": ", pass_count, " features with FDR < 0.05"))
                  
                }, error = function(e) {
                  message("Error in ROTS analysis: ", e$message)
                  
                  # Always calculate log2_fc regardless of error, based on data scale
                  mean1 <- rowMeans(data1, na.rm = TRUE)
                  mean2 <- rowMeans(data2, na.rm = TRUE)
                  
                  # Calculate fold change based on data scale
                  if (is_data_log_scale()) {
                    log2_fc <- mean2 - mean1
                  } else {
                    log2_fc <- log2(mean2 / mean1)
                  }
                  log2_fc[is.infinite(log2_fc)] <- NA
                  # Add columns with NA values so the structure is consistent
                  comparison_name <- paste(g1, "vs", g2)
                  stat_results[[paste0(comparison_name, "_PValue")]] <- NA
                  stat_results[[paste0(comparison_name, "_FDR")]] <- NA
                  stat_results[[paste0(comparison_name, "_Log2FC")]] <- log2_fc
                  stat_results[[paste0(comparison_name, "_ROTS_d")]] <- NA
                  stat_results[[paste0(comparison_name, "_ROTS_R")]] <- NA
                  stat_results[[paste0(comparison_name, "_ROTS_Z")]] <- NA  # Include Z score in error case too
                })
            }
            values$stat_results <- merge_bootstrap_columns(stat_results)
          })
          }  # End of else block for standard ROTS (rots_mode != "lmrots")
        } else {
          # For pairwise comparisons (default to Wilcoxon if more than 2 groups)
          # Get pairwise combinations to use (respects pre-analysis modal selection)
          message("=== STATISTICAL CALCULATION ===")
          message("  dual_analysis_current_level: ", values$dual_analysis_current_level)
          message("  unique_groups: ", paste(values$unique_groups, collapse=", "))
          message("  current_pairwise_combinations: ", if(is.null(values$current_pairwise_combinations)) "NULL" else paste(nrow(values$current_pairwise_combinations), "rows"))
          message("  sig_method: ", input$sig_method)
          message("  bootstrap_enabled: ", input$bootstrap_enabled)
          
          pairwise_combinations <- get_pairwise_combinations_for_analysis()
          message("  pairwise_combinations from get_pairwise_combinations_for_analysis(): ", if(is.null(pairwise_combinations)) "NULL" else paste(nrow(pairwise_combinations), "rows"))
          if (!is.null(pairwise_combinations) && nrow(pairwise_combinations) > 0) {
            message("  First comparison: ", pairwise_combinations[1, "Group_1"], " vs ", pairwise_combinations[1, "Group_2"])
          }
          
          n_comparisons <- nrow(pairwise_combinations)
          message("  ENTERING PAIRWISE LOOP: n_comparisons = ", n_comparisons)
          
          for (comp_idx in seq_len(n_comparisons)) {
            group1 <- pairwise_combinations[comp_idx, "Group_1"]
            group2 <- pairwise_combinations[comp_idx, "Group_2"]
            comparison_name <- paste(group1, "vs", group2)
            message("    [Pairwise] comp_idx=", comp_idx, " ", comparison_name)
            
            # Find group indices
            group1_idx <- which(values$unique_groups == group1)
            group2_idx <- which(values$unique_groups == group2)
            
            if (length(group1_idx) == 0 || length(group2_idx) == 0) next
            
            # Get data for each group
            group1_columns <- values$group_column_indices[[group1_idx]]
            group2_columns <- values$group_column_indices[[group2_idx]]
              
            # Prepare ANCOVA p-values for pairwise comparison when requested
            ancova_p_values <- NULL
            if (input$sig_method == "anova" && isTRUE(input$anova_include_covariates)) {
              covariates <- input$anova_covariates %||% NULL
              if (is.null(covariates) || length(covariates) == 0) {
                showNotification("Please select at least one continuous covariate for ANCOVA.", type = "error")
              } else if (is.null(values$metadata) || nrow(values$metadata) == 0) {
                showNotification("ANCOVA requires sample metadata with covariates. Please upload data with a metadata sheet.", type = "error")
              } else {
                # Align metadata to the pairwise sample set
                data_matrix <- as.matrix(values$normalized_data[, c(group1_columns, group2_columns), drop = FALSE])
                sample_names <- colnames(data_matrix)
                
                meta_sample_col <- NULL
                for (col in colnames(values$metadata)) {
                  if (tolower(col) %in% c("sampleid", "sample_id", "sample", "id")) {
                    meta_sample_col <- col
                    break
                  }
                }
                
                if (is.null(meta_sample_col)) {
                  if (!is.null(rownames(values$metadata)) && all(rownames(values$metadata) != seq_len(nrow(values$metadata)))) {
                    meta_samples <- rownames(values$metadata)
                  } else {
                    meta_samples <- as.character(values$metadata[, 1])
                    meta_sample_col <- colnames(values$metadata)[1]
                  }
                } else {
                  meta_samples <- as.character(values$metadata[[meta_sample_col]])
                }
                
                matched_idx <- match(sample_names, meta_samples)
                if (any(is.na(matched_idx))) {
                  valid_samples <- !is.na(matched_idx)
                  if (sum(valid_samples) < 3) {
                    showNotification("Too few matching samples between data and metadata for ANCOVA.", type = "error")
                  } else {
                    data_matrix <- data_matrix[, valid_samples, drop = FALSE]
                    sample_names <- sample_names[valid_samples]
                    matched_idx <- matched_idx[valid_samples]
                  }
                }
                
                if (ncol(data_matrix) >= 3) {
                  metadata_ordered <- values$metadata[matched_idx, , drop = FALSE]
                  rownames(metadata_ordered) <- sample_names
                  
                  group_labels <- ifelse(sample_names %in% colnames(values$normalized_data)[group1_columns], group1, group2)
                  group_labels <- factor(group_labels, levels = c(group1, group2))
                  
                  covariate_data <- metadata_ordered[, covariates, drop = FALSE]
                  for (col in colnames(covariate_data)) {
                    covariate_data[[col]] <- as.numeric(covariate_data[[col]])
                  }
                  
                  covariate_complete <- complete.cases(covariate_data)
                  if (sum(covariate_complete) < 3) {
                    showNotification("ANCOVA covariates have too many missing values for the selected groups.", type = "warning")
                  } else {
                    data_matrix <- data_matrix[, covariate_complete, drop = FALSE]
                    group_labels <- group_labels[covariate_complete]
                    covariate_data <- covariate_data[covariate_complete, , drop = FALSE]
                    
                    use_type3 <- isTRUE(input$anova_type3)
                    if (use_type3 && !requireNamespace("car", quietly = TRUE)) {
                      install.packages("car")
                    }
                    
                    ancova_formula <- as.formula(paste0("feature_value ~ Group + ", paste(covariates, collapse = " + ")))
                    ancova_p_values <- rep(NA_real_, nrow(values$normalized_data))
                    
                    for (f in seq_len(nrow(data_matrix))) {
                      feature_values <- as.numeric(data_matrix[f, ])
                      if (sum(!is.na(feature_values)) < 3) next
                      
                      ancova_df <- data.frame(
                        feature_value = feature_values,
                        Group = group_labels
                      )
                      ancova_df <- cbind(ancova_df, covariate_data)
                      ancova_df <- ancova_df[complete.cases(ancova_df), ]
                      
                      if (nrow(ancova_df) < 3) next
                      
                      ancova_model <- lm(ancova_formula, data = ancova_df)
                      if (use_type3) {
                        type3_result <- car::Anova(ancova_model, type = 3)
                        group_row <- which(rownames(type3_result) == "Group")
                        if (length(group_row) > 0) {
                          ancova_p_values[f] <- type3_result[group_row, "Pr(>F)"]
                        }
                      } else {
                        anova_result <- anova(ancova_model)
                        group_row <- which(rownames(anova_result) == "Group")
                        if (length(group_row) > 0) {
                          ancova_p_values[f] <- anova_result[group_row, "Pr(>F)"]
                        }
                      }
                    }
                  }
                }
              }
            }
            
            # Calculate p-values
            p_values <- if (!is.null(ancova_p_values)) {
              ancova_p_values
            } else {
              apply(values$normalized_data, 1, function(row) {
                group1_data <- row[group1_columns]
                group2_data <- row[group2_columns]
                
                # Remove NAs
                group1_data <- group1_data[!is.na(group1_data)]
                group2_data <- group2_data[!is.na(group2_data)]
                
                # Check if we have enough data
                if (length(group1_data) >= 2 && length(group2_data) >= 2) {
                  if (input$sig_method == "wilcox") {
                    tryCatch({
                      wilcox.test(group1_data, group2_data)$p.value
                    }, error = function(e) { NA })
                  } else if (input$sig_method == "t.test") {
                    tryCatch({
                      t.test(group1_data, group2_data)$p.value
                    }, error = function(e) { NA })
                  } else if (input$sig_method == "kruskal") {
                    tryCatch({
                      kruskal.test(list(group1_data, group2_data))$p.value
                    }, error = function(e) { NA })
                  } else if (input$sig_method == "anova") {
                    tryCatch({
                      Group <- factor(c(rep(group1, length(group1_data)), rep(group2, length(group2_data))),
                                      levels = c(group1, group2))
                      anova_result <- anova(lm(c(group1_data, group2_data) ~ Group))
                      group_row <- which(rownames(anova_result) == "Group")
                      if (length(group_row) > 0) {
                        anova_result[group_row, "Pr(>F)"]
                      } else {
                        NA
                      }
                    }, error = function(e) { NA })
                  } else {
                    NA
                  }
                } else {
                  NA
                }
              })
            }
              
              # Calculate fold change as Group2/Group1 to match documentation
              fold_changes <- apply(values$normalized_data, 1, function(row) {
                group1_mean <- mean(row[group1_columns], na.rm = TRUE)
                group2_mean <- mean(row[group2_columns], na.rm = TRUE)
                return(group2_mean / group1_mean)
              })
              
              # Calculate log2 fold change
              log2_fold_changes <- log2(fold_changes)
              log2_fold_changes[is.infinite(log2_fold_changes)] <- NA
              
              # Adjust p-values
              adjusted_p_values <- p.adjust(p_values, method = get_correction_method())
              
              # Add columns to results
              stat_results[[paste0(comparison_name, "_PValue")]] <- p_values
              stat_results[[paste0(comparison_name, "_AdjPValue")]] <- adjusted_p_values
              stat_results[[paste0(comparison_name, "_FoldChange")]] <- fold_changes
              stat_results[[paste0(comparison_name, "_Log2FC")]] <- log2_fold_changes
              message("      Added ", comparison_name, " columns")
          }
          message("  PAIRWISE LOOP COMPLETE. stat_results now: ", ncol(stat_results), " cols = ", paste(colnames(stat_results), collapse=", "))
        }
      }
    }
    # Store the statistical results
    values$stat_results <- merge_bootstrap_columns(stat_results)
    
    # ============================================================================
    # DUAL GROUPING ANALYSIS - Store results for current level
    # ============================================================================
    if (isTRUE(values$has_dual_grouping)) {
      message("=== DUAL GROUPING: Storing results ===")
      message("  dual_analysis_current_level: ", values$dual_analysis_current_level)
      message("  biological_stat_results NULL? ", is.null(values$biological_stat_results))
      message("  experimental_stat_results NULL? ", is.null(values$experimental_stat_results))
      
      # Store results based on which grouping level was used for this analysis
      if (isTRUE(values$dual_analysis_current_level == "experimental")) {
        # This was the experimental grouping analysis
        message("=== Saving EXPERIMENTAL stat_results ===")
        message("  experimental stat_results dimensions: ", paste(dim(values$stat_results), collapse=" x "))
        message("  experimental stat_results columns: ", paste(colnames(values$stat_results), collapse=", "))
        if (!is_valid_stat_results(values$stat_results)) {
          message("  WARNING: experimental stat_results missing comparison columns; not caching")
          values$experimental_stat_results <- NULL
        } else {
          values$experimental_stat_results <- values$stat_results
          # Cache the results
          store_dual_analysis_cache("experimental", values$stat_results)
        }
        
        showNotification("Experimental grouping analysis complete", type = "message", duration = 3)
        
        # Clear the flags to prevent infinite loops
        values$dual_analysis_current_level <- NULL
        values$dual_analysis_in_progress <- FALSE
        values$dual_analysis_trigger_rerun <- NULL  # CRITICAL: Clear trigger to prevent re-triggering
        
        # Restore grouping values and stat_results based on active level
        if (values$active_grouping_level == "biological") {
          values$stat_results <- values$biological_stat_results
          values$unique_groups <- values$biological_unique_groups
          values$group_column_indices <- values$biological_group_column_indices
          values$current_pairwise_combinations <- values$biological_pairwise_combinations
        } else {
          if (!is.null(values$experimental_stat_results)) {
            values$stat_results <- values$experimental_stat_results
            values$unique_groups <- values$experimental_unique_groups
            values$group_column_indices <- values$experimental_group_column_indices
            values$current_pairwise_combinations <- values$experimental_pairwise_combinations
            message("  stat_results now shows experimental data with ", ncol(values$stat_results), " columns")
          } else {
            message("  experimental stat_results still unavailable; retaining current stat_results")
          }
        }
        showNotification("Dual-level analysis complete! Use the toggle buttons to switch between results.", 
                         type = "message", duration = 5)
      } else if (isTRUE(values$dual_analysis_current_level == "biological")) {
        # This was the biological grouping analysis
        message("=== Saving BIOLOGICAL stat_results ===")
        values$biological_stat_results <- values$stat_results
        
        # Cache the results
        store_dual_analysis_cache("biological", values$stat_results)
        
        # Check if experimental analysis is already complete - if so, don't re-trigger
        exp_already_complete <- !is.null(values$experimental_stat_results) && 
                                is_valid_stat_results(values$experimental_stat_results)
        
        if (exp_already_complete) {
          message("=== EXPERIMENTAL ANALYSIS ALREADY COMPLETE - Skipping re-trigger ===")
          values$dual_analysis_current_level <- NULL
          values$dual_analysis_in_progress <- FALSE
          values$dual_analysis_trigger_rerun <- NULL
          showNotification("Both biological and experimental analyses are complete.", 
                         type = "message", duration = 3)
        } else {
          showNotification("Biological grouping analysis complete. Running experimental grouping analysis...", 
                           type = "message", duration = 3)
          
          # Now switch to experimental grouping and trigger re-analysis
          message("=== Setting up EXPERIMENTAL analysis ===")
          values$dual_analysis_current_level <- "experimental"
          values$dual_analysis_in_progress <- TRUE  # Set flag to prevent concurrent triggers
          
          # Swap to experimental grouping values
          values$unique_groups <- values$experimental_unique_groups
          values$group_column_indices <- values$experimental_group_column_indices
          values$current_pairwise_combinations <- values$experimental_pairwise_combinations
          message("  experimental_unique_groups: ", paste(values$experimental_unique_groups, collapse=", "))
          message("  Triggering re-analysis...")
          
          # Trigger re-analysis by setting a flag
          values$dual_analysis_trigger_rerun <- Sys.time()
        }
      } else {
        # First analysis run - determine if we need dual analysis
        # Default first run uses biological grouping
        values$biological_stat_results <- values$stat_results
        
        # Cache the results
        store_dual_analysis_cache("biological", values$stat_results)
        
        # Check if experimental grouping is different
        message("=== CHECKING EXPERIMENTAL ANALYSIS CONDITION ===")
        message("  biological_unique_groups: ", if(is.null(values$biological_unique_groups)) "NULL" else paste(values$biological_unique_groups, collapse=", "))
        message("  experimental_unique_groups: ", if(is.null(values$experimental_unique_groups)) "NULL" else paste(values$experimental_unique_groups, collapse=", "))
        message("  groups identical? ", identical(values$biological_unique_groups, values$experimental_unique_groups))
        
        if (!is.null(values$experimental_unique_groups) && 
            !identical(values$biological_unique_groups, values$experimental_unique_groups)) {
          # Check if experimental analysis is already complete - if so, don't re-trigger
          exp_already_complete <- !is.null(values$experimental_stat_results) && 
                                  is_valid_stat_results(values$experimental_stat_results)
          
          if (exp_already_complete) {
            message("  CONDITION MET but experimental already complete - Skipping re-trigger")
            values$dual_analysis_current_level <- NULL
            values$dual_analysis_in_progress <- FALSE
            values$dual_analysis_trigger_rerun <- NULL
          } else {
            message("  CONDITION MET: Running experimental analysis")
            showNotification("First-level (biological) analysis complete. Running second-level (experimental) analysis...", 
                             type = "message", duration = 3)
            
            # Set up for experimental analysis
            values$dual_analysis_in_progress <- TRUE
            values$dual_analysis_current_level <- "experimental"
            
            # Swap to experimental grouping values
            values$unique_groups <- values$experimental_unique_groups
            values$group_column_indices <- values$experimental_group_column_indices
            values$current_pairwise_combinations <- values$experimental_pairwise_combinations
            
            # Trigger re-analysis
            values$dual_analysis_trigger_rerun <- Sys.time()
          }
        } else {
          message("  CONDITION NOT MET: Skipping experimental analysis")
          # No experimental grouping or same as biological
          values$experimental_stat_results <- NULL
        }
      }
    }
    # ============================================================================
    # END DUAL GROUPING ANALYSIS
    # ============================================================================
    
    # Pre-compute and store pairwise combinations for the modal
    # Only fall back to inferred combinations when none are currently set
    # Skip this update if we're in the middle of dual analysis (about to re-run)
    if (!isTRUE(values$dual_analysis_in_progress)) {
      if (is.null(values$current_pairwise_combinations) || nrow(values$current_pairwise_combinations) == 0) {
        values$current_pairwise_combinations <- get_actual_pairwise_combinations()
      }
    }
    
    # Show the Review Pairwise Order button now that analysis is complete
    shinyjs::show("reviewPairwiseOrderBtn")
  })
  
  # Render the statistics results table with improved formatting
  # This is placed outside the observeEvent to ensure it's always available
  output$statsResultsTable <- DT::renderDataTable({
    # CRITICAL: Explicit reactive dependencies to ensure proper re-rendering
    # when switching between simple and complex experiments
    # These dependencies ensure the table updates when:
    # 1. Main stat_results changes (simple experiments)
    # 2. Dual grouping stat_results change (complex experiments)
    # 3. Dual grouping state changes (switching experiment types)
    dual_state <- values$has_dual_grouping
    active_level <- values$active_grouping_level
    bio_stats <- values$biological_stat_results
    exp_stats <- values$experimental_stat_results
    main_stats <- values$stat_results
    
    # Prefer the active-level helper to keep views in sync
    display_data <- get_active_stat_results()
    req(display_data)
    
    message("=== STATS TABLE RENDER ===")
    message("  has_dual_grouping: ", dual_state)
    message("  stat_results dimensions: ", paste(dim(display_data), collapse=" x "))
    message("  stat_results columns: ", paste(colnames(display_data), collapse=", "))
    message("  active_grouping_level: ", active_level)
    
    tryCatch({
      dt <- DT::datatable(
        display_data,
        options = list(
          pageLength = 15,
          scrollX = TRUE,
          autoWidth = TRUE
        ),
        rownames = FALSE
      )
      # Round only numeric columns (avoids errors when showing placeholder for experimental stats)
      num_cols <- which(sapply(display_data, is.numeric))
      if (length(num_cols) > 0) {
        dt <- dt %>% DT::formatRound(columns = num_cols, digits = 6)
      }
      
      # Add visual indication for bootstrap columns if bootstrap is enabled
      if (input$bootstrap_enabled == "yes") {
        bootstrap_cols <- grep("Bootstrap", colnames(display_data))
        if (length(bootstrap_cols) > 0) {
          dt <- dt %>% DT::formatStyle(
            columns = bootstrap_cols,
            backgroundColor = "#E6F3FF",
            fontWeight = "bold"
          )
        }
      }
      
      # Add visual indication for global test columns
      global_cols <- grep("Global", colnames(display_data))
      if (length(global_cols) > 0) {
        dt <- dt %>% DT::formatStyle(
          columns = global_cols,
          backgroundColor = "#FFEDCC",
          fontWeight = "bold"
        )
      }
      
      message("  Stats table created successfully")
      return(dt)
    }, error = function(e) {
      message("ERROR in stats table render: ", e$message)
      # Return a simple table with error message
      return(DT::datatable(data.frame(Error = "Failed to render statistics table", Details = e$message)))
    })
  })
  
  # Check and update yulab.utils version
  if (!requireNamespace("yulab.utils", quietly = TRUE) ||
      packageVersion("yulab.utils") < "0.1.9") {
    message("Updating yulab.utils package to required version...")
    
    # Detach if loaded
    if ("yulab.utils" %in% (.packages())) {
      detach("package:yulab.utils", unload = TRUE, force = TRUE)
    }
    
    # Install the package
    BiocManager::install("yulab.utils", update = FALSE)
    
    # Verify installation
    if (packageVersion("yulab.utils") >= "0.1.9") {
      message("Successfully updated yulab.utils to ", packageVersion("yulab.utils"))
    } else {
      warning("Failed to update yulab.utils to the required version")
    }
  }
  
  # Add reactive observers to update dependent tabs when MA or Volcano results change
  observe({
    # Watch for changes in MA plot data
    req(values$ma_plot_data)
    
    # If this is the first time MA data is available, switch to the Differential Analysis tab
    # Only do this for auto-generated results (not button presses)
    isolate({
      if (is.null(values$ma_tab_shown) && !is.null(values$last_ma_btn_press_time)) {
        if (as.numeric(Sys.time()) - values$last_ma_btn_press_time > 1) {
          # This was auto-generated, not from button press
          values$ma_tab_shown <- TRUE
        }
      }
    })
    
    # Update dropdowns in other tabs that might use this data
    updateTabsetPanel(session, "diffAnalysisTabs", selected = "maTab")
  })
  
  observe({
    # Watch for changes in Volcano plot data
    req(values$volcano_data)
    
    # If this is the first time Volcano data is available, handle UI updates
    isolate({
      if (is.null(values$volcano_tab_shown) && !is.null(values$last_volcano_btn_press_time)) {
        if (as.numeric(Sys.time()) - values$last_volcano_btn_press_time > 1) {
          # This was auto-generated, not from button press
          values$volcano_tab_shown <- TRUE
        }
      }
    })
    
    # Update Venn diagram UI when volcano data changes
    if (!is.null(input$venn_source) && input$venn_source == "volcano") {
      # Trigger UI refresh for Venn diagram
      values$volcano_update_counter <- if(is.null(values$volcano_update_counter)) 1 else values$volcano_update_counter + 1
    }
    
    # Update UpSet plot UI when volcano data changes
    if (!is.null(input$upset_source) && input$upset_source == "volcano") {
      # Trigger UI refresh for UpSet plot
      values$volcano_for_upset_update_counter <- if(is.null(values$volcano_for_upset_update_counter)) 1 else values$volcano_for_upset_update_counter + 1
    }
  })
  
  # Update Venn diagram with latest differential analysis results
  observe({
    # React to changes in volcano data or selection
    req(values$volcano_data)
    volcano_update <- values$volcano_update_counter # Use as dependency to trigger updates
    
    # Only update when volcano is selected as source
    if (!is.null(input$venn_source) && input$venn_source == "volcano") {
      # Update Venn UI elements with latest volcano data
      updateSelectInput(session, "venn_volcano_comparison",
                        choices = unique(paste(input$volcanoGroup1, "vs", input$volcanoGroup2)),
                        selected = paste(input$volcanoGroup1, "vs", input$volcanoGroup2))
    }
  })
  
  # Update UpSet plot with latest differential analysis results
  observe({
    # React to changes in data sources
    req(values$normalized_data)
    volcano_update <- values$volcano_for_upset_update_counter # Use as dependency to trigger updates
    
    # Only update when relevant sources are selected
    if (!is.null(input$upset_source)) {
      if (input$upset_source == "volcano" && !is.null(values$volcano_data)) {
        # Refresh available comparisons
        updateCheckboxGroupInput(session, "upset_volcano_comparisons",
                                 choices = unique(paste(input$volcanoGroup1, "vs", input$volcanoGroup2)),
                                 selected = paste(input$volcanoGroup1, "vs", input$volcanoGroup2))
      } else if (input$upset_source == "ma" && !is.null(values$ma_plot_data)) {
        # Refresh available comparisons for MA plot
        updateCheckboxGroupInput(session, "upset_ma_comparisons",
                                 choices = unique(paste(input$maGroup1, "vs", input$maGroup2)),
                                 selected = paste(input$maGroup1, "vs", input$maGroup2))
      }
    }
  })
  
  # Visualization tab
  # Add this to your server function to handle the visualization tab
  
  # Helper function to generate plots for both raw and normalized data
  generate_data_viz_plot <- function(data_matrix, data_type = "normalized") {
    req(data_matrix)
    
    # Handle per-feature filtering for appropriate plot types
    if (input$viz_plot_type %in% c("hist", "density", "qq") && 
        !is.null(input$viz_selected_feature) && 
        input$viz_selected_feature != "") {
      # Find the selected feature
      feature_idx <- which(values$cleaned_molecules == input$viz_selected_feature)
      if (length(feature_idx) > 0) {
        # Extract only this feature's data
        data_matrix <- data_matrix[feature_idx, , drop = FALSE]
      }
    }
    
    # Apply transformation if selected
    if (input$viz_plot_type %in% c("hist", "density") && input$viz_data_transform != "none") {
      plot_data <- as.matrix(data_matrix)
      
      # Handle zeros and negative values before transformation
      if (input$viz_data_transform %in% c("log2", "log10")) {
        min_positive <- min(plot_data[plot_data > 0], na.rm = TRUE)
        if (!is.infinite(min_positive)) {
          plot_data[plot_data <= 0] <- min_positive / 2
        }
      }
      
      # Apply transformation
      plot_data <- switch(input$viz_data_transform,
                          "log2" = log2(plot_data),
                          "log10" = log10(plot_data),
                          "sqrt" = sqrt(plot_data),
                          plot_data)
    } else {
      plot_data <- as.matrix(data_matrix)
    }
    
    data_label <- if(data_type == "raw") "Raw" else "Normalized"
    
    # Set a consistent ggplot theme for all plots
    theme_set <- theme_bw() +
      theme(
        plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
        plot.subtitle = element_text(hjust = 0.5, face = "italic", size = 12),
        axis.title = element_text(face = "bold", size = 14),
        axis.text = element_text(size = 12),
        legend.title = element_text(face = "bold", size = 12),
        legend.text = element_text(size = 11)
      )
    
    if (input$viz_plot_type == "hist") {
      # Create histogram of data values - properly flatten the matrix
      values_vec <- as.numeric(plot_data)
      values_vec <- values_vec[!is.na(values_vec)]
      
      # Create proper data frame for ggplot
      plot_data_long <- data.frame(Value = values_vec)
      
      transform_label <- switch(input$viz_data_transform,
                                "log2" = "Log2-transformed ",
                                "log10" = "Log10-transformed ",
                                "sqrt" = "Square-root transformed ",
                                "")
      
      p <- ggplot(plot_data_long, aes(x = Value)) +
        geom_histogram(bins = input$viz_hist_bins, fill = "steelblue", color = "black", alpha = 0.7) +
        labs(
          title = paste0(data_label, " - ", transform_label, "Value Distribution"),
          x = "Value",
          y = "Frequency"
        ) +
        theme_set
      
      return(p)
      
    } else if (input$viz_plot_type == "density") {
      # Create density plot of values - properly flatten the matrix
      values_vec <- as.numeric(plot_data)
      values_vec <- values_vec[!is.na(values_vec)]
      
      # Create proper data frame for ggplot
      plot_data_long <- data.frame(Value = values_vec)
      
      transform_label <- switch(input$viz_data_transform,
                                "log2" = "Log2-transformed ",
                                "log10" = "Log10-transformed ",
                                "sqrt" = "Square-root transformed ",
                                "")
      
      p <- ggplot(plot_data_long, aes(x = Value)) +
        geom_density(fill = "steelblue", alpha = 0.7) +
        labs(
          title = paste0(data_label, " - ", transform_label, "Density Distribution"),
          x = "Value",
          y = "Density"
        ) +
        theme_set
      
      return(p)
      
    } else if (input$viz_plot_type == "boxplot") {
      # Create boxplot of samples or groups
      if (input$viz_grouping == "all") {
        # Long format data with each sample as a column
        plot_data_long <- reshape2::melt(
          plot_data,
          varnames = c("Feature", "Sample"),
          value.name = "Value"
        )
        
        p <- ggplot(plot_data_long, aes(x = Sample, y = Value)) +
          geom_boxplot(fill = "steelblue", alpha = 0.7) +
          labs(
            title = paste0(data_label, " - Sample Distributions"),
            x = "Sample",
            y = "Value"
          ) +
          theme_set +
          theme(axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5))
        
        return(p)
        
      } else {
        # Group samples by experimental group
        plot_data_long <- data.frame(
          Value = numeric(),
          Group = factor(),
          stringsAsFactors = FALSE
        )
        
        # Create data for each group
        for (i in seq_along(values$unique_groups)) {
          group <- values$unique_groups[i]
          group_columns <- values$group_column_indices[[i]]
          
          # Extract data for this group
          group_data <- plot_data[, group_columns, drop = FALSE]
          
          # Add to long-format data frame
          group_long <- reshape2::melt(
            group_data,
            varnames = c("Feature", "Sample"),
            value.name = "Value"
          )
          group_long$Group <- group
          
          plot_data_long <- rbind(plot_data_long, group_long)
        }
        
        p <- ggplot(plot_data_long, aes(x = Group, y = Value, fill = Group)) +
          geom_boxplot(alpha = 0.7) +
          labs(
            title = paste0(data_label, " - Group Distributions"),
            x = "Group",
            y = "Value"
          ) +
          theme_set +
          theme(axis.text.x = element_text(angle = 45, hjust = 1, vjust = 1))
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "qq") {
      # Create Q-Q plot for normality checking
      # Determine if showing per-feature data
      feature_suffix <- ""
      if (!is.null(input$viz_selected_feature) && input$viz_selected_feature != "") {
        feature_suffix <- paste0(" - ", input$viz_selected_feature)
      }
      
      if (input$viz_grouping == "all") {
        # Use all data as a single group
        values_vec <- as.numeric(plot_data)
        values_vec <- values_vec[!is.na(values_vec)]
        
        df <- data.frame(Value = values_vec)
        
        p <- ggplot(df, aes(sample = Value)) +
          stat_qq() +
          stat_qq_line(color = "red") +
          labs(
            title = paste0(data_label, " - Normal Q-Q Plot (All Data)", feature_suffix),
            x = "Theoretical Quantiles",
            y = "Sample Quantiles"
          ) +
          theme_set
        
        return(p)
        
      } else {
        # Create a multi-panel Q-Q plot for each group
        qq_plots <- list()
        
        for (i in seq_along(values$unique_groups)) {
          group <- values$unique_groups[i]
          group_columns <- values$group_column_indices[[i]]
          
          # Extract data for this group
          group_data <- plot_data[, group_columns, drop = FALSE]
          group_values <- as.numeric(group_data)
          group_values <- group_values[!is.na(group_values)]
          
          # Create QQ plot for this group
          df <- data.frame(Value = group_values, Group = group)
          
          qq_plots[[i]] <- ggplot(df, aes(sample = Value)) +
            stat_qq() +
            stat_qq_line(color = "red") +
            labs(
              title = paste0(data_label, " - Normal Q-Q Plot - ", group, feature_suffix),
              x = "Theoretical Quantiles",
              y = "Sample Quantiles"
            ) +
            theme_set
        }
        
        # Combine the plots into a grid
        p <- do.call(gridExtra::grid.arrange, c(qq_plots, ncol = min(2, length(qq_plots))))
        
        # Store a static version for download
        png_file <- tempfile(fileext = ".png")
        png(png_file, width = 10, height = 8, units = "in", res = 300)
        print(p)
        dev.off()
        return(p)
      }
      
    } else if (input$viz_plot_type == "mds") {
      # MDS Plot - use the data_matrix parameter which respects raw vs normalized choice
      # Convert to matrix and filter low-expression genes
      plot_matrix <- as.matrix(plot_data)
      keep <- rowSums(plot_matrix > 1) >= 2
      plot_matrix <- plot_matrix[keep, ]
      
      # Guard: need at least 2 features and 2 samples
      if (is.null(dim(plot_matrix)) || nrow(plot_matrix) < 2 || ncol(plot_matrix) < 2) {
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "Not enough data to compute MDS (need >=2 features and >=2 samples)."),
                    size = 6, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          theme_void()
        return(p)
      }
      
      # Simple distance-based MDS
      sample_dist <- dist(t(plot_matrix))
      mds_result <- cmdscale(sample_dist, k = 2, eig = TRUE)
      
      # Calculate percentage of variance explained
      total_variance <- sum(mds_result$eig[mds_result$eig > 0])
      var_explained <- (mds_result$eig[1:2] / total_variance) * 100
      
      mds_df <- data.frame(
        Dim1 = mds_result$points[, 1],
        Dim2 = mds_result$points[, 2],
        Sample = colnames(plot_matrix)
      )
      
      # Add group information if available - with robust matching
      if (!is.null(values$groups)) {
        # Try multiple approaches to match groups safely
        if (is.null(names(values$groups))) {
          # If no names, assume same order as samples
          if (length(values$groups) == nrow(mds_df)) {
            mds_df$Group <- as.character(values$groups)
          }
        } else {
          # Try to match by sample names
          matched_groups <- values$groups[match(mds_df$Sample, names(values$groups))]
          if (sum(!is.na(matched_groups)) > 0) {  # At least some matches
            mds_df$Group <- as.character(matched_groups)
          }
        }
      }
      
      p <- ggplot(mds_df, aes(x = Dim1, y = Dim2)) +
        {if ("Group" %in% colnames(mds_df) && (input$viz_color_by_group %||% TRUE))
          geom_point(aes(color = Group), size = 3)
          else
            geom_point(size = 3)} +
        {if (input$viz_show_labels %||% TRUE)
          geom_text(aes(label = Sample), vjust = -0.5, size = 3)} +
        labs(title = paste0(data_label, " - Multidimensional Scaling (MDS) Plot"),
             subtitle = "Distance-based MDS from expression data",
             x = sprintf("Dimension 1 (%.1f%%)", var_explained[1]), 
             y = sprintf("Dimension 2 (%.1f%%)", var_explained[2])) +
        theme_set
      
      return(p)
      
    } else if (input$viz_plot_type == "pca") {
      # PCA Plot for DESeq2
      if (input$sig_method == "deseq2") {
        # Perform PCA on transposed data (samples as rows)
        pca_result <- prcomp(t(plot_data), scale. = TRUE)
        
        # Calculate variance explained
        var_explained <- summary(pca_result)$importance[2, 1:2] * 100
        
        pca_df <- data.frame(
          PC1 = pca_result$x[, 1],
          PC2 = pca_result$x[, 2],
          Sample = rownames(pca_result$x)
        )
        
        # Add group information if available
        if (!is.null(values$groups)) {
          pca_df$Group <- values$groups[match(pca_df$Sample, names(values$groups))]
        }
        
        p <- ggplot(pca_df, aes(x = PC1, y = PC2)) +
          {if (!is.null(values$groups) && (input$viz_color_by_group %||% TRUE))
            geom_point(aes(color = Group), size = 3)
            else
              geom_point(size = 3)} +
          {if (input$viz_show_labels %||% TRUE)
            geom_text(aes(label = Sample), vjust = -0.5, size = 3)} +
          labs(title = paste0(data_label, " - Principal Component Analysis (PCA)"),
               x = paste0("PC1 (", round(var_explained[1], 1), "%)"),
               y = paste0("PC2 (", round(var_explained[2], 1), "%)")) +
          theme_set
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "meanvar") {
      # Mean-Variance Plot for edgeR/limma-voom
      if (input$sig_method %in% c("edger", "limma_voom")) {
        # Calculate mean and variance for each gene
        gene_means <- rowMeans(plot_data, na.rm = TRUE)
        gene_vars <- apply(plot_data, 1, var, na.rm = TRUE)
        
        meanvar_df <- data.frame(
          Mean = gene_means,
          Variance = gene_vars
        )
        
        p <- ggplot(meanvar_df, aes(x = Mean, y = Variance)) +
          geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
          {if (input$viz_show_trend %||% TRUE)
            geom_smooth(method = "loess", color = "red", se = TRUE)} +
          scale_x_log10() +
          scale_y_log10() +
          labs(title = paste0(data_label, " - Mean-Variance Relationship"),
               subtitle = if (input$viz_show_trend %||% TRUE) "Red line shows fitted trend" else "",
               x = "Log10(Mean Expression)",
               y = "Log10(Variance)") +
          theme_set
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "libsize") {
      # Library Size Distribution
      if (input$sig_method %in% c("edger", "limma_voom")) {
        # Calculate library sizes (column sums)
        lib_sizes <- colSums(exp(plot_data) - 1, na.rm = TRUE)  # Convert back from log if needed
        
        libsize_df <- data.frame(
          Sample = names(lib_sizes),
          LibrarySize = lib_sizes
        )
        
        # Add group information if available
        if (!is.null(values$groups)) {
          libsize_df$Group <- values$groups[match(libsize_df$Sample, names(values$groups))]
        }
        
        p <- ggplot(libsize_df, aes(x = Sample, y = LibrarySize)) +
          {if (!is.null(values$groups)) geom_col(aes(fill = Group)) else geom_col()} +
          scale_y_continuous(expand = expansion(mult = c(0, 0.1))) +
          labs(title = paste0(data_label, " - Library Size Distribution"),
               x = "Sample", y = "Library Size") +
          theme_set +
          theme(axis.text.x = element_text(angle = 45, hjust = 1))
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "bcv") {
      # BCV Plot requires cached statistical analysis - not a data visualization
      # This plot type only uses the cached DGEList, so data_type is ignored
      if (data_type == "raw") {
        # Don't render "raw" version of BCV - it's based on statistical analysis
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "BCV Plot is based on statistical analysis\n(not raw data comparisons).\nUse the normalized data plot only."),
                    size = 5, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "BCV Plot Not Available for Raw Data") +
          theme_void()
        return(p)
      }
      
      # For normalized (or statistical analysis context), try to get the cached DGEList
      if (input$sig_method == "edger" && !is.null(values$edger_state$y)) {
        y <- values$edger_state$y
        
        # Calculate average log expression and BCV
        ave_log_expr <- edgeR::aveLogCPM(y)
        bcv <- sqrt(y$tagwise.dispersion)
        
        bcv_df <- data.frame(
          AveLogCPM = ave_log_expr,
          BCV = bcv
        )
        
        p <- ggplot(bcv_df, aes(x = AveLogCPM, y = BCV)) +
          geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
          {if (input$viz_show_trend %||% TRUE)
            geom_smooth(method = "loess", color = "red", se = TRUE)} +
          labs(title = paste0(data_label, " - Biological Coefficient of Variation (edgeR)"),
               subtitle = if (input$viz_show_trend %||% TRUE) "Biological variability vs expression level" else "Biological variability vs expression level",
               x = "Average log2(CPM)",
               y = "Biological CV") +
          theme_set
        
        return(p)
        
      } else if (input$sig_method == "limma_voom" && !is.null(values$limma_voom_state$y)) {
        y <- values$limma_voom_state$y
        
        # For limma-voom, show the dispersion estimates from edgeR preprocessing
        if (!is.null(y$tagwise.dispersion)) {
          ave_log_expr <- edgeR::aveLogCPM(y)
          bcv <- sqrt(y$tagwise.dispersion)
          
          bcv_df <- data.frame(
            AveLogCPM = ave_log_expr,
            BCV = bcv
          )
          
          p <- ggplot(bcv_df, aes(x = AveLogCPM, y = BCV)) +
            geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
            {if (input$viz_show_trend %||% TRUE)
              geom_smooth(method = "loess", color = "red", se = TRUE)} +
            labs(title = paste0(data_label, " - Biological Coefficient of Variation (limma-voom)"),
                 subtitle = "Dispersion estimates from edgeR preprocessing",
                 x = "Average log2(CPM)",
                 y = "Biological CV") +
            theme_set
          
          return(p)
        } else {
          # Fallback: show message that dispersion estimation is needed
          p <- ggplot() +
            geom_text(aes(x = 0.5, y = 0.5,
                          label = "BCV plot requires dispersion estimation.\nRun statistical analysis first."),
                      size = 6, hjust = 0.5, vjust = 0.5) +
            xlim(0, 1) + ylim(0, 1) +
            labs(title = "BCV Plot Not Available") +
            theme_set +
            theme(axis.text = element_blank(), axis.ticks = element_blank())
          
          return(p)
        }
      } else {
        # No statistical analysis run yet
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "BCV plot requires statistical analysis.\nRun edgeR or limma-voom analysis first."),
                    size = 6, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "BCV Plot Not Available") +
          theme_set +
          theme(axis.text = element_blank(), axis.ticks = element_blank())
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "ql_disp") {
      # QL Dispersion Plot requires cached statistical analysis - not a data visualization
      # This plot type only uses the cached edgeR QLF fit, so data_type is ignored
      if (data_type == "raw") {
        # Don't render "raw" version of QL Dispersion - it's based on statistical analysis
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "QL Dispersion Plot is based on statistical analysis\n(not raw data comparisons).\nUse the normalized data plot only."),
                    size = 5, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "QL Dispersion Plot Not Available for Raw Data") +
          theme_void()
        return(p)
      }
      
      # For normalized (or statistical analysis context), try to get the cached QLF fit
      if (input$sig_method == "edger" && !is.null(values$edger_qlf)) {
        tryCatch({
          qlf_fit <- values$edger_qlf
          
          # Extract data for QL dispersion plot
          # This replicates what plotQLDisp does internally
          A <- qlf_fit$AveLogCPM
          if (is.null(A)) {
            # Fallback: calculate average log2 CPM
            A <- edgeR::aveLogCPM(values$edger_state$y)
          }
          
          # Get QL dispersions (quarter-root mean deviance)
          ql_disp <- qlf_fit$var.post
          if (is.null(ql_disp)) {
            ql_disp <- qlf_fit$dispersion
          }
          
          # Convert to quarter-root mean deviance
          quarter_root_disp <- ql_disp^0.25
          
          # Create data frame for plotting
          ql_df <- data.frame(
            AveLogCPM = A,
            QuarterRootMeanDeviance = quarter_root_disp
          )
          
          # Remove any infinite or NA values
          ql_df <- ql_df[is.finite(ql_df$AveLogCPM) & is.finite(ql_df$QuarterRootMeanDeviance), ]
          
          p <- ggplot(ql_df, aes(x = AveLogCPM, y = QuarterRootMeanDeviance)) +
            geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 0.8, color = "black") +
            {if (input$viz_show_trend %||% TRUE)
              geom_smooth(method = "loess", color = "red", se = TRUE)} +
            labs(
              title = "QL Dispersion Plot (edgeR)",
              subtitle = "Quarter-root mean deviance vs average log2 CPM",
              x = "Average log2 CPM",
              y = "Quarter-root mean deviance"
            ) +
            theme_set
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            geom_text(aes(x = 0.5, y = 0.5,
                          label = paste("Error creating QL dispersion plot:", e$message)),
                      size = 4, hjust = 0.5, vjust = 0.5) +
            xlim(0, 1) + ylim(0, 1) +
            labs(title = "QL Dispersion Plot Error") +
            theme_set +
            theme(axis.text = element_blank(), axis.ticks = element_blank())
          
          return(p)
        })
        
      } else {
        # Show message when QLF fit is not available
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "QL dispersion plot requires edgeR QLF analysis.\nRun statistical analysis with QLF test first."),
                    size = 5, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "QL Dispersion Plot Not Available") +
          theme_set +
          theme(axis.text = element_blank(), axis.ticks = element_blank())
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "dispersion") {
      # Dispersion Plot for DESeq2
      if (input$sig_method == "deseq2") {
        # Create a simulated dispersion plot using the available data
        # In a real implementation, this would use the DESeqDataSet object
        
        # Calculate mean and dispersion estimates from the data
        gene_means <- rowMeans(plot_data, na.rm = TRUE)
        gene_vars <- apply(plot_data, 1, var, na.rm = TRUE)
        # Rough dispersion estimate (variance / mean)
        dispersion_est <- gene_vars / (gene_means + 1)
        
        disp_df <- data.frame(
          BaseMean = gene_means,
          Dispersion = dispersion_est
        )
        
        # Remove infinite or negative values
        disp_df <- disp_df[is.finite(disp_df$Dispersion) & disp_df$Dispersion > 0, ]
        
        p <- ggplot(disp_df, aes(x = BaseMean, y = Dispersion)) +
          geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
          {if (input$viz_show_trend %||% TRUE)
            geom_smooth(method = "loess", color = "red", se = TRUE)} +
          scale_x_log10() +
          scale_y_log10() +
          labs(title = "Dispersion Estimates",
               subtitle = "Dispersion vs mean expression (simulated from data)",
               x = "Log10(Base Mean)",
               y = "Log10(Dispersion)") +
          theme_set
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "ma_sizefactors") {
      # MA Plot using size factors - FIXED VERSION
      req(input$sig_method == "deseq2")
      
      if (!is.null(values$dds)) {
        tryCatch({
          # Get size factors
          sf <- DESeq2::sizeFactors(values$dds)
          
          # Calculate means and size factor ratios
          baseMean <- rowMeans(DESeq2::counts(values$dds, normalized = FALSE))
          
          # Create plot data - each sample gets its size factor
          sample_names <- colnames(values$dds)
          plot_df <- data.frame(
            BaseMean = rep(baseMean, length(sample_names)),
            SizeFactor = rep(sf, each = length(baseMean)),
            Sample = rep(sample_names, each = length(baseMean))
          )
          
          # Add group information if available
          if (!is.null(values$groups)) {
            plot_df$Group <- rep(values$groups[sample_names], each = length(baseMean))
          }
          
          p <- ggplot(plot_df, aes(x = BaseMean, y = SizeFactor)) +
            {if (!is.null(values$groups) && (input$viz_color_by_group %||% TRUE))
              geom_point(aes(color = Group), alpha = 0.6, size = 0.5)
              else
                geom_point(alpha = 0.6, size = 0.5)} +
            geom_hline(yintercept = 1, color = "red", linetype = "dashed") +
            scale_x_log10() +
            labs(
              title = "MA Plot: Size Factors vs Base Mean",
              x = "Base Mean (log10)",
              y = "Size Factor"
            ) +
            theme_set
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating MA plot:", e$message),
                     hjust = 0.5, size = 4) +
            theme_void()
          return(p)
        })
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "DESeq2 analysis required for MA plot",
                   hjust = 0.5, size = 4) +
          theme_void()
        return(p)
      }
      
    } else if (input$viz_plot_type == "meansd_plot") {
      # Mean-SD Plot (effect of transformations on variance) - NEW
      req(input$sig_method == "deseq2")
      
      if (!is.null(values$dds)) {
        tryCatch({
          # Load required package
          if (!requireNamespace("vsn", quietly = TRUE)) {
            install.packages("vsn")
          }
          library(vsn)
          
          # Get different transformations
          vsd <- DESeq2::vst(values$dds, blind = FALSE)
          rld <- DESeq2::rlog(values$dds, blind = FALSE)
          
          # Since this needs to return a ggplot object, we'll create a combined plot
          # First get data for each transformation
          raw_counts <- log2(DESeq2::counts(values$dds, normalized = TRUE) + 1)
          vst_data <- SummarizedExperiment::assay(vsd)
          rlog_data <- SummarizedExperiment::assay(rld)
          
          # Calculate mean and sd for each gene in each transformation
          calc_mean_sd <- function(mat, transform_name) {
            gene_means <- rowMeans(mat, na.rm = TRUE)
            gene_sds <- apply(mat, 1, sd, na.rm = TRUE)
            mean_ranks <- rank(gene_means)
            data.frame(
              MeanRank = mean_ranks,
              SD = gene_sds,
              Transform = transform_name
            )
          }
          
          combined_data <- rbind(
            calc_mean_sd(raw_counts, "Raw (log2+1)"),
            calc_mean_sd(vst_data, "VST"),
            calc_mean_sd(rlog_data, "rlog")
          )
          
          p <- ggplot(combined_data, aes(x = MeanRank, y = SD)) +
            geom_point(alpha = 0.4, size = 0.5) +
            geom_smooth(method = "loess", color = "red", se = TRUE) +
            facet_wrap(~ Transform, scales = "free_y") +
            labs(
              title = "Effect of Transformations on Variance",
              subtitle = "Standard Deviation vs Rank of Mean Expression",
              x = "Rank of Mean Expression",
              y = "Standard Deviation"
            ) +
            theme_set
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating mean-SD plot:", e$message),
                     hjust = 0.5, size = 4) +
            theme_void()
          return(p)
        })
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "DESeq2 analysis required for mean-SD plot",
                   hjust = 0.5, size = 4) +
          theme_void()
        return(p)
      }
      
    } else if (input$viz_plot_type == "count_outliers") {
      # Count Outlier Detection Plot - NEW
      req(input$sig_method == "deseq2")
      
      if (!is.null(values$deseq2_results) && !is.null(values$dds)) {
        tryCatch({
          # Get results from DESeq2 analysis
          res <- values$deseq2_results
          
          # Extract Wald statistics and Cook's distances
          W <- res$stat
          maxCooks <- apply(SummarizedExperiment::assays(values$dds)[["cooks"]], 1, max)
          idx <- !is.na(W)
          
          # Plot parameters
          m <- ncol(values$dds)  # number of samples
          p_param <- 3  # number of parameters (can be adjusted)
          
          # Create data frame for ggplot
          plot_data <- data.frame(
            WaldRank = rank(W[idx]),
            MaxCooks = maxCooks[idx]
          )
          
          # Calculate threshold
          threshold <- qf(0.99, p_param, m - p_param)
          
          p <- ggplot(plot_data, aes(x = WaldRank, y = MaxCooks)) +
            geom_point(alpha = 0.4, size = 0.4, color = rgb(0, 0, 0, 0.3)) +
            geom_hline(yintercept = threshold, color = "red", linetype = "dashed") +
            coord_cartesian(ylim = c(0, 5)) +
            labs(
              title = "Count Outlier Detection",
              x = "Rank of Wald statistic",
              y = "Maximum Cook's distance per gene"
            ) +
            annotate("text", x = max(plot_data$WaldRank) * 0.7, y = threshold + 0.2,
                     label = "99% F-distribution threshold", color = "red") +
            theme_set
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating count outliers plot:", e$message),
                     hjust = 0.5, size = 4) +
            theme_void()
          return(p)
        })
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "DESeq2 analysis and results required",
                   hjust = 0.5, size = 4) +
          theme_void()
        return(p)
      }
      
    } else if (input$viz_plot_type == "ma_pvalues") {
      # MA Plot with p-values (Expanded model matrices plot) - NEW
      req(input$sig_method == "deseq2")
      
      if (!is.null(values$deseq2_results)) {
        tryCatch({
          res <- values$deseq2_results
          
          # Filter out NA values for plotting
          valid_idx <- !is.na(res$baseMean) & !is.na(res$pvalue) & res$baseMean > 0
          
          plot_data <- data.frame(
            BaseMean = res$baseMean[valid_idx] + 1,
            NegLogPvalue = -log10(res$pvalue[valid_idx])
          )
          
          # Cap extremely high values for better visualization
          plot_data$NegLogPvalue[plot_data$NegLogPvalue > 30] <- 30
          
          p <- ggplot(plot_data, aes(x = BaseMean, y = NegLogPvalue)) +
            geom_point(alpha = 0.4, size = 0.4, color = rgb(0, 0, 0, 0.3)) +
            geom_hline(yintercept = -log10(0.05), color = "red", linetype = "dashed") +
            geom_hline(yintercept = -log10(0.01), color = "blue", linetype = "dashed") +
            scale_x_log10() +
            coord_cartesian(ylim = c(0, 30)) +
            labs(
              title = "MA Plot: Mean Expression vs P-values",
              x = "Mean of normalized counts (log10)",
              y = "-log10(p-value)"
            ) +
            annotate("text", x = max(plot_data$BaseMean) * 0.001, y = -log10(0.05) + 0.5,
                     label = "p = 0.05", color = "red", size = 3) +
            annotate("text", x = max(plot_data$BaseMean) * 0.001, y = -log10(0.01) + 0.5,
                     label = "p = 0.01", color = "blue", size = 3) +
            theme_set
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating MA p-values plot:", e$message),
                     hjust = 0.5, size = 4) +
            theme_void()
          return(p)
        })
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "DESeq2 analysis and results required",
                   hjust = 0.5, size = 4) +
          theme_void()
        return(p)
      }
      
    } else if (input$viz_plot_type == "cooks") {
      # Cook's Distance for DESeq2
      if (input$sig_method == "deseq2" && !is.null(values$dds)) {
        tryCatch({
          # Get Cook's distances from DESeq2 object
          cooks_matrix <- SummarizedExperiment::assays(values$dds)[["cooks"]]
          
          # Calculate max Cook's distance per sample
          sample_names <- colnames(cooks_matrix)
          max_cooks_per_sample <- apply(cooks_matrix, 2, max, na.rm = TRUE)
          
          cooks_df <- data.frame(
            Sample = sample_names,
            CooksDistance = max_cooks_per_sample
          )
          
          # Add group information if available
          if (!is.null(values$groups)) {
            cooks_df$Group <- values$groups[match(cooks_df$Sample, names(values$groups))]
          }
          
          p <- ggplot(cooks_df, aes(x = Sample, y = CooksDistance)) +
            {if (!is.null(values$groups) && (input$viz_color_by_group %||% TRUE))
              geom_col(aes(fill = Group))
              else
                geom_col()} +
            geom_hline(yintercept = 1, linetype = "dashed", color = "red") +
            scale_y_continuous(expand = expansion(mult = c(0, 0.1))) +
            labs(title = "Cook's Distance",
                 subtitle = "Sample outlier detection",
                 x = "Sample", y = "Max Cook's Distance") +
            theme_set +
            theme(axis.text.x = element_text(angle = 45, hjust = 1))
          
          return(p)
          
        }, error = function(e) {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating Cook's distance plot:", e$message),
                     hjust = 0.5, size = 4) +
            theme_void()
          return(p)
        })
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "DESeq2 analysis required for Cook's distance plot",
                   hjust = 0.5, size = 4) +
          theme_void()
        return(p)
      }
      
    } else if (input$viz_plot_type == "voom_weights") {
      # Voom Precision Weights requires cached statistical analysis - not a data visualization
      # This plot type only uses the cached voom object, so data_type is ignored
      if (data_type == "raw") {
        # Don't render "raw" version of voom weights - it's based on statistical analysis
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "Voom Precision Weights is based on statistical analysis\n(not raw data comparisons).\nUse the normalized data plot only."),
                    size = 5, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "Voom Precision Weights Not Available for Raw Data") +
          theme_void()
        return(p)
      }
      
      # For normalized (or statistical analysis context), try to get the cached voom object
      if (input$sig_method == "limma_voom" && !is.null(values$limma_voom_state$v)) {
        v <- values$limma_voom_state$v
        
        # Create mean-variance plot from voom object
        if (!is.null(v$voom.xy) && !is.null(v$voom.line)) {
          # Use the voom trend data
          voom_df <- data.frame(
            x = v$voom.xy$x,
            y = v$voom.xy$y,
            fitted = v$voom.line$fitted
          )
          
          p <- ggplot(voom_df, aes(x = x, y = y)) +
            geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
            geom_line(aes(y = fitted), color = "red", size = 1) +
            labs(title = "Voom Mean-Variance Trend",
                 subtitle = "Precision weights based on mean-variance relationship",
                 x = "log2(count size + 0.5)",
                 y = "Sqrt(standard deviation)") +
            theme_set
          
        } else {
          # Fallback: create a simplified mean-variance plot
          # Calculate mean and sqrt(std dev) for each gene
          gene_means <- rowMeans(v$E, na.rm = TRUE)
          gene_sds <- apply(v$E, 1, sd, na.rm = TRUE)
          
          voom_df <- data.frame(
            Mean = gene_means,
            SqrtSD = sqrt(gene_sds)
          )
          
          p <- ggplot(voom_df, aes(x = Mean, y = SqrtSD)) +
            geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 1) +
            {if (input$viz_show_trend %||% TRUE)
              geom_smooth(method = "loess", color = "red", se = TRUE)} +
            labs(title = "Voom Mean-Variance Relationship",
                 subtitle = "Mean vs sqrt(standard deviation) from voom transformation",
                 x = "Mean log2(expression)",
                 y = "Sqrt(standard deviation)") +
            theme_set
        }
        
        return(p)
      } else {
        # Show message when voom object is not available
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "Voom weights plot requires limma-voom analysis.\nRun limma-voom analysis first."),
                    size = 6, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "Voom Precision Weights Not Available") +
          theme_set +
          theme(axis.text = element_blank(), axis.ticks = element_blank())
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "residuals") {
      # Model Residuals requires cached statistical analysis - not a data visualization
      # This plot type only uses the cached model fit, so data_type is ignored
      if (data_type == "raw") {
        # Don't render "raw" version of model residuals - it's based on statistical analysis
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "Model Residuals is based on statistical analysis\n(not raw data comparisons).\nUse the normalized data plot only."),
                    size = 5, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "Model Residuals Not Available for Raw Data") +
          theme_void()
        return(p)
      }
      
      # For normalized (or statistical analysis context), try to get the cached model fit
      if (input$sig_method == "limma_voom" && !is.null(values$limma_voom_state$fit)) {
        fit <- values$limma_voom_state$fit
        v <- values$limma_voom_state$v
        
        # Calculate residuals
        fitted_values <- fit$coefficients %*% t(fit$design)
        residuals <- v$E - fitted_values
        
        # Create residuals vs fitted plot
        fitted_vec <- as.vector(fitted_values)
        residuals_vec <- as.vector(residuals)
        
        # Remove any infinite or NA values
        valid_idx <- is.finite(fitted_vec) & is.finite(residuals_vec)
        fitted_vec <- fitted_vec[valid_idx]
        residuals_vec <- residuals_vec[valid_idx]
        
        resid_df <- data.frame(
          Fitted = fitted_vec,
          Residuals = residuals_vec
        )
        
        p <- ggplot(resid_df, aes(x = Fitted, y = Residuals)) +
          geom_point(alpha = input$viz_point_alpha %||% 0.6, size = 0.5) +
          geom_hline(yintercept = 0, color = "red", linetype = "dashed") +
          {if (input$viz_show_trend %||% TRUE)
            geom_smooth(method = "loess", color = "blue", se = TRUE)} +
          labs(title = "Model Residuals vs Fitted Values",
               subtitle = "Diagnostic plot for limma-voom linear model",
               x = "Fitted Values",
               y = "Residuals") +
          theme_set
        
        return(p)
        
      } else {
        # Show message when model fit is not available
        p <- ggplot() +
          geom_text(aes(x = 0.5, y = 0.5,
                        label = "Model residuals plot requires fitted limma model.\nRun limma-voom analysis first."),
                    size = 6, hjust = 0.5, vjust = 0.5) +
          xlim(0, 1) + ylim(0, 1) +
          labs(title = "Model Residuals Not Available") +
          theme_set +
          theme(axis.text = element_blank(), axis.ticks = element_blank())
        
        return(p)
      }
      
    } else if (input$viz_plot_type == "sample_dist") {
      # Sample Distance Heatmap
      # Calculate sample-to-sample distances using specified method
      dist_method <- input$viz_dist_method %||% "euclidean"
      sample_dists <- dist(t(plot_data), method = dist_method)
      sample_dist_matrix <- as.matrix(sample_dists)
      
      # Convert to long format for ggplot
      dist_df <- expand.grid(Sample1 = rownames(sample_dist_matrix),
                             Sample2 = colnames(sample_dist_matrix))
      dist_df$Distance <- as.vector(sample_dist_matrix)
      
      p <- ggplot(dist_df, aes(x = Sample1, y = Sample2, fill = Distance)) +
        geom_tile() +
        scale_fill_gradient(low = "white", high = "darkblue") +
        labs(title = paste0(data_label, " - Sample-to-Sample Distance Heatmap"),
             subtitle = paste("Distance method:", stringr::str_to_title(dist_method)),
             x = "Sample", y = "Sample") +
        theme_set +
        theme(axis.text.x = element_text(angle = 90, hjust = 1),
              axis.text.y = element_text(angle = 0)) +
        coord_fixed()
      
      return(p)
      
    } else if (input$viz_plot_type == "corr") {
      # Create correlation heatmap of samples
      # Get column names as sample identifiers
      sample_names <- colnames(values$normalized_data)
      
      # Calculate correlation matrix
      cor_matrix <- cor(plot_data, use = "pairwise.complete.obs", method = input$viz_corr_method)
      
      # Convert to data frame for ggplot
      cor_df <- as.data.frame(as.table(cor_matrix))
      colnames(cor_df) <- c("Sample1", "Sample2", "Correlation")
      
      # Create heatmap
      p <- ggplot(cor_df, aes(x = Sample1, y = Sample2, fill = Correlation)) +
        geom_tile() +
        scale_fill_gradient2(
          low = "blue",
          mid = "white",
          high = "red",
          midpoint = 0.5,
          limits = c(0, 1)
        ) +
        labs(
          title = paste0(data_label, " - Sample Correlation Heatmap - ", toupper(input$viz_corr_method)),
          x = "Sample",
          y = "Sample"
        ) +
        theme_set +
        theme(
          axis.text.x = element_text(angle = 90, hjust = 1, vjust = 0.5),
          axis.text.y = element_text(angle = 0)
        ) +
        coord_fixed()
      
      return(p)
    }
  }
  
  # Generate visualizations when button is clicked
  observeEvent(input$generate_viz_btn, {
    req(values$normalized_data)
    
    # Set a flag to indicate plots should be generated
    values$viz_plots_ready <- TRUE
    
    # Store one plot for download (normalized version)
    values$data_viz_plot <- generate_data_viz_plot(values$normalized_data, "normalized")
  })
  
  # Generate plots for both raw and normalized data (reactive to feature selection)
  output$data_viz_plot_raw <- renderPlot({ 
    req(values$viz_plots_ready)
    req(values$raw_data)
    # Extract numeric columns from raw_data (assuming first column is feature names)
    raw_matrix <- as.matrix(values$raw_data[, -1, drop = FALSE])
    generate_data_viz_plot(raw_matrix, "raw")
  })
  
  output$data_viz_plot_normalized <- renderPlot({ 
    req(values$viz_plots_ready)
    req(values$normalized_data)
    generate_data_viz_plot(values$normalized_data, "normalized")
  })
  
  # Generate summary statistics - per-feature for appropriate plot types
  output$viz_summary_stats <- renderUI({
      # Validate input$viz_plot_type exists and has length > 0
      if (is.null(input$viz_plot_type) || length(input$viz_plot_type) == 0) {
        return(NULL)
      }
      
      # For histogram, density, Q-Q plot: show per-feature statistics with normality pie chart
      if (input$viz_plot_type %in% c("hist", "density", "qq")) {
        req(input$viz_selected_feature)
        
        # Find the selected feature in the normalized data
        feature_idx <- which(values$cleaned_molecules == input$viz_selected_feature)
        
        if (length(feature_idx) == 0) {
          return(div(class = "alert alert-warning", "Feature not found in the data."))
        }
        
        # Get feature data
        feature_values_raw <- as.numeric(values$raw_data[feature_idx, -1])
        feature_values_norm <- as.numeric(values$normalized_data[feature_idx, ])
        
        feature_values_raw <- feature_values_raw[!is.na(feature_values_raw)]
        feature_values_norm <- feature_values_norm[!is.na(feature_values_norm)]
        
        # Perform Shapiro-Wilk tests
        raw_test <- NULL
        norm_test <- NULL
        
        if (length(feature_values_raw) >= 3) {
          if (length(feature_values_raw) > 5000) {
            set.seed(123)
            test_sample <- sample(feature_values_raw, 5000)
            raw_test <- shapiro.test(test_sample)
          } else {
            raw_test <- shapiro.test(feature_values_raw)
          }
        }
        
        if (length(feature_values_norm) >= 3) {
          if (length(feature_values_norm) > 5000) {
            set.seed(123)
            test_sample <- sample(feature_values_norm, 5000)
            norm_test <- shapiro.test(test_sample)
          } else {
            norm_test <- shapiro.test(feature_values_norm)
          }
        }
        
        # Determine normality status (p > 0.05 = normal)
        raw_normal <- if (!is.null(raw_test)) raw_test$p.value > 0.05 else NA
        norm_normal <- if (!is.null(norm_test)) norm_test$p.value > 0.05 else NA
        
        # Count features meeting normality criteria (across ALL features)
        all_normal_count <- 0
        all_total_count <- length(values$cleaned_molecules)
        
        if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) > 0) {
          for (i in seq_along(values$cleaned_molecules)) {
            f_values <- as.numeric(values$normalized_data[i, ])
            f_values <- f_values[!is.na(f_values)]
            
            if (length(f_values) >= 3) {
              if (length(f_values) > 5000) {
                set.seed(123)
                f_sample <- sample(f_values, 5000)
                f_test <- shapiro.test(f_sample)
              } else {
                f_test <- shapiro.test(f_values)
              }
              
              if (f_test$p.value > 0.05) {
                all_normal_count <- all_normal_count + 1
              }
            }
          }
        }
        
        all_not_normal <- all_total_count - all_normal_count
        
        # Create normality summary pie chart
        pie_data <- data.frame(
          Status = c("Normal", "Not Normal"),
          Count = c(all_normal_count, all_not_normal),
          Percentage = c(
            round(all_normal_count / all_total_count * 100, 1),
            round(all_not_normal / all_total_count * 100, 1)
          )
        )
        
        # Build the HTML content as a neat table
        HTML(
          paste0(
            "<div style='display: flex; gap: 30px;'>",
            "<div style='flex: 1;'>",
            "<h4 style='color: #2c3e50; font-weight: bold; margin-bottom: 12px;'>NORMALITY ASSESSMENT</h4>",
            "<p style='margin: 6px 0 12px 0;'><strong>Feature:</strong> ", input$viz_selected_feature, "</p>",
            "<table class='table table-striped' style='margin-bottom: 0; width: 100%;'>",
            "<thead><tr><th>Metric</th><th>Raw Data</th><th>Normalized Data</th></tr></thead>",
            "<tbody>",
            "<tr><td>Number of samples</td><td>", length(feature_values_raw), "</td><td>", length(feature_values_norm), "</td></tr>",
            "<tr><td>Minimum</td><td>", formatC(min(feature_values_raw, na.rm = TRUE), digits = 4, format = "f"), "</td><td>", formatC(min(feature_values_norm, na.rm = TRUE), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Maximum</td><td>", formatC(max(feature_values_raw, na.rm = TRUE), digits = 4, format = "f"), "</td><td>", formatC(max(feature_values_norm, na.rm = TRUE), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Mean</td><td>", formatC(mean(feature_values_raw, na.rm = TRUE), digits = 4, format = "f"), "</td><td>", formatC(mean(feature_values_norm, na.rm = TRUE), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Median</td><td>", formatC(median(feature_values_raw, na.rm = TRUE), digits = 4, format = "f"), "</td><td>", formatC(median(feature_values_norm, na.rm = TRUE), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Standard deviation</td><td>", formatC(sd(feature_values_raw, na.rm = TRUE), digits = 4, format = "f"), "</td><td>", formatC(sd(feature_values_norm, na.rm = TRUE), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Skewness</td><td>", formatC(moments::skewness(feature_values_raw), digits = 4, format = "f"), "</td><td>", formatC(moments::skewness(feature_values_norm), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Kurtosis</td><td>", formatC(moments::kurtosis(feature_values_raw), digits = 4, format = "f"), "</td><td>", formatC(moments::kurtosis(feature_values_norm), digits = 4, format = "f"), "</td></tr>",
            "<tr><td>Shapiro-Wilk W</td><td>", if (!is.null(raw_test)) formatC(raw_test$statistic, digits = 6, format = "f") else "N/A", "</td><td>", if (!is.null(norm_test)) formatC(norm_test$statistic, digits = 6, format = "f") else "N/A", "</td></tr>",
            "<tr><td>Shapiro-Wilk p-value</td><td>", if (!is.null(raw_test)) formatC(raw_test$p.value, digits = 6, format = "e") else "N/A", "</td><td>", if (!is.null(norm_test)) formatC(norm_test$p.value, digits = 6, format = "e") else "N/A", "</td></tr>",
            "<tr><td>Status</td><td><strong style='color:", if (raw_normal) "#27ae60" else "#c0392b", ";'>", if (!is.null(raw_test)) if (raw_normal) "NORMAL" else "NOT NORMAL" else "N/A", "</strong></td>",
            "<td><strong style='color:", if (norm_normal) "#27ae60" else "#c0392b", ";'>", if (!is.null(norm_test)) if (norm_normal) "NORMAL" else "NOT NORMAL" else "N/A", "</strong></td></tr>",
            "</tbody></table>",
            "</div>",
            "</div>"
          )
        )
        
      } else {
        # For other plot types, show overall data statistics
        plot_data <- as.matrix(values$normalized_data)
        values_vec <- as.numeric(plot_data)
        values_vec <- values_vec[!is.na(values_vec)]
        
        HTML(
          paste0(
            "<div style='padding: 15px;'>",
            "<h4 style='color: #2c3e50; font-weight: bold; margin-bottom: 15px;'>Summary Statistics (All Data)</h4>",
            "<p style='margin: 5px 0;'><strong>Number of data points:</strong> ", length(values_vec), "</p>",
            "<p style='margin: 5px 0;'><strong>Minimum:</strong> ", formatC(min(values_vec, na.rm = TRUE), digits = 4, format = "f"), "</p>",
            "<p style='margin: 5px 0;'><strong>Maximum:</strong> ", formatC(max(values_vec, na.rm = TRUE), digits = 4, format = "f"), "</p>",
            "<p style='margin: 5px 0;'><strong>Mean:</strong> ", formatC(mean(values_vec, na.rm = TRUE), digits = 4, format = "f"), "</p>",
            "<p style='margin: 5px 0;'><strong>Median:</strong> ", formatC(median(values_vec, na.rm = TRUE), digits = 4, format = "f"), "</p>",
            "<p style='margin: 5px 0;'><strong>Standard Deviation:</strong> ", formatC(sd(values_vec, na.rm = TRUE), digits = 4, format = "f"), "</p>",
            if (input$viz_plot_type == "boxplot") {
              quantiles <- quantile(values_vec, probs = c(0, 0.01, 0.05, 0.1, 0.25, 0.5, 0.75, 0.9, 0.95, 0.99, 1), na.rm = TRUE)
              paste0(
                "<h5 style='color: #34495e; margin-top: 15px; margin-bottom: 10px;'>Quantiles:</h5>",
                paste(
                  sapply(names(quantiles), function(q) {
                    paste0("<p style='margin: 3px 0;'><strong>", q, ":</strong> ", formatC(quantiles[q], digits = 4, format = "f"), "</p>")
                  }),
                  collapse = ""
                )
              )
            } else if (input$viz_plot_type == "corr") {
              cor_values <- as.vector(cor(plot_data, use = "pairwise.complete.obs", method = input$viz_corr_method))
              cor_values <- cor_values[!is.na(cor_values) & cor_values != 1]
              paste0(
                "<h5 style='color: #34495e; margin-top: 15px; margin-bottom: 10px;'>Correlation Summary:</h5>",
                "<p style='margin: 5px 0;'><strong>Min correlation:</strong> ", formatC(min(cor_values, na.rm = TRUE), digits = 4, format = "f"), "</p>",
                "<p style='margin: 5px 0;'><strong>Max correlation:</strong> ", formatC(max(cor_values, na.rm = TRUE), digits = 4, format = "f"), "</p>",
                "<p style='margin: 5px 0;'><strong>Mean correlation:</strong> ", formatC(mean(cor_values, na.rm = TRUE), digits = 4, format = "f"), "</p>",
                "<p style='margin: 5px 0;'><strong>Median correlation:</strong> ", formatC(median(cor_values, na.rm = TRUE), digits = 4, format = "f"), "</p>"
              )
            } else {
              ""
            },
            "</div>"
          )
        )
      }
    })
    
    # Render the normality pie chart on the right side
    output$viz_normality_pie <- renderUI({
      req(input$viz_plot_type %in% c("hist", "density", "qq"))
      
      # Check if data is loaded - don't render if data is not available
      if (is.null(values$cleaned_molecules) || length(values$cleaned_molecules) == 0 ||
          is.null(values$normalized_data) || nrow(values$normalized_data) == 0) {
        return(NULL)
      }
      
      plotOutput("viz_normality_pie_plot", height = "320px", width = "100%")
    })
    
    # Render the actual pie chart plot
    output$viz_normality_pie_plot <- renderPlot({ 
      # Validate plot type first to avoid errors
      if (is.null(input$viz_plot_type) || length(input$viz_plot_type) == 0) {
        return(NULL)
      }
      req(input$viz_plot_type %in% c("hist", "density", "qq"))
      
      # Check if data is loaded - don't render if data is not available
      if (is.null(values$cleaned_molecules) || length(values$cleaned_molecules) == 0 ||
          is.null(values$normalized_data) || nrow(values$normalized_data) == 0) {
        return(NULL)
      }
      
      # Count features meeting normality criteria across all features
      all_normal_count <- 0
      all_total_count <- length(values$cleaned_molecules)
      
      if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) > 0) {
        for (i in seq_along(values$cleaned_molecules)) {
          f_values <- as.numeric(values$normalized_data[i, ])
          f_values <- f_values[!is.na(f_values)]
          
          if (length(f_values) >= 3) {
            if (length(f_values) > 5000) {
              set.seed(123)
              f_sample <- sample(f_values, 5000)
              f_test <- shapiro.test(f_sample)
            } else {
              f_test <- shapiro.test(f_values)
            }
            
            if (f_test$p.value > 0.05) {
              all_normal_count <- all_normal_count + 1
            }
          }
        }
      }
      
      # Don't render if no valid data to display
      if (all_total_count == 0) {
        return(NULL)
      }
      
      all_not_normal <- all_total_count - all_normal_count
      
      # Create normality summary pie chart
      pie_data <- data.frame(
        Status = c("Normal", "Not Normal"),
        Count = c(all_normal_count, all_not_normal),
        Percentage = c(
          round(all_normal_count / all_total_count * 100, 1),
          round(all_not_normal / all_total_count * 100, 1)
        )
      )
      
      # Create the plot with minimal margins to avoid "figure margins too large" error
      p <- ggplot(pie_data, aes(x = "", y = Count, fill = Status)) +
        geom_bar(stat = "identity", width = 1, color = "white", linewidth = 2) +
        coord_polar("y", start = 0) +
        scale_fill_manual(
          values = c("Normal" = "#2ecc71", "Not Normal" = "#e74c3c"),
          guide = guide_legend(title = "Normality Status")
        ) +
        geom_text(
          aes(label = paste0(Count, "\n(", Percentage, "%)")),
          position = position_stack(vjust = 0.5),
          size = 3,
          fontface = "bold",
          color = "white"
        ) +
        labs(title = "Overall Feature Normality Distribution") +
        theme_void() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 11, face = "bold", margin = margin(b = 4)),
          legend.position = "bottom",
          legend.title = element_text(face = "bold", size = 9),
          legend.text = element_text(size = 8),
          legend.key.size = unit(0.45, "cm"),
          legend.margin = margin(t = 1, b = 1),
          legend.box.margin = margin(t = 1, b = 1),
          plot.margin = margin(2, 4, 4, 4, "pt")
        )
      
      # Return the plot - ggplot handles its own margins better than base R
      p
    }, height = 320, res = UI_PLOT_RES, execOnResize = TRUE)
  
  # Download visualization plot
  output$download_viz_btn <- downloadHandler(
    filename = function() {
      paste0("Data_Visualization_RawAndNormalized_", input$viz_plot_type, "_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      
      # Generate both raw and normalized plots
      req(values$raw_data, values$normalized_data)
      
      # Extract numeric columns from raw_data (assuming first column is feature names)
      raw_matrix <- as.matrix(values$raw_data[, -1, drop = FALSE])
      plot_raw <- generate_data_viz_plot(raw_matrix, "raw")
      plot_normalized <- generate_data_viz_plot(values$normalized_data, "normalized")
      
      # Combine plots side by side using patchwork
      combined_plot <- plot_raw + plot_normalized +
        plot_layout(ncol = 2) +
        plot_annotation(
          title = paste0(toupper(input$viz_plot_type), " - Raw vs Normalized Data"),
          theme = theme(plot.title = element_text(size = 16, face = "bold", hjust = 0.5))
        )
      
      # Save the combined plot
      if (input$viz_plot_type == "qq" && input$viz_grouping != "all") {
        # For multi-panel QQ plots, we need to save differently
        ggsave(file,
               plot = grid::grid.grabExpr(print(combined_plot)),
               width = 16,  # Doubled width for side-by-side plots
               height = 8,
               dpi = dpi)
      } else {
        # For single ggplot objects
        ggsave(file,
               plot = combined_plot,
               width = 16,  # Doubled width for side-by-side plots
               height = 8,
               dpi = dpi)
      }
    }
  )
  # Generate all heatmaps
  # Download all heatmaps as ZIP file
  output$downloadAllHeatmapsBtn <- downloadHandler(
    filename = function() {
      paste0("All_Heatmaps_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".zip")
    },
    content = function(file) {
      req(values$normalized_data, values$cleaned_molecules,
          values$unique_groups, values$group_column_indices,
          values$stat_results)
      
      # Create temporary directory for heatmaps
      temp_dir <- tempdir()
      heatmap_dir <- file.path(temp_dir, paste0("Heatmap_Plots_", format(Sys.time(), "%Y%m%d_%H%M%S")))
      dir.create(heatmap_dir, showWarnings = FALSE, recursive = TRUE)
      
      # Progress bar
      withProgress(message = "Generating heatmaps...", {
        
        # Define dpi for plot generation
        dpi <- ifelse(is.null(input$global_dpi), 300, as.numeric(input$global_dpi))
        
        # Calculate total number of heatmaps to generate
        n_groups <- length(values$unique_groups)
        n_comparisons <- n_groups * (n_groups - 1) / 2 + 1  # Pairwise + All groups
        
        plot_count <- 0
        
        # Generate heatmap for all groups - but don't exit if it fails
        all_groups_success <- FALSE
        incProgress(amount = 0, detail = "Processing all groups heatmap")
        
        # Get all columns
        all_columns <- unlist(values$group_column_indices)
        all_data <- values$normalized_data[, all_columns, drop = FALSE]
        # Try to get precomputed p-values for all groups comparison using the helper function
        global_p_value_column <- get_appropriate_pvalue_column("Global")
        
        if (!is.null(values$stat_results) && global_p_value_column %in% colnames(values$stat_results)) {
          adjusted_p_values_all <- values$stat_results[[global_p_value_column]]
          
          # Calculate max log2FC between any two groups for filtering using precomputed results
          max_log2fc <- numeric(nrow(values$normalized_data))
          max_log2fc[] <- 0  # Initialize with zeros
          
          # Extract maximum absolute Log2FC from existing statistical results columns
          if (!is.null(values$stat_results)) {
            log2fc_columns <- grep("_Log2FC$", colnames(values$stat_results), value = TRUE)
            
            if (length(log2fc_columns) > 0) {
              # Calculate maximum absolute Log2FC across all pairwise comparisons
              for (col in log2fc_columns) {
                log2fc_values <- values$stat_results[[col]]
                # Handle reversed columns
                if (grepl("^REVERSED:", col)) {
                  log2fc_values <- -log2fc_values
                }
                max_log2fc <- pmax(max_log2fc, abs(log2fc_values), na.rm = TRUE)
              }
            } else {
              # Fallback: if no Log2FC columns found, skip fold change filtering
              message("No Log2FC columns found in statistical results. Skipping fold change filtering for all groups heatmap.")
              max_log2fc[] <- input$fc_cutoff  # Set to threshold so all features pass
            }
          } else {
            # No statistical results available - skip fold change filtering
            message("No statistical results available. Skipping fold change filtering for all groups heatmap.")
            max_log2fc[] <- input$fc_cutoff  # Set to threshold so all features pass
          }
          
          # Filter by BOTH p-value AND max log2FC
          significant_idx_all <- which(adjusted_p_values_all < input$pvalue_cutoff &
                                         max_log2fc >= input$fc_cutoff)
          all_groups_success <- TRUE
        } else {
          # Show warning but continue with pairwise comparisons
          showNotification(paste0("No precomputed global statistics found for all-groups heatmap. Skipping..."),
                           type = "warning", duration = 5)
          all_groups_success <- FALSE
        }
        
        # Only generate all-groups heatmap if we have the necessary stats
        if (all_groups_success) {
          if (length(significant_idx_all) > 0) {
            # If the stored heatmap object exists, use it for the All Groups heatmap
            tryCatch({
              all_groups_canvas_size <- compute_download_canvas_size(values$heatmap_data, input$heatmap_cell_size, dpi)
              png(file.path(heatmap_dir, "All_Groups_Heatmap.png"),
                  width = all_groups_canvas_size$width, height = all_groups_canvas_size$height, res = dpi)
              if (!is.null(values$heatmap_obj)) {
                row_label_size <- if(!is.null(input$heatmap_row_label_size)) input$heatmap_row_label_size else 10
                show_row_labels <- isTRUE(input$show_row_names) && !input$heatmap_cell_size %in% c("Small", "Compact")
                row_label_width_mm <- 0
                if (show_row_labels) {
                  row_names <- rownames(values$heatmap_data)
                  if (!is.null(row_names) && length(row_names) > 0) {
                    row_label_width_mm <- tryCatch({
                      grid::convertWidth(
                        ComplexHeatmap::max_text_width(row_names,
                                                       gp = grid::gpar(fontsize = row_label_size, fontface = "bold")),
                        "mm",
                        valueOnly = TRUE
                      )
                    }, error = function(e) 0)
                  }
                }
                right_pad_mm <- switch(input$heatmap_cell_size,
                                       "Medium" = 15,
                                       "Large" = 20,
                                       5)
                left_pad_mm <- max(5, row_label_width_mm + 5)
                ComplexHeatmap::draw(
                  values$heatmap_obj,
                  heatmap_legend_side = "bottom",
                  padding = unit(c(5, right_pad_mm, 5, left_pad_mm), "mm")
                )
              } else {
                # Fallback: recreate the heatmap if the stored object is missing
                # ...existing code for recreating the heatmap (copy from above if needed)...
                # For brevity, you may want to keep the old code here as a fallback
              }
              dev.off()
              # Save significant features to Excel
              wb <- createWorkbook()
              addWorksheet(wb, "Significant_Features")
              sig_features <- data.frame(
                Feature = values$cleaned_molecules[significant_idx_all],
                Adjusted_P_Value = adjusted_p_values_all[significant_idx_all],
                Max_Log2FC = max_log2fc[significant_idx_all],
                P_Value_Column_Used = global_p_value_column,
                stringsAsFactors = FALSE
              )
              writeData(wb, "Significant_Features", sig_features)
              saveWorkbook(wb, file.path(heatmap_dir, "All_Groups_Significant_Features.xlsx"), overwrite = TRUE)
            }, error = function(e) {
              message("Error generating all groups heatmap: ", e$message)
            })
          } else {
            showNotification(paste0("No significant features found for all groups with p-value < ",
                                    input$pvalue_cutoff, " and log2FC = ", input$fc_cutoff),
                             type = "warning", duration = 3)
          }
        }
        
        plot_count <- plot_count + 1
        incProgress(amount = 1 / n_comparisons, detail = "Completed all groups heatmap")
        
        # Initialize counter for successful pairwise heatmaps
        successful_pairwise <- 0
        
        # Generate pairwise heatmaps
        for (i in 1:(n_groups - 1)) {
          for (j in (i + 1):n_groups) {
            group1 <- values$unique_groups[i]
            group2 <- values$unique_groups[j]
            comparison_name <- paste(group1, "vs", group2)
            
            incProgress(amount = 0, detail = paste("Processing", group1, "vs", group2))
            
            # Get precomputed p-values and fold changes using helper functions
            p_value_column <- get_appropriate_pvalue_column(comparison_name)
            fc_column_result <- get_foldchange_column(comparison_name)
            
            # Handle reversed fold change columns
            is_reversed <- FALSE
            if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
              is_reversed <- TRUE
              fc_column <- sub("^REVERSED:", "", fc_column_result)
            } else {
              fc_column <- fc_column_result
            }
            
            # Continue to next comparison if precomputed stats are not available
            if (!p_value_column %in% colnames(values$stat_results) ||
                is.null(fc_column) || !fc_column %in% colnames(values$stat_results)) {
              showNotification(paste("No precomputed statistics found for", comparison_name,
                                     "- Skipping this comparison."),
                               type = "warning", duration = 3)
              plot_count <- plot_count + 1
              incProgress(amount = 1 / n_comparisons, detail = paste("Skipped", comparison_name, "- no stats"))
              next
            }
            
            # Use precomputed values and handle fold change direction correctly
            adjusted_p_values <- values$stat_results[[p_value_column]]
            log2_fc <- values$stat_results[[fc_column]]
            
            # CORRECTION: Reverse fold change values to match expected direction
            # If "Group1 vs Group2" should show features upregulated in Group1 as positive,
            # but the calculation gives Group2/Group1, then we need to negate the values
            if (is_reversed) {
              log2_fc <- -log2_fc
            }
            
            # Get significant molecules using BOTH p-value AND log2FC
            significant_idx <- which(!is.na(adjusted_p_values) &
                                       !is.na(log2_fc) &
                                       adjusted_p_values < input$pvalue_cutoff &
                                       abs(log2_fc) >= input$fc_cutoff)
            
            if (length(significant_idx) == 0) {
              # Skip generating heatmap if no significant features found
              showNotification(paste0("No significant features found for ", group1, " vs ", group2,
                                      " with p-value < ", input$pvalue_cutoff, " and log2FC = ", input$fc_cutoff),
                               type = "warning", duration = 3)
              # Update progress counter
              plot_count <- plot_count + 1
              incProgress(amount = 1 / n_comparisons, detail = paste("Skipped", group1, "vs", group2, "- no features"))
              next
            }
            
            # Extract data for the selected groups
            group1_columns <- values$group_column_indices[[i]]
            group2_columns <- values$group_column_indices[[j]]
            
            data1 <- values$normalized_data[, group1_columns, drop = FALSE]
            data2 <- values$normalized_data[, group2_columns, drop = FALSE]
            
            # Prepare heatmap data
            heatmap_data <- cbind(data1[significant_idx, , drop = FALSE],
                                  data2[significant_idx, , drop = FALSE])
            
            # Set row names based on label type selection
            if (!is.null(input$heatmap_label_type) && input$heatmap_label_type == "ids" &&
                !is.null(values$accession_ids) && length(values$accession_ids) >= max(significant_idx)) {
              rownames(heatmap_data) <- make.unique(values$accession_ids[significant_idx])
            } else {
              rownames(heatmap_data) <- make.unique(values$cleaned_molecules[significant_idx])
            }
            
            # Rename sample columns
            colnames(heatmap_data) <- rename_samples(colnames(heatmap_data))
            
            # Column annotation
            column_split <- c(rep(group1, length(group1_columns)),
                              rep(group2, length(group2_columns)))
            
            # Z-score normalize
            heatmap_data <- t(scale(t(heatmap_data)))
            
            # Define color function
            col_fun <- circlize::colorRamp2(c(-2, 0, 2),
                                            c(input$lowColor, input$midColor, input$highColor))
            
            tryCatch({
              # Calculate dynamic canvas size for pairwise heatmap
              pairwise_canvas_size <- compute_download_canvas_size(heatmap_data, input$heatmap_cell_size, dpi)
              
              png(file.path(heatmap_dir, paste0(group1, "_vs_", group2, "_Heatmap.png")),
                  width = pairwise_canvas_size$width, height = pairwise_canvas_size$height, res = dpi)
              
              row_split <- if(nrow(heatmap_data) < 2) NULL else 2
              
              # Fix spaces in column_split by creating a named factor with proper labels (SAME AS UI)
              clean_splits <- column_split
              split_levels <- unique(clean_splits)
              original_labels <- preserve_group_names(split_levels)
              names(split_levels) <- original_labels
              fixed_column_split <- factor(clean_splits, levels = split_levels)
              
              # Handle the Small size option (EXACT same as UI staticHeatmap)
              if(input$heatmap_cell_size == "Small") {
                column_labels <- HeatmapAnnotation(
                  Group = anno_block(
                    gp = grid::gpar(fill = rainbow(length(unique(fixed_column_split)))),
                    labels = original_labels,
                    labels_gp = grid::gpar(fontsize = 8, fontface = "bold"),
                    height = unit(3, "mm")
                  ),
                  show_legend = FALSE,
                  height = unit(5, "mm")
                )
                
                ht <- ComplexHeatmap::Heatmap(
                  heatmap_data,
                  name = "Z-score",
                  cluster_rows = input$cluster_rows,
                  cluster_columns = input$cluster_cols,
                  show_row_names = FALSE,
                  show_column_names = FALSE,
                  column_names_side = "top",
                  rect_gp = gpar(col = "black"),
                  row_dend_reorder = FALSE,
                  column_title = paste0(group1, " vs ", group2, " Heatmap"),
                  column_title_gp = grid::gpar(fontface = "bold", fontsize = 14),
                  heatmap_legend_param = list(
                    title = NULL,
                    legend_width = switch(input$heatmap_cell_size,
                                          "Small" = unit(1, "in"),
                                          "Compact" = unit(2, "in"),
                                          "Medium" = unit(3, "in"),
                                          "Large" = unit(4, "in"),
                                          unit(3, "in")),
                    grid_height = unit(0.05, "in"),
                    direction = "horizontal",
                    labels_gp = grid::gpar(fontface = "bold")
                  ),
                  col = col_fun,
                  na_col = input$naColor %||% "gray",
                  row_split = row_split,
                  column_split = fixed_column_split,
                  row_names_gp = grid::gpar(fontsize = 0),
                  column_names_gp = grid::gpar(fontsize = 0),
                  row_title = NULL,
                  top_annotation = column_labels,
                  show_row_dend = TRUE,
                  row_gap = unit(1, "mm"),
                  column_gap = unit(1, "mm"),
                  border = FALSE
                )
              } else {
                ht <- ComplexHeatmap::Heatmap(
                  heatmap_data,
                  name = "Z-score",
                  cluster_rows = input$cluster_rows,
                  cluster_columns = input$cluster_cols,
                  show_row_names = ifelse(input$heatmap_cell_size %in% c("Compact"), FALSE, input$show_row_names),
                  show_column_names = TRUE,
                  column_names_side = "top",
                  rect_gp = gpar(col = "black"),
                  row_dend_reorder = FALSE,
                  column_title = paste0(group1, " vs ", group2, " Heatmap"),
                  column_title_gp = gpar(fontface = "bold", fontsize = 14),
                  heatmap_legend_param = list(
                    title = NULL,
                    legend_width = switch(input$heatmap_cell_size,
                                          "Small" = unit(1, "in"),
                                          "Compact" = unit(2, "in"),
                                          "Medium" = unit(3, "in"),
                                          "Large" = unit(4, "in"),
                                          unit(3, "in")),
                    grid_height = unit(0.05, "in"),
                    direction = "horizontal",
                    labels_gp = grid::gpar(fontface = "bold")
                  ),
                  col = col_fun,
                  na_col = input$naColor %||% "gray",
                  row_split = row_split,
                  column_split = fixed_column_split,
                  row_names_gp = switch(input$heatmap_cell_size,
                                        "Compact" = grid::gpar(fontsize = 0),
                                        "Medium" = grid::gpar(fontsize = 8, fontface = "bold"),
                                        "Large" = grid::gpar(fontsize = 10, fontface = "bold"),
                                        grid::gpar(fontsize = 10, fontface = "bold")),
                  column_names_gp = switch(input$heatmap_cell_size,
                                           "Compact" = grid::gpar(fontsize = 12, fontface = "bold"),
                                           "Medium" = grid::gpar(fontsize = 12, fontface = "bold"),
                                           "Large" = grid::gpar(fontsize = 14, fontface = "bold"),
                                           grid::gpar(fontsize = 12, fontface = "bold")),
                  row_title = NULL,
                  show_row_dend = TRUE,
                  row_gap = unit(1, "mm"),
                  column_gap = unit(1, "mm"),
                  border = FALSE
                )
              }
              
              row_label_size <- if(!is.null(input$heatmap_row_label_size)) input$heatmap_row_label_size else 10
              show_row_labels <- isTRUE(input$show_row_names) && !input$heatmap_cell_size %in% c("Small", "Compact")
              row_label_width_mm <- 0
              if (show_row_labels) {
                row_names <- rownames(heatmap_data)
                if (!is.null(row_names) && length(row_names) > 0) {
                  row_label_width_mm <- tryCatch({
                    grid::convertWidth(
                      ComplexHeatmap::max_text_width(row_names,
                                                     gp = grid::gpar(fontsize = row_label_size, fontface = "bold")),
                      "mm",
                      valueOnly = TRUE
                    )
                  }, error = function(e) 0)
                }
              }
              right_pad_mm <- switch(input$heatmap_cell_size,
                                     "Medium" = 15,
                                     "Large" = 20,
                                     5)
              left_pad_mm <- max(5, row_label_width_mm + 5)
              ComplexHeatmap::draw(
                ht,
                heatmap_legend_side = "bottom",
                padding = unit(c(5, right_pad_mm, 5, left_pad_mm), "mm")
              )
              dev.off()
              
              # Save significant features to Excel
              wb <- createWorkbook()
              addWorksheet(wb, "Significant_Features")
              sig_features <- data.frame(
                Feature = values$cleaned_molecules[significant_idx],
                Adjusted_P_Value = adjusted_p_values[significant_idx],
                Log2FC = log2_fc[significant_idx],
                stringsAsFactors = FALSE
              )
              writeData(wb, "Significant_Features", sig_features)
              saveWorkbook(wb, file.path(heatmap_dir, paste0(group1, "_vs_", group2, "_Significant_Features.xlsx")), overwrite = TRUE)
              
              # Track successful heatmap generation
              successful_pairwise <- successful_pairwise + 1
              
            }, error = function(e) {
              message("Error generating heatmap for ", group1, " vs ", group2, ": ", e$message)
              showNotification(paste("Error generating heatmap for", group1, "vs", group2, ":", e$message),
                               type = "error", duration = 3)
            })
            
            # Update progress counter
            plot_count <- plot_count + 1
            incProgress(amount = 1 / n_comparisons, detail = paste("Completed", group1, "vs", group2))
          }
        }
        
        # Create ZIP file with all generated heatmaps
        create_zip_file <- function(zipfile, files, root_dir) {
          if (requireNamespace("zip", quietly = TRUE)) {
            zip::zip(zipfile = zipfile, files = files, root = root_dir)
          } else {
            # For utils::zip, we need to change to the directory first
            old_wd <- getwd()
            on.exit(setwd(old_wd), add = TRUE)
            setwd(root_dir)
            utils::zip(zipfile = zipfile, files = files)
          }
        }
        incProgress(amount = 0, detail = "Creating ZIP file...")
        
        # List all files in the heatmap directory (basename only)
        heatmap_files <- list.files(heatmap_dir, full.names = FALSE)
        
        if (length(heatmap_files) > 0) {
          # Create ZIP file
          create_zip_file(zipfile = file, files = heatmap_files, root_dir = heatmap_dir)
          
          # Show completion message
          showNotification(paste0(
            "Heatmaps ZIP file created successfully! ",
            ifelse(all_groups_success, "All-groups heatmap included. ", ""),
            ifelse(successful_pairwise > 0, paste0(successful_pairwise, " pairwise heatmap(s) included."), ""),
            " Using p-value < ", input$pvalue_cutoff, " and log2FC = ", input$fc_cutoff
          ), type = "message", duration = 5)
        } else {
          # No files generated, create empty ZIP with message
          temp_file <- file.path(heatmap_dir, "No_heatmaps_generated.txt")
          writeLines(paste0("No heatmaps were generated. No features meet the current thresholds:\n",
                            "P-value < ", input$pvalue_cutoff, "\n",
                            "Log2FC = ", input$fc_cutoff), temp_file)
          create_zip_file(zipfile = file, files = "No_heatmaps_generated.txt", root_dir = heatmap_dir)
          
          showNotification(paste0("No heatmaps were generated. No features meet the current thresholds (p-value < ",
                                  input$pvalue_cutoff, ", log2FC = ", input$fc_cutoff, ")."), type = "warning", duration = 5)
        }
        
      }) # Close withProgress
    } # Close content function
  ) # Close downloadHandler
  
  # Proteomics tab functionality
  # Initialize reactive values for proteomics
  proteomics_values <- reactiveValues(
    gene_list = NULL,
    background = NULL,
    enrichment_results = NULL,
    plots_available = NULL,
    current_plots = list(),
    network_plots = list(),
    enrichment_cache = list(),
    input_summary_message = NULL,
    sample_genes = NULL,
    highlight_terms = NULL,  # Store user-specified highlight terms
    fold_change_data = NULL,
    original_fold_change_data = NULL,
    analysis_running = FALSE,  # Flag to track if analysis is currently running
    last_kegg_pathway_cleared = NULL  # Track when KEGG inputs were last cleared
  )
  
  # Observer to update highlight terms when user changes them
  observeEvent(input$proteomics_gprofiler_highlight_terms, {
    # Now input is a vector of selected term IDs
    if (!is.null(input$proteomics_gprofiler_highlight_terms) &&
        length(input$proteomics_gprofiler_highlight_terms) > 0) {
      proteomics_values$highlight_terms <- input$proteomics_gprofiler_highlight_terms
    } else {
      proteomics_values$highlight_terms <- NULL
    }
  })
  
  # Handle group swapping in enrichment pairwise comparison
  observeEvent(input$proteomics_swap_groups, {
    temp_group1 <- input$proteomics_pairwise_group1
    temp_group2 <- input$proteomics_pairwise_group2
    updateSelectInput(session, "proteomics_pairwise_group1", selected = temp_group2)
    updateSelectInput(session, "proteomics_pairwise_group2", selected = temp_group1)
  })
  
  # Update UI based on available data
  observe({
    # Update intersection sets
    if (!is.null(values$intersection_comparison_results)) {
      set_names <- names(values$intersection_comparison_results)
      updateSelectInput(session, "proteomics_intersection_set",
                        choices = set_names)
    }
  })
  
  # Helper to get comparison stats with fallback to reversed comparison
  get_comparison_stats <- function(group1, group2) {
    # Try direct comparison first
    comparison_name <- paste(group1, "vs", group2)
    p_value_column <- get_appropriate_pvalue_column(comparison_name)
    fc_column_result <- get_foldchange_column(comparison_name)
    
    # Check if columns exist
    if (!is.null(values$stat_results) && 
        p_value_column %in% colnames(values$stat_results) &&
        !is.null(fc_column_result)) {
      return(list(
        comparison_name = comparison_name,
        p_value_column = p_value_column,
        fc_column_result = fc_column_result,
        is_reversed = FALSE
      ))
    }
    
    # Try reversed comparison
    comparison_name_rev <- paste(group2, "vs", group1)
    p_value_column_rev <- get_appropriate_pvalue_column(comparison_name_rev)
    fc_column_result_rev <- get_foldchange_column(comparison_name_rev)
    
    if (!is.null(values$stat_results) && 
        p_value_column_rev %in% colnames(values$stat_results) &&
        !is.null(fc_column_result_rev)) {
      return(list(
        comparison_name = comparison_name_rev,
        p_value_column = p_value_column_rev,
        fc_column_result = fc_column_result_rev,
        is_reversed = TRUE  # Flag that we found the reverse
      ))
    }
    
    return(NULL)
  }
  
  # Helper functions to determine which column to use for p-values and fold changes
  get_pvalue_column <- function(comparison_name) {
    if (input$bootstrap_enabled == "yes") {
      paste0(comparison_name, "_Bootstrap_AdjPValue")
    } else {
      paste0(comparison_name, "_AdjPValue")
    }
  }
  
  # Helper function to get IDs for features using designated ID columns with fallback
  get_ids_for_features <- function(feature_names, data, designated_columns) {
    if (is.null(designated_columns) || length(designated_columns) == 0) {
      return(feature_names)  # Fallback to feature names if no designated columns
    }
    
    # Initialize result vector
    result_ids <- rep(NA, length(feature_names))
    
    # Try each designated column in order (first is primary, others are fallback)
    for (col_idx in designated_columns) {
      if (col_idx <= ncol(data)) {
        col_name <- colnames(data)[col_idx]
        if (col_name %in% colnames(data)) {
          col_values <- data[[col_name]]
          # For each feature, if we don't have an ID yet, try to get it from this column
          for (i in seq_along(feature_names)) {
            if (is.na(result_ids[i]) || result_ids[i] == "") {
              # Find the row where the feature name matches
              matching_rows <- which(data[[1]] == feature_names[i])  # Assuming first column is feature names
              if (length(matching_rows) > 0) {
                id_value <- col_values[matching_rows[1]]
                if (!is.na(id_value) && id_value != "") {
                  result_ids[i] <- as.character(id_value)
                }
              }
            }
          }
        }
      }
    }
    
    # For any remaining NA values, use the original feature names
    result_ids[is.na(result_ids) | result_ids == ""] <- feature_names[is.na(result_ids) | result_ids == ""]
    
    return(result_ids)
  }
  
  # Helper function to get IDs for features by their indices in the data
  get_ids_for_features_by_index <- function(feature_indices, data, designated_columns) {
    if (is.null(designated_columns) || length(designated_columns) == 0) {
      # Fallback to feature names using indices
      feature_names <- data[feature_indices, 1]  # Assuming first column is feature names
      return(feature_names)
    }
    
    # Get feature names first
    feature_names <- data[feature_indices, 1]
    
    # Use the same logic as get_ids_for_features
    return(get_ids_for_features(feature_names, data, designated_columns))
  }
  
  # Updated Proteomics Analysis Observer
  observeEvent(input$proteomics_run, {
    # Mark analysis as running and timestamp the clearing
    proteomics_values$analysis_running <- TRUE
    proteomics_values$last_kegg_pathway_cleared <- Sys.time()
    
    # Immediately send aggressive reset command
    session$sendCustomMessage(type = "resetKeggInputs", message = list(
      timestamp = as.character(Sys.time()),
      force = TRUE
    ))
    
    # Also directly clear any existing KEGG pathway inputs server-side
    if(exists("KEGG_pathway") && !is.null(input$KEGG_pathway)) {
      updateTextInput(session, "KEGG_pathway", value = "")
    }
    
    # Clear any cached values that might be lingering
    session$userData$last_kegg_click <- NULL
    
    showNotification("Running enrichment analysis...", type = "message", duration = 3)
    # Recalculate filtered gene list using adjusted values
    if (input$proteomics_source == "intersection") {
      req(input$proteomics_intersection_set)

      feature_list <- values$intersection_comparison_results[[input$proteomics_intersection_set]]
      proteomics_values$gene_list_feature_names <- feature_list

      # Intersection results are feature names; map to designated enrichment IDs.
      gene_list <- feature_list
      if (!is.null(values$accession_ids) &&
          !is.null(values$cleaned_molecules) &&
          length(values$accession_ids) == length(values$cleaned_molecules)) {
        idx <- match(feature_list, values$cleaned_molecules)
        gene_list <- values$accession_ids[idx]
      }

      # Drop features without any designated ID after primary+secondary fallback.
      gene_list <- unique(gene_list[!is.na(gene_list) & nzchar(gene_list)])
      if (length(gene_list) == 0) {
        showNotification("No designated enrichment IDs were found for the selected intersection set.",
                         type = "error", duration = 6)
        return(NULL)
      }
    }
    # In the pairwise comparison section of the get_gene_list() function
    else if (input$proteomics_source == "pairwise") {
      # Get comparison stats with fallback to reversed comparison
      comp_stats <- get_comparison_stats(input$proteomics_pairwise_group1, input$proteomics_pairwise_group2)
      
      if (is.null(comp_stats)) {
        showNotification(paste("Statistical results not found for comparison between",
                              input$proteomics_pairwise_group1, "and", input$proteomics_pairwise_group2),
                         type = "error", duration = 5)
        return(NULL)
      }
      
      comparison_name <- comp_stats$comparison_name
      p_value_column <- comp_stats$p_value_column
      fc_column_result <- comp_stats$fc_column_result
      is_comparison_reversed <- comp_stats$is_reversed  # TRUE if we had to use reversed comparison
      
      # Handle reversed fold change columns
      is_fc_reversed <- FALSE
      if (!is.null(fc_column_result) && grepl("^REVERSED:", fc_column_result)) {
        is_fc_reversed <- TRUE
        fc_column <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_column <- fc_column_result
      }
      
      # Use pre-calculated statistics
      adjusted_p_values <- values$stat_results[[p_value_column]]
      log2_fold_changes <- values$stat_results[[fc_column]]
      
      # Reverse fold changes if necessary:
      # 1. If the FC column itself is marked as REVERSED
      # 2. If we had to use the reversed comparison name to find the stats
      if (is_fc_reversed) {
        log2_fold_changes <- -log2_fold_changes
      }
      if (is_comparison_reversed) {
        log2_fold_changes <- -log2_fold_changes
      }
      
      # Add ROTS FDR handling (match ROC tab implementation)
      fdr_values <- NULL
      fdr_column <- NULL
      is_fdr_reversed <- FALSE
      if (input$sig_method == "rots") {
        # Use the same comparison_name from get_comparison_stats to maintain consistency
        fdr_column_direct <- paste0(comparison_name, "_FDR")
        
        # Try direct comparison name first
        if (!is.null(values$stat_results)) {
          if (fdr_column_direct %in% colnames(values$stat_results)) {
            fdr_column <- fdr_column_direct
            fdr_values <- values$stat_results[[fdr_column]]
            is_fdr_reversed <- FALSE
          }
        }
      }
      
      # Apply filtering using p-value, FDR (if ROTS), AND fold change thresholds based on checkboxes
      significant_idx <- c()
      
      # Debug output
      cat("Proteomics filtering debug:\n")
      cat("  - sig_method:", input$sig_method, "\n")
      cat("  - FDR column found:", !is.null(fdr_column), "\n")
      if (!is.null(fdr_column)) {
        cat("  - FDR column name:", fdr_column, "\n")
        cat("  - FDR values available:", !is.null(fdr_values), "\n")
        if (!is.null(fdr_values)) {
          cat("  - FDR values range:", range(fdr_values, na.rm = TRUE), "\n")
        }
      }
      cat("  - proteomics_fdr_cutoff:", input$proteomics_fdr_cutoff, "\n")
      cat("  - P-value cutoff:", input$proteomics_pairwise_pval, "\n")
      cat("  - FC cutoff:", input$proteomics_pairwise_fc, "\n")
      cat("  - Include up:", input$proteomics_include_up, "\n")
      cat("  - Include down:", input$proteomics_include_down, "\n")
      
      # Include upregulated features if checkbox is checked
      if (input$proteomics_include_up) {
        # For ROTS with FDR available, apply all three cutoffs simultaneously
        if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          up_idx <- which(!is.na(adjusted_p_values) &
                            !is.na(fdr_values) &
                            !is.na(log2_fold_changes) &
                            log2_fold_changes >= input$proteomics_pairwise_fc &
                            adjusted_p_values <= input$proteomics_pairwise_pval &
                            fdr_values <= input$proteomics_fdr_cutoff)
          cat("  - Upregulated with FDR: found", length(up_idx), "features\n")
        } else {
          # Standard filter for non-ROTS or missing FDR
          up_idx <- which(!is.na(adjusted_p_values) &
                            !is.na(log2_fold_changes) &
                            log2_fold_changes >= input$proteomics_pairwise_fc &
                            adjusted_p_values <= input$proteomics_pairwise_pval)
          cat("  - Upregulated without FDR: found", length(up_idx), "features\n")
        }
        significant_idx <- c(significant_idx, up_idx)
      }
      
      # Include downregulated features if checkbox is checked
      if (input$proteomics_include_down) {
        # For ROTS with FDR available, apply all three cutoffs simultaneously
        if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          down_idx <- which(!is.na(adjusted_p_values) &
                              !is.na(fdr_values) &
                              !is.na(log2_fold_changes) &
                              log2_fold_changes <= -input$proteomics_pairwise_fc &
                              adjusted_p_values <= input$proteomics_pairwise_pval &
                              fdr_values <= input$proteomics_fdr_cutoff)
          cat("  - Downregulated with FDR: found", length(down_idx), "features\n")
        } else {
          # Standard filter for non-ROTS or missing FDR
          down_idx <- which(!is.na(adjusted_p_values) &
                              !is.na(log2_fold_changes) &
                              log2_fold_changes <= -input$proteomics_pairwise_fc &
                              adjusted_p_values <= input$proteomics_pairwise_pval)
          cat("  - Downregulated without FDR: found", length(down_idx), "features\n")
        }
        significant_idx <- c(significant_idx, down_idx)
      }
      
      # Remove duplicates
      significant_idx <- unique(significant_idx)
      
      # Check if any direction was selected
      if (length(significant_idx) == 0 && (!input$proteomics_include_up && !input$proteomics_include_down)) {
        showNotification("Please select at least one direction (upregulated or downregulated) to analyze.",
                         type = "error", duration = 5)
        return(NULL)
      }
      
      if (length(significant_idx) == 0) {
        showNotification("No significant genes/proteins found with the current thresholds.",
                         type = "error", duration = 5)
        return(NULL)
      }
      
      # Use designated ID columns with fallback logic for significant features
      if (!is.null(values$accession_ids) &&
          !is.null(values$cleaned_molecules) &&
          length(values$accession_ids) == length(values$cleaned_molecules)) {
        gene_list <- values$accession_ids[significant_idx]
      } else {
        gene_list <- values$cleaned_molecules[significant_idx]
      }

      # Drop features without any designated ID after primary+secondary fallback.
      gene_list <- unique(gene_list[!is.na(gene_list) & nzchar(gene_list)])
      if (length(gene_list) == 0) {
        showNotification("No designated enrichment IDs were found for the selected pairwise thresholds.",
                         type = "error", duration = 6)
        return(NULL)
      }
      # Store the corresponding feature names for mapping
      proteomics_values$gene_list_feature_names <- values$cleaned_molecules[significant_idx]
      validation <- validate_ids(gene_list)
      
      # Create descriptive message based on which directions are included
      direction_text <- c()
      if (input$proteomics_include_up) direction_text <- c(direction_text, "upregulated")
      if (input$proteomics_include_down) direction_text <- c(direction_text, "downregulated")
      direction_str <- paste(direction_text, collapse = " and ")
      
      # Create result object WITHOUT returning
      if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
        result <- list(
          genes = gene_list,
          message = sprintf("Found %d significant %s genes/proteins (adjusted p-value = %.3g, FDR = %.3g, |log2FC| = %.2f). %s",
                            length(gene_list),
                            direction_str,
                            input$proteomics_pairwise_pval,
                            input$proteomics_fdr_cutoff,
                            input$proteomics_pairwise_fc,
                            validation$message)
        )
      } else {
        result <- list(
          genes = gene_list,
          message = sprintf("Found %d significant %s genes/proteins (adjusted p-value = %.3g, |log2FC| = %.2f). %s",
                            length(gene_list),
                            direction_str,
                            input$proteomics_pairwise_pval,
                            input$proteomics_pairwise_fc,
                            validation$message)
        )
      }
    }
    else if (input$proteomics_source == "manual") {
      # Use the updated get_gene_list function for manual input
      result <- get_gene_list()
      if (is.null(result$genes)) {
        showNotification(result$message, type = "error", duration = 5)
        return(NULL)
      }
      gene_list <- result$genes
      
      # Store full gene universe for custom background (if available)
      if (!is.null(result$full_gene_universe)) {
        proteomics_values$manual_full_gene_universe <- result$full_gene_universe
        cat("Stored full gene universe:", length(result$full_gene_universe), "genes for background\n")
      } else {
        proteomics_values$manual_full_gene_universe <- NULL
      }
      
      # Try to map manual gene list to feature names
      feature_names <- gene_list  # Default to gene_list
      
      # First check if input matches accession_ids
      if (!is.null(values$accession_ids) && length(values$accession_ids) == length(values$cleaned_molecules)) {
        matched_idx <- match(gene_list, values$accession_ids, nomatch = 0)
        if (any(matched_idx > 0)) {
          # Some or all matches found in accession_ids
          feature_names <- ifelse(matched_idx > 0,
                                  values$cleaned_molecules[matched_idx],
                                  gene_list)  # Use original if no match
        } else {
          # Try matching against cleaned_molecules instead
          matched_idx <- match(gene_list, values$cleaned_molecules, nomatch = 0)
          if (any(matched_idx > 0)) {
            feature_names <- ifelse(matched_idx > 0,
                                    values$cleaned_molecules[matched_idx],
                                    gene_list)
          }
        }
      } else {
        # No accession_ids or mismatch in length, try cleaned_molecules
        matched_idx <- match(gene_list, values$cleaned_molecules, nomatch = 0)
        if (any(matched_idx > 0)) {
          feature_names <- ifelse(matched_idx > 0,
                                  values$cleaned_molecules[matched_idx],
                                  gene_list)
        }
      }
      proteomics_values$gene_list_feature_names <- feature_names
      
      # Store additional data for GSEA if available
      if (!is.null(result$pvalues) && !is.null(result$fold_changes)) {
        proteomics_values$manual_pvalues <- result$pvalues
        proteomics_values$manual_fold_changes <- result$fold_changes
        proteomics_values$analysis_type <- "GSEA"
      } else {
        proteomics_values$manual_pvalues <- NULL
        proteomics_values$manual_fold_changes <- NULL
        proteomics_values$analysis_type <- "ORA"
      }
    }
    else if (input$proteomics_source == "mofa_factor") {
      # Use the get_gene_list function for MOFA input
      result <- get_gene_list()
      if (is.null(result$genes)) {
        showNotification(result$message, type = "error", duration = 5)
        return(NULL)
      }
      gene_list <- result$genes
      
      # Store additional data for GSEA if available
      if (!is.null(result$fold_changes)) {
        proteomics_values$manual_fold_changes <- result$fold_changes
        proteomics_values$analysis_type <- "GSEA"
      } else {
        proteomics_values$manual_fold_changes <- NULL
        proteomics_values$analysis_type <- "ORA"
      }
    }
    # Store the obtained gene/protein list
    values$proteomics_genes <- gene_list
    # Also store the original gene list separately to preserve for UpSet plot usage
    values$proteomics_genes_original <- gene_list
    proteomics_values$gene_list <- gene_list
    
    # If result is not defined (e.g. for sources other than diff_analysis), create a default summary using adjusted filtering info
    if (!exists("result") || is.null(result$message)) {
      validation <- validate_ids(gene_list)
      result <- list(
        genes = gene_list,
        message = sprintf("Found %d genes/proteins. %s", length(gene_list), validation$message)
      )
    }
    # Run enrichment analysis using the selected tool
    enrichment_results <- NULL
    
    # Create cache key for enrichment results based on analysis parameters
    general_params <- list(
      source = input$proteomics_source,
      id_type = input$proteomics_id_type,
      organism = input$proteomics_organism
    )
    
    # Add source-specific parameters to the cache key
    if (input$proteomics_source == "pairwise") {
      general_params$group1 <- input$proteomics_pairwise_group1
      general_params$group2 <- input$proteomics_pairwise_group2
      general_params$pval <- input$proteomics_pairwise_pval
      general_params$fc <- input$proteomics_pairwise_fc
      general_params$include_up <- input$proteomics_include_up
      general_params$include_down <- input$proteomics_include_down
      general_params$sig_method <- input$sig_method
      if (input$sig_method == "rots") {
        general_params$fdr_cutoff <- input$proteomics_fdr_cutoff
      }
    } else if (input$proteomics_source == "intersection") {
      general_params$intersection_set <- input$proteomics_intersection_set
    } else if (identical(input$proteomics_source, "mofa_factor")) {
      general_params$mofa_view <- input$mofa_enrich_view
      general_params$mofa_factor <- input$mofa_enrich_factor
      general_params$mofa_sign <- input$mofa_enrich_sign
      general_params$mofa_rank_type <- input$mofa_enrich_rank_type
      general_params$mofa_top_n <- input$mofa_enrich_top_n
    }
    
    # Tool-specific parameters for cache key
    tool_params <- list()
    if (input$proteomics_tool == "gprofiler") {
      tool_params <- list(
        correction_method = input$proteomics_gprofiler_correction,
        significant = input$proteomics_gprofiler_sig,
        sources = input$proteomics_gprofiler_sources,
        domain_scope = input$proteomics_gprofiler_domain,
        bg_source = input$proteomics_gprofiler_bg_source,
        custom_bg_text = input$proteomics_gprofiler_custom_bg
      )
    } else if (input$proteomics_tool == "clusterprofiler") {
      tool_params <- list(
        analysis = input$proteomics_cp_analysis,
        pval = input$proteomics_cp_pval,
        qval = input$proteomics_cp_qval,
        pmethod = input$proteomics_cp_pmethod,
        background_type = input$proteomics_cp_background_type,
        bg_source = input$proteomics_cp_bg_source,
        custom_bg_text = input$proteomics_cp_custom_bg
      )
      if (input$proteomics_cp_analysis == "go" || input$proteomics_cp_analysis == "gsea_go") {
        tool_params$go_ont <- input$proteomics_cp_go_ont
      } else if (input$proteomics_cp_analysis == "msigdb" || input$proteomics_cp_analysis == "gsea_msigdb") {
        tool_params$msigdb_category <- input$proteomics_cp_msigdb_category
        tool_params$msigdb_subcategory <- input$proteomics_cp_msigdb_subcategory
      }
      
      # Add GSEA-specific parameters for cache key
      if (input$proteomics_cp_analysis %in% c("gsea_go", "gsea_kegg", "gsea_kegg_module", "gsea_reactome", "gsea_pathwaycommons", "gsea_wikipathways", "gsea_msigdb")) {
        tool_params$gsea_minGSSize <- input$proteomics_gsea_minGSSize
        tool_params$gsea_maxGSSize <- input$proteomics_gsea_maxGSSize
        tool_params$gsea_scoreType <- input$proteomics_gsea_scoreType
        # For MOFA-factor source, ranking metric is always MOFA weights (log2FC-style ranking)
        tool_params$gsea_ranking_metric <- if (identical(input$proteomics_source, "mofa_factor")) "log2fc" else input$proteomics_gsea_ranking_metric
      }
    } else if (input$proteomics_tool == "enrichr") {
      tool_params <- list(
        databases = input$proteomics_enrichr_db,
        bg_option = input$proteomics_enrichr_bg_option,
        bg_source = input$proteomics_enrichr_bg_source,
        custom_bg_text = input$proteomics_enrichr_custom_bg
      )
    } else if (input$proteomics_tool == "reactomepa") {
      tool_params <- list(
        pval = input$proteomics_reactome_pval,
        qval = input$proteomics_reactome_qval,
        bg_type = input$proteomics_reactome_bg_type,
        bg_source = input$proteomics_reactome_bg_source,
        custom_bg_text = input$proteomics_reactome_custom_bg
      )
    } else if (input$proteomics_tool == "topgo") {
      tool_params <- list(
        ontology = input$proteomics_topgo_ontology,
        algorithm = input$proteomics_topgo_algorithm,
        statistic = input$proteomics_topgo_statistic,
        nodesize = input$proteomics_topgo_nodesize,
        terms = input$proteomics_topgo_terms,
        correction = input$proteomics_topgo_correction,
        bg_type = input$proteomics_topgo_bg_type,
        bg_source = input$proteomics_topgo_bg_source,
        custom_bg_text = input$proteomics_topgo_custom_bg
      )
    }
    
    # Create cache key for enrichment results
    enrichment_cache_key <- create_enrichment_cache_key(
      tool = input$proteomics_tool,
      gene_list = gene_list,
      organism = input$proteomics_organism,
      analysis_params = general_params,
      tool_specific_params = tool_params
    )
    
    # Check if enrichment results are cached
    cached_enrichment <- get_enrichment_from_cache(enrichment_cache_key)
    if (!is.null(cached_enrichment)) {
      cat("Using cached enrichment results for", input$proteomics_tool, "\n")
      enrichment_results <- cached_enrichment$enrichment_results
      fold_change_data <- cached_enrichment$fold_change_data
      # Handle original fold change data if it exists in cache
      if(!is.null(cached_enrichment$original_fold_change_data)) {
        original_fold_change_data <- cached_enrichment$original_fold_change_data
      } else {
        # For backward compatibility with older cached data
        original_fold_change_data <- fold_change_data
      }
      # Restore cached pathview gene data
      if(!is.null(cached_enrichment$pathview_gene_data)) {
        proteomics_values$pathview_gene_data <- cached_enrichment$pathview_gene_data
        cat("Restored", length(cached_enrichment$pathview_gene_data), "cached Entrez genes for pathview\n")
      }
      showNotification("Using cached enrichment results (no recalculation needed)", type = "message", duration = 3)
    } else {
      cat("Generating new enrichment results for", input$proteomics_tool, "and caching them\n")
      showNotification("Computing enrichment analysis...", type = "message", duration = 3)
      
      # Check for metabolomics data incompatibility with gene-centric tools
      if (!is.null(input$is_metabolomics_data) && input$is_metabolomics_data) {
        gene_centric_tools <- c("clusterprofiler", "reactomepa", "topgo")
        if (input$proteomics_tool %in% gene_centric_tools) {
          showNotification(
            HTML("Error: Metabolomics data cannot be analyzed with gene-centric enrichment tools.<br/>
                 <strong>Selected tool:</strong> ", input$proteomics_tool, "<br/>
                 <strong>Compatible tools for metabolomics data:</strong> g:Profiler, Enrichr<br/>
                 Please select a compatible enrichment tool for metabolite analysis."),
            type = "error",
            duration = 15
          )
          return(NULL)
        }
      }
      
      # Run the actual enrichment analysis
      fold_change_data <- NULL  # Initialize fold_change_data
      # If MOFA is selected and we have previously computed the MOFA fold-change-like weights,
      # use them as the GSEA ranking vector (analogous to log2FC)
      if (identical(input$proteomics_source, "mofa_factor") && !is.null(proteomics_values$manual_fold_changes) && length(proteomics_values$manual_fold_changes) > 0) {
        fold_change_data <- proteomics_values$manual_fold_changes
        original_fold_change_data <- fold_change_data
      }
      
      if (input$proteomics_tool == "gprofiler") {
        # Show global g:Profiler banner across all proteomics tabs
        session$sendCustomMessage(type = "showGProfilerProgress", message = list())
        tryCatch({
          # Prepare custom background if custom domain is selected
          custom_bg <- NULL
          if (input$proteomics_gprofiler_domain %in% c("custom", "custom_annotated")) {
            if (input$proteomics_gprofiler_bg_source == "full_dataset") {
              # Use full uploaded feature universe as background
              if (input$proteomics_source == "manual" &&
                  !is.null(proteomics_values$manual_full_gene_universe) &&
                  length(proteomics_values$manual_full_gene_universe) > 0) {
                custom_bg <- proteomics_values$manual_full_gene_universe
                showNotification(paste("Using", length(custom_bg), "features from uploaded file as custom background (full universe)"),
                                 type = "message", duration = 3)
              } else if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) > 0) {
                custom_bg <- values$cleaned_molecules
                showNotification(paste("Using", length(custom_bg), "features from uploaded dataset as custom background"),
                                 type = "message", duration = 3)
              } else {
                showNotification("No uploaded dataset available for custom background. Please upload data first.",
                                 type = "error", duration = 5)
                return(NULL)
              }
            } else if (input$proteomics_gprofiler_bg_source == "manual_input") {
              # Use manually pasted background
              if (!is.null(input$proteomics_gprofiler_custom_bg) && nchar(trimws(input$proteomics_gprofiler_custom_bg)) > 0) {
                bg_text <- trimws(input$proteomics_gprofiler_custom_bg)
                custom_bg <- unique(trimws(unlist(strsplit(bg_text, "\n"))))
                custom_bg <- custom_bg[custom_bg != ""]  # Remove empty lines
                if (length(custom_bg) > 0) {
                  showNotification(paste("Using", length(custom_bg), "manually provided genes as custom background"),
                                   type = "message", duration = 3)
                } else {
                  showNotification("Custom background list is empty. Please provide gene identifiers.",
                                   type = "error", duration = 5)
                  return(NULL)
                }
              } else {
                showNotification("Please provide a custom background gene list when using manual input.",
                                 type = "error", duration = 5)
                return(NULL)
              }
            }
          }
          
          # Run g:Profiler with or without custom background
          if (!is.null(custom_bg)) {
            enrichment_results <- gprofiler2::gost(query = gene_list,
                                                   organism = input$proteomics_organism,
                                                   correction_method = input$proteomics_gprofiler_correction,
                                                   significant = input$proteomics_gprofiler_sig,
                                                   sources = input$proteomics_gprofiler_sources,
                                                   domain_scope = input$proteomics_gprofiler_domain,
                                                   custom_bg = custom_bg)
          } else {
            enrichment_results <- gprofiler2::gost(query = gene_list,
                                                   organism = input$proteomics_organism,
                                                   correction_method = input$proteomics_gprofiler_correction,
                                                   significant = input$proteomics_gprofiler_sig,
                                                   sources = input$proteomics_gprofiler_sources,
                                                   domain_scope = input$proteomics_gprofiler_domain)
          }
        }, error = function(e) {
          # Hide banner on error
          session$sendCustomMessage(type = "hideGProfilerProgress", message = list())

          # Check if it's a network connectivity error
          if (grepl("Could not resolve host|Couldn't resolve host|timeout|connection", e$message, ignore.case = TRUE)) {
            showNotification(
              HTML("g:Profiler Network Error: Unable to connect to g:Profiler service.<br/>
                 Please check your internet connection and try again.<br/>
                 Alternative: Use ClusterProfiler for offline analysis."),
              type = "error",
              duration = 10
            )
          } else {
            showNotification(paste("g:Profiler error:", e$message), type = "error", duration = 8)
          }
          enrichment_results <- NULL
        })
        # Hide banner after completion
        session$sendCustomMessage(type = "hideGProfilerProgress", message = list())
      }
      else if (input$proteomics_tool == "clusterprofiler") {
        # Show progress bar specifically for ClusterProfiler
        session$sendCustomMessage(type = "showClusterProfilerProgress", message = list())
        
        tryCatch({
          # Enforce required columns for ClusterProfiler GSEA when using Manual CSV/TSV input
          is_cp_gsea <- !is.null(input$proteomics_cp_analysis) &&
            input$proteomics_cp_analysis %in% c(
              "gsea_go", "gsea_kegg", "gsea_kegg_module", "gsea_reactome",
              "gsea_pathwaycommons", "gsea_wikipathways", "gsea_msigdb"
            )
          is_manual_csv_source <- input$proteomics_source == "manual" &&
            !is.null(input$proteomics_manual_input_type) && input$proteomics_manual_input_type == "file" &&
            !is.null(input$proteomics_manual_filetype) && input$proteomics_manual_filetype %in% c("csv", "tab")

          if (is_cp_gsea && is_manual_csv_source) {
            if (is.null(proteomics_values$manual_pvalues) || is.null(proteomics_values$manual_fold_changes)) {
              showNotification(
                "ClusterProfiler GSEA requires selecting both a P-value column and a Fold Change column for Manual CSV/TSV input.",
                type = "error", duration = 8
              )
              session$sendCustomMessage(type = "hideClusterProfilerProgress", message = list())
              return(NULL)
            }
          }

          # Get pre-loaded annotation database or load on-demand
          annotation_db <- get_annotation_database(input$proteomics_organism)
          
          # First convert IDs if needed
          if(input$proteomics_id_type != "ENTREZID") {
            showNotification("Converting IDs for ClusterProfiler...", type = "message")
            
            # Validate the actual ID type in gene_list to ensure it matches user selection
            gene_list_validation <- validate_ids(gene_list)
            
            # Determine the correct fromType: use detected type if user selection fails
            from_type <- input$proteomics_id_type
            if (!gene_list_validation$valid || gene_list_validation$confidence %in% c("low", "medium")) {
              # Auto-detect the correct ID type from the gene_list
              detected_type <- switch(gene_list_validation$type,
                                      "UniProt" = "UNIPROT",
                                      "Entrez" = "ENTREZID", 
                                      "Ensembl" = "ENSEMBL",
                                      "Symbol" = "SYMBOL",
                                      input$proteomics_id_type) # fallback to user selection
              
              if (detected_type != input$proteomics_id_type) {
                showNotification(paste("Auto-corrected ID type from", input$proteomics_id_type, "to", detected_type, 
                                     "based on gene list content"), type = "warning", duration = 5)
                from_type <- detected_type
              }
            }
            
            # Use cached bitr to convert IDs - this function handles ID mapping with caching
            gene_ids <- cached_bitr(
              geneID = gene_list,
              fromType = from_type,
              toType = "ENTREZID",
              OrgDb = annotation_db,
              trigger_update = trigger_id_cache_update
            )
            
            # Rename the column to match the user's selected ID type for consistency
            if (!is.null(gene_ids) && nrow(gene_ids) > 0 && from_type != input$proteomics_id_type) {
              colnames(gene_ids)[1] <- input$proteomics_id_type
            }
            
            # Check if we have any successful conversions
            if(nrow(gene_ids) == 0) {
              showNotification("Failed to convert any IDs. Please check your ID type selection.", type = "error")
              session$sendCustomMessage(type = "hideClusterProfilerProgress", message = list())
              return(NULL)
            }
            
            # Show how many IDs were successfully mapped
            showNotification(paste("Successfully mapped", nrow(gene_ids), "out of", length(gene_list), "IDs"), type = "message")
            
            # Use the converted IDs for enrichment
            mapped_genes <- gene_ids$ENTREZID
          } else {
            mapped_genes <- gene_list
          }
          
          # Prepare fold change data for tree plots if available and requested
          fold_change_data <- NULL
          original_fold_change_data <- NULL
          
          if(input$proteomics_source == "pairwise" && !is.null(values$stat_results)) {
            # Get comparison stats with flexible group selection
            comp_stats <- get_comparison_stats(input$proteomics_pairwise_group1, input$proteomics_pairwise_group2)
            
            if(!is.null(comp_stats)) {
              comparison_name <- comp_stats$comparison_name
              fc_column_result <- comp_stats$fc_column_result
              is_fc_reversed <- grepl("^REVERSED:", fc_column_result)
              fc_column <- if(is_fc_reversed) sub("^REVERSED:", "", fc_column_result) else fc_column_result
              is_comparison_reversed <- comp_stats$is_reversed
            } else {
              fc_column <- NULL
              is_fc_reversed <- FALSE
              is_comparison_reversed <- FALSE
            }
            
            if(!is.null(fc_column) && fc_column %in% colnames(values$stat_results)) {
              # Create fold change vector with original molecule names
              fc_values <- values$stat_results[[fc_column]]
              names(fc_values) <- values$cleaned_molecules
              
              # Reverse fold changes if necessary
              if(is_fc_reversed || is_comparison_reversed) {
                fc_values <- -fc_values
              }
              
              # Filter to only include significant molecules and convert to ENTREZ IDs
              if(input$proteomics_id_type != "ENTREZID") {
                # Map fold change data to ENTREZ IDs
                fc_mapped <- fc_values[gene_list]  # Get FC values for our significant genes
                fc_mapped <- fc_mapped[!is.na(fc_mapped)]  # Remove NA values
                
                # Convert names to ENTREZ IDs using the same mapping we did above
                if(exists("gene_ids") && nrow(gene_ids) > 0) {
                  # Create mapping from original to ENTREZ IDs
                  name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                  
                  # Map fold change data
                  entrez_names <- name_to_entrez[names(fc_mapped)]
                  entrez_names <- entrez_names[!is.na(entrez_names)]
                  
                  if(length(entrez_names) > 0) {
                    fold_change_data <- fc_mapped[names(entrez_names)]
                    names(fold_change_data) <- entrez_names
                    fold_change_data <- sort(fold_change_data, decreasing = TRUE)
                    
                    # Store original fold change data for heatplot option
                    original_fold_change_data <- fc_mapped[names(entrez_names)]
                    original_fold_change_data <- sort(original_fold_change_data, decreasing = TRUE)
                  }
                }
              } else {
                # IDs are already ENTREZ, use directly
                fold_change_data <- fc_values[mapped_genes]
                fold_change_data <- fold_change_data[!is.na(fold_change_data)]
                fold_change_data <- sort(fold_change_data, decreasing = TRUE)
                
                # For ENTREZ IDs, original and converted are the same
                original_fold_change_data <- fold_change_data
              }
            }
          }
          
          # Handle fold change data for manual input
          else if(input$proteomics_source == "manual" && !is.null(proteomics_values$manual_fold_changes)) {
            # Create fold change vector with original gene names
            fc_values <- proteomics_values$manual_fold_changes
            names(fc_values) <- gene_list
            
            # Filter to only include valid fold change values
            fc_values <- fc_values[!is.na(fc_values)]
            
            if(length(fc_values) > 0) {
              if(input$proteomics_id_type != "ENTREZID") {
                # Map fold change data to ENTREZ IDs using the same mapping we did above
                if(exists("gene_ids") && nrow(gene_ids) > 0) {
                  # Create mapping from original to ENTREZ IDs
                  name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                  
                  # Map fold change data
                  entrez_names <- name_to_entrez[names(fc_values)]
                  entrez_names <- entrez_names[!is.na(entrez_names)]
                  
                  if(length(entrez_names) > 0) {
                    fold_change_data <- fc_values[names(entrez_names)]
                    names(fold_change_data) <- entrez_names
                    fold_change_data <- sort(fold_change_data, decreasing = TRUE)
                    
                    # Store original fold change data for heatplot option
                    original_fold_change_data <- fc_values[names(entrez_names)]
                    original_fold_change_data <- sort(original_fold_change_data, decreasing = TRUE)
                  }
                }
              } else {
                # IDs are already ENTREZ, use directly
                fold_change_data <- fc_values
                fold_change_data <- sort(fold_change_data, decreasing = TRUE)
                
                # For ENTREZ IDs, original and converted are the same
                original_fold_change_data <- fold_change_data
              }
            }
          }
          
          # Handle fold change data for MOFA input (uses feature names directly, no ID conversion)
          else if(identical(input$proteomics_source, "mofa_factor") && !is.null(proteomics_values$manual_fold_changes) && length(proteomics_values$manual_fold_changes) > 0) {
            # MOFA weights are already named with feature names and ranked
            fold_change_data <- proteomics_values$manual_fold_changes
            original_fold_change_data <- fold_change_data
            showNotification("Using MOFA feature weights as ranking metric for GSEA", type = "message", duration = 3)
          }
          
          # Prepare custom background/universe if selected
          custom_universe <- NULL
          if (input$proteomics_cp_background_type == "custom") {
            if (input$proteomics_cp_bg_source == "full_dataset") {
              # Use full uploaded feature universe as background
              # For manual input with full gene universe, use that; otherwise use cleaned_molecules
              if (input$proteomics_source == "manual" && 
                  !is.null(proteomics_values$manual_full_gene_universe) &&
                  length(proteomics_values$manual_full_gene_universe) > 0) {
                raw_universe <- proteomics_values$manual_full_gene_universe
                showNotification(paste("Using", length(raw_universe), "features from uploaded file as custom universe (full gene universe)"),
                                 type = "message", duration = 3)
              } else if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) > 0) {
                raw_universe <- values$cleaned_molecules
                showNotification(paste("Using", length(raw_universe), "features from uploaded dataset as custom universe"),
                                 type = "message", duration = 3)
              } else {
                showNotification("No uploaded dataset available for custom universe. Please upload data first.",
                                 type = "error", duration = 5)
                return(NULL)
              }
            } else if (input$proteomics_cp_bg_source == "manual_input") {
              # Use manually pasted background
              if (!is.null(input$proteomics_cp_custom_bg) && nchar(trimws(input$proteomics_cp_custom_bg)) > 0) {
                bg_text <- trimws(input$proteomics_cp_custom_bg)
                raw_universe <- unique(trimws(unlist(strsplit(bg_text, "\n"))))
                raw_universe <- raw_universe[raw_universe != ""]  # Remove empty lines
                if (length(raw_universe) > 0) {
                  showNotification(paste("Using", length(raw_universe), "manually provided genes as custom universe"),
                                   type = "message", duration = 3)
                } else {
                  showNotification("Custom universe list is empty. Please provide gene identifiers.",
                                   type = "error", duration = 5)
                  return(NULL)
                }
              } else {
                showNotification("Please provide a custom universe gene list when using manual input.",
                                 type = "error", duration = 5)
                return(NULL)
              }
            }
            
            # Convert custom universe to ENTREZ IDs if needed
            if (!is.null(raw_universe)) {
              if(input$proteomics_id_type != "ENTREZID") {
                # Validate the actual ID type in raw_universe
                universe_validation <- validate_ids(raw_universe)
                
                # Determine the correct fromType for universe
                universe_from_type <- input$proteomics_id_type
                if (!universe_validation$valid || universe_validation$confidence %in% c("low", "medium")) {
                  detected_type <- switch(universe_validation$type,
                                          "UniProt" = "UNIPROT",
                                          "Entrez" = "ENTREZID", 
                                          "Ensembl" = "ENSEMBL",
                                          "Symbol" = "SYMBOL",
                                          input$proteomics_id_type)
                  
                  if (detected_type != input$proteomics_id_type) {
                    showNotification(paste("Auto-corrected universe ID type from", input$proteomics_id_type, "to", detected_type), 
                                   type = "warning", duration = 5)
                    universe_from_type <- detected_type
                  }
                }
                
                # Convert universe IDs to ENTREZ
                showNotification("Converting custom universe IDs to ENTREZ format...", type = "message")
                
                universe_ids <- cached_bitr(
                  geneID = raw_universe,
                  fromType = universe_from_type,
                  toType = "ENTREZID",
                  OrgDb = annotation_db,
                  trigger_update = trigger_id_cache_update
                )
                
                # Rename the column to match the user's selected ID type for consistency
                if (!is.null(universe_ids) && nrow(universe_ids) > 0 && universe_from_type != input$proteomics_id_type) {
                  colnames(universe_ids)[1] <- input$proteomics_id_type
                }
                
                if(!is.null(universe_ids) && nrow(universe_ids) > 0) {
                  custom_universe <- universe_ids$ENTREZID
                  showNotification(paste("Successfully mapped", length(custom_universe), "out of", length(raw_universe), "universe IDs"), type = "message")
                } else {
                  showNotification("Failed to convert any universe IDs. Using default background.", type = "warning")
                  custom_universe <- NULL
                }
              } else {
                # IDs are already ENTREZ, use directly
                custom_universe <- raw_universe
              }
            }
          }
          
          # Notify about background/universe usage
          if (!is.null(custom_universe)) {
            showNotification(paste("Using custom background universe with", length(custom_universe), "genes for ClusterProfiler analysis"),
                             type = "message", duration = 3)
          } else {
            showNotification("Using default annotation database background for ClusterProfiler analysis",
                             type = "message", duration = 2)
          }
          
          # Run the enrichment analysis based on the selected analysis type
          if(input$proteomics_cp_analysis == "go") {
            if (is.null(annotation_db)) {
              showNotification("GO enrichment requires an organism annotation database (e.g. org.Hs.eg.db). Please install the appropriate OrgDb package or select a supported organism.", type = "error")
              enrichment_results <- NULL
            } else {
              enrichment_results <- clusterProfiler::enrichGO(
                gene = mapped_genes,
                universe = custom_universe,
                OrgDb = annotation_db,
                keyType = "ENTREZID",
                ont = input$proteomics_cp_go_ont,
                pvalueCutoff = input$proteomics_cp_pval,
                qvalueCutoff = input$proteomics_cp_qval,
                pAdjustMethod = input$proteomics_cp_pmethod
              )
            }
          }
          else if(input$proteomics_cp_analysis == "kegg") {
            kegg_org <- switch(input$proteomics_organism,
                               hsapiens = "hsa",
                               mmusculus = "mmu",
                               rnorvegicus = "rno",
                               dmelanogaster = "dme",
                               drerio = "dre",
                               athaliana = "ath",
                               scerevisiae = "sce",
                               ecoli = "eco")
            
            enrichment_results <- clusterProfiler::enrichKEGG(
              gene = mapped_genes,
              universe = custom_universe,
              organism = kegg_org,
              keyType = "kegg",
              pvalueCutoff = input$proteomics_cp_pval,
              qvalueCutoff = input$proteomics_cp_qval,
              pAdjustMethod = input$proteomics_cp_pmethod
            )
          }
          else if(input$proteomics_cp_analysis == "kegg_module") {
            # KEGG Module analysis using enrichMKEGG
            kegg_org <- switch(input$proteomics_organism,
                               hsapiens = "hsa",
                               mmusculus = "mmu",
                               rnorvegicus = "rno",
                               dmelanogaster = "dme",
                               drerio = "dre",
                               athaliana = "ath",
                               scerevisiae = "sce",
                               ecoli = "eco")
            
            showNotification("Running KEGG module enrichment analysis...", type = "message")
            
            enrichment_results <- clusterProfiler::enrichMKEGG(
              gene = mapped_genes,
              universe = custom_universe,
              organism = kegg_org,
              keyType = "kegg",
              pvalueCutoff = input$proteomics_cp_pval,
              qvalueCutoff = input$proteomics_cp_qval,
              pAdjustMethod = input$proteomics_cp_pmethod,
              minGSSize = input$proteomics_cp_minGSSize,
              maxGSSize = input$proteomics_cp_maxGSSize
            )
          }
          else if(input$proteomics_cp_analysis == "msigdb") {
            # MSigDB analysis using msigdbr
            if (requireNamespace("msigdbr", quietly = TRUE)) {
              organism_code <- switch(input$proteomics_organism,
                                      hsapiens = "Homo sapiens",
                                      mmusculus = "Mus musculus",
                                      rnorvegicus = "Rattus norvegicus",
                                      dmelanogaster = "Drosophila melanogaster",
                                      drerio = "Danio rerio",
                                      athaliana = "Arabidopsis thaliana",
                                      scerevisiae = "Saccharomyces cerevisiae",
                                      ecoli = "Escherichia coli"
              )
              
              # Check if organism is supported by MSigDB
              available_species <- msigdbr::msigdbr_species()
              if (!organism_code %in% available_species$species_name) {
                showNotification(paste("MSigDB analysis is not available for", organism_code, ". Available species are:", paste(available_species$species_name, collapse = ", ")), type = "warning")
                enrichment_results <- NULL
              } else {
                # Get MSigDB gene sets
                if (!is.null(input$proteomics_cp_msigdb_subcategory) && input$proteomics_cp_msigdb_subcategory != "") {
                  # Filter by subcategory
                  msigdb_sets <- msigdbr::msigdbr(
                    species = organism_code,
                    category = input$proteomics_cp_msigdb_category,
                    subcategory = input$proteomics_cp_msigdb_subcategory
                  )
                  showNotification(paste("Using MSigDB category", input$proteomics_cp_msigdb_category, "subcategory", input$proteomics_cp_msigdb_subcategory), type = "message")
                } else {
                  # Use all gene sets in the category
                  msigdb_sets <- msigdbr::msigdbr(
                    species = organism_code,
                    category = input$proteomics_cp_msigdb_category
                  )
                  showNotification(paste("Using all MSigDB gene sets in category", input$proteomics_cp_msigdb_category), type = "message")
                }
                
                # Convert to the format expected by enricher
                if (nrow(msigdb_sets) > 0) {
                  # Create TERM2GENE and TERM2NAME mappings
                  term2gene <- msigdb_sets[, c("gs_name", "entrez_gene")]
                  term2name <- unique(msigdb_sets[, c("gs_name", "gs_description")])
                  
                  showNotification(paste("Running MSigDB enrichment with", length(unique(msigdb_sets$gs_name)), "gene sets..."), type = "message")
                  
                  enrichment_results <- clusterProfiler::enricher(
                    gene = mapped_genes,
                    universe = custom_universe,
                    TERM2GENE = term2gene,
                    TERM2NAME = term2name,
                    pvalueCutoff = input$proteomics_cp_pval,
                    qvalueCutoff = input$proteomics_cp_qval,
                    pAdjustMethod = input$proteomics_cp_pmethod
                  )
                } else {
                  showNotification("No MSigDB gene sets found for the selected category/subcategory and organism.", type = "warning")
                  enrichment_results <- NULL
                }
              }
            } else {
              showNotification("msigdbr package not available. Please install it for MSigDB analysis.", type = "error")
              enrichment_results <- NULL
            }
          }
          else if(input$proteomics_cp_analysis == "pathwaycommons") {
            # Pathway Commons analysis using enrichPC
            if (requireNamespace("clusterProfiler", quietly = TRUE)) {
              showNotification("Running Pathway Commons enrichment analysis...", type = "message")
              
              # Check if clusterProfiler has enrichPC function
              if (exists("enrichPC", where = asNamespace("clusterProfiler"))) {
                # Convert gene IDs to appropriate format for enrichPC
                # enrichPC accepts HGNC symbols or UniProt IDs
                pc_genes <- NULL
                conversion_type <- NULL
                
                if(input$proteomics_id_type == "SYMBOL") {
                  # Already in HGNC symbols, use directly
                  pc_genes <- mapped_genes
                  conversion_type <- "SYMBOL"
                  showNotification(paste("Using", length(pc_genes), "HGNC symbols for Pathway Commons analysis"), type = "message")
                } else if(input$proteomics_id_type == "UNIPROT") {
                  # Already in UniProt IDs, use directly - no conversion needed
                  pc_genes <- mapped_genes
                  conversion_type <- "UNIPROT"
                  showNotification(paste("Using", length(pc_genes), "UniProt IDs for Pathway Commons analysis"), type = "message")
                } else {
                  # For other ID types, try to convert to HGNC symbols first, then UniProt if that fails
                  if(exists("gene_ids") && nrow(gene_ids) > 0) {
                    # First attempt: Convert to SYMBOL
                    if(input$proteomics_id_type == "ENTREZID") {
                      # Map ENTREZ to SYMBOL
                      if("SYMBOL" %in% colnames(gene_ids)) {
                        entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                        pc_genes <- entrez_to_symbol[mapped_genes]
                        pc_genes <- pc_genes[!is.na(pc_genes)]
                        if(length(pc_genes) > 0) {
                          conversion_type <- "SYMBOL"
                          showNotification(paste("Converted", length(pc_genes), "genes to HGNC symbols for Pathway Commons analysis"), type = "message")
                        }
                      }
                    } else {
                      # First convert to ENTREZ, then to SYMBOL
                      if(input$proteomics_id_type %in% colnames(gene_ids) && "SYMBOL" %in% colnames(gene_ids)) {
                        input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_genes <- input_to_entrez[gene_list]
                        entrez_genes <- entrez_genes[!is.na(entrez_genes)]
                        
                        if(length(entrez_genes) > 0) {
                          entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                          pc_genes <- entrez_to_symbol[entrez_genes]
                          pc_genes <- pc_genes[!is.na(pc_genes)]
                          if(length(pc_genes) > 0) {
                            conversion_type <- "SYMBOL"
                            showNotification(paste("Converted", length(pc_genes), "genes to HGNC symbols for Pathway Commons analysis"), type = "message")
                          }
                        }
                      }
                    }
                    
                    # Second attempt: If SYMBOL conversion failed or yielded too few genes, try UNIPROT
                    if((is.null(pc_genes) || length(pc_genes) < 10) && "UNIPROT" %in% colnames(gene_ids)) {
                      showNotification("SYMBOL conversion yielded insufficient genes. Attempting UniProt ID conversion...", type = "message")
                      
                      if(input$proteomics_id_type == "ENTREZID") {
                        # Map ENTREZ to UNIPROT
                        entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                        pc_genes <- entrez_to_uniprot[mapped_genes]
                        pc_genes <- pc_genes[!is.na(pc_genes)]
                        if(length(pc_genes) > 0) {
                          conversion_type <- "UNIPROT"
                          showNotification(paste("Converted", length(pc_genes), "genes to UniProt IDs for Pathway Commons analysis"), type = "message")
                        }
                      } else {
                        # First convert to ENTREZ, then to UNIPROT
                        if(input$proteomics_id_type %in% colnames(gene_ids)) {
                          input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                          entrez_genes <- input_to_entrez[gene_list]
                          entrez_genes <- entrez_genes[!is.na(entrez_genes)]
                          
                          if(length(entrez_genes) > 0) {
                            entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                            pc_genes <- entrez_to_uniprot[entrez_genes]
                            pc_genes <- pc_genes[!is.na(pc_genes)]
                            if(length(pc_genes) > 0) {
                              conversion_type <- "UNIPROT"
                              showNotification(paste("Converted", length(pc_genes), "genes to UniProt IDs for Pathway Commons analysis"), type = "message")
                            }
                          }
                        }
                      }
                    }
                  }
                  
                  if(is.null(pc_genes) || length(pc_genes) == 0) {
                    showNotification("Could not convert gene IDs to HGNC symbols or UniProt IDs for Pathway Commons analysis. Please ensure your gene annotation data includes SYMBOL or UNIPROT columns.", type = "error")
                    enrichment_results <- NULL
                  }
                }
                
                # Convert custom universe to the same format as pc_genes (SYMBOL or UNIPROT)
                pc_universe <- NULL
                if(!is.null(custom_universe) && !is.null(conversion_type)) {
                  # If input type matches conversion type, use custom universe directly
                  if((input$proteomics_id_type == "SYMBOL" && conversion_type == "SYMBOL") ||
                     (input$proteomics_id_type == "UNIPROT" && conversion_type == "UNIPROT")) {
                    pc_universe <- custom_universe
                    showNotification(paste("Using custom universe directly with", length(pc_universe), conversion_type, "IDs"), type = "message")
                  } else if(exists("gene_ids") && nrow(gene_ids) > 0) {
                    # Only convert if input type differs from conversion type
                    if(conversion_type == "SYMBOL" && "SYMBOL" %in% colnames(gene_ids)) {
                      if(input$proteomics_id_type == "ENTREZID") {
                        entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                        pc_universe <- entrez_to_symbol[custom_universe]
                        pc_universe <- pc_universe[!is.na(pc_universe)]
                        showNotification(paste("Converted custom universe to", length(pc_universe), "SYMBOL IDs"), type = "message")
                      } else {
                        # Convert universe through ENTREZ to SYMBOL
                        input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_universe <- input_to_entrez[custom_universe]
                        entrez_universe <- entrez_universe[!is.na(entrez_universe)]
                        
                        if(length(entrez_universe) > 0) {
                          entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                          pc_universe <- entrez_to_symbol[entrez_universe]
                          pc_universe <- pc_universe[!is.na(pc_universe)]
                          showNotification(paste("Converted custom universe to", length(pc_universe), "SYMBOL IDs"), type = "message")
                        }
                      }
                    } else if(conversion_type == "UNIPROT" && "UNIPROT" %in% colnames(gene_ids)) {
                      if(input$proteomics_id_type == "ENTREZID") {
                        entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                        pc_universe <- entrez_to_uniprot[custom_universe]
                        pc_universe <- pc_universe[!is.na(pc_universe)]
                        showNotification(paste("Converted custom universe to", length(pc_universe), "UNIPROT IDs"), type = "message")
                      } else {
                        # Convert universe through ENTREZ to UNIPROT
                        input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_universe <- input_to_entrez[custom_universe]
                        entrez_universe <- entrez_universe[!is.na(entrez_universe)]
                        
                        if(length(entrez_universe) > 0) {
                          entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                          pc_universe <- entrez_to_uniprot[entrez_universe]
                          pc_universe <- pc_universe[!is.na(pc_universe)]
                          showNotification(paste("Converted custom universe to", length(pc_universe), "UNIPROT IDs"), type = "message")
                        }
                      }
                    }
                  }
                }
                
                # Run enrichPC analysis if we have genes
                if(!is.null(pc_genes) && length(pc_genes) > 0) {
                  enrichment_results <- clusterProfiler::enrichPC(
                    gene = pc_genes,
                    universe = pc_universe,
                    pvalueCutoff = input$proteomics_cp_pval,
                    qvalueCutoff = input$proteomics_cp_qval,
                    pAdjustMethod = input$proteomics_cp_pmethod,
                    minGSSize = input$proteomics_cp_minGSSize,
                    maxGSSize = input$proteomics_cp_maxGSSize
                  )
                } else {
                  showNotification("No valid genes found for Pathway Commons analysis", type = "error")
                  enrichment_results <- NULL
                }
              } else {
                showNotification("enrichPC function not available in clusterProfiler. Please ensure you have the latest version.", type = "error")
                enrichment_results <- NULL
              }
            } else {
              showNotification("clusterProfiler package not available for Pathway Commons analysis.", type = "error")
              enrichment_results <- NULL
            }
          }
          else if(input$proteomics_cp_analysis == "do") {
            # Disease Ontology analysis using enrichDO
            if (requireNamespace("DOSE", quietly = TRUE)) {
              showNotification("Running Disease Ontology enrichment analysis...", type = "message")
              
              enrichment_results <- DOSE::enrichDO(
                gene = mapped_genes,
                universe = custom_universe,
                pvalueCutoff = input$proteomics_cp_pval,
                qvalueCutoff = input$proteomics_cp_qval,
                pAdjustMethod = input$proteomics_cp_pmethod,
                minGSSize = input$proteomics_cp_minGSSize,
                maxGSSize = input$proteomics_cp_maxGSSize
              )
            } else {
              showNotification("DOSE package not available for Disease Ontology analysis. Please install it.", type = "error")
              enrichment_results <- NULL
            }
          }
          else if(input$proteomics_cp_analysis == "reactome") {
            # Reactome analysis using enrichPathway
            if (requireNamespace("ReactomePA", quietly = TRUE)) {
              showNotification("Running Reactome pathway enrichment analysis...", type = "message")
              
              # ReactomePA uses specific organism names
              reactome_organism <- switch(input$proteomics_organism,
                                          hsapiens = "human",
                                          mmusculus = "mouse",
                                          rnorvegicus = "rat",
                                          dmelanogaster = "fly",
                                          drerio = "zebrafish",
                                          athaliana = "arabidopsis",
                                          scerevisiae = "yeast",
                                          ecoli = "coli"
              )
              
              # Check if organism is supported by ReactomePA
              if (is.null(reactome_organism)) {
                showNotification(paste("ReactomePA does not support", input$proteomics_organism, "organism"), type = "error")
                enrichment_results <- NULL
              } else {
                tryCatch({
                  enrichment_results <- ReactomePA::enrichPathway(
                    gene = mapped_genes,
                    universe = custom_universe,
                    organism = reactome_organism,
                    pvalueCutoff = input$proteomics_cp_pval,
                    qvalueCutoff = input$proteomics_cp_qval,
                    pAdjustMethod = input$proteomics_cp_pmethod,
                    minGSSize = input$proteomics_cp_minGSSize,
                    maxGSSize = input$proteomics_cp_maxGSSize,
                    readable = FALSE
                  )
                }, error = function(e) {
                  showNotification(paste("ReactomePA enrichPathway failed:", e$message), type = "error")
                  enrichment_results <<- NULL
                })
              }
            } else {
              showNotification("ReactomePA package not available for Reactome analysis. Please install it.", type = "error")
              enrichment_results <- NULL
            }
          }
          else if(input$proteomics_cp_analysis == "wikipathways") {
            # WikiPathways analysis using enrichWP
            if (requireNamespace("clusterProfiler", quietly = TRUE)) {
              showNotification("Running WikiPathways enrichment analysis...", type = "message")
              
              # Check if clusterProfiler has enrichWP function
              if (exists("enrichWP", where = asNamespace("clusterProfiler"))) {
                # Convert organism name for WikiPathways
                wp_organism <- switch(input$proteomics_organism,
                                      hsapiens = "Homo sapiens",
                                      mmusculus = "Mus musculus",
                                      rnorvegicus = "Rattus norvegicus",
                                      dmelanogaster = "Drosophila melanogaster",
                                      drerio = "Danio rerio",
                                      scerevisiae = "Saccharomyces cerevisiae",
                                      athaliana = "Arabidopsis thaliana",
                                      ecoli = "Escherichia coli"
                )
                
                enrichment_results <- clusterProfiler::enrichWP(
                  gene = mapped_genes,
                  universe = custom_universe,
                  organism = wp_organism,
                  pvalueCutoff = input$proteomics_cp_pval,
                  qvalueCutoff = input$proteomics_cp_qval,
                  pAdjustMethod = input$proteomics_cp_pmethod,
                  minGSSize = input$proteomics_cp_minGSSize,
                  maxGSSize = input$proteomics_cp_maxGSSize
                )
              } else {
                showNotification("enrichWP function not available in clusterProfiler. Please ensure you have the latest version.", type = "error")
                enrichment_results <- NULL
              }
            } else {
              showNotification("clusterProfiler package not available for WikiPathways analysis.", type = "error")
              enrichment_results <- NULL
            }
          }
          # GSEA analyses - require ranked gene lists
          else if(input$proteomics_cp_analysis %in% c("gsea_go", "gsea_kegg", "gsea_kegg_module", "gsea_reactome", "gsea_pathwaycommons", "gsea_wikipathways", "gsea_msigdb")) {
            # Check if we have fold change data for ranking - more comprehensive check
            fold_change_available <- FALSE

            # Check if fold_change_data variable has data
            if(!is.null(fold_change_data) && length(fold_change_data) > 0) {
              fold_change_available <- TRUE
            }

            # For pairwise source, check if fold change data can be retrieved from stat results
            if(!fold_change_available && input$proteomics_source == "pairwise" && !is.null(values$stat_results)) {
              comparison_name <- paste(input$proteomics_pairwise_group1, "vs", input$proteomics_pairwise_group2)
              fc_col <- get_foldchange_column(comparison_name)
              if(!is.null(fc_col) && fc_col %in% colnames(values$stat_results)) {
                fold_change_available <- TRUE
              }
            }

            # For manual source, check if manual fold changes are available
            if(!fold_change_available && input$proteomics_source == "manual" &&
               !is.null(proteomics_values$manual_fold_changes) && length(proteomics_values$manual_fold_changes) > 0) {
              fold_change_available <- TRUE
            }

            # For MOFA source, check if manual fold changes (MOFA weights) are available
            if(!fold_change_available && identical(input$proteomics_source, "mofa_factor") &&
               !is.null(proteomics_values$manual_fold_changes) && length(proteomics_values$manual_fold_changes) > 0) {
              fold_change_available <- TRUE
            }

            # Show error only if no fold change data is available from any source
            if(!fold_change_available) {
              # Provide a helpful message that includes MOFA as a valid source when rankings are present
            if (identical(input$proteomics_source, "mofa_factor")) {
              showNotification("GSEA analysis requires a ranked gene list. For MOFA select a view and factor and ensure feature names can be mapped to dataset IDs so MOFA weights are available for ranking.", type = "error")
            } else {
              showNotification("GSEA analysis requires fold change data. Please use pairwise comparison with available fold change values, manual input with p-values and fold changes, or MOFA Factor with mapped feature weights.", type = "error")
            }
            enrichment_results <- NULL
            } else {
              # Create ranked gene list based on selected metric
              if(input$proteomics_gsea_ranking_metric == "log2fc") {
                # Use log2 fold change directly
                if (input$proteomics_source == "pairwise" && !is.null(values$stat_results)) {
                  comparison_name <- paste(input$proteomics_pairwise_group1, "vs", input$proteomics_pairwise_group2)
                  fc_col <- get_foldchange_column(comparison_name)
                  if (!is.null(fc_col) && fc_col %in% colnames(values$stat_results)) {
                    # Use designated accession IDs if available to name the fc vector so GSEA sees proper IDs
                    id_names <- if (!is.null(values$accession_ids) && length(values$accession_ids) == length(values$cleaned_molecules)) {
                      values$accession_ids
                    } else {
                      values$cleaned_molecules
                    }
                    fc_values <- values$stat_results[[fc_col]]
                    # Assign IDs and remove any NA/empty names
                    names(fc_values) <- id_names
                    valid_idx <- which(!is.na(names(fc_values)) & nzchar(names(fc_values)))
                    if (length(valid_idx) > 0) {
                      ranked_genes <- fc_values[valid_idx]
                      ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                      # Store fold_change_data for caching/plotting
                      fold_change_data <- ranked_genes
                    } else {
                      ranked_genes <- fold_change_data
                    }
                  } else {
                    ranked_genes <- fold_change_data
                  }
                } else {
                  ranked_genes <- fold_change_data
                }
              } else if(input$proteomics_gsea_ranking_metric == "signed_pval") {
                # Create signed p-value metric: -log10(p) * sign(fc)
                # This requires access to p-values from the statistical results
                
                if(input$proteomics_source == "pairwise" && !is.null(values$stat_results)) {
                  showNotification("Creating ranked list using signed p-values...", type = "message")
                  # Extract p-values and fold changes for ranking
                  comparison_name <- paste(input$proteomics_pairwise_group1, "vs", input$proteomics_pairwise_group2)
                  p_value_col <- get_appropriate_pvalue_column(comparison_name)
                  fc_col <- get_foldchange_column(comparison_name)
                  
                  if(!is.null(p_value_col) && p_value_col %in% colnames(values$stat_results) &&
                     !is.null(fc_col) && fc_col %in% colnames(values$stat_results)) {
                    # Get p-values and fold changes
                    p_values <- values$stat_results[[p_value_col]]
                    fc_values <- values$stat_results[[fc_col]]

                    # Create signed p-value metric
                    signed_pvals <- -log10(p_values + 1e-300) * sign(fc_values)  # Add small value to avoid log(0)

                    # Name the metric using designated IDs (accession IDs if available) so mapping is consistent
                    id_names <- if (!is.null(values$accession_ids) && length(values$accession_ids) == length(values$cleaned_molecules)) {
                      values$accession_ids
                    } else {
                      values$cleaned_molecules
                    }
                    names(signed_pvals) <- id_names
                    
                    # Map to ENTREZ IDs if needed
                    if(input$proteomics_id_type != "ENTREZID") {
                      if(exists("gene_ids") && nrow(gene_ids) > 0) {
                        name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_names <- name_to_entrez[names(signed_pvals)]
                        entrez_names <- entrez_names[!is.na(entrez_names)]
                        
                        if(length(entrez_names) > 0) {
                          ranked_genes <- signed_pvals[names(entrez_names)]
                          names(ranked_genes) <- entrez_names
                          ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                        } else {
                          showNotification("Could not map gene IDs for signed p-value ranking", type = "error")
                          enrichment_results <- NULL
                        }
                      }
                    } else {
                      # IDs are already ENTREZ, use directly
                      ranked_genes <- signed_pvals
                      ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                    }
                  } else {
                    showNotification("Could not find p-value or fold change columns for signed p-value ranking", type = "error")
                    enrichment_results <- NULL
                  }
                }
                else if(input$proteomics_source == "manual" && !is.null(proteomics_values$manual_pvalues) && !is.null(proteomics_values$manual_fold_changes)) {
                  showNotification("Creating ranked list using manual p-values and fold changes...", type = "message")
                  
                  # Get p-values and fold changes from manual input
                  p_values <- proteomics_values$manual_pvalues
                  fc_values <- proteomics_values$manual_fold_changes
                  
                  # Create signed p-value metric
                  signed_pvals <- -log10(p_values + 1e-300) * sign(fc_values)  # Add small value to avoid log(0)
                  names(signed_pvals) <- gene_list
                  
                  # Map to ENTREZ IDs if needed
                  if(input$proteomics_id_type != "ENTREZID") {
                    if(exists("gene_ids") && nrow(gene_ids) > 0) {
                      name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                      entrez_names <- name_to_entrez[names(signed_pvals)]
                      entrez_names <- entrez_names[!is.na(entrez_names)]
                      
                      if(length(entrez_names) > 0) {
                        ranked_genes <- signed_pvals[names(entrez_names)]
                        names(ranked_genes) <- entrez_names
                        ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                      } else {
                        showNotification("Could not map gene IDs for signed p-value ranking", type = "error")
                        enrichment_results <- NULL
                      }
                    }
                  } else {
                    # IDs are already ENTREZ, use directly
                    ranked_genes <- signed_pvals
                    ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                  }
                } else {
                  showNotification("Signed p-value ranking requires both p-values and fold changes", type = "error")
                  enrichment_results <- NULL
                }
              } else {
                # For t-statistic, would need additional implementation
                showNotification("t-statistic ranking not yet implemented. Using log2 fold change instead.", type = "warning")
                ranked_genes <- fold_change_data
              }
              
              # Proceed with GSEA if we have a ranked gene list
              if(!is.null(ranked_genes) && length(ranked_genes) > 0) {
                showNotification(paste("Running GSEA with", length(ranked_genes), "ranked genes..."), type = "message")
                
                if(input$proteomics_cp_analysis == "gsea_go") {
                  # Ensure we have an annotation database (OrgDb) available
                  can_run_gsea <- TRUE
                  if (is.null(annotation_db)) {
                    showNotification("GO GSEA requires an organism annotation database (e.g. org.Hs.eg.db). Please install the appropriate OrgDb package or select a supported organism.", type = "error")
                    can_run_gsea <- FALSE
                    enrichment_results <- NULL
                  }

                  # If using MOFA or other non-ENTREZ identifiers, attempt to convert ranked gene names to ENTREZ IDs
                  if (can_run_gsea && !is.null(ranked_genes) && length(ranked_genes) > 0 && !is.null(names(ranked_genes)) && length(names(ranked_genes)) > 0) {
                    # Only attempt conversion if ID type is not ENTREZ
                    if (input$proteomics_id_type != "ENTREZID") {
                      # Validate the actual ID type in the ranked gene names
                      ranked_validation <- validate_ids(names(ranked_genes))
                      
                      # Determine the correct fromType for ranked genes
                      ranked_from_type <- input$proteomics_id_type
                      if (!ranked_validation$valid || ranked_validation$confidence %in% c("low", "medium")) {
                        detected_type <- switch(ranked_validation$type,
                                                "UniProt" = "UNIPROT",
                                                "Entrez" = "ENTREZID", 
                                                "Ensembl" = "ENSEMBL",
                                                "Symbol" = "SYMBOL",
                                                input$proteomics_id_type)
                        
                        if (detected_type != input$proteomics_id_type) {
                          showNotification(paste("Auto-corrected ranked gene ID type from", input$proteomics_id_type, "to", detected_type), 
                                         type = "warning", duration = 5)
                          ranked_from_type <- detected_type
                        }
                      }
                      
                      gene_ids <- cached_bitr(
                        geneID = names(ranked_genes),
                        fromType = ranked_from_type,
                        toType = "ENTREZID",
                        OrgDb = annotation_db,
                        trigger_update = trigger_id_cache_update
                      )
                      
                      # Rename the column to match the user's selected ID type for consistency
                      if (!is.null(gene_ids) && nrow(gene_ids) > 0 && ranked_from_type != input$proteomics_id_type) {
                        colnames(gene_ids)[1] <- input$proteomics_id_type
                      }

                      if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                        showNotification("Could not convert MOFA feature names to ENTREZ IDs for GO GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                        can_run_gsea <- FALSE
                        enrichment_results <- NULL
                      } else {
                        name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[ranked_from_type]])
                        entrez_names <- name_to_entrez[names(ranked_genes)]
                        entrez_names <- entrez_names[!is.na(entrez_names)]

                        if (length(entrez_names) == 0) {
                          showNotification("No ENTREZ IDs found for MOFA feature names. GO GSEA cannot proceed.", type = "error")
                          can_run_gsea <- FALSE
                          enrichment_results <- NULL
                        } else {
                          ranked_genes <- ranked_genes[names(entrez_names)]
                          names(ranked_genes) <- entrez_names
                          ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          
                          # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                          if (any(duplicated(names(ranked_genes)))) {
                            showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                            unique_names <- unique(names(ranked_genes))
                            ranked_genes_list <- lapply(unique_names, function(name) {
                              idx <- which(names(ranked_genes) == name)
                              idx[which.max(abs(ranked_genes[idx]))]
                            })
                            ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                            ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          }
                        }
                      }
                    }
                  }

                  # Run GSEA if the checks passed
                  if (isTRUE(can_run_gsea) && !is.null(ranked_genes) && length(ranked_genes) > 0) {
                    enrichment_results <- clusterProfiler::gseGO(
                      geneList = ranked_genes,
                      OrgDb = annotation_db,
                      keyType = "ENTREZID",
                      ont = input$proteomics_cp_go_ont,
                      minGSSize = input$proteomics_gsea_minGSSize,
                      maxGSSize = input$proteomics_gsea_maxGSSize,
                      pvalueCutoff = input$proteomics_cp_pval,
                      pAdjustMethod = input$proteomics_cp_pmethod,
                      scoreType = input$proteomics_gsea_scoreType,
                      verbose = FALSE,
                      by = "fgsea"
                    )
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_kegg") {
                  kegg_org <- switch(input$proteomics_organism,
                                     hsapiens = "hsa", mmusculus = "mmu", rnorvegicus = "rno",
                                     dmelanogaster = "dme", drerio = "dre", athaliana = "ath",
                                     scerevisiae = "sce", ecoli = "eco")

                  # Attempt to convert ranked gene names to ENTREZ IDs if needed
                  can_run_gsea <- TRUE
                  if (!is.null(ranked_genes) && length(ranked_genes) > 0 && input$proteomics_id_type != "ENTREZID") {
                    if (is.null(annotation_db)) {
                      showNotification("Cannot convert IDs for KEGG GSEA because annotation database is missing. Install OrgDb or set ID type to ENTREZID.", type = "error")
                      can_run_gsea <- FALSE
                      enrichment_results <- NULL
                    } else {
                      gene_ids <- cached_bitr(
                        geneID = names(ranked_genes),
                        fromType = input$proteomics_id_type,
                        toType = "ENTREZID",
                        OrgDb = annotation_db,
                        trigger_update = trigger_id_cache_update
                      )

                      if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                        showNotification("Could not convert MOFA feature names to ENTREZ IDs for KEGG GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                        can_run_gsea <- FALSE
                        enrichment_results <- NULL
                      } else {
                        name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_names <- name_to_entrez[names(ranked_genes)]
                        entrez_names <- entrez_names[!is.na(entrez_names)]

                        if (length(entrez_names) == 0) {
                          showNotification("No ENTREZ IDs found for MOFA feature names. KEGG GSEA cannot proceed.", type = "error")
                          can_run_gsea <- FALSE
                          enrichment_results <- NULL
                        } else {
                          ranked_genes <- ranked_genes[names(entrez_names)]
                          names(ranked_genes) <- entrez_names
                          ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          
                          # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                          if (any(duplicated(names(ranked_genes)))) {
                            showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                            unique_names <- unique(names(ranked_genes))
                            ranked_genes_list <- lapply(unique_names, function(name) {
                              idx <- which(names(ranked_genes) == name)
                              idx[which.max(abs(ranked_genes[idx]))]
                            })
                            ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                            ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          }
                        }
                      }
                    }
                  }

                  if (isTRUE(can_run_gsea)) {
                    enrichment_results <- clusterProfiler::gseKEGG(
                      geneList = ranked_genes,
                      organism = kegg_org,
                      keyType = "kegg",
                      minGSSize = input$proteomics_gsea_minGSSize,
                      maxGSSize = input$proteomics_gsea_maxGSSize,
                      pvalueCutoff = input$proteomics_cp_pval,
                      pAdjustMethod = input$proteomics_cp_pmethod,
                      scoreType = input$proteomics_gsea_scoreType,
                      verbose = FALSE,
                      by = "fgsea"
                    )
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_kegg_module") {
                  # KEGG Module GSEA analysis using gseMKEGG
                  kegg_org <- switch(input$proteomics_organism,
                                     hsapiens = "hsa", mmusculus = "mmu", rnorvegicus = "rno",
                                     dmelanogaster = "dme", drerio = "dre", athaliana = "ath",
                                     scerevisiae = "sce", ecoli = "eco")
                  
                  showNotification("Running KEGG module GSEA analysis...", type = "message")

                  # Attempt to convert ranked gene names to ENTREZ IDs if needed
                  can_run_gsea <- TRUE
                  if (!is.null(ranked_genes) && length(ranked_genes) > 0 && input$proteomics_id_type != "ENTREZID") {
                    if (is.null(annotation_db)) {
                      showNotification("Cannot convert IDs for KEGG module GSEA because annotation database is missing. Install OrgDb or set ID type to ENTREZID.", type = "error")
                      can_run_gsea <- FALSE
                      enrichment_results <- NULL
                    } else {
                      gene_ids <- cached_bitr(
                        geneID = names(ranked_genes),
                        fromType = input$proteomics_id_type,
                        toType = "ENTREZID",
                        OrgDb = annotation_db,
                        trigger_update = trigger_id_cache_update
                      )
                      if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                        showNotification("Could not convert MOFA feature names to ENTREZ IDs for KEGG module GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                        can_run_gsea <- FALSE
                        enrichment_results <- NULL
                      } else {
                        name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                        entrez_names <- name_to_entrez[names(ranked_genes)]
                        entrez_names <- entrez_names[!is.na(entrez_names)]

                        if (length(entrez_names) == 0) {
                          showNotification("No ENTREZ IDs found for MOFA feature names. KEGG module GSEA cannot proceed.", type = "error")
                          can_run_gsea <- FALSE
                          enrichment_results <- NULL
                        } else {
                          ranked_genes <- ranked_genes[names(entrez_names)]
                          names(ranked_genes) <- entrez_names
                          ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          
                          # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                          if (any(duplicated(names(ranked_genes)))) {
                            showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                            unique_names <- unique(names(ranked_genes))
                            ranked_genes_list <- lapply(unique_names, function(name) {
                              idx <- which(names(ranked_genes) == name)
                              idx[which.max(abs(ranked_genes[idx]))]
                            })
                            ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                            ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                          }
                        }
                      }
                    }
                  }

                  if (isTRUE(can_run_gsea)) {
                    enrichment_results <- clusterProfiler::gseMKEGG(
                      geneList = ranked_genes,
                      organism = kegg_org,
                      keyType = "kegg",
                      minGSSize = input$proteomics_gsea_minGSSize,
                      maxGSSize = input$proteomics_gsea_maxGSSize,
                      eps = 1e-10,
                      pvalueCutoff = input$proteomics_cp_pval,
                      pAdjustMethod = input$proteomics_cp_pmethod,
                      verbose = FALSE,
                      seed = FALSE,
                      by = "fgsea"
                    )
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_reactome") {
                  # Reactome GSEA analysis using gsePathway
                  if (requireNamespace("ReactomePA", quietly = TRUE)) {
                    showNotification("Running Reactome GSEA analysis...", type = "message")
                    
                    # ReactomePA uses specific organism names
                    reactome_organism <- switch(input$proteomics_organism,
                                                hsapiens = "human",
                                                mmusculus = "mouse",
                                                rnorvegicus = "rat",
                                                dmelanogaster = "fly",
                                                drerio = "zebrafish",
                                                athaliana = "arabidopsis",
                                                scerevisiae = "yeast",
                                                ecoli = "coli"
                    )
                    
                    # Check if organism is supported by ReactomePA
                    if (is.null(reactome_organism)) {
                      showNotification(paste("ReactomePA does not support", input$proteomics_organism, "organism"), type = "error")
                      enrichment_results <- NULL
                    } else {
                      # Attempt to convert ranked gene names to ENTREZ IDs if needed
                      can_run_gsea <- TRUE
                      if (!is.null(ranked_genes) && length(ranked_genes) > 0 && input$proteomics_id_type != "ENTREZID") {
                        if (is.null(annotation_db)) {
                          showNotification("Cannot convert IDs for Reactome GSEA because annotation database is missing. Install OrgDb or set ID type to ENTREZID.", type = "error")
                          can_run_gsea <- FALSE
                          enrichment_results <- NULL
                        } else {
                          gene_ids <- cached_bitr(
                            geneID = names(ranked_genes),
                            fromType = input$proteomics_id_type,
                            toType = "ENTREZID",
                            OrgDb = annotation_db,
                            trigger_update = trigger_id_cache_update
                          )

                          if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                            showNotification("Could not convert MOFA feature names to ENTREZ IDs for Reactome GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                            can_run_gsea <- FALSE
                            enrichment_results <- NULL
                          } else {
                            name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                            entrez_names <- name_to_entrez[names(ranked_genes)]
                            entrez_names <- entrez_names[!is.na(entrez_names)]

                            if (length(entrez_names) == 0) {
                              showNotification("No ENTREZ IDs found for MOFA feature names. Reactome GSEA cannot proceed.", type = "error")
                              can_run_gsea <- FALSE
                              enrichment_results <- NULL
                            } else {
                              ranked_genes <- ranked_genes[names(entrez_names)]
                              names(ranked_genes) <- entrez_names
                              ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                              
                              # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                              if (any(duplicated(names(ranked_genes)))) {
                                showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                unique_names <- unique(names(ranked_genes))
                                ranked_genes_list <- lapply(unique_names, function(name) {
                                  idx <- which(names(ranked_genes) == name)
                                  idx[which.max(abs(ranked_genes[idx]))]
                                })
                                ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                                ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                              }
                            }
                          }
                        }
                      }

                      if (isTRUE(can_run_gsea)) {
                        tryCatch({
                          enrichment_results <- ReactomePA::gsePathway(
                            geneList = ranked_genes,
                            organism = reactome_organism,
                            minGSSize = input$proteomics_gsea_minGSSize,
                            maxGSSize = input$proteomics_gsea_maxGSSize,
                            pvalueCutoff = input$proteomics_cp_pval,
                            pAdjustMethod = input$proteomics_cp_pmethod,
                            eps = 1e-10,
                            verbose = FALSE,
                            seed = FALSE,
                            by = "fgsea"
                          )
                        }, error = function(e) {
                          showNotification(paste("ReactomePA gsePathway failed:", e$message), type = "error")
                          enrichment_results <<- NULL
                        })
                      }
                    }
                  } else {
                    showNotification("ReactomePA package not available for Reactome GSEA analysis. Please install it.", type = "error")
                    enrichment_results <- NULL
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_pathwaycommons") {
                  # Pathway Commons GSEA analysis using gsePC
                  pc_org <- switch(input$proteomics_organism,
                                   hsapiens = "hsa", mmusculus = "mmu", rnorvegicus = "rno",
                                   dmelanogaster = "dme", drerio = "dre", athaliana = "ath",
                                   scerevisiae = "sce", ecoli = "eco")
                  
                  if (requireNamespace("clusterProfiler", quietly = TRUE)) {
                    showNotification("Running Pathway Commons GSEA analysis...", type = "message")
                    
                    # Check if clusterProfiler has gsePC function
                    if (exists("gsePC", where = asNamespace("clusterProfiler"))) {
                      # Convert ranked genes to SYMBOL or UNIPROT format for gsePC
                      pc_ranked_genes <- NULL
                      conversion_type <- NULL
                      
                      if(input$proteomics_id_type == "SYMBOL") {
                        # Already in HGNC symbols, use directly
                        pc_ranked_genes <- ranked_genes
                        conversion_type <- "SYMBOL"
                        showNotification(paste("Using", length(pc_ranked_genes), "HGNC symbols for Pathway Commons GSEA"), type = "message")
                      } else if(input$proteomics_id_type == "UNIPROT") {
                        # Already in UniProt IDs, use directly - no conversion needed
                        pc_ranked_genes <- ranked_genes
                        conversion_type <- "UNIPROT"
                        showNotification(paste("Using", length(pc_ranked_genes), "UniProt IDs for Pathway Commons GSEA"), type = "message")
                      } else {
                        # For other ID types, try to convert to HGNC symbols first, then UniProt if that fails
                        if(exists("gene_ids") && nrow(gene_ids) > 0) {
                          # First attempt: Convert to SYMBOL
                          if(input$proteomics_id_type == "ENTREZID") {
                            # Map ENTREZ to SYMBOL
                            if("SYMBOL" %in% colnames(gene_ids)) {
                              entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                              symbol_names <- entrez_to_symbol[names(ranked_genes)]
                              valid_mappings <- !is.na(symbol_names)
                              
                              if(sum(valid_mappings) > 0) {
                                pc_ranked_genes <- ranked_genes[valid_mappings]
                                names(pc_ranked_genes) <- symbol_names[valid_mappings]
                                conversion_type <- "SYMBOL"
                                
                                # Handle duplicate symbols by keeping feature with max absolute value
                                if (any(duplicated(names(pc_ranked_genes)))) {
                                  showNotification("Duplicate gene symbols detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                  unique_names <- unique(names(pc_ranked_genes))
                                  pc_ranked_genes_list <- lapply(unique_names, function(name) {
                                    idx <- which(names(pc_ranked_genes) == name)
                                    idx[which.max(abs(pc_ranked_genes[idx]))]
                                  })
                                  pc_ranked_genes <- pc_ranked_genes[unlist(pc_ranked_genes_list)]
                                }
                                
                                showNotification(paste("Converted", length(pc_ranked_genes), "genes to HGNC symbols for Pathway Commons GSEA"), type = "message")
                              }
                            }
                          } else {
                            # First convert to ENTREZ, then to SYMBOL
                            if(input$proteomics_id_type %in% colnames(gene_ids)) {
                              input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                              entrez_names <- input_to_entrez[names(ranked_genes)]
                              valid_entrez <- !is.na(entrez_names)
                              
                              if(sum(valid_entrez) > 0 && "SYMBOL" %in% colnames(gene_ids)) {
                                entrez_to_symbol <- setNames(gene_ids$SYMBOL, gene_ids$ENTREZID)
                                symbol_names <- entrez_to_symbol[entrez_names[valid_entrez]]
                                valid_symbols <- !is.na(symbol_names)
                                
                                if(sum(valid_symbols) > 0) {
                                  pc_ranked_genes <- ranked_genes[valid_entrez][valid_symbols]
                                  names(pc_ranked_genes) <- symbol_names[valid_symbols]
                                  conversion_type <- "SYMBOL"
                                  
                                  # Handle duplicate symbols by keeping feature with max absolute weight
                                  if (any(duplicated(names(pc_ranked_genes)))) {
                                    showNotification("Duplicate gene symbols detected. Retaining features with maximum absolute weights.", type = "warning", duration = 4)
                                    unique_names <- unique(names(pc_ranked_genes))
                                    pc_ranked_genes_list <- lapply(unique_names, function(name) {
                                      idx <- which(names(pc_ranked_genes) == name)
                                      idx[which.max(abs(pc_ranked_genes[idx]))]
                                    })
                                    pc_ranked_genes <- pc_ranked_genes[unlist(pc_ranked_genes_list)]
                                  }
                                  
                                  showNotification(paste("Converted", length(pc_ranked_genes), "genes to HGNC symbols for Pathway Commons GSEA"), type = "message")
                                }
                              }
                            }
                          }
                          
                          # Second attempt: If SYMBOL conversion failed or yielded too few genes, try UNIPROT
                          if((is.null(pc_ranked_genes) || length(pc_ranked_genes) < 10) && "UNIPROT" %in% colnames(gene_ids)) {
                            showNotification("SYMBOL conversion yielded insufficient genes. Attempting UniProt ID conversion...", type = "message")
                            
                            if(input$proteomics_id_type == "ENTREZID") {
                              # Map ENTREZ to UNIPROT
                              entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                              uniprot_names <- entrez_to_uniprot[names(ranked_genes)]
                              valid_mappings <- !is.na(uniprot_names)
                              
                              if(sum(valid_mappings) > 0) {
                                pc_ranked_genes <- ranked_genes[valid_mappings]
                                names(pc_ranked_genes) <- uniprot_names[valid_mappings]
                                conversion_type <- "UNIPROT"
                                
                                # Handle duplicate UniProt IDs by keeping feature with max absolute value
                                if (any(duplicated(names(pc_ranked_genes)))) {
                                  showNotification("Duplicate UniProt IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                  unique_names <- unique(names(pc_ranked_genes))
                                  pc_ranked_genes_list <- lapply(unique_names, function(name) {
                                    idx <- which(names(pc_ranked_genes) == name)
                                    idx[which.max(abs(pc_ranked_genes[idx]))]
                                  })
                                  pc_ranked_genes <- pc_ranked_genes[unlist(pc_ranked_genes_list)]
                                }
                                
                                showNotification(paste("Converted", length(pc_ranked_genes), "genes to UniProt IDs for Pathway Commons GSEA"), type = "message")
                              }
                            } else {
                              # First convert to ENTREZ, then to UNIPROT
                              if(input$proteomics_id_type %in% colnames(gene_ids)) {
                                input_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                                entrez_names <- input_to_entrez[names(ranked_genes)]
                                valid_entrez <- !is.na(entrez_names)
                                
                                if(sum(valid_entrez) > 0) {
                                  entrez_to_uniprot <- setNames(gene_ids$UNIPROT, gene_ids$ENTREZID)
                                  uniprot_names <- entrez_to_uniprot[entrez_names[valid_entrez]]
                                  valid_uniprot <- !is.na(uniprot_names)
                                  
                                  if(sum(valid_uniprot) > 0) {
                                    pc_ranked_genes <- ranked_genes[valid_entrez][valid_uniprot]
                                    names(pc_ranked_genes) <- uniprot_names[valid_uniprot]
                                    conversion_type <- "UNIPROT"
                                    
                                    # Handle duplicate UniProt IDs by keeping feature with max absolute value
                                    if (any(duplicated(names(pc_ranked_genes)))) {
                                      showNotification("Duplicate UniProt IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                      unique_names <- unique(names(pc_ranked_genes))
                                      pc_ranked_genes_list <- lapply(unique_names, function(name) {
                                        idx <- which(names(pc_ranked_genes) == name)
                                        idx[which.max(abs(pc_ranked_genes[idx]))]
                                      })
                                      pc_ranked_genes <- pc_ranked_genes[unlist(pc_ranked_genes_list)]
                                    }
                                    
                                    showNotification(paste("Converted", length(pc_ranked_genes), "genes to UniProt IDs for Pathway Commons GSEA"), type = "message")
                                  }
                                }
                              }
                            }
                          }
                        }
                        
                        if(is.null(pc_ranked_genes) || length(pc_ranked_genes) == 0) {
                          showNotification("Could not convert gene IDs to HGNC symbols or UniProt IDs for Pathway Commons GSEA. Please ensure your gene annotation data includes SYMBOL or UNIPROT columns.", type = "error")
                          enrichment_results <- NULL
                        }
                      }
                      
                      # Run gsePC analysis if we have converted genes
                      if(!is.null(pc_ranked_genes) && length(pc_ranked_genes) > 0) {
                        enrichment_results <- clusterProfiler::gsePC(
                          geneList = pc_ranked_genes,
                          organism = pc_org,
                          minGSSize = input$proteomics_gsea_minGSSize,
                          maxGSSize = input$proteomics_gsea_maxGSSize,
                          pvalueCutoff = input$proteomics_cp_pval,
                          pAdjustMethod = input$proteomics_cp_pmethod,
                          eps = 1e-10,
                          verbose = FALSE,
                          seed = FALSE,
                          by = "fgsea"
                        )
                      } else {
                        showNotification("No valid genes found for Pathway Commons GSEA analysis", type = "error")
                        enrichment_results <- NULL
                      }
                    } else {
                      showNotification("gsePC function not available in clusterProfiler. Please ensure you have the latest version.", type = "error")
                      enrichment_results <- NULL
                    }
                  } else {
                    showNotification("clusterProfiler package not available for Pathway Commons GSEA.", type = "error")
                    enrichment_results <- NULL
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_wikipathways") {
                  # WikiPathways GSEA analysis using gseWP
                  if (requireNamespace("clusterProfiler", quietly = TRUE)) {
                    showNotification("Running WikiPathways GSEA analysis...", type = "message")
                    
                    # Check if clusterProfiler has gseWP function
                    if (exists("gseWP", where = asNamespace("clusterProfiler"))) {
                      # Convert organism name for WikiPathways
                      wp_organism <- switch(input$proteomics_organism,
                                            hsapiens = "Homo sapiens",
                                            mmusculus = "Mus musculus",
                                            rnorvegicus = "Rattus norvegicus",
                                            dmelanogaster = "Drosophila melanogaster",
                                            drerio = "Danio rerio",
                                            scerevisiae = "Saccharomyces cerevisiae",
                                            athaliana = "Arabidopsis thaliana",
                                            ecoli = "Escherichia coli"
                      )

                      # Attempt to convert ranked gene names to ENTREZ IDs if needed
                      can_run_gsea <- TRUE
                      if (!is.null(ranked_genes) && length(ranked_genes) > 0 && input$proteomics_id_type != "ENTREZID") {
                        if (is.null(annotation_db)) {
                          showNotification("Cannot convert IDs for WikiPathways GSEA because annotation database is missing. Install OrgDb or set ID type to ENTREZID.", type = "error")
                          can_run_gsea <- FALSE
                          enrichment_results <- NULL
                        } else {
                          gene_ids <- cached_bitr(
                            geneID = names(ranked_genes),
                            fromType = input$proteomics_id_type,
                            toType = "ENTREZID",
                            OrgDb = annotation_db,
                            trigger_update = trigger_id_cache_update
                          )

                          if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                            showNotification("Could not convert MOFA feature names to ENTREZ IDs for WikiPathways GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                            can_run_gsea <- FALSE
                            enrichment_results <- NULL
                          } else {
                            name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                            entrez_names <- name_to_entrez[names(ranked_genes)]
                            entrez_names <- entrez_names[!is.na(entrez_names)]

                            if (length(entrez_names) == 0) {
                              showNotification("No ENTREZ IDs found for MOFA feature names. WikiPathways GSEA cannot proceed.", type = "error")
                              can_run_gsea <- FALSE
                              enrichment_results <- NULL
                            } else {
                              ranked_genes <- ranked_genes[names(entrez_names)]
                              names(ranked_genes) <- entrez_names
                              ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                              
                              # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                              if (any(duplicated(names(ranked_genes)))) {
                                showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                unique_names <- unique(names(ranked_genes))
                                ranked_genes_list <- lapply(unique_names, function(name) {
                                  idx <- which(names(ranked_genes) == name)
                                  idx[which.max(abs(ranked_genes[idx]))]
                                })
                                ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                                ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                              }
                            }
                          }
                        }
                      }

                      if (isTRUE(can_run_gsea)) {
                        enrichment_results <- clusterProfiler::gseWP(
                          geneList = ranked_genes,
                          organism = wp_organism,
                          minGSSize = input$proteomics_gsea_minGSSize,
                          maxGSSize = input$proteomics_gsea_maxGSSize,
                          pvalueCutoff = input$proteomics_cp_pval,
                          pAdjustMethod = input$proteomics_cp_pmethod,
                          eps = 1e-10,
                          verbose = FALSE,
                          seed = FALSE,
                          by = "fgsea"
                        )
                      }
                    } else {
                      showNotification("gseWP function not available in clusterProfiler. Please ensure you have the latest version.", type = "error")
                      enrichment_results <- NULL
                    }
                  } else {
                    showNotification("clusterProfiler package not available for WikiPathways GSEA.", type = "error")
                    enrichment_results <- NULL
                  }
                }
                else if(input$proteomics_cp_analysis == "gsea_msigdb") {
                  # MSigDB GSEA analysis
                  if (requireNamespace("msigdbr", quietly = TRUE)) {
                    organism_code <- switch(input$proteomics_organism,
                                            hsapiens = "Homo sapiens", mmusculus = "Mus musculus", rnorvegicus = "Rattus norvegicus",
                                            dmelanogaster = "Drosophila melanogaster", drerio = "Danio rerio",
                                            athaliana = "Arabidopsis thaliana", scerevisiae = "Saccharomyces cerevisiae",
                                            ecoli = "Escherichia coli"
                    )
                    
                    # Check if organism is supported by MSigDB
                    available_species <- msigdbr::msigdbr_species()
                    if (!organism_code %in% available_species$species_name) {
                      showNotification(paste("MSigDB GSEA is not available for", organism_code), type = "warning")
                      enrichment_results <- NULL
                    } else {
                      # Get MSigDB gene sets
                      if (!is.null(input$proteomics_cp_msigdb_subcategory) && input$proteomics_cp_msigdb_subcategory != "") {
                        msigdb_sets <- msigdbr::msigdbr(
                          species = organism_code,
                          category = input$proteomics_cp_msigdb_category,
                          subcategory = input$proteomics_cp_msigdb_subcategory
                        )
                      } else {
                        msigdb_sets <- msigdbr::msigdbr(
                          species = organism_code,
                          category = input$proteomics_cp_msigdb_category
                        )
                      }
                      
                      if (nrow(msigdb_sets) > 0) {
                        # Create TERM2GENE and TERM2NAME mappings
                        term2gene <- msigdb_sets[, c("gs_name", "entrez_gene")]
                        term2name <- unique(msigdb_sets[, c("gs_name", "gs_description")])
                        
                        showNotification(paste("Running MSigDB GSEA with", length(unique(msigdb_sets$gs_name)), "gene sets..."), type = "message")

                        # Ensure ranked genes are ENTREZ IDs
                        can_run_gsea <- TRUE
                        if (!is.null(ranked_genes) && length(ranked_genes) > 0 && input$proteomics_id_type != "ENTREZID") {
                          if (is.null(annotation_db)) {
                            showNotification("Cannot convert IDs for MSigDB GSEA because annotation database is missing. Install OrgDb or set ID type to ENTREZID.", type = "error")
                            can_run_gsea <- FALSE
                            enrichment_results <- NULL
                          } else {
                            gene_ids <- cached_bitr(
                              geneID = names(ranked_genes),
                              fromType = input$proteomics_id_type,
                              toType = "ENTREZID",
                              OrgDb = annotation_db,
                              trigger_update = trigger_id_cache_update
                            )

                            if (is.null(gene_ids) || nrow(gene_ids) == 0) {
                              showNotification("Could not convert MOFA feature names to ENTREZ IDs for MSigDB GSEA. Ensure 'ID type' matches MOFA feature identifiers or provide mapping.", type = "error")
                              can_run_gsea <- FALSE
                              enrichment_results <- NULL
                            } else {
                              name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
                              entrez_names <- name_to_entrez[names(ranked_genes)]
                              entrez_names <- entrez_names[!is.na(entrez_names)]

                              if (length(entrez_names) == 0) {
                                showNotification("No ENTREZ IDs found for MOFA feature names. MSigDB GSEA cannot proceed.", type = "error")
                                can_run_gsea <- FALSE
                                enrichment_results <- NULL
                              } else {
                                ranked_genes <- ranked_genes[names(entrez_names)]
                                names(ranked_genes) <- entrez_names
                                ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                                
                                # Handle duplicate ENTREZ IDs by keeping feature with max absolute value
                                if (any(duplicated(names(ranked_genes)))) {
                                  showNotification("Duplicate ENTREZ IDs detected. Retaining features with maximum absolute values.", type = "warning", duration = 4)
                                  unique_names <- unique(names(ranked_genes))
                                  ranked_genes_list <- lapply(unique_names, function(name) {
                                    idx <- which(names(ranked_genes) == name)
                                    idx[which.max(abs(ranked_genes[idx]))]
                                  })
                                  ranked_genes <- ranked_genes[unlist(ranked_genes_list)]
                                  ranked_genes <- sort(ranked_genes, decreasing = TRUE)
                                }
                              }
                            }
                          }
                        }

                        if (isTRUE(can_run_gsea)) {
                          enrichment_results <- clusterProfiler::GSEA(
                            geneList = ranked_genes,
                            TERM2GENE = term2gene,
                            TERM2NAME = term2name,
                            eps = 1e-10,
                            minGSSize = input$proteomics_gsea_minGSSize,
                            maxGSSize = input$proteomics_gsea_maxGSSize,
                            pvalueCutoff = input$proteomics_cp_pval,
                            pAdjustMethod = input$proteomics_cp_pmethod,
                            scoreType = input$proteomics_gsea_scoreType,
                            verbose = FALSE,
                            by = "fgsea"
                          )
                        }
                      } else {
                        showNotification("No MSigDB gene sets found for GSEA analysis", type = "warning")
                        enrichment_results <- NULL
                      }
                    }
                  } else {
                    showNotification("msigdbr package not available for MSigDB GSEA", type = "error")
                    enrichment_results <- NULL
                  }
                }
              }
            }
          }
          
          # Check if we have any results
          if(is.null(enrichment_results) || nrow(enrichment_results) == 0) {
            showNotification("No enrichment results found. Try adjusting parameters or checking ID mapping.", type = "warning")
          } else {
            # === STORE ORIGINAL ENRICHMENT RESULTS FOR UPSETPLOT ===
            # Store the original enrichment results with ENTREZ IDs before ID mapping
            # This is needed for upsetplot to properly show expression box plots
            enrichment_results_original <- enrichment_results
            
            # === ID MAPPING FOR VISUALIZATION ===
            # ClusterProfiler internally uses ENTREZ IDs for analysis, but we want to display
            # the original IDs (e.g., gene symbols, UniProt IDs) in the enrichment plots.
            # This section maps ENTREZ IDs back to the original IDs in the enrichment results.
            # This ensures that when users view plots (dotplot, barplot, heatplot, etc.),
            # they see the familiar gene identifiers they originally provided.
            
            # Map ENTREZ IDs back to original IDs in the enrichment results
            if(input$proteomics_id_type != "ENTREZID" && exists("gene_ids") && nrow(gene_ids) > 0) {
              # Create mapping from ENTREZ to original IDs
              entrez_to_original <- setNames(gene_ids[[input$proteomics_id_type]], gene_ids$ENTREZID)
              
              # Function to map ENTREZ IDs back to original IDs
              map_entrez_to_original <- function(entrez_string) {
                if(is.na(entrez_string) || entrez_string == "") return(entrez_string)
                
                # Split by "/" delimiter (used by ClusterProfiler)
                entrez_ids <- strsplit(as.character(entrez_string), "/")[[1]]
                
                # Map each ENTREZ ID back to original ID
                original_ids <- sapply(entrez_ids, function(id) {
                  original_id <- entrez_to_original[id]
                  if(is.na(original_id)) return(id)  # Keep ENTREZ if no mapping found
                  return(original_id)
                })
                
                # Rejoin with "/" delimiter
                return(paste(original_ids, collapse = "/"))
              }
              
              # Apply mapping to enrichment results
              enrichment_df <- as.data.frame(enrichment_results)
              
              # Map geneID field (for ORA results)
              if("geneID" %in% colnames(enrichment_df)) {
                enrichment_df$geneID <- sapply(enrichment_df$geneID, map_entrez_to_original)
              }
              
              # Map core_enrichment field (for GSEA results)
              if("core_enrichment" %in% colnames(enrichment_df)) {
                enrichment_df$core_enrichment <- sapply(enrichment_df$core_enrichment, map_entrez_to_original)
              }
              
              # Update the enrichment results object
              enrichment_results@result <- enrichment_df
              
              # Also update the fold change data for visualization to use original IDs
              if(exists("fold_change_data") && !is.null(fold_change_data)) {
                # Map fold change data names from ENTREZ to original IDs
                mapped_names <- sapply(names(fold_change_data), function(entrez_id) {
                  original_id <- entrez_to_original[entrez_id]
                  if(is.na(original_id)) return(entrez_id)
                  return(original_id)
                })
                
                # Update the fold change data with original names
                names(fold_change_data) <- mapped_names
                
                # Store the mapped fold change data
                proteomics_values$fold_change_data <- fold_change_data
              }
              
              # Update original_fold_change_data as well if it exists
              if(exists("original_fold_change_data") && !is.null(original_fold_change_data)) {
                # The original_fold_change_data should already have the original names
                # but ensure it's stored in proteomics_values
                proteomics_values$original_fold_change_data <- original_fold_change_data
              }
              
              showNotification("Gene IDs mapped back to original identifiers in enrichment results", type = "message", duration = 3)
            }
          }
          
          # Hide progress bar after successful completion
          session$sendCustomMessage(type = "hideClusterProfilerProgress", message = list())
          
        }, error = function(e) {
          showNotification(paste("ClusterProfiler error:", e$message), type = "error")
          # Hide progress bar on error
          session$sendCustomMessage(type = "hideClusterProfilerProgress", message = list())
          NULL
        })
      } else if (input$proteomics_tool == "enrichr") {
        # Show global Enrichr banner across all proteomics tabs
        session$sendCustomMessage(type = "showEnrichrProgress", message = list())
        tryCatch({
          # Prepare custom background for Enrichr if selected
          enrichr_background <- NULL
          
          if (input$proteomics_enrichr_bg_option == "custom") {
            if (input$proteomics_enrichr_bg_source == "full_dataset") {
              # Use full uploaded feature universe as background
              if (input$proteomics_source == "manual" &&
                  !is.null(proteomics_values$manual_full_gene_universe) &&
                  length(proteomics_values$manual_full_gene_universe) > 0) {
                enrichr_background <- proteomics_values$manual_full_gene_universe
                showNotification(paste("Using", length(enrichr_background), "features from uploaded file as Enrichr background (full universe)"),
                                 type = "message", duration = 3)
              } else if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) > 0) {
                enrichr_background <- values$cleaned_molecules
                showNotification(paste("Using", length(enrichr_background), "features from uploaded dataset as Enrichr background"),
                                 type = "message", duration = 3)
              } else {
                showNotification("No uploaded dataset available for custom background. Using default Enrichr background.",
                                 type = "warning", duration = 5)
              }
            } else if (input$proteomics_enrichr_bg_source == "manual_input") {
              # Use manual input as background
              bg_text <- input$proteomics_enrichr_custom_bg
              if (!is.null(bg_text) && nchar(trimws(bg_text)) > 0) {
                enrichr_background <- unique(trimws(unlist(strsplit(bg_text, "\n"))))
                enrichr_background <- enrichr_background[enrichr_background != ""]  # Remove empty lines
                
                if (length(enrichr_background) > 0) {
                  showNotification(paste("Using", length(enrichr_background), "custom genes as Enrichr background"),
                                   type = "message", duration = 3)
                } else {
                  showNotification("Custom background list is empty. Using default Enrichr background.",
                                   type = "warning", duration = 5)
                  enrichr_background <- NULL
                }
              } else {
                showNotification("Please provide a custom background gene list. Using default Enrichr background.",
                                 type = "warning", duration = 5)
              }
            }
          }
          
          dbs <- input$proteomics_enrichr_db

          # Enrichr base URL (use official maayanlab endpoint)
          enrichr_url <- "https://maayanlab.cloud/Enrichr"

          # Quick availability check for Enrichr service
          enrichr_available <- FALSE
          try({
            res_head <- httr::HEAD(enrichr_url, httr::timeout(4))
            enrichr_available <- httr::status_code(res_head) %in% c(200, 301, 302)
          }, silent = TRUE)

          if (!enrichr_available) {
            showNotification(
              HTML("Enrichr service is currently unreachable (<a href='https://maayanlab.cloud/Enrichr' target='_blank'>maayanlab.cloud/Enrichr</a>).<br/>Please check your internet connection or try an alternative tool (ClusterProfiler)."),
              type = "error", duration = 10
            )
            enrichment_results <- NULL
          } else {
            # Call enrichr with or without background parameter and explicit URL
            # Detect whether the installed enrichR::enrichr supports the 'url' argument
            enrichr_formals <- tryCatch(names(formals(enrichR::enrichr)), error = function(e) NULL)
            use_url_arg <- !is.null(enrichr_formals) && 'url' %in% enrichr_formals

            if (!is.null(enrichr_background)) {
              # Use custom background with include_overlap to get detailed overlap information
              showNotification("Running Enrichr with custom background...",
                               type = "message", duration = 3)

              if (use_url_arg) {
                enrichment_results <- enrichR::enrichr(genes = gene_list,
                                                       databases = dbs,
                                                       background = enrichr_background,
                                                       include_overlap = TRUE,
                                                       url = enrichr_url)
              } else {
                # Fallback for older enrichR versions (no url arg)
                enrichment_results <- enrichR::enrichr(genes = gene_list,
                                                       databases = dbs,
                                                       background = enrichr_background,
                                                       include_overlap = TRUE)
                showNotification("Note: using enrichR without explicit URL parameter (package version < expected).", type = "warning", duration = 6)
              }

              if (!is.null(enrichment_results)) {
                showNotification(paste0("Enrichment completed with custom background of ",
                                        length(enrichr_background), " genes"),
                                 type = "message", duration = 3)
              }
            } else {
              # Use default Enrichr (no background)
              if (use_url_arg) {
                enrichment_results <- enrichR::enrichr(genes = gene_list,
                                                       databases = dbs,
                                                       url = enrichr_url)
              } else {
                enrichment_results <- enrichR::enrichr(genes = gene_list,
                                                       databases = dbs)
                showNotification("Note: using enrichR without explicit URL parameter (package version < expected).", type = "warning", duration = 6)
              }
            }
          }
        }, error = function(e) {
          # Hide Enrichr banner on error
          session$sendCustomMessage(type = "hideEnrichrProgress", message = list())

          # Check if it's a network connectivity error
          if (grepl("Could not resolve host|Couldn't resolve host|timeout|connection|maayanlab.cloud", e$message, ignore.case = TRUE)) {
            showNotification(
              HTML("Enrichr Network Error: Unable to connect to Enrichr service.<br/>
                 Please check your internet connection and try again.<br/>
                 Alternative: Use ClusterProfiler for offline analysis."),
              type = "error",
              duration = 10
            )
          } else {
            showNotification(paste("Enrichr error:", e$message), type = "error", duration = 8)
          }
          enrichment_results <- NULL
        })
        # Hide Enrichr banner after completion
        session$sendCustomMessage(type = "hideEnrichrProgress", message = list())
        
      }
      
      else if (input$proteomics_tool == "reactomepa") {
        # Show progress bar specifically for ReactomePA
        session$sendCustomMessage(type = "showReactomePAProgress", message = list())
        
        tryCatch({
          # Get pre-loaded annotation database or load on-demand
          annotation_db <- get_annotation_database(input$proteomics_organism)
          
          # Get organism code for ReactomePA
          organism_code <- switch(input$proteomics_organism,
                                  hsapiens = "human",
                                  mmusculus = "mouse",
                                  rnorvegicus = "rat",
                                  "human") # Default to human
          
          # Show notification about ID conversion
          showNotification("Converting IDs for ReactomePA...", type = "message")
          
          # Convert IDs to ENTREZ
          if (input$proteomics_id_type != "ENTREZID") {
            # Use cached bitr to convert IDs
            gene_ids <- cached_bitr(
              geneID = gene_list,
              fromType = input$proteomics_id_type,
              toType = "ENTREZID",
              OrgDb = annotation_db,
              trigger_update = trigger_id_cache_update
            )
            
            if (nrow(gene_ids) == 0) {
              showNotification("Failed to convert IDs. Please check your ID type selection.", type = "error")
              session$sendCustomMessage(type = "hideReactomePAProgress", message = list())
              return(NULL)
            }
            
            # Show conversion stats
            showNotification(paste("Successfully mapped", nrow(gene_ids), "out of",
                                   length(gene_list), "IDs to ENTREZ format"), type = "message")
            
            # Use only the converted IDs
            mapped_genes <- gene_ids$ENTREZID
          } else {
            # IDs are already ENTREZ
            mapped_genes <- gene_list
          }
          
          # Prepare custom universe (background) for ReactomePA
          reactome_universe <- NULL
          if (input$proteomics_reactome_bg_type == "custom") {
            if (input$proteomics_reactome_bg_source == "full_dataset") {
              # Use full uploaded dataset as background
              background_genes <- NULL
              if (input$proteomics_source == "manual" &&
                  !is.null(proteomics_values$manual_full_gene_universe) &&
                  length(proteomics_values$manual_full_gene_universe) > 0) {
                background_genes <- proteomics_values$manual_full_gene_universe
              } else {
                background_genes <- values$cleaned_molecules
              }
              
              if (!is.null(background_genes) && length(background_genes) > 0) {
                showNotification(paste("Using full dataset as ReactomePA background:",
                                       length(background_genes), "genes"),
                                 type = "message", duration = 3)
                
                # Convert background genes to ENTREZ if needed
                if (input$proteomics_id_type != "ENTREZID") {
                  bg_ids <- cached_bitr(
                    geneID = background_genes,
                    fromType = input$proteomics_id_type,
                    toType = "ENTREZID",
                    OrgDb = annotation_db,
                    trigger_update = trigger_id_cache_update
                  )
                  reactome_universe <- bg_ids$ENTREZID
                } else {
                  reactome_universe <- background_genes
                }
                
                showNotification(paste("Converted", length(reactome_universe),
                                       "background genes to ENTREZ format"),
                                 type = "message", duration = 3)
              } else {
                showNotification("Full dataset not available. Using default ReactomePA background.",
                                 type = "warning", duration = 5)
              }
            } else if (input$proteomics_reactome_bg_source == "manual_input") {
              # Use manually entered background
              bg_text <- input$proteomics_reactome_custom_bg
              if (!is.null(bg_text) && nchar(trimws(bg_text)) > 0) {
                background_genes <- unique(trimws(unlist(strsplit(bg_text, "\n"))))
                background_genes <- background_genes[background_genes != ""]  # Remove empty lines
                
                if (length(background_genes) > 0) {
                  showNotification(paste("Using", length(background_genes),
                                         "custom genes as ReactomePA background"),
                                   type = "message", duration = 3)
                  
                  # Convert background genes to ENTREZ if needed
                  if (input$proteomics_id_type != "ENTREZID") {
                    bg_ids <- cached_bitr(
                      geneID = background_genes,
                      fromType = input$proteomics_id_type,
                      toType = "ENTREZID",
                      OrgDb = annotation_db,
                      trigger_update = trigger_id_cache_update
                    )
                    reactome_universe <- bg_ids$ENTREZID
                  } else {
                    reactome_universe <- background_genes
                  }
                  
                  showNotification(paste("Converted", length(reactome_universe),
                                         "background genes to ENTREZ format"),
                                   type = "message", duration = 3)
                } else {
                  showNotification("Custom background list is empty. Using default ReactomePA background.",
                                   type = "warning", duration = 5)
                }
              } else {
                showNotification("Please provide a custom background gene list. Using default ReactomePA background.",
                                 type = "warning", duration = 5)
              }
            }
          }
          
          # Now run ReactomePA with proper ENTREZ IDs and universe
          if (!is.null(reactome_universe)) {
            showNotification(paste("Running ReactomePA with custom background of",
                                   length(reactome_universe), "genes"),
                             type = "message", duration = 3)
          }
          
          enrichment_results <- ReactomePA::enrichPathway(
            gene = mapped_genes,
            universe = reactome_universe,  # Use custom background if provided
            organism = organism_code,
            pvalueCutoff = input$proteomics_reactome_pval,
            qvalueCutoff = input$proteomics_reactome_qval,
            readable = TRUE  # Convert IDs to gene symbols in the output
          )
          
          # Check if we got results
          if (is.null(enrichment_results) || nrow(enrichment_results) == 0) {
            showNotification("No significant pathways found in Reactome. Try adjusting parameters.",
                             type = "warning")
          }
          
          # Hide progress bar after successful completion
          session$sendCustomMessage(type = "hideReactomePAProgress", message = list())
          
        }, error = function(e) {
          showNotification(paste("ReactomePA error:", e$message), type = "error")
          # Hide progress bar on error
          session$sendCustomMessage(type = "hideReactomePAProgress", message = list())
          NULL
        })
      }
      
      # Modify the topGO section to store results directly in values$proteomics_results
      
      else if (input$proteomics_tool == "topgo") {
        # Show progress bar specifically for topGO
        session$sendCustomMessage(type = "showTopGOProgress", message = list())
        
        tryCatch({
          # Ensure required packages
          if (!requireNamespace("topGO", quietly = TRUE)) {
            showNotification("Installing topGO package...", type = "message")
            BiocManager::install("topGO", update = FALSE)
          }
          
          # Load required packages explicitly
          library(topGO)
          library(methods)
          
          # Get pre-loaded annotation database or load on-demand
          annotation_db <- get_annotation_database(input$proteomics_organism)
          
          # Get the package name for topGO mapping parameter
          OrgDb_name <- switch(input$proteomics_organism,
                               hsapiens = "org.Hs.eg.db",
                               mmusculus = "org.Mm.eg.db",
                               rnorvegicus = "org.Rn.eg.db",
                               dmelanogaster = "org.Dm.eg.db",
                               drerio = "org.Dr.eg.db",
                               athaliana = "org.At.tair.db",
                               scerevisiae = "org.Sc.sgd.db",
                               ecoli = "org.EcK12.eg.db")
          
          # Convert IDs if needed
          if(input$proteomics_id_type != "ENTREZID") {
            showNotification("Converting IDs for topGO...", type = "message")
            
            # Use cached bitr to convert IDs
            gene_ids <- cached_bitr(
              geneID = gene_list,
              fromType = input$proteomics_id_type,
              toType = "ENTREZID",
              OrgDb = annotation_db,
              trigger_update = trigger_id_cache_update
            )
            
            if (nrow(gene_ids) == 0) {
              showNotification("Failed to convert any IDs. Please check your ID type selection.",
                               type = "error")
              session$sendCustomMessage(type = "hideTopGOProgress", message = list())
              return(NULL)
            }
            
            # Show conversion stats
            showNotification(paste("Successfully mapped", nrow(gene_ids), "out of",
                                   length(gene_list), "IDs"), type = "message")
            
            # Use the converted IDs
            mapped_genes <- gene_ids$ENTREZID
          } else {
            mapped_genes <- gene_list
          }
          
          # Prepare custom background/universe for topGO
          all_genes <- NULL
          if (input$proteomics_topgo_bg_type == "custom") {
            if (input$proteomics_topgo_bg_source == "full_dataset") {
              # Use full uploaded dataset as background
              background_genes <- NULL
              if (input$proteomics_source == "manual" &&
                  !is.null(proteomics_values$manual_full_gene_universe) &&
                  length(proteomics_values$manual_full_gene_universe) > 0) {
                background_genes <- proteomics_values$manual_full_gene_universe
              } else {
                background_genes <- values$cleaned_molecules
              }
              
              if (!is.null(background_genes) && length(background_genes) > 0) {
                showNotification(paste("Using full dataset as topGO background:",
                                       length(background_genes), "genes"),
                                 type = "message", duration = 3)
                
                # Convert background genes to ENTREZ if needed
                if (input$proteomics_id_type != "ENTREZID") {
                  bg_ids <- cached_bitr(
                    geneID = background_genes,
                    fromType = input$proteomics_id_type,
                    toType = "ENTREZID",
                    OrgDb = annotation_db,
                    trigger_update = trigger_id_cache_update
                  )
                  all_genes <- bg_ids$ENTREZID
                } else {
                  all_genes <- background_genes
                }
                
                showNotification(paste("Converted", length(all_genes),
                                       "background genes to ENTREZ format"),
                                 type = "message", duration = 3)
              } else {
                showNotification("Full dataset not available. Using default topGO background.",
                                 type = "warning", duration = 5)
              }
            } else if (input$proteomics_topgo_bg_source == "manual_input") {
              # Use manually entered background
              bg_text <- input$proteomics_topgo_custom_bg
              if (!is.null(bg_text) && nchar(trimws(bg_text)) > 0) {
                background_genes <- unique(trimws(unlist(strsplit(bg_text, "\n"))))
                background_genes <- background_genes[background_genes != ""]  # Remove empty lines
                
                if (length(background_genes) > 0) {
                  showNotification(paste("Using", length(background_genes),
                                         "custom genes as topGO background"),
                                   type = "message", duration = 3)
                  
                  # Convert background genes to ENTREZ if needed
                  if (input$proteomics_id_type != "ENTREZID") {
                    bg_ids <- cached_bitr(
                      geneID = background_genes,
                      fromType = input$proteomics_id_type,
                      toType = "ENTREZID",
                      OrgDb = annotation_db,
                      trigger_update = trigger_id_cache_update
                    )
                    all_genes <- bg_ids$ENTREZID
                  } else {
                    all_genes <- background_genes
                  }
                  
                  showNotification(paste("Converted", length(all_genes),
                                         "background genes to ENTREZ format"),
                                   type = "message", duration = 3)
                } else {
                  showNotification("Custom background list is empty. Using default topGO background.",
                                   type = "warning", duration = 5)
                }
              } else {
                showNotification("Please provide a custom background gene list. Using default topGO background.",
                                 type = "warning", duration = 5)
              }
            }
          }
          
          # Create custom geneList
          showNotification("Creating gene list for topGO...", type = "message")
          
          # Get all genes for the selected organism
          if (is.null(all_genes)) {
            # Use default background (all genes in the annotation database)
            all_genes <- AnnotationDbi::keys(annotation_db, keytype = "ENTREZID")
          } else {
            # Custom background already prepared above
            showNotification(paste("Using custom background with", length(all_genes), "genes for topGO analysis"),
                             type = "message", duration = 3)
          }
          
          # Create a factor vector to indicate which genes are in our list (1 = in list, 0 = not in list)
          gene_list_vector <- factor(as.integer(all_genes %in% mapped_genes))
          names(gene_list_vector) <- all_genes
          
          showNotification("Building topGO data object...", type = "message")
          
          # Create topGOdata object with proper parameter values
          topgo_data <- new("topGOdata",
                            ontology = input$proteomics_topgo_ontology,
                            allGenes = gene_list_vector,
                            nodeSize = input$proteomics_topgo_nodesize,
                            annot = topGO::annFUN.org,
                            mapping = OrgDb_name,
                            ID = "entrez")  # NOTE: use "entrez" (lowercase), not "ENTREZID"
          
          showNotification("Running GO enrichment test...", type = "message")
          
          # Validate algorithm-statistic combination before running
          valid_combinations <- list(
            fisher = c("classic", "elim", "weight", "weight01", "parentchild"),  # Fisher works with ALL algorithms
            ks = c("classic", "elim", "weight01"),                               # Weight algorithm only works with Fisher
            t = c("classic", "elim", "weight01"),                                # Other statistics work with classic, elim, weight01 but NOT parentchild or weight
            globaltest = c("classic", "elim", "weight01"),
            sum = c("classic", "elim", "weight01")
          )
          
          selected_algorithm <- input$proteomics_topgo_algorithm
          selected_statistic <- input$proteomics_topgo_statistic
          
          if (!selected_statistic %in% names(valid_combinations) ||
              !selected_algorithm %in% valid_combinations[[selected_statistic]]) {
            error_msg <- paste("Invalid combination:", selected_algorithm, "algorithm with", selected_statistic,
                               "statistic. Valid algorithms for", selected_statistic, "are:",
                               paste(valid_combinations[[selected_statistic]], collapse = ", "))
            showNotification(error_msg, type = "error", duration = 10)
            session$sendCustomMessage(type = "hideTopGOProgress", message = list())
            return(NULL)
          }
          
          # Run GO enrichment test with selected statistic
          topgo_result <- topGO::runTest(topgo_data,
                                         algorithm = selected_algorithm,
                                         statistic = selected_statistic)
          
          # Extract results table using the selected statistic
          showNotification("Generating results table...", type = "message")
          
          # Create named argument for GenTable based on selected statistic
          genTable_args <- list(
            topgo_data,
            orderBy = selected_statistic,
            ranksOf = selected_statistic,
            topNodes = input$proteomics_topgo_terms,
            numChar = 1000  # Prevent truncation of term names (default is 40 characters)
          )
          genTable_args[[selected_statistic]] <- topgo_result
          
          result_table <- do.call(topGO::GenTable, genTable_args)
          
          # Add adjusted p-values - convert the statistic column to numeric
          stat_col_values <- as.numeric(result_table[[selected_statistic]])
          result_table$padj <- p.adjust(stat_col_values, method = input$proteomics_topgo_correction)
          
          # Package results as a list to match other tools' return format
          enrichment_results <- list(
            data = topgo_data,
            test = topgo_result,
            table = result_table,
            statistic = selected_statistic  # Store the statistic used for plot generation
          )
          
          # Create visualization function for GO graph
          if (nrow(result_table) > 0) {
            # Store the topGO data and result objects for flexible graph generation
            enrichment_results$topgo_data <- topgo_data
            enrichment_results$topgo_result <- topgo_result
            enrichment_results$topgo_algorithm <- selected_algorithm
            enrichment_results$topgo_statistic <- selected_statistic
            
            # Store graph command for visualization with user-selectable parameters
            enrichment_results$go_graph_cmd <- function(selected_terms = NULL,
                                                        first_sig_nodes = 5,
                                                        use_info = "all") {
              cat("Inside go_graph_cmd function\n")
              cat("Selected terms:", selected_terms, "\n")
              cat("First sig nodes:", first_sig_nodes, "\n")
              cat("Use info:", use_info, "\n")
              
              # If specific terms are selected, use them; otherwise use top significant nodes
              if (!is.null(selected_terms) && length(selected_terms) > 0) {
                cat("Using selected terms for graph\n")
                # Validate that selected terms exist in the results
                available_terms <- enrichment_results$table$GO.ID
                valid_terms <- selected_terms[selected_terms %in% available_terms]
                cat("Valid terms:", valid_terms, "\n")
                
                if (length(valid_terms) > 0) {
                  # Create a custom score vector with selected terms having high significance
                  all_terms <- names(score(topgo_result))
                  custom_scores <- score(topgo_result)
                  
                  # Set selected terms to have very high significance (low p-values)
                  # to ensure they are included in the graph
                  for (term in valid_terms) {
                    if (term %in% names(custom_scores)) {
                      custom_scores[term] <- min(custom_scores[term], 1e-10)
                    }
                  }
                  
                  cat("Calling showSigOfNodes with custom scores\n")
                  # Show graph with custom scores that prioritize selected terms
                  topGO::showSigOfNodes(topgo_data, custom_scores,
                                        firstSigNodes = max(first_sig_nodes, length(valid_terms)),
                                        useInfo = use_info)
                } else {
                  cat("No valid terms, using standard graph\n")
                  # Fallback to standard graph if no valid terms selected
                  topGO::showSigOfNodes(topgo_data, score(topgo_result),
                                        firstSigNodes = first_sig_nodes,
                                        useInfo = use_info)
                }
              } else {
                cat("No terms selected, using standard graph\n")
                # Standard graph with top significant nodes
                topGO::showSigOfNodes(topgo_data, score(topgo_result),
                                      firstSigNodes = first_sig_nodes,
                                      useInfo = use_info)
              }
              cat("showSigOfNodes call completed\n")
              # topGO::showSigOfNodes generates plots directly in the active graphics device
            }
            
            # Generate a barplot for visualization using the correct statistic column
            enrichment_results$barplot <- function() {
              # Sort by significance using the correct column name
              stat_col_values <- as.numeric(result_table[[selected_statistic]])
              ordered_indices <- order(stat_col_values)
              ordered_table <- result_table[ordered_indices, ]
              top_n <- min(20, nrow(ordered_table))
              top_terms <- head(ordered_table, top_n)
              
              # Create barplot data using the correct statistic
              stat_values <- as.numeric(top_terms[[selected_statistic]])
              
              # Handle different statistics appropriately
              if (selected_statistic %in% c("fisher", "ks", "t")) {
                # These are p-values, so use -log10 transformation
                y_values <- -log10(stat_values)
                y_label <- paste0("-log10(", selected_statistic, " p-value)")
              } else if (selected_statistic %in% c("globaltest", "sum")) {
                # These may have different scales, use raw values
                y_values <- stat_values
                y_label <- paste(selected_statistic, "statistic")
              } else {
                # Default to -log10 transformation
                y_values <- -log10(stat_values)
                y_label <- paste0("-log10(", selected_statistic, ")")
              }
              
              # Create barplot data
              barplot_data <- data.frame(
                Term = top_terms$Term,  # Use only the Term name, without GO ID prefix
                StatValue = y_values,
                stringsAsFactors = FALSE
              )
              
              # Create barplot
              p <- ggplot(barplot_data,
                          aes(x = StatValue, y = reorder(Term, StatValue))) +
                geom_bar(stat = "identity", fill = "steelblue") +
                scale_x_continuous(expand = expansion(mult = c(0, 0.1)), breaks = scales::pretty_breaks(n = 5)) +
                labs(title = paste("Top Enriched GO Terms -", input$proteomics_topgo_ontology),
                     subtitle = paste("Algorithm:", selected_algorithm, "| Statistic:", selected_statistic),
                     x = y_label,
                     y = "") +
                theme_bw() +
                theme(axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                      axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                      axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                      plot.title = element_text(size = 16, color = "black", face = "bold"),
                      plot.subtitle = element_text(size = 12, color = "gray50", face = "bold")) +
                scale_y_discrete(labels = function(x) {
                  # Wrap long labels to multiple lines
                  sapply(x, function(label) {
                    paste(strwrap(label, width = 50), collapse = "\n")
                  })
                })
              
              # Return the plot object
              return(p)
            }
          }
          
          # Print debug info for table size verification
          print(paste("topGO result table has", nrow(result_table), "rows"))
          
          showNotification("topGO analysis complete!", type = "message", duration = 3)
          
          # Hide progress bar after successful completion
          session$sendCustomMessage(type = "hideTopGOProgress", message = list())
          
          # Store enrichment results (don't return immediately for caching)
          # enrichment_results is already set above
          
        }, error = function(e) {
          # Detailed error reporting
          err_message <- paste("topGO error:", e$message)
          showNotification(err_message, type = "error", duration = 10)
          message(err_message)
          print(traceback())  # Print stack trace for debugging
          # Hide progress bar on error
          session$sendCustomMessage(type = "hideTopGOProgress", message = list())
          enrichment_results <- NULL
        })
      }
      
      # Cache the enrichment results if they were computed (not from cache)
      if (is.null(cached_enrichment) && !is.null(enrichment_results)) {
        cat("Caching enrichment results for", input$proteomics_tool, "\n")
        store_enrichment_in_cache(enrichment_cache_key, enrichment_results,
                                  fold_change_data,
                                  if(exists("original_fold_change_data")) original_fold_change_data else NULL)
        showNotification("Enrichment results cached for faster future access", type = "message", duration = 2)
      }
    } # End of cache check
    
    # Save the enrichment results
    values$proteomics_results <- enrichment_results
    
    # Also store in standard location for download handler compatibility
    proteomics_values$enrichment_results <- enrichment_results
    
    # Cache Entrez-formatted gene expression data specifically for pathview
    # This eliminates the need for ID conversion during pathview generation
    if (!is.null(fold_change_data) && length(fold_change_data) > 0) {
      # Create a separate pathview-specific gene data with Entrez IDs as names
      pathview_data <- fold_change_data
      
      # Ensure names are Entrez IDs for pathview
      if(input$proteomics_id_type != "ENTREZID" && exists("gene_ids") && nrow(gene_ids) > 0) {
        # Double-check that we have the correct Entrez ID mapping
        name_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
        
        # If fold_change_data has original names, convert them to Entrez
        current_names <- names(pathview_data)
        if(!all(grepl("^[0-9]+$", current_names))) {
          # Names are not Entrez IDs, convert them
          entrez_mapped <- name_to_entrez[current_names]
          valid_entrez <- !is.na(entrez_mapped)
          
          if(sum(valid_entrez) > 0) {
            pathview_data <- pathview_data[valid_entrez]
            names(pathview_data) <- entrez_mapped[valid_entrez]
            cat("Created pathview data with", length(pathview_data), "genes using Entrez IDs\n")
            cat("Sample Entrez IDs:", head(names(pathview_data), 5), "\n")
          }
        }
      }
      
      proteomics_values$pathview_gene_data <- pathview_data
      cat("Cached", length(pathview_data), "genes for pathview with proper Entrez IDs\n")
    }
    
    # Store fold change data for other purposes
    proteomics_values$fold_change_data <- fold_change_data
    
    # Mark analysis as complete
    proteomics_values$analysis_running <- FALSE
    
    # Reset KEGG pathway click inputs to prevent old clicks from firing
    session$sendCustomMessage(type = "resetKeggInputs", message = list())
    
    # Update the Input Summary tab
    proteomics_values$input_summary_message <- result$message
    proteomics_values$sample_genes <- head(result$genes, 10)
    
    # Update the Enrichment Results table
    output$proteomics_results_table <- DT::renderDataTable({
      if (is.null(enrichment_results)) return(NULL)
      
      if (input$proteomics_tool == "gprofiler" && !is.null(enrichment_results$result)) {
        # Clean the data frame and column names
        df <- enrichment_results$result
        if (ncol(df) > 0 && nrow(df) > 0) {
          # Remove any columns with empty, NA, or whitespace-only names
          empty_col_idx <- which(colnames(df) == "" | is.na(colnames(df)) | trimws(colnames(df)) == "" | colnames(df) == " ")
          if (length(empty_col_idx) > 0) {
            df <- df[, -empty_col_idx, drop = FALSE]
          }
          
          # Clean remaining column names to remove any problematic characters
          colnames(df) <- make.names(colnames(df), unique = TRUE)
          
          DT::datatable(df, options = list(scrollX = TRUE, pageLength = 10))
        } else {
          DT::datatable(data.frame(Message = "No enrichment results found."),
                        options = list(scrollX = TRUE, pageLength = 10))
        }
      } else if (input$proteomics_tool == "clusterprofiler") {
        # Safely convert enrichment results to data frame with validation
        df <- NULL
        tryCatch({
          if (!is.null(enrichment_results) && nrow(enrichment_results) > 0) {
            df <- as.data.frame(enrichment_results)
          }
        }, error = function(e) {
          cat("Error converting ClusterProfiler results to data frame:", e$message, "\n")
        })
        
        if (!is.null(df) && ncol(df) > 0 && nrow(df) > 0) {
          # Remove any columns with empty, NA, or whitespace-only names
          empty_col_idx <- which(colnames(df) == "" | is.na(colnames(df)) | trimws(colnames(df)) == "" | colnames(df) == " ")
          if (length(empty_col_idx) > 0) {
            df <- df[, -empty_col_idx, drop = FALSE]
          }
          
          # Clean remaining column names to remove any problematic characters
          colnames(df) <- make.names(colnames(df), unique = TRUE)
          
          # Check if this is a KEGG analysis and make pathway IDs clickable
          if (input$proteomics_cp_analysis %in% c("kegg", "gsea_kegg", "kegg_module", "gsea_kegg_module")) {
            # Find the ID column (usually "ID" or "pathway")
            id_col <- NULL
            if ("ID" %in% colnames(df)) {
              id_col <- "ID"
            } else if ("pathway" %in% colnames(df)) {
              id_col <- "pathway"
            }
            
            if (!is.null(id_col)) {
              # Store original pathway IDs before creating links
              original_ids <- df[[id_col]]
              
              # Create clickable links for KEGG pathway IDs
              df[[id_col]] <- paste0('<a href="#" class="kegg-pathway-link" data-pathway-id="',
                                     original_ids, '">', original_ids, '</a>')
              
              # Find the column index of the ID column
              id_col_index <- which(colnames(df) == id_col)
              
              # Create logical vector for escape parameter (TRUE = escape, FALSE = don't escape)
              escape_vector <- rep(TRUE, ncol(df))
              escape_vector[id_col_index] <- FALSE
              
              # Debug: print a sample of the transformed cell to confirm anchor generation
              if (length(original_ids) > 0) {
                cat("KEGG clickable debug - first transformed ID cell:\n")
                cat(df[[id_col]][1], "\n")
              }
              
              # 0-based index for JS (DataTables uses 0-based indices in some APIs if needed)
              id_col_js_index <- id_col_index - 1
              
              # Create datatable with selective escaping
              DT::datatable(df,
                            options = list(scrollX = TRUE, pageLength = 10,
                                           columnDefs = list(list(className = 'dt-center', targets = '_all'))),
                            escape = FALSE,  # Force all columns to not escape HTML
                            callback = DT::JS(paste0("
                             // Enhanced fallback: convert escaped HTML to clickable links on table initialization and redraw
                             function convertToLinks() {
                               table.column(", id_col_js_index, ").nodes().to$().each(function() {
                                 var $cell = $(this);
                                 var cellContent = $cell.html().trim();

                                 // Case 1: HTML was escaped and shows as literal text
                                 if(cellContent.indexOf('&lt;a ') === 0 || cellContent.indexOf('<a ') === 0) {
                                   // Decode HTML entities if needed
                                   var decodedHTML = cellContent
                                     .replace(/&lt;/g, '<')
                                     .replace(/&gt;/g, '>')
                                     .replace(/&quot;/g, '\"')
                                     .replace(/&#x27;/g, \"'\")
                                     .replace(/&amp;/g, '&');
                                   $cell.html(decodedHTML);
                                 }
                                 // Case 2: Only pathway/module ID visible, create link
                                 else if(/^(K\\d{5}|M\\d{5})$/i.test(cellContent) && !$cell.find('a.kegg-pathway-link').length) {
                                   $cell.html('<a href=\"#\" class=\"kegg-pathway-link\" data-pathway-id=\"' + cellContent + '\">' + cellContent + '</a>');
                                 }
                               });
                             }

                             // Run conversion on initial draw and redraws
                             table.on('draw.dt', convertToLinks);
                             convertToLinks(); // Also run immediately

                             table.on('click', '.kegg-pathway-link', function(e) {
                               e.preventDefault();
                               var pathwayId = $(this).data('pathway-id');

                               // Get the row data to extract gene IDs
                               var rowData = table.row($(this).closest('tr')).data();
                               var geneIds = '';

                               // Extract gene IDs from the appropriate column
                               // For ORA results: look for 'geneID' column
                               // For GSEA results: look for 'core_enrichment' column
                               if (rowData && Array.isArray(rowData)) {
                                 var geneIdIndex = -1;
                                 var coreEnrichmentIndex = -1;

                                 // Find column indices by examining table headers
                                 table.columns().header().to$().each(function(index) {
                                   var headerText = $(this).text().trim();
                                   if (headerText === 'geneID') {
                                     geneIdIndex = index;
                                   } else if (headerText === 'core_enrichment') {
                                     coreEnrichmentIndex = index;
                                   }
                                 });

                                 // Extract gene IDs from the appropriate column
                                 if (geneIdIndex >= 0 && rowData[geneIdIndex]) {
                                   geneIds = rowData[geneIdIndex];
                                 } else if (coreEnrichmentIndex >= 0 && rowData[coreEnrichmentIndex]) {
                                   geneIds = rowData[coreEnrichmentIndex];
                                 }

                                 // Clean up gene IDs by removing HTML tags if present
                                 if (geneIds) {
                                   geneIds = geneIds.replace(/<[^>]*>/g, '').trim();
                                 }
                               }

                               // Check if this is a KEGG module (M#####) or pathway (K#####)
                               if(/^M\\d{5}$/i.test(pathwayId)) {
                                 // For KEGG modules, open direct URL
                                 window.open('https://www.kegg.jp/module/' + pathwayId, '_blank');
                               } else {
                                 // For KEGG pathways, use browseKEGG via Shiny and pass gene IDs
                                 Shiny.setInputValue('kegg_pathway_clicked', pathwayId, {priority: 'event'});
                                 Shiny.setInputValue('kegg_pathway_genes', geneIds, {priority: 'event'});
                               }
                             });
                           ")))
            } else {
              # No ID column found, render normally
              DT::datatable(df, options = list(scrollX = TRUE, pageLength = 10))
            }
          } else {
            # Non-KEGG analysis, render normally
            DT::datatable(df, options = list(scrollX = TRUE, pageLength = 10))
          }
        } else {
          DT::datatable(data.frame(Message = "No enrichment results found."),
                        options = list(scrollX = TRUE, pageLength = 10))
        }
      } else if (input$proteomics_tool == "enrichr") {
        res <- do.call(rbind, lapply(enrichment_results, function(x) {
          if (is.data.frame(x)) x else NULL
        }))
        if (!is.null(res) && ncol(res) > 0 && nrow(res) > 0) {
          # Remove any columns with empty, NA, or whitespace-only names
          empty_col_idx <- which(colnames(res) == "" | is.na(colnames(res)) | trimws(colnames(res)) == "" | colnames(res) == " ")
          if (length(empty_col_idx) > 0) {
            res <- res[, -empty_col_idx, drop = FALSE]
          }
          
          # Clean remaining column names to remove any problematic characters
          colnames(res) <- make.names(colnames(res), unique = TRUE)
          
          DT::datatable(res, options = list(scrollX = TRUE, pageLength = 10))
        } else {
          DT::datatable(data.frame(Message = "No enrichment results found."),
                        options = list(scrollX = TRUE, pageLength = 10))
        }
      } else if (input$proteomics_tool == "reactomepa") {
        df <- as.data.frame(enrichment_results)
        if (ncol(df) > 0 && nrow(df) > 0) {
          # Remove any columns with empty, NA, or whitespace-only names
          empty_col_idx <- which(colnames(df) == "" | is.na(colnames(df)) | trimws(colnames(df)) == "" | colnames(df) == " ")
          if (length(empty_col_idx) > 0) {
            df <- df[, -empty_col_idx, drop = FALSE]
          }
          
          # Clean remaining column names to remove any problematic characters
          colnames(df) <- make.names(colnames(df), unique = TRUE)
          
          DT::datatable(df, options = list(scrollX = TRUE, pageLength = 10))
        } else {
          DT::datatable(data.frame(Message = "No enrichment results found."),
                        options = list(scrollX = TRUE, pageLength = 10))
        }
      }
      else if (input$proteomics_tool == "topgo") {
        # Now properly check for table in the results
        if (!is.null(enrichment_results) && !is.null(enrichment_results$table)) {
          # Print debug info
          print(paste("Found topGO table with", nrow(enrichment_results$table), "rows"))
          df <- enrichment_results$table
          if (ncol(df) > 0 && nrow(df) > 0) {
            # Remove any columns with empty, NA, or whitespace-only names
            empty_col_idx <- which(colnames(df) == "" | is.na(colnames(df)) | trimws(colnames(df)) == "" | colnames(df) == " ")
            if (length(empty_col_idx) > 0) {
              df <- df[, -empty_col_idx, drop = FALSE]
            }
            
            # Clean remaining column names to remove any problematic characters
            colnames(df) <- make.names(colnames(df), unique = TRUE)
            
            DT::datatable(df, options = list(scrollX = TRUE, pageLength = 10))
          } else {
            DT::datatable(data.frame(Message = "No topGO results found."),
                          options = list(scrollX = TRUE, pageLength = 10))
          }
        }
        else {
          # Print exactly what's in the results for debugging
          print("topGO results structure:")
          print(str(enrichment_results))
          DT::datatable(data.frame(Message = "No topGO results available."),
                        options = list(scrollX = TRUE, pageLength = 10))
        }
      }
      else {
        DT::datatable(data.frame(Message = "No results available or tool not implemented."),
                      options = list(scrollX = TRUE, pageLength = 10))
      }
    })
    
    # Observer for KEGG pathway clicks - triggers browseKEGG function
    # Observer for KEGG pathway clicks - triggers browseKEGG function (pathways only, not modules)
    observeEvent(input$kegg_pathway_clicked, {
      req(input$kegg_pathway_clicked)
      
      # Check if analysis is currently running - if so, ignore clicks
      if (!is.null(proteomics_values$analysis_running) && proteomics_values$analysis_running) {
        return()
      }
      
      # Check if this click happened too soon after clearing (within 2 seconds)
      if (!is.null(proteomics_values$last_kegg_pathway_cleared)) {
        time_since_clear <- as.numeric(difftime(Sys.time(), proteomics_values$last_kegg_pathway_cleared, units = "secs"))
        if (time_since_clear < 2) {
          cat("Ignoring KEGG pathway click - too soon after clearing\n")
          return()
        }
      }
      
      # Ignore if the input is empty or just whitespace
      if (is.null(input$kegg_pathway_clicked) || trimws(input$kegg_pathway_clicked) == "") {
        return()
      }
      
      # Check if the clicked pathway exists in current enrichment results
      pathway_found <- FALSE
      if (!is.null(values$proteomics_results)) {
        tryCatch({
          results_df <- as.data.frame(values$proteomics_results)
          if (!is.null(results_df) && nrow(results_df) > 0) {
            # Check both ID and pathway columns for the clicked pathway
            id_columns <- c("ID", "pathway")
            for (col in id_columns) {
              if (col %in% colnames(results_df)) {
                if (input$kegg_pathway_clicked %in% results_df[[col]]) {
                  pathway_found <- TRUE
                  break
                }
              }
            }
          }
        }, error = function(e) {
          cat("Error checking pathway in results:", e$message, "\n")
        })
      }
      
      # Show notification that pathway is being opened (only for pathways, not modules)
      showNotification(paste("Opening KEGG pathway:", input$kegg_pathway_clicked),
                       type = "message", duration = 3)
      
      # Call browseKEGG function with the clicked pathway ID (only for K##### pathways)
      tryCatch({
        if (requireNamespace("clusterProfiler", quietly = TRUE)) {
          # Check if enrichment_results exists and has the necessary data
          if (!is.null(values$proteomics_results)) {
            # Get gene IDs if available from the JavaScript
            gene_ids <- NULL
            if (!is.null(input$kegg_pathway_genes) && input$kegg_pathway_genes != "") {
              # Split gene IDs and clean them
              gene_ids <- unlist(strsplit(input$kegg_pathway_genes, "/"))
              gene_ids <- trimws(gene_ids)
              gene_ids <- gene_ids[gene_ids != ""]
            }
            
            # Call browseKEGG with or without gene IDs
            if (!is.null(gene_ids) && length(gene_ids) > 0) {
              clusterProfiler::browseKEGG(values$proteomics_results, input$kegg_pathway_clicked)
            } else {
              clusterProfiler::browseKEGG(values$proteomics_results, input$kegg_pathway_clicked)
            }
            
            # Mark that a pathway was successfully browsed
            proteomics_values$last_kegg_browse_time <- Sys.time()
            
          } else {
            showNotification("No enrichment results available for pathway browsing.",
                             type = "warning", duration = 5)
          }
        } else {
          showNotification("ClusterProfiler package not available for pathway browsing.",
                           type = "error", duration = 5)
        }
      }, error = function(e) {
      })
      
      # Clear the input immediately after processing to prevent repeated firing
      updateTextInput(session, "kegg_pathway_clicked", value = "")
    })
    
    # Dynamic UI output for proteomics plot (handles both static and interactive plots)
    output$proteomics_plot_output <- renderUI({
      # Determine if we need interactive plot (g:Profiler Manhattan plot in interactive mode)
      if (input$proteomics_tool == "gprofiler" &&
          input$proteomics_plot_type == "manhattan" &&
          !is.null(proteomics_manhattan_mode()) &&
          proteomics_manhattan_mode() == "interactive") {
        # Interactive plot for g:Profiler Manhattan
        plotly::plotlyOutput("proteomics_plot_interactive", height = "600px")
      } else {
        # Regular static plot for all other cases (including static Manhattan plots)
        plotOutput("proteomics_plot", height = "600px")
      }
    })
    
    # Interactive plot for g:Profiler Manhattan plot
    output$proteomics_plot_interactive <- plotly::renderPlotly({
      enrichment_results <- proteomics_values$enrichment_results
      if (is.null(enrichment_results)) return(NULL)
      
      # Only render if this is g:Profiler and Manhattan plot
      if (input$proteomics_tool != "gprofiler" || input$proteomics_plot_type != "manhattan") {
        return(NULL)
      }
      
      # Check if we have any results to plot
      if (is.null(enrichment_results$result) || nrow(enrichment_results$result) == 0) {
        return(NULL)
      }
      
      # Parse highlight terms from user input
      highlight_terms <- NULL
      if (!is.null(input$proteomics_gprofiler_highlight_terms) &&
          length(input$proteomics_gprofiler_highlight_terms) > 0) {
        # Input is now a vector of selected term IDs
        highlight_terms <- input$proteomics_gprofiler_highlight_terms
      }
      
      tryCatch({
        # Get capped setting
        capped_setting <- if (!is.null(input$proteomics_manhattan_capped)) input$proteomics_manhattan_capped else TRUE
        
        # Create interactive Manhattan plot
        p <- gprofiler2::gostplot(enrichment_results,
                                  capped = capped_setting,
                                  interactive = TRUE)
        
        # Note: Highlighting will be handled differently for interactive plots
        # The publish_gostplot function returns a static plot, so we'll maintain the base interactive plot
        # and let users see highlights through the selection interface
        
        return(p)
      }, error = function(e) {
        # Fallback to regular static plot if interactive fails
        return(plotly::ggplotly(
          ggplot() +
            geom_text(aes(x = 0.5, y = 0.5, label = paste("Error creating interactive plot:", e$message)), size = 4) +
            xlim(0, 1) + ylim(0, 1) +
            theme_void()
        ))
      })
    })
    
    # Render a basic visualization for the enrichment results with caching
    output$proteomics_plot <- renderPlot({ 
      enrichment_results <- proteomics_values$enrichment_results
      if (is.null(enrichment_results)) return(NULL)
      
      # Determine number of terms to show for cache key
      # Use helper function to get number of rows for different result types
      total_rows <- get_enrichment_results_nrow(enrichment_results, input$proteomics_tool)
      num_terms <- min(30, total_rows)
      if (!is.null(input$proteomics_top_terms)) {
        num_terms <- min(as.numeric(input$proteomics_top_terms), total_rows)
      }
      
      # Create cache key for this specific plot configuration
      cache_key <- create_proteomics_plot_cache_key(
        tool = input$proteomics_tool,
        plot_type = input$proteomics_plot_type,
        enrichment_results = enrichment_results,
        num_terms = num_terms,
        fold_change_data = proteomics_values$fold_change_data,
        color_theme = input$proteomics_plot_color %||% "default",
        highlight_terms = proteomics_values$highlight_terms
      )
      
      # Check cache first (skip for topGO GO graphs as they use base R plots)
      if (!(input$proteomics_tool == "topgo" && input$proteomics_plot_type == "gograph")) {
        cached_plot <- get_proteomics_plot_from_cache(cache_key)
        if (!is.null(cached_plot)) {
          cat("Using cached proteomics plot\n")
          replayPlot(cached_plot)
          return(invisible())
        }
      } else {
        cat("Skipping cache check for topGO GO graph (base R plot)\n")
      }
      
      # If not cached, generate the plot and record it
      cat("Generating new proteomics plot and caching it\n")
      
      # Get font sizes from inputs or use defaults
      title_size <- if(!is.null(input$enrichment_title_size)) input$enrichment_title_size else 14
      axis_title_size <- if(!is.null(input$enrichment_axis_title_size)) input$enrichment_axis_title_size else 12
      axis_text_size <- if(!is.null(input$enrichment_axis_text_size)) input$enrichment_axis_text_size else 10
      legend_text_size <- if(!is.null(input$enrichment_legend_text_size)) input$enrichment_legend_text_size else 12
      legend_title_size <- max(8, legend_text_size - 2)  # Legend title slightly smaller than legend text
      
      # g:Profiler visualization
      if (input$proteomics_tool == "gprofiler" && !is.null(enrichment_results$result)) {
        # Check if we have any results to plot
        if (nrow(enrichment_results$result) == 0) {
          plot.new()
          text(0.5, 0.5, "No enrichment results found with current settings.")
          return()
        }
        
        # Manhattan plot for g:Profiler
        if (input$proteomics_plot_type == "manhattan") {
          # Check if this is static mode
          if (!is.null(proteomics_manhattan_mode()) && proteomics_manhattan_mode() == "static") {
            # Get capped setting
            capped_setting <- if (!is.null(input$proteomics_manhattan_capped)) input$proteomics_manhattan_capped else TRUE
            
            # Create base Manhattan plot
            p <- gprofiler2::gostplot(enrichment_results, capped = capped_setting, interactive = FALSE)
            
            # Add highlighting if terms are specified and valid
            if (!is.null(input$proteomics_gprofiler_highlight_terms) &&
                length(input$proteomics_gprofiler_highlight_terms) > 0) {
              # Check which terms exist in the results
              available_terms <- NULL
              if (!is.null(enrichment_results$result) && "term_id" %in% colnames(enrichment_results$result)) {
                available_terms <- enrichment_results$result$term_id
              }
              
              if (!is.null(available_terms)) {
                valid_highlight_terms <- input$proteomics_gprofiler_highlight_terms[input$proteomics_gprofiler_highlight_terms %in% available_terms]
                
                if (length(valid_highlight_terms) > 0) {
                  # Use publish_gostplot with highlighting for static plots
                  p <- gprofiler2::publish_gostplot(p,
                                                    highlight_terms = valid_highlight_terms,
                                                    width = 10,
                                                    height = 8)
                  # publish_gostplot returns a plot that can be displayed directly
                  print(p)
                  return()
                }
              }
            }
            
            # If no highlighting, just show the base plot
            print(p)
            return()
          } else {
            # Interactive mode - show placeholder
            plot.new()
            text(0.5, 0.5, "Interactive Manhattan plot is displayed above", cex = 1.2)
            return()
          }
        }
        else if (input$proteomics_plot_type == "barplot") {
          # Get results data
          gost_results <- enrichment_results$result
          
          # Check if we have any results to plot
          if (is.null(gost_results) || nrow(gost_results) == 0) {
            plot.new()
            text(0.5, 0.5, "No enrichment results found with current settings.")
            return()
          }
          
          # Calculate enrichment ratio
          gost_results$enrichment_ratio <- gost_results$intersection_size / gost_results$term_size
          
          # Add negative log10 of adjusted p-value for color gradient
          gost_results$negative_log10_of_adjusted_p_value <- -log10(gost_results$p_value)
          
          # Sort by significance and take top terms
          top_n <- min(as.numeric(input$proteomics_top_terms), nrow(gost_results))
          top_results <- head(gost_results[order(gost_results$p_value), ], top_n)
          
          # Create term labels from term names (without GO identifiers)
          top_results$term_label <- top_results$term_name
          # Trim term names if too long
          top_results$term_label <- substr(top_results$term_label, 1, 60)
          
          # Create bar plot using ggplot2
          p <- ggplot(top_results,
                      aes(x = enrichment_ratio,
                          y = reorder(term_label, negative_log10_of_adjusted_p_value),
                          fill = negative_log10_of_adjusted_p_value)) +
            geom_bar(stat = "identity") +
            geom_text(aes(label = intersection_size, hjust = -0.2),
                      color = "black", size = axis_text_size * 0.45, fontface = "bold") +
            coord_cartesian(clip = "off") +
            scale_x_continuous(expand = expansion(mult = c(0, 0.1))) +
            scale_fill_gradient(low = "orange", high = "red", name = "-log10(P-adj)") +
            guides(fill = guide_colorbar(title.position = "top")) +
            labs(title = "Enrichment Overview",
                 x = "Enrichment Ratio",
                 y = "") +
            theme_bw(base_size = title_size) +
            theme(
              axis.text.y = element_text(face = "bold", size = axis_title_size, color = "black"),
              axis.line.x = element_line(size = 1),
              axis.ticks.x = element_line(size = 1),
              axis.text.x = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.title.x = element_text(color = "black", face = "bold", size = title_size),
              plot.title = element_text(face = "bold", size = title_size + 2),
              legend.title = element_text(face = "bold", size = legend_title_size),
              legend.position = c(0.85, 0.4),
              legend.key.width = unit(0.5, "cm"),
              panel.grid = element_blank(),
              legend.text = element_text(face = "bold", size = legend_text_size))
          
          # If ggprism is loaded, use that theme instead but preserve our customization
          if (requireNamespace("ggprism", quietly = TRUE)) {
            p <- p + ggprism::theme_prism(base_size = title_size) +
              theme(axis.text.y = element_text(face = "bold", size = axis_title_size, color = "black"),
                    axis.text.x = element_text(size = axis_title_size, face = "bold", color = "black"),
                    axis.title.x = element_text(color = "black", face = "bold", size = title_size),
                    plot.title = element_text(face = "bold", size = title_size + 2),
                    legend.title = element_text(face = "bold", size = legend_title_size),
                    legend.position = c(0.85, 0.4),
                    legend.key.width = unit(0.5, "cm"),
                    panel.grid = element_blank(),
                    legend.text = element_text(face = "bold", size = legend_text_size))
          }
          
          return(p)
        }
      }
      # ClusterProfiler visualization - FIXED IMPLEMENTATION
      else if (input$proteomics_tool == "clusterprofiler") {
        tryCatch({
          # Check if we have valid results to plot
          if (is.null(enrichment_results) || get_enrichment_results_nrow(enrichment_results, input$proteomics_tool) == 0) {
            plot.new()
            text(0.5, 0.5, "No significant enrichment results found", cex = 1.5)
            return()
          }
          
          # Get font sizes from inputs or use defaults
          title_size <- if(!is.null(input$enrichment_title_size)) input$enrichment_title_size else 14
          axis_title_size <- if(!is.null(input$enrichment_axis_title_size)) input$enrichment_axis_title_size else 12
          axis_text_size <- if(!is.null(input$enrichment_axis_text_size)) input$enrichment_axis_text_size else 10
          legend_text_size <- if(!is.null(input$enrichment_legend_text_size)) input$enrichment_legend_text_size else 12
          legend_title_size <- max(8, legend_text_size - 2)  # Legend title slightly smaller than legend text
          
          # Determine number of terms to show
          total_rows <- get_enrichment_results_nrow(enrichment_results, input$proteomics_tool)
          num_terms <- min(30, total_rows)
          if (!is.null(input$proteomics_top_terms)) {
            num_terms <- min(as.numeric(input$proteomics_top_terms), total_rows)
          }
          
          # Generate the appropriate plot based on plot type
          if (input$proteomics_plot_type == "dotplot") {
            return(enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
                     theme(
                       # Make all text black and bold
                       axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                       axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                       axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                       axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                       plot.title = element_text(size = title_size, color = "black", face = "bold"),
                       legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                       legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                       # Add black border
                       panel.border = element_rect(color = "black", fill = NA, size = 1),
                       axis.line = element_line(color = "black", size = 0.5),
                       # Remove gridlines
                       panel.grid.major = element_blank(),
                       panel.grid.minor = element_blank()
                     ))
          }
          else if (input$proteomics_plot_type == "barplot") {
            # Create barplot using enrichplot barplot function (more compatible)
            tryCatch({
              if (requireNamespace("enrichplot", quietly = TRUE)) {
                library(enrichplot)
                
                # Check if this is GSEA results - enrichplot::barplot doesn't work well with GSEA
                enrichment_df_check <- as.data.frame(enrichment_results)
                if ("NES" %in% colnames(enrichment_df_check)) {
                  # For GSEA results, use custom ggplot2 implementation
                  enrichment_df <- head(enrichment_df_check[order(enrichment_df_check$p.adjust), ], num_terms)
                  
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  # Use p.adjust for color gradient instead of fixed colors
                  enrichment_df$neg_log_padj <- -log10(enrichment_df$p.adjust)
                  
                  return(ggplot(enrichment_df, aes(x = NES, y = reorder(Description, abs(NES)), fill = neg_log_padj)) +
                           geom_bar(stat = "identity") +
                           scale_fill_gradient(low = "lightblue", high = "darkred", name = "-log10(P.adj)") +
                           labs(title = "GSEA Enrichment Analysis", x = "Normalized Enrichment Score (NES)", y = y_label) +
                           theme_bw() +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                             legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                } else {
                  # For ORA results, use enrichplot::barplot
                    return(barplot(enrichment_results, showCategory = num_terms) +
                             scale_x_continuous(breaks = scales::pretty_breaks(n = 5)) +
                             theme(
                               axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                               axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                               axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                               axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                               plot.title = element_text(size = title_size, color = "black", face = "bold"),
                               legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                               legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                               panel.border = element_rect(color = "black", fill = NA, size = 1),
                               axis.line = element_line(color = "black", size = 0.5),
                               panel.grid.major = element_blank(),
                               panel.grid.minor = element_blank()
                             ))
                }
              } else {
                # Fallback to custom ggplot2 barplot
                enrichment_df <- as.data.frame(enrichment_results)
                enrichment_df <- head(enrichment_df[order(enrichment_df$p.adjust), ], num_terms)
                
                # Check if this is GSEA results (has NES column) or ORA results (has Count column)
                if ("NES" %in% colnames(enrichment_df)) {
                  # GSEA results - use NES (Normalized Enrichment Score)
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  # Use p.adjust for color gradient instead of fixed colors
                  enrichment_df$neg_log_padj <- -log10(enrichment_df$p.adjust)
                  
                  return(ggplot(enrichment_df, aes(x = NES, y = reorder(Description, abs(NES)), fill = neg_log_padj)) +
                           geom_bar(stat = "identity") +
                           scale_fill_gradient(low = "lightblue", high = "darkred", name = "-log10(P.adj)") +
                           labs(title = "GSEA Enrichment Analysis", x = "Normalized Enrichment Score (NES)", y = y_label) +
                           theme_bw() +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                             legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                } else if ("Count" %in% colnames(enrichment_df)) {
                  # ORA results - use Count
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  return(ggplot(enrichment_df, aes(x = Count, y = reorder(Description, Count))) +
                           geom_bar(stat = "identity", fill = "steelblue") +
                           labs(title = "Enrichment Analysis", x = "Gene Count", y = y_label) +
                           theme_bw() +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                } else if ("setSize" %in% colnames(enrichment_df)) {
                  # Alternative GSEA format - use setSize
