                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  return(ggplot(enrichment_df, aes(x = setSize, y = reorder(Description, setSize))) +
                           geom_bar(stat = "identity", fill = "steelblue") +
                           labs(title = "Enrichment Analysis", x = "Set Size", y = y_label) +
                           theme_bw() +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                } else {
                  # Fallback - use -log10(p.adjust) if no suitable count column is found
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  enrichment_df$neg_log_pval <- -log10(enrichment_df$p.adjust)
                  return(ggplot(enrichment_df, aes(x = neg_log_pval, y = reorder(Description, neg_log_pval))) +
                           geom_bar(stat = "identity", fill = "steelblue") +
                           labs(title = "Enrichment Analysis", x = "-log10(Adjusted P-value)", y = y_label) +
                           theme_bw() +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                }
              }
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error creating barplot:", e$message), cex = 1.2)
            })
          }
          else if (input$proteomics_plot_type == "heatplot") {
            # Create heatplot using enrichplot's heatplot
            # Check if this is GSEA results first
            enrichment_df_check <- as.data.frame(enrichment_results)
            is_gsea <- "NES" %in% colnames(enrichment_df_check)
            
            # For GSEA, only use fold change data if the ranking metric requires fold change
            # Log2 Fold Change and Signed p-value require fold change data
            requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
              input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
            should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
            
            if (should_use_fold_change) {
              # Use the fold change data
              fc_data_to_use <- proteomics_values$fold_change_data
              
              # For GSEA results, ensure the heatplot works properly with fold change data
              if (is_gsea) {
                tryCatch({
                  # Add debug information
                  cat("Creating GSEA heatplot with fold change data\n")
                  cat("Ranking metric:", input$proteomics_gsea_ranking_metric, "\n")
                  cat("Fold change data length:", length(proteomics_values$fold_change_data), "\n")
                  cat("Enrichment results rows:", nrow(enrichment_df_check), "\n")
                  
                  return(enrichplot::heatplot(enrichment_results, showCategory = num_terms,
                                              foldChange = fc_data_to_use) +
                           theme(
                             # Make all text black and bold
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                             legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                             # Add black border
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             # Remove gridlines
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                }, error = function(e) {
                  cat("Error with GSEA heatplot:", e$message, "\n")
                  # Fallback to dotplot for GSEA if heatplot fails
                  return(enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
                           labs(title = "Heatplot failed - showing dotplot instead") +
                           theme(
                             axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                             axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                             axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                             plot.title = element_text(size = title_size, color = "black", face = "bold"),
                             legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                             legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                             panel.border = element_rect(color = "black", fill = NA, size = 1),
                             axis.line = element_line(color = "black", size = 0.5),
                             panel.grid.major = element_blank(),
                             panel.grid.minor = element_blank()
                           ))
                })
              }
            } else {
              # No fold change data - use regular heatplot
              return(enrichplot::heatplot(enrichment_results, showCategory = num_terms) +
                       theme(
                         # Make all text black and bold
                         axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                         axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                         axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                         axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                         plot.title = element_text(size = title_size, color = "black", face = "bold"),
                         legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                         legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                         # Add black border
                         panel.border = element_rect(color = "black", fill = NA, size = 1),
                         axis.line = element_line(color = "black", size = 0.5),
                         # Remove gridlines
                         panel.grid.major = element_blank(),
                         panel.grid.minor = element_blank()
                       ))
            }
          }
          else if (input$proteomics_plot_type == "treeplot") {
            # Create treeplot using enrichplot's treeplot
            # Treeplot often requires term similarity calculation like enrichmap
            tryCatch({
              # Compute pairwise term similarities if needed
              enrichment_results_with_sim <- enrichplot::pairwise_termsim(enrichment_results)
              
              # Check if this is GSEA results first and if ranking metric requires fold change
              enrichment_df_check <- as.data.frame(enrichment_results)
              is_gsea <- "NES" %in% colnames(enrichment_df_check)
              requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
                input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
              should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
              
              # For GSEA, use fold change data only if the ranking metric requires it
              if(should_use_fold_change) {
                return(enrichplot::treeplot(enrichment_results_with_sim,
                                            showCategory = num_terms,
                                            foldChange = proteomics_values$fold_change_data) +
                         theme(
                           # Make all text black and bold
                           plot.title = element_text(size = title_size, color = "black", face = "bold"),
                           legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                           legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                           # Remove all borders and axes for treeplot
                           panel.border = element_blank(),
                           axis.line = element_blank(),
                           axis.text.x = element_blank(),
                           axis.text.y = element_blank(),
                           axis.title.x = element_blank(),
                           axis.title.y = element_blank(),
                           axis.ticks = element_blank(),
                           # Remove gridlines
                           panel.grid.major = element_blank(),
                           panel.grid.minor = element_blank()
                         ))
              } else {
                return(enrichplot::treeplot(enrichment_results_with_sim, showCategory = num_terms) +
                         theme(
                           # Make all text black and bold
                           plot.title = element_text(size = title_size, color = "black", face = "bold"),
                           legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                           legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                           # Remove all borders and axes for treeplot
                           panel.border = element_blank(),
                           axis.line = element_blank(),
                           axis.text.x = element_blank(),
                           axis.text.y = element_blank(),
                           axis.title.x = element_blank(),
                           axis.title.y = element_blank(),
                           axis.ticks = element_blank(),
                           # Remove gridlines
                           panel.grid.major = element_blank(),
                           panel.grid.minor = element_blank()
                         ))
              }
            }, error = function(e) {
              # Fallback to dotplot if treeplot fails
              enrichment_df_check <- as.data.frame(enrichment_results)
              is_gsea <- "NES" %in% colnames(enrichment_df_check)
              requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
                input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
              should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
              
              if(should_use_fold_change) {
                return(enrichplot::dotplot(enrichment_results, showCategory = num_terms,
                                           foldChange = proteomics_values$fold_change_data) +
                         theme(
                           # Make all text black and bold
                           plot.title = element_text(size = title_size, color = "black", face = "bold"),
                           legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                           legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                           # Remove all borders and axes for treeplot fallback
                           panel.border = element_blank(),
                           axis.line = element_blank(),
                           axis.text.x = element_blank(),
                           axis.text.y = element_blank(),
                           axis.title.x = element_blank(),
                           axis.title.y = element_blank(),
                           axis.ticks = element_blank(),
                           # Remove gridlines
                           panel.grid.major = element_blank(),
                           panel.grid.minor = element_blank()
                         ) +
                         labs(title = "Treeplot failed - showing dotplot with fold change instead"))
              } else {
                return(enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
                         theme(
                           # Make all text black and bold
                           plot.title = element_text(size = title_size, color = "black", face = "bold"),
                           legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                           legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                           # Remove all borders and axes for treeplot fallback
                           panel.border = element_blank(),
                           axis.line = element_blank(),
                           axis.text.x = element_blank(),
                           axis.text.y = element_blank(),
                           axis.title.x = element_blank(),
                           axis.title.y = element_blank(),
                           axis.ticks = element_blank(),
                           # Remove gridlines
                           panel.grid.major = element_blank(),
                           panel.grid.minor = element_blank()
                         ) +
                         labs(title = "Treeplot failed - showing dotplot instead"))
              }
            })
          }
          else if (input$proteomics_plot_type == "enrichmap") {
            # Compute pairwise term similarities before using emapplot
            enrichment_results_with_sim <- enrichplot::pairwise_termsim(enrichment_results)
            return(enrichplot::emapplot(enrichment_results_with_sim, showCategory = min(num_terms, 50)))
          }
          else if (input$proteomics_plot_type == "cnetplot") {
            # Check if this is GSEA results first and if ranking metric requires fold change
            enrichment_df_check <- as.data.frame(enrichment_results)
            is_gsea <- "NES" %in% colnames(enrichment_df_check)
            requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
              input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
            should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
            
            if (should_use_fold_change) {
              return(enrichplot::cnetplot(enrichment_results, showCategory = min(num_terms, 10),
                                          foldChange = proteomics_values$fold_change_data))
            } else {
              return(enrichplot::cnetplot(enrichment_results, showCategory = min(num_terms, 10)))
            }
          }
          else if (input$proteomics_plot_type == "upsetplot") {
            # Generate UpSet plot for ClusterProfiler results
            tryCatch({
              # For upsetplot to show expression box plots, we need to use the original enrichment results
              # before any ID mapping modifications, as upsetplot relies on the internal GSEA structure
              
              # Check if we have the original enrichment results stored somewhere
              # If the enrichment_results has been modified for display, we need the original version
              if (exists("enrichment_results_original") && !is.null(enrichment_results_original)) {
                # Use the original enrichment results with ENTREZ IDs and embedded expression data
                return(enrichplot::upsetplot(enrichment_results_original, n = min(num_terms, 20)))
              } else {
                # If no original version is available, use the current enrichment_results
                # This should work if the enrichment_results hasn't been modified
                return(enrichplot::upsetplot(enrichment_results, n = min(num_terms, 20)))
              }
            }, error = function(e) {
              # Fallback to a custom UpSet plot if enrichplot version doesn't support it
              tryCatch({
                # Check if we have the required data structure
                if (!("geneID" %in% colnames(enrichment_results@result))) {
                  plot.new()
                  text(0.5, 0.5, "UpSet plot requires gene ID data.\nPlease use a different plot type.",
                       cex = 1.2, adj = 0.5)
                  return(NULL)
                }
                
                # Extract gene lists from enrichment results
                result_subset <- head(enrichment_results@result, min(num_terms, 10))
                gene_lists <- lapply(result_subset$geneID, function(x) {
                  if (is.na(x) || x == "") return(character(0))
                  strsplit(as.character(x), "/")[[1]]
                })
                
                # Create proper names for gene lists
                if ("Description" %in% colnames(result_subset)) {
                  list_names <- result_subset$Description
                } else if ("ID" %in% colnames(result_subset)) {
                  list_names <- result_subset$ID
                } else {
                  list_names <- paste("Set", seq_along(gene_lists))
                }
                
                # Truncate long names for display
                list_names <- sapply(list_names, function(name) {
                  if (nchar(name) > 30) {
                    paste0(substr(name, 1, 27), "...")
                  } else {
                    name
                  }
                })
                
                names(gene_lists) <- list_names
                
                # Remove empty gene lists
                gene_lists <- gene_lists[sapply(gene_lists, length) > 0]
                
                if (length(gene_lists) == 0) {
                  plot.new()
                  text(0.5, 0.5, "No gene sets available for UpSet plot",
                       cex = 1.2, adj = 0.5)
                  return(NULL)
                }
                
                # Use UpSetR package as fallback
                if (requireNamespace("UpSetR", quietly = TRUE)) {
                  # Create a binary matrix for UpSetR
                  all_genes <- unique(unlist(gene_lists))
                  
                  if (length(all_genes) == 0) {
                    plot.new()
                    text(0.5, 0.5, "No genes found in gene sets",
                         cex = 1.2, adj = 0.5)
                    return(NULL)
                  }
                  
                  upset_data <- data.frame(
                    Gene = all_genes,
                    stringsAsFactors = FALSE
                  )
                  
                  for (i in seq_along(gene_lists)) {
                    set_name <- names(gene_lists)[i]
                    upset_data[[set_name]] <- as.numeric(upset_data$Gene %in% gene_lists[[i]])
                  }
                  
                  return(UpSetR::upset(upset_data,
                                       sets = names(gene_lists),
                                       order.by = "freq",
                                       nsets = min(length(gene_lists), 10),
                                       nintersects = 20,
                                       text.scale = c(1.2, 1, 1, 1, 1.5, 1),
                                       point.size = 2.5,
                                       line.size = 1))
                } else {
                  # Ultimate fallback - show a message
                  plot.new()
                  text(0.5, 0.5, "UpSet plot requires the UpSetR package.\nPlease install it with: install.packages('UpSetR')",
                       cex = 1.2, adj = 0.5)
                  return(NULL)
                }
              }, error = function(e2) {
                plot.new()
                text(0.5, 0.5, paste("Error generating UpSet plot:\n", e2$message), cex = 1, adj = 0.5)
                return(NULL)
              })
            })
          }
          else if (input$proteomics_plot_type == "gseaplot2") {
            # Generate gseaplot2 for ClusterProfiler GSEA results
            plot_result <- tryCatch({
              cat("Generating gseaplot2 plot\n")
              
              # Check if we have GSEA results
              enrichment_df_check <- as.data.frame(enrichment_results)
              if (!("NES" %in% colnames(enrichment_df_check))) {
                cat("No GSEA results found - NES column missing\n")
                plot.new()
                text(0.5, 0.5, "gseaplot2 requires GSEA results.\nPlease use GSEA analysis type.",
                     cex = 1.2, adj = 0.5)
                return(NULL)
              }
              
              cat("GSEA results found, rows:", nrow(enrichment_df_check), "\n")
              
              # Get selected gene sets
              selected_gene_sets <- input$proteomics_gseaplot2_gene_sets
              cat("Selected gene sets:", selected_gene_sets, "\n")
              
              if (is.null(selected_gene_sets) || length(selected_gene_sets) == 0) {
                # Default to top 3 gene sets by significance
                selected_gene_sets <- head(enrichment_df_check$ID, 3)
                cat("Using default gene sets:", selected_gene_sets, "\n")
              }
              
              # Validate that selected gene sets exist in results
              available_sets <- enrichment_df_check$ID
              valid_sets <- selected_gene_sets[selected_gene_sets %in% available_sets]
              cat("Valid gene sets:", valid_sets, "\n")
              
              if (length(valid_sets) == 0) {
                cat("No valid gene sets found\n")
                plot.new()
                text(0.5, 0.5, "No valid gene sets selected for gseaplot2.",
                     cex = 1.2, adj = 0.5)
                return(NULL)
              }
              
              # Prepare gseaplot2 parameters - simplified approach
              subplots <- input$proteomics_gseaplot2_subplots
              
              # Default to showing all subplots if none specified
              if (is.null(subplots) || length(subplots) == 0) {
                subplots <- c("gsea", "expr", "rank")
              }
              
              cat("Selected subplots:", subplots, "\n")
              
              # For gseaplot2, we need to specify which subplots to show
              # The function expects a numeric vector: 1=GSEA, 2=Expression, 3=Ranking
              subplot_indices <- c()
              if ("gsea" %in% subplots) subplot_indices <- c(subplot_indices, 1)
              if ("expr" %in% subplots) subplot_indices <- c(subplot_indices, 2)
              if ("rank" %in% subplots) subplot_indices <- c(subplot_indices, 3)
              
              # Sort to maintain proper order
              subplot_indices <- sort(subplot_indices)
              
              # Create rel_heights vector based on the number of subplots
              base_height <- input$proteomics_gseaplot2_rel_heights %||% 1.5
              
              # For rel_heights, create a vector with the same length as subplot_indices
              # The enrichplot source expects rel_heights to match the length of subplots exactly
              if (length(subplot_indices) == 1) {
                rel_heights_vec <- base_height
              } else if (length(subplot_indices) == 2) {
                # Most common case: two subplots
                rel_heights_vec <- c(base_height, 1.0)
              } else if (length(subplot_indices) == 3) {
                # All three subplots
                rel_heights_vec <- c(base_height, 0.5, 1.0)
              } else {
                # Fallback for any other combination
                rel_heights_vec <- rep(1.0, length(subplot_indices))
              }
              
              cat("Subplot indices:", subplot_indices, "\n")
              cat("Rel heights:", rel_heights_vec, "\n")
              cat("Number of subplots:", length(subplot_indices), "\n")
              
              # Call gseaplot2 with proper parameter handling
              tryCatch({
                cat("Attempting gseaplot2 with subplots:", subplot_indices, "\n")
                cat("Valid gene sets:", valid_sets, "\n")
                cat("Length of valid_sets:", length(valid_sets), "\n")
                cat("Length of subplot_indices:", length(subplot_indices), "\n")
                cat("Length of rel_heights_vec:", length(rel_heights_vec), "\n")
                
                # Prepare colors for multiple gene sets
                colors <- if (length(valid_sets) == 1) {
                  "green"
                } else {
                  # Use different colors for multiple gene sets
                  c("#E495A5", "#86B875", "#7DB0DD", "#F2B866", "#C4A484")[seq_along(valid_sets)]
                }
                
                cat("Colors:", colors, "\n")
                
                # Call gseaplot2 with proper parameter handling
                # According to enrichplot documentation, gseaplot2 accepts vector of geneSetID
                # and handles multiple gene sets with different colors automatically
                tryCatch({
                  cat("Attempting gseaplot2 with all selected gene sets\n")
                  
                  p <- enrichplot::gseaplot2(
                    x = enrichment_results,
                    geneSetID = valid_sets,
                    title = paste("GSEA Plot:", paste(valid_sets, collapse = ", ")),
                    color = colors,
                    base_size = input$proteomics_gseaplot2_base_size %||% 11,
                    rel_heights = rel_heights_vec,
                    pvalue_table = input$proteomics_gseaplot2_pvalue_table %||% FALSE,
                    ES_geom = "line",
                    subplots = subplot_indices
                  )
                  
                  cat("gseaplot2 with multiple gene sets successful\n")
                  
                }, error = function(e) {
                  cat("Multiple gene sets failed, trying conservative approach:", e$message, "\n")
                  
                  # Fallback: if multiple gene sets fail, try with single gene set
                  if (length(valid_sets) > 1) {
                    cat("Falling back to single gene set approach\n")
                    gene_set_to_use <- valid_sets[1]
                    
                    p <<- enrichplot::gseaplot2(
                      x = enrichment_results,
                      geneSetID = gene_set_to_use,
                      title = paste("GSEA Plot:", gene_set_to_use),
                      color = "green",
                      base_size = input$proteomics_gseaplot2_base_size %||% 11,
                      rel_heights = rel_heights_vec,
                      pvalue_table = input$proteomics_gseaplot2_pvalue_table %||% FALSE,
                      ES_geom = "line",
                      subplots = subplot_indices
                    )
                    cat("Fallback to single gene set successful\n")
                  } else {
                    # Re-throw the error if we only had one gene set
                    stop(e$message)
                  }
                })
                
                cat("gseaplot2 created successfully\n")
                
                # Return the plot with default enrichplot styling
                return(p)
                
              }, error = function(e) {
                cat("gseaplot2 failed:", e$message, "\n")
                
                # Try with minimal parameters as fallback
                tryCatch({
                  cat("Trying with minimal parameters\n")
                  p <- enrichplot::gseaplot2(
                    enrichment_results,
                    geneSetID = valid_sets[1],  # Use only first gene set
                    subplots = subplot_indices,
                    title = paste("GSEA Plot:", valid_sets[1]),
                    base_size = input$proteomics_gseaplot2_base_size %||% 11
                  )
                  
                  return(p)
                }, error = function(e2) {
                  cat("Minimal parameters also failed:", e2$message, "\n")
                  
                  # Final fallback - show error message
                  plot.new()
                  text(0.5, 0.6, "Error generating gseaplot2:", cex = 1.2, adj = 0.5)
                  text(0.5, 0.5, e$message, cex = 1, adj = 0.5, col = "red")
                  text(0.5, 0.4, "Please check your GSEA results and try again.", cex = 1, adj = 0.5)
                  return(NULL)
                })
              })
              
            }, error = function(e) {
              # Fallback with informative error message
              plot.new()
              text(0.5, 0.6, "Error generating gseaplot2:", cex = 1.2, adj = 0.5)
              text(0.5, 0.5, e$message, cex = 1, adj = 0.5, col = "red")
              text(0.5, 0.4, "Please check your GSEA results and try again.", cex = 1, adj = 0.5)
              return(NULL)
            })
            
            # Return the plot result (ggplot object or NULL)
            return(plot_result)
          }
          else {
            # Default fallback
            return(enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
                     theme(
                       # Make all text black and bold
                       axis.text.x = element_text(size = 10, color = "black", face = "bold"),
                       axis.text.y = element_text(size = 10, color = "black", face = "bold"),
                       axis.title.x = element_text(size = 12, color = "black", face = "bold"),
                       axis.title.y = element_text(size = 12, color = "black", face = "bold"),
                       plot.title = element_text(size = 14, color = "black", face = "bold"),
                       legend.title = element_text(size = 10, color = "black", face = "bold"),
                       legend.text = element_text(size = 9, color = "black", face = "bold"),
                       # Add black border
                       panel.border = element_rect(color = "black", fill = NA, size = 1),
                       axis.line = element_line(color = "black", size = 0.5),
                       # Remove gridlines
                       panel.grid.major = element_blank(),
                       panel.grid.minor = element_blank()
                     ))
          }
        }, error = function(e) {
          # Handle errors gracefully
          plot.new()
          text(0.5, 0.5, paste("Error generating plot:", e$message), cex = 1)
        })
      }
      # Enrichr visualization
      else if (input$proteomics_tool == "enrichr") {
        plot_result <- tryCatch({
          req(input$proteomics_enrichr_db_to_plot)
          
          # Check if we have any results
          if (is.null(enrichment_results) || length(enrichment_results) == 0) {
            plot.new()
            text(0.5, 0.5, "No enrichment results found", cex = 1.5)
            return(NULL)
          }
          
          # Get results for the user-selected database
          db_name <- input$proteomics_enrichr_db_to_plot
          if (!db_name %in% names(enrichment_results)) {
            plot.new()
            text(0.5, 0.5, paste("Database", db_name, "not found in results"), cex = 1.5)
            return(NULL)
          }
          
          db_results <- enrichment_results[[db_name]]

          # Apply the same font size controls as the clusterProfiler plots
          title_size <- if(!is.null(input$enrichment_title_size)) input$enrichment_title_size else 14
          axis_title_size <- if(!is.null(input$enrichment_axis_title_size)) input$enrichment_axis_title_size else 12
          axis_text_size <- if(!is.null(input$enrichment_axis_text_size)) input$enrichment_axis_text_size else 10
          legend_text_size <- if(!is.null(input$enrichment_legend_text_size)) input$enrichment_legend_text_size else 12
          legend_title_size <- max(8, legend_text_size - 2)
          
          if (nrow(db_results) == 0) {
            plot.new()
            text(0.5, 0.5, paste("No significant results for", db_name), cex = 1.5)
            return(NULL)
          }
          
          # Sort by adjusted p-value and take top results
          db_results <- db_results[order(db_results$Adjusted.P.value), ]
          top_n <- min(as.numeric(input$proteomics_top_terms %||% 15), nrow(db_results))
          top_results <- head(db_results, top_n)
          
          # Clean Term names by removing GO identifiers (GO:xxxxxxx) for better readability
          top_results$Term <- gsub("\\s*\\(GO:\\d+\\)\\s*$", "", top_results$Term)
          
          # Use the plotEnrich function from enrichR package
          if (input$proteomics_plot_type == "barplot") {
            # Create a bar plot using custom ggplot2 (more reliable than plotEnrich)
            tryCatch({
              return(ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                             y = reorder(Term, -log10(Adjusted.P.value)))) +
                       geom_bar(stat = "identity", fill = "steelblue") +
                       labs(title = paste("Enrichr Bar Plot:", db_name),
                            x = "-log10(Adjusted P-value)",
                            y = "Term") +
                       theme_bw() +
                       theme(
                         axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                         axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                         axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                         axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                         plot.title = element_text(size = title_size, color = "black", face = "bold"),
                         legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                         legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                         panel.border = element_rect(color = "black", fill = NA, size = 1),
                         panel.grid.major = element_blank(),
                         panel.grid.minor = element_blank()
                       ))
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error creating barplot:", e$message), cex = 1.2)
              return(NULL)
            })
          }
          else if (input$proteomics_plot_type == "dotplot") {
            # Create a custom dot plot for EnrichR results
            return(ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                           y = reorder(Term, -log10(Adjusted.P.value)),
                                           size = Combined.Score)) +
                     geom_point(color = "steelblue", alpha = 0.7) +
                     scale_size_continuous(name = "Combined Score") +
                     labs(title = paste("Enrichr Dot Plot:", db_name),
                          x = "-log10(Adjusted P-value)",
                          y = "Term") +
                     theme_bw() +
                     theme(
                       axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                       axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                       axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                       axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                       plot.title = element_text(size = 16, color = "black", face = "bold"),
                       legend.title = element_text(size = 12, color = "black", face = "bold"),
                       legend.text = element_text(size = 11, color = "black", face = "bold"),
                       panel.border = element_rect(color = "black", fill = NA, size = 1),
                       panel.grid.major = element_blank(),
                       panel.grid.minor = element_blank()
                     ))
          }
          else if (input$proteomics_plot_type == "enrichplot") {
            # Create an enrichment plot showing both p-value and combined score
            # Extract gene count from Overlap column (format: "5/123")
            top_results$gene_count <- as.numeric(gsub("/.*", "", top_results$Overlap))
            
            return(ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                           y = Combined.Score,
                                           size = gene_count)) +
                     geom_point(color = "steelblue", alpha = 0.7) +
                     scale_size_continuous(name = "Gene Count") +
                     labs(title = paste("Enrichr Enrichment Plot:", db_name),
                          x = "-log10(Adjusted P-value)",
                          y = "Combined Score") +
                     theme_bw() +
                     theme(
                       axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                       axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                       axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                       axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                       plot.title = element_text(size = 16, color = "black", face = "bold"),
                       legend.title = element_text(size = 12, color = "black", face = "bold"),
                       legend.text = element_text(size = 11, color = "black", face = "bold"),
                       panel.border = element_rect(color = "black", fill = NA, size = 1),
                       panel.grid.major = element_blank(),
                       panel.grid.minor = element_blank()
                     ))
          }
          else {
            # Default to bar plot using custom ggplot2
            tryCatch({
              return(ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                             y = reorder(Term, -log10(Adjusted.P.value)))) +
                       geom_bar(stat = "identity", fill = "steelblue") +
                       labs(title = paste("Enrichr Bar Plot:", db_name),
                            x = "-log10(Adjusted P-value)",
                            y = "Term") +
                       theme_bw() +
                       theme(
                         axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                         axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                         axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                         axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                         plot.title = element_text(size = 16, color = "black", face = "bold"),
                         legend.title = element_text(size = 12, color = "black", face = "bold"),
                         legend.text = element_text(size = 11, color = "black", face = "bold"),
                         panel.border = element_rect(color = "black", fill = NA, size = 1),
                         panel.grid.major = element_blank(),
                         panel.grid.minor = element_blank()
                       ))
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error creating plot:", e$message), cex = 1.2)
              return(NULL)
            })
          }
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, paste("Error generating Enrichr plot:", e$message), cex = 1)
          NULL
        })
        
        # Return the plot result (ggplot object or NULL)
        return(plot_result)
      }
      
      # ReactomePA visualization
      else if (input$proteomics_tool == "reactomepa") {
        tryCatch({
          if (is.null(enrichment_results) || get_enrichment_results_nrow(enrichment_results, input$proteomics_tool) == 0) {
            plot.new()
            text(0.5, 0.5, "No significant Reactome pathways found", cex = 1.5)
            return()
          }
          # Determine number of pathways to show
          total_rows <- get_enrichment_results_nrow(enrichment_results, input$proteomics_tool)
          num_terms <- min(30, total_rows)
          if (!is.null(input$proteomics_top_terms)) {
            num_terms <- min(as.numeric(input$proteomics_top_terms), total_rows)
          }
          
          # Generate appropriate visualization
          if (input$proteomics_plot_type == "dotplot") {
            # Use enrichplot::dotplot to avoid namespace conflicts
            enrichplot::dotplot(enrichment_results, showCategory = num_terms)
          }
          else if (input$proteomics_plot_type == "barplot") {
            # FIX 1: Create a custom barplot using ggplot2 to avoid namespace issues
            df <- as.data.frame(enrichment_results)[1:num_terms, ]
            
            # Create barplot
            ggplot(df, aes(x = reorder(Description, -log10(p.adjust)), y = -log10(p.adjust))) +
              geom_bar(stat = "identity", fill = "steelblue") +
              coord_flip() +
              labs(title = "Enriched Reactome Pathways",
                   x = "Pathway",
                   y = "-log10(adjusted p-value)") +
              theme_bw() +
              theme(axis.text.y = element_text(size = 10))
          }
          else if (input$proteomics_plot_type == "enrichmap") {
            # FIX 2: First compute pairwise term similarities before using emapplot
            enrichment_results_with_sim <- enrichplot::pairwise_termsim(enrichment_results)
            enrichplot::emapplot(enrichment_results_with_sim, showCategory = min(num_terms, 30))
          }
          else if (input$proteomics_plot_type == "cnetplot") {
            # Check if this is GSEA results first and if ranking metric requires fold change
            enrichment_df_check <- as.data.frame(enrichment_results)
            is_gsea <- "NES" %in% colnames(enrichment_df_check)
            requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
              input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
            should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
            
            if (should_use_fold_change) {
              # Use enrichplot::cnetplot with fold change data for GSEA
              enrichplot::cnetplot(enrichment_results, showCategory = min(num_terms, 10),
                                   foldChange = proteomics_values$fold_change_data)
            } else {
              # Use enrichplot::cnetplot to avoid namespace conflicts
              enrichplot::cnetplot(enrichment_results, showCategory = min(num_terms, 10))
            }
          }
          else if (input$proteomics_plot_type == "pathview") {
            # FIX 3: Completely revised pathway viewer with better error handling for UI integration
            output$proteomics_plot <- renderUI({
              # Get pathway IDs from the results
              pathway_ids <- enrichment_results@result$ID[1:min(3, nrow(enrichment_results@result))]
              pathway_names <- enrichment_results@result$Description[1:min(3, nrow(enrichment_results@result))]
              
              # Use the top pathway for display
              pathway_id <- pathway_ids[1]
              pathway_name <- pathway_names[1]
              
              # Create container for both plot and link
              tagList(
                # Plot output inside the UI
                plotOutput("proteomics_pathway_plot", height = "600px"),
                
                # Add clickable link and info below the plot
                wellPanel(
                  h4("Pathway Information:"),
                  p(strong("Name: "), pathway_name),
                  p(strong("ID: "), pathway_id),
                  p(strong("Direct link: "),
                    a(href = paste0("https://reactome.org/PathwayBrowser/#/", pathway_id),
                      "View pathway on Reactome",
                      target = "_blank")
                  ),
                  style = "margin-top: 10px; font-size: 14px;"
                )
              )
            })
            
            # Create the actual pathway plot in a nested renderPlot
            output$proteomics_pathway_plot <- renderPlot({ 
              # Get pathway IDs from the results
              pathway_ids <- enrichment_results@result$ID[1:min(3, nrow(enrichment_results@result))]
              pathway_names <- enrichment_results@result$Description[1:min(3, nrow(enrichment_results@result))]
              
              # Use the Reactome diagram viewer API
              pathway_id <- pathway_ids[1]
              
              # Construct direct URL to the PNG static image
              pathway_url <- paste0("https://reactome.org/ContentService/diagram/",
                                    pathway_id, "/png")
              
              # Download the pathway image with proper headers
              tryCatch({
                # Ensure required packages
                if (!requireNamespace("httr", quietly = TRUE)) install.packages("httr")
                if (!requireNamespace("png", quietly = TRUE)) install.packages("png")
                
                # Create a temporary file
                tmp_file <- tempfile(fileext = ".png")
                
                # Use httr with proper headers and error handling
                response <- httr::GET(
                  pathway_url,
                  httr::add_headers(Accept = "image/png"),
                  httr::timeout(10)
                )
                
                # Check if response is successful and contains a PNG
                if (httr::status_code(response) == 200 &&
                    grepl("image/png", httr::headers(response)$`content-type`, fixed = TRUE)) {
                  
                  # Save response content to temporary file
                  writeBin(httr::content(response, "raw"), tmp_file)
                  
                  if (file.exists(tmp_file) && file.size(tmp_file) > 100) {
                    # Read the image
                    img <- png::readPNG(tmp_file)
                    
                    # Display the image
                    plot.new()
                    par(mar = c(0.5, 0.5, 2, 0.5))
                    plot.window(xlim = c(0, 1), ylim = c(0, 1))
                    rasterImage(img, 0, 0, 1, 1)
                    title(main = paste("Reactome Pathway:", pathway_names[1]),
                          cex.main = 1.2, font.main = 2)
                  } else {
                    plot.new()
                    text(0.5, 0.5, "Invalid pathway image received", cex = 1.5)
                  }
                } else {
                  # Display an error message if image couldn't be retrieved
                  plot.new()
                  text(0.5, 0.5, "Could not retrieve pathway image from Reactome", cex = 1.5)
                  text(0.5, 0.4, paste("Pathway:", pathway_id), cex = 1)
                  text(0.5, 0.3, "Try visiting Reactome website directly", cex = 1)
                }
              }, error = function(e) {
                # Error handling with informative message
                plot.new()
                text(0.5, 0.7, "Reactome Pathway Visualization", cex = 1.8, font = 2)
                text(0.5, 0.6, paste("Pathway:", pathway_names[1]), cex = 1.3)
                text(0.5, 0.5, "Could not fetch the pathway diagram", cex = 1.2)
                text(0.5, 0.4, "Please use the link below to view this pathway online", cex = 1.2)
                text(0.5, 0.25, paste("Error:", e$message), cex = 1, col = "red")
              })
            }, res = UI_PLOT_RES)
            
            # Return NULL since we're using renderUI
            return(NULL)
          }
          else {
            # Default visualization - use enrichplot::dotplot to avoid namespace conflicts
            enrichplot::dotplot(enrichment_results, showCategory = num_terms)
          }
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, paste("Error generating ReactomePA plot:", e$message), cex = 1.2)
        })
      }
      
      # topGO visualization - MAIN RENDER SECTION
      else if (input$proteomics_tool == "topgo") {
        tryCatch({
          req(enrichment_results)
          
          if (input$proteomics_plot_type == "barplot") {
            # Use the barplot function stored in results
            if (!is.null(enrichment_results$barplot)) {
              plot_result <- enrichment_results$barplot()
              if (!is.null(plot_result)) {
                return(plot_result)
              } else {
                # If the stored function returns NULL, fall back to direct rendering
                enrichment_results$barplot()
              }
            } else {
              # Create a basic barplot if stored function not available
              result_table <- enrichment_results$table
              
              # Get the statistic that was used (stored in enrichment_results)
              used_statistic <- enrichment_results$statistic %||% "fisher"  # fallback to fisher
              
              # Check if the statistic column exists
              if (!used_statistic %in% colnames(result_table)) {
                # Try to find a suitable column
                possible_stats <- c("fisher", "ks", "t", "globaltest", "sum")
                found_stat <- NULL
                for (stat in possible_stats) {
                  if (stat %in% colnames(result_table)) {
                    found_stat <- stat
                    break
                  }
                }
                used_statistic <- found_stat %||% "fisher"
              }
              
              # Order by the correct statistic column
              if (used_statistic %in% colnames(result_table)) {
                stat_values <- as.numeric(result_table[[used_statistic]])
                ordered_indices <- order(stat_values)
                ordered_table <- result_table[ordered_indices, ]
              } else {
                ordered_table <- result_table  # Use as-is if no valid statistic column found
              }
              
              top_n <- min(20, nrow(ordered_table))
              top_terms <- head(ordered_table, top_n)
              
              # Create appropriate y-values based on statistic type
              if (used_statistic %in% colnames(top_terms)) {
                stat_values <- as.numeric(top_terms[[used_statistic]])
                
                if (used_statistic %in% c("fisher", "ks", "t")) {
                  y_values <- -log10(stat_values)
                  y_label <- paste0("-log10(", used_statistic, " p-value)")
                } else {
                  y_values <- stat_values
                  y_label <- paste(used_statistic, "statistic")
                }
              } else {
                # Fallback if no statistic column found
                y_values <- seq_along(top_terms$GO.ID)
                y_label <- "Rank"
              }
              
              barplot_data <- data.frame(
                Term = top_terms$Term,  # Use only the Term name, without GO ID prefix
                StatValue = y_values,
                stringsAsFactors = FALSE
              )
              
              return(ggplot(barplot_data, aes(x = StatValue, y = reorder(Term, StatValue))) +
                       geom_bar(stat = "identity", fill = "steelblue") +
                       labs(title = paste("Top Enriched GO Terms -",
                                          input$proteomics_topgo_ontology),
                            subtitle = paste("Statistic:", used_statistic),
                            x = y_label,
                            y = "") +
                       theme_bw() +
                       theme(axis.text.y = element_text(size = 10),
                             plot.subtitle = element_text(size = 10, color = "gray50")) +
                       scale_y_discrete(labels = function(x) {
                         # Wrap long labels to multiple lines
                         sapply(x, function(label) {
                           paste(strwrap(label, width = 50), collapse = "\n")
                          })
                       }))
            }
          } else if (input$proteomics_plot_type == "gograph") {
            # Generate GO graph with user-selected parameters
            if (!is.null(enrichment_results$go_graph_cmd)) {
              # Get user selections for graph parameters
              selected_terms <- input$proteomics_topgo_graph_terms
              first_sig_nodes <- input$proteomics_topgo_first_sig_nodes %||% 5
              use_info <- input$proteomics_topgo_use_info %||% "all"
              
              cat("Generating topGO GO graph with terms:", selected_terms, "\n")
              cat("First sig nodes:", first_sig_nodes, "Use info:", use_info, "\n")
              
              # For base R plots from topGO, we need to ensure the plot is properly generated
              tryCatch({
                # Call the stored function with user parameters
                # topGO::showSigOfNodes creates a base plot that will render in renderPlot
                enrichment_results$go_graph_cmd(
                  selected_terms = selected_terms,
                  first_sig_nodes = first_sig_nodes,
                  use_info = use_info
                )
                cat("topGO GO graph generation completed\n")
                # For base R plots, we don't return anything - the plot is already created
              }, error = function(e) {
                cat("Error in topGO GO graph generation:", e$message, "\n")
                plot.new()
                text(0.5, 0.6, "Error generating GO graph:", cex = 1.2, adj = 0.5)
                text(0.5, 0.4, e$message, cex = 1, adj = 0.5, col = "red")
              })
            } else {
              cat("go_graph_cmd not available in enrichment_results\n")
              plot.new()
              text(0.5, 0.5, "GO graph visualization not available")
            }
          } else {
            # Default fallback - create a simple table visualization
            result_table <- enrichment_results$table
            plot.new()
            title("topGO Results")
            grid::grid.table(head(result_table, 10))
          }
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, paste("Error generating topGO plot:", e$message), cex = 1)
        })
      }
      
      # Record and cache the generated plot (skip for topGO GO graphs as they use base R plots)
      if (!(input$proteomics_tool == "topgo" && input$proteomics_plot_type == "gograph")) {
        tryCatch({
          recorded_plot <- recordPlot()
          if (!is.null(recorded_plot)) {
            store_proteomics_plot_in_cache(cache_key, recorded_plot)
            cat("Successfully cached proteomics plot\n")
          }
        }, error = function(e) {
          cat("Failed to cache proteomics plot:", e$message, "\n")
        })
      } else {
        cat("Skipping cache for topGO GO graph (base R plot)\n")
      }
    })
    
    # Render network view if applicable with caching
    output$proteomics_network_plot <- renderPlot({ 
      if (is.null(enrichment_results)) return(NULL)
      
      # Skip pathview rendering here as it's handled separately
      if (!is.null(input$proteomics_network_type) && input$proteomics_network_type == "pathview") {
        return(NULL)
      }
      
      # Create cache key for network plot
      network_cache_key <- create_proteomics_plot_cache_key(
        tool = paste0(input$proteomics_tool, "_network"),
        plot_type = input$proteomics_network_type %||% "cnetplot",
        enrichment_results = enrichment_results,
        num_terms = input$proteomics_network_terms %||% 10,
        fold_change_data = proteomics_values$fold_change_data,
        color_theme = "network",
        highlight_terms = NULL  # Network plots don't use highlight terms
      )
      
      # Check cache first
      cached_network_plot <- get_from_cache(proteomics_values$network_plots, network_cache_key)
      if (!is.null(cached_network_plot)) {
        cat("Using cached proteomics network plot\n")
        replayPlot(cached_network_plot)
        return()
      }
      
      cat("Generating new proteomics network plot and caching it\n")
      
      if (input$proteomics_tool == "clusterprofiler") {
        enrichplot::cnetplot(enrichment_results, foldChange = NULL, showCategory = input$proteomics_network_terms)
      } else {
        plot.new()
        text(0.5, 0.5, "Network view is not available for the selected tool.")
      }
      
      # Record and cache the generated network plot
      tryCatch({
        recorded_plot <- recordPlot()
        if (!is.null(recorded_plot)) {
          proteomics_values$network_plots <- store_in_cache(proteomics_values$network_plots, network_cache_key, recorded_plot)
          cat("Successfully cached proteomics network plot\n")
        }
      }, error = function(e) {
        cat("Failed to cache proteomics network plot:", e$message, "\n")
      })
    }, res = UI_PLOT_RES)
    
    # Update pathview pathway choices when enrichment results change
    observe({
      if (!is.null(enrichment_results) &&
          input$proteomics_tool == "clusterprofiler" &&
          input$proteomics_cp_analysis %in% c("kegg", "gsea_kegg")) {
        
        # Extract KEGG pathway IDs from enrichment results
        tryCatch({
          results_df <- as.data.frame(enrichment_results)
          
          if (nrow(results_df) > 0) {
            # Get pathway IDs and descriptions
            pathway_ids <- results_df$ID
            pathway_descriptions <- results_df$Description
            
            # Filter for KEGG pathways (should start with species code + pathway number)
            valid_pathways <- grep("^[a-z]{2,3}[0-9]{5}$", pathway_ids, value = TRUE)
            
            if (length(valid_pathways) > 0) {
              # Create named vector for dropdown
              pathway_choices <- setNames(valid_pathways,
                                          paste0(valid_pathways, " - ",
                                                 pathway_descriptions[match(valid_pathways, pathway_ids)]))
              
              updateSelectInput(session, "pathview_pathway_select",
                                choices = pathway_choices,
                                selected = valid_pathways[1])
            } else {
              updateSelectInput(session, "pathview_pathway_select",
                                choices = list("No KEGG pathways found" = ""),
                                selected = "")
            }
          }
        }, error = function(e) {
          cat("Error updating pathview pathway choices:", e$message, "\n")
          updateSelectInput(session, "pathview_pathway_select",
                            choices = list("Error loading pathways" = ""),
                            selected = "")
        })
      } else {
        updateSelectInput(session, "pathview_pathway_select",
                          choices = list("KEGG analysis required" = ""),
                          selected = "")
      }
    })
    
    # Generate pathview visualization
    observeEvent(input$generate_pathview, {
      req(input$pathview_pathway_select)
      req(values$proteomics_results)
      req(proteomics_values$fold_change_data)
      
      if (input$pathview_pathway_select == "" || input$pathview_pathway_select == "No KEGG pathways found") {
        showNotification("Please select a valid KEGG pathway.", type = "warning")
        return()
      }
      
      # Validate that this is actually a KEGG pathway
      if (!grepl("^[a-z]{2,3}[0-9]{5}$", input$pathview_pathway_select)) {
        showNotification("Invalid KEGG pathway ID format.", type = "warning")
        return()
      }
      
      withProgress(message = "Generating pathview visualization...", {
        tryCatch({
          # Reset any previously stored pathview outputs
          proteomics_values$pathview_image_path <- NULL
          proteomics_values$pathview_output_path <- NULL
          proteomics_values$pathview_output_type <- NULL

          # Check if pathview package is available
          if (!requireNamespace("pathview", quietly = TRUE)) {
            showNotification("pathview package is not installed. Please install it from Bioconductor.",
                             type = "error", duration = 10)
            return()
          }

          # Graphviz rendering requires Rgraphviz (Bioconductor)
          if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") {
            if (!requireNamespace("Rgraphviz", quietly = TRUE)) {
              showNotification(
                "Graphviz engine requires the Bioconductor package 'Rgraphviz'. Please install it, then retry.",
                type = "error", duration = 10
              )
              return()
            }

            # Graphviz mode also relies on KEGGgraph helpers/data (e.g., KEGGEdgeSubtype)
            if (!requireNamespace("KEGGgraph", quietly = TRUE)) {
              showNotification(
                "Graphviz engine requires the Bioconductor package 'KEGGgraph'. Please install it, then retry.",
                type = "error", duration = 10
              )
              return()
            }
          }
          
          # Load pathview data including bods object
          # pathview may look for `bods` via normal symbol lookup, so load into .GlobalEnv
          tryCatch({
            utils::data("bods", package = "pathview", envir = .GlobalEnv)
          }, error = function(e) {
            cat("Note: Could not load pathview::bods dataset:", e$message, "\n")
          }, res = UI_PLOT_RES)

          # Some pathview internals (Graphviz route) expect KEGGgraph datasets via symbol lookup
          if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") {
            tryCatch({
              utils::data("KEGGEdgeSubtype", package = "KEGGgraph", envir = .GlobalEnv)
            }, error = function(e) {
              cat("Note: Could not load KEGGgraph::KEGGEdgeSubtype dataset:", e$message, "\n")
            }, res = UI_PLOT_RES)
          }
          
          # Get gene data for pathview - use cached Entrez-formatted data
          # This eliminates the need for inefficient ID conversion
          if (!is.null(proteomics_values$pathview_gene_data) && length(proteomics_values$pathview_gene_data) > 0) {
            # Use pre-computed Entrez-formatted gene data from enrichment analysis
            gene_data <- proteomics_values$pathview_gene_data
            cat("Using cached Entrez-formatted gene data for pathview\n")
            cat("Number of genes:", length(gene_data), "\n")
          } else {
            # Fallback to original method if cached data is not available
            gene_data <- proteomics_values$fold_change_data
            
            if (is.null(gene_data) || length(gene_data) == 0) {
              showNotification("No gene expression data available for pathview.", type = "warning")
              return()
            }
            
            cat("Using fallback gene data, may require ID conversion\n")
          }
          
          # Debug: Check what type of gene data we have
          cat("Original gene data structure:\n")
          cat("Length:", length(gene_data), "\n")
          cat("Names (first 10):", head(names(gene_data), 10), "\n")
          cat("Values (first 10):", head(gene_data, 10), "\n")
          cat("Class:", class(gene_data), "\n")
          cat("Is named vector:", !is.null(names(gene_data)), "\n")
          
          # Ensure gene_data is a named numeric vector (required by pathview)
          if (!is.numeric(gene_data)) {
            cat("Converting gene_data to numeric\n")
            gene_data <- as.numeric(gene_data)
          }
          
          # Ensure names are preserved
          if (is.null(names(gene_data)) && !is.null(proteomics_values$pathview_gene_data)) {
            names(gene_data) <- names(proteomics_values$pathview_gene_data)
            cat("Restored gene names from cached data\n")
          }
          
          # For pathview, we need Entrez gene IDs as names
          # Check if current names are Entrez IDs (numeric) or if we're using cached Entrez data
          current_names <- names(gene_data)
          are_entrez <- all(grepl("^[0-9]+$", current_names[!is.na(current_names)]))
          
          # Skip ID conversion if we're using cached Entrez data or names are already Entrez IDs
          if (!is.null(proteomics_values$pathview_gene_data) && identical(gene_data, proteomics_values$pathview_gene_data)) {
            cat("Using cached Entrez-formatted data - checking ID format\n")
            # Double-check that cached data actually has Entrez IDs
            if(all(grepl("^[0-9]+$", names(gene_data)))) {
              are_entrez <- TRUE  # Force skip of conversion logic
              cat("Confirmed: cached data has valid Entrez IDs\n")
            } else {
              cat("Warning: cached data has gene symbols, not Entrez IDs - will convert\n")
              are_entrez <- FALSE  # Force conversion
            }
          }
          
          if (!are_entrez) {
            # Need to convert to Entrez IDs
            cat("Current gene names are not Entrez IDs, attempting conversion...\n")
            
            # Try to get the gene mapping that was used during enrichment
            if (exists("gene_ids") && !is.null(gene_ids) && nrow(gene_ids) > 0) {
              # Use the existing gene_ids mapping
              original_to_entrez <- setNames(gene_ids$ENTREZID, gene_ids[[input$proteomics_id_type]])
              entrez_ids <- original_to_entrez[current_names]
              
              # Remove NAs and create new gene_data with Entrez IDs
              valid_entrez <- !is.na(entrez_ids)
              if (sum(valid_entrez) > 0) {
                gene_data_entrez <- gene_data[valid_entrez]
                names(gene_data_entrez) <- entrez_ids[valid_entrez]
                gene_data <- gene_data_entrez
                
                cat("Successfully converted", sum(valid_entrez), "genes to Entrez IDs\n")
                cat("New gene names (first 10):", head(names(gene_data), 10), "\n")
              } else {
                showNotification("Could not convert gene IDs to Entrez format for pathview.", type = "error")
                return()
              }
            } else {
              # Try to perform ID conversion using current organism
              cat("Attempting direct ID conversion...\n")
              if (input$proteomics_id_type != "ENTREZID") {
                if (requireNamespace("clusterProfiler", quietly = TRUE)) {
                  tryCatch({
                    # Get organism database
                    orgdb <- get_orgdb(input$proteomics_organism)
                    if (!is.null(orgdb)) {
                      converted_ids <- clusterProfiler::bitr(
                        current_names,
                        fromType = input$proteomics_id_type,
                        toType = "ENTREZID",
                        OrgDb = orgdb
                      )
                      
                      if (nrow(converted_ids) > 0) {
                        # Create mapping
                        mapping <- setNames(converted_ids$ENTREZID, converted_ids[[input$proteomics_id_type]])
                        entrez_ids <- mapping[current_names]
                        
                        # Remove NAs and update gene_data
                        valid_entrez <- !is.na(entrez_ids)
                        if (sum(valid_entrez) > 0) {
                          gene_data_entrez <- gene_data[valid_entrez]
                          names(gene_data_entrez) <- entrez_ids[valid_entrez]
                          gene_data <- gene_data_entrez
                          
                          cat("Converted", sum(valid_entrez), "genes to Entrez IDs via clusterProfiler\n")
                        } else {
                          showNotification("No genes could be converted to Entrez IDs for pathview.", type = "error")
                          return()
                        }
                      } else {
                        showNotification("Gene ID conversion failed - no matches found.", type = "error")
                        return()
                      }
                    } else {
                      showNotification("Could not load organism database for gene ID conversion.", type = "error")
                      return()
                    }
                  }, error = function(e) {
                    showNotification(paste("Gene ID conversion error:", e$message), type = "error")
                    return()
                  })
                } else {
                  showNotification("clusterProfiler not available for gene ID conversion.", type = "error")
                  return()
                }
              }
            }
          }
          
          # Ensure gene data is properly formatted for pathview
          if (is.data.frame(gene_data)) {
            # If it's a data frame, convert to named vector using first numeric column
            numeric_cols <- sapply(gene_data, is.numeric)
            if (any(numeric_cols)) {
              first_numeric_col <- which(numeric_cols)[1]
              gene_data <- setNames(gene_data[[first_numeric_col]], rownames(gene_data))
            } else {
              showNotification("No numeric data found for pathview visualization.", type = "warning")
              return()
            }
          }
          
          # Remove any NA values
          gene_data <- gene_data[!is.na(gene_data)]
          
          if (length(gene_data) == 0) {
            showNotification("No valid gene expression data for pathview.", type = "warning")
            return()
          }
          
          cat("Final gene data for pathview:\n")
          cat("Length:", length(gene_data), "\n")
          cat("Names (first 10):", head(names(gene_data), 10), "\n")
          cat("Range of values:", range(gene_data, na.rm = TRUE), "\n")
          cat("Has names:", !is.null(names(gene_data)), "\n")
          cat("Names are Entrez IDs:", all(grepl("^[0-9]+$", names(gene_data)[!is.na(names(gene_data))])), "\n")
          
          # Validate that gene names are valid Entrez IDs
          if (is.null(names(gene_data))) {
            showNotification("Gene data lacks proper gene IDs for pathview.", type = "error")
            return()
          }
          
          valid_entrez_names <- grepl("^[0-9]+$", names(gene_data))
          if (sum(valid_entrez_names) == 0) {
            showNotification("No valid Entrez gene IDs found for pathview visualization.", type = "warning")
            return()
          }
          
          if (sum(valid_entrez_names) < length(gene_data)) {
            cat("Filtering to", sum(valid_entrez_names), "genes with valid Entrez IDs\n")
            gene_data <- gene_data[valid_entrez_names]
          }
          
          # Set color scheme
          if (input$pathview_colorscheme == "green_gray_red") {
            low_color <- "green"
            mid_color <- "gray"
            high_color <- "red"
          } else if (input$pathview_colorscheme == "blue_gray_yellow") {
            low_color <- "blue"
            mid_color <- "gray"
            high_color <- "yellow"
          } else {
            # Custom - use default pathview colors
            low_color <- "green"
            mid_color <- "gray"
            high_color <- "red"
          }
          
          setProgress(0.3, detail = "Please wait...")
          
          # Debug pathview parameters
          cat("Pathview parameters:\n")
          cat("Pathway ID:", input$pathview_pathway_select, "\n")
          cat("Species:", input$pathview_species, "\n")
          cat("Gene limit:", input$pathview_limit, "\n")
          cat("Color scheme - Low:", low_color, "Mid:", mid_color, "High:", high_color, "\n")
          cat("Sample gene data for pathview:\n")
          cat("First 5 genes:", paste(names(head(gene_data, 5)), "=", head(gene_data, 5), collapse = ", "), "\n")
          
          # Safe wrapper to prevent accidental unsupported arguments (e.g., na.rm)
          safe_pathview <- function(...) {
            args <- list(...)
            # Remove any na.rm arguments that might have been passed
            args$na.rm <- NULL
            # Drop NULL arguments (prevents passing split.group=NULL etc.)
            args <- args[!vapply(args, is.null, logical(1))]
            # Also clean any nested lists that might contain na.rm
            args <- lapply(args, function(x) {
              if (is.list(x)) {
                x$na.rm <- NULL
              }
              return(x)
            })
            do.call(pathview::pathview, args)
          }
          
          # Call pathview function with cleaned arguments
          pathview_result <- safe_pathview(
            gene.data = gene_data,
            pathway.id = input$pathview_pathway_select,
            species = input$pathview_species,
            limit = list(gene = input$pathview_limit, cpd = 1),
            low = list(gene = low_color, cpd = "blue"),
            mid = list(gene = mid_color, cpd = "gray"),
            high = list(gene = high_color, cpd = "yellow"),
            kegg.native = (input$pathview_engine == "kegg_native"),  # Use selected rendering engine
            same.layer = FALSE,  # Helps with gene expression overlay
            kegg.dir = getwd(),
            out.suffix = paste0("_", format(Sys.time(), "%Y%m%d_%H%M%S")),
            split.group = if (input$pathview_engine == "graphviz") isTRUE(input$graphviz_split_group) else NULL,
            expand.node = if (input$pathview_engine == "graphviz") isTRUE(input$graphviz_expand_node) else NULL
          )
          
          setProgress(0.8, detail = "Processing results...")
          
          # Find the generated PNG file
          expected_ext <- if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") "pdf" else "png"
          primary_pattern <- paste0(input$pathview_pathway_select, ".*\\.", expected_ext, "$")
          primary_files <- list.files(pattern = primary_pattern, full.names = TRUE)

          # Fallback: some environments may only generate the other image format
          fallback_ext <- if (expected_ext == "pdf") "png" else "pdf"
          fallback_pattern <- paste0(input$pathview_pathway_select, ".*\\.", fallback_ext, "$")
          fallback_files <- list.files(pattern = fallback_pattern, full.names = TRUE)

          selected_file <- NULL
          if (length(primary_files) > 0) {
            selected_file <- primary_files[which.max(file.mtime(primary_files))]
          } else if (length(fallback_files) > 0) {
            selected_file <- fallback_files[which.max(file.mtime(fallback_files))]
          }

          if (!is.null(selected_file)) {
            out_ext <- tolower(tools::file_ext(selected_file))
            proteomics_values$pathview_output_path <- selected_file
            proteomics_values$pathview_output_type <- out_ext
          }

          # If no image file was written yet, check if only the XML exists (common when Graphviz binaries are missing)
          if (is.null(proteomics_values$pathview_output_path)) {
            xml_pattern <- paste0(input$pathview_pathway_select, ".*\\.xml$")
            xml_files <- list.files(pattern = xml_pattern, full.names = TRUE)
            if (length(xml_files) > 0) {
              proteomics_values$pathview_output_path <- xml_files[which.max(file.mtime(xml_files))]
              proteomics_values$pathview_output_type <- "xml"
            }
          }

          selected_output_path <- proteomics_values$pathview_output_path
          selected_output_type <- proteomics_values$pathview_output_type

          if (!is.null(selected_output_path)) {
            if (selected_output_type == "png") {
              proteomics_values$pathview_image_path <- selected_output_path
              showNotification(paste("Pathview generated successfully:", basename(selected_output_path)),
                               type = "message", duration = 5)
            } else if (selected_output_type == "pdf") {
              showNotification(paste("Graphviz Pathview generated (PDF):", basename(selected_output_path)),
                               type = "message", duration = 5)
            } else if (selected_output_type == "xml") {
              showNotification("Pathview completed but only XML output was generated (Graphviz likely failed).",
                               type = "warning", duration = 8)
            } else {
              showNotification(paste("Pathview completed. Output file:", basename(selected_output_path)),
                               type = "message", duration = 5)
            }
          } else {
            if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") {
              showNotification(
                "Pathview completed but no Graphviz output was found. Ensure Graphviz/Rgraphviz are installed.",
                type = "warning"
              )
            } else {
              showNotification("Pathview completed but PNG file not found.", type = "warning")
            }
          }
          
          setProgress(1, detail = "Complete!")
          
        }, error = function(e) {
          showNotification(paste("Error generating pathview:", e$message),
                           type = "error", duration = 10)
          cat("Pathview error:", e$message, "\n")
        })
      })
    })
    
    # Render pathview image
    output$pathview_image_output <- renderImage({
      # If we have a PNG, show it
      if (!is.null(proteomics_values$pathview_image_path) &&
          file.exists(proteomics_values$pathview_image_path)) {
        return(list(
          src = proteomics_values$pathview_image_path,
          alt = "KEGG Pathview Visualization",
          width = "100%",
          height = "auto"
        ))
      }

      # If graphviz produced a PDF, we can't render it as an image
      if (!is.null(proteomics_values$pathview_output_path) &&
          file.exists(proteomics_values$pathview_output_path) &&
          identical(tolower(proteomics_values$pathview_output_type), "pdf")) {
        return(list(src = "", alt = "Graphviz Pathview generated (PDF). Use the download button."))
      }

      # Return a placeholder when no image is available
      list(src = "", alt = "No pathview image generated yet")
    }, deleteFile = FALSE)
    
    # Download pathview output (PNG for KEGG Native, PDF for Graphviz)
    output$download_pathview <- downloadHandler(
      filename = function() {
        out_path <- proteomics_values$pathview_output_path %||% proteomics_values$pathview_image_path
        if (!is.null(out_path)) return(basename(out_path))

        ext <- if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") "pdf" else "png"
        paste0("pathview_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", ext)
      },
      content = function(file) {
        out_path <- proteomics_values$pathview_output_path %||% proteomics_values$pathview_image_path
        if (!is.null(out_path) && file.exists(out_path)) {
          file.copy(out_path, file)
          return(invisible())
        }
        showNotification("No pathview output available for download.", type = "warning")
      },
      contentType = "application/octet-stream"
    )
    
    # Store enrichment results and set available plots
    if (!is.null(enrichment_results)) {
      proteomics_values$enrichment_results <- enrichment_results
      
      # Reset KEGG pathway click inputs to prevent old clicks from firing
      session$sendCustomMessage(type = "resetKeggInputs", message = list())
      
      # Store fold change data for ClusterProfiler tree plots
      if(input$proteomics_tool == "clusterprofiler" && exists("fold_change_data")) {
        proteomics_values$fold_change_data <- fold_change_data
        # Store original fold change data for heatplot option
        if(exists("original_fold_change_data")) {
          proteomics_values$original_fold_change_data <- original_fold_change_data
        } else {
          proteomics_values$original_fold_change_data <- fold_change_data
        }
      } else {
        proteomics_values$fold_change_data <- NULL
        proteomics_values$original_fold_change_data <- NULL
      }
      
      # Set available plots based on the tool used
      proteomics_values$plots_available <- switch(input$proteomics_tool,
                                                  "gprofiler" = c("manhattan", "barplot"),
                                                  "clusterprofiler" = c("dotplot", "barplot", "heatplot", "treeplot", "enrichmap", "cnetplot", "upsetplot", "gseaplot2"),
                                                  "enrichr" = c("barplot", "dotplot", "enrichplot"),
                                                  "reactomepa" = c("dotplot", "barplot", "enrichmap", "cnetplot", "pathview"),
                                                  "topgo" = c("barplot", "gograph"),
                                                  c()
      )
    } else {
      proteomics_values$enrichment_results <- NULL
      proteomics_values$plots_available <- NULL
      proteomics_values$fold_change_data <- NULL
      proteomics_values$original_fold_change_data <- NULL
      proteomics_values$pathview_gene_data <- NULL  # Clear cached pathview data
    }
    
    showNotification("Enrichment analysis complete.", type = "message", duration = 5)
  })
  # Proteomics Input Summary - Always show live updates
  output$proteomics_input_summary <- renderPrint({
    # Add reactive dependencies for all parameters that affect gene list
    input$proteomics_source
    input$proteomics_intersection_set
    input$proteomics_pairwise_group1
    input$proteomics_pairwise_group2
    input$proteomics_pairwise_pval
    input$proteomics_pairwise_fc
    input$proteomics_fdr_cutoff
    input$proteomics_include_up
