      } else if (is.null(input$proteomics_source) || input$proteomics_source == "") {
        cat("No data source selected. Choose Intersection, Pairwise, Manual, or MOFA Factor.\n")
      } else {
        cat(result$message, "\n")
      }
    } else {
      cat(result$message, "\n\n")
      cat("First 10 genes/proteins:\n")
      cat(paste(head(result$genes, 10), collapse = ", "), "\n")
      if (length(result$genes) > 10) {
        cat("...\n")
      }
    }
  })
  
