    # Only update if we have a valid gene list
    if (!is.null(result$genes) && length(result$genes) > 0) {
      # Validate IDs to detect type
      validation <- validate_ids(result$genes)
      
      # Debug output
      cat("ID Auto-detection:\n")
      cat("  - Gene list length:", length(result$genes), "\n")
      cat("  - Sample genes:", paste(head(result$genes, 5), collapse = ", "), "\n")
      cat("  - Detected type:", validation$type, "\n")
      cat("  - Confidence:", validation$confidence, "\n")
      cat("  - Valid:", validation$valid, "\n")
      cat("  - Current ID type:", input$proteomics_id_type, "\n")
      
      # Map validation result to selectInput options
      detected_type <- switch(validation$type,
                              "UniProt" = "UNIPROT",
                              "Entrez" = "ENTREZID",
                              "Ensembl" = "ENSEMBL",
                              "Symbol" = "SYMBOL",
                              "SYMBOL") # Default fallback
      
      cat("  - Mapped detected type:", detected_type, "\n")
      
      # Update the selectInput if detection was successful with high confidence and type has changed
      if (validation$valid &&
          validation$confidence == "high" &&
          input$proteomics_id_type != detected_type) {
        cat("  - CONDITIONS MET: Updating ID type to:", detected_type, "\n")
        updateSelectInput(session, "proteomics_id_type",
                          selected = detected_type)
