                         type = "message", duration = 3)
      } else if (validation$valid &&
                 validation$confidence == "medium" &&
                 input$proteomics_id_type != detected_type) {
        # Show notification for medium confidence but don't auto-update
        cat("  - MEDIUM CONFIDENCE: Showing suggestion for:", validation$type, "\n")
        showNotification(paste("Suggested ID type:", validation$type, "(medium confidence - please verify)"),
                         type = "warning", duration = 5)
      } else {
        cat("  - No ID type update needed. Reasons:\n")
        cat("    - Valid:", validation$valid, "\n")
        cat("    - Confidence:", validation$confidence, "\n")
        cat("    - Current type:", input$proteomics_id_type, "\n")
        cat("    - Detected type:", detected_type, "\n")
        cat("    - Types different:", input$proteomics_id_type != detected_type, "\n")
      }
    } else {
      cat("ID Auto-detection: No valid gene list available\n")
      if (!is.null(result$genes)) {
        cat("  - Gene list length:", length(result$genes), "\n")
      }
    }
  }, ignoreInit = TRUE)
  
  # Update manual file column choice
  observeEvent(input$proteomics_manual_file, {
    req(input$proteomics_manual_file)
    req(input$proteomics_manual_filetype != "single")
    
    tryCatch({
      # Read file based on type
      if (input$proteomics_manual_filetype == "csv") {
