      } else if (input$proteomics_manual_filetype == "tab") {
        # Handle both .tab and .tsv files
        data <- read.delim(input$proteomics_manual_file$datapath, stringsAsFactors = FALSE)
      }
      
      # Clean column names and data
      colnames(data) <- trimws(colnames(data))
      data[] <- lapply(data, function(x) if(is.character(x)) trimws(x) else x)
      
      # Get column names
      col_names <- colnames(data)
      
      # Auto-detect ID column
      id_column_patterns <- c("id", "gene", "protein", "symbol", "gene_symbol", "gene_name",
                              "protein_id", "uniprot", "ensembl", "entrez", "identifier")
      id_column <- NULL
      for (pattern in id_column_patterns) {
        matches <- grep(pattern, col_names, ignore.case = TRUE)
        if (length(matches) > 0) {
          id_column <- col_names[matches[1]]
          break
        }
      }
      
      # Auto-detect p-value column
      pvalue_column_patterns <- c("pval", "p_val", "p.val", "pvalue", "p_value", "p.value",
                                  "adj_pval", "adj_p_val", "adj.p.val", "padj", "p_adj", "p.adj",
                                  "fdr", "qval", "q_val", "q.val", "qvalue", "q_value", "q.value")
      pvalue_column <- NULL
      for (pattern in pvalue_column_patterns) {
        matches <- grep(pattern, col_names, ignore.case = TRUE)
        if (length(matches) > 0) {
          pvalue_column <- col_names[matches[1]]
          break
        }
      }
      
      # Auto-detect fold change column
      fc_column_patterns <- c("fc", "fold_change", "fold.change", "foldchange", "log2fc", "log2_fc",
                              "log2.fc", "log2_fold_change", "log2.fold.change", "logfc", "log_fc",
                              "log.fc", "log_fold_change", "log.fold.change")
      fc_column <- NULL
      for (pattern in fc_column_patterns) {
        matches <- grep(pattern, col_names, ignore.case = TRUE)
        if (length(matches) > 0) {
          fc_column <- col_names[matches[1]]
          break
        }
      }
      
      # Update ID column dropdown
      updateSelectInput(session, "proteomics_manual_column",
                        choices = col_names,
                        selected = id_column)
      
      # Update p-value column dropdown
      pvalue_choices <- c("None (for ORA only)" = "", col_names)
      updateSelectInput(session, "proteomics_manual_pvalue_column",
                        choices = pvalue_choices,
                        selected = if (!is.null(pvalue_column)) pvalue_column else "")
      
      # Update fold change column dropdown
      fc_choices <- c("None (for ORA only)" = "", col_names)
      updateSelectInput(session, "proteomics_manual_foldchange_column",
                        choices = fc_choices,
                        selected = if (!is.null(fc_column)) fc_column else "")
      
      # Show notification about auto-detection
      auto_detected <- c()
      if (!is.null(id_column)) auto_detected <- c(auto_detected, paste("ID:", id_column))
      if (!is.null(pvalue_column)) auto_detected <- c(auto_detected, paste("P-value:", pvalue_column))
      if (!is.null(fc_column)) auto_detected <- c(auto_detected, paste("Fold Change:", fc_column))
      
      if (length(auto_detected) > 0) {
        showNotification(paste("Auto-detected columns:", paste(auto_detected, collapse = ", ")),
                         type = "message", duration = 5)
      }
      
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
    })
  })
  # Update plot type choices based on selected tool
  observe({
