  # Function to validate gene/protein IDs with improved detection
  validate_ids <- function(ids) {
    if (is.null(ids) || length(ids) == 0) {
      return(list(valid = FALSE, type = "Unknown", message = "No IDs provided"))
    }
    
    # Clean up IDs by removing whitespace and empty entries
    clean_ids <- trimws(ids)
    clean_ids <- clean_ids[clean_ids != "" & !is.na(clean_ids)]
    
    if (length(clean_ids) == 0) {
      return(list(valid = FALSE, type = "Unknown", message = "No valid IDs after cleanup"))
    }
    
    # Check some sample IDs (more samples for better detection)
    sample_size <- min(30, length(clean_ids))
    sample_ids <- head(clean_ids, sample_size)
    
    # Define improved patterns for different ID types
    uniprot_pattern <- "^([OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9]([A-Z][A-Z0-9]{2}[0-9]){1,2})(-[0-9]+)?$"
    entrez_pattern <- "^[0-9]{1,8}$"  # Entrez IDs are typically 1-8 digits
    ensembl_pattern <- "^ENS[A-Z]*[GT][0-9]{11}(\\.[0-9]+)?$"
    # More restrictive gene symbol pattern - typically starts with letter, contains letters/numbers/_/-
    gene_symbol_pattern <- "^[A-Za-z][A-Za-z0-9_.-]{0,19}$"
    
    # Count matches for each pattern
    uniprot_matches <- sum(grepl(uniprot_pattern, sample_ids, ignore.case = FALSE))
    entrez_matches <- sum(grepl(entrez_pattern, sample_ids))
    ensembl_matches <- sum(grepl(ensembl_pattern, sample_ids, ignore.case = FALSE))
    symbol_matches <- sum(grepl(gene_symbol_pattern, sample_ids, ignore.case = FALSE))
    
    # Calculate confidence threshold (at least 70% match for high confidence)
    high_threshold <- sample_size * 0.7
    low_threshold <- sample_size * 0.5
    
    # Determine ID type based on highest confidence match
    if (uniprot_matches >= high_threshold) {
      return(list(valid = TRUE, type = "UniProt", confidence = "high",
                  message = "IDs appear to be UniProt accessions"))
    } else if (entrez_matches >= high_threshold) {
      return(list(valid = TRUE, type = "Entrez", confidence = "high",
                  message = "IDs appear to be Entrez Gene IDs"))
    } else if (ensembl_matches >= high_threshold) {
      return(list(valid = TRUE, type = "Ensembl", confidence = "high",
                  message = "IDs appear to be Ensembl Gene IDs"))
    } else if (symbol_matches >= high_threshold) {
      return(list(valid = TRUE, type = "Symbol", confidence = "high",
                  message = "IDs appear to be gene symbols"))
    } else {
      # Check for medium confidence matches
      if (uniprot_matches >= low_threshold) {
        return(list(valid = TRUE, type = "UniProt", confidence = "medium",
                    message = "IDs likely UniProt accessions (please verify)"))
      } else if (entrez_matches >= low_threshold) {
        return(list(valid = TRUE, type = "Entrez", confidence = "medium",
                    message = "IDs likely Entrez Gene IDs (please verify)"))
      } else if (ensembl_matches >= low_threshold) {
        return(list(valid = TRUE, type = "Ensembl", confidence = "medium",
                    message = "IDs likely Ensembl Gene IDs (please verify)"))
      } else if (symbol_matches >= low_threshold) {
        return(list(valid = TRUE, type = "Symbol", confidence = "medium",
                    message = "IDs likely gene symbols (please verify)"))
      } else {
        # Show the best guess even if below threshold
        best_match <- which.max(c(uniprot_matches, entrez_matches, ensembl_matches, symbol_matches))
        best_type <- c("UniProt", "Entrez", "Ensembl", "Symbol")[best_match]
        best_count <- c(uniprot_matches, entrez_matches, ensembl_matches, symbol_matches)[best_match]
        
        return(list(valid = FALSE, type = best_type, confidence = "low",
                    message = sprintf("Warning: ID type unclear. Best guess is %s. Please verify ID type selection.", best_type)))
      }
    }
  }
  
  # Update UI based on available data
  observe({
    # Update differential analysis comparisons - show ALL possible comparisons
    if (!is.null(values$unique_groups)) {
      # Generate all possible pairwise comparisons
      all_comparisons <- c()
