    # Update intersection sets
    if (!is.null(values$intersection_comparison_results)) {
      set_names <- names(values$intersection_comparison_results)
      updateSelectInput(session, "proteomics_intersection_set",
                        choices = set_names)
    }
    
    # Update pairwise group selections
    if (!is.null(values$unique_groups)) {
      updateSelectInput(session, "proteomics_pairwise_group1",
                        choices = values$unique_groups,
                        selected = values$unique_groups[1])
      
      updateSelectInput(session, "proteomics_pairwise_group2",
                        choices = values$unique_groups,
                        selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
    }
  })
  
  # Get gene list based on selected source
  get_gene_list <- function() {
    if (input$proteomics_source == "intersection") {
      if (is.null(values$intersection_comparison_results) || length(values$intersection_comparison_results) == 0) {
        return(list(genes = NULL, message = "Intersection analysis not performed yet."))
      }
      req(input$proteomics_intersection_set)
      if (!input$proteomics_intersection_set %in% names(values$intersection_comparison_results)) {
        return(list(genes = NULL, message = "Selected intersection set not found."))
      }
      genes <- values$intersection_comparison_results[[input$proteomics_intersection_set]]
      if (length(genes) == 0) {
        return(list(genes = NULL, message = "Selected intersection set contains no genes/proteins."))
      }
      
      # Validate that genes exist in the original data to prevent UpSet plot issues
      if (!is.null(values$normalized_data)) {
        original_feature_names <- rownames(values$normalized_data)
        if (is.null(original_feature_names)) {
          original_feature_names <- values$cleaned_molecules
        }
        # Filter to only include genes that exist in the original data
        valid_genes <- genes[genes %in% original_feature_names]
        if (length(valid_genes) != length(genes)) {
          showNotification(paste("Warning:", length(genes) - length(valid_genes),
                                 "genes were not found in the original data and will be excluded."),
                           type = "warning")
          genes <- valid_genes
        }
        if (length(genes) == 0) {
          return(list(genes = NULL, message = "No valid genes found in the original data."))
        }
      }
      
      # Convert feature names to accession IDs for enrichment if available
      if (!is.null(values$accession_ids) && !is.null(values$cleaned_molecules) && 
          length(values$accession_ids) == length(values$cleaned_molecules)) {
        # Find indices of feature names in cleaned_molecules
        feature_indices <- match(genes, values$cleaned_molecules)
        valid_indices <- !is.na(feature_indices)
        if (any(valid_indices)) {
          genes <- values$accession_ids[feature_indices[valid_indices]]
        }
      }
      
      validation <- validate_ids(genes)
      return(list(genes = genes,
                  message = sprintf("Found %d genes/proteins. %s", length(genes), validation$message)))
    } else if (input$proteomics_source == "pairwise") {
      req(values$normalized_data, values$cleaned_molecules,
          input$proteomics_pairwise_group1, input$proteomics_pairwise_group2)
      
      # Get group indices
      group1_idx <- which(values$unique_groups == input$proteomics_pairwise_group1)
      group2_idx <- which(values$unique_groups == input$proteomics_pairwise_group2)
      if (length(group1_idx) == 0 || length(group2_idx) == 0) {
        return(list(genes = NULL, message = "Selected groups not found."))
      }
      
      # Get statistics columns with flexible group selection
      comp_stats <- get_comparison_stats(input$proteomics_pairwise_group1, input$proteomics_pairwise_group2)
      if (is.null(comp_stats)) {
        return(list(genes = NULL, message = "Statistical results not found for selected comparison."))
      }
      
      comparison_name <- comp_stats$comparison_name
      p_value_column <- comp_stats$p_value_column
      fc_column_result <- comp_stats$fc_column_result
      is_fc_reversed <- grepl("^REVERSED:", fc_column_result)
      fc_column <- if(is_fc_reversed) sub("^REVERSED:", "", fc_column_result) else fc_column_result
      is_comparison_reversed <- comp_stats$is_reversed
      
      pvals <- values$stat_results[[p_value_column]]
      log2fc <- values$stat_results[[fc_column]]
      
      # Reverse fold changes if necessary
      if(is_fc_reversed || is_comparison_reversed) {
        log2fc <- -log2fc
      }
      
      # Get FDR column for ROTS method using same comparison_name from get_comparison_stats
      fdr_values <- NULL
      fdr_column <- NULL
      if (input$sig_method == "rots" && !is.null(values$stat_results)) {
        fdr_column_name <- paste0(comparison_name, "_FDR")
        
        if (fdr_column_name %in% colnames(values$stat_results)) {
          fdr_column <- fdr_column_name
          fdr_values <- values$stat_results[[fdr_column]]
        }
      }
      
      # Apply filtering based on checkboxes
      idx <- c()
      if (isTRUE(input$proteomics_include_up)) {
        # For ROTS with FDR available, apply all three cutoffs simultaneously
        if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          idx <- c(idx, which(
            !is.na(pvals) & !is.na(fdr_values) & !is.na(log2fc) &
              pvals <= input$proteomics_pairwise_pval &
              fdr_values <= input$proteomics_fdr_cutoff &
              log2fc >= input$proteomics_pairwise_fc
          ))
        } else {
          # Standard filter for non-ROTS or missing FDR
          idx <- c(idx, which(
            !is.na(pvals) & !is.na(log2fc) &
              pvals <= input$proteomics_pairwise_pval &
              log2fc >= input$proteomics_pairwise_fc
          ))
        }
      }
      if (isTRUE(input$proteomics_include_down)) {
        # For ROTS with FDR available, apply all three cutoffs simultaneously
        if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          idx <- c(idx, which(
            !is.na(pvals) & !is.na(fdr_values) & !is.na(log2fc) &
              pvals <= input$proteomics_pairwise_pval &
              fdr_values <= input$proteomics_fdr_cutoff &
              log2fc <= -input$proteomics_pairwise_fc
          ))
        } else {
          # Standard filter for non-ROTS or missing FDR
          idx <- c(idx, which(
            !is.na(pvals) & !is.na(log2fc) &
              pvals <= input$proteomics_pairwise_pval &
              log2fc <= -input$proteomics_pairwise_fc
          ))
        }
      }
      idx <- unique(idx)        # Apply feature source filtering (like other analysis tabs)
      if (!is.null(input$proteomics_feature_source) && input$proteomics_feature_source != "all") {
        feature_source_idx <- get_feature_indices_by_source(input$proteomics_feature_source, comparison_name)
        # Intersect significant indices with feature source indices
        idx <- intersect(idx, feature_source_idx)
      }
      
      if (length(idx) == 0) {
        return(list(genes = NULL, message = "No proteins found matching the selected criteria."))
      }
      
      # Use accession IDs (Gene/Accession columns) for enrichment if available, otherwise use feature names
      if (!is.null(values$accession_ids) && length(values$accession_ids) == length(values$cleaned_molecules)) {
        genes <- values$accession_ids[idx]
      } else {
        genes <- values$cleaned_molecules[idx]
      }
      validation <- validate_ids(genes)
      
      # Create message with feature source information
      feature_source_text <- switch(input$feature_source %||% "all",
                                    "all" = "",        "pca" = {
                                      feature_indices <- get_feature_indices_by_source("pca", comparison_name)
                                      if (length(feature_indices) > 0 && length(feature_indices) < length(values$cleaned_molecules)) {
                                        sprintf(" [Using Top %d PCA Features]", length(feature_indices))
                                      } else {
                                        " [PCA features not available, using all]"
                                      }
                                    },
                                    "ml" = {
                                      if (!is.null(values$selected_features$features) &&
                                          values$selected_features$source == "ML") {
                                        sprintf(" [Using %d ML-Selected Features]", length(values$selected_features$features))
                                      } else {
                                        " [ML features not available, using all]"
                                      }
                                    }
      )
      return(list(
        genes = genes,
        message = if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
          sprintf(
            "Found %d proteins (p-value = %.3g, FDR = %.3g, |log2FC| = %.2f). Included: %s.%s %s",
            length(genes),
            input$proteomics_pairwise_pval,
            input$proteomics_fdr_cutoff,
            input$proteomics_pairwise_fc,
            paste(c(
              if (isTRUE(input$proteomics_include_up)) "Upregulated",
              if (isTRUE(input$proteomics_include_down)) "Downregulated"
            ), collapse = " & "),
            feature_source_text,
            validation$message
          )
        } else {
          sprintf(
            "Found %d proteins (p-value = %.3g, |log2FC| = %.2f). Included: %s.%s %s",
            length(genes),
            input$proteomics_pairwise_pval,
            input$proteomics_pairwise_fc,
            paste(c(
              if (isTRUE(input$proteomics_include_up)) "Upregulated",
              if (isTRUE(input$proteomics_include_down)) "Downregulated"
            ), collapse = " & "),
            feature_source_text,
            validation$message
          )
        }
      ))
    } else if (input$proteomics_source == "manual") {
      if (input$proteomics_manual_input_type == "paste") {
        # Handle pasted text input - only for ORA
        genes_text <- input$proteomics_manual_text
        if (is.null(genes_text) || genes_text == "") {
          return(list(genes = NULL, message = "No genes/proteins entered."))
        }
        
        # Split by newline and remove empty lines
        genes <- strsplit(genes_text, "\\r?\\n")[[1]]
        genes <- genes[genes != ""]
        genes <- trimws(genes)
        genes <- unique(genes)
        
        if (length(genes) == 0) {
          return(list(genes = NULL, message = "No valid genes/proteins found in the pasted text."))
        }
        
        validation <- validate_ids(genes)
        
        return(list(genes = genes,
                    pvalues = NULL,
                    fold_changes = NULL,
                    analysis_type = "ORA",
                    message = sprintf("Found %d genes/proteins from pasted text (ORA only). %s",
                                      length(genes), validation$message)))
        
      } else {
        # Handle file upload
        req(input$proteomics_manual_file)
        
        tryCatch({
          if (input$proteomics_manual_filetype == "single") {
            # Read as single column file - only for ORA
            genes <- readLines(input$proteomics_manual_file$datapath)
            genes <- genes[genes != ""] # Remove empty lines
            genes <- trimws(genes)
            genes <- unique(genes)
            
            if (length(genes) == 0) {
              return(list(genes = NULL, message = "No genes/proteins found in the file."))
            }
            
            validation <- validate_ids(genes)
            
            return(list(genes = genes,
                        pvalues = NULL,
                        fold_changes = NULL,
                        analysis_type = "ORA",
                        message = sprintf("Found %d genes/proteins from single column file (ORA only). %s",
                                          length(genes), validation$message)))
            
          } else if (input$proteomics_manual_filetype == "csv") {
            # Read as CSV
            data <- read.csv(input$proteomics_manual_file$datapath, stringsAsFactors = FALSE)
            req(input$proteomics_manual_column)
            
            # Clean data
            colnames(data) <- trimws(colnames(data))
            data[] <- lapply(data, function(x) if(is.character(x)) trimws(x) else x)
            
            # Extract all genes (full universe for background)
            all_genes <- data[[input$proteomics_manual_column]]
            all_genes <- trimws(as.character(all_genes))
            all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]
            full_gene_universe <- unique(all_genes)
            
            # Check for p-value and fold change columns
            pvalues <- NULL
            fold_changes <- NULL
            analysis_type <- "ORA"
            
            if (!is.null(input$proteomics_manual_pvalue_column) &&
                input$proteomics_manual_pvalue_column != "" &&
                input$proteomics_manual_pvalue_column %in% colnames(data)) {
              pvalues <- as.numeric(data[[input$proteomics_manual_pvalue_column]])
              pvalues <- pvalues[!is.na(all_genes) & all_genes != ""]
              pvalues <- pvalues[!duplicated(all_genes)]
            }
            
            if (!is.null(input$proteomics_manual_foldchange_column) &&
                input$proteomics_manual_foldchange_column != "" &&
                input$proteomics_manual_foldchange_column %in% colnames(data)) {
              fold_changes <- as.numeric(data[[input$proteomics_manual_foldchange_column]])
              fold_changes <- fold_changes[!is.na(all_genes) & all_genes != ""]
              fold_changes <- fold_changes[!duplicated(all_genes)]
            }
            
            # Determine analysis type
            if (!is.null(pvalues) && !is.null(fold_changes)) {
              analysis_type <- "GSEA"
            }
            
            # Apply filtering if enabled for GSEA
            genes <- full_gene_universe
            filtered_pvalues <- pvalues
            filtered_fold_changes <- fold_changes
            
            if (analysis_type == "GSEA" && 
                !is.null(input$proteomics_manual_apply_filters) &&
                isTRUE(input$proteomics_manual_apply_filters)) {
              
              # Apply p-value and log2FC cutoffs
              pval_cutoff <- input$proteomics_manual_pval_cutoff %||% 0.05
              fc_cutoff <- input$proteomics_manual_fc_cutoff %||% 1.0
              
              # Filter based on cutoffs
              filter_idx <- which(
                !is.na(pvalues) & !is.na(fold_changes) &
                  pvalues <= pval_cutoff &
                  abs(fold_changes) >= fc_cutoff
              )
              
              if (length(filter_idx) > 0) {
                genes <- full_gene_universe[filter_idx]
                filtered_pvalues <- pvalues[filter_idx]
                filtered_fold_changes <- fold_changes[filter_idx]
              } else {
                genes <- character(0)
                filtered_pvalues <- numeric(0)
                filtered_fold_changes <- numeric(0)
              }
            }
            
            # Store both filtered genes and full universe
            pvalues <- filtered_pvalues
            fold_changes <- filtered_fold_changes
            
          } else if (input$proteomics_manual_filetype == "tab") {
            # Read as tab-delimited
            data <- read.delim(input$proteomics_manual_file$datapath, stringsAsFactors = FALSE)
            req(input$proteomics_manual_column)
            
            # Clean data
            colnames(data) <- trimws(colnames(data))
            data[] <- lapply(data, function(x) if(is.character(x)) trimws(x) else x)
            
            # Extract all genes (full universe for background)
            all_genes <- data[[input$proteomics_manual_column]]
            all_genes <- trimws(as.character(all_genes))
            all_genes <- all_genes[!is.na(all_genes) & all_genes != ""]
            full_gene_universe <- unique(all_genes)
            
            # Check for p-value and fold change columns
            pvalues <- NULL
            fold_changes <- NULL
            analysis_type <- "ORA"
            
            if (!is.null(input$proteomics_manual_pvalue_column) &&
                input$proteomics_manual_pvalue_column != "" &&
                input$proteomics_manual_pvalue_column %in% colnames(data)) {
              pvalues <- as.numeric(data[[input$proteomics_manual_pvalue_column]])
              pvalues <- pvalues[!is.na(all_genes) & all_genes != ""]
              pvalues <- pvalues[!duplicated(all_genes)]
            }
            
            if (!is.null(input$proteomics_manual_foldchange_column) &&
                input$proteomics_manual_foldchange_column != "" &&
                input$proteomics_manual_foldchange_column %in% colnames(data)) {
              fold_changes <- as.numeric(data[[input$proteomics_manual_foldchange_column]])
              fold_changes <- fold_changes[!is.na(all_genes) & all_genes != ""]
              fold_changes <- fold_changes[!duplicated(all_genes)]
            }
            
            # Determine analysis type
            if (!is.null(pvalues) && !is.null(fold_changes)) {
              analysis_type <- "GSEA"
            }
            
            # Apply filtering if enabled for GSEA
            genes <- full_gene_universe
            filtered_pvalues <- pvalues
            filtered_fold_changes <- fold_changes
            
            if (analysis_type == "GSEA" && 
                !is.null(input$proteomics_manual_apply_filters) &&
                isTRUE(input$proteomics_manual_apply_filters)) {
              
              # Apply p-value and log2FC cutoffs
              pval_cutoff <- input$proteomics_manual_pval_cutoff %||% 0.05
              fc_cutoff <- input$proteomics_manual_fc_cutoff %||% 1.0
              
              # Filter based on cutoffs
              filter_idx <- which(
                !is.na(pvalues) & !is.na(fold_changes) &
                  pvalues <= pval_cutoff &
                  abs(fold_changes) >= fc_cutoff
              )
              
              if (length(filter_idx) > 0) {
                genes <- full_gene_universe[filter_idx]
                filtered_pvalues <- pvalues[filter_idx]
                filtered_fold_changes <- fold_changes[filter_idx]
              } else {
                genes <- character(0)
                filtered_pvalues <- numeric(0)
                filtered_fold_changes <- numeric(0)
              }
            }
            
            # Store both filtered genes and full universe
            pvalues <- filtered_pvalues
            fold_changes <- filtered_fold_changes
          }
          
          if (length(genes) == 0) {
            return(list(genes = NULL, 
                        full_gene_universe = if(exists("full_gene_universe")) full_gene_universe else NULL,
                        message = "No genes/proteins found in the file."))
          }
          
          validation <- validate_ids(genes)
          
          # Create appropriate message based on analysis type and filtering
          if (analysis_type == "GSEA") {
            if (!is.null(input$proteomics_manual_apply_filters) && 
                isTRUE(input$proteomics_manual_apply_filters) &&
                exists("full_gene_universe")) {
              pval_cutoff <- input$proteomics_manual_pval_cutoff %||% 0.05
              fc_cutoff <- input$proteomics_manual_fc_cutoff %||% 1.0
              message_text <- sprintf(
                "Found %d genes/proteins (filtered from %d total; p-value ≤ %.3g, |log2FC| ≥ %.2f). Full universe available for background. %s",
                length(genes), length(full_gene_universe), pval_cutoff, fc_cutoff, validation$message
              )
            } else {
              message_text <- sprintf("Found %d genes/proteins with p-values and fold changes (GSEA compatible). %s",
                                      length(genes), validation$message)
            }
          } else {
            message_text <- sprintf("Found %d genes/proteins from uploaded file (ORA only). %s",
                                    length(genes), validation$message)
          }
          
          return(list(genes = genes,
                      pvalues = pvalues,
                      fold_changes = fold_changes,
                      full_gene_universe = if(exists("full_gene_universe")) full_gene_universe else NULL,
                      analysis_type = analysis_type,
                      message = message_text))
          
        }, error = function(e) {
          return(list(genes = NULL,
                      message = paste("Error processing file:", e$message)))
        })
      }
    }
    else if (input$proteomics_source == "mofa_factor") {
      # Extract gene list from MOFA factor weights
      req(multiomics$integration_results)
      req(input$mofa_enrich_view)
      req(input$mofa_enrich_factor)
      
      tryCatch({
        # Get the factor weights for the selected view and factor
        mofa_res <- multiomics$integration_results
        view_name <- input$mofa_enrich_view
        factor_name <- input$mofa_enrich_factor
        
        # Extract weights - handle both MOFA and MOFA2 object structures
        if (!is.null(mofa_res$weights) && !is.null(mofa_res$weights[[view_name]])) {
          weights_matrix <- mofa_res$weights[[view_name]]
        } else if (!is.null(mofa_res$expectations) && !is.null(mofa_res$expectations$W) && !is.null(mofa_res$expectations$W[[view_name]])) {
          weights_matrix <- mofa_res$expectations$W[[view_name]]
        } else {
          showNotification("Could not extract MOFA weights. Please check your MOFA results.", type = "error", duration = 6)
          proteomics_values$analysis_running <- FALSE
          return(NULL)
        }
        
        # Get weights for the selected factor
        if (factor_name %in% colnames(weights_matrix)) {
          factor_weights <- weights_matrix[, factor_name]
        } else {
          showNotification(paste0("Factor '", factor_name, "' not found in MOFA weights."), type = "error", duration = 6)
          proteomics_values$analysis_running <- FALSE
          return(NULL)
        }
        
        # Get feature names from rownames
        feature_names <- rownames(weights_matrix)
        
        # Filter based on sign selection if not "both"
        if (input$mofa_enrich_sign != "both") {
          if (input$mofa_enrich_sign == "positive") {
            feature_names <- feature_names[factor_weights > 0]
            factor_weights <- factor_weights[factor_weights > 0]
          } else if (input$mofa_enrich_sign == "negative") {
            feature_names <- feature_names[factor_weights < 0]
            factor_weights <- factor_weights[factor_weights < 0]
          }
        }

        # Apply ranking + Top-N selection (Top N features by signed/absolute weight)
        rank_type <- input$mofa_enrich_rank_type
        if (is.null(rank_type) || !nzchar(rank_type)) rank_type <- "signed"

        if (length(feature_names) != length(factor_weights)) {
          showNotification("Internal error: MOFA features and weights length mismatch.", type = "error", duration = 6)
          proteomics_values$analysis_running <- FALSE
          return(NULL)
        }

        if (length(feature_names) > 0) {
          if (identical(rank_type, "absolute")) {
            ord <- order(abs(factor_weights), decreasing = TRUE)
          } else {
            if (identical(input$mofa_enrich_sign, "negative")) {
              ord <- order(factor_weights, decreasing = FALSE)
            } else {
              ord <- order(factor_weights, decreasing = TRUE)
            }
          }
          feature_names <- feature_names[ord]
          factor_weights <- factor_weights[ord]

          top_n <- input$mofa_enrich_top_n
          if (is.null(top_n) || is.na(top_n)) top_n <- 0
          top_n <- as.integer(top_n)
          if (top_n > 0) {
            top_n <- min(top_n, length(feature_names))
            feature_names <- feature_names[seq_len(top_n)]
            factor_weights <- factor_weights[seq_len(top_n)]
          }
        }
        
        # Handle potential duplicate feature names by keeping the one with maximum absolute weight
        if (any(duplicated(feature_names))) {
          showNotification("Duplicate feature names found in MOFA weights. Keeping features with maximum absolute weights.", type = "warning", duration = 4)
          
          # Create a data frame to handle duplicates
          weight_df <- data.frame(
            feature = feature_names,
            weight = factor_weights,
            abs_weight = abs(factor_weights)
          )
          
          # For each unique feature, keep the one with maximum absolute weight (base R implementation)
          unique_features <- unique(feature_names)
          filtered_indices <- sapply(unique_features, function(feat) {
            feat_rows <- which(weight_df$feature == feat)
            feat_rows[which.max(weight_df$abs_weight[feat_rows])]
          })
          
          weight_df <- weight_df[filtered_indices, ]
          
          # Update feature_names and factor_weights
          feature_names <- weight_df$feature
          factor_weights <- weight_df$weight
        }
        
        # Use MOFA feature names directly for enrichment
        gene_list <- feature_names
        fold_change_data <- sort(factor_weights, decreasing = TRUE)
        names(fold_change_data) <- feature_names
        proteomics_values$manual_fold_changes <- fold_change_data

        proteomics_values$gene_list_feature_names <- feature_names
        proteomics_values$gene_list_mapped_ids <- gene_list
        proteomics_values$mofa_factor_weights <- factor_weights
        
        if (length(gene_list) == 0) {
          showNotification("No features found for the selected MOFA factor and sign filter.", type = "error", duration = 6)
          proteomics_values$analysis_running <- FALSE
          return(NULL)
        }
        
      }, error = function(e) {
        showNotification(paste0("Error extracting MOFA factor data: ", e$message), type = "error", duration = 6)
        proteomics_values$analysis_running <- FALSE
        return(NULL)
      })
      
      # Return successful MOFA extraction result
      validation <- validate_ids(gene_list)
      return(list(
        genes = gene_list,
        fold_changes = proteomics_values$manual_fold_changes,
        analysis_type = "GSEA",
        message = sprintf("Found %d features from MOFA factor %s (ranked by %s weights). %s", 
                          length(gene_list), factor_name, rank_type, validation$message)
      ))
    }

    return(list(genes = NULL, message = "Invalid data source."))
  }
  
  # Update settings summary
  output$proteomics_settings_summary <- renderPrint({
    cat("Tool:", switch(input$proteomics_tool,
                        "gprofiler" = "g:Profiler (gprofiler2)",
                        "clusterprofiler" = "ClusterProfiler",
                        "enrichr" = "Enrichr",
                        "reactomepa" = "ReactomePA",
                        "topgo" = "topGO"), "\n")
    
    cat("Organism:", switch(input$proteomics_organism,
                            "hsapiens" = "Homo sapiens (Human)",
                            "mmusculus" = "Mus musculus (Mouse)",
                            "rnorvegicus" = "Rattus norvegicus (Rat)",
                            "scerevisiae" = "Saccharomyces cerevisiae (Yeast)",
                            "dmelanogaster" = "Drosophila melanogaster (Fruit fly)",
                            "celegans" = "Caenorhabditis elegans (Worm)",
                            "btaurus" = "Bos taurus (Cow)",
                            "ggallus" = "Gallus gallus (Chicken)",
                            "drerio" = "Danio rerio (Zebrafish)",
                            "sscrofa" = "Sus scrofa (Pig)",
                            "ecoli" = "Escherichia coli",
                            "athaliana" = "Arabidopsis thaliana (Mouse-ear cress)",
                            input$proteomics_organism), "\n")
    
    cat("Data source:", switch(input$proteomics_source,
                               "intersection" = "Intersection Analysis",
                               "pairwise" = "Pairwise Comparison",
                               "manual" = "Manual Input",
                               "mofa_factor" = "MOFA Factor"), "\n")
    
    if (input$proteomics_tool == "gprofiler") {
      cat("Significance threshold:", input$proteomics_gprofiler_pval, "\n")
      cat("Correction method:", input$proteomics_gprofiler_correction, "\n")
      cat("Sources:", paste(input$proteomics_gprofiler_sources, collapse = ", "), "\n")
    } else if (input$proteomics_tool == "clusterprofiler") {
      cat("p-value cutoff:", input$proteomics_cp_pval, "\n")
      cat("q-value cutoff:", input$proteomics_cp_qval, "\n")
      cat("Min gene set size:", input$proteomics_cp_min_gs, "\n")
      cat("Max gene set size:", input$proteomics_cp_max_gs, "\n")
    } else if (input$proteomics_tool == "enrichr") {
      cat("Databases:", paste(input$proteomics_enrichr_dbs, collapse = ", "), "\n")
    } else if (input$proteomics_tool == "reactomepa") {
      cat("p-value cutoff:", input$proteomics_reactome_pval, "\n")
      cat("q-value cutoff:", input$proteomics_reactome_qval, "\n")
      cat("Min gene set size:", input$proteomics_reactome_min_gs, "\n")
      cat("Max gene set size:", input$proteomics_reactome_max_gs, "\n")
    } else if (input$proteomics_tool == "topgo") {
      cat("GO category:", input$proteomics_topgo_ontology, "\n")
      cat("Algorithm:", input$proteomics_topgo_algorithm, "\n")
      cat("Test statistic:", input$proteomics_topgo_statistic, "\n")
      cat("Significance threshold:", input$proteomics_topgo_pval, "\n")
    }
  })
  
  # Generate plot based on selected plot type
  observe({
    req(proteomics_values$enrichment_results, input$proteomics_plot_type,
        proteomics_values$plots_available)
    
    # Add additional length checks to prevent errors during initialization
    req(length(input$proteomics_plot_type) > 0, length(proteomics_values$plots_available) > 0)
    
    # Skip if selected plot type is not available
    if (!input$proteomics_plot_type %in% proteomics_values$plots_available) {
      output$proteomics_plot <- renderPlot({ 
        plot.new()
        text(0.5, 0.5, "Selected plot type is not available for this analysis", cex = 1.2)
      }, res = UI_PLOT_RES)
      return()
    }
    
    plot_type <- input$proteomics_plot_type
    
    # Generate plot based on selected tool and plot type
    if (input$proteomics_tool == "gprofiler") {
      if (plot_type == "manhattan") {
        # Generate Manhattan plot for g:Profiler
        output$proteomics_plot <- renderPlot({ 
          req(proteomics_values$enrichment_results)
          gprofiler2::gostplot(proteomics_values$enrichment_results, capped = TRUE, interactive = FALSE)
        }, res = UI_PLOT_RES)
      } else if (plot_type == "barplot") {
        # Generate barplot for gprofiler results
        output$proteomics_plot <- renderPlot({ 
          # Get top results sorted by p-value
          gost_results <- proteomics_values$enrichment_results$result
          
          if (is.null(gost_results) || nrow(gost_results) == 0) {
            plot.new()
            text(0.5, 0.5, "No enrichment results available", cex = 1.2)
            return()
          }
          
          # Take top N results
          top_n <- min(input$proteomics_top_terms, nrow(gost_results))
          top_results <- gost_results[order(gost_results$p_value)[1:top_n], ]
          
          # Create term labels
          top_results$term_label <- paste(top_results$term_id, top_results$term_name, sep = ": ")
          top_results$term_label <- substr(top_results$term_label, 1, 60)
          
          # Create bar plot
          ggplot(top_results, aes(x = reorder(term_label, -log10(p_value)), y = -log10(p_value), fill = source)) +
            geom_bar(stat = "identity") +
            coord_flip() +
            labs(
              title = "Top Enriched Terms",
              x = "Term",
              y = "-log10(p-value)",
              fill = "Source"
            ) +
            theme_minimal() +
            theme(
              # Make all text black and bold
              axis.text.x = element_text(size = 10, color = "black", face = "bold"),
              axis.text.y = element_text(size = 10, color = "black", face = "bold"),
              axis.title.x = element_text(size = 12, color = "black", face = "bold"),
              axis.title.y = element_text(size = 12, color = "black", face = "bold"),
              plot.title = element_text(size = 14, color = "black", face = "bold"),
              legend.title = element_text(size = 10, color = "black", face = "bold"),
              legend.text = element_text(size = 9, color = "black", face = "bold"),
              legend.position = "bottom",
              # Add borders on all four sides
              panel.border = element_rect(color = "black", fill = NA, size = 1),
              axis.line = element_line(color = "black", size = 0.5),
              # Remove gridlines
              panel.grid.major = element_blank(),
              panel.grid.minor = element_blank()
            )
        }, res = UI_PLOT_RES)
      }
      
    }
    
    else if (input$proteomics_tool == "clusterprofiler") {
      tryCatch({
        # Make sure to use values$proteomics_results instead of enrichment_results
        req(values$proteomics_results)
        
        # Check if we have valid results to plot
        if (is.null(values$proteomics_results) || length(values$proteomics_results) == 0) {
          plot.new()
          text(0.5, 0.5, "No enrichment results available for visualization")
          return()
        }
        
        # Handle the list structure for multiple GO ontologies
        # First check if we have a list of results from multiple ontologies
        if (is.list(values$proteomics_results) && !is.data.frame(values$proteomics_results) &&
            !inherits(values$proteomics_results, "enrichResult")) {
          
          # If we have a list, check if we have a selection from UI
          if (!is.null(input$proteomics_cp_result_to_plot) &&
              input$proteomics_cp_result_to_plot %in% names(values$proteomics_results)) {
            # Use the selected result for visualization
            result_to_plot <- values$proteomics_results[[input$proteomics_cp_result_to_plot]]
          } else {
            # Default to first result if selection not available
            result_to_plot <- values$proteomics_results[[1]]
          }
        } else {
          # For a single result object, use it directly
          result_to_plot <- values$proteomics_results
        }
        
        # Now create the plots using the selected result
        if (input$proteomics_plot_type == "dotplot") {
          # Dotplot visualization
          clusterProfiler::dotplot(result_to_plot,
                                   showCategory = as.numeric(input$proteomics_top_terms),
                                   title = paste("Top Enriched Terms"))
          
        } else if (input$proteomics_plot_type == "barplot") {
          # Barplot visualization
          clusterProfiler::barplot(result_to_plot,
                                   showCategory = as.numeric(input$proteomics_top_terms),
                                   title = paste("Top Enriched Terms"))
          
        } else if (input$proteomics_plot_type == "enrichmap") {
          # Enrichment map (network of similar terms)
          if (nrow(result_to_plot) > 0) {
            # Limit to a reasonable number of terms to avoid visualization issues
            max_terms <- min(30, nrow(result_to_plot))
            enrichplot::emapplot(result_to_plot, showCategory = max_terms)
          } else {
            plot.new()
            text(0.5, 0.5, "No significant terms found for visualization")
          }
          
        } else if (input$proteomics_plot_type == "cnetplot") {
          # Gene-concept network
          if (nrow(result_to_plot) > 0) {
            # Limit to fewer categories for better visualization
            max_terms <- min(10, nrow(result_to_plot))
            enrichplot::cnetplot(result_to_plot,
                                 showCategory = max_terms,
                                 foldChange = NULL)
          } else {
            plot.new()
            text(0.5, 0.5, "No significant terms found for visualization")
          }
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error generating visualization:", e$message))
      }, res = UI_PLOT_RES)
    }
    
    else if (input$proteomics_tool == "reactomepa") {
      if (plot_type %in% c("dotplot", "barplot")) {
        output$proteomics_plot <- renderPlot({ 
          if (plot_type == "dotplot") {
            enrichplot::dotplot(proteomics_values$enrichment_results,
                                showCategory = min(input$proteomics_top_terms,
                                                   nrow(proteomics_values$enrichment_results)))
          } else {
            # Create barplot using enrichplot barplot function (more compatible)
            tryCatch({
              if (requireNamespace("enrichplot", quietly = TRUE)) {
                library(enrichplot)
                barplot(proteomics_values$enrichment_results,
                        showCategory = min(input$proteomics_top_terms,
                                           nrow(proteomics_values$enrichment_results)))
              } else {
                # Fallback to custom ggplot2 barplot
                tryCatch({
                  enrichment_df <- as.data.frame(proteomics_values$enrichment_results)
                  if (!is.null(enrichment_df) && nrow(enrichment_df) > 0) {
                    enrichment_df <- head(enrichment_df[order(enrichment_df$p.adjust), ],
                                          min(input$proteomics_top_terms, nrow(enrichment_df)))
                    
                    ggplot(enrichment_df, aes(x = Count, y = reorder(Description, Count))) +
                      geom_bar(stat = "identity", fill = "steelblue") +
                      labs(title = "ReactomePA Enrichment", x = "Gene Count", y = "Pathway") +
                      theme_bw() +
                      theme(axis.text.y = element_text(size = 10))
                  } else {
                    ggplot() +
                      labs(title = "No enrichment results available") +
                      theme_void()
                  }
                }, error = function(e) {
                  cat("Error creating ReactomePA barplot:", e$message, "\n")
                  ggplot() +
                    labs(title = "Error creating plot") +
                    theme_void()
                }, res = UI_PLOT_RES)
              }
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error creating ReactomePA barplot:", e$message), cex = 1.2)
            }, res = UI_PLOT_RES)
          }
        }, res = UI_PLOT_RES)
      } else if (plot_type %in% c("enrichmap", "cnetplot")) {
        output$proteomics_plot <- renderPlot({ 
          # Validate enrichment results before using
          enrichment_nrows <- 0
          tryCatch({
            if (!is.null(proteomics_values$enrichment_results)) {
              enrichment_nrows <- nrow(proteomics_values$enrichment_results)
            }
          }, error = function(e) {
            cat("Error getting enrichment results dimensions:", e$message, "\n")
          }, res = UI_PLOT_RES)
          
          if (enrichment_nrows > 50) {
            plot.new()
            text(0.5, 0.5, "Too many terms to visualize. Use dotplot or barplot instead.", cex = 1.2)
            return()
          }
          
          if (enrichment_nrows == 0) {
            plot.new()
            text(0.5, 0.5, "No enrichment results available for visualization.", cex = 1.2)
            return()
          }
          
          # Generate the network visualization
          if (plot_type == "enrichmap") {
            tryCatch({
              enrichplot::emapplot(proteomics_values$enrichment_results,
                                   showCategory = min(30, enrichment_nrows))
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error generating enrichment map:", e$message), cex = 1)
            }, res = UI_PLOT_RES)
          } else {
            tryCatch({
              # Check if this is GSEA results first and if ranking metric requires fold change
              enrichment_df_check <- as.data.frame(proteomics_values$enrichment_results)
              is_gsea <- "NES" %in% colnames(enrichment_df_check)
              requires_fold_change <- is_gsea && !is.null(input$proteomics_gsea_ranking_metric) &&
                input$proteomics_gsea_ranking_metric %in% c("log2fc", "signed_pval")
              should_use_fold_change <- requires_fold_change && !is.null(proteomics_values$fold_change_data)
              
              if (should_use_fold_change) {
                enrichplot::cnetplot(proteomics_values$enrichment_results,
                                     showCategory = min(10, nrow(proteomics_values$enrichment_results)),
                                     categorySize = "pvalue",
                                     foldChange = proteomics_values$fold_change_data)
              } else {
                enrichplot::cnetplot(proteomics_values$enrichment_results,
                                     showCategory = min(10, nrow(proteomics_values$enrichment_results)),
                                     categorySize = "pvalue")
              }
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste("Error generating gene-concept network:", e$message), cex = 1)
            }, res = UI_PLOT_RES)
          }
        }, res = UI_PLOT_RES)
      } else if (plot_type == "pathview") {
        output$proteomics_plot <- renderPlot({ 
          # Select top pathway to visualize
          if (nrow(proteomics_values$enrichment_results) == 0) {
            plot.new()
            text(0.5, 0.5, "No pathways available to visualize", cex = 1.2)
            return()
          }
          
          # Get top pathway ID
          top_pathway <- proteomics_values$enrichment_results@result$ID[1]
          
          # Show message that pathview will generate separate files
          plot.new()
          text(0.5, 0.6, "Pathway visualization files are being generated...", cex = 1.5)
          text(0.5, 0.5, paste("Top pathway:", top_pathway), cex = 1.2)
          text(0.5, 0.4, "Check the app's working directory for pathway images", cex = 1.2)
          
          # Generate pathview in background
          try({
            # Load pathview data including bods object
            # pathview may look for `bods` via normal symbol lookup, so load into .GlobalEnv
            tryCatch({
              utils::data("bods", package = "pathview", envir = .GlobalEnv)
            }, error = function(e) {
              cat("Note: Could not load pathview::bods dataset:", e$message, "\n")
            }, res = UI_PLOT_RES)

            # Graphviz mode relies on KEGGgraph helpers/data (e.g., KEGGEdgeSubtype)
            if (!is.null(input$pathview_engine) && input$pathview_engine == "graphviz") {
              tryCatch({
                utils::data("KEGGEdgeSubtype", package = "KEGGgraph", envir = .GlobalEnv)
              }, error = function(e) {
                cat("Note: Could not load KEGGgraph::KEGGEdgeSubtype dataset:", e$message, "\n")
              }, res = UI_PLOT_RES)
            }
            
            # Reuse safe wrapper in proteomics context with enhanced cleaning
            safe_pathview <- function(...) {
              args <- list(...)
              # Remove any na.rm arguments that might have been passed
              args$na.rm <- NULL
              # Drop NULL arguments (prevents passing split.group=NULL etc.)
              args <- args[!vapply(args, is.null, logical(1))]
              # Also clean any nested lists that might contain na.rm
              args <- lapply(args, function(x) {
                if (is.list(x)) {
                  x$na.rm <- NULL
                }
                return(x)
              }, res = UI_PLOT_RES)
              do.call(pathview::pathview, args)
            }
            safe_pathview(
              gene.data = proteomics_values$gene_list,
              pathway.id = top_pathway,
              species = gsub("hsapiens", "hsa", input$proteomics_organism),
              kegg.native = (input$pathview_engine == "kegg_native"),
              same.layer = FALSE,
              split.group = if (input$pathview_engine == "graphviz") isTRUE(input$graphviz_split_group) else NULL,
              expand.node = if (input$pathview_engine == "graphviz") isTRUE(input$graphviz_expand_node) else NULL
            )
          }, silent = TRUE)
        }, res = UI_PLOT_RES)
      }
      
      else if (input$proteomics_tool == "topgo") {
        tryCatch({
          req(enrichment_results)
          
          if (input$proteomics_plot_type == "barplot") {
            # Use the barplot function stored in results
            if (!is.null(enrichment_results$barplot)) {
              enrichment_results$barplot()
            } else {
              # Create a basic barplot if stored function not available
              result_table <- enrichment_results$table
              
              # Get the statistic that was used (stored in enrichment_results)
              used_statistic <- enrichment_results$statistic %||% "fisher"  # fallback to fisher
              
              # Check if the statistic column exists
              if (!used_statistic %in% colnames(result_table)) {
                # Try to find a suitable column
                possible_stats <- c("fisher", "ks", "t", "globaltest", "sum")
                found_stat <- NULL
                for (stat in possible_stats) {
                  if (stat %in% colnames(result_table)) {
                    found_stat <- stat
                    break
                  }
                }
                used_statistic <- found_stat %||% "fisher"
              }
              
              # Order by the correct statistic column
              if (used_statistic %in% colnames(result_table)) {
                stat_values <- as.numeric(result_table[[used_statistic]])
                ordered_indices <- order(stat_values)
                ordered_table <- result_table[ordered_indices, ]
              } else {
                ordered_table <- result_table  # Use as-is if no valid statistic column found
              }
              
              top_n <- min(20, nrow(ordered_table))
              top_terms <- head(ordered_table, top_n)
              
              # Create appropriate y-values based on statistic type
              if (used_statistic %in% colnames(top_terms)) {
                stat_values <- as.numeric(top_terms[[used_statistic]])
                
                if (used_statistic %in% c("fisher", "ks", "t")) {
                  y_values <- -log10(stat_values)
                  y_label <- paste0("-log10(", used_statistic, " p-value)")
                } else {
                  y_values <- stat_values
                  y_label <- paste(used_statistic, "statistic")
                }
              } else {
                # Fallback if no statistic column found
                y_values <- seq_along(top_terms$GO.ID)
                y_label <- "Rank"
              }
              
              barplot_data <- data.frame(
                Term = paste0(top_terms$GO.ID, ": ", top_terms$Term),
                StatValue = y_values,
                stringsAsFactors = FALSE
              )
              
              ggplot(barplot_data, aes(x = StatValue, y = reorder(Term, StatValue))) +
                geom_bar(stat = "identity", fill = "steelblue") +
                labs(title = paste("Top Enriched GO Terms -",
                                   input$proteomics_topgo_ontology),
                     subtitle = paste("Statistic:", used_statistic),
                     x = y_label,
                     y = "") +
                theme_bw() +
                theme(axis.text.y = element_text(size = 10),
                      plot.subtitle = element_text(size = 10, color = "gray50"))
            }
          } else if (input$proteomics_plot_type == "gograph") {
            # Generate GO graph
            if (!is.null(enrichment_results$go_graph_cmd)) {
              enrichment_results$go_graph_cmd()
            } else {
              plot.new()
              text(0.5, 0.5, "GO graph visualization not available")
            }
          } else {
            # Default fallback - create a simple table visualization
            result_table <- enrichment_results$table
            plot.new()
            title("topGO Results")
            grid::grid.table(head(result_table, 10))
          }
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, paste("Error generating topGO plot:", e$message), cex = 1)
        }, res = UI_PLOT_RES)
      }
      
      # Record and cache the generated plot for topGO
      tryCatch({
        recorded_plot <- recordPlot()
        if (!is.null(recorded_plot)) {
          store_proteomics_plot_in_cache(cache_key, recorded_plot)
          cat("Successfully cached topGO plot\n")
        }
      }, error = function(e) {
        cat("Failed to cache topGO plot:", e$message, "\n")
      }, res = UI_PLOT_RES)
    }
  })
  
  # Observer to populate gseaplot2 gene sets dropdown
  observe({
    req(input$proteomics_tool, input$proteomics_plot_type)
    
    # Only populate for gseaplot2 with ClusterProfiler
    if (input$proteomics_tool == "clusterprofiler" &&
        input$proteomics_plot_type == "gseaplot2") {
      
      # Check if we have enrichment results
      if (!is.null(proteomics_values$enrichment_results)) {
        tryCatch({
          
          # Handle both single result and multiple result scenarios
          enrichment_obj <- NULL
          
          # Check if we have multiple categories of results (list with multiple elements)
          if (is.list(proteomics_values$enrichment_results) &&
              !inherits(proteomics_values$enrichment_results, "enrichResult") &&
              !inherits(proteomics_values$enrichment_results, "gseaResult")) {
            
            # Multiple results - try to get the first available result
            if (length(proteomics_values$enrichment_results) > 0) {
              enrichment_obj <- proteomics_values$enrichment_results[[1]]
              cat("Using first enrichment result from multiple categories\n")
            }
          } else {
            # Single result object
            enrichment_obj <- proteomics_values$enrichment_results
            cat("Using single enrichment result object\n")
          }
          
          # Check if we have a valid enrichment object
          if (!is.null(enrichment_obj)) {
            # Convert to data frame to extract gene set names
            enrichment_df <- as.data.frame(enrichment_obj)
            
            # Check if this is GSEA results (has NES column) and has data
            if ("NES" %in% colnames(enrichment_df) && nrow(enrichment_df) > 0) {
              # Create choices with Description as display and ID as value
              if ("Description" %in% colnames(enrichment_df) && "ID" %in% colnames(enrichment_df)) {
                gene_set_choices <- setNames(enrichment_df$ID, enrichment_df$Description)
              } else if ("ID" %in% colnames(enrichment_df)) {
                gene_set_choices <- setNames(enrichment_df$ID, enrichment_df$ID)
              } else {
                # Fallback to row names
                gene_set_choices <- setNames(rownames(enrichment_df), rownames(enrichment_df))
              }
              
              # Limit to top 50 for dropdown performance
              if (length(gene_set_choices) > 50) {
                gene_set_choices <- gene_set_choices[1:50]
              }
              
              # Update the dropdown
              updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                                choices = gene_set_choices,
                                selected = gene_set_choices[1:min(3, length(gene_set_choices))])
              
              cat("Updated gseaplot2 gene sets dropdown with", length(gene_set_choices), "choices\n")
            } else if (nrow(enrichment_df) > 0) {
              # Has results but not GSEA
              updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                                choices = list("GSEA results required for gseaplot2" = ""),
                                selected = "")
              cat("Non-GSEA results available - gseaplot2 requires GSEA analysis\n")
            } else {
              # No results in the data frame
              updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                                choices = list("No enrichment results found" = ""),
                                selected = "")
              cat("Empty enrichment results data frame\n")
            }
          } else {
            # No enrichment object available
            updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                              choices = list("No enrichment results available" = ""),
                              selected = "")
            cat("No enrichment object available for gseaplot2\n")
          }
        }, error = function(e) {
          cat("Error updating gseaplot2 gene sets:", e$message, "\n")
          updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                            choices = list("Error loading gene sets" = ""),
                            selected = "")
        })
      } else {
        # No enrichment results yet
        updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                          choices = list("Run GSEA analysis first" = ""),
                          selected = "")
        cat("No enrichment results available yet for gseaplot2\n")
      }
    } else {
      # Not gseaplot2 or not ClusterProfiler - clear the dropdown
      updateSelectInput(session, "proteomics_gseaplot2_gene_sets",
                        choices = list("Select ClusterProfiler + GSEA Plot 2 first" = ""),
                        selected = "")
    }
  })
  
  # Observer to populate g:Profiler highlight terms dropdown
  observe({
    req(input$proteomics_tool, input$proteomics_plot_type)
    
    # Only populate for g:Profiler Manhattan plot
    if (input$proteomics_tool == "gprofiler" &&
        input$proteomics_plot_type == "manhattan") {
      
      # Check if we have enrichment results
      if (!is.null(proteomics_values$enrichment_results)) {
        tryCatch({
          # Get available terms from results - handle both g:Profiler and ClusterProfiler formats
          results_df <- NULL
          
          if (!is.null(proteomics_values$enrichment_results$result)) {
            # g:Profiler format
            results_df <- proteomics_values$enrichment_results$result
          } else if (inherits(proteomics_values$enrichment_results, "enrichResult")) {
            # ClusterProfiler format
            results_df <- as.data.frame(proteomics_values$enrichment_results)
          }
          
          if (!is.null(results_df) && nrow(results_df) > 0) {
            # Create choices with term_name as display and term_id as value
            if ("term_name" %in% colnames(results_df) && "term_id" %in% colnames(results_df)) {
              # Format display text with source and significance
              display_names <- results_df$term_name
              
              # Add source if available
              if ("source" %in% colnames(results_df)) {
                display_names <- paste0(display_names, " (", results_df$source, ")")
              }
              
              # Add p-value if available
              if ("p_value" %in% colnames(results_df)) {
                display_names <- paste0(display_names, " - p=", format(results_df$p_value, scientific = TRUE, digits = 2))
              }
              
              highlight_choices <- setNames(results_df$term_id, display_names)
            } else if ("term_id" %in% colnames(results_df)) {
              # Fallback to just term IDs
              highlight_choices <- setNames(results_df$term_id, results_df$term_id)
            } else {
              # No valid columns
              highlight_choices <- list("No valid terms found" = "")
            }
            
            # Limit to top 100 terms for dropdown performance, ordered by significance
            if (length(highlight_choices) > 100) {
              highlight_choices <- highlight_choices[1:100]
            }
            
            # Update the dropdown
            updateSelectInput(session, "proteomics_gprofiler_highlight_terms",
                              choices = highlight_choices,
                              selected = NULL)  # No terms selected by default
            
            cat("Updated g:Profiler highlight terms dropdown with", length(highlight_choices), "choices\n")
          } else {
            # No results
            updateSelectInput(session, "proteomics_gprofiler_highlight_terms",
                              choices = list("No enrichment results found" = ""),
                              selected = "")
            cat("No g:Profiler results available for highlighting\n")
          }
        }, error = function(e) {
          cat("Error updating g:Profiler highlight terms:", e$message, "\n")
          updateSelectInput(session, "proteomics_gprofiler_highlight_terms",
                            choices = list("Error loading terms" = ""),
                            selected = "")
        })
      } else {
        # No enrichment results yet
        updateSelectInput(session, "proteomics_gprofiler_highlight_terms",
                          choices = list("Run g:Profiler analysis first" = ""),
                          selected = "")
        cat("No g:Profiler results available yet for highlighting\n")
      }
    } else {
      # Not g:Profiler Manhattan plot - clear the dropdown
      updateSelectInput(session, "proteomics_gprofiler_highlight_terms",
                        choices = list("Select g:Profiler + Manhattan Plot first" = ""),
                        selected = "")
    }
  })
  
  # Observer to populate topGO graph terms dropdown
  observe({
    req(input$proteomics_tool, input$proteomics_plot_type)
    
    # Only populate for topGO GOGraph plot
    if (input$proteomics_tool == "topgo" &&
        input$proteomics_plot_type == "gograph") {
      
      # Check if we have enrichment results
      if (!is.null(proteomics_values$enrichment_results) &&
          !is.null(proteomics_values$enrichment_results$table)) {
        tryCatch({
          # Get available terms from topGO results
          results_table <- proteomics_values$enrichment_results$table
          
          if (nrow(results_table) > 0) {
            # Create choices with GO term info as display and GO.ID as value
            if ("GO.ID" %in% colnames(results_table) && "Term" %in% colnames(results_table)) {
              # Get the statistic column for significance ordering
              stat_col <- proteomics_values$enrichment_results$statistic %||% "fisher"
              
              # Format display text with GO ID, term name, and significance
              display_names <- paste0(results_table$GO.ID, ": ", results_table$Term)
              
              # Add significance information if available
              if (stat_col %in% colnames(results_table)) {
                stat_values <- as.numeric(results_table[[stat_col]])
                if (stat_col %in% c("fisher", "ks", "t")) {
                  # These are p-values, format appropriately
                  display_names <- paste0(display_names, " (p=", format(stat_values, scientific = TRUE, digits = 2), ")")
                } else {
                  # Other statistics, show raw values
                  display_names <- paste0(display_names, " (", stat_col, "=", round(stat_values, 3), ")")
                }
              }
              
              graph_choices <- setNames(results_table$GO.ID, display_names)
              
              # Order by significance (lowest p-values or highest statistics first)
              if (stat_col %in% colnames(results_table)) {
                stat_values <- as.numeric(results_table[[stat_col]])
                if (stat_col %in% c("fisher", "ks", "t")) {
                  # For p-values, order ascending (most significant first)
                  order_indices <- order(stat_values)
                } else {
                  # For other statistics, order descending (highest values first)
                  order_indices <- order(stat_values, decreasing = TRUE)
                }
                graph_choices <- graph_choices[order_indices]
              }
            } else if ("GO.ID" %in% colnames(results_table)) {
              # Fallback to just GO IDs
              graph_choices <- setNames(results_table$GO.ID, results_table$GO.ID)
            } else {
              # No valid columns
              graph_choices <- list("No valid GO terms found" = "")
            }
            
            # Limit to top 50 terms for dropdown performance
            if (length(graph_choices) > 50) {
              graph_choices <- graph_choices[1:50]
            }
            
            # Auto-select top 5 most significant terms by default (like documentation example)
            top_5_terms <- if (length(graph_choices) >= 5) {
              names(graph_choices)[1:5]  # First 5 terms (most significant)
            } else if (length(graph_choices) > 0) {
              names(graph_choices)  # All available terms if less than 5
            } else {
              NULL
            }
            
            # Update the dropdown with top 5 terms pre-selected
            updateSelectInput(session, "proteomics_topgo_graph_terms",
                              choices = graph_choices,
                              selected = top_5_terms)  # Auto-select top 5 significant terms
            
            cat("Updated topGO graph terms dropdown with", length(graph_choices), "choices\n")
            cat("Auto-selected top 5 terms:", top_5_terms, "\n")
          } else {
            # No results
            updateSelectInput(session, "proteomics_topgo_graph_terms",
                              choices = list("No topGO results found" = ""),
                              selected = "")
            cat("No topGO results available for graph\n")
          }
        }, error = function(e) {
          cat("Error updating topGO graph terms:", e$message, "\n")
          updateSelectInput(session, "proteomics_topgo_graph_terms",
                            choices = list("Error loading GO terms" = ""),
                            selected = "")
        })
      } else {
        # No enrichment results yet
        updateSelectInput(session, "proteomics_topgo_graph_terms",
                          choices = list("Run topGO analysis first" = ""),
                          selected = "")
        cat("No topGO results available yet for graph\n")
      }
    } else {
      # Not topGO GOGraph - clear the dropdown
      updateSelectInput(session, "proteomics_topgo_graph_terms",
                        choices = list("Select topGO + GO Graph first" = ""),
                        selected = "")
    }
  })
  
  # Observer to handle topGO graph term selections
  observeEvent(input$proteomics_topgo_graph_terms, {
    # Store selected terms for plotting
    if (!is.null(input$proteomics_topgo_graph_terms) &&
        length(input$proteomics_topgo_graph_terms) > 0) {
      proteomics_values$topgo_selected_terms <- input$proteomics_topgo_graph_terms
      cat("Updated topGO selected terms:", length(input$proteomics_topgo_graph_terms), "terms\n")
    } else {
      proteomics_values$topgo_selected_terms <- NULL
    }
  })
  
  # Display enrichment results table
  output$proteomics_table <- DT::renderDataTable({
    req(proteomics_values$enrichment_results)
    
    if (input$proteomics_tool == "gprofiler") {
      # Format g:Profiler results
      if (is.null(proteomics_values$enrichment_results) ||
          is.null(proteomics_values$enrichment_results$result)) {
        return(NULL)
      }
      
      tryCatch({
        # Check if required columns exist
        required_cols <- c("term_id", "term_name", "p_value", "term_size",
                           "query_size", "intersection_size", "effective_domain_size", "source")
        
        # Safely get column names
        result_colnames <- colnames(proteomics_values$enrichment_results$result)
        if (is.null(result_colnames)) {
          return(NULL)
        }
        
        available_cols <- intersect(required_cols, result_colnames)
        
        if (length(available_cols) > 0) {
          results <- proteomics_values$enrichment_results$result[, available_cols, drop = FALSE]
          
          # Create appropriate column names based on available columns
          col_name_map <- c(
            "term_id" = "Term ID", "term_name" = "Term Name", "p_value" = "p-value",
            "term_size" = "Term Size", "query_size" = "Query Size",
            "intersection_size" = "Overlap", "effective_domain_size" = "Domain Size",
            "source" = "Source"
          )
          colnames(results) <- col_name_map[available_cols]
          
          # Clean column names to ensure no empty or problematic names
          colnames(results) <- make.names(colnames(results), unique = TRUE)
          
          DT::datatable(results, options = list(pageLength = 15, scrollX = TRUE)) %>%
            DT::formatSignif(columns = which(grepl("p.value|p-value", colnames(results))), digits = 3)
        } else {
          # Fallback: use all available columns
          if (!is.null(proteomics_values$enrichment_results$result)) {
            results <- proteomics_values$enrichment_results$result
            colnames(results) <- make.names(colnames(results), unique = TRUE)
            DT::datatable(results, options = list(pageLength = 15, scrollX = TRUE))
          } else {
            return(NULL)
          }
        }
      }, error = function(e) {
        cat("Error formatting g:Profiler results:", e$message, "\n")
        return(DT::datatable(data.frame(Error = "Could not format results"),
                             options = list(pageLength = 15, scrollX = TRUE)))
      })
      
    } else if (input$proteomics_tool == "clusterprofiler") {
      req(input$proteomics_cp_result_to_plot)
      
      # Check if selected category exists
      if (!input$proteomics_cp_result_to_plot %in% names(proteomics_values$enrichment_results)) {
        return(NULL)
      }
      
      # Extract results for the selected category
      results_obj <- proteomics_values$enrichment_results[[input$proteomics_cp_result_to_plot]]
      results_df <- as.data.frame(results_obj)
      
      # Clean column names and remove empty columns
      empty_col_idx <- which(colnames(results_df) == "" | is.na(colnames(results_df)) | trimws(colnames(results_df)) == "" | colnames(results_df) == " ")
      if (length(empty_col_idx) > 0) {
        results_df <- results_df[, -empty_col_idx, drop = FALSE]
      }
      colnames(results_df) <- make.names(colnames(results_df), unique = TRUE)
      
      DT::datatable(results_df, options = list(pageLength = 15, scrollX = TRUE)) %>%
        DT::formatSignif(columns = c("pvalue", "p.adjust", "qvalue"), digits = 3)
      
    } else if (input$proteomics_tool == "enrichr") {
      req(input$proteomics_enrichr_db_to_plot)
      
      # Check if selected database exists
      if (!input$proteomics_enrichr_db_to_plot %in% names(proteomics_values$enrichment_results)) {
        return(NULL)
      }
      
      # Get results for the selected database
      db_results <- proteomics_values$enrichment_results[[input$proteomics_enrichr_db_to_plot]]
      
      # Clean column names and remove empty columns
      empty_col_idx <- which(colnames(db_results) == "" | is.na(colnames(db_results)) | trimws(colnames(db_results)) == "" | colnames(db_results) == " ")
      if (length(empty_col_idx) > 0) {
        db_results <- db_results[, -empty_col_idx, drop = FALSE]
      }
      colnames(db_results) <- make.names(colnames(db_results), unique = TRUE)
      
      DT::datatable(db_results, options = list(pageLength = 15, scrollX = TRUE)) %>%
        DT::formatSignif(columns = c("P.value", "Adjusted.P.value", "Combined.Score"), digits = 3)
      
    } else if (input$proteomics_tool == "reactomepa") {
      results_df <- as.data.frame(proteomics_values$enrichment_results)
      
      # Clean column names and remove empty columns
      empty_col_idx <- which(colnames(results_df) == "" | is.na(colnames(results_df)) | trimws(colnames(results_df)) == "" | colnames(results_df) == " ")
      if (length(empty_col_idx) > 0) {
        results_df <- results_df[, -empty_col_idx, drop = FALSE]
      }
      colnames(results_df) <- make.names(colnames(results_df), unique = TRUE)
      
      DT::datatable(results_df, options = list(pageLength = 15, scrollX = TRUE)) %>%
        DT::formatSignif(columns = c("pvalue", "p.adjust", "qvalue"), digits = 3)
      
    } else if (input$proteomics_tool == "topgo") {
      # For topGO, check if we have results in proteomics_values$enrichment_results
      if (!is.null(proteomics_values$enrichment_results) && !is.null(proteomics_values$enrichment_results$table)) {
        results_table <- proteomics_values$enrichment_results$table
        
        # Clean column names and remove empty columns
        empty_col_idx <- which(colnames(results_table) == "" | is.na(colnames(results_table)) | trimws(colnames(results_table)) == "" | colnames(results_table) == " ")
        if (length(empty_col_idx) > 0) {
          results_table <- results_table[, -empty_col_idx, drop = FALSE]
        }
        colnames(results_table) <- make.names(colnames(results_table), unique = TRUE)
        
        # Get the statistic column name used for this analysis
        statistic_col <- proteomics_values$enrichment_results$statistic
        stat_col_clean <- make.names(statistic_col, unique = TRUE)
        padj_col_clean <- make.names("padj", unique = TRUE)
        
        # Identify numeric columns for formatting
        numeric_cols <- c()
        if (stat_col_clean %in% colnames(results_table)) numeric_cols <- c(numeric_cols, stat_col_clean)
        if (padj_col_clean %in% colnames(results_table)) numeric_cols <- c(numeric_cols, padj_col_clean)
        
        dt_result <- DT::datatable(results_table, options = list(pageLength = 15, scrollX = TRUE))
        if (length(numeric_cols) > 0) {
          dt_result <- dt_result %>% DT::formatSignif(columns = numeric_cols, digits = 3)
        }
        dt_result
      } else {
        return(NULL)
      }
    }
  })
  
  # Download handler for enrichment results
  output$proteomics_download_results <- downloadHandler(
    filename = function() {
      paste0("Functional_Enrichment_", input$proteomics_tool, "_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      tryCatch({
        # Check for enrichment results in either location
        enrichment_data <- NULL
        if (!is.null(proteomics_values$enrichment_results)) {
          enrichment_data <- proteomics_values$enrichment_results
        } else if (!is.null(values$proteomics_results)) {
          enrichment_data <- values$proteomics_results
        }
        
        if (is.null(enrichment_data)) {
          showNotification("No enrichment results available for download", type = "error")
          return(NULL)
        }
        
        # Create workbook for Excel export
        if (!requireNamespace("openxlsx", quietly = TRUE)) {
          showNotification("openxlsx package is required for Excel export", type = "error")
          return(NULL)
        }
        
        wb <- openxlsx::createWorkbook()
        
        # Add enrichment results as the first sheet
        if (input$proteomics_tool == "gprofiler") {
          openxlsx::addWorksheet(wb, "Enrichment Results")
          results <- enrichment_data$result
          openxlsx::writeData(wb, "Enrichment Results", results)
          
        } else if (input$proteomics_tool == "clusterprofiler") {
          # For ClusterProfiler, the enrichment_data is the enrichResult object directly
          openxlsx::addWorksheet(wb, "Enrichment Results")
          results_df <- as.data.frame(enrichment_data)
          openxlsx::writeData(wb, "Enrichment Results", results_df)
        } else if (input$proteomics_tool == "enrichr") {
          # Add combined results as first sheet, then individual databases
          combined_results <- do.call(rbind, lapply(names(enrichment_data), function(db) {
            db_results <- enrichment_data[[db]]
            if (is.data.frame(db_results) && nrow(db_results) > 0) {
              db_results$Database <- db
              return(db_results)
            }
            return(NULL)
          }))
          
          if (!is.null(combined_results) && nrow(combined_results) > 0) {
            openxlsx::addWorksheet(wb, "Enrichment Results")
            openxlsx::writeData(wb, "Enrichment Results", combined_results)
          }
          
          # Add individual database sheets
          for (db in names(enrichment_data)) {
            db_results <- enrichment_data[[db]]
            if (is.data.frame(db_results) && nrow(db_results) > 0) {
              sheet_name <- substr(db, 1, 30)  # Limit sheet name length
              openxlsx::addWorksheet(wb, sheet_name)
              openxlsx::writeData(wb, sheet_name, db_results)
            }
          }
          
        } else if (input$proteomics_tool == "reactomepa") {
          openxlsx::addWorksheet(wb, "Enrichment Results")
          results_df <- as.data.frame(enrichment_data)
          openxlsx::writeData(wb, "Enrichment Results", results_df)
          
        } else if (input$proteomics_tool == "topgo") {
          openxlsx::addWorksheet(wb, "Enrichment Results")
          results_table <- enrichment_data$table
          openxlsx::writeData(wb, "Enrichment Results", results_table)
        }
        
        # Add sheet with analysis parameters
        openxlsx::addWorksheet(wb, "Analysis Parameters")
        param_data <- data.frame(
          Parameter = c("Tool", "Organism", "Data Source", "Number of Input Genes/Proteins",
                        "Analysis Date"),
          Value = c(
            switch(input$proteomics_tool,
                   "gprofiler" = "g:Profiler (gprofiler2)",
                   "clusterprofiler" = "ClusterProfiler",
                   "enrichr" = "Enrichr",
                   "reactomepa" = "ReactomePA",
                   "topgo" = "topGO"),
            switch(input$proteomics_organism,
                   "hsapiens" = "Homo sapiens (Human)",
                   "mmusculus" = "Mus musculus (Mouse)",
                   "rnorvegicus" = "Rattus norvegicus (Rat)",
                   "scerevisiae" = "Saccharomyces cerevisiae (Yeast)",
                   "dmelanogaster" = "Drosophila melanogaster (Fruit fly)",
                   "celegans" = "Caenorhabditis elegans (Worm)",
                   "btaurus" = "Bos taurus (Cow)",
                   "ggallus" = "Gallus gallus (Chicken)",
                   "drerio" = "Danio rerio (Zebrafish)",
                   "sscrofa" = "Sus scrofa (Pig)",
                   "ecoli" = "Escherichia coli",
                   "athaliana" = "Arabidopsis thaliana (Mouse-ear cress)",
                   input$proteomics_organism),
            switch(input$proteomics_source,
                   "intersection" = "Intersection Analysis",
                   "pairwise" = "Pairwise Comparison",
                   "manual" = "Manual Input"),
            length(proteomics_values$gene_list),
            format(Sys.time(), "%Y-%m-%d %H:%M:%S")
          ),
          stringsAsFactors = FALSE
        )
        openxlsx::writeData(wb, "Analysis Parameters", param_data)
        
        # Add sheet with input genes
        openxlsx::addWorksheet(wb, "Input Genes")
        openxlsx::writeData(wb, "Input Genes", data.frame(Gene = proteomics_values$gene_list))
        
        # Save the workbook
        openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
        
      }, error = function(e) {
        showNotification(paste("Error creating Excel file:", e$message), type = "error")
      })
    }
  )
  
  # Download handler for enrichment plot
  output$proteomics_download_enrichment_plot <- downloadHandler(
    filename = function() {
      paste0("Enrichment_", input$proteomics_tool, "_",
             input$proteomics_plot_type, "_Plot_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(proteomics_values$enrichment_results)
      
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      
      # Get the global image format
      image_format <- get_safe_global_image_format()
      
      enrichment_results <- proteomics_values$enrichment_results
      
      # Determine number of terms to show for cache key
      total_rows <- get_enrichment_results_nrow(enrichment_results, input$proteomics_tool)
      num_terms <- min(30, total_rows)
      if (!is.null(input$proteomics_top_terms) && !is.na(as.numeric(input$proteomics_top_terms))) {
        num_terms <- min(as.numeric(input$proteomics_top_terms), total_rows)
      }
      
      # Create cache key for download plot (different from display plot due to different dimensions/DPI)
      download_cache_key <- create_proteomics_plot_cache_key(
        tool = paste0(input$proteomics_tool, "_download"),
        plot_type = input$proteomics_plot_type,
        enrichment_results = enrichment_results,
        num_terms = num_terms,
        fold_change_data = proteomics_values$fold_change_data,
        color_theme = paste0(input$proteomics_plot_color %||% "default", "_dpi", dpi),
        highlight_terms = proteomics_values$highlight_terms
      )
      
      # Check if we have this download in cache
      cached_download <- get_proteomics_plot_from_cache(download_cache_key)
      if (!is.null(cached_download)) {
        # Using cached plot (re-written to avoid any accidental truncation / encoding issues)
        cat('Using cached proteomics download plot\n')
        # Save cached plot to file
        file.copy(cached_download, file)
        return()
      }
      
      cat('Generating new proteomics download plot and caching it\n')
      
      # Get font sizes from inputs or use defaults
      title_size <- if(!is.null(input$enrichment_title_size)) input$enrichment_title_size else 14
      axis_title_size <- if(!is.null(input$enrichment_axis_title_size)) input$enrichment_axis_title_size else 12
      axis_text_size <- if(!is.null(input$enrichment_axis_text_size)) input$enrichment_axis_text_size else 10
      legend_text_size <- if(!is.null(input$enrichment_legend_text_size)) input$enrichment_legend_text_size else 12
      legend_title_size <- max(8, legend_text_size - 2)  # Legend title slightly smaller than legend text
      
      tryCatch({
        # Generate the same plot as shown in the UI
        if (input$proteomics_tool == "gprofiler" && !is.null(enrichment_results$result)) {
          if (nrow(enrichment_results$result) == 0) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, "No enrichment results found with current settings.")
            dev.off()
            return()
          }
          
          if (input$proteomics_plot_type == "manhattan") {
            # For manhattan plot from g:Profiler - simplified version matching backup
            capped_value <- ifelse(is.null(input$proteomics_manhattan_capped), TRUE, input$proteomics_manhattan_capped)
            p <- gprofiler2::gostplot(enrichment_results, capped = capped_value, interactive = FALSE)
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = "png")
          } else if (input$proteomics_plot_type == "barplot") {
            # For barplot - EXACTLY matching the backup implementation
            gost_results <- enrichment_results$result
            
            # Take top N results - simplified version
            top_n <- min(as.numeric(input$proteomics_top_terms %||% 15), nrow(gost_results))
            top_results <- gost_results[order(gost_results$p_value)[1:top_n], ]
            
            # Create term labels
            top_results$term_label <- paste(top_results$term_id, top_results$term_name, sep = ": ")
            top_results$term_label <- substr(top_results$term_label, 1, 60)
            
            # Create bar plot - EXACTLY matching the backup implementation
            p <- ggplot(top_results, aes(x = reorder(term_label, -log10(p_value)), y = -log10(p_value), fill = source)) +
              geom_bar(stat = "identity") +
              coord_flip() +
              labs(
                title = "Top Enriched Terms",
                x = "Term",
                y = "-log10(p-value)",
                fill = "Source"
              ) +
              theme_minimal() +
              theme(
                # Make all text black and bold
                axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                plot.title = element_text(size = title_size, color = "black", face = "bold"),
                legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                legend.position = "bottom",
                # Add borders on all four sides
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                axis.line = element_line(color = "black", size = 0.5),
                # Remove gridlines
                panel.grid.major = element_blank(),
                panel.grid.minor = element_blank()
              )
            
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = "png")
          }
        } else if (input$proteomics_tool == "clusterprofiler") {
          # ClusterProfiler plot download - EXACTLY matching UI plot generation
          enrichment_results <- proteomics_values$enrichment_results
          req(enrichment_results)
          
          # Check if we have valid results to plot
          if (is.null(enrichment_results) || get_enrichment_results_nrow(enrichment_results, input$proteomics_tool) == 0) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, "No significant enrichment results found", cex = 1.5)
            dev.off()
            return()
          }
          
          # Determine number of terms to show - EXACTLY matching UI logic
          total_rows <- get_enrichment_results_nrow(enrichment_results, input$proteomics_tool)
          num_terms <- min(30, total_rows)
          if (!is.null(input$proteomics_top_terms) && !is.na(as.numeric(input$proteomics_top_terms))) {
            num_terms <- min(as.numeric(input$proteomics_top_terms), total_rows)
          }
          
          # Generate the appropriate plot based on plot type - EXACTLY matching UI
          if (input$proteomics_plot_type == "dotplot") {
            p <- enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
              theme(
                # Make all text black and bold
                axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                plot.title = element_text(size = title_size, color = "black", face = "bold"),
                legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                # Add black border
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                axis.line = element_line(color = "black", size = 0.5),
                # Remove gridlines
                panel.grid.major = element_blank(),
                panel.grid.minor = element_blank()
              )
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
          }
          else if (input$proteomics_plot_type == "barplot") {
            # Create barplot using enrichplot barplot function (more compatible)
            tryCatch({
              if (requireNamespace("enrichplot", quietly = TRUE)) {
                library(enrichplot)
                
                # Check if this is GSEA results - enrichplot::barplot doesn't work well with GSEA
                enrichment_df_check <- as.data.frame(enrichment_results)
                if ("NES" %in% colnames(enrichment_df_check)) {
                  # For GSEA results, use custom ggplot2 implementation
                  enrichment_df <- head(enrichment_df_check[order(enrichment_df_check$p.adjust), ], num_terms)
                  
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  # Use p.adjust for color gradient instead of fixed colors
                  enrichment_df$neg_log_padj <- -log10(enrichment_df$p.adjust)
                  
                  p <- ggplot(enrichment_df, aes(x = NES, y = reorder(Description, abs(NES)), fill = neg_log_padj)) +
                    geom_bar(stat = "identity") +
                    scale_fill_gradient(low = "lightblue", high = "darkred", name = "-log10(P.adj)") +
                    labs(title = "GSEA Enrichment Analysis", x = "Normalized Enrichment Score (NES)", y = y_label) +
                    theme_bw() +
                    theme(
                      axis.text.x = element_text(size = axis_text_size, color = "black", face = "bold"),
                      axis.text.y = element_text(size = axis_text_size, color = "black", face = "bold"),
                      axis.title.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                      axis.title.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                      plot.title = element_text(size = title_size, color = "black", face = "bold"),
                      legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                      legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      axis.line = element_line(color = "black", size = 0.5),
                      panel.grid.major = element_blank(),
                      panel.grid.minor = element_blank()
                    )
                } else {
                  # For ORA results, use enrichplot::barplot
                  p <- barplot(enrichment_results, showCategory = num_terms) +
                    scale_x_continuous(breaks = scales::pretty_breaks(n = 5)) +
                    theme(
                      # Make all text black and bold
                      axis.text.x = element_text(size = axis_title_size, color = "black", face = "bold"),
                      axis.text.y = element_text(size = axis_title_size, color = "black", face = "bold"),
                      axis.title.x = element_text(size = title_size, color = "black", face = "bold"),
                      axis.title.y = element_text(size = title_size, color = "black", face = "bold"),
                      plot.title = element_text(size = title_size + 2, color = "black", face = "bold"),
                      legend.title = element_text(size = legend_title_size, color = "black", face = "bold"),
                      legend.text = element_text(size = legend_text_size, color = "black", face = "bold"),
                      # Add black border
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      axis.line = element_line(color = "black", size = 0.5),
                      # Remove gridlines
                      panel.grid.major = element_blank(),
                      panel.grid.minor = element_blank()
                    )
                }
              } else {
                # Fallback to custom ggplot2 barplot
                enrichment_df <- as.data.frame(enrichment_results)
                enrichment_df <- head(enrichment_df[order(enrichment_df$p.adjust), ], num_terms)
                
                # Check if this is GSEA results (has NES column) or ORA results (has Count column)
                if ("NES" %in% colnames(enrichment_df)) {
                  # GSEA results - use NES (Normalized Enrichment Score)
                  # Determine y-axis label based on analysis type
                  y_label <- "Term"  # Default
                  if (!is.null(input$proteomics_cp_analysis)) {
                    if (grepl("kegg", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Pathway"
                    } else if (grepl("go", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "GO Term"
                    } else if (grepl("msigdb", input$proteomics_cp_analysis, ignore.case = TRUE)) {
                      y_label <- "Gene Set"
                    }
                  }
                  
                  # Use p.adjust for color gradient instead of fixed colors
                  enrichment_df$neg_log_padj <- -log10(enrichment_df$p.adjust)
                  
                  p <- ggplot(enrichment_df, aes(x = NES, y = reorder(Description, abs(NES)), fill = neg_log_padj)) +
                    geom_bar(stat = "identity") +
                    scale_fill_gradient(low = "lightblue", high = "darkred", name = "-log10(P.adj)") +
