          }
          else if (input$proteomics_plot_type == "upsetplot") {
            # Generate UpSet plot for ClusterProfiler results - EXACTLY matching UI
            tryCatch({
              # For upsetplot to show expression box plots, we need to use the original enrichment results
              # before any ID mapping modifications, as upsetplot relies on the internal GSEA structure
              
              # Check if we have the original enrichment results stored somewhere
              # If the enrichment_results has been modified for display, we need the original version
              if (exists("enrichment_results_original") && !is.null(enrichment_results_original)) {
                # Use the original enrichment results with ENTREZ IDs and embedded expression data
                p <- enrichplot::upsetplot(enrichment_results_original, n = min(num_terms, 20))
                ggsave(file, plot = p, width = 12, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
                return()
              } else {
                # If no original version is available, use the current enrichment_results
                # This should work if the enrichment_results hasn't been modified
                p <- enrichplot::upsetplot(enrichment_results, n = min(num_terms, 20))
                ggsave(file, plot = p, width = 12, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
                return()
              }
            }, error = function(e) {
              # Fallback to a custom UpSet plot if enrichplot version doesn't support it
              tryCatch({
                # Check if we have the required data structure
                if (!("geneID" %in% colnames(enrichment_results@result))) {
                  png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                  plot.new()
                  text(0.5, 0.5, "UpSet plot requires gene ID data.\nPlease use a different plot type.",
                       cex = 1.2, adj = 0.5)
                  dev.off()
                  return()
                }
                
                # Extract gene lists from enrichment results
                result_subset <- head(enrichment_results@result, min(num_terms, 10))
                gene_lists <- lapply(result_subset$geneID, function(x) {
                  if (is.na(x) || x == "") return(character(0))
                  strsplit(as.character(x), "/")[[1]]
                })
                
                # Create proper names for gene lists
                if ("Description" %in% colnames(result_subset)) {
                  list_names <- result_subset$Description
                } else if ("ID" %in% colnames(result_subset)) {
                  list_names <- result_subset$ID
                } else {
                  list_names <- paste("Set", seq_along(gene_lists))
                }
                
                # Truncate long names for display
                list_names <- sapply(list_names, function(name) {
                  if (nchar(name) > 30) {
                    paste0(substr(name, 1, 27), "...")
                  } else {
                    name
                  }
                })
                
                names(gene_lists) <- list_names
                
                # Remove empty gene lists
                gene_lists <- gene_lists[sapply(gene_lists, length) > 0]
                
                if (length(gene_lists) == 0) {
                  png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                  plot.new()
                  text(0.5, 0.5, "No gene sets available for UpSet plot",
                       cex = 1.2, adj = 0.5)
                  dev.off()
                  return()
                }
                
                # Use UpSetR package as fallback
                if (requireNamespace("UpSetR", quietly = TRUE)) {
                  # Create a binary matrix for UpSetR
                  all_genes <- unique(unlist(gene_lists))
                  
                  if (length(all_genes) == 0) {
                    png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                    plot.new()
                    text(0.5, 0.5, "No genes found in gene sets",
                         cex = 1.2, adj = 0.5)
                    dev.off()
                    return()
                  }
                  
                  upset_data <- data.frame(
                    Gene = all_genes,
                    stringsAsFactors = FALSE
                  )
                  
                  for (i in seq_along(gene_lists)) {
                    set_name <- names(gene_lists)[i]
                    upset_data[[set_name]] <- as.numeric(upset_data$Gene %in% gene_lists[[i]])
                  }
                  
                  # For UpSetR plots, we need to use a different approach for saving
                  png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                  UpSetR::upset(upset_data,
                                sets = names(gene_lists),
                                order.by = "freq",
                                nsets = min(length(gene_lists), 10),
                                nintersects = 20,
                                text.scale = c(1.2, 1, 1, 1, 1.5, 1),
                                point.size = 2.5,
                                line.size = 1)
                  dev.off()
                } else {
                  # Ultimate fallback - create error message plot
                  png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                  plot.new()
                  text(0.5, 0.5, "UpSet plot requires the UpSetR package.\nPlease install it with: install.packages('UpSetR')",
                       cex = 1.2, adj = 0.5)
                  dev.off()
                }
              }, error = function(e2) {
                png(file, width = 12*dpi, height = 8*dpi, res = dpi)
                plot.new()
                text(0.5, 0.5, paste("Error generating UpSet plot:\n", e2$message), cex = 1, adj = 0.5)
                dev.off()
              })
            })
