                dev.off()
                return()
              }
              
              # Get selected gene sets - EXACTLY matching UI logic
              selected_gene_sets <- input$proteomics_gseaplot2_gene_sets
              if (is.null(selected_gene_sets) || length(selected_gene_sets) == 0) {
                # Default to top 3 gene sets by significance
                selected_gene_sets <- head(enrichment_df_check$ID, 3)
              }
              
              # Validate that selected gene sets exist in results
              available_sets <- enrichment_df_check$ID
              valid_sets <- selected_gene_sets[selected_gene_sets %in% available_sets]
              
              if (length(valid_sets) == 0) {
                png(file, width = 12*dpi, height = 10*dpi, res = dpi)
                plot.new()
                text(0.5, 0.5, "No valid gene sets selected for gseaplot2.",
                     cex = 1.2, adj = 0.5)
                dev.off()
                return()
              }
              
              # Prepare gseaplot2 parameters - EXACTLY matching UI logic
              subplots <- input$proteomics_gseaplot2_subplots
              
              # Default to showing all subplots if none specified
              if (is.null(subplots) || length(subplots) == 0) {
                subplots <- c("gsea", "expr", "rank")
              }
              
              # For gseaplot2, we need to specify which subplots to show
              # The function expects a numeric vector: 1=GSEA, 2=Expression, 3=Ranking
              subplot_indices <- c()
              if ("gsea" %in% subplots) subplot_indices <- c(subplot_indices, 1)
              if ("expr" %in% subplots) subplot_indices <- c(subplot_indices, 2)
              if ("rank" %in% subplots) subplot_indices <- c(subplot_indices, 3)
              
              # Sort to maintain proper order
              subplot_indices <- sort(subplot_indices)
              
              # Create rel_heights vector based on the number of subplots
              base_height <- input$proteomics_gseaplot2_rel_heights %||% 1.5
              
              # For rel_heights, create a vector with the same length as subplot_indices
              # The enrichplot source expects rel_heights to match the length of subplots exactly
              if (length(subplot_indices) == 1) {
                rel_heights_vec <- base_height
              } else if (length(subplot_indices) == 2) {
                # Most common case: two subplots
                rel_heights_vec <- c(base_height, 1.0)
              } else if (length(subplot_indices) == 3) {
                # All three subplots
                rel_heights_vec <- c(base_height, 0.5, 1.0)
              } else {
                # Fallback for any other combination
                rel_heights_vec <- rep(1.0, length(subplot_indices))
              }
              
              # Prepare colors for multiple gene sets
              colors <- if (length(valid_sets) == 1) {
                "green"
              } else {
                # Use different colors for multiple gene sets
                c("#E495A5", "#86B875", "#7DB0DD", "#F2B866", "#C4A484")[seq_along(valid_sets)]
              }
              
              # Call gseaplot2 with proper parameter handling - EXACTLY matching UI logic
              tryCatch({
                # According to enrichplot documentation, gseaplot2 accepts vector of geneSetID
