              png(file, width = 12*dpi, height = 10*dpi, res = dpi)
              plot.new()
              text(0.5, 0.6, "Error generating gseaplot2:", cex = 1.2, adj = 0.5)
              text(0.5, 0.5, e$message, cex = 1, adj = 0.5, col = "red")
              text(0.5, 0.4, "Please check your GSEA results and try again.", cex = 1, adj = 0.5)
              dev.off()
            })
          }
          else {
            # Default fallback - EXACTLY matching UI
            p <- enrichplot::dotplot(enrichment_results, showCategory = num_terms) +
              theme(
                # Make all text black and bold
                axis.text.x = element_text(size = 10, color = "black", face = "bold"),
                axis.text.y = element_text(size = 10, color = "black", face = "bold"),
                axis.title.x = element_text(size = 12, color = "black", face = "bold"),
                axis.title.y = element_text(size = 12, color = "black", face = "bold"),
                plot.title = element_text(size = 14, color = "black", face = "bold"),
                legend.title = element_text(size = 10, color = "black", face = "bold"),
                legend.text = element_text(size = 9, color = "black", face = "bold"),
                # Add black border
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                axis.line = element_line(color = "black", size = 0.5),
                # Remove gridlines
                panel.grid.major = element_blank(),
                panel.grid.minor = element_blank()
              )
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
          }
          
        } else if (input$proteomics_tool == "enrichr") {
          # Enrichr plot download implementation
          req(input$proteomics_enrichr_db_to_plot)
          
          # Check if we have any results
          if (is.null(enrichment_results) || length(enrichment_results) == 0) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, "No enrichment results found", cex = 1.5)
            dev.off()
            return()
          }
          
          # Get results for the user-selected database
          db_name <- input$proteomics_enrichr_db_to_plot
          if (!db_name %in% names(enrichment_results)) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, paste("Database", db_name, "not found"), cex = 1.5)
            dev.off()
            return()
          }
          
          db_results <- enrichment_results[[db_name]]
          
          if (nrow(db_results) == 0) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, paste("No significant results for", db_name), cex = 1.5)
            dev.off()
            return()
          }
          
          # Sort by adjusted p-value and take top results
          db_results <- db_results[order(db_results$Adjusted.P.value), ]
          top_n <- min(as.numeric(input$proteomics_top_terms %||% 15), nrow(db_results))
          top_results <- head(db_results, top_n)
          
          # Clean Term names by removing GO identifiers (GO:xxxxxxx) for better readability
          top_results$Term <- gsub("\\s*\\(GO:\\d+\\)\\s*$", "", top_results$Term)
          
          # Generate plot based on plot type
          if (input$proteomics_plot_type == "barplot") {
            # Create a bar plot using custom ggplot2 (more reliable)
            tryCatch({
              p <- ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                           y = reorder(Term, -log10(Adjusted.P.value)))) +
                geom_bar(stat = "identity", fill = "steelblue") +
                labs(title = paste("Enrichr Bar Plot:", db_name),
                     x = "-log10(Adjusted P-value)",
                     y = "Term") +
                theme_bw() +
                theme(
                  axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                  axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                  axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                  axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                  plot.title = element_text(size = 16, color = "black", face = "bold"),
                  legend.title = element_text(size = 12, color = "black", face = "bold"),
                  legend.text = element_text(size = 11, color = "black", face = "bold"),
                  panel.border = element_rect(color = "black", fill = NA, size = 1),
                  panel.grid.major = element_blank(),
                  panel.grid.minor = element_blank()
                )
              ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
            }, error = function(e) {
              png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
              plot.new()
              text(0.5, 0.5, paste("Error creating barplot:", e$message), cex = 1.2)
              dev.off()
            })
          }
          else if (input$proteomics_plot_type == "dotplot") {
            # Create a custom dot plot for EnrichR results
            p <- ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                         y = reorder(Term, -log10(Adjusted.P.value)),
                                         size = Combined.Score)) +
              geom_point(color = "steelblue", alpha = 0.7) +
              scale_size_continuous(name = "Combined Score") +
              labs(title = paste("Enrichr Dot Plot:", db_name),
                   x = "-log10(Adjusted P-value)",
                   y = "Term") +
              theme_bw() +
              theme(
                axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                plot.title = element_text(size = 16, color = "black", face = "bold"),
                legend.title = element_text(size = 12, color = "black", face = "bold"),
                legend.text = element_text(size = 11, color = "black", face = "bold"),
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                panel.grid.major = element_blank(),
                panel.grid.minor = element_blank()
              )
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
          }
          else if (input$proteomics_plot_type == "enrichplot") {
            # Create an enrichment plot showing both p-value and combined score
            # Extract gene count from Overlap column (format: "5/123")
            top_results$gene_count <- as.numeric(gsub("/.*", "", top_results$Overlap))
            
            p <- ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                         y = Combined.Score,
                                         size = gene_count)) +
              geom_point(color = "steelblue", alpha = 0.7) +
              scale_size_continuous(name = "Gene Count") +
              labs(title = paste("Enrichr Enrichment Plot:", db_name),
                   x = "-log10(Adjusted P-value)",
                   y = "Combined Score") +
              theme_bw() +
              theme(
                axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                plot.title = element_text(size = 16, color = "black", face = "bold"),
                legend.title = element_text(size = 12, color = "black", face = "bold"),
                legend.text = element_text(size = 11, color = "black", face = "bold"),
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                panel.grid.major = element_blank(),
                panel.grid.minor = element_blank()
              )
            ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
          }
          else {
            # Default to bar plot using custom ggplot2
            tryCatch({
              p <- ggplot(top_results, aes(x = -log10(Adjusted.P.value),
                                           y = reorder(Term, -log10(Adjusted.P.value)))) +
                geom_bar(stat = "identity", fill = "steelblue") +
                labs(title = paste("Enrichr Bar Plot:", db_name),
                     x = "-log10(Adjusted P-value)",
                     y = "Term") +
                theme_bw() +
                theme(
                  axis.text.x = element_text(size = 12, color = "black", face = "bold"),
                  axis.text.y = element_text(size = 12, color = "black", face = "bold"),
                  axis.title.x = element_text(size = 14, color = "black", face = "bold"),
                  axis.title.y = element_text(size = 14, color = "black", face = "bold"),
                  plot.title = element_text(size = 16, color = "black", face = "bold"),
                  legend.title = element_text(size = 12, color = "black", face = "bold"),
                  legend.text = element_text(size = 11, color = "black", face = "bold"),
                  panel.border = element_rect(color = "black", fill = NA, size = 1),
                  panel.grid.major = element_blank(),
                  panel.grid.minor = element_blank()
                )
              ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
            }, error = function(e) {
              png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
              plot.new()
              text(0.5, 0.5, paste("Error creating plot:", e$message), cex = 1.2)
              dev.off()
            })
          }
          
        } else if (input$proteomics_tool == "topgo") {
          # topGO plot download implementation
          req(enrichment_results)
          
          if (nrow(enrichment_results$table) == 0) {
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, "No significant GO terms found")
            dev.off()
            return()
          }
          
          if (input$proteomics_plot_type == "barplot") {
            # Use the barplot function if available, otherwise create fallback
            if (!is.null(enrichment_results$barplot)) {
              # Use the stored barplot function
              p <- enrichment_results$barplot()
              ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
            } else {
              # Create fallback barplot
              result_table <- enrichment_results$table
              used_statistic <- enrichment_results$statistic %||% "fisher"
              
              # Order by the correct statistic
              if (used_statistic %in% colnames(result_table)) {
                stat_values <- as.numeric(result_table[[used_statistic]])
                ordered_indices <- order(stat_values)
                ordered_table <- result_table[ordered_indices, ]
              } else {
                ordered_table <- result_table
              }
              
              top_n <- min(20, nrow(ordered_table))
              top_terms <- head(ordered_table, top_n)
              
              # Create y-values based on statistic type
              if (used_statistic %in% colnames(top_terms)) {
                stat_vals <- as.numeric(top_terms[[used_statistic]])
                if (used_statistic %in% c("fisher", "ks", "t")) {
                  y_values <- -log10(stat_vals)
                  y_label <- paste0("-log10(", used_statistic, " p-value)")
                } else {
                  y_values <- stat_vals
                  y_label <- paste(used_statistic, "statistic")
                }
              } else {
                y_values <- seq_along(top_terms$GO.ID)
                y_label <- "Rank"
              }
              
              barplot_data <- data.frame(
                Term = top_terms$Term,  # Use only the Term name, without GO ID prefix
                StatValue = y_values,
                stringsAsFactors = FALSE
              )
              
              p <- ggplot(barplot_data, aes(x = StatValue, y = reorder(Term, StatValue))) +
                geom_bar(stat = "identity", fill = "steelblue") +
                labs(title = paste("Top GO Terms -", input$proteomics_topgo_ontology),
                     subtitle = paste("Algorithm:", input$proteomics_topgo_algorithm, "| Statistic:", used_statistic),
                     x = y_label,
                     y = "") +
                theme_bw() +
                theme(
                  axis.text.x = element_text(size = 10, color = "black", face = "bold"),
                  axis.text.y = element_text(size = 8, color = "black", face = "bold"),
                  axis.title.x = element_text(size = 12, color = "black", face = "bold"),
                  axis.title.y = element_text(size = 12, color = "black", face = "bold"),
                  plot.title = element_text(size = 14, color = "black", face = "bold"),
                  plot.subtitle = element_text(size = 10, color = "gray50"),
                  panel.border = element_rect(color = "black", fill = NA, size = 1),
                  panel.grid.major = element_blank(),
                  panel.grid.minor = element_blank()
                ) +
                scale_y_discrete(labels = function(x) {
                  # Wrap long labels to multiple lines
                  sapply(x, function(label) {
                    paste(strwrap(label, width = 50), collapse = "\n")
                  })
                })
              ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format))
            }
          } else if (input$proteomics_plot_type == "gograph") {
            # Generate GO graph with user-selected parameters for download
            if (!is.null(enrichment_results$go_graph_cmd)) {
              # Get user selections for graph parameters
              selected_terms <- input$proteomics_topgo_graph_terms
              first_sig_nodes <- input$proteomics_topgo_first_sig_nodes %||% 5
              use_info <- input$proteomics_topgo_use_info %||% "all"
              
              # Create the graph in a PNG file
              png(file, width = 12 * dpi, height = 10 * dpi, res = dpi)
              
              # Call the stored function with user parameters
              tryCatch({
                enrichment_results$go_graph_cmd(
                  selected_terms = selected_terms,
                  first_sig_nodes = first_sig_nodes,
                  use_info = use_info
                )
              }, error = function(e) {
                plot.new()
                text(0.5, 0.6, "Error generating GO graph", cex = 1.5, font = 2)
                text(0.5, 0.5, e$message, cex = 1, col = "red")
                text(0.5, 0.4, "Please check your GO term selections", cex = 1)
              })
              
              dev.off()
            } else {
              # Fallback if go_graph_cmd not available
              png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
              plot.new()
              text(0.5, 0.6, "GO Graph Visualization", cex = 1.5, font = 2)
              text(0.5, 0.5, "GO graph function not available", cex = 1.2)
              text(0.5, 0.4, "Please re-run the topGO analysis", cex = 1)
              dev.off()
            }
          } else {
            # Default fallback
            png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
            plot.new()
            text(0.5, 0.5, paste("topGO plot type", input$proteomics_plot_type, "not supported for download"))
            dev.off()
          }
          
        } else {
          # For other tools, create a generic plot or show not available message
          png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
          plot.new()
          text(0.5, 0.5, paste("Plot download not yet implemented for", input$proteomics_tool))
          dev.off()
        }
      }, error = function(e) {
        showNotification(paste("Error downloading plot:", e$message), type = "error")
        # Create a simple error plot
        png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
        plot.new()
        text(0.5, 0.5, paste("Error generating plot:", e$message))
        dev.off()
      })
      
      # Cache the generated file for future downloads
      tryCatch({
        if (file.exists(file)) {
          temp_cache_file <- tempfile(fileext = ".png")
          file.copy(file, temp_cache_file)
          store_proteomics_plot_in_cache(download_cache_key, temp_cache_file)
          cat("Successfully cached proteomics download plot\n")
        }
      }, error = function(e) {
        cat("Failed to cache proteomics download plot:", e$message, "\n")
      })
    }
  )
  
  # Download handler for network plot
  output$proteomics_download_network_plot <- downloadHandler(
    filename = function() {
      paste0("Network_", input$proteomics_tool, "_",
             input$proteomics_plot_type, "_Plot_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      req(proteomics_values$enrichment_results)
      
      # Get the user-specified DPI or use 300 as default
      dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
      
      # For network plots
      if (input$proteomics_plot_type %in% c("enrichmap", "cnetplot", "gograph")) {
        plot_obj <- proteomics_values$network_plots[[input$proteomics_plot_type]]
        req(plot_obj)
        ggsave(file, plot = plot_obj, width = 10, height = 8, dpi = dpi)
      }
    }
  )
  
  
  # Now add the UI elements for the Proteomics tab
  output$proteomics_cp_category_ui <- renderUI({
    req(proteomics_values$enrichment_results)
    
    if (input$proteomics_tool == "clusterprofiler") {
      selectInput(
        "proteomics_cp_result_to_plot",
        "Select Result Category:",
        choices = names(proteomics_values$enrichment_results),
        selected = names(proteomics_values$enrichment_results)[1]
      )
    }
  })
  
  output$proteomics_enrichr_db_ui <- renderUI({
    req(proteomics_values$enrichment_results)
    
    if (input$proteomics_tool == "enrichr") {
      selectInput(
        "proteomics_enrichr_db_to_plot",
        "Select Database:",
        choices = names(proteomics_values$enrichment_results),
        selected = names(proteomics_values$enrichment_results)[1]
      )
    }
  })
  
  # Update results status
  output$proteomics_results_status <- renderText({
    if (is.null(proteomics_values$enrichment_results)) {
      return("<div class='alert alert-warning'>No enrichment results available. Run an analysis first.</div>")
    } else {
      return("<div class='alert alert-success'>Enrichment analysis completed. View results below.</div>")
    }
  })
  
  # Update available plots
  output$proteomics_available_plots <- renderText({
    if (!is.null(proteomics_values$plots_available)) {
      plot_names <- switch(input$proteomics_tool,
                           "gprofiler" = c(manhattan = "Manhattan Plot", barplot = "Bar Plot"),
                           "clusterprofiler" = c(dotplot = "Dot Plot", barplot = "Bar Plot",
                                                 enrichmap = "Enrichment Map", cnetplot = "Gene-Concept Network"),
                           "enrichr" = c(barplot = "Bar Plot"),
                           "reactomepa" = c(dotplot = "Dot Plot", barplot = "Bar Plot",
                                            enrichmap = "Enrichment Map", cnetplot = "Gene-Concept Network",
                                            pathview = "Pathway View"),
                           "topgo" = c(barplot = "Bar Plot", gograph = "GO Graph"))
      
      available_plots <- names(plot_names)[names(plot_names) %in% proteomics_values$plots_available]
      available_plot_names <- plot_names[available_plots]
      
      paste("<strong>Available Plots:</strong> ", paste(available_plot_names, collapse=", "))
    } else {
      ""
    }
  })
  
  # Add this in your server function, alongside other proteomics-related code
  
  # Create a table of identified proteins/genes
  output$proteomics_genes_table <- DT::renderDataTable({
    # Add reactive dependencies for all parameters that affect gene list
    input$proteomics_source
    input$proteomics_intersection_set
    input$proteomics_pairwise_group1
    input$proteomics_pairwise_group2
    input$proteomics_pairwise_pval
    input$proteomics_pairwise_fc
    input$proteomics_fdr_cutoff
    input$proteomics_include_up
    input$proteomics_include_down
    input$proteomics_feature_source
    input$proteomics_manual_text
    input$proteomics_manual_file
    input$proteomics_manual_column
    input$proteomics_manual_input_type
    input$proteomics_manual_filetype
    input$feature_source
    input$pca_top_features
    input$pca_feature_ranking
    input$sig_method
    values$normalized_data
    values$cleaned_molecules
    values$stat_results
    values$intersection_comparison_results
    values$unique_groups
    values$selected_features
    
    # Check if we have gene list data
    if (is.null(proteomics_values$gene_list)) {
      # If no analysis has been run yet, try to get genes dynamically
      result <- get_gene_list()
      if (is.null(result$genes)) {
        return(data.frame(Message = "No genes/proteins identified yet. Run analysis first."))
      }
      genes <- result$genes
    } else {
      # Use stored gene list from analysis
      genes <- proteomics_values$gene_list
    }
    
    # Clean and validate genes list
    if (is.null(genes) || length(genes) == 0) {
      return(DT::datatable(
        data.frame(Message = "No genes/proteins identified with current settings."),
        options = list(pageLength = 10, scrollX = TRUE, dom = 'tip'),
        rownames = FALSE
      ))
    }
    
    # Remove any empty, NA, or whitespace-only entries more thoroughly
    genes <- genes[!is.na(genes) & !is.null(genes) & nchar(trimws(as.character(genes))) > 0]
    # Also remove any entries that are just whitespace characters
    genes <- genes[!grepl("^\\s+$", genes)]
    
    if (length(genes) == 0) {
      return(DT::datatable(
        data.frame(Message = "No valid genes/proteins found after filtering."),
        options = list(pageLength = 10, scrollX = TRUE, dom = 'tip'),
        rownames = FALSE
      ))
    }
    
    # Create a data frame for display with clean column names
    gene_df <- data.frame(
      Index = 1:length(genes),
      Gene_ID = as.character(genes),  # Ensure it's character
      Feature_Name = rep(NA_character_, length(genes)),  # Always include Feature_Name column
      stringsAsFactors = FALSE
    )
    
    # Fill feature names if available
    if (!is.null(proteomics_values$gene_list_feature_names) &&
        length(proteomics_values$gene_list_feature_names) == length(genes)) {
      gene_df$Feature_Name <- as.character(proteomics_values$gene_list_feature_names)
    }
    
    # Ensure column names are clean and valid
    colnames(gene_df) <- make.names(colnames(gene_df), unique = TRUE)
    
    # Double-check for any empty or problematic column names
    if (any(colnames(gene_df) == "" | is.na(colnames(gene_df)) | trimws(colnames(gene_df)) == "")) {
      colnames(gene_df) <- paste0("Col_", seq_len(ncol(gene_df)))
    }
    
    # Return the datatable with proper formatting
    DT::datatable(
      gene_df,
      options = list(
        pageLength = 10,
        scrollX = TRUE,
        dom = 'tip'  # table, information, pagination
      ),
      rownames = FALSE
    )
  })
  
  # Render UI for paste sets input
  output$intersection_paste_sets_ui <- renderUI({
    if (input$intersection_source == "manual" && input$intersection_manual_input_type == "paste") {
      # Get current number of sets
      num_sets <- values$intersection_paste_sets_count
      
      # Create UI elements for each set
      set_ui <- lapply(1:num_sets, function(i) {
        div(class = "mlfs-card", style = "margin-bottom: 15px;",
            div(class = "mlfs-card-body",
                if(i > 2) {  # Only show remove button for sets beyond the initial 2
                  div(style = "text-align: right; margin-bottom: 10px;",
                      actionButton(paste0("remove_intersection_set_", i), "",
                                   icon = icon("trash"),
                                   title = "Remove this set",
                                   style = "background-color: #ef4444; color: white; border: none; padding: 4px 8px; border-radius: 4px; cursor: pointer;")
                  )
                },
                textInput(paste0("intersection_set_name_", i), "Set Name:",
                         value = paste("Set", i), width = "100%"),
                textAreaInput(paste0("intersection_set_features_", i), "Features (one per line):",
                             placeholder = "Paste your features here, one per line",
                             rows = 5, width = "100%")
            )
        )
      })
      
      # Add "Add Set" button
      add_button <- div(style = "text-align: center; margin-top: 15px;",
                        actionButton("add_intersection_set", "Add Another Set",
                                     icon = icon("plus"), class = "btn-primary"))
      
      # Combine all UI elements
      tagList(set_ui, add_button)
    } else {
      return(NULL)
    }
  })
  
  # Observer for adding intersection sets
  observeEvent(input$add_intersection_set, {
    values$intersection_paste_sets_count <- values$intersection_paste_sets_count + 1
  })
  
  # Observers for removing intersection sets (dynamic observers for each set)
  observe({
    num_sets <- values$intersection_paste_sets_count
    if(num_sets > 2) {  # Only create observers for sets that can be removed
      for(i in 3:num_sets) {
        local({
          local_i <- i
          observeEvent(input[[paste0("remove_intersection_set_", local_i)]], {
            # Remove the set by shifting all subsequent sets down
            values$intersection_paste_sets_count <- values$intersection_paste_sets_count - 1
            
            # Note: The UI will automatically update due to the reactive renderUI
            # The input values will be preserved for the remaining sets
          }, ignoreInit = TRUE)
        })
      }
    }
  })
  
  # ============================================================================
  # METABOLOMICS TAB SERVER CODE
  # ============================================================================
  
  # Initialize metabolomics reactive values
  metab_values <- reactiveValues(
    id_mapping_results = NULL,
    classification_data = NULL,
    pathway_data = NULL,
    pathway_summary = NULL,
    module_data = NULL,           # KEGG module raw data
    module_summary = NULL,        # KEGG module enrichment results
    current_plot = NULL,
    summary_text = NULL,
    mapping_in_progress = FALSE,
    # Fuzzy match review system
    fuzzy_suggestions = NULL,      # Data frame of fuzzy match suggestions
    fuzzy_pending_review = FALSE,  # Flag to show review modal
    fuzzy_original_results = NULL, # Original batch results (before fuzzy corrections)
    fuzzy_molecule_names = NULL,   # Original molecule names list
    fuzzy_selected_databases = NULL # Databases used in search
  )
  
  # =========================================================================
  # METABOLOMICS DATA SOURCE SHOW/HIDE OBSERVERS
  # =========================================================================
  
  # Main data source toggle (Intersection/Pairwise/Manual)
  observe({
    shinyjs::hide("metab_intersection_block")
    shinyjs::hide("metab_pairwise_block")
    shinyjs::hide("metab_manual_block")
    
    switch(input$metab_source,
           intersection  = shinyjs::show("metab_intersection_block"),
           pairwise      = shinyjs::show("metab_pairwise_block"),
           manual        = shinyjs::show("metab_manual_block"))
  })
  
  # Manual input method toggle (File/Paste)
  observe({
    shinyjs::hide("metab_manual_file_block")
    shinyjs::hide("metab_manual_paste_block")
    
    if (!is.null(input$metab_source) && input$metab_source == "manual") {
      if (!is.null(input$metab_manual_input_type)) {
        if (input$metab_manual_input_type == "file") {
          shinyjs::show("metab_manual_file_block")
        } else if (input$metab_manual_input_type == "paste") {
          shinyjs::show("metab_manual_paste_block")
        }
      }
    }
  })
  
  # FDR cutoff visibility - only show when ROTS is selected
  observe({
    if (!is.null(input$sig_method) && input$sig_method == "rots") {
      shinyjs::show("metab_fdr_cutoff_container")
    } else {
      shinyjs::hide("metab_fdr_cutoff_container")
    }
  })
  
  # Toggle cutoff row layout based on ROTS selection
  observe({
    if (!is.null(input$sig_method) && input$sig_method == "rots") {
      shinyjs::removeClass("metab_cutoff_row", "cutoff-row-without-fdr")
      shinyjs::addClass("metab_cutoff_row", "cutoff-row-with-fdr")
    } else {
      shinyjs::removeClass("metab_cutoff_row", "cutoff-row-with-fdr")
      shinyjs::addClass("metab_cutoff_row", "cutoff-row-without-fdr")
    }
  })
  
  # Update pairwise group selections when data is available
  observe({
    req(values$unique_groups)
    groups <- values$unique_groups
    
    updateSelectInput(session, "metab_pairwise_group1", 
                      choices = groups, 
                      selected = if (length(groups) >= 1) groups[1] else NULL)
    updateSelectInput(session, "metab_pairwise_group2", 
                      choices = groups, 
                      selected = if (length(groups) >= 2) groups[2] else NULL)
  })
  
  # Update intersection set choices when available
  observe({
    req(values$comparison_results)
    # Get intersection names from comparison results
    intersection_sets <- tryCatch({
      if (!is.null(values$comparison_results$intersection_sets)) {
        names(values$comparison_results$intersection_sets)
      } else {
        NULL
      }
    }, error = function(e) NULL)
    
    if (!is.null(intersection_sets) && length(intersection_sets) > 0) {
      updateSelectInput(session, "metab_intersection_set", 
                        choices = intersection_sets,
                        selected = intersection_sets[1])
    }
  })
  
  # Update column choices when manual file is uploaded
  observeEvent(input$metab_manual_file, {
    req(input$metab_manual_file)
    
    file_path <- input$metab_manual_file$datapath
    file_name <- input$metab_manual_file$name
    
    tryCatch({
      # Read a small preview for column names
      if (grepl("\\.csv$", file_name, ignore.case = TRUE)) {
        df <- read.csv(file_path, stringsAsFactors = FALSE, nrows = 5)
      } else if (grepl("\\.(tab|tsv)$", file_name, ignore.case = TRUE)) {
        df <- read.delim(file_path, stringsAsFactors = FALSE, nrows = 5)
      } else if (grepl("\\.(xlsx|xls)$", file_name, ignore.case = TRUE)) {
        df <- readxl::read_excel(file_path, n_max = 5)
      } else if (grepl("\\.txt$", file_name, ignore.case = TRUE)) {
        df <- tryCatch(read.delim(file_path, stringsAsFactors = FALSE, nrows = 5),
                       error = function(e) NULL)
      } else {
        df <- NULL
      }
      
      if (!is.null(df) && ncol(df) > 0) {
        updateSelectInput(session, "metab_manual_file_column",
                          choices = colnames(df),
                          selected = colnames(df)[1])
      } else {
        updateSelectInput(session, "metab_manual_file_column",
                          choices = character(0),
                          selected = character(0))
      }
    }, error = function(e) {
      showNotification(paste("Error reading file:", e$message), type = "error")
    })
  })
  
  # =========================================================================
  # CUSTOM BACKGROUND UNIVERSE HANDLING
  # =========================================================================
  
  # Reactive to get custom background molecules count
  metab_custom_background_molecules <- reactive({
    # Only compute if custom background is selected for manual input
    if (is.null(input$metab_source) || input$metab_source != "manual") return(NULL)
    if (is.null(input$metab_manual_background_type) || input$metab_manual_background_type != "custom") return(NULL)
    
    bg_molecules <- NULL
    
    if (input$metab_manual_input_type == "paste") {
      # Get from pasted background text
      if (!is.null(input$metab_custom_background_paste) && nchar(trimws(input$metab_custom_background_paste)) > 0) {
        bg_molecules <- strsplit(input$metab_custom_background_paste, "\\n")[[1]]
        bg_molecules <- trimws(bg_molecules)
        bg_molecules <- bg_molecules[bg_molecules != "" & !is.na(bg_molecules)]
      }
    } else if (input$metab_manual_input_type == "file") {
      # Get from sheet 2 of uploaded Excel file
      req(input$metab_manual_file)
      
      file_path <- input$metab_manual_file$datapath
      file_name <- input$metab_manual_file$name
      
      if (grepl("\\.(xlsx|xls)$", file_name, ignore.case = TRUE)) {
        tryCatch({
          # Check if sheet 2 exists
          sheet_names <- readxl::excel_sheets(file_path)
          if (length(sheet_names) >= 2) {
            sheet2_data <- readxl::read_excel(file_path, sheet = 2, col_names = TRUE)
            if (ncol(sheet2_data) >= 1 && nrow(sheet2_data) > 0) {
              bg_molecules <- as.character(sheet2_data[[1]])
              bg_molecules <- bg_molecules[!is.na(bg_molecules) & bg_molecules != ""]
            }
          }
        }, error = function(e) {
          message("[BACKGROUND] Error reading sheet 2: ", e$message)
        })
      }
    }
    
    return(bg_molecules)
  })
  
  # Render status for sheet 2 background
  output$metab_background_sheet_status <- renderUI({
    if (is.null(input$metab_manual_file)) {
      return(tags$span(style = "color: #6c757d; font-style: italic;", 
                       icon("info-circle"), " No file uploaded yet. KEGG default will be used if no custom background is provided."))
    }
    
    file_name <- input$metab_manual_file$name
    if (!grepl("\\.(xlsx|xls)$", file_name, ignore.case = TRUE)) {
      return(tags$span(style = "color: #17a2b8;", 
                       icon("info-circle"), " CSV/TXT file detected. KEGG default will be used for background."))
    }
    
    # Check if sheet 2 exists and has data
    file_path <- input$metab_manual_file$datapath
    tryCatch({
      sheet_names <- readxl::excel_sheets(file_path)
      if (length(sheet_names) < 2) {
        return(tags$span(style = "color: #17a2b8;", 
                         icon("info-circle"), " No custom background found. KEGG default will be used for background."))
      }
      
      sheet2_data <- readxl::read_excel(file_path, sheet = 2, col_names = TRUE)
      if (nrow(sheet2_data) == 0) {
        return(tags$span(style = "color: #17a2b8;", 
                         icon("info-circle"), " Custom background list is empty. KEGG default will be used for background."))
      }
      
      n_bg <- sum(!is.na(sheet2_data[[1]]) & sheet2_data[[1]] != "")
      return(tags$span(style = "color: #28a745;", 
                       icon("check-circle"), sprintf(" Found %s molecules in custom background ('%s')", 
                                                     format(n_bg, big.mark = ","), sheet_names[2])))
    }, error = function(e) {
      return(tags$span(style = "color: #dc3545;", 
                       icon("exclamation-triangle"), " Error reading Sheet 2: ", e$message))
    })
  })
  
  # Render the count of custom background molecules
  output$metab_custom_background_count <- renderUI({
    bg_molecules <- metab_custom_background_molecules()
    
    if (is.null(bg_molecules) || length(bg_molecules) == 0) {
      return(tags$div(style = "margin-top: 8px; padding: 6px 10px; background-color: #e7f3ff; border-radius: 4px; font-size: 12px;",
                      icon("info-circle", style = "color: #0056b3;"),
                      tags$span(style = "color: #0056b3;", " Optional: If not provided, KEGG default will be used")))
    }
    
    tags$div(style = "margin-top: 8px; padding: 6px 10px; background-color: #d4edda; border-radius: 4px; font-size: 12px;",
             icon("check-circle", style = "color: #155724;"),
             tags$span(style = "color: #155724; font-weight: 600;", 
                       sprintf(" Background universe: %s molecules", format(length(bg_molecules), big.mark = ","))))
  })
  
  # Render feature set status for pairwise comparison
  output$metab_feature_set_status <- renderUI({
    feature_source <- input$metab_feature_source
    
    if (is.null(feature_source)) return(NULL)
    
    status_text <- switch(feature_source,
      "all" = "Using all features from the dataset",
      "pca" = if (!is.null(values$pca_top_features)) {
        paste0("Using ", length(values$pca_top_features), " PCA-selected features")
      } else {
        tags$span(style = "color: #e74c3c;", "No PCA features available - run PCA first")
      },
      "ml" = if (!is.null(values$ml_selected_features)) {
        paste0("Using ", length(values$ml_selected_features), " ML-selected features")
      } else {
        tags$span(style = "color: #e74c3c;", "No ML features available - run feature selection first")
      },
      NULL
    )
    
    if (!is.null(status_text)) {
      tags$small(class = "text-muted", status_text)
    }
  })
  
  # Update Metabolomics group selections when data is processed
  observe({
    req(values$unique_groups)
    # Any group-related inputs for metabolomics would be updated here
  })
  
  # Observer for ID mapping button - Full replica of Data tab ID mapping logic
  observeEvent(input$apply_metab_mapping, {
    # For manual input, we don't need processed data
    # For intersection/pairwise, we need processed data
    metab_source <- input$metab_source %||% "pairwise"
    
    # Initialize pre_existing_ids for manual input handling
    pre_existing_ids <- NULL
    
    if (metab_source != "manual") {
      # Non-manual sources require processed data
      if (is.null(values$normalized_data) || is.null(values$cleaned_molecules)) {
        showNotification(
          "Please process your data in the Data tab first before mapping metabolite IDs, or use Manual Input mode.",
          type = "warning",
          duration = 5
        )
        return()
      }
      req(values$normalized_data, values$cleaned_molecules)
    }
    
    # Initialize session cache if not exists
    if (is.null(metab_values$id_mapping_cache)) {
      metab_values$id_mapping_cache <- list()
    }
    
    # Lazy load metabolomics packages
    lazy_load_packages(c("KEGGREST", "PubChemR", "biodb", "ChemmineR", "biodbChebi", "future.apply", "progressr"))
    
    # Get selected databases
    selected_databases <- input$metab_target_dbs
    if (is.null(selected_databases) || length(selected_databases) == 0) {
      selected_databases <- c("kegg", "pubchem", "hmdb")  # Default
    }
    
    # Always use parallel processing for faster execution
    use_parallel <- TRUE
    
    # Get metabolite names based on selected source (intersection/pairwise/manual)
    molecule_names <- NULL
    
    # Determine source and get appropriate metabolite list
    if (input$metab_source == "intersection") {
      # Get metabolites from selected intersection set
      req(input$metab_intersection_set)
      
      if (!is.null(values$comparison_results$intersection_sets)) {
        selected_set <- values$comparison_results$intersection_sets[[input$metab_intersection_set]]
        
        if (!is.null(selected_set) && length(selected_set) > 0) {
          molecule_names <- selected_set
          showNotification(paste("Using", length(molecule_names), "metabolites from intersection set:", 
                                input$metab_intersection_set), type = "message", duration = 3)
        } else {
          showNotification("Selected intersection set is empty", type = "error", duration = 5)
          metab_values$mapping_in_progress <- FALSE
          return()
        }
      } else {
        showNotification("No intersection results available. Please run intersection analysis first.", 
                        type = "error", duration = 5)
        metab_values$mapping_in_progress <- FALSE
        return()
      }
      
    } else if (input$metab_source == "pairwise") {
      # Get metabolites from pairwise comparison with filters
      req(input$metab_pairwise_group1, input$metab_pairwise_group2)
      req(values$stat_results)
      
      comparison_name <- paste(input$metab_pairwise_group1, "vs", input$metab_pairwise_group2)
      
      # Use the same helper functions as enrichment tab
      p_value_column <- get_appropriate_pvalue_column(comparison_name)
      fc_column <- get_foldchange_column(comparison_name)
      
      # Handle reversed fold change column
      fc_reversed <- FALSE
      if (!is.null(fc_column) && grepl("^REVERSED:", fc_column)) {
        fc_column <- sub("^REVERSED:", "", fc_column)
        fc_reversed <- TRUE
      }
      
      if (is.null(p_value_column) || is.null(fc_column) ||
          !(p_value_column %in% colnames(values$stat_results)) ||
          !(fc_column %in% colnames(values$stat_results))) {
        showNotification(paste("Statistical columns not found for", comparison_name, 
                              ". Please run statistical analysis first."),
                        type = "error", duration = 5)
        metab_values$mapping_in_progress <- FALSE
        return()
      }
      
      # Apply filters
      p_values <- values$stat_results[[p_value_column]]
      log2fc_values <- values$stat_results[[fc_column]]
      if (fc_reversed) log2fc_values <- -log2fc_values
      
      significant_idx <- which(!is.na(p_values) & !is.na(log2fc_values) &
                               p_values <= input$metab_pairwise_pval &
                               abs(log2fc_values) >= input$metab_pairwise_fc)
      
      if (length(significant_idx) == 0) {
        showNotification(paste("No significant metabolites found for", comparison_name,
                              "with p-value <=", input$metab_pairwise_pval,
                              "and |log2FC| >=", input$metab_pairwise_fc),
                        type = "warning", duration = 5)
        metab_values$mapping_in_progress <- FALSE
        return()
      }
      
      molecule_names <- values$cleaned_molecules[significant_idx]
      showNotification(paste("Using", length(molecule_names), "significant metabolites from", comparison_name),
                      type = "message", duration = 3)
      
    } else if (input$metab_source == "manual") {
      # Get metabolites from manual input
      if (input$metab_manual_input_type == "file") {
        req(input$metab_manual_file)
        
        # Read metabolites from file
        file_path <- input$metab_manual_file$datapath
        file_ext <- tools::file_ext(input$metab_manual_file$name)
        
        tryCatch({
          if (file_ext %in% c("csv")) {
            data <- read.csv(file_path, header = TRUE, stringsAsFactors = FALSE)
          } else if (file_ext %in% c("tsv", "tab")) {
            data <- read.delim(file_path, header = TRUE, stringsAsFactors = FALSE)
          } else if (file_ext %in% c("txt")) {
            data <- tryCatch(read.delim(file_path, header = TRUE, stringsAsFactors = FALSE),
                             error = function(e) NULL)
            if (is.null(data)) {
              raw_lines <- readLines(file_path, warn = FALSE)
              data <- data.frame(Value = raw_lines, stringsAsFactors = FALSE)
            }
          } else if (file_ext %in% c("xlsx", "xls")) {
            data <- readxl::read_excel(file_path)
          } else {
            showNotification("Unsupported file format. Use CSV, TSV, TXT, or Excel files.",
                            type = "error", duration = 5)
            metab_values$mapping_in_progress <- FALSE
            return()
          }
          
          # Use selected column if available; fallback to first column
          selected_col <- input$metab_manual_file_column
          if (!is.null(selected_col) && selected_col %in% colnames(data)) {
            molecule_names <- as.character(data[[selected_col]])
          } else {
            molecule_names <- as.character(data[[1]])
          }
          molecule_names <- molecule_names[molecule_names != "" & !is.na(molecule_names)]
          
          # Deduplicate manual input and warn user if duplicates found
          n_before <- length(molecule_names)
          molecule_names <- unique(molecule_names)
          n_after <- length(molecule_names)
          if (n_before > n_after) {
            showNotification(
              paste0("Found ", n_before - n_after, " duplicate entries in your file. Using ", n_after, " unique metabolites."),
              type = "info", duration = 5
            )
          }
          
        }, error = function(e) {
          showNotification(paste("Error reading file:", e$message), type = "error", duration = 5)
          metab_values$mapping_in_progress <- FALSE
          return()
        })
        
      } else {
        # Get from pasted text
        req(input$metab_manual_paste)
        
        molecule_names <- strsplit(input$metab_manual_paste, "\\n")[[1]]
        molecule_names <- trimws(molecule_names)
        molecule_names <- molecule_names[molecule_names != "" & !is.na(molecule_names)]
        
        # Deduplicate manual input and warn user if duplicates found
        n_before <- length(molecule_names)
        molecule_names <- unique(molecule_names)
        n_after <- length(molecule_names)
        if (n_before > n_after) {
          showNotification(
            paste0("Found ", n_before - n_after, " duplicate entries in your paste. Using ", n_after, " unique metabolites."),
            type = "message", duration = 5
          )
        }
        
        if (length(molecule_names) == 0) {
          showNotification("No metabolite names provided", type = "error", duration = 5)
          metab_values$mapping_in_progress <- FALSE
          return()
        }
      }
      
      # For manual input, create pre-existing IDs structure based on user selection
      manual_id_types <- input$metab_manual_id_types %||% c("name")
      
      # Only create pre_existing_ids if user selected specific ID types (not just compound names)
      if (input$metab_source == "manual" && length(manual_id_types) > 0 && !identical(manual_id_types, c("name"))) {
        # Create pre-existing IDs structure for manual input with specific ID types
        pre_existing_ids <- data.frame(
          molecule_name = molecule_names,
          id_value = molecule_names,  # The input values themselves
          id_type = "manual_input",
          stringsAsFactors = FALSE
        )
        
        # Add metadata about what types of IDs are present
        attr(pre_existing_ids, "manual_id_types") <- manual_id_types
        
        showNotification(
          paste("Manual input detected with ID types:", paste(manual_id_types, collapse = ", ")),
          type = "message", 
          duration = 4
        )
        
        message(sprintf("[MANUAL INPUT] Processing %d entries with ID types: %s", 
                       length(molecule_names), paste(manual_id_types, collapse = ", ")))
      } else if (input$metab_source == "manual" && (identical(manual_id_types, c("name")) || is.null(manual_id_types))) {
        # For compound names in manual input, treat as regular batch search
        showNotification(
          paste("Manual input detected: treating as compound names for database search"),
          type = "message", 
          duration = 3
        )
        message(sprintf("[MANUAL INPUT] Processing %d compound names", length(molecule_names)))
        pre_existing_ids <- NULL  # Don't use pre-existing IDs, use batch search instead
      }
      
      showNotification(paste("Using", length(molecule_names), "manually input metabolites"),
                      type = "message", duration = 3)
    } else {
      # Fallback to all molecules
      molecule_names <- values$cleaned_molecules
    }
    
    # Final safety check: deduplicate molecule_names across all sources
    n_before_final <- length(molecule_names)
    molecule_names <- unique(molecule_names)
    n_after_final <- length(molecule_names)
    if (n_before_final > n_after_final) {
      message(sprintf("[DEDUP] Removed %d duplicate metabolites (after source-specific dedup). Using %d unique metabolites.", 
                     n_before_final - n_after_final, n_after_final))
    }
    
    # Validate we have molecules to process
    if (is.null(molecule_names) || length(molecule_names) == 0) {
      showNotification("No metabolites available for mapping", type = "error", duration = 5)
      metab_values$mapping_in_progress <- FALSE
      return()
    }
    
    # Create cache key from input parameters
    custom_bg_list <- NULL
    if ((input$metab_source %||% "pairwise") == "manual" && (input$metab_manual_background_type %||% "kegg") == "custom") {
      custom_bg_list <- metab_custom_background_molecules()
    }
    cache_key_data <- list(
      molecule_names = sort(molecule_names),  # Sort for consistent hashing
      selected_databases = sort(selected_databases),
      metab_source = input$metab_source,
      metab_id_type = input$metab_id_type %||% "name",
      metab_manual_id_types = input$metab_manual_id_types %||% NULL,
      metab_fetch_classification = isTRUE(input$metab_fetch_classification),
      metab_fetch_pathways = isTRUE(input$metab_fetch_pathways),
      metab_fetch_modules = isTRUE(input$metab_fetch_modules),
      metab_enrichment_background = input$metab_enrichment_background %||% "analyzed",
      metab_manual_background_type = input$metab_manual_background_type %||% "kegg",
      custom_background_hash = if(!is.null(custom_bg_list)) digest::digest(sort(unique(custom_bg_list))) else NULL,
      pre_existing_ids_hash = if(!is.null(pre_existing_ids)) digest::digest(pre_existing_ids) else NULL
    )
    cache_key <- digest::digest(cache_key_data)
    
    # Check session cache for existing results
    if (!is.null(metab_values$id_mapping_cache) && 
        !is.null(metab_values$id_mapping_cache[[cache_key]])) {
      message("[METAB CACHE] Using cached ID mapping results for identical input")
      cached_result <- metab_values$id_mapping_cache[[cache_key]]
      
      # Restore cached results
      metab_values$id_mapping_results <- cached_result$id_results
      values$metabolomics_mapping <- cached_result$mapping
      values$metabolomics_id_columns <- cached_result$id_columns
      
      if (!is.null(cached_result$classification_data)) {
        metab_values$classification_data <- cached_result$classification_data
      }
      if (!is.null(cached_result$pathway_data)) {
        metab_values$pathway_data <- cached_result$pathway_data
      }
      if (!is.null(cached_result$pathway_summary)) {
        metab_values$pathway_summary <- cached_result$pathway_summary
      }
      if (!is.null(cached_result$module_data)) {
        metab_values$module_data <- cached_result$module_data
      }
      if (!is.null(cached_result$module_summary)) {
        metab_values$module_summary <- cached_result$module_summary
      }
      if (!is.null(cached_result$enrichment_background_size)) {
        metab_values$enrichment_background_size <- cached_result$enrichment_background_size
      }
      
      showNotification("Using cached metabolite ID mapping results", type = "message", duration = 3)
      metab_values$mapping_in_progress <- FALSE
      return()
    }
    
    # =========================================================================
    # CHECK FOR PRE-EXISTING IDS FROM USER'S DATA OR MANUAL INPUT
    # =========================================================================
    # If user has ID columns in their data and selected an ID type, use those directly
    id_type_selected <- input$metab_id_type %||% "name"
    
    # First check for manual input IDs (takes precedence)
    if (input$metab_source == "manual" && !is.null(pre_existing_ids)) {
      # Manual input IDs were already created above - use them
      message(sprintf("[MANUAL INPUT] Using %d manual input entries", nrow(pre_existing_ids)))
      
    } else if (!is.null(values$metabolite_id_columns_from_data) && id_type_selected != "name") {
      tryCatch({
        id_data <- values$metabolite_id_columns_from_data
        
        # Use the selected column name directly (no mapping needed)
        if (id_type_selected %in% colnames(id_data)) {
          # Match molecule names to their IDs
          pre_existing_ids <- data.frame(
            molecule_name = character(),
            id_value = character(),
            stringsAsFactors = FALSE
          )
          
          for (mol_name in molecule_names) {
            # Find matching row in id_data
            match_idx <- which(id_data$molecule_name == mol_name)
            
            if (length(match_idx) > 0) {
              id_val <- as.character(id_data[[id_type_selected]][match_idx[1]])
              
              if (!is.na(id_val) && id_val != "") {
                pre_existing_ids <- rbind(pre_existing_ids, 
                                         data.frame(molecule_name = mol_name,
                                                   id_value = id_val,
                                                   stringsAsFactors = FALSE))
              }
            }
          }
          
          if (nrow(pre_existing_ids) > 0) {
            showNotification(
              paste("Found", nrow(pre_existing_ids), "pre-existing", 
                   id_type_selected, "IDs from your data.",
                   "These will be used directly, skipping redundant API calls."),
              type = "message",
              duration = 5
            )
            
            message(sprintf("[ID OPTIMIZATION] Using %d pre-existing %s IDs from user data", 
                           nrow(pre_existing_ids), id_type_selected))
          } else {
            pre_existing_ids <- NULL
            showNotification(
              paste("No valid", id_type_selected, 
                   "IDs found in your data. Will use compound name mapping instead."),
              type = "warning",
              duration = 4
            )
          }
        } else {
          showNotification(
            paste("Selected ID type", id_type_selected, 
                 "not found in your data columns. Using compound name mapping."),
            type = "message",
            duration = 4
          )
        }
      }, error = function(e) {
        message("Error checking pre-existing IDs: ", e$message)
        pre_existing_ids <- NULL
      })
    }
    
    # Show progress message
    showNotification("Starting metabolomics ID mapping (parallel processing enabled)...", type = "message", duration = 3)
    
    # Initialize metabolomics cache if not exists
    if (!exists(".metabolomics_cache", envir = .GlobalEnv)) {
      assign(".metabolomics_cache", new.env(), envir = .GlobalEnv)
    }
    
    # Helper function to check if an ID value is valid (not NA, not "NA" string, not empty)
    is_valid_id <- function(x) {
      tryCatch({
        if (is.null(x)) return(FALSE)
        if (length(x) == 0) return(FALSE)
        if (length(x) > 1) x <- x[1]  # Take first element if vector
        if (is.na(x)) return(FALSE)
        x <- as.character(x)
        if (x == "") return(FALSE)
        if (toupper(trimws(x)) == "NA") return(FALSE)
        return(TRUE)
      }, error = function(e) FALSE)
    }
    
    # Initialize placeholder for cached_mappings
    cached_mappings <- NULL
    
    # Apply ID mapping with progress tracking
    withProgress(message = "Mapping metabolite IDs...", {
      setProgress(0.01, detail = "Preparing caches and checking saved mappings...")
      
      # Initialize and load cached_mappings from SQLite
      setProgress(0.05, detail = "Checking persistent cached mappings...")
      
      # Initialize SQLite cache table
      initialize_cache_table()
      
      # Try to load from SQLite first
      cached_mappings <- load_cached_mappings()
      
      if (is.null(cached_mappings)) {
        # Create empty cache structure (will be populated and saved during ID mapping)
        cached_mappings <- data.frame(
          original_name = character(),
          clean_name = character(),
          normalized_name = character(),
          kegg_id = character(),
          kegg_status = character(),
          pubchem_cid = character(),
          pubchem_status = character(),
          hmdb_id = character(),
          chebi_id = character(),
          chebi_status = character(),
          lipidmaps_id = character(),
          lipidmaps_status = character(),
          databases_searched = character(),
          stringsAsFactors = FALSE
        )
        message("Initialized new SQLite cache for metabolite mappings")
      } else {
        setProgress(0.08, detail = paste0("Loaded ", nrow(cached_mappings), " cached entries from SQLite"))
      }
      
      # Add missing status columns for backward compatibility
      if (!is.null(cached_mappings)) {
        if (!"normalized_name" %in% colnames(cached_mappings)) cached_mappings$normalized_name <- ""
        if (!"kegg_status" %in% colnames(cached_mappings)) cached_mappings$kegg_status <- ""
        if (!"pubchem_status" %in% colnames(cached_mappings)) cached_mappings$pubchem_status <- ""
        if (!"chebi_status" %in% colnames(cached_mappings)) cached_mappings$chebi_status <- ""
        if (!"lipidmaps_status" %in% colnames(cached_mappings)) cached_mappings$lipidmaps_status <- ""
        if (!"databases_searched" %in% colnames(cached_mappings)) cached_mappings$databases_searched <- ""
      }
      
      tryCatch({
        # =====================================================================
        # HANDLE MANUAL INPUT IDs OR USE OPTIMIZED BATCH SEARCH
        # =====================================================================
        
        if (!is.null(pre_existing_ids) && input$metab_source == "manual") {
          # For manual input with specified ID types, create mapped_ids directly
          setProgress(0.10, detail = sprintf("Processing %d manual input entries...", nrow(pre_existing_ids)))
          
          manual_id_types <- attr(pre_existing_ids, "manual_id_types") %||% c("name")
          
          # Create mapped_ids structure for manual input
          mapped_ids <- vector("list", length(molecule_names))
          names(mapped_ids) <- molecule_names
          
          for (i in seq_along(molecule_names)) {
            mol_name <- molecule_names[i]
            id_entry <- pre_existing_ids[pre_existing_ids$molecule_name == mol_name, ]
            
            if (nrow(id_entry) > 0) {
              id_value <- id_entry$id_value[1]
              
              # Create ID mapping based on selected types
              id_mapping <- list()
              
              if ("name" %in% manual_id_types) {
                # If compound names are included, treat as primary identifier
                id_mapping$name <- id_value
              }
              
              if ("kegg" %in% manual_id_types) {
                id_mapping$kegg <- id_value
              }
              
              if ("hmdb" %in% manual_id_types) {
                id_mapping$hmdb <- id_value
              }
              
              if ("pubchem" %in% manual_id_types) {
                id_mapping$pubchem <- id_value
              }
              
              if ("chebi" %in% manual_id_types) {
                id_mapping$chebi <- id_value
              }
              
              if ("lipidmaps" %in% manual_id_types) {
                id_mapping$lipidmaps <- id_value
              }
              
              mapped_ids[[i]] <- id_mapping
            }
          }
          
          # Create batch_results structure for manual input
          batch_results <- data.frame(
            original_name = molecule_names,
            clean_name = molecule_names,
            normalized_name = molecule_names,
            kegg_id = sapply(mapped_ids, function(x) x$kegg %||% NA_character_),
            pubchem_cid = sapply(mapped_ids, function(x) x$pubchem %||% NA_character_),
            hmdb_id = sapply(mapped_ids, function(x) x$hmdb %||% NA_character_),
            chebi_id = sapply(mapped_ids, function(x) x$chebi %||% NA_character_),
            lipidmaps_id = sapply(mapped_ids, function(x) x$lipidmaps %||% NA_character_),
            stringsAsFactors = FALSE
          )
          
          setProgress(0.85, detail = "Manual input processing complete...")
          
        } else {
          # Use optimized batch search for regular compound name input
          setProgress(0.10, detail = sprintf("Searching %d metabolites...", length(molecule_names)))
          
          # Call the optimized batch_search_metabolites function
          batch_results <- batch_search_metabolites(
            molecule_names, 
            databases = selected_databases
          )
          
          setProgress(0.85, detail = "Processing batch results...")
        }
        
        # Convert batch_results dataframe to the format expected by the rest of the app
        # batch_results has columns: original_name, clean_name, normalized_name, kegg_id, pubchem_cid, hmdb_id, chebi_id, lipidmaps_id
        mapped_results <- lapply(seq_len(nrow(batch_results)), function(i) {
          row <- batch_results[i, ]
          list(
            original_name = row$original_name,
            clean_name = row$clean_name,
            resolved_ids = list(
              kegg = if (!is.na(row$kegg_id) && row$kegg_id != "") row$kegg_id else NA_character_,
              pubchem = if (!is.na(row$pubchem_cid) && row$pubchem_cid != "") row$pubchem_cid else NA_character_,
              hmdb = if (!is.na(row$hmdb_id) && row$hmdb_id != "") row$hmdb_id else NA_character_,
              chebi = if (!is.na(row$chebi_id) && row$chebi_id != "") row$chebi_id else NA_character_,
              lipidmaps = if (!is.na(row$lipidmaps_id) && row$lipidmaps_id != "") row$lipidmaps_id else NA_character_
            )
          )
        })
        
        setProgress(0.98, detail = "Finalizing results...")
        
        # Extract results
        mapped_ids <- lapply(mapped_results, function(x) x$resolved_ids)
        clean_names <- sapply(mapped_results, function(x) x$clean_name)
        
        message(sprintf("[DEBUG] Extracted mapped_ids: length=%d, class=%s", length(mapped_ids), paste(class(mapped_ids), collapse=",")))
        if (length(mapped_ids) > 0) {
          message(sprintf("[DEBUG]   First resolved_ids: %s", 
                        paste(names(mapped_ids[[1]]), "=", sapply(mapped_ids[[1]], function(v) if(is.na(v) || v == "") "NA/empty" else v), collapse="; ")))
        }
        
        # Store mapping results in values for app-wide access
        values$metabolomics_mapping <- list(
          original_names = molecule_names,
          clean_names = clean_names,
          mapped_ids = mapped_ids,
          selected_databases = selected_databases,
          use_parallel = use_parallel
        )
        
        # Create individual ID columns for each database type
        id_columns <- data.frame(
          matrix(NA, nrow = length(mapped_ids), ncol = 0),
          stringsAsFactors = FALSE
        )
        
        if ("kegg" %in% selected_databases) {
          id_columns$KEGG_ID <- sapply(mapped_ids, function(ids) {
            if (is.null(ids) || !is.list(ids)) return("")
            kegg_id <- ids$kegg
            if (is.null(kegg_id) || is.na(kegg_id) || kegg_id == "") "" else as.character(kegg_id)
          })
          message(sprintf("[DEBUG] KEGG_ID column: %s", paste(id_columns$KEGG_ID, collapse=", ")))
        }
        
        if ("hmdb" %in% selected_databases) {
          id_columns$HMDB_ID <- sapply(mapped_ids, function(ids) {
            if (is.null(ids) || !is.list(ids)) return("")
            hmdb_id <- ids$hmdb
            if (is.null(hmdb_id) || is.na(hmdb_id) || hmdb_id == "") "" else as.character(hmdb_id)
          })
        }
        
        if ("pubchem" %in% selected_databases) {
          id_columns$PubChem_CID <- sapply(mapped_ids, function(ids) {
            if (is.null(ids) || !is.list(ids)) return("")
            pubchem_id <- ids$pubchem
            if (is.null(pubchem_id) || is.na(pubchem_id) || pubchem_id == "") "" else as.character(pubchem_id)
          })
        }
        
        if ("chebi" %in% selected_databases) {
          id_columns$ChEBI_ID <- sapply(mapped_ids, function(ids) {
            if (is.null(ids) || !is.list(ids)) return("")
            chebi_id <- ids$chebi
            if (is.null(chebi_id) || is.na(chebi_id) || chebi_id == "") "" else as.character(chebi_id)
          })
        }
        
        if ("lipidmaps" %in% selected_databases) {
          id_columns$LipidMaps_ID <- sapply(mapped_ids, function(ids) {
            if (is.null(ids) || !is.list(ids)) return("")
            lipidmaps_id <- ids$lipidmaps
            if (is.null(lipidmaps_id) || is.na(lipidmaps_id) || lipidmaps_id == "") "" else as.character(lipidmaps_id)
          })
        }
        
        # Store the individual ID columns
        values$metabolomics_id_columns <- id_columns
        
        # Create results dataframe for the Metabolomics tab display
        id_results <- data.frame(
          Compound_Name = molecule_names,
          stringsAsFactors = FALSE
        )
        id_results <- cbind(id_results, id_columns)
        
        metab_values$id_mapping_results <- id_results
        
        # Count successful mappings
        successful_mappings <- sum(sapply(mapped_ids, function(x) {
          if (is.null(x) || !is.list(x)) return(FALSE)
          any(!is.na(unlist(x)))
        }))
        
        setProgress(0.95, detail = "Finalizing...")
        
        # Classify metabolites if requested
        if (isTRUE(input$metab_fetch_classification)) {
          setProgress(0.96, detail = "Classifying metabolites (from HMDB)...")
          
          classification_results <- tryCatch({
            classify_metabolites_cached(
              metabolite_names = molecule_names,
              hmdb_ids = id_results$HMDB_ID,
              use_online = TRUE
            )
          }, error = function(e) {
            showNotification(paste("Error classifying metabolites:", e$message), type = "warning")
            return(NULL)
          })
          
          metab_values$classification_data <- classification_results
        }
        
        # Fetch pathways if requested
        if (isTRUE(input$metab_fetch_pathways)) {
          setProgress(0.97, detail = "Fetching pathway information...")
          
          pathway_results <- tryCatch({
            fetch_metabolite_pathways_cached(
              kegg_ids = id_results$KEGG_ID
            )
          }, error = function(e) {
            showNotification(paste("Error fetching pathways:", e$message), type = "warning")
            return(NULL)
          })
          
          metab_values$pathway_data <- pathway_results
          
          if (!is.null(pathway_results) && nrow(pathway_results) > 0) {
            # Determine background size based on user settings
            bg_size <- 6610  # Default: KEGG pathway-mapped compounds
            
            if (metab_source != "manual") {
              # For pairwise/intersection: check if user wants analyzed metabolites as background
              bg_choice <- input$metab_enrichment_background %||% "analyzed"
              if (bg_choice == "analyzed" && !is.null(values$cleaned_molecules)) {
                bg_size <- length(values$cleaned_molecules)
                message(sprintf("[PATHWAY] Using analyzed metabolites as background: %d", bg_size))
              } else {
                message(sprintf("[PATHWAY] Using KEGG pathway-mapped compounds as background: %d", bg_size))
              }
            } else {
              # For manual input: check if user provided custom background list
              bg_type <- input$metab_manual_background_type %||% "kegg"
              if (bg_type == "custom") {
                # Get background molecules from paste or file sheet 2
                custom_bg_molecules <- NULL
                
                if (input$metab_manual_input_type == "paste") {
                  # Get from pasted background text
                  if (!is.null(input$metab_custom_background_paste) && nchar(trimws(input$metab_custom_background_paste)) > 0) {
                    custom_bg_molecules <- strsplit(input$metab_custom_background_paste, "\\n")[[1]]
                    custom_bg_molecules <- trimws(custom_bg_molecules)
                    custom_bg_molecules <- custom_bg_molecules[custom_bg_molecules != "" & !is.na(custom_bg_molecules)]
                  }
                } else if (input$metab_manual_input_type == "file") {
                  # Get from sheet 2 of uploaded Excel file
                  if (!is.null(input$metab_manual_file)) {
                    file_path <- input$metab_manual_file$datapath
                    file_name <- input$metab_manual_file$name
                    
                    if (grepl("\\.(xlsx|xls)$", file_name, ignore.case = TRUE)) {
                      tryCatch({
                        sheet_names <- readxl::excel_sheets(file_path)
                        if (length(sheet_names) >= 2) {
                          sheet2_data <- readxl::read_excel(file_path, sheet = 2, col_names = TRUE)
                          if (ncol(sheet2_data) >= 1 && nrow(sheet2_data) > 0) {
                            custom_bg_molecules <- as.character(sheet2_data[[1]])
                            custom_bg_molecules <- custom_bg_molecules[!is.na(custom_bg_molecules) & custom_bg_molecules != ""]
                          }
                        }
                      }, error = function(e) {
                        message("[BACKGROUND] Error reading sheet 2: ", e$message)
                      })
                    }
                  }
                }
                
                if (!is.null(custom_bg_molecules) && length(custom_bg_molecules) >= 10) {
                  bg_size <- length(custom_bg_molecules)
                  message(sprintf("[PATHWAY] Using custom background list: %d molecules", bg_size))
                } else {
                  message("[PATHWAY] Custom background list too small or empty, using KEGG default: 6610")
                }
              } else {
                message(sprintf("[PATHWAY] Using KEGG pathway-mapped compounds as background: %d", bg_size))
              }
            }
            
            # Calculate enrichment statistics with determined background size
            metab_values$pathway_summary <- calculate_pathway_enrichment_cached(
              pathway_df = pathway_results,
              total_measured = length(molecule_names),
              background_size = bg_size,
              p_adjust_method = "BH"
            )
            
            # Store the background size used for display
            metab_values$enrichment_background_size <- bg_size
          }
        }
        
        # Fetch modules if requested (KEGG Module Enrichment)
        if (isTRUE(input$metab_fetch_modules)) {
          setProgress(0.975, detail = "Fetching module information...")
          
          module_results <- tryCatch({
            fetch_metabolite_modules_cached(
              kegg_ids = id_results$KEGG_ID
            )
          }, error = function(e) {
            showNotification(paste("Error fetching modules:", e$message), type = "warning")
            return(NULL)
          })
          
          metab_values$module_data <- module_results
          
          if (!is.null(module_results) && nrow(module_results) > 0) {
            # Determine background size based on user settings (same logic as pathways)
            bg_size_module <- 6610  # Default: KEGG module-mapped compounds
            
            if (metab_source != "manual") {
              bg_choice <- input$metab_enrichment_background %||% "analyzed"
              if (bg_choice == "analyzed" && !is.null(values$cleaned_molecules)) {
                bg_size_module <- length(values$cleaned_molecules)
                message(sprintf("[MODULE] Using analyzed metabolites as background: %d", bg_size_module))
              } else {
                message(sprintf("[MODULE] Using KEGG module-mapped compounds as background: %d", bg_size_module))
              }
            } else {
              bg_type <- input$metab_manual_background_type %||% "kegg"
              if (bg_type == "custom") {
                custom_bg_molecules <- NULL
                
                if (input$metab_manual_input_type == "paste") {
                  if (!is.null(input$metab_custom_background_paste) && nchar(trimws(input$metab_custom_background_paste)) > 0) {
                    custom_bg_molecules <- strsplit(input$metab_custom_background_paste, "\\n")[[1]]
                    custom_bg_molecules <- trimws(custom_bg_molecules)
                    custom_bg_molecules <- custom_bg_molecules[custom_bg_molecules != "" & !is.na(custom_bg_molecules)]
                  }
                } else if (input$metab_manual_input_type == "file") {
                  if (!is.null(input$metab_manual_file)) {
                    file_path <- input$metab_manual_file$datapath
                    file_name <- input$metab_manual_file$name
                    
                    if (grepl("\\.(xlsx|xls)$", file_name, ignore.case = TRUE)) {
                      tryCatch({
                        sheet_names <- readxl::excel_sheets(file_path)
                        if (length(sheet_names) >= 2) {
                          sheet2_data <- readxl::read_excel(file_path, sheet = 2, col_names = TRUE)
                          if (ncol(sheet2_data) >= 1 && nrow(sheet2_data) > 0) {
                            custom_bg_molecules <- as.character(sheet2_data[[1]])
                            custom_bg_molecules <- custom_bg_molecules[!is.na(custom_bg_molecules) & custom_bg_molecules != ""]
                          }
                        }
                      }, error = function(e) {
                        message("[MODULE BACKGROUND] Error reading sheet 2: ", e$message)
                      })
                    }
                  }
                }
                
                if (!is.null(custom_bg_molecules) && length(custom_bg_molecules) >= 10) {
                  bg_size_module <- length(custom_bg_molecules)
                  message(sprintf("[MODULE] Using custom background list: %d molecules", bg_size_module))
                } else {
                  message("[MODULE] Custom background list too small or empty, using KEGG default: 6610")
                }
              } else {
                message(sprintf("[MODULE] Using KEGG module-mapped compounds as background: %d", bg_size_module))
              }
            }
            
            # Calculate module enrichment statistics
            metab_values$module_summary <- calculate_module_enrichment_cached(
              module_df = module_results,
              total_measured = length(molecule_names),
              background_size = bg_size_module,
              p_adjust_method = "BH"
            )
            
            # Store the background size used for display (if not already set by pathways)
            if (is.null(metab_values$enrichment_background_size)) {
              metab_values$enrichment_background_size <- bg_size_module
            }
            
            showNotification(
              sprintf("Found %d modules linked to your metabolites", 
                      if(!is.null(metab_values$module_summary)) nrow(metab_values$module_summary) else 0),
              type = "message", duration = 3
            )
          }
        }
        
        # Fetch associations from HMDB (always fetch if HMDB IDs are available)
        if ("hmdb" %in% selected_databases && any(!is.na(id_results$HMDB_ID) & id_results$HMDB_ID != "")) {
          setProgress(0.98, detail = "Fetching metabolite associations...")
          
          associations_results <- tryCatch({
            fetch_metabolite_associations_cached(
              hmdb_ids = id_results$HMDB_ID,
              metabolite_names = molecule_names,
              progress_callback = function(pct, msg) {
                setProgress(0.98 + pct * 0.01, detail = msg)
              }
            )
          }, error = function(e) {
            showNotification(paste("Error fetching associations:", e$message), type = "warning")
            return(NULL)
          })
          
          metab_values$associations_data <- associations_results
        }
        
        # Update metabolite selector for ontology browser
        updateSelectInput(session, "metab_ontology_select",
                          choices = molecule_names,
                          selected = molecule_names[1])
        
        # =====================================================================
        # FUZZY SEARCH FOR UNMATCHED METABOLITES
        # Find metabolites that didn't get any IDs and offer similar name suggestions
        # =====================================================================
        unmatched_indices <- which(sapply(mapped_ids, function(x) {
          if (is.null(x) || !is.list(x)) return(TRUE)
          !any(!is.na(unlist(x)) & unlist(x) != "")
        }))
        
        if (length(unmatched_indices) > 0) {
          unmatched_names <- molecule_names[unmatched_indices]
          # Deduplicate to avoid duplicate suggestions for same metabolite
          unmatched_names_unique <- unique(unmatched_names)
          message(sprintf("[FUZZY] %d metabolites have no IDs, searching for similar names...", length(unmatched_names_unique)))
          
          fuzzy_results <- fuzzy_search_metabolites(unmatched_names_unique, max_suggestions = 3, min_similarity = 0.65)
          
          if (!is.null(fuzzy_results) && nrow(fuzzy_results) > 0) {
            # Remove duplicate suggestions (same original and suggested name with same IDs)
            fuzzy_results <- fuzzy_results[!duplicated(fuzzy_results[, c("original_name", "suggested_name", "kegg_id", "hmdb_id", "pubchem_id", "chebi_id")]), ]
            
            # Store for user review
            metab_values$fuzzy_suggestions <- fuzzy_results
            metab_values$fuzzy_original_results <- batch_results
            metab_values$fuzzy_molecule_names <- molecule_names
            metab_values$fuzzy_selected_databases <- selected_databases
            metab_values$fuzzy_pending_review <- TRUE
            
            showNotification(
              sprintf("Found %d potential matches for %d unmatched metabolites. Click 'Review Suggestions' to see them.",
                      nrow(fuzzy_results), length(unique(fuzzy_results$original_name))),
              type = "message",
              duration = 10
            )
          }
        }
        
        showNotification(
          paste("Metabolomics ID mapping completed. Successfully mapped", 
                successful_mappings, "out of", length(molecule_names), "metabolites using databases:", 
                paste(selected_databases, collapse = ", ")),
          type = "message", 
          duration = 8
        )
        
      }, error = function(e) {
        error_msg <- paste("Error during metabolomics ID mapping:", e$message)
        showNotification(error_msg, type = "error", duration = 10)
        values$metabolomics_mapping <- list(
          error = e$message,
          selected_databases = selected_databases,
          use_parallel = use_parallel
        )
      })
    })
    
    # Store results in session cache
    if (is.null(metab_values$id_mapping_cache)) {
      metab_values$id_mapping_cache <- list()
    }
    metab_values$id_mapping_cache[[cache_key]] <- list(
      id_results = metab_values$id_mapping_results,
      mapping = values$metabolomics_mapping,
      id_columns = values$metabolomics_id_columns,
      classification_data = if(exists("classification_results")) classification_results else NULL,
      pathway_data = if(exists("pathway_results")) pathway_results else NULL,
      pathway_summary = if(!is.null(metab_values$pathway_summary)) metab_values$pathway_summary else NULL,
      module_data = if(exists("module_results")) module_results else NULL,
      module_summary = if(!is.null(metab_values$module_summary)) metab_values$module_summary else NULL,
      enrichment_background_size = metab_values$enrichment_background_size %||% NULL
    )
    
    metab_values$mapping_in_progress <- FALSE
  })
  
  # Observer for visualization generation
  observeEvent(input$generate_metab_btn, {
    # Parse numeric inputs safely at the very beginning (outside withProgress)
    metab_top_terms_val <- {
      val <- input$metab_top_terms
      if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 20
    }
    metab_pie_top_terms_val <- {
      val <- input$metab_pie_top_terms
      if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
    }
    
    # Load visualization packages
    load_package_group("visualization")
    
    # Reset pie tracking each time we generate
    metab_values$pie_plots <- NULL
    metab_values$use_multiple_pies <- FALSE

    # Check data source - manual input doesn't require processed data
    metab_source <- input$metab_source %||% "processed"
    
    if (metab_source != "manual") {
      # For non-manual sources, require processed data
      if (is.null(values$normalized_data) || is.null(values$cleaned_molecules)) {
        showNotification(
          "Please process your data in the Data tab first before generating visualizations.",
          type = "warning",
          duration = 5
        )
        return()
      }
    }
    
    if (is.null(metab_values$classification_data)) {
      showNotification(
        "Please map metabolite IDs first before generating visualizations.",
        type = "warning",
        duration = 5
      )
      return()
    }
    
    req(metab_values$classification_data)
    req(input$metab_plot_mode)
    
    withProgress(message = "Generating metabolomics visualization...", value = 0, {
      # Capture all input values at the start to ensure consistency
      analysis_type <- input$metab_analysis_type %||% "classification"
      plot_type <- input$metab_plot_type %||% "bar"
      message("[DEBUG-METAB] generate button clicked. analysis_type=", analysis_type, ", plot_type=", plot_type, ", plot_mode=", input$metab_plot_mode)
      class_level <- input$metab_class_level
      
      # Get font sizes - handle both bar and non-bar input IDs
      if (plot_type == "bar") {
        title_size <- input$metab_title_size_bar %||% input$metab_title_size %||% 14
        axis_title_size <- input$metab_axis_title_size_bar %||% input$metab_axis_title_size %||% 12
        axis_text_size <- input$metab_axis_text_size_bar %||% input$metab_axis_text_size %||% 10
        legend_text_size <- input$metab_legend_text_size_bar %||% input$metab_legend_text_size %||% 10
        count_font_size <- input$metab_count_font_size %||% 8
      } else {
        title_size <- input$metab_title_size %||% 14
        axis_title_size <- input$metab_axis_title_size %||% 12
        axis_text_size <- input$metab_axis_text_size %||% 10
        legend_text_size <- input$metab_legend_text_size %||% 10
        count_font_size <- NULL
      }
      
      # Parse numeric inputs safely - removed from here since they're already parsed above
      # metab_top_terms_val and metab_pie_top_terms_val are already available from the outer scope
      
      setProgress(0.3, detail = "Preparing data...")
      
      if (analysis_type == "classification") {
        # Check plot mode selection
        plot_mode <- input$metab_plot_mode %||% "groups"
        use_group_comparison <- plot_mode == "groups" && 
                                !is.null(values$normalized_data) && 
                                !is.null(values$unique_groups)
        
        if (plot_mode == "groups" && !use_group_comparison) {
          showNotification("Please process your data in the Data tab first for group comparison plots.", type = "warning", duration = 5)
          return()
        }
        
        if (use_group_comparison) {
          # =====================================================================
          # GLYCOMICS-STYLE GROUP COMPARISON ALGORITHM
          # Calculate per-group statistics with mean percentages and error bars
          # =====================================================================
          
          # Get classification data with metabolite names
          class_data <- metab_values$classification_data
          
          # Get the classification categories for each metabolite
          metabolite_categories <- setNames(class_data[[class_level]], class_data$metabolite_name)
          
          # Get metabolite indices in the normalized data
          metabolite_names <- names(metabolite_categories)
          metabolite_indices <- match(metabolite_names, values$cleaned_molecules)
          
          # Filter out NA indices (metabolites not found in normalized data)
          valid_indices <- !is.na(metabolite_indices)
          metabolite_indices <- metabolite_indices[valid_indices]
          metabolite_categories <- metabolite_categories[valid_indices]
          
          if (length(metabolite_indices) == 0) {
            showNotification("No metabolites found in normalized data for group comparison.", type = "warning")
            return()
          }
          
          # Extract normalized data for these metabolites
          metabolite_data <- values$normalized_data[metabolite_indices, , drop = FALSE]
          
          # Calculate distribution by group (glycomics-style algorithm)
          group_distributions <- list()
          
          for (i in seq_along(values$unique_groups)) {
            group_name <- values$unique_groups[i]
            group_columns <- values$group_column_indices[[i]]
            
            # Extract data for this group
            group_data <- metabolite_data[, group_columns, drop = FALSE]
            
            # Skip if all values are NA or zero
            if (all(is.na(group_data)) || sum(group_data, na.rm = TRUE) == 0) {
              next
            }
            
            # For each classification category, calculate stats across samples
            unique_categories <- unique(metabolite_categories)
            type_stats <- lapply(unique_categories, function(category) {
              category_indices <- which(metabolite_categories == category)
              category_data <- group_data[category_indices, , drop = FALSE]
              
              # Sum abundance for this category in each sample
              sample_category_sums <- colSums(category_data, na.rm = TRUE)
              total_sample_sums <- colSums(group_data, na.rm = TRUE)
              
              # Calculate percentage for each sample
              sample_percentages <- (sample_category_sums / total_sample_sums) * 100
              sample_percentages[is.nan(sample_percentages)] <- 0
              
              # Calculate mean abundance
              mean_abundance <- sum(category_data, na.rm = TRUE)
              
              # Calculate statistics
              mean_pct <- mean(sample_percentages, na.rm = TRUE)
              sd_pct <- sd(sample_percentages, na.rm = TRUE)
              n_samples <- length(sample_percentages)
              sem_pct <- sd_pct / sqrt(n_samples)
              
              data.frame(
                Category = category,
                Abundance = mean_abundance,
                Percentage = mean_pct,
                SD = ifelse(is.na(sd_pct), 0, sd_pct),
                SEM = ifelse(is.na(sem_pct), 0, sem_pct),
                N = n_samples,
                Group = group_name,
                stringsAsFactors = FALSE
              )
            })
            
            type_abundances <- do.call(rbind, type_stats)
            
            # Remove categories with zero abundance
            type_abundances <- type_abundances[type_abundances$Abundance > 0, ]
            
            if (nrow(type_abundances) > 0) {
              group_distributions[[length(group_distributions) + 1]] <- type_abundances
            }
          }
          
          # Combine all group distributions
          all_distributions <- do.call(rbind, group_distributions)
          
          if (is.null(all_distributions) || nrow(all_distributions) == 0) {
            showNotification("No valid group distributions found. Please check your data.", type = "warning")
            return()
          }
          
          # Store all_distributions for reactive updates
          metab_values$all_distributions <- all_distributions
          
          plot_data <- all_distributions
          
          setProgress(0.5, detail = "Creating plot...")
          
          # Generate colors for categories
          unique_cats <- unique(plot_data$Category)
          n_cats <- length(unique_cats)
          
          if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
            category_colors <- setNames(
              viridis::viridis_pal(option = input$metab_color_palette)(n_cats),
              unique_cats
            )
          } else if (input$metab_color_palette == "rainbow") {
            category_colors <- setNames(
              rainbow(n_cats),
              unique_cats
            )
          } else {
            palette <- input$metab_color_palette
            colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_cats), 9), palette)
            if (n_cats > 9) {
              colors_vec <- colorRampPalette(colors_vec)(n_cats)
            }
            category_colors <- setNames(colors_vec[1:n_cats], unique_cats)
          }
          
          # Generate group colors for bar chart
          n_groups <- length(unique(plot_data$Group))
          if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
            group_colors <- setNames(
              viridis::viridis_pal(option = input$metab_color_palette)(n_groups),
              unique(plot_data$Group)
            )
          } else if (input$metab_color_palette == "rainbow") {
            group_colors <- setNames(
              rainbow(n_groups),
              unique(plot_data$Group)
            )
          } else {
            palette <- if (input$metab_color_palette == "metabolite") "Set1" else input$metab_color_palette
            colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_groups), 9), palette)
            if (n_groups > 9) {
              colors_vec <- colorRampPalette(colors_vec)(n_groups)
            }
            group_colors <- setNames(colors_vec[1:n_groups], unique(plot_data$Group))
          }
          
          # Determine which error value to use based on user selection
          error_col <- if ((input$metab_error_type %||% "sem") == "sem") "SEM" else "SD"
          plot_data$Error <- plot_data[[error_col]]
          
          # Create plot based on type
          if (plot_type == "pie") {
            # Reset pie tracking for classification branch
            metab_values$pie_plots <- NULL
            metab_values$use_multiple_pies <- FALSE
            metab_values$pie_shared_legend <- FALSE
            metab_values$shared_legend_plot <- NULL

            # Create separate pie charts for each group (glycomics-style)
            groups <- unique(all_distributions$Group)
            
            if (length(groups) > 1) {
              # Multiple groups - create separate pie charts with consistent colors
              if (!requireNamespace("gridExtra", quietly = TRUE)) {
                install.packages("gridExtra")
              }
              if (!requireNamespace("cowplot", quietly = TRUE)) {
                install.packages("cowplot")
              }
              
              # First pass: collect all categories across all groups to ensure consistent colors
              all_categories_in_pies <- unique(unlist(lapply(groups, function(group) {
                group_data <- all_distributions[all_distributions$Group == group, ]
                pie_top_n <- metab_pie_top_terms_val
                if (!is.null(pie_top_n) && pie_top_n > 0 && nrow(group_data) > pie_top_n) {
                  group_data <- group_data %>% arrange(desc(Abundance))
                  top_cats <- group_data$Category[1:pie_top_n]
                  has_other <- nrow(group_data) > pie_top_n
                  if (has_other) c(top_cats, "Other") else top_cats
                } else {
                  group_data$Category
                }
              })))
              
              # Create a GLOBAL color mapping for all categories (ensures same term = same color)
              n_all_cats <- length(all_categories_in_pies)
              if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
                global_cat_colors <- setNames(
                  viridis::viridis_pal(option = input$metab_color_palette)(n_all_cats),
                  all_categories_in_pies
                )
              } else if (input$metab_color_palette == "rainbow") {
                global_cat_colors <- setNames(rainbow(n_all_cats), all_categories_in_pies)
              } else {
                palette <- input$metab_color_palette
                colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_all_cats), 9), palette)
                if (n_all_cats > 9) {
                  colors_vec <- colorRampPalette(colors_vec)(n_all_cats)
                }
                global_cat_colors <- setNames(colors_vec[1:n_all_cats], all_categories_in_pies)
              }
              # Always set "Other" to gray if present
              if ("Other" %in% names(global_cat_colors)) {
                global_cat_colors["Other"] <- "#999999"
              }
              
              pie_plots <- list()
              group_data_list <- list()
              group_categories_list <- list()
              
              # GLOBAL TOP N APPROACH: Find top N categories across ALL groups to ensure consistency
              pie_top_n <- metab_pie_top_terms_val
              global_top_cats <- NULL
              
              if (!is.null(pie_top_n) && pie_top_n > 0) {
                # Calculate total/mean abundance per category across all groups
                cat_totals <- all_distributions %>%
                  dplyr::group_by(Category) %>%
                  dplyr::summarise(total_abundance = sum(Abundance, na.rm = TRUE), .groups = "drop") %>%
                  dplyr::arrange(desc(total_abundance))
                
                n_cats <- nrow(cat_totals)
                if (n_cats > pie_top_n) {
                  global_top_cats <- cat_totals$Category[1:pie_top_n]
                  message("[DEBUG-METAB PIE] Using GLOBAL top ", pie_top_n, " categories: ", paste(global_top_cats, collapse = ", "))
                }
              }
              
              for (i in seq_along(groups)) {
                group <- groups[i]
                group_data <- all_distributions[all_distributions$Group == group, ]
                original_n <- nrow(group_data)
                
                # Apply global top N filtering if specified
                if (!is.null(global_top_cats)) {
                  # Keep only global top categories, lump rest into "Other"
                  top_data <- group_data[group_data$Category %in% global_top_cats, ]
                  other_data <- group_data[!group_data$Category %in% global_top_cats, ]
                  
                  if (nrow(other_data) > 0) {
                    other_row <- data.frame(
                      Category = "Other",
                      Abundance = sum(other_data$Abundance),
                      Percentage = sum(other_data$Percentage),
                      SD = NA,
                      SEM = NA,
                      N = sum(other_data$N),
                      Group = group,
                      stringsAsFactors = FALSE
                    )
                    group_data <- rbind(top_data, other_row)
                  } else {
                    group_data <- top_data
                  }
                }
                
                group_data_list[[i]] <- group_data
                group_categories_list[[i]] <- sort(unique(group_data$Category))
              }
              
              # If all groups have identical categories, use a single shared legend
              shared_legend <- FALSE
              if (length(group_categories_list) > 1) {
                group_key <- vapply(group_categories_list, function(x) {
                  paste(sort(unique(x)), collapse = "|")
                }, character(1))
                message("[DEBUG-METAB PIE] Group category keys for shared legend check:")
                for (gi in seq_along(groups)) {
                  message("  Group '", groups[gi], "': ", group_key[gi])
                }
                shared_legend <- length(unique(group_key)) == 1
                message("[DEBUG-METAB PIE] Shared legend decision: ", shared_legend, " (unique keys: ", length(unique(group_key)), ")")
              }
              if (shared_legend && !requireNamespace("cowplot", quietly = TRUE)) {
                message("[DEBUG-METAB PIE] Disabling shared legend because cowplot not available")
                shared_legend <- FALSE
              }
              metab_values$pie_shared_legend <- shared_legend
              message("[DEBUG-METAB PIE] Final pie_shared_legend value: ", shared_legend)
              
              # Compute filtered color set for legend (only categories actually displayed)
              displayed_categories <- unique(unlist(group_categories_list))
              filtered_cat_colors <- global_cat_colors[names(global_cat_colors) %in% displayed_categories]
              # Ensure "Other" is included if present in any group
              if ("Other" %in% displayed_categories && !("Other" %in% names(filtered_cat_colors))) {
                filtered_cat_colors <- c(filtered_cat_colors, "Other" = "#999999")
              }
              
              for (i in seq_along(groups)) {
                group <- groups[i]
                group_data <- group_data_list[[i]]
                
                # Use filtered color mapping (only displayed categories)
                group_cat_colors <- filtered_cat_colors[names(filtered_cat_colors) %in% group_data$Category]
                # Ensure "Other" is in colors if present in data
                if ("Other" %in% group_data$Category && !("Other" %in% names(group_cat_colors))) {
                  group_cat_colors <- c(group_cat_colors, "Other" = "#999999")
                }
                legend_rows <- 4
                legend_cols <- max(1, ceiling(length(group_cat_colors) / legend_rows))
                
                # Determine legend position based on shared legend decision
                legend_pos <- if (shared_legend) "none" else "bottom"
                
                # Create pie chart for this group
                p_group <- ggplot(group_data, aes(x = "", y = Abundance, fill = Category)) +
                  geom_bar(stat = "identity", width = 1) +
                  coord_polar("y", start = 0) +
                  scale_fill_manual(values = filtered_cat_colors, breaks = group_data$Category, drop = TRUE) +
                  labs(
                    title = group,
                    fill = NULL
                  ) +
                  theme_minimal() +
                  theme(
                    axis.title = element_blank(),
                    panel.grid = element_blank(),
                    axis.text = element_blank(),
                    plot.title = element_text(hjust = 0.5, size = title_size, face = "bold"),
                    legend.position = legend_pos,
                    legend.direction = "horizontal",
                    legend.title = element_blank(),
                    legend.text = element_text(size = legend_text_size - 1),
                    legend.key.size = unit(0.4, "cm"),
                    plot.margin = margin(5, 5, 5, 5)
                  ) +
                  guides(fill = guide_legend(nrow = legend_rows, ncol = legend_cols, byrow = TRUE)) +
                  geom_text(aes(label = paste0(sprintf("%.1f", Percentage), "%")),
                            position = position_stack(vjust = 0.5),
                            size = 3.5, fontface = "bold")
                
                # Store the first plot WITH legend for extracting shared legend later
                if (shared_legend && i == 1) {
                  # Create a version with legend for extraction using FILTERED categories only
                  legend_data <- data.frame(
                    Category = factor(displayed_categories, levels = displayed_categories),
                    Abundance = 1
                  )
                  p_with_legend <- ggplot(legend_data, aes(x = "", y = Abundance, fill = Category)) +
                    geom_bar(stat = "identity", width = 1) +
                    coord_polar("y", start = 0) +
                    scale_fill_manual(values = filtered_cat_colors, breaks = displayed_categories, drop = FALSE) +
                    labs(fill = NULL) +
                    theme_minimal() +
                    theme(
                      legend.position = "bottom",
                      legend.direction = "horizontal",
                      legend.title = element_blank(),
                      legend.text = element_text(size = legend_text_size - 1),
                      legend.key.size = unit(0.4, "cm")
                    ) +
                    guides(fill = guide_legend(nrow = legend_rows, ncol = legend_cols, byrow = TRUE))
                  metab_values$shared_legend_plot <- p_with_legend
                }
                
                pie_plots[[i]] <- p_group
              }
              
              # Store pie plots and number of groups for rendering
              metab_values$pie_plots <- pie_plots
              metab_values$use_multiple_pies <- TRUE
              metab_values$n_pie_groups <- length(groups)

              # Provide a lightweight placeholder so renderPlot has an object
              p <- ggplot() +
                annotate("text", x = 0.5, y = 0.5,
                         label = paste(length(groups), "group pies will render"),
                         size = 5) +
                theme_void()
              metab_values$current_plot <- p
              
            } else {
              # Single group - create one pie chart
              metab_values$use_multiple_pies <- FALSE
              
              original_n <- nrow(plot_data)
              
              # Limit to top N terms for pie chart readability
              pie_top_n <- metab_pie_top_terms_val
              if (!is.null(pie_top_n) && pie_top_n > 0 && original_n > pie_top_n) {
                # Sort by abundance and keep top N
                plot_data <- plot_data %>%
                  arrange(desc(Abundance))
                
                top_data <- plot_data[1:pie_top_n, ]
                other_data <- plot_data[(pie_top_n + 1):nrow(plot_data), ]
                
                # Combine remaining into "Other"
                if (nrow(other_data) > 0) {
                  other_row <- data.frame(
                    Category = "Other",
                    Abundance = sum(other_data$Abundance),
                    Percentage = sum(other_data$Percentage),
                    SD = NA,
                    SEM = NA,
                    N = sum(other_data$N),
                    Group = unique(plot_data$Group),
                    stringsAsFactors = FALSE
                  )
                  plot_data <- rbind(top_data, other_row)
                } else {
                  plot_data <- top_data
                }
                
                # Update category colors to include "Other" if needed
                if ("Other" %in% plot_data$Category && !("Other" %in% names(category_colors))) {
                  category_colors <- c(category_colors, "Other" = "#999999")
                }
              }
              
              p <- ggplot(plot_data, aes(x = "", y = Abundance, fill = Category)) +
                geom_bar(stat = "identity", width = 1) +
                coord_polar("y", start = 0) +
                scale_fill_manual(values = category_colors) +
                labs(
                  title = if(title_size == 0) NULL else unique(plot_data$Group),
                  fill = NULL
                ) +
                theme_minimal() +
                theme(
                  axis.title = element_blank(),
                  panel.grid = element_blank(),
                  axis.text = element_blank(),
                  plot.title = if(title_size == 0) element_blank() else element_text(hjust = 0.5, size = title_size, face = "bold"),
                  legend.title = element_text(face = "bold", size = legend_text_size),
                  legend.text = element_text(size = legend_text_size - 1)
                ) +
                geom_text(aes(label = paste0(sprintf("%.1f", Percentage), "%")),
                          position = position_stack(vjust = 0.5),
                          size = 4, fontface = "bold")
              
              metab_values$current_plot <- p
            }
            
          } else if (plot_type == "bar") {
            # Grouped bar chart with error bars (glycomics-style)
            # Limit to top N terms if specified
            top_n <- metab_top_terms_val
            if (!is.null(top_n) && top_n > 0 && top_n < nrow(plot_data)) {
              # Sort by mean abundance across groups and take top N
              plot_data <- plot_data %>%
                dplyr::group_by(Category) %>%
                dplyr::mutate(mean_abundance = mean(Abundance)) %>%
                dplyr::ungroup() %>%
                dplyr::arrange(desc(mean_abundance)) %>%
                dplyr::slice_head(n = top_n) %>%
                dplyr::select(-mean_abundance)
            }
            
            p <- ggplot(plot_data, aes(x = Category, y = Percentage, fill = Group)) +
              geom_bar(stat = "identity", position = position_dodge(width = 0.9)) +
              geom_errorbar(aes(ymin = pmax(0, Percentage - Error), ymax = Percentage + Error),
                            position = position_dodge(width = 0.9),
                            width = 0.25)
            
            p <- p + scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
              scale_fill_manual(values = group_colors) +
              labs(
                title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level)), 
                             if(!is.null(top_n) && top_n > 0) paste0("(Top ", top_n, ")") else ""),
                x = NULL,
                y = "% Mean Abundance"
              ) +
              guides(fill = guide_legend(title = NULL)) +
              theme_minimal() +
              theme(
                axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, face = "bold", color = "black", size = axis_text_size),
                axis.text.y = ggplot2::element_text(face = "bold", color = "black", size = axis_text_size),
                axis.title = ggplot2::element_text(face = "bold", color = "black", size = axis_title_size),
                plot.title = if(title_size == 0) element_blank() else ggplot2::element_text(hjust = 0.5, face = "bold", color = "black", size = title_size),
                axis.ticks.y = ggplot2::element_line(color = "black"),
                axis.ticks.x = ggplot2::element_blank(),
                axis.ticks.length = grid::unit(4, "pt"),
                axis.line.y = ggplot2::element_line(color = "black"),
                legend.position = "right",
                legend.text = ggplot2::element_text(face = "bold", size = legend_text_size),
                panel.grid = ggplot2::element_blank(),
                panel.border = ggplot2::element_rect(color = "black", fill = NA, size = 1),
                plot.margin = ggplot2::margin(t = 30, r = 10, b = 10, l = 30, unit = "pt")
              )
            
            metab_values$current_plot <- p
            message("[DEBUG-METAB observe] Single pie plot created")
            
          } else {
            # Default to grouped bar chart
            # Limit to top N terms if specified
            top_n <- metab_top_terms_val
            if (!is.null(top_n) && top_n > 0 && top_n < nrow(plot_data)) {
              # Sort by mean abundance across groups and take top N
              plot_data <- plot_data %>%
                dplyr::group_by(Category) %>%
                dplyr::mutate(mean_abundance = mean(Abundance)) %>%
                dplyr::ungroup() %>%
                dplyr::arrange(desc(mean_abundance)) %>%
                dplyr::slice_head(n = top_n) %>%
                dplyr::select(-mean_abundance)
            }
            
            p <- ggplot(plot_data, aes(x = Category, y = Percentage, fill = Group)) +
              geom_bar(stat = "identity", position = position_dodge(width = 0.9)) +
              geom_errorbar(aes(ymin = pmax(0, Percentage - Error), ymax = Percentage + Error),
                            position = position_dodge(width = 0.9),
                            width = 0.25) +
              scale_fill_manual(values = group_colors) +
              labs(
                title = paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level)),
                             if(!is.null(top_n) && top_n > 0) paste0("(Top ", top_n, ")") else ""),
                x = NULL,
                y = "% Mean Abundance"
              ) +
              theme_minimal() +
              theme(
                axis.text.x = element_text(angle = 45, hjust = 1),
                legend.position = "right"
              )
            
            metab_values$current_plot <- p
          }
          
          # Generate summary text for group comparison
          metab_values$summary_text <- paste0(
            "=== METABOLITE CLASSIFICATION BY GROUP ===\n\n",
            "Groups\n",
            "Classification Level: ", gsub("_", " ", tools::toTitleCase(class_level)), "\n",
            "Number of Groups: ", length(unique(plot_data$Group)), "\n",
            "Number of Categories: ", length(unique(plot_data$Category)), "\n",
            "Error Bars: ", toupper(error_col), "\n\n",
            "--- Distribution by Group ---\n",
            paste(
              sapply(unique(plot_data$Group), function(g) {
                group_data <- plot_data[plot_data$Group == g, ]
                paste0("\n", g, ":\n",
                       paste(sapply(seq_len(nrow(group_data)), function(i) {
                         sprintf("  %s: %.1f%% (±%.2f)", 
                                group_data$Category[i], 
                                group_data$Percentage[i], 
                                group_data$Error[i])
                       }), collapse = "\n"))
              }),
              collapse = "\n"
            )
          )
          
        } else {
          # =====================================================================
          # ORIGINAL SIMPLE CLASSIFICATION (for manual input or when no group data)
          # =====================================================================
          
          # Get classification summary for selected level
          summary_data <- summarize_metabolite_classification_cached(
            metab_values$classification_data,
            level = class_level
          )
          
          if (is.null(summary_data) || nrow(summary_data) == 0) {
            showNotification("No classification data available for visualization.", type = "warning")
            return()
          }
          
          setProgress(0.5, detail = "Creating plot...")
          
          # Create plot based on type
          if (plot_type == "pie") {
            # Limit to top N terms for pie chart readability
            pie_top_n <- metab_pie_top_terms_val
            if (!is.null(pie_top_n) && pie_top_n > 0 && nrow(summary_data) > pie_top_n) {
              # Sort by count and keep top N
              summary_data <- summary_data %>%
                arrange(desc(count))
              
              top_data <- summary_data[1:pie_top_n, ]
              other_data <- summary_data[(pie_top_n + 1):nrow(summary_data), ]
              
              # Combine remaining into "Other"
              if (nrow(other_data) > 0) {
                other_row <- top_data[1, , drop = FALSE]
                other_row$count <- sum(other_data$count)
                other_row$percentage <- sum(other_data$percentage)
                other_row[[class_level]] <- "Other"
                if ("color" %in% names(other_row)) {
                  other_row$color <- "#BDC3C7"
                }
                summary_data <- rbind(top_data, other_row)
              } else {
                summary_data <- top_data
              }
            }
            
            # Update colors after potential limiting
            n_categories <- nrow(summary_data)
            color_values <- get_color_palette(input$metab_color_palette, n_categories)
            names(color_values) <- summary_data[[class_level]]
            
            p <- ggplot(summary_data, aes(x = "", y = count, fill = !!sym(class_level))) +
              geom_bar(stat = "identity", width = 1, color = "white") +
              coord_polar("y", start = 0) +
              scale_fill_manual(values = color_values) +
              labs(
                title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level))),
                fill = NULL
              ) +
              theme_void() +
              theme(
                plot.title = if(title_size == 0) element_blank() else element_text(size = title_size, hjust = 0.5, face = "bold"),
                legend.text = element_text(size = legend_text_size),
                legend.title = element_text(size = legend_text_size + 1, face = "bold"),
                legend.position = "right"
              ) +
              geom_text(aes(label = paste0(count, " (", percentage, "%)")),
                        position = position_stack(vjust = 0.5),
                        size = 3, color = "white")
            
          } else if (plot_type == "bar") {
            # Limit to top N terms if specified
            top_n <- metab_top_terms_val
            if (!is.null(top_n) && top_n > 0) {
              summary_data <- summary_data %>%
                arrange(desc(count)) %>%
                head(top_n)
            }
            
            # Get colors after potential limiting
            n_categories <- nrow(summary_data)
            color_values <- get_color_palette(input$metab_color_palette, n_categories)
            names(color_values) <- summary_data[[class_level]]
            
            p <- ggplot(summary_data, aes(x = reorder(!!sym(class_level), count), y = count, fill = !!sym(class_level))) +
              geom_bar(stat = "identity") +
              scale_fill_manual(values = color_values) +
              labs(
                title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level)),
                             if(!is.null(top_n) && top_n > 0) paste0("(Top ", top_n, ")") else ""),
                x = NULL,
                y = "Count"
              ) +
              theme_minimal() +
              theme(
                plot.title = if(title_size == 0) element_blank() else element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
                axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
                axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
                axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, face = "bold", color = "black", size = axis_text_size),
                axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black"),
                axis.ticks.y = ggplot2::element_line(color = "black"),
                axis.ticks.x = ggplot2::element_blank(),
                axis.ticks.length = grid::unit(4, "pt"),
                axis.line.y = ggplot2::element_line(color = "black"),
                legend.position = "right",
                legend.text = ggplot2::element_text(face = "bold", size = legend_text_size),
                panel.grid = ggplot2::element_blank(),
                panel.border = ggplot2::element_rect(color = "black", fill = NA, size = 1),
                plot.margin = ggplot2::margin(t = 30, r = 10, b = 10, l = 30, unit = "pt")
              )
            
            if (!is.null(count_font_size) && count_font_size > 0) {
              p <- p + geom_text(aes(label = count), vjust = -0.5, size = count_font_size / 2.845, color = "black", fontface = "bold")
            }
            
          } else {
            # Default to bar chart
            p <- ggplot(summary_data, aes(x = reorder(!!sym(class_level), count), y = count, fill = !!sym(class_level))) +
              geom_bar(stat = "identity") +
              scale_fill_manual(values = color_values) +
              coord_flip() +
              labs(
                title = paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level))),
                x = gsub("_", " ", tools::toTitleCase(class_level)),
                y = "Count"
              ) +
              theme_minimal() +
              theme(legend.position = "none")
          }
          
          metab_values$current_plot <- p
          
          # Generate summary text
          metab_values$summary_text <- paste0(
            "=== METABOLITE CLASSIFICATION SUMMARY ===\n\n",
            "Count\n",
            "Classification Level: ", gsub("_", " ", tools::toTitleCase(class_level)), "\n",
            "Total Metabolites: ", sum(summary_data$count), "\n",
            "Number of Categories: ", nrow(summary_data), "\n\n",
            "--- Distribution ---\n",
            paste(
              sapply(seq_len(nrow(summary_data)), function(i) {
                sprintf("  %s: %d (%.1f%%)", summary_data[[class_level]][i], summary_data$count[i], summary_data$percentage[i])
              }),
              collapse = "\n"
            )
          )
        }
        
      } else if (analysis_type == "pathway") {
        # Pathway visualization
        req(metab_values$pathway_summary)
        
        summary_data <- metab_values$pathway_summary
        
        if (nrow(summary_data) == 0) {
          showNotification("No pathway data available.", type = "warning")
          return()
        }
        
        # Show top pathways - use user-specified value if available
        top_n_input <- input$metab_pathway_top_n %||% 20
        top_n <- min(top_n_input, nrow(summary_data))
        plot_data <- head(summary_data, top_n)
        
        # Create plot based on type - re-capture to ensure current value
        current_plot_type <- input$metab_plot_type %||% "bar"
        if (current_plot_type == "dot") {
          # Dot plot: Fold enrichment vs pathway name, colored by -log10(p-value), sized by hits
          # This mimics the enrichment tab dot plot design
          plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
          
          p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                      y = reorder(pathway_name, enrichment_ratio))) +
            geom_point(aes(size = hits, color = neg_log_p), alpha = 0.8) +
            scale_color_gradient(low = "#FFC107", high = "#DC3545", 
                                name = "-log10(Adj. P)") +
            scale_size_continuous(range = c(3, 10), name = "Hits") +
            labs(
              title = "KEGG Pathway Enrichment",
              x = "Fold Enrichment",
              y = ""
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1),
              legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.position = "right"
            )
        } else if (current_plot_type == "bar") {
          # Horizontal bar chart - Fold enrichment on x-axis, colored by p-value significance
          plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
          
          p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                      y = reorder(pathway_name, enrichment_ratio),
                                      fill = neg_log_p)) +
            geom_bar(stat = "identity", color = "black", size = 0.3) +
            scale_fill_gradient(low = "#FFC107", high = "#DC3545", 
                                name = "-log10(Adj. P)") +
            labs(
              title = "KEGG Pathway Enrichment",
              x = "Fold Enrichment",
              y = ""
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              plot.subtitle = element_text(size = 9, hjust = 0.5, color = "gray50"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1),
              legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.position = "right"
            )
        }

        
        metab_values$current_plot <- p
        
        # Get background size from stored value or attribute
        bg_size_display <- metab_values$enrichment_background_size %||% 
                           attr(summary_data, "analysis_params")$background_size %||% 
                           6610
        
        metab_values$summary_text <- paste0(
          "=== PATHWAY ANALYSIS SUMMARY ===\n\n",
          "Background Universe: ", format(bg_size_display, big.mark = ","), " compounds\n",
          "Total Pathways Found: ", nrow(summary_data), "\n",
          "Pathways Displayed: ", top_n, "\n",
          "Total Pathway-Metabolite Associations: ", sum(summary_data$hits), "\n\n",
          "--- Top ", min(10, top_n), " Pathways ---\n",
          paste(
            sapply(seq_len(min(10, nrow(plot_data))), function(i) {
              sprintf("  %s: %d metabolites (fold enrichment: %.2f)", 
                     plot_data$pathway_name[i], plot_data$hits[i], plot_data$enrichment_ratio[i])
            }),
            collapse = "\n"
          )
        )
        
      } else if (analysis_type == "module") {
        # Module enrichment visualization
        req(metab_values$module_summary)
        
        summary_data <- metab_values$module_summary
        
        if (nrow(summary_data) == 0) {
          showNotification("No module data available.", type = "warning")
          return()
        }
        
        # Show top modules - use user-specified value if available
        top_n_input <- input$metab_module_top_n %||% 20
        top_n <- min(top_n_input, nrow(summary_data))
        plot_data <- head(summary_data, top_n)
        
        # Create plot based on type - re-capture to ensure current value
        current_plot_type <- input$metab_plot_type %||% "bar"
        if (current_plot_type == "dot") {
          # Dot plot: Fold enrichment vs module name, colored by -log10(p-value), sized by hits
          plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))
          
          p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                      y = reorder(module_name, enrichment_ratio))) +
            geom_point(aes(size = hits, color = neg_log_p), alpha = 0.8) +
            scale_color_gradient(low = "#FFC107", high = "#DC3545", 
                                name = "-log10(Adj. P)") +
            scale_size_continuous(range = c(3, 10), name = "Hits") +
            labs(
              title = "KEGG Module Enrichment",
              x = "Fold Enrichment",
              y = ""
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1),
              legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.position = "right"
            )
        } else if (current_plot_type == "bar") {
          # Horizontal bar chart - Fold enrichment on x-axis, colored by p-value significance
          plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
          
          p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                      y = reorder(module_name, enrichment_ratio),
                                      fill = neg_log_p)) +
            geom_bar(stat = "identity", color = "black", size = 0.3) +
            scale_fill_gradient(low = "#FFC107", high = "#DC3545", 
                                name = "-log10(Adj. P)") +
            labs(
              title = "KEGG Module Enrichment",
              x = "Fold Enrichment",
              y = ""
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              plot.subtitle = element_text(size = 9, hjust = 0.5, color = "gray50"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1),
              legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
              legend.position = "right"
            )
        }
        
        metab_values$current_plot <- p
        
        # Get background size from stored value or attribute
        bg_size_display <- metab_values$enrichment_background_size %||% 
                           attr(summary_data, "analysis_params")$background_size %||% 
                           6610
        
        metab_values$summary_text <- paste0(
          "=== MODULE ANALYSIS SUMMARY ===\n\n",
          "Background Universe: ", format(bg_size_display, big.mark = ","), " compounds\n",
          "Total Modules Found: ", nrow(summary_data), "\n",
          "Modules Displayed: ", top_n, "\n",
          "Total Module-Metabolite Associations: ", sum(summary_data$hits), "\n\n",
          "--- Top ", min(10, top_n), " Modules ---\n",
          paste(
            sapply(seq_len(min(10, nrow(plot_data))), function(i) {
              sprintf("  %s: %d metabolites (fold enrichment: %.2f)", 
                     plot_data$module_name[i], plot_data$hits[i], plot_data$enrichment_ratio[i])
            }),
            collapse = "\n"
          )
        )
        
      } else if (analysis_type == "biospecimen") {

        # Biospecimen distribution visualization
        req(metab_values$associations_data)
        
        # Parse biospecimen data from associations
        if (is.null(metab_values$associations_data) || nrow(metab_values$associations_data) == 0) {
          showNotification("No biospecimen data available. Ensure metabolites have biospecimen associations.", type = "warning")
          return()
        }
        
        # Count occurrences of biospecimens
        biospec_list <- metab_values$associations_data$Biospecimens
        if (all(is.na(biospec_list) | biospec_list == "")) {
          showNotification("No biospecimen data found in metabolite associations.", type = "warning")
          return()
        }
        
        # Split and count biospecimens
        biospec_counts <- table(unlist(strsplit(paste(biospec_list, collapse = ","), ",\\s*")))
        biospec_counts <- biospec_counts[biospec_counts > 0]
        
        if (length(biospec_counts) == 0) {
          showNotification("No biospecimen data found in metabolite associations.", type = "warning")
          return()
        }
        
        summary_data <- data.frame(
          biospecimen = names(biospec_counts),
          count = as.numeric(biospec_counts),
          stringsAsFactors = FALSE
        )
        summary_data$percentage <- (summary_data$count / sum(summary_data$count)) * 100
        summary_data <- summary_data[order(-summary_data$count), ]
        
        # Get colors with improved palette
        n_categories <- nrow(summary_data)
        color_values <- get_color_palette(input$metab_color_palette, n_categories)
        
        # Create plot based on type
        if (plot_type == "pie") {
          p <- ggplot(summary_data, aes(x = "", y = count, fill = biospecimen)) +
            geom_bar(stat = "identity", width = 1, color = "white") +
            coord_polar("y", start = 0) +
            scale_fill_manual(values = color_values) +
            labs(
              title = "Metabolite Distribution by Biospecimen",
              fill = "Biospecimen"
            ) +
            theme_void() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold"),
              legend.text = element_text(size = legend_text_size),
              legend.title = element_text(size = legend_text_size + 1, face = "bold"),
              legend.position = "right"
            ) +
            geom_text(aes(label = paste0(count, " (", round(percentage, 1), "%)")),
                      position = position_stack(vjust = 0.5),
                      size = 3, color = "white")
        } else if (plot_type == "bar") {
          # Vertical bar chart
          p <- ggplot(summary_data, aes(x = reorder(biospecimen, -count), y = count, fill = biospecimen)) +
            geom_bar(stat = "identity") +
            scale_fill_manual(values = color_values) +
            labs(
              title = "Metabolite Distribution by Biospecimen",
              x = "Biospecimen",
              y = "Count"
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.x = element_text(size = axis_text_size - 1, face = "bold", color = "black", angle = 45, hjust = 1),
              legend.position = "none",
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1)
            ) +
            geom_text(aes(label = count), vjust = -0.2, size = 3, color = "black", fontface = "bold")
        } else if (plot_type == "barh") {
          # Horizontal bar chart (existing code)
          p <- ggplot(summary_data, aes(x = reorder(biospecimen, count), y = count, fill = biospecimen)) +
            geom_bar(stat = "identity") +
            scale_fill_manual(values = color_values) +
            coord_flip() +
            labs(
              title = "Metabolite Distribution by Biospecimen",
              x = "Biospecimen",
              y = "Count"
            ) +
            theme_minimal() +
            theme(
              plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
              axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
              axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
              axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
              legend.position = "none",
              panel.grid = element_blank(),
              panel.border = element_rect(fill = NA, color = "black", size = 1)
            ) +
            geom_text(aes(label = count), hjust = -0.2, size = 3, color = "black", fontface = "bold")
        }
        
        metab_values$current_plot <- p
        
        metab_values$summary_text <- paste0(
          "=== BIOSPECIMEN DISTRIBUTION SUMMARY ===\n\n",
          "Total Biospecimens: ", nrow(summary_data), "\n",
          "Total Metabolite-Biospecimen Associations: ", sum(summary_data$count), "\n\n",
          "--- Distribution ---\n",
          paste(
            sapply(seq_len(nrow(summary_data)), function(i) {
              sprintf("  %s: %d (%.1f%%)", summary_data$biospecimen[i], summary_data$count[i], summary_data$percentage[i])
            }),
            collapse = "\n"
          )
        )
      }
      
      setProgress(1, detail = "Done!")
    })
    
    showNotification("Visualization generated!", type = "message", duration = 3)
  })

  # Log changes to metab_plot_type to detect unexpected resets
  observeEvent(input$metab_plot_type, {
    message("[DEBUG-METAB input] metab_plot_type changed to: ", input$metab_plot_type)
  }, ignoreNULL = TRUE, ignoreInit = FALSE)
  
  # Reactive observer for visualization settings changes (font sizes, plot dimensions, top terms)
  # This ensures the plot updates whenever any setting changes without needing to regenerate
  observe({
    # Trigger when any visualization settings change
    input$metab_title_size; input$metab_axis_title_size; input$metab_axis_text_size; input$metab_legend_text_size
    input$metab_title_size_bar; input$metab_axis_title_size_bar; input$metab_axis_text_size_bar; input$metab_legend_text_size_bar
    input$metab_count_font_size
    input$metab_top_terms; input$metab_pie_top_terms
    input$metab_plot_type; input$metab_color_palette; input$metab_error_type; input$metab_plot_mode
    
    # Only update if we have an existing plot or valid classification data
    # req(metab_values$current_plot)
    req(metab_values$classification_data)
    
    # Avoid re-entrance while a render operation is ongoing
    if (isTRUE(metab_values$is_rendering)) {
      message("[DEBUG-METAB observe] Skipping observer because a render is in progress")
      return()
    }

    # Parse numeric inputs safely in the observe block (same as in the generate button)
    metab_top_terms_val <- {
      val <- input$metab_top_terms
      if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 20
    }
    metab_pie_top_terms_val <- {
      val <- input$metab_pie_top_terms
      if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
    }

    # Get current settings
    plot_type <- input$metab_plot_type %||% "bar"
    analysis_type <- input$metab_analysis_type %||% "classification"
    class_level <- input$metab_class_level
    
      # Get font sizes - handle both bar and non-bar input IDs
      if (plot_type == "bar") {
        title_size <- {
          val <- input$metab_title_size_bar
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else {
            val <- input$metab_title_size
            if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 14
          }
        }
        axis_title_size <- {
          val <- input$metab_axis_title_size_bar
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else {
            val <- input$metab_axis_title_size
            if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 12
          }
        }
        axis_text_size <- {
          val <- input$metab_axis_text_size_bar
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else {
            val <- input$metab_axis_text_size
            if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
          }
        }
        legend_text_size <- {
          val <- input$metab_legend_text_size_bar
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else {
            val <- input$metab_legend_text_size
            if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
          }
        }
        count_font_size <- {
          val <- input$metab_count_font_size
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 8
        }
      } else {
        title_size <- {
          val <- input$metab_title_size
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 14
        }
        axis_title_size <- {
          val <- input$metab_axis_title_size
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 12
        }
        axis_text_size <- {
          val <- input$metab_axis_text_size
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
        }
        legend_text_size <- {
          val <- input$metab_legend_text_size
          if (!is.null(val) && val != "" && !is.na(suppressWarnings(as.numeric(val)))) suppressWarnings(as.numeric(val)) else 10
        }
        count_font_size <- NULL
      }    # For pie/bar charts with group comparison, we need to regenerate with new top terms
    if (analysis_type == "classification") {
      plot_mode <- input$metab_plot_mode %||% "groups"
      use_group_comparison <- plot_mode == "groups" && 
                              !is.null(values$normalized_data) && 
                              !is.null(values$unique_groups)
      
      if (use_group_comparison && !is.null(metab_values$all_distributions)) {
        # Clear previous pie plots if user selected bar chart
        if (plot_type != "pie") {
          metab_values$pie_plots <- NULL
          metab_values$use_multiple_pies <- FALSE
        }
        # Build viz state to avoid endless reactive loops by re-applying the same plot multiple times
        viz_state <- list(
          plot_type = plot_type,
          plot_mode = plot_mode,
          top_terms = metab_top_terms_val,
          pie_top_terms = metab_pie_top_terms_val,
          palette = input$metab_color_palette %||% NA,
          error_type = input$metab_error_type %||% NA,
          title_size = title_size,
          axis_title_size = axis_title_size,
          axis_text_size = axis_text_size,
          legend_text_size = legend_text_size,
          count_font_size = count_font_size
        )
        viz_hash <- digest::digest(viz_state)
        if (!is.null(metab_values$viz_state_hash) && metab_values$viz_state_hash == viz_hash) {
          message("[DEBUG-METAB observe] Viz state unchanged; skipping re-render to avoid loop")
          return()
        }
        metab_values$viz_state_hash <- viz_hash
        message("[DEBUG-METAB observe] Visualization observer triggered. analysis_type=", analysis_type, ", plot_type=", plot_type, ", use_group_comparison=", use_group_comparison)
        # Re-create the plot with updated font sizes and top terms
        all_distributions <- metab_values$all_distributions
        plot_data <- all_distributions
        
        if (plot_type == "pie") {
          # Regenerate pie charts with new top_terms setting
          metab_values$pie_plots <- NULL
          metab_values$use_multiple_pies <- FALSE
          
          groups <- unique(all_distributions$Group)
          
          if (length(groups) > 1) {
            # Build global color mapping once for consistent colors across groups
            unique_cats <- unique(all_distributions$Category)
            n_cats <- length(unique_cats)
            if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
              global_cat_colors <- setNames(
                viridis::viridis_pal(option = input$metab_color_palette)(n_cats),
                unique_cats
              )
            } else if (input$metab_color_palette == "rainbow") {
              global_cat_colors <- setNames(rainbow(n_cats), unique_cats)
            } else {
              palette <- input$metab_color_palette
              colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_cats), 9), palette)
              if (n_cats > 9) colors_vec <- colorRampPalette(colors_vec)(n_cats)
              global_cat_colors <- setNames(colors_vec[1:n_cats], unique_cats)
            }
            if ("Other" %in% names(global_cat_colors)) {
              global_cat_colors["Other"] <- "#999999"
            }

            pie_plots <- list()
            group_data_list <- list()
            group_categories_list <- list()
            
            # First pass: apply top N filtering to each group and collect categories
            for (i in seq_along(groups)) {
              group <- groups[i]
              group_data <- all_distributions[all_distributions$Group == group, ]
              original_n <- nrow(group_data)
              
              pie_top_n <- metab_pie_top_terms_val
              if (!is.null(pie_top_n) && pie_top_n > 0 && original_n > pie_top_n) {
                group_data <- group_data %>% arrange(desc(Abundance))
                top_data <- group_data[1:pie_top_n, ]
                other_data <- group_data[(pie_top_n + 1):nrow(group_data), ]
                
                if (nrow(other_data) > 0) {
                  other_row <- data.frame(
                    Category = "Other",
                    Abundance = sum(other_data$Abundance),
                    Percentage = sum(other_data$Percentage),
                    SD = NA,
                    SEM = NA,
                    N = sum(other_data$N),
                    Group = group,
                    stringsAsFactors = FALSE
                  )
                  group_data <- rbind(top_data, other_row)
                } else {
                  group_data <- top_data
                }
              }
              
              group_data_list[[i]] <- group_data
              group_categories_list[[i]] <- sort(unique(group_data$Category))
            }
            
            # Determine if shared legend should be used
            shared_legend <- FALSE
            if (length(group_categories_list) > 1 && requireNamespace("cowplot", quietly = TRUE)) {
              group_key <- vapply(group_categories_list, function(x) paste(sort(unique(x)), collapse = "|"), character(1))
              shared_legend <- length(unique(group_key)) == 1
            }
            metab_values$pie_shared_legend <- shared_legend
            
            # Compute filtered colors (only displayed categories)
            displayed_categories <- unique(unlist(group_categories_list))
            filtered_cat_colors <- global_cat_colors[names(global_cat_colors) %in% displayed_categories]
            if ("Other" %in% displayed_categories && !("Other" %in% names(filtered_cat_colors))) {
              filtered_cat_colors <- c(filtered_cat_colors, "Other" = "#999999")
            }
            
            # Second pass: create plots
            for (i in seq_along(groups)) {
              group <- groups[i]
              group_data <- group_data_list[[i]]
              
              group_cat_colors <- filtered_cat_colors[names(filtered_cat_colors) %in% group_data$Category]
              if ("Other" %in% group_data$Category && !("Other" %in% names(group_cat_colors))) {
                group_cat_colors <- c(group_cat_colors, "Other" = "#999999")
              }
              
              legend_pos <- if (shared_legend) "none" else "bottom"
              legend_rows <- ceiling(length(group_cat_colors) / 3)
              
              p_group <- ggplot(group_data, aes(x = "", y = Abundance, fill = Category)) +
                geom_bar(stat = "identity", width = 1) +
                coord_polar("y", start = 0) +
                scale_fill_manual(values = filtered_cat_colors, breaks = group_data$Category, drop = TRUE) +
                labs(
                  title = if(title_size == 0) NULL else group,
                  fill = NULL
                ) +
                theme_minimal() +
                theme(
                  axis.title = element_blank(),
                  panel.grid = element_blank(),
                  axis.text = element_blank(),
                  plot.title = if(title_size == 0) element_blank() else element_text(hjust = 0.5, size = title_size, face = "bold"),
                  legend.position = legend_pos,
                  legend.direction = "horizontal",
                  legend.title = element_blank(),
                  legend.text = element_text(size = legend_text_size - 1),
                  legend.key.size = unit(0.4, "cm"),
                  plot.margin = margin(5, 5, 5, 5)
                ) +
                guides(fill = guide_legend(nrow = legend_rows)) +
                geom_text(aes(label = paste0(sprintf("%.1f", Percentage), "%")),
                          position = position_stack(vjust = 0.5),
                          size = 3.5, fontface = "bold")
              
              # Create shared legend plot from first group
              if (shared_legend && i == 1) {
                legend_rows_shared <- 4
                legend_cols_shared <- max(1, ceiling(length(displayed_categories) / legend_rows_shared))
                legend_data <- data.frame(
                  Category = factor(displayed_categories, levels = displayed_categories),
                  Abundance = 1
                )
                p_with_legend <- ggplot(legend_data, aes(x = "", y = Abundance, fill = Category)) +
                  geom_bar(stat = "identity", width = 1) +
                  coord_polar("y", start = 0) +
                  scale_fill_manual(values = filtered_cat_colors, breaks = displayed_categories, drop = FALSE) +
                  labs(fill = NULL) +
                  theme_minimal() +
                  theme(
                    legend.position = "bottom",
                    legend.direction = "horizontal",
                    legend.title = element_blank(),
                    legend.text = element_text(size = legend_text_size - 1),
                    legend.key.size = unit(0.4, "cm")
                  ) +
                  guides(fill = guide_legend(nrow = legend_rows_shared, ncol = legend_cols_shared, byrow = TRUE))
                metab_values$shared_legend_plot <- p_with_legend
              }
              
              pie_plots[[i]] <- p_group
            }
            
            # Mark as rendering
            metab_values$is_rendering <- TRUE
            metab_values$pie_plots <- pie_plots
            metab_values$use_multiple_pies <- TRUE
            message("[DEBUG-METAB observe] Set multiple pie plots: ", length(pie_plots))
            
            p <- ggplot() +
              annotate("text", x = 0.5, y = 0.5,
                       label = paste(length(groups), "group pies will render"),
                       size = 5) +
              theme_void()
            metab_values$current_plot <- p
            metab_values$is_rendering <- FALSE
          } else {
            # Single group pie chart
            metab_values$is_rendering <- TRUE
            original_n <- nrow(plot_data)
            pie_top_n <- metab_pie_top_terms_val
            if (!is.null(pie_top_n) && pie_top_n > 0 && original_n > pie_top_n) {
              plot_data <- plot_data %>% arrange(desc(Abundance))
              top_data <- plot_data[1:pie_top_n, ]
              other_data <- plot_data[(pie_top_n + 1):nrow(plot_data), ]
              
              if (nrow(other_data) > 0) {
                other_row <- data.frame(
                  Category = "Other",
                  Abundance = sum(other_data$Abundance),
                  Percentage = sum(other_data$Percentage),
                  SD = NA,
                  SEM = NA,
                  N = sum(other_data$N),
                  Group = unique(plot_data$Group),
                  stringsAsFactors = FALSE
                )
                plot_data <- rbind(top_data, other_row)
              } else {
                plot_data <- top_data
              }
            }
            
            unique_cats <- unique(all_distributions$Category)
            n_cats <- length(unique_cats)
            if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
              category_colors <- setNames(
                viridis::viridis_pal(option = input$metab_color_palette)(n_cats),
                unique_cats
              )
            } else if (input$metab_color_palette == "rainbow") {
              category_colors <- setNames(rainbow(n_cats), unique_cats)
            } else {
              palette <- input$metab_color_palette
              colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_cats), 9), palette)
              if (n_cats > 9) colors_vec <- colorRampPalette(colors_vec)(n_cats)
              category_colors <- setNames(colors_vec[1:n_cats], unique_cats)
            }
            
            if ("Other" %in% plot_data$Category && !("Other" %in% names(category_colors))) {
              category_colors <- c(category_colors, "Other" = "#999999")
            }
            
            p <- ggplot(plot_data, aes(x = "", y = Abundance, fill = Category)) +
              geom_bar(stat = "identity", width = 1) +
              coord_polar("y", start = 0) +
              scale_fill_manual(values = category_colors) +
              labs(
                title = if(title_size == 0) NULL else unique(plot_data$Group),
                fill = NULL
              ) +
              theme_minimal() +
              theme(
                axis.title = element_blank(),
                panel.grid = element_blank(),
                axis.text = element_blank(),
                plot.title = if(title_size == 0) element_blank() else element_text(hjust = 0.5, size = title_size, face = "bold"),
                legend.title = element_text(face = "bold", size = legend_text_size),
                legend.text = element_text(size = legend_text_size - 1)
              ) +
              geom_text(aes(label = paste0(sprintf("%.1f", Percentage), "%")),
                        position = position_stack(vjust = 0.5),
                        size = 4, fontface = "bold")
            
            metab_values$current_plot <- p
            metab_values$is_rendering <- FALSE
          }
        } else if (plot_type == "bar") {
          metab_values$is_rendering <- TRUE
          # Regenerate bar chart with new font sizes and top terms
          top_n <- metab_top_terms_val
          if (!is.null(top_n) && top_n > 0 && top_n < nrow(plot_data)) {
            plot_data <- plot_data %>%
              dplyr::group_by(Category) %>%
              dplyr::mutate(mean_abundance = mean(Abundance)) %>%
              dplyr::ungroup() %>%
              dplyr::arrange(desc(mean_abundance)) %>%
              dplyr::slice_head(n = top_n) %>%
              dplyr::select(-mean_abundance)
          }
          
          # Get group colors
          n_groups <- length(unique(plot_data$Group))
          if (input$metab_color_palette %in% c("viridis", "plasma", "magma", "inferno", "cividis")) {
            group_colors <- setNames(
              viridis::viridis_pal(option = input$metab_color_palette)(n_groups),
              unique(plot_data$Group)
            )
          } else if (input$metab_color_palette == "rainbow") {
            group_colors <- setNames(rainbow(n_groups), unique(plot_data$Group))
          } else {
            palette <- if (input$metab_color_palette == "metabolite") "Set1" else input$metab_color_palette
            colors_vec <- RColorBrewer::brewer.pal(min(max(3, n_groups), 9), palette)
            if (n_groups > 9) colors_vec <- colorRampPalette(colors_vec)(n_groups)
            group_colors <- setNames(colors_vec[1:n_groups], unique(plot_data$Group))
          }
          
          error_col <- if ((input$metab_error_type %||% "sem") == "sem") "SEM" else "SD"
          plot_data$Error <- plot_data[[error_col]]
          
          p <- ggplot(plot_data, aes(x = Category, y = Percentage, fill = Group)) +
            geom_bar(stat = "identity", position = position_dodge(width = 0.9)) +
            geom_errorbar(aes(ymin = pmax(0, Percentage - Error), ymax = Percentage + Error),
                          position = position_dodge(width = 0.9),
                          width = 0.25) +
            scale_y_continuous(expand = expansion(mult = c(0, 0.15))) +
            scale_fill_manual(values = group_colors) +
            labs(
              title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level)), 
                           if(!is.null(top_n) && top_n > 0) paste0("(Top ", top_n, ")") else ""),
              x = NULL,
              y = "% Mean Abundance"
            ) +
            guides(fill = guide_legend(title = NULL)) +
            scale_x_discrete(labels = function(x) {
              sapply(x, function(label) {
                if (nchar(label) > 15) {
                  if (grepl("Biospecimen", label, ignore.case = TRUE)) {
                    parts <- strsplit(label, ";")[[1]]
                    paste(trimws(parts), collapse = "\n")
                  } else {
                    strwrap(label, width = 15)
                  }
                } else {
                  label
                }
              })
            }) +
            theme_minimal() +
            theme(
              axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, face = "bold", color = "black", size = axis_text_size),
              axis.text.y = ggplot2::element_text(face = "bold", color = "black", size = axis_text_size),
              axis.title = ggplot2::element_text(face = "bold", color = "black", size = axis_title_size),
              plot.title = if(title_size == 0) element_blank() else ggplot2::element_text(hjust = 0.5, face = "bold", color = "black", size = title_size),
              axis.ticks.y = ggplot2::element_line(color = "black"),
              axis.ticks.x = ggplot2::element_line(color = "black"),
              axis.ticks.length = grid::unit(4, "pt"),
              axis.line.y = ggplot2::element_line(color = "black"),
              legend.position = "right",
              legend.text = ggplot2::element_text(face = "bold", size = legend_text_size),
              panel.grid = ggplot2::element_blank(),
              panel.border = ggplot2::element_rect(color = "black", fill = NA, size = 1),
              plot.margin = ggplot2::margin(t = 30, r = 10, b = 10, l = 30, unit = "pt")
            )
          
          metab_values$current_plot <- p
        }
      } else {
        # Non-group classification (summary-based) - regenerate simple classification plots
        # Use cached classification data
        summary_data <- summarize_metabolite_classification_cached(
          metab_values$classification_data,
          level = class_level
        )

        if (is.null(summary_data) || nrow(summary_data) == 0) {
          # Nothing to update
        } else {
          # Clear previous pie plots when user switched to bar
          if (plot_type != "pie") {
            metab_values$pie_plots <- NULL
            metab_values$use_multiple_pies <- FALSE
          }
          # Build viz state hash for non-group classification branch
          viz_state <- list(
            plot_type = plot_type,
            top_terms = input$metab_top_terms %||% NA,
            pie_top_terms = input$metab_pie_top_terms %||% NA,
            palette = input$metab_color_palette %||% NA,
            title_size = title_size,
            axis_title_size = axis_title_size,
            axis_text_size = axis_text_size,
            legend_text_size = legend_text_size,
            count_font_size = count_font_size
          )
          viz_hash <- digest::digest(viz_state)
          if (!is.null(metab_values$viz_state_hash) && metab_values$viz_state_hash == viz_hash) {
            message("[DEBUG-METAB observe] Non-group viz state unchanged; skipping re-render")
            return()
          }
          metab_values$viz_state_hash <- viz_hash
          # Create plot based on type
          if (plot_type == "pie") {
            pie_top_n <- metab_pie_top_terms_val
            sd <- summary_data
            if (!is.null(pie_top_n) && pie_top_n > 0 && nrow(sd) > pie_top_n) {
              sd <- sd %>% arrange(desc(count))
              top_data <- sd[1:pie_top_n, ]
              other_data <- sd[(pie_top_n + 1):nrow(sd), ]
              if (nrow(other_data) > 0) {
                other_row <- top_data[1, , drop = FALSE]
                other_row$count <- sum(other_data$count)
                other_row$percentage <- sum(other_data$percentage)
                other_row[[class_level]] <- "Other"
                if ("color" %in% names(other_row)) {
                  other_row$color <- "#BDC3C7"
                }
                sd <- rbind(top_data, other_row)
              } else {
                sd <- top_data
              }
            }
            n_categories <- nrow(sd)
            color_values <- get_color_palette(input$metab_color_palette, n_categories)
            names(color_values) <- sd[[class_level]]

            metab_values$is_rendering <- TRUE
            p <- ggplot(sd, aes(x = "", y = count, fill = !!sym(class_level))) +
              geom_bar(stat = "identity", width = 1, color = "white") +
              coord_polar("y", start = 0) +
              scale_fill_manual(values = color_values) +
              labs(title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level))), fill = NULL) +
              theme_void() +
              theme(plot.title = if(title_size == 0) element_blank() else element_text(size = title_size, hjust = 0.5, face = "bold"), legend.text = element_text(size = legend_text_size), legend.title = element_text(size = legend_text_size + 1, face = "bold")) +
              geom_text(aes(label = paste0(count, " (", percentage, "%)")), position = position_stack(vjust = 0.5), size = axis_text_size * 0.35, color = "white")

            metab_values$current_plot <- p
            metab_values$is_rendering <- FALSE

          } else if (plot_type == "bar") {
            top_n <- metab_top_terms_val
            sd <- summary_data
            if (!is.null(top_n) && top_n > 0) {
              sd <- sd %>% arrange(desc(count)) %>% head(top_n)
            }
            n_categories <- nrow(sd)
            color_values <- get_color_palette(input$metab_color_palette, n_categories)
            names(color_values) <- sd[[class_level]]

            metab_values$is_rendering <- TRUE
            p <- ggplot(sd, aes(x = reorder(!!sym(class_level), count), y = count, fill = !!sym(class_level))) +
              geom_bar(stat = "identity") +
              scale_fill_manual(values = color_values) +
              scale_x_discrete(labels = function(x) {
                sapply(x, function(label) {
                  if (nchar(label) > 15) {
                    if (grepl("Biospecimen", label, ignore.case = TRUE)) {
                      parts <- strsplit(label, ";")[[1]]
                      paste(trimws(parts), collapse = "\n")
                    } else {
                      strwrap(label, width = 15)
                    }
                  } else {
                    label
                  }
                })
              }) +
              labs(title = if(title_size == 0) NULL else paste("Metabolite Distribution by", gsub("_", " ", tools::toTitleCase(class_level)), if(!is.null(top_n) && top_n > 0) paste0("(Top ", top_n, ")") else ""), x = NULL, y = "Count") +
              theme_minimal() +
              theme(plot.title = if(title_size == 0) element_blank() else element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"), axis.title = element_text(size = axis_title_size, face = "bold", color = "black"), axis.text = element_text(size = axis_text_size, face = "bold", color = "black"), axis.text.x = ggplot2::element_text(angle = 45, hjust = 1, face = "bold", color = "black", size = axis_text_size), axis.text.y = element_text(size = axis_text_size, face = "bold", color = "black"), axis.ticks.y = ggplot2::element_line(color = "black"), axis.ticks.x = ggplot2::element_line(color = "black"), axis.ticks.length = grid::unit(4, "pt"), axis.line.y = ggplot2::element_line(color = "black"), legend.position = "right", legend.text = ggplot2::element_text(face = "bold", size = legend_text_size), panel.grid = ggplot2::element_blank(), panel.border = ggplot2::element_rect(color = "black", fill = NA, size = 1), plot.margin = ggplot2::margin(t = 30, r = 10, b = 10, l = 30, unit = "pt"))
            
            if (!is.null(count_font_size) && count_font_size > 0) {
              p <- p + geom_text(aes(label = count), vjust = -0.5, size = count_font_size / 2.845, color = "black", fontface = "bold")
            }

            metab_values$current_plot <- p
            metab_values$is_rendering <- FALSE
          }
        }
      }
    } else if (analysis_type %in% c("pathway", "module")) {
      # Handle KEGG pathway/module enrichment plots
      message("[DEBUG-METAB observe] Handling enrichment analysis: ", analysis_type)
      
      # Check if we have enrichment results
      if (analysis_type == "pathway" && !is.null(metab_values$pathway_summary)) {
        summary_data <- metab_values$pathway_summary
        plot_title <- "KEGG Pathway Enrichment"
        name_col <- "pathway_name"
      } else if (analysis_type == "module" && !is.null(metab_values$module_summary)) {
        summary_data <- metab_values$module_summary
        plot_title <- "KEGG Module Enrichment"
        name_col <- "module_name"
      } else {
        message("[DEBUG-METAB observe] No enrichment data available for ", analysis_type)
        return()
      }
      
      # Get top N input
      top_n_input <- metab_top_terms_val
      if (is.null(top_n_input) || top_n_input <= 0) {
        top_n_input <- 20
      }
      
      top_n <- min(top_n_input, nrow(summary_data))
      plot_data <- head(summary_data, top_n)
      
      # Create plot based on type
      current_plot_type <- input$metab_plot_type %||% "bar"
      if (current_plot_type == "dot") {
        # Dot plot: Fold enrichment vs pathway/module name, colored by -log10(p-value), sized by hits
        plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
        
        p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                    y = reorder(!!sym(name_col), enrichment_ratio))) +
          geom_point(aes(size = hits, color = neg_log_p), alpha = 0.8) +
          scale_color_gradient(low = "#FFC107", high = "#DC3545", 
                              name = "-log10(Adj. P)") +
          scale_size_continuous(range = c(3, 10), name = "Hits") +
          labs(
            title = plot_title,
            x = "Fold Enrichment",
            y = ""
          ) +
          theme_minimal() +
          theme(
            plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
            panel.grid = element_blank(),
            panel.border = element_rect(fill = NA, color = "black", size = 1),
            legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
            legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
            legend.position = "right"
          )
      } else if (current_plot_type == "bar") {
        # Horizontal bar chart - Fold enrichment on x-axis, colored by p-value significance
        plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
        
        p <- ggplot(plot_data, aes(x = enrichment_ratio, 
                                    y = reorder(!!sym(name_col), enrichment_ratio),
                                    fill = neg_log_p)) +
          geom_bar(stat = "identity", color = "black", size = 0.3) +
          scale_fill_gradient(low = "#FFC107", high = "#DC3545", 
                              name = "-log10(Adj. P)") +
          labs(
            title = plot_title,
            x = "Fold Enrichment",
            y = ""
          ) +
          theme_minimal() +
          theme(
            plot.title = element_text(size = title_size, hjust = 0.5, face = "bold", color = "black"),
            plot.subtitle = element_text(size = 9, hjust = 0.5, color = "gray50"),
            axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
            axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
            axis.text.y = element_text(size = axis_text_size - 1, face = "bold", color = "black"),
            panel.grid = element_blank(),
            panel.border = element_rect(fill = NA, color = "black", size = 1),
            legend.text = element_text(size = legend_text_size, face = "bold", color = "black"),
            legend.title = element_text(size = legend_text_size, face = "bold", color = "black"),
            legend.position = "right"
          )
      }
      
      metab_values$current_plot <- p
      message("[DEBUG-METAB observe] Enrichment plot updated for ", analysis_type, " with plot_type=", current_plot_type)
    }
  })
  
  # Render metabolomics statistics summary
  output$metab_stats_summary_ui <- renderUI({
    req(metab_values$id_mapping_results)  # Ensure this updates whenever ID mapping changes
    
    if (is.null(metab_values$classification_data) && is.null(metab_values$id_mapping_results)) {
      return(
        div(class = "alert alert-info",
            icon("info-circle"), " ",
            "Map metabolite IDs to view classification statistics and visualizations."
        )
      )
    }
    
    # Calculate statistics using correct column names (UPPERCASE)
    n_metabolites <- if (!is.null(metab_values$id_mapping_results)) nrow(metab_values$id_mapping_results) else 0
    
    # Count metabolites with at least one ID mapping across all databases
    n_mapped <- if (!is.null(metab_values$id_mapping_results)) {
      id_cols <- colnames(metab_values$id_mapping_results)
      # Find all database ID columns (KEGG_ID, HMDB_ID, PubChem_CID, ChEBI_ID, LipidMaps_ID)
      db_id_cols <- id_cols[id_cols %in% c("KEGG_ID", "HMDB_ID", "PubChem_CID", "ChEBI_ID", "LipidMaps_ID")]
      
      if (length(db_id_cols) > 0) {
        # Count rows where at least one database ID is non-empty
        sum(apply(metab_values$id_mapping_results[, db_id_cols, drop = FALSE], 1, function(row) {
          any(!is.na(row) & row != "")
        }))
      } else {
        0
      }
    } else 0
    
    n_classified <- if (!is.null(metab_values$classification_data)) sum(metab_values$classification_data$super_class != "Unknown") else 0
    n_pathways <- if (!is.null(metab_values$pathway_summary)) nrow(metab_values$pathway_summary) else 0
    
    fluidRow(
      column(3,
             div(class = "metab-stat-box",
                 span(class = "metab-stat-number", n_metabolites),
                 span(class = "metab-stat-label", "Total Metabolites")
             )
      ),
      column(3,
             div(class = "metab-stat-box", style = "background: linear-gradient(135deg, #e74c3c 0%, #c0392b 100%);",
                 span(class = "metab-stat-number", n_mapped),
                 span(class = "metab-stat-label", "Metabolites Mapped")
             )
      ),
      column(3,
             div(class = "metab-stat-box", style = "background: linear-gradient(135deg, #2ecc71 0%, #27ae60 100%);",
                 span(class = "metab-stat-number", n_classified),
                 span(class = "metab-stat-label", "Classified")
             )
      ),
      column(3,
             div(class = "metab-stat-box", style = "background: linear-gradient(135deg, #f39c12 0%, #d35400 100%);",
                 span(class = "metab-stat-number", n_pathways),
                 span(class = "metab-stat-label", "Pathways Found")
             )
      )
    )
  })
  
