  outputOptions(output, "metab_plot_generated", suspendWhenHidden = FALSE)
  
  # Render the main plot (improved diagnostics + robust multi-pie arrangement)
  output$metab_main_plot <- renderPlot({ 
    # Diagnostic logging for render
    message("[DEBUG-METAB renderPlot] use_multiple_pies=", isTRUE(metab_values$use_multiple_pies), 
            ", pie_plots length=", ifelse(is.null(metab_values$pie_plots), 0, length(metab_values$pie_plots)),
            ", pie_shared_legend=", isTRUE(metab_values$pie_shared_legend),
            ", shared_legend_plot exists=", !is.null(metab_values$shared_legend_plot))

    # If multiple pie charts were generated, arrange them with legends
    if (!is.null(metab_values$use_multiple_pies) && isTRUE(metab_values$use_multiple_pies) && !is.null(metab_values$pie_plots)) {
      n_plots <- length(metab_values$pie_plots)
      ncol_val <- min(2, n_plots)
      nrow_val <- ceiling(n_plots / ncol_val)
      
      tryCatch({
        # Use cowplot::plot_grid for better arrangement
        if (requireNamespace("cowplot", quietly = TRUE)) {
          if (isTRUE(metab_values$pie_shared_legend) && !is.null(metab_values$shared_legend_plot)) {
            message("[DEBUG-METAB renderPlot] Using SHARED LEGEND layout")
            legend_grob <- cowplot::get_legend(metab_values$shared_legend_plot)
            pies_grid <- cowplot::plot_grid(
              plotlist = metab_values$pie_plots,
              ncol = ncol_val,
              nrow = nrow_val,
              align = "hv",
              axis = "tblr"
            )
            arranged_plot <- cowplot::plot_grid(
              pies_grid,
              legend_grob,
              ncol = 1,
              rel_heights = c(1, 0.25)
            )
            print(arranged_plot)
          } else {
            message("[DEBUG-METAB renderPlot] Using INDIVIDUAL LEGENDS layout")
            # Arrange plots in a grid - each pie has its own legend below it
            arranged_plot <- cowplot::plot_grid(
              plotlist = metab_values$pie_plots,
              ncol = ncol_val,
              nrow = nrow_val,
              align = "hv",
              axis = "tblr"
            )
            print(arranged_plot)
          }
        } else {
          # Fallback to gridExtra
          if (n_plots > 1) {
            arranged_plot <- gridExtra::arrangeGrob(grobs = metab_values$pie_plots, ncol = ncol_val)
          } else {
            arranged_plot <- gridExtra::arrangeGrob(grobs = metab_values$pie_plots, ncol = 1)
          }
          grid::grid.draw(arranged_plot)
        }
        message("[DEBUG-METAB renderPlot] grid/cowplot completed for arranged pie plots")
        return(invisible(NULL))
      }, error = function(e) {
        message("[DEBUG-METAB renderPlot] Error arranging pie_plots: ", e$message)
        # Fall back to showing a placeholder indicating error
        p_err <- ggplot() + annotate("text", x = 0.5, y = 0.5, label = "Error rendering pie charts: see console for details", size = 5) + theme_void()
        return(p_err)
      }, res = UI_PLOT_RES)
    }

    # For standard single plots, return the cached ggplot object
    req(metab_values$current_plot)
    message("[DEBUG-METAB renderPlot] returning ggplot object of class: ", paste(class(metab_values$current_plot), collapse = ", "))
    metab_values$current_plot
  }, height = function() {
    # Adjust height for multiple pies with legends - need more vertical space
    base_height <- input$metab_viz_plot_height * 50
    if (!is.null(metab_values$use_multiple_pies) && isTRUE(metab_values$use_multiple_pies) && !is.null(metab_values$n_pie_groups)) {
      n_plots <- metab_values$n_pie_groups
      ncol_val <- min(2, n_plots)
      nrow_val <- ceiling(n_plots / ncol_val)
      legend_extra <- if (isTRUE(metab_values$pie_shared_legend)) 120 else 0
      # Increase height per row to accommodate legends below each pie or shared legend
      return(max(base_height, nrow_val * 400 + legend_extra))
    }
    base_height
  },
     width = function() input$metab_viz_plot_width * 80)
  
  # Render font controls
