      ),
      column(2, style = paste("padding: 2px;", if(input$metab_plot_type == 'bar') "" else "display: none;"),
             numericInput("metab_count_font_size", "Count Font Size:",
                          value = 8, min = 6, max = 16, step = 1, width = "100%")
      )
    )
  })
  
  # Clear viz_state_hash when the user intentionally generates a new plot
  observeEvent(input$generate_metab_btn, {
