    metab_values$summary_text
  })
  
  # Render classification table
  output$metab_classification_table <- DT::renderDataTable({
    req(metab_values$classification_data)
    
    # DEBUG: Log classification data structure
    message("[DEBUG-CLASSIFICATION] Class: ", paste(class(metab_values$classification_data), collapse=", "))
    message("[DEBUG-CLASSIFICATION] Dimensions: ", nrow(metab_values$classification_data), " rows x ", ncol(metab_values$classification_data), " cols")
    message("[DEBUG-CLASSIFICATION] Column names: ", paste(names(metab_values$classification_data), collapse=", "))
