  # =========================================================================
  # FUZZY MATCH REVIEW SYSTEM
  # =========================================================================
  
  # Output for conditional panel - shows Review Suggestions button when fuzzy matches exist
  output$has_fuzzy_suggestions <- reactive({
    !is.null(metab_values$fuzzy_suggestions) && nrow(metab_values$fuzzy_suggestions) > 0
  })
  outputOptions(output, "has_fuzzy_suggestions", suspendWhenHidden = FALSE)
  
  # Observer to show fuzzy match review modal
  observeEvent(input$review_fuzzy_btn, {
    req(metab_values$fuzzy_suggestions)
    
    suggestions <- metab_values$fuzzy_suggestions
    
    # Build the modal content with checkboxes for each suggestion
    suggestion_ui <- lapply(unique(suggestions$original_name), function(orig_name) {
      # Get all suggestions for this original name
      orig_suggestions <- suggestions[suggestions$original_name == orig_name, ]
      
      # Create checkbox choices
      choices <- setNames(
        seq_len(nrow(orig_suggestions)),
        sapply(seq_len(nrow(orig_suggestions)), function(i) {
          row <- orig_suggestions[i, ]
          # Format: "Suggested Name (95% match, typo type) - IDs: KEGG:C00123, HMDB:HMDB0000456"
          ids_str <- c()
          if (row$kegg_id != "") ids_str <- c(ids_str, paste0("KEGG:", row$kegg_id))
          if (row$hmdb_id != "") ids_str <- c(ids_str, paste0("HMDB:", row$hmdb_id))
          if (row$pubchem_id != "") ids_str <- c(ids_str, paste0("PubChem:", row$pubchem_id))
          if (row$chebi_id != "") ids_str <- c(ids_str, paste0("ChEBI:", row$chebi_id))
          
          match_pct <- paste0(round(row$similarity_score * 100), "%")
          match_type <- gsub("_", " ", row$match_type)
          
          sprintf("%s (%s match, %s)%s", 
                  row$suggested_name, 
                  match_pct,
                  match_type,
                  if (length(ids_str) > 0) paste0(" - ", paste(ids_str, collapse = ", ")) else "")
        })
      )
      
      div(
        style = "margin-bottom: 15px; padding: 10px; background: #f8f9fa; border-radius: 6px; border-left: 4px solid #ffc107;",
        h5(style = "margin: 0 0 8px 0; color: #dc3545;", 
           icon("times-circle"), " ", orig_name, " (not found)"),
        checkboxGroupInput(
          inputId = paste0("fuzzy_select_", gsub("[^a-zA-Z0-9]", "_", orig_name)),
          label = "Select a suggestion to use:",
          choices = choices,
          selected = NULL,
          width = "100%"
        )
      )
    })
    
    showModal(modalDialog(
      title = div(icon("search-plus"), " Review Similar Name Suggestions"),
      size = "l",
      easyClose = FALSE,
      
      div(
        style = "margin-bottom: 15px;",
        p(class = "text-muted", 
          "The following metabolites were not found by exact search. ",
          "We found similar names in our database that might be what you're looking for. ",
          "Select the suggestions you want to accept, or leave unchecked to keep as 'not found'.")
      ),
      
      div(
        style = "max-height: 400px; overflow-y: auto;",
        suggestion_ui
      ),
      
      footer = tagList(
        actionButton("fuzzy_apply_btn", "Apply Selected", class = "btn-success", icon = icon("check")),
        actionButton("fuzzy_skip_btn", "Skip All", class = "btn-secondary", icon = icon("forward")),
        modalButton("Cancel")
      )
    ))
  })
  
  # Observer to apply selected fuzzy matches
  observeEvent(input$fuzzy_apply_btn, {
    req(metab_values$fuzzy_suggestions)
    req(metab_values$id_mapping_results)
    
    suggestions <- metab_values$fuzzy_suggestions
    id_results <- metab_values$id_mapping_results
    
    applied_count <- 0
    new_hmdb_ids <- character(0)
    new_kegg_ids <- character(0)
    
    # Process each original name's selections
    for (orig_name in unique(suggestions$original_name)) {
      input_id <- paste0("fuzzy_select_", gsub("[^a-zA-Z0-9]", "_", orig_name))
      selected <- input[[input_id]]
      
      if (!is.null(selected) && length(selected) > 0) {
        # Get the first selected suggestion (only accept one per metabolite)
        selected_idx <- as.integer(selected[1])
        orig_suggestions <- suggestions[suggestions$original_name == orig_name, ]
        
        if (selected_idx <= nrow(orig_suggestions)) {
          selected_row <- orig_suggestions[selected_idx, ]
          
          # Find the row in id_results for this original name
          result_idx <- which(id_results$Compound_Name == orig_name)
          
          if (length(result_idx) > 0) {
            result_idx <- result_idx[1]
            
            # Update the IDs from the selected suggestion
            if ("KEGG_ID" %in% names(id_results) && selected_row$kegg_id != "") {
              id_results$KEGG_ID[result_idx] <- selected_row$kegg_id
              new_kegg_ids <- c(new_kegg_ids, selected_row$kegg_id)
            }
            if ("HMDB_ID" %in% names(id_results) && selected_row$hmdb_id != "") {
              id_results$HMDB_ID[result_idx] <- selected_row$hmdb_id
              new_hmdb_ids <- c(new_hmdb_ids, selected_row$hmdb_id)
            }
            if ("PubChem_CID" %in% names(id_results) && selected_row$pubchem_id != "") {
              id_results$PubChem_CID[result_idx] <- selected_row$pubchem_id
            }
            if ("ChEBI_ID" %in% names(id_results) && selected_row$chebi_id != "") {
              id_results$ChEBI_ID[result_idx] <- selected_row$chebi_id
            }
            
            applied_count <- applied_count + 1
            message(sprintf("[FUZZY] Applied suggestion: '%s' -> '%s'", orig_name, selected_row$suggested_name))
          }
        }
      }
    }
    
    # Update the main ID mapping results
    metab_values$id_mapping_results <- id_results
    
    # Update values$metabolomics_id_columns (used by exports and other parts of the app)
    if (!is.null(values$metabolomics_id_columns)) {
      # Rebuild id_columns from updated id_results (excluding Compound_Name column)
      id_col_names <- setdiff(names(id_results), "Compound_Name")
      values$metabolomics_id_columns <- id_results[, id_col_names, drop = FALSE]
      message(sprintf("[FUZZY] Updated values$metabolomics_id_columns with %d columns", length(id_col_names)))
    }
    
    # Update values$metabolomics_mapping for consistency
    if (!is.null(values$metabolomics_mapping)) {
      # Rebuild mapped_ids from updated id_results
      new_mapped_ids <- lapply(seq_len(nrow(id_results)), function(i) {
        list(
          kegg = if ("KEGG_ID" %in% names(id_results) && !is.na(id_results$KEGG_ID[i]) && id_results$KEGG_ID[i] != "") id_results$KEGG_ID[i] else NA_character_,
          pubchem = if ("PubChem_CID" %in% names(id_results) && !is.na(id_results$PubChem_CID[i]) && id_results$PubChem_CID[i] != "") id_results$PubChem_CID[i] else NA_character_,
          hmdb = if ("HMDB_ID" %in% names(id_results) && !is.na(id_results$HMDB_ID[i]) && id_results$HMDB_ID[i] != "") id_results$HMDB_ID[i] else NA_character_,
          chebi = if ("ChEBI_ID" %in% names(id_results) && !is.na(id_results$ChEBI_ID[i]) && id_results$ChEBI_ID[i] != "") id_results$ChEBI_ID[i] else NA_character_,
          lipidmaps = if ("LipidMaps_ID" %in% names(id_results) && !is.na(id_results$LipidMaps_ID[i]) && id_results$LipidMaps_ID[i] != "") id_results$LipidMaps_ID[i] else NA_character_
        )
      })
      values$metabolomics_mapping$mapped_ids <- new_mapped_ids
      message("[FUZZY] Updated values$metabolomics_mapping$mapped_ids")
    }
    
    # Re-fetch classification data if we have new HMDB IDs and classification was previously fetched
    if (length(new_hmdb_ids) > 0 && !is.null(metab_values$classification_data)) {
      message(sprintf("[FUZZY] Re-classifying metabolites with %d new HMDB IDs...", length(new_hmdb_ids)))
      
      tryCatch({
        molecule_names <- id_results$Compound_Name
        hmdb_ids <- if ("HMDB_ID" %in% names(id_results)) id_results$HMDB_ID else NULL
        
        classification_results <- classify_metabolites_cached(
          metabolite_names = molecule_names,
          hmdb_ids = hmdb_ids,
          use_online = TRUE
        )
        
        metab_values$classification_data <- classification_results
        message("[FUZZY] Classification data updated successfully")
      }, error = function(e) {
        message(sprintf("[FUZZY] Error updating classification: %s", e$message))
      })
    }
    
    # Re-fetch pathway data if we have new KEGG IDs and pathways were previously fetched
    if (length(new_kegg_ids) > 0 && !is.null(metab_values$pathway_data)) {
      message(sprintf("[FUZZY] Re-fetching pathways with %d new KEGG IDs...", length(new_kegg_ids)))
      
      tryCatch({
        kegg_ids <- if ("KEGG_ID" %in% names(id_results)) id_results$KEGG_ID else NULL
        
        pathway_results <- fetch_metabolite_pathways_cached(kegg_ids = kegg_ids)
        metab_values$pathway_data <- pathway_results
        
        if (!is.null(pathway_results) && nrow(pathway_results) > 0) {
          # Use the previously determined background size, or default to KEGG
          bg_size <- metab_values$enrichment_background_size %||% 6610
          
          metab_values$pathway_summary <- calculate_pathway_enrichment_cached(
            pathway_df = pathway_results,
            total_measured = nrow(id_results),
            background_size = bg_size,
            p_adjust_method = "BH"
          )
        }
        message("[FUZZY] Pathway data updated successfully")
      }, error = function(e) {
        message(sprintf("[FUZZY] Error updating pathways: %s", e$message))
      })
    }
    
    # Re-fetch module data if we have new KEGG IDs and modules were previously fetched
    if (length(new_kegg_ids) > 0 && !is.null(metab_values$module_data)) {
      message(sprintf("[FUZZY] Re-fetching modules with %d new KEGG IDs...", length(new_kegg_ids)))
      
      tryCatch({
        kegg_ids <- if ("KEGG_ID" %in% names(id_results)) id_results$KEGG_ID else NULL
        
        module_results <- fetch_metabolite_modules_cached(kegg_ids = kegg_ids)
        metab_values$module_data <- module_results
        
        if (!is.null(module_results) && nrow(module_results) > 0) {
          # Use the previously determined background size, or default to KEGG
          bg_size <- metab_values$enrichment_background_size %||% 6610
          
          metab_values$module_summary <- calculate_module_enrichment_cached(
            module_df = module_results,
            total_measured = nrow(id_results),
            background_size = bg_size,
            p_adjust_method = "BH"
          )
        }
        message("[FUZZY] Module data updated successfully")
      }, error = function(e) {
        message(sprintf("[FUZZY] Error updating modules: %s", e$message))
      })
    }
    
    # Re-fetch associations if we have new HMDB IDs and associations were previously fetched
    if (length(new_hmdb_ids) > 0 && !is.null(metab_values$associations_data)) {
      message(sprintf("[FUZZY] Re-fetching associations with %d new HMDB IDs...", length(new_hmdb_ids)))
      
      tryCatch({
        hmdb_ids <- if ("HMDB_ID" %in% names(id_results)) id_results$HMDB_ID else NULL
        molecule_names <- id_results$Compound_Name
        
        associations_results <- fetch_metabolite_associations_cached(
          hmdb_ids = hmdb_ids,
          metabolite_names = molecule_names
        )
        metab_values$associations_data <- associations_results
        message("[FUZZY] Associations data updated successfully")
      }, error = function(e) {
        message(sprintf("[FUZZY] Error updating associations: %s", e$message))
      })
    }
    
    # Clear fuzzy suggestions
    metab_values$fuzzy_suggestions <- NULL
    metab_values$fuzzy_pending_review <- FALSE
    
    removeModal()
    
    # Build detailed notification message
    update_details <- c()
    if (length(new_hmdb_ids) > 0 && !is.null(metab_values$classification_data)) {
      update_details <- c(update_details, "classification")
    }
    if (length(new_kegg_ids) > 0 && !is.null(metab_values$pathway_data)) {
      update_details <- c(update_details, "pathways")
    }
    if (length(new_kegg_ids) > 0 && !is.null(metab_values$module_data)) {
      update_details <- c(update_details, "modules")
    }
    if (length(new_hmdb_ids) > 0 && !is.null(metab_values$associations_data)) {
      update_details <- c(update_details, "associations")
    }
    
    if (length(update_details) > 0) {
      showNotification(
        sprintf("Applied %d fuzzy match(es). Updated: ID table, %s.", 
                applied_count, paste(update_details, collapse = ", ")),
        type = "message",
        duration = 8
      )
    } else {
      showNotification(
        sprintf("Applied %d fuzzy match suggestion(s). ID mapping table updated.", applied_count),
        type = "message",
        duration = 5
      )
    }
  })
  
  # Observer to skip all fuzzy matches
  observeEvent(input$fuzzy_skip_btn, {
    metab_values$fuzzy_suggestions <- NULL
    metab_values$fuzzy_pending_review <- FALSE
    removeModal()
    showNotification("Skipped all fuzzy match suggestions.", type = "message", duration = 3)
  })
  
  # Render background universe info for pathway enrichment
  output$metab_pathway_background_info <- renderUI({
    if (is.null(metab_values$pathway_summary) || nrow(metab_values$pathway_summary) == 0) {
      return(NULL)
    }
    
    # Get background size from stored value or attribute
    bg_size <- metab_values$enrichment_background_size %||% 
               attr(metab_values$pathway_summary, "analysis_params")$background_size %||% 
               6610
    
    # Determine source description
    metab_source <- input$metab_source %||% "processed"
    bg_choice <- if (metab_source != "manual") {
      input$metab_enrichment_background %||% "analyzed"
    } else {
      input$metab_manual_background_type %||% "kegg"
    }
    
    source_desc <- switch(bg_choice,
      "analyzed" = "All Analyzed Metabolites",
      "kegg" = "KEGG Pathway-Mapped Compounds",
      "custom" = "Custom Background",
      "KEGG Pathway-Mapped Compounds"
    )
    
    div(style = "padding: 8px 15px; background-color: #f8f9fa; border-bottom: 1px solid #e9ecef; font-size: 13px;",
        icon("info-circle", style = "color: #17a2b8; margin-right: 5px;"),
        span("Background Universe: ", style = "font-weight: 600;"),
        span(format(bg_size, big.mark = ","), " compounds"),
        span(paste0(" (", source_desc, ")"), style = "color: #6c757d;")
    )
  })
  
  # Render pathway table
  output$metab_pathway_table <- DT::renderDataTable({
    # Check which type to display
    pathway_type <- input$metab_pathway_type %||% "pathways"
    
    # Use module data if available and selected
    if (pathway_type == "modules") {
      if (!is.null(metab_values$module_summary) && nrow(metab_values$module_summary) > 0) {
        display_data <- metab_values$module_summary
        id_col_name <- "module_id"
        name_col_name <- "module_name"
        title_type <- "Module"
      } else {
        return(DT::datatable(data.frame(Message = "No module data available. Click 'Map Metabolite IDs' with 'Fetch Module Information' enabled.")))
      }
    } else if (is.null(metab_values$pathway_summary) || nrow(metab_values$pathway_summary) == 0) {
      return(DT::datatable(data.frame(Message = "No pathway data available. Click 'Map Metabolite IDs' with 'Fetch Pathway Information' enabled.")))
    } else {
      display_data <- metab_values$pathway_summary
      id_col_name <- "pathway_id"
      name_col_name <- "pathway_name"
      title_type <- "Pathway"
    }
    
    # Select and rename columns for display (enrichment analysis format)
    if ("enrichment_ratio" %in% names(display_data)) {
      # New enrichment format - select relevant columns
      # Handle both pathway_size and module_size column names
      size_col_name <- if (pathway_type == "modules") "module_size" else "pathway_size"
      display_cols <- c("rank", id_col_name, name_col_name, "hits", size_col_name, 
                       "expected", "enrichment_ratio", "p_value_display", "p_adjusted_display", 
                       "significant", "metabolites")
      display_cols <- display_cols[display_cols %in% names(display_data)]
      display_data <- display_data[, display_cols, drop = FALSE]
      
      # Rename columns for cleaner display
      col_rename <- c(
        "rank" = "Rank",
        "pathway_id" = paste(title_type, "ID"),
        "module_id" = paste(title_type, "ID"),
        "pathway_name" = paste(title_type, "Name"),
        "module_name" = paste(title_type, "Name"),
        "hits" = "Hits",
        "pathway_size" = paste(title_type, "Size"),
        "module_size" = paste(title_type, "Size"),
        "expected" = "Expected",
        "enrichment_ratio" = "Fold Enrichment",
        "p_value_display" = "P-value",
        "p_adjusted_display" = "Adj. P-value (BH)",
        "significant" = "Significant",
        "metabolites" = "Metabolites"
      )
      for (old_name in names(col_rename)) {
        if (old_name %in% names(display_data)) {
          names(display_data)[names(display_data) == old_name] <- col_rename[old_name]
        }
      }
      
      # Format significant column
      if ("Significant" %in% names(display_data)) {
        display_data$Significant <- ifelse(display_data$Significant, 
                                           "<span style='color:green;font-weight:bold;'>✓</span>", 
                                           "<span style='color:gray;'>✗</span>")
      }
    }
    
    # Add clickable links to ID column
    id_col_display <- if (pathway_type == "modules") "Module ID" else "Pathway ID"
    if (id_col_display %in% names(display_data)) {
      display_data[[id_col_display]] <- sapply(display_data[[id_col_display]], function(id) {
        if (!is.na(id) && id != "") {
          if (pathway_type == "modules") {
            paste0('<a href="https://www.genome.jp/dbget-bin/www_bget?', id, '" target="_blank">', id, '</a>')
          } else {
            paste0('<a href="https://www.genome.jp/dbget-bin/www_bget?', id, '" target="_blank">', id, '</a>')
          }
        } else {
          ""
        }
      })
    }
    
    # Add links to metabolite IDs in the metabolites column
    metab_col <- if ("Metabolites" %in% names(display_data)) "Metabolites" else "metabolites"
    if (metab_col %in% names(display_data)) {
      display_data[[metab_col]] <- sapply(display_data[[metab_col]], function(kegg_ids_str) {
        if (!is.na(kegg_ids_str) && kegg_ids_str != "") {
          ids <- strsplit(kegg_ids_str, ", ")[[1]]
          links <- sapply(ids, function(id) {
            id <- trimws(id)
            if (id != "") {
              paste0('<a href="https://www.genome.jp/entry/', id, '" target="_blank">', id, '</a>')
            } else {
              ""
            }
          })
          paste(links, collapse = ", ")
        } else {
          ""
        }
      })
    }
    
    DT::datatable(
      display_data,
      options = list(
        pageLength = 25,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(className = 'dt-center', targets = c(0, 3, 4, 5, 6))  # Center numeric columns
        )
      ),
      filter = 'top',
      rownames = FALSE,
      escape = FALSE
    )
  })
  
  # Render pathway/module plot
  output$metab_pathway_plot <- renderPlot({ 
    pathway_type <- input$metab_pathway_type %||% "pathways"
    
    # Use module data if available and selected
    if (pathway_type == "modules") {
      if (!is.null(metab_values$module_summary) && nrow(metab_values$module_summary) > 0) {
        plot_data <- head(metab_values$module_summary, min(15, nrow(metab_values$module_summary)))
        name_col <- "module_name"
        plot_title <- "KEGG Module Enrichment"
      } else {
        return(NULL)
      }
    } else {
      req(metab_values$pathway_summary)
      if (is.null(metab_values$pathway_summary) || nrow(metab_values$pathway_summary) == 0) return(NULL)
      plot_data <- head(metab_values$pathway_summary, min(15, nrow(metab_values$pathway_summary)))
      name_col <- "pathway_name"
      plot_title <- "KEGG Pathway Enrichment"
    }
    
    top_n <- nrow(plot_data)
    
    # Wrap long names for better readability
    plot_data$name_wrapped <- stringr::str_wrap(plot_data[[name_col]], width = 30)
    sort_choice <- input$metab_enrichment_sort %||% "enrichment"
    
    # Check if we have enrichment data (new format) or just counts (old format)
    has_enrichment <- "enrichment_ratio" %in% names(plot_data) && "p_adjusted" %in% names(plot_data)
    
    if (has_enrichment) {
      # New enrichment-aware plot: bar plot with fold enrichment colored by p-value significance
      # Color by -log10(adjusted p-value), height by fold enrichment
      plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))  # Cap at 1e-10 to avoid Inf
      
      # Sort data based on user selection
      if (sort_choice == "neg_log_p") {
        plot_data <- plot_data[order(plot_data$neg_log_p, decreasing = TRUE), , drop = FALSE]
        plot_data$sort_order <- seq_len(nrow(plot_data))
      } else {
        plot_data <- plot_data[order(plot_data$enrichment_ratio, decreasing = TRUE), , drop = FALSE]
        plot_data$sort_order <- seq_len(nrow(plot_data))
      }
      
      ggplot(plot_data, aes(x = reorder(name_wrapped, -sort_order), 
                            y = enrichment_ratio,
                            fill = neg_log_p)) +
        geom_col(color = "black", size = 0.3) +
        geom_hline(yintercept = 1, linetype = "dashed", color = "gray50", alpha = 0.7) +
        scale_fill_gradient(low = "#FFC107", high = "#DC3545", 
                            name = "-log10(Adj. P)") +
        coord_flip() +
        labs(
          title = plot_title,
          subtitle = sprintf("Top %d %s (sorted by %s)", top_n, 
                            tolower(ifelse(pathway_type == "modules", "modules", "pathways")),
                            ifelse(sort_choice == "neg_log_p", "-log10 P-value", "Fold Enrichment")),
          x = "",
          y = "Fold Enrichment"
        ) +
        theme_minimal() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 10, hjust = 0.5, color = "gray50"),
          axis.text.y = element_text(size = 9, lineheight = 1.2),
          legend.position = "right"
        )
    } else {
      # Fallback to old format (just counts), but color by -log adj p-value if available
      count_col <- if ("hits" %in% names(plot_data)) "hits" else "metabolite_count"
      
      # Check if we have p-values for coloring
      has_p_values <- "p_adjusted" %in% names(plot_data) && all(!is.na(plot_data$p_adjusted))
      
      if (has_p_values) {
        # Color by -log adj p-value in horizontal bar chart
        plot_data$neg_log_p <- -log10(pmax(plot_data$p_adjusted, 1e-10))
        
        # Sort data based on user selection
        if (sort_choice == "neg_log_p") {
          plot_data <- plot_data[order(plot_data$neg_log_p, decreasing = TRUE), , drop = FALSE]
        } else {
          plot_data <- plot_data[order(plot_data[[count_col]], decreasing = TRUE), , drop = FALSE]
        }
        plot_data$sort_order <- seq_len(nrow(plot_data))
        
        ggplot(plot_data, aes(x = reorder(name_wrapped, -sort_order), 
                              y = .data[[count_col]],
                              fill = neg_log_p)) +
          geom_col(color = "black", size = 0.3) +
          scale_fill_gradient(low = "#FFC107", high = "#DC3545", name = "-log10(Adj. P)") +
          coord_flip() +
          labs(
            title = paste("Top Metabolite", ifelse(pathway_type == "modules", "Modules", "Pathways")),
            subtitle = sprintf("Sorted by %s", ifelse(sort_choice == "neg_log_p", "-log10 P-value", "Count")),
            x = "",
            y = "Number of Metabolites"
          ) +
          theme_minimal() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 9, hjust = 0.5, color = "gray50"),
            axis.text.y = element_text(size = 9, lineheight = 1.2),
            legend.position = "right"
          )
      } else {
        # No p-values, use default coloring - still a bar chart format
        plot_data <- plot_data[order(plot_data[[count_col]], decreasing = TRUE), , drop = FALSE]
        ggplot(plot_data, aes(x = reorder(name_wrapped, .data[[count_col]]), y = .data[[count_col]])) +
          geom_col(fill = "#3498DB", color = "black", size = 0.3) +
          coord_flip() +
          labs(
            title = paste("Top Metabolite", ifelse(pathway_type == "modules", "Modules", "Pathways")),
            x = "",
            y = "Number of Metabolites"
          ) +
          theme_minimal() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            axis.text.y = element_text(size = 9, lineheight = 1.2)
          )
      }
    }
  })
  
  # Render associations table
  output$metab_associations_table <- DT::renderDataTable({
    # DEBUG: Log initial state
    message("[DEBUG-ASSOCIATIONS] Is null: ", is.null(metab_values$associations_data))
    
    if (is.null(metab_values$associations_data) || nrow(metab_values$associations_data) == 0) {
      message("[DEBUG-ASSOCIATIONS] No data available")
      return(DT::datatable(data.frame(
        Message = "No association data available. Metabolite associations require HMDB IDs. Click 'Map Metabolite IDs' with HMDB database selected."
      )))
    }
    
    # DEBUG: Log association data structure
    message("[DEBUG-ASSOCIATIONS] Class: ", paste(class(metab_values$associations_data), collapse=", "))
    message("[DEBUG-ASSOCIATIONS] Dimensions: ", nrow(metab_values$associations_data), " rows x ", ncol(metab_values$associations_data), " cols")
    message("[DEBUG-ASSOCIATIONS] Column names: ", paste(names(metab_values$associations_data), collapse=", "))
    if (nrow(metab_values$associations_data) > 0) {
      message("[DEBUG-ASSOCIATIONS] First row sample: ")
      for (col in names(metab_values$associations_data)) {
        val <- as.character(metab_values$associations_data[1, col])
        message("  ", col, ": '", substr(val, 1, 100), "'")
      }
    }
    
    display_data <- add_metabolite_links_to_dataframe(metab_values$associations_data)
    
    message("[DEBUG-ASSOCIATIONS] After add_metabolite_links - Column names: ", paste(names(display_data), collapse=", "))
    
    # Apply collapsible content to Disease column (max 200 characters preview)
    if ("Diseases" %in% names(display_data)) {
      display_data$Diseases <- sapply(display_data$Diseases, function(x) create_collapsible_content(x, max_chars = 200, id_prefix = "diseases"))
    }
    
    # Apply collapsible content to other large columns too
    if ("Biospecimens" %in% names(display_data)) {
      display_data$Biospecimens <- sapply(display_data$Biospecimens, function(x) create_collapsible_content(x, max_chars = 150, id_prefix = "biospec"))
    }
    if ("Tissues" %in% names(display_data)) {
      display_data$Tissues <- sapply(display_data$Tissues, function(x) create_collapsible_content(x, max_chars = 150, id_prefix = "tissues"))
    }
    if ("Genes" %in% names(display_data)) {
      display_data$Genes <- sapply(display_data$Genes, function(x) create_collapsible_content(x, max_chars = 150, id_prefix = "genes"))
    }
    if ("Proteins" %in% names(display_data)) {
      display_data$Proteins <- sapply(display_data$Proteins, function(x) create_collapsible_content(x, max_chars = 150, id_prefix = "proteins"))
    }
    
    DT::datatable(
      display_data,
      options = list(
        pageLength = 25,
        scrollX = TRUE,
        scrollY = "600px",
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(width = '150px', targets = 0),  # Metabolite
          list(width = '100px', targets = 1),  # HMDB_ID
          list(width = '200px', targets = 2:7) # Associations columns (including PMIDs)
        )
      ),
      filter = 'top',
      rownames = FALSE,
      escape = FALSE
    ) %>%
      DT::formatStyle(
        columns = c('Diseases', 'Biospecimens', 'Tissues', 'Genes', 'Proteins', 'PMIDs'),
        fontSize = '11px'
      )
  })
  
  # ============================================================================
  # METABOLOMICS COMPARISON ANALYSIS
  # ============================================================================
  
  # Update comparison dropdown when groups are available (same as enrichment tab)
  observe({
    req(values$unique_groups)
    
    # Generate all possible pairwise comparisons (same approach as enrichment tab)
    all_comparisons <- c()
    for (i in 1:(length(values$unique_groups) - 1)) {
      for (j in (i + 1):length(values$unique_groups)) {
        all_comparisons <- c(all_comparisons, paste(values$unique_groups[i], "vs", values$unique_groups[j]))
      }
    }
    
    if (length(all_comparisons) > 0) {
      updateSelectInput(session, "metab_comparison_select",
                       choices = c("Select a comparison..." = "", all_comparisons))
    } else {
      updateSelectInput(session, "metab_comparison_select",
                       choices = c("No comparisons available" = ""))
    }
  })
  
  # Reactive expression for filtered metabolomics results
  metab_filtered_data <- reactive({
    req(input$metab_comparison_select, input$metab_comparison_select != "")
    req(values$stat_results)
    
    comparison_name <- input$metab_comparison_select
    
    # Get the full statistical results (not pre-filtered)
    if (is.null(values$stat_results) || nrow(values$stat_results) == 0) {
      return(data.frame(Message = "No statistical results available"))
    }
    
    # Use the same helper functions as the enrichment tab
    p_value_column <- get_appropriate_pvalue_column(comparison_name)
    fc_column <- get_foldchange_column(comparison_name)
    
    # Check if columns exist
    if (is.null(p_value_column) || is.null(fc_column) ||
        !(p_value_column %in% colnames(values$stat_results))) {
      return(data.frame(Message = paste("Statistical columns not found for", comparison_name, 
                                        ". Please run statistical analysis first.")))
    }
    
    # Handle reversed fold change column
    fc_reversed <- FALSE
    if (!is.null(fc_column) && grepl("^REVERSED:", fc_column)) {
      fc_column <- sub("^REVERSED:", "", fc_column)
      fc_reversed <- TRUE
    }
    
    if (!(fc_column %in% colnames(values$stat_results))) {
      return(data.frame(Message = paste("Fold change column not found for", comparison_name)))
    }
    
    # Get values
    pvals <- values$stat_results[[p_value_column]]
    log2fc <- values$stat_results[[fc_column]]
    if (fc_reversed) log2fc <- -log2fc
    
    # Get FDR column for ROTS method (same logic as enrichment tab)
    fdr_values <- NULL
    fdr_column <- NULL
    if (input$sig_method == "rots" && !is.null(values$stat_results)) {
      comparison_parts <- strsplit(comparison_name, " vs ")[[1]]
      comparison_name_alt <- paste(rev(comparison_parts), collapse = " vs ")
      fdr_direct_name <- paste0(comparison_name, "_FDR")
      fdr_alt_name <- paste0(comparison_name_alt, "_FDR")
      
      if (fdr_direct_name %in% colnames(values$stat_results)) {
        fdr_column <- fdr_direct_name
      } else if (fdr_alt_name %in% colnames(values$stat_results)) {
        fdr_column <- fdr_alt_name
      }
      
      if (!is.null(fdr_column)) {
        fdr_values <- values$stat_results[[fdr_column]]
      }
    }
    
    # Get thresholds
    pval_threshold <- input$metab_pvalue_filter %||% 0.05
    log2fc_threshold <- input$metab_log2fc_filter %||% 1.0
    fdr_threshold <- input$metab_fdr_filter %||% 0.05
    
    # Apply filtering (same approach as enrichment tab)
    idx <- c()
    if (isTRUE(input$metab_include_up %||% TRUE)) {
      if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
        idx <- c(idx, which(
          !is.na(pvals) & !is.na(fdr_values) & !is.na(log2fc) &
            pvals <= pval_threshold &
            fdr_values <= fdr_threshold &
            log2fc >= log2fc_threshold
        ))
      } else {
        idx <- c(idx, which(
          !is.na(pvals) & !is.na(log2fc) &
            pvals <= pval_threshold &
            log2fc >= log2fc_threshold
        ))
      }
    }
    if (isTRUE(input$metab_include_down %||% TRUE)) {
      if (input$sig_method == "rots" && !is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
        idx <- c(idx, which(
          !is.na(pvals) & !is.na(fdr_values) & !is.na(log2fc) &
            pvals <= pval_threshold &
            fdr_values <= fdr_threshold &
            log2fc <= -log2fc_threshold
        ))
      } else {
        idx <- c(idx, which(
          !is.na(pvals) & !is.na(log2fc) &
            pvals <= pval_threshold &
            log2fc <= -log2fc_threshold
        ))
      }
    }
    idx <- unique(idx)
    
    if (length(idx) == 0) {
      return(data.frame(Message = paste("No metabolites meet the filter criteria:",
                                       "p-value <=", pval_threshold,
                                       "and |log2FC| >=", log2fc_threshold)))
    }
    
    # Extract filtered results
    filtered_results <- data.frame(
      molecule_name = values$cleaned_molecules[idx],
      pvalue = pvals[idx],
      log2fc = log2fc[idx],
      stringsAsFactors = FALSE
    )
    
    # Add FDR column if available
    if (!is.null(fdr_column) && fdr_column %in% colnames(values$stat_results)) {
      filtered_results$fdr <- fdr_values[idx]
    }
    
    # Add metabolite IDs to results
    if (nrow(filtered_results) > 0 && !is.null(values$metabolomics_id_columns)) {
      # Match molecule names and add ID information
      id_data <- values$metabolomics_id_columns
      
      # Merge with ID data
      filtered_results <- merge(filtered_results, id_data, 
                               by.x = "molecule_name", by.y = "row.names", 
                               all.x = TRUE, sort = FALSE)
    }
    
    # Sort by p-value
    filtered_results <- filtered_results[order(filtered_results$pvalue), ]
    
    filtered_results
  })
  
  # Update filtered count display
  output$metab_filtered_count <- renderText({
    data <- metab_filtered_data()
    
    if (nrow(data) == 0) {
      return("No metabolites match the selected filters")
    }
    
    paste("Showing", nrow(data), "differential metabolites")
  })
  
  # Render comparison results table
  output$metab_comparison_results <- DT::renderDataTable({
    data <- metab_filtered_data()
    
    if (is.null(data) || nrow(data) == 0) {
      return(DT::datatable(data.frame(Message = "Select a comparison and apply filters to view results")))
    }
    
    DT::datatable(
      data,
      options = list(
        pageLength = 25,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel'),
        columnDefs = list(
          list(visible = FALSE, targets = c())  # Hide row numbers
        )
      ),
      filter = 'top',
      rownames = FALSE,
      escape = FALSE
    )
  })
  
  # Volcano plot for comparison
  output$metab_volcano_plot <- renderPlot({ 
    data <- metab_filtered_data()
    
    if (is.null(data) || nrow(data) == 0) {
      return(ggplot() + theme_void() + 
             geom_text(aes(x = 0.5, y = 0.5, label = "No data to display"),
                      inherit.aes = FALSE, vjust = 0.5, hjust = 0.5, size = 5))
    }
    
    # Ensure we have the necessary columns
    if (!("log2fc" %in% colnames(data)) || !("pvalue" %in% colnames(data))) {
      return(ggplot() + theme_void() + 
             geom_text(aes(x = 0.5, y = 0.5, label = "Missing log2fc or pvalue column"),
                      inherit.aes = FALSE, vjust = 0.5, hjust = 0.5, size = 5))
    }
    
    # Determine significance
    data$significant <- data$pvalue <= input$metab_pvalue_filter & 
                       abs(data$log2fc) >= input$metab_log2fc_filter
    data$direction <- ifelse(data$log2fc > 0, "Upregulated", "Downregulated")
    
    ggplot(data, aes(x = log2fc, y = -log10(pvalue))) +
      geom_point(aes(color = direction, shape = significant), size = 3, alpha = 0.7) +
      scale_color_manual(values = c("Upregulated" = "#E74C3C", "Downregulated" = "#3498DB")) +
      scale_shape_manual(values = c("TRUE" = 19, "FALSE" = 1)) +
      geom_hline(yintercept = -log10(input$metab_pvalue_filter), linetype = "dashed", color = "gray50", alpha = 0.5) +
      geom_vline(xintercept = c(-input$metab_log2fc_filter, input$metab_log2fc_filter), linetype = "dashed", color = "gray50", alpha = 0.5) +
      labs(
        title = "Volcano Plot - Metabolite Significance",
        x = "Log2(Fold Change)",
        y = "-Log10(P-value)",
        color = "Direction",
        shape = "Significant"
      ) +
      theme_minimal() +
      theme(
        plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
        legend.position = "right"
      )
  })
  
  # Fold change vs significance plot
  output$metab_fc_significance_plot <- renderPlot({ 
    data <- metab_filtered_data()
    
    if (is.null(data) || nrow(data) == 0) {
      return(ggplot() + theme_void() + 
             geom_text(aes(x = 0.5, y = 0.5, label = "No data to display"),
                      inherit.aes = FALSE, vjust = 0.5, hjust = 0.5, size = 5))
    }
    
    # Ensure we have necessary columns
    if (!("log2fc" %in% colnames(data))) {
      return(ggplot() + theme_void() + 
             geom_text(aes(x = 0.5, y = 0.5, label = "Missing log2fc column"),
                      inherit.aes = FALSE, vjust = 0.5, hjust = 0.5, size = 5))
    }
    
    data$direction <- ifelse(data$log2fc > 0, "Up", "Down")
    
    ggplot(data, aes(x = direction, y = log2fc)) +
      geom_boxplot(aes(fill = direction), alpha = 0.6, outlier.shape = NA) +
      geom_jitter(width = 0.2, alpha = 0.5, size = 2) +
      scale_fill_manual(values = c("Up" = "#E74C3C", "Down" = "#3498DB")) +
      geom_hline(yintercept = 0, linetype = "dashed", color = "gray50", alpha = 0.7) +
      labs(
        title = "Fold Change Distribution",
        x = "Direction",
        y = "Log2(Fold Change)"
      ) +
      theme_minimal() +
      theme(
        plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
        legend.position = "none"
      )
  })
  
  # Download comparison results
  output$download_metab_comparison_results <- downloadHandler(
