                     tags$tr(tags$td(tags$strong("KEGG:")), tags$td(ifelse(is.na(row$KEGG_ID) || row$KEGG_ID == "", "Not found", row$KEGG_ID))),
                     tags$tr(tags$td(tags$strong("PubChem CID:")), tags$td(ifelse(is.na(row$PubChem_CID) || row$PubChem_CID == "", "Not found", row$PubChem_CID))),
                     tags$tr(tags$td(tags$strong("ChEBI:")), tags$td(ifelse(is.na(row$ChEBI_ID) || row$ChEBI_ID == "", "Not found", row$ChEBI_ID))),
                     tags$tr(tags$td(tags$strong("LipidMaps:")), tags$td(ifelse(is.na(row$LipidMaps_ID) || row$LipidMaps_ID == "", "Not found", row$LipidMaps_ID)))
          )
