  # Download handlers for metabolomics
  output$download_metab_plot <- downloadHandler(
    filename = function() {
      paste0("metabolomics_plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(metab_values$current_plot)
      
      # Check if we have multiple pie plots that need to be arranged
      if (!is.null(metab_values$use_multiple_pies) && isTRUE(metab_values$use_multiple_pies) &&
          !is.null(metab_values$pie_plots)) {
        # For multiple pie charts, arrange them with shared or per-pie legends
        n_plots <- length(metab_values$pie_plots)
        ncol_val <- min(2, n_plots)
        nrow_val <- ceiling(n_plots / ncol_val)

        plot_width <- input$metab_viz_plot_width
        legend_extra <- if (isTRUE(metab_values$pie_shared_legend)) 0.25 else 0
        plot_height <- input$metab_viz_plot_height * nrow_val + legend_extra

        if (requireNamespace("cowplot", quietly = TRUE)) {
          if (isTRUE(metab_values$pie_shared_legend) && !is.null(metab_values$shared_legend_plot)) {
            legend_grob <- cowplot::get_legend(metab_values$shared_legend_plot)
            pies_grid <- cowplot::plot_grid(
              plotlist = metab_values$pie_plots,
              ncol = ncol_val,
              nrow = nrow_val,
              align = "hv",
              axis = "tblr"
            )
            arranged_plot <- cowplot::plot_grid(
              pies_grid,
              legend_grob,
              ncol = 1,
              rel_heights = c(1, 0.25)
            )
          } else {
            arranged_plot <- cowplot::plot_grid(
              plotlist = metab_values$pie_plots,
              ncol = ncol_val,
              nrow = nrow_val,
              align = "hv",
              axis = "tblr"
            )
          }
          ggsave(file, plot = arranged_plot,
                 width = plot_width,
                 height = plot_height,
                 dpi = get_safe_global_dpi(),
                 device = resolve_ggsave_device(get_safe_global_image_format()))
        } else {
          arranged_plot <- gridExtra::arrangeGrob(grobs = metab_values$pie_plots, ncol = ncol_val)
          ggsave(file, plot = arranged_plot,
                 width = plot_width,
                 height = plot_height,
                 dpi = get_safe_global_dpi(),
                 device = resolve_ggsave_device(get_safe_global_image_format()))
        }
      } else {
        # For single plots, use the current_plot directly
        ggsave(file, plot = metab_values$current_plot,
               width = input$metab_viz_plot_width,
               height = input$metab_viz_plot_height,
               dpi = get_safe_global_dpi(),
               device = resolve_ggsave_device(get_safe_global_image_format()))
      }
    }
  )
  
