      type_name <- if (pathway_type == "modules") "modules" else "pathways"
      paste0("metabolite_", type_name, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      pathway_type <- input$metab_pathway_type %||% "pathways"
      sort_choice <- input$metab_enrichment_sort %||% "enrichment"
      
      if (pathway_type == "modules") {
        req(metab_values$module_summary)
        export_data <- metab_values$module_summary
      } else {
        req(metab_values$pathway_summary)
        export_data <- metab_values$pathway_summary
      }
      
      # Apply sort order based on user selection
      if (nrow(export_data) > 0) {
        has_enrichment <- "enrichment_ratio" %in% names(export_data) && "p_adjusted" %in% names(export_data)
        
        if (has_enrichment) {
          if (sort_choice == "neg_log_p") {
            export_data$neg_log_p <- -log10(pmax(export_data$p_adjusted, 1e-10))
            export_data <- export_data[order(export_data$neg_log_p, decreasing = TRUE), , drop = FALSE]
            export_data$neg_log_p <- NULL  # Remove temporary column
          } else {
            export_data <- export_data[order(export_data$enrichment_ratio, decreasing = TRUE), , drop = FALSE]
          }
        } else if ("p_adjusted" %in% names(export_data) && all(!is.na(export_data$p_adjusted))) {
          count_col <- if ("hits" %in% names(export_data)) "hits" else "metabolite_count"
          if (sort_choice == "neg_log_p") {
            export_data$neg_log_p <- -log10(pmax(export_data$p_adjusted, 1e-10))
            export_data <- export_data[order(export_data$neg_log_p, decreasing = TRUE), , drop = FALSE]
            export_data$neg_log_p <- NULL
          } else {
            export_data <- export_data[order(export_data[[count_col]], decreasing = TRUE), , drop = FALSE]
          }
        }
      }
      
      writexl::write_xlsx(export_data, file)
    }
  )
  
