  # Missing value imputation function
  perform_imputation <- function(data, method = "knn", params = list(), by_group = FALSE, group_info = NULL) {
    # Set seed prior to imputation for consistent result generation across multiple runs/filters
    set.seed(12345)
    
    # Create a copy of the data to modify
    imputed_data <- as.matrix(data)
    
    # Helper function for imputing a single data matrix
    impute_matrix <- function(mat, method, params) {
      if (method == "minprob") {
        # MinProb implementation: missing values are replaced with random draws from a
        # normal distribution with mean = shift*sd below the data mean and sd = scale*data_sd
        
        # Get parameters
        shift <- params$shift
        if (is.null(shift)) shift <- 1.8  # default is shift down by 1.8 SDs
        
        scale <- params$scale
        if (is.null(scale)) scale <- 0.3  # default is SD of 0.3 times the data SD
        
        # Calculate mean and standard deviation for each row
        row_means <- rowMeans(mat, na.rm = TRUE)
        row_sds <- apply(mat, 1, sd, na.rm = TRUE)
        
        # Replace NAs with random values from downshifted distribution
        for (i in 1:nrow(mat)) {
          na_indices <- which(is.na(mat[i, ]))
          
          # Skip rows with no missing values or all missing (would have NA sd)
          if (length(na_indices) == 0 || is.na(row_means[i]) || is.na(row_sds[i]) || row_sds[i] == 0) {
            next
          }
          
          # Calculate parameters for the imputation distribution
          mean_i <- row_means[i] - shift * row_sds[i]
          sd_i <- scale * row_sds[i]
          
          # Generate random values for imputation
          mat[i, na_indices] <- rnorm(length(na_indices), mean = mean_i, sd = sd_i)
        }
        
        return(mat)
      }
      else if (method == "knn") {
        # Try to load required library
        if (!requireNamespace("impute", quietly = TRUE)) {
          message("Installing impute package for k-nearest neighbors imputation...")
          if (!requireNamespace("BiocManager", quietly = TRUE)) {
            install.packages("BiocManager", quiet = TRUE)
          }
          BiocManager::install("impute", update = FALSE)
          if (!requireNamespace("impute", quietly = TRUE)) {
            warning("Failed to install impute package. Falling back to row means.")
            # Fall back to mean imputation if package installation fails
            for (i in 1:nrow(mat)) {
              na_indices <- which(is.na(mat[i, ]))
              if (length(na_indices) > 0) {
                mat[i, na_indices] <- mean(mat[i, -na_indices], na.rm = TRUE)
              }
            }
            return(mat)
          }
        }
        
        # Get parameters
        k <- params$k
        if (is.null(k)) k <- 10  # Default k value
        
        # Perform KNN imputation
        # Note: impute.knn works on transposed matrix (genes as columns)
        result <- tryCatch({
          knn_result <- impute::impute.knn(t(mat), k = k)
          # Result is transposed back to original orientation
          t(knn_result$data)
        }, error = function(e) {
          warning("Error in knn imputation: ", e$message, ". Falling back to row means.")
          # Fall back to mean imputation
          for (i in 1:nrow(mat)) {
            na_indices <- which(is.na(mat[i, ]))
            if (length(na_indices) > 0) {
              mat[i, na_indices] <- mean(mat[i, -na_indices], na.rm = TRUE)
            }
          }
          return(mat)
        })
        
        return(result)
      }
      else if (method == "min") {
        # Impute with minimum values
        fraction <- params$fraction
        if (is.null(fraction)) fraction <- 0.5  # Default fraction value
        
        # Impute with a fraction of the minimum non-NA value in each row
        for (i in 1:nrow(mat)) {
          na_indices <- which(is.na(mat[i, ]))
          if (length(na_indices) > 0) {
            non_na_values <- mat[i, -na_indices]
            if (length(non_na_values) > 0) {
              min_val <- min(non_na_values, na.rm = TRUE)
              mat[i, na_indices] <- min_val * fraction
            }
          }
        }
        return(mat)
      }
      else if (method == "mean") {
        # Impute with row means
        for (i in 1:nrow(mat)) {
          na_indices <- which(is.na(mat[i, ]))
          if (length(na_indices) > 0) {
            mat[i, na_indices] <- mean(mat[i, -na_indices], na.rm = TRUE)
          }
        }
        return(mat)
      }
      else if (method == "median") {
        # Impute with row medians
        for (i in 1:nrow(mat)) {
          na_indices <- which(is.na(mat[i, ]))
          if (length(na_indices) > 0) {
            mat[i, na_indices] <- median(mat[i, -na_indices], na.rm = TRUE)
          }
        }
        return(mat)
      }
      else if (method == "linear") {
        # Linear interpolation
        # This is most useful for time series, but can be applied to other ordered data
        # For each row, interpolate missing values
        for (i in 1:nrow(mat)) {
          # Create a vector of indices
          indices <- 1:ncol(mat)
          # Get the values and their positions
          y <- mat[i, ]
          x <- indices
          
          # If there are NAs and some non-NA values
          if (any(is.na(y)) && !all(is.na(y))) {
            # Use approx for linear interpolation
            interp <- stats::approx(x[!is.na(y)], y[!is.na(y)], xout = x[is.na(y)],
                                    rule = 2) # rule=2 uses nearest non-NA value for extrapolation
            mat[i, is.na(y)] <- interp$y
          }
        }
        return(mat)
      }
      else if (method == "mice") {
        # MICE (Multivariate Imputation by Chained Equations)
        if (!requireNamespace("mice", quietly = TRUE)) {
          message("Installing mice package for multivariate imputation...")
          install.packages("mice", quiet = TRUE)
          if (!requireNamespace("mice", quietly = TRUE)) {
            warning("Failed to install mice package. Falling back to row means.")
            # Fall back to mean imputation if package installation fails
            for (i in 1:nrow(mat)) {
              na_indices <- which(is.na(mat[i, ]))
              if (length(na_indices) > 0) {
                mat[i, na_indices] <- mean(mat[i, -na_indices], na.rm = TRUE)
              }
            }
            return(mat)
          }
        }
        
        # MICE works better on transposed matrix for omics data
        # (features as columns, samples as rows)
        t_mat <- t(mat)
        
        # Get parameters for mice
        m <- params$m  # number of imputations
        if (is.null(m)) m <- 5  # default number of imputations
        
        maxit <- params$maxit  # max iterations
        if (is.null(maxit)) maxit <- 5  # default max iterations
        
        # Run MICE imputation
        tryCatch({
          # Impute using predictive mean matching (PMM) method
          mice_result <- mice::mice(t_mat, m = m, maxit = maxit, method = "pmm", printFlag = FALSE)
          # Get the complete dataset (using the first imputation)
          completed <- mice::complete(mice_result, 1)
          # Transpose back to original orientation
          mat <<- t(completed)
        }, error = function(e) {
          warning("Error in MICE imputation: ", e$message, ". Falling back to row means.")
          # Fall back to mean imputation on the original matrix
          for (i in 1:nrow(mat)) {
            na_indices <- which(is.na(mat[i, ]))
            if (length(na_indices) > 0) {
              mat[i, na_indices] <- mean(mat[i, -na_indices], na.rm = TRUE)
            }
          }
          # Return the modified matrix from error handler
          mat <<- mat
        })
        
        return(mat)
      }
      else {
        # For unknown methods, return the original data
        return(mat)
      }
    }
    
    # Process by group or all at once
    if (by_group && !is.null(group_info)) {
      # Get unique groups
      groups <- unique(group_info)
      
      # Process each group separately
      for (grp in groups) {
        # Get columns for this group
        grp_cols <- which(group_info == grp)
        
        # Skip if no columns found
        if (length(grp_cols) == 0) next
        
        # Extract submatrix for this group
        grp_data <- imputed_data[, grp_cols, drop = FALSE]
        
        # Impute this group's data
        imputed_data[, grp_cols] <- impute_matrix(grp_data, method, params)
      }
    } else {
      # Process all data at once
      imputed_data <- impute_matrix(imputed_data, method, params)
    }
    
    return(as.data.frame(imputed_data))
  }
  
  # Display missing value summary
  output$missingValueSummary <- renderPrint({
    req(values$original_unfiltered_data)
    
    # Use original unfiltered data for missing value analysis
    data <- values$original_unfiltered_data[, -1]  # Exclude first column (feature names)
    total_cells <- prod(dim(data))
    missing_cells <- sum(is.na(data))
    missing_pct <- missing_cells / total_cells * 100
    
    cat("Raw Dataset (before filtering):\n")
    cat("Features:", nrow(data), "\n")
    cat("Samples:", ncol(data), "\n")
    cat("Total cells:", total_cells, "\n")
    cat("Missing cells:", missing_cells, "(", round(missing_pct, 2), "%)\n\n")
    
    # Show filtered dataset info if filtering was applied
    if (!is.null(values$raw_data)) {
      filtered_data <- values$raw_data[, -1]  # Exclude first column (feature names)
      filtered_total_cells <- prod(dim(filtered_data))
      filtered_missing_cells <- sum(is.na(filtered_data))
      filtered_missing_pct <- filtered_missing_cells / filtered_total_cells * 100
      
      cat("Filtered Dataset (after preprocessing):\n")
      cat("Features:", nrow(filtered_data), "\n")
      cat("Samples:", ncol(filtered_data), "\n")
      cat("Total cells:", filtered_total_cells, "\n")
      cat("Missing cells:", filtered_missing_cells, "(", round(filtered_missing_pct, 2), "%)\n\n")
    }
    
    if (!is.null(values$removed_features)) {
      cat("Features removed:", length(values$removed_features), "\n")
      cat("Removal criteria:", values$removal_reason, "\n\n")
    }
  })
  
