    if (values$imputation_stats$missing_before > 0) {
      imputation_percentage <- round(values$imputation_stats$imputed_count / values$imputation_stats$missing_before * 100, 2)
      cat("Imputation rate:", imputation_percentage, "% of missing values in filtered data\n")
    }
    
    # Add group-wise imputation info
    cat("Perform imputation within groups:", values$imputation_by_group, "\n")
    
    # Add method-specific parameters
    if (values$imputation_stats$method == "knn") {
      cat("KNN parameters:\n")
      cat("  k:", values$imputation_stats$params$k, "\n")
    } else if (values$imputation_stats$method == "min") {
      cat("Minimum value parameters:\n")
