  # Generate imputation comparison plot when requested
  observeEvent(input$show_imputation_comparison, {
    req(values$data_after_imputation, values$data_before_imputation,
        input$impute_comparison_feature)
    
    # Validate that imputation was actually performed
    if(!isTruthy(values$imputation_applied) || input$missing_value_strategy != "impute") {
      showNotification("No imputation data available. Please run data processing with imputation first.",
                       type = "warning")
      return()
    }
    
    # Get feature index
    feature_idx <- which(values$cleaned_molecules == input$impute_comparison_feature)
    
    if(length(feature_idx) == 0) {
      showNotification("Selected feature not found", type = "error")
      return()
    }
    
    # Extract data for the feature (ensure we get vectors with proper names)
    before_data <- as.numeric(values$data_before_imputation[feature_idx, ])
    after_data <- as.numeric(values$data_after_imputation[feature_idx, ])
    
    # Get sample names
    sample_names <- colnames(values$data_before_imputation)
    names(before_data) <- sample_names
    names(after_data) <- sample_names
    
    # Identify which values were originally missing (these were imputed)
    was_missing <- is.na(before_data)
    
    # Check if there were any missing values to impute for this feature
    if(sum(was_missing) == 0) {
      showNotification(paste("No missing values were found for feature",
                             input$impute_comparison_feature,
                             "- no imputation comparison available"),
                       type = "message")
      return()
    }
    
    # Create data frame for plotting - only include non-missing values for "Before" and all values for "After"
    plot_df <- data.frame(
      Value = c(as.numeric(before_data[!was_missing]), as.numeric(after_data)),
      Type = factor(c(rep("Before Imputation", sum(!was_missing)),
                      rep("After Imputation", length(after_data))),
                    levels = c("Before Imputation", "After Imputation")),
      Sample = c(names(before_data)[!was_missing], names(after_data)),
      Imputed = c(rep(FALSE, sum(!was_missing)), was_missing),
      stringsAsFactors = FALSE
    )
    
    # Debug information
    cat("=== IMPUTATION COMPARISON DEBUG ===\n")
    cat("Debug: Before data length:", length(before_data), "\n")
    cat("Debug: After data length:", length(after_data), "\n")
    cat("Debug: Missing values count:", sum(was_missing), "\n")
    cat("Debug: Before data range:", range(before_data, na.rm = TRUE), "\n")
    cat("Debug: After data range:", range(after_data, na.rm = TRUE), "\n")
    cat("Debug: Before data sample values:", head(before_data, 10), "\n")
    cat("Debug: After data sample values:", head(after_data, 10), "\n")
    cat("Debug: After data unique values count:", length(unique(after_data)), "\n")
    cat("Debug: Plot data frame rows:", nrow(plot_df), "\n")
    cat("Debug: Plot data value range:", range(plot_df$Value, na.rm = TRUE), "\n")
    cat("=======================================\n")
    
    # Create the imputation comparison plot based on selected view type
    output$imputationComparisonPlot <- renderPlot({ 
      p <- switch(input$impute_comparison_view,
                  "boxplot" = {
                    ggplot(plot_df, aes(x = Type, y = Value, fill = Type)) +
                      geom_boxplot(alpha = 0.7) +
                      ggbeeswarm::geom_beeswarm(alpha = 0.6, size = 2) +
                      theme_minimal(base_size = 14) +
                      labs(title = paste("Imputation Comparison for", input$impute_comparison_feature),
                           x = "", y = "Value") +
                      theme (legend.title = element_blank()) +
                      scale_fill_manual(values = c("Before Imputation" = "#3498db",
                                                   "After Imputation" = "#e74c3c"))
                  },
                  "histogram" = {
                    ggplot(plot_df, aes(x = Value, fill = Type)) +
                      geom_histogram(alpha = 0.7, position = "identity", bins = 30) +
                      theme_minimal(base_size = 14) +
                      labs(title = paste("Imputation Comparison for", input$impute_comparison_feature),
                           x = "Value", y = "Count") +
                      theme (legend.title = element_blank()) +
                      scale_fill_manual(values = c("Before Imputation" = "#3498db",
                                                   "After Imputation" = "#e74c3c"))
                  },
                  "density" = {
                    ggplot(plot_df, aes(x = Value, fill = Type)) +
                      geom_density(alpha = 0.5) +
                      theme_minimal(base_size = 14) +
                      labs(title = paste("Imputation Comparison for", input$impute_comparison_feature),
                           x = "Value", y = "Density") +
                      theme (legend.title = element_blank()) +
                      scale_fill_manual(values = c("Before Imputation" = "#3498db",
                                                   "After Imputation" = "#e74c3c"))
                  }, res = UI_PLOT_RES
      )
      
      # Add points showing imputed values for boxplot
      if(input$impute_comparison_view == "boxplot") {
        # Highlight imputed values in the "After Imputation" group
        imputed_data <- subset(plot_df, Type == "After Imputation" & Imputed == TRUE)
        if(nrow(imputed_data) > 0) {
          p <- p + geom_point(data = imputed_data,
                              aes(y = Value), x = 2,
                              color = "#e74c3c", size = 3, alpha = 0.8) +
            labs(caption = paste("Red points show", nrow(imputed_data), "imputed values"))
        }
      }
      
      return(p)
    }, res = UI_PLOT_RES)
    
    # Make imputation comparison plot available even when the UI is not visible
    outputOptions(output, "imputationComparisonPlot", suspendWhenHidden = FALSE)
  })
  
