    if (input$glyco_analysis_type == "structure") {
      # Structural Features: only Bar Chart
      selectInput("glyco_plot_type", "Plot Type:",
                  choices = c(
                    "Bar Chart" = "bar"
                  ),
                  selected = "bar",
                  width = "100%")
    } else {
      # Other analysis types: all plot options
      selectInput("glyco_plot_type", "Plot Type:",
                  choices = c(
                    "Pie Chart" = "pie",
                    "Bar Chart" = "bar",
                    "Radar Chart" = "radar",
                    "Heatmap" = "heatmap"
                  ),
                  selected = "pie",
                  width = "100%")
    }
  })
  
  # Observer to validate radar chart requests based on available data
  observeEvent(input$glyco_plot_type, {
    req(input$glyco_plot_type, input$glyco_analysis_type)
    # Only check when radar is selected
    if (input$glyco_plot_type == "radar" ||
        (!is.null(input$glyco_plot_type_group_comp) && input$glyco_analysis_type == "group_comparison" && input$glyco_plot_type_group_comp == "radar")) {
      
      # Check how many categories/variables we have
      n_vars <- 0
      
      if (input$glyco_analysis_type == "distribution" && !is.null(glyco_values$parsed_glycans)) {
        # For glycan type distribution
        glycan_types <- sapply(glyco_values$parsed_glycans, function(g) g$type)
        n_vars <- length(unique(glycan_types))
      } else if (input$glyco_analysis_type == "monosaccharide" && !is.null(glyco_values$monosaccharide_data)) {
        # For monosaccharide analysis
        n_vars <- nrow(glyco_values$monosaccharide_data)
      } else if (input$glyco_analysis_type == "structure" && !is.null(glyco_values$classification_data)) {
        # Structure analysis - check each category
        branching_data <- table(sapply(glyco_values$classification_data, function(x) x$branching))
        sialylation_data <- table(sapply(glyco_values$classification_data, function(x) x$sialylation))
        fucosylation_data <- table(sapply(glyco_values$classification_data, function(x) x$fucosylation))
        
        # Check minimum count
        n_vars <- min(length(branching_data), length(sialylation_data), length(fucosylation_data))
      }
      
      # Show warning if too few variables
      if (n_vars < 3) {
        showNotification(
          paste("Radar charts require at least 3 variables, but only", n_vars,
                "found. Please select a different plot type."),
          type = "warning",
          duration = 8
        )
        
        # Switch to a different plot type automatically to prevent crash
        if(input$glyco_analysis_type == "group_comparison") {
          updateSelectInput(session, "glyco_plot_type_group_comp", selected = "bar")
        } else {
          updateSelectInput(session, "glyco_plot_type", selected = "bar")
        }
      }
    }
  })
  
  output$glyco_radar_type_ui <- renderUI({
    req(input$glyco_analysis_type == "structure", input$glyco_plot_type == "radar")
    selectInput(
      "glyco_radar_type",
      "Radar Chart Category:",
      choices = c("Branching", "Sialylation", "Fucosylation"),
      selected = "Branching"
    )
  })
  
  # --- ML Feature Selection Server Logic ---
  # Update target variable choices based on available groups and binary mode
  observe({
    req(values$unique_groups, length(values$unique_groups) > 0)
    
    method <- input$feature_selection_method %||% ""
    # Additional safety check to ensure method is not NULL or empty
    if (is.null(method) || nchar(method) == 0) return()
    
    # Check if binary mode is active for any method
    is_lasso_binary <- method == "lasso" &&
      !is.null(input$glmnet_family) &&
      input$glmnet_family == "binomial" &&
      !is.null(input$mlfsGroup1) &&
      !is.null(input$mlfsGroup2) &&
      input$mlfsGroup1 != input$mlfsGroup2
    
    is_rf_binary <- method == "rf" &&
      !is.null(input$rf_family) &&
      input$rf_family == "binary" &&
      !is.null(input$rfGroup1) &&
      !is.null(input$rfGroup2) &&
      input$rfGroup1 != input$rfGroup2
    
    is_perm_binary <- method == "permutation" &&
      !is.null(input$perm_family) &&
      input$perm_family == "binary" &&
      !is.null(input$permGroup1) &&
      !is.null(input$permGroup2) &&
      input$permGroup1 != input$permGroup2
    
    is_rfe_binary <- method == "rfe" &&
      !is.null(input$rfe_problem_type) &&
      input$rfe_problem_type == "binary" &&
      !is.null(input$rfe_group_1) &&
      !is.null(input$rfe_group_2) &&
      input$rfe_group_1 != input$rfe_group_2
    
    is_boruta_binary <- method == "boruta" &&
      !is.null(input$boruta_problem_type) &&
      input$boruta_problem_type == "binary" &&
      !is.null(input$boruta_group_1) &&
      !is.null(input$boruta_group_2) &&
      input$boruta_group_1 != input$boruta_group_2
    
    # Create choices based on mode
    if (is_lasso_binary) {
      # Only show the two selected groups + All Groups option
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS",
                   setNames(input$mlfsGroup1, input$mlfsGroup1),
                   setNames(input$mlfsGroup2, input$mlfsGroup2))
      cat("LASSO Binary mode: Limiting target variable to selected groups:", input$mlfsGroup1, "and", input$mlfsGroup2, "\n")
    } else if (is_rf_binary) {
      # Only show the two selected groups + All Groups option
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS",
                   setNames(input$rfGroup1, input$rfGroup1),
                   setNames(input$rfGroup2, input$rfGroup2))
      cat("RF Binary mode: Limiting target variable to selected groups:", input$rfGroup1, "and", input$rfGroup2, "\n")
    } else if (is_perm_binary) {
      # Only show the two selected groups + All Groups option
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS",
                   setNames(input$permGroup1, input$permGroup1),
                   setNames(input$permGroup2, input$permGroup2))
      cat("Permutation Binary mode: Limiting target variable to selected groups:", input$permGroup1, "and", input$permGroup2, "\n")
    } else if (is_rfe_binary) {
      # Only show the two selected groups + All Groups option
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS",
                   setNames(input$rfe_group_1, input$rfe_group_1),
                   setNames(input$rfe_group_2, input$rfe_group_2))
      cat("RFE Binary mode: Limiting target variable to selected groups:", input$rfe_group_1, "and", input$rfe_group_2, "\n")
    } else if (is_boruta_binary) {
      # Only show the two selected groups + All Groups option
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS",
                   setNames(input$boruta_group_1, input$boruta_group_1),
                   setNames(input$boruta_group_2, input$boruta_group_2))
      cat("Boruta Binary mode: Limiting target variable to selected groups:", input$boruta_group_1, "and", input$boruta_group_2, "\n")
    } else {
      # Show all groups
      choices <- c("All Groups (Multi-class)" = "ALL_GROUPS")
      choices <- c(choices, setNames(values$unique_groups, values$unique_groups))
    }
    
    updateSelectInput(session, "feature_selection_target",
                      choices = choices,
                      selected = "ALL_GROUPS")
  })
  
  # Reactive data for MLFS filtering based on binary or multiclass selection
  mlfs_filtered_data <- reactive({
    req(values$normalized_data, values$cleaned_molecules, input$feature_selection_target,
        length(values$normalized_data) > 0, length(values$cleaned_molecules) > 0)
    
    # Check if binary classification with specific group selection for LASSO
    is_lasso_binary_with_groups <- input$feature_selection_method == "lasso" &&
      !is.null(input$glmnet_family) &&
      input$glmnet_family == "binomial" &&
      !is.null(input$mlfsGroup1) &&
      !is.null(input$mlfsGroup2) &&
      input$mlfsGroup1 != input$mlfsGroup2
    
    # Check if binary classification with specific group selection for RF
    is_rf_binary_with_groups <- input$feature_selection_method == "rf" &&
      !is.null(input$rf_family) &&
      input$rf_family == "binary" &&
      !is.null(input$rfGroup1) &&
      !is.null(input$rfGroup2) &&
      input$rfGroup1 != input$rfGroup2
    
    # Check if binary classification with specific group selection for Permutation
    is_perm_binary_with_groups <- input$feature_selection_method == "permutation" &&
      !is.null(input$perm_family) &&
      input$perm_family == "binary" &&
      !is.null(input$permGroup1) &&
      !is.null(input$permGroup2) &&
      input$permGroup1 != input$permGroup2
    
    if (is_lasso_binary_with_groups) {
      # LASSO Binary classification: use selected Group1 vs Group2
      group1_idx <- which(values$unique_groups == input$mlfsGroup1)
      group2_idx <- which(values$unique_groups == input$mlfsGroup2)
      cols1 <- values$group_column_indices[[group1_idx]]
      cols2 <- values$group_column_indices[[group2_idx]]
      selected_cols <- c(cols1, cols2)
      data <- values$normalized_data[, selected_cols, drop = FALSE]
      labels <- c(rep(input$mlfsGroup1, length(cols1)), rep(input$mlfsGroup2, length(cols2)))
      list(data = data, labels = labels)
      
    } else if (is_rf_binary_with_groups) {
      # RF Binary classification: use selected Group1 vs Group2
      group1_idx <- which(values$unique_groups == input$rfGroup1)
      group2_idx <- which(values$unique_groups == input$rfGroup2)
      cols1 <- values$group_column_indices[[group1_idx]]
      cols2 <- values$group_column_indices[[group2_idx]]
      selected_cols <- c(cols1, cols2)
      data <- values$normalized_data[, selected_cols, drop = FALSE]
      labels <- c(rep(input$rfGroup1, length(cols1)), rep(input$rfGroup2, length(cols2)))
      list(data = data, labels = labels)
      
    } else if (is_perm_binary_with_groups) {
      # Permutation Binary classification: use selected Group1 vs Group2
      group1_idx <- which(values$unique_groups == input$permGroup1)
      group2_idx <- which(values$unique_groups == input$permGroup2)
      cols1 <- values$group_column_indices[[group1_idx]]
      cols2 <- values$group_column_indices[[group2_idx]]
      selected_cols <- c(cols1, cols2)
      data <- values$normalized_data[, selected_cols, drop = FALSE]
      labels <- c(rep(input$permGroup1, length(cols1)), rep(input$permGroup2, length(cols2)))
      list(data = data, labels = labels)
      
    } else {
      # Multi-class or target-based classification
      target_var <- input$feature_selection_target
      group_names <- values$unique_groups
      
      if (is.null(target_var) || target_var == "" || target_var == "ALL_GROUPS") {
        # Determine optional subset for multi-class processing
        selected_multi_groups <- NULL
        current_method <- input$feature_selection_method %||% ""
        if (current_method == "lasso" && !is.null(input$glmnet_family) &&
            input$glmnet_family %in% c("multinomial", "grouped_multinomial") &&
            !is.null(input$lasso_groups_multi) && length(input$lasso_groups_multi) >= 2) {
          selected_multi_groups <- intersect(input$lasso_groups_multi, group_names)
        } else if (current_method == "rf" && identical(input$rf_family, "multiclass") &&
                   !is.null(input$rf_groups_multi) && length(input$rf_groups_multi) >= 2) {
          selected_multi_groups <- intersect(input$rf_groups_multi, group_names)
        } else if (current_method == "permutation" && identical(input$perm_family, "multiclass") &&
                   !is.null(input$perm_groups_multi) && length(input$perm_groups_multi) >= 2) {
          selected_multi_groups <- intersect(input$perm_groups_multi, group_names)
        }
        
        groups_to_use <- if (!is.null(selected_multi_groups) && length(selected_multi_groups) >= 2) selected_multi_groups else group_names
        
        selected_cols <- integer(0)
        labels <- character(0)
        for (i in seq_along(group_names)) {
          grp <- group_names[i]
          if (!grp %in% groups_to_use) next
          group_cols <- values$group_column_indices[[i]]
          if (length(group_cols) == 0) next
          selected_cols <- c(selected_cols, group_cols)
          labels <- c(labels, rep(grp, length(group_cols)))
        }
        
        if (length(selected_cols) == 0) {
          showNotification("No samples available for the selected groups. Please adjust your group selection.", type = "error", duration = 8)
          return(NULL)
        }
        
        data <- values$normalized_data[, selected_cols, drop = FALSE]
        list(data = data, labels = labels)
      } else {
        # Target variable approach: Target vs All Others
        data <- values$normalized_data
        labels <- character(ncol(data))
        target_idx <- which(group_names == target_var)
        
        if (length(target_idx) > 0) {
          for (i in seq_along(group_names)) {
            group_cols <- values$group_column_indices[[i]]
            if (length(group_cols) == 0) next
            if (i == target_idx) {
              labels[group_cols] <- target_var
            } else {
              labels[group_cols] <- "Other"
            }
          }
        } else {
          for (i in seq_along(group_names)) {
            group_cols <- values$group_column_indices[[i]]
            if (length(group_cols) == 0) next
            labels[group_cols] <- group_names[i]
          }
        }
        
        list(data = data, labels = labels)
      }
    }
  })
  
  # Update RFE group selection choices when groups become available
  observe({
    req(values$unique_groups, length(values$unique_groups) > 0)
    # Update binary group choices
    updateSelectizeInput(session, "rfe_group_1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "rfe_group_2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    # Update multiclass group choices
    updateSelectizeInput(session, "rfe_groups_multi", choices = values$unique_groups)
  })
  
  # Update Boruta group choices when groups change
  observe({
    req(values$unique_groups, length(values$unique_groups) > 0)
    # Update binary group choices
    updateSelectizeInput(session, "boruta_group_1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "boruta_group_2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    # Update multiclass group choices
    updateSelectizeInput(session, "boruta_groups_multi", choices = values$unique_groups)
  })
  
  # Auto-manage target variable when multi-class problem types are active
  observe({
    req(input$feature_selection_method)  # Ensure method selector is initialized
    method <- input$feature_selection_method %||% ""
    # Return early if method is NULL or empty to avoid errors
    if (is.null(method) || nchar(method) == 0) return()
    disable_target <- FALSE
    
    if (method == "lasso") {
      disable_target <- !is.null(input$glmnet_family) && input$glmnet_family %in% c("multinomial", "grouped_multinomial")
    } else if (method == "rf") {
      disable_target <- identical(input$rf_family, "multiclass")
    } else if (method == "permutation") {
      disable_target <- identical(input$perm_family, "multiclass")
    } else if (method == "rfe") {
      disable_target <- identical(input$rfe_problem_type, "multiclass")
    } else if (method == "boruta") {
      disable_target <- identical(input$boruta_problem_type, "multiclass")
    }
    
    if (disable_target) {
      if (!identical(input$feature_selection_target, "ALL_GROUPS")) {
        updateSelectInput(session, "feature_selection_target", selected = "ALL_GROUPS")
      }
      shinyjs::disable("feature_selection_target")
    } else {
      shinyjs::enable("feature_selection_target")
    }
  })
  
  # Dynamically filter base models by problem type
  observe({
    req(input$rfe_problem_type, nchar(input$rfe_problem_type) > 0)
    # Simplified: Only Random Forest available for all problem types
    base_rf_only <- c("Random Forest" = "rf")
    current <- isolate(input$rfe_base_model)
    # Check if current is valid before comparing
    if (is.null(current) || nchar(current) == 0 || current != "rf") {
      updateSelectInput(session, "rfe_base_model", choices = base_rf_only, selected = "rf")
      if (!is.null(current) && nchar(current) > 0 && current != "rf") {
        showNotification("RFE: Only Random Forest is available for stable operation", type = "message", duration = 4)
      }
    } else {
      updateSelectInput(session, "rfe_base_model", choices = base_rf_only, selected = current)
    }
  })
  
  # Auto-correct duplicate group selection in binary RFE
  observe({
    req(input$rfe_problem_type == "binary", values$unique_groups, length(values$unique_groups) > 1)
    g1 <- input$rfe_group_1; g2 <- input$rfe_group_2
    groups <- values$unique_groups
    if (!is.null(g1) && !is.null(g2) && nchar(g1) > 0 && nchar(g2) > 0 && g1 == g2 && length(groups) > 1) {
      # Pick an alternative group (first different)
      alt <- groups[groups != g1][1]
      if (!is.na(alt)) {
        updateSelectizeInput(session, "rfe_group_2", selected = alt)
      }
    }
  })
  
  # Main feature selection logic
  observeEvent(input$run_feature_selection, {
    req(values$normalized_data, values$cleaned_molecules, input$feature_selection_method)
    
    # ============================================================================
    # CLEAR/RESET PREVIOUS ML FEATURE SELECTION RESULTS
    # ============================================================================
    # This ensures that when a new ML feature selection is run, all previous results
    # are cleared to avoid confusion in the results tabs
    
    # Clear core ML results
    values$ml_selected_features <- NULL
    values$ml_importance <- NULL
    values$ml_performance <- NULL
    values$ml_feature_names <- NULL
    values$ml_coefficients_by_class <- NULL
    values$ml_method_used <- NULL
    values$ml_classifier_used <- NULL
    
    # Clear LASSO/GLMNet specific results
    values$ml_glmnet_fit <- NULL
    values$ml_cv_fit <- NULL
    values$ml_lambda_best <- NULL
    values$ml_glmnet_family <- NULL
    values$ml_glmnet_alpha <- NULL
    values$ml_X_matrix <- NULL
    
    # Clear Random Forest specific results
    values$ml_rf_fit <- NULL
    values$ml_rf_X <- NULL
    values$ml_rf_y <- NULL
    values$ml_rf_importance_full <- NULL
    values$ml_rf_type <- NULL
    values$ml_rf_proximity <- NULL
    values$ml_rf_local_importance <- NULL
    values$ml_rf_var_used <- NULL
    values$ml_rf_tree_sizes <- NULL
    values$ml_rf_stability_scores <- NULL
    values$ml_rf_stability_features <- NULL
    values$ml_rf_stability_method <- NULL
    
    # Clear Boruta specific results
    values$boruta_object <- NULL
    values$boruta_stats <- NULL
    values$boruta_plot_data <- NULL
    values$boruta_importance_source_used <- NULL
    
    # Clear RFE specific results (if any additional ones exist)
    values$ml_rfe_fit <- NULL
    values$ml_rfe_results <- NULL
    
    # Clear Permutation Importance specific results (if any additional ones exist)
    values$ml_permutation_results <- NULL
    
    # Reset UI elements that depend on ML results
    updateSelectInput(session, "coef_class_focus", choices = character(0), selected = NULL)
    
    # Helper to replace numeric IDs with feature names in a data.frame column
    map_numeric_ids_to_names <- function(df, col_candidates = c("Feature","Variable","Name")) {
      if (is.null(df) || !is.data.frame(df)) return(df)
      target_col <- intersect(col_candidates, colnames(df))[1]
      if (is.null(target_col)) return(df)
      vec <- df[[target_col]]
      # Detect all numeric or coercible to integer or pattern like ^[0-9]+$
      if (is.numeric(vec) || all(grepl("^[0-9]+$", as.character(vec)))) {
        idx <- suppressWarnings(as.integer(as.character(vec)))
        if (all(!is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
          df[[target_col]] <- values$cleaned_molecules[idx]
        }
      }
      df
    }
    
    # Validate target variable alignment with group selections for binary comparison
    is_binary_with_groups <- input$feature_selection_method == "lasso" &&
      !is.null(input$glmnet_family) &&
      input$glmnet_family == "binomial" &&
      !is.null(input$mlfsGroup1) &&
      !is.null(input$mlfsGroup2) &&
      input$mlfsGroup1 != input$mlfsGroup2
    
    if (is_binary_with_groups) {
      target_var <- input$feature_selection_target
      selected_groups <- c(input$mlfsGroup1, input$mlfsGroup2)
      
      # Check if target variable is compatible with selected groups
      if (!is.null(target_var) && target_var != "ALL_GROUPS" && target_var != "") {
        if (!target_var %in% selected_groups) {
          error_msg <- paste0("Target Variable Mismatch: You selected '", target_var,
                              "' as your target variable, but your binary comparison is between '",
                              input$mlfsGroup1, "' and '", input$mlfsGroup2, "'. ",
                              "Please either:\n",
                              "  Select 'All Groups (Multi-class)' as your target variable, OR\n",
                              "  Choose a target variable that matches one of your selected groups ('",
                              paste(selected_groups, collapse = "' or '"), "')")
          showNotification(error_msg, type = "error", duration = 10)
          return()
        }
      }
    }
    
    # Reset coefficient-related values for new analysis
    values$ml_coefficients_by_class <- NULL
    updateSelectInput(session, "coef_class_focus", choices = character(0), selected = NULL)
    
    # Show progress
    withProgress(message = "Running feature selection...", {
      # Check that we have required data
      filtered_data <- mlfs_filtered_data()
      
      if (is.null(filtered_data)) {
        showNotification("No filtered data available. Please check your input settings.", type = "error")
        return()
      }
      
      if (is.null(filtered_data$data) || is.null(filtered_data$labels)) {
        showNotification("Invalid filtered data structure. Please check your group selections.", type = "error")
        return()
      }
      
      # Load packages as needed
      if (input$feature_selection_method == "lasso" && !requireNamespace("glmnet", quietly = TRUE)) {
        install.packages("glmnet")
      }
      if (input$feature_selection_method == "rf" && !requireNamespace("randomForest", quietly = TRUE)) {
        install.packages("randomForest")
      }
      
      # Initialize mlfs with filtered data
      mlfs <- filtered_data
      
      # Apply initial filtering if selected
      if (!is.null(input$feature_filtering_method) && input$feature_filtering_method != "none") {
        if (input$feature_filtering_method == "variance") {
          tryCatch({
            vars <- apply(mlfs$data, 2, var, na.rm = TRUE)
            vars <- vars[!is.na(vars)]  # Remove any NAs
            
            if (length(vars) == 0) {
              showNotification("No valid variances could be calculated for filtering.", type = "error")
              return()
            }
            
            # Filter features by variance threshold
            selected_mask <- vars >= input$feature_filtering_variance
            selected_vars <- vars[selected_mask]
            
            if (length(selected_vars) == 0) {
              showNotification(paste("No features meet variance threshold of", input$feature_filtering_variance, "for filtering."), type = "warning")
              return()
            }
            
            # Apply filtering to data
            mlfs$data <- mlfs$data[, names(selected_vars), drop = FALSE]
            showNotification(paste("Variance filtering: Kept", length(selected_vars), "of", length(vars), "features"), type = "message")
            
          }, error = function(e) {
            showNotification(paste("Variance filtering error:", e$message), type = "error")
            return()
          })
          
        } else if (input$feature_filtering_method == "correlation") {
          tryCatch({
            # Handle different target variable types
            y_for_filter <- mlfs$labels
            if (is.factor(y_for_filter)) {
              if (nlevels(y_for_filter) == 2) {
                # Binary classification: convert to 0/1
                y_numeric <- as.numeric(y_for_filter) - 1
              } else {
                # Multiclass: use first level vs rest for correlation
                y_numeric <- as.numeric(y_for_filter == levels(y_for_filter)[1])
                showNotification("Multiclass target detected. Using first class vs. rest for correlation filtering.", type = "message")
              }
            } else {
              # Continuous target: use as-is
              y_numeric <- as.numeric(y_for_filter)
            }
            
            # Calculate correlations between features and target
            cors <- apply(mlfs$data, 2, function(feature_col) {
              tryCatch({
                abs(cor(feature_col, y_numeric, use = "pairwise.complete.obs"))
              }, error = function(e) {
                NA
              })
            })
            
            # Remove any NAs
            cors <- cors[!is.na(cors)]
            
            if (length(cors) == 0) {
              showNotification("No valid correlations could be calculated for filtering.", type = "error")
              return()
            }
            
            # Filter features by correlation threshold
            high_cor_features <- names(cors)[cors >= input$feature_filtering_corr_cutoff]
            
            if (length(high_cor_features) == 0) {
              showNotification(paste("No features meet correlation threshold of", input$feature_filtering_corr_cutoff, "for filtering."), type = "warning")
              return()
            }
            
            # Apply filtering to data
            mlfs$data <- mlfs$data[, high_cor_features, drop = FALSE]
            showNotification(paste("Correlation filtering: Kept", length(high_cor_features), "of", length(cors), "features"), type = "message")
            
          }, error = function(e) {
            showNotification(paste("Correlation filtering error:", e$message), type = "error")
            return()
          })
        } else if (input$feature_filtering_method == "pca") {
          tryCatch({
            # Check if PCA features are available
            if (is.null(values$pca_top_features) || length(values$pca_top_features) == 0) {
              showNotification("No PCA Top N features available. Please run PCA analysis in the Dimensionality Reduction tab and make features global first.", type = "warning")
              return()
            }
            
            # Use the same pattern as other tabs: get feature indices and subset by rows
            pca_feature_indices <- get_feature_indices_by_source("pca", "All Groups")
            
            if (length(pca_feature_indices) == 0) {
              showNotification("No PCA Top N features found. Please ensure PCA was run on compatible data.", type = "warning")
              return()
            }
            
            # Apply PCA filtering to data by subsetting rows (molecules) using indices
            mlfs$data <- mlfs$data[pca_feature_indices, , drop = FALSE]
            showNotification(paste("PCA filtering: Using", length(pca_feature_indices), "Top N PCA features from Dimensionality Reduction tab"), type = "message")
            
          }, error = function(e) {
            showNotification(paste("PCA filtering error:", e$message), type = "error")
            return()
          })
        }
      }
      # Debug information
      cat("=== ML Feature Selection Debug ===\n")
      cat("  Target Variable:", input$feature_selection_target, "\n")
      cat("  Data dimensions:", dim(mlfs$data), "\n")
      cat("  Number of labels:", length(mlfs$labels), "\n")
      cat("  Unique labels:", paste(unique(mlfs$labels), collapse = ", "), "\n")
      
      # Check if this is a target vs others analysis
      target_var <- input$feature_selection_target
      if ("Other" %in% mlfs$labels && target_var != "ALL_GROUPS") {
        target_count <- sum(mlfs$labels == target_var)
        other_count <- sum(mlfs$labels == "Other")
        cat("  Target-based analysis: ", target_var, " (", target_count, " samples) vs Other (", other_count, " samples)\n", sep = "")
      } else if (target_var == "ALL_GROUPS") {
        cat("  Multi-class analysis using all", length(unique(mlfs$labels)), "groups:", paste(unique(mlfs$labels), collapse = ", "), "\n")
      }
      
      X <- as.data.frame(t(mlfs$data))
      y <- as.factor(mlfs$labels)
      # Debug audit (console only): pre-split label distribution
      cat("  Audit (pre-split) group counts:\n")
      print(table(y))
      
      # ============================================================================
      # METHOD-SPECIFIC GROUP SELECTION (BEFORE TRAIN/TEST SPLIT)
      # ============================================================================
      # Apply RFE-specific problem definition overrides BEFORE train/test split
      if (!is.null(input$feature_selection_method) && input$feature_selection_method %in% c("rfe") ) {
        if (!is.null(input$rfe_problem_type) && input$rfe_problem_type == "binary") {
          # Binary (mirroring LASSO handling): build directly from normalized_data group columns
          if (!is.null(input$rfe_group_1) && !is.null(input$rfe_group_2) && input$rfe_group_1 != input$rfe_group_2) {
            g1_idx <- which(values$unique_groups == input$rfe_group_1)
            g2_idx <- which(values$unique_groups == input$rfe_group_2)
            if (length(g1_idx) == 1 && length(g2_idx) == 1) {
              cols1 <- values$group_column_indices[[g1_idx]]
              cols2 <- values$group_column_indices[[g2_idx]]
              if (length(cols1) > 0 && length(cols2) > 0) {
                data_mat <- values$normalized_data[, c(cols1, cols2), drop = FALSE]
                labels <- c(rep(input$rfe_group_1, length(cols1)), rep(input$rfe_group_2, length(cols2)))
                X <- as.data.frame(t(data_mat))
                y <- factor(labels, levels = c(input$rfe_group_1, input$rfe_group_2))
                cat("  RFE Binary (direct construction):", input$rfe_group_1, "(", length(cols1), ") vs", input$rfe_group_2, "(", length(cols2), ")\n", sep = " ")
                cat("  Audit (post-RFE binary selection) group counts:\n")
                print(table(y))
              } else {
                showNotification("RFE binary mode: One of the selected groups has zero samples.", type = "error", duration = 8)
                return()
              }
            } else {
              showNotification("RFE binary mode: Unable to locate selected group indices.", type = "error", duration = 8)
              return()
            }
          } else {
            showNotification("RFE binary mode: Please select two distinct groups. Falling back to multiclass.", type = "warning", duration = 8)
          }
        } else if (!is.null(input$rfe_problem_type) && input$rfe_problem_type == "multiclass") {
          # Multiclass: optional subset of groups
          if (!is.null(input$rfe_groups_multi) && length(input$rfe_groups_multi) >= 2) {
            keep_idx <- which(y %in% input$rfe_groups_multi)
            X <- X[keep_idx, , drop = FALSE]
            y <- droplevels(factor(y[keep_idx]))
            cat("  RFE Problem Override: Multiclass restricted to groups:", paste(levels(y), collapse=", "), "\n")
            cat("  Audit (post-RFE multiclass selection) group counts:\n")
            print(table(y))
          } else {
            cat("  RFE Problem Override: Multiclass using all groups (default)\n")
            cat("  Audit (post-RFE multiclass selection, all groups) group counts:\n")
            print(table(y))
          }
        }
      }
      
      # Apply Boruta-specific problem definition overrides BEFORE train/test split
      if (!is.null(input$feature_selection_method) && input$feature_selection_method %in% c("boruta")) {
        if (!is.null(input$boruta_problem_type) && input$boruta_problem_type == "binary") {
          # Binary: build directly from normalized_data group columns
          if (!is.null(input$boruta_group_1) && !is.null(input$boruta_group_2) && input$boruta_group_1 != input$boruta_group_2) {
            g1_idx <- which(values$unique_groups == input$boruta_group_1)
            g2_idx <- which(values$unique_groups == input$boruta_group_2)
            if (length(g1_idx) == 1 && length(g2_idx) == 1) {
              cols1 <- values$group_column_indices[[g1_idx]]
              cols2 <- values$group_column_indices[[g2_idx]]
              if (length(cols1) > 0 && length(cols2) > 0) {
                data_mat <- values$normalized_data[, c(cols1, cols2), drop = FALSE]
                labels <- c(rep(input$boruta_group_1, length(cols1)), rep(input$boruta_group_2, length(cols2)))
                X <- as.data.frame(t(data_mat))
                y <- factor(labels, levels = c(input$boruta_group_1, input$boruta_group_2))
                cat("  Boruta Binary (direct construction):", input$boruta_group_1, "(", length(cols1), ") vs", input$boruta_group_2, "(", length(cols2), ")\n", sep = " ")
                cat("  Audit (post-Boruta binary selection) group counts:\n")
                print(table(y))
              } else {
                showNotification("Boruta binary mode: One of the selected groups has zero samples.", type = "error", duration = 8)
                return()
              }
            } else {
              showNotification("Boruta binary mode: Unable to locate selected group indices.", type = "error", duration = 8)
              return()
            }
          } else {
            showNotification("Boruta binary mode: Please select two distinct groups. Falling back to multiclass.", type = "warning", duration = 8)
          }
        } else if (!is.null(input$boruta_problem_type) && input$boruta_problem_type == "multiclass") {
          # Multiclass: optional subset of groups
          if (!is.null(input$boruta_groups_multi) && length(input$boruta_groups_multi) >= 2) {
            keep_idx <- which(y %in% input$boruta_groups_multi)
            X <- X[keep_idx, , drop = FALSE]
            y <- droplevels(factor(y[keep_idx]))
            cat("  Boruta Problem Override: Multiclass restricted to groups:", paste(levels(y), collapse=", "), "\n")
            cat("  Audit (post-Boruta multiclass selection) group counts:\n")
            print(table(y))
          } else {
            cat("  Boruta Problem Override: Multiclass using all groups (default)\n")
            cat("  Audit (post-Boruta multiclass selection, all groups) group counts:\n")
            print(table(y))
          }
        } else if (!is.null(input$boruta_problem_type) && input$boruta_problem_type == "regression") {
          # For regression, y should be numeric
          # Convert y to numeric if it's currently a factor
          if (is.factor(y)) {
            showNotification("Regression mode: Converting target to numeric values.", type = "message", duration = 3)
            y <- as.numeric(as.character(y))
          }
          cat("  Boruta Problem Override: Regression mode\n")
        }
      }
      
      # ============================================================================
      # TRAIN/TEST SPLIT IMPLEMENTATION
      # ============================================================================
      # Clear previous validation results
      values$ml_train_indices <- NULL
      values$ml_test_indices <- NULL
      values$ml_train_X <- NULL
      values$ml_train_y <- NULL
      values$ml_test_X <- NULL
      values$ml_test_y <- NULL
      values$ml_test_predictions <- NULL
      values$ml_test_performance <- NULL
      values$ml_train_performance <- NULL
      
      if (isTRUE(input$enable_train_test_split)) {
        cat("=== Train/Test Split Enabled ===\n")
        
        # Set seed for reproducibility
        set.seed(input$feature_selection_seed)
        
        n_samples <- nrow(X)
        train_ratio <- input$train_test_ratio / 100
        
        if (isTRUE(input$stratified_split)) {
          # Stratified split - maintain class proportions
          cat("  Using stratified split to maintain class proportions\n")
          
          # Create stratified indices
          train_indices <- integer(0)
          for (class_level in levels(y)) {
            class_indices <- which(y == class_level)
            n_class <- length(class_indices)
            n_train_class <- ceiling(n_class * train_ratio)
            
            # Ensure at least 1 sample in each set if possible
            if (n_class >= 2) {
              n_train_class <- max(1, min(n_train_class, n_class - 1))
            }
            
            train_class_indices <- sample(class_indices, n_train_class)
            train_indices <- c(train_indices, train_class_indices)
          }
          
          test_indices <- setdiff(1:n_samples, train_indices)
          
        } else {
          # Simple random split
          cat("  Using simple random split\n")
          n_train <- ceiling(n_samples * train_ratio)
          train_indices <- sample(1:n_samples, n_train)
          test_indices <- setdiff(1:n_samples, train_indices)
        }
        
        # Split data
        X_train <- X[train_indices, , drop = FALSE]
        y_train <- y[train_indices]
        X_test <- X[test_indices, , drop = FALSE]
        y_test <- y[test_indices]
        
        # Store split data
        values$ml_train_indices <- train_indices
        values$ml_test_indices <- test_indices
        values$ml_train_X <- X_train
        values$ml_train_y <- y_train
        values$ml_test_X <- X_test
        values$ml_test_y <- y_test
        
        # Print split information
        cat("  Train set:", length(train_indices), "samples\n")
        cat("  Test set:", length(test_indices), "samples\n")
        cat("  Train class distribution:\n")
        print(table(y_train))
        cat("  Test class distribution:\n")
        print(table(y_test))
        
        # Use training data for feature selection
        X <- X_train
        y <- y_train
        
        showNotification(
          paste0("Train/Test Split: ", length(train_indices), " training / ",
                 length(test_indices), " test samples"),
          type = "message", duration = 5
        )
      } else {
        cat("=== Train/Test Split Disabled - Using full dataset ===\n")
      }
      
      cat("  X dimensions after transpose:", dim(X), "\n")
      cat("  y length:", length(y), "\n")
      cat("  Unique y levels:", paste(levels(y), collapse = ", "), "\n")
      
      # Validate data
      if (nrow(X) == 0 || ncol(X) == 0) {
        showNotification("No data available for feature selection. Please check your data and settings.", type = "error")
        return()
      }
      
      {
        unique_y <- unique(y)
        if (length(unique_y) < 2) {
          is_regression_mode <- (!is.null(input$feature_selection_method) &&
                                   input$feature_selection_method == "rfe" &&
                                   identical(input$rfe_problem_type, "regression"))
          
          if (!is_regression_mode) {
            # Additional diagnostics for binary RFE
            if (!is.null(input$rfe_problem_type) && input$rfe_problem_type == "binary") {
              g1 <- input$rfe_group_1; g2 <- input$rfe_group_2
              msg <- paste0("Binary RFE requires two distinct groups with samples. Current unique outcome count: ",
                            length(unique_y), ".\n",
                            "Selected Group 1: ", ifelse(is.null(g1), "<none>", g1), "; Group 2: ", ifelse(is.null(g2), "<none>", g2), ".")
              # Suggest fixes
              msg <- paste0(msg, "\nSuggestions:\n  Ensure both groups have at least one sample.\n  Re-select Group 2 if it defaulted to the same as Group 1.\n  If intending regression, switch Problem Type to 'Regression'.")
              showNotification(msg, type = "error", duration = 12)
            } else {
              showNotification("Need at least 2 different groups/classes for feature selection.", type = "error")
            }
            return()
          }
          # In regression mode we allow a single numeric outcome vector; further checks happen later
        }
      }
      
      # Validate glmnet family selection for LASSO method
      if (input$feature_selection_method == "lasso") {
        n_classes <- length(unique(y))
        family_type <- input$glmnet_family
        
        if (n_classes == 2 && family_type == "multinomial") {
          showNotification("For 2 classes, use 'binomial' family instead of 'multinomial'.", type = "warning")
        } else if (n_classes > 2 && family_type == "binomial") {
          showNotification("For more than 2 classes, use 'multinomial' family instead of 'binomial'.", type = "warning")
        } else if (family_type == "gaussian" && is.factor(y)) {
          showNotification("Gaussian family is for continuous outcomes. Your target appears to be categorical.", type = "warning")
        }
      }
      # ==============================
      # FEATURE NAME RESTORATION BLOCK
      # ==============================
      # Correctly obtain feature names (columns of X correspond to rows of mlfs$data)
      feature_names <- NULL
      
      # PRIORITY 1: Use cleaned_molecules if available and matches dimensionality
      if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) == ncol(X)) {
        feature_names <- values$cleaned_molecules
        cat("Using cleaned_molecules for feature names (", length(feature_names), " features)\n")
      }
      
      # PRIORITY 2: Use rownames from mlfs$data if not numeric-only
      if (is.null(feature_names) && !is.null(mlfs$data)) {
        data_rownames <- rownames(mlfs$data)
        # Only use if they're not purely numeric (which would be placeholder IDs)
        if (!is.null(data_rownames) && length(data_rownames) == ncol(X) &&
            !all(grepl("^[0-9]+$", data_rownames))) {
          feature_names <- data_rownames
          cat("Using mlfs$data rownames for feature names\n")
        }
      }
      
      # PRIORITY 3: Try cleaned_molecules subset if lengths don't match exactly
      if (is.null(feature_names) && !is.null(values$cleaned_molecules)) {
        if (length(values$cleaned_molecules) >= ncol(X)) {
          feature_names <- values$cleaned_molecules[seq_len(ncol(X))]
          cat("Using subset of cleaned_molecules for feature names\n")
        }
      }
      
      # PRIORITY 4: Keep existing X colnames if they look meaningful
      if (is.null(feature_names) || length(feature_names) != ncol(X)) {
        existing_cols <- colnames(X)
        if (!is.null(existing_cols) && length(existing_cols) == ncol(X) &&
            !all(grepl("^[0-9]+$", existing_cols))) {
          feature_names <- existing_cols
          cat("Using existing colnames(X) for feature names\n")
        } else {
          # FALLBACK: Generate generic names that will be mapped later
          feature_names <- paste0("Feature_", seq_len(ncol(X)))
          cat("Using generic Feature_N names (", length(feature_names), " features)\n")
        }
      }
      
      colnames(X) <- feature_names
      # Store for downstream diagnostic use
      values$ml_feature_names <- feature_names
      
      # Update stored train/test data column names to match
      if (!is.null(values$ml_train_X)) {
        colnames(values$ml_train_X) <- feature_names
        cat("Updated train data column names to match feature_names\n")
      }
      if (!is.null(values$ml_test_X)) {
        colnames(values$ml_test_X) <- feature_names
        cat("Updated test data column names to match feature_names\n")
      }
      
      # Debug: Print first few feature names
      cat("DEBUG: First 10 feature names assigned to X:\n")
      cat(paste(head(feature_names, 10), collapse = ", "), "\n")
      cat("DEBUG: First 10 colnames(X) after assignment:\n")
      cat(paste(head(colnames(X), 10), collapse = ", "), "\n")
      
      # Create binary y for some methods
      y_bin <- as.numeric(y) - 1  # Convert factor to 0/1
      
      # Optionally scale/center
      if (isTRUE(input$feature_selection_scale)) {
        X <- scale(X)
        # Convert back to data.frame with proper column names
        X <- as.data.frame(X)
        colnames(X) <- feature_names
        
        # Also scale train/test data if split is enabled
        if (!is.null(values$ml_train_X)) {
          values$ml_train_X <- scale(values$ml_train_X)
          values$ml_train_X <- as.data.frame(values$ml_train_X)
          colnames(values$ml_train_X) <- feature_names
          cat("Scaled train data and updated column names\n")
        }
        if (!is.null(values$ml_test_X)) {
          values$ml_test_X <- scale(values$ml_test_X)
          values$ml_test_X <- as.data.frame(values$ml_test_X)
          colnames(values$ml_test_X) <- feature_names
          cat("Scaled test data and updated column names\n")
        }
      }
      
      set.seed(input$feature_selection_seed)
      n_features <- input$feature_selection_nfeatures
      
      fs_result <- NULL
      importance <- NULL
      selected <- NULL
      perf <- NULL
      
      # Enhanced LASSO/ElasticNet Implementation
      if (input$feature_selection_method == "lasso") {
        # Check for sufficient data
        if (nrow(X) == 0 || ncol(X) == 0 || length(unique(y)) < 2) {
          showNotification("No data available for LASSO/ElasticNet after filtering. Check your pairwise/group selections.", type = "error")
          values$ml_selected_features <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_importance <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_performance <- "No features selected."
          return()
        }
        
        # Load required packages
        if (!requireNamespace("glmnet", quietly = TRUE)) {
          install.packages("glmnet")
          library(glmnet)
        }
        
        tryCatch({
          # Prepare parameters - Handle alpha autotuning
          if (isTRUE(input$autotune_alpha)) {
            # Alpha autotuning - will be determined through grid search
            autotune_alpha <- TRUE
            alpha_grid <- seq(from = input$alpha_grid_min %||% 0,
                              to = input$alpha_grid_max %||% 1,
                              length.out = input$alpha_grid_length %||% 11)
            alpha <- 1  # Default placeholder (will be overwritten)
          } else {
            # Manual alpha selection
            autotune_alpha <- FALSE
            alpha <- input$feature_selection_alpha
            alpha_grid <- NULL
          }
          
          family_type <- input$glmnet_family
          standardize <- isTRUE(input$glmnet_standardize)
          intercept <- isTRUE(input$glmnet_intercept)
          
          # Determine cross-validation folds
          cv_folds <- input$glmnet_nfolds
          cv_folds <- min(cv_folds, nrow(X))  # Can't have more folds than samples
          
          # Prepare data matrix
          X_mat <- as.matrix(X)
          
          # Class imbalance detection and weights calculation
          imbalance_info <- detect_class_imbalance(y, threshold = 0.1)
          sample_weights <- NULL
          
          if (imbalance_info$is_imbalanced) {
            cat("=== Class Imbalance Detected ===\n")
            cat("Class counts:", paste(names(imbalance_info$class_counts),
                                       imbalance_info$class_counts, sep = ":", collapse = ", "), "\n")
            cat("Imbalance ratio:", round(imbalance_info$imbalance_ratio, 3), "\n")
            
            if (!isTRUE(input$glmnet_use_weights)) {
              # Notify user about imbalance and suggest using weights
              showNotification(
                paste("Class imbalance detected! Minority class:",
                      imbalance_info$minority_class, "(",
                      round(imbalance_info$class_proportions[imbalance_info$minority_class] * 100, 1),
                      "%). Consider enabling 'Use Sample Weights' for better results."),
                type = "warning",
                duration = 8
              )
            } else {
              # Calculate sample weights
              weight_method <- input$glmnet_weight_method %||% "balanced"
              custom_weights <- NULL
              
              if (weight_method == "custom" && !is.null(input$glmnet_custom_weights) &&
                  nchar(input$glmnet_custom_weights) > 0) {
                tryCatch({
                  custom_weights <- as.numeric(strsplit(input$glmnet_custom_weights, ",")[[1]])
                  if (length(custom_weights) != length(unique(y))) {
                    showNotification("Custom weights count doesn't match number of classes. Using balanced weights.",
                                     type = "warning")
                    custom_weights <- NULL
                    weight_method <- "balanced"
                  }
                }, error = function(e) {
                  showNotification("Invalid custom weights format. Using balanced weights.", type = "warning")
                  custom_weights <- NULL
                  weight_method <- "balanced"
                })
              }
              
              sample_weights <- calculate_sample_weights(y, method = weight_method, custom_weights = custom_weights)
              
              cat("Using sample weights with method:", weight_method, "\n")
              cat("Weight summary - Min:", round(min(sample_weights), 3),
                  "Max:", round(max(sample_weights), 3),
                  "Mean:", round(mean(sample_weights), 3), "\n")
              
              showNotification(
                paste("Applied", weight_method, "sample weights to handle class imbalance."),
                type = "message",
                duration = 5
              )
            }
          }
          
          # Handle different target variable types based on family
          if (family_type == "gaussian") {
            # Convert to numeric for regression
            if (is.factor(y)) {
              y_model <- as.numeric(y)
            } else {
              y_model <- y
            }
          } else if (family_type == "binomial") {
            # Ensure binary classification
            if (length(unique(y)) != 2) {
              stop("Binary classification requires exactly 2 classes")
            }
            y_model <- as.factor(y)
          } else if (family_type == "multinomial") {
            y_model <- as.factor(y)
          } else if (family_type == "poisson") {
            # Convert to non-negative integers
            y_model <- pmax(0, round(as.numeric(y)))
          } else {
            y_model <- y
          }
          
          # Prepare additional glmnet arguments
          glmnet_args <- list(
            x = X_mat,
            y = y_model,
            family = family_type,
            alpha = alpha,
            standardize = standardize,
            intercept = intercept
          )
          
          # Add sample weights if available
          if (!is.null(sample_weights)) {
            glmnet_args$weights <- sample_weights
          }
          
          # Add bounds if specified
          if (!is.na(input$glmnet_lower_limits)) {
            glmnet_args$lower.limits <- input$glmnet_lower_limits
          }
          if (!is.na(input$glmnet_upper_limits)) {
            glmnet_args$upper.limits <- input$glmnet_upper_limits
          }
          
          # Add penalty factors if specified
          if (isTRUE(input$use_penalty_factors) && !is.null(input$penalty_factors_file)) {
            penalty_data <- read.csv(input$penalty_factors_file$datapath)
            if (ncol(penalty_data) >= 2) {
              penalty_factors <- setNames(penalty_data[,2], penalty_data[,1])
              # Match to current features
              matched_penalties <- penalty_factors[colnames(X_mat)]
              matched_penalties[is.na(matched_penalties)] <- 1  # Default penalty
              glmnet_args$penalty.factor <- matched_penalties
            }
          }
          
          # Add relax option if specified
          if (isTRUE(input$glmnet_relax)) {
            glmnet_args$relax <- TRUE
          }
          
          # Handle alpha autotuning first (if enabled)
          best_alpha_cv_fit <- NULL
          if (autotune_alpha) {
            cat("Debug LASSO: Performing alpha grid search with", length(alpha_grid), "values\n")
            cat("Alpha grid:", paste(round(alpha_grid, 3), collapse = ", "), "\n")
            
            # Perform alpha grid search
            alpha_results <- list()
            best_cv_error <- Inf
            best_alpha <- alpha_grid[1]
            
            for (i in seq_along(alpha_grid)) {
              current_alpha <- alpha_grid[i]
              
              # Update alpha in glmnet args
              glmnet_args$alpha <- current_alpha
              
              # Perform CV for this alpha
              cv_args <- glmnet_args
              cv_args$nfolds <- cv_folds
              
              # Add appropriate type.measure for binomial
              if (family_type == "binomial") {
                cv_args$keep <- TRUE
                cv_args$type.measure <- "auc"  # Use AUC for binomial
              }
              
              tryCatch({
                temp_cv_fit <- do.call(glmnet::cv.glmnet, cv_args)
                
                # Extract CV error (note: for AUC we want maximum, so we use negative)
                if (family_type == "binomial") {
                  # For AUC, higher is better, so we minimize negative AUC
                  cv_error <- -max(temp_cv_fit$cvm, na.rm = TRUE)
                } else {
                  # For other metrics, lower is better
                  cv_error <- min(temp_cv_fit$cvm, na.rm = TRUE)
                }
                
                alpha_results[[i]] <- list(
                  alpha = current_alpha,
                  cv_error = cv_error,
                  cv_fit = temp_cv_fit
                )
                
                if (cv_error < best_cv_error) {
                  best_cv_error <- cv_error
                  best_alpha <- current_alpha
                }
                
                cat("Alpha =", round(current_alpha, 3), "CV error =", round(cv_error, 4), "\n")
                
              }, error = function(e) {
                cat("Error with alpha =", current_alpha, ":", e$message, "\n")
                alpha_results[[i]] <- list(
                  alpha = current_alpha,
                  cv_error = Inf,
                  cv_fit = NULL
                )
              })
            }
            
            # Use the best alpha
            alpha <- best_alpha
            glmnet_args$alpha <- alpha
            cat("Best alpha selected:", round(alpha, 3), "with CV error:", round(best_cv_error, 4), "\n")
            
            # Store alpha grid results for display and get the best alpha's CV fit
            values$alpha_grid_results <- alpha_results
            best_alpha_cv_fit <- NULL
            for (result in alpha_results) {
              if (!is.null(result) && result$alpha == best_alpha && !is.null(result$cv_fit)) {
                best_alpha_cv_fit <- result$cv_fit
                break
              }
            }
            
            showNotification(paste("Alpha auto-tuning completed. Best alpha:", round(alpha, 3)),
                             type = "message", duration = 5)
          }
          
          # Handle lambda selection
          if (autotune_alpha && !is.null(best_alpha_cv_fit)) {
            # Use the CV fit from the best alpha to maintain consistency
            cv_fit <- best_alpha_cv_fit
            fit <- cv_fit$glmnet.fit
            lambda_best <- cv_fit[[input$lambda_rule]]
            cat("Using lambda from best alpha's CV fit:", lambda_best, "\n")
            
          } else if (input$lambda_selection == "manual") {
            # Manual lambda specification with validation
            lambda_val <- input$feature_selection_lambda %||% 0.01
            if (is.null(lambda_val) || is.na(lambda_val) || lambda_val <= 0) {
              lambda_val <- 0.01
              showNotification("Invalid lambda value, using default 0.01", type = "warning")
            }
            glmnet_args$lambda <- lambda_val
            cat("Debug LASSO: Using manual lambda =", lambda_val, "\n")
            
            # Fit model with specified lambda
            fit <- do.call(glmnet::glmnet, glmnet_args)
            lambda_best <- lambda_val
            cv_fit <- NULL
            
          } else if (input$lambda_selection == "sequence") {
            # Lambda sequence specification
            lambda_seq <- exp(seq(log(input$lambda_max), log(input$lambda_min), length.out = input$lambda_length))
            glmnet_args$lambda <- lambda_seq
            
            # Fit model with sequence
            fit <- do.call(glmnet::glmnet, glmnet_args)
            
            # Use cross-validation to select best lambda from sequence
            cv_args <- glmnet_args
            cv_args$nfolds <- cv_folds
            # Add keep=TRUE for binomial classification to enable roc.glmnet
            if (family_type == "binomial") {
              cv_args$keep <- TRUE
              cv_args$type.measure <- "auc"  # Use AUC for binomial
            }
            cv_fit <- do.call(glmnet::cv.glmnet, cv_args)
            lambda_best <- cv_fit[[input$lambda_rule]]
            
          } else {
            # Cross-validation (default)
            cv_args <- glmnet_args
            cv_args$nfolds <- cv_folds
            # Add keep=TRUE for binomial classification to enable roc.glmnet
            if (family_type == "binomial") {
              cv_args$keep <- TRUE
              cv_args$type.measure <- "auc"  # Use AUC for binomial
            }
            
            # Fit with cross-validation
            cv_fit <- do.call(glmnet::cv.glmnet, cv_args)
            fit <- cv_fit$glmnet.fit
            lambda_best <- cv_fit[[input$lambda_rule]]
          }
          
          # Extract coefficients at optimal lambda
          coef_mat <- coef(fit, s = lambda_best)
          
          # Handle different coefficient structures
          if (inherits(coef_mat, "list")) {
            # Multinomial case - average absolute coefficients across classes
            coef_names <- rownames(coef_mat[[1]])[-1]  # Exclude intercept
            imp <- Reduce("+", lapply(coef_mat, function(m) abs(as.vector(m)[-1]))) / length(coef_mat)
            names(imp) <- coef_names
            
            # Debug: Print coefficient names
            cat("DEBUG LASSO: Multinomial coefficient names (first 10):\n")
            cat(paste(head(coef_names, 10), collapse = ", "), "\n")
            
            # Store coefficients for each class
            values$ml_coefficients_by_class <- coef_mat
            
          } else {
            # Binary or continuous case
            coef_names <- rownames(coef_mat)[-1]  # Exclude intercept
            imp <- abs(as.vector(coef_mat)[-1])
            names(imp) <- coef_names
            
            # Debug: Print coefficient names
            cat("DEBUG LASSO: Binary/Continuous coefficient names (first 10):\n")
            cat(paste(head(coef_names, 10), collapse = ", "), "\n")
            
            # Store single coefficient matrix
            values$ml_coefficients_by_class <- list(Response = coef_mat)
          }
          
          # Sort by importance
          importance <- sort(imp, decreasing = TRUE)
          n_nonzero <- sum(importance > 0)
          
          if (n_nonzero == 0) {
            showNotification("LASSO/ElasticNet did not select any features. Try adjusting lambda or alpha parameters.", type = "warning")
            selected <- character(0)
            fs_result <- data.frame(Feature = character(0), Importance = numeric(0))
            perf <- "No features selected."
          } else {
            selected <- names(importance)[1:min(n_features, n_nonzero)]
            fs_result <- data.frame(Feature = names(importance), Importance = importance)
            
            # Calculate performance metrics
            if (!is.null(cv_fit)) {
              # For AUC (binomial), use max; for other metrics, use min
              if (family_type == "binomial") {
                cv_error <- max(cv_fit$cvm, na.rm = TRUE)
                cv_se <- cv_fit$cvsd[which.max(cv_fit$cvm)]
              } else {
                cv_error <- min(cv_fit$cvm, na.rm = TRUE)
                cv_se <- cv_fit$cvsd[which.min(cv_fit$cvm)]
              }
              perf <- paste0("CV Error: ", round(cv_error, 4), " ( ", round(cv_se, 4), ")")
            } else {
              perf <- paste("Model fitted with lambda =", round(lambda_best, 4))
            }
          }
          
          # Store comprehensive results
          values$ml_selected_features <- map_numeric_ids_to_names(fs_result[fs_result$Feature %in% selected, , drop = FALSE])
          values$ml_importance <- map_numeric_ids_to_names(fs_result)
          
          # Enhanced performance output with target variable info
          target_var <- input$feature_selection_target
          target_info <- if (target_var == "ALL_GROUPS") {
            paste("Multi-class analysis with", length(unique(y)), "classes:", paste(unique(y), collapse = ", "))
          } else if ("Other" %in% unique(y)) {
            paste("Target vs Others:", target_var, "vs Other")
          } else {
            paste("Analysis with groups:", paste(unique(y), collapse = ", "))
          }
          
          # Add class imbalance handling information to performance output
          final_performance <- paste(perf, "\nAnalysis type:", target_info)
          if (!is.null(sample_weights)) {
            weight_method <- input$glmnet_weight_method %||% "balanced"
            weight_info <- paste0("\n\nClass Imbalance Handling:\n  Sample Weights Applied: ", weight_method,
                                  " (Min: ", round(min(sample_weights), 3),
                                  ", Max: ", round(max(sample_weights), 3), ")")
            final_performance <- paste0(final_performance, weight_info)
          }
          
          values$ml_performance <- final_performance
          
          values$ml_glmnet_fit <- fit
          values$ml_cv_fit <- cv_fit
          values$ml_lambda_best <- lambda_best
          values$ml_glmnet_family <- family_type
          values$ml_glmnet_alpha <- alpha
          values$ml_X_matrix <- X_mat
          values$ml_y_response <- y_model
          
          # Debug: Validate lambda values
          if (!is.null(cv_fit)) {
            cat("Debug - CV fit lambda.min:", cv_fit$lambda.min, "\n")
            cat("Debug - CV fit lambda.1se:", cv_fit$lambda.1se, "\n")
            cat("Debug - Selected lambda_best:", lambda_best, "\n")
            cat("Debug - Lambda rule used:", input$lambda_rule, "\n")
          }
          
          # ===================================================================
          # CALCULATE TRAIN/TEST PERFORMANCE METRICS
          # ===================================================================
          if (!is.null(values$ml_train_X) && !is.null(values$ml_test_X)) {
            cat("=== Calculating Train/Test Performance Metrics ===\n")
            
            # Source validation functions if not already loaded
            if (!exists("calculate_binary_metrics") && file.exists("ml_validation_functions.R")) {
              source("ml_validation_functions.R")
            }
            
            tryCatch({
              # Training set performance
              if (family_type == "binomial") {
                # Binary classification
                train_pred_prob <- predict(fit, newx = X_mat, s = lambda_best, type = "response")[,1]
                train_pred_class <- predict(fit, newx = X_mat, s = lambda_best, type = "class")
                
                if (exists("calculate_binary_metrics")) {
                  train_metrics <- calculate_binary_metrics(train_pred_class, y_model)
                  values$ml_train_performance <- train_metrics
                  cat("Training metrics calculated (binary)\n")
                } else {
                  values$ml_train_performance <- list(
                    metrics = data.frame(
                      Metric = "Accuracy",
                      Value = mean(train_pred_class == y_model)
                    )
                  )
                }
                
                # Test set performance
                test_pred_prob <- predict(fit, newx = as.matrix(values$ml_test_X),
                                          s = lambda_best, type = "response")[,1]
                test_pred_class <- predict(fit, newx = as.matrix(values$ml_test_X),
                                           s = lambda_best, type = "class")
                
                if (exists("calculate_binary_metrics")) {
                  test_metrics <- calculate_binary_metrics(test_pred_class, values$ml_test_y)
                  values$ml_test_performance <- test_metrics
                  cat("Test metrics calculated (binary)\n")
                } else {
                  values$ml_test_performance <- list(
                    metrics = data.frame(
                      Metric = "Accuracy",
                      Value = mean(test_pred_class == values$ml_test_y)
                    )
                  )
                }
                
              } else if (family_type == "multinomial" || family_type == "grouped_multinomial") {
                # Multi-class classification
                train_pred_class <- predict(fit, newx = X_mat, s = lambda_best, type = "class")
                
                if (exists("calculate_multiclass_metrics")) {
                  train_metrics <- calculate_multiclass_metrics(train_pred_class, y_model)
                  values$ml_train_performance <- train_metrics
                  cat("Training metrics calculated (multiclass)\n")
                } else {
                  values$ml_train_performance <- list(
                    metrics = data.frame(
                      Metric = "Accuracy",
                      Value = mean(train_pred_class == y_model)
                    )
                  )
                }
                
                # Test set performance
                test_pred_class <- predict(fit, newx = as.matrix(values$ml_test_X),
                                           s = lambda_best, type = "class")
                
                if (exists("calculate_multiclass_metrics")) {
                  test_metrics <- calculate_multiclass_metrics(test_pred_class, values$ml_test_y)
                  values$ml_test_performance <- test_metrics
                  cat("Test metrics calculated (multiclass)\n")
                } else {
                  values$ml_test_performance <- list(
                    metrics = data.frame(
                      Metric = "Accuracy",
                      Value = mean(test_pred_class == values$ml_test_y)
                    )
                  )
                }
                
              } else if (family_type == "gaussian") {
                # Regression
                train_pred <- predict(fit, newx = X_mat, s = lambda_best)[,1]
                
                if (exists("calculate_regression_metrics")) {
                  train_metrics <- calculate_regression_metrics(train_pred, y_model)
                  values$ml_train_performance <- train_metrics
                  cat("Training metrics calculated (regression)\n")
                } else {
                  values$ml_train_performance <- list(
                    metrics = data.frame(
                      Metric = c("RMSE", "R-squared"),
                      Value = c(sqrt(mean((train_pred - y_model)^2)),
                                cor(train_pred, y_model)^2)
                    )
                  )
                }
                
                # Test set performance
                test_pred <- predict(fit, newx = as.matrix(values$ml_test_X), s = lambda_best)[,1]
                
                if (exists("calculate_regression_metrics")) {
                  test_metrics <- calculate_regression_metrics(test_pred, values$ml_test_y)
                  values$ml_test_performance <- test_metrics
                  cat("Test metrics calculated (regression)\n")
                } else {
                  values$ml_test_performance <- list(
                    metrics = data.frame(
                      Metric = c("RMSE", "R-squared"),
                      Value = c(sqrt(mean((test_pred - values$ml_test_y)^2)),
                                cor(test_pred, values$ml_test_y)^2)
                    )
                  )
                }
              }
              
              cat("Train/Test performance metrics stored successfully\n")
              
            }, error = function(e) {
              cat("Error calculating train/test metrics:", e$message, "\n")
              # Store minimal metrics to avoid null errors
              values$ml_train_performance <- list(
                metrics = data.frame(Metric = "Error", Value = NA)
              )
              values$ml_test_performance <- list(
                metrics = data.frame(Metric = "Error", Value = NA)
              )
            })
          } else {
            cat("Train/test split not enabled - skipping performance calculation\n")
          }
          
          showNotification("LASSO/ElasticNet feature selection completed successfully!", type = "message")
          
          # ENHANCED STABILITY ANALYSIS SECTION
          if (isTRUE(input$enable_enhanced_stability) && !is.null(values$ml_X_matrix) && !is.null(values$ml_y_response)) {
            
            cat("Starting enhanced stability analysis...\n")
            
            # Source the stability functions
            if (file.exists("stability_selection_enhancement.R")) {
              source("stability_selection_enhancement.R")
            }
            if (file.exists("lasso_stability_integration.R")) {
              source("lasso_stability_integration.R")
            }
            if (file.exists("rf_stability_selection.R")) {
              source("rf_stability_selection.R")
            }
            
            # Get stability parameters from UI
            stability_method <- input$stability_method %||% "bootstrap"
            n_stability_bootstrap <- input$n_stability_bootstrap %||% 100
            stability_threshold <- input$stability_threshold %||% 0.6
            
            # Prepare feature names for stability analysis
            feature_names_for_stability <- NULL
            if (!is.null(values$cleaned_molecules) && length(values$cleaned_molecules) == ncol(values$ml_X_matrix)) {
              feature_names_for_stability <- values$cleaned_molecules
              cat("Using cleaned molecule names for stability analysis\n")
            } else if (!is.null(colnames(values$ml_X_matrix))) {
              feature_names_for_stability <- colnames(values$ml_X_matrix)
              cat("Using column names from X matrix for stability analysis\n")
            } else {
              feature_names_for_stability <- paste0("Feature_", 1:ncol(values$ml_X_matrix))
              cat("Using default feature names for stability analysis\n")
            }
            
            tryCatch({
              # Perform enhanced stability analysis
              stability_results <- enhanced_lasso_stability_analysis(
                X = values$ml_X_matrix,
                y = values$ml_y_response,
                family_type = family_type,
                alpha = alpha,
                stability_method = stability_method,
                n_bootstrap = n_stability_bootstrap,
                stability_threshold = stability_threshold,
                feature_names = feature_names_for_stability
              )
              
              # Store results
              values$stability_results <- stability_results
              
              # Handle consensus features differently for single vs. multiple methods
              if (stability_method == "all") {
                # Multiple methods - use consensus analysis with UI parameters
                tryCatch({
                  consensus_features <- get_consensus_features(
                    stability_results = stability_results,
                    consensus_threshold = input$consensus_threshold %||% 0.5
                  )
                  
                  values$consensus_features <- consensus_features
                  
                  # Update ML results with consensus features if requested
                  if (nrow(consensus_features) > 0 && isTRUE(input$use_consensus_features)) {
                    values$ml_selected_features <- consensus_features %>%
                      rename(Feature = Feature, Importance = ConsensusScore) %>%
                      slice_head(n = min(n_features, nrow(.)))
                    
                    showNotification(
                      paste("Feature selection updated with", nrow(values$ml_selected_features),
                            "consensus stable features from multiple methods."),
                      type = "message", duration = 6
                    )
                  } else if (nrow(consensus_features) == 0) {
                    showNotification(
                      "No consensus features found. This may indicate that the stability methods returned different feature sets or that the consensus threshold is too high.",
                      type = "warning", duration = 8
                    )
                  }
                  
                }, error = function(e) {
                  cat("Error in consensus analysis:", e$message, "\n")
                  showNotification(
                    paste("Error in consensus analysis:", e$message),
                    type = "error", duration = 10
                  )
                  # Create empty consensus results as fallback
                  values$consensus_features <- data.frame(
                    Feature = character(0),
                    ConsensusScore = numeric(0),
                    MethodsSupporting = character(0),
                    stringsAsFactors = FALSE
                  )
                })
                
              } else {
                # Single method - extract stable features directly from that method
                stable_features <- NULL
                
                if (stability_method == "bootstrap" && "bootstrap" %in% names(stability_results)) {
                  stable_features <- stability_results$bootstrap$selection_frequencies %>%
                    filter(WeightedFrequency >= stability_threshold) %>%
                    arrange(desc(WeightedFrequency)) %>%
                    rename(Importance = WeightedFrequency)
                  
                } else if (stability_method == "stability_selection" && "stability_selection" %in% names(stability_results)) {
                  stable_set <- stability_results$stability_selection$stable_features
                  if (length(stable_set$features) > 0) {
                    stable_features <- data.frame(
                      Feature = stable_set$features,
                      Importance = stable_set$frequencies,
                      stringsAsFactors = FALSE
                    ) %>% arrange(desc(Importance))
                  }
                  
                } else if (stability_method == "randomized_lasso" && "randomized_lasso" %in% names(stability_results)) {
                  stable_features <- stability_results$randomized_lasso$selection_frequencies %>%
                    filter(SelectionFrequency >= stability_threshold) %>%
                    arrange(desc(SelectionFrequency)) %>%
                    rename(Importance = SelectionFrequency)
                  
                } else if (stability_method == "stability_path" && "stability_path" %in% names(stability_results)) {
                  optimal_features <- stability_results$stability_path$optimal_features
                  if (length(optimal_features) > 0) {
                    stable_features <- data.frame(
                      Feature = optimal_features,
                      Importance = 1.0,  # Binary selection from stability path
                      stringsAsFactors = FALSE
                    )
                  }
                }
                
                # Store single method results as "consensus" for consistency in display
                if (!is.null(stable_features) && nrow(stable_features) > 0) {
                  values$consensus_features <- stable_features %>%
                    rename(ConsensusScore = Importance) %>%
                    mutate(MethodsSupporting = stability_method)
                  
                  # Update ML results with stable features
                  values$ml_selected_features <- stable_features %>%
                    slice_head(n = min(n_features, nrow(.)))
                  
                  showNotification(
                    paste("Feature selection updated with", nrow(values$ml_selected_features),
                          "stable features from", stability_method, "analysis."),
                    type = "message", duration = 6
                  )
                } else {
                  values$consensus_features <- data.frame(
                    Feature = character(0),
                    ConsensusScore = numeric(0),
                    MethodsSupporting = character(0)
                  )
                  showNotification(
                    paste("No stable features found with", stability_method, "method at threshold", stability_threshold),
                    type = "warning", duration = 6
                  )
                }
              }
              
              # Add stability information to performance output
              if (stability_method == "all") {
                n_consensus <- if (!is.null(values$consensus_features)) nrow(values$consensus_features) else 0
                stability_info <- paste0("\n\nStability Analysis (All Methods Consensus):\n",
                                         "  Bootstrap samples: ", n_stability_bootstrap, "\n",
                                         "  Consensus features: ", n_consensus, "\n",
                                         "  Consensus threshold: ", input$consensus_threshold %||% 0.5)
              } else {
                n_stable <- if (!is.null(values$consensus_features)) nrow(values$consensus_features) else 0
                stability_info <- paste0("\n\nStability Analysis (", stability_method, "):\n",
                                         "  Bootstrap samples: ", n_stability_bootstrap, "\n",
                                         "  Stable features: ", n_stable, "\n",
                                         "  Stability threshold: ", stability_threshold)
              }
              
              values$ml_performance <- paste0(values$ml_performance, stability_info)
              
              showNotification("Enhanced stability analysis completed successfully!",
                               type = "message", duration = 4)
              
            }, error = function(e) {
              error_msg <- paste("Enhanced stability analysis error:", e$message)
              showNotification(error_msg, type = "warning")
              cat("Stability analysis error:", e$message, "\n")
            })
          }
          
          # Post-process names: replace generic placeholders with real feature names when possible
          if (!is.null(values$ml_importance) && !is.null(values$cleaned_molecules)) {
            name_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_importance))[1]
            if (!is.null(name_col)) {
              current_names <- values$ml_importance[[name_col]]
              if (length(current_names) == length(values$cleaned_molecules) && all(grepl("^Feature_[0-9]+$", current_names))) {
                values$ml_importance[[name_col]] <- values$cleaned_molecules
                if (!is.null(values$ml_selected_features)) {
                  sel_name_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_selected_features))[1]
                  if (!is.null(sel_name_col)) {
                    idx_map <- match(values$ml_selected_features[[sel_name_col]], current_names)
                    values$ml_selected_features[[sel_name_col]] <- values$cleaned_molecules[idx_map]
                  }
                }
              }
            }
          }
          
        }, error = function(e) {
          error_msg <- paste("LASSO/ElasticNet error:", e$message)
          showNotification(error_msg, type = "error")
          
          # Create empty results on error
          empty_result <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_selected_features <- empty_result
          values$ml_importance <- empty_result
          values$ml_performance <- error_msg
          values$ml_glmnet_fit <- NULL
          values$ml_cv_fit <- NULL
        })
        
      } else if (input$feature_selection_method == "rf") {
        # Enhanced Random Forest implementation with stability analysis support
        tryCatch({
          cat("=== Random Forest Feature Selection ===\n")
          
          # Prepare Random Forest parameters (shared by both standard and stability analysis)
          rf_ntree <- input$feature_selection_ntree %||% 500
          rf_mtry <- if (!is.null(input$feature_selection_mtry) && !is.na(input$feature_selection_mtry)) {
            input$feature_selection_mtry
          } else {
            # Use default mtry based on problem type
            if (is.factor(y)) {
              floor(sqrt(ncol(X)))  # Classification default
            } else {
              max(floor(ncol(X)/3), 1)  # Regression default
            }
          }
          
          # Additional RF parameters from UI inputs
          rf_nodesize <- if (!is.null(input$rf_nodesize) && !is.na(input$rf_nodesize)) {
            input$rf_nodesize
          } else {
            if (is.factor(y)) 1 else 5  # Default nodesize
          }
          
          rf_maxnodes <- if (!is.null(input$rf_maxnodes) && !is.na(input$rf_maxnodes)) {
            input$rf_maxnodes
          } else {
            NULL
          }
          
          # Calculate proximity if requested
          calc_proximity <- isTRUE(input$rf_proximity)
          
          # Calculate local importance if requested
          calc_local_imp <- isTRUE(input$rf_local_importance)
          
          cat("RF Parameters: ntree =", rf_ntree, ", mtry =", rf_mtry, ", nodesize =", rf_nodesize, "\n")
          cat("Advanced options: proximity =", calc_proximity, ", local importance =", calc_local_imp, "\n")
          
          # Check if enhanced stability analysis is enabled
          rf_enable_stability <- isTRUE(input$rf_enable_enhanced_stability)
          
          if (rf_enable_stability) {
            cat("=== Random Forest with Enhanced Stability Analysis ===\n")
            
            # Get stability parameters
            rf_stability_method <- input$rf_stability_method %||% "bootstrap"
            rf_stability_iterations <- input$rf_stability_iterations %||% 100
            rf_stability_threshold <- input$rf_stability_threshold %||% 0.6
            
            showNotification(paste("Running RF Stability Analysis using", rf_stability_method, "method with",
                                   rf_stability_iterations, "iterations..."),
                             type = "message", duration = 5)
            
            # Performance check and warning
            total_rf_models <- rf_stability_iterations
            if (rf_stability_method == "all") {
              total_rf_models <- rf_stability_iterations * 4 # Multiple methods
            }
            
            estimated_time_per_model <- 0.1 + (rf_ntree / 1000) + (ncol(X) / 10000) # Rough estimate in seconds
            estimated_total_time <- total_rf_models * estimated_time_per_model
            
            if (estimated_total_time > 300) { # More than 5 minutes
              performance_warning <- paste0(
                "RF Stability Analysis may take approximately ", round(estimated_total_time / 60, 1),
                " minutes with current settings (", rf_ntree, " trees   ", rf_stability_iterations,
                " iterations). Consider reducing 'Number of Trees' to ", max(100, floor(rf_ntree / 3)),
                " or 'Bootstrap Samples' to ", max(50, floor(rf_stability_iterations / 2)),
                " for faster execution."
              )
              showNotification(performance_warning, type = "warning", duration = 12)
              cat("PERFORMANCE WARNING:", performance_warning, "\n")
            }
            
            # Implement basic stability analysis
            feature_selection_counts <- rep(0, ncol(X))
            feature_importances <- matrix(0, nrow = rf_stability_iterations, ncol = ncol(X))
            
            cat("Starting", rf_stability_method, "stability analysis with", rf_stability_iterations, "iterations\n")
            
            # Progress tracking
            progress_step <- max(1, floor(rf_stability_iterations / 10))
            failed_iterations <- 0
            
            for (i in 1:rf_stability_iterations) {
              if (i %% progress_step == 0) {
                cat("Stability iteration:", i, "/", rf_stability_iterations, "\n")
              }
              
              tryCatch({
                # Generate bootstrap or subsample based on method
                if (rf_stability_method == "bootstrap") {
                  # Bootstrap sampling with replacement
                  boot_indices <- sample(nrow(X), replace = TRUE)
                  X_boot <- X[boot_indices, , drop = FALSE]
                  y_boot <- y[boot_indices]
                  
                } else if (rf_stability_method == "subsampling") {
                  # Subsampling without replacement
                  subsample_ratio <- input$rf_subsample_ratio %||% 0.7
                  subsample_size <- floor(nrow(X) * subsample_ratio)
                  subsample_indices <- sample(nrow(X), size = subsample_size, replace = FALSE)
                  X_boot <- X[subsample_indices, , drop = FALSE]
                  y_boot <- y[subsample_indices]
                  
                } else if (rf_stability_method == "cv") {
                  # Cross-validation based sampling
                  cv_folds <- input$rf_cv_folds %||% 10
                  fold_size <- floor(nrow(X) / cv_folds)
                  fold_start <- ((i - 1) %% cv_folds) * fold_size + 1
                  fold_end <- min(fold_start + fold_size - 1, nrow(X))
                  
                  # Use all except one fold for training
                  train_indices <- setdiff(1:nrow(X), fold_start:fold_end)
                  X_boot <- X[train_indices, , drop = FALSE]
                  y_boot <- y[train_indices]
                  
                } else if (rf_stability_method == "noise") {
                  # Noise injection method
                  noise_levels_str <- input$rf_noise_levels %||% "0.01, 0.05, 0.1"
                  noise_levels <- as.numeric(strsplit(noise_levels_str, ",")[[1]])
                  noise_level <- sample(noise_levels, 1)
                  
                  # Add Gaussian noise to features
                  X_boot <- X + matrix(rnorm(nrow(X) * ncol(X), mean = 0,
                                             sd = noise_level * apply(X, 2, sd, na.rm = TRUE)),
                                       nrow = nrow(X), ncol = ncol(X))
                  y_boot <- y
                  
                } else {
                  # Default to bootstrap
                  boot_indices <- sample(nrow(X), replace = TRUE)
                  X_boot <- X[boot_indices, , drop = FALSE]
                  y_boot <- y[boot_indices]
                }
                
                # Fit Random Forest on bootstrap/subsample
                rf_boot <- randomForest::randomForest(
                  x = X_boot,
                  y = y_boot,
                  ntree = rf_ntree, # Use user's ntree setting
                  mtry = rf_mtry,
                  importance = TRUE,
                  do.trace = FALSE
                )
                
                # Extract variable importance
                if (is.factor(y_boot)) {
                  # Classification: use MeanDecreaseGini or MeanDecreaseAccuracy
                  importance_scores <- randomForest::importance(rf_boot)[, "MeanDecreaseGini"]
                } else {
                  # Regression: use %IncMSE
                  importance_scores <- randomForest::importance(rf_boot)[, "%IncMSE"]
                }
                
                # Normalize importance scores to [0,1]
                if (max(importance_scores, na.rm = TRUE) > 0) {
                  importance_scores <- importance_scores / max(importance_scores, na.rm = TRUE)
                }
                
                # Store importance scores
                feature_importances[i, ] <- importance_scores
                
                # Count features above threshold
                selected_features <- which(importance_scores >= (rf_stability_threshold * 0.1)) # Lower threshold for individual iterations
                feature_selection_counts[selected_features] <- feature_selection_counts[selected_features] + 1
                
              }, error = function(e) {
                failed_iterations <<- failed_iterations + 1
                cat("Error in stability iteration", i, ":", e$message, "\n")
                
                # If too many iterations fail, provide helpful guidance
                if (failed_iterations > rf_stability_iterations * 0.2) { # More than 20% failures
                  warning_msg <- paste0(
                    "RF Stability Analysis: High failure rate (", failed_iterations, "/", i, " iterations failed). ",
                    "Consider reducing 'Number of Trees' to ", max(50, floor(rf_ntree / 2)), " or fewer, ",
                    "or reducing 'Bootstrap Samples' to improve performance and stability."
                  )
                  cat("WARNING:", warning_msg, "\n")
                  showNotification(warning_msg, type = "warning", duration = 10)
                }
              })
            }
            
            # Check for overall failure rate and provide guidance
            failure_rate <- failed_iterations / rf_stability_iterations
            if (failure_rate > 0.1) { # More than 10% failures overall
              failure_msg <- paste0(
                "RF Stability Analysis completed with ", round(failure_rate * 100, 1), "% failed iterations. ",
                "For better performance, consider: 1) Reducing 'Number of Trees' from ", rf_ntree,
                " to ", max(50, floor(rf_ntree / 3)), " or lower, 2) Reducing 'Bootstrap Samples' from ",
                rf_stability_iterations, " to ", max(50, floor(rf_stability_iterations / 2)),
                ", or 3) Using a simpler stability method like 'Enhanced Bootstrap'."
              )
              showNotification(failure_msg, type = "warning", duration = 15)
            } else if (failed_iterations > 0) {
              showNotification(paste0("RF Stability Analysis completed with ", failed_iterations,
                                      " failed iterations out of ", rf_stability_iterations,
                                      ". Results are still reliable."), type = "message", duration = 5)
            }
            
            # Calculate stability scores
            stability_scores <- feature_selection_counts / rf_stability_iterations
            
            # Apply stability threshold to select final features
            stable_features <- which(stability_scores >= rf_stability_threshold)
            
            cat("=== Stability Analysis Results ===\n")
            cat("Features selected in >=", rf_stability_threshold * 100, "% of iterations:", length(stable_features), "\n")
            cat("Average stability score:", round(mean(stability_scores), 3), "\n")
            cat("Max stability score:", round(max(stability_scores), 3), "\n")
            
            # Consensus analysis for "all methods"
            if (rf_stability_method == "all") {
              consensus_threshold <- input$rf_consensus_threshold %||% 0.6
              use_consensus <- input$rf_use_consensus_features %||% TRUE
              
              # Run multiple methods and combine results
              methods <- c("bootstrap", "subsampling", "cv", "noise")
              method_results <- list()
              
              for (method in methods) {
                # Simplified implementation - run each method with fewer iterations
                method_iterations <- max(25, floor(rf_stability_iterations / length(methods)))
                # ... (implementation would be similar to above but for each method)
                # For now, use the bootstrap results as placeholder
                method_results[[method]] <- stability_scores
              }
              
              # Calculate consensus
              consensus_scores <- rowMeans(do.call(cbind, method_results), na.rm = TRUE)
              consensus_features <- which(consensus_scores >= consensus_threshold)
              
              cat("Consensus features (>=", consensus_threshold * 100, "% agreement):", length(consensus_features), "\n")
              
              if (use_consensus && length(consensus_features) > 0) {
                stable_features <- consensus_features
                stability_scores <- consensus_scores
              }
            }
            
            # Store stability results
            values$ml_rf_stability_scores <- stability_scores
            values$ml_rf_stability_features <- stable_features
            values$ml_rf_stability_method <- rf_stability_method
            
            # Continue with final RF model using selected features if stability filtering is effective
            if (length(stable_features) > 0 && length(stable_features) < ncol(X)) {
              cat("Using", length(stable_features), "stable features for final RF model\n")
              X <- X[, stable_features, drop = FALSE]
              feature_names <- feature_names[stable_features]
              
              # Also subset train/test data if train/test split is enabled
              if (!is.null(values$ml_train_X) && !is.null(values$ml_test_X)) {
                cat("Subsetting train/test data to match stable features\n")
                values$ml_train_X <- values$ml_train_X[, stable_features, drop = FALSE]
                values$ml_test_X <- values$ml_test_X[, stable_features, drop = FALSE]
                cat("Train/test data subsetted to", ncol(values$ml_train_X), "features\n")
              }
              
              showNotification(paste("Stability analysis complete:", length(stable_features),
                                     "stable features selected using", rf_stability_method, "method"),
                               type = "message", duration = 5)
            } else {
              cat("Stability analysis did not reduce feature set. Using all features.\n")
              showNotification("Stability analysis complete. All features retained due to high stability.",
                               type = "message", duration = 3)
            }
          }
          
          # Standard Random Forest implementation
          cat("=== Standard Random Forest Implementation ===\n")
          
          cat("=== Enhanced Random Forest Debug ===\n")
          cat("Data dimensions:", dim(X), "\n")
          cat("Response levels:", if(is.factor(y)) levels(y) else "numeric", "\n")
          cat("ntree:", rf_ntree, "mtry:", rf_mtry, "nodesize:", rf_nodesize, "\n")
          cat("Proximity:", calc_proximity, "Local Importance:", calc_local_imp, "\n")
          
          # Class imbalance detection and weighting for Random Forest
          rf_classwt <- NULL
          rf_sampsize <- NULL
          
          if (is.factor(y)) {
            imbalance_info <- detect_class_imbalance(y, threshold = 0.1)
            
            if (imbalance_info$is_imbalanced) {
              cat("=== Random Forest Class Imbalance Detected ===\n")
              cat("Class counts:", paste(names(imbalance_info$class_counts),
                                         imbalance_info$class_counts, sep = ":", collapse = ", "), "\n")
              cat("Imbalance ratio:", round(imbalance_info$imbalance_ratio, 3), "\n")
              
              if (!isTRUE(input$rf_use_class_weights) && !isTRUE(input$rf_use_balanced_sampling)) {
                # Notify user about imbalance and suggest using weights or sampling
                showNotification(
                  paste("Class imbalance detected in Random Forest! Minority class:",
                        imbalance_info$minority_class, "(",
                        round(imbalance_info$class_proportions[imbalance_info$minority_class] * 100, 1),
                        "%). Consider enabling 'Use Class Weights' or 'Use Balanced Sampling' for better results."),
                  type = "warning",
                  duration = 8
                )
              }
              
              # Apply class weights if enabled
              if (isTRUE(input$rf_use_class_weights)) {
                weight_method <- input$rf_weight_method %||% "balanced"
                custom_weights <- NULL
                
                if (weight_method == "custom" && !is.null(input$rf_custom_weights) &&
                    nchar(input$rf_custom_weights) > 0) {
                  tryCatch({
                    custom_weights <- as.numeric(strsplit(input$rf_custom_weights, ",")[[1]])
                    if (length(custom_weights) != length(unique(y))) {
                      showNotification("Custom weights count doesn't match number of classes. Using balanced weights.",
                                       type = "warning")
                      custom_weights <- NULL
                      weight_method <- "balanced"
                    }
                  }, error = function(e) {
                    showNotification("Invalid custom weights format. Using balanced weights.", type = "warning")
                    custom_weights <- NULL
                    weight_method <- "balanced"
                  })
                }
                
                rf_classwt <- calculate_class_weights(y, method = weight_method, custom_weights = custom_weights)
                
                cat("Using class weights with method:", weight_method, "\n")
                cat("Class weights:", paste(names(rf_classwt), round(rf_classwt, 3), sep = ":", collapse = ", "), "\n")
                
                showNotification(
                  paste("Applied", weight_method, "class weights to Random Forest for imbalance handling."),
                  type = "message",
                  duration = 5
                )
              }
              
              # Apply balanced sampling if enabled
              if (isTRUE(input$rf_use_balanced_sampling)) {
                min_samples <- input$rf_min_samples_per_class %||% 50
                rf_sampsize <- calculate_balanced_sampsize(y, min_samples)
                
                cat("Using balanced sampling with sampsize:", paste(names(rf_sampsize), rf_sampsize, sep = ":", collapse = ", "), "\n")
                
                showNotification(
                  paste("Applied balanced sampling to Random Forest. Samples per class:", paste(rf_sampsize, collapse = ", ")),
                  type = "message",
                  duration = 5
                )
              }
            }
          }
          
          # Build Random Forest model with comprehensive parameters
          rf_args <- list(
            x = X,
            y = y,
            ntree = rf_ntree,
            mtry = rf_mtry,
            nodesize = rf_nodesize,
            maxnodes = rf_maxnodes,
            importance = TRUE,
            localImp = calc_local_imp,
            proximity = calc_proximity,
            keep.forest = TRUE,
            keep.inbag = TRUE,
            do.trace = FALSE
          )
          
          # Add class weighting if available
          if (!is.null(rf_classwt)) {
            rf_args$classwt <- rf_classwt
          }
          
          # Add balanced sampling if available
          if (!is.null(rf_sampsize)) {
            rf_args$sampsize <- rf_sampsize
          }
          
          rf_fit <- do.call(randomForest::randomForest, rf_args)
          
          cat("Random Forest training completed successfully\n")
          
          # Extract variable importance with multiple measures
          rf_imp <- randomForest::importance(rf_fit, scale = TRUE)
          
          # Handle different importance matrix structures
          if (is.factor(y)) {
            # Classification - multiple importance measures available
            importance_measures <- list()
            
            if ("MeanDecreaseAccuracy" %in% colnames(rf_imp)) {
              importance_measures$MeanDecreaseAccuracy <- rf_imp[, "MeanDecreaseAccuracy"]
            }
            if ("MeanDecreaseGini" %in% colnames(rf_imp)) {
              importance_measures$MeanDecreaseGini <- rf_imp[, "MeanDecreaseGini"]
            }
            
            # Use MeanDecreaseAccuracy as primary measure if available, otherwise Gini
            if (length(importance_measures$MeanDecreaseAccuracy) > 0) {
              primary_importance <- importance_measures$MeanDecreaseAccuracy
              primary_measure <- "MeanDecreaseAccuracy"
            } else if (length(importance_measures$MeanDecreaseGini) > 0) {
              primary_importance <- importance_measures$MeanDecreaseGini
              primary_measure <- "MeanDecreaseGini"
            } else {
              primary_importance <- rf_imp[, ncol(rf_imp)]
              primary_measure <- "Importance"
            }
          } else {
            # Regression - typically has %IncMSE and IncNodePurity
            if (ncol(rf_imp) > 1) {
              if ("%IncMSE" %in% colnames(rf_imp)) {
                primary_importance <- rf_imp[, "%IncMSE"]
                primary_measure <- "%IncMSE"
              } else {
                primary_importance <- rf_imp[, 1]
                primary_measure <- colnames(rf_imp)[1]
              }
            } else {
              primary_importance <- rf_imp[, 1]
              primary_measure <- "Importance"
            }
          }
          
          # Create comprehensive importance data frame
          importance_df <- data.frame(
            Feature = names(primary_importance),
            Importance = as.numeric(primary_importance),
            Measure = primary_measure,
            stringsAsFactors = FALSE
          )
          
          # Add additional importance measures if available
          if (is.factor(y) && ncol(rf_imp) > 2) {
            for (measure_name in colnames(rf_imp)) {
              if (!measure_name %in% c("MeanDecreaseAccuracy", "MeanDecreaseGini")) next
              if (measure_name != primary_measure) {
                importance_df[[measure_name]] <- as.numeric(rf_imp[, measure_name])
              }
            }
          }
          
          # Sort by primary importance
          importance_df <- importance_df[order(-importance_df$Importance), ]
          
          # Select top features
          n_show <- min(n_features, nrow(importance_df))
          selected_features <- importance_df[1:n_show, ]
          
          # Calculate comprehensive performance metrics
          if (is.factor(y)) {
            # Classification metrics
            oob_error <- rf_fit$err.rate[nrow(rf_fit$err.rate), "OOB"]
            conf_matrix <- rf_fit$confusion
            
            performance_text <- paste0(
              "Classification Performance:\n",
              "  OOB Error Rate: ", round(oob_error * 100, 2), "%\n",
              "  OOB Accuracy: ", round((1 - oob_error) * 100, 2), "%\n",
              "  Number of Classes: ", length(levels(y)), "\n",
              "  Primary Importance Measure: ", primary_measure
            )
            
            # Add class imbalance handling information
            if (!is.null(rf_classwt) || !is.null(rf_sampsize)) {
              imbalance_text <- "\n\nClass Imbalance Handling:"
              if (!is.null(rf_classwt)) {
                imbalance_text <- paste0(imbalance_text, "\n  Class Weights Applied: ",
                                         paste(paste0(names(rf_classwt), "=", round(rf_classwt, 2)), collapse = ", "))
              }
              if (!is.null(rf_sampsize)) {
                imbalance_text <- paste0(imbalance_text, "\n  Balanced Sampling Used: ",
                                         paste(paste0(names(rf_sampsize), "=", rf_sampsize), collapse = ", "))
              }
              performance_text <- paste0(performance_text, imbalance_text)
            }
            
            # Add class-specific error rates if available
            if (!is.null(conf_matrix)) {
              class_errors <- diag(conf_matrix) / rowSums(conf_matrix[, -ncol(conf_matrix)])
              class_error_text <- paste0(
                "  Class Error Rates: ",
                paste(paste0(levels(y), ": ", round((1-class_errors) * 100, 1), "%"), collapse = ", ")
              )
              performance_text <- paste(performance_text, class_error_text, sep = "\n")
            }
          } else {
            # Regression metrics
            mse <- rf_fit$mse[length(rf_fit$mse)]
            rsq <- rf_fit$rsq[length(rf_fit$rsq)]
            
            performance_text <- paste0(
              "Regression Performance:\n",
              "  Mean Squared Error: ", round(mse, 4), "\n",
              "  Pseudo R-squared: ", round(rsq, 4), "\n",
              "  Primary Importance Measure: ", primary_measure
            )
          }
          
          # Store comprehensive results
          values$ml_selected_features <- map_numeric_ids_to_names(selected_features)
          values$ml_importance <- map_numeric_ids_to_names(importance_df)
          
          # Add stability analysis information to performance text if available
          if (!is.null(values$ml_rf_stability_method) && !is.null(values$ml_rf_stability_scores)) {
            stability_info <- paste0(
              "\n\nStability Analysis Results:",
              "\n  Method: ", values$ml_rf_stability_method,
              "\n  Stable Features: ", length(values$ml_rf_stability_features), " / ", length(values$ml_rf_stability_scores),
              "\n  Average Stability: ", round(mean(values$ml_rf_stability_scores, na.rm = TRUE), 3),
              "\n  Max Stability: ", round(max(values$ml_rf_stability_scores, na.rm = TRUE), 3)
            )
            performance_text <- paste0(performance_text, stability_info)
          }
          
          values$ml_performance <- performance_text
          
          # Store the Random Forest model and additional info for advanced plots
          values$ml_rf_fit <- rf_fit
          values$ml_rf_X <- X
          values$ml_rf_y <- y
          values$ml_rf_importance_full <- rf_imp
          values$ml_rf_type <- if(is.factor(y)) "classification" else "regression"
          
          # Calculate train/test performance if split was enabled
          if (!is.null(values$ml_train_X) && !is.null(values$ml_test_X)) {
            cat("Calculating train/test performance for Random Forest...\n")
            
            # Source validation functions if not already loaded
            validation_file <- "ml_validation_functions.R"
            if (file.exists(validation_file)) {
              tryCatch({
                source(validation_file)
                cat("Validation functions sourced successfully\n")
              }, error = function(e) {
                cat("Error sourcing validation functions:", e$message, "\n")
              })
            }
            
            # Get predictions on training and test sets
            tryCatch({
              # Ensure train/test data column names match the model's training data
              cat("Verifying feature alignment between model and test data...\n")
              cat("Model features:", ncol(X), "features:", paste(head(colnames(X), 5), collapse=", "), "...\n")
              cat("Train data features:", ncol(values$ml_train_X), "features:", paste(head(colnames(values$ml_train_X), 5), collapse=", "), "...\n")
              cat("Test data features:", ncol(values$ml_test_X), "features:", paste(head(colnames(values$ml_test_X), 5), collapse=", "), "...\n")
              
              # Check if column names match
              model_features <- colnames(X)
              train_features <- colnames(values$ml_train_X)
              test_features <- colnames(values$ml_test_X)
              
              # If features don't match, subset to common features
              if (!identical(model_features, train_features)) {
                cat("WARNING: Train data features don't match model features. Subsetting...\n")
                # Find common features in same order as model
                common_features <- intersect(model_features, train_features)
                if (length(common_features) == length(model_features)) {
                  values$ml_train_X <- values$ml_train_X[, model_features, drop = FALSE]
                  cat("Train data aligned to", length(model_features), "model features\n")
                } else {
                  stop("Feature mismatch between model and train data. Model has ", length(model_features),
                       " features but only ", length(common_features), " match train data.")
                }
              }
              
              if (!identical(model_features, test_features)) {
                cat("WARNING: Test data features don't match model features. Subsetting...\n")
                # Find common features in same order as model
                common_features <- intersect(model_features, test_features)
                if (length(common_features) == length(model_features)) {
                  values$ml_test_X <- values$ml_test_X[, model_features, drop = FALSE]
                  cat("Test data aligned to", length(model_features), "model features\n")
                } else {
                  stop("Feature mismatch between model and test data. Model has ", length(model_features),
                       " features but only ", length(common_features), " match test data.")
                }
              }
              
              # Determine problem type
              is_classification <- is.factor(values$ml_train_y)
              is_binary <- is_classification && length(levels(values$ml_train_y)) == 2
              is_multiclass <- is_classification && length(levels(values$ml_train_y)) > 2
              
              cat("Problem type - Classification:", is_classification,
                  "Binary:", is_binary, "Multiclass:", is_multiclass, "\n")
              
              # Get predictions
              train_pred <- predict(rf_fit, newdata = values$ml_train_X, type = ifelse(is_classification, "class", "response"))
              test_pred <- predict(rf_fit, newdata = values$ml_test_X, type = ifelse(is_classification, "class", "response"))
              
              # Get probability predictions for classification
              train_prob <- NULL
              test_prob <- NULL
              if (is_classification) {
                train_prob <- predict(rf_fit, newdata = values$ml_train_X, type = "prob")
                test_prob <- predict(rf_fit, newdata = values$ml_test_X, type = "prob")
              }
              
              cat("Training predictions obtained:", length(train_pred), "samples\n")
              cat("Test predictions obtained:", length(test_pred), "samples\n")
              
              # Calculate metrics based on problem type
              if (is_binary && exists("calculate_binary_metrics")) {
                cat("Calculating binary classification metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_binary_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y
                )
                
                # Test metrics
                test_metrics <- calculate_binary_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Binary classification metrics calculated and stored\n")
                
              } else if (is_multiclass && exists("calculate_multiclass_metrics")) {
                cat("Calculating multiclass classification metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_multiclass_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y
                )
                
                # Test metrics
                test_metrics <- calculate_multiclass_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Multiclass classification metrics calculated and stored\n")
                
              } else if (!is_classification && exists("calculate_regression_metrics")) {
                cat("Calculating regression metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_regression_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y
                )
                
                # Test metrics
                test_metrics <- calculate_regression_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Regression metrics calculated and stored\n")
                
              } else {
                cat("Validation functions not available, calculating basic metrics...\n")
                # Fallback: Calculate basic metrics without validation functions
                if (is_classification) {
                  train_acc <- sum(train_pred == values$ml_train_y) / length(values$ml_train_y)
                  test_acc <- sum(test_pred == values$ml_test_y) / length(values$ml_test_y)
                  
                  values$ml_train_performance <- list(
                    accuracy = train_acc,
                    n_samples = length(values$ml_train_y)
                  )
                  values$ml_test_performance <- list(
                    accuracy = test_acc,
                    n_samples = length(values$ml_test_y)
                  )
                } else {
                  train_rmse <- sqrt(mean((values$ml_train_y - train_pred)^2))
                  test_rmse <- sqrt(mean((values$ml_test_y - test_pred)^2))
                  
                  values$ml_train_performance <- list(
                    rmse = train_rmse,
                    n_samples = length(values$ml_train_y)
                  )
                  values$ml_test_performance <- list(
                    rmse = test_rmse,
                    n_samples = length(values$ml_test_y)
                  )
                }
                cat("Basic metrics calculated and stored\n")
              }
              
            }, error = function(e) {
              cat("Error calculating performance metrics:", e$message, "\n")
              values$ml_train_performance <- list(error = e$message)
              values$ml_test_performance <- list(error = e$message)
            })
          } else {
            cat("Train/test split not enabled, skipping performance calculation\n")
          }
          
          # Store proximity matrix if calculated
          if (calc_proximity && !is.null(rf_fit$proximity)) {
            values$ml_rf_proximity <- rf_fit$proximity
            cat("Proximity matrix stored:", dim(rf_fit$proximity), "\n")
          }
          
          # Store local importance if calculated
          if (calc_local_imp && !is.null(rf_fit$localImp)) {
            values$ml_rf_local_importance <- rf_fit$localImp
            cat("Local importance stored:", dim(rf_fit$localImp), "\n")
          }
          
          # Store variable usage information
          var_used <- randomForest::varUsed(rf_fit, count = TRUE)
          # Ensure names exist; if missing, assign from X
          if (is.null(names(var_used)) || any(names(var_used) == "")) {
            names(var_used) <- colnames(X)
          }
          # Map numeric / generic names to cleaned molecules
          if (!is.null(values$cleaned_molecules)) {
            name_vec <- names(var_used)
            suppressWarnings({
              idx1 <- as.integer(sub("^Feature_", "", name_vec))
              idx2 <- ifelse(grepl("^[0-9]+$", name_vec), as.integer(name_vec), NA)
              idx <- ifelse(!is.na(idx1), idx1, idx2)
              valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
              name_vec[valid] <- values$cleaned_molecules[idx[valid]]
            })
            names(var_used) <- name_vec
          }
          values$ml_rf_var_used <- var_used
          
          # Store tree size information
          tree_sizes <- randomForest::treesize(rf_fit)
          values$ml_rf_tree_sizes <- tree_sizes
          
          showNotification(paste0("Enhanced Random Forest completed! Selected ",
                                  nrow(selected_features), " features using ",
                                  primary_measure, " measure."), type = "message")
          # Post-process RF names
          if (!is.null(values$ml_importance) && !is.null(values$cleaned_molecules)) {
            name_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_importance))[1]
            if (!is.null(name_col)) {
              current_names <- values$ml_importance[[name_col]]
              # If importance length matches cleaned molecules and names are generic
              if (length(current_names) == length(values$cleaned_molecules) && all(grepl("^Feature_[0-9]+$", current_names))) {
                # Map order by matching current generic index numbers
                # Extract numeric index from Feature_ pattern
                idx <- as.integer(sub("Feature_", "", current_names))
                if (all(!is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
                  values$ml_importance[[name_col]] <- values$cleaned_molecules[idx]
                  if (!is.null(values$ml_selected_features)) {
                    sel_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_selected_features))[1]
                    if (!is.null(sel_col)) {
                      sel_idx <- as.integer(sub("Feature_", "", values$ml_selected_features[[sel_col]]))
                      if (all(!is.na(sel_idx)) && max(sel_idx) <= length(values$cleaned_molecules)) {
                        values$ml_selected_features[[sel_col]] <- values$cleaned_molecules[sel_idx]
                      }
                    }
                  }
                }
              }
            }
          }
          
        }, error = function(e) {
          cat("Enhanced Random Forest error:", e$message, "\n")
          showNotification(paste("Enhanced Random Forest error:", e$message), type = "error")
          
          # Create empty results on error
          empty_result <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_selected_features <- empty_result
          values$ml_importance <- empty_result
          values$ml_performance <- paste("Random Forest error:", e$message)
          
          # Clear RF-specific stored values
          values$ml_rf_fit <- NULL
          values$ml_rf_X <- NULL
          values$ml_rf_y <- NULL
          values$ml_rf_importance_full <- NULL
          values$ml_rf_proximity <- NULL
          values$ml_rf_local_importance <- NULL
          values$ml_rf_var_used <- NULL
          values$ml_rf_tree_sizes <- NULL
          values$ml_rf_stability_scores <- NULL
          values$ml_rf_stability_features <- NULL
          values$ml_rf_stability_method <- NULL
        })
      } else if (input$feature_selection_method == "permutation") {
        # Permutation Importance using randomForest and iml
        if (!requireNamespace("iml", quietly = TRUE)) install.packages("iml")
        if (!requireNamespace("randomForest", quietly = TRUE)) install.packages("randomForest")
        
        tryCatch({
          # Get user-configurable parameters or use defaults
          perm_ntree <- input$perm_ntree %||% 500
          perm_mtry <- if (is.na(input$perm_mtry) || is.null(input$perm_mtry)) {
            if (input$perm_family %||% "binary" == "regression") floor(ncol(X)/3) else floor(sqrt(ncol(X)))
          } else {
            input$perm_mtry
          }
          perm_nodesize <- if (is.na(input$perm_nodesize) || is.null(input$perm_nodesize)) {
            if (input$perm_family %||% "binary" == "regression") 5 else 1
          } else {
            input$perm_nodesize
          }
          perm_maxnodes <- if (is.na(input$perm_maxnodes) || is.null(input$perm_maxnodes)) NULL else input$perm_maxnodes
          
          # Handle class weights if specified
          perm_classwt <- NULL
          if (input$perm_use_class_weights %||% FALSE) {
            if (input$perm_weight_method %||% "balanced" == "balanced") {
              # Calculate balanced class weights (inverse frequency)
              class_freq <- table(y)
              total_samples <- length(y)
              n_classes <- length(class_freq)
              perm_classwt <- setNames(total_samples / (n_classes * class_freq), names(class_freq))
            } else if (input$perm_weight_method == "custom" && !is.null(input$perm_custom_weights) && nzchar(input$perm_custom_weights)) {
              # Parse custom weights
              weights_str <- trimws(unlist(strsplit(input$perm_custom_weights, ",")))
              if (length(weights_str) == length(levels(y))) {
                perm_classwt <- setNames(as.numeric(weights_str), levels(y))
              }
            }
          }
          
          # Parallel processing setup
          use_parallel <- input$perm_use_parallel %||% TRUE
          n_cores <- if (use_parallel) {
            if (is.na(input$perm_n_cores) || is.null(input$perm_n_cores)) {
              max(1, parallel::detectCores() - 1)
            } else {
              input$perm_n_cores
            }
          } else {
            1
          }
          
          cat("Debug Permutation: X dims:", dim(X), "y length:", length(y), "\n")
          cat("Debug Permutation: Using ntree =", perm_ntree, "mtry =", perm_mtry, "nodesize =", perm_nodesize, "\n")
          if (!is.null(perm_classwt)) {
            cat("Debug Permutation: Class weights:", paste(names(perm_classwt), "=", round(perm_classwt, 3), collapse = ", "), "\n")
          }
          
          # Create data frame with consistent column names BEFORE training
          X_df <- as.data.frame(X)
          # Ensure column names are valid R names (no special characters)
          valid_names <- make.names(colnames(X_df), unique = TRUE)
          colnames(X_df) <- valid_names
          
          cat("Debug Permutation: Original colnames (first 5):", paste(head(colnames(X), 5), collapse = ", "), "\n")
          cat("Debug Permutation: Valid colnames (first 5):", paste(head(valid_names, 5), collapse = ", "), "\n")
          
          # Train Random Forest model using the data frame with consistent column names
          rf_args <- list(
            x = X_df,  # Use X_df instead of X for consistency
            y = y,
            ntree = perm_ntree,
            mtry = perm_mtry,
            nodesize = perm_nodesize,
            importance = TRUE
          )
          
          if (!is.null(perm_maxnodes)) rf_args$maxnodes <- perm_maxnodes
          if (!is.null(perm_classwt)) rf_args$classwt <- perm_classwt
          
          rf <- do.call(randomForest::randomForest, rf_args)
          
          # Store the RF model for permutation importance
          values$ml_perm_rf <- rf
          values$ml_perm_X_df <- X_df  # Store the data frame with valid column names
          
          # Calculate train/test performance if split was enabled
          if (!is.null(values$ml_train_X) && !is.null(values$ml_test_X)) {
            cat("Calculating train/test performance for Permutation Importance...\n")
            
            # Source validation functions if not already loaded
            validation_file <- "ml_validation_functions.R"
            if (file.exists(validation_file)) {
              tryCatch({
                source(validation_file)
                cat("Validation functions sourced successfully\n")
              }, error = function(e) {
                cat("Error sourcing validation functions:", e$message, "\n")
              })
            }
            
            # Get predictions on training and test sets
            tryCatch({
              # Prepare train and test data with same column names as training
              train_X_df <- as.data.frame(values$ml_train_X)
              test_X_df <- as.data.frame(values$ml_test_X)
              colnames(train_X_df) <- valid_names
              colnames(test_X_df) <- valid_names
              
              # Determine problem type
              is_classification <- is.factor(values$ml_train_y)
              is_binary <- is_classification && length(levels(values$ml_train_y)) == 2
              is_multiclass <- is_classification && length(levels(values$ml_train_y)) > 2
              
              cat("Problem type - Classification:", is_classification,
                  "Binary:", is_binary, "Multiclass:", is_multiclass, "\n")
              
              # Get predictions
              train_pred <- predict(rf, newdata = train_X_df, type = ifelse(is_classification, "class", "response"))
              test_pred <- predict(rf, newdata = test_X_df, type = ifelse(is_classification, "class", "response"))
              
              # Get probability predictions for classification
              train_prob <- NULL
              test_prob <- NULL
              if (is_classification) {
                train_prob <- predict(rf, newdata = train_X_df, type = "prob")
                test_prob <- predict(rf, newdata = test_X_df, type = "prob")
              }
              
              cat("Training predictions obtained:", length(train_pred), "samples\n")
              cat("Test predictions obtained:", length(test_pred), "samples\n")
              
              # Calculate metrics based on problem type
              if (is_binary && exists("calculate_binary_metrics")) {
                cat("Calculating binary classification metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_binary_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y,
                )
                
                # Test metrics
                test_metrics <- calculate_binary_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y,
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Binary classification metrics calculated and stored\n")
                
              } else if (is_multiclass && exists("calculate_multiclass_metrics")) {
                cat("Calculating multiclass classification metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_multiclass_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y,
                )
                
                # Test metrics
                test_metrics <- calculate_multiclass_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y,
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Multiclass classification metrics calculated and stored\n")
                
              } else if (!is_classification && exists("calculate_regression_metrics")) {
                cat("Calculating regression metrics...\n")
                
                # Training metrics
                train_metrics <- calculate_regression_metrics(
                  predictions = train_pred,
                  actual = values$ml_train_y
                )
                
                # Test metrics
                test_metrics <- calculate_regression_metrics(
                  predictions = test_pred,
                  actual = values$ml_test_y
                )
                
                values$ml_train_performance <- train_metrics
                values$ml_test_performance <- test_metrics
                cat("Regression metrics calculated and stored\n")
                
              } else {
                cat("Validation functions not available, calculating basic metrics...\n")
                # Fallback: Calculate basic metrics without validation functions
                if (is_classification) {
                  train_acc <- sum(train_pred == values$ml_train_y) / length(values$ml_train_y)
                  test_acc <- sum(test_pred == values$ml_test_y) / length(values$ml_test_y)
                  
                  values$ml_train_performance <- list(
                    accuracy = train_acc,
                    n_samples = length(values$ml_train_y)
                  )
                  values$ml_test_performance <- list(
                    accuracy = test_acc,
                    n_samples = length(values$ml_test_y)
                  )
                } else {
                  train_rmse <- sqrt(mean((values$ml_train_y - train_pred)^2))
                  test_rmse <- sqrt(mean((values$ml_test_y - test_pred)^2))
                  
                  values$ml_train_performance <- list(
                    rmse = train_rmse,
                    n_samples = length(values$ml_train_y)
                  )
                  values$ml_test_performance <- list(
                    rmse = test_rmse,
                    n_samples = length(values$ml_test_y)
                  )
                }
                cat("Basic metrics calculated and stored\n")
              }
              
            }, error = function(e) {
              cat("Error calculating performance metrics:", e$message, "\n")
              values$ml_train_performance <- list(error = e$message)
              values$ml_test_performance <- list(error = e$message)
            })
          } else {
            cat("Train/test split not enabled, skipping performance calculation\n")
          }
          
          # Create predictor object with consistent data structure
          predictor <- iml::Predictor$new(
            model = rf,
            data = X_df,
            y = as.character(y),  # Convert factor to character for iml
            type = "prob"
          )
          
          cat("Debug Permutation: Predictor created successfully with", ncol(X_df), "features\n")
          cat("Debug Permutation: Data types - X_df:", class(X_df), ", y:", class(y), "\n")
          
          # Calculate permutation importance using user-specified parameters
          n_permutations <- input$feature_selection_permutation_n %||% 100
          loss_function <- input$perm_loss_function %||% "ce"
          
          # Validate loss function for problem type
          if (input$perm_family %||% "binary" == "regression" && loss_function == "ce") {
            loss_function <- "mse"
            showNotification("Switched to MSE loss for regression problem", type = "message")
          }
          
          cat("Debug Permutation: Using", n_permutations, "permutations with", loss_function, "loss function\n")
          
          # Set up parallel processing if requested
          if (use_parallel && n_cores > 1) {
            # Set up parallel backend for iml package
            if (!requireNamespace("parallel", quietly = TRUE)) install.packages("parallel")
            if (!requireNamespace("doParallel", quietly = TRUE)) install.packages("doParallel")
            
            tryCatch({
              library(doParallel)
              cl <- makeCluster(n_cores)
              registerDoParallel(cl)
              cat("Debug Permutation: Parallel processing enabled with", n_cores, "cores\n")
              
              # Use cross-entropy loss for classification (most reliable with iml package)
              perm <- iml::FeatureImp$new(
                predictor,
                loss = loss_function,
                n.repetitions = n_permutations
              )
              imp_results <- perm$results
              
              # Clean up parallel backend
              stopCluster(cl)
              registerDoSEQ()
              
            }, error = function(e) {
              cat("Warning: Parallel processing failed, falling back to sequential:", e$message, "\n")
              # Fallback to sequential processing
              perm <- iml::FeatureImp$new(
                predictor,
                loss = loss_function,
                n.repetitions = n_permutations
              )
              imp_results <- perm$results
            })
          } else {
            # Sequential processing
            perm <- iml::FeatureImp$new(
              predictor,
              loss = loss_function,
              n.repetitions = n_permutations
            )
            imp_results <- perm$results
          }
          
          # Extract importance values
          importance <- setNames(imp_results$importance, imp_results$feature)
          importance <- sort(importance, decreasing = TRUE)
          
          # Select top features
          selected <- names(importance)[1:min(n_features, length(importance))]
          fs_result <- data.frame(Feature = names(importance), Importance = importance, stringsAsFactors = FALSE)
          
          # Create comprehensive performance summary
          oob_error <- rf$err.rate[nrow(rf$err.rate), "OOB"]
          performance_text <- paste0(
            "Permutation Importance Analysis Completed:\n",
            "  Base Model: Random Forest (", perm_ntree, " trees, mtry=", perm_mtry, ")\n",
            "  OOB Error Rate: ", round(oob_error * 100, 2), "%\n",
            "  Permutations: ", n_permutations, " (", loss_function, " loss)\n",
            "  Features Analyzed: ", nrow(fs_result), "\n",
            "  Features Selected: ", length(selected)
          )
          
          if (!is.null(perm_classwt)) {
            performance_text <- paste0(performance_text, "\n  Class Weights Applied: ",
                                       paste(paste0(names(perm_classwt), "=", round(perm_classwt, 2)), collapse = ", "))
          }
          
          if (use_parallel) {
            performance_text <- paste0(performance_text, "\n  Parallel Processing: ", n_cores, " cores")
          }
          
          # Store results
          values$ml_selected_features <- map_numeric_ids_to_names(fs_result[fs_result$Feature %in% selected, , drop = FALSE])
          values$ml_importance <- map_numeric_ids_to_names(fs_result)
          values$ml_performance <- performance_text
          showNotification("Permutation importance completed successfully!", type = "message")  }, error = function(e) {
            # Post-process permutation names
            if (!is.null(values$ml_importance) && !is.null(values$cleaned_molecules)) {
              name_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_importance))[1]
              if (!is.null(name_col)) {
                current_names <- values$ml_importance[[name_col]]
                if (length(current_names) == length(values$cleaned_molecules) && all(grepl("^Feature_[0-9]+$", current_names))) {
                  idx <- as.integer(sub("Feature_", "", current_names))
                  if (all(!is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
                    values$ml_importance[[name_col]] <- values$cleaned_molecules[idx]
                  }
                }
              }
            }
            cat("Permutation importance error:", e$message, "\n")
            # Try a simpler permutation importance approach without iml package
            tryCatch({
              cat("Attempting manual permutation importance calculation...\n")
              
              # Get baseline accuracy using the same data format as training
              baseline_pred <- predict(rf, X_df)
              baseline_accuracy <- mean(baseline_pred == y)
              
              # Calculate permutation importance manually
              perm_importance <- numeric(ncol(X_df))
              names(perm_importance) <- colnames(X_df)
              
              for (i in 1:min(ncol(X_df), 50)) {  # Limit to first 50 features for speed
                # Create permuted version of feature i
                X_perm <- X_df
                X_perm[, i] <- sample(X_perm[, i])
                
                # Get predictions with permuted feature
                perm_pred <- predict(rf, X_perm)
                perm_accuracy <- mean(perm_pred == y)
                
                # Importance is the decrease in accuracy
                perm_importance[i] <- baseline_accuracy - perm_accuracy
              }
              
              # Sort by importance
              importance <- sort(perm_importance, decreasing = TRUE)
              selected <- names(importance)[1:min(n_features, length(importance))]
              fs_result <- data.frame(Feature = names(importance), Importance = importance, stringsAsFactors = FALSE)
              
              values$ml_selected_features <- map_numeric_ids_to_names(fs_result[fs_result$Feature %in% selected, , drop = FALSE])
              values$ml_importance <- map_numeric_ids_to_names(fs_result)
              values$ml_performance <- paste("Manual Permutation Importance completed with", length(importance), "features")
              showNotification("Manual permutation importance completed successfully!", type = "message")
              
            }, error = function(e2) {
              showNotification(paste("Permutation importance error:", e$message, "; Manual fallback error:", e2$message), type = "error")
              values$ml_selected_features <- data.frame(Feature = character(0), Importance = numeric(0))
              values$ml_importance <- data.frame(Feature = character(0), Importance = numeric(0))
              values$ml_performance <- paste("Permutation importance error:", e$message)
            })
          })
      } else if (input$feature_selection_method == "boruta") {
        if (!requireNamespace("Boruta", quietly = TRUE)) install.packages("Boruta")
        if (!requireNamespace("ranger", quietly = TRUE)) install.packages("ranger")
        
        tryCatch({
          # Extract Boruta parameters from UI
          boruta_max_runs <- input$feature_selection_boruta_max_runs %||% 100
          boruta_p_value <- input$feature_selection_boruta_p_value %||% 0.01
          boruta_importance_source <- input$feature_selection_boruta_importance_source %||% "getImpRfZ"
          boruta_classifier <- input$feature_selection_boruta_classifier %||% "ranger"
          boruta_tentative_fix <- input$feature_selection_boruta_tentative_fix %||% TRUE
          boruta_ntree <- input$feature_selection_boruta_ntree %||% 500
          boruta_do_trace <- if(input$feature_selection_boruta_do_trace %||% FALSE) 2 else 0
          
          # Classifier-specific parameters
          boruta_gbm_trees <- input$feature_selection_boruta_gbm_trees %||% 100
          boruta_xgb_rounds <- input$feature_selection_boruta_xgb_rounds %||% 100
          
          cat("Debug Boruta: X dimensions:", dim(X), "y levels:", levels(y), "\n")
          cat("Debug Boruta: Parameters - classifier:", boruta_classifier, "maxRuns:", boruta_max_runs,
              "pValue:", boruta_p_value, "importance:", boruta_importance_source, "\n")
          
          # Check if we have binary or multiclass data
          n_classes <- length(levels(y))
          cat("Debug Boruta: Number of classes:", n_classes, "\n")
          
          if (n_classes > 2) {
            # For multiclass, use the selected classifier for importance instead of Boruta
            showNotification(paste("Multiclass detected. Using", boruta_classifier, "importance instead of Boruta for feature selection."), type = "message")
            
            # Use selected classifier for multiclass
            if (boruta_classifier == "ranger") {
              rf_fit <- ranger::ranger(x = X, y = y, num.trees = boruta_ntree, importance = "impurity")
              importance_values <- rf_fit$variable.importance
            } else if (boruta_classifier == "randomForest") {
              rf_fit <- randomForest::randomForest(x = X, y = y, ntree = boruta_ntree, importance = TRUE)
              rf_imp <- randomForest::importance(rf_fit)
              if (ncol(rf_imp) > 1) {
                if ("MeanDecreaseAccuracy" %in% colnames(rf_imp)) {
                  importance_values <- rf_imp[, "MeanDecreaseAccuracy"]
                } else {
                  importance_values <- rf_imp[, ncol(rf_imp)]
                }
              } else {
                importance_values <- rf_imp[, 1]
              }
            } else {
              # Fallback to randomForest for other classifiers in multiclass
              rf_fit <- randomForest::randomForest(x = X, y = y, ntree = boruta_ntree, importance = TRUE)
              rf_imp <- randomForest::importance(rf_fit)
              importance_values <- if (ncol(rf_imp) > 1 && "MeanDecreaseAccuracy" %in% colnames(rf_imp)) {
                rf_imp[, "MeanDecreaseAccuracy"]
              } else {
                rf_imp[, ncol(rf_imp)]
              }
            }
            
            # Sort by importance
            importance_sorted <- sort(importance_values, decreasing = TRUE)
            
            # Create results
            fs_result <- data.frame(
              Feature = names(importance_sorted),
              Importance = as.numeric(importance_sorted),
              stringsAsFactors = FALSE
            )
            
            n_selected <- min(n_features, nrow(fs_result))
            selected_result <- fs_result[1:n_selected, , drop = FALSE]
            perf <- paste(boruta_classifier, "(multiclass): selected", n_selected, "features")
            
            # Store results and skip Boruta processing
            values$ml_selected_features <- selected_result
            values$ml_importance <- fs_result
            values$ml_performance <- perf
            values$boruta_object <- NULL
            values$boruta_stats <- NULL
            values$boruta_plot_data <- NULL
            values$ml_method_used <- "boruta_multiclass"  # Track method for summary display
            values$ml_classifier_used <- boruta_classifier  # Track classifier for detailed display
            # Post-process multiclass Boruta substitute names
            if (!is.null(values$ml_importance) && !is.null(values$cleaned_molecules)) {
              name_col <- intersect(c("Feature","Variable","Name"), colnames(values$ml_importance))[1]
              if (!is.null(name_col)) {
                current_names <- values$ml_importance[[name_col]]
                if (length(current_names) == length(values$cleaned_molecules) && all(grepl("^Feature_[0-9]+$", current_names))) {
                  idx <- as.integer(sub("Feature_", "", current_names))
                  if (all(!is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
                    values$ml_importance[[name_col]] <- values$cleaned_molecules[idx]
                  }
                }
              }
            }
            
          } else {
            # Binary classification - use full Boruta implementation with custom classifier
            
            # Convert X to data frame with proper column names for Boruta
            X_df <- as.data.frame(X)
            y_binary <- as.factor(y_bin)
            
            # Ensure we have valid data for Boruta
            if (nrow(X_df) < 3 || ncol(X_df) < 1) {
              stop("Insufficient data for Boruta analysis. Need at least 3 samples and 1 feature.")
            }
            
            if (length(levels(y_binary)) != 2) {
              stop("Boruta requires exactly 2 classes. Found: ", length(levels(y_binary)))
            }
            
            # Store original feature names before make.names conversion
            original_feature_names <- colnames(X_df)
            
            # Ensure column names are valid
            colnames(X_df) <- make.names(colnames(X_df), unique = TRUE)
            
            # Create mapping from make.names() version back to original
            feature_name_mapping <- setNames(original_feature_names, colnames(X_df))
            
            cat("Debug Boruta: Running Boruta with", nrow(X_df), "samples and", ncol(X_df), "features using", boruta_classifier, "\n")
            
            # Create custom importance function based on selected classifier
            getImp_function <- NULL
            getImp_label <- NULL
            
            if (boruta_importance_source == "custom") {
              # Create custom VIM function based on selected classifier
              if (boruta_classifier == "ranger") {
                getImp_function <- function(x, y) {
                  if (!requireNamespace("ranger", quietly = TRUE)) stop("ranger package required")
                  tryCatch({
                    rf_fit <- ranger::ranger(x = x, y = y, num.trees = boruta_ntree, importance = "permutation")
                    imp <- rf_fit$variable.importance
                    if (is.null(imp) || length(imp) == 0) {
                      stop("ranger returned empty importance values")
                    }
                    # Ensure importance vector has names matching column names
                    if (is.null(names(imp)) && ncol(x) == length(imp)) {
                      names(imp) <- colnames(x)
                    }
                    return(imp)
                  }, error = function(e) {
                    cat("Error in ranger VIM function:", e$message, "\n")
                    stop(paste("ranger VIM error:", e$message))
                  })
                }
                getImp_label <- "custom:ranger-permutation"
              } else if (boruta_classifier == "randomForest") {
                getImp_function <- function(x, y) {
                  if (!requireNamespace("randomForest", quietly = TRUE)) stop("randomForest package required")
                  tryCatch({
                    rf_fit <- randomForest::randomForest(x = x, y = y, ntree = boruta_ntree, importance = TRUE)
                    # Use Mean Decrease Accuracy for VIM (type = 1)
                    imp_matrix <- randomForest::importance(rf_fit, type = 1)
                    # importance() returns matrix; coerce to named vector
                    if (is.matrix(imp_matrix)) {
                      imp <- imp_matrix[, 1]
                    } else {
                      imp <- as.numeric(imp_matrix)
                    }
                    if (is.null(names(imp)) || length(imp) != ncol(x)) {
                      names(imp) <- rownames(imp_matrix)
                    }
                    # Align to full feature set
                    full_imp <- rep(0, ncol(x))
                    names(full_imp) <- colnames(x)
                    common_names <- intersect(names(imp), colnames(x))
                    full_imp[common_names] <- imp[common_names]
                    return(full_imp)
                  }, error = function(e) {
                    cat("Error in randomForest VIM function:", e$message, "\n")
                    stop(paste("randomForest VIM error:", e$message))
                  })
                }
                getImp_label <- "custom:randomForest-MDA"
              } else if (boruta_classifier == "gbm") {
                getImp_function <- function(x, y) {
                  if (!requireNamespace("gbm", quietly = TRUE)) stop("gbm package required")
                  tryCatch({
                    # Convert factor to numeric for gbm
                    y_numeric <- as.numeric(y) - 1
                    data_df <- cbind(y = y_numeric, x)
                    gbm_fit <- gbm::gbm(y ~ ., data = data_df, distribution = "bernoulli",
                                        n.trees = boruta_gbm_trees, interaction.depth = 3,
                                        shrinkage = 0.01, verbose = FALSE)
                    imp <- gbm::relative.influence(gbm_fit, n.trees = boruta_gbm_trees)
                    if (length(imp) == 0) {
                      stop("gbm returned empty importance values")
                    }
                    # Map to full, named vector matching all features
                    full_imp <- rep(0, ncol(x))
                    names(full_imp) <- colnames(x)
                    # relative.influence already returns names; align safely
                    common_names <- intersect(names(imp), colnames(x))
                    full_imp[common_names] <- imp[common_names]
                    return(full_imp)
                  }, error = function(e) {
                    cat("Error in gbm VIM function:", e$message, "\n")
                    stop(paste("gbm VIM error:", e$message))
                  })
                }
                getImp_label <- "custom:gbm-relative.influence"
              } else if (boruta_classifier == "xgboost") {
                getImp_function <- function(x, y) {
                  if (!requireNamespace("xgboost", quietly = TRUE)) stop("xgboost package required")
                  tryCatch({
                    # Convert to xgboost format
                    y_numeric <- as.numeric(y) - 1
                    dtrain <- xgboost::xgb.DMatrix(data = as.matrix(x), label = y_numeric)
                    xgb_fit <- xgboost::xgboost(data = dtrain, objective = "binary:logistic",
                                                nrounds = boruta_xgb_rounds, verbose = 0)
                    imp <- xgboost::xgb.importance(colnames(x), model = xgb_fit)
                    if (nrow(imp) == 0) {
                      stop("xgboost returned empty importance values")
                    }
                    imp_named <- setNames(imp$Gain, imp$Feature)
                    # Ensure all features are represented
                    full_imp <- rep(0, ncol(x))
                    names(full_imp) <- colnames(x)
                    full_imp[names(imp_named)] <- imp_named
                    return(full_imp)
                  }, error = function(e) {
                    cat("Error in xgboost VIM function:", e$message, "\n")
                    stop(paste("xgboost VIM error:", e$message))
                  })
                }
                getImp_label <- "custom:xgboost-gain"
              } else {
                # Default to ranger
                getImp_function <- Boruta::getImpRfZ
                getImp_label <- "builtin:getImpRfZ (default)"
              }
            } else {
              # Use built-in Boruta importance functions
              getImp_function <- switch(boruta_importance_source,
                                        "getImpRfGini" = Boruta::getImpRfGini,
                                        "getImpRfZ" = Boruta::getImpRfZ,  # Uses ranger/randomForest under the hood
                                        "getImpRfRaw" = Boruta::getImpRfRaw,
                                        Boruta::getImpRfZ  # Default fallback
              )
              getImp_label <- paste0("builtin:", boruta_importance_source)
            }
            
            # Prepare additional arguments based on classifier
            extra_args <- list()
            if (boruta_classifier %in% c("ranger", "randomForest") && boruta_importance_source != "custom") {
              extra_args$ntree <- boruta_ntree
            }
            
            # Notify/warn when classifier selection won't affect importance
            if (boruta_importance_source != "custom" && !(boruta_classifier %in% c("ranger", "randomForest"))) {
              showNotification(
                paste0("Base classifier '", boruta_classifier, "' is ignored unless Importance Source is set to 'custom'. Using ", getImp_label, "."),
                type = "warning"
              )
            }
            
            cat("Debug Boruta: Using importance source:", getImp_label, "| base classifier:", boruta_classifier, "\n")
            
            # Run Boruta with comprehensive parameters
            boruta_fit <- tryCatch({
              cat("Debug Boruta: Calling Boruta with parameters - pValue:", boruta_p_value, "maxRuns:", boruta_max_runs, "\n")
              
              # Build Boruta call arguments
              boruta_args <- list(
                x = X_df,
                y = y_binary,
                pValue = boruta_p_value,
                maxRuns = boruta_max_runs,
                doTrace = boruta_do_trace,
                holdHistory = TRUE,
                getImp = getImp_function
              )
              
              # Add ntree parameter only for appropriate methods
              if (boruta_classifier %in% c("ranger", "randomForest") && boruta_importance_source != "custom") {
                boruta_args$ntree <- boruta_ntree
              }
              
              # Call Boruta
              do.call(Boruta::Boruta, boruta_args)
              
            }, error = function(e) {
              cat("Debug Boruta: Error during Boruta execution:", e$message, "\n")
              stop(paste("Boruta execution failed:", e$message))
            })
            
            cat("Debug Boruta: Boruta completed using", boruta_classifier, "classifier. Processing results...\n")
            
            # Apply TentativeRoughFix if requested and there are tentative features
            if (boruta_tentative_fix) {
              tentative_count <- sum(boruta_fit$finalDecision == "Tentative")
              if (tentative_count > 0) {
                cat("Debug Boruta: Applying TentativeRoughFix to", tentative_count, "tentative features\n")
                boruta_fit <- Boruta::TentativeRoughFix(boruta_fit)
                showNotification(paste("Applied TentativeRoughFix to", tentative_count, "tentative features"), type = "message")
              }
            }
            
            # Extract comprehensive statistics using attStats
            stats <- Boruta::attStats(boruta_fit)
            cat("Debug Boruta: Stats dimensions:", dim(stats), "\n")
            cat("Debug Boruta: Stats colnames:", colnames(stats), "\n")
            cat("Debug Boruta: Stats rownames length:", length(rownames(stats)), "\n")
            
            # Validate stats structure
            if (is.null(stats) || nrow(stats) == 0) {
              stop("Boruta attStats returned empty results")
            }
            
            # Check for required columns (pValue is optional)
            required_cols <- c("decision", "meanImp")
            missing_cols <- setdiff(required_cols, colnames(stats))
            if (length(missing_cols) > 0) {
              stop(paste("Missing required columns in Boruta stats:", paste(missing_cols, collapse = ", ")))
            }
            
            # Add pValue column if missing (can happen with custom importance functions)
            if (!"pValue" %in% colnames(stats)) {
              cat("Debug Boruta: pValue column missing, adding default values\n")
              stats$pValue <- rep(NA, nrow(stats))
            }
            
            cat("Debug Boruta: Decision summary:", table(stats$decision), "\n")
            
            # Get confirmed features
            confirmed_idx <- which(stats$decision == "Confirmed")
            confirmed <- rownames(stats)[confirmed_idx]
            
            # Get rejected and tentative for reporting
            rejected_idx <- which(stats$decision == "Rejected")
            tentative_idx <- which(stats$decision == "Tentative")
            
            cat("Debug Boruta: Confirmed:", length(confirmed), "Rejected:", length(rejected_idx), "Tentative:", length(tentative_idx), "\n")
            
            if (length(confirmed) == 0) {
              # No features confirmed - create empty but valid results
              warning_msg <- paste("No features were confirmed by Boruta.",
                                   "Rejected:", length(rejected_idx),
                                   "Tentative:", length(tentative_idx),
                                   "Try increasing maxRuns or adjusting pValue.")
              showNotification(warning_msg, type = "warning")
              
              # Create empty results with proper structure
              empty_cols <- list(
                Feature = character(0),
                Importance = numeric(0),
                Decision = character(0)
              )
              
              # Add pValue column if it exists in stats
              if ("pValue" %in% colnames(stats)) {
                empty_cols$pValue <- numeric(0)
              }
              
              fs_result <- do.call(data.frame, c(empty_cols, stringsAsFactors = FALSE))
              selected_result <- fs_result
              perf <- paste("Boruta: No confirmed features. Rejected:", length(rejected_idx), "Tentative:", length(tentative_idx))
            } else {
              # Extract importance for confirmed features
              importance_values <- stats[confirmed_idx, "meanImp"]
              names(importance_values) <- confirmed
              
              # Sort by importance
              importance_sorted <- sort(importance_values, decreasing = TRUE)
              
              # Create comprehensive results data frame with all stats - with validation
              tryCatch({
                # Validate that all vectors have the same length
                # Map make.names() rownames back to original feature names
                stats_rownames <- rownames(stats)
                feature_names <- if (!is.null(feature_name_mapping)) {
                  # Use mapping to restore original names
                  sapply(stats_rownames, function(rn) {
                    if (rn %in% names(feature_name_mapping)) {
                      feature_name_mapping[[rn]]
                    } else {
                      rn  # fallback to rowname if not in mapping
                    }
                  }, USE.NAMES = FALSE)
                } else {
                  stats_rownames
                }
                importance_vals <- stats$meanImp
                decision_vals <- stats$decision
                
                # Handle optional pValue column
                has_pvalue <- "pValue" %in% colnames(stats) && !all(is.na(stats$pValue))
                if (has_pvalue) {
                  pvalue_vals <- stats$pValue
                  vector_lengths <- c(length(feature_names), length(importance_vals),
                                      length(decision_vals), length(pvalue_vals))
                  cat("Debug Boruta: Vector lengths - Features:", length(feature_names),
                      "Importance:", length(importance_vals),
                      "Decision:", length(decision_vals),
                      "pValue:", length(pvalue_vals), "\n")
                } else {
                  pvalue_vals <- NULL
                  vector_lengths <- c(length(feature_names), length(importance_vals), length(decision_vals))
                  cat("Debug Boruta: Vector lengths - Features:", length(feature_names),
                      "Importance:", length(importance_vals),
                      "Decision:", length(decision_vals),
                      "(pValue not available)\n")
                }
                
                # Ensure all vectors have the same length
                if (length(unique(vector_lengths)) != 1) {
                  stop("Inconsistent vector lengths in Boruta results")
                }
                
                # Build data frame with available columns
                df_cols <- list(
                  Feature = feature_names,
                  Importance = importance_vals,
                  Decision = decision_vals
                )
                
                if (has_pvalue) {
                  df_cols$pValue <- pvalue_vals
                }
                
                fs_result <- do.call(data.frame, c(df_cols, stringsAsFactors = FALSE))
                
                # Sort full results by importance
                fs_result <- fs_result[order(fs_result$Importance, decreasing = TRUE), ]
                
                # Filter confirmed features and select top N
                confirmed_results <- fs_result[fs_result$Decision == "Confirmed", ]
                n_selected <- min(n_features, nrow(confirmed_results))
                
                if (n_selected > 0) {
                  selected_result <- confirmed_results[1:n_selected, , drop = FALSE]
                } else {
                  selected_result <- fs_result[0, , drop = FALSE]  # Empty but with correct structure
                }
                
                perf <- paste("Boruta: Confirmed", length(confirmed),
                              "features; selected top", n_selected,
                              "| Rejected:", length(rejected_idx),
                              "| Tentative:", length(tentative_idx))
                
              }, error = function(e) {
                cat("Debug Boruta: Error creating results data frame:", e$message, "\n")
                # Fallback to simpler results structure
                fs_result <<- data.frame(
                  Feature = confirmed,
                  Importance = importance_sorted,
                  stringsAsFactors = FALSE
                )
                selected_result <<- head(fs_result, min(n_features, nrow(fs_result)))
                perf <<- paste("Boruta: Confirmed", length(confirmed), "features (simplified results due to data structure issue)")
              })
            }
            
            # Store comprehensive Boruta results
            values$boruta_object <- boruta_fit
            values$boruta_stats <- stats
            values$ml_method_used <- "boruta"  # Track method for summary display
            values$ml_classifier_used <- boruta_classifier  # Track classifier for detailed display
            values$boruta_importance_source_used <- getImp_label
            
            # Create plot data for importance history if available
            if (!is.null(boruta_fit$ImpHistory)) {
              # Ensure finalDecision is named with real feature names
              fd <- boruta_fit$finalDecision
              if (is.null(names(fd)) || any(names(fd) == "")) {
                names(fd) <- original_feature_names[seq_len(length(fd))]
              } else if (!is.null(feature_name_mapping)) {
                # Map make.names() names back to original
                names(fd) <- sapply(names(fd), function(nm) {
                  if (nm %in% names(feature_name_mapping)) {
                    feature_name_mapping[[nm]]
                  } else {
                    nm
                  }
                }, USE.NAMES = FALSE)
              }
              values$boruta_plot_data <- list(
                ImpHistory = boruta_fit$ImpHistory,
                finalDecision = fd,
                realFeatureNames = original_feature_names,
                pValue = boruta_p_value,
                maxRuns = boruta_max_runs
              )
            } else {
              values$boruta_plot_data <- NULL
            }
            
            # Store final results
            # Map Boruta feature identifiers (e.g., X12, Feature_34, plain digits) to real feature names
            map_boruta_names <- function(df) {
              if (is.null(df) || nrow(df) == 0) return(df)
              if (is.null(values$cleaned_molecules)) return(df)
              name_col <- intersect(c("Feature","Variable","Name"), colnames(df))[1]
              if (is.null(name_col)) return(df)
              feats <- df[[name_col]]
              suppressWarnings({
                # Patterns: X123, Feature_123, 123
                idx1 <- as.integer(sub("^X", "", feats))
                idx2 <- as.integer(sub("^Feature_", "", feats))
                idx3 <- ifelse(grepl("^[0-9]+$", feats), as.integer(feats), NA_integer_)
                # Prefer explicit numeric extraction order
                idx <- ifelse(!is.na(idx2), idx2, ifelse(!is.na(idx1), idx1, idx3))
                valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
                feats[valid] <- values$cleaned_molecules[idx[valid]]
              })
              df[[name_col]] <- feats
              df
            }
            values$ml_selected_features <- map_boruta_names(selected_result)
            values$ml_importance <- map_boruta_names(fs_result)
            values$ml_performance <- perf
          }  # End binary classification else block
          
          showNotification("Boruta feature selection completed!", type = "message")
          
        }, error = function(e) {
          error_msg <- paste("Boruta error:", e$message)
          cat("Debug Boruta Error:", error_msg, "\n")
          showNotification(error_msg, type = "error")
          
          # Create empty results
          empty_result <- data.frame(Feature = character(0), Importance = numeric(0),
                                     Decision = character(0), pValue = numeric(0), stringsAsFactors = FALSE)
          values$ml_selected_features <- empty_result
          values$ml_importance <- empty_result
          values$ml_performance <- error_msg
          values$boruta_object <- NULL
          values$boruta_stats <- NULL
          values$boruta_plot_data <- NULL
        })
      } else if (input$feature_selection_method == "rfe") {
        # Enhanced Recursive Feature Elimination
        if (!requireNamespace("caret", quietly = TRUE)) install.packages("caret")
        
        tryCatch({
          # Setup parallel processing if enabled
          if (input$rfe_parallel) {
            if (!requireNamespace("doParallel", quietly = TRUE)) install.packages("doParallel")
            if (!requireNamespace("foreach", quietly = TRUE)) install.packages("foreach")
            
            # Register parallel backend
            cl <- parallel::makeCluster(input$rfe_n_cores)
            doParallel::registerDoParallel(cl)
            on.exit(parallel::stopCluster(cl), add = TRUE)
            showNotification(paste("Parallel processing enabled with", input$rfe_n_cores, "cores"), type = "message")
          } else {
            # Ensure sequential processing (important for RFE stability)
            if (requireNamespace("foreach", quietly = TRUE)) {
              foreach::registerDoSEQ()
            }
          }
          
          # Since we only support Random Forest now, directly use rfFuncs
          base_functions <- caret::rfFuncs
          
          # Determine whether user selected RFECV (full customizable CV) or basic RFE
          is_rfecv <- identical(input$feature_selection_rfe_method, "rfecv")
          
          # Configure cross-validation / resampling strategy
          # Requirement: CV options (user-specified) must ONLY be honored when RFECV is selected.
          # When plain RFE is chosen, we ignore UI CV inputs (even if hidden) and use a small internal default.
          if (is_rfecv) {
            cv_method <- input$rfe_cv_method
            train_control_args <- list(method = cv_method)
            if (cv_method %in% c("cv", "repeatedcv")) {
              train_control_args$number <- input$rfe_cv_folds
              if (cv_method == "repeatedcv") {
                train_control_args$repeats <- input$rfe_cv_repeats
              }
            } else if (cv_method == "boot") {
              train_control_args$number <- input$rfe_bootstrap_samples
            } else if (cv_method == "LGOCV") {
              train_control_args$number <- 10  # default iterations
              train_control_args$p <- input$rfe_lgocv_p
            }
          } else {
            # Plain RFE path: enforce lightweight internal 5-fold CV (or less if data limited) to rank subsets.
            # This guarantees consistent feature ranking while insulating from hidden CV UI inputs.
            cv_method <- "cv"
            internal_folds <- min(5, max(2, nrow(X) - 1))
            train_control_args <- list(method = "cv", number = internal_folds)
          }
          
          # Add evaluation metric and other options
          # Regression vs classification paths
          metric_requested <- input$rfe_metric
          is_regression <- identical(input$rfe_problem_type, "regression")
          if (is_regression) {
            # Ensure y numeric for regression
            if (!is.numeric(y)) {
              suppressWarnings({ y_numeric <- as.numeric(as.character(y)) })
              if (anyNA(y_numeric)) {
                # Enhanced diagnostics for user clarity
                raw_levels <- unique(as.character(y))
                n_levels <- length(raw_levels)
                preview_n <- min(6, n_levels)
                shown <- paste(head(raw_levels, preview_n), collapse = ", ")
                if (n_levels > preview_n) {
                  shown <- paste0(shown, " ... (", n_levels - preview_n, " more)")
                }
                msg <- paste0(
                  "Regression mode aborted: outcome is non-numeric (factor with ", n_levels,
                  ifelse(n_levels == 1, " level).", " levels)."),
                  "\nSample levels: ", shown,
                  "\nAction: Provide a numeric continuous outcome (e.g., a quantitative phenotype) or switch Problem Type to Binary/Multiclass classification.")
                showNotification(msg, type = "error", duration = 14)
                return()
              }
              y <- y_numeric
            }
            # Map metric choices (already filtered to RMSE/MAE/Rsquared by observer)
            train_control_args$summaryFunction <- caret::defaultSummary
            train_control_args$classProbs <- FALSE
            if (!(metric_requested %in% c("RMSE","MAE","Rsquared"))) metric_requested <- "RMSE"
          } else {
            # Classification metrics
            if (metric_requested %in% c("Accuracy", "Kappa")) {
              train_control_args$summaryFunction <- caret::defaultSummary
              train_control_args$classProbs <- FALSE
            } else if (metric_requested %in% c("ROC", "Sens", "Spec")) {
              train_control_args$summaryFunction <- caret::twoClassSummary
              train_control_args$classProbs <- TRUE
              metric_requested <- if (metric_requested %in% c("Sens","Spec")) "ROC" else metric_requested
            } else if (metric_requested %in% c("Precision","Recall","F")) {
              # Map precision/recall/F1 to twoClassSummary (primary metric=ROC fallback)
              train_control_args$summaryFunction <- caret::twoClassSummary
              train_control_args$classProbs <- TRUE
              metric_requested <- "ROC"
            } else {
              train_control_args$summaryFunction <- caret::twoClassSummary
              train_control_args$classProbs <- TRUE
              metric_requested <- "ROC"
            }
          }
          if (input$rfe_save_predictions) train_control_args$savePredictions <- "final"
          if (input$rfe_return_resamp) train_control_args$returnResamp <- "all"
          
          # Handle multi-class vs binary classification
          if (length(unique(y)) > 2) {
            # caret::multiClassSummary depends on MLmetrics; provide graceful fallback if missing
            if (requireNamespace("MLmetrics", quietly = TRUE)) {
              train_control_args$summaryFunction <- caret::multiClassSummary
            } else {
              # Fallback: compute macro-averaged Accuracy and Kappa only
              fallback_multi_summary <- function(data, lev = NULL, model = NULL) {
                # data has columns: obs, pred, and possibly probabilities
                acc <- mean(data$pred == data$obs)
                # Simple unweighted Cohen's Kappa implementation
                tab <- table(data$obs, data$pred)
                if (nrow(tab) == ncol(tab)) {
                  po <- sum(diag(tab)) / sum(tab)
                  rowsums <- rowSums(tab)
                  colsums <- colSums(tab)
                  pe <- sum(rowsums * colsums) / (sum(tab)^2)
                  kappa <- ifelse(1 - pe == 0, NA, (po - pe)/(1 - pe))
                } else {
                  kappa <- NA
                }
                c(Accuracy = acc, Kappa = kappa)
              }
              train_control_args$summaryFunction <- fallback_multi_summary
              showNotification(
                "Multi-class performance: package 'MLmetrics' not installed; using fallback (Accuracy & Kappa only). Install MLmetrics for full metrics.",
                type = "warning", duration = 10
              )
            }
          }
          
          # Create trainControl object
          train_control <- do.call(caret::trainControl, train_control_args)
          
          # Configure selection function
          selection_function <- switch(input$rfe_selection_function,
                                       "pickSizeTolerance" = caret::pickSizeTolerance,
                                       "pickSizeBest" = caret::pickSizeBest,
                                       "pickSizeOneStandardError" = function(x, metric, tol = 1, maximize) {
                                         # One SE rule implementation
                                         best_perf <- if(maximize) max(x[, metric], na.rm = TRUE) else min(x[, metric], na.rm = TRUE)
                                         se_threshold <- if(maximize) best_perf - sd(x[, metric], na.rm = TRUE) else best_perf + sd(x[, metric], na.rm = TRUE)
                                         candidates <- if(maximize) which(x[, metric] >= se_threshold) else which(x[, metric] <= se_threshold)
                                         if(length(candidates) > 0) min(x$Variables[candidates]) else x$Variables[which.max(x[, metric])]
                                       },
                                       caret::pickSizeTolerance  # default
          )
          
          # Determine feature subset sizes
          max_features <- min(input$rfe_max_features, ncol(X))
          min_features <- input$rfe_min_features
          
          subset_sizes <- switch(input$rfe_subset_strategy,
                                 "auto" = {
                                   # Powers of 2 approach with some modifications
                                   sizes <- unique(c(min_features, 2^(1:floor(log2(max_features))), max_features))
                                   sizes[sizes >= min_features & sizes <= max_features]
                                 },
                                 "linear" = {
                                   seq(min_features, max_features, by = input$rfe_linear_step)
                                 },
                                 "custom" = {
                                   tryCatch({
                                     custom_sizes <- as.numeric(unlist(strsplit(input$rfe_custom_sizes, ",")))
                                     custom_sizes <- custom_sizes[!is.na(custom_sizes)]
                                     custom_sizes <- custom_sizes[custom_sizes >= min_features & custom_sizes <= max_features]
                                     if (length(custom_sizes) == 0) seq(min_features, max_features, by = 5) else sort(custom_sizes)
                                   }, error = function(e) {
                                     showNotification("Invalid custom sizes, using default linear sequence", type = "warning")
                                     seq(min_features, max_features, by = 5)
                                   })
                                 }
          )
          
          # Create RFE control object with enhanced parameters
          rfe_control_args <- list(
            functions = base_functions,
            method = cv_method,
            saveDetails = TRUE,
            returnResamp = "all",
            rerank = TRUE,
            verbose = FALSE
          )
          
          if (is_rfecv) {
            # Only honor user CV parameters in RFECV mode
            if (cv_method %in% c("cv", "repeatedcv")) {
              rfe_control_args$number <- input$rfe_cv_folds
              if (cv_method == "repeatedcv") {
                rfe_control_args$repeats <- input$rfe_cv_repeats
              }
            } else if (cv_method == "boot") {
              rfe_control_args$number <- input$rfe_bootstrap_samples
            }
          } else {
            # Fixed internal folds for plain RFE
            rfe_control_args$number <- train_control_args$number
          }
          
          # Use Random Forest functions and customize for adaptive mtry
          rfe_functions <- caret::rfFuncs
          
          # Wrap fit to adapt mtry to current subset size to avoid errors when subset size < user mtry
          user_ntree <- input$rfe_rf_ntree
          user_mtry  <- if (!is.null(input$rfe_rf_mtry) && input$rfe_rf_mtry > 0) input$rfe_rf_mtry else NA
          original_fit <- rfe_functions$fit
          rfe_functions$fit <- function(x, y, first, last, ...) {
            # Ensure x is data.frame for randomForest
            if (!is.data.frame(x)) x <- as.data.frame(x)
            p <- ncol(x)
            adaptive_mtry <- if (is.na(user_mtry)) max(1, floor(sqrt(p))) else min(user_mtry, p)
            randomForest::randomForest(x, y, importance = TRUE, ntree = user_ntree, mtry = adaptive_mtry)
          }
          
          # Override the summary and selectSize functions if needed
          # Ensure summary function matches train_control metric expectations
          # Will set after train_control is created (guard later if object exists)
          if (input$rfe_selection_function == "pickSizeTolerance") {
            rfe_functions$selectSize <- function(x, metric, tol = input$rfe_tolerance, maximize) {
              caret::pickSizeTolerance(x, metric, tol, maximize)
            }
          } else {
            rfe_functions$selectSize <- selection_function
          }
          
          rfe_control_args$functions <- rfe_functions
          
          # Create control object
          ctrl <- do.call(caret::rfeControl, rfe_control_args)
          # After train_control exists, align summary function (if possible)
          if (!is.null(train_control$summaryFunction)) {
            if (is.null(rfe_control_args$functions$summary) ||
                !identical(body(rfe_control_args$functions$summary), body(train_control$summaryFunction))) {
              rfe_functions$summary <- train_control$summaryFunction
              ctrl$functions$summary <- train_control$summaryFunction
            }
          }
          
          # Prepare Random Forest parameters
          model_params <- list()
          
          if (input$rfe_rf_mtry > 0) {
            model_params$mtry <- input$rfe_rf_mtry
          }
          
          # Show progress
          incProgress(0.3, detail = "Running RFE analysis...")
          
          # --- RFE Pre-flight Data Validation & Cleaning ---
          # Ensure predictors are numeric (caret RFE expects numeric/factor predictors; here features should be numeric)
          # Remove any non-numeric columns silently
          non_numeric_cols <- vapply(X, function(col) !is.numeric(col), logical(1))
          if (any(non_numeric_cols)) {
            X <- X[ , !non_numeric_cols, drop = FALSE]
          }
          # Remove columns with all NA or zero variance
          if (ncol(X) > 0) {
            all_na <- vapply(X, function(col) all(is.na(col)), logical(1))
            if (any(all_na)) X <- X[ , !all_na, drop = FALSE]
            if (ncol(X) > 0) {
              nzv <- caret::nearZeroVar(X)
              if (length(nzv) > 0) X <- X[ , -nzv, drop = FALSE]
            }
          }
          # Impute remaining NA with column medians (simple, fast)
          if (anyNA(X)) {
            for (j in seq_len(ncol(X))) {
              col_vals <- X[[j]]
              if (anyNA(col_vals)) {
                med <- suppressWarnings(stats::median(col_vals, na.rm = TRUE))
                if (is.finite(med)) col_vals[is.na(col_vals)] <- med else col_vals[is.na(col_vals)] <- 0
                X[[j]] <- col_vals
              }
            }
          }
          # Re-check dimensions
          if (ncol(X) == 0) {
            showNotification("RFE aborted: No valid numeric predictors after cleaning.", type = "error")
            return()
          }
          # Convert X to matrix for caret compatibility (many models expect matrix)
          X <- as.matrix(X)
          
          # Ensure subset sizes are valid after potential column removal
          subset_sizes <- subset_sizes[subset_sizes > 0 & subset_sizes <= ncol(X)]
          subset_sizes <- unique(sort(subset_sizes))
          if (length(subset_sizes) == 0) {
            subset_sizes <- seq_len(min(5, ncol(X)))
          }
          if (max(subset_sizes) > ncol(X)) subset_sizes[length(subset_sizes)] <- ncol(X)
          # Guard factor y
          if (!is.factor(y)) y <- as.factor(y)
          if (length(y) != nrow(X)) {
            showNotification("RFE aborted: Length mismatch between labels and samples.", type = "error")
            return()
          }
          
          # Auto-install randomForest package if needed
          if (!requireNamespace("randomForest", quietly = TRUE)) {
            try(utils::install.packages("randomForest"), silent = TRUE)
          }
          
          # Diagnostics prior to RFE
          cat("[RFE Debug] Samples=", nrow(X), " Features=", ncol(X), "\n", sep = "")
          cat("[RFE Debug] Subset Sizes: ", paste(subset_sizes, collapse = ","), "\n", sep = "")
          cat("[RFE Debug] Method=", input$rfe_base_model, " Metric=", input$rfe_metric, "\n", sep = "")
          
          # === PREFLIGHT DATA VALIDATION ===
          # This block prevents "argument 1 is not a vector" and similar RFE data format errors
          cat("[RFE Preflight] Validating data structures...\n")
          
          # 1. Validate X (feature matrix)
          if (!is.data.frame(X) && !is.matrix(X)) {
            showNotification("RFE aborted: X must be a data.frame or matrix", type = "error")
            return()
          }
          if (nrow(X) == 0 || ncol(X) == 0) {
            showNotification("RFE aborted: X has zero rows or columns", type = "error")
            return()
          }
          
          # 2. Validate y (outcome vector)
          if (length(y) == 0) {
            showNotification("RFE aborted: outcome vector y is empty", type = "error")
            return()
          }
          if (length(y) != nrow(X)) {
            showNotification(paste("RFE aborted: y length (", length(y), ") != X rows (", nrow(X), ")", sep=""), type = "error")
            return()
          }
          
          # 3. Ensure y is proper vector/factor (not list or other complex structure)
          if (is.list(y) || (!is.vector(y) && !is.factor(y))) {
            cat("[RFE Preflight] Converting y to factor...\n")
            y <- factor(as.character(y))
          }
          
          # 4. Clean subset_sizes to valid range
          original_sizes <- subset_sizes
          subset_sizes <- subset_sizes[subset_sizes >= 1 & subset_sizes <= ncol(X)]
          if (length(subset_sizes) == 0) {
            subset_sizes <- seq_len(min(5, ncol(X)))
            showNotification(paste("RFE: Invalid subset sizes adjusted to 1:", max(subset_sizes)), type = "warning", duration = 6)
          } else if (length(subset_sizes) != length(original_sizes)) {
            showNotification(paste("RFE: Subset sizes filtered from", length(original_sizes), "to", length(subset_sizes), "valid values"), type = "message", duration = 4)
          }
          
          # 5. Ensure X contains only numeric columns (drop any non-numeric)
          numeric_cols <- sapply(X, is.numeric)
          if (!all(numeric_cols)) {
            dropped_cols <- colnames(X)[!numeric_cols]
            X <- X[, numeric_cols, drop = FALSE]
            showNotification(paste("RFE: Dropped", length(dropped_cols), "non-numeric columns:", paste(head(dropped_cols, 3), collapse = ", ")), type = "warning", duration = 6)
            if (ncol(X) == 0) {
              showNotification("RFE aborted: No numeric columns remain after filtering", type = "error")
              return()
            }
            # Re-validate subset_sizes after column removal
            subset_sizes <- subset_sizes[subset_sizes <= ncol(X)]
            if (length(subset_sizes) == 0) {
              subset_sizes <- seq_len(min(3, ncol(X)))
            }
          }
          
          # 6. Check for minimum sample size requirements
          if (nrow(X) < 4) {
            showNotification("RFE aborted: Need at least 4 samples for cross-validation", type = "error")
            return()
          }
          
          # 7. Validate CV fold settings
          max_safe_folds <- nrow(X) - 1
          if (is_rfecv && cv_method %in% c("cv", "repeatedcv") && input$rfe_cv_folds > max_safe_folds) {
            old_folds <- input$rfe_cv_folds
            cv_folds_adjusted <- max(3, max_safe_folds)
            showNotification(paste("RFE: Reduced CV folds from", old_folds, "to", cv_folds_adjusted, "for", nrow(X), "samples"), type = "warning", duration = 8)
            # Update train_control_args
            train_control_args$number <- cv_folds_adjusted
          }
          
          # 8. Final structure audit (console only)
          cat("[RFE Preflight] Final validation:\n")
          cat("  X: ", nrow(X), " ", ncol(X), " (", class(X)[1], ")\n", sep="")
          cat("  y: length=", length(y), " class=", class(y)[1], " levels=", ifelse(is.factor(y), nlevels(y), "N/A"), "\n", sep="")
          cat("  subset_sizes: ", paste(head(subset_sizes, 10), collapse=","), ifelse(length(subset_sizes) > 10, "...", ""), "\n", sep="")
          cat("  CV method: ", if(is_rfecv) cv_method else "internal", "\n", sep="")
          
          # Execute RFE with simplified approach (Stage 1: reintroduce RFECV + metric handling)
          rfe_result <- tryCatch({
            # Force sequential processing for stability
            foreach::registerDoSEQ()
            
            # Ensure data.frame format (caret requirement)
            X_clean <- as.data.frame(X)
            
            # Basic diagnostics
            cat("[RFE Debug] Data format: X=", class(X_clean)[1], " (", nrow(X_clean), " ", ncol(X_clean), "), y=", class(y)[1], " (length=", length(y), ")\n", sep = "")
            # Simplified stable metric handling: use Accuracy for all classification in Stage 1
            is_classification <- is.factor(y)
            use_metric <- if (is_classification) "Accuracy" else "RMSE"
            
            # CV configuration
            if (is_rfecv) {
              cv_method_final <- cv_method
              folds_final <- if (!is.null(train_control_args$number)) train_control_args$number else min(5, nrow(X_clean)-1)
              repeats_final <- if (!is.null(train_control_args$repeats)) train_control_args$repeats else NULL
            } else {
              cv_method_final <- "cv"
              folds_final <- min(5, nrow(X_clean) - 1)
              repeats_final <- NULL
            }
            cat("[RFE Debug] CV method=", cv_method_final, " folds=", folds_final, if(!is.null(repeats_final)) paste(" repeats=", repeats_final) else "", " metric=", use_metric, " (Stage1 simplified)\n", sep="")
            
            # Choose functions set (only RF now)
            funcs <- caret::rfFuncs
            
            rfe_ctrl <- caret::rfeControl(functions = funcs,
                                          method = cv_method_final,
                                          number = folds_final,
                                          repeats = repeats_final,
                                          saveDetails = TRUE,
                                          returnResamp = "final",
                                          verbose = FALSE)
            
            # Simplified RFE call - only Random Forest
            caret::rfe(x = X_clean, y = y,
                       sizes = subset_sizes,
                       rfeControl = rfe_ctrl)
          }, error = function(e) {
            err_msg <- paste("RFE internal error:", e$message)
            cat("[RFE Debug] ERROR ->", err_msg, "\n")
            cat("[RFE Debug] Model:", input$rfe_base_model, "\n")
            cat("[RFE Debug] Data types: X=", class(X), " y=", class(y), "\n")
            cat("[RFE Debug] X dims:", dim(X), " y length:", length(y), "\n")
            cat("[RFE Debug] Subset sizes:", paste(subset_sizes, collapse=","), "\n")
            cat("[RFE Debug] Y levels:", paste(levels(y), collapse=","), "\n")
            
            # Provide specific guidance based on error type and model
            if (grepl("subscript out of bounds", e$message)) {
              if (input$rfe_base_model == "glm") {
                guidance <- paste("GLM 'subscript out of bounds' error. Try:",
                                  "  Reduce CV folds to =", min(5, nrow(X) - 1),
                                  "  Reduce max subset size to =", min(nrow(X) - 5, ncol(X)),
                                  "  Use simpler CV method (e.g., 'cv' instead of 'repeatedcv')")
              } else {
                guidance <- paste("'Subscript out of bounds' error. Try:",
                                  "  Reduce CV folds to 3-5",
                                  "  Reduce feature subset sizes",
                                  "  Check for perfect class separation")
              }
            } else if (grepl("Stopping", e$message)) {
              if (input$rfe_base_model == "gbm") {
                guidance <- paste("GBM 'Stopping' error. Try:",
                                  "  Reduce n.trees to 50-200",
                                  "  Set interaction.depth to 1-3",
                                  "  Use shrinkage between 0.01-0.1",
                                  "  Increase min samples per node")
              } else if (input$rfe_base_model == "nb") {
                guidance <- paste("Naive Bayes 'Stopping' error. Try:",
                                  "  Check for features with zero variance",
                                  "  Ensure adequate samples per class",
                                  "  Consider feature preprocessing")
              } else {
                guidance <- paste("Model 'Stopping' error. Try:",
                                  "  Reduce model complexity",
                                  "  Increase sample size",
                                  "  Check data quality")
              }
            } else if (grepl("argument.*not.*vector", e$message)) {
              guidance <- paste("Data format error. Try:",
                                "  Disable parallel processing",
                                "  Check for missing values",
                                "  Ensure feature names are valid",
                                "  Use simpler CV method")
            } else {
              guidance <- paste("General RFE error for", input$rfe_base_model, ". Try:",
                                "  Reduce CV folds",
                                "  Simplify model parameters",
                                "  Check data preprocessing",
                                "  Try a different base model")
            }
            
            showNotification(
              paste("RFE Failed:", err_msg, "\n\nSuggested solutions:\n", guidance),
              type = 'error',
              duration = 15
            )
            
            # Store empty results to prevent downstream failures
            values$ml_selected_features <- data.frame(Feature = character(0))
            values$ml_importance <- data.frame()
            values$ml_performance <- paste(err_msg, "\n\nGuidance:", guidance)
            return(NULL)
          })
          if (is.null(rfe_result)) return()
          
          incProgress(0.7, detail = "Processing results...")
          
          # Extract and process results
          selected_features <- rfe_result$optVariables
          optimal_size <- rfe_result$bestSubset
          
          # Get detailed performance metrics
          performance_results <- rfe_result$results
          best_performance <- performance_results[performance_results$Variables == optimal_size, ]
          
          # Extract variable importance
          if (length(selected_features) > 0) {
            # Try to get importance from multiple sources
            importance_scores <- NULL
            
            if (!is.null(rfe_result$fit$importance)) {
              importance_scores <- rfe_result$fit$importance
              if (is.matrix(importance_scores)) {
                importance_scores <- importance_scores[, 1]  # Take first column
              }
            } else if (!is.null(rfe_result$variables)) {
              # Calculate importance from resampling results
              var_importance <- aggregate(rfe_result$variables$Overall,
                                          by = list(rfe_result$variables$var),
                                          FUN = mean, na.rm = TRUE)
              importance_scores <- setNames(var_importance$x, var_importance$Group.1)
            }
            
            # Fallback: create ranking-based importance
            if (is.null(importance_scores)) {
              importance_scores <- seq(length(selected_features), 1, by = -1)
              names(importance_scores) <- selected_features
            }
            
            # Ensure we only include selected features
            importance_scores <- importance_scores[names(importance_scores) %in% selected_features]
            
            # Create results dataframe with ALL RFE-selected features
            fs_result <- data.frame(
              Feature = names(importance_scores),
              Importance = as.numeric(importance_scores),
              Rank = rank(-importance_scores, ties.method = "first"),
              stringsAsFactors = FALSE
            )
            fs_result <- fs_result[order(-fs_result$Importance), ]
            
            # Limit to user-requested number of features
            n_features_requested <- input$feature_selection_nfeatures
            if (nrow(fs_result) > n_features_requested) {
              cat("RFE selected", nrow(fs_result), "optimal features. Limiting to top", n_features_requested, "as requested by user.\n")
              selected_result <- head(fs_result, n_features_requested)
            } else {
              selected_result <- fs_result
            }
            
            # Store results
            values$ml_selected_features <- map_numeric_ids_to_names(selected_result)
            values$ml_importance <- map_numeric_ids_to_names(fs_result)
            
            # Create comprehensive performance summary
            performance_summary <- paste0(
              "RFE Analysis Complete:\n",
              "  Base Model: ", input$rfe_base_model, "\n",
              "  CV Method: ", input$rfe_cv_method,
              if(input$rfe_cv_method == "cv") paste0(" (", input$rfe_cv_folds, "-fold)") else "",
              if(input$rfe_cv_method == "repeatedcv") paste0(" (", input$rfe_cv_folds, "-fold, ", input$rfe_cv_repeats, " repeats)") else "",
              "\n  Optimal Features (RFE): ", optimal_size,
              "\n  Features Selected: ", nrow(selected_result), " (limited to user request)",
              "\n  Best ", input$rfe_metric, ": ", round(best_performance[[input$rfe_metric]], 4),
              if("Kappa" %in% names(best_performance)) paste0("\n  Kappa: ", round(best_performance$Kappa, 4)) else "",
              if("ROC" %in% names(best_performance)) paste0("\n  ROC AUC: ", round(best_performance$ROC, 4)) else "",
              "\n  Features Tested: ", paste(range(subset_sizes), collapse = "-"),
              "\n  Selection Function: ", input$rfe_selection_function,
              if(input$rfe_parallel) paste0("\n  Parallel Processing: ", input$rfe_n_cores, " cores") else ""
            )
            
            values$ml_performance <- performance_summary
            
            # Store detailed RFE results for further analysis
            values$rfe_detailed_results <- list(
              rfe_result = rfe_result,
              performance_by_size = performance_results,
              optimal_size = optimal_size,
              subset_sizes_tested = subset_sizes,
              cv_method = input$rfe_cv_method,
              base_model = input$rfe_base_model,
              selection_function = input$rfe_selection_function
            )
            
            # Calculate train/test performance if split was enabled
            if (!is.null(values$ml_train_X) && !is.null(values$ml_test_X)) {
              cat("Calculating train/test performance for RFE...\n")
              
              # Source validation functions if not already loaded
              validation_file <- "ml_validation_functions.R"
              if (file.exists(validation_file)) {
                tryCatch({
                  source(validation_file)
                  cat("Validation functions sourced successfully\n")
                }, error = function(e) {
                  cat("Error sourcing validation functions:", e$message, "\n")
                })
              }
              
              # Get predictions on training and test sets using RFE fit object
              tryCatch({
                # Determine problem type
                is_classification <- is.factor(values$ml_train_y)
                is_binary <- is_classification && length(levels(values$ml_train_y)) == 2
                is_multiclass <- is_classification && length(levels(values$ml_train_y)) > 2
                
                cat("Problem type - Classification:", is_classification,
                    "Binary:", is_binary, "Multiclass:", is_multiclass, "\n")
                
                # Get predictions using the RFE fit object
                # Extract only selected features for prediction
                train_X_selected <- values$ml_train_X[, selected_features, drop = FALSE]
                test_X_selected <- values$ml_test_X[, selected_features, drop = FALSE]
                
                train_pred <- predict(rfe_result$fit, newdata = train_X_selected)
                test_pred <- predict(rfe_result$fit, newdata = test_X_selected)
                
                # Get probability predictions for classification
                train_prob <- NULL
                test_prob <- NULL
                if (is_classification) {
                  tryCatch({
                    train_prob <- predict(rfe_result$fit, newdata = train_X_selected, type = "prob")
                    test_prob <- predict(rfe_result$fit, newdata = test_X_selected, type = "prob")
                  }, error = function(e) {
                    cat("Warning: Could not extract probabilities:", e$message, "\n")
                  })
                }
                
                cat("Training predictions obtained:", length(train_pred), "samples\n")
                cat("Test predictions obtained:", length(test_pred), "samples\n")
                
                # Calculate metrics based on problem type
                if (is_binary && exists("calculate_binary_metrics")) {
                  cat("Calculating binary classification metrics...\n")
                  
                  # Training metrics
                  train_metrics <- calculate_binary_metrics(
                    predictions = train_pred,
                    actual = values$ml_train_y,
                  )
                  
                  # Test metrics
                  test_metrics <- calculate_binary_metrics(
                    predictions = test_pred,
                    actual = values$ml_test_y,
                  )
                  
                  values$ml_train_performance <- train_metrics
                  values$ml_test_performance <- test_metrics
                  cat("Binary classification metrics calculated and stored\n")
                  
                } else if (is_multiclass && exists("calculate_multiclass_metrics")) {
                  cat("Calculating multiclass classification metrics...\n")
                  
                  # Training metrics
                  train_metrics <- calculate_multiclass_metrics(
                    predictions = train_pred,
                    actual = values$ml_train_y,
                  )
                  
                  # Test metrics
                  test_metrics <- calculate_multiclass_metrics(
                    predictions = test_pred,
                    actual = values$ml_test_y,
                  )
                  
                  values$ml_train_performance <- train_metrics
                  values$ml_test_performance <- test_metrics
                  cat("Multiclass classification metrics calculated and stored\n")
                  
                } else if (!is_classification && exists("calculate_regression_metrics")) {
                  cat("Calculating regression metrics...\n")
                  
                  # Training metrics
                  train_metrics <- calculate_regression_metrics(
                    predictions = train_pred,
                    actual = values$ml_train_y
                  )
                  
                  # Test metrics
                  test_metrics <- calculate_regression_metrics(
                    predictions = test_pred,
                    actual = values$ml_test_y
                  )
                  
                  values$ml_train_performance <- train_metrics
                  values$ml_test_performance <- test_metrics
                  cat("Regression metrics calculated and stored\n")
                  
                } else {
                  cat("Validation functions not available, calculating basic metrics...\n")
                  # Fallback: Calculate basic metrics without validation functions
                  if (is_classification) {
                    train_acc <- sum(train_pred == values$ml_train_y) / length(values$ml_train_y)
                    test_acc <- sum(test_pred == values$ml_test_y) / length(values$ml_test_y)
                    
                    values$ml_train_performance <- list(
                      accuracy = train_acc,
                      n_samples = length(values$ml_train_y)
                    )
                    values$ml_test_performance <- list(
                      accuracy = test_acc,
                      n_samples = length(values$ml_test_y)
                    )
                  } else {
                    train_rmse <- sqrt(mean((values$ml_train_y - train_pred)^2))
                    test_rmse <- sqrt(mean((values$ml_test_y - test_pred)^2))
                    
                    values$ml_train_performance <- list(
                      rmse = train_rmse,
                      n_samples = length(values$ml_train_y)
                    )
                    values$ml_test_performance <- list(
                      rmse = test_rmse,
                      n_samples = length(values$ml_test_y)
                    )
                  }
                  cat("Basic metrics calculated and stored\n")
                }
                
              }, error = function(e) {
                cat("Error calculating performance metrics:", e$message, "\n")
                values$ml_train_performance <- list(error = e$message)
                values$ml_test_performance <- list(error = e$message)
              })
            } else {
              cat("Train/test split not enabled, skipping performance calculation\n")
            }
            
          } else {
            values$ml_selected_features <- data.frame(Feature = character(0), Importance = numeric(0), Rank = integer(0))
            values$ml_importance <- data.frame(Feature = character(0), Importance = numeric(0), Rank = integer(0))
            values$ml_performance <- paste("RFE did not select any features with method:", input$rfe_base_model)
            values$rfe_detailed_results <- NULL
          }
          
          incProgress(1.0, detail = "RFE analysis completed!")
          
          showNotification(paste("RFE feature selection completed! Selected", length(selected_features), "optimal features using", input$rfe_base_model),
                           type = "message", duration = 5)
          
          # Clean up parallel backend
          if (input$rfe_parallel && exists("cl")) {
            try(parallel::stopCluster(cl), silent = TRUE)
          }
          
        }, error = function(e) {
          # Clean up parallel backend on error
          if (input$rfe_parallel && exists("cl")) {
            try(parallel::stopCluster(cl), silent = TRUE)
          }
          showNotification(paste("RFE error:", e$message), type = "error")
          cat("RFE Error Details:\n", e$message, "\n")
          
          # Set error state for variables
          values$ml_selected_features <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_importance <- data.frame(Feature = character(0), Importance = numeric(0))
          values$ml_performance <- paste("RFE error:", e$message)
          values$rfe_detailed_results <- NULL
        })
      }
      
    }) # End withProgress
  })
  
  # Output: Selected Features Table
  output$feature_selection_table <- DT::renderDataTable({
    if (is.null(values$ml_selected_features) || nrow(values$ml_selected_features) == 0) {
      # Return empty table with appropriate column names
      empty_df <- data.frame(
        Feature = character(0),
        Importance = numeric(0)
      )
      DT::datatable(empty_df, options = list(pageLength = 10, scrollX = TRUE))
    } else {
      DT::datatable(values$ml_selected_features, options = list(pageLength = 10, scrollX = TRUE))
    }
  })
  
  # Output: Model Performance
  output$mlfs_performance_metrics <- renderPrint({
    if (is.null(values$ml_performance) || values$ml_performance == "") {
      cat("No feature selection performed yet.")
    } else {
      cat(values$ml_performance)
      
      # Display alpha grid search results if available
      if (!is.null(values$alpha_grid_results)) {
        cat("\n\nAlpha Grid Search Results:\n")
        cat("==========================\n")
        
        alpha_df <- data.frame(
          Alpha = sapply(values$alpha_grid_results, function(x) x$alpha),
          CV_Error = sapply(values$alpha_grid_results, function(x) {
            if (is.finite(x$cv_error)) round(x$cv_error, 4) else "Failed"
          })
        )
        
        # Find best alpha (minimum CV error for most metrics, maximum for AUC which is stored as negative)
        best_idx <- which.min(sapply(values$alpha_grid_results, function(x) x$cv_error))
        alpha_df$Best <- ifelse(seq_len(nrow(alpha_df)) == best_idx, " <- BEST", "")
        
        # Print the table
        print(alpha_df, row.names = FALSE)
        
        cat("\nBest Alpha:", round(values$alpha_grid_results[[best_idx]]$alpha, 3), "\n")
        cat("Alpha Range: [", round(min(alpha_df$Alpha), 3), " - ", round(max(alpha_df$Alpha), 3), "]\n")
        cat("Grid Points:", length(values$alpha_grid_results), "\n")
      }
    }
  })
  
  # Output: Feature Selection Plot (e.g., importance barplot)
  output$feature_selection_plot <- renderPlot({ 
    if (is.null(values$ml_selected_features) || nrow(values$ml_selected_features) == 0) {
      # Create empty plot with message
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "No features selected.\nPlease run feature selection first.", size = 6, hjust = 0.5) +
        theme_void() +
        xlim(0, 1) + ylim(0, 1)
    } else {
      ggplot(values$ml_selected_features, aes(x = reorder(Feature, Importance), y = Importance)) +
        geom_col(fill = "#2ecc71") +
        coord_flip() +
        labs(title = "Top Selected Features", x = "Feature", y = "Importance") +
        theme_minimal()
    }
  })
  
  # Download selected features
  output$download_selected_features <- downloadHandler(
    filename = function() {
      method_name <- if (!is.null(values$boruta_object)) "boruta" else "features"
      paste0("selected_", method_name, "_", Sys.Date(), ".csv")
    },
    content = function(file) {
      req(values$ml_selected_features)
      
      # If Boruta results available, include comprehensive information
      if (!is.null(values$boruta_stats) && ncol(values$ml_selected_features) > 2) {
        # Include all Boruta statistics for selected features
        write.csv(values$ml_selected_features, file, row.names = FALSE)
      } else {
        # Standard feature selection output
        write.csv(values$ml_selected_features, file, row.names = FALSE)
      }
    }
  )
  
  # ==============================================================================
  # ML FEATURE SELECTION PCA STATUS
  # ==============================================================================
  
  # PCA status indicator for ML Feature Selection tab
  output$mlfs_pca_status <- renderUI({
    # Check if PCA features are available
    if (is.null(values$pca_top_features) || length(values$pca_top_features) == 0) {
      # No PCA features available
      div(class = "alert alert-warning", style = "margin: 10px 0; font-size: 0.9em;",
          icon("exclamation-triangle"), " ",
          strong("No PCA Top N features available."),
          br(),
          "Run PCA analysis in the Dimensionality Reduction tab and enable 'Use PCA Top N features for downstream analysis' first."
      )
    } else {
      # PCA features are available
      n_features <- length(values$pca_top_features)
      # Convert indices to feature names for display
      feature_names <- if (!is.null(values$cleaned_molecules) && max(values$pca_top_features) <= length(values$cleaned_molecules)) {
        paste(head(values$cleaned_molecules[values$pca_top_features], 3), collapse = ", ")
      } else {
        "Features"
      }
      
      div(class = "alert alert-success", style = "margin: 10px 0; font-size: 0.9em;",
          icon("check-circle"), " ",
          strong(paste("?", n_features, "PCA features available.")),
          br(),
          "Top features: ", feature_names, if(n_features > 3) "..." else "",
          br(),
          em("These features will be used when PCA filtering is selected.")
      )
    }
  })
  
  # ==============================================================================
  # ENHANCED GLMNET OUTPUTS
  # ==============================================================================
  
  # Summary text for selected features
  output$mlfs_summary_text <- renderText({
    if (is.null(values$ml_selected_features) || nrow(values$ml_selected_features) == 0) {
      "No features selected yet. Please run feature selection first."
    } else {
      # Determine method name based on what was actually used
      method_name <- if (!is.null(values$ml_method_used)) {
        # Use stored method information
        switch(values$ml_method_used,
               "boruta" = {
                 classifier_name <- values$ml_classifier_used %||% "Random Forest"
                 paste0("Boruta (", switch(classifier_name,
                                           "ranger" = "Random Forest",
                                           "randomForest" = "Random Forest",
                                           "gbm" = "Gradient Boosting",
                                           "xgboost" = "XGBoost",
                                           classifier_name), ")")
               },
               "boruta_multiclass" = {
                 classifier_name <- values$ml_classifier_used %||% "Random Forest"
                 paste0("Boruta-Multiclass (", switch(classifier_name,
                                                      "ranger" = "Random Forest",
                                                      "randomForest" = "Random Forest",
                                                      "gbm" = "Gradient Boosting",
                                                      "xgboost" = "XGBoost",
                                                      classifier_name), ")")
               },
               "rf" = "Random Forest",
               "rfe" = "Recursive Feature Elimination",
               "permutation" = "Permutation Importance",
               "lasso" = {
                 if (!is.null(values$ml_glmnet_alpha)) {
                   if (values$ml_glmnet_alpha == 1) "LASSO"
                   else if (values$ml_glmnet_alpha == 0) "Ridge Regression"
                   else "Elastic Net"
                 } else "LASSO/ElasticNet"
               },
               values$ml_method_used)
      } else if (!is.null(values$boruta_object)) {
        # Fallback for Boruta
        classifier_name <- input$feature_selection_boruta_classifier %||% "ranger"
        paste0("Boruta (", switch(classifier_name,
                                  "ranger" = "Random Forest",
                                  "randomForest" = "Random Forest",
                                  "gbm" = "Gradient Boosting",
                                  "xgboost" = "XGBoost",
                                  classifier_name), ")")
      } else if (!is.null(values$ml_glmnet_fit)) {
        # Fallback for LASSO/ElasticNet
        if (values$ml_glmnet_alpha == 1) "LASSO"
        else if (values$ml_glmnet_alpha == 0) "Ridge Regression"
        else "Elastic Net"
      } else if (!is.null(input$feature_selection_method)) {
        # Fallback to current input
        switch(input$feature_selection_method,
               "rf" = "Random Forest",
               "rfe" = "Recursive Feature Elimination",
               "permutation" = "Permutation Importance",
               "boruta" = "Boruta",
               "lasso" = "LASSO/ElasticNet",
               "Feature Selection")
      } else {
        "Feature Selection"
      }
      
      n_selected <- nrow(values$ml_selected_features)
      n_total <- if (!is.null(values$ml_importance)) nrow(values$ml_importance) else "unknown"
      paste0(method_name, " selected ", n_selected, " features out of ", n_total, " total features.")
    }
  })
  
  # Cross-validation plot
  output$glmnet_cv_plot <- renderPlot({ 
    if (is.null(values$ml_cv_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Cross-validation plot not available.\nRun LASSO/ElasticNet with CV first.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      # Create CV plot using ggplot
      cv_data <- data.frame(
        lambda = values$ml_cv_fit$lambda,
        cvm = values$ml_cv_fit$cvm,
        cvup = values$ml_cv_fit$cvup,
        cvlo = values$ml_cv_fit$cvlo,
        nzero = values$ml_cv_fit$nzero
      )
      
      ggplot(cv_data, aes(x = log(lambda))) +
        geom_errorbar(aes(ymin = cvlo, ymax = cvup), color = "grey60", alpha = 0.7) +
        geom_point(aes(y = cvm), color = "#e74c3c", size = 1.5) +
        geom_vline(xintercept = log(values$ml_cv_fit$lambda.min), linetype = "dashed", color = "#3498db") +
        geom_vline(xintercept = log(values$ml_cv_fit$lambda.1se), linetype = "dashed", color = "#2ecc71") +
        labs(title = "Cross-Validation Curve",
             x = "log(?)",
             y = "Cross-Validation Error",
             subtitle = "Blue: ?.min, Green: ?.1se") +
        theme_minimal() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
          plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
          axis.title.x = element_text(size = 12, face = "bold"),
          axis.title.y = element_text(size = 12, face = "bold"),
          axis.text.x = element_text(size = 11, face = "bold"),
          axis.text.y = element_text(size = 11, face = "bold"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          axis.line = element_line(color = "black", size = 0.5)
        )
    }
  })
  
  # Regularization path plot
  output$glmnet_path_plot <- renderPlot({ 
    if (is.null(values$ml_glmnet_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Regularization path not available.\nRun LASSO/ElasticNet first.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      # Extract coefficients across lambda path
      fit <- values$ml_glmnet_fit
      lambda_seq <- fit$lambda
      # Handle multinomial (list of beta matrices) by aggregating mean absolute value
      if (is.list(fit$beta)) {
        beta_list <- lapply(fit$beta, function(m) {
          bm <- as.matrix(m)
          # Ensure consistent feature ordering
          bm
        }, res = UI_PLOT_RES)
        # Use first class rownames as base
        feature_names_raw <- rownames(beta_list[[1]])
        # Aggregate mean absolute coefficients across classes (exclude intercept later)
        abs_sum <- Reduce("+", lapply(beta_list, function(bm) abs(bm))) / length(beta_list)
        beta_matrix <- abs_sum
      } else {
        beta_matrix <- as.matrix(fit$beta)
      }
      # Map feature names if generic/numeric (exclude intercept row if present later)
      feature_names <- rownames(beta_matrix)
      if (!is.null(feature_names) && !is.null(values$cleaned_molecules)) {
        # Detect intercept (usually '(Intercept)')
        has_intercept <- any(tolower(feature_names) %in% c("(intercept)", "intercept"))
        if (has_intercept) {
          intercept_idx <- which(tolower(feature_names) %in% c("(intercept)", "intercept"))
          feature_part <- feature_names[-intercept_idx]
        } else {
          feature_part <- feature_names
        }
        if (length(feature_part) == length(values$cleaned_molecules) &&
            (all(grepl("^Feature_[0-9]+$", feature_part)) || all(suppressWarnings(!is.na(as.numeric(feature_part)))))) {
          mapped <- values$cleaned_molecules
          if (has_intercept) {
            feature_names[-intercept_idx] <- mapped
          } else {
            feature_names <- mapped
          }
          rownames(beta_matrix) <- feature_names
        }
      }
      
      # Convert to long format for ggplot
      path_data <- data.frame(
        lambda = rep(lambda_seq, each = nrow(beta_matrix)),
        coefficient = as.vector(beta_matrix),
        feature = rep(rownames(beta_matrix), length(lambda_seq)),
        stringsAsFactors = FALSE
      )
      
      # Filter to show only top features (to avoid overcrowding)
      if (!is.null(values$ml_importance) && nrow(values$ml_importance) > 0) {
        top_features <- head(values$ml_importance$Feature, 30)
        filtered <- path_data[path_data$feature %in% top_features, ]
        if (nrow(filtered) > 0) {
          path_data <- filtered
        } else {
          # Fallback: choose top features by variance across path
          coef_var <- aggregate(coefficient ~ feature, data = path_data, function(x) sd(x, na.rm = TRUE))
          top_by_var <- head(coef_var[order(-coef_var$coefficient), "feature"], 30)
          path_data <- path_data[path_data$feature %in% top_by_var, ]
        }
      }
      # If still too many, limit
      if (length(unique(path_data$feature)) > 40) {
        keep_feats <- unique(path_data$feature)[1:40]
        path_data <- path_data[path_data$feature %in% keep_feats, ]
      }
      
      ggplot(path_data, aes(x = log(lambda), y = coefficient, color = feature)) +
        geom_line(alpha = 0.7, size = 0.8) +
        geom_vline(xintercept = log(values$ml_lambda_best), linetype = "dashed", color = "red") +
        labs(title = "Regularization Path",
             x = "log(?)",
             y = "Coefficient Value",
             subtitle = paste("Red line: selected ? =", round(values$ml_lambda_best, 4))) +
        theme_minimal() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
          plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
          axis.title.x = element_text(size = 12, face = "bold"),
          axis.title.y = element_text(size = 12, face = "bold"),
          axis.text.x = element_text(size = 11, face = "bold"),
          axis.text.y = element_text(size = 11, face = "bold"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          axis.line = element_line(color = "black", size = 0.5),
          legend.position = "none"  # Hide legend to reduce clutter
        )
    }
  })
  
  # Lambda information
  output$lambda_info <- renderPrint({
    if (is.null(values$ml_cv_fit) || is.null(values$ml_lambda_best)) {
      cat("Lambda information not available.")
    } else {
      cat("Lambda Selection Information:\n")
      cat("===========================\n")
      cat("Selected lambda:", values$ml_lambda_best, "\n")
      if (!is.null(values$ml_cv_fit$lambda.min)) {
        cat("Lambda min (minimum CV error):", values$ml_cv_fit$lambda.min, "\n")
        cat("Lambda 1se (1-SE rule):", values$ml_cv_fit$lambda.1se, "\n")
      }
      cat("Number of non-zero coefficients:", sum(values$ml_importance$Importance > 0), "\n")
      if (!is.null(values$ml_glmnet_fit)) {
        cat("Total lambda values tested:", length(values$ml_glmnet_fit$lambda), "\n")
      }
    }
  })
  
  # Alpha Grid Search Plot
  output$alpha_grid_plot <- renderPlot({ 
    if (is.null(values$alpha_grid_results)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Alpha grid search results not available.\nEnable 'Auto-tune Alpha' and run LASSO/ElasticNet.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      # Prepare data for plotting
      alpha_df <- data.frame(
        Alpha = sapply(values$alpha_grid_results, function(x) x$alpha),
        CV_Error = sapply(values$alpha_grid_results, function(x) {
          if (is.finite(x$cv_error)) x$cv_error else NA
        }, res = UI_PLOT_RES)
      )
      
      # Remove failed results
      alpha_df <- alpha_df[!is.na(alpha_df$CV_Error), ]
      
      if (nrow(alpha_df) == 0) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = "All alpha values failed.\nTry adjusting the alpha grid range.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      } else {
        # Find best alpha
        best_idx <- which.min(alpha_df$CV_Error)
        best_alpha <- alpha_df$Alpha[best_idx]
        
        # Create the plot
        ggplot(alpha_df, aes(x = Alpha, y = CV_Error)) +
          geom_line(color = "#3498db", size = 1.2) +
          geom_point(color = "#e74c3c", size = 2.5) +
          geom_point(data = alpha_df[best_idx, ], aes(x = Alpha, y = CV_Error),
                     color = "#2ecc71", size = 4, shape = 17) +
          labs(title = "Alpha Grid Search Results",
               x = "Alpha (0 = Ridge, 1 = LASSO)",
               y = "Cross-Validation Error",
               subtitle = paste("Best Alpha:", round(best_alpha, 3), "(Green Triangle)")) +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 11, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          ) +
          scale_x_continuous(breaks = seq(0, 1, by = 0.2))
      }
    }
  })
  
  # Check if alpha grid results are available (for conditional panel)
  output$alpha_grid_available <- reactive({
    !is.null(values$alpha_grid_results)
  })
  outputOptions(output, "alpha_grid_available", suspendWhenHidden = FALSE)
  
  # Enhanced feature importance plot
  output$feature_importance_plot <- renderPlot({ 
    if (is.null(values$ml_importance) || nrow(values$ml_importance) == 0) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "No features available.\nPlease run feature selection first.",
                 size = 6, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      top_n <- min(input$importance_top_n %||% 20, nrow(values$ml_importance))
      plot_data <- head(values$ml_importance, top_n)
      
      if (input$importance_plot_type == "bar") {
        ggplot(plot_data, aes(x = reorder(Feature, Importance), y = Importance)) +
          geom_col(fill = "#3498db", alpha = 0.8) +
          coord_flip() +
          labs(title = paste("Top", top_n, "Feature Importance"),
               x = "Feature", y = "Importance Score") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 10, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          )
        
      } else if (input$importance_plot_type == "dot") {
        ggplot(plot_data, aes(x = Importance, y = reorder(Feature, Importance))) +
          geom_point(color = "#e74c3c", size = 3) +
          geom_segment(aes(x = 0, xend = Importance, yend = reorder(Feature, Importance)),
                       color = "#e74c3c", alpha = 0.6) +
          labs(title = paste("Top", top_n, "Feature Importance"),
               y = "Feature", x = "Importance Score") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 10, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          )
        
      } else if (input$importance_plot_type == "heatmap") {
        # Create a single-column heatmap
        plot_data$rank <- seq_len(nrow(plot_data))
        ggplot(plot_data, aes(x = 1, y = reorder(Feature, Importance), fill = Importance)) +
          geom_tile() +
          scale_fill_gradient(low = "white", high = "#e74c3c") +
          labs(title = paste("Top", top_n, "Feature Importance Heatmap"),
               y = "Feature", x = "") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_blank(),
            axis.text.y = element_text(size = 10, face = "bold"),
            axis.ticks.x = element_blank(),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          )
        
      } else if (input$importance_plot_type == "boruta_history") {
        # Boruta importance history plot (plotImpHistory equivalent)
        if (is.null(values$boruta_plot_data) || is.null(values$boruta_plot_data$ImpHistory)) {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "Boruta importance history not available.\nRun Boruta feature selection first.",
                     size = 5, hjust = 0.5) +
            theme_void() + xlim(0, 1) + ylim(0, 1)
        } else {
          tryCatch({
            # Create Boruta importance history plot
            imp_history <- values$boruta_plot_data$ImpHistory
            final_decision <- values$boruta_plot_data$finalDecision
            real_names <- values$boruta_plot_data$realFeatureNames %||% NULL
            
            # Validate data structure
            if (is.null(imp_history) || is.null(final_decision)) {
              stop("Missing importance history or decision data")
            }
            
            # Convert importance history to long format with validation
            n_runs <- ncol(imp_history)
            n_features <- nrow(imp_history)
            feature_names <- rownames(imp_history)
            rn <- rownames(imp_history); cn <- colnames(imp_history)
            # If orientation seems flipped (features are columns), transpose
            if (!is.null(cn) && length(cn) > length(rn) && length(cn) == length(final_decision)) {
              cat("Debug Boruta History: Detected features in columns; transposing ImpHistory.\n")
              imp_history <- t(imp_history)
              rn <- rownames(imp_history); cn <- colnames(imp_history)
              feature_names <- rownames(imp_history)
              n_runs <- ncol(imp_history)
              n_features <- nrow(imp_history)
            } else if (!is.null(cn) && length(cn) == length(final_decision) && (is.null(rn) || length(rn) != length(final_decision))) {
              cat("Debug Boruta History: Column name length matches decisions; transposing ImpHistory.\n")
              imp_history <- t(imp_history)
              rn <- rownames(imp_history); cn <- colnames(imp_history)
              feature_names <- rownames(imp_history)
              n_runs <- ncol(imp_history)
              n_features <- nrow(imp_history)
            }
            # If rownames are missing or generic, try to rebuild from stored real names
            if (is.null(feature_names)) {
              if (!is.null(real_names)) {
                # ImpHistory has 2x rows of real features (real + shadow). We'll assign real names in order;
                # shadow rows will still be filtered out by the '^shadow' check.
                # Attempt to detect which rows are shadow; if none, assign real names to first ncol(X) rows.
                rn <- rep(NA_character_, nrow(imp_history))
                # Prefer existing hint in Boruta: shadow features are typically named 'shadow...'
                # If not present, we'll just assign placeholders for non-shadow and let filtering work.
                # Assign real names to non-shadow rows by index up to length(real_names)
                assignable <- min(length(real_names), nrow(imp_history))
                rn[seq_len(assignable)] <- real_names[seq_len(assignable)]
                rownames(imp_history) <- rn
                feature_names <- rownames(imp_history)
              } else {
                feature_names <- paste0("Feature_", seq_len(n_features))
              }
            }
            # Safeguard: if rownames are missing, create default feature names
            if (is.null(feature_names)) {
              feature_names <- paste0("Feature_", seq_len(n_features))
            }
            
            cat("Debug Boruta History: n_runs:", n_runs, "n_features:", n_features,
                "feature_names length:", length(feature_names),
                "final_decision length:", length(final_decision), "\n")
            
            # Note: ImpHistory rows include shadow attributes; finalDecision covers only real features.
            # We'll align decisions to non-shadow features by name, not by position.
            if (length(feature_names) != length(final_decision)) {
              cat("Debug Boruta History: Length mismatch (ImpHistory rows:", length(feature_names),
                  "finalDecision length:", length(final_decision), ") -- will align by name.\n")
            }
            
            # Remove shadow features before creating data frame
            # Shadow attributes in Boruta typically start with the prefix 'shadow'
            non_shadow_idx <- !grepl("^shadow", feature_names, ignore.case = TRUE)
            cat("Debug Boruta History: shadow rows:", sum(!non_shadow_idx),
                "non-shadow rows:", sum(non_shadow_idx), "\n")
            if (sum(non_shadow_idx) == 0) {
              # Graceful fallback: show informative message instead of error
              fallback_msg <- paste0(
                "Boruta history: No non-shadow features found.\n",
                "Only shadow attributes are present in ImpHistory.\n",
                "Try rerunning Boruta with more iterations (maxRuns), different importance source/classifier,\n",
                "or ensure real features weren't filtered out earlier."
              )
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5, label = fallback_msg, size = 4.5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            feature_names <- feature_names[non_shadow_idx]
            imp_history <- imp_history[non_shadow_idx, , drop = FALSE]
            n_features <- sum(non_shadow_idx)
            
            # Map decisions by feature name when possible; otherwise, best-effort fallback
            dec_names <- names(final_decision)
            if (!is.null(dec_names)) {
              mapped_decisions <- final_decision[feature_names]
            } else if (length(final_decision) == length(feature_names)) {
              mapped_decisions <- final_decision
            } else {
              mapped_decisions <- rep("Tentative", length(feature_names))
            }
            
            # Standardize decision labels to the canonical set
            mapped_decisions <- as.character(mapped_decisions)
            mapped_decisions[grepl("^conf", mapped_decisions, ignore.case = TRUE)] <- "Confirmed"
            mapped_decisions[grepl("^rej", mapped_decisions, ignore.case = TRUE)] <- "Rejected"
            mapped_decisions[grepl("^ten", mapped_decisions, ignore.case = TRUE)] <- "Tentative"
            # Any unknown or NA -> Tentative for visualization
            mapped_decisions[is.na(mapped_decisions) | !(mapped_decisions %in% c("Confirmed","Rejected","Tentative"))] <- "Tentative"
            
            # Prefer the exact selected features (top list) from the Selected Features table
            chosen_names <- NULL
            if (!is.null(values$ml_selected_features) &&
                is.data.frame(values$ml_selected_features) &&
                nrow(values$ml_selected_features) > 0 &&
                !is.null(values$ml_selected_features$Feature)) {
              # Take top-20 from the table order to ensure consistency
              chosen_names <- head(as.character(values$ml_selected_features$Feature), 20)
            }
            
            # Robust name matching against ImpHistory feature names
            chosen_idx <- integer(0)
            if (!is.null(chosen_names) && length(chosen_names) > 0) {
              fn <- as.character(feature_names)
              # 1) direct match
              idx1 <- match(chosen_names, fn)
              # 2) make.names match
              idx2 <- match(make.names(chosen_names, unique = FALSE), make.names(fn, unique = FALSE))
              # 3) case-insensitive match on normalized
              idx3 <- match(tolower(make.names(chosen_names, unique = FALSE)), tolower(make.names(fn, unique = FALSE)))
              chosen_idx <- unique(na.omit(c(idx1, idx2, idx3)))
              cat("Debug Boruta History: chosen table names (head):", paste(head(chosen_names, 5), collapse=", "), "\n")
              cat("Debug Boruta History: matches found:", length(chosen_idx), "\n")
            }
            
            if (length(chosen_idx) == 0) {
              cat("Debug Boruta History: No matches between Selected Features and ImpHistory names.\n")
              cat("Debug Boruta History: ImpHistory feature names (head):", paste(head(feature_names, 5), collapse=", "), "\n")
              # Fallback: compute top 20 confirmed by mean importance
              confirmed_idx <- which(mapped_decisions == "Confirmed")
              if (length(confirmed_idx) == 0) {
                fallback_msg <- paste0(
                  "Boruta history: No confirmed features to display.\n",
                  "Consider increasing maxRuns or adjusting importance source/classifier."
                )
                return(ggplot() +
                         annotate("text", x = 0.5, y = 0.5, label = fallback_msg, size = 4.5, hjust = 0.5) +
                         theme_void() + xlim(0, 1) + ylim(0, 1))
              }
              mean_importance <- apply(imp_history[confirmed_idx, , drop = FALSE], 1, mean, na.rm = TRUE)
              ord <- order(mean_importance, decreasing = TRUE)
              top_n <- min(20, length(confirmed_idx))
              chosen_idx <- confirmed_idx[ord][seq_len(top_n)]
            }
            
            feature_names <- feature_names[chosen_idx]
            mapped_decisions <- mapped_decisions[chosen_idx]
            imp_history <- imp_history[chosen_idx, , drop = FALSE]
            n_features <- length(chosen_idx)
            
            # Map generic feature IDs (Feature_#/X##/digits) to cleaned names if available
            if (!is.null(values$cleaned_molecules)) {
              map_feat_names_hist <- function(x) {
                ix <- suppressWarnings(as.integer(sub("^Feature_", "", x)))
                ix2 <- suppressWarnings(as.integer(sub("^X", "", x)))
                ix_num <- suppressWarnings(as.integer(x))
                res <- x
                if (!is.na(ix) && ix >= 1 && ix <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix]
                else if (!is.na(ix2) && ix2 >= 1 && ix2 <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix2]
                else if (!is.na(ix_num) && ix_num >= 1 && ix_num <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix_num]
                res
              }
              feature_names <- vapply(feature_names, map_feat_names_hist, character(1))
            }
            
            # Create data frame with validated dimensions (after mapping feature names)
            history_data <- data.frame(
              Run = rep(1:n_runs, each = n_features),
              Feature = rep(feature_names, n_runs),
              Importance = as.vector(imp_history),
              Decision = rep(mapped_decisions, n_runs),
              stringsAsFactors = FALSE
            )
            
            # Remove any rows with NA importance values
            history_data <- history_data[!is.na(history_data$Importance), ]
            
            if (nrow(history_data) == 0) {
              stop("No valid importance data after filtering")
            }
            
            # Create colors based on decision
            decision_colors <- c("Confirmed" = "#2ecc71", "Rejected" = "#e74c3c", "Tentative" = "#f39c12")
            
            ggplot(history_data, aes(x = Run, y = Importance, color = Decision)) +
              geom_line(aes(group = Feature), alpha = 0.6) +
              facet_wrap(~ Feature, scales = "free_y", ncol = 4) +
              scale_color_manual(values = decision_colors) +
              labs(title = "Boruta Importance History",
                   x = "Iteration", y = "Importance Score",
                   subtitle = paste("Top", n_features, "confirmed features (from selection) across", n_runs, "iterations")) +
              theme_minimal() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                plot.subtitle = element_text(hjust = 0.5, size = 12),
                axis.title.x = element_text(size = 12, face = "bold"),
                axis.title.y = element_text(size = 12, face = "bold"),
                strip.text = element_text(size = 8, face = "bold"),
                legend.title = element_text(face = "bold"),
                panel.border = element_rect(color = "gray", fill = NA, size = 0.5)
              )
            
          }, error = function(e) {
            cat("Debug Boruta History Error:", e$message, "\n")
            ggplot() +
              annotate("text", x = 0.5, y = 0.5,
                       label = paste("Error creating Boruta history plot:\n", e$message),
                       size = 5, hjust = 0.5) +
              theme_void() + xlim(0, 1) + ylim(0, 1)
          })
        }
        
      } else if (input$importance_plot_type == "boruta_box") {
        # Boruta box plot visualization (similar to plot.Boruta)
        if (is.null(values$boruta_object)) {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "Boruta results not available.\nRun Boruta feature selection first.",
                     size = 5, hjust = 0.5) +
            theme_void() + xlim(0, 1) + ylim(0, 1)
        } else {
          tryCatch({
            # Use Boruta's built-in plotting but capture as ggplot
            if (!requireNamespace("Boruta", quietly = TRUE)) {
              ggplot() +
                annotate("text", x = 0.5, y = 0.5,
                         label = "Boruta package required for box plot.",
                         size = 5, hjust = 0.5) +
                theme_void() + xlim(0, 1) + ylim(0, 1)
            } else {
              # Extract data for custom ggplot box plot
              imp_history <- values$boruta_plot_data$ImpHistory
              final_decision <- values$boruta_plot_data$finalDecision
              real_names <- values$boruta_plot_data$realFeatureNames %||% NULL
              
              if (is.null(imp_history) || is.null(final_decision)) {
                ggplot() +
                  annotate("text", x = 0.5, y = 0.5,
                           label = "Insufficient Boruta data for box plot.",
                           size = 5, hjust = 0.5) +
                  theme_void() + xlim(0, 1) + ylim(0, 1)
              } else {
                # Validate and prepare data with dimension checks
                n_runs <- ncol(imp_history)
                n_features <- nrow(imp_history)
                feature_names <- rownames(imp_history)
                rn <- rownames(imp_history); cn <- colnames(imp_history)
                if (!is.null(cn) && length(cn) > length(rn) && length(cn) == length(final_decision)) {
                  cat("Debug Boruta Box: Detected features in columns; transposing ImpHistory.\n")
                  imp_history <- t(imp_history)
                  rn <- rownames(imp_history); cn <- colnames(imp_history)
                  feature_names <- rownames(imp_history)
                  n_runs <- ncol(imp_history)
                  n_features <- nrow(imp_history)
                } else if (!is.null(cn) && length(cn) == length(final_decision) && (is.null(rn) || length(rn) != length(final_decision))) {
                  cat("Debug Boruta Box: Column name length matches decisions; transposing ImpHistory.\n")
                  imp_history <- t(imp_history)
                  rn <- rownames(imp_history); cn <- colnames(imp_history)
                  feature_names <- rownames(imp_history)
                  n_runs <- ncol(imp_history)
                  n_features <- nrow(imp_history)
                }
                if (is.null(feature_names)) {
                  if (!is.null(real_names)) {
                    rn <- rep(NA_character_, nrow(imp_history))
                    assignable <- min(length(real_names), nrow(imp_history))
                    rn[seq_len(assignable)] <- real_names[seq_len(assignable)]
                    rownames(imp_history) <- rn
                    feature_names <- rownames(imp_history)
                  } else {
                    feature_names <- paste0("Feature_", seq_len(n_features))
                  }
                }
                
                cat("Debug Boruta Box: n_runs:", n_runs, "n_features:", n_features,
                    "feature_names length:", length(feature_names),
                    "final_decision length:", length(final_decision), "\n")
                
                # Note: ImpHistory includes shadow rows; finalDecision is for real features only.
                if (length(feature_names) != length(final_decision)) {
                  cat("Debug Boruta Box: Length mismatch (ImpHistory rows:", length(feature_names),
                      "finalDecision length:", length(final_decision), ") -- will align by name.\n")
                }
                
                # Remove shadow features before creating data frame
                non_shadow_idx <- !grepl("^shadow", feature_names, ignore.case = TRUE)
                cat("Debug Boruta Box: shadow rows:", sum(!non_shadow_idx),
                    "non-shadow rows:", sum(non_shadow_idx), "\n")
                if (sum(non_shadow_idx) == 0) {
                  # Graceful fallback plot with guidance
                  fallback_msg <- paste0(
                    "Boruta box plot: No non-shadow features found.\n",
                    "Only shadow attributes are present in ImpHistory.\n",
                    "Consider increasing maxRuns, adjusting p-value thresholds,\n",
                    "or switching the classifier/importance source."
                  )
                  return(ggplot() +
                           annotate("text", x = 0.5, y = 0.5, label = fallback_msg, size = 4.5, hjust = 0.5) +
                           theme_void() + xlim(0, 1) + ylim(0, 1))
                }
                
                feature_names <- feature_names[non_shadow_idx]
                imp_history <- imp_history[non_shadow_idx, , drop = FALSE]
                n_features <- sum(non_shadow_idx)
                
                # Map decisions by feature name when possible; otherwise fallback
                dec_names <- names(final_decision)
                if (!is.null(dec_names)) {
                  mapped_decisions <- final_decision[feature_names]
                } else if (length(final_decision) == length(feature_names)) {
                  mapped_decisions <- final_decision
                } else {
                  mapped_decisions <- rep("Tentative", length(feature_names))
                }
                
                # Standardize decision labels
                mapped_decisions <- as.character(mapped_decisions)
                mapped_decisions[grepl("^conf", mapped_decisions, ignore.case = TRUE)] <- "Confirmed"
                mapped_decisions[grepl("^rej", mapped_decisions, ignore.case = TRUE)] <- "Rejected"
                mapped_decisions[grepl("^ten", mapped_decisions, ignore.case = TRUE)] <- "Tentative"
                mapped_decisions[is.na(mapped_decisions) | !(mapped_decisions %in% c("Confirmed","Rejected","Tentative"))] <- "Tentative"
                
                # Prefer the exact selected features (top list) from the Selected Features table
                chosen_names <- NULL
                if (!is.null(values$ml_selected_features) &&
                    is.data.frame(values$ml_selected_features) &&
                    nrow(values$ml_selected_features) > 0 &&
                    !is.null(values$ml_selected_features$Feature)) {
                  chosen_names <- head(as.character(values$ml_selected_features$Feature), 20)
                }
                
                # Robust name matching against ImpHistory feature names
                chosen_idx <- integer(0)
                if (!is.null(chosen_names) && length(chosen_names) > 0) {
                  fn <- as.character(feature_names)
                  idx1 <- match(chosen_names, fn)
                  idx2 <- match(make.names(chosen_names, unique = FALSE), make.names(fn, unique = FALSE))
                  idx3 <- match(tolower(make.names(chosen_names, unique = FALSE)), tolower(make.names(fn, unique = FALSE)))
                  chosen_idx <- unique(na.omit(c(idx1, idx2, idx3)))
                  cat("Debug Boruta Box: chosen table names (head):", paste(head(chosen_names, 5), collapse=", "), "\n")
                  cat("Debug Boruta Box: matches found:", length(chosen_idx), "\n")
                }
                
                if (length(chosen_idx) == 0) {
                  cat("Debug Boruta Box: No matches between Selected Features and ImpHistory names.\n")
                  cat("Debug Boruta Box: ImpHistory feature names (head):", paste(head(feature_names, 5), collapse=", "), "\n")
                  confirmed_idx <- which(mapped_decisions == "Confirmed")
                  if (length(confirmed_idx) == 0) {
                    fallback_msg <- paste0(
                      "Boruta box plot: No confirmed features to display.\n",
                      "Consider increasing maxRuns or adjusting importance source/classifier."
                    )
                    return(ggplot() +
                             annotate("text", x = 0.5, y = 0.5, label = fallback_msg, size = 4.5, hjust = 0.5) +
                             theme_void() + xlim(0, 1) + ylim(0, 1))
                  }
                  mean_importance <- apply(imp_history[confirmed_idx, , drop = FALSE], 1, mean, na.rm = TRUE)
                  ord <- order(mean_importance, decreasing = TRUE)
                  top_n <- min(20, length(confirmed_idx))
                  chosen_idx <- confirmed_idx[ord][seq_len(top_n)]
                }
                
                feature_names <- feature_names[chosen_idx]
                # Map generic feature names to cleaned names if available
                if (!is.null(values$cleaned_molecules)) {
                  map_feat_names_box <- function(x) {
                    ix <- suppressWarnings(as.integer(sub("^Feature_", "", x)))
                    ix2 <- suppressWarnings(as.integer(sub("^X", "", x)))
                    ix_num <- suppressWarnings(as.integer(x))
                    res <- x
                    if (!is.na(ix) && ix >= 1 && ix <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix]
                    else if (!is.na(ix2) && ix2 >= 1 && ix2 <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix2]
                    else if (!is.na(ix_num) && ix_num >= 1 && ix_num <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix_num]
                    res
                  }
                  feature_names <- vapply(feature_names, map_feat_names_box, character(1))
                }
                mapped_decisions <- mapped_decisions[chosen_idx]
                imp_history <- imp_history[chosen_idx, , drop = FALSE]
                n_features <- length(chosen_idx)
                
                # Convert to long format for box plot with validated dimensions
                box_data <- data.frame(
                  Feature = rep(feature_names, each = n_runs),
                  Importance = as.vector(imp_history),
                  Decision = rep(mapped_decisions, each = n_runs),
                  stringsAsFactors = FALSE
                )
                
                # Remove NA values
                box_data <- box_data[!is.na(box_data$Importance), ]
                
                if (nrow(box_data) == 0) {
                  stop("No valid importance data after filtering")
                }
                
                # Filter to confirmed and rejected features (exclude tentative for clarity)
                box_data <- box_data[box_data$Decision %in% c("Confirmed", "Rejected"), ]
                
                if (nrow(box_data) == 0) {
                  # If no confirmed/rejected features, include all decisions
                  box_data <- data.frame(
                    Feature = rep(feature_names, each = n_runs),
                    Importance = as.vector(imp_history),
                    Decision = rep(final_decision, each = n_runs),
                    stringsAsFactors = FALSE
                  )
                  box_data <- box_data[!is.na(box_data$Importance), ]
                }
                
                # Order features by median importance
                if (nrow(box_data) > 0) {
                  feature_medians <- tapply(box_data$Importance, box_data$Feature, median, na.rm = TRUE)
                  feature_order <- names(sort(feature_medians, decreasing = TRUE))
                  
                  box_data$Feature <- factor(box_data$Feature, levels = feature_order)
                  
                  # Limit to top features for readability
                  top_features <- head(feature_order, 25)
                  box_data <- box_data[box_data$Feature %in% top_features, ]
                  
                  decision_colors <- c("Confirmed" = "#2ecc71", "Rejected" = "#e74c3c", "Tentative" = "#f39c12")
                  
                  ggplot(box_data, aes(x = Feature, y = Importance, fill = Decision)) +
                    geom_boxplot(alpha = 0.7, outlier.alpha = 0.5) +
                    scale_fill_manual(values = decision_colors) +
                    coord_flip() +
                    labs(title = "Boruta Feature Selection Results",
                         x = "Feature", y = "Importance Distribution",
                         subtitle = paste("Box plots of importance across", n_runs, "iterations")) +
                    theme_minimal() +
                    theme(
                      plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                      plot.subtitle = element_text(hjust = 0.5, size = 12),
                      axis.title.x = element_text(size = 12, face = "bold"),
                      axis.title.y = element_text(size = 12, face = "bold"),
                      axis.text.y = element_text(size = 10, face = "bold"),
                      legend.title = element_text(face = "bold"),
                      panel.grid.minor = element_blank(),
                      panel.border = element_rect(color = "black", fill = NA, size = 1)
                    )
                } else {
                  stop("No features available for box plot after filtering")
                }
              }
            }
          }, error = function(e) {
            ggplot() +
              annotate("text", x = 0.5, y = 0.5,
                       label = paste("Error creating Boruta box plot:", e$message),
                       size = 5, hjust = 0.5) +
              theme_void() + xlim(0, 1) + ylim(0, 1)
          })
        }
      }
    }
  })
  
  # Model information
  output$mlfs_model_info <- renderPrint({
    if (!is.null(values$boruta_object) && !is.null(values$boruta_stats)) {
      # Show Boruta information
      cat("Boruta Feature Selection Results:\n")
      cat("=================================\n")
      
      stats <- values$boruta_stats
      decision_summary <- table(stats$decision)
      
      cat("Algorithm: Boruta (All-relevant feature selection)\n")
      
      # Show classifier information
      classifier_name <- input$feature_selection_boruta_classifier %||% "ranger"
      cat("Base Classifier:", switch(classifier_name,
                                     "ranger" = "Random Forest (ranger)",
                                     "randomForest" = "Random Forest (randomForest)",
                                     "gbm" = "Gradient Boosting Machine",
                                     "xgboost" = "XGBoost",
                                     classifier_name), "\n")
      
      cat("Importance Source:", input$feature_selection_boruta_importance_source %||% "getImpRfZ", "\n")
      cat("Maximum Runs:", input$feature_selection_boruta_max_runs %||% 100, "\n")
      cat("P-Value Threshold:", input$feature_selection_boruta_p_value %||% 0.01, "\n")
      
      # Classifier-specific parameters
      if (classifier_name %in% c("ranger", "randomForest")) {
        cat("Number of Trees:", input$feature_selection_boruta_ntree %||% 500, "\n")
      } else if (classifier_name == "gbm") {
        cat("GBM Trees:", input$feature_selection_boruta_gbm_trees %||% 100, "\n")
      } else if (classifier_name == "xgboost") {
        cat("XGBoost Rounds:", input$feature_selection_boruta_xgb_rounds %||% 100, "\n")
      }
      
      cat("\nFeature Decision Summary:\n")
      cat("------------------------\n")
      if ("Confirmed" %in% names(decision_summary)) {
        cat("Confirmed features:", decision_summary[["Confirmed"]], "\n")
      }
      if ("Rejected" %in% names(decision_summary)) {
        cat("Rejected features:", decision_summary[["Rejected"]], "\n")
      }
      if ("Tentative" %in% names(decision_summary)) {
        cat("Tentative features:", decision_summary[["Tentative"]], "\n")
      }
      
      total_features <- nrow(stats)
      confirmed_features <- sum(stats$decision == "Confirmed")
      cat("Total features analyzed:", total_features, "\n")
      cat("Selection rate:", round(confirmed_features / total_features * 100, 2), "%\n")
      
      if (input$feature_selection_boruta_tentative_fix %||% TRUE) {
        cat("Tentative Rough Fix: Applied\n")
      } else {
        cat("Tentative Rough Fix: Not applied\n")
      }
      
      # Show statistics for confirmed features
      if (confirmed_features > 0) {
        confirmed_stats <- stats[stats$decision == "Confirmed", ]
        cat("\nConfirmed Features Statistics:\n")
        cat("-----------------------------\n")
        cat("Mean importance:", round(mean(confirmed_stats$meanImp), 4), "\n")
        cat("Median importance:", round(median(confirmed_stats$meanImp), 4), "\n")
        cat("Min importance:", round(min(confirmed_stats$meanImp), 4), "\n")
        cat("Max importance:", round(max(confirmed_stats$meanImp), 4), "\n")
        
        # Handle pValue which might be NA for custom importance functions
        if (all(is.na(confirmed_stats$pValue))) {
          cat("P-values: Not available (custom importance function)\n")
        } else {
          cat("Mean p-value:", round(mean(confirmed_stats$pValue, na.rm = TRUE), 6), "\n")
        }
      }
      
    } else if (!is.null(values$ml_glmnet_fit)) {
      # Show LASSO/ElasticNet information
      cat("Model Information:\n")
      cat("=================\n")
      cat("Method:", ifelse(values$ml_glmnet_alpha == 1, "LASSO",
                            ifelse(values$ml_glmnet_alpha == 0, "Ridge", "Elastic Net")), "\n")
      cat("Alpha (L1/L2 mix):", values$ml_glmnet_alpha, "\n")
      cat("Family:", values$ml_glmnet_family, "\n")
      cat("Number of features:", ncol(values$ml_X_matrix), "\n")
      cat("Number of observations:", nrow(values$ml_X_matrix), "\n")
      if (is.factor(values$ml_y_response)) {
        cat("Response classes:", paste(levels(values$ml_y_response), collapse = ", "), "\n")
      }
      cat("Selected lambda:", values$ml_lambda_best, "\n")
    } else {
      cat("No model information available.")
    }
  })
  
  # ROC plot for binary classification
  output$mlfs_roc_plot <- renderPlot({ 
    if (is.null(values$ml_glmnet_fit) || values$ml_glmnet_family != "binomial") {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "ROC curve only available\nfor binary classification.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      # Use proper roc.glmnet function for binomial data
      if (!requireNamespace("glmnet", quietly = TRUE)) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = "glmnet package required\nfor ROC analysis.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      } else {
        tryCatch({
          # Check if we have a CV fit with keep=TRUE for prevlidated predictions
          if (!is.null(values$ml_cv_fit) && !is.null(values$ml_cv_fit$fit.preval)) {
            # Convert factor response to numeric for roc.glmnet (0/1 encoding)
            y_numeric <- if (is.factor(values$ml_y_response)) {
              as.numeric(droplevels(values$ml_y_response)) - 1  # Convert to 0/1
            } else {
              as.numeric(values$ml_y_response)
            }
            
            # Coerce predictions to a numeric matrix and drop rows with any NA/NaN/Inf
            P <- values$ml_cv_fit$fit.preval
            P <- tryCatch(as.matrix(P), error = function(e) P)
            if (!is.matrix(P)) {
              stop("fit.preval is not a matrix of numeric predictions")
            }
            storage.mode(P) <- "double"
            valid_rows <- is.finite(y_numeric) & apply(P, 1, function(r) all(is.finite(r)))
            if (!any(valid_rows)) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "Cannot compute ROC: predictions/labels contain no finite rows.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            P_valid <- P[valid_rows, , drop = FALSE]
            y_valid <- y_numeric[valid_rows]
            
            # Use roc.glmnet with prevlidated CV predictions
            rocs <- glmnet::roc.glmnet(P_valid, newy = y_valid)
            
            # Validate that rocs is a list with valid elements
            if (!is.list(rocs) || length(rocs) == 0) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "ROC analysis failed:\nNo valid ROC curves generated.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            # Find the best lambda index based on AUC
            auc_vec <- tryCatch({
              sapply(seq_along(rocs), function(i) {
                if (i > length(rocs)) return(NA_real_)
                roc <- rocs[[i]]
                if (is.null(roc) || !is.list(roc) || is.null(roc$auc)) return(NA_real_)
                a <- suppressWarnings(as.numeric(roc$auc))
                ifelse(is.finite(a), a, NA_real_)
              }, res = UI_PLOT_RES)
            }, error = function(e) {
              cat("Error extracting AUC values:", e$message, "\n")
              rep(NA_real_, length(rocs))
            }, res = UI_PLOT_RES)
            
            if (all(is.na(auc_vec))) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "ROC could not be computed for any lambda.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            # Find best index with validation
            valid_aucs <- !is.na(auc_vec)
            if (!any(valid_aucs)) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "No valid AUC values found.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            best_idx <- which.max(ifelse(is.na(auc_vec), -Inf, auc_vec))
            
            # Validate best_idx and access elements safely
            if (best_idx < 1 || best_idx > length(rocs)) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "Invalid best ROC index found.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            # Get the best ROC curve with validation
            best_roc <- rocs[[best_idx]]
            if (is.null(best_roc) || is.null(best_roc$fpr) || is.null(best_roc$tpr)) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "Best ROC curve is invalid or missing data.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            best_auc <- best_roc$auc
            
            # Create ROC plot data frame with validation
            if (length(best_roc$fpr) != length(best_roc$tpr) || length(best_roc$fpr) == 0) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = "ROC curve data is malformed.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            roc_data <- data.frame(
              fpr = as.numeric(best_roc$fpr),
              tpr = as.numeric(best_roc$tpr)
            )
            
            # Validate lambda access
            lambda_text <- tryCatch({
              if (is.null(values$ml_cv_fit$lambda) || best_idx > length(values$ml_cv_fit$lambda)) {
                "unknown"
              } else {
                round(values$ml_cv_fit$lambda[best_idx], 5)
              }
            }, error = function(e) "unknown")
            
            # Create the plot
            p <- ggplot(roc_data, aes(x = fpr, y = tpr)) +
              geom_line(color = "#e74c3c", size = 2, alpha = 0.8) +
              geom_abline(intercept = 0, slope = 1, linetype = "dashed", color = "grey50", size = 1) +
              labs(title = paste("Cross-Validated ROC Curve (AUC =", round(best_auc, 3), ")"),
                   subtitle = paste("Best model at lambda =", lambda_text),
                   x = "False Positive Rate (1 - Specificity)",
                   y = "True Positive Rate (Sensitivity)") +
              theme_minimal() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
                axis.title.x = element_text(size = 12, face = "bold"),
                axis.title.y = element_text(size = 12, face = "bold"),
                axis.text.x = element_text(size = 11, face = "bold"),
                axis.text.y = element_text(size = 11, face = "bold"),
                panel.grid = element_blank(),
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                axis.line = element_line(color = "black", size = 0.5)
              ) +
              coord_equal() +
              scale_x_continuous(limits = c(0, 1), expand = c(0, 0)) +
              scale_y_continuous(limits = c(0, 1), expand = c(0, 0))
            
            # Optionally add all ROC curves in grey background
            if (length(rocs) > 1) {
              # Create background data for all ROC curves with validation
              all_roc_data <- tryCatch({
                do.call(rbind, lapply(seq_along(rocs), function(i) {
                  if (i != best_idx && i <= length(rocs)) {
                    roc_i <- rocs[[i]]
                    if (!is.null(roc_i) && !is.null(roc_i$fpr) && !is.null(roc_i$tpr) &&
                        length(roc_i$fpr) > 0 && length(roc_i$fpr) == length(roc_i$tpr)) {
                      data.frame(
                        fpr = as.numeric(roc_i$fpr),
                        tpr = as.numeric(roc_i$tpr),
                        lambda_idx = i,
                        stringsAsFactors = FALSE
                      )
                    } else {
                      NULL
                    }
                  } else {
                    NULL
                  }
                }))
              }, error = function(e) {
                cat("Error processing background ROC curves:", e$message, "\n")
                NULL
              }, res = UI_PLOT_RES)
              
              if (!is.null(all_roc_data) && nrow(all_roc_data) > 0) {
                p <- p +
                  geom_line(data = all_roc_data, aes(group = lambda_idx),
                            color = "grey70", size = 0.5, alpha = 0.5)
              }
            }
            
            p
            
          } else {
            # Fallback: use standard predictions if CV with keep=TRUE is not available
            # Get predictions at best lambda
            pred_probs <- predict(values$ml_glmnet_fit, values$ml_X_matrix,
                                  s = values$ml_lambda_best, type = "response")[,1]
            
            # Calculate ROC using pROC if available
            if (requireNamespace("pROC", quietly = TRUE)) {
              # Ensure proper response variable format for pROC
              y_for_roc <- if (is.factor(values$ml_y_response)) {
                values$ml_y_response
              } else {
                as.factor(values$ml_y_response)
              }
              
              roc_obj <- pROC::roc(y_for_roc, pred_probs, quiet = TRUE)
              
              # Create ROC plot data
              roc_data <- data.frame(
                fpr = 1 - roc_obj$specificities,
                tpr = roc_obj$sensitivities
              )
              
              ggplot(roc_data, aes(x = fpr, y = tpr)) +
                geom_line(color = "#e74c3c", size = 1.5) +
                geom_abline(intercept = 0, slope = 1, linetype = "dashed", color = "grey50") +
                labs(title = paste("ROC Curve (AUC =", round(roc_obj$auc, 3), ")"),
                     subtitle = "Note: Using training data predictions (may be optimistic)",
                     x = "False Positive Rate (1 - Specificity)",
                     y = "True Positive Rate (Sensitivity)") +
                theme_minimal() +
                theme(
                  plot.title = element_text(hjust = 0.5, size = 14, face = "bold"),
                  plot.subtitle = element_text(hjust = 0.5, size = 10, color = "orange"),
                  axis.title = element_text(size = 12),
                  panel.border = element_rect(color = "black", fill = NA, size = 0.5)
                ) +
                coord_equal() +
                scale_x_continuous(limits = c(0, 1), expand = c(0, 0)) +
                scale_y_continuous(limits = c(0, 1), expand = c(0, 0))
            } else {
              ggplot() +
                annotate("text", x = 0.5, y = 0.5, label = "pROC package required\nfor fallback ROC analysis.",
                         size = 5, hjust = 0.5) +
                theme_void() + xlim(0, 1) + ylim(0, 1)
            }
          }
        }, error = function(e) {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5, label = paste("ROC calculation error:", e$message),
                     size = 4, hjust = 0.5) +
            theme_void() + xlim(0, 1) + ylim(0, 1)
        })
      }
    }
  })
  
  # Confusion matrix for multinomial
  output$mlfs_confusion_matrix <- renderPlot({ 
    if (is.null(values$ml_glmnet_fit) || values$ml_glmnet_family != "multinomial") {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Confusion matrix only available\nfor multinomial classification.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Get predictions
        pred_class <- predict(values$ml_glmnet_fit, values$ml_X_matrix,
                              s = values$ml_lambda_best, type = "class")[,1]
        
        # Create confusion matrix
        conf_matrix <- table(Predicted = pred_class, Actual = values$ml_y_response)
        
        # Convert to data frame for ggplot
        conf_df <- as.data.frame(conf_matrix)
        
        ggplot(conf_df, aes(x = Actual, y = Predicted, fill = Freq)) +
          geom_tile() +
          geom_text(aes(label = Freq), color = "white", size = 4) +
          scale_fill_gradient(low = "white", high = "#3498db") +
          labs(title = "Confusion Matrix",
               x = "Actual Class",
               y = "Predicted Class") +
          theme_minimal() +
          theme(plot.title = element_text(hjust = 0.5))
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Confusion matrix error:", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Residuals plot for Gaussian
  output$mlfs_residuals_plot <- renderPlot({ 
    if (is.null(values$ml_glmnet_fit) || values$ml_glmnet_family != "gaussian") {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Residuals plot only available\nfor Gaussian regression.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Get predictions
        pred_values <- predict(values$ml_glmnet_fit, values$ml_X_matrix,
                               s = values$ml_lambda_best)[,1]
        
        # Calculate residuals
        residuals <- values$ml_y_response - pred_values
        
        # Create residuals data
        resid_data <- data.frame(
          fitted = as.numeric(pred_values),
          residuals = as.numeric(residuals)
        )
        
        ggplot(resid_data, aes(x = fitted, y = residuals)) +
          geom_point(alpha = 0.6, color = "#3498db") +
          geom_hline(yintercept = 0, linetype = "dashed", color = "red") +
          geom_smooth(se = FALSE, color = "#e74c3c") +
          labs(title = "Residuals vs Fitted Values",
               x = "Fitted Values",
               y = "Residuals") +
          theme_minimal() +
          theme(plot.title = element_text(hjust = 0.5))
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Residuals plot error:", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Coefficient analysis plot
  output$coefficient_analysis_plot <- renderPlot({ 
    # Guard: no model
    if (is.null(values$ml_glmnet_fit)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "No model available. Fit a model first.",
                        size = 5, hjust = 0.5) +
               theme_void() + xlim(0, 1) + ylim(0, 1))
    }
    
    analysis_type <- input$coef_analysis_type %||% "values"
    
    if (analysis_type == "values") {
      # Plot coefficient values at optimal lambda
      coef_data <- tryCatch(coef(values$ml_glmnet_fit, s = values$ml_lambda_best),
                            error = function(e) NULL)
      if (is.null(coef_data)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Coefficients not available at selected lambda.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      if (inherits(coef_data, "list")) {
        # Multinomial case: choose class to focus on
        class_focus <- input$coef_class_focus %||% names(coef_data)[1]
        if (class_focus %in% names(coef_data)) {
          coef_vec <- as.vector(coef_data[[class_focus]])[-1]  # Exclude intercept
          coef_names <- rownames(coef_data[[class_focus]])[-1]
        } else {
          coef_vec <- as.vector(coef_data[[1]])[-1]
          coef_names <- rownames(coef_data[[1]])[-1]
        }
      } else {
        # Binomial/Gaussian case
        coef_vec <- as.vector(coef_data)[-1]  # Exclude intercept
        coef_names <- rownames(coef_data)[-1]
      }
      
      # Map numeric / generic feature names to cleaned molecule names when possible
      if (!is.null(values$cleaned_molecules) && length(coef_names) == length(values$cleaned_molecules)) {
        if (all(grepl("^Feature_[0-9]+$", coef_names)) || all(suppressWarnings(!is.na(as.numeric(coef_names))))) {
          coef_names <- values$cleaned_molecules
        }
      } else if (exists("map_numeric_ids_to_names", inherits = TRUE)) {
        tmp_df_map <- data.frame(Feature = coef_names, stringsAsFactors = FALSE)
        tmp_df_map <- map_numeric_ids_to_names(tmp_df_map)
        coef_names <- tmp_df_map$Feature
      }
      
      # Optional: filter zero coefficients
      if (!isTRUE(input$coef_show_zero)) {
        keep <- coef_vec != 0
        coef_vec <- coef_vec[keep]
        coef_names <- coef_names[keep]
      }
      
      if (length(coef_vec) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No non-zero coefficients to display.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      plot_data <- data.frame(Feature = coef_names, Coefficient = coef_vec)
      plot_data <- plot_data[order(abs(plot_data$Coefficient), decreasing = TRUE), ]
      plot_data <- head(plot_data, 30)
      
      return(
        ggplot(plot_data, aes(x = reorder(Feature, Coefficient), y = Coefficient)) +
          geom_col(aes(fill = Coefficient > 0), alpha = 0.85) +
          scale_fill_manual(values = c("TRUE" = "#2ecc71", "FALSE" = "#e74c3c"),
                            name = "Sign", labels = c("Negative", "Positive")) +
          coord_flip() +
          labs(title = "Coefficient Values at Optimal Lambda",
               x = "Feature", y = "Coefficient Value") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 10, face = "bold"),
            legend.title = element_text(size = 11, face = "bold"),
            legend.text = element_text(size = 10, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          )
      )
    }
    
    else if (analysis_type == "stability") {
      # Coefficient Stability Analysis - values across lambda path
      if (is.null(values$ml_glmnet_fit$lambda)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Lambda path not available.\nRun with lambda sequence.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      coef_path <- coef(values$ml_glmnet_fit, s = values$ml_glmnet_fit$lambda)
      if (inherits(coef_path, "list")) {
        class_focus <- input$coef_class_focus %||% names(coef_path)[1]
        if (class_focus %in% names(coef_path)) {
          coef_matrix <- as.matrix(coef_path[[class_focus]])[-1, ]  # Exclude intercept
        } else {
          coef_matrix <- as.matrix(coef_path[[1]])[-1, ]
        }
      } else {
        coef_matrix <- as.matrix(coef_path)[-1, ]  # Exclude intercept
      }
      
      opt_coef <- coef_matrix[, which.min(abs(values$ml_glmnet_fit$lambda - values$ml_lambda_best))]
      selected_features <- names(opt_coef)[opt_coef != 0]
      if (length(selected_features) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No features selected.\nTry different lambda values.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      selected_features <- head(selected_features, 10)
      stability_data <- coef_matrix[selected_features, , drop = FALSE]
      # Attempt mapping rownames to cleaned molecules if generic/numeric
      if (!is.null(values$cleaned_molecules) && nrow(stability_data) <= length(values$cleaned_molecules)) {
        rn <- rownames(stability_data)
        if (all(grepl("^Feature_[0-9]+$", rn)) || all(suppressWarnings(!is.na(as.numeric(rn))))) {
          # Use positional match: attempt to find indices from names
          idx <- suppressWarnings(as.numeric(gsub("^Feature_", "", rn)))
          if (!any(is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
            rownames(stability_data) <- make.unique(values$cleaned_molecules[idx])
          } else if (nrow(stability_data) == length(values$cleaned_molecules)) {
            rownames(stability_data) <- make.unique(values$cleaned_molecules)
          }
        }
      }
      plot_data <- data.frame(
        Feature = rep(rownames(stability_data), ncol(stability_data)),
        Lambda = rep(values$ml_glmnet_fit$lambda, each = nrow(stability_data)),
        Coefficient = as.vector(stability_data)
      )
      plot_data$LogLambda <- log(plot_data$Lambda)
      
      return(
        ggplot(plot_data, aes(x = LogLambda, y = Coefficient, color = Feature)) +
          geom_line(size = 1.2, alpha = 0.85) +
          geom_vline(xintercept = log(values$ml_lambda_best), linetype = "dashed",
                     color = "red", size = 1, alpha = 0.7) +
          labs(title = "Coefficient Stability Across Lambda Path",
               subtitle = "Red line shows optimal lambda",
               x = "log(?)", y = "Coefficient Value") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 11, face = "bold"),
            legend.title = element_text(size = 11, face = "bold"),
            legend.text = element_text(size = 10, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5),
            legend.position = "right"
          ) +
          guides(color = guide_legend(title = "Feature", ncol = 1))
      )
    }
    
    else if (analysis_type == "selection") {
      # Feature selection path and entry points
      if (is.null(values$ml_glmnet_fit$lambda)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "Lambda path not available.\nRun with lambda sequence.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      coef_path <- coef(values$ml_glmnet_fit, s = values$ml_glmnet_fit$lambda)
      if (inherits(coef_path, "list")) {
        class_focus <- input$coef_class_focus %||% names(coef_path)[1]
        if (class_focus %in% names(coef_path)) {
          coef_matrix <- as.matrix(coef_path[[class_focus]])[-1, ]  # Exclude intercept
        } else {
          coef_matrix <- as.matrix(coef_path[[1]])[-1, ]
        }
      } else {
        coef_matrix <- as.matrix(coef_path)[-1, ]  # Exclude intercept
      }
      
      n_features <- apply(coef_matrix, 2, function(x) sum(x != 0))
      feature_entry <- apply(coef_matrix, 1, function(x) {
        first_nonzero <- which(x != 0)[1]
        if (is.na(first_nonzero)) NA else values$ml_glmnet_fit$lambda[first_nonzero]
      })
      feature_entry <- feature_entry[!is.na(feature_entry)]
      
      if (length(feature_entry) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No features selected across lambda path.",
                          size = 5, hjust = 0.5) +
                 theme_void() + xlim(0, 1) + ylim(0, 1))
      }
      
      path_data <- data.frame(
        Lambda = values$ml_glmnet_fit$lambda,
        LogLambda = log(values$ml_glmnet_fit$lambda),
        NumFeatures = n_features
      )
      entry_data <- data.frame(
        Feature = names(feature_entry),
        EntryLambda = feature_entry,
        LogEntryLambda = log(feature_entry)
      )
      
      # Map feature names for selection plot labels
      if (!is.null(values$cleaned_molecules)) {
        # If all generic/numeric and sizes align, replace
        feats <- entry_data$Feature
        if (all(grepl("^Feature_[0-9]+$", feats)) || all(suppressWarnings(!is.na(as.numeric(feats))))) {
          # Try extracting indices
          idx <- suppressWarnings(as.numeric(gsub("^Feature_", "", feats)))
          if (!any(is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
            entry_data$Feature <- values$cleaned_molecules[idx]
          } else if (length(feats) == length(values$cleaned_molecules)) {
            entry_data$Feature <- values$cleaned_molecules
          }
        }
      } else if (exists("map_numeric_ids_to_names", inherits = TRUE)) {
        entry_data <- map_numeric_ids_to_names(entry_data)
      }
      
      p1 <- ggplot(path_data, aes(x = LogLambda, y = NumFeatures)) +
        geom_line(size = 1.5, color = "#3498db") +
        geom_point(size = 2, color = "#2980b9", alpha = 0.7) +
        geom_vline(xintercept = log(values$ml_lambda_best), linetype = "dashed",
                   color = "red", size = 1, alpha = 0.7) +
        labs(title = "Feature Selection Path",
             subtitle = "Number of selected features vs. regularization strength",
             x = "log(?)", y = "Number of Selected Features") +
        theme_minimal() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
          plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
          axis.title.x = element_text(size = 12, face = "bold"),
          axis.title.y = element_text(size = 12, face = "bold"),
          axis.text.x = element_text(size = 11, face = "bold"),
          axis.text.y = element_text(size = 11, face = "bold"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          axis.line = element_line(color = "black", size = 0.5)
        )
      
      if (nrow(entry_data) <= 15) {
        entry_data <- entry_data[order(entry_data$EntryLambda, decreasing = TRUE), ]
        entry_data$YPos <- seq(0.5, nrow(entry_data) + 0.5)
        p1 <- p1 +
          geom_vline(data = entry_data, aes(xintercept = LogEntryLambda),
                     linetype = "dotted", alpha = 0.5, color = "#95a5a6") +
          geom_text(data = head(entry_data, 10),
                    aes(x = LogEntryLambda, y = YPos, label = Feature),
                    angle = 90, hjust = 0, size = 3, alpha = 0.8)
      }
      
      return(p1)
    }
    
    # Fallback for unknown analysis type
    ggplot() +
      annotate("text", x = 0.5, y = 0.5,
               label = paste("Analysis type", analysis_type, "not recognized."),
               size = 5, hjust = 0.5) +
      theme_void() + xlim(0, 1) + ylim(0, 1)
  })
  
  # Coefficient table
  output$coefficient_table <- DT::renderDataTable({
    if (is.null(values$ml_glmnet_fit)) {
      DT::datatable(data.frame(Feature = character(0), Coefficient = numeric(0)),
                    options = list(pageLength = 10, scrollX = TRUE))
    } else {
      analysis_type <- input$coef_analysis_type %||% "values"
      
      if (analysis_type == "values") {
        # Show coefficient values at optimal lambda
        coef_data <- coef(values$ml_glmnet_fit, s = values$ml_lambda_best)
        
        if (inherits(coef_data, "list")) {
          # Multinomial case - combine all classes
          all_coef <- data.frame()
          for (class_name in names(coef_data)) {
            class_coef <- data.frame(
              Feature = rownames(coef_data[[class_name]])[-1],  # Exclude intercept
              Class = class_name,
              Coefficient = as.vector(coef_data[[class_name]])[-1],
              stringsAsFactors = FALSE
            )
            all_coef <- rbind(all_coef, class_coef)
          }
          
          # Filter zero coefficients if requested
          if (!isTRUE(input$coef_show_zero)) {
            all_coef <- all_coef[all_coef$Coefficient != 0, ]
          }
          
          DT::datatable(all_coef, options = list(pageLength = 15, scrollX = TRUE)) %>%
            DT::formatRound("Coefficient", digits = 6)
        } else {
          # Binary/continuous case
          coef_df <- data.frame(
            Feature = rownames(coef_data)[-1],  # Exclude intercept
            Coefficient = as.vector(coef_data)[-1],
            stringsAsFactors = FALSE
          )
          
          # Map coefficient table feature names
          if (!is.null(values$cleaned_molecules) && nrow(coef_df) == length(values$cleaned_molecules)) {
            if (all(grepl("^Feature_[0-9]+$", coef_df$Feature)) || all(suppressWarnings(!is.na(as.numeric(coef_df$Feature))))) {
              coef_df$Feature <- values$cleaned_molecules
            }
          } else if (exists("map_numeric_ids_to_names", inherits = TRUE)) {
            coef_df <- map_numeric_ids_to_names(coef_df)
          }
          
          # Filter zero coefficients if requested
          if (!isTRUE(input$coef_show_zero)) {
            coef_df <- coef_df[coef_df$Coefficient != 0, ]
          }
          
          DT::datatable(coef_df, options = list(pageLength = 15, scrollX = TRUE)) %>%
            DT::formatRound("Coefficient", digits = 6)
        }
        
      } else if (analysis_type == "stability") {
        # Show coefficient stability statistics
        if (is.null(values$ml_glmnet_fit$lambda)) {
          DT::datatable(data.frame(Message = "Lambda path not available"),
                        options = list(pageLength = 10, scrollX = TRUE))
        } else {
          coef_path <- coef(values$ml_glmnet_fit, s = values$ml_glmnet_fit$lambda)
          
          if (inherits(coef_path, "list")) {
            # Multinomial case
            class_focus <- input$coef_class_focus %||% names(coef_path)[1]
            if (class_focus %in% names(coef_path)) {
              coef_matrix <- as.matrix(coef_path[[class_focus]])[-1, ]  # Exclude intercept
            } else {
              coef_matrix <- as.matrix(coef_path[[1]])[-1, ]
            }
          } else {
            coef_matrix <- as.matrix(coef_path)[-1, ]
          }
          
          # Calculate stability statistics
          stability_stats <- data.frame(
            Feature = rownames(coef_matrix),
            Mean_Coefficient = rowMeans(coef_matrix),
            SD_Coefficient = apply(coef_matrix, 1, sd),
            Max_Abs_Coefficient = apply(abs(coef_matrix), 1, max),
            Times_Nonzero = rowSums(coef_matrix != 0),
            Stability_Score = 1 - apply(coef_matrix, 1, sd) / (apply(abs(coef_matrix), 1, max) + 1e-8),
            stringsAsFactors = FALSE
          )
          
          # Map stability stats feature names
          if (!is.null(values$cleaned_molecules) && nrow(stability_stats) <= length(values$cleaned_molecules)) {
            feats <- stability_stats$Feature
            if (all(grepl("^Feature_[0-9]+$", feats)) || all(suppressWarnings(!is.na(as.numeric(feats))))) {
              idx <- suppressWarnings(as.numeric(gsub("^Feature_", "", feats)))
              if (!any(is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
                stability_stats$Feature <- values$cleaned_molecules[idx]
              } else if (nrow(stability_stats) == length(values$cleaned_molecules)) {
                stability_stats$Feature <- values$cleaned_molecules
              }
            }
          } else if (exists("map_numeric_ids_to_names", inherits = TRUE)) {
            stability_stats <- map_numeric_ids_to_names(stability_stats)
          }
          
          # Filter to features that appear at least once
          stability_stats <- stability_stats[stability_stats$Times_Nonzero > 0, ]
          stability_stats <- stability_stats[order(stability_stats$Stability_Score, decreasing = TRUE), ]
          
          DT::datatable(stability_stats, options = list(pageLength = 15, scrollX = TRUE)) %>%
            DT::formatRound(c("Mean_Coefficient", "SD_Coefficient", "Max_Abs_Coefficient", "Stability_Score"), digits = 4)
        }
        
      } else if (analysis_type == "selection") {
        # Show feature selection path statistics
        if (is.null(values$ml_glmnet_fit$lambda)) {
          DT::datatable(data.frame(Message = "Lambda path not available"),
                        options = list(pageLength = 10, scrollX = TRUE))
        } else {
          coef_path <- coef(values$ml_glmnet_fit, s = values$ml_glmnet_fit$lambda)
          
          if (inherits(coef_path, "list")) {
            # Multinomial case
            class_focus <- input$coef_class_focus %||% names(coef_path)[1]
            if (class_focus %in% names(coef_path)) {
              coef_matrix <- as.matrix(coef_path[[class_focus]])[-1, ]  # Exclude intercept
            } else {
              coef_matrix <- as.matrix(coef_path[[1]])[-1, ]
            }
          } else {
            coef_matrix <- as.matrix(coef_path)[-1, ]
          }
          
          # Calculate selection path statistics
          selection_stats <- data.frame(
            Feature = rownames(coef_matrix),
            Entry_Lambda = apply(coef_matrix, 1, function(x) {
              first_nonzero <- which(x != 0)[1]
              if (is.na(first_nonzero)) NA else values$ml_glmnet_fit$lambda[first_nonzero]
            }),
            Exit_Lambda = apply(coef_matrix, 1, function(x) {
              last_nonzero <- which(x != 0)
              if (length(last_nonzero) == 0) NA else values$ml_glmnet_fit$lambda[max(last_nonzero)]
            }),
            Times_Selected = rowSums(coef_matrix != 0),
            Selection_Frequency = rowSums(coef_matrix != 0) / ncol(coef_matrix),
            Final_Coefficient = coef_matrix[, ncol(coef_matrix)],
            stringsAsFactors = FALSE
          )
          
          # Map selection stats feature names
          if (!is.null(values$cleaned_molecules) && nrow(selection_stats) <= length(values$cleaned_molecules)) {
            feats <- selection_stats$Feature
            if (all(grepl("^Feature_[0-9]+$", feats)) || all(suppressWarnings(!is.na(as.numeric(feats))))) {
              idx <- suppressWarnings(as.numeric(gsub("^Feature_", "", feats)))
              if (!any(is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
                selection_stats$Feature <- values$cleaned_molecules[idx]
              } else if (nrow(selection_stats) == length(values$cleaned_molecules)) {
                selection_stats$Feature <- values$cleaned_molecules
              }
            }
          } else if (exists("map_numeric_ids_to_names", inherits = TRUE)) {
            selection_stats <- map_numeric_ids_to_names(selection_stats)
          }
          
          # Filter to features that were selected at least once
          selection_stats <- selection_stats[!is.na(selection_stats$Entry_Lambda), ]
          selection_stats <- selection_stats[order(selection_stats$Entry_Lambda, decreasing = TRUE), ]
          
          DT::datatable(selection_stats, options = list(pageLength = 15, scrollX = TRUE)) %>%
            DT::formatRound(c("Entry_Lambda", "Exit_Lambda", "Selection_Frequency", "Final_Coefficient"), digits = 4)
        }
        
      } else {
        DT::datatable(data.frame(Message = paste("Table for", analysis_type, "not available")),
                      options = list(pageLength = 10, scrollX = TRUE))
      }
    }
  })
  
  # Download handlers for new outputs
  output$download_glmnet_plots <- downloadHandler(
    filename = function() {
      paste0("glmnet_regularization_plots_", Sys.Date(), ".", get_safe_global_image_format())
