  output$download_coefficients <- downloadHandler(
    filename = function() {
      paste0("model_coefficients_", Sys.Date(), ".csv")
    },
    content = function(file) {
      if (!is.null(values$ml_glmnet_fit)) {
        coef_data <- coef(values$ml_glmnet_fit, s = values$ml_lambda_best)
        
        if (inherits(coef_data, "list")) {
          # Multinomial case
          all_coef <- data.frame()
          for (class_name in names(coef_data)) {
            fn_raw <- rownames(coef_data[[class_name]])
            if (!is.null(values$cleaned_molecules)) {
              map_feat_names_coef <- function(x) {
                ix <- suppressWarnings(as.integer(sub("^Feature_", "", x)))
                ix2 <- suppressWarnings(as.integer(sub("^X", "", x)))
                ix_num <- suppressWarnings(as.integer(x))
                res <- x
                if (!is.na(ix) && ix >= 1 && ix <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix]
                else if (!is.na(ix2) && ix2 >= 1 && ix2 <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix2]
                else if (!is.na(ix_num) && ix_num >= 1 && ix_num <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix_num]
                res
              }
              fn_raw <- vapply(fn_raw, map_feat_names_coef, character(1))
            }
            class_coef <- data.frame(
              Feature = fn_raw,
              Class = class_name,
              Coefficient = as.vector(coef_data[[class_name]]),
              stringsAsFactors = FALSE
            )
            all_coef <- rbind(all_coef, class_coef)
          }
          write.csv(all_coef, file, row.names = FALSE)
        } else {
          # Binary/continuous case
          fn_raw <- rownames(coef_data)
          if (!is.null(values$cleaned_molecules)) {
            map_feat_names_coef2 <- function(x) {
              ix <- suppressWarnings(as.integer(sub("^Feature_", "", x)))
              ix2 <- suppressWarnings(as.integer(sub("^X", "", x)))
              ix_num <- suppressWarnings(as.integer(x))
              res <- x
              if (!is.na(ix) && ix >= 1 && ix <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix]
              else if (!is.na(ix2) && ix2 >= 1 && ix2 <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix2]
              else if (!is.na(ix_num) && ix_num >= 1 && ix_num <= length(values$cleaned_molecules)) res <- values$cleaned_molecules[ix_num]
              res
            }
            fn_raw <- vapply(fn_raw, map_feat_names_coef2, character(1))
          }
          coef_df <- data.frame(
            Feature = fn_raw,
            Coefficient = as.vector(coef_data),
            stringsAsFactors = FALSE
          )
          write.csv(coef_df, file, row.names = FALSE)
        }
      }
    }
  )
  
  # Update coefficient class choices for multinomial
  observe({
    if (!is.null(values$ml_coefficients_by_class) && length(values$ml_coefficients_by_class) > 1) {
      choices <- names(values$ml_coefficients_by_class)
      updateSelectInput(session, "coef_class_focus", choices = choices, selected = choices[1])
    } else if (!is.null(values$ml_coefficients_by_class) && length(values$ml_coefficients_by_class) == 1) {
      # Single class case (binary or gaussian)
      choices <- names(values$ml_coefficients_by_class)
      updateSelectInput(session, "coef_class_focus", choices = choices, selected = choices[1])
    } else {
      # No coefficients available - clear the dropdown
      updateSelectInput(session, "coef_class_focus", choices = character(0), selected = NULL)
    }
  })
  
  # Advanced diagnostics outputs (placeholders)
  output$model_selection_criteria <- renderPrint({
    if (is.null(values$ml_cv_fit)) {
      cat("Model selection criteria not available.")
    } else {
      cat("Model Selection Criteria:\n")
      cat("========================\n")
      cat("Minimum CV Error:", round(min(values$ml_cv_fit$cvm), 4), "\n")
      cat("Lambda at min CV:", round(values$ml_cv_fit$lambda.min, 4), "\n")
      cat("Lambda 1-SE:", round(values$ml_cv_fit$lambda.1se, 4), "\n")
      cat("Number of non-zero coefficients at optimal lambda:",
          sum(values$ml_importance$Importance > 0), "\n")
      
      # Add enhanced stability information if available
      if (!is.null(values$stability_results) &&
          isTRUE(input$enable_enhanced_stability) &&
          input$feature_selection_method == "lasso") {
        
        cat("\nEnhanced Stability Analysis:\n")
        cat("============================\n")
        
        stability_method <- input$stability_method %||% "bootstrap"
        cat("Selected Method:", stability_method, "\n")
        
        if (stability_method == "all") {
          cat("Number of methods used:", length(values$stability_results), "\n")
          
          if (!is.null(values$consensus_features) && nrow(values$consensus_features) > 0) {
            cat("Consensus features found:", nrow(values$consensus_features), "\n")
            cat("Consensus threshold:", input$consensus_threshold %||% 0.5, "\n")
            cat("Top consensus feature:", values$consensus_features$Feature[1],
                "(score:", round(values$consensus_features$ConsensusScore[1], 3), ")\n")
          } else {
            cat("No consensus features found\n")
          }
          
        } else {
          # Single method statistics
          if (stability_method == "bootstrap" && "bootstrap" %in% names(values$stability_results)) {
            bootstrap_params <- values$stability_results$bootstrap$parameters
            cat("Bootstrap samples:", bootstrap_params$n_bootstrap, "\n")
            cat("Performance metric:", bootstrap_params$performance_metric, "\n")
            
            stability_features <- values$stability_results$bootstrap$selection_frequencies
            stable_count <- sum(stability_features$WeightedFrequency >= (input$stability_threshold %||% 0.6))
            cat("Features above stability threshold:", stable_count, "\n")
            
          } else if (stability_method == "stability_selection" && "stability_selection" %in% names(values$stability_results)) {
            ss_params <- values$stability_results$stability_selection$parameters
            cat("Bootstrap samples:", ss_params$n_bootstrap, "\n")
            cat("Pi threshold:", ss_params$pi_thr, "\n")
            
            stable_features <- values$stability_results$stability_selection$stable_features
            cat("Stable features found:", length(stable_features$features), "\n")
            
          } else if (stability_method == "randomized_lasso" && "randomized_lasso" %in% names(values$stability_results)) {
            rl_params <- values$stability_results$randomized_lasso$parameters
            cat("Bootstrap samples:", rl_params$n_bootstrap, "\n")
            
            randomized_features <- values$stability_results$randomized_lasso$selection_frequencies
            stable_count <- sum(randomized_features$SelectionFrequency >= (input$stability_threshold %||% 0.6))
            cat("Features above stability threshold:", stable_count, "\n")
            
          } else if (stability_method == "stability_path" && "stability_path" %in% names(values$stability_results)) {
            sp_params <- values$stability_results$stability_path$parameters
            cat("Bootstrap samples:", sp_params$n_bootstrap, "\n")
            cat("Optimal lambda:", round(values$stability_results$stability_path$optimal_lambda, 4), "\n")
            cat("Optimal features:", length(values$stability_results$stability_path$optimal_features), "\n")
          }
        }
        
        # General stability threshold information
        if (!is.null(input$stability_threshold)) {
          cat("Stability threshold:", input$stability_threshold, "\n")
        }
        
      } else {
        cat("\nEnhanced stability analysis not enabled or not available.\n")
      }
    }
  })
  
  output$stability_plot <- renderPlot({ 
    if (is.null(values$ml_cv_fit) || is.null(values$ml_X_matrix) || is.null(values$ml_y_response)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Stability analysis requires\ncompleted ML feature selection.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        
        # Check if enhanced stability analysis results are available
        if (!is.null(values$stability_results) &&
            isTRUE(input$enable_enhanced_stability) &&
            input$feature_selection_method == "lasso") {
          
          cat("Using enhanced stability analysis results for Advanced Diagnostics\n")
          
          # Use results from enhanced stability analysis
          stability_results <- values$stability_results
          stability_method <- input$stability_method %||% "bootstrap"
          
          # Extract appropriate results based on selected method
          if (stability_method == "all") {
            # For "all methods", show consensus or combined results
            if (!is.null(values$consensus_features) && nrow(values$consensus_features) > 0) {
              freq_df <- values$consensus_features %>%
                rename(Feature = Feature, Frequency = ConsensusScore) %>%
                arrange(desc(Frequency)) %>%
                slice_head(n = min(25, nrow(.)))
              
              plot_title <- "Consensus Stability Analysis"
              plot_subtitle <- paste("Combined results from", length(stability_results), "stability methods")
              
            } else {
              # Fallback to bootstrap if consensus is empty
              if ("bootstrap" %in% names(stability_results)) {
                freq_df <- stability_results$bootstrap$selection_frequencies %>%
                  select(Feature, Frequency = WeightedFrequency) %>%
                  arrange(desc(Frequency)) %>%
                  slice_head(n = min(25, nrow(.)))
                
                plot_title <- "Enhanced Bootstrap Stability"
                plot_subtitle <- paste("Fallback: Bootstrap results from",
                                       stability_results$bootstrap$parameters$n_bootstrap, "samples")
              } else {
                return(ggplot() +
                         annotate("text", x = 0.5, y = 0.5,
                                  label = "Enhanced stability results\nnot available",
                                  size = 4, hjust = 0.5) +
                         theme_void() + xlim(0, 1) + ylim(0, 1))
              }
            }
            
          } else {
            # Single method selected
            if (stability_method == "bootstrap" && "bootstrap" %in% names(stability_results)) {
              freq_df <- stability_results$bootstrap$selection_frequencies %>%
                select(Feature, Frequency = WeightedFrequency) %>%
                arrange(desc(Frequency)) %>%
                slice_head(n = min(25, nrow(.)))
              
              plot_title <- "Enhanced Bootstrap Stability"
              plot_subtitle <- paste("Based on", stability_results$bootstrap$parameters$n_bootstrap, "bootstrap samples")
              
            } else if (stability_method == "stability_selection" && "stability_selection" %in% names(stability_results)) {
              stable_features <- stability_results$stability_selection$stable_features
              if (length(stable_features$features) > 0) {
                freq_df <- data.frame(
                  Feature = stable_features$features,
                  Frequency = stable_features$frequencies,
                  stringsAsFactors = FALSE
                ) %>%
                  arrange(desc(Frequency)) %>%
                  slice_head(n = min(25, nrow(.)))
                
                plot_title <- "Stability Selection Analysis"
                plot_subtitle <- paste("Meinshausen & B hlmann method,",
                                       stability_results$stability_selection$parameters$n_bootstrap, "samples")
              } else {
                return(ggplot() +
                         annotate("text", x = 0.5, y = 0.5,
                                  label = "No stable features found\nby stability selection",
                                  size = 4, hjust = 0.5) +
                         theme_void() + xlim(0, 1) + ylim(0, 1))
              }
              
            } else if (stability_method == "randomized_lasso" && "randomized_lasso" %in% names(stability_results)) {
              freq_df <- stability_results$randomized_lasso$selection_frequencies %>%
                select(Feature, Frequency = SelectionFrequency) %>%
                arrange(desc(Frequency)) %>%
                slice_head(n = min(25, nrow(.)))
              
              plot_title <- "Randomized LASSO Stability"
              plot_subtitle <- paste("Random feature scaling method,",
                                     stability_results$randomized_lasso$parameters$n_bootstrap, "samples")
              
            } else if (stability_method == "stability_path" && "stability_path" %in% names(stability_results)) {
              optimal_features <- stability_results$stability_path$optimal_features
              if (length(optimal_features) > 0) {
                # For stability path, create binary frequencies (selected = 1.0)
                freq_df <- data.frame(
                  Feature = optimal_features,
                  Frequency = 1.0,
                  stringsAsFactors = FALSE
                ) %>%
                  slice_head(n = min(25, nrow(.)))
                
                plot_title <- "Stability Path Analysis"
                plot_subtitle <- paste("Optimal path features,",
                                       stability_results$stability_path$parameters$n_bootstrap, "samples")
              } else {
                return(ggplot() +
                         annotate("text", x = 0.5, y = 0.5,
                                  label = "No optimal features found\nby stability path",
                                  size = 4, hjust = 0.5) +
                         theme_void() + xlim(0, 1) + ylim(0, 1))
              }
            } else {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5,
                                label = paste("Enhanced stability results\nnot available for", stability_method),
                                size = 4, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
          }
          
          # Add stability threshold line if applicable
          stability_threshold <- input$stability_threshold %||% 0.6
          
        } else {
          
          cat("Using fallback basic stability analysis for Advanced Diagnostics\n")
          
          # Fallback to basic bootstrap stability analysis with user parameters
          n_bootstrap <- input$n_stability_bootstrap %||% 100
          n_samples <- nrow(values$ml_X_matrix)
          feature_names <- colnames(values$ml_X_matrix)
          
          # Map generic/numeric feature names to cleaned molecules if possible
          if (!is.null(values$cleaned_molecules) && length(feature_names) == length(values$cleaned_molecules)) {
            if (all(grepl("^Feature_[0-9]+$", feature_names)) || all(suppressWarnings(!is.na(as.numeric(feature_names))))) {
              feature_names <- values$cleaned_molecules
            }
          }
          n_features <- length(feature_names)
          
          # Matrix to store selected features across bootstrap samples
          stability_matrix <- matrix(0, nrow = n_bootstrap, ncol = n_features)
          colnames(stability_matrix) <- feature_names
          
          cat("Starting basic stability analysis with", n_bootstrap, "bootstrap samples...\n")
          
          # Track successful bootstrap runs
          successful_boots <- 0
          
          for (i in 1:n_bootstrap) {
            # Bootstrap sample with some variability
            boot_indices <- sample(1:n_samples, size = floor(n_samples * 0.8), replace = TRUE)
            X_boot <- values$ml_X_matrix[boot_indices, , drop = FALSE]
            y_boot <- values$ml_y_response[boot_indices]
            
            # Check if we have enough variation in bootstrap sample
            if (is.factor(y_boot)) {
              unique_classes <- length(unique(as.character(y_boot)))
              if (unique_classes < 2) next  # Skip if no class variation
            } else {
              if (var(y_boot, na.rm = TRUE) == 0) next  # Skip if no variation in continuous response
            }
            
            # Check if we have enough samples for cross-validation
            if (length(y_boot) < 6) next
            
            # For classification, ensure we have at least 2 samples per class for CV
            if (values$ml_glmnet_family == "binomial") {
              class_counts <- table(y_boot)
              if (any(class_counts < 2)) next
            }
            
            # Fit glmnet model on bootstrap sample
            cv_boot <- tryCatch({
              # Calculate appropriate number of folds
              max_folds <- if (values$ml_glmnet_family == "binomial") {
                min(10, floor(min(table(y_boot)) * 2))
              } else {
                min(10, length(y_boot))
              }
              
              nfolds_use <- max(3, min(max_folds, 10))
              
              # Additional safety check
              if (nfolds_use < 3 || length(y_boot) < nfolds_use) {
                return(NULL)
              }
              
              cv.glmnet(X_boot, y_boot,
                        family = values$ml_glmnet_family,
                        alpha = values$ml_glmnet_alpha,
                        nfolds = nfolds_use,
                        standardize = TRUE)
            }, error = function(e) {
              cat("Bootstrap", i, "failed:", e$message, "\n")
              return(NULL)
            })
            
            if (!is.null(cv_boot)) {
              # Get selected features using the same lambda rule as original
              lambda_use <- tryCatch({
                if (input$lambda_rule == "1se") cv_boot$lambda.1se else cv_boot$lambda.min
              }, error = function(e) cv_boot$lambda.min)
              
              coefs <- coef(cv_boot, s = lambda_use)
              
              # Handle different glmnet family types
              selected_idx <- numeric(0)
              
              if (values$ml_glmnet_family == "multinomial") {
                # Multinomial: coefs is a list of matrices, one for each class
                if (is.list(coefs)) {
                  # Aggregate across all classes to find features selected in any class
                  all_coef_matrices <- lapply(coefs, function(x) {
                    if (is(x, "dgCMatrix")) {
                      as.numeric(x)
                    } else {
                      as.numeric(x[, 1])
                    }
                  })
                  
                  # Find features selected in any class (exclude intercept)
                  for (class_coefs in all_coef_matrices) {
                    if (length(class_coefs) > 1) {  # Ensure we have features beyond intercept
                      class_selected <- which(abs(class_coefs[-1]) > 1e-8)
                      selected_idx <- unique(c(selected_idx, class_selected))
                    }
                  }
                }
              } else {
                # Binomial or Gaussian: single matrix/vector of coefficients
                if (is(coefs, "dgCMatrix")) {
                  coef_vec <- as.numeric(coefs)
                } else {
                  coef_vec <- as.numeric(coefs[, 1])
                }
                
                # Find selected features (exclude intercept)
                if (length(coef_vec) > 1) {
                  selected_idx <- which(abs(coef_vec[-1]) > 1e-8)
                }
              }
              
              if (length(selected_idx) > 0) {
                stability_matrix[i, selected_idx] <- 1
                successful_boots <- successful_boots + 1
              }
            }
            
            if (i %% 20 == 0) {
              cat("Completed", i, "bootstrap samples,", successful_boots, "successful\n")
            }
          }
          
          cat("Basic stability analysis completed:", successful_boots, "successful bootstrap samples\n")
          
          if (successful_boots < 10) {
            return(ggplot() +
                     annotate("text", x = 0.5, y = 0.5,
                              label = paste("Insufficient successful bootstrap samples\n(", successful_boots, "out of", n_bootstrap, ")"),
                              size = 4, hjust = 0.5) +
                     theme_void() + xlim(0, 1) + ylim(0, 1))
          }
          
          # Calculate selection frequency for each feature (based on successful boots only)
          selection_freq <- colSums(stability_matrix[1:successful_boots, , drop = FALSE]) / successful_boots
          
          # Filter features that were selected at least once
          selected_features <- selection_freq > 0
          
          if (sum(selected_features) == 0) {
            return(ggplot() +
                     annotate("text", x = 0.5, y = 0.5,
                              label = "No features were consistently selected\nacross bootstrap samples",
                              size = 4, hjust = 0.5) +
                     theme_void() + xlim(0, 1) + ylim(0, 1))
          }
          
          # Create data frame for plotting - only include features that were selected
          freq_df <- data.frame(
            Feature = feature_names[selected_features],
            Frequency = selection_freq[selected_features],
            stringsAsFactors = FALSE
          ) %>%
            arrange(desc(Frequency)) %>%
            slice_head(n = min(25, nrow(.)))  # Top features, but ensure we don't exceed available features
          
          # Safeguard: map again if still generic
          if (!is.null(values$cleaned_molecules) && all(grepl("^Feature_[0-9]+$", freq_df$Feature))) {
            idx <- suppressWarnings(as.numeric(gsub("^Feature_", "", freq_df$Feature)))
            if (!any(is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
              freq_df$Feature <- values$cleaned_molecules[idx]
            }
          }
          
          plot_title <- "Basic Bootstrap Stability Analysis"
          plot_subtitle <- paste("Based on", successful_boots, "successful bootstrap samples")
          stability_threshold <- input$stability_threshold %||% 0.6
        }
        
        # Common plotting code for both enhanced and basic analysis
        if (nrow(freq_df) == 0) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5,
                            label = "No features found\nfor stability analysis",
                            size = 4, hjust = 0.5) +
                   theme_void() + xlim(0, 1) + ylim(0, 1))
        }
        
        cat("Plotting", nrow(freq_df), "features with selection frequency >0\n")
        cat("Frequency range:", min(freq_df$Frequency), "to", max(freq_df$Frequency), "\n")
        
        # Plot stability with enhanced styling
        stability_plot <- ggplot(freq_df, aes(x = reorder(Feature, Frequency), y = Frequency)) +
          geom_col(fill = "#3498db", alpha = 0.7, width = 0.8) +
          coord_flip() +
          scale_y_continuous(limits = c(0, 1), expand = c(0.01, 0)) +
          labs(title = plot_title,
               subtitle = plot_subtitle,
               x = "Features",
               y = "Selection Frequency") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
            axis.title.x = element_text(size = 12, face = "bold"),
            axis.title.y = element_text(size = 12, face = "bold"),
            axis.text.x = element_text(size = 11, face = "bold"),
            axis.text.y = element_text(size = 10, face = "bold"),
            panel.grid = element_blank(),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            axis.line = element_line(color = "black", size = 0.5)
          )
        
        # Add stability threshold line if meaningful (not for stability path which uses binary selection)
        if (exists("stability_threshold") &&
            !is.null(stability_threshold) &&
            max(freq_df$Frequency) > stability_threshold &&
            !grepl("Stability Path", plot_title)) {
          stability_plot <- stability_plot +
            geom_hline(yintercept = stability_threshold,
                       linetype = "dashed", color = "red", alpha = 0.7, size = 1) +
            annotate("text", x = nrow(freq_df) * 0.1, y = stability_threshold + 0.05,
                     label = paste("Threshold =", stability_threshold),
                     size = 3, color = "red", fontface = "bold")
        } else if (max(freq_df$Frequency) > 0.5 && !grepl("Stability Path", plot_title)) {
          # Default 50% line if no specific threshold
          stability_plot <- stability_plot +
            geom_hline(yintercept = 0.5, linetype = "dashed", color = "red", alpha = 0.7)
        }
        
        return(stability_plot)
        
      }, error = function(e) {
        cat("Error in stability analysis:", e$message, "\n")
        print(traceback())
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error in stability analysis:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      })
    }
  })
  
  output$lambda_performance_plot <- renderPlot({ 
    if (is.null(values$ml_cv_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Performance by lambda\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      perf_data <- data.frame(
        lambda = values$ml_cv_fit$lambda,
        performance = values$ml_cv_fit$cvm,
        nzero = values$ml_cv_fit$nzero
      )
      
      ggplot(perf_data, aes(x = nzero, y = performance)) +
        geom_point(alpha = 0.7, color = "#3498db") +
        geom_smooth(se = FALSE, color = "#e74c3c") +
        labs(title = "Performance vs Number of Features",
             x = "Number of Non-zero Coefficients",
             y = "Cross-Validation Error") +
        theme_minimal() +
        theme(
          plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
          axis.title.x = element_text(size = 12, face = "bold"),
          axis.title.y = element_text(size = 12, face = "bold"),
          axis.text.x = element_text(size = 11, face = "bold"),
          axis.text.y = element_text(size = 11, face = "bold"),
          panel.grid = element_blank(),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          axis.line = element_line(color = "black", size = 0.5)
        )
    }
  })
  
  output$feature_frequency_plot <- renderPlot({ 
    if (is.null(values$ml_cv_fit) || is.null(values$ml_glmnet_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Feature frequency analysis requires\ncompleted ML feature selection.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        
        # Check if enhanced stability analysis results are available and prioritize them
        if (!is.null(values$rf_enhanced_stability_results) &&
            isTRUE(input$rf_enable_enhanced_stability) &&
            input$feature_selection_method == "rf") {
          
          # Random Forest stability analysis
          rf_stability_method <- input$rf_stability_method %||% "bootstrap"
          
          if (rf_stability_method == "all" && !is.null(values$rf_consensus_results)) {
            # Use consensus results
            consensus_features <- values$rf_consensus_results %>%
              arrange(-Consensus_Score) %>%
              slice_head(n = 20)
            
            freq_data <- data.frame(
              Feature = consensus_features$Feature,
              Frequency = consensus_features$Mean_Selection_Frequency,
              stringsAsFactors = FALSE
            )
            
            plot_title <- "RF Consensus Feature Selection Frequency"
            plot_subtitle <- paste("Consensus across", length(values$rf_enhanced_stability_results), "RF stability methods")
            
          } else if (rf_stability_method %in% names(values$rf_enhanced_stability_results)) {
            # Use specific method results
            method_results <- values$rf_enhanced_stability_results[[rf_stability_method]]
            
            if (!is.null(method_results) && "Selection_Frequency" %in% colnames(method_results)) {
              freq_data <- method_results %>%
                arrange(-Selection_Frequency) %>%
                select(Feature, Selection_Frequency) %>%
                rename(Frequency = Selection_Frequency) %>%
                slice_head(n = 20)
              
              method_names <- list(
                "bootstrap" = "Enhanced Bootstrap",
                "subsampling" = "Subsampling Stability",
                "cv" = "Cross-Validation Stability",
                "noise" = "Noise Injection Robustness"
              )
              
              plot_title <- paste("RF", method_names[[rf_stability_method]], "Selection Frequency")
              plot_subtitle <- paste("Based on", attr(method_results, "n_iterations") %||% "100", "iterations")
            } else {
              freq_data <- NULL
            }
          } else {
            freq_data <- NULL
          }
          
          # Create RF stability plot if we have data
          if (!is.null(freq_data) && nrow(freq_data) > 0) {
            return(ggplot(freq_data, aes(x = reorder(Feature, Frequency), y = Frequency)) +
                     geom_col(fill = "#27ae60", alpha = 0.7, width = 0.8) +
                     coord_flip() +
                     scale_y_continuous(limits = c(0, max(1, max(freq_data$Frequency) * 1.1)), expand = c(0.01, 0)) +
                     labs(title = plot_title,
                          subtitle = plot_subtitle,
                          x = "Features",
                          y = "Selection Frequency") +
                     theme_minimal() +
                     theme(
                       plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                       plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
                       axis.title.x = element_text(size = 12, face = "bold"),
                       axis.title.y = element_text(size = 12, face = "bold"),
                       axis.text.x = element_text(size = 11, face = "bold"),
                       axis.text.y = element_text(size = 10, face = "bold"),
                       panel.grid = element_blank(),
                       panel.border = element_rect(color = "black", fill = NA, size = 1),
                       axis.line = element_line(color = "black", size = 0.5)
                     ))
          }
          
        } else if (!is.null(values$stability_results) &&
                   isTRUE(input$enable_enhanced_stability) &&
                   input$feature_selection_method == "lasso") {
          
          cat("Using enhanced stability results for feature frequency plot\n")
          
          stability_method <- input$stability_method %||% "bootstrap"
          
          # Extract feature frequency data from stability results
          if (stability_method == "all" && !is.null(values$consensus_features) && nrow(values$consensus_features) > 0) {
            # Use consensus results
            freq_data <- values$consensus_features %>%
              rename(Feature = Feature, Frequency = ConsensusScore) %>%
              arrange(desc(Frequency)) %>%
              slice_head(n = 20)
            
            plot_title <- "Consensus Feature Frequencies"
            plot_subtitle <- "Combined stability across all methods"
            
          } else if (stability_method %in% c("bootstrap", "all") && "bootstrap" %in% names(values$stability_results)) {
            freq_data <- values$stability_results$bootstrap$selection_frequencies %>%
              select(Feature, Frequency = WeightedFrequency) %>%
              arrange(desc(Frequency)) %>%
              slice_head(n = 20)
            
            plot_title <- "Enhanced Bootstrap Feature Frequencies"
            plot_subtitle <- "Performance-weighted bootstrap sampling"
            
          } else if (stability_method %in% c("randomized_lasso", "all") && "randomized_lasso" %in% names(values$stability_results)) {
            freq_data <- values$stability_results$randomized_lasso$selection_frequencies %>%
              select(Feature, Frequency = SelectionFrequency) %>%
              arrange(desc(Frequency)) %>%
              slice_head(n = 20)
            
            plot_title <- "Randomized LASSO Feature Frequencies"
            plot_subtitle <- "Random feature scaling stability"
            
          } else if (stability_method %in% c("stability_selection", "all") && "stability_selection" %in% names(values$stability_results)) {
            stable_features <- values$stability_results$stability_selection$stable_features
            if (length(stable_features$features) > 0) {
              freq_data <- data.frame(
                Feature = stable_features$features,
                Frequency = stable_features$frequencies,
                stringsAsFactors = FALSE
              ) %>%
                arrange(desc(Frequency)) %>%
                slice_head(n = 20)
              
              plot_title <- "Stability Selection Feature Frequencies"
              plot_subtitle <- "Meinshausen & B hlmann method"
            } else {
              freq_data <- data.frame(Feature = character(0), Frequency = numeric(0))
            }
            
          } else if (stability_method %in% c("stability_path", "all") && "stability_path" %in% names(values$stability_results)) {
            optimal_features <- values$stability_results$stability_path$optimal_features
            if (length(optimal_features) > 0) {
              freq_data <- data.frame(
                Feature = optimal_features,
                Frequency = 1.0,  # Binary selection
                stringsAsFactors = FALSE
              ) %>%
                slice_head(n = 20)
              
              plot_title <- "Stability Path Optimal Features"
              plot_subtitle <- "Binary selection from optimal path"
            } else {
              freq_data <- data.frame(Feature = character(0), Frequency = numeric(0))
            }
          } else {
            # Fallback to lambda path analysis
            freq_data <- NULL
          }
          
          # If we have stability-based frequency data, use it
          if (!is.null(freq_data) && nrow(freq_data) > 0) {
            # Create the plot using stability frequency data
            ggplot(freq_data, aes(x = reorder(Feature, Frequency), y = Frequency)) +
              geom_col(fill = "#e74c3c", alpha = 0.7, width = 0.8) +
              coord_flip() +
              scale_y_continuous(limits = c(0, max(1, max(freq_data$Frequency) * 1.1)), expand = c(0.01, 0)) +
              labs(title = plot_title,
                   subtitle = plot_subtitle,
                   x = "Features",
                   y = "Selection Frequency") +
              theme_minimal() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
                axis.title.x = element_text(size = 12, face = "bold"),
                axis.title.y = element_text(size = 12, face = "bold"),
                axis.text.x = element_text(size = 11, face = "bold"),
                axis.text.y = element_text(size = 10, face = "bold"),
                panel.grid = element_blank(),
                panel.border = element_rect(color = "black", fill = NA, size = 1),
                axis.line = element_line(color = "black", size = 0.5)
              )
          } else {
            # Fall through to lambda path analysis
            freq_data <- NULL
          }
        } else {
          freq_data <- NULL
        }
        
        # If no enhanced stability data available, fall back to lambda path analysis
        if (is.null(freq_data)) {
          cat("Using fallback lambda path analysis for feature frequency plot\n")
          
          # Handle different glmnet family types for coefficient extraction
          if (values$ml_glmnet_family == "multinomial") {
            # Multinomial: beta is a list of matrices, one for each class
            beta_list <- values$ml_glmnet_fit$beta
            if (!is.list(beta_list) || length(beta_list) == 0) {
              return(ggplot() +
                       annotate("text", x = 0.5, y = 0.5, label = "No coefficient data available\nfor multinomial model.",
                                size = 5, hjust = 0.5) +
                       theme_void() + xlim(0, 1) + ylim(0, 1))
            }
            
            # Get feature names from the first class (should be the same for all)
            feature_names <- rownames(beta_list[[1]])
            lambda_values <- values$ml_glmnet_fit$lambda
            
            # Calculate frequency across all classes and lambda values
            # A feature is considered "selected" if it's non-zero in any class at a given lambda
            n_features <- length(feature_names)
            n_lambdas <- length(lambda_values)
            
            # Create a binary matrix: feature x lambda, 1 if selected in any class
            selection_matrix <- matrix(0, nrow = n_features, ncol = n_lambdas)
            rownames(selection_matrix) <- feature_names
            
            # Check each class
            for (class_name in names(beta_list)) {
              class_beta <- as.matrix(beta_list[[class_name]])
              # For each lambda, mark features as selected if non-zero
              selection_matrix <- selection_matrix | (abs(class_beta) > 1e-8)
            }
            
            # Calculate selection frequency across lambda path
            feature_freq <- rowSums(selection_matrix) / n_lambdas
            
          } else {
            # Binomial or Gaussian: single beta matrix
            beta_matrix <- as.matrix(values$ml_glmnet_fit$beta)
            feature_names <- rownames(beta_matrix)
            lambda_values <- values$ml_glmnet_fit$lambda
            
            # Calculate how frequently each feature is selected (non-zero) across lambda path
            feature_freq <- rowSums(abs(beta_matrix) > 1e-8) / length(lambda_values)
          }
          
          # Map generic or numeric feature names to cleaned molecules if possible
          if (!is.null(values$cleaned_molecules) && length(feature_names) == length(values$cleaned_molecules)) {
            if (all(grepl("^Feature_[0-9]+$", feature_names)) || all(suppressWarnings(!is.na(as.numeric(feature_names))))) {
              feature_names <- values$cleaned_molecules
              # If we created a selection_matrix earlier (multinomial), update its rownames
              if (exists("selection_matrix")) {
                rownames(selection_matrix) <- feature_names
              }
            }
          }
          
          # Validate that we have valid frequency data
          if (length(feature_freq) == 0 || length(feature_names) == 0 ||
              length(feature_freq) != length(feature_names)) {
            return(ggplot() +
                     annotate("text", x = 0.5, y = 0.5, label = "Invalid frequency data structure.",
                              size = 5, hjust = 0.5) +
                     theme_void() + xlim(0, 1) + ylim(0, 1))
          }
          
          # Create frequency data frame for lambda path analysis
          freq_df <- data.frame(
            Feature = feature_names,
            Frequency = feature_freq,
            stringsAsFactors = FALSE
          ) %>%
            filter(Frequency > 0) %>%  # Only include features that were selected at least once
            arrange(desc(Frequency)) %>%
            slice_head(n = 20)
          
          if (nrow(freq_df) == 0) {
            return(ggplot() +
                     annotate("text", x = 0.5, y = 0.5, label = "No features selected\nacross lambda path.",
                              size = 5, hjust = 0.5) +
                     theme_void() + xlim(0, 1) + ylim(0, 1))
          }
          
          # Create the lambda path frequency plot
          return(ggplot(freq_df, aes(x = reorder(Feature, Frequency), y = Frequency)) +
                   geom_col(fill = "#e74c3c", alpha = 0.7, width = 0.8) +
                   coord_flip() +
                   scale_y_continuous(limits = c(0, 1), expand = c(0.01, 0)) +
                   labs(title = "Feature Selection Frequency Across Lambda Path",
                        subtitle = paste("Based on", length(lambda_values), "lambda values"),
                        x = "Features",
                        y = "Selection Frequency") +
                   theme_minimal() +
                   theme(
                     plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                     plot.subtitle = element_text(hjust = 0.5, size = 12, face = "bold"),
                     axis.title.x = element_text(size = 12, face = "bold"),
                     axis.title.y = element_text(size = 12, face = "bold"),
                     axis.text.x = element_text(size = 11, face = "bold"),
                     axis.text.y = element_text(size = 10, face = "bold"),
                     panel.grid = element_blank(),
                     panel.border = element_rect(color = "black", fill = NA, size = 1),
                     axis.line = element_line(color = "black", size = 0.5)
                   ))
        }
        
      }, error = function(e) {
        cat("Error in feature frequency analysis:", e$message, "\n")
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error in feature frequency analysis:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      })
    }
  })
  
  # ==============================================================================
  # ENHANCED STABILITY ANALYSIS OUTPUTS AND VISUALIZATIONS
  # ==============================================================================
  
