  # Consensus features table
  output$consensus_features_table <- DT::renderDataTable({
    if (!is.null(values$consensus_features) && nrow(values$consensus_features) > 0) {
      DT::datatable(values$consensus_features,
                    options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                    rownames = FALSE) %>%
        DT::formatRound(columns = "ConsensusScore", digits = 3) %>%
        DT::formatStyle("ConsensusScore",
                        backgroundColor = DT::styleColorBar(values$consensus_features$ConsensusScore, "lightblue"))
    } else {
      DT::datatable(data.frame(Message = "No consensus features available"),
                    options = list(pageLength = 10, scrollX = TRUE))
    }
  })
  
  # Download handlers for stability results
  output$download_stability_results <- downloadHandler(
    filename = function() {
      paste0("enhanced_stability_results_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      if (!requireNamespace("openxlsx", quietly = TRUE)) install.packages("openxlsx")
      
      wb <- openxlsx::createWorkbook()
      
      # Add consensus features
      if (!is.null(values$consensus_features)) {
        openxlsx::addWorksheet(wb, "Consensus_Features")
        openxlsx::writeData(wb, "Consensus_Features", values$consensus_features)
      }
      
      # Add individual method results
      if (!is.null(values$stability_results)) {
        if ("bootstrap" %in% names(values$stability_results)) {
          openxlsx::addWorksheet(wb, "Bootstrap_Results")
          openxlsx::writeData(wb, "Bootstrap_Results", values$stability_results$bootstrap$selection_frequencies)
        }
        
        if ("randomized_lasso" %in% names(values$stability_results)) {
          openxlsx::addWorksheet(wb, "Randomized_LASSO")
          openxlsx::writeData(wb, "Randomized_LASSO", values$stability_results$randomized_lasso$selection_frequencies)
        }
        
        if ("stability_selection" %in% names(values$stability_results)) {
          stable_features <- values$stability_results$stability_selection$stable_features
          if (length(stable_features$features) > 0) {
            stable_df <- data.frame(
              Feature = stable_features$features,
              Frequency = stable_features$frequencies
            )
            openxlsx::addWorksheet(wb, "Stability_Selection")
            openxlsx::writeData(wb, "Stability_Selection", stable_df)
          }
        }
      }
      
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  output$download_stability_plots <- downloadHandler(
    filename = function() {
      paste0("stability_plots_", Sys.Date(), ".", get_safe_global_image_format())
    },
    content = function(file) {
      image_format <- get_safe_global_image_format()
      if (image_format == "png") {
        png(file, width = 1200, height = 800, res = 150)
      } else if (image_format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      
      if (!is.null(values$stability_results)) {
        if (file.exists("lasso_stability_integration.R")) {
          source("lasso_stability_integration.R")
          stability_plots <- plot_stability_comparison(values$stability_results)
          
          # Print available plots
          for (plot_name in names(stability_plots)) {
            if (!is.null(stability_plots[[plot_name]])) {
              print(stability_plots[[plot_name]])
            }
          }
        }
      }
      
      dev.off()
    }
  )
  
  # ==============================================================================
  # MODEL VALIDATION AND TRAIN/TEST SPLIT OUTPUTS
  # ==============================================================================
  
  # Source validation functions
  if (file.exists("ml_validation_functions.R")) {
    source("ml_validation_functions.R")
  }
  
  # Train/test split size displays
  output$train_size_text <- renderText({
    if (!is.null(values$ml_train_indices)) {
      as.character(length(values$ml_train_indices))
    } else {
      "N/A"
    }
  })
  
  output$test_size_text <- renderText({
    if (!is.null(values$ml_test_indices)) {
      as.character(length(values$ml_test_indices))
    } else {
      "N/A"
    }
  })
  
  # Training performance metrics
  output$train_performance_metrics <- renderPrint({
    if (is.null(values$ml_train_performance)) {
      cat("Training performance not available.\nEnable train/test split and run feature selection.")
    } else {
      cat("=== TRAINING SET PERFORMANCE ===\n\n")
      
      # Check if it's a structured list from validation functions
      if (is.list(values$ml_train_performance) && "metrics" %in% names(values$ml_train_performance)) {
        if (is.data.frame(values$ml_train_performance$metrics)) {
          print(values$ml_train_performance$metrics, row.names = FALSE)
        } else {
          # Print all list elements
          for (name in names(values$ml_train_performance)) {
            if (name != "metrics") {
              cat(sprintf("%s: %s\n", name,
                          paste(values$ml_train_performance[[name]], collapse = ", ")))
            }
          }
        }
      } else if (is.list(values$ml_train_performance)) {
        # Print list as key-value pairs
        for (name in names(values$ml_train_performance)) {
          value <- values$ml_train_performance[[name]]
          if (is.numeric(value)) {
            cat(sprintf("%s: %.4f\n", name, value))
          } else {
            cat(sprintf("%s: %s\n", name, as.character(value)))
          }
        }
      } else {
        # Fallback for other types
        print(values$ml_train_performance)
      }
    }
  })
  
  # Test performance metrics
  output$test_performance_metrics <- renderPrint({
    if (is.null(values$ml_test_performance)) {
      cat("Test performance not available.\nEnable train/test split and run feature selection.")
    } else {
      cat("=== TEST SET PERFORMANCE ===\n\n")
      
      # Check if it's a structured list from validation functions
      if (is.list(values$ml_test_performance) && "metrics" %in% names(values$ml_test_performance)) {
        if (is.data.frame(values$ml_test_performance$metrics)) {
          print(values$ml_test_performance$metrics, row.names = FALSE)
        } else {
          # Print all list elements
          for (name in names(values$ml_test_performance)) {
            if (name != "metrics") {
              cat(sprintf("%s: %s\n", name,
                          paste(values$ml_test_performance[[name]], collapse = ", ")))
            }
          }
        }
      } else if (is.list(values$ml_test_performance)) {
        # Print list as key-value pairs
        for (name in names(values$ml_test_performance)) {
          value <- values$ml_test_performance[[name]]
          if (is.numeric(value)) {
            cat(sprintf("%s: %.4f\n", name, value))
          } else {
            cat(sprintf("%s: %s\n", name, as.character(value)))
          }
        }
      } else {
        # Fallback for other types
        print(values$ml_test_performance)
      }
    }
  })
  
  # Train/Test comparison plot
  output$train_test_comparison_plot <- renderPlot({ 
    if (is.null(values$ml_train_performance) || is.null(values$ml_test_performance)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Train/test performance comparison\nnot available",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      # Check if metrics are data frames
      train_metrics <- if (is.list(values$ml_train_performance) && "metrics" %in% names(values$ml_train_performance)) {
        values$ml_train_performance$metrics
      } else {
        NULL
      }
      
      test_metrics <- if (is.list(values$ml_test_performance) && "metrics" %in% names(values$ml_test_performance)) {
        values$ml_test_performance$metrics
      } else {
        NULL
      }
      
      if (is.null(train_metrics) || is.null(test_metrics) ||
          !is.data.frame(train_metrics) || !is.data.frame(test_metrics)) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Metrics not in expected format\nfor comparison plot",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      } else if (exists("plot_train_test_comparison")) {
        tryCatch({
          plot_train_test_comparison(train_metrics, test_metrics)
        }, error = function(e) {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating comparison plot:\n", e$message),
                     size = 4, hjust = 0.5) +
            theme_void() + xlim(0, 1) + ylim(0, 1)
        }, res = UI_PLOT_RES)
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Validation functions not loaded",
                            size = 5) + theme_void()
      }
    }
  })
  
  # Validation metrics table
  output$validation_metrics_table <- DT::renderDataTable({
    if (is.null(values$ml_train_performance) || is.null(values$ml_test_performance)) {
      return(DT::datatable(data.frame(Message = "No validation metrics available"),
                           options = list(pageLength = 10)))
    }
    
    # Extract metrics data frames
    train_df <- if (is.list(values$ml_train_performance) && "metrics" %in% names(values$ml_train_performance)) {
      values$ml_train_performance$metrics
    } else {
      NULL
    }
    
    test_df <- if (is.list(values$ml_test_performance) && "metrics" %in% names(values$ml_test_performance)) {
      values$ml_test_performance$metrics
    } else {
      NULL
    }
    
    # Check if we have valid data frames
    if (is.null(train_df) || is.null(test_df) ||
        !is.data.frame(train_df) || !is.data.frame(test_df)) {
      return(DT::datatable(data.frame(Message = "Metrics not in expected format for comparison"),
                           options = list(pageLength = 10)))
    }
    
    # Check if both have Metric column
    if (!"Metric" %in% colnames(train_df) || !"Metric" %in% colnames(test_df)) {
      return(DT::datatable(data.frame(Message = "Metrics missing 'Metric' column for comparison"),
                           options = list(pageLength = 10)))
    }
    
    tryCatch({
      comparison <- merge(train_df, test_df, by = "Metric", suffixes = c("_Train", "_Test"))
      comparison$Difference <- comparison$Value_Test - comparison$Value_Train
      comparison$Overfitting <- ifelse(abs(comparison$Difference) > 0.1, "Yes", "No")
      
      DT::datatable(comparison,
                    options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                    rownames = FALSE) %>%
        DT::formatRound(columns = c("Value_Train", "Value_Test", "Difference"), digits = 4) %>%
        DT::formatStyle("Overfitting",
                        backgroundColor = DT::styleEqual(c("Yes", "No"),
                                                         c("lightcoral", "lightgreen")))
    }, error = function(e) {
      DT::datatable(data.frame(Message = paste("Error creating comparison table:", e$message)),
                    options = list(pageLength = 10))
    })
  })
  
  # Reactive expression for test ROC curve plotting
  test_roc_plot <- reactive({
    if (is.null(values$ml_test_X) || is.null(values$ml_test_y) ||
        is.null(values$ml_glmnet_fit)) {
      return(ggplot() + theme_void())
    }
    
    tryCatch({
      # Get predictions
      pred_probs <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_test_X),
                            s = values$ml_lambda_best, type = "response")[,1]
      
      if (exists("calculate_roc_auc")) {
        roc_results <- calculate_roc_auc(pred_probs, values$ml_test_y)
        plot_roc_curve(roc_results$roc_data, roc_results$auc,
                       roc_results$auc_ci_lower, roc_results$auc_ci_upper,
                       title = "Test Set ROC Curve")
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Validation functions not loaded",
                            size = 5) + theme_void()
      }
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message), size = 4) + theme_void()
    })
  })
  
  # Reactive expression for test confusion matrix plotting
  test_confusion_plot <- reactive({
    if (is.null(values$ml_test_X) || is.null(values$ml_test_y)) {
      return(ggplot() + theme_void())
    }
    
    tryCatch({
      # Get predictions based on method
      if (!is.null(values$ml_glmnet_fit)) {
        pred <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_test_X),
                        s = values$ml_lambda_best, type = "class")
      } else if (!is.null(values$ml_rf_fit)) {
        pred <- predict(values$ml_rf_fit, newdata = values$ml_test_X)
      } else {
        return(ggplot() + theme_void())
      }
      
      cm <- table(Actual = values$ml_test_y, Predicted = as.factor(pred))
      
      if (exists("plot_confusion_matrix")) {
        plot_confusion_matrix(cm, title = "Test Set Confusion Matrix")
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Validation functions not loaded",
                            size = 5) + theme_void()
      }
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message), size = 4) + theme_void()
    })
  })
  
  # ROC curves for train/test
  output$train_roc_curve <- renderPlot({ 
    if (is.null(values$ml_train_X) || is.null(values$ml_train_y) ||
        is.null(values$ml_glmnet_fit)) {
      return(ggplot() + theme_void())
    }
    
    tryCatch({
      # Get predictions
      pred_probs <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_train_X),
                            s = values$ml_lambda_best, type = "response")[,1]
      
      if (exists("calculate_roc_auc")) {
        roc_results <- calculate_roc_auc(pred_probs, values$ml_train_y)
        plot_roc_curve(roc_results$roc_data, roc_results$auc,
                       roc_results$auc_ci_lower, roc_results$auc_ci_upper,
                       title = "Training Set ROC Curve")
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Validation functions not loaded",
                            size = 5) + theme_void()
      }
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message), size = 4) + theme_void()
    })
  })
  
  output$test_roc_curve <- renderPlot({ 
    test_roc_plot()
  })
  
  # Confusion matrices for train/test
  output$train_confusion_matrix <- renderPlot({ 
    if (is.null(values$ml_train_X) || is.null(values$ml_train_y)) {
      return(ggplot() + theme_void())
    }
    
    tryCatch({
      # Get predictions based on method
      if (!is.null(values$ml_glmnet_fit)) {
        pred <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_train_X),
                        s = values$ml_lambda_best, type = "class")
      } else if (!is.null(values$ml_rf_fit)) {
        pred <- predict(values$ml_rf_fit, newdata = values$ml_train_X)
      } else {
        return(ggplot() + theme_void())
      }
      
      cm <- table(Actual = values$ml_train_y, Predicted = as.factor(pred))
      
      if (exists("plot_confusion_matrix")) {
        plot_confusion_matrix(cm, title = "Training Set Confusion Matrix")
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Validation functions not loaded",
                            size = 5) + theme_void()
      }
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message), size = 4) + theme_void()
    })
  })
  
  output$test_confusion_matrix <- renderPlot({ 
    test_confusion_plot()
  })
  
  # Enable validation button observer
  observeEvent(input$enable_validation_btn, {
    updateCheckboxInput(session, "enable_train_test_split", value = TRUE)
    showNotification("Train/Test Split enabled! Please re-run feature selection.",
                     type = "message", duration = 5)
  })
  
  # Download validation results
  output$download_validation_results <- downloadHandler(
    filename = function() {
      paste0("validation_results_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      if (!requireNamespace("openxlsx", quietly = TRUE)) install.packages("openxlsx")
      
      wb <- openxlsx::createWorkbook()
      
      # Training metrics
      if (!is.null(values$ml_train_performance$metrics)) {
        openxlsx::addWorksheet(wb, "Training_Metrics")
        openxlsx::writeData(wb, "Training_Metrics", values$ml_train_performance$metrics)
      }
      
      # Test metrics
      if (!is.null(values$ml_test_performance$metrics)) {
        openxlsx::addWorksheet(wb, "Test_Metrics")
        openxlsx::writeData(wb, "Test_Metrics", values$ml_test_performance$metrics)
      }
      
      # Comparison
      if (!is.null(values$ml_train_performance) && !is.null(values$ml_test_performance)) {
        train_df <- values$ml_train_performance$metrics
        test_df <- values$ml_test_performance$metrics
        comparison <- merge(train_df, test_df, by = "Metric", suffixes = c("_Train", "_Test"))
        comparison$Difference <- comparison$Value_Test - comparison$Value_Train
        
        openxlsx::addWorksheet(wb, "Comparison")
        openxlsx::writeData(wb, "Comparison", comparison)
      }
      
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  # ==============================================================================
  # COMPREHENSIVE PERFORMANCE METRICS OUTPUTS
  # ==============================================================================
  
  # Classification metrics table
  output$classification_metrics_table <- DT::renderDataTable({
    if (is.null(values$ml_test_performance)) {
      return(DT::datatable(data.frame(Message = "Run feature selection with train/test split enabled"),
                           options = list(pageLength = 10)))
    }
    
    # Extract metrics if available
    metrics_df <- if (is.list(values$ml_test_performance) && "metrics" %in% names(values$ml_test_performance)) {
      values$ml_test_performance$metrics
    } else {
      NULL
    }
    
    if (is.null(metrics_df) || !is.data.frame(metrics_df)) {
      return(DT::datatable(data.frame(Message = "Metrics not available in expected format"),
                           options = list(pageLength = 10)))
    }
    
    DT::datatable(metrics_df,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE) %>%
      DT::formatRound(columns = "Value", digits = 4)
  })
  
  # Detailed ROC plot
  output$detailed_roc_plot <- renderPlot({ 
    test_roc_plot()  # Use reactive expression
  })
  
  # AUC confidence interval text
  output$auc_confidence_interval <- renderText({
    if (is.null(values$ml_test_X) || is.null(values$ml_test_y) ||
        is.null(values$ml_glmnet_fit)) {
      return("")
    }
    
    tryCatch({
      pred_probs <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_test_X),
                            s = values$ml_lambda_best, type = "response")[,1]
      
      if (exists("calculate_roc_auc")) {
        roc_results <- calculate_roc_auc(pred_probs, values$ml_test_y)
        sprintf("AUC: %.3f (95%% CI: %.3f - %.3f)",
                roc_results$auc, roc_results$auc_ci_lower, roc_results$auc_ci_upper)
      } else {
        ""
      }
    }, error = function(e) {
      ""
    })
  })
  
  # Detailed confusion matrix
  output$detailed_confusion_matrix <- renderPlot({ 
    test_confusion_plot()  # Use reactive expression
  })
  
  # Precision-Recall curve
  output$precision_recall_curve <- renderPlot({ 
    if (is.null(values$ml_test_X) || is.null(values$ml_test_y) ||
        is.null(values$ml_glmnet_fit)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5, label = "PR curve not available",
                        size = 5) + theme_void())
    }
    
    tryCatch({
      pred_probs <- predict(values$ml_glmnet_fit, newx = as.matrix(values$ml_test_X),
                            s = values$ml_lambda_best, type = "response")[,1]
      
      if (exists("calculate_pr_curve") && requireNamespace("PRROC", quietly = TRUE)) {
        pr_results <- calculate_pr_curve(pred_probs, values$ml_test_y)
        
        ggplot(pr_results$pr_data, aes(x = Recall, y = Precision)) +
          geom_line(color = "#9b59b6", size = 1.5) +
          annotate("text", x = 0.3, y = 0.8,
                   label = sprintf("AUC-PR = %.3f", pr_results$auc_pr),
                   size = 5, fontface = "bold", color = "#9b59b6") +
          labs(title = "Precision-Recall Curve",
               x = "Recall (Sensitivity)", y = "Precision (PPV)") +
          theme_minimal() +
          theme(plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                panel.border = element_rect(color = "black", fill = NA, size = 1)) +
          xlim(0, 1) + ylim(0, 1)
      } else {
        ggplot() + annotate("text", x = 0.5, y = 0.5,
                            label = "Install PRROC package\nfor PR curve",
                            size = 5) + theme_void()
      }
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message), size = 4) + theme_void()
    })
  })
  
  # Download all metrics
  output$download_all_metrics <- downloadHandler(
    filename = function() {
      paste0("comprehensive_metrics_", Sys.Date(), ".pdf")
    },
    content = function(file) {
      pdf(file, width = 12, height = 10)
      
      # Include all available plots
      tryCatch({
        if (!is.null(values$ml_test_performance)) {
          print(output$detailed_roc_plot())
          print(output$detailed_confusion_matrix())
          print(output$precision_recall_curve())
          print(output$train_test_comparison_plot())
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error generating plots:", e$message))
      })
      
      dev.off()
    }
  )
  
  # ==============================================================================
  # MODEL MANAGEMENT OUTPUTS
  # ==============================================================================
  
  # Current model information
  output$current_model_info <- renderPrint({
    if (is.null(values$ml_glmnet_fit) && is.null(values$ml_rf_fit) &&
        is.null(values$boruta_object)) {
      cat("No model trained yet.\nRun feature selection to create a model.")
    } else {
      cat("=== CURRENT MODEL INFORMATION ===\n\n")
      cat("Method:", values$ml_method_used %||% "Unknown", "\n")
      
      if (!is.null(values$ml_glmnet_fit)) {
        cat("Family:", values$ml_glmnet_family, "\n")
        cat("Alpha:", values$ml_glmnet_alpha, "\n")
        cat("Lambda:", values$ml_lambda_best, "\n")
      } else if (!is.null(values$ml_rf_fit)) {
        cat("Number of trees:", values$ml_rf_fit$ntree, "\n")
        cat("mtry:", values$ml_rf_fit$mtry, "\n")
      }
      
      cat("Number of features selected:", nrow(values$ml_selected_features), "\n")
      cat("Training samples:", length(values$ml_train_indices %||% integer(0)), "\n")
      cat("Test samples:", length(values$ml_test_indices %||% integer(0)), "\n")
      
      if (!is.null(values$ml_performance)) {
        cat("\nPerformance Summary:\n")
        cat(values$ml_performance, "\n")
      }
    }
  })
  
  # Save model observer
  observeEvent(input$save_model_btn, {
    req(input$model_save_name)
    
    if (is.null(values$ml_glmnet_fit) && is.null(values$ml_rf_fit) &&
        is.null(values$boruta_object)) {
      showNotification("No model to save. Please run feature selection first.",
                       type = "error", duration = 5)
      return()
    }
    
    tryCatch({
      # Determine which model to save
      model_obj <- values$ml_glmnet_fit %||% values$ml_rf_fit %||% values$boruta_object
      
      # Prepare metadata
      feature_names <- values$ml_selected_features$Feature
      method <- values$ml_method_used %||% input$feature_selection_method
      
      # Create file path
      file_path <- paste0(input$model_save_name, ".rds")
      
      # Save model
      if (exists("save_ml_model")) {
        save_ml_model(
          model = model_obj,
          model_name = input$model_save_name,
          model_description = input$model_description,
          feature_names = feature_names,
          method = method,
          performance_metrics = values$ml_performance,
          file_path = file_path
        )
        
        output$model_save_status <- renderPrint({
          cat("Model saved successfully!\n")
          cat("File:", file_path, "\n")
          cat("Date:", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n")
        })
        
        showNotification(paste("Model saved to:", file_path),
                         type = "message", duration = 5)
      } else {
        showNotification("Model saving functions not loaded. Check ml_validation_functions.R",
                         type = "error", duration = 5)
      }
    }, error = function(e) {
      output$model_save_status <- renderPrint({
        cat("Error saving model:\n")
        cat(e$message)
      })
      showNotification(paste("Error:", e$message), type = "error", duration = 5)
    })
  })
  
  # Load model observer
  observeEvent(input$load_model_btn, {
    req(input$model_file_upload)
    
    tryCatch({
      if (exists("load_ml_model")) {
        model_package <- load_ml_model(input$model_file_upload$datapath)
        
        # Store loaded model
        if (model_package$metadata$method == "lasso") {
          values$ml_glmnet_fit <- model_package$model
        } else if (model_package$metadata$method == "rf") {
          values$ml_rf_fit <- model_package$model
        } else if (model_package$metadata$method == "boruta") {
          values$boruta_object <- model_package$model
        }
        
        # Update related values
        values$ml_method_used <- model_package$metadata$method
        values$ml_selected_features <- data.frame(
          Feature = model_package$metadata$feature_names,
          stringsAsFactors = FALSE
        )
        
        output$model_load_status <- renderPrint({
          cat("Model loaded successfully!\n")
          cat("Name:", model_package$metadata$name, "\n")
          cat("Method:", model_package$metadata$method, "\n")
          cat("Features:", model_package$metadata$n_features, "\n")
          cat("Created:", format(model_package$metadata$created_date, "%Y-%m-%d %H:%M:%S"), "\n")
        })
        
        showNotification("Model loaded successfully!", type = "message", duration = 5)
      } else {
        showNotification("Model loading functions not loaded. Check ml_validation_functions.R",
                         type = "error", duration = 5)
      }
    }, error = function(e) {
      output$model_load_status <- renderPrint({
        cat("Error loading model:\n")
        cat(e$message)
      })
      showNotification(paste("Error:", e$message), type = "error", duration = 5)
    })
  })
  
  # Check if predictions are available
  output$has_predictions <- reactive({
    !is.null(values$ml_new_data_predictions)
  })
  outputOptions(output, "has_predictions", suspendWhenHidden = FALSE)
  
  # Prediction results table
  output$prediction_results_table <- DT::renderDataTable({
    if (is.null(values$ml_new_data_predictions)) {
      return(DT::datatable(data.frame(Message = "No predictions available"),
                           options = list(pageLength = 10)))
    }
    
    DT::datatable(values$ml_new_data_predictions,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE)
  })
  
  # Predict on new data observer
  observeEvent(input$predict_new_data_btn, {
    req(input$new_data_upload)
    
    if (is.null(values$ml_glmnet_fit) && is.null(values$ml_rf_fit)) {
      showNotification("No trained model available. Please train a model first.",
                       type = "error", duration = 5)
      return()
    }
    
    tryCatch({
      # Read new data
      new_data <- read.csv(input$new_data_upload$datapath,
                           header = input$new_data_has_header,
                           stringsAsFactors = FALSE)
      
      # Generate predictions
      if (!is.null(values$ml_glmnet_fit)) {
        # LASSO predictions
        pred <- predict(values$ml_glmnet_fit, newx = as.matrix(new_data),
                        s = values$ml_lambda_best, type = "response")
        pred_class <- predict(values$ml_glmnet_fit, newx = as.matrix(new_data),
                              s = values$ml_lambda_best, type = "class")
        
        results <- data.frame(
          Sample = rownames(new_data),
          Predicted_Class = as.character(pred_class),
          Probability = as.numeric(pred),
          stringsAsFactors = FALSE
        )
      } else if (!is.null(values$ml_rf_fit)) {
        # Random Forest predictions
        pred_class <- predict(values$ml_rf_fit, newdata = new_data, type = "class")
        pred_prob <- predict(values$ml_rf_fit, newdata = new_data, type = "prob")
        
        results <- data.frame(
          Sample = rownames(new_data),
          Predicted_Class = as.character(pred_class),
          stringsAsFactors = FALSE
        )
        
        # Add probabilities for each class
        if (ncol(pred_prob) > 1) {
          results <- cbind(results, pred_prob)
        } else {
          results$Probability <- pred_prob[,1]
        }
      }
      
      values$ml_new_data_predictions <- results
      
      showNotification(paste("Predictions generated for", nrow(results), "samples"),
                       type = "message", duration = 5)
    }, error = function(e) {
      showNotification(paste("Error generating predictions:", e$message),
                       type = "error", duration = 5)
    })
  })
  
  # Download predictions
  output$download_predictions <- downloadHandler(
    filename = function() {
      paste0("predictions_", Sys.Date(), ".csv")
    },
    content = function(file) {
      req(values$ml_new_data_predictions)
      write.csv(values$ml_new_data_predictions, file, row.names = FALSE)
    }
  )
  
  # ==============================================================================
  # ENHANCED RFE-SPECIFIC OUTPUTS AND VISUALIZATIONS
  # ==============================================================================
  
  # RFE Performance by Feature Count Plot
  output$rfe_performance_plot <- renderPlot({ 
    if (is.null(values$rfe_detailed_results)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Run RFE feature selection to see performance by feature count.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Extract performance results
    perf_data <- values$rfe_detailed_results$performance_by_size
    optimal_size <- values$rfe_detailed_results$optimal_size
    
    # Create the plot
    p <- ggplot(perf_data, aes(x = Variables)) +
      geom_line(aes(y = Accuracy), color = "blue", size = 1.2) +
      geom_point(aes(y = Accuracy), color = "blue", size = 2) +
      geom_errorbar(aes(ymin = Accuracy - AccuracySD, ymax = Accuracy + AccuracySD),
                    color = "blue", alpha = 0.6, width = 0.5) +
      geom_vline(xintercept = optimal_size, color = "red", linetype = "dashed", size = 1) +
      labs(title = "RFE Performance by Number of Features",
           subtitle = paste("Optimal:", optimal_size, "features (red line)"),
           x = "Number of Features",
           y = "Cross-Validation Accuracy") +
      theme_minimal() +
      theme(
        plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 12),
        axis.title = element_text(size = 12, face = "bold"),
        axis.text = element_text(size = 10),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 1)
      )
    
    # Add secondary metrics if available
    if ("Kappa" %in% names(perf_data)) {
      p <- p +
        geom_line(aes(y = Kappa), color = "green", size = 1, alpha = 0.7) +
        geom_point(aes(y = Kappa), color = "green", size = 1.5, alpha = 0.7) +
        scale_y_continuous(name = "Accuracy",
                           sec.axis = sec_axis(~., name = "Kappa",
                                               labels = scales::number_format(accuracy = 0.01))) +
        labs(caption = "Blue: Accuracy, Green: Kappa")
    }
    
    return(p)
  })
  
  # RFE Variable Rankings Plot
  output$rfe_variable_rankings <- renderPlot({ 
    if (is.null(values$rfe_detailed_results) || is.null(values$ml_importance)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Run RFE feature selection to see variable rankings.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Get top features for visualization
    top_features <- head(values$ml_importance, 20)  # Show top 20
    
    # Create ranking plot
    ggplot(top_features, aes(x = reorder(Feature, Importance), y = Importance)) +
      geom_col(fill = "steelblue", alpha = 0.8) +
      coord_flip() +
      labs(title = "RFE Variable Importance Rankings",
           subtitle = paste("Base Model:", values$rfe_detailed_results$base_model),
           x = "Features",
           y = "Importance Score") +
      theme_minimal() +
      theme(
        plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 12),
        axis.title = element_text(size = 12, face = "bold"),
        axis.text = element_text(size = 10),
        axis.text.y = element_text(size = 9),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 1)
      )
  })
  
  # RFE Cross-Validation Details Table
  output$rfe_cv_details <- DT::renderDataTable({
    if (is.null(values$rfe_detailed_results)) {
      return(DT::datatable(data.frame(Message = "Run RFE analysis to see CV details"),
                           options = list(pageLength = 10, scrollX = TRUE)))
    }
    
    perf_data <- values$rfe_detailed_results$performance_by_size
    perf_data$Rank <- rank(-perf_data$Accuracy, ties.method = "first")
    
    # Add optimal indicator
    optimal_size <- values$rfe_detailed_results$optimal_size
    perf_data$Optimal <- ifelse(perf_data$Variables == optimal_size, "?", "")
    
    # Reorder columns
    col_order <- c("Variables", "Accuracy", "AccuracySD", "Optimal", "Rank")
    if ("Kappa" %in% names(perf_data)) {
      col_order <- c(col_order[1:3], "Kappa", "KappaSD", col_order[4:5])
    }
    if ("ROC" %in% names(perf_data)) {
      col_order <- c(col_order, "ROC", "ROCSD")
    }
    
    display_data <- perf_data[, intersect(col_order, names(perf_data)), drop = FALSE]
    
    DT::datatable(display_data,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE) %>%
      DT::formatRound(columns = c("Accuracy", "AccuracySD"), digits = 4) %>%
      DT::formatStyle("Optimal", backgroundColor = DT::styleEqual("?", "lightgreen"))
  })
  
  # RFE Selected Features Detailed Table
  output$rfe_selected_features <- DT::renderDataTable({
    if (is.null(values$ml_importance) || nrow(values$ml_importance) == 0) {
      return(DT::datatable(data.frame(Message = "No RFE features selected"),
                           options = list(pageLength = 10, scrollX = TRUE)))
    }
    
    # Enhance the features table with additional info
    enhanced_features <- values$ml_importance
    enhanced_features$Selected <- "?"
    enhanced_features$Method <- "RFE"
    
    if (!is.null(values$rfe_detailed_results)) {
      enhanced_features$BaseModel <- values$rfe_detailed_results$base_model
      enhanced_features$CVMethod <- values$rfe_detailed_results$cv_method
    }
    
    DT::datatable(enhanced_features,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE) %>%
      DT::formatRound(columns = "Importance", digits = 4) %>%
      DT::formatStyle("Selected", backgroundColor = "lightgreen")
  })
  
  # RFE Algorithm Summary
  output$rfe_algorithm_summary <- renderPrint({
    if (is.null(values$rfe_detailed_results)) {
      cat("Run RFE analysis to see algorithm summary.")
    } else {
      rfe_info <- values$rfe_detailed_results
      cat("RFE Algorithm Summary\n")
      cat("====================\n\n")
      cat("Base Model:", rfe_info$base_model, "\n")
      cat("Cross-Validation:", rfe_info$cv_method, "\n")
      cat("Selection Function:", rfe_info$selection_function, "\n")
      cat("Optimal Features:", rfe_info$optimal_size, "\n")
      cat("Features Tested:", paste(range(rfe_info$subset_sizes_tested), collapse = " - "), "\n")
      cat("Total Subsets Evaluated:", length(rfe_info$subset_sizes_tested), "\n\n")
      
      if (!is.null(rfe_info$rfe_result)) {
        cat("Final Model Performance:\n")
        best_perf <- rfe_info$performance_by_size[
          rfe_info$performance_by_size$Variables == rfe_info$optimal_size, ]
        cat("  Accuracy:", round(best_perf$Accuracy, 4), " ", round(best_perf$AccuracySD, 4), "\n")
        if ("Kappa" %in% names(best_perf)) {
          cat("  Kappa:", round(best_perf$Kappa, 4), " ", round(best_perf$KappaSD, 4), "\n")
        }
        if ("ROC" %in% names(best_perf)) {
          cat("  ROC AUC:", round(best_perf$ROC, 4), " ", round(best_perf$ROCSD, 4), "\n")
        }
      }
    }
  })
  
  # RFE Stability Analysis
  output$rfe_stability_analysis <- renderPlot({ 
    if (is.null(values$rfe_detailed_results) ||
        is.null(values$rfe_detailed_results$rfe_result$variables)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "RFE stability analysis requires resampling results.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Extract variable selection frequency across resamples
    var_results <- values$rfe_detailed_results$rfe_result$variables
    
    if (is.null(var_results) || nrow(var_results) == 0) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "No resampling results available for stability analysis.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Calculate selection frequency for each variable
    var_freq <- table(var_results$var)
    total_resamples <- length(unique(var_results$Resample))
    
    stability_data <- data.frame(
      Variable = names(var_freq),
      SelectionFrequency = as.numeric(var_freq) / total_resamples,
      stringsAsFactors = FALSE
    )
    
    # Map variable names if possible
    if (!is.null(values$cleaned_molecules) && exists("map_numeric_ids_to_names")) {
      stability_data <- map_numeric_ids_to_names(stability_data, feature_col = "Variable")
    }
    
    # Focus on top variables for clarity
    stability_data <- stability_data[order(-stability_data$SelectionFrequency), ]
    top_vars <- head(stability_data, 20)
    
    ggplot(top_vars, aes(x = reorder(Variable, SelectionFrequency), y = SelectionFrequency)) +
      geom_col(fill = "orange", alpha = 0.8) +
      geom_hline(yintercept = 0.5, color = "red", linetype = "dashed", alpha = 0.7) +
      coord_flip() +
      labs(title = "RFE Variable Selection Stability",
           subtitle = "Frequency of selection across CV resamples",
           x = "Variables",
           y = "Selection Frequency",
           caption = "Red line: 50% selection threshold") +
      scale_y_continuous(labels = scales::percent_format()) +
      theme_minimal() +
      theme(
        plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 12),
        axis.title = element_text(size = 12, face = "bold"),
        axis.text = element_text(size = 10),
        axis.text.y = element_text(size = 9),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 1)
      )
  })
  
  # Download handlers for RFE results
  output$download_rfe_results <- downloadHandler(
    filename = function() {
      paste0("rfe_analysis_results_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      if (!requireNamespace("openxlsx", quietly = TRUE)) install.packages("openxlsx")
      
      wb <- openxlsx::createWorkbook()
      
      # Add performance by size sheet
      if (!is.null(values$rfe_detailed_results$performance_by_size)) {
        openxlsx::addWorksheet(wb, "Performance_by_Size")
        openxlsx::writeData(wb, "Performance_by_Size", values$rfe_detailed_results$performance_by_size)
      }
      
      # Add selected features sheet
      if (!is.null(values$ml_importance)) {
        openxlsx::addWorksheet(wb, "Selected_Features")
        openxlsx::writeData(wb, "Selected_Features", values$ml_importance)
      }
      
      # Add algorithm summary sheet
      if (!is.null(values$rfe_detailed_results)) {
        openxlsx::addWorksheet(wb, "Algorithm_Summary")
        summary_data <- data.frame(
          Parameter = c("Base Model", "CV Method", "Selection Function", "Optimal Features",
                        "Features Tested Range", "Total Subsets Evaluated"),
          Value = c(values$rfe_detailed_results$base_model,
                    values$rfe_detailed_results$cv_method,
                    values$rfe_detailed_results$selection_function,
                    values$rfe_detailed_results$optimal_size,
                    paste(range(values$rfe_detailed_results$subset_sizes_tested), collapse = " - "),
                    length(values$rfe_detailed_results$subset_sizes_tested))
        )
        openxlsx::writeData(wb, "Algorithm_Summary", summary_data)
      }
      
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  output$download_rfe_plots <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("rfe_plots_", Sys.Date(), ".", format)
    },
    content = function(file) {
      format <- get_safe_global_image_format()
      
      if (format == "png") {
        png(file, width = 12, height = 8, units = "in", res = 300)
      } else if (format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      
      # Performance plot
      if (!is.null(values$rfe_detailed_results)) {
        print(output$rfe_performance_plot())
      }
      
      # Variable rankings plot
      if (!is.null(values$ml_importance)) {
        print(output$rfe_variable_rankings())
      }
      
      # Stability plot
      if (!is.null(values$rfe_detailed_results)) {
        print(output$rfe_stability_analysis())
      }
      
      dev.off()
    }
  )
  
  # ==============================================================================
  # ENHANCED RANDOM FOREST OUTPUTS
  # ==============================================================================
  
  # Random Forest Error Rate Plot
  output$rf_error_plot <- renderPlot({ 
    if (is.null(values$ml_rf_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Random Forest model\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        rf_fit <- values$ml_rf_fit
        
        if (values$ml_rf_type == "classification") {
          # Classification error plot
          error_data <- as.data.frame(rf_fit$err.rate)
          error_data$ntree <- 1:nrow(error_data)
          
          # Reshape for plotting
          error_long <- reshape2::melt(error_data, id.vars = "ntree",
                                       variable.name = "Class", value.name = "Error")
          
          ggplot(error_long, aes(x = ntree, y = Error, color = Class)) +
            geom_line(size = 1) +
            labs(title = "Random Forest Classification Error Rates",
                 x = "Number of Trees", y = "Error Rate") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              legend.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            ) +
            scale_y_continuous(labels = scales::percent_format())
        } else {
          # Regression MSE plot
          mse_data <- data.frame(
            ntree = 1:length(rf_fit$mse),
            MSE = rf_fit$mse
          )
          
          ggplot(mse_data, aes(x = ntree, y = MSE)) +
            geom_line(color = "#e74c3c", size = 1) +
            labs(title = "Random Forest Mean Squared Error",
                 x = "Number of Trees", y = "Mean Squared Error") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            )
        }
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating RF error plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Variable Importance Plot (Enhanced)
  output$rf_importance_plot <- renderPlot({ 
    if (is.null(values$ml_rf_importance_full)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Variable importance data\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Use randomForest's built-in varImpPlot style with ggplot2
        imp_data <- values$ml_rf_importance_full
        # Helper: map numeric / generic Feature_* identifiers to cleaned molecule names
        map_feat_names <- function(x) {
          if (is.null(x) || is.null(values$cleaned_molecules)) return(x)
          suppressWarnings({
            idx1 <- as.integer(sub("^Feature_", "", x))
            idx2 <- ifelse(grepl("^[0-9]+$", x), as.integer(x), NA)
            idx <- ifelse(!is.na(idx1), idx1, idx2)
            valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
            x[valid] <- values$cleaned_molecules[idx[valid]]
          }, res = UI_PLOT_RES)
          x
        }
        
        if (ncol(imp_data) > 1) {
          # Multiple importance measures
          imp_df <- as.data.frame(imp_data)
          imp_df$Feature <- map_feat_names(rownames(imp_df))
          
          # Select top N features for visualization
          top_n <- min(20, nrow(imp_df))
          
          if (values$ml_rf_type == "classification") {
            # For classification, show both MeanDecreaseAccuracy and MeanDecreaseGini
            if ("MeanDecreaseAccuracy" %in% colnames(imp_df)) {
              imp_df <- imp_df[order(-imp_df$MeanDecreaseAccuracy), ][1:top_n, ]
              
              # Create side-by-side importance plot
              imp_long <- reshape2::melt(imp_df[, c("Feature", "MeanDecreaseAccuracy", "MeanDecreaseGini")],
                                         id.vars = "Feature", variable.name = "Measure", value.name = "Importance")
              
              ggplot(imp_long, aes(x = reorder(Feature, Importance), y = Importance, fill = Measure)) +
                geom_col(position = "dodge", alpha = 0.7) +
                coord_flip() +
                labs(title = "Random Forest Variable Importance",
                     x = "Features", y = "Importance Score") +
                theme_minimal() +
                theme(
                  plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                  axis.title = element_text(size = 12, face = "bold"),
                  legend.title = element_text(size = 12, face = "bold"),
                  panel.grid.minor = element_blank()
                ) +
                scale_fill_manual(values = c("MeanDecreaseAccuracy" = "#3498db", "MeanDecreaseGini" = "#e74c3c"))
            } else {
              # Fallback to single measure
              primary_col <- colnames(imp_df)[1]
              imp_df <- imp_df[order(-imp_df[[primary_col]]), ][1:top_n, ]
              
              ggplot(imp_df, aes_string(x = paste0("reorder(Feature, ", primary_col, ")"), y = primary_col)) +
                geom_col(fill = "#3498db", alpha = 0.7) +
                coord_flip() +
                labs(title = "Random Forest Variable Importance",
                     x = "Features", y = primary_col) +
                theme_minimal()
            }
          } else {
            # Regression importance
            primary_col <- if ("%IncMSE" %in% colnames(imp_df)) "%IncMSE" else colnames(imp_df)[1]
            imp_df <- imp_df[order(-imp_df[[primary_col]]), ][1:top_n, ]
            
            ggplot(imp_df, aes_string(x = paste0("reorder(Feature, ", primary_col, ")"), y = primary_col)) +
              geom_col(fill = "#e74c3c", alpha = 0.7) +
              coord_flip() +
              labs(title = "Random Forest Variable Importance (Regression)",
                   x = "Features", y = primary_col) +
              theme_minimal() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                axis.title = element_text(size = 12, face = "bold"),
                panel.grid.minor = element_blank()
              )
          }
        } else {
          # Single importance measure
          imp_df <- data.frame(
            Feature = map_feat_names(rownames(imp_data)),
            Importance = as.numeric(imp_data[, 1]),
            stringsAsFactors = FALSE
          )
          top_n <- min(20, nrow(imp_df))
          imp_df <- imp_df[order(-imp_df$Importance), ][1:top_n, ]
          
          ggplot(imp_df, aes(x = reorder(Feature, Importance), y = Importance)) +
            geom_col(fill = "#3498db", alpha = 0.7) +
            coord_flip() +
            labs(title = "Random Forest Variable Importance",
                 x = "Features", y = "Importance Score") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            )
        }
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating importance plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # MDS Plot of Proximity Matrix
  output$rf_mds_plot <- renderPlot({ 
    if (is.null(values$ml_rf_proximity)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Proximity matrix not available.\nEnable proximity calculation\nin Random Forest options.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Perform MDS on 1 - proximity matrix
        prox_mat <- values$ml_rf_proximity
        dist_mat <- 1 - prox_mat
        
        # Check for valid distance matrix
        if (any(is.na(dist_mat)) || any(dist_mat < 0)) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5, label = "Invalid proximity matrix\nfor MDS analysis.",
                            size = 5, hjust = 0.5) +
                   theme_void() + xlim(0, 1) + ylim(0, 1))
        }
        
        # Perform classical MDS
        mds_result <- cmdscale(dist_mat, eig = TRUE, k = 2)
        
        # Create MDS data frame
        mds_df <- data.frame(
          MDS1 = mds_result$points[, 1],
          MDS2 = mds_result$points[, 2],
          Group = values$ml_rf_y,
          Sample = rownames(values$ml_rf_X)
        )
        
        # Calculate goodness of fit
        gof <- mds_result$GOF
        
        ggplot(mds_df, aes(x = MDS1, y = MDS2, color = Group)) +
          geom_point(size = 3, alpha = 0.7) +
          stat_ellipse(type = "confidence", level = 0.95, alpha = 0.3) +
          labs(title = "MDS Plot of Random Forest Proximity Matrix",
               subtitle = paste("Goodness of Fit:", round(gof[1], 3), "/", round(gof[2], 3)),
               x = "MDS Dimension 1",
               y = "MDS Dimension 2") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            legend.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          ) +
          guides(color = guide_legend(title = "Group"))
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating MDS plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Partial Dependence Plot (for selected feature)
  output$rf_partial_plot <- renderPlot({ 
    req(values$ml_rf_fit, input$rf_partial_feature)
    
    if (is.null(values$ml_rf_fit) || is.null(input$rf_partial_feature) ||
        input$rf_partial_feature == "" || !input$rf_partial_feature %in% colnames(values$ml_rf_X)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Select a feature for\npartial dependence analysis.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Create partial dependence plot using randomForest::partialPlot
        rf_fit <- values$ml_rf_fit
        X_data <- values$ml_rf_X
        feature_name <- input$rf_partial_feature
        
        # For classification, use the first class as default
        which_class <- if (values$ml_rf_type == "classification" && is.factor(values$ml_rf_y)) {
          levels(values$ml_rf_y)[1]
        } else {
          NULL
        }
        
        # Calculate partial dependence
        if (values$ml_rf_type == "classification") {
          partial_result <- randomForest::partialPlot(
            rf_fit,
            pred.data = X_data,
            x.var = feature_name,
            which.class = which_class,
            plot = FALSE
          )
        } else {
          partial_result <- randomForest::partialPlot(
            rf_fit,
            pred.data = X_data,
            x.var = feature_name,
            plot = FALSE
          )
        }
        
        # Create ggplot version
        partial_df <- data.frame(
          x = partial_result$x,
          y = partial_result$y
        )
        
        title_text <- if (values$ml_rf_type == "classification") {
          paste("Partial Dependence on", feature_name, "for class", which_class)
        } else {
          paste("Partial Dependence on", feature_name)
        }
        
        ggplot(partial_df, aes(x = x, y = y)) +
          geom_line(color = "#3498db", size = 1.5) +
          geom_point(color = "#e74c3c", size = 2, alpha = 0.7) +
          labs(title = title_text,
               x = feature_name,
               y = if (values$ml_rf_type == "classification") "Logit" else "Response") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating partial plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Tree Size Distribution
  output$rf_tree_size_plot <- renderPlot({ 
    if (is.null(values$ml_rf_tree_sizes)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Tree size information\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        tree_sizes <- values$ml_rf_tree_sizes
        
        tree_df <- data.frame(
          TreeSize = tree_sizes,
          TreeIndex = 1:length(tree_sizes)
        )
        
        ggplot(tree_df, aes(x = TreeSize)) +
          geom_histogram(bins = 30, fill = "#3498db", alpha = 0.7, color = "black") +
          geom_vline(aes(xintercept = mean(TreeSize)), color = "#e74c3c",
                     linetype = "dashed", size = 1) +
          annotate("text", x = mean(tree_sizes) + sd(tree_sizes) * 0.5,
                   y = Inf, vjust = 1.5,
                   label = paste("Mean:", round(mean(tree_sizes), 1)),
                   color = "#e74c3c", fontface = "bold") +
          labs(title = "Distribution of Tree Sizes in Random Forest",
               subtitle = paste("Total trees:", length(tree_sizes)),
               x = "Number of Terminal Nodes",
               y = "Frequency") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating tree size plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Variable Usage Frequency
  output$rf_var_usage_plot <- renderPlot({ 
    if (is.null(values$ml_rf_var_used)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Variable usage information\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        var_used <- values$ml_rf_var_used
        # Defensive naming
        if (is.null(names(var_used)) || any(names(var_used) == "")) {
          if (!is.null(values$ml_rf_X)) names(var_used) <- colnames(values$ml_rf_X)
        }
        # Map numeric / generic names
        if (!is.null(values$cleaned_molecules)) {
          name_vec <- names(var_used)
          suppressWarnings({
            idx1 <- as.integer(sub("^Feature_", "", name_vec))
            idx2 <- ifelse(grepl("^[0-9]+$", name_vec), as.integer(name_vec), NA)
            idx <- ifelse(!is.na(idx1), idx1, idx2)
            valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
            name_vec[valid] <- values$cleaned_molecules[idx[valid]]
          }, res = UI_PLOT_RES)
          names(var_used) <- name_vec
        }
        
        # Create data frame for top used variables
        usage_df <- data.frame(
          Feature = names(var_used),
          Usage = as.numeric(var_used),
          stringsAsFactors = FALSE
        ) %>%
          arrange(desc(Usage)) %>%
          slice_head(n = min(25, nrow(.)))  # Top 25 most used variables
        
        ggplot(usage_df, aes(x = reorder(Feature, Usage), y = Usage)) +
          geom_col(fill = "#2ecc71", alpha = 0.7) +
          coord_flip() +
          labs(title = "Variable Usage Frequency in Random Forest",
               subtitle = paste("Frequency of usage across", values$ml_rf_fit$ntree, "trees"),
               x = "Features",
               y = "Number of Trees Using Feature") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating usage plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Outlier Detection Plot
  output$rf_outlier_plot <- renderPlot({ 
    if (is.null(values$ml_rf_proximity) || values$ml_rf_type != "classification") {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Outlier detection requires\nproximity matrix and\nclassification model.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Calculate outlying measures
        outlier_scores <- randomForest::outlier(values$ml_rf_fit)
        
        outlier_df <- data.frame(
          Sample = 1:length(outlier_scores),
          OutlierScore = outlier_scores,
          Group = values$ml_rf_y,
          stringsAsFactors = FALSE
        )
        
        # Add sample names if available
        if (!is.null(rownames(values$ml_rf_X))) {
          outlier_df$Sample <- rownames(values$ml_rf_X)
        }
        
        # Identify potential outliers (scores > 2 standard deviations)
        threshold <- mean(outlier_scores) + 2 * sd(outlier_scores)
        outlier_df$IsOutlier <- outlier_df$OutlierScore > threshold
        
        ggplot(outlier_df, aes(x = Sample, y = OutlierScore, color = Group)) +
          geom_point(size = 3, alpha = 0.7) +
          geom_hline(yintercept = threshold, linetype = "dashed", color = "#e74c3c") +
          geom_text(data = outlier_df[outlier_df$IsOutlier, ],
                    aes(label = Sample), vjust = -0.5, size = 3, show.legend = FALSE) +
          labs(title = "Random Forest Outlier Detection",
               subtitle = paste("Threshold:", round(threshold, 2)),
               x = "Sample Index",
               y = "Outlier Score") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            legend.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank(),
            axis.text.x = element_text(angle = 45, hjust = 1)
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating outlier plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Random Forest Summary Information
  output$rf_summary_info <- renderPrint({
    if (is.null(values$ml_rf_fit)) {
      cat("No Random Forest model available.\n")
    } else {
      cat("=== ENHANCED RANDOM FOREST SUMMARY ===\n\n")
      
      rf_fit <- values$ml_rf_fit
      cat("Model Type:", values$ml_rf_type, "\n")
      cat("Number of Trees:", rf_fit$ntree, "\n")
      cat("Variables tried at each split (mtry):", rf_fit$mtry, "\n")
      
      if (values$ml_rf_type == "classification") {
        cat("\nClassification Details:\n")
        cat("Number of Classes:", length(levels(values$ml_rf_y)), "\n")
        cat("Classes:", paste(levels(values$ml_rf_y), collapse = ", "), "\n")
        cat("OOB Error Rate:", round(rf_fit$err.rate[nrow(rf_fit$err.rate), "OOB"] * 100, 2), "%\n")
        
        if (!is.null(rf_fit$confusion)) {
          cat("\nConfusion Matrix (OOB):\n")
          print(rf_fit$confusion)
        }
      } else {
        cat("\nRegression Details:\n")
        cat("Mean of Squared Residuals:", round(rf_fit$mse[length(rf_fit$mse)], 4), "\n")
        cat("% Variance Explained:", round(rf_fit$rsq[length(rf_fit$rsq)] * 100, 2), "%\n")
      }
      
      # Tree size statistics
      if (!is.null(values$ml_rf_tree_sizes)) {
        cat("\nTree Size Statistics:\n")
        cat("Mean tree size (terminal nodes):", round(mean(values$ml_rf_tree_sizes), 1), "\n")
        cat("Min tree size:", min(values$ml_rf_tree_sizes), "\n")
        cat("Max tree size:", max(values$ml_rf_tree_sizes), "\n")
      }
      
      # Variable usage statistics
      if (!is.null(values$ml_rf_var_used)) {
        total_vars <- length(values$ml_rf_var_used)
        used_vars <- sum(values$ml_rf_var_used > 0)
        cat("\nVariable Usage:\n")
        cat("Total variables:", total_vars, "\n")
        cat("Variables used at least once:", used_vars, "\n")
        cat("Variable usage rate:", round(used_vars/total_vars * 100, 1), "%\n")
        
        # Most used variables
        top_used <- head(sort(values$ml_rf_var_used, decreasing = TRUE), 5)
        cat("Top 5 most used variables:\n")
        for(i in 1:length(top_used)) {
          cat("  ", names(top_used)[i], ":", top_used[i], "times\n")
        }
      }
      
      # Additional info
      cat("\nAdditional Features:\n")
      cat("Proximity matrix:", ifelse(!is.null(values$ml_rf_proximity), "Available", "Not calculated"), "\n")
      cat("Local importance:", ifelse(!is.null(values$ml_rf_local_importance), "Available", "Not calculated"), "\n")
      cat("Variable importance:", ifelse(!is.null(values$ml_rf_importance_full), "Available", "Not calculated"), "\n")
    }
  })
  
  # Update feature choices for partial dependence plot
  observe({
    if (!is.null(values$ml_rf_X)) {
      feature_choices <- colnames(values$ml_rf_X)
      if (!is.null(values$cleaned_molecules)) {
        suppressWarnings({
          idx1 <- as.integer(sub("^Feature_", "", feature_choices))
          idx2 <- ifelse(grepl("^[0-9]+$", feature_choices), as.integer(feature_choices), NA)
          idx <- ifelse(!is.na(idx1), idx1, idx2)
          valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
          feature_choices[valid] <- values$cleaned_molecules[idx[valid]]
        })
      }
      updateSelectInput(session, "rf_partial_feature",
                        choices = feature_choices,
                        selected = if(length(feature_choices) > 0) feature_choices[1] else NULL)
    }
  })
  
  # Download handlers for Random Forest outputs
  output$download_rf_plots <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("random_forest_plots_", Sys.Date(), ".", format)
    },
    content = function(file) {
      if (is.null(values$ml_rf_fit)) {
        # Create empty PDF if no model
        format <- get_safe_global_image_format()
        if (format == "png") {
          png(file, width = 8, height = 6, units = "in", res = 300)
        } else if (format == "svg") {
          svg(file, width = 8, height = 6)
        } else {
          pdf(file, width = 8, height = 6)
        }
        plot.new()
        text(0.5, 0.5, "No Random Forest model available", cex = 1.5)
        dev.off()
        return()
      }
      
      format <- get_safe_global_image_format()
      if (format == "png") {
        png(file, width = 12, height = 8, units = "in", res = 300)
      } else if (format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      
      tryCatch({
        # Error rate plot
        if (values$ml_rf_type == "classification") {
          plot(values$ml_rf_fit, main = "Random Forest Error Rates")
        } else {
          plot(values$ml_rf_fit, main = "Random Forest Mean Squared Error")
        }
        
        # Variable importance plot
        if (!is.null(values$ml_rf_importance_full)) {
          randomForest::varImpPlot(values$ml_rf_fit, main = "Variable Importance")
        }
        
        # MDS plot if proximity is available
        if (!is.null(values$ml_rf_proximity)) {
          randomForest::MDSplot(values$ml_rf_fit, values$ml_rf_y, main = "MDS Plot of Proximity Matrix")
        }
        
        # Tree size histogram
        if (!is.null(values$ml_rf_tree_sizes)) {
          hist(values$ml_rf_tree_sizes, main = "Distribution of Tree Sizes",
               xlab = "Number of Terminal Nodes", col = "lightblue")
        }
        
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error generating plots:", e$message), cex = 1)
      })
      
      dev.off()
    }
  )
  
