  output$dist_stat_comparisons_ui <- renderUI({
    # Only show when statistics are enabled
    if (!isTRUE(input$showStats)) {
      return(NULL)
    }

    # Build comparisons from current group order selection
    groups <- preserve_group_names(get_active_unique_groups() %||% values$unique_groups)
    if (!is.null(input$dist_group_order) && length(input$dist_group_order) > 0) {
      groups <- input$dist_group_order[input$dist_group_order %in% groups]
    }

    if (length(groups) < 2) {
      return(NULL)
    }

    comparisons <- combn(groups, 2, simplify = FALSE)
    comparison_labels <- vapply(comparisons, function(comp) paste(comp[1], "vs", comp[2]), character(1))

    stored_selection <- isolate(values$dist_stat_comparisons_custom)
    if (is.null(stored_selection)) {
      # No user choice saved yet: default to all comparisons
      selected <- comparison_labels
    } else if (length(stored_selection) == 0) {
      # User explicitly cleared all comparisons: keep none selected
      selected <- character(0)
    } else {
      # Match stored selections against current labels, checking both forward and reverse orders
      selected <- character(0)
      for (label in comparison_labels) {
        # Parse the label to get the two groups
        parts <- unlist(strsplit(label, " vs "))
        if (length(parts) == 2) {
          forward <- label
          reverse <- paste(parts[2], "vs", parts[1])
          # Check if either order exists in stored selection
          if (forward %in% stored_selection || reverse %in% stored_selection) {
            selected <- c(selected, label)
          }
        }
      }

      # If prior non-empty selection no longer matches current groups, fall back to all
      if (length(selected) == 0) {
        selected <- comparison_labels
      }
    }

    selectizeInput(
      "dist_stat_comparisons",
      "Stat comparisons to show",
      choices = comparison_labels,
      selected = selected,
      multiple = TRUE,
      width = "100%",
      options = list(
        placeholder = "Select comparisons for stat bars",
        plugins = list("remove_button")
      )
    )
  })

  observeEvent(input$dist_stat_comparisons, {
