  # =============================================================================
  # sPCA (Sparse PCA) Server Logic using mixOmics
  # =============================================================================
  
  # Store sPCA results
  values$spca_result <- NULL
  values$spca_data <- NULL
  
  # Initialize caching systems
  values$pca_cache <- list()
  values$spca_cache <- list()
  
  # Reactive sPCA computation for All Groups mode (updates on keepX/ncomp/scale/center)
  spca_all_result <- reactive({
    if ((input$spcaType %||% "all") != "all") return(NULL)
    req(values$normalized_data, values$group_column_indices, values$unique_groups)
    prepared <- spca_prepared_data()
    if (is.null(prepared)) return(NULL)
    
    # Cache key mirrors observer
    cache_key <- paste(
      input$spcaType %||% "all",
      input$spcaGroup1 %||% "all",
      input$spcaGroup2 %||% "all",
      input$spca_ncomp %||% 2,
      input$spca_keepX_pc1 %||% 50,
      input$spca_keepX_pc2 %||% 50,
      input$spcaScale %||% TRUE,
      input$spcaCenter %||% TRUE,
      digest::digest(values$normalized_data, algo = "xxhash64"),
      sep = "_"
    )
    
    if (!is.null(values$spca_cache[[cache_key]])) {
      return(values$spca_cache[[cache_key]])
    }
    
    if (!requireNamespace("mixOmics", quietly = TRUE)) return(NULL)
    
    keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
    if ((input$spca_ncomp %||% 2) > 2) {
      avg_keepX <- round(mean(c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)))
      keepX_values <- c(keepX_values, rep(avg_keepX, (input$spca_ncomp %||% 2) - 2))
    }
    keepX_values <- pmin(keepX_values, ncol(prepared$data))
    
    res <- tryCatch({
      list(
        spca_result = mixOmics::spca(
          X = prepared$data,
          ncomp = input$spca_ncomp %||% 2,
          keepX = keepX_values,
          scale = input$spcaScale %||% TRUE,
          center = input$spcaCenter %||% TRUE
        ),
        spca_data = prepared
      )
    }, error = function(e) NULL)
    
    if (is.null(res)) return(NULL)
    values$spca_cache[[cache_key]] <- res
    res
  })
  
  # Reactive functions for sPCA visualization (separating analysis from plotting)
  spca_plot_reactive <- reactive({
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$spca_title_size)) input$spca_title_size else 14
    axis_title_size <- if(!is.null(input$spca_axis_title_size)) input$spca_axis_title_size else 12
    axis_text_size <- if(!is.null(input$spca_axis_text_size)) input$spca_axis_text_size else 10
    legend_text_size <- if(!is.null(input$spca_legend_text_size)) input$spca_legend_text_size else 12
    
    # Choose source depending on mode
    if ((input$spcaType %||% "all") == "all") {
      res <- spca_all_result()
      req(res)
      spca_result <- res$spca_result
      spca_data <- res$spca_data
    } else {
      req(values$spca_result, values$spca_data)
      spca_result <- values$spca_result
      spca_data <- values$spca_data
    }
    
    cat("Creating sPCA plot (visualization only)\n")
    
    tryCatch({
      # Extract components
      comp1 <- spca_result$variates$X[, 1]
      comp2 <- spca_result$variates$X[, 2]
      
      # Create data frame for plotting - use corrected sample names
      original_sample_names <- spca_data$sample_names
      cleaned_sample_names <- get_corrected_column_names(original_sample_names)
      
      plot_data <- data.frame(
        PC1 = comp1,
        PC2 = comp2,
        Group = spca_data$groups,
        Sample = cleaned_sample_names
      )
      group_levels <- get_group_order_for_plot(unique(plot_data$Group))
      plot_data$Group <- factor(plot_data$Group, levels = group_levels)
      ordered_levels <- levels(plot_data$Group)
      group_levels <- get_group_order_for_plot(unique(plot_data$Group))
      plot_data$Group <- factor(plot_data$Group, levels = group_levels)
      group_levels <- get_group_order_for_plot(unique(plot_data$Group))
      plot_data$Group <- factor(plot_data$Group, levels = group_levels)
      n_groups <- length(unique(plot_data$Group))
      show_spca_legend <- isTRUE(input$spcaGridLegend %||% TRUE)
      legend_position <- if (show_spca_legend) "bottom" else "none"
      
      # Store hover data for tooltip
      values$spca_hover_data <- plot_data[, c("PC1", "PC2", "Group", "Sample"), drop = FALSE]
      
      # Calculate variance explained
      var_exp <- spca_result$prop_expl_var$X
      pc1_var <- round(var_exp[1] * 100, 1)
      pc2_var <- round(var_exp[2] * 100, 1)
      
      # Create base plot with updated styling
      p <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
        geom_point(size = 3, alpha = 0.8) +
        labs(
          title = "Sparse PCA (sPCA) Analysis",
          subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
          x = paste0("PC1 (", pc1_var, "%)"),
          y = paste0("PC2 (", pc2_var, "%)")
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
          axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
          axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
          legend.text = element_text(size = legend_text_size, face = "bold"),
          legend.title = element_blank(),
          plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
          plot.subtitle = element_text(face = "bold"),
          strip.text = element_text(face = "bold"),
          text = element_text(face = "bold"),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          legend.position = legend_position
        )
      
      # Add confidence ellipses if requested
      if (input$spca_add_ellipses %||% FALSE) {
        p <- p + stat_ellipse(aes(fill = Group),
                              level = input$spca_ellipse_level %||% 0.95,
                              alpha = 0.2,
                              geom = "polygon",
                              show.legend = FALSE)
      }
      
      # Add sample labels if requested
      if (input$spca_show_labels %||% FALSE) {
        p <- p + geom_text(aes(label = Sample),
                           vjust = -0.5,
                           size = 3,
                           check_overlap = TRUE,
                           fontface = "bold")
      }
      
      # Add sample counts to legend if requested
      if (input$spca_show_counts %||% TRUE) {
        counts <- table(plot_data$Group)
        new_labels <- paste0(names(counts), " (n=", counts, ")")
        ordered_levels <- levels(plot_data$Group)
        ordered_levels <- levels(plot_data$Group)
        
        # Apply custom colors if enabled
        custom_colors <- get_spca_colors()
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p + scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        } else {
          p <- p + scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        }
      } else {
        # Apply custom colors if enabled
        custom_colors <- get_spca_colors()
        ordered_levels <- levels(plot_data$Group)
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p + scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels)
        } else {
          p <- p + scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels)
        }
      }
      
      if (show_spca_legend && n_groups > 0) {
        legend_layout <- get_legend_grid_layout(n_groups)
        legend_guide <- guide_legend(
          nrow = legend_layout$nrow,
          ncol = legend_layout$ncol,
          byrow = TRUE
        )
        p <- p + guides(color = legend_guide, fill = legend_guide)
      }
      
      # Add persistent clicked sample labels (these appear in downloads)
      clicked <- values$spca_clicked_samples
      if (length(clicked) > 0 && "Sample" %in% names(plot_data)) {
        label_data <- plot_data[plot_data$Sample %in% clicked, , drop = FALSE]
        if (nrow(label_data) > 0) {
          p <- p + ggrepel::geom_label_repel(
            data = label_data,
            aes(x = PC1, y = PC2, label = Sample),
            size = 3.5,
            fontface = "bold",
            color = "black",
            fill = "white",
            box.padding = 0.5,
            point.padding = 0.3,
            segment.color = "grey40",
            segment.size = 0.5,
            max.overlaps = 50,
            show.legend = FALSE,
            inherit.aes = FALSE
          )
        }
      }
      
      p
    }, error = function(e) ggplot())
  })

  output$rfe_ranking_plot <- renderPlot({ 
    if (is.null(values$ml_importance) || nrow(values$ml_importance) == 0) {
      return(ggplot() + 
        annotate("text", x = 0.5, y = 0.5,
                   label = "Run RFE feature selection to see variable rankings.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Get top features for visualization
    top_features <- head(values$ml_importance, 20)  # Show top 20
    
    # Create ranking plot
    ggplot(top_features, aes(x = reorder(Feature, Importance), y = Importance)) +
      geom_col(fill = "steelblue", alpha = 0.8) +
      coord_flip() +
      labs(title = "RFE Variable Importance Rankings",
           subtitle = paste("Base Model:", values$rfe_detailed_results$base_model),
           x = "Features",
           y = "Importance Score") +
      theme_minimal() +
      theme(
        plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 12),
        axis.title = element_text(size = 12, face = "bold"),
        axis.text = element_text(size = 10),
        axis.text.y = element_text(size = 9),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 1)
      )
  })
  
  # RFE Cross-Validation Details Table
  output$rfe_cv_details <- DT::renderDataTable({
    if (is.null(values$rfe_detailed_results)) {
      return(DT::datatable(data.frame(Message = "Run RFE analysis to see CV details"),
                           options = list(pageLength = 10, scrollX = TRUE)))
    }
    
    perf_data <- values$rfe_detailed_results$performance_by_size
    perf_data$Rank <- rank(-perf_data$Accuracy, ties.method = "first")
    
    # Add optimal indicator
    optimal_size <- values$rfe_detailed_results$optimal_size
    perf_data$Optimal <- ifelse(perf_data$Variables == optimal_size, "?", "")
    
    # Reorder columns
    col_order <- c("Variables", "Accuracy", "AccuracySD", "Optimal", "Rank")
    if ("Kappa" %in% names(perf_data)) {
      col_order <- c(col_order[1:3], "Kappa", "KappaSD", col_order[4:5])
    }
    if ("ROC" %in% names(perf_data)) {
      col_order <- c(col_order, "ROC", "ROCSD")
    }
    
    display_data <- perf_data[, intersect(col_order, names(perf_data)), drop = FALSE]
    
    DT::datatable(display_data,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE) %>%
      DT::formatRound(columns = c("Accuracy", "AccuracySD"), digits = 4) %>%
      DT::formatStyle("Optimal", backgroundColor = DT::styleEqual("?", "lightgreen"))
  })
  
  # RFE Selected Features Detailed Table
  output$rfe_selected_features <- DT::renderDataTable({
    if (is.null(values$ml_importance) || nrow(values$ml_importance) == 0) {
      return(DT::datatable(data.frame(Message = "No RFE features selected"),
                           options = list(pageLength = 10, scrollX = TRUE)))
    }
    
    # Enhance the features table with additional info
    enhanced_features <- values$ml_importance
    enhanced_features$Selected <- "?"
    enhanced_features$Method <- "RFE"
    
    if (!is.null(values$rfe_detailed_results)) {
      enhanced_features$BaseModel <- values$rfe_detailed_results$base_model
      enhanced_features$CVMethod <- values$rfe_detailed_results$cv_method
    }
    
    DT::datatable(enhanced_features,
                  options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                  rownames = FALSE) %>%
      DT::formatRound(columns = "Importance", digits = 4) %>%
      DT::formatStyle("Selected", backgroundColor = "lightgreen")
  })
  
  # RFE Algorithm Summary
  output$rfe_algorithm_summary <- renderPrint({
    if (is.null(values$rfe_detailed_results)) {
      cat("Run RFE analysis to see algorithm summary.")
    } else {
      rfe_info <- values$rfe_detailed_results
      cat("RFE Algorithm Summary\n")
      cat("====================\n\n")
      cat("Base Model:", rfe_info$base_model, "\n")
      cat("Cross-Validation:", rfe_info$cv_method, "\n")
      cat("Selection Function:", rfe_info$selection_function, "\n")
      cat("Optimal Features:", rfe_info$optimal_size, "\n")
      cat("Features Tested:", paste(range(rfe_info$subset_sizes_tested), collapse = " - "), "\n")
      cat("Total Subsets Evaluated:", length(rfe_info$subset_sizes_tested), "\n\n")
      
      if (!is.null(rfe_info$rfe_result)) {
        cat("Final Model Performance:\n")
        best_perf <- rfe_info$performance_by_size[
          rfe_info$performance_by_size$Variables == rfe_info$optimal_size, ]
        cat("  Accuracy:", round(best_perf$Accuracy, 4), " ", round(best_perf$AccuracySD, 4), "\n")
        if ("Kappa" %in% names(best_perf)) {
          cat("  Kappa:", round(best_perf$Kappa, 4), " ", round(best_perf$KappaSD, 4), "\n")
        }
        if ("ROC" %in% names(best_perf)) {
          cat("  ROC AUC:", round(best_perf$ROC, 4), " ", round(best_perf$ROCSD, 4), "\n")
        }
      }
    }
  })
  
  # RFE Stability Analysis
  output$rfe_stability_analysis <- renderPlot({ 
    if (is.null(values$rfe_detailed_results) ||
        is.null(values$rfe_detailed_results$rfe_result$variables)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "RFE stability analysis requires resampling results.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Extract variable selection frequency across resamples
    var_results <- values$rfe_detailed_results$rfe_result$variables
    
    if (is.null(var_results) || nrow(var_results) == 0) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "No resampling results available for stability analysis.",
                   size = 5, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      )
    }
    
    # Calculate selection frequency for each variable
    var_freq <- table(var_results$var)
    total_resamples <- length(unique(var_results$Resample))
    
    stability_data <- data.frame(
      Variable = names(var_freq),
      SelectionFrequency = as.numeric(var_freq) / total_resamples,
      stringsAsFactors = FALSE
    )
    
    # Map variable names if possible
    if (!is.null(values$cleaned_molecules) && exists("map_numeric_ids_to_names")) {
      stability_data <- map_numeric_ids_to_names(stability_data, feature_col = "Variable")
    }
    
    # Focus on top variables for clarity
    stability_data <- stability_data[order(-stability_data$SelectionFrequency), ]
    top_vars <- head(stability_data, 20)
    
    ggplot(top_vars, aes(x = reorder(Variable, SelectionFrequency), y = SelectionFrequency)) +
      geom_col(fill = "orange", alpha = 0.8) +
      geom_hline(yintercept = 0.5, color = "red", linetype = "dashed", alpha = 0.7) +
      coord_flip() +
      labs(title = "RFE Variable Selection Stability",
           subtitle = "Frequency of selection across CV resamples",
           x = "Variables",
           y = "Selection Frequency",
           caption = "Red line: 50% selection threshold") +
      scale_y_continuous(labels = scales::percent_format()) +
      theme_minimal() +
      theme(
        plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
        plot.subtitle = element_text(hjust = 0.5, size = 12),
        axis.title = element_text(size = 12, face = "bold"),
        axis.text = element_text(size = 10),
        axis.text.y = element_text(size = 9),
        panel.grid.minor = element_blank(),
        panel.border = element_rect(color = "black", fill = NA, size = 1)
      )
  })
  
  # Download handlers for RFE results
  output$download_rfe_results <- downloadHandler(
    filename = function() {
      paste0("rfe_analysis_results_", Sys.Date(), ".xlsx")
    },
    content = function(file) {
      if (!requireNamespace("openxlsx", quietly = TRUE)) install.packages("openxlsx")
      
      wb <- openxlsx::createWorkbook()
      
      # Add performance by size sheet
      if (!is.null(values$rfe_detailed_results$performance_by_size)) {
        openxlsx::addWorksheet(wb, "Performance_by_Size")
        openxlsx::writeData(wb, "Performance_by_Size", values$rfe_detailed_results$performance_by_size)
      }
      
      # Add selected features sheet
      if (!is.null(values$ml_importance)) {
        openxlsx::addWorksheet(wb, "Selected_Features")
        openxlsx::writeData(wb, "Selected_Features", values$ml_importance)
      }
      
      # Add algorithm summary sheet
      if (!is.null(values$rfe_detailed_results)) {
        openxlsx::addWorksheet(wb, "Algorithm_Summary")
        summary_data <- data.frame(
          Parameter = c("Base Model", "CV Method", "Selection Function", "Optimal Features",
                        "Features Tested Range", "Total Subsets Evaluated"),
          Value = c(values$rfe_detailed_results$base_model,
                    values$rfe_detailed_results$cv_method,
                    values$rfe_detailed_results$selection_function,
                    values$rfe_detailed_results$optimal_size,
                    paste(range(values$rfe_detailed_results$subset_sizes_tested), collapse = " - "),
                    length(values$rfe_detailed_results$subset_sizes_tested))
        )
        openxlsx::writeData(wb, "Algorithm_Summary", summary_data)
      }
      
      openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
    }
  )
  
  output$download_rfe_plots <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("rfe_plots_", Sys.Date(), ".", format)
    },
    content = function(file) {
      format <- get_safe_global_image_format()
      
      if (format == "png") {
        png(file, width = 12, height = 8, units = "in", res = 300)
      } else if (format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      
      # Performance plot
      if (!is.null(values$rfe_detailed_results)) {
        print(output$rfe_performance_plot())
      }
      
      # Variable rankings plot
      if (!is.null(values$ml_importance)) {
        print(output$rfe_variable_rankings())
      }
      
      # Stability plot
      if (!is.null(values$rfe_detailed_results)) {
        print(output$rfe_stability_analysis())
      }
      
      dev.off()
    }
  )
  
  # ==============================================================================
  # ENHANCED RANDOM FOREST OUTPUTS
  # ==============================================================================
  
  # Random Forest Error Rate Plot
  output$rf_error_plot <- renderPlot({ 
    if (is.null(values$ml_rf_fit)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Random Forest model\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        rf_fit <- values$ml_rf_fit
        
        if (values$ml_rf_type == "classification") {
          # Classification error plot
          error_data <- as.data.frame(rf_fit$err.rate)
          error_data$ntree <- 1:nrow(error_data)
          
          # Reshape for plotting
          error_long <- reshape2::melt(error_data, id.vars = "ntree",
                                       variable.name = "Class", value.name = "Error")
          
          ggplot(error_long, aes(x = ntree, y = Error, color = Class)) +
            geom_line(size = 1) +
            labs(title = "Random Forest Classification Error Rates",
                 x = "Number of Trees", y = "Error Rate") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              legend.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            ) +
            scale_y_continuous(labels = scales::percent_format())
        } else {
          # Regression MSE plot
          mse_data <- data.frame(
            ntree = 1:length(rf_fit$mse),
            MSE = rf_fit$mse
          )
          
          ggplot(mse_data, aes(x = ntree, y = MSE)) +
            geom_line(color = "#e74c3c", size = 1) +
            labs(title = "Random Forest Mean Squared Error",
                 x = "Number of Trees", y = "Mean Squared Error") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            )
        }
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating RF error plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Variable Importance Plot (Enhanced)
  output$rf_importance_plot <- renderPlot({ 
    if (is.null(values$ml_rf_importance_full)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Variable importance data\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Use randomForest's built-in varImpPlot style with ggplot2
        imp_data <- values$ml_rf_importance_full
        # Helper: map numeric / generic Feature_* identifiers to cleaned molecule names
        map_feat_names <- function(x) {
          if (is.null(x) || is.null(values$cleaned_molecules)) return(x)
          suppressWarnings({
            idx1 <- as.integer(sub("^Feature_", "", x))
            idx2 <- ifelse(grepl("^[0-9]+$", x), as.integer(x), NA)
            idx <- ifelse(!is.na(idx1), idx1, idx2)
            valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
            x[valid] <- values$cleaned_molecules[idx[valid]]
          }, res = UI_PLOT_RES)
          x
        }
        
        if (ncol(imp_data) > 1) {
          # Multiple importance measures
          imp_df <- as.data.frame(imp_data)
          imp_df$Feature <- map_feat_names(rownames(imp_df))
          
          # Select top N features for visualization
          top_n <- min(20, nrow(imp_df))
          
          if (values$ml_rf_type == "classification") {
            # For classification, show both MeanDecreaseAccuracy and MeanDecreaseGini
            if ("MeanDecreaseAccuracy" %in% colnames(imp_df)) {
              imp_df <- imp_df[order(-imp_df$MeanDecreaseAccuracy), ][1:top_n, ]
              
              # Create side-by-side importance plot
              imp_long <- reshape2::melt(imp_df[, c("Feature", "MeanDecreaseAccuracy", "MeanDecreaseGini")],
                                         id.vars = "Feature", variable.name = "Measure", value.name = "Importance")
              
              ggplot(imp_long, aes(x = reorder(Feature, Importance), y = Importance, fill = Measure)) +
                geom_col(position = "dodge", alpha = 0.7) +
                coord_flip() +
                labs(title = "Random Forest Variable Importance",
                     x = "Features", y = "Importance Score") +
                theme_minimal() +
                theme(
                  plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                  axis.title = element_text(size = 12, face = "bold"),
                  legend.title = element_text(size = 12, face = "bold"),
                  panel.grid.minor = element_blank()
                ) +
                scale_fill_manual(values = c("MeanDecreaseAccuracy" = "#3498db", "MeanDecreaseGini" = "#e74c3c"))
            } else {
              # Fallback to single measure
              primary_col <- colnames(imp_df)[1]
              imp_df <- imp_df[order(-imp_df[[primary_col]]), ][1:top_n, ]
              
              ggplot(imp_df, aes_string(x = paste0("reorder(Feature, ", primary_col, ")"), y = primary_col)) +
                geom_col(fill = "#3498db", alpha = 0.7) +
                coord_flip() +
                labs(title = "Random Forest Variable Importance",
                     x = "Features", y = primary_col) +
                theme_minimal()
            }
          } else {
            # Regression importance
            primary_col <- if ("%IncMSE" %in% colnames(imp_df)) "%IncMSE" else colnames(imp_df)[1]
            imp_df <- imp_df[order(-imp_df[[primary_col]]), ][1:top_n, ]
            
            ggplot(imp_df, aes_string(x = paste0("reorder(Feature, ", primary_col, ")"), y = primary_col)) +
              geom_col(fill = "#e74c3c", alpha = 0.7) +
              coord_flip() +
              labs(title = "Random Forest Variable Importance (Regression)",
                   x = "Features", y = primary_col) +
              theme_minimal() +
              theme(
                plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
                axis.title = element_text(size = 12, face = "bold"),
                panel.grid.minor = element_blank()
              )
          }
        } else {
          # Single importance measure
          imp_df <- data.frame(
            Feature = map_feat_names(rownames(imp_data)),
            Importance = as.numeric(imp_data[, 1]),
            stringsAsFactors = FALSE
          )
          top_n <- min(20, nrow(imp_df))
          imp_df <- imp_df[order(-imp_df$Importance), ][1:top_n, ]
          
          ggplot(imp_df, aes(x = reorder(Feature, Importance), y = Importance)) +
            geom_col(fill = "#3498db", alpha = 0.7) +
            coord_flip() +
            labs(title = "Random Forest Variable Importance",
                 x = "Features", y = "Importance Score") +
            theme_minimal() +
            theme(
              plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
              axis.title = element_text(size = 12, face = "bold"),
              panel.grid.minor = element_blank()
            )
        }
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating importance plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # MDS Plot of Proximity Matrix
  output$rf_mds_plot <- renderPlot({ 
    if (is.null(values$ml_rf_proximity)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Proximity matrix not available.\nEnable proximity calculation\nin Random Forest options.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Perform MDS on 1 - proximity matrix
        prox_mat <- values$ml_rf_proximity
        dist_mat <- 1 - prox_mat
        
        # Check for valid distance matrix
        if (any(is.na(dist_mat)) || any(dist_mat < 0)) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5, label = "Invalid proximity matrix\nfor MDS analysis.",
                            size = 5, hjust = 0.5) +
                   theme_void() + xlim(0, 1) + ylim(0, 1))
        }
        
        # Perform classical MDS
        mds_result <- cmdscale(dist_mat, eig = TRUE, k = 2)
        
        # Create MDS data frame
        mds_df <- data.frame(
          MDS1 = mds_result$points[, 1],
          MDS2 = mds_result$points[, 2],
          Group = values$ml_rf_y,
          Sample = rownames(values$ml_rf_X)
        )
        
        # Calculate goodness of fit
        gof <- mds_result$GOF
        
        ggplot(mds_df, aes(x = MDS1, y = MDS2, color = Group)) +
          geom_point(size = 3, alpha = 0.7) +
          stat_ellipse(type = "confidence", level = 0.95, alpha = 0.3) +
          labs(title = "MDS Plot of Random Forest Proximity Matrix",
               subtitle = paste("Goodness of Fit:", round(gof[1], 3), "/", round(gof[2], 3)),
               x = "MDS Dimension 1",
               y = "MDS Dimension 2") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            legend.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          ) +
          guides(color = guide_legend(title = "Group"))
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating MDS plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Partial Dependence Plot (for selected feature)
  output$rf_partial_plot <- renderPlot({ 
    req(values$ml_rf_fit, input$rf_partial_feature)
    
    if (is.null(values$ml_rf_fit) || is.null(input$rf_partial_feature) ||
        input$rf_partial_feature == "" || !input$rf_partial_feature %in% colnames(values$ml_rf_X)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Select a feature for\npartial dependence analysis.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Create partial dependence plot using randomForest::partialPlot
        rf_fit <- values$ml_rf_fit
        X_data <- values$ml_rf_X
        feature_name <- input$rf_partial_feature
        
        # For classification, use the first class as default
        which_class <- if (values$ml_rf_type == "classification" && is.factor(values$ml_rf_y)) {
          levels(values$ml_rf_y)[1]
        } else {
          NULL
        }
        
        # Calculate partial dependence
        if (values$ml_rf_type == "classification") {
          partial_result <- randomForest::partialPlot(
            rf_fit,
            pred.data = X_data,
            x.var = feature_name,
            which.class = which_class,
            plot = FALSE
          )
        } else {
          partial_result <- randomForest::partialPlot(
            rf_fit,
            pred.data = X_data,
            x.var = feature_name,
            plot = FALSE
          )
        }
        
        # Create ggplot version
        partial_df <- data.frame(
          x = partial_result$x,
          y = partial_result$y
        )
        
        title_text <- if (values$ml_rf_type == "classification") {
          paste("Partial Dependence on", feature_name, "for class", which_class)
        } else {
          paste("Partial Dependence on", feature_name)
        }
        
        ggplot(partial_df, aes(x = x, y = y)) +
          geom_line(color = "#3498db", size = 1.5) +
          geom_point(color = "#e74c3c", size = 2, alpha = 0.7) +
          labs(title = title_text,
               x = feature_name,
               y = if (values$ml_rf_type == "classification") "Logit" else "Response") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating partial plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Tree Size Distribution
  output$rf_tree_size_plot <- renderPlot({ 
    if (is.null(values$ml_rf_tree_sizes)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Tree size information\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        tree_sizes <- values$ml_rf_tree_sizes
        
        tree_df <- data.frame(
          TreeSize = tree_sizes,
          TreeIndex = 1:length(tree_sizes)
        )
        
        ggplot(tree_df, aes(x = TreeSize)) +
          geom_histogram(bins = 30, fill = "#3498db", alpha = 0.7, color = "black") +
          geom_vline(aes(xintercept = mean(TreeSize)), color = "#e74c3c",
                     linetype = "dashed", size = 1) +
          annotate("text", x = mean(tree_sizes) + sd(tree_sizes) * 0.5,
                   y = Inf, vjust = 1.5,
                   label = paste("Mean:", round(mean(tree_sizes), 1)),
                   color = "#e74c3c", fontface = "bold") +
          labs(title = "Distribution of Tree Sizes in Random Forest",
               subtitle = paste("Total trees:", length(tree_sizes)),
               x = "Number of Terminal Nodes",
               y = "Frequency") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating tree size plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Variable Usage Frequency
  output$rf_var_usage_plot <- renderPlot({ 
    if (is.null(values$ml_rf_var_used)) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Variable usage information\nnot available.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        var_used <- values$ml_rf_var_used
        # Defensive naming
        if (is.null(names(var_used)) || any(names(var_used) == "")) {
          if (!is.null(values$ml_rf_X)) names(var_used) <- colnames(values$ml_rf_X)
        }
        # Map numeric / generic names
        if (!is.null(values$cleaned_molecules)) {
          name_vec <- names(var_used)
          suppressWarnings({
            idx1 <- as.integer(sub("^Feature_", "", name_vec))
            idx2 <- ifelse(grepl("^[0-9]+$", name_vec), as.integer(name_vec), NA)
            idx <- ifelse(!is.na(idx1), idx1, idx2)
            valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
            name_vec[valid] <- values$cleaned_molecules[idx[valid]]
          }, res = UI_PLOT_RES)
          names(var_used) <- name_vec
        }
        
        # Create data frame for top used variables
        usage_df <- data.frame(
          Feature = names(var_used),
          Usage = as.numeric(var_used),
          stringsAsFactors = FALSE
        ) %>%
          arrange(desc(Usage)) %>%
          slice_head(n = min(25, nrow(.)))  # Top 25 most used variables
        
        ggplot(usage_df, aes(x = reorder(Feature, Usage), y = Usage)) +
          geom_col(fill = "#2ecc71", alpha = 0.7) +
          coord_flip() +
          labs(title = "Variable Usage Frequency in Random Forest",
               subtitle = paste("Frequency of usage across", values$ml_rf_fit$ntree, "trees"),
               x = "Features",
               y = "Number of Trees Using Feature") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank()
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating usage plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Outlier Detection Plot
  output$rf_outlier_plot <- renderPlot({ 
    if (is.null(values$ml_rf_proximity) || values$ml_rf_type != "classification") {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5, label = "Outlier detection requires\nproximity matrix and\nclassification model.",
                 size = 5, hjust = 0.5) +
        theme_void() + xlim(0, 1) + ylim(0, 1)
    } else {
      tryCatch({
        # Calculate outlying measures
        outlier_scores <- randomForest::outlier(values$ml_rf_fit)
        
        outlier_df <- data.frame(
          Sample = 1:length(outlier_scores),
          OutlierScore = outlier_scores,
          Group = values$ml_rf_y,
          stringsAsFactors = FALSE
        )
        
        # Add sample names if available
        if (!is.null(rownames(values$ml_rf_X))) {
          outlier_df$Sample <- rownames(values$ml_rf_X)
        }
        
        # Identify potential outliers (scores > 2 standard deviations)
        threshold <- mean(outlier_scores) + 2 * sd(outlier_scores)
        outlier_df$IsOutlier <- outlier_df$OutlierScore > threshold
        
        ggplot(outlier_df, aes(x = Sample, y = OutlierScore, color = Group)) +
          geom_point(size = 3, alpha = 0.7) +
          geom_hline(yintercept = threshold, linetype = "dashed", color = "#e74c3c") +
          geom_text(data = outlier_df[outlier_df$IsOutlier, ],
                    aes(label = Sample), vjust = -0.5, size = 3, show.legend = FALSE) +
          labs(title = "Random Forest Outlier Detection",
               subtitle = paste("Threshold:", round(threshold, 2)),
               x = "Sample Index",
               y = "Outlier Score") +
          theme_minimal() +
          theme(
            plot.title = element_text(hjust = 0.5, size = 16, face = "bold"),
            plot.subtitle = element_text(hjust = 0.5, size = 12),
            axis.title = element_text(size = 12, face = "bold"),
            legend.title = element_text(size = 12, face = "bold"),
            panel.grid.minor = element_blank(),
            axis.text.x = element_text(angle = 45, hjust = 1)
          )
        
      }, error = function(e) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5, label = paste("Error creating outlier plot:\n", e$message),
                   size = 4, hjust = 0.5) +
          theme_void() + xlim(0, 1) + ylim(0, 1)
      }, res = UI_PLOT_RES)
    }
  })
  
  # Random Forest Summary Information
  output$rf_summary_info <- renderPrint({
    if (is.null(values$ml_rf_fit)) {
      cat("No Random Forest model available.\n")
    } else {
      cat("=== ENHANCED RANDOM FOREST SUMMARY ===\n\n")
      
      rf_fit <- values$ml_rf_fit
      cat("Model Type:", values$ml_rf_type, "\n")
      cat("Number of Trees:", rf_fit$ntree, "\n")
      cat("Variables tried at each split (mtry):", rf_fit$mtry, "\n")
      
      if (values$ml_rf_type == "classification") {
        cat("\nClassification Details:\n")
        cat("Number of Classes:", length(levels(values$ml_rf_y)), "\n")
        cat("Classes:", paste(levels(values$ml_rf_y), collapse = ", "), "\n")
        cat("OOB Error Rate:", round(rf_fit$err.rate[nrow(rf_fit$err.rate), "OOB"] * 100, 2), "%\n")
        
        if (!is.null(rf_fit$confusion)) {
          cat("\nConfusion Matrix (OOB):\n")
          print(rf_fit$confusion)
        }
      } else {
        cat("\nRegression Details:\n")
        cat("Mean of Squared Residuals:", round(rf_fit$mse[length(rf_fit$mse)], 4), "\n")
        cat("% Variance Explained:", round(rf_fit$rsq[length(rf_fit$rsq)] * 100, 2), "%\n")
      }
      
      # Tree size statistics
      if (!is.null(values$ml_rf_tree_sizes)) {
        cat("\nTree Size Statistics:\n")
        cat("Mean tree size (terminal nodes):", round(mean(values$ml_rf_tree_sizes), 1), "\n")
        cat("Min tree size:", min(values$ml_rf_tree_sizes), "\n")
        cat("Max tree size:", max(values$ml_rf_tree_sizes), "\n")
      }
      
      # Variable usage statistics
      if (!is.null(values$ml_rf_var_used)) {
        total_vars <- length(values$ml_rf_var_used)
        used_vars <- sum(values$ml_rf_var_used > 0)
        cat("\nVariable Usage:\n")
        cat("Total variables:", total_vars, "\n")
        cat("Variables used at least once:", used_vars, "\n")
        cat("Variable usage rate:", round(used_vars/total_vars * 100, 1), "%\n")
        
        # Most used variables
        top_used <- head(sort(values$ml_rf_var_used, decreasing = TRUE), 5)
        cat("Top 5 most used variables:\n")
        for(i in 1:length(top_used)) {
          cat("  ", names(top_used)[i], ":", top_used[i], "times\n")
        }
      }
      
      # Additional info
      cat("\nAdditional Features:\n")
      cat("Proximity matrix:", ifelse(!is.null(values$ml_rf_proximity), "Available", "Not calculated"), "\n")
      cat("Local importance:", ifelse(!is.null(values$ml_rf_local_importance), "Available", "Not calculated"), "\n")
      cat("Variable importance:", ifelse(!is.null(values$ml_rf_importance_full), "Available", "Not calculated"), "\n")
    }
  })
  
  # Update feature choices for partial dependence plot
  observe({
    if (!is.null(values$ml_rf_X)) {
      feature_choices <- colnames(values$ml_rf_X)
      if (!is.null(values$cleaned_molecules)) {
        suppressWarnings({
          idx1 <- as.integer(sub("^Feature_", "", feature_choices))
          idx2 <- ifelse(grepl("^[0-9]+$", feature_choices), as.integer(feature_choices), NA)
          idx <- ifelse(!is.na(idx1), idx1, idx2)
          valid <- !is.na(idx) & idx > 0 & idx <= length(values$cleaned_molecules)
          feature_choices[valid] <- values$cleaned_molecules[idx[valid]]
        })
      }
      updateSelectInput(session, "rf_partial_feature",
                        choices = feature_choices,
                        selected = if(length(feature_choices) > 0) feature_choices[1] else NULL)
    }
  })
  
  # Download handlers for Random Forest outputs
  output$download_rf_plots <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("random_forest_plots_", Sys.Date(), ".", format)
    },
    content = function(file) {
      if (is.null(values$ml_rf_fit)) {
        # Create empty PDF if no model
        format <- get_safe_global_image_format()
        if (format == "png") {
          png(file, width = 8, height = 6, units = "in", res = 300)
        } else if (format == "svg") {
          svg(file, width = 8, height = 6)
        } else {
          pdf(file, width = 8, height = 6)
        }
        plot.new()
        text(0.5, 0.5, "No Random Forest model available", cex = 1.5)
        dev.off()
        return()
      }
      
      format <- get_safe_global_image_format()
      if (format == "png") {
        png(file, width = 12, height = 8, units = "in", res = 300)
      } else if (format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      
      tryCatch({
        # Error rate plot
        if (values$ml_rf_type == "classification") {
          plot(values$ml_rf_fit, main = "Random Forest Error Rates")
        } else {
          plot(values$ml_rf_fit, main = "Random Forest Mean Squared Error")
        }
        
        # Variable importance plot
        if (!is.null(values$ml_rf_importance_full)) {
          randomForest::varImpPlot(values$ml_rf_fit, main = "Variable Importance")
        }
        
        # MDS plot if proximity is available
        if (!is.null(values$ml_rf_proximity)) {
          randomForest::MDSplot(values$ml_rf_fit, values$ml_rf_y, main = "MDS Plot of Proximity Matrix")
        }
        
        # Tree size histogram
        if (!is.null(values$ml_rf_tree_sizes)) {
          hist(values$ml_rf_tree_sizes, main = "Distribution of Tree Sizes",
               xlab = "Number of Terminal Nodes", col = "lightblue")
        }
        
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error generating plots:", e$message), cex = 1)
      })
      
      dev.off()
    }
  )
  
  output$download_diagnostics <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("model_diagnostics_", Sys.Date(), ".", format)
    },
    content = function(file) {
      format <- get_safe_global_image_format()
      
      if (format == "png") {
        png(file, width = 12, height = 8, units = "in", res = 300)
      } else if (format == "svg") {
        svg(file, width = 12, height = 8)
      } else {
        pdf(file, width = 12, height = 8)
      }
      # Add diagnostic plots
      dev.off()
    }
  )
  
  # Update groups dropdown for pairwise ML processing
  observe({
    req(values$unique_groups)
    updateSelectizeInput(session, "mlfsGroup1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "mlfsGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    
    # Also update RF group selections
    updateSelectizeInput(session, "rfGroup1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "rfGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    updateSelectizeInput(session, "rf_groups_multi", choices = values$unique_groups)
    
    # Also update Permutation group selections
    updateSelectizeInput(session, "permGroup1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "permGroup2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    updateSelectizeInput(session, "perm_groups_multi", choices = values$unique_groups)
    
    # Also update RFE group selections
    updateSelectizeInput(session, "rfe_group_1", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 0) values$unique_groups[1] else NULL)
    updateSelectizeInput(session, "rfe_group_2", choices = values$unique_groups,
                         selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else NULL)
    updateSelectizeInput(session, "rfe_groups_multi", choices = values$unique_groups)
    
    # Also update LASSO and Boruta multi-class selections
    updateSelectizeInput(session, "lasso_groups_multi", choices = values$unique_groups)
    updateSelectizeInput(session, "boruta_groups_multi", choices = values$unique_groups)
  })
  
  # Use selected features downstream
  values$selected_features <- list(
    features = NULL,
    source = NULL # "PCA" or "ML"
  )
  
  get_selected_features <- reactive({
    req(input$feature_source)
    all_features <- rownames(data) # or however you define all features
    switch(input$feature_source,
           "all" = all_features,
           "pca" = values$selected_features$features[values$selected_features$source == "PCA"],
           "ml"  = values$selected_features$features[values$selected_features$source == "ML"]
    )
  })
  
  # Use inside a reactive context:
  filtered_data <- reactive({
    selected_features <- get_selected_features()
    req(selected_features)
    data[selected_features, , drop = FALSE]
  })
  
  # Helper to get status text for the selected feature used or not
  get_feature_set_status <- function(source_input = "all") {
    if (is.null(source_input)) {
      return("<b>Using:</b> All Features")
    }
    
    tryCatch({
      switch(source_input,
             "all" = "<b>Using:</b> All Features",
             "pca" = {
               # Use centralized function to check PCA availability
               if (is.null(values$cleaned_molecules)) {
                 return("<b>Using:</b> All Features (Data not loaded)")
               }
               
               feature_indices <- get_feature_indices_by_source("pca", "All Groups")
               total_features <- length(values$cleaned_molecules)
               
               if (length(feature_indices) < total_features && length(feature_indices) > 0) {
                 paste0("<b>Using:</b> Top ", length(feature_indices), " PCA Features")
               } else {
                 "<b>Using:</b> All Features (PCA not available)"
               }
             },
             "ml" = {
               # Use centralized function to check ML availability
               if (is.null(values$cleaned_molecules)) {
                 return("<b>Using:</b> All Features (Data not loaded)")
               }
               
               feature_indices <- get_feature_indices_by_source("ml", "All Groups")
               total_features <- length(values$cleaned_molecules)
               
               if (length(feature_indices) < total_features && length(feature_indices) > 0) {
                 paste0("<b>Using:</b> ", length(feature_indices), " ML-Selected Features")
               } else {
                 "<b>Using:</b> All Features (ML not available)"
               }
             },
             "<b>Using:</b> All Features"
      )  }, error = function(e) {
        return("<b>Using:</b> All Features (Error checking status)")
      })
  }
  
  # Render the status box for each tab
  output$heatmap_feature_set_status <- renderUI({
    input$heatmap_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features  # Add reactive dependency on selected features
    HTML(get_feature_set_status(input$heatmap_feature_source))
  })
  
  output$distribution_feature_set_status <- renderUI({
    input$dist_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features  # Add reactive dependency on selected features
    HTML(get_feature_set_status(input$dist_feature_source))
  })
  
  output$distribution_feature_count <- renderUI({
    req(values$cleaned_molecules)
    
    # Get available features based on the selected source
    available_features <- get_available_feature_names(input$dist_feature_source %||% "all", "All Groups")
    
    total_features <- length(values$cleaned_molecules)
    selected_features <- length(available_features)
    
    # Create a visual indicator
    if (selected_features == total_features) {
      badge_class <- "badge-secondary"
      icon_type <- "list"
    } else if (selected_features == 0) {
      badge_class <- "badge-danger"
      icon_type <- "exclamation-triangle"
    } else {
      badge_class <- "badge-success"
      icon_type <- "filter"
    }
    
    tags$span(
      style = "font-size: 0.9rem;",
      tags$span(
        class = paste("badge", badge_class),
        style = "padding: 8px 12px; border-radius: 20px; font-weight: 500;",
        icon(icon_type, style = "margin-right: 5px;"),
        paste(selected_features, "/", total_features)
      )
    )
  })
  
  # Feature count indicator for Distribution Analysis
  output$distribution_feature_count <- renderUI({
    req(values$cleaned_molecules)
    
    # Get available features based on the selected source
    available_features <- get_available_feature_names(input$dist_feature_source %||% "all", "All Groups")
    
    total_features <- length(values$cleaned_molecules)
    selected_features <- length(available_features)
    
    # Create a visual indicator
    if (selected_features == total_features) {
      badge_class <- "badge-secondary"
      icon_type <- "list"
    } else if (selected_features == 0) {
      badge_class <- "badge-danger"
      icon_type <- "exclamation-triangle"
    } else {
      badge_class <- "badge-success"
      icon_type <- "filter"
    }
    
    tags$span(
      style = "font-size: 0.9rem;",
      tags$span(
        class = paste("badge", badge_class),
        style = "padding: 8px 12px; border-radius: 20px; font-weight: 500;",
        icon(icon_type, style = "margin-right: 5px;"),
        paste(selected_features, "/", total_features)
      )
    )
  })
  
  output$diff_feature_set_status <- renderUI({
    input$diff_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features  # Add reactive dependency on selected features
    HTML(get_feature_set_status(input$diff_feature_source))
  })
  
  output$intersection_feature_set_status <- renderUI({
    input$intersection_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features  # Add reactive dependency on selected features
    HTML(get_feature_set_status(input$intersection_feature_source))
  })
  
  output$roc_feature_set_status <- renderUI({
    input$roc_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features  # Add reactive dependency on selected features
    HTML(get_feature_set_status(input$roc_feature_source))
  })
  
  output$proteomics_feature_set_status <- renderUI({
    input$proteomics_feature_source
    input$pca_top_features
    input$pca_feature_ranking
    values$pca_top_features
    values$selected_features
    HTML(get_feature_set_status(input$proteomics_feature_source))
  })
  
  # Reset button logic
  observeEvent(input$reset_feature_selection, {
    values$selected_features$features <- NULL
    values$selected_features$source <- NULL
    
    # Reset all tab-specific feature sources to "all"
    updateSelectInput(session, "heatmap_feature_source", selected = "all")
    updateSelectInput(session, "dist_feature_source", selected = "all")
    updateSelectInput(session, "diff_feature_source", selected = "all")
    updateSelectInput(session, "intersection_feature_source", selected = "all")
    updateSelectInput(session, "roc_feature_source", selected = "all")
    updateSelectInput(session, "proteomics_feature_source", selected = "all")
    showNotification("Feature selection reset to all features.", type = "message")
  })
  
  # Download PCA Grid (dedicated handler)
  output$downloadPCAGridBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("PCA_Grid_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      tryCatch({
        # More lenient validation - check that basic data is available
        if (is.null(values$normalized_data) || is.null(values$unique_groups)) {
          showNotification("Please process data first before downloading PCA plots.", type = "error")
          return()
        }
        
        # Check if we have the plot object stored from the UI
        if (is.null(values$pca_grid_obj)) {
          showNotification("No PCA plot available to download. Please generate PCA plots first.", type = "error")
          return()
        }
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Use the exact same plot object that's displayed in the UI
        grid_plot <- values$pca_grid_obj
        
        # Calculate appropriate canvas size for the download
        # For pairwise plots, use grid dimensions
        if (input$pcaType == "pairwise") {
          # Use actual pairwise comparison count (not all-possible-pairs from unique_groups)
          n_plots <- if (!is.null(values$current_pairwise_combinations)) {
            max(1, nrow(values$current_pairwise_combinations))
          } else {
            n_groups <- length(values$unique_groups) %||% 0
            if (n_groups < 2) 1 else n_groups * (n_groups - 1) / 2
          }
          grid_cols <- input$pcaGridCols %||% 2
          n_rows <- ceiling(n_plots / grid_cols)
          grid_width <- input$pcaGridWidth %||% 400
          grid_height <- input$pcaGridHeight %||% 400
          
          raw_w <- min(49, max(6, (grid_width * grid_cols) / 100))
          raw_h <- min(49, max(6, (grid_height * n_rows) / 100))
          ggsave(file,
                 plot = grid_plot,
                 width = raw_w,
                 height = raw_h,
                 dpi = dpi,
                 device = resolve_ggsave_device(format),
                 units = "in",
                 limitsize = FALSE)
        } else {
          # For all groups, use the dedicated width/height controls
          plot_width <- input$pcaAllWidth %||% 600
          plot_height <- input$pcaAllHeight %||% 600
          
          raw_w <- min(49, max(6, plot_width / 100))
          raw_h <- min(49, max(6, plot_height / 100))
          ggsave(file,
                 plot = grid_plot,
                 width = raw_w,
                 height = raw_h,
                 dpi = dpi,
                 device = resolve_ggsave_device(format),
                 units = "in",
                 limitsize = FALSE)
        }
        
        showNotification("PCA plot downloaded successfully!", type = "message")
        
      }, error = function(e) {
        showNotification(paste("Error downloading PCA plot:", e$message), type = "error")
      })
    }
  )
  
  # =============================================================================
  # sPCA (Sparse PCA) Server Logic using mixOmics
  # =============================================================================
  
  # Store sPCA results
  values$spca_result <- NULL
  values$spca_data <- NULL
  
  # Initialize caching systems
  values$pca_cache <- list()
  values$spca_cache <- list()
  
  # Reactive sPCA computation for All Groups mode (updates on keepX/ncomp/scale/center)
  spca_all_result <- reactive({
    if ((input$spcaType %||% "all") != "all") return(NULL)
    req(values$normalized_data, values$group_column_indices, values$unique_groups)
    prepared <- spca_prepared_data()
    if (is.null(prepared)) return(NULL)
    
    # Cache key mirrors observer
    cache_key <- paste(
      input$spcaType %||% "all",
      input$spcaGroup1 %||% "all",
      input$spcaGroup2 %||% "all",
      input$spca_ncomp %||% 2,
      input$spca_keepX_pc1 %||% 50,
      input$spca_keepX_pc2 %||% 50,
      input$spcaScale %||% TRUE,
      input$spcaCenter %||% TRUE,
      digest::digest(values$normalized_data, algo = "xxhash64"),
      sep = "_"
    )
    
    if (!is.null(values$spca_cache[[cache_key]])) {
      return(values$spca_cache[[cache_key]])
    }
    
    if (!requireNamespace("mixOmics", quietly = TRUE)) return(NULL)
    
    keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
    if ((input$spca_ncomp %||% 2) > 2) {
      avg_keepX <- round(mean(c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)))
      keepX_values <- c(keepX_values, rep(avg_keepX, (input$spca_ncomp %||% 2) - 2))
    }
    keepX_values <- pmin(keepX_values, ncol(prepared$data))
    
    res <- tryCatch({
      list(
        spca_result = mixOmics::spca(
          X = prepared$data,
          ncomp = input$spca_ncomp %||% 2,
          keepX = keepX_values,
          scale = input$spcaScale %||% TRUE,
          center = input$spcaCenter %||% TRUE
        ),
        spca_data = prepared
      )
    }, error = function(e) NULL)
    
    if (is.null(res)) return(NULL)
    values$spca_cache[[cache_key]] <- res
    res
  })
  
  # Reactive functions for sPCA visualization (separating analysis from plotting)
  spca_plot_reactive <- reactive({
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$spca_title_size)) input$spca_title_size else 14
    axis_title_size <- if(!is.null(input$spca_axis_title_size)) input$spca_axis_title_size else 12
    axis_text_size <- if(!is.null(input$spca_axis_text_size)) input$spca_axis_text_size else 10
    legend_text_size <- if(!is.null(input$spca_legend_text_size)) input$spca_legend_text_size else 12
    
    # Choose source depending on mode
    if ((input$spcaType %||% "all") == "all") {
      res <- spca_all_result()
      req(res)
      spca_result <- res$spca_result
      spca_data <- res$spca_data
    } else {
      req(values$spca_result, values$spca_data)
      spca_result <- values$spca_result
      spca_data <- values$spca_data
    }
    
    cat("Creating sPCA plot (visualization only)\n")
    
    tryCatch({
      # Extract components
      comp1 <- spca_result$variates$X[, 1]
      comp2 <- spca_result$variates$X[, 2]
      
      # Create data frame for plotting - use corrected sample names
      original_sample_names <- spca_data$sample_names
      cleaned_sample_names <- get_corrected_column_names(original_sample_names)
      
      plot_data <- data.frame(
        PC1 = comp1,
        PC2 = comp2,
        Group = spca_data$groups,
        Sample = cleaned_sample_names
      )
      
      # Set up group factor with proper ordering
      group_levels <- get_group_order_for_plot(unique(plot_data$Group))
      plot_data$Group <- factor(plot_data$Group, levels = group_levels)
      
      # Store hover data for tooltip
      values$spca_hover_data <- plot_data[, c("PC1", "PC2", "Group", "Sample"), drop = FALSE]
      
      # Calculate variance explained
      var_exp <- spca_result$prop_expl_var$X
      pc1_var <- round(var_exp[1] * 100, 1)
      pc2_var <- round(var_exp[2] * 100, 1)
      
      # Create base plot with updated styling
      p <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
        geom_point(size = 3, alpha = 0.8) +
        labs(
          title = "Sparse PCA (sPCA) Analysis",
          subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
          x = paste0("PC1 (", pc1_var, "%)"),
          y = paste0("PC2 (", pc2_var, "%)")
        ) +
        ggprism::theme_prism(base_size = 14) +
        theme(
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8),
          axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
          axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
          axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
          legend.text = element_text(size = legend_text_size, face = "bold"),
          legend.title = element_blank(),
          plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
          plot.subtitle = element_text(face = "bold"),
          strip.text = element_text(face = "bold"),
          text = element_text(face = "bold"),
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          legend.position = ifelse(input$spcaGridLegend %||% TRUE, "bottom", "none")
        )
      
      # Add confidence ellipses if requested
      if (input$spca_add_ellipses %||% FALSE) {
        p <- p + stat_ellipse(aes(fill = Group),
                              level = input$spca_ellipse_level %||% 0.95,
                              alpha = 0.2,
                              geom = "polygon",
                              show.legend = FALSE)
      }
      
      # Add sample labels if requested
      if (input$spca_show_labels %||% FALSE) {
        p <- p + geom_text(aes(label = Sample),
                           vjust = -0.5,
                           size = 3,
                           check_overlap = TRUE,
                           fontface = "bold")
      }
      
      # Add sample counts to legend if requested
      if (input$spca_show_counts %||% TRUE) {
        counts <- table(plot_data$Group)
        new_labels <- paste0(names(counts), " (n=", counts, ")")
        ordered_levels <- levels(plot_data$Group)
        
        # Apply custom colors if enabled
        custom_colors <- get_spca_colors()
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p + scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        } else {
          p <- p + scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
        }
      } else {
        # Apply custom colors if enabled
        custom_colors <- get_spca_colors()
        ordered_levels <- levels(plot_data$Group)
        if (!is.null(custom_colors)) {
          plot_colors <- custom_colors[ordered_levels]
          p <- p + scale_color_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_manual(name = NULL, values = plot_colors, breaks = ordered_levels, limits = ordered_levels)
        } else {
          p <- p + scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels) +
            scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels)
        }
      }
      
      # Apply smart legend grid layout for 4+ groups (like PCA)
      n_groups <- length(unique(plot_data$Group))
      if (isTRUE(input$spcaGridLegend %||% TRUE) && n_groups >= 4) {
        legend_layout <- get_legend_grid_layout(n_groups)
        legend_guide <- guide_legend(
          nrow = legend_layout$nrow,
          ncol = legend_layout$ncol,
          byrow = TRUE
        )
        p <- p + guides(color = legend_guide, fill = legend_guide)
      }
      
      # Add persistent clicked sample labels (these appear in downloads)
      clicked <- values$spca_clicked_samples
      if (length(clicked) > 0 && "Sample" %in% names(plot_data)) {
        label_data <- plot_data[plot_data$Sample %in% clicked, , drop = FALSE]
        if (nrow(label_data) > 0) {
          p <- p + ggrepel::geom_label_repel(
            data = label_data,
            aes(x = PC1, y = PC2, label = Sample),
            size = 3.5,
            fontface = "bold",
            color = "black",
            fill = "white",
            box.padding = 0.5,
            point.padding = 0.3,
            segment.color = "grey40",
            segment.size = 0.5,
            max.overlaps = 50,
            show.legend = FALSE,
            inherit.aes = FALSE
          )
        }
      }
      
      return(p)
      
    }, error = function(e) {
      cat("Error creating sPCA plot:", e$message, "\n")
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = paste("Error creating sPCA plot:", e$message),
                        size = 6) +
               theme_void())
    })
  })
  
  spca_variance_plot_reactive <- reactive({
    # Use context-aware sPCA result so switching Analysis type or groups updates this plot
    res <- spca_result_for_current_context()
    req(res)
    spca_result <- res$spca_result
    
    cat("Creating sPCA variance plot (visualization only)\n")
    
    tryCatch({
      # Extract variance explained
      var_exp <- spca_result$prop_expl_var$X
      
      # Create data frame with proper PC ordering
      var_data <- data.frame(
        Component = factor(paste0("PC", 1:length(var_exp)),
                           levels = paste0("PC", 1:length(var_exp))),
        Variance = var_exp * 100,
        Cumulative = cumsum(var_exp) * 100
      )
      
      # Create combined plot (similar to PCA variance plot)
      p <- ggplot(var_data) +
        geom_col(aes(x = Component, y = Variance), fill = "#3498db", alpha = 0.8) +
        geom_line(aes(x = Component, y = Cumulative, group = 1),
                  color = "#e74c3c", size = 1.5) +
        geom_point(aes(x = Component, y = Cumulative),
                   color = "#e74c3c", size = 3) +
        scale_y_continuous(name = "Variance Explained (%)",
                           sec.axis = sec_axis(~., name = "Cumulative Variance (%)")) +
        ggprism::theme_prism() +
        labs(title = "sPCA Variance Explained",
             x = "Principal Component") +
        theme(
          axis.text.x = element_text(angle = 45, hjust = 1),
          plot.title = element_text(hjust = 0.5)
        )
      
      return(p)
      
    }, error = function(e) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = paste("Error creating variance plot:", e$message),
                        size = 6) +
               theme_void())
    })
  })
  
  spca_loadings_plot_reactive <- reactive({
    # Use context-aware sPCA result for loadings
    res <- spca_result_for_current_context()
    req(res)
    spca_result <- res$spca_result
    spca_data <- res$spca_data
    
    # Explicitly depend on the toggle to ensure reactivity
    toggle_state <- input$spca_use_feature_names
    
    cat("Creating sPCA loadings plot (visualization only)\n")
    
    tryCatch({
      # Extract loadings for PC1 and PC2
      loadings_pc1 <- spca_result$loadings$X[, 1]
      loadings_pc2 <- spca_result$loadings$X[, 2]
      
      # Get loadings names first
      loadings_names <- rownames(spca_result$loadings$X)
      
      # CRITICAL: Map loadings_names to the actual cleaned feature names
      # loadings_names are from transposed data (feature names from original data)
      # They should match rownames(values$normalized_data) or cleaned_molecules
      
      # Build the feature names mapping based on loadings_names
      mapped_feature_names <- character(length(loadings_names))
      
      for (i in seq_along(loadings_names)) {
        name <- loadings_names[i]
        
        # Strategy 1: Direct match in cleaned_molecules
        if (!is.null(values$cleaned_molecules)) {
          match_idx <- match(name, values$cleaned_molecules)
          if (!is.na(match_idx)) {
            mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
            next
          }
        }
        
        # Strategy 2: Direct match in rownames(normalized_data)
        if (!is.null(rownames(values$normalized_data))) {
          match_idx <- match(name, rownames(values$normalized_data))
          if (!is.na(match_idx)) {
            mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
            next
          }
        }
        
        # Strategy 3: If name is numeric (X123 format), extract and map by index
        if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
          idx <- suppressWarnings(as.integer(substring(name, 2)))
          if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
            mapped_feature_names[i] <- values$cleaned_molecules[idx]
            next
          }
        }
        
        # Strategy 4: If name is just a number, map by index
        if (grepl("^\\d+$", name)) {
          idx <- suppressWarnings(as.integer(name))
          if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
            mapped_feature_names[i] <- values$cleaned_molecules[idx]
            next
          }
        }
        
        # Fallback: use original loadings name
        mapped_feature_names[i] <- name
      }
      
      # Determine which labels to use based on toggle
      use_feature_names <- isTRUE(toggle_state)
      
      if (use_feature_names) {
        # Use mapped feature names
        names(loadings_pc1) <- mapped_feature_names
        names(loadings_pc2) <- mapped_feature_names
        x_label <- "Features"
      } else {
        # Use numeric variable IDs consistently, not raw names
        idx_all <- sapply(loadings_names, function(name) {
          if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
            suppressWarnings(as.integer(substring(name, 2)))
          } else if (!is.null(rownames(values$normalized_data))) {
            mi <- match(name, rownames(values$normalized_data))
            if (is.na(mi) && !is.null(values$cleaned_molecules)) {
              mi <- match(name, values$cleaned_molecules)
            }
            if (is.na(mi) && !is.null(spca_data$feature_names)) {
              mi <- match(name, spca_data$feature_names)
            }
            mi
          } else {
            NA_integer_
          }
        })
        # Fallback: position index
        na_pos <- which(is.na(idx_all))
        if (length(na_pos) > 0) idx_all[na_pos] <- na_pos
        id_labels <- as.character(idx_all)
        names(loadings_pc1) <- id_labels
        names(loadings_pc2) <- id_labels
        x_label <- "Variables (ID)"
      }
      
      # Get selected variables (non-zero loadings)
      selected_pc1 <- loadings_pc1[loadings_pc1 != 0]
      selected_pc2 <- loadings_pc2[loadings_pc2 != 0]
      
      # Create data frames for plotting
      pc1_data <- data.frame(
        Variable = names(selected_pc1),
        Loading = selected_pc1,
        Component = "PC1"
      )
      
      pc2_data <- data.frame(
        Variable = names(selected_pc2),
        Loading = selected_pc2,
        Component = "PC2"
      )
      
      # Combine data
      loadings_data <- rbind(pc1_data, pc2_data)
      
      if (nrow(loadings_data) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No variables selected in current analysis",
                          size = 6) +
                 theme_void())
      }
      
      # Create plot with PCA feature contribution styling
      p <- ggplot(loadings_data, aes(x = reorder(Variable, abs(Loading)), y = Loading, fill = Component)) +
        geom_col(alpha = 0.8) +
        coord_flip() +
        facet_wrap(~Component, scales = "free_y") +
        labs(
          title = "sPCA Loadings for Selected Variables",
          subtitle = paste("PC1:", length(selected_pc1), "variables, PC2:", length(selected_pc2), "variables"),
          x = x_label,
          y = "Loading Value"
        ) +
        ggprism::theme_prism() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 12, hjust = 0.5),
          strip.text = element_text(size = 12, face = "bold"),
          axis.text = element_text(size = 10, face = "bold", color = "black"),
          axis.title = element_text(size = 12, face = "bold", color = "black"),
          legend.position = "none",
          panel.grid = element_blank(),
          axis.line = element_line(color = "black", size = 0.8)
        ) +
        scale_fill_manual(values = c("PC1" = "#3498db", "PC2" = "#e74c3c"))
      
      return(p)
      
    }, error = function(e) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = paste("Error creating loadings plot:", e$message),
                        size = 6) +
               theme_void())
    })
  })
  
  # Original sPCA observer with caching (analysis part)
  
  # Update group choices for sPCA pairwise analysis
  observe({
    req(values$unique_groups)
    updateSelectizeInput(session, "spcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
    updateSelectizeInput(session, "spcaGroup2", choices = values$unique_groups, selected = values$unique_groups[2])
  })
  
  # Reactive data preparation for sPCA
  spca_prepared_data <- reactive({
    req(values$normalized_data)
    req(values$group_column_indices)
    req(values$unique_groups)
    
    # Additional validation to prevent errors during data loading
    if (is.null(values$group_column_indices) || length(values$group_column_indices) == 0) {
      return(NULL)
    }
    
    # Get data based on analysis type
    if ((input$spcaType %||% "all") == "pairwise") {
      req(input$spcaGroup1, input$spcaGroup2)
      req(input$spcaGroup1 != input$spcaGroup2)
      
      # Find the indices for the selected groups
      group1_idx <- which(values$unique_groups == input$spcaGroup1)
      group2_idx <- which(values$unique_groups == input$spcaGroup2)
      
      # Validate that groups exist
      if (length(group1_idx) == 0 || length(group2_idx) == 0) {
        return(NULL)
      }
      
      # Get column indices for each group
      group1_cols <- values$group_column_indices[[group1_idx]]
      group2_cols <- values$group_column_indices[[group2_idx]]
      
      # Combine column indices and sort them to maintain original data order
      selected_cols <- sort(c(group1_cols, group2_cols))
      
      # Extract data subset
      data_subset <- values$normalized_data[, selected_cols, drop = FALSE]
      
      # Create proper group labels based on actual column assignments
      # Map each selected column to its correct group
      groups_subset <- character(length(selected_cols))
      for (i in seq_along(selected_cols)) {
        col_index <- selected_cols[i]
        if (col_index %in% group1_cols) {
          groups_subset[i] <- input$spcaGroup1
        } else if (col_index %in% group2_cols) {
          groups_subset[i] <- input$spcaGroup2
        }
      }
      
    } else {
      # All groups - need to properly map group labels to actual columns
      # Use active grouping level if dual grouping is available
      if (isTRUE(values$has_dual_grouping) && !is.null(values$active_grouping_level)) {
        if (values$active_grouping_level == "biological") {
          active_groups <- values$biological_unique_groups
          active_indices <- values$biological_group_column_indices
        } else {
          active_groups <- values$experimental_unique_groups
          active_indices <- values$experimental_group_column_indices
        }
      } else {
        active_groups <- values$unique_groups
        active_indices <- values$group_column_indices
      }
      
      all_columns <- unlist(active_indices)
      
      # Validate that we have columns to work with
      if (length(all_columns) == 0) {
        return(NULL)
      }
      
      data_subset <- values$normalized_data[, all_columns, drop = FALSE]
      
      # Create proper group labels based on actual column assignments
      # Use a more robust mapping that handles scrambled columns correctly
      groups_subset <- character(length(all_columns))
      for (i in seq_along(all_columns)) {
        col_index <- all_columns[i]
        # Find which group this column belongs to
        for (j in seq_along(active_groups)) {
          group_name <- active_groups[j]
          group_cols <- active_indices[[j]]
          if (col_index %in% group_cols) {
            groups_subset[i] <- group_name
            break
          }
        }
      }
    }
    
    # Basic validation - ensure minimum data dimensions
    if (ncol(data_subset) < 2) {
      return(NULL)
    }
    
    if (nrow(data_subset) < 2) {
      return(NULL)
    }
    
    # Transpose data for mixOmics (samples as rows, features as columns)
    data_t <- t(data_subset)
    
    list(
      data = data_t,
      groups = groups_subset,
      sample_names = colnames(data_subset),
      feature_names = rownames(data_subset)
    )
  })
  
  # --- sPCA context helpers to keep sPCA views in sync with Analysis type/group selection ---
  spca_current_context_key <- reactive({
    req(input$spcaType)
    if ((input$spcaType %||% "all") == "pairwise") {
      req(input$spcaGroup1, input$spcaGroup2)
      if (identical(input$spcaGroup1, input$spcaGroup2)) return(NULL)
      paste(input$spcaGroup1, "vs", input$spcaGroup2)
    } else {
      "all_groups"
    }
  })
  
  spca_result_for_current_context <- reactive({
    # All mode reuses the dedicated all-mode reactive compute (spca_all_result)
    if ((input$spcaType %||% "all") == "all") {
      res <- spca_all_result()
      req(res)
      return(res)
    }
    # Pairwise mode: ensure values$spca_result is computed for the chosen pair
    req(values$unique_groups, values$group_column_indices)
    ctx <- spca_current_context_key()
    req(ctx)
    # If current values$spca_data aligns with the requested pair, reuse it; otherwise recompute
    need_recompute <- TRUE
    if (!is.null(values$spca_data) && !is.null(values$spca_data$groups)) {
      grp <- unique(values$spca_data$groups)
      parts <- strsplit(ctx, " vs ")[[1]]
      if (length(parts) == 2) {
        if (setequal(grp, parts)) need_recompute <- FALSE
      }
    }
    if (need_recompute || is.null(values$spca_result)) {
      # Prepare data for the selected pair and run sPCA with current parameters
      g1 <- input$spcaGroup1; g2 <- input$spcaGroup2
      g1_idx <- which(values$unique_groups == g1)
      g2_idx <- which(values$unique_groups == g2)
      req(length(g1_idx) == 1, length(g2_idx) == 1)
      g1_cols <- values$group_column_indices[[g1_idx]]
      g2_cols <- values$group_column_indices[[g2_idx]]
      selected_cols <- sort(c(g1_cols, g2_cols))
      data_subset <- values$normalized_data[, selected_cols, drop = FALSE]
      groups_subset <- vapply(selected_cols, function(ci) if (ci %in% g1_cols) g1 else g2, character(1))
      data_t <- t(data_subset)
      keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
      keepX_values <- pmin(keepX_values, ncol(data_t))
      spca_res <- mixOmics::spca(
        X = data_t,
        ncomp = input$spca_ncomp %||% 2,
        keepX = if ((input$spca_ncomp %||% 2) > 2) {
          c(keepX_values, rep(round(mean(keepX_values)), (input$spca_ncomp %||% 2) - 2))
        } else keepX_values,
        scale = input$spcaScale %||% TRUE,
        center = input$spcaCenter %||% TRUE
      )
      values$spca_result <- spca_res
      values$spca_data <- list(
        data = data_t,
        groups = groups_subset,
        sample_names = colnames(data_subset),
        feature_names = rownames(data_subset)
      )
    }
    list(spca_result = values$spca_result, spca_data = values$spca_data)
  })
  
  # Perform sPCA analysis with Data tab priority
  observe({
    # Explicitly depend on current_tab to ensure observer re-triggers when returning to Dimensionality Reduction tab
    current_tab <- input$current_tab
    
    # Only run sPCA computations when the Dimensionality Reduction tab is active
    if (is.null(current_tab) || current_tab != "Dimensionality Reduction") {
      return()
    }
    # Pause heavy sPCA operations if Data tab is active (priority loading)
    if (isTRUE(values$data_tab_active)) {
      return()
    }
    
    # Explicitly depend on active_grouping_level to trigger re-computation when it changes
    grouping_level <- values$active_grouping_level %||% "single"
    
    # Validate that we have the necessary data structures before proceeding
    if (is.null(values$normalized_data) ||
        is.null(values$group_column_indices) ||
        is.null(values$unique_groups) ||
        length(values$group_column_indices) == 0) {
      return()
    }
    
    # Only proceed if spca_prepared_data would return valid data
    prepared_data_check <- NULL
    tryCatch({
      prepared_data_check <- spca_prepared_data()
    }, error = function(e) {
      return()
    })
    
    if (is.null(prepared_data_check)) {
      return()
    }
    
    req(spca_prepared_data())
    
    # Create cache key based on critical parameters
    cache_key <- paste(
      input$spcaType %||% "all",
      input$spcaGroup1 %||% "all",
      input$spcaGroup2 %||% "all",
      input$spca_ncomp %||% 2,
      input$spca_keepX_pc1 %||% 50,
      input$spca_keepX_pc2 %||% 50,
      input$spcaScale %||% TRUE,
      input$spcaCenter %||% TRUE,
      grouping_level,
      digest::digest(values$normalized_data, algo = "xxhash64"),
      sep = "_"
    )
    
    # Check if we have cached results
    if (!is.null(values$spca_cache[[cache_key]])) {
      cat("Using cached sPCA results\n")
      cached_result <- values$spca_cache[[cache_key]]
      
      # Restore cached values
      values$spca_result <- cached_result$spca_result
      values$spca_data <- cached_result$spca_data
      
      showNotification("sPCA loaded from cache", type = "message", duration = 2)
      return()
    }
    
    # Add some debugging  cat("sPCA observer triggered\n")
    cat("Number of components:", input$spca_ncomp %||% 2, "\n")
    cat("keepX PC1:", input$spca_keepX_pc1 %||% 50, "\n")
    cat("keepX PC2:", input$spca_keepX_pc2 %||% 50, "\n")
    
    tryCatch({
      prepared <- spca_prepared_data()
      
      cat("Data dimensions:", nrow(prepared$data), "x", ncol(prepared$data), "\n")
      cat("Number of groups:", length(unique(prepared$groups)), "\n")
      
      # Check if mixOmics is available
      if (!requireNamespace("mixOmics", quietly = TRUE)) {
        showNotification("mixOmics package is required for sPCA analysis. Installing...", type = "warning")
        # Try to install mixOmics from Bioconductor
        if (!requireNamespace("BiocManager", quietly = TRUE)) {
          install.packages("BiocManager")
        }
        BiocManager::install("mixOmics")
        
        if (!requireNamespace("mixOmics", quietly = TRUE)) {
          showNotification("Failed to install mixOmics package", type = "error")
          return()
        }
      }    # Prepare keepX parameter (number of variables to keep for each component)
      keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
      if ((input$spca_ncomp %||% 2) > 2) {
        # For additional components, use the average of PC1 and PC2 settings
        avg_keepX <- round(mean(c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)))
        keepX_values <- c(keepX_values, rep(avg_keepX, (input$spca_ncomp %||% 2) - 2))
      }
      
      # Ensure keepX doesn't exceed number of features
      max_features <- ncol(prepared$data)
      keepX_values <- pmin(keepX_values, max_features)
      
      cat("keepX values:", paste(keepX_values, collapse = ", "), "\n")
      cat("Max features:", max_features, "\n")
      # Perform sPCA with error handling for missing values
      cat("Running mixOmics::spca...\n")
      tryCatch({
        spca_result <- mixOmics::spca(
          X = prepared$data,
          ncomp = input$spca_ncomp %||% 2,
          keepX = keepX_values,
          scale = input$spcaScale %||% TRUE,
          center = input$spcaCenter %||% TRUE
        )
      }, error = function(e) {
        showNotification(paste("sPCA analysis failed:", e$message, ". Consider improving data preprocessing in the Missing Value Handling step."), type = "error")
        return()
      })
      
      cat("sPCA completed successfully\n")
      
      # Store results
      values$spca_result <- spca_result
      values$spca_data <- prepared
      
      # Cache the sPCA results
      values$spca_cache[[cache_key]] <- list(
        spca_result = spca_result,
        spca_data = prepared
      )
      
      # Limit cache size to prevent memory issues (keep last 10 results)
      if (length(values$spca_cache) > 10) {
        values$spca_cache <- values$spca_cache[-(1:(length(values$spca_cache) - 10))]
      }
      
      cat("sPCA results cached with key:", cache_key, "\n")
      showNotification("sPCA analysis completed successfully!", type = "message")
      
    }, error = function(e) {
      cat("Error in sPCA analysis:", e$message, "\n")
      showNotification(paste("Error in sPCA analysis:", e$message), type = "error")
      values$spca_result <- NULL
      values$spca_data <- NULL
    })
  })
  
  # Trigger sPCA computation when switching to Dimensionality Reduction tab if not yet computed
  observeEvent(input$current_tab, {
    if (identical(input$current_tab, "Dimensionality Reduction")) {
      # Check if sPCA computation is needed (All Groups mode and no result yet)
      if (identical(input$spcaType, "all") && 
          is.null(values$spca_result) &&
          !is.null(values$normalized_data) &&
          !is.null(values$unique_groups) &&
          !is.null(values$group_column_indices)) {
        # Trigger the main sPCA observer by invalidating cache
        values$spca_cache <- list()
      }
    }
  })
  
  # sPCA Plot
  output$spcaPlot <- renderPlot({ 
    # Get font sizes from inputs or use defaults
    title_size <- if(!is.null(input$spca_title_size)) input$spca_title_size else 14
    axis_title_size <- if(!is.null(input$spca_axis_title_size)) input$spca_axis_title_size else 12
    axis_text_size <- if(!is.null(input$spca_axis_text_size)) input$spca_axis_text_size else 10
    legend_text_size <- if(!is.null(input$spca_legend_text_size)) input$spca_legend_text_size else 12
    
    if ((input$spcaType %||% "all") == "pairwise") {
      # Generate grid of pairwise sPCA plots - only for comparisons in current_pairwise_combinations
      req(values$normalized_data, values$unique_groups, values$group_column_indices)
      req(length(values$unique_groups) >= 2)

      cat("Rendering sPCA pairwise plots\n")

      # Use active-level pairwise combinations (mirrors Differential Analysis behavior)
      active_pairwise <- get_active_pairwise_combinations()
      if (is.null(active_pairwise) || nrow(active_pairwise) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No pairwise comparisons available for sPCA. Please configure comparisons in the Statistical Analysis tab.",
                          size = 5) +
                 theme_void())
      }

      pairwise_plots <- list()

      # De-duplicate pairwise combinations while preserving order
      combos_df <- active_pairwise
      if (!is.null(combos_df) && nrow(combos_df) > 1) {
        combo_keys <- apply(combos_df[, c("Group_1", "Group_2"), drop = FALSE], 1, function(row) {
          groups <- sort(c(as.character(row["Group_1"]), as.character(row["Group_2"])))
          paste(groups[1], groups[2], sep = "__")
        })
        combos_df <- combos_df[!duplicated(combo_keys), , drop = FALSE]
      }

      # Convert the pairwise combinations data frame to a list format
      group_combinations <- lapply(1:nrow(combos_df), function(i) {
        c(combos_df[i, "Group_1"],
          combos_df[i, "Group_2"])
      })

      for (combo_idx in seq_along(group_combinations)) {
        group1 <- group_combinations[[combo_idx]][1]
        group2 <- group_combinations[[combo_idx]][2]

        # Find indices for these groups
        group1_idx <- which(values$unique_groups == group1)
        group2_idx <- which(values$unique_groups == group2)

        if (length(group1_idx) == 0 || length(group2_idx) == 0) next

        # Get indices for the two groups being compared
        group1_cols <- values$group_column_indices[[group1_idx]]
        group2_cols <- values$group_column_indices[[group2_idx]]
          # Preserve original data order among selected columns
          selected_cols <- sort(c(group1_cols, group2_cols))
          
          # Skip if too few samples
          if (length(selected_cols) < 3) next
          
          # Get data for this comparison
          spca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
          # Map each selected column to its originating group
          groups_subset <- vapply(selected_cols, function(ci) {
            if (ci %in% group1_cols) group1 else group2
          }, character(1))
          # Run sPCA
          tryCatch({
            # Prepare keepX values
            keepX_values <- c(input$spca_keepX_pc1 %||% 50,
                              input$spca_keepX_pc2 %||% 50)
            max_features <- ncol(spca_data_subset)
            keepX_values <- pmin(keepX_values, max_features)
            # Perform sPCA
            pairwise_spca <- mixOmics::spca(
              X = spca_data_subset,
              ncomp = 2,
              keepX = keepX_values,
              scale = input$spcaScale %||% TRUE,
              center = input$spcaCenter %||% TRUE
            )
            
            # Create sPCA plot for this pair
            comp1 <- pairwise_spca$variates$X[, 1]
            comp2 <- pairwise_spca$variates$X[, 2]
            
            # Use corrected column names for labels
            original_sample_names <- rownames(spca_data_subset)
            cleaned_sample_names <- get_corrected_column_names(original_sample_names)
            
            plot_data <- data.frame(
              PC1 = comp1,
              PC2 = comp2,
              Group = groups_subset,
              Sample = cleaned_sample_names
            )
            group_levels <- get_group_order_for_plot(c(group1, group2))
            plot_data$Group <- factor(plot_data$Group, levels = group_levels)
            
            # Calculate variance explained
            var_exp <- pairwise_spca$prop_expl_var$X
            pc1_var <- round(var_exp[1] * 100, 1)
            pc2_var <- round(var_exp[2] * 100, 1)
            # Create plot with consistent styling
            if(input$spca_show_counts %||% FALSE) {
              counts <- table(plot_data$Group)
              new_labels <- paste0(names(counts), " (n=", counts, ")")
              ordered_levels <- levels(plot_data$Group)
              
              pair_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 2, alpha = 0.8) +
                labs(
                  title = paste(group1, "vs", group2),
                  x = paste0("PC1 (", pc1_var, "%)"),
                  y = paste0("PC2 (", pc2_var, "%)")
                )
              
              # Apply custom colors if enabled
              custom_colors <- get_spca_colors()
              if (!is.null(custom_colors)) {
                pairwise_colors <- custom_colors[ordered_levels]
                pair_plot <- pair_plot +
                  scale_color_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
                  scale_fill_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
              } else {
                pair_plot <- pair_plot +
                  scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels) +
                  scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels, labels = new_labels)
              }
              
              pair_plot <- pair_plot +
                ggprism::theme_prism(base_size = 10) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.5),
                  axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
                  axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = legend_text_size, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
                  panel.border = element_rect(color = "black", fill = NA, size = 0.5),
                  legend.position = ifelse(input$spcaGridLegend %||% TRUE, "bottom", "none")
                )
            } else {
              ordered_levels <- levels(plot_data$Group)
              
              pair_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 2, alpha = 0.8) +
                labs(
                  title = paste(group1, "vs", group2),
                  x = paste0("PC1 (", pc1_var, "%)"),
                  y = paste0("PC2 (", pc2_var, "%)")
                )
              
              # Apply custom colors if enabled
              custom_colors <- get_spca_colors()
              if (!is.null(custom_colors)) {
                pairwise_colors <- custom_colors[ordered_levels]
                pair_plot <- pair_plot +
                  scale_color_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels) +
                  scale_fill_manual(name = NULL, values = pairwise_colors, breaks = ordered_levels, limits = ordered_levels)
              } else {
                pair_plot <- pair_plot +
                  scale_color_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels) +
                  scale_fill_discrete(name = NULL, breaks = ordered_levels, limits = ordered_levels)
              }
              
              pair_plot <- pair_plot +
                ggprism::theme_prism(base_size = 10) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.5),
                  axis.text = element_text(size = axis_text_size, face = "bold", color = "black"),
                  axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = legend_text_size, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = title_size),
                  panel.border = element_rect(color = "black", fill = NA, size = 0.5),
                  legend.position = ifelse(input$spcaGridLegend %||% TRUE, "bottom", "none")
                )
            }
            # Add sample labels if requested
            if (input$spca_show_labels %||% FALSE) {
              pair_plot <- pair_plot + geom_text(aes(label = Sample),
                                                 vjust = -0.5,
                                                 size = 2.5,
                                                 check_overlap = TRUE,
                                                 fontface = "bold")
            }
            
            # Add ellipses if requested
            if (input$spca_add_ellipses %||% FALSE) {
              pair_plot <- pair_plot + stat_ellipse(
                aes(fill = Group),
                geom = "polygon",
                alpha = 0.2,
                level = input$spca_ellipse_level %||% 0.95,
                show.legend = FALSE
              )
            }
            
            pairwise_plots[[length(pairwise_plots) + 1]] <- pair_plot
            
          }, error = function(e) {
            cat("Error in sPCA for", group1, "vs", group2, ":", e$message, "\n")
          })
        }

      if (length(pairwise_plots) == 0) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "No valid pairwise comparisons available for sPCA",
                          size = 6) +
                 theme_void())
      }
      
      # Arrange plots in grid
      grid_cols <- input$spcaGridCols %||% 2
      grid_plot <- patchwork::wrap_plots(pairwise_plots, ncol = grid_cols)
      
      # Store the grid plot for download
      values$spca_grid_obj <- grid_plot
      values$spca_grid_count <- length(pairwise_plots)
      
      # Clear hover data for grid mode (hover not supported on patchwork grids)
      values$spca_hover_data <- NULL
      
      return(grid_plot)
      
    } else {
      # Use reactive visualization for single plot
      p <- spca_plot_reactive()
      
      # Store the plot
      values$spca_plot_obj <- p
      
      return(p)
    }
  },
  width = function() {  if ((input$spcaType %||% "all") == "pairwise") {
    grid_cols <- input$spcaGridCols %||% 2
    grid_width <- input$spcaGridWidth %||% 400
    grid_cols * grid_width
  } else {
    input$spcaAllWidth %||% 500
  }
  },
  height = function() {
    if ((input$spcaType %||% "all") == "pairwise") {
      # Calculate grid height
      n_groups <- length(values$unique_groups) %||% 0
      n_plots <- if (!is.null(values$spca_grid_count)) values$spca_grid_count else if (n_groups < 2) 0 else n_groups * (n_groups - 1) / 2
      grid_cols <- input$spcaGridCols %||% 2
      n_rows <- ceiling(n_plots / grid_cols)
      grid_height <- input$spcaGridHeight %||% 400
      max(300, n_rows * grid_height)
    } else {
      input$spcaAllHeight %||% 500
    }
  })
  
  # Prevent state tracking conflicts for sPCA plot
  outputOptions(output, "spcaPlot", suspendWhenHidden = TRUE)
  
  # sPCA hover tooltip - shows sample name when hovering over a point
  output$spcaPlot_tooltip <- renderUI({
    hover <- input$spcaPlot_hover
    if (is.null(hover) || is.null(values$spca_hover_data)) return(NULL)
    
    point <- nearPoints(values$spca_hover_data, hover, xvar = "PC1", yvar = "PC2",
                        threshold = 10, maxpoints = 1)
    if (nrow(point) == 0) return(NULL)
    
    left_px <- hover$coords_css$x
    top_px <- hover$coords_css$y
    
    div(
      style = paste0(
        "position: absolute; z-index: 100; pointer-events: none; ",
        "background: rgba(0,0,0,0.8); color: white; padding: 6px 10px; ",
        "border-radius: 4px; font-size: 12px; font-weight: bold; ",
        "left: ", left_px + 12, "px; top: ", top_px + 12, "px;"
      ),
      tags$span(point$Sample[1]),
      tags$br(),
      tags$span(style = "font-weight: normal; font-size: 11px; color: #ccc;",
                paste0("Group: ", point$Group[1]))
    )
  })
  
  # sPCA click-to-label: toggle persistent sample labels on the plot
  observeEvent(input$spcaPlot_click, {
    click <- input$spcaPlot_click
    if (is.null(click) || is.null(values$spca_hover_data)) return()
    
    point <- nearPoints(values$spca_hover_data, click, xvar = "PC1", yvar = "PC2",
                        threshold = 10, maxpoints = 1)
    if (nrow(point) == 0) return()
    
    sample_name <- point$Sample[1]
    current <- values$spca_clicked_samples %||% character(0)
    
    if (sample_name %in% current) {
      values$spca_clicked_samples <- setdiff(current, sample_name)
    } else {
      values$spca_clicked_samples <- c(current, sample_name)
    }
  })
  
  # Clear all sPCA clicked labels
  observeEvent(input$clearSPCALabelsBtn, {
    values$spca_clicked_samples <- character(0)
  })
  
  # sPCA Variance Explained Plot
  output$spcaVariancePlot <- renderPlot({ 
    p <- spca_variance_plot_reactive()
    
    # Store the plot object for downloads
    values$spca_variance_plot_obj <- p
    
    return(p)
  })
  
  # Prevent state tracking conflicts for sPCA variance plot
  outputOptions(output, "spcaVariancePlot", suspendWhenHidden = TRUE)
  
  # sPCA Loadings Plot
  output$spcaLoadingsPlot <- renderPlot({ 
    p <- spca_loadings_plot_reactive()
    
    # Store the plot object for downloads
    values$spca_loadings_plot_obj <- p
    
    return(p)
  })
  
  # Prevent state tracking conflicts for sPCA loadings plot
  outputOptions(output, "spcaLoadingsPlot", suspendWhenHidden = TRUE)
  
  # sPCA Selected Variables Table
  output$spcaSelectedVariables <- DT::renderDataTable({
    # Use context-aware sPCA result/data for consistency
    res <- spca_result_for_current_context()
    req(res)
    values$spca_result <- res$spca_result
    values$spca_data <- res$spca_data
    
    tryCatch({
      # Get loadings matrix and names first
      loadings_matrix <- values$spca_result$loadings$X
      loadings_names <- rownames(loadings_matrix)
      
      # CRITICAL: Build robust feature names mapping from loadings names
      # loadings_names are from transposed data and should map to cleaned_molecules
      mapped_feature_names <- character(length(loadings_names))
      
      for (i in seq_along(loadings_names)) {
        name <- loadings_names[i]
        
        # Strategy 1: Direct match in cleaned_molecules
        if (!is.null(values$cleaned_molecules)) {
          match_idx <- match(name, values$cleaned_molecules)
          if (!is.na(match_idx)) {
            mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
            next
          }
        }
        
        # Strategy 2: Direct match in rownames(normalized_data)
        if (!is.null(rownames(values$normalized_data))) {
          match_idx <- match(name, rownames(values$normalized_data))
          if (!is.na(match_idx)) {
            mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
            next
          }
        }
        
        # Strategy 3: If name is numeric (X123 format), extract and map by index
        if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
          idx <- suppressWarnings(as.integer(substring(name, 2)))
          if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
            mapped_feature_names[i] <- values$cleaned_molecules[idx]
            next
          }
        }
        
        # Strategy 4: If name is just a number, map by index
        if (grepl("^\\d+$", name)) {
          idx <- suppressWarnings(as.integer(name))
          if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
            mapped_feature_names[i] <- values$cleaned_molecules[idx]
            next
          }
        }
        
        # Fallback: use original loadings name
        mapped_feature_names[i] <- name
      }
      
      original_feature_names <- mapped_feature_names
      
      # Create summary table of selected variables
      selected_vars <- list()
      
      for (i in 1:ncol(loadings_matrix)) {
        comp_name <- paste0("PC", i)
        non_zero_idx <- which(loadings_matrix[, i] != 0)
        if (length(non_zero_idx) > 0) {
          # Compute numeric Variable_IDs consistently across normal/transposed inputs
          # Start from full set of loadings rownames and then subset
          all_idx <- sapply(loadings_names, function(name) {
            if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
              suppressWarnings(as.integer(substring(name, 2)))
            } else if (!is.null(rownames(values$normalized_data))) {
              mi <- match(name, rownames(values$normalized_data))
              if (is.na(mi) && !is.null(values$cleaned_molecules)) {
                mi <- match(name, values$cleaned_molecules)
              }
              if (is.na(mi) && !is.null(values$spca_data) && !is.null(values$spca_data$feature_names)) {
                # Attempt match against the feature names used in this sPCA
                mi <- match(name, values$spca_data$feature_names)
              }
              mi
            } else {
              NA_integer_
            }
          })
          # Fallback: any remaining NA become their position index
          if (anyNA(all_idx)) {
            fallback <- seq_along(loadings_names)
            na_pos <- which(is.na(all_idx))
            all_idx[na_pos] <- fallback[na_pos]
          }
          clean_variable_ids <- as.character(all_idx[non_zero_idx])
          
          # Handle feature names: prefer actual feature names; fallback to clean variable IDs only if missing
          if (length(original_feature_names) == length(loadings_names)) {
            feature_names <- original_feature_names[non_zero_idx]
            # If missing/empty, fallback to numeric IDs; otherwise keep the provided name (even if numeric)
            feature_names <- ifelse(is.na(feature_names) | feature_names == "",
                                    clean_variable_ids,
                                    feature_names)
          } else {
            # Fallback: use clean numeric IDs as feature names
            feature_names <- clean_variable_ids
          }
          
          var_data <- data.frame(
            Component = comp_name,
            Variable_ID = clean_variable_ids,
            Feature = feature_names,
            Loading = loadings_matrix[non_zero_idx, i],
            AbsLoading = abs(loadings_matrix[non_zero_idx, i])
          )
          var_data <- var_data[order(var_data$AbsLoading, decreasing = TRUE), ]
          selected_vars[[comp_name]] <- var_data
        }
      }
      
      # Combine all selected variables
      if (length(selected_vars) > 0) {
        all_selected <- do.call(rbind, selected_vars)
        rownames(all_selected) <- NULL
        DT::datatable(
          all_selected,
          options = list(
            pageLength = 15,
            scrollX = TRUE,
            order = list(list(4, 'desc')) # Order by absolute loading (now column 5, 0-indexed is 4)
          ),
          caption = "Variables selected by sPCA (non-zero loadings)",
          rownames = FALSE  # Remove row names to avoid S/N column
        ) %>%
          DT::formatRound(columns = c("Loading", "AbsLoading"), digits = 4)
      } else {      # Return empty table if no variables selected
        empty_table <- data.frame(
          Component = character(0),
          Variable_ID = character(0),
          Feature = character(0),
          Loading = numeric(0),
          AbsLoading = numeric(0)
        )
        DT::datatable(empty_table, caption = "No variables selected", rownames = FALSE)
      }
      
    }, error = function(e) {
      # Return error table
      error_table <- data.frame(Error = paste("Error creating table:", e$message))
      DT::datatable(error_table)
    })
  })
  
  # sPCA Results Table
  output$spcaResultsTable <- DT::renderDataTable({
    # Use context-aware sPCA result/data for both modes
    res <- spca_result_for_current_context()
    req(res)
    spca_result <- res$spca_result
    spca_data <- res$spca_data
    tryCatch({
      # Get corrected sample names and align to the number of score rows
      original_sample_names <- spca_data$sample_names
      cleaned_sample_names <- get_corrected_column_names(original_sample_names)
      pc_scores <- spca_result$variates$X
      n_rows <- nrow(pc_scores)
      min_length <- min(length(cleaned_sample_names), n_rows)
      
      # Create summary results table without Group column
      results_data <- data.frame(
        Sample = cleaned_sample_names[seq_len(min_length)],
        PC1 = pc_scores[seq_len(min_length), 1],
        PC2 = pc_scores[seq_len(min_length), 2]
      )
      
      # Add additional components if they exist
      if (ncol(pc_scores) > 2) {
        for (i in 3:ncol(pc_scores)) {
          results_data[[paste0("PC", i)]] <- pc_scores[seq_len(min_length), i]
        }
      }
      
      DT::datatable(
        results_data,
        options = list(
          pageLength = 15,
          scrollX = TRUE
        ),
        caption = "sPCA Analysis Results - Sample Coordinates",
        rownames = FALSE  # Remove row names to avoid extra columns
      ) %>%
        DT::formatRound(columns = grep("PC", names(results_data)), digits = 4)
      
    }, error = function(e) {
      error_table <- data.frame(Error = paste("Error creating results table:", e$message))
      DT::datatable(error_table)
    })
  })
  
  # Download sPCA Plot
  output$downloadSPCABtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      active_tab <- input$spcaTabset
      if (is.null(active_tab) || active_tab == "spcaPlotTab") {
        if ((input$spcaType %||% "all") == "pairwise" && !is.null(input$spcaGroup1) && !is.null(input$spcaGroup2)) {
          paste0(input$spcaGroup1, "_vs_", input$spcaGroup2, "_sPCA_",
                 format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
        } else {
          paste0("sPCA_plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
        }
      } else if (active_tab == "spcaLoadingsTab") {
        paste0("sPCA_loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else if (active_tab == "spcaVarianceTab") {
        paste0("sPCA_variance_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      } else {
        paste0("sPCA_plot_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
      }
    },
    content = function(file) {
      tryCatch({
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        active_tab <- input$spcaTabset
        if (is.null(active_tab) || active_tab == "spcaPlotTab") {
          if ((input$spcaType %||% "all") == "pairwise") {
            # Check if specific groups are selected for single plot download
            if (!is.null(input$spcaGroup1) && !is.null(input$spcaGroup2) &&
                input$spcaGroup1 != input$spcaGroup2) {
              # Generate single pairwise plot for selected groups for download
              req(values$normalized_data, values$unique_groups, values$group_column_indices)
              
              group1_idx <- which(values$unique_groups == input$spcaGroup1)
              group2_idx <- which(values$unique_groups == input$spcaGroup2)
              
              group1_cols <- values$group_column_indices[[group1_idx]]
              group2_cols <- values$group_column_indices[[group2_idx]]
              # Preserve original data order among selected columns
              selected_cols <- sort(c(group1_cols, group2_cols))
              
              if (length(selected_cols) >= 3) {
                spca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
                # Map each selected column to its originating group
                groups_subset <- vapply(selected_cols, function(ci) {
                  if (ci %in% group1_cols) input$spcaGroup1 else input$spcaGroup2
                }, character(1))
                # Prepare keepX values
                keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
                max_features <- ncol(spca_data_subset)
                keepX_values <- pmin(keepX_values, max_features)
                # Perform sPCA
                pairwise_spca <- mixOmics::spca(
                  X = spca_data_subset,
                  ncomp = 2,
                  keepX = keepX_values,
                  scale = input$spcaScale %||% TRUE,
                  center = input$spcaCenter %||% TRUE
                )
                # Create sPCA plot for this pair
                comp1 <- pairwise_spca$variates$X[, 1]
                comp2 <- pairwise_spca$variates$X[, 2]
                
                # Use corrected sample names for labels
                original_sample_names <- rownames(spca_data_subset)
                cleaned_sample_names <- get_corrected_column_names(original_sample_names)
                
                plot_data <- data.frame(
                  PC1 = comp1,
                  PC2 = comp2,
                  Group = groups_subset,
                  Sample = cleaned_sample_names
                )
                
                # Calculate variance explained
                var_exp <- pairwise_spca$prop_expl_var$X
                pc1_var <- round(var_exp[1] * 100, 1)
                pc2_var <- round(var_exp[2] * 100, 1)
                # Create base plot with sample counts if requested
                if(input$spca_show_counts %||% FALSE) {
                  counts <- table(plot_data$Group)
                  new_labels <- paste0(names(counts), " (n=", counts, ")")
                  single_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
                    geom_point(size = 3, alpha = 0.8) +
                    labs(
                      title = paste(input$spcaGroup1, "vs", input$spcaGroup2),
                      subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
                      x = paste0("PC1 (", pc1_var, "%)"),
                      y = paste0("PC2 (", pc2_var, "%)")
                    )
                  
                  # Apply custom colors if enabled
                  custom_colors <- get_spca_colors()
                  if (!is.null(custom_colors)) {
                    pairwise_colors <- custom_colors[names(custom_colors) %in% unique(plot_data$Group)]
                    single_plot <- single_plot +
                      scale_color_manual(name = NULL, values = pairwise_colors, labels = new_labels) +
                      scale_fill_manual(name = NULL, values = pairwise_colors, labels = new_labels)
                  } else {
                    single_plot <- single_plot +
                      scale_color_discrete(name = NULL, labels = new_labels) +
                      scale_fill_discrete(name = NULL, labels = new_labels)
                  }
                  
                  single_plot <- single_plot +
                    ggprism::theme_prism(base_size = 14) +
                    theme(
                      panel.grid = element_blank(),
                      axis.line = element_line(color = "black", size = 0.8),
                      axis.text = element_text(size = 14, face = "bold", color = "black"),
                      axis.title = element_text(size = 14, face = "bold", color = "black"),
                      axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                      legend.text = element_text(size = 12, face = "bold"),
                      legend.title = element_blank(),
                      plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                      plot.subtitle = element_text(face = "bold"),
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      legend.position = "bottom"
                    )
                } else {
                  single_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
                    geom_point(size = 3, alpha = 0.8) +
                    labs(
                      title = paste(input$spcaGroup1, "vs", input$spcaGroup2),
                      subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
                      x = paste0("PC1 (", pc1_var, "%)"),
                      y = paste0("PC2 (", pc2_var, "%)")
                    )
                  
                  # Apply custom colors if enabled
                  custom_colors <- get_spca_colors()
                  if (!is.null(custom_colors)) {
                    pairwise_colors <- custom_colors[names(custom_colors) %in% unique(plot_data$Group)]
                    single_plot <- single_plot +
                      scale_color_manual(name = NULL, values = pairwise_colors) +
                      scale_fill_manual(name = NULL, values = pairwise_colors)
                  } else {
                    single_plot <- single_plot +
                      scale_color_discrete(name = NULL) +
                      scale_fill_discrete(name = NULL)
                  }
                  
                  single_plot <- single_plot +
                    ggprism::theme_prism(base_size = 14) +
                    theme(
                      panel.grid = element_blank(),
                      axis.line = element_line(color = "black", size = 0.8),
                      axis.text = element_text(size = 14, face = "bold", color = "black"),
                      axis.title = element_text(size = 14, face = "bold", color = "black"),
                      axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                      legend.text = element_text(size = 12, face = "bold"),
                      legend.title = element_blank(),
                      plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                      plot.subtitle = element_text(face = "bold"),
                      panel.border = element_rect(color = "black", fill = NA, size = 1),
                      legend.position = "bottom"
                    )
                }
                # Add sample labels if requested
                if (input$spca_show_labels %||% FALSE) {
                  single_plot <- single_plot + geom_text(aes(label = Sample),
                                                         vjust = -0.5,
                                                         size = 3,
                                                         check_overlap = TRUE,
                                                         fontface = "bold")
                }
                
                # Add ellipses if requested
                if (input$spca_add_ellipses %||% FALSE) {
                  single_plot <- single_plot + stat_ellipse(
                    aes(fill = Group),
                    geom = "polygon",
                    alpha = 0.2,
                    level = input$spca_ellipse_level %||% 0.95,
                    show.legend = FALSE
                  )
                }
                
                ggsave(file,
                       plot = single_plot,
                       width = max(6, (input$spca_width %||% 600) / 100),
                       height = max(6, (input$spca_height %||% 600) / 100),
                       dpi = dpi,
                       device = resolve_ggsave_device(format),
                       units = "in")
              }
            } else {
              # Download the grid plot if no specific groups selected
              req(values$spca_grid_obj)
              
              # Calculate grid dimensions
              n_groups <- length(values$unique_groups) %||% 0
              n_plots <- if (n_groups < 2) 0 else n_groups * (n_groups - 1) / 2
              grid_cols <- input$spcaGridCols %||% 2
              n_rows <- ceiling(n_plots / grid_cols)
              
              ggsave(file,
                     plot = values$spca_grid_obj,
                     width = (input$spcaGridWidth %||% 400) * grid_cols / 100,
                     height = (input$spcaGridHeight %||% 400) * n_rows / 100,
                     dpi = dpi,
                     device = resolve_ggsave_device(format),
                     units = "in")
            }
          } else {          # Single plot mode - use the on-screen plot to ensure parity and avoid build errors
            req(values$spca_plot_obj)
            ggsave(file,
                   plot = values$spca_plot_obj,
                   width = max(6, (input$spca_width %||% 600) / 100),
                   height = max(6, (input$spca_height %||% 600) / 100),
                   dpi = dpi,
                   device = resolve_ggsave_device(format),
                   units = "in")
          }
        } else if (active_tab == "spcaLoadingsTab") {
          req(values$spca_loadings_plot_obj)
          ggsave(file, plot = values$spca_loadings_plot_obj,
                 width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(format), units = "in")
        } else if (active_tab == "spcaVarianceTab") {
          req(values$spca_variance_plot_obj)
          ggsave(file, plot = values$spca_variance_plot_obj,
                 width = 10, height = 6, dpi = dpi, device = resolve_ggsave_device(format), units = "in")
        }
        
        showNotification("sPCA plot downloaded successfully!", type = "message")
        
      }, error = function(e) {
        showNotification(paste("Error downloading sPCA plot:", e$message), type = "error")
      })
    }
  )
  
  # Individual download handlers for sPCA Variance and Loadings plots
  output$downloadSPCAVarianceBtn <- downloadHandler(
    filename = function() {
      format <- input$global_format %||% "png"
      paste0("sPCA_Variance_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$spca_variance_plot_obj)
      format <- input$global_format %||% "png"
      dpi <- input$global_dpi %||% 300
      ggsave(file, plot = values$spca_variance_plot_obj, width = 10, height = 6, dpi = dpi,
             device = resolve_ggsave_device(format), units = "in")
      showNotification("Variance plot downloaded!", type = "message")
    }
  )
  
  output$downloadSPCALoadingsPlotBtn <- downloadHandler(
    filename = function() {
      format <- input$global_format %||% "png"
      paste0("sPCA_Loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      req(values$spca_loadings_plot_obj)
      format <- input$global_format %||% "png"
      dpi <- input$global_dpi %||% 300
      ggsave(file, plot = values$spca_loadings_plot_obj, width = 10, height = 8, dpi = dpi,
             device = resolve_ggsave_device(format), units = "in")
      showNotification("Loadings plot downloaded!", type = "message")
    }
  )
  
  # Download sPCA Loadings
  output$downloadSPCALoadingsBtn <- downloadHandler(
    filename = function() {
      paste0("sPCA_loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(values$spca_result, values$spca_data)
      
      tryCatch({
        # Get loadings matrix
        loadings_matrix <- values$spca_result$loadings$X
        
        # Get original feature names using same logic as GUI
        loadings_names <- rownames(loadings_matrix)
        original_feature_names <- values$spca_data$feature_names
        
        # If spca_data feature names are not available or don't match, use cleaned_molecules
        if (is.null(original_feature_names) || length(original_feature_names) != length(loadings_names)) {
          original_feature_names <- values$cleaned_molecules
        }
        
        # If lengths still don't match, create a mapping based on the loadings row names
        if (length(original_feature_names) != length(loadings_names)) {
          # Extract indices from loadings names if they're in X123 format
          feature_indices <- sapply(loadings_names, function(name) {
            if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
              as.numeric(substring(name, 2))
            } else {
              match(name, rownames(values$normalized_data))
            }
          })
          
          # Get corresponding feature names
          valid_indices <- !is.na(feature_indices) & feature_indices <= length(values$cleaned_molecules)
          mapped_names <- rep(NA, length(loadings_names))
          mapped_names[valid_indices] <- values$cleaned_molecules[feature_indices[valid_indices]]
          
          # Use the mapped names where available, otherwise use loadings names
          original_feature_names <- ifelse(is.na(mapped_names), loadings_names, mapped_names)
        }
        
        # Create comprehensive loadings table
        loadings_df <- data.frame(
          Variable_ID = loadings_names,
          Feature = original_feature_names,
          loadings_matrix,
          stringsAsFactors = FALSE
        )
        
        # Add selected status for each component
        for (i in 1:ncol(loadings_matrix)) {
          comp_name <- paste0("PC", i, "_Selected")
          loadings_df[[comp_name]] <- loadings_matrix[, i] != 0
        }
        
        write.csv(loadings_df, file, row.names = FALSE)
        showNotification("sPCA loadings downloaded successfully!", type = "message")
        
      }, error = function(e) {
        showNotification(paste("Error downloading sPCA loadings:", e$message), type = "error")
      })
    }
  )
  
  # Generate all sPCA plots
  observeEvent(input$generateAllSPCABtn, {
    req(values$normalized_data, values$unique_groups, values$group_column_indices)
    
    # Create directory for sPCA plots
    dir.create("sPCA_Plots", showWarnings = FALSE)
    
    # Progress bar
    progress <- shiny::Progress$new()
    on.exit(progress$close())
    
    # Set dpi
    dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
    
    # Calculate total number of plots (all groups + pairwise comparisons)
    n_groups <- length(values$unique_groups)
    n_pairs <- n_groups * (n_groups - 1) / 2
    total_plots <- n_pairs * 2 + 5  # All groups (main plot, variance, loadings plot, loadings CSV, results CSV) + pairwise comparisons (score plot + loadings plot each)
    
    plot_count <- 0
    progress$set(message = "Generating all sPCA plots", value = 0)
    
    tryCatch({
      # ==================== ALL GROUPS sPCA ====================
      progress$set(value = plot_count / total_plots, detail = "Creating all groups sPCA plot")
      
      # Run sPCA on all groups data
      all_groups_spca_data <- t(values$normalized_data)
      all_groups_groups <- create_proper_group_labels(values$unique_groups, values$group_column_indices)
      
      # Prepare keepX values
      keepX_values <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
      max_features <- ncol(all_groups_spca_data)
      keepX_values <- pmin(keepX_values, max_features)
      
      # Perform sPCA
      all_groups_spca <- mixOmics::spca(
        X = all_groups_spca_data,
        ncomp = 2,
        keepX = keepX_values,
        scale = input$spcaScale %||% TRUE,
        center = input$spcaCenter %||% TRUE
      )
      
      # Extract components
      comp1 <- all_groups_spca$variates$X[, 1]
      comp2 <- all_groups_spca$variates$X[, 2]
      
      # Use corrected sample names
      original_sample_names <- rownames(all_groups_spca_data)
      cleaned_sample_names <- get_corrected_column_names(original_sample_names)
      
      plot_data <- data.frame(
        PC1 = comp1,
        PC2 = comp2,
        Group = all_groups_groups,
        Sample = cleaned_sample_names
      )
      
      # Calculate variance explained
      var_exp <- all_groups_spca$prop_expl_var$X
      pc1_var <- round(var_exp[1] * 100, 1)
      pc2_var <- round(var_exp[2] * 100, 1)
      
      # Create main sPCA plot
      if (input$spca_show_counts %||% TRUE) {
        counts <- table(plot_data$Group)
        new_labels <- paste0(names(counts), " (n=", counts, ")")
        
        main_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(
            title = "Sparse PCA (sPCA) Analysis",
            subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
            x = paste0("PC1 (", pc1_var, "%)"),
            y = paste0("PC2 (", pc2_var, "%)")
          ) +
          scale_color_discrete(name = NULL, labels = new_labels) +
          scale_fill_discrete(name = NULL, labels = new_labels) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = 14, face = "bold", color = "black"),
            axis.title = element_text(size = 14, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = 12, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
            plot.subtitle = element_text(face = "bold"),
            strip.text = element_text(face = "bold"),
            text = element_text(face = "bold"),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = "bottom"
          )
      } else {
        main_plot <- ggplot(plot_data, aes(x = PC1, y = PC2, color = Group)) +
          geom_point(size = 3, alpha = 0.8) +
          labs(
            title = "Sparse PCA (sPCA) Analysis",
            subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
            x = paste0("PC1 (", pc1_var, "%)"),
            y = paste0("PC2 (", pc2_var, "%)")
          ) +
          scale_color_discrete(name = NULL) +
          scale_fill_discrete(name = NULL) +
          ggprism::theme_prism(base_size = 14) +
          theme(
            panel.grid = element_blank(),
            axis.line = element_line(color = "black", size = 0.8),
            axis.text = element_text(size = 14, face = "bold", color = "black"),
            axis.title = element_text(size = 14, face = "bold", color = "black"),
            axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
            legend.text = element_text(size = 12, face = "bold"),
            legend.title = element_blank(),
            plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
            plot.subtitle = element_text(face = "bold"),
            strip.text = element_text(face = "bold"),
            text = element_text(face = "bold"),
            panel.border = element_rect(color = "black", fill = NA, size = 1),
            legend.position = "bottom"
          )
      }
      
      # Add confidence ellipses if requested
      if (input$spca_add_ellipses %||% FALSE) {
        main_plot <- main_plot + stat_ellipse(aes(fill = Group),
                                              level = input$spca_ellipse_level %||% 0.95,
                                              alpha = 0.2,
                                              geom = "polygon",
                                              show.legend = FALSE)
      }
      
      # Add sample labels if requested
      if (input$spca_show_labels %||% FALSE) {
        main_plot <- main_plot + geom_text(aes(label = Sample),
                                           vjust = -0.5,
                                           size = 3,
                                           check_overlap = TRUE,
                                           fontface = "bold")
      }
      
      ggsave("sPCA_Plots/All_Groups_sPCA_Scores.png", plot = main_plot,
             width = max(6, (input$spca_width %||% 600) / 100),
             height = max(6, (input$spca_height %||% 600) / 100),
             dpi = dpi, units = "in")
      plot_count <- plot_count + 1
      progress$set(value = plot_count / total_plots)
      
      # Save variance explained plot
      progress$set(value = plot_count / total_plots, detail = "Creating variance explained plot")
      
      var_data <- data.frame(
        Component = factor(paste0("PC", 1:length(var_exp)),
                           levels = paste0("PC", 1:length(var_exp))),
        Variance = var_exp * 100,
        Cumulative = cumsum(var_exp) * 100
      )
      
      variance_plot <- ggplot(var_data) +
        geom_col(aes(x = Component, y = Variance), fill = "#3498db", alpha = 0.8) +
        geom_line(aes(x = Component, y = Cumulative, group = 1),
                  color = "#e74c3c", size = 1.5) +
        geom_point(aes(x = Component, y = Cumulative),
                   color = "#e74c3c", size = 3) +
        scale_y_continuous(name = "Variance Explained (%)",
                           sec.axis = sec_axis(~., name = "Cumulative Variance (%)")) +
        ggprism::theme_prism() +
        labs(title = "sPCA Variance Explained",
             x = "Principal Component") +
        theme(
          axis.text.x = element_text(angle = 45, hjust = 1),
          plot.title = element_text(hjust = 0.5)
        )
      
      ggsave("sPCA_Plots/All_Groups_sPCA_Variance.png", plot = variance_plot,
             width = 10, height = 6, dpi = dpi, units = "in")
      plot_count <- plot_count + 1
      progress$set(value = plot_count / total_plots)
      
      # Save loadings plot
      progress$set(value = plot_count / total_plots, detail = "Creating loadings plot")
      
      tryCatch({
        # Extract loadings for PC1 and PC2
        loadings_pc1 <- all_groups_spca$loadings$X[, 1]
        loadings_pc2 <- all_groups_spca$loadings$X[, 2]
        
        # Get original feature names
        loadings_names <- rownames(all_groups_spca$loadings$X)
        
        # Use the same feature names that were used to create the sPCA data
        original_feature_names <- rownames(values$normalized_data)
        
        # If the lengths don't match (due to filtering), fall back to cleaned_molecules
        if (is.null(original_feature_names) || length(original_feature_names) != length(loadings_names)) {
          original_feature_names <- values$cleaned_molecules
        }
        
        # If lengths still don't match, create a mapping based on the loadings row names
        if (length(original_feature_names) != length(loadings_names)) {
          # Extract indices from loadings names if they're in X123 format
          feature_indices <- sapply(loadings_names, function(name) {
            if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
              as.numeric(substring(name, 2))
            } else {
              match(name, rownames(values$normalized_data))
            }
          })
          
          # Get corresponding feature names
          valid_indices <- !is.na(feature_indices) & feature_indices <= length(values$cleaned_molecules)
          mapped_names <- rep(NA, length(loadings_names))
          mapped_names[valid_indices] <- values$cleaned_molecules[feature_indices[valid_indices]]
          
          # Use the mapped names where available, otherwise use loadings names
          original_feature_names <- ifelse(is.na(mapped_names), loadings_names, mapped_names)
        }
        
        # Determine which labels to use based on toggle (same logic as GUI)
        use_feature_names <- isTRUE(input$spca_use_feature_names)
        
        if (use_feature_names && length(original_feature_names) == length(loadings_names)) {
          # Use original feature names
          names(loadings_pc1) <- original_feature_names
          names(loadings_pc2) <- original_feature_names
          x_label <- "Features"
        } else {
          # Use variable IDs (cleaned)
          clean_ids <- sapply(loadings_names, function(id) {
            if (startsWith(id, "X") && grepl("^X[0-9]+$", id)) {
              return(substring(id, 2))  # Remove the "X" prefix
            } else {
              return(id)  # Keep as is if not in X123 format
            }
          })
          names(loadings_pc1) <- clean_ids
          names(loadings_pc2) <- clean_ids
          x_label <- "Variables (ID)"
        }
        
        # Get selected variables (non-zero loadings)
        selected_pc1 <- loadings_pc1[loadings_pc1 != 0]
        selected_pc2 <- loadings_pc2[loadings_pc2 != 0]
        
        # Create data frames for plotting
        pc1_data <- data.frame(
          Variable = names(selected_pc1),
          Loading = selected_pc1,
          Component = "PC1"
        )
        
        pc2_data <- data.frame(
          Variable = names(selected_pc2),
          Loading = selected_pc2,
          Component = "PC2"
        )
        
        # Combine data
        loadings_data <- rbind(pc1_data, pc2_data)
        
        if (nrow(loadings_data) > 0) {
          # Create loadings plot with same styling as GUI
          loadings_plot <- ggplot(loadings_data, aes(x = reorder(Variable, abs(Loading)), y = Loading, fill = Component)) +
            geom_col(alpha = 0.8) +
            coord_flip() +
            facet_wrap(~Component, scales = "free_y") +
            labs(
              title = "sPCA Loadings for Selected Variables",
              subtitle = paste("PC1:", length(selected_pc1), "variables, PC2:", length(selected_pc2), "variables"),
              x = x_label,
              y = "Loading Value"
            ) +
            ggprism::theme_prism() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 12, hjust = 0.5),
              strip.text = element_text(size = 12, face = "bold"),
              axis.text = element_text(size = 10, face = "bold", color = "black"),
              axis.title = element_text(size = 12, face = "bold", color = "black"),
              legend.position = "none",
              panel.grid = element_blank(),
              axis.line = element_line(color = "black", size = 0.8)
            ) +
            scale_fill_manual(values = c("PC1" = "#3498db", "PC2" = "#e74c3c"))
          
          ggsave("sPCA_Plots/All_Groups_sPCA_Loadings.png", plot = loadings_plot,
                 width = 12, height = 8, dpi = dpi, units = "in")
        }
        
      }, error = function(e) {
        showNotification(paste("Error generating loadings plot:", e$message), type = "warning")
      })
      
      plot_count <- plot_count + 1
      progress$set(value = plot_count / total_plots)
      
      # Save loadings data as CSV
      progress$set(value = plot_count / total_plots, detail = "Saving loadings data")
      
      loadings_matrix <- all_groups_spca$loadings$X
      original_feature_names <- values$cleaned_molecules
      loadings_names <- rownames(loadings_matrix)
      
      # Use feature names with Variable_ID and Feature columns
      if (length(original_feature_names) == length(loadings_names)) {
        feature_names <- original_feature_names
      } else {
        feature_names <- loadings_names  # Fallback
      }
      # If feature names look like numeric indices, map them to cleaned_molecules when possible
      if (length(feature_names) == length(values$cleaned_molecules) && all(grepl("^\\d+$", feature_names))) {
        idx <- suppressWarnings(as.integer(feature_names))
        if (all(!is.na(idx)) && max(idx) <= length(values$cleaned_molecules)) {
          feature_names <- values$cleaned_molecules[idx]
        }
      }
      
      loadings_df <- data.frame(
        Variable_ID = loadings_names,
        Feature = feature_names,
        loadings_matrix,
        stringsAsFactors = FALSE
      )
      
      for (i in 1:ncol(loadings_matrix)) {
        comp_name <- paste0("PC", i, "_Selected")
        loadings_df[[comp_name]] <- loadings_matrix[, i] != 0
      }
      
      write.csv(loadings_df, "sPCA_Plots/All_Groups_sPCA_Loadings.csv", row.names = FALSE)
      plot_count <- plot_count + 1
      progress$set(value = plot_count / total_plots)
      
      # Save results table
      progress$set(value = plot_count / total_plots, detail = "Saving results table")
      
      results_data <- data.frame(
        Sample = cleaned_sample_names,
        Group = all_groups_groups,
        PC1 = all_groups_spca$variates$X[, 1],
        PC2 = all_groups_spca$variates$X[, 2]
      )
      
      if (ncol(all_groups_spca$variates$X) > 2) {
        for (i in 3:ncol(all_groups_spca$variates$X)) {
          results_data[[paste0("PC", i)]] <- all_groups_spca$variates$X[, i]
        }
      }
      
      write.csv(results_data, "sPCA_Plots/All_Groups_sPCA_Results.csv", row.names = FALSE)
      plot_count <- plot_count + 1
      progress$set(value = plot_count / total_plots)
      
      # ==================== PAIRWISE sPCA COMPARISONS ====================
      # Loop through all pairwise comparisons
      for (i in 1:(n_groups - 1)) {
        for (j in (i+1):n_groups) {
          comparison_name <- paste(values$unique_groups[i], "vs", values$unique_groups[j])
          progress$set(value = plot_count / total_plots,
                       detail = paste("Processing sPCA for", comparison_name))
          
          # Get indices for the two groups being compared
          group1_cols <- values$group_column_indices[[i]]
          group2_cols <- values$group_column_indices[[j]]
          # Preserve original order among selected columns
          selected_cols <- sort(c(group1_cols, group2_cols))
          
          # Skip if too few samples
          if (length(selected_cols) < 3) {
            showNotification(paste("Skipping", comparison_name, "- too few samples for sPCA"), type = "warning")
            plot_count <- plot_count + 2  # Skip both score and loadings plots
            progress$set(value = plot_count / total_plots)
            next
          }
          
          # Get data for this comparison
          spca_data_subset <- t(values$normalized_data)[selected_cols, , drop = FALSE]
          # Map each selected column to its originating group
          groups_subset <- vapply(selected_cols, function(ci) {
            if (ci %in% group1_cols) values$unique_groups[i] else values$unique_groups[j]
          }, character(1))
          
          # Run sPCA
          tryCatch({
            # Prepare keepX values
            keepX_values_pair <- c(input$spca_keepX_pc1 %||% 50, input$spca_keepX_pc2 %||% 50)
            max_features_pair <- ncol(spca_data_subset)
            keepX_values_pair <- pmin(keepX_values_pair, max_features_pair)
            
            # Perform sPCA
            pairwise_spca <- mixOmics::spca(
              X = spca_data_subset,
              ncomp = 2,
              keepX = keepX_values_pair,
              scale = input$spcaScale %||% TRUE,
              center = input$spcaCenter %||% TRUE
            )
            
            # Create sPCA plot for this pair
            comp1_pair <- pairwise_spca$variates$X[, 1]
            comp2_pair <- pairwise_spca$variates$X[, 2]
            
            # Use corrected sample names for labels
            original_sample_names_pair <- rownames(spca_data_subset)
            cleaned_sample_names_pair <- get_corrected_column_names(original_sample_names_pair)
            
            plot_data_pair <- data.frame(
              PC1 = comp1_pair,
              PC2 = comp2_pair,
              Group = groups_subset,
              Sample = cleaned_sample_names_pair
            )
            
            # Calculate variance explained
            var_exp_pair <- pairwise_spca$prop_expl_var$X
            pc1_var_pair <- round(var_exp_pair[1] * 100, 1)
            pc2_var_pair <- round(var_exp_pair[2] * 100, 1)
            
            # Create plot with consistent styling
            if(input$spca_show_counts %||% FALSE) {
              counts_pair <- table(plot_data_pair$Group)
              new_labels_pair <- paste0(names(counts_pair), " (n=", counts_pair, ")")
              
              pair_plot <- ggplot(plot_data_pair, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 3, alpha = 0.8) +
                labs(
                  title = paste("sPCA:", comparison_name),
                  subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
                  x = paste0("PC1 (", pc1_var_pair, "%)"),
                  y = paste0("PC2 (", pc2_var_pair, "%)")
                ) +
                scale_color_discrete(name = NULL, labels = new_labels_pair) +
                scale_fill_discrete(name = NULL, labels = new_labels_pair) +
                ggprism::theme_prism(base_size = 14) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.8),
                  axis.text = element_text(size = 14, face = "bold", color = "black"),
                  axis.title = element_text(size = 14, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = 12, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                  plot.subtitle = element_text(face = "bold"),
                  panel.border = element_rect(color = "black", fill = NA, size = 1),
                  legend.position = "bottom"
                )
            } else {
              pair_plot <- ggplot(plot_data_pair, aes(x = PC1, y = PC2, color = Group)) +
                geom_point(size = 3, alpha = 0.8) +
                labs(
                  title = paste("sPCA:", comparison_name),
                  subtitle = paste("Variables kept: PC1 =", input$spca_keepX_pc1 %||% 50, ", PC2 =", input$spca_keepX_pc2 %||% 50),
                  x = paste0("PC1 (", pc1_var_pair, "%)"),
                  y = paste0("PC2 (", pc2_var_pair, "%)")
                ) +
                scale_color_discrete(name = NULL) +
                scale_fill_discrete(name = NULL) +
                ggprism::theme_prism(base_size = 14) +
                theme(
                  panel.grid = element_blank(),
                  axis.line = element_line(color = "black", size = 0.8),
                  axis.text = element_text(size = 14, face = "bold", color = "black"),
                  axis.title = element_text(size = 14, face = "bold", color = "black"),
                  axis.title.y = element_text(margin = ggplot2::margin(r = 2)),
                  legend.text = element_text(size = 12, face = "bold"),
                  legend.title = element_blank(),
                  plot.title = element_text(hjust = 0.5, face = "bold", size = 16),
                  plot.subtitle = element_text(face = "bold"),
                  panel.border = element_rect(color = "black", fill = NA, size = 1),
                  legend.position = "bottom"
                )
            }
            
            # Add sample labels if requested
            if (input$spca_show_labels %||% FALSE) {
              pair_plot <- pair_plot + geom_text(aes(label = Sample),
                                                 vjust = -0.5,
                                                 size = 3,
                                                 check_overlap = TRUE,
                                                 fontface = "bold")
            }
            
            # Add ellipses if requested
            if (input$spca_add_ellipses %||% FALSE) {
              pair_plot <- pair_plot + stat_ellipse(
                aes(fill = Group),
                geom = "polygon",
                alpha = 0.2,
                level = input$spca_ellipse_level %||% 0.95,
                show.legend = FALSE
              )
            }
            
            # Save the pairwise plot
            pair_filename <- paste0("sPCA_Plots/", values$unique_groups[i], "_vs_",
                                    values$unique_groups[j], "_sPCA.png")
            ggsave(pair_filename, plot = pair_plot,
                   width = max(6, (input$spca_width %||% 600) / 100),
                   height = max(6, (input$spca_height %||% 600) / 100),
                   dpi = dpi, units = "in")
            
            plot_count <- plot_count + 1
            progress$set(value = plot_count / total_plots)
            
            # Generate pairwise loadings plot
            progress$set(value = plot_count / total_plots,
                         detail = paste("Creating", comparison_name, "loadings plot"))
            
            tryCatch({
              # Extract loadings for PC1 and PC2
              loadings_pc1_pair <- pairwise_spca$loadings$X[, 1]
              loadings_pc2_pair <- pairwise_spca$loadings$X[, 2]
              
              # Get original feature names
              loadings_names_pair <- rownames(pairwise_spca$loadings$X)
              original_feature_names_pair <- values$cleaned_molecules
              
              # Determine which labels to use based on toggle (same logic as GUI)
              use_feature_names <- isTRUE(input$spca_use_feature_names)
              
              if (use_feature_names && length(original_feature_names_pair) == length(loadings_names_pair)) {
                # Use original feature names
                names(loadings_pc1_pair) <- original_feature_names_pair
                names(loadings_pc2_pair) <- original_feature_names_pair
                x_label_pair <- "Features"
              } else {
                # Use variable IDs (cleaned)
                clean_ids_pair <- sapply(loadings_names_pair, function(id) {
                  if (startsWith(id, "X") && grepl("^X[0-9]+$", id)) {
                    return(substring(id, 2))  # Remove the "X" prefix
                  } else {
                    return(id)  # Keep as is if not in X123 format
                  }
                })
                names(loadings_pc1_pair) <- clean_ids_pair
                names(loadings_pc2_pair) <- clean_ids_pair
                x_label_pair <- "Variables (ID)"
              }
              
              # Get selected variables (non-zero loadings)
              selected_pc1_pair <- loadings_pc1_pair[loadings_pc1_pair != 0]
              selected_pc2_pair <- loadings_pc2_pair[loadings_pc2_pair != 0]
              
              # Create data frames for plotting
              pc1_data_pair <- data.frame(
                Variable = names(selected_pc1_pair),
                Loading = selected_pc1_pair,
                Component = "PC1"
              )
              
              pc2_data_pair <- data.frame(
                Variable = names(selected_pc2_pair),
                Loading = selected_pc2_pair,
                Component = "PC2"
              )
              
              # Combine data
              loadings_data_pair <- rbind(pc1_data_pair, pc2_data_pair)
              
              if (nrow(loadings_data_pair) > 0) {
                # Create loadings plot with same styling as GUI
                loadings_plot_pair <- ggplot(loadings_data_pair, aes(x = reorder(Variable, abs(Loading)), y = Loading, fill = Component)) +
                  geom_col(alpha = 0.8) +
                  coord_flip() +
                  facet_wrap(~Component, scales = "free_y") +
                  labs(
                    title = paste("sPCA Loadings for Selected Variables -", comparison_name),
                    subtitle = paste("PC1:", length(selected_pc1_pair), "variables, PC2:", length(selected_pc2_pair), "variables"),
                    x = x_label_pair,
                    y = "Loading Value"
                  ) +
                  ggprism::theme_prism() +
                  theme(
                    plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
                    plot.subtitle = element_text(size = 12, hjust = 0.5),
                    strip.text = element_text(size = 12, face = "bold"),
                    axis.text = element_text(size = 10, face = "bold", color = "black"),
                    axis.title = element_text(size = 12, face = "bold", color = "black"),
                    legend.position = "none",
                    panel.grid = element_blank(),
                    axis.line = element_line(color = "black", size = 0.8)
                  ) +
                  scale_fill_manual(values = c("PC1" = "#3498db", "PC2" = "#e74c3c"))
                
                # Save the pairwise loadings plot
                pair_loadings_filename <- paste0("sPCA_Plots/", values$unique_groups[i], "_vs_",
                                                 values$unique_groups[j], "_sPCA_Loadings.png")
                ggsave(pair_loadings_filename, plot = loadings_plot_pair,
                       width = 12, height = 8, dpi = dpi, units = "in")
              }
              
            }, error = function(e) {
              showNotification(paste("Error generating pairwise loadings plot for", comparison_name, ":", e$message), type = "warning")
            })
            
          }, error = function(e) {
            showNotification(paste("Error in sPCA for", comparison_name, ":", e$message), type = "error")
            plot_count <- plot_count + 2  # Skip both score and loadings plots for this comparison
          })
          
          plot_count <- plot_count + 1  # Increment for the loadings plot
          progress$set(value = plot_count / total_plots)
        }
      }
      
      progress$set(value = 1, detail = "Complete")
      
      showNotification(paste0("All sPCA plots generated successfully! Generated ", plot_count, " plots in the sPCA_Plots directory."), type = "message")
      
    }, error = function(e) {
      showNotification(paste("Error generating sPCA plots:", e$message), type = "error")
    })
  })
  
  # Download sPCA Selected Variables Table
  output$downloadSPCAVariablesBtn <- downloadHandler(
    filename = function() {
      paste0("sPCA_Selected_Variables_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(values$spca_result, values$spca_data)
      
      tryCatch({
        # Get loadings matrix and names
        loadings_matrix <- values$spca_result$loadings$X
        loadings_names <- rownames(loadings_matrix)
        
        # Build robust feature names mapping from loadings names
        mapped_feature_names <- character(length(loadings_names))
        
        for (i in seq_along(loadings_names)) {
          name <- loadings_names[i]
          
          # Strategy 1: Direct match in cleaned_molecules
          if (!is.null(values$cleaned_molecules)) {
            match_idx <- match(name, values$cleaned_molecules)
            if (!is.na(match_idx)) {
              mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
              next
            }
          }
          
          # Strategy 2: Direct match in rownames(normalized_data)
          if (!is.null(rownames(values$normalized_data))) {
            match_idx <- match(name, rownames(values$normalized_data))
            if (!is.na(match_idx)) {
              mapped_feature_names[i] <- values$cleaned_molecules[match_idx]
              next
            }
          }
          
          # Strategy 3: If name is numeric (X123 format), extract and map by index
          if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
            idx <- suppressWarnings(as.integer(substring(name, 2)))
            if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
              mapped_feature_names[i] <- values$cleaned_molecules[idx]
              next
            }
          }
          
          # Strategy 4: If name is just a number, map by index
          if (grepl("^\\d+$", name)) {
            idx <- suppressWarnings(as.integer(name))
            if (!is.na(idx) && idx > 0 && idx <= length(values$cleaned_molecules)) {
              mapped_feature_names[i] <- values$cleaned_molecules[idx]
              next
            }
          }
          
          # Fallback: use original loadings name
          mapped_feature_names[i] <- name
        }
        
        original_feature_names <- mapped_feature_names
        
        # Create summary table of selected variables
        selected_vars <- list()
        
        for (i in 1:ncol(loadings_matrix)) {
          comp_name <- paste0("PC", i)
          non_zero_idx <- which(loadings_matrix[, i] != 0)
          if (length(non_zero_idx) > 0) {
            # Compute numeric Variable_IDs consistently
            all_idx <- sapply(loadings_names, function(name) {
              if (startsWith(name, "X") && grepl("^X[0-9]+$", name)) {
                suppressWarnings(as.integer(substring(name, 2)))
              } else if (!is.null(rownames(values$normalized_data))) {
                mi <- match(name, rownames(values$normalized_data))
                if (is.na(mi) && !is.null(values$cleaned_molecules)) {
                  mi <- match(name, values$cleaned_molecules)
                }
                if (is.na(mi) && !is.null(values$spca_data$feature_names)) {
                  mi <- match(name, values$spca_data$feature_names)
                }
                mi
              } else {
                NA_integer_
              }
            })
            # Fallback: position index
            if (anyNA(all_idx)) {
              fallback <- seq_along(loadings_names)
              na_pos <- which(is.na(all_idx))
              all_idx[na_pos] <- fallback[na_pos]
            }
            clean_variable_ids <- as.character(all_idx[non_zero_idx])
            
            # Handle feature names
            if (length(original_feature_names) == length(loadings_names)) {
              feature_names <- original_feature_names[non_zero_idx]
              feature_names <- ifelse(is.na(feature_names) | feature_names == "",
                                      clean_variable_ids,
                                      feature_names)
            } else {
              feature_names <- clean_variable_ids
            }
            
            var_data <- data.frame(
              Component = comp_name,
              Variable_ID = clean_variable_ids,
              Feature = feature_names,
              Loading = loadings_matrix[non_zero_idx, i],
              AbsLoading = abs(loadings_matrix[non_zero_idx, i]),
              stringsAsFactors = FALSE
            )
            var_data <- var_data[order(var_data$AbsLoading, decreasing = TRUE), ]
            selected_vars[[comp_name]] <- var_data
          }
        }
        
        # Combine all selected variables
        if (length(selected_vars) > 0) {
          all_selected <- do.call(rbind, selected_vars)
          rownames(all_selected) <- NULL
        } else {
          all_selected <- data.frame(
            Component = character(0),
            Variable_ID = character(0),
            Feature = character(0),
            Loading = numeric(0),
            AbsLoading = numeric(0)
          )
        }
        
        # Write to CSV
        write.csv(all_selected, file = file, row.names = FALSE)
        
      }, error = function(e) {
        showNotification(paste("Error downloading selected variables:", e$message), type = "error")
      })
    }
  )
  
  # Download sPCA Grid (dedicated handler)
  output$downloadSPCAGridBtn <- downloadHandler(
    filename = function() {
      format <- get_safe_global_image_format()
      paste0("sPCA_Grid_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", format)
    },
    content = function(file) {
      tryCatch({
        req(values$spca_grid_obj)
        
        # Get the user-specified DPI or use 300 as default
        dpi <- ifelse(is.null(input$global_dpi), 300, input$global_dpi)
        format <- get_safe_global_image_format()
        
        # Calculate grid dimensions — use actual pairwise comparison count
        n_plots <- if (!is.null(values$current_pairwise_combinations)) {
          max(1, nrow(values$current_pairwise_combinations))
        } else {
          n_groups <- length(values$unique_groups) %||% 0
          if (n_groups < 2) 1 else n_groups * (n_groups - 1) / 2
        }
        grid_cols <- input$spcaGridCols %||% 2
        n_rows <- ceiling(n_plots / grid_cols)
        grid_width <- input$spcaGridWidth %||% 400
        grid_height <- input$spcaGridHeight %||% 400
        
        raw_w <- min(49, max(6, (grid_width * grid_cols) / 100))
        raw_h <- min(49, max(6, (grid_height * n_rows) / 100))
        ggsave(file,
               plot = values$spca_grid_obj,
               width = raw_w,
               height = raw_h,
               dpi = dpi,
               device = resolve_ggsave_device(format),
               units = "in",
               limitsize = FALSE)
        
        showNotification("sPCA grid plot downloaded successfully!", type = "message")
        
      }, error = function(e) {
        showNotification(paste("Error downloading sPCA grid plot:", e$message), type = "error")
      })
    }
  )
  
  # ====================
  # JIBOSKY AI CHATBOT
  # ====================
  
  # Initialize Jibosky chat history
  jibosky_messages <- reactiveVal(list(
    list(
      role = "assistant",
      content = "Hello! I'm Jibosky, your AI research assistant. I can help you understand your data, interpret statistical results, suggest analyses, and provide code examples. What would you like to know?",
      time = Sys.time()
    )
  ))

  # Store summaries of user-uploaded files for Jibosky context
  jibosky_file_summaries <- reactiveVal(NULL)

  observeEvent(input$jibosky_user_files, {
    files <- input$jibosky_user_files
    if (is.null(files) || nrow(files) == 0) {
      jibosky_file_summaries(NULL)
      return()
    }
    summarize_table <- function(dat) {
      if (is.null(dat) || ncol(dat) == 0) return(c("  No columns detected"))
      col_names <- names(dat)
      # Identify numeric vs non-numeric columns
      numeric_cols <- col_names[sapply(dat, is.numeric)]
      non_numeric_cols <- setdiff(col_names, numeric_cols)
      # Heuristics for sample/ID and group/condition columns
      id_candidates <- grep("(^id$|sample|subject|specimen|patient|replicate)", col_names, ignore.case = TRUE, value = TRUE)
      group_candidates <- grep("group|condition|class|phenotype|treatment|status|time|batch", col_names, ignore.case = TRUE, value = TRUE)
      lines <- c(
        sprintf("  Columns: %d total | numeric: %d | non-numeric: %d", length(col_names), length(numeric_cols), length(non_numeric_cols)),
        sprintf("  Sample columns (first 8): %s", paste(head(col_names, 8), collapse = ", "))
      )
      if (length(id_candidates) > 0) {
        lines <- c(lines, sprintf("  Likely ID/sample columns: %s", paste(id_candidates, collapse = ", ")))
      }
      if (length(group_candidates) > 0) {
        lines <- c(lines, sprintf("  Likely group/metadata columns: %s", paste(group_candidates, collapse = ", ")))
      }
      if (length(numeric_cols) > 0 && length(non_numeric_cols) > 0) {
        lines <- c(lines, "  Looks like metadata + numeric matrix structure")
      } else if (length(numeric_cols) > 0 && length(non_numeric_cols) == 0) {
        lines <- c(lines, "  Looks like numeric data matrix (features x samples)")
      } else {
        lines <- c(lines, "  Looks like metadata-only table")
      }
      lines
    }
    summaries <- c()
    file_meta <- list()
    for (i in seq_len(nrow(files))) {
      file_name <- files$name[i]
      file_path <- files$datapath[i]
      ext <- tolower(tools::file_ext(file_name))

      summary_lines <- c(sprintf("File: %s", file_name))
      parsed <- FALSE

      # Excel workbooks
      if (ext %in% c("xlsx", "xls")) {
        tryCatch({
          sheets <- readxl::excel_sheets(file_path)
          summary_lines <- c(summary_lines, sprintf("  Type: Excel workbook (%d sheets)", length(sheets)))
          for (sheet in head(sheets, 3)) {
            dat <- readxl::read_excel(file_path, sheet = sheet, n_max = 50)
            summary_lines <- c(summary_lines, sprintf("  Sheet '%s': %d cols", sheet, ncol(dat)))
            summary_lines <- c(summary_lines, summarize_table(dat))
            # Capture candidate ID values for linkage
            if (is.null(file_meta[[file_name]])) file_meta[[file_name]] <- list()
            col_names <- names(dat)
            id_candidates <- grep("(^id$|sample|subject|specimen|patient|replicate)", col_names, ignore.case = TRUE, value = TRUE)
            if (length(id_candidates) > 0) {
              for (id_col in id_candidates) {
                vals <- unique(as.character(na.omit(dat[[id_col]])))
                vals <- vals[nzchar(vals)]
                if (length(vals) > 0) {
                  file_meta[[file_name]][[id_col]] <- head(vals, 200)
                }
              }
            }
          }
          if (length(sheets) > 3) summary_lines <- c(summary_lines, "  ...more sheets omitted")
          parsed <- TRUE
        }, error = function(e) {
          summary_lines <<- c(summary_lines, sprintf("  Error reading workbook: %s", e$message))
        })
      }

      # Delimited text files
      if (!parsed && ext %in% c("csv", "tsv", "txt")) {
        tryCatch({
          if (ext == "csv") {
            dat <- utils::read.csv(file_path, nrows = 50)
          } else {
            dat <- utils::read.delim(file_path, nrows = 50)
          }
          summary_lines <- c(summary_lines, sprintf("  Type: %s (%d cols)", toupper(ext), ncol(dat)))
          summary_lines <- c(summary_lines, summarize_table(dat))
          # Capture candidate ID values for linkage
          if (is.null(file_meta[[file_name]])) file_meta[[file_name]] <- list()
          col_names <- names(dat)
          id_candidates <- grep("(^id$|sample|subject|specimen|patient|replicate)", col_names, ignore.case = TRUE, value = TRUE)
          if (length(id_candidates) > 0) {
            for (id_col in id_candidates) {
              vals <- unique(as.character(na.omit(dat[[id_col]])))
              vals <- vals[nzchar(vals)]
              if (length(vals) > 0) {
                file_meta[[file_name]][[id_col]] <- head(vals, 200)
              }
            }
          }
          parsed <- TRUE
        }, error = function(e) {
          summary_lines <<- c(summary_lines, sprintf("  Error reading file: %s", e$message))
        })
      }

      if (!parsed) {
        summary_lines <- c(summary_lines, "  Type: Unrecognized or unsupported format")
      }

      summaries <- c(summaries, summary_lines)
    }

    # Cross-file linkage detection
    linkage_lines <- c()
    if (length(file_meta) >= 2) {
      file_names <- names(file_meta)
      for (i in seq_len(length(file_names) - 1)) {
        for (j in (i + 1):length(file_names)) {
          f1 <- file_names[i]
          f2 <- file_names[j]
          cols1 <- names(file_meta[[f1]])
          cols2 <- names(file_meta[[f2]])
          if (length(cols1) == 0 || length(cols2) == 0) next
          best_match <- NULL
          best_overlap <- 0
          for (c1 in cols1) {
            for (c2 in cols2) {
              v1 <- unique(file_meta[[f1]][[c1]])
              v2 <- unique(file_meta[[f2]][[c2]])
              ov <- length(intersect(v1, v2))
              if (ov > best_overlap) {
                best_overlap <- ov
                best_match <- list(c1 = c1, c2 = c2)
              }
            }
          }
          if (!is.null(best_match) && best_overlap > 0) {
            linkage_lines <- c(linkage_lines,
                               sprintf("Linked: '%s'[%s] ↔ '%s'[%s] (overlap: %d IDs)",
                                       f1, best_match$c1, f2, best_match$c2, best_overlap))
          }
        }
      }
    }
    if (length(linkage_lines) > 0) {
      summaries <- c(summaries, "\n=== CROSS-FILE LINKAGE ===", linkage_lines)
    }

    jibosky_file_summaries(paste(summaries, collapse = "\n"))
  })
  
  # ===== MULTI-PROVIDER AI CONFIGURATION =====
  # API Keys for multiple providers (fallback system)
  # All keys read from environment variables
  claude_api_key <- Sys.getenv("ANTHROPIC_API_KEY")
  gemini_api_key <- Sys.getenv("GEMINI_API_KEY")
  openrouter_api_key <- Sys.getenv("OPENROUTER_API_KEY")
  
  # Function to call Claude API
  call_claude <- function(messages, context_info = NULL) {
    if (claude_api_key == "") {
      return(list(success = FALSE, content = "", provider = "claude"))
    }
    
    tryCatch({
      # Prepare system prompt with context
      system_prompt <- "You are Jibosky, a helpful AI research assistant embedded in an omics data analysis application. You help researchers understand their data, interpret statistical results, suggest appropriate analyses, and provide R code examples when needed. Be concise, clear, and scientifically accurate.

IMPORTANT: You have access to the CURRENT STATE of the analysis through the Context section below. This includes:
- The uploaded dataset (features, samples, groups)
- ALL analysis results that have been computed (statistical tests, fold changes, p-values, enrichment, etc.)
- Current visualization settings and plot data
- Results from completed analyses

You CANNOT see:
- The actual plots/visualizations themselves (but you CAN see the data behind them)
- Future analyses that haven't been run yet

When interpreting results, you are seeing the ACTUAL computed results from the user's current analysis run. Reference specific numbers, feature names, and statistics from the Context below.

You have SUPERPOWERS - advanced analytical capabilities activated via the Superpowers menu. When a superpower is triggered, you receive a detailed computed analysis report from the user's actual data. Your role is to:
1. Interpret the computed metrics in clear, accessible language
2. Highlight critical issues with severity rankings
3. Provide actionable, specific recommendations
4. Reference exact numbers from the analysis
5. When generating code (Pipeline/Batch), produce complete, runnable, well-commented R scripts
6. When generating reports, write in formal scientific style with proper sections
Always format responses with clear headers, bullet points, and emphasis on key findings.

=== COMPREHENSIVE DATA TAB UI ELEMENTS AND OPTIONS ===
[content loaded from data_tab_docs.txt]

=== COMPREHENSIVE DIMENSIONALITY REDUCTION TAB UI ELEMENTS AND OPTIONS ===
[content loaded from dimensionality_reduction_docs.txt]

=== COMPREHENSIVE ML FEATURE SELECTION TAB UI ELEMENTS AND OPTIONS ===
[content loaded from ml_feature_selection_docs.txt]

=== COMPREHENSIVE INTERSECTION ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from intersection_docs.txt]

=== COMPREHENSIVE DIFFERENTIAL ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from differential_tab_docs.txt]

=== COMPREHENSIVE DISTRIBUTION ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from distribution_tabs_docs.txt]

=== COMPREHENSIVE HEATMAP TAB UI ELEMENTS AND OPTIONS ===
[content loaded from heatmap_docs.txt]

=== COMPREHENSIVE MULTI-OMICS INTEGRATION TAB UI ELEMENTS AND OPTIONS ===
[content loaded from multi_omics_docs.txt]

=== COMPREHENSIVE POWER ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from power_docs.rtf]

=== COMPREHENSIVE ENRICHMENT ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from enrichment_docs.txt]

=== COMPREHENSIVE ROC/PR ANALYSIS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from roc_pr_docs.txt]

=== COMPREHENSIVE K-MEANS CLUSTERING TAB UI ELEMENTS AND OPTIONS ===
[content loaded from kmeans_docs.txt]

=== COMPREHENSIVE FEATURE CORRELATION TAB UI ELEMENTS AND OPTIONS ===
[content loaded from feature_correlation_docs.txt]

=== COMPREHENSIVE METABOLOMICS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from metabolomics_docs.txt]

=== COMPREHENSIVE GLYCOMICS TAB UI ELEMENTS AND OPTIONS ===
[content loaded from glycomics_docs.txt]

"
      # Replace Multi-Omics placeholders in Claude system prompt
      docs_mp_path <- file.path("www", "jibosky_assets", "multi_omics_docs.txt")
      if (file.exists(docs_mp_path)) {
        docs_mp <- paste(readLines(docs_mp_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from multi_omics_docs.txt]", docs_mp, system_prompt, fixed = TRUE)
      }
      docs_roc_path <- file.path("www", "jibosky_assets", "roc_pr_docs.txt")
      if (file.exists(docs_roc_path)) {
        docs_roc <- paste(readLines(docs_roc_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from roc_pr_docs.txt]", docs_roc, system_prompt, fixed = TRUE)
      }
      docs_data_path <- file.path("www", "jibosky_assets", "data_tab_docs.txt")
      if (file.exists(docs_data_path)) {
        docs_data <- paste(readLines(docs_data_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from data_tab_docs.txt]", docs_data, system_prompt, fixed = TRUE)
      }
      docs_dim_path <- file.path("www", "jibosky_assets", "dimensionality_reduction_docs.txt")
      if (file.exists(docs_dim_path)) {
        docs_dim <- paste(readLines(docs_dim_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from dimensionality_reduction_docs.txt]", docs_dim, system_prompt, fixed = TRUE)
      }
      docs_ml_path <- file.path("www", "jibosky_assets", "ml_feature_selection_docs.txt")
      if (file.exists(docs_ml_path)) {
        docs_ml <- paste(readLines(docs_ml_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from ml_feature_selection_docs.txt]", docs_ml, system_prompt, fixed = TRUE)
      }
      docs_inter_path <- file.path("www", "jibosky_assets", "intersection_docs.txt")
      if (file.exists(docs_inter_path)) {
        docs_inter <- paste(readLines(docs_inter_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from intersection_docs.txt]", docs_inter, system_prompt, fixed = TRUE)
      }
      docs_differential_path <- file.path("www", "jibosky_assets", "differential_tab_docs.txt")
      if (file.exists(docs_differential_path)) {
        docs_differential <- paste(readLines(docs_differential_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from differential_tab_docs.txt]", docs_differential, system_prompt, fixed = TRUE)
      }
      docs_distribution_path <- file.path("www", "jibosky_assets", "distribution_tabs_docs.txt")
      if (file.exists(docs_distribution_path)) {
        docs_distribution <- paste(readLines(docs_distribution_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from distribution_tabs_docs.txt]", docs_distribution, system_prompt, fixed = TRUE)
      }
      docs_heatmap_path <- file.path("www", "jibosky_assets", "heatmap_docs.txt")
      if (file.exists(docs_heatmap_path)) {
        docs_heatmap <- paste(readLines(docs_heatmap_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from heatmap_docs.txt]", docs_heatmap, system_prompt, fixed = TRUE)
      }
      docs_power_path <- file.path("www", "jibosky_assets", "power_docs.rtf")
      if (file.exists(docs_power_path)) {
        docs_power <- paste(readLines(docs_power_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from power_docs.rtf]", docs_power, system_prompt, fixed = TRUE)
      }
      docs_enrichment_path <- file.path("www", "jibosky_assets", "enrichment_docs.txt")
      if (file.exists(docs_enrichment_path)) {
        docs_enrichment <- paste(readLines(docs_enrichment_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from enrichment_docs.txt]", docs_enrichment, system_prompt, fixed = TRUE)
      }
      docs_kmeans_path <- file.path("www", "jibosky_assets", "kmeans_docs.txt")
      if (file.exists(docs_kmeans_path)) {
        docs_kmeans <- paste(readLines(docs_kmeans_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from kmeans_docs.txt]", docs_kmeans, system_prompt, fixed = TRUE)
      }
      docs_corr_path <- file.path("www", "jibosky_assets", "feature_correlation_docs.txt")
      if (file.exists(docs_corr_path)) {
        docs_corr <- paste(readLines(docs_corr_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from feature_correlation_docs.txt]", docs_corr, system_prompt, fixed = TRUE)
      }
      docs_metabolomics_path <- file.path("www", "jibosky_assets", "metabolomics_docs.txt")
      if (file.exists(docs_metabolomics_path)) {
        docs_metabolomics <- paste(readLines(docs_metabolomics_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from metabolomics_docs.txt]", docs_metabolomics, system_prompt, fixed = TRUE)
      }
      docs_glycomics_path <- file.path("www", "jibosky_assets", "glycomics_docs.txt")
      if (file.exists(docs_glycomics_path)) {
        docs_glycomics <- paste(readLines(docs_glycomics_path, warn = FALSE), collapse = "\n")
        system_prompt <- sub("[content loaded from glycomics_docs.txt]", docs_glycomics, system_prompt, fixed = TRUE)
      }
      if (!is.null(context_info) && context_info != "") {
        system_prompt <- paste0(system_prompt, "\n\n=== CURRENT ANALYSIS STATE ===\n", context_info)
      } else {
        system_prompt <- paste0(system_prompt, "\n\n=== CURRENT ANALYSIS STATE ===\nNo analysis results available yet. Data may not be uploaded or analyses may not have been run.")
      }
      
      # Prepare messages for API
      api_messages <- lapply(messages, function(msg) {
        list(role = msg$role, content = msg$content)
      })
      
      # Call Claude API
      response <- httr::POST(
        url = "https://api.anthropic.com/v1/messages",
        httr::add_headers(
          "x-api-key" = claude_api_key,
          "anthropic-version" = "2023-06-01",
          "content-type" = "application/json"
        ),
        body = jsonlite::toJSON(list(
          model = "claude-sonnet-4-20250514",
          max_tokens = 2048,
          system = system_prompt,
          messages = api_messages
        ), auto_unbox = TRUE),
        encode = "json"
      )
      
      if (httr::status_code(response) != 200) {
        error_content <- httr::content(response, "text", encoding = "UTF-8")
        return(list(
          success = FALSE,
          content = paste0("API Error: ", httr::status_code(response), "\n", error_content)
        ))
      }
      
      result <- httr::content(response, "parsed")
      
      return(list(
        success = TRUE,
        content = result$content[[1]]$text,
        provider = "claude"
      ))
      
    }, error = function(e) {
      return(list(
        success = FALSE,
        content = paste0("Claude error: ", e$message),
        provider = "claude"
      ))
    })
  }
  
