      } else {
        system_prompt <- paste0(system_prompt, "\n\n=== CURRENT ANALYSIS STATE ===\nNo analysis results available yet.")
      }
      
      # Gemini format: combine system prompt and messages
      gemini_contents <- list()
      
      # Add system prompt as first user message
      gemini_contents[[1]] <- list(
        role = "user",
        parts = list(list(text = system_prompt))
      )
      gemini_contents[[2]] <- list(
        role = "model",
        parts = list(list(text = "Understood. I'm Jibosky, ready to help with your omics analysis."))
      )
      
      # Add conversation messages
      for (msg in messages) {
        role <- if (msg$role == "assistant") "model" else msg$role
        gemini_contents[[length(gemini_contents) + 1]] <- list(
          role = role,
          parts = list(list(text = msg$content))
        )
      }
      
      # Call Gemini API
      response <- httr::POST(
        url = paste0("https://generativelanguage.googleapis.com/v1/models/gemini-2.5-flash:generateContent?key=", gemini_api_key),
        httr::add_headers("Content-Type" = "application/json"),
        body = jsonlite::toJSON(list(
          contents = gemini_contents,
          generationConfig = list(
            temperature = 0.7,
            maxOutputTokens = 2048
          )
        ), auto_unbox = TRUE),
        encode = "json"
      )
      
      if (httr::status_code(response) != 200) {
        return(list(success = FALSE, content = paste0("Gemini API error: ", httr::status_code(response)), provider = "gemini"))
      }
      
      result <- httr::content(response, "parsed")
      
      if (!is.null(result$candidates) && length(result$candidates) > 0) {
        content <- result$candidates[[1]]$content$parts[[1]]$text
        return(list(success = TRUE, content = content, provider = "gemini"))
      }
      
      return(list(success = FALSE, content = "Gemini returned no content", provider = "gemini"))
      
    }, error = function(e) {
      return(list(success = FALSE, content = paste0("Gemini error: ", e$message), provider = "gemini"))
    })
  }
  
