  # --- SP1: Data Quality Report ---
  sp_data_quality_report <- function() {
    parts <- c()
    if (is.null(values$normalized_data) || nrow(values$normalized_data) == 0) {
      return("No data loaded yet. Please upload a dataset first.")
    }
    norm_mat <- values$normalized_data
    raw_mat <- values$raw_data
    n_feat <- nrow(norm_mat); n_samp <- ncol(norm_mat)
    parts <- c(parts, sprintf("=== DATA QUALITY REPORT ===\nFeatures: %d | Samples: %d", n_feat, n_samp))
    
    # Missing values
    if (!is.null(raw_mat)) {
      raw_num <- apply(raw_mat, 2, function(x) suppressWarnings(as.numeric(x)))
      if (is.vector(raw_num)) raw_num <- matrix(raw_num, nrow = 1)
      total_cells <- length(raw_num)
      n_na <- sum(is.na(raw_num))
      pct_na <- round(100 * n_na / total_cells, 2)
      parts <- c(parts, sprintf("\n[Missing Values] Total cells: %d | Missing: %d (%.2f%%)", total_cells, n_na, pct_na))
      
      feat_miss <- rowSums(is.na(raw_num))
      samp_miss <- colSums(is.na(raw_num))
      if (any(feat_miss > 0)) {
        worst_feat_idx <- head(order(feat_miss, decreasing = TRUE), 5)
        for (idx in worst_feat_idx) {
          fname <- if (!is.null(rownames(raw_mat))) rownames(raw_mat)[idx] else paste0("Feature ", idx)
          parts <- c(parts, sprintf("  Feature '%s': %d/%d missing (%.1f%%)", fname, feat_miss[idx], n_samp, 100*feat_miss[idx]/n_samp))
        }
      }
      if (any(samp_miss > 0)) {
        worst_samp_idx <- head(order(samp_miss, decreasing = TRUE), 5)
        for (idx in worst_samp_idx) {
          sname <- if (!is.null(colnames(raw_mat))) colnames(raw_mat)[idx] else paste0("Sample ", idx)
          parts <- c(parts, sprintf("  Sample '%s': %d/%d missing (%.1f%%)", sname, samp_miss[idx], n_feat, 100*samp_miss[idx]/n_feat))
        }
      }
    }
    
    # Constant / near-zero variance features
    norm_num <- apply(norm_mat, 1, function(x) suppressWarnings(as.numeric(x)))
    if (is.vector(norm_num)) norm_num <- matrix(norm_num, ncol = 1)
    feat_var <- apply(norm_num, 2, var, na.rm = TRUE)
    n_const <- sum(feat_var < 1e-10, na.rm = TRUE)
    n_low_var <- sum(feat_var < quantile(feat_var, 0.01, na.rm = TRUE), na.rm = TRUE)
    parts <- c(parts, sprintf("\n[Variance] Constant features: %d | Bottom 1%% variance: %d", n_const, n_low_var))
    
    # Normality overview (sample of features)
    n_check <- min(n_feat, 100)
    check_idx <- if (n_feat > 100) sample(seq_len(n_feat), 100) else seq_len(n_feat)
    n_normal <- 0
    for (i in check_idx) {
      fv <- suppressWarnings(as.numeric(norm_mat[i, ]))
      fv <- fv[!is.na(fv)]
      if (length(fv) >= 3 && length(fv) <= 5000) {
        p <- tryCatch(shapiro.test(fv)$p.value, error = function(e) NA)
        if (!is.na(p) && p > 0.05) n_normal <- n_normal + 1
      }
    }
    parts <- c(parts, sprintf("\n[Normality] Of %d features sampled: %d normal (%.1f%%), %d non-normal (%.1f%%)",
                              n_check, n_normal, 100*n_normal/n_check, n_check-n_normal, 100*(n_check-n_normal)/n_check))
    
    # Value range & potential batch effects
    samp_medians <- apply(norm_num, 1, median, na.rm = TRUE)
    samp_range <- range(samp_medians, na.rm = TRUE)
    samp_cv <- sd(samp_medians, na.rm = TRUE) / mean(samp_medians, na.rm = TRUE)
    parts <- c(parts, sprintf("\n[Batch Effects] Sample median range: [%.2f, %.2f] | CV of sample medians: %.3f",
                              samp_range[1], samp_range[2], abs(samp_cv)))
    if (abs(samp_cv) > 0.3) {
      parts <- c(parts, "  WARNING: High CV of sample medians suggests possible batch effects or incomplete normalization")
    }
    
    # Potential contamination (outlier samples by median absolute deviation)
    global_median <- median(samp_medians, na.rm = TRUE)
    global_mad <- mad(samp_medians, na.rm = TRUE)
    if (global_mad > 0) {
      outlier_samps <- which(abs(samp_medians - global_median) > 3 * global_mad)
      if (length(outlier_samps) > 0) {
        parts <- c(parts, sprintf("\n[Potential Contamination] %d sample(s) with medians > 3 MAD from global median:", length(outlier_samps)))
        for (oi in outlier_samps) {
          sname <- if (!is.null(colnames(norm_mat))) colnames(norm_mat)[oi] else paste0("Sample ", oi)
          parts <- c(parts, sprintf("  %s (median: %.2f, global: %.2f)", sname, samp_medians[oi], global_median))
        }
      }
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP2: Missing Data Analysis ---
  sp_missing_data_analysis <- function() {
    parts <- c()
    raw_mat <- values$raw_data
    if (is.null(raw_mat)) return("No raw data loaded. Please upload a dataset first.")
    
    raw_num <- apply(raw_mat, 2, function(x) suppressWarnings(as.numeric(x)))
    if (is.vector(raw_num)) raw_num <- matrix(raw_num, nrow = 1)
    n_feat <- nrow(raw_num); n_samp <- ncol(raw_num)
    total_cells <- length(raw_num)
    n_na <- sum(is.na(raw_num))
    
    parts <- c(parts, "=== MISSING DATA ANALYSIS ===")
    parts <- c(parts, sprintf("Total cells: %d | Missing: %d (%.2f%%)", total_cells, n_na, 100*n_na/total_cells))
    
    if (n_na == 0) {
      parts <- c(parts, "No missing values detected. Dataset is complete.")
      return(paste(parts, collapse = "\n"))
    }
    
    # Missing per feature
    feat_miss <- rowSums(is.na(raw_num))
    feat_miss_pct <- 100 * feat_miss / n_samp
    parts <- c(parts, sprintf("\n[Feature-level] Features with missing: %d/%d", sum(feat_miss > 0), n_feat))
    parts <- c(parts, sprintf("  >50%% missing: %d features", sum(feat_miss_pct > 50)))
    parts <- c(parts, sprintf("  20-50%% missing: %d features", sum(feat_miss_pct > 20 & feat_miss_pct <= 50)))
    parts <- c(parts, sprintf("  <20%% missing: %d features", sum(feat_miss_pct > 0 & feat_miss_pct <= 20)))
    
    # Missing per sample
    samp_miss <- colSums(is.na(raw_num))
    samp_miss_pct <- 100 * samp_miss / n_feat
    parts <- c(parts, sprintf("\n[Sample-level] Samples with missing: %d/%d", sum(samp_miss > 0), n_samp))
    worst_samp <- head(order(samp_miss, decreasing = TRUE), 5)
    for (idx in worst_samp) {
      if (samp_miss[idx] == 0) break
      sname <- if (!is.null(colnames(raw_mat))) colnames(raw_mat)[idx] else paste0("Sample ", idx)
      parts <- c(parts, sprintf("  %s: %d missing (%.1f%%)", sname, samp_miss[idx], samp_miss_pct[idx]))
    }
    
    # MCAR/MNAR pattern analysis
    if (!is.null(values$unique_groups) && length(values$unique_groups) >= 2 && !is.null(values$group_column_indices)) {
      parts <- c(parts, "\n[Missingness Pattern by Group]")
      for (grp in names(values$group_column_indices)) {
        grp_idx <- values$group_column_indices[[grp]]
        grp_miss <- sum(is.na(raw_num[, grp_idx, drop = FALSE]))
        grp_total <- n_feat * length(grp_idx)
        parts <- c(parts, sprintf("  %s: %.2f%% missing (%d/%d)", grp, 100*grp_miss/grp_total, grp_miss, grp_total))
      }
    }
    
    # Imputation recommendations
    parts <- c(parts, "\n[Imputation Recommendations]")
    overall_pct <- 100 * n_na / total_cells
    if (overall_pct < 5) {
      parts <- c(parts, "  Low missingness (<5%): Min/half-min, KNN, or median imputation suitable")
    } else if (overall_pct < 20) {
      parts <- c(parts, "  Moderate missingness (5-20%): KNN or multiple imputation recommended")
    } else {
      parts <- c(parts, "  High missingness (>20%): Consider removing features >50% missing first, then KNN/multiple imputation")
    }
    if (sum(feat_miss_pct > 50) > 0) {
      parts <- c(parts, sprintf("  Consider removing %d features with >50%% missing before imputation", sum(feat_miss_pct > 50)))
    }
    if (any(samp_miss_pct > 40)) {
      parts <- c(parts, sprintf("  Consider removing %d sample(s) with >40%% missing", sum(samp_miss_pct > 40)))
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP3: Outlier Detection ---
  sp_outlier_detection <- function() {
    parts <- c()
    if (is.null(values$normalized_data)) return("No data loaded. Please upload a dataset first.")
    norm_mat <- values$normalized_data
    n_feat <- nrow(norm_mat); n_samp <- ncol(norm_mat)
    
    norm_num <- apply(norm_mat, 2, function(x) suppressWarnings(as.numeric(x)))
    if (is.vector(norm_num)) norm_num <- matrix(norm_num, ncol = 1)
    
    parts <- c(parts, "=== OUTLIER DETECTION REPORT ===")
    
    # Sample-level outlier detection via PCA
    parts <- c(parts, "\n[Sample-Level Outliers (PCA-based)]")
    tryCatch({
      complete_rows <- complete.cases(t(norm_num))
      if (sum(complete_rows) >= 3) {
        pca_dat <- t(norm_num[, complete_rows, drop = FALSE])
        pca_res <- prcomp(pca_dat, center = TRUE, scale. = TRUE)
        scores <- pca_res$x[, 1:min(3, ncol(pca_res$x)), drop = FALSE]
        dists <- sqrt(rowSums(scale(scores)^2))
        threshold <- median(dists) + 3 * mad(dists)
        outlier_idx <- which(dists > threshold)
        if (length(outlier_idx) > 0) {
          parts <- c(parts, sprintf("  %d sample(s) flagged (distance > median + 3*MAD):", length(outlier_idx)))
          for (oi in outlier_idx) {
            sname <- if (!is.null(colnames(norm_mat)[complete_rows])) colnames(norm_mat)[complete_rows][oi] else paste0("Sample ", oi)
            parts <- c(parts, sprintf("    %s (PCA distance: %.2f, threshold: %.2f)", sname, dists[oi], threshold))
          }
        } else {
          parts <- c(parts, "  No PCA-based sample outliers detected (all within 3*MAD)")
        }
      }
    }, error = function(e) {
      parts <<- c(parts, sprintf("  PCA outlier check failed: %s", e$message))
    })
    
    # Feature-level: extreme values
    parts <- c(parts, "\n[Feature-Level Extreme Values]")
    n_check_feat <- min(n_feat, 200)
    check_feats <- if (n_feat > 200) sample(seq_len(n_feat), 200) else seq_len(n_feat)
    features_with_outliers <- 0
    extreme_entries <- c()
    for (fi in check_feats) {
      fv <- suppressWarnings(as.numeric(norm_mat[fi, ]))
      fv_clean <- fv[!is.na(fv)]
      if (length(fv_clean) < 3) next
      q1 <- quantile(fv_clean, 0.25); q3 <- quantile(fv_clean, 0.75); iqr <- q3 - q1
      lower <- q1 - 3 * iqr; upper <- q3 + 3 * iqr
      n_outliers <- sum(fv_clean < lower | fv_clean > upper)
      if (n_outliers > 0) {
        features_with_outliers <- features_with_outliers + 1
        if (length(extreme_entries) < 10) {
          fname <- if (!is.null(rownames(norm_mat))) rownames(norm_mat)[fi] else paste0("Feature ", fi)
          extreme_entries <- c(extreme_entries, sprintf("  %s: %d extreme values (3*IQR rule)", fname, n_outliers))
        }
      }
    }
    parts <- c(parts, sprintf("  Of %d features checked: %d (%.1f%%) have extreme outliers (3*IQR)", 
                              n_check_feat, features_with_outliers, 100*features_with_outliers/n_check_feat))
    if (length(extreme_entries) > 0) {
      parts <- c(parts, "  Top flagged features:")
      parts <- c(parts, extreme_entries)
    }
    
    # Group-specific outlier check
    if (!is.null(values$unique_groups) && length(values$unique_groups) >= 2 && !is.null(values$group_column_indices)) {
      parts <- c(parts, "\n[Group-Specific Sample Medians]")
      for (grp in names(values$group_column_indices)) {
        grp_idx <- values$group_column_indices[[grp]]
        if (length(grp_idx) >= 2) {
          grp_vals <- norm_num[, grp_idx, drop = FALSE]
          grp_medians <- colMedians_safe <- apply(grp_vals, 2, median, na.rm = TRUE)
          grp_med_global <- median(grp_medians, na.rm = TRUE)
          grp_mad <- mad(grp_medians, na.rm = TRUE)
          if (grp_mad > 0) {
            grp_outliers <- which(abs(grp_medians - grp_med_global) > 2.5 * grp_mad)
            if (length(grp_outliers) > 0) {
              for (go in grp_outliers) {
                sname <- if (!is.null(colnames(norm_mat))) colnames(norm_mat)[grp_idx[go]] else paste0("Sample ", grp_idx[go])
                parts <- c(parts, sprintf("  %s in group '%s': median %.2f (group median: %.2f)", sname, grp, grp_medians[go], grp_med_global))
              }
            }
          }
        }
      }
    }
    
    parts <- c(parts, "\n[Suggestions]")
    parts <- c(parts, "  - Investigate flagged samples before removal")
    parts <- c(parts, "  - Consider robust normalization if batch effects suspected")
    parts <- c(parts, "  - Winsorization can reduce impact of extreme feature values")
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP4: Statistical Method Suggestions ---
  sp_stat_recommendations <- function() {
    parts <- c("=== STATISTICAL METHOD RECOMMENDATIONS ===")
    if (is.null(values$normalized_data)) return("No data loaded. Please upload a dataset first.")
    
    n_samp <- ncol(values$normalized_data)
    n_feat <- nrow(values$normalized_data)
    n_groups <- length(values$unique_groups)
    group_sizes <- if (!is.null(values$group_column_indices)) sapply(values$group_column_indices, length) else integer(0)
    min_group <- if (length(group_sizes) > 0) min(group_sizes) else n_samp
    balanced <- if (length(group_sizes) >= 2) (max(group_sizes) / min(group_sizes)) < 1.5 else TRUE
    
    # Normality check on a sample of features
    n_check <- min(n_feat, 50)
    check_idx <- if (n_feat > 50) sample(seq_len(n_feat), 50) else seq_len(n_feat)
    n_normal <- 0
    for (i in check_idx) {
      fv <- suppressWarnings(as.numeric(values$normalized_data[i, ]))
      fv <- fv[!is.na(fv)]
      if (length(fv) >= 3 && length(fv) <= 5000) {
        p <- tryCatch(shapiro.test(fv)$p.value, error = function(e) NA)
        if (!is.na(p) && p > 0.05) n_normal <- n_normal + 1
      }
    }
    normality_pct <- 100 * n_normal / n_check
    
    parts <- c(parts, sprintf("\n[Data Characteristics]"))
    parts <- c(parts, sprintf("  Groups: %d | Total samples: %d | Min group size: %d", n_groups, n_samp, min_group))
    parts <- c(parts, sprintf("  Balanced design: %s", if (balanced) "Yes" else "No"))
    parts <- c(parts, sprintf("  Normality: %.0f%% of sampled features are normally distributed", normality_pct))
    
    parts <- c(parts, "\n[Recommended Statistical Tests]")
    if (n_groups == 2) {
      if (normality_pct > 60 && min_group >= 10) {
        parts <- c(parts, "  PRIMARY: Welch's t-test (parametric, robust to unequal variance)")
        parts <- c(parts, "  ALTERNATIVE: Mann-Whitney U / Wilcoxon rank-sum (non-parametric backup)")
      } else {
        parts <- c(parts, "  PRIMARY: Mann-Whitney U / Wilcoxon rank-sum (non-parametric, recommended for non-normal or small-sample data)")
        parts <- c(parts, "  ALTERNATIVE: Welch's t-test (if visual inspection suggests approximate normality)")
      }
      if (min_group < 5) {
        parts <- c(parts, "  CAUTION: Very small group sizes (<5). Consider permutation tests for more reliable p-values.")
      }
    } else if (n_groups > 2) {
      if (normality_pct > 60 && min_group >= 10) {
        parts <- c(parts, "  PRIMARY: One-way ANOVA + Tukey HSD post-hoc")
        parts <- c(parts, "  ALTERNATIVE: Kruskal-Wallis + Dunn's post-hoc (if normality is questionable)")
      } else {
        parts <- c(parts, "  PRIMARY: Kruskal-Wallis + Dunn's post-hoc (non-parametric)")
        parts <- c(parts, "  ALTERNATIVE: One-way ANOVA + Games-Howell (if approximately normal)")
      }
      if (!balanced) {
        parts <- c(parts, "  NOTE: Unbalanced design detected. Use Welch's ANOVA or non-parametric tests.")
      }
    } else {
      parts <- c(parts, "  Only 1 group detected. Statistical comparison requires 2+ groups.")
    }
    
    # Multiple testing
    parts <- c(parts, "\n[Multiple Testing Correction]")
    if (n_feat > 100) {
      parts <- c(parts, "  Recommended: Benjamini-Hochberg FDR (good balance of power and control)")
    } else {
      parts <- c(parts, "  Recommended: Benjamini-Hochberg FDR or Bonferroni (conservative for small feature sets)")
    }
    
    # Machine learning
    parts <- c(parts, "\n[Machine Learning Recommendations]")
    if (min_group >= 20) {
      parts <- c(parts, "  Feature selection: Random Forest importance or Boruta")
      parts <- c(parts, "  Validation: 5-fold or 10-fold cross-validation")
    } else if (min_group >= 10) {
      parts <- c(parts, "  Feature selection: LASSO/Elastic Net (handles high dimensionality)")
      parts <- c(parts, "  Validation: Leave-one-out cross-validation (LOOCV)")
    } else {
      parts <- c(parts, "  CAUTION: Small sample sizes limit reliable ML. Consider permutation-based importance.")
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP5: Power / Sample Size Check ---
  sp_power_check <- function() {
    parts <- c("=== POWER / SAMPLE SIZE ASSESSMENT ===")
    if (is.null(values$normalized_data)) return("No data loaded. Please upload a dataset first.")
    
    n_groups <- length(values$unique_groups)
    group_sizes <- if (!is.null(values$group_column_indices)) sapply(values$group_column_indices, length) else integer(0)
    n_feat <- nrow(values$normalized_data)
    
    parts <- c(parts, sprintf("\n[Current Design]"))
    parts <- c(parts, sprintf("  Features: %d | Groups: %d", n_feat, n_groups))
    if (length(group_sizes) > 0) {
      for (grp in names(group_sizes)) {
        parts <- c(parts, sprintf("  %s: n = %d", grp, group_sizes[grp]))
      }
    }
    
    # Compute effect sizes for top features
    if (!is.null(values$stat_results) && n_groups >= 2 && length(group_sizes) >= 2) {
      stat_df <- values$stat_results
      fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      
      if (length(fc_cols) > 0 && length(p_cols) > 0) {
        fc_col <- fc_cols[1]; p_col <- p_cols[1]
        fc_vals <- suppressWarnings(abs(as.numeric(stat_df[[fc_col]])))
        fc_vals <- fc_vals[!is.na(fc_vals)]
        
        if (length(fc_vals) > 0) {
          parts <- c(parts, "\n[Effect Size Distribution (|log2FC|)]")
          parts <- c(parts, sprintf("  Median: %.2f | Mean: %.2f | Max: %.2f", median(fc_vals), mean(fc_vals), max(fc_vals)))
          parts <- c(parts, sprintf("  Large effects (|log2FC|>1): %d features", sum(fc_vals > 1)))
          parts <- c(parts, sprintf("  Medium effects (0.5-1): %d features", sum(fc_vals >= 0.5 & fc_vals <= 1)))
          parts <- c(parts, sprintf("  Small effects (<0.5): %d features", sum(fc_vals < 0.5)))
        }
      }
      
      # Quick power estimate using Cohen's d approximation
      min_n <- min(group_sizes)
      parts <- c(parts, "\n[Estimated Power at Current Sample Size]")
      parts <- c(parts, sprintf("  (Based on two-sample t-test, min group n = %d, alpha = 0.05)", min_n))
      
      effect_sizes <- c(small = 0.2, medium = 0.5, large = 0.8, very_large = 1.2)
      for (es_name in names(effect_sizes)) {
        d <- effect_sizes[es_name]
        # Approximation: power ~ Phi(d*sqrt(n/2) - z_alpha/2)
        ncp <- d * sqrt(min_n / 2)
        z_crit <- qnorm(0.975)
        power_approx <- pnorm(ncp - z_crit)
        parts <- c(parts, sprintf("  Cohen's d = %.1f (%s): ~%.0f%% power", d, es_name, 100*power_approx))
      }
      
      # Sample size recommendations
      parts <- c(parts, "\n[Recommended Sample Sizes per Group (80% power, alpha=0.05)]")
      for (es_name in names(effect_sizes)) {
        d <- effect_sizes[es_name]
        z_alpha <- qnorm(0.975); z_beta <- qnorm(0.80)
        n_needed <- ceiling(2 * ((z_alpha + z_beta) / d)^2)
        parts <- c(parts, sprintf("  d = %.1f (%s): n = %d per group needed (you have n = %d)",
                                  d, es_name, n_needed, min_n))
      }
    } else {
      parts <- c(parts, "\nRun statistical analysis first for effect-size-based power estimates.")
      if (length(group_sizes) > 0) {
        min_n <- min(group_sizes)
        parts <- c(parts, sprintf("\n[General Power Guidance for n = %d per group]", min_n))
        parts <- c(parts, sprintf("  Can reliably detect large effects (d > 0.8): %s", if(min_n >= 26) "YES" else "Likely underpowered"))
        parts <- c(parts, sprintf("  Can reliably detect medium effects (d ~ 0.5): %s", if(min_n >= 64) "YES" else "Likely underpowered"))
        parts <- c(parts, sprintf("  Can reliably detect small effects (d ~ 0.2): %s", if(min_n >= 394) "YES" else "Underpowered"))
      }
    }
    
    # Existing power analysis results
    if (!is.null(values$power_results)) {
      parts <- c(parts, "\n[Computed Power Analysis Available]")
      parts <- c(parts, "  Power analysis has been computed in the Power Analysis tab. Check there for detailed per-feature power estimates.")
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP6: Data Transformation Suggestions ---
  sp_transform_suggestions <- function() {
    parts <- c("=== DATA TRANSFORMATION RECOMMENDATIONS ===")
    if (is.null(values$normalized_data)) return("No data loaded. Please upload a dataset first.")
    
    norm_mat <- values$normalized_data
    raw_mat <- values$raw_data
    n_feat <- nrow(norm_mat)
    
    # Assess skewness on a sample
    n_check <- min(n_feat, 100)
    check_idx <- if (n_feat > 100) sample(seq_len(n_feat), 100) else seq_len(n_feat)
    skew_vals <- c(); kurt_vals <- c(); n_normal <- 0; has_negatives <- FALSE; has_zeros <- FALSE
    
    for (i in check_idx) {
      fv <- suppressWarnings(as.numeric(norm_mat[i, ]))
      fv <- fv[!is.na(fv)]
      if (any(fv < 0, na.rm = TRUE)) has_negatives <- TRUE
      if (any(fv == 0, na.rm = TRUE)) has_zeros <- TRUE
      if (length(fv) >= 3) {
        sk <- tryCatch(moments::skewness(fv), error = function(e) NA)
        kt <- tryCatch(moments::kurtosis(fv) - 3, error = function(e) NA)
        if (!is.na(sk)) skew_vals <- c(skew_vals, sk)
        if (!is.na(kt)) kurt_vals <- c(kurt_vals, kt)
        if (length(fv) <= 5000) {
          p <- tryCatch(shapiro.test(fv)$p.value, error = function(e) NA)
          if (!is.na(p) && p > 0.05) n_normal <- n_normal + 1
        }
      }
    }
    
    parts <- c(parts, "\n[Current Data Properties]")
    parts <- c(parts, sprintf("  Normal features: %d/%d (%.0f%%)", n_normal, n_check, 100*n_normal/n_check))
    if (length(skew_vals) > 0) {
      parts <- c(parts, sprintf("  Median skewness: %.2f (%.0f%% right-skewed, %.0f%% left-skewed)",
                                median(skew_vals), 100*mean(skew_vals > 0.5), 100*mean(skew_vals < -0.5)))
    }
    if (length(kurt_vals) > 0) {
      parts <- c(parts, sprintf("  Median excess kurtosis: %.2f", median(kurt_vals)))
    }
    parts <- c(parts, sprintf("  Has negative values: %s | Has zeros: %s", has_negatives, has_zeros))
    
    # Current preprocessing
    parts <- c(parts, "\n[Current Preprocessing Applied]")
    if (!is.null(input$normalization)) parts <- c(parts, sprintf("  Normalization: %s", input$normalization))
    if (!is.null(input$imputation)) parts <- c(parts, sprintf("  Imputation: %s", input$imputation))
    if (!is.null(input$batch_correction)) parts <- c(parts, sprintf("  Batch correction: %s", input$batch_correction))
    
    # Recommendations
    parts <- c(parts, "\n[Transformation Recommendations]")
    if (length(skew_vals) > 0 && median(skew_vals) > 1) {
      parts <- c(parts, "  HIGH RIGHT SKEW detected:")
      if (!has_negatives) {
        parts <- c(parts, "  - Log2 transformation recommended (most common for omics data)")
        if (has_zeros) parts <- c(parts, "  - Add small constant before log (e.g., log2(x + 1))")
      } else {
        parts <- c(parts, "  - Cube root or rank-based inverse normal transformation (data has negatives)")
      }
    } else if (length(skew_vals) > 0 && median(skew_vals) < -1) {
      parts <- c(parts, "  LEFT SKEW detected: Square or exponential transformation may help")
    } else {
      parts <- c(parts, "  Skewness is moderate. Current transformations may be adequate.")
    }
    
    if (100*n_normal/n_check < 40) {
      parts <- c(parts, "\n  LOW NORMALITY (<40%): Consider:")
      parts <- c(parts, "  - Quantile normalization (forces normal distribution)")
      parts <- c(parts, "  - Rank-based inverse normal transformation")
      parts <- c(parts, "  - Use non-parametric statistical tests instead")
    }
    
    # Normalization recommendations
    parts <- c(parts, "\n[Normalization Method Recommendations]")
    parts <- c(parts, "  - Quantile normalization: Best for reducing technical variation across samples")
    parts <- c(parts, "  - Median centering: Good when samples have different global intensity")
    parts <- c(parts, "  - VSN (Variance Stabilizing): Good for heteroscedastic data")
    
    # Scaling
    parts <- c(parts, "\n[Scaling Recommendations]")
    parts <- c(parts, "  - Auto-scaling (z-score): Recommended for PCA, heatmaps, ML")
    parts <- c(parts, "  - Pareto scaling: Less aggressive, preserves more structure")
    parts <- c(parts, "  - Range scaling: Useful when features have very different ranges")
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP7: Automated Result Summary ---
  sp_result_summary <- function() {
    parts <- c("=== COMPREHENSIVE ANALYSIS RESULTS SUMMARY ===")
    if (is.null(values$normalized_data)) return("No data loaded. Please upload a dataset first.")
    
    n_feat <- nrow(values$normalized_data)
    n_samp <- ncol(values$normalized_data)
    parts <- c(parts, sprintf("Dataset: %d features x %d samples | Groups: %s", 
                              n_feat, n_samp, paste(values$unique_groups, collapse = ", ")))
    
    # Statistical Results
    if (!is.null(values$stat_results) && nrow(values$stat_results) > 0) {
      stat_df <- values$stat_results
      p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      
      sig_col <- if (length(fdr_cols) > 0) fdr_cols[1] else if (length(p_cols) > 0) p_cols[1] else NULL
      if (!is.null(sig_col)) {
        n_sig <- sum(stat_df[[sig_col]] < 0.05, na.rm = TRUE)
        parts <- c(parts, sprintf("\n[Statistical Analysis] %d significant features (p/FDR < 0.05 using %s)",
                                  n_sig, sig_col))
        parts <- c(parts, sprintf("  Significance: p<0.001: %d | p<0.01: %d | p<0.05: %d",
                                  sum(stat_df[[sig_col]] < 0.001, na.rm = TRUE),
                                  sum(stat_df[[sig_col]] < 0.01, na.rm = TRUE), n_sig))
      }
      if (length(fc_cols) > 0) {
        fc_vals <- suppressWarnings(as.numeric(stat_df[[fc_cols[1]]]))
        fc_vals <- fc_vals[!is.na(fc_vals)]
        if (length(fc_vals) > 0) {
          parts <- c(parts, sprintf("  Upregulated (log2FC>0): %d | Downregulated: %d",
                                    sum(fc_vals > 0), sum(fc_vals < 0)))
          parts <- c(parts, sprintf("  Strong changes (|log2FC|>1): %d features", sum(abs(fc_vals) > 1)))
        }
      }
    }
    
    # PCA
    if (!is.null(values$pca_result)) {
      pca <- values$pca_result
      var_exp <- summary(pca)$importance[2, 1:min(3, ncol(pca$x))] * 100
      parts <- c(parts, sprintf("\n[PCA] Variance explained: PC1=%.1f%%, PC2=%.1f%%",
                                var_exp[1], if(length(var_exp)>=2) var_exp[2] else 0))
    }
    
    # ML Results
    if (!is.null(values$ml_results) && !is.null(values$ml_selected_features)) {
      ml_df <- values$ml_selected_features
      parts <- c(parts, sprintf("\n[Machine Learning] Method: %s | Features selected: %d",
                                values$ml_method_used %||% "unknown", nrow(ml_df)))
      top_ml <- head(ml_df, 5)
      if (nrow(top_ml) > 0) {
        imp_col <- grep("importance|score|coefficient", colnames(top_ml), value = TRUE, ignore.case = TRUE)
        feat_col <- grep("feature|variable|name", colnames(top_ml), value = TRUE, ignore.case = TRUE)
        if (length(feat_col) > 0 && length(imp_col) > 0) {
          for (j in seq_len(nrow(top_ml))) {
            parts <- c(parts, sprintf("  %d. %s (importance: %.3f)", j, top_ml[[feat_col[1]]][j], top_ml[[imp_col[1]]][j]))
          }
        }
      }
    }
    
    # Enrichment
    if (!is.null(values$enrichment_results) && length(values$enrichment_results) > 0) {
      enrich_df <- if (is.data.frame(values$enrichment_results)) values$enrichment_results else NULL
      if (!is.null(enrich_df) && nrow(enrich_df) > 0) {
        parts <- c(parts, sprintf("\n[Enrichment] %d enriched terms found", nrow(enrich_df)))
        p_col_e <- grep("pvalue|p.value|P.Value|FDR", colnames(enrich_df), value = TRUE, ignore.case = TRUE)
        term_col <- grep("term|description|pathway|name", colnames(enrich_df), value = TRUE, ignore.case = TRUE)
        if (length(term_col) > 0 && length(p_col_e) > 0) {
          top_e <- head(enrich_df[order(enrich_df[[p_col_e[1]]]), ], 5)
          for (j in seq_len(nrow(top_e))) {
            parts <- c(parts, sprintf("  %d. %s (p=%.2e)", j, top_e[[term_col[1]]][j], top_e[[p_col_e[1]]][j]))
          }
        }
      }
    }
    
    # ROC
    if (!is.null(values$roc_results) && is.data.frame(values$roc_results) && nrow(values$roc_results) > 0) {
      roc_df <- values$roc_results
      auc_col <- grep("AUC|auc", colnames(roc_df), value = TRUE, ignore.case = TRUE)
      if (length(auc_col) > 0) {
        top_roc <- head(roc_df[order(roc_df[[auc_col[1]]], decreasing = TRUE), ], 5)
        parts <- c(parts, sprintf("\n[ROC/PR] Top %d features by AUC:", nrow(top_roc)))
        feat_col_r <- grep("feature|variable|name", colnames(top_roc), value = TRUE, ignore.case = TRUE)
        if (length(feat_col_r) > 0) {
          for (j in seq_len(nrow(top_roc))) {
            parts <- c(parts, sprintf("  %d. %s (AUC: %.3f)", j, top_roc[[feat_col_r[1]]][j], top_roc[[auc_col[1]]][j]))
          }
        }
      }
    }
    
    # Multi-omics
    if (!is.null(values$integration_result)) {
      parts <- c(parts, sprintf("\n[Multi-Omics Integration] Method: %s", values$integration_result$method %||% "unknown"))
    }
    
    # Power
    if (!is.null(values$power_results)) {
      parts <- c(parts, "\n[Power Analysis] Completed - see Power Analysis tab for details")
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP8: Biological Context ---
  sp_bio_context <- function() {
    parts <- c("=== BIOLOGICAL CONTEXT & PATHWAY GUIDANCE ===")
    if (is.null(values$stat_results)) return("Run statistical analysis first to identify significant features for biological interpretation.")
    
    stat_df <- values$stat_results
    p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
    fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
    fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
    sig_col <- if (length(fdr_cols) > 0) fdr_cols[1] else if (length(p_cols) > 0) p_cols[1] else NULL
    
    if (!is.null(sig_col)) {
      sig_features <- stat_df[stat_df[[sig_col]] < 0.05, , drop = FALSE]
      n_sig <- nrow(sig_features)
      parts <- c(parts, sprintf("\n%d significant features identified for biological context", n_sig))
      
      # Separate up/down if fold change available
      if (length(fc_cols) > 0) {
        fc_vals <- suppressWarnings(as.numeric(sig_features[[fc_cols[1]]]))
        n_up <- sum(fc_vals > 0, na.rm = TRUE); n_down <- sum(fc_vals < 0, na.rm = TRUE)
        parts <- c(parts, sprintf("  Upregulated: %d | Downregulated: %d", n_up, n_down))
      }
      
      # Feature names for pathway queries
      feat_names <- head(rownames(sig_features), 30)
      if (!is.null(values$cleaned_molecules)) {
        idx_match <- match(feat_names, rownames(stat_df))
        idx_match <- idx_match[!is.na(idx_match)]
        if (length(idx_match) > 0) {
          feat_names <- values$cleaned_molecules[idx_match]
        }
      }
      parts <- c(parts, sprintf("\n[Top Significant Features for Pathway Analysis]"))
      parts <- c(parts, paste("  ", head(feat_names, 30), collapse = "\n"))
    }
    
    # Enrichment results if available
    if (!is.null(values$enrichment_results) && is.data.frame(values$enrichment_results) && nrow(values$enrichment_results) > 0) {
      parts <- c(parts, "\n[Enrichment Results Available]")
      parts <- c(parts, "  Enrichment analysis has been completed. Results integrated into context.")
    }
    
    parts <- c(parts, "\n[Recommended Databases for Further Investigation]")
    parts <- c(parts, "  - Gene Ontology (GO): Biological process, molecular function, cellular component")
    parts <- c(parts, "  - KEGG: Metabolic & signaling pathways")
    parts <- c(parts, "  - Reactome: Curated pathway database")
    parts <- c(parts, "  - STRING: Protein-protein interactions")
    parts <- c(parts, "  - UniProt: Protein function & structure")
    parts <- c(parts, "  - HMDB: Human Metabolome Database (for metabolomics)")
    parts <- c(parts, "  - GlyConnect/GlyGen: Glycan databases (for glycomics)")
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP9: Multiple Testing Interpretation ---
  sp_multiple_testing <- function() {
    parts <- c("=== MULTIPLE TESTING INTERPRETATION ===")
    if (is.null(values$stat_results)) return("Run statistical analysis first.")
    
    stat_df <- values$stat_results
    n_feat <- nrow(stat_df)
    p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
    fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
    
    if (length(p_cols) > 0) {
      raw_p <- stat_df[[p_cols[1]]]
      raw_p <- raw_p[!is.na(raw_p)]
      parts <- c(parts, sprintf("\n[Raw P-values (%s)]", p_cols[1]))
      parts <- c(parts, sprintf("  Total tests: %d", length(raw_p)))
      parts <- c(parts, sprintf("  Significant at p<0.05: %d (%.1f%%)", sum(raw_p < 0.05), 100*mean(raw_p < 0.05)))
      parts <- c(parts, sprintf("  Expected false positives at p<0.05: %.0f (5%% of %d)", 0.05*length(raw_p), length(raw_p)))
      
      # Bonferroni
      bonf_threshold <- 0.05 / length(raw_p)
      n_bonf <- sum(raw_p < bonf_threshold)
      parts <- c(parts, sprintf("\n[Bonferroni Correction]"))
      parts <- c(parts, sprintf("  Adjusted threshold: %.2e", bonf_threshold))
      parts <- c(parts, sprintf("  Significant features: %d", n_bonf))
      parts <- c(parts, "  Note: Very conservative - controls family-wise error rate (FWER)")
    }
    
    if (length(fdr_cols) > 0) {
      fdr_vals <- stat_df[[fdr_cols[1]]]
      fdr_vals <- fdr_vals[!is.na(fdr_vals)]
      parts <- c(parts, sprintf("\n[FDR / Adjusted P-values (%s)]", fdr_cols[1]))
      parts <- c(parts, sprintf("  FDR < 0.01: %d features", sum(fdr_vals < 0.01)))
      parts <- c(parts, sprintf("  FDR < 0.05: %d features", sum(fdr_vals < 0.05)))
      parts <- c(parts, sprintf("  FDR < 0.10: %d features", sum(fdr_vals < 0.10)))
      parts <- c(parts, sprintf("  FDR < 0.20: %d features", sum(fdr_vals < 0.20)))
      parts <- c(parts, "\n  Interpretation: At FDR < 0.05, up to 5%% of declared significant features may be false positives.")
    }
    
    parts <- c(parts, "\n[Practical Guidance]")
    parts <- c(parts, "  - FDR < 0.05: Standard threshold for discovery-based studies")
    parts <- c(parts, "  - FDR < 0.01: Stringent; good for high-confidence hits")
    parts <- c(parts, "  - FDR < 0.10: Relaxed; acceptable for exploratory analyses")
    parts <- c(parts, "  - Combine FDR with fold-change cutoffs for biologically meaningful results")
    if (length(p_cols) > 0) {
      pi0 <- mean(raw_p > 0.5) * 2
      pi0 <- min(max(pi0, 0), 1)
      parts <- c(parts, sprintf("\n[Estimated Proportion of True Nulls] ~%.0f%%", 100*pi0))
      parts <- c(parts, sprintf("  Estimated truly differential features: ~%.0f", n_feat * (1 - pi0)))
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP10: Pipeline Generation ---
  sp_pipeline_generation <- function() {
    parts <- c("=== R ANALYSIS PIPELINE CONTEXT ===")
    if (is.null(values$normalized_data)) return("No data loaded. Pipeline generation requires an active dataset.")
    
    n_feat <- nrow(values$normalized_data)
    n_samp <- ncol(values$normalized_data)
    n_groups <- length(values$unique_groups)
    
    parts <- c(parts, sprintf("\n[Dataset for Pipeline]"))
    parts <- c(parts, sprintf("  Features: %d | Samples: %d | Groups: %d (%s)",
                              n_feat, n_samp, n_groups, paste(values$unique_groups, collapse = ", ")))
    
    # Current preprocessing
    parts <- c(parts, "\n[Current Preprocessing Settings]")
    parts <- c(parts, sprintf("  Normalization: %s", input$normalization %||% "none"))
    parts <- c(parts, sprintf("  Imputation: %s", input$imputation %||% "none"))
    parts <- c(parts, sprintf("  Batch correction: %s", input$batch_correction %||% "none"))
    
    # Statistical method
    parts <- c(parts, sprintf("  Statistical method: %s", input$sig_method %||% "not set"))
    parts <- c(parts, sprintf("  P-value cutoff: %s", input$p_value_cutoff %||% "0.05"))
    parts <- c(parts, sprintf("  Fold change cutoff: %s", input$fc_cutoff %||% "1"))
    
    # Analyses completed
    parts <- c(parts, "\n[Analyses Completed]")
    if (!is.null(values$stat_results)) parts <- c(parts, "  ✓ Statistical testing")
    if (!is.null(values$pca_result)) parts <- c(parts, "  ✓ PCA")
    if (!is.null(values$ml_results)) parts <- c(parts, sprintf("  ✓ ML (%s)", values$ml_method_used %||% "unknown"))
    if (!is.null(values$enrichment_results)) parts <- c(parts, "  ✓ Enrichment analysis")
    if (!is.null(values$roc_data)) parts <- c(parts, "  ✓ ROC/PR analysis")
    if (!is.null(values$integration_result)) parts <- c(parts, "  ✓ Multi-omics integration")
    if (!is.null(values$power_results)) parts <- c(parts, "  ✓ Power analysis")
    
    parts <- c(parts, "\n[INSTRUCTION TO AI] Generate a complete reproducible R script that replicates the user's analysis pipeline")
    parts <- c(parts, "  using standard R/Bioconductor packages. Include data loading, preprocessing, statistical analysis,")
    parts <- c(parts, "  visualization, and all completed analyses above. Make it well-commented and publication-ready.")
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP11: Batch Processing ---
