  # --- SP12: Report Generation ---
  sp_report_generation <- function() {
    parts <- c("=== ANALYSIS REPORT COMPILATION ===")
    if (is.null(values$normalized_data)) return("No data loaded. Report generation requires an active dataset.")
    
    # Gather all results
    report_sections <- c()
    
    # Dataset overview
    n_feat <- nrow(values$normalized_data)
    n_samp <- ncol(values$normalized_data)
    report_sections <- c(report_sections, sprintf("DATASET: %d features x %d samples", n_feat, n_samp))
    report_sections <- c(report_sections, sprintf("GROUPS: %s", paste(values$unique_groups, collapse = ", ")))
    if (!is.null(values$group_column_indices)) {
      for (grp in names(values$group_column_indices)) {
        report_sections <- c(report_sections, sprintf("  %s: n=%d", grp, length(values$group_column_indices[[grp]])))
      }
    }
    report_sections <- c(report_sections, sprintf("PREPROCESSING: Normalization=%s, Imputation=%s",
                                                  input$normalization %||% "none", input$imputation %||% "none"))
    
    # Statistical results summary
    if (!is.null(values$stat_results) && nrow(values$stat_results) > 0) {
      stat_df <- values$stat_results
      p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      sig_col <- if (length(fdr_cols) > 0) fdr_cols[1] else if (length(p_cols) > 0) p_cols[1] else NULL
      
      report_sections <- c(report_sections, sprintf("\nSTATISTICAL METHOD: %s", input$sig_method %||% "unknown"))
      if (!is.null(sig_col)) {
        n_sig <- sum(stat_df[[sig_col]] < 0.05, na.rm = TRUE)
        report_sections <- c(report_sections, sprintf("SIGNIFICANT FEATURES: %d/%d (%.1f%%)", n_sig, nrow(stat_df), 100*n_sig/nrow(stat_df)))
        
        # Top 15 features
        sorted_df <- stat_df[order(stat_df[[sig_col]]), ]
        top15 <- head(sorted_df, 15)
        report_sections <- c(report_sections, "\nTOP 15 FEATURES:")
        for (j in seq_len(nrow(top15))) {
          fname <- rownames(top15)[j]
          pval <- top15[[sig_col]][j]
          fc_str <- ""
          if (length(fc_cols) > 0) {
            fc_val <- suppressWarnings(as.numeric(top15[[fc_cols[1]]][j]))
            if (!is.na(fc_val)) fc_str <- sprintf(" | log2FC=%.2f", fc_val)
          }
          report_sections <- c(report_sections, sprintf("  %d. %s (p=%.2e%s)", j, fname, pval, fc_str))
        }
      }
    }
    
    # PCA
    if (!is.null(values$pca_result)) {
      pca <- values$pca_result
      var_exp <- summary(pca)$importance[2, 1:min(5, ncol(pca$x))] * 100
      report_sections <- c(report_sections, "\nPCA RESULTS:")
      for (pc_i in seq_along(var_exp)) {
        report_sections <- c(report_sections, sprintf("  PC%d: %.1f%% variance explained", pc_i, var_exp[pc_i]))
      }
    }
    
    # ML
    if (!is.null(values$ml_selected_features) && nrow(values$ml_selected_features) > 0) {
      report_sections <- c(report_sections, sprintf("\nMACHINE LEARNING: %s", values$ml_method_used %||% "unknown"))
      report_sections <- c(report_sections, sprintf("  Features selected: %d", nrow(values$ml_selected_features)))
    }
    
    # Enrichment
    if (!is.null(values$enrichment_results) && is.data.frame(values$enrichment_results) && nrow(values$enrichment_results) > 0) {
      report_sections <- c(report_sections, sprintf("\nENRICHMENT: %d terms enriched", nrow(values$enrichment_results)))
    }
    
    parts <- c(parts, paste(report_sections, collapse = "\n"))
    parts <- c(parts, "\n\n[INSTRUCTION TO AI] Format all the above into a well-structured, publication-ready analysis report")
    parts <- c(parts, "  with the following sections: Introduction, Methods, Results, Discussion, and Conclusions.")
    parts <- c(parts, "  Include interpretation of all findings and statistical context. Write it as a scientific report.")
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP14: Experimental Design Validation ---
  sp_design_validation <- function() {
    parts <- c("=== EXPERIMENTAL DESIGN VALIDATION ===")
    if (is.null(values$normalized_data)) return("No data loaded. Design validation requires an active dataset.")
    
    n_samp <- ncol(values$normalized_data)
    n_groups <- length(values$unique_groups)
    group_sizes <- if (!is.null(values$group_column_indices)) sapply(values$group_column_indices, length) else integer(0)
    
    parts <- c(parts, sprintf("\n[Design Overview]"))
    parts <- c(parts, sprintf("  Total samples: %d | Groups: %d", n_samp, n_groups))
    
    # Balance assessment
    if (length(group_sizes) >= 2) {
      parts <- c(parts, "\n[Group Balance]")
      for (grp in names(group_sizes)) {
        parts <- c(parts, sprintf("  %s: n = %d", grp, group_sizes[grp]))
      }
      ratio <- max(group_sizes) / min(group_sizes)
      parts <- c(parts, sprintf("  Max/Min ratio: %.2f", ratio))
      if (ratio > 2) {
        parts <- c(parts, "  WARNING: Severely unbalanced design (ratio > 2:1). Consider:")
        parts <- c(parts, "    - Using non-parametric tests")
        parts <- c(parts, "    - Weighted analyses")
        parts <- c(parts, "    - Subsampling the larger group")
      } else if (ratio > 1.5) {
        parts <- c(parts, "  CAUTION: Moderately unbalanced. Use Welch's corrections.")
      } else {
        parts <- c(parts, "  OK: Reasonably balanced design")
      }
    }
    
    # Sample size adequacy
    min_n <- if (length(group_sizes) > 0) min(group_sizes) else n_samp
    parts <- c(parts, "\n[Sample Size Adequacy]")
    if (min_n < 3) {
      parts <- c(parts, "  CRITICAL: Fewer than 3 samples in a group. Statistical testing unreliable.")
    } else if (min_n < 5) {
      parts <- c(parts, "  WARNING: Very small group sizes. Limited statistical power.")
      parts <- c(parts, "    - Use exact tests or permutation-based methods")
      parts <- c(parts, "    - Results should be considered exploratory")
    } else if (min_n < 10) {
      parts <- c(parts, "  CAUTION: Small-to-moderate group sizes. May miss subtle effects.")
    } else {
      parts <- c(parts, "  OK: Adequate sample sizes for standard statistical methods")
    }
    
    # Metadata quality check
    if (!is.null(values$metadata) && is.data.frame(values$metadata)) {
      meta <- values$metadata
      parts <- c(parts, sprintf("\n[Metadata] %d columns: %s", ncol(meta), paste(colnames(meta), collapse = ", ")))
      
      # Check for potential confounders
      potential_confounders <- grep("batch|plate|run|date|operator|site|center", colnames(meta), value = TRUE, ignore.case = TRUE)
      if (length(potential_confounders) > 0) {
        parts <- c(parts, sprintf("  Potential confounders detected: %s", paste(potential_confounders, collapse = ", ")))
        parts <- c(parts, "  Recommendation: Check if confounders are balanced across experimental groups")
      }
      
      # Check for missing metadata
      meta_miss <- colSums(is.na(meta) | meta == "")
      if (any(meta_miss > 0)) {
        parts <- c(parts, "  Metadata columns with missing values:")
        for (col in names(meta_miss[meta_miss > 0])) {
          parts <- c(parts, sprintf("    %s: %d missing", col, meta_miss[col]))
        }
      }
    }
    
    # Replicate structure
    parts <- c(parts, "\n[Replication Assessment]")
    if (n_groups >= 2 && min_n >= 3) {
      parts <- c(parts, sprintf("  Biological replicates per group: %d - %d", min(group_sizes), max(group_sizes)))
      parts <- c(parts, "  Technical replicates: Unknown (check metadata for replicate identifiers)")
    }
    
    paste(parts, collapse = "\n")
  }
  
  # --- SP15: Comparison Recommendations ---
  sp_comparison_recommendations <- function() {
    parts <- c("=== COMPARISON RECOMMENDATIONS ===")
    if (is.null(values$normalized_data)) return("No data loaded.")
    
    groups <- values$unique_groups
    n_groups <- length(groups)
    group_sizes <- if (!is.null(values$group_column_indices)) sapply(values$group_column_indices, length) else integer(0)
    
    parts <- c(parts, sprintf("\n[Available Groups] %d groups: %s", n_groups, paste(groups, collapse = ", ")))
    if (length(group_sizes) > 0) {
      for (grp in names(group_sizes)) {
        parts <- c(parts, sprintf("  %s: n = %d", grp, group_sizes[grp]))
      }
    }
    
    # Current comparison
    if (!is.null(input$group_1) && !is.null(input$group_2)) {
      parts <- c(parts, sprintf("\n[Current Comparison] %s vs %s", input$group_1, input$group_2))
    }
    
    # Generate all pairwise comparisons
    if (n_groups >= 2) {
      parts <- c(parts, sprintf("\n[All Possible Pairwise Comparisons] %d total:", choose(n_groups, 2)))
      combo_idx <- 0
      for (i in seq_len(n_groups - 1)) {
        for (j in (i+1):n_groups) {
          combo_idx <- combo_idx + 1
          n1 <- if (groups[i] %in% names(group_sizes)) group_sizes[groups[i]] else "?"
          n2 <- if (groups[j] %in% names(group_sizes)) group_sizes[groups[j]] else "?"
          parts <- c(parts, sprintf("  %d. %s (n=%s) vs %s (n=%s)", combo_idx, groups[i], n1, groups[j], n2))
        }
      }
    }
    
    # Statistical results for current comparison
    if (!is.null(values$stat_results) && nrow(values$stat_results) > 0) {
      stat_df <- values$stat_results
      p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
      sig_col <- if (length(p_cols) > 0) p_cols[1] else NULL
      if (!is.null(sig_col)) {
        n_sig <- sum(stat_df[[sig_col]] < 0.05, na.rm = TRUE)
        parts <- c(parts, sprintf("\n[Current Comparison Results] %d significant features", n_sig))
      }
    }
    
    # Multi-group recommendations
    if (n_groups > 2) {
      parts <- c(parts, "\n[Multi-Group Recommendations]")
      parts <- c(parts, "  - Run ANOVA/Kruskal-Wallis first for global differences")
      parts <- c(parts, "  - Follow up with post-hoc pairwise tests (Tukey HSD or Dunn's)")
      parts <- c(parts, "  - Consider control-vs-all comparisons if a reference group exists")
      
      # Look for control group
      control_patterns <- grep("control|ctrl|baseline|normal|healthy|wt|wild", groups, value = TRUE, ignore.case = TRUE)
      if (length(control_patterns) > 0) {
        parts <- c(parts, sprintf("  Potential control group detected: '%s'", control_patterns[1]))
        parts <- c(parts, "  Recommended: Compare each treatment group against this control")
      }
    }
    
    parts <- c(parts, "\n[INSTRUCTION TO AI] Based on the group structure and any metadata available,")
    parts <- c(parts, "  suggest the most scientifically meaningful comparisons and explain the rationale.")
    
    paste(parts, collapse = "\n")
  }

  # Function to gather comprehensive context information from ALL page elements
  get_context_info <- function() {
    context_parts <- c()
    resolve_feature_label <- function(row_name, row_index = NA_integer_, stat_df_local = NULL) {
      if (is.null(stat_df_local)) return(row_name %||% "")
      candidate_label <- row_name %||% ""
      if ((is.na(row_index) || row_index < 1 || row_index > nrow(stat_df_local)) &&
          !is.null(row_name) && grepl("^feature\\s*\\d+$", row_name, ignore.case = TRUE)) {
        parsed_idx <- suppressWarnings(as.integer(gsub("[^0-9]", "", row_name)))
        if (!is.na(parsed_idx)) row_index <- parsed_idx
      }
      if (!is.na(row_index) && row_index >= 1 && row_index <= nrow(stat_df_local)) {
        name_cols <- grep("(feature|gene|metabolite|protein|compound|analyte|symbol|name)$", colnames(stat_df_local), value = TRUE, ignore.case = TRUE)
        name_cols <- setdiff(name_cols, c("feature_count", "feature_source", "feature_index"))
        if (length(name_cols) > 0) {
          for (col in name_cols) {
            val <- stat_df_local[[col]][row_index]
            if (is.factor(val)) val <- as.character(val)
            if (!is.null(val) && !is.na(val) && nzchar(val) && !grepl("^feature\\s*\\d+$", val, ignore.case = TRUE)) {
              candidate_label <- as.character(val)
              break
            }
          }
        }
        if ((is.null(candidate_label) || candidate_label == "" || grepl("^feature\\s*\\d+$", candidate_label, ignore.case = TRUE)) &&
            !is.null(values$cleaned_molecules) && row_index <= length(values$cleaned_molecules)) {
          cm_val <- values$cleaned_molecules[row_index]
          if (is.factor(cm_val)) cm_val <- as.character(cm_val)
          if (!is.null(cm_val) && !is.na(cm_val) && nzchar(cm_val)) {
            candidate_label <- cm_val
          }
        }
      }
      if (is.null(candidate_label) || candidate_label == "") candidate_label <- row_name %||% "Unknown feature"
      candidate_label
    }
    
    # ===== BASIC DATASET INFORMATION =====
    if (!is.null(values$normalized_data)) {
      n_features <- nrow(values$normalized_data)
      n_samples <- ncol(values$normalized_data)
      context_parts <- c(context_parts, "=== DATASET OVERVIEW ===")
      context_parts <- c(context_parts, sprintf("Total features: %d", n_features))
      context_parts <- c(context_parts, sprintf("Total samples: %d", n_samples))
      
      # Feature names
      if (!is.null(rownames(values$normalized_data))) {
        sample_features <- head(rownames(values$normalized_data), 20)
        context_parts <- c(context_parts, sprintf("Sample features: %s", paste(sample_features, collapse = ", ")))
      }
    }
    
    # ===== GROUP INFORMATION =====
    if (!is.null(values$unique_groups) && length(values$unique_groups) > 0) {
      context_parts <- c(context_parts, "\n=== GROUP INFORMATION ===")
      context_parts <- c(context_parts, sprintf("Groups: %s", paste(values$unique_groups, collapse = ", ")))
      
      # Sample counts per group
      if (!is.null(values$group_column_indices)) {
        for (grp in names(values$group_column_indices)) {
          n_samples_in_group <- length(values$group_column_indices[[grp]])
          context_parts <- c(context_parts, sprintf("  %s: %d samples", grp, n_samples_in_group))
        }
      }
    }
    
    # ===== CURRENT TAB =====
    if (!is.null(input$navbar)) {
      context_parts <- c(context_parts, sprintf("\n=== CURRENT TAB: %s ===", input$navbar))
    }
    
    # ===== PREPROCESSING SETTINGS =====
    context_parts <- c(context_parts, "\n=== PREPROCESSING ===")
    if (!is.null(input$normalization) && input$normalization != "") {
      context_parts <- c(context_parts, sprintf("Normalization: %s", input$normalization))
    }
    if (!is.null(input$imputation) && input$imputation != "") {
      context_parts <- c(context_parts, sprintf("Imputation: %s", input$imputation))
    }
    if (!is.null(input$batch_correction) && input$batch_correction != "") {
      context_parts <- c(context_parts, sprintf("Batch correction: %s", input$batch_correction))
    }
    
    # ===== USER-UPLOADED FILE SUMMARIES (JIBOSKY) =====
    if (!is.null(jibosky_file_summaries()) && nzchar(jibosky_file_summaries())) {
      context_parts <- c(context_parts, "\n=== USER-UPLOADED FILES ===")
      context_parts <- c(context_parts, jibosky_file_summaries())
    }

    # ===== COMPLETED ANALYSES SUMMARY =====
    # This section helps Jibosky know what analyses have been completed regardless of current tab
    context_parts <- c(context_parts, "\n=== COMPLETED ANALYSES SUMMARY ===")
    analyses_completed <- c()
    
    # Statistical analysis
    if (!is.null(values$stat_results) && nrow(values$stat_results) > 0) {
      analyses_completed <- c(analyses_completed, sprintf("Statistical Analysis (%d features tested)", nrow(values$stat_results)))
    }
    
    # PCA
    if (!is.null(values$pca_result)) {
      analyses_completed <- c(analyses_completed, "PCA (Principal Component Analysis)")
    }
    
    # sPCA
    tryCatch({
      if (!is.null(values$spca_result)) {
        analyses_completed <- c(analyses_completed, "sPCA (Sparse PCA)")
      }
    }, error = function(e) NULL)
    
    # UMAP
    if (!is.null(values$umap_result)) {
      analyses_completed <- c(analyses_completed, "UMAP")
    }
    
    # t-SNE
    if (!is.null(values$tsne_result)) {
      analyses_completed <- c(analyses_completed, "t-SNE")
    }
    
    # Machine Learning
    if (!is.null(values$ml_results)) {
      analyses_completed <- c(analyses_completed, "Machine Learning Analysis")
    }
    
    # Enrichment Analysis
    if (!is.null(values$enrichment_results) && length(values$enrichment_results) > 0) {
      analyses_completed <- c(analyses_completed, "Enrichment Analysis")
    }
    
    # Glycomics
    if (!is.null(values$glycomics_parsed)) {
      analyses_completed <- c(analyses_completed, "Glycomics Analysis")
    }
    
    # ROC/PR Analysis
    if (!is.null(values$roc_data)) {
      analyses_completed <- c(analyses_completed, "ROC/PR Analysis")
    }
    
    # Intersection Analysis
    if (!is.null(values$intersection_results)) {
      analyses_completed <- c(analyses_completed, "Intersection Analysis")
    }
    
    # Multi-Omics Integration
    if (!is.null(values$integration_result)) {
      analyses_completed <- c(analyses_completed, sprintf("Multi-Omics Integration (%s method)", 
                                                          values$integration_result$method %||% "unknown"))
    }
    
    # Power Analysis
    if (!is.null(values$power_results)) {
      analyses_completed <- c(analyses_completed, "Power Analysis")
    }
    
    # Metabolomics
    if (!is.null(metab_values$classification_data) && nrow(metab_values$classification_data) > 0) {
      analyses_completed <- c(analyses_completed, "Metabolomics Classification")
    }
    
    if (length(analyses_completed) > 0) {
      for (analysis in analyses_completed) {
        context_parts <- c(context_parts, sprintf("✓ %s", analysis))
      }
    } else {
      context_parts <- c(context_parts, "No analyses completed yet")
    }
    
    # ===== STATISTICAL ANALYSIS SETTINGS =====
    if (!is.null(input$sig_method) && input$sig_method != "") {
      context_parts <- c(context_parts, "\n=== STATISTICAL ANALYSIS ===")
      context_parts <- c(context_parts, sprintf("Statistical method: %s", input$sig_method))
      
      if (!is.null(input$p_value_cutoff)) {
        context_parts <- c(context_parts, sprintf("P-value cutoff: %.3f", input$p_value_cutoff))
      }
      if (!is.null(input$fc_cutoff)) {
        context_parts <- c(context_parts, sprintf("Fold change cutoff: %.2f", input$fc_cutoff))
      }
    }
    
    # ===== DETAILED STATISTICAL RESULTS (MOST IMPORTANT!) =====
    # Always include statistical outputs once available so Jibosky can reference them even when the chat tab is active
    if (!is.null(values$stat_results)) {
      tryCatch({
        stat_df <- values$stat_results
        context_parts <- c(context_parts, "\n=== COMPLETE STATISTICAL RESULTS ===")
        
        # Comparison information
        if (!is.null(input$group_1) && !is.null(input$group_2)) {
          context_parts <- c(context_parts, sprintf("Comparison: %s vs %s", input$group_1, input$group_2))
        }
        
        # Column information
        context_parts <- c(context_parts, sprintf("Available columns: %s", paste(colnames(stat_df), collapse = ", ")))
        
        # Find relevant columns
        p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        mean_cols <- grep("_mean$|_Mean$|_average", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        
        # Report what we found
        if (length(p_cols) > 0) context_parts <- c(context_parts, sprintf("P-value columns: %s", paste(p_cols, collapse = ", ")))
        if (length(fdr_cols) > 0) context_parts <- c(context_parts, sprintf("FDR columns: %s", paste(fdr_cols, collapse = ", ")))
        if (length(fc_cols) > 0) context_parts <- c(context_parts, sprintf("Fold change columns: %s", paste(fc_cols, collapse = ", ")))
        
        # Check for bootstrap columns
        bootstrap_cols <- grep("Bootstrap", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        if (length(bootstrap_cols) > 0) {
          context_parts <- c(context_parts, sprintf("Bootstrap columns: %s", paste(bootstrap_cols, collapse = ", ")))
          context_parts <- c(context_parts, sprintf("Bootstrap analysis was performed with %d replicates",
                                                    ifelse(!is.null(input$bootstrap_replicates), input$bootstrap_replicates, "unknown")))
        }
        
        # Check for ANOVA columns
        anova_cols <- grep("ANOVA", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        if (length(anova_cols) > 0) {
          context_parts <- c(context_parts, sprintf("ANOVA columns: %s", paste(anova_cols, collapse = ", ")))
          if ("ANOVA_PValue" %in% colnames(stat_df)) {
            anova_pvals <- stat_df$ANOVA_PValue
            n_anova_sig <- sum(anova_pvals < 0.05, na.rm = TRUE)
            context_parts <- c(context_parts, sprintf("ANOVA: %d features significant at p < 0.05", n_anova_sig))
          }
        }
        
        # Check for post-hoc test columns
        posthoc_cols <- grep("PostHoc", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        if (length(posthoc_cols) > 0) {
          context_parts <- c(context_parts, sprintf("Post-hoc test columns: %s", paste(head(posthoc_cols, 5), collapse = ", ")))
          if (length(posthoc_cols) > 5) {
            context_parts <- c(context_parts, sprintf("... and %d more post-hoc columns", length(posthoc_cols) - 5))
          }
          if ("PostHoc_Method" %in% colnames(stat_df)) {
            posthoc_method <- unique(stat_df$PostHoc_Method)
            context_parts <- c(context_parts, sprintf("Post-hoc method used: %s", paste(posthoc_method, collapse = ", ")))
          }
        }
        
        # Choose a primary fold-change column that actually contains numeric values
        fc_col_primary <- NULL
        if (length(fc_cols) > 0) {
          for (candidate in fc_cols) {
            if (!candidate %in% colnames(stat_df)) next
            candidate_vals <- suppressWarnings(as.numeric(stat_df[[candidate]]))
            if (!all(is.na(candidate_vals))) {
              fc_col_primary <- candidate
              break
            }
          }
        }
        
        # Statistical summary
        sig_col <- if(length(fdr_cols) > 0) fdr_cols[1] else if(length(p_cols) > 0) p_cols[1] else NULL
        
        if (!is.null(sig_col) && sig_col %in% colnames(stat_df)) {
          p_cutoff <- if(!is.null(input$p_value_cutoff)) input$p_value_cutoff else 0.05
          
          sig_values <- stat_df[[sig_col]]
          n_sig <- sum(sig_values < p_cutoff, na.rm = TRUE)
          n_total <- sum(!is.na(sig_values))
          
          context_parts <- c(context_parts, sprintf("\nSignificant features (p < %.3f): %d out of %d (%.1f%%)",
                                                    p_cutoff, n_sig, n_total, 100*n_sig/n_total))
          
          # Distribution of p-values
          p_ranges <- c(
            sum(sig_values < 0.001, na.rm = TRUE),
            sum(sig_values >= 0.001 & sig_values < 0.01, na.rm = TRUE),
            sum(sig_values >= 0.01 & sig_values < 0.05, na.rm = TRUE),
            sum(sig_values >= 0.05, na.rm = TRUE)
          )
          context_parts <- c(context_parts, sprintf("P-value distribution: p<0.001: %d, 0.001-0.01: %d, 0.01-0.05: %d, p>=0.05: %d",
                                                    p_ranges[1], p_ranges[2], p_ranges[3], p_ranges[4]))
          
          # TOP SIGNIFICANT FEATURES (Extended to 20)
          if (n_sig > 0) {
            top_n <- min(20, n_sig)
            stat_df_sorted <- stat_df[order(stat_df[[sig_col]]), ]
            top_features <- head(stat_df_sorted, top_n)
            
            context_parts <- c(context_parts, sprintf("\n=== TOP %d MOST SIGNIFICANT FEATURES ===", top_n))
            
            for (i in 1:nrow(top_features)) {
              feature_key <- rownames(top_features)[i]
              row_idx <- match(feature_key, rownames(stat_df))
              display_name <- resolve_feature_label(feature_key, row_idx, stat_df)
              p_val <- top_features[[sig_col]][i]
              
              feature_info <- sprintf("%d. %s", i, display_name)
              feature_info <- paste0(feature_info, sprintf(" | p-value: %.2e", p_val))
              
              # Add fold change
              if (!is.null(fc_col_primary) && fc_col_primary %in% colnames(top_features)) {
                fc_val <- suppressWarnings(as.numeric(top_features[[fc_col_primary]][i]))
                if (!is.na(fc_val)) {
                  # Show fold change properly: positive values as increase, negative as decrease
                  fold_change_linear <- 2^fc_val
                  direction_arrow <- if(fc_val > 0) " ↑ UPREGULATED" else " ↓ DOWNREGULATED"
                  feature_info <- paste0(feature_info, sprintf(" | log2FC: %+.3f (%.2fx change)%s",
                                                               fc_val, fold_change_linear, direction_arrow))
                }
              }
              
              # Add mean values per group if available
              if (length(mean_cols) >= 2) {
                mean1 <- top_features[[mean_cols[1]]][i]
                mean2 <- top_features[[mean_cols[2]]][i]
                if (!is.na(mean1) && !is.na(mean2)) {
                  feature_info <- paste0(feature_info, sprintf(" | Means: %.2f vs %.2f", mean1, mean2))
                }
              }
              
              context_parts <- c(context_parts, feature_info)
            }
          }
        }
        
        # Fold change summary - ONLY use the primary validated FC column
        if (!is.null(fc_col_primary) && fc_col_primary %in% colnames(stat_df)) {
          fc_values <- suppressWarnings(as.numeric(stat_df[[fc_col_primary]]))
          fc_values <- fc_values[!is.na(fc_values)]
          if (length(fc_values) > 0) {
            context_parts <- c(context_parts, sprintf("\n=== FOLD CHANGE SUMMARY (%s) ===", fc_col_primary))
            context_parts <- c(context_parts, "NOTE: Positive log2FC values = UPREGULATION (feature higher in first group)")
            context_parts <- c(context_parts, "      Negative log2FC values = DOWNREGULATION (feature lower in first group)")
            
            n_upregulated <- sum(fc_values > 0)
            n_downregulated <- sum(fc_values < 0)
            mean_fc <- mean(abs(fc_values))
            max_fc_up <- max(fc_values, na.rm = TRUE)
            max_fc_down <- min(fc_values, na.rm = TRUE)
            
            context_parts <- c(context_parts, sprintf("UPREGULATED features: %d (max log2FC: %+.2f = %.2fx increase)",
                                                      n_upregulated, max_fc_up, 2^max_fc_up))
            context_parts <- c(context_parts, sprintf("DOWNREGULATED features: %d (min log2FC: %+.2f = %.2fx decrease)",
                                                      n_downregulated, max_fc_down, 2^max_fc_down))
            context_parts <- c(context_parts, sprintf("Average |log2FC|: %.2f", mean_fc))
            
            if (!is.null(input$fc_cutoff)) {
              fc_cutoff <- input$fc_cutoff
              strong_up <- sum(fc_values > fc_cutoff)
              strong_down <- sum(fc_values < -fc_cutoff)
              context_parts <- c(context_parts, sprintf("Strong changes (|log2FC| > %.1f): %d upregulated, %d downregulated",
                                                        fc_cutoff, strong_up, strong_down))
            }
          }
        }
        
      }, error = function(e) {
        context_parts <- c(context_parts, sprintf("Error reading statistical results: %s", e$message))
      })
    }
    
    # ===== PCA RESULTS =====
    if (!is.null(input$navbar) && input$navbar == "PCA" && !is.null(values$pca_result)) {
      tryCatch({
        pca_res <- values$pca_result
        context_parts <- c(context_parts, "\n=== PCA ANALYSIS RESULTS ===")
        
        # Variance explained
        if (!is.null(pca_res$sdev)) {
          var_exp <- pca_res$sdev^2 / sum(pca_res$sdev^2) * 100
          context_parts <- c(context_parts, sprintf("PC1 variance: %.1f%%", var_exp[1]))
          context_parts <- c(context_parts, sprintf("PC2 variance: %.1f%%", var_exp[2]))
          context_parts <- c(context_parts, sprintf("PC3 variance: %.1f%%", var_exp[3]))
          context_parts <- c(context_parts, sprintf("Cumulative (PC1-3): %.1f%%", sum(var_exp[1:3])))
        }
        
      }, error = function(e) {})
    }
    
    # ===== MACHINE LEARNING RESULTS =====
    if (!is.null(input$navbar) && input$navbar == "Machine Learning" && !is.null(values$ml_results)) {
      tryCatch({
        ml_res <- values$ml_results
        context_parts <- c(context_parts, "\n=== MACHINE LEARNING RESULTS ===")
        
        if (!is.null(input$mlfs_method)) {
          context_parts <- c(context_parts, sprintf("Method: %s", input$mlfs_method))
        }
        
        # Extract performance metrics
        if (!is.null(ml_res$performance)) {
          perf <- ml_res$performance
          for (metric_name in names(perf)) {
            context_parts <- c(context_parts, sprintf("%s: %.3f", metric_name, perf[[metric_name]]))
          }
        }
        
        # Top features
        if (!is.null(ml_res$important_features)) {
          top_ml_features <- head(ml_res$important_features, 10)
          context_parts <- c(context_parts, sprintf("Top ML features: %s", paste(top_ml_features, collapse = ", ")))
        }
        
      }, error = function(e) {})
    }
    
    # ===== GLYCOMICS ANALYSIS =====
    if (!is.null(input$navbar) && input$navbar == "Glycomics Analysis") {
      context_parts <- c(context_parts, "\n=== GLYCOMICS ANALYSIS ===")
      
      if (!is.null(input$glyco_analysis_type)) {
        context_parts <- c(context_parts, sprintf("Analysis type: %s", input$glyco_analysis_type))
      }
      if (!is.null(input$glyco_plot_type)) {
        context_parts <- c(context_parts, sprintf("Plot type: %s", input$glyco_plot_type))
      }
      if (!is.null(input$glyco_notation_system)) {
        context_parts <- c(context_parts, sprintf("Notation system: %s", input$glyco_notation_system))
      }
    }
    
    # ===== ENRICHMENT RESULTS =====
    if (!is.null(values$enrichment_results)) {
      context_parts <- c(context_parts, "\n=== ENRICHMENT ANALYSIS ===")
      context_parts <- c(context_parts, sprintf("Enrichment results available: %d pathways", nrow(values$enrichment_results)))
    }
    
    # ===== VOLCANO PLOT TAB =====
    if (!is.null(input$navbar) && input$navbar == "Volcano Plots" && !is.null(values$stat_results)) {
      tryCatch({
        context_parts <- c(context_parts, "\n=== VOLCANO PLOT ANALYSIS ===")
        context_parts <- c(context_parts, "You are viewing volcano plots showing log2 fold change vs -log10(p-value)")
        
        stat_df <- values$stat_results
        
        # Get comparison info
        if (!is.null(input$group_1) && !is.null(input$group_2)) {
          context_parts <- c(context_parts, sprintf("Current comparison: %s vs %s", input$group_1, input$group_2))
        }
        
        # Cutoff information
        if (!is.null(input$p_value_cutoff)) {
          context_parts <- c(context_parts, sprintf("Significance threshold: p < %.3f (shown as horizontal line at -log10(p) = %.2f)",
                                                    input$p_value_cutoff, -log10(input$p_value_cutoff)))
        }
        if (!is.null(input$fc_cutoff)) {
          context_parts <- c(context_parts, sprintf("Fold change threshold: |log2FC| > %.2f (shown as vertical lines)", input$fc_cutoff))
        }
        
        # Find relevant columns
        p_cols <- grep("_pvalue$|_p_value$|_P$|_pval", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        fdr_cols <- grep("_FDR$|_adj|_padj|_qvalue", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        fc_cols <- grep("Log2FC|log2fc|_FC$|fold|_log2", colnames(stat_df), value = TRUE, ignore.case = TRUE)
        
        sig_col <- if(length(fdr_cols) > 0) fdr_cols[1] else if(length(p_cols) > 0) p_cols[1] else NULL
        fc_col <- if(length(fc_cols) > 0) fc_cols[1] else NULL
        
        if (!is.null(sig_col) && !is.null(fc_col)) {
          p_values <- stat_df[[sig_col]]
          fc_values <- stat_df[[fc_col]]
          
          p_cutoff <- if(!is.null(input$p_value_cutoff)) input$p_value_cutoff else 0.05
          fc_cutoff <- if(!is.null(input$fc_cutoff)) input$fc_cutoff else 1.0
          
          # Classify features into quadrants
          sig_up <- sum(!is.na(p_values) & !is.na(fc_values) & p_values < p_cutoff & fc_values > fc_cutoff)
          sig_down <- sum(!is.na(p_values) & !is.na(fc_values) & p_values < p_cutoff & fc_values < -fc_cutoff)
          not_sig_changed <- sum(!is.na(p_values) & !is.na(fc_values) & p_values >= p_cutoff & abs(fc_values) > fc_cutoff)
          sig_not_changed <- sum(!is.na(p_values) & !is.na(fc_values) & p_values < p_cutoff & abs(fc_values) <= fc_cutoff)
          
          context_parts <- c(context_parts, "\n=== VOLCANO PLOT QUADRANTS ===")
          context_parts <- c(context_parts, sprintf("Upper Right (Significant + Upregulated): %d features", sig_up))
          context_parts <- c(context_parts, sprintf("Upper Left (Significant + Downregulated): %d features", sig_down))
          context_parts <- c(context_parts, sprintf("Lower quadrants (Not significant but changed): %d features", not_sig_changed))
          context_parts <- c(context_parts, sprintf("Central (Significant but small change): %d features", sig_not_changed))
          
          # Most extreme features in each direction
          if (sig_up > 0) {
            sig_up_data <- stat_df[!is.na(p_values) & !is.na(fc_values) & p_values < p_cutoff & fc_values > fc_cutoff, ]
            sig_up_data <- sig_up_data[order(-sig_up_data[[fc_col]]), ]
            top_up <- head(sig_up_data, 5)
            
            context_parts <- c(context_parts, "\nTop 5 UPREGULATED significant features:")
            for (i in 1:min(5, nrow(top_up))) {
              feature_key <- rownames(top_up)[i]
              row_idx <- match(feature_key, rownames(stat_df))
              display_name <- resolve_feature_label(feature_key, row_idx, stat_df)
              fc_val <- suppressWarnings(as.numeric(top_up[[fc_col]][i]))
              fc_text <- if (!is.na(fc_val)) sprintf("log2FC: %.2f (%.1fx)", fc_val, 2^fc_val) else sprintf("log2FC: %s", as.character(top_up[[fc_col]][i]))
              p_val <- suppressWarnings(as.numeric(top_up[[sig_col]][i]))
              p_text <- if (!is.na(p_val)) sprintf("p: %.2e", p_val) else sprintf("p: %s", as.character(top_up[[sig_col]][i]))
              context_parts <- c(context_parts, sprintf("  %d. %s | %s | %s", i, display_name, fc_text, p_text))
            }
          }
          
          if (sig_down > 0) {
            sig_down_data <- stat_df[!is.na(p_values) & !is.na(fc_values) & p_values < p_cutoff & fc_values < -fc_cutoff, ]
            sig_down_data <- sig_down_data[order(sig_down_data[[fc_col]]), ]
            top_down <- head(sig_down_data, 5)
            
            context_parts <- c(context_parts, "\nTop 5 DOWNREGULATED significant features:")
            for (i in 1:min(5, nrow(top_down))) {
              feature_key <- rownames(top_down)[i]
              row_idx <- match(feature_key, rownames(stat_df))
              display_name <- resolve_feature_label(feature_key, row_idx, stat_df)
              fc_val <- suppressWarnings(as.numeric(top_down[[fc_col]][i]))
              fc_text <- if (!is.na(fc_val)) sprintf("log2FC: %.2f (%.1fx)", fc_val, 2^abs(fc_val)) else sprintf("log2FC: %s", as.character(top_down[[fc_col]][i]))
              p_val <- suppressWarnings(as.numeric(top_down[[sig_col]][i]))
              p_text <- if (!is.na(p_val)) sprintf("p: %.2e", p_val) else sprintf("p: %s", as.character(top_down[[sig_col]][i]))
              context_parts <- c(context_parts, sprintf("  %d. %s | %s | %s", i, display_name, fc_text, p_text))
            }
          }
          
          # Most significant features (highest on volcano plot)
          most_sig <- stat_df[order(p_values), ]
          most_sig <- head(most_sig[!is.na(most_sig[[sig_col]]), ], 5)
          
          if (nrow(most_sig) > 0) {
            context_parts <- c(context_parts, "\nMost SIGNIFICANT features (highest points on plot):")
            for (i in 1:nrow(most_sig)) {
              feature_key <- rownames(most_sig)[i]
              row_idx <- match(feature_key, rownames(stat_df))
              display_name <- resolve_feature_label(feature_key, row_idx, stat_df)
              p_val <- suppressWarnings(as.numeric(most_sig[[sig_col]][i]))
              p_text <- if (!is.na(p_val)) sprintf("p: %.2e (-log10: %.2f)", p_val, -log10(p_val)) else sprintf("p: %s", as.character(most_sig[[sig_col]][i]))
              fc_val <- suppressWarnings(as.numeric(most_sig[[fc_col]][i]))
              fc_text <- if (!is.na(fc_val)) sprintf("log2FC: %.2f", fc_val) else sprintf("log2FC: %s", as.character(most_sig[[fc_col]][i]))
              context_parts <- c(context_parts, sprintf("  %d. %s | %s | %s", i, display_name, p_text, fc_text))
            }
          }
        }
        
      }, error = function(e) {
        context_parts <- c(context_parts, "Volcano plot data available but unable to parse details")
      })
    }
    
    # ===== HEATMAP TAB =====
    if (!is.null(input$navbar) && input$navbar == "Heatmaps" && !is.null(values$normalized_data)) {
      context_parts <- c(context_parts, "\n=== HEATMAP VISUALIZATION ===")
      context_parts <- c(context_parts, "You are viewing a heatmap showing feature expression across samples")
      
      if (!is.null(input$heatmap_clustering)) {
        context_parts <- c(context_parts, sprintf("Clustering method: %s", input$heatmap_clustering))
      }
      if (!is.null(input$heatmap_distance)) {
        context_parts <- c(context_parts, sprintf("Distance metric: %s", input$heatmap_distance))
      }
      if (!is.null(input$heatmap_scale)) {
        context_parts <- c(context_parts, sprintf("Scaling: %s", input$heatmap_scale))
      }
      
      context_parts <- c(context_parts, "Heatmap shows: rows = features, columns = samples")
      context_parts <- c(context_parts, "Colors represent expression levels (typically: blue = low, red = high)")
      context_parts <- c(context_parts, "Dendrograms show hierarchical clustering of similar features/samples")
    }
    
    # ===== MA PLOT TAB =====
    if (!is.null(input$navbar) && input$navbar == "MA Plots" && !is.null(values$stat_results)) {
      context_parts <- c(context_parts, "\n=== MA PLOT ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing MA plots (M = log ratio, A = average intensity)")
      context_parts <- c(context_parts, "X-axis: Average expression (log scale)")
      context_parts <- c(context_parts, "Y-axis: Log2 fold change")
      context_parts <- c(context_parts, "Horizontal lines show fold change cutoffs")
      context_parts <- c(context_parts, "Points above/below lines are differentially expressed")
      
      if (!is.null(input$group_1) && !is.null(input$group_2)) {
        context_parts <- c(context_parts, sprintf("Comparison: %s vs %s", input$group_1, input$group_2))
      }
    }
    
    # ===== BOX PLOTS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Box Plots" && !is.null(values$normalized_data)) {
      context_parts <- c(context_parts, "\n=== BOX PLOT VISUALIZATION ===")
      context_parts <- c(context_parts, "You are viewing box plots showing feature distribution across groups")
      context_parts <- c(context_parts, "Box: 25th-75th percentile (IQR)")
      context_parts <- c(context_parts, "Line inside box: median")
      context_parts <- c(context_parts, "Whiskers: 1.5×IQR or min/max")
      context_parts <- c(context_parts, "Points: potential outliers")
    }
    
    # ===== ENRICHMENT ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Enrichment") {
      context_parts <- c(context_parts, "\n=== ENRICHMENT ANALYSIS ===")
      
      # Gene/Protein List Information
      if (!is.null(proteomics_values$gene_list) && length(proteomics_values$gene_list) > 0) {
        context_parts <- c(context_parts, sprintf("Total genes/proteins analyzed: %d", length(proteomics_values$gene_list)))
        
        # Show sample of genes
        sample_genes <- head(proteomics_values$gene_list, 10)
        context_parts <- c(context_parts, sprintf("Sample genes: %s", paste(sample_genes, collapse = ", ")))
        if (length(proteomics_values$gene_list) > 10) {
          context_parts <- c(context_parts, sprintf("... and %d more genes", length(proteomics_values$gene_list) - 10))
        }
      }
      
      # Analysis Settings
      if (!is.null(input$proteomics_source)) {
        context_parts <- c(context_parts, sprintf("Gene source: %s", input$proteomics_source))
      }
      if (!is.null(input$proteomics_tool)) {
        context_parts <- c(context_parts, sprintf("Enrichment tool: %s", input$proteomics_tool))
      }
      if (!is.null(input$proteomics_organism)) {
        context_parts <- c(context_parts, sprintf("Organism: %s", input$proteomics_organism))
      }
      
      # Enrichment Results
      if (!is.null(proteomics_values$enrichment_results)) {
        tryCatch({
          enrich_df <- proteomics_values$enrichment_results
          
          if (nrow(enrich_df) > 0) {
            context_parts <- c(context_parts, sprintf("\nTotal enriched terms found: %d", nrow(enrich_df)))
            
            # Find relevant columns
            term_col <- NULL
            pval_col <- NULL
            fdr_col <- NULL
            source_col <- NULL
            genes_col <- NULL
            
            # Try to identify columns
            for (col in colnames(enrich_df)) {
              if (grepl("term|pathway|description|name", col, ignore.case = TRUE) && is.null(term_col)) {
                term_col <- col
              }
              if (grepl("^p\\.value$|^pvalue$|^p_value$", col, ignore.case = TRUE) && is.null(pval_col)) {
                pval_col <- col
              }
              if (grepl("fdr|adj|q\\.value|qvalue|padj", col, ignore.case = TRUE) && is.null(fdr_col)) {
                fdr_col <- col
              }
              if (grepl("source|database|category", col, ignore.case = TRUE) && is.null(source_col)) {
                source_col <- col
              }
              if (grepl("genes|intersection|overlap", col, ignore.case = TRUE) && is.null(genes_col)) {
                genes_col <- col
              }
            }
            
            # Report what was found
            if (!is.null(pval_col) || !is.null(fdr_col)) {
              sig_col <- if(!is.null(fdr_col)) fdr_col else pval_col
              sig_values <- enrich_df[[sig_col]]
              n_sig_001 <- sum(sig_values < 0.001, na.rm = TRUE)
              n_sig_01 <- sum(sig_values < 0.01, na.rm = TRUE)
              n_sig_05 <- sum(sig_values < 0.05, na.rm = TRUE)
              
              context_parts <- c(context_parts, sprintf("Significance levels: p<0.001: %d, p<0.01: %d, p<0.05: %d",
                                                        n_sig_001, n_sig_01, n_sig_05))
            }
            
            # Group by source/database if available
            if (!is.null(source_col)) {
              sources <- table(enrich_df[[source_col]])
              context_parts <- c(context_parts, "\nEnrichment by source:")
              for (src in names(sources)) {
                context_parts <- c(context_parts, sprintf("  %s: %d terms", src, sources[src]))
              }
            }
            
            # Top enriched terms
            if (!is.null(term_col)) {
              context_parts <- c(context_parts, "\n=== TOP 15 ENRICHED TERMS ===")
              
              # Sort by significance
              if (!is.null(fdr_col)) {
                enrich_sorted <- enrich_df[order(enrich_df[[fdr_col]]), ]
              } else if (!is.null(pval_col)) {
                enrich_sorted <- enrich_df[order(enrich_df[[pval_col]]), ]
              } else {
                enrich_sorted <- enrich_df
              }
              
              top_n <- min(15, nrow(enrich_sorted))
              
              for (i in 1:top_n) {
                term_name <- enrich_sorted[[term_col]][i]
                term_info <- sprintf("%d. %s", i, term_name)
                
                # Add p-value/FDR
                if (!is.null(fdr_col)) {
                  fdr_val <- enrich_sorted[[fdr_col]][i]
                  term_info <- paste0(term_info, sprintf(" | FDR: %.2e", fdr_val))
                } else if (!is.null(pval_col)) {
                  pval <- enrich_sorted[[pval_col]][i]
                  term_info <- paste0(term_info, sprintf(" | p-value: %.2e", pval))
                }
                
                # Add source if available
                if (!is.null(source_col)) {
                  src <- enrich_sorted[[source_col]][i]
                  term_info <- paste0(term_info, sprintf(" | Source: %s", src))
                }
                
                # Add gene count if available
                if (!is.null(genes_col)) {
                  genes_val <- enrich_sorted[[genes_col]][i]
                  if (is.character(genes_val)) {
                    # Count comma-separated genes
                    n_genes <- length(strsplit(as.character(genes_val), ",")[[1]])
                    term_info <- paste0(term_info, sprintf(" | Genes: %d", n_genes))
                  } else if (is.numeric(genes_val)) {
                    term_info <- paste0(term_info, sprintf(" | Genes: %d", genes_val))
                  }
                }
                
                context_parts <- c(context_parts, term_info)
              }
            }
            
            # Biological interpretation hints
            context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
            context_parts <- c(context_parts, "These enriched terms represent biological pathways, processes, or functions")
            context_parts <- c(context_parts, "that are statistically over-represented in your gene list.")
            context_parts <- c(context_parts, "Lower p-values/FDR indicate stronger enrichment.")
            
          } else {
            context_parts <- c(context_parts, "No enriched terms found with current settings")
            context_parts <- c(context_parts, "Consider: using a less stringent p-value cutoff, checking gene ID format,")
            context_parts <- c(context_parts, "or ensuring sufficient genes in your list (typically 20+ recommended)")
          }
        }, error = function(e) {
          context_parts <- c(context_parts, sprintf("Error reading enrichment results: %s", e$message))
        })
      } else {
        context_parts <- c(context_parts, "Enrichment analysis not yet run")
        context_parts <- c(context_parts, "Note: Run enrichment analysis to see pathway/function results")
      }
    }
    
    # ===== GLYCOMICS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Glycomics") {
      context_parts <- c(context_parts, "\n=== GLYCOMICS ANALYSIS ===")
      
      # Check if glycan notation has been parsed
      if (!is.null(glyco_values$parsed_glycans) && length(glyco_values$parsed_glycans) > 0) {
        n_glycans <- length(glyco_values$parsed_glycans)
        context_parts <- c(context_parts, sprintf("Total glycans parsed: %d", n_glycans))
        
        # Notation system used
        if (!is.null(input$glyco_notation_system)) {
          context_parts <- c(context_parts, sprintf("Notation system: %s", input$glyco_notation_system))
        }
        
        # Classification type
        if (!is.null(input$glycan_classification_type)) {
          context_parts <- c(context_parts, sprintf("Classification: %s", input$glycan_classification_type))
        }
        
        # Glycan type distribution
        if (!is.null(glyco_values$classification_data) && length(glyco_values$classification_data) > 0) {
          glycan_types <- sapply(glyco_values$classification_data, function(x) x$type)
          type_counts <- table(glycan_types)
          
          context_parts <- c(context_parts, "\n=== GLYCAN TYPE DISTRIBUTION ===")
          for (gtype in names(type_counts)) {
            pct <- round(100 * type_counts[gtype] / n_glycans, 1)
            context_parts <- c(context_parts, sprintf("  %s: %d glycans (%.1f%%)",
                                                      gtype, type_counts[gtype], pct))
          }
          
          # Structural features summary
          sialylation_counts <- table(sapply(glyco_values$classification_data, function(x) x$sialylation))
          fucosylation_counts <- table(sapply(glyco_values$classification_data, function(x) x$fucosylation))
          branching_counts <- table(sapply(glyco_values$classification_data, function(x) x$branching))
          
          context_parts <- c(context_parts, "\n=== STRUCTURAL FEATURES ===")
          context_parts <- c(context_parts, sprintf("Sialylation levels: %s",
                                                    paste(names(sialylation_counts), ":", sialylation_counts, collapse = ", ")))
          context_parts <- c(context_parts, sprintf("Fucosylation levels: %s",
                                                    paste(names(fucosylation_counts), ":", fucosylation_counts, collapse = ", ")))
          context_parts <- c(context_parts, sprintf("Branching patterns: %s",
                                                    paste(names(branching_counts), ":", branching_counts, collapse = ", ")))
        }
        
        # Current analysis type
        if (!is.null(input$glyco_analysis_type)) {
          context_parts <- c(context_parts, sprintf("\nCurrent view: %s", input$glyco_analysis_type))
          
          # Distribution analysis
          if (input$glyco_analysis_type == "distribution") {
            context_parts <- c(context_parts, "Showing glycan type distribution across all samples")
            if (!is.null(input$glyco_plot_type)) {
              context_parts <- c(context_parts, sprintf("Plot type: %s", input$glyco_plot_type))
            }
          }
          
          # Structure analysis
          else if (input$glyco_analysis_type == "structure") {
            context_parts <- c(context_parts, "Analyzing structural features (sialylation, fucosylation, branching)")
          }
          
          # Group comparison
          else if (input$glyco_analysis_type == "group_comparison") {
            context_parts <- c(context_parts, "Comparing glycan profiles between groups")
            if (!is.null(values$unique_groups)) {
              context_parts <- c(context_parts, sprintf("Groups compared: %s",
                                                        paste(values$unique_groups, collapse = " vs ")))
            }
          }
          
          # Glycan comparison
          else if (input$glyco_analysis_type == "glycan_comparison") {
            context_parts <- c(context_parts, "Comparing individual glycan abundances across groups")
          }
        }
        
        # Sample glycans
        glycan_names <- names(glyco_values$parsed_glycans)
        if (length(glycan_names) > 0) {
          sample_glycans <- head(glycan_names, 10)
          context_parts <- c(context_parts, sprintf("\nSample glycans: %s", paste(sample_glycans, collapse = ", ")))
          if (length(glycan_names) > 10) {
            context_parts <- c(context_parts, sprintf("... and %d more glycans", length(glycan_names) - 10))
          }
        }
        
        # Top glycans by abundance (if normalized data available)
        if (!is.null(values$normalized_data) && !is.null(glyco_values$parsed_glycans)) {
          tryCatch({
            # Get glycan indices
            glycan_indices <- match(names(glyco_values$parsed_glycans),
                                    if (isTRUE(glyco_values$using_accession_ids) && !is.null(values$accession_ids)) {
                                      values$accession_ids
                                    } else {
                                      values$cleaned_molecules
                                    })
            glycan_indices <- glycan_indices[!is.na(glycan_indices)]
            
            if (length(glycan_indices) > 0) {
              glycan_data <- values$normalized_data[glycan_indices, , drop = FALSE]
              mean_abundances <- rowMeans(glycan_data, na.rm = TRUE)
              
              # Get top 5 most abundant
              top_idx <- order(mean_abundances, decreasing = TRUE)[1:min(5, length(mean_abundances))]
              
              context_parts <- c(context_parts, "\n=== TOP 5 MOST ABUNDANT GLYCANS ===")
              for (i in seq_along(top_idx)) {
                idx <- top_idx[i]
                glycan_name <- rownames(glycan_data)[idx]
                abundance <- mean_abundances[idx]
                glycan_type <- glyco_values$parsed_glycans[[glycan_name]]$type
                context_parts <- c(context_parts, sprintf("%d. %s | Type: %s | Mean abundance: %.2f",
                                                          i, glycan_name, glycan_type, abundance))
              }
            }
          }, error = function(e) {
            # Silently skip if error
          })
        }
        
        # Interpretation guidance
        context_parts <- c(context_parts, "\n=== GLYCOMICS INTERPRETATION ===")
        context_parts <- c(context_parts, "Glycans are complex carbohydrates that play key roles in:")
        context_parts <- c(context_parts, "  - Cell recognition and signaling")
        context_parts <- c(context_parts, "  - Immune response and inflammation")
        context_parts <- c(context_parts, "  - Protein folding and stability")
        context_parts <- c(context_parts, "  - Disease biomarkers (especially cancer)")
        context_parts <- c(context_parts, "\nKey structural features:")
        context_parts <- c(context_parts, "  - Sialylation: often increased in cancer/inflammation")
        context_parts <- c(context_parts, "  - Fucosylation: important for immune recognition")
        context_parts <- c(context_parts, "  - Branching: affects glycan conformation and binding")
        
      } else {
        context_parts <- c(context_parts, "Glycan notation not yet parsed")
        context_parts <- c(context_parts, "Note: Upload data with glycan notation and click 'Apply Glycan Notation'")
        context_parts <- c(context_parts, "Supported notation systems: IUPAC-condensed, GlycoCT, Oxford")
      }
    }
    
    # ===== ROC/PR ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "ROC/PR Analysis") {
      context_parts <- c(context_parts, "\n=== ROC/PR CURVE ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing ROC (Receiver Operating Characteristic) and PR (Precision-Recall) curve results")
      
      # Check if analysis has been run
      if (!is.null(values$roc_results) && nrow(values$roc_results) > 0) {
        # Get comparison information
        if (!is.null(input$rocGroup1) && !is.null(input$rocGroup2)) {
          comparison_text <- sprintf("Comparison: %s vs %s", input$rocGroup1, input$rocGroup2)
          context_parts <- c(context_parts, comparison_text)
          context_parts <- c(context_parts, sprintf("  Control group: %s", input$rocGroup1))
          context_parts <- c(context_parts, sprintf("  Case group: %s", input$rocGroup2))
        }
        
        # Analysis settings
        context_parts <- c(context_parts, "\n=== ANALYSIS SETTINGS ===")
        if (!is.null(input$rocPvalCutoff)) {
          context_parts <- c(context_parts, sprintf("P-value cutoff: %.4f", input$rocPvalCutoff))
        }
        if (!is.null(input$rocLogFCCutoff)) {
          context_parts <- c(context_parts, sprintf("Log2 fold change cutoff: %.2f", input$rocLogFCCutoff))
        }
        if (!is.null(values$roc_using_fdr) && values$roc_using_fdr && !is.null(input$roc_fdr_cutoff)) {
          context_parts <- c(context_parts, sprintf("FDR cutoff: %.4f (ROTS method)", input$roc_fdr_cutoff))
        }
        
        # Feature source information
        if (!is.null(input$roc_feature_source)) {
          feature_source_text <- switch(input$roc_feature_source,
                                        "all" = "All features",
                                        "pca" = "PCA-selected features",
                                        "ml" = "Machine Learning-selected features",
                                        "All features")
          context_parts <- c(context_parts, sprintf("Feature source: %s", feature_source_text))
        }
        
        # Number of features analyzed
        context_parts <- c(context_parts, sprintf("Total features analyzed: %d", nrow(values$roc_results)))
        
        # Check if Combined model is present
        has_combined <- "Combined" %in% values$roc_results$Molecule
        if (has_combined) {
          context_parts <- c(context_parts, "Combined model: YES (logistic regression using all features)")
        }
        
        # Get top performers by AUC
        context_parts <- c(context_parts, "\n=== TOP PERFORMING FEATURES (by ROC AUC) ===")
        
        # Sort by AUC and get top 10
        results_sorted <- values$roc_results[order(-as.numeric(values$roc_results$AUC)), ]
        top_n <- min(10, nrow(results_sorted))
        
        for (i in 1:top_n) {
          feature_name <- results_sorted$Molecule[i]
          auc_val <- as.numeric(results_sorted$AUC[i])
          auprc_val <- results_sorted$AUPRC[i]
          regulation <- results_sorted$Regulation[i]
          
          # Determine performance classification
          performance <- if (auc_val >= 0.9) "Excellent"
          else if (auc_val >= 0.8) "Good"
          else if (auc_val >= 0.7) "Fair"
          else "Poor"
          
          feature_line <- sprintf("%d. %s: AUC=%.3f (%s), AUPRC=%s, %s",
                                  i, feature_name, auc_val, performance,
                                  auprc_val, regulation)
          context_parts <- c(context_parts, feature_line)
        }
        
        # Performance summary
        context_parts <- c(context_parts, "\n=== PERFORMANCE SUMMARY ===")
        auc_values <- as.numeric(results_sorted$AUC)
        
        excellent_count <- sum(auc_values >= 0.9, na.rm = TRUE)
        good_count <- sum(auc_values >= 0.8 & auc_values < 0.9, na.rm = TRUE)
        fair_count <- sum(auc_values >= 0.7 & auc_values < 0.8, na.rm = TRUE)
        poor_count <- sum(auc_values < 0.7, na.rm = TRUE)
        
        if (excellent_count > 0) {
          context_parts <- c(context_parts, sprintf("Excellent classifiers (AUC ≥ 0.9): %d", excellent_count))
        }
        if (good_count > 0) {
          context_parts <- c(context_parts, sprintf("Good classifiers (AUC 0.8-0.9): %d", good_count))
        }
        if (fair_count > 0) {
          context_parts <- c(context_parts, sprintf("Fair classifiers (AUC 0.7-0.8): %d", fair_count))
        }
        if (poor_count > 0) {
          context_parts <- c(context_parts, sprintf("Poor classifiers (AUC < 0.7): %d", poor_count))
        }
        
        context_parts <- c(context_parts, sprintf("Average AUC: %.3f", mean(auc_values, na.rm = TRUE)))
        context_parts <- c(context_parts, sprintf("Median AUC: %.3f", median(auc_values, na.rm = TRUE)))
        
        # Regulation distribution
        if ("Regulation" %in% colnames(values$roc_results)) {
          up_count <- sum(values$roc_results$Regulation == "Upregulated", na.rm = TRUE)
          down_count <- sum(values$roc_results$Regulation == "Downregulated", na.rm = TRUE)
          
          if (up_count > 0 || down_count > 0) {
            context_parts <- c(context_parts, "\n=== REGULATION STATUS ===")
            if (up_count > 0) {
              context_parts <- c(context_parts, sprintf("Upregulated features: %d (higher in %s)", up_count, input$rocGroup2))
            }
            if (down_count > 0) {
              context_parts <- c(context_parts, sprintf("Downregulated features: %d (lower in %s)", down_count, input$rocGroup2))
            }
          }
        }
        
        # AUPRC information
        auprc_available <- sum(values$roc_results$AUPRC != "N/A", na.rm = TRUE)
        if (auprc_available > 0) {
          context_parts <- c(context_parts, "\n=== PRECISION-RECALL CURVES ===")
          context_parts <- c(context_parts, sprintf("Features with AUPRC calculated: %d", auprc_available))
          
          # Get numeric AUPRC values
          auprc_numeric <- as.numeric(values$roc_results$AUPRC[values$roc_results$AUPRC != "N/A"])
          if (length(auprc_numeric) > 0) {
            context_parts <- c(context_parts, sprintf("Average AUPRC: %.3f", mean(auprc_numeric, na.rm = TRUE)))
            context_parts <- c(context_parts, sprintf("Median AUPRC: %.3f", median(auprc_numeric, na.rm = TRUE)))
          }
        }
        
        # Interpretation guidance
        context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDE ===")
        context_parts <- c(context_parts, "ROC AUC interpretation:")
        context_parts <- c(context_parts, "  - AUC = 0.5: Random classifier (no discriminatory power)")
        context_parts <- c(context_parts, "  - AUC 0.7-0.8: Acceptable discrimination")
        context_parts <- c(context_parts, "  - AUC 0.8-0.9: Excellent discrimination")
        context_parts <- c(context_parts, "  - AUC > 0.9: Outstanding discrimination")
        context_parts <- c(context_parts, "\nPR curves are especially useful for imbalanced datasets")
        context_parts <- c(context_parts, "Higher AUPRC indicates better precision-recall trade-off")
        context_parts <- c(context_parts, "\nThe Combined model uses logistic regression to integrate multiple features")
        
      } else {
        context_parts <- c(context_parts, "No ROC/PR analysis results available yet")
        context_parts <- c(context_parts, "To generate results:")
        context_parts <- c(context_parts, "  1. Select two groups to compare")
        context_parts <- c(context_parts, "  2. Set p-value and log2FC cutoffs")
        context_parts <- c(context_parts, "  3. Click 'Calculate ROC Curves' button")
      }
    }
    
    # ===== INTERSECTION ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Intersection Analysis") {
      context_parts <- c(context_parts, "\n=== INTERSECTION ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing feature set intersection analysis results")
      
      # Check if analysis has been run
      if (!is.null(values$intersection_sets) && length(values$intersection_sets) > 0 &&
          !is.null(values$intersection_set_names)) {
        
        # Basic analysis information
        num_sets <- length(values$intersection_sets)
        context_parts <- c(context_parts, sprintf("Number of sets analyzed: %d", num_sets))
        context_parts <- c(context_parts, "Sets included:")
        
        # List all sets with their sizes
        total_features <- 0
        for (i in seq_along(values$intersection_sets)) {
          set_size <- length(values$intersection_sets[[i]])
          set_name <- values$intersection_set_names[i]
          context_parts <- c(context_parts, sprintf("  - %s: %d features", set_name, set_size))
          total_features <- total_features + set_size
        }
        
        context_parts <- c(context_parts, sprintf("Total features across all sets: %d", total_features))
        
        # Analysis settings
        if (!is.null(input$intersection_source)) {
          source_text <- switch(input$intersection_source,
                                "pairwise" = "Pairwise comparisons between all group pairs",
                                "intersection" = "Intersection of multiple comparisons",
                                "manual" = "Manual file upload",
                                "Comparisons")
          context_parts <- c(context_parts, sprintf("\nAnalysis source: %s", source_text))
        }
        
        # Get comparison results if available
        if (!is.null(values$intersection_comparison_results)) {
          context_parts <- c(context_parts, "\n=== INTERSECTION RESULTS ===")
          
          results <- values$intersection_comparison_results
          
          # Union and complete intersection
          if ("Union" %in% names(results)) {
            union_count <- length(results[["Union"]])
            context_parts <- c(context_parts, sprintf("Union (all features): %d", union_count))
          }
          
          if ("Intersection_All_Sets" %in% names(results)) {
            all_intersection_count <- length(results[["Intersection_All_Sets"]])
            context_parts <- c(context_parts, sprintf("Complete intersection (in all sets): %d", all_intersection_count))
          }
          
          # Unique features per set
          unique_results <- grep("^Unique_", names(results), value = TRUE)
          if (length(unique_results) > 0) {
            context_parts <- c(context_parts, "\nUnique features (exclusive to each set):")
            for (result_name in unique_results) {
              unique_count <- length(results[[result_name]])
              set_label <- gsub("^Unique_", "", result_name)
              context_parts <- c(context_parts, sprintf("  - %s: %d features", set_label, unique_count))
            }
          }
          
          # Pairwise intersections
          pairwise_results <- setdiff(names(results),
                                      c("Union", "Intersection_All_Sets", unique_results))
          
          if (length(pairwise_results) > 0) {
            context_parts <- c(context_parts, "\nPairwise and partial intersections:")
            
            # Sort pairwise results by count (descending) and limit to top 15
            pairwise_counts <- sapply(pairwise_results, function(x) length(results[[x]]))
            pairwise_sorted <- names(sort(pairwise_counts, decreasing = TRUE)[1:min(15, length(pairwise_counts))])
            
            for (result_name in pairwise_sorted) {
              intersection_count <- length(results[[result_name]])
              # Clean up the name for display
              display_name <- gsub("_", " vs ", result_name)
              context_parts <- c(context_parts, sprintf("  - %s: %d features", display_name, intersection_count))
            }
            
            if (length(pairwise_results) > 15) {
              context_parts <- c(context_parts,
                                 sprintf("  ... and %d more intersections", length(pairwise_results) - 15))
            }
          }
          
          # Visualization type
          context_parts <- c(context_parts, "\n=== VISUALIZATION ===")
          if (num_sets <= 5) {
            context_parts <- c(context_parts, "Display type: Venn Diagram")
            context_parts <- c(context_parts, "This shows overlaps between sets clearly for small numbers of sets")
          } else {
            context_parts <- c(context_parts, "Display type: UpSet Plot")
            context_parts <- c(context_parts, "This shows all possible intersections for complex multi-set comparisons")
            
            if (!is.null(values$intersection_binary_matrix)) {
              num_features <- nrow(values$intersection_binary_matrix)
              context_parts <- c(context_parts, sprintf("Binary matrix size: %d features x %d sets",
                                                        num_features, ncol(values$intersection_binary_matrix)))
            }
          }
          
          # Statistics summary
          context_parts <- c(context_parts, "\n=== INTERPRETATION ===")
          
          if ("Intersection_All_Sets" %in% names(results)) {
            all_int <- length(results[["Intersection_All_Sets"]])
            if ("Union" %in% names(results)) {
              union <- length(results[["Union"]])
              overlap_pct <- if (union > 0) round(100 * all_int / union, 1) else 0
              context_parts <- c(context_parts,
                                 sprintf("Overlap: %.1f%% of all features are common to all sets", overlap_pct))
              context_parts <- c(context_parts,
                                 sprintf("Diversity: %.1f%% of features are unique to individual sets",
                                         100 - overlap_pct))
            }
          }
          
          context_parts <- c(context_parts, "\nUse the Venn/UpSet diagram to:")
          context_parts <- c(context_parts, "  - Identify common biomarkers across conditions")
          context_parts <- c(context_parts, "  - Find condition-specific features")
          context_parts <- c(context_parts, "  - Understand feature overlap patterns")
          
        } else {
          context_parts <- c(context_parts, "Intersection analysis loaded but results not yet computed")
        }
        
      } else {
        context_parts <- c(context_parts, "No intersection analysis results available yet")
        context_parts <- c(context_parts, "To perform intersection analysis:")
        context_parts <- c(context_parts, "  1. Select an analysis source (Pairwise, Intersection, or Manual)")
        context_parts <- c(context_parts, "  2. Choose comparisons to include")
        context_parts <- c(context_parts, "  3. Click 'Perform Analysis' button")
        context_parts <- c(context_parts, "  4. View results as Venn diagram (≤5 sets) or UpSet plot (>5 sets)")
      }
    }
    
    # ===== DIFFERENTIAL ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Differential Analysis") {
      context_parts <- c(context_parts, "\n=== DIFFERENTIAL ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing differential expression/abundance analysis results")
      
      # Check if analysis has been performed
      if (!is.null(values$diff_data) && nrow(values$diff_data) > 0) {
        # Basic comparison information
        context_parts <- c(context_parts, sprintf("Comparison: %s vs %s", input$diffGroup1, input$diffGroup2))
        
        # Analysis method information
        context_parts <- c(context_parts, "\n=== STATISTICAL METHOD ===")
        
        method_text <- switch(input$sig_method,
                              "t.test" = "Parametric t-test (two groups)",
                              "wilcox" = "Non-parametric Mann-Whitney U test (two groups)",
                              "anova" = "Parametric ANOVA (multiple groups)",
                              "kruskal" = "Non-parametric Kruskal-Wallis test (multiple groups)",
                              "deseq2" = "DESeq2 (RNA-seq, count-based)",
                              "edger" = "edgeR (RNA-seq, count-based)",
                              "limma" = "Limma (microarray/RNA-seq with design matrix)",
                              "limma_voom" = "Limma with voom transformation (RNA-seq count data)",
                              "rots" = "ROTS (Reproducibility-Optimized Test Statistic)",
                              input$sig_method)
        
        context_parts <- c(context_parts, sprintf("Method: %s", method_text))
        
        # Check for special features
        if (input$sig_method == "edger" && !is.null(input$batch_correction_enabled) && input$batch_correction_enabled == "yes") {
          context_parts <- c(context_parts, "Batch correction: Enabled (using edgeR GLM approach)")
        }
        
        # Significance thresholds
        context_parts <- c(context_parts, "\n=== SIGNIFICANCE THRESHOLDS ===")
        context_parts <- c(context_parts, sprintf("Log2 fold change threshold: %.2f", input$diff_fc_cutoff))
        
        if (input$sig_method == "rots" && !is.null(input$diff_fdr_cutoff)) {
          context_parts <- c(context_parts, sprintf("FDR cutoff: %.4f (ROTS method)", input$diff_fdr_cutoff))
        } else {
          context_parts <- c(context_parts, sprintf("P-value cutoff: %.4f", input$diff_pval_cutoff))
        }
        
        # Feature source
        if (!is.null(input$diff_feature_source)) {
          feature_source_text <- switch(input$diff_feature_source,
                                        "all" = "All features",
                                        "pca" = "PCA-selected features",
                                        "ml" = "Machine Learning-selected features",
                                        "All features")
          context_parts <- c(context_parts, sprintf("Feature source: %s", feature_source_text))
        }
        
        # Summary statistics
        context_parts <- c(context_parts, "\n=== RESULTS SUMMARY ===")
        
        total_features <- nrow(values$diff_data)
        upregulated <- sum(values$diff_data$Significance == "Upregulated", na.rm = TRUE)
        downregulated <- sum(values$diff_data$Significance == "Downregulated", na.rm = TRUE)
        non_significant <- sum(values$diff_data$Significance == "Not Significant", na.rm = TRUE)
        
        context_parts <- c(context_parts, sprintf("Total features analyzed: %d", total_features))
        context_parts <- c(context_parts, sprintf("Upregulated features (in %s): %d", input$diffGroup2, upregulated))
        context_parts <- c(context_parts, sprintf("Downregulated features (in %s): %d", input$diffGroup2, downregulated))
        context_parts <- c(context_parts, sprintf("Non-significant features: %d", non_significant))
        
        # Calculate and report percentages
        if (total_features > 0) {
          up_pct <- round(100 * upregulated / total_features, 1)
          down_pct <- round(100 * downregulated / total_features, 1)
          sig_pct <- round(100 * (upregulated + downregulated) / total_features, 1)
          
          context_parts <- c(context_parts, "")
          context_parts <- c(context_parts, sprintf("Upregulated percentage: %.1f%%", up_pct))
          context_parts <- c(context_parts, sprintf("Downregulated percentage: %.1f%%", down_pct))
          context_parts <- c(context_parts, sprintf("Total significant percentage: %.1f%%", sig_pct))
        }
        
        # Top features by statistical significance
        context_parts <- c(context_parts, "\n=== TOP SIGNIFICANT FEATURES (by p-value) ===")
        
        # Get top features (limit to 15)
        sig_features <- values$diff_data %>%
          dplyr::filter(Significance != "Not Significant") %>%
          dplyr::arrange(`Adjusted P-value`)
        
        top_n <- min(15, nrow(sig_features))
        
        if (top_n > 0) {
          for (i in 1:top_n) {
            feature <- sig_features[[i, "Feature"]]
            log2fc <- sig_features[[i, "Log2FC"]]
            p_value <- sig_features[[i, "Adjusted P-value"]]
            significance <- sig_features[[i, "Significance"]]
            
            # Format log2FC with sign
            fc_display <- sprintf("%+.3f", log2fc)
            direction <- if (log2fc > 0) "↑" else "↓"
            
            feature_line <- sprintf("%d. %s: log2FC=%s (%s), p-adj=%.2e, %s",
                                    i, feature, fc_display, direction, p_value, significance)
            context_parts <- c(context_parts, feature_line)
          }
          
          if (nrow(sig_features) > 15) {
            context_parts <- c(context_parts,
                               sprintf("... and %d more significant features", nrow(sig_features) - 15))
          }
        } else {
          context_parts <- c(context_parts, "No significant features found with current thresholds")
        }
        
        # Fold change statistics
        context_parts <- c(context_parts, "\n=== FOLD CHANGE STATISTICS ===")
        
        if (nrow(sig_features) > 0) {
          max_fc <- max(abs(sig_features$Log2FC), na.rm = TRUE)
          mean_fc <- mean(abs(sig_features$Log2FC), na.rm = TRUE)
          max_fc_feature <- sig_features$Feature[which.max(abs(sig_features$Log2FC))]
          max_fc_value <- sig_features$Log2FC[which.max(abs(sig_features$Log2FC))]
          
          context_parts <- c(context_parts, sprintf("Maximum absolute log2FC: %.3f (%s)", max_fc, max_fc_feature))
          context_parts <- c(context_parts, sprintf("Mean absolute log2FC (significant): %.3f", mean_fc))
          
          # Count features by fold change ranges
          very_high_fc <- sum(abs(sig_features$Log2FC) >= 2, na.rm = TRUE)
          high_fc <- sum(abs(sig_features$Log2FC) >= 1 & abs(sig_features$Log2FC) < 2, na.rm = TRUE)
          
          if (very_high_fc > 0) {
            context_parts <- c(context_parts, sprintf("Features with |log2FC| ≥ 2.0: %d (very high)", very_high_fc))
          }
          if (high_fc > 0) {
            context_parts <- c(context_parts, sprintf("Features with 1.0 ≤ |log2FC| < 2.0: %d (high)", high_fc))
          }
        }
        
        # Visualization information
        context_parts <- c(context_parts, "\n=== VISUALIZATIONS AVAILABLE ===")
        context_parts <- c(context_parts, "- MA Plot: Shows log fold change vs. mean expression/abundance")
        context_parts <- c(context_parts, "- Volcano Plot: Shows fold change vs. statistical significance")
        context_parts <- c(context_parts, "- Both plots highlight upregulated (red) and downregulated (blue) features")
        
        # Interpretation guidance
        context_parts <- c(context_parts, "\n=== INTERPRETATION ===")
        context_parts <- c(context_parts, "Upregulated features: Abundance/expression higher in group 2")
        context_parts <- c(context_parts, "Downregulated features: Abundance/expression lower in group 2")
        context_parts <- c(context_parts, sprintf("Comparison groups: Group 1 (%s) vs Group 2 (%s)", input$diffGroup1, input$diffGroup2))
        context_parts <- c(context_parts, "Use thresholds to focus on biologically relevant changes")
        
      } else {
        context_parts <- c(context_parts, "No differential analysis results available yet")
        context_parts <- c(context_parts, "To run differential analysis:")
        context_parts <- c(context_parts, "  1. Select two different groups to compare")
        context_parts <- c(context_parts, "  2. Set appropriate significance thresholds")
        context_parts <- c(context_parts, "  3. Choose feature set (all, PCA, or ML-selected)")
        context_parts <- c(context_parts, "  4. Results will automatically display when analysis is complete")
      }
    }
    
    # ===== DISTRIBUTION ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Distribution Analysis") {
      context_parts <- c(context_parts, "\n=== DISTRIBUTION ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing feature abundance distribution across groups")
      
      # Check if feature is selected and data exists
      if (!is.null(input$featureSelect) && !is.null(values$dist_test_results)) {
        feature_name <- input$featureSelect
        
        # Determine display label based on label type
        display_label <- feature_name
        if (!is.null(input$dist_label_type) && input$dist_label_type == "ids" &&
            !is.null(values$accession_ids) && length(values$accession_ids) > 0) {
          feature_idx <- which(values$cleaned_molecules == feature_name)[1]
          if (!is.na(feature_idx) && feature_idx <= length(values$accession_ids)) {
            display_label <- values$accession_ids[feature_idx]
          }
        }
        
        context_parts <- c(context_parts, sprintf("Feature analyzed: %s", display_label))
        
        # Visualization settings
        context_parts <- c(context_parts, "\n=== VISUALIZATION SETTINGS ===")
        
        plot_type <- input$plotType %||% "Boxplot"
        context_parts <- c(context_parts, sprintf("Plot type: %s", plot_type))
        
        if (!is.null(input$dist_feature_source)) {
          feature_source_text <- switch(input$dist_feature_source,
                                        "all" = "All features",
                                        "pca" = "PCA-selected features",
                                        "ml" = "Machine Learning-selected features",
                                        "All features")
          context_parts <- c(context_parts, sprintf("Feature source: %s", feature_source_text))
        }
        
        context_parts <- c(context_parts, sprintf("Show individual points: %s", if (input$showPoints) "Yes" else "No"))
        context_parts <- c(context_parts, sprintf("Show error bars: %s", if (input$showErrorBars) "Yes" else "No"))
        
        # Get summary statistics if available
        if (!is.null(values$dist_summary_stats)) {
          stats_df <- values$dist_summary_stats
          
          context_parts <- c(context_parts, "\n=== GROUP-WISE SUMMARY STATISTICS ===")
          
          for (i in 1:nrow(stats_df)) {
            group <- stats_df$Group[i]
            n <- stats_df$N[i]
            mean_val <- stats_df$Mean[i]
            sd_val <- stats_df$SD[i]
            median_val <- stats_df$Median[i]
            
            context_parts <- c(context_parts, sprintf("Group: %s", group))
            context_parts <- c(context_parts, sprintf("  N = %d", n))
            context_parts <- c(context_parts, sprintf("  Mean = %.3f ± %.3f (SD)", mean_val, sd_val))
            context_parts <- c(context_parts, sprintf("  Median = %.3f", median_val))
            context_parts <- c(context_parts, sprintf("  Range = %.3f to %.3f", stats_df$Min[i], stats_df$Max[i]))
            context_parts <- c(context_parts, "")
          }
        }
        
        # Statistical test results
        test_results <- values$dist_test_results
        if (!is.null(test_results)) {
          context_parts <- c(context_parts, "\n=== STATISTICAL TEST RESULTS ===")
          context_parts <- c(context_parts, sprintf("Test method: %s", test_results$method))
          
          # Overall test results
          if (!is.null(test_results$overall$p.value)) {
            p_value <- test_results$overall$p.value
            significant <- if (p_value < 0.05) "YES (p < 0.05)" else "NO (p ≥ 0.05)"
            context_parts <- c(context_parts, sprintf("Overall test p-value: %.4f", p_value))
            context_parts <- c(context_parts, sprintf("Significantly different between groups: %s", significant))
          }
          
          # Fold change information
          if (!is.null(test_results$overall$fold_change)) {
            fc <- test_results$overall$fold_change
            context_parts <- c(context_parts, sprintf("Fold change (log2): %.3f", fc))
          }
          
          # Post-hoc results if available
          if (!is.null(test_results$posthoc) && length(test_results$posthoc) > 0) {
            context_parts <- c(context_parts, "\nPost-hoc pairwise comparisons:")
            
            for (comp in names(test_results$posthoc)) {
              p_val <- test_results$posthoc[[comp]]
              sig_marker <- if (p_val < 0.05) "*" else ""
              context_parts <- c(context_parts,
                                 sprintf("  %s: p = %.4f %s", comp, p_val, sig_marker))
            }
          }
        } else {
          context_parts <- c(context_parts, "\n=== STATISTICAL RESULTS ===")
          context_parts <- c(context_parts, "Statistical tests not yet computed")
          context_parts <- c(context_parts, "Run statistical analysis in the Data tab first")
        }
        
        # Normality information
        context_parts <- c(context_parts, "\n=== DATA DISTRIBUTION CHARACTERISTICS ===")
        context_parts <- c(context_parts, "Plot types help assess data distribution:")
        context_parts <- c(context_parts, "- Boxplot: Shows quartiles and outliers")
        context_parts <- c(context_parts, "- Violin: Shows full distribution shape")
        context_parts <- c(context_parts, "- Ridgeline: Compares distributions side-by-side")
        context_parts <- c(context_parts, "- Swarm/Strip: Shows individual data points")
        
        context_parts <- c(context_parts, "\nKey observations:")
        context_parts <- c(context_parts, "- Symmetric distributions suggest normal data")
        context_parts <- c(context_parts, "- Skewed distributions may need transformation or non-parametric tests")
        context_parts <- c(context_parts, "- Outliers visible in boxplots may warrant investigation")
        
      } else if (!is.null(input$featureSelect)) {
        # Feature selected but no test results
        context_parts <- c(context_parts, sprintf("Feature selected: %s", input$featureSelect))
        context_parts <- c(context_parts, "No statistical test results available yet")
        context_parts <- c(context_parts, "Results will display once data is loaded and analyzed")
        
      } else {
        # No feature selected
        context_parts <- c(context_parts, "No feature currently selected")
        context_parts <- c(context_parts, "To view distribution analysis:")
        context_parts <- c(context_parts, "  1. Select a feature from the Feature dropdown")
        context_parts <- c(context_parts, "  2. Choose plot type (Boxplot, Violin, Ridgeline, etc.)")
        context_parts <- c(context_parts, "  3. Adjust visualization settings as needed")
        context_parts <- c(context_parts, "  4. Statistical comparisons shown if available")
      }
    }
    
    # ===== HEATMAPS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Heatmaps") {
      context_parts <- c(context_parts, "\n=== HEATMAP ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing hierarchical clustered heatmaps of feature expression/abundance")
      
      # Check if heatmap data is available
      if (!is.null(values$heatmap_data) && nrow(values$heatmap_data) > 0) {
        
        # Analysis type information
        analysis_type <- input$heatmapType %||% "all_groups"
        
        if (analysis_type == "pairwise") {
          context_parts <- c(context_parts, sprintf("Analysis type: Pairwise Comparison"))
          if (!is.null(input$group1) && !is.null(input$group2)) {
            context_parts <- c(context_parts, sprintf("Comparing: %s vs %s", input$group1, input$group2))
          }
        } else {
          context_parts <- c(context_parts, sprintf("Analysis type: All Groups"))
        }
        
        # Feature source information
        context_parts <- c(context_parts, "\n=== HEATMAP CONFIGURATION ===")
        
        if (!is.null(input$heatmap_feature_source)) {
          feature_source_text <- switch(input$heatmap_feature_source,
                                        "all" = "All features",
                                        "pca" = "PCA-selected features",
                                        "ml" = "Machine Learning-selected features",
                                        "All features")
          context_parts <- c(context_parts, sprintf("Feature source: %s", feature_source_text))
        }
        
        # Heatmap dimensions
        n_features <- nrow(values$heatmap_data)
        n_samples <- ncol(values$heatmap_data)
        context_parts <- c(context_parts, sprintf("Heatmap dimensions: %d features × %d samples",
                                                  n_features, n_samples))
        
        # Filtering criteria
        context_parts <- c(context_parts, "\n=== FILTERING CRITERIA ===")
        
        if (!is.null(input$pvalue_cutoff)) {
          context_parts <- c(context_parts, sprintf("P-value threshold: %.4f", input$pvalue_cutoff))
        }
        
        if (!is.null(input$fc_cutoff)) {
          context_parts <- c(context_parts, sprintf("Log2FC threshold: %.2f", input$fc_cutoff))
        }
        
        if (input$sig_method == "rots" && !is.null(input$fdr_cutoff)) {
          context_parts <- c(context_parts, sprintf("FDR threshold: %.4f (ROTS)", input$fdr_cutoff))
        }
        
        # Clustering information
        context_parts <- c(context_parts, "\n=== CLUSTERING ===")
        
        cluster_rows <- input$cluster_rows %||% TRUE
        cluster_cols <- input$cluster_cols %||% FALSE
        
        context_parts <- c(context_parts, sprintf("Row clustering (features): %s",
                                                  if (cluster_rows) "Yes (hierarchical)" else "No"))
        context_parts <- c(context_parts, sprintf("Column clustering (samples): %s",
                                                  if (cluster_cols) "Yes (hierarchical)" else "No"))
        
        # Row naming information
        context_parts <- c(context_parts, "\n=== ROW LABELS ===")
        
        show_names <- input$show_row_names %||% TRUE
        if (show_names) {
          label_type <- input$heatmap_label_type %||% "features"
          label_text <- if (label_type == "ids") "Accession IDs" else "Feature Names"
          context_parts <- c(context_parts, sprintf("Row labels visible: Yes (%s)", label_text))
        } else {
          context_parts <- c(context_parts, "Row labels visible: No")
        }
        
        # Data transformation info
        context_parts <- c(context_parts, "\n=== DATA PROCESSING ===")
        context_parts <- c(context_parts, "Z-score normalization: Applied (per row)")
        context_parts <- c(context_parts, "This standardizes each feature across samples for better color contrast")
        
        # Color scheme information
        context_parts <- c(context_parts, "\n=== COLOR SCHEME ===")
        context_parts <- c(context_parts, "Diverging color gradient:")
        low_col <- input$lowColor %||% "green"
        mid_col <- input$midColor %||% "black"
        high_col <- input$highColor %||% "red"
        context_parts <- c(context_parts, sprintf("  Low values: %s, Mid: %s, High: %s",
                                                  low_col, mid_col, high_col))
        context_parts <- c(context_parts, "Z-score of 0 appears as mid-color")
        context_parts <- c(context_parts, "Negative Z-scores show as low-color, positive as high-color")
        
        # Feature statistics
        context_parts <- c(context_parts, "\n=== DISPLAYED FEATURES ===")
        
        if (analysis_type == "pairwise" && !is.null(values$log2fc_pairwise)) {
          fc_values <- values$log2fc_pairwise
          up_count <- sum(fc_values > 0, na.rm = TRUE)
          down_count <- sum(fc_values < 0, na.rm = TRUE)
          
          context_parts <- c(context_parts, sprintf("Total significant features: %d", length(fc_values)))
          context_parts <- c(context_parts, sprintf("  Upregulated in %s: %d", input$group2, up_count))
          context_parts <- c(context_parts, sprintf("  Downregulated in %s: %d", input$group2, down_count))
          
          # Fold change range
          max_up <- max(fc_values[fc_values > 0], na.rm = TRUE)
          max_down <- min(fc_values[fc_values < 0], na.rm = TRUE)
          
          if (!is.na(max_up)) {
            context_parts <- c(context_parts, sprintf("  Max upregulation (log2FC): %.2f", max_up))
          }
          if (!is.na(max_down)) {
            context_parts <- c(context_parts, sprintf("  Max downregulation (log2FC): %.2f", max_down))
          }
        } else {
          context_parts <- c(context_parts, sprintf("Features shown: %d (meeting significance thresholds)", n_features))
        }
        
        # Interpretation guidance
        context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDE ===")
        context_parts <- c(context_parts, "Heatmap reading tips:")
        context_parts <- c(context_parts, "- Rows represent individual features (genes/proteins/metabolites)")
        context_parts <- c(context_parts, "- Columns represent individual samples")
        context_parts <- c(context_parts, "- Color intensity indicates abundance level after normalization")
        context_parts <- c(context_parts, "- Clustering groups similar features and samples together")
        context_parts <- c(context_parts, "- White/gray cells indicate missing or NA values")
        
      } else {
        context_parts <- c(context_parts, "No heatmap data currently displayed")
        context_parts <- c(context_parts, "To generate a heatmap:")
        context_parts <- c(context_parts, "  1. Select analysis type (All Groups or Pairwise Comparison)")
        context_parts <- c(context_parts, "  2. Choose groups to compare (if pairwise)")
        context_parts <- c(context_parts, "  3. Set significance thresholds (p-value, FDR, log2FC)")
        context_parts <- c(context_parts, "  4. Configure visualization options (clustering, colors, labels)")
        context_parts <- c(context_parts, "  5. Heatmap will render automatically")
      }
    }
    
    # ===== DIMENSIONALITY REDUCTION TAB =====
    if (!is.null(input$navbar) && input$navbar == "Dimensionality Reduction") {
      context_parts <- c(context_parts, "\n=== DIMENSIONALITY REDUCTION ===")
      
      # Check which method is active in the sub-navigation
      active_dimred_method <- input$dimred_navbar %||% "PCA"
      
      if (active_dimred_method == "PCA") {
        # PCA Analysis Context
        context_parts <- c(context_parts, "\n--- PCA Analysis ---")
        
        if (!is.null(values$pca_result) && !is.null(values$pca_data)) {
          # Analysis type and configuration
          pca_type <- input$pcaType %||% "all"
          if (pca_type == "pairwise") {
            group1 <- input$pcaGroup1
            group2 <- input$pcaGroup2
            if (!is.null(group1) && !is.null(group2)) {
              context_parts <- c(context_parts, sprintf("Analysis Type: Pairwise Comparison (%s vs %s)", group1, group2))
            }
          } else {
            context_parts <- c(context_parts, "Analysis Type: All Groups")
          }
          
          # Data scaling status
          if (isTRUE(input$pcaScale)) {
            context_parts <- c(context_parts, "Data scaling: Enabled (standardized to mean=0, sd=1)")
          } else {
            context_parts <- c(context_parts, "Data scaling: Disabled (using raw values)")
          }
          
          # PCA dimensions and variance explained
          variance_explained <- summary(values$pca_result)$importance[2, ] * 100
          n_pcs <- min(5, length(variance_explained))
          
          context_parts <- c(context_parts, sprintf("\nNumber of features analyzed: %d", ncol(values$pca_data)))
          context_parts <- c(context_parts, sprintf("Number of samples: %d", nrow(values$pca_data)))
          
          context_parts <- c(context_parts, "\n=== VARIANCE EXPLAINED BY PRINCIPAL COMPONENTS ===")
          for (i in 1:n_pcs) {
            var_pct <- round(variance_explained[i], 1)
            cumsum_var <- round(sum(variance_explained[1:i]), 1)
            context_parts <- c(context_parts, sprintf("PC%d: %.1f%% (Cumulative: %.1f%%)", i, var_pct, cumsum_var))
          }
          
          # Top contributing features
          if (!is.null(values$pca_result$rotation)) {
            loadings <- values$pca_result$rotation
            
            # PC1 loadings
            pc1_loadings <- abs(loadings[, 1])
            top_pc1_idx <- order(pc1_loadings, decreasing = TRUE)[1:min(10, length(pc1_loadings))]
            
            context_parts <- c(context_parts, "\n=== TOP 10 FEATURES CONTRIBUTING TO PC1 ===")
            if (!is.null(values$cleaned_molecules)) {
              feature_names <- values$cleaned_molecules[top_pc1_idx]
            } else {
              feature_names <- rownames(loadings)[top_pc1_idx]
            }
            
            for (i in 1:length(top_pc1_idx)) {
              idx <- top_pc1_idx[i]
              loading_val <- loadings[idx, 1]
              context_parts <- c(context_parts,
                                 sprintf("%d. %s (Loading: %+.4f)", i, feature_names[i], loading_val))
            }
            
            # PC2 loadings
            pc2_loadings <- abs(loadings[, 2])
            top_pc2_idx <- order(pc2_loadings, decreasing = TRUE)[1:min(10, length(pc2_loadings))]
            
            context_parts <- c(context_parts, "\n=== TOP 10 FEATURES CONTRIBUTING TO PC2 ===")
            if (!is.null(values$cleaned_molecules)) {
              feature_names <- values$cleaned_molecules[top_pc2_idx]
            } else {
              feature_names <- rownames(loadings)[top_pc2_idx]
            }
            
            for (i in 1:length(top_pc2_idx)) {
              idx <- top_pc2_idx[i]
              loading_val <- loadings[idx, 2]
              context_parts <- c(context_parts,
                                 sprintf("%d. %s (Loading: %+.4f)", i, feature_names[i], loading_val))
            }
          }
          
          # Visualization options
          if (isTRUE(input$addEllipses)) {
            context_parts <- c(context_parts,
                               sprintf("Confidence ellipses: Enabled (%.0f%% confidence level)", input$ellipseLevel * 100))
          }
          
          # Top N features for downstream analysis
          if (!is.null(values$pca_top_features) && length(values$pca_top_features) > 0) {
            context_parts <- c(context_parts,
                               sprintf("\nTop N features selected for downstream analysis: %d features",
                                       length(values$pca_top_features)))
            
            feature_ranking_method <- input$pca_feature_ranking %||% "overall"
            ranking_text <- switch(feature_ranking_method,
                                   "overall" = "Overall contribution (sum of squared loadings)",
                                   "pc1" = "PC1 contribution",
                                   "pc2" = "PC2 contribution",
                                   "pc1_pc2" = "PC1 + PC2 combined",
                                   feature_ranking_method)
            context_parts <- c(context_parts, sprintf("Feature ranking method: %s", ranking_text))
          }
          
        } else {
          context_parts <- c(context_parts, "PCA analysis not yet performed.")
          context_parts <- c(context_parts, "\nTo run PCA:")
          context_parts <- c(context_parts, "  1. Select analysis type (All Groups or Pairwise Comparison)")
          context_parts <- c(context_parts, "  2. Configure PCA settings (scaling, ellipses, labels)")
          context_parts <- c(context_parts, "  3. Results will appear in PCA Plot, Scree Plot, and Loadings tabs")
          context_parts <- c(context_parts, "  4. Top N features can be selected for downstream analysis")
        }
        
      } else if (active_dimred_method == "UMAP" || active_dimred_method == "tSNE") {
        # UMAP or t-SNE Analysis Context
        method_name <- active_dimred_method
        context_parts <- c(context_parts, sprintf("\n--- %s Analysis ---", method_name))
        
        method_abbrev <- if (active_dimred_method == "UMAP") "UMAP" else "t-SNE"
        plot_obj <- if (active_dimred_method == "UMAP") values$umap_plot_obj else values$tsne_plot_obj
        
        if (!is.null(plot_obj)) {
          context_parts <- c(context_parts,
                             sprintf("%s dimensionality reduction applied to visualize data patterns and cluster structure.", method_name))
          
          # Extract plot information from ggplot object if available
          if (!is.null(input$umap_groups_to_color) || !is.null(input$tsne_groups_to_color)) {
            selected_groups <- if (active_dimred_method == "UMAP") input$umap_groups_to_color else input$tsne_groups_to_color
            context_parts <- c(context_parts, sprintf("Colored by groups: %s", paste(selected_groups, collapse = ", ")))
          }
          
          # Other visualization parameters
          if (active_dimred_method == "UMAP") {
            context_parts <- c(context_parts, sprintf("UMAP parameters: n_neighbors=%d, min_dist=%.3f, metric=%s",
                                                      input$umap_n_neighbors %||% 15,
                                                      input$umap_min_dist %||% 0.1,
                                                      input$umap_metric %||% "euclidean"))
          } else if (active_dimred_method == "tSNE") {
            context_parts <- c(context_parts, sprintf("t-SNE parameters: perplexity=%d, theta=%.2f",
                                                      input$tsne_perplexity %||% 30,
                                                      input$tsne_theta %||% 0.5))
          }
        } else {
          context_parts <- c(context_parts,
                             sprintf("%s analysis not yet performed.", method_name))
          context_parts <- c(context_parts,
                             sprintf("To run %s: Configure parameters and click 'Run %s' button", method_name, method_name))
        }
        
      } else {
        # sPCA or other method
        method_name <- active_dimred_method %||% "Sparse PCA"
        context_parts <- c(context_parts, sprintf("\n--- %s Analysis ---", method_name))
        context_parts <- c(context_parts, sprintf("Analysis method: %s", method_name))
        context_parts <- c(context_parts, "Sparse PCA (sPCA) performs feature selection during dimensionality reduction by enforcing sparsity constraints.")
        
        if (!is.null(values$spca_result)) {
          context_parts <- c(context_parts, "Sparse PCA analysis completed successfully.")
          
          # Extract sparsity parameters if available
          if (!is.null(input$spca_keepX_pc1) && !is.null(input$spca_keepX_pc2)) {
            context_parts <- c(context_parts,
                               sprintf("Sparsity parameters: PC1 keepX=%d, PC2 keepX=%d",
                                       input$spca_keepX_pc1, input$spca_keepX_pc2))
          }
          
          # Get selected variables (non-zero loadings) from sPCA result
          spca_res <- values$spca_result
          if (!is.null(spca_res$loadings) && !is.null(spca_res$loadings$X)) {
            loadings_matrix <- spca_res$loadings$X
            n_pcs <- ncol(loadings_matrix)
            
            context_parts <- c(context_parts, sprintf("Number of sparse components: %d", n_pcs))
            
            # Count and list selected variables per component
            for (pc_idx in 1:min(3, n_pcs)) {
              pc_name <- colnames(loadings_matrix)[pc_idx]
              pc_loadings <- loadings_matrix[, pc_idx]
              selected_vars <- names(pc_loadings)[pc_loadings != 0]
              n_selected <- length(selected_vars)
              
              context_parts <- c(context_parts, sprintf("\n%s: %d features selected", pc_name, n_selected))
              
              # Top contributing features (by absolute loading)
              if (n_selected > 0) {
                top_loadings <- sort(abs(pc_loadings[selected_vars]), decreasing = TRUE)[1:min(5, n_selected)]
                top_features <- names(top_loadings)
                context_parts <- c(context_parts, sprintf("  Top features: %s", paste(top_features, collapse = ", ")))
              }
            }
            
            # Total unique features across all components
            all_selected <- unique(unlist(lapply(1:n_pcs, function(i) {
              names(loadings_matrix[, i])[loadings_matrix[, i] != 0]
            })))
            context_parts <- c(context_parts, sprintf("\nTotal unique features across all components: %d", length(all_selected)))
          }
          
          # Variance explained if available
          if (!is.null(spca_res$prop_expl_var) && !is.null(spca_res$prop_expl_var$X)) {
            var_expl <- spca_res$prop_expl_var$X
            context_parts <- c(context_parts, "\nVariance explained per component:")
            for (i in 1:min(3, length(var_expl))) {
              context_parts <- c(context_parts, sprintf("  PC%d: %.1f%%", i, var_expl[i] * 100))
            }
            context_parts <- c(context_parts, sprintf("  Total: %.1f%%", sum(var_expl[1:min(3, length(var_expl))]) * 100))
          }
          
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- sPCA reduces data complexity while SELECTING key features")
          context_parts <- c(context_parts, "- Non-zero loadings = features contributing to that component")
          context_parts <- c(context_parts, "- Selected features can be exported for downstream analysis")
          context_parts <- c(context_parts, "- Use the Loadings tab to see feature contributions")
          context_parts <- c(context_parts, "- Compare to standard PCA to assess sparsity trade-off")
          
        } else {
          context_parts <- c(context_parts, sprintf("%s analysis not yet performed.", method_name))
          context_parts <- c(context_parts, "\nTo run Sparse PCA:")
          context_parts <- c(context_parts, "  1. Select 'sPCA (Sparse PCA)' from the method dropdown")
          context_parts <- c(context_parts, "  2. Set keepX values for each component (number of features to select)")
          context_parts <- c(context_parts, "  3. Configure visualization options (point size, colors)")
          context_parts <- c(context_parts, "  4. Click 'Run sPCA' button")
          context_parts <- c(context_parts, "  5. View selected features in the Loadings tab")
        }
      }
    }
    
    # ===== ML FEATURE SELECTION TAB =====
    if (!is.null(input$navbar) && input$navbar == "ML Feature Selection") {
      context_parts <- c(context_parts, "\n=== ML FEATURE SELECTION ===")
      
      if (!is.null(values$ml_selected_features) && nrow(values$ml_selected_features) > 0) {
        # Feature selection method information
        method_name <- "Unknown Method"
        if (!is.null(values$ml_method_used)) {
          method_name <- switch(values$ml_method_used,
                                "boruta" = "Boruta (Importance Source: Random Forest)",
                                "boruta_multiclass" = "Boruta Multi-class (Importance Source: Random Forest)",
                                "rf" = "Random Forest",
                                "rfe" = "Recursive Feature Elimination",
                                "permutation" = "Permutation Importance",
                                "lasso" = {
                                  if (!is.null(values$ml_glmnet_family)) {
                                    family_text <- switch(values$ml_glmnet_family,
                                                          "binomial" = "Binary Classification",
                                                          "multinomial" = "Multi-class Classification",
                                                          "gaussian" = "Continuous Regression",
                                                          "poisson" = "Poisson Regression",
                                                          "cox" = "Cox Survival",
                                                          values$ml_glmnet_family)
                                    alpha_text <- if (!is.null(values$ml_glmnet_alpha)) {
                                      if (values$ml_glmnet_alpha == 1) "Pure LASSO (L1)"
                                      else if (values$ml_glmnet_alpha == 0) "Ridge (L2)"
                                      else sprintf("Elastic Net (Alpha=%.2f)", values$ml_glmnet_alpha)
                                    } else "LASSO"
                                    sprintf("LASSO/ElasticNet (%s, %s)", family_text, alpha_text)
                                  } else "LASSO/ElasticNet"
                                },
                                values$ml_method_used)
        } else if (!is.null(input$feature_selection_method)) {
          method_name <- switch(input$feature_selection_method,
                                "rf" = "Random Forest",
                                "rfe" = "Recursive Feature Elimination",
                                "permutation" = "Permutation Importance",
                                "boruta" = "Boruta",
                                "lasso" = "LASSO/ElasticNet",
                                "Feature Selection")
        }
        
        context_parts <- c(context_parts, sprintf("Feature Selection Method: %s", method_name))
        
        # Data characteristics
        if (!is.null(input$feature_selection_target)) {
          context_parts <- c(context_parts, sprintf("Target Variable: %s", input$feature_selection_target))
        }
        
        # Filtering information
        if (!is.null(input$feature_filtering_method) && input$feature_filtering_method != "none") {
          filter_text <- switch(input$feature_filtering_method,
                                "variance" = sprintf("Variance Threshold (min variance = %.4f)", input$feature_filtering_variance),
                                "correlation" = sprintf("Correlation Filter (min |r| = %.3f)", input$feature_filtering_corr_cutoff),
                                "pca" = sprintf("PCA Top N Features (from Dimensionality Reduction tab)"),
                                "None")
          context_parts <- c(context_parts, sprintf("Pre-selection Filtering: %s", filter_text))
        }
        
        # Train/Test split information
        if (isTRUE(input$enable_train_test_split)) {
          train_ratio <- sprintf("%.0f%%", input$train_test_ratio %||% 80)
          split_type <- if (isTRUE(input$stratified_split)) "Stratified" else "Random"
          context_parts <- c(context_parts, sprintf("Train/Test Split: %s split (%s training ratio)", split_type, train_ratio))
          if (!is.null(values$ml_train_indices) && !is.null(values$ml_test_indices)) {
            context_parts <- c(context_parts, sprintf("Training samples: %d | Test samples: %d",
                                                      length(values$ml_train_indices), length(values$ml_test_indices)))
          }
        }
        
        # Selected features information
        n_selected <- nrow(values$ml_selected_features)
        context_parts <- c(context_parts, sprintf("Features Selected: %d", n_selected))
        
        # Display top selected features with importance scores
        if ("Importance" %in% colnames(values$ml_selected_features)) {
          top_n <- min(15, nrow(values$ml_selected_features))
          top_features <- values$ml_selected_features[1:top_n, , drop = FALSE]
          
          context_parts <- c(context_parts, "\n=== TOP SELECTED FEATURES ===")
          for (i in 1:nrow(top_features)) {
            feature_name <- top_features$Feature[i]
            importance_val <- top_features$Importance[i]
            context_parts <- c(context_parts,
                               sprintf("%d. %s (Importance: %.4f)", i, feature_name, importance_val))
          }
          
          # Summary statistics for importance scores
          if (nrow(values$ml_selected_features) > 0) {
            min_imp <- min(values$ml_selected_features$Importance, na.rm = TRUE)
            max_imp <- max(values$ml_selected_features$Importance, na.rm = TRUE)
            mean_imp <- mean(values$ml_selected_features$Importance, na.rm = TRUE)
            context_parts <- c(context_parts,
                               sprintf("\nImportance Score Range: Min=%.4f, Mean=%.4f, Max=%.4f", min_imp, mean_imp, max_imp))
          }
        }
        
        # Additional columns (Rank, Stats, etc.)
        if ("Rank" %in% colnames(values$ml_selected_features)) {
          context_parts <- c(context_parts, "Features are ranked by importance score")
        }
        
        if ("mean_imp" %in% colnames(values$ml_selected_features) || "shadow_imp" %in% colnames(values$ml_selected_features)) {
          context_parts <- c(context_parts, "Boruta statistics available: confirmed vs tentative importance comparison")
        }
        
        # Stability information for Random Forest
        if (!is.null(values$ml_rf_stability_scores) && length(values$ml_rf_stability_scores) > 0) {
          context_parts <- c(context_parts,
                             sprintf("Random Forest Stability Scores: Calculated using %s method",
                                     values$ml_rf_stability_method %||% "Jaccard similarity"))
        }
        
        # Cross-validation information for LASSO
        if (!is.null(values$ml_cv_fit) && !is.null(values$ml_lambda_best)) {
          context_parts <- c(context_parts,
                             sprintf("LASSO Cross-Validation: Optimal lambda = %.6f (from %d-fold CV)",
                                     values$ml_lambda_best, input$glmnet_nfolds %||% 10))
        }
        
        # Scaling information
        if (isTRUE(input$feature_selection_scale)) {
          context_parts <- c(context_parts, "Data was scaled and centered before feature selection")
        }
        
        # Seed for reproducibility
        if (!is.null(input$feature_selection_seed)) {
          context_parts <- c(context_parts,
                             sprintf("Random seed: %d (for reproducible results)", input$feature_selection_seed))
        }
        
      } else {
        context_parts <- c(context_parts, "No features selected yet. Please run feature selection analysis.")
        context_parts <- c(context_parts, "\nTo run ML Feature Selection:")
        context_parts <- c(context_parts, "  1. Select a feature selection method (LASSO/ElasticNet, Random Forest, Boruta, RFE, or Permutation)")
        context_parts <- c(context_parts, "  2. Configure method-specific parameters")
        context_parts <- c(context_parts, "  3. Optionally apply pre-selection filtering (Variance, Correlation, or PCA)")
        context_parts <- c(context_parts, "  4. Click 'Run Feature Selection' button")
        context_parts <- c(context_parts, "  5. View results in the Features Table and Feature Importance plot")
      }
    }
    
    # ===== MULTI-OMICS INTEGRATION TAB =====
    if (!is.null(input$navbar) && input$navbar == "Multi-Omics Integration") {
      context_parts <- c(context_parts, "\n=== MULTI-OMICS INTEGRATION ===")
      context_parts <- c(context_parts, "You are viewing multi-omics integration analysis for cross-layer biological insights")
      
      # Check loaded analyses
      if (!is.null(multiomics$loaded_analyses) && length(multiomics$loaded_analyses) > 0) {
        context_parts <- c(context_parts, sprintf("\nLoaded Analyses: %d datasets", length(multiomics$loaded_analyses)))
        for (name in names(multiomics$loaded_analyses)) {
          analysis <- multiomics$loaded_analyses[[name]]
          n_features <- if (!is.null(analysis$data)) nrow(analysis$data) else 0
          n_samples <- if (!is.null(analysis$data)) ncol(analysis$data) else 0
          omics_type <- analysis$omics_type %||% "Unknown"
          context_parts <- c(context_parts, sprintf("  - %s: %s (%d features × %d samples)", 
                                                    name, omics_type, n_features, n_samples))
        }
      }
      
      # Common samples
      if (!is.null(multiomics$common_samples) && length(multiomics$common_samples) > 0) {
        context_parts <- c(context_parts, sprintf("\nCommon samples across datasets: %d", length(multiomics$common_samples)))
      }
      
      # Sample groups information
      if (!is.null(multiomics$sample_groups)) {
        group_table <- table(multiomics$sample_groups)
        context_parts <- c(context_parts, sprintf("Sample groups: %s", paste(names(group_table), collapse = ", ")))
        for (grp in names(group_table)) {
          context_parts <- c(context_parts, sprintf("  - %s: %d samples", grp, group_table[grp]))
        }
      }
      
      # Integration method selection
      integration_method <- input$integration_method %||% "mofa"
      context_parts <- c(context_parts, sprintf("\nSelected integration method: %s", toupper(integration_method)))
      
      # Check if integration results exist
      if (!is.null(multiomics$integration_results)) {
        result <- multiomics$integration_results
        
        # ===== MOFA RESULTS =====
        if (result$method == "mofa") {
          context_parts <- c(context_parts, "\n=== MOFA ANALYSIS RESULTS ===")
          context_parts <- c(context_parts, "Multi-Omics Factor Analysis (MOFA) - Unsupervised factor decomposition")
          
          # Views/Datasets integrated
          if (!is.null(result$views) && length(result$views) > 0) {
            context_parts <- c(context_parts, sprintf("Views integrated: %s", paste(result$views, collapse = ", ")))
          }
          
          # Number of factors
          n_factors <- if (!is.null(result$variance_explained)) {
            if (is.matrix(result$variance_explained) || is.data.frame(result$variance_explained)) {
              nrow(result$variance_explained)
            } else length(result$variance_explained)
          } else if (!is.null(result$factors)) {
            sum(grepl("^Factor", colnames(result$factors)))
          } else NA
          
          if (!is.na(n_factors)) {
            context_parts <- c(context_parts, sprintf("Number of factors learned: %d", n_factors))
          }
          
          # Variance explained per factor per view
          if (!is.null(result$variance_explained)) {
            context_parts <- c(context_parts, "\n=== VARIANCE EXPLAINED PER FACTOR ===")
            var_df <- tryCatch(as.data.frame(result$variance_explained), error = function(e) NULL)
            
            if (!is.null(var_df) && nrow(var_df) > 0 && ncol(var_df) > 0) {
              multiplier <- if (max(result$variance_explained, na.rm = TRUE) > 1) 1 else 100
              
              for (i in seq_len(min(5, nrow(var_df)))) {
                factor_vals <- sapply(colnames(var_df), function(view) {
                  val <- var_df[i, view]
                  if (is.na(val)) return(NA)
                  sprintf("%s: %.1f%%", view, val * multiplier)
                })
                factor_vals <- factor_vals[!is.na(factor_vals)]
                context_parts <- c(context_parts, sprintf("Factor %d: %s", i, paste(factor_vals, collapse = ", ")))
              }
              
              # Total variance explained per view
              if (!is.null(result$variance_explained_total_view)) {
                context_parts <- c(context_parts, "\nTotal variance explained per view:")
                for (view in names(result$variance_explained_total_view)) {
                  total <- result$variance_explained_total_view[[view]]
                  mult <- if (total > 1) 1 else 100
                  context_parts <- c(context_parts, sprintf("  %s: %.1f%%", view, total * mult))
                }
              }
            }
          }
          
          # Top contributing features per factor
          if (!is.null(result$top_features) && length(result$top_features) > 0) {
            context_parts <- c(context_parts, "\n=== TOP FEATURES PER FACTOR ===")
            for (factor_name in names(result$top_features)[1:min(3, length(result$top_features))]) {
              context_parts <- c(context_parts, sprintf("\n%s:", factor_name))
              factor_features <- result$top_features[[factor_name]]
              if (!is.null(factor_features)) {
                for (view in names(factor_features)[1:min(2, length(factor_features))]) {
                  top_3 <- head(factor_features[[view]], 3)
                  if (!is.null(top_3) && "Feature" %in% colnames(top_3)) {
                    features_str <- paste(top_3$Feature, collapse = ", ")
                    context_parts <- c(context_parts, sprintf("  %s: %s", view, features_str))
                  }
                }
              }
            }
          }
          
          # MOFA factor scores availability
          if (!is.null(result$factors) && nrow(result$factors) > 0) {
            context_parts <- c(context_parts, sprintf("\nFactor scores available for %d samples", nrow(result$factors)))
          }
          
          # Weights availability
          if (!is.null(result$weights) && length(result$weights) > 0) {
            context_parts <- c(context_parts, "Feature weights (loadings) available for all views")
          }
          
          # MOFA model object
          if (!is.null(result$mofa_model)) {
            context_parts <- c(context_parts, "Full MOFA model object available for advanced analysis")
          }
          
          # Interpretation guidance
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- Factors with high variance in MULTIPLE views = SHARED patterns across omics layers")
          context_parts <- c(context_parts, "- Factors with high variance in ONE view = DATASET-SPECIFIC patterns")
          context_parts <- c(context_parts, "- Top features per factor identify key drivers of coordinated variation")
          context_parts <- c(context_parts, "- Use Factor Values tab to see sample-factor associations")
          context_parts <- c(context_parts, "- Use Associations tab to correlate factors with covariates")
        }
        
        # ===== DIABLO RESULTS =====
        else if (result$method == "diablo") {
          context_parts <- c(context_parts, "\n=== DIABLO ANALYSIS RESULTS ===")
          context_parts <- c(context_parts, "Data Integration Analysis for Biomarker discovery using Latent variable approaches for Omics studies")
          context_parts <- c(context_parts, "DIABLO is a SUPERVISED method that maximizes covariance between blocks while discriminating groups")
          
          # Grouping variable
          if (!is.null(result$Y)) {
            group_table <- table(result$Y)
            context_parts <- c(context_parts, sprintf("\nClassification groups: %s", paste(names(group_table), collapse = " vs ")))
            for (grp in names(group_table)) {
              context_parts <- c(context_parts, sprintf("  - %s: %d samples", grp, group_table[grp]))
            }
          }
          
          # Number of components
          if (!is.null(result$ncomp)) {
            context_parts <- c(context_parts, sprintf("Number of components: %d", result$ncomp))
          }
          
          # Blocks/datasets integrated
          if (!is.null(result$sample_coords) && length(result$sample_coords) > 0) {
            context_parts <- c(context_parts, sprintf("Data blocks integrated: %s", 
                                                      paste(names(result$sample_coords), collapse = ", ")))
          }
          
          # Features selected per block (keepX)
          if (!is.null(result$keepX) && length(result$keepX) > 0) {
            context_parts <- c(context_parts, "\n=== FEATURES SELECTED PER BLOCK ===")
            for (block_name in names(result$keepX)) {
              keep_values <- result$keepX[[block_name]]
              total_kept <- sum(keep_values)
              context_parts <- c(context_parts, sprintf("  %s: %d features selected", block_name, total_kept))
            }
          }
          
          # Variable importance
          if (!is.null(result$var_importance) && length(result$var_importance) > 0) {
            context_parts <- c(context_parts, "\n=== TOP DISCRIMINATING FEATURES ===")
            for (block_name in names(result$var_importance)[1:min(2, length(result$var_importance))]) {
              block_imp <- result$var_importance[[block_name]]
              if (!is.null(block_imp) && nrow(block_imp) > 0) {
                context_parts <- c(context_parts, sprintf("\n%s block:", block_name))
                top_5 <- head(block_imp[order(-abs(block_imp$importance)), ], 5)
                for (i in 1:nrow(top_5)) {
                  context_parts <- c(context_parts, sprintf("  %d. %s (importance: %.3f)", 
                                                            i, top_5$feature[i], top_5$importance[i]))
                }
              }
            }
          }
          
          # Classification performance
          if (!is.null(result$performance)) {
            context_parts <- c(context_parts, "\n=== CLASSIFICATION PERFORMANCE ===")
            context_parts <- c(context_parts, "Cross-validation performance metrics available")
            if (!is.null(result$performance$error_rate)) {
              context_parts <- c(context_parts, sprintf("Overall error rate: %.2f%%", 
                                                        result$performance$error_rate * 100))
            }
          }
          
          # Design matrix
          if (!is.null(result$design)) {
            context_parts <- c(context_parts, "\nBlock design matrix specified for cross-block correlations")
          }
          
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- DIABLO selects features that DISCRIMINATE between groups across multiple omics")
          context_parts <- c(context_parts, "- Selected features are potential multi-omics BIOMARKERS")
          context_parts <- c(context_parts, "- Component scores show how well samples separate by group")
          context_parts <- c(context_parts, "- Use loading plots to identify feature contributions per component")
        }
        
        # ===== CORRELATION NETWORK RESULTS =====
        else if (result$method == "correlation") {
          context_parts <- c(context_parts, "\n=== CROSS-OMICS CORRELATION NETWORK ===")
          context_parts <- c(context_parts, "Pairwise correlations between features across different omics datasets")
          
          # Dataset pair
          if (!is.null(result$dataset_labels)) {
            context_parts <- c(context_parts, sprintf("Dataset pair: %s vs %s", 
                                                      result$dataset_labels[1], result$dataset_labels[2]))
          } else if (!is.null(result$dataset_pair)) {
            context_parts <- c(context_parts, sprintf("Dataset pair: %s vs %s", 
                                                      result$dataset_pair[1], result$dataset_pair[2]))
          }
          
          # Correlation parameters
          context_parts <- c(context_parts, sprintf("Correlation method: %s", input$corr_method %||% "pearson"))
          context_parts <- c(context_parts, sprintf("Correlation threshold: |r| ≥ %.2f", result$threshold %||% 0.7))
          context_parts <- c(context_parts, sprintf("P-value cutoff: %.4f%s", 
                                                    result$pval_threshold %||% 0.05,
                                                    if (isTRUE(result$adjusted_p)) " (FDR-adjusted)" else ""))
          context_parts <- c(context_parts, sprintf("Edge direction filter: %s", result$filter_mode %||% "absolute"))
          
          # Network statistics
          if (!is.null(result$edge_list) && nrow(result$edge_list) > 0) {
            n_edges <- nrow(result$edge_list)
            n_nodes <- if (!is.null(result$node_list)) nrow(result$node_list) else 0
            
            context_parts <- c(context_parts, "\n=== NETWORK STATISTICS ===")
            context_parts <- c(context_parts, sprintf("Total significant pairs: %d", result$n_sig_pairs %||% n_edges))
            context_parts <- c(context_parts, sprintf("Edges displayed: %d (capped at %d)", n_edges, result$max_edges %||% 150))
            context_parts <- c(context_parts, sprintf("Unique nodes (features): %d", n_nodes))
            
            # Correlation distribution
            pos_cors <- sum(result$edge_list$correlation > 0)
            neg_cors <- sum(result$edge_list$correlation < 0)
            avg_cor <- mean(abs(result$edge_list$correlation))
            
            context_parts <- c(context_parts, sprintf("Positive correlations: %d (%.1f%%)", pos_cors, 100*pos_cors/n_edges))
            context_parts <- c(context_parts, sprintf("Negative correlations: %d (%.1f%%)", neg_cors, 100*neg_cors/n_edges))
            context_parts <- c(context_parts, sprintf("Average |correlation|: %.3f", avg_cor))
            
            # Top connected features (hub features)
            if (!is.null(result$node_list) && "degree" %in% colnames(result$node_list)) {
              top_nodes <- result$node_list[order(-result$node_list$degree), ]
              top_5 <- head(top_nodes, 5)
              
              context_parts <- c(context_parts, "\n=== TOP HUB FEATURES (Most Connected) ===")
              for (i in 1:nrow(top_5)) {
                context_parts <- c(context_parts, sprintf("%d. %s (%s): %d connections", 
                                                          i, top_5$id[i], top_5$dataset[i], top_5$degree[i]))
              }
            }
            
            # Strongest correlations
            strongest <- result$edge_list[order(-abs(result$edge_list$correlation)), ]
            top_5_edges <- head(strongest, 5)
            
            context_parts <- c(context_parts, "\n=== STRONGEST CORRELATIONS ===")
            for (i in 1:nrow(top_5_edges)) {
              edge <- top_5_edges[i, ]
              dir_text <- if (edge$correlation > 0) "positive" else "negative"
              context_parts <- c(context_parts, sprintf("%d. %s ↔ %s: r = %.3f (%s, p = %.2e)", 
                                                        i, edge$from, edge$to, edge$correlation, dir_text, edge$pvalue))
            }
          } else {
            context_parts <- c(context_parts, "No significant correlations found with current thresholds")
            context_parts <- c(context_parts, "Try: lowering correlation threshold, increasing p-value cutoff, or including more features")
          }
          
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- Hub features (high degree) may be key regulatory molecules")
          context_parts <- c(context_parts, "- Positive correlations suggest coordinated regulation")
          context_parts <- c(context_parts, "- Negative correlations suggest inverse/antagonistic relationships")
          context_parts <- c(context_parts, "- Dense clusters indicate functional modules or pathways")
        }
        
        # ===== PATHWAY INTEGRATION RESULTS =====
        else if (result$method == "pathway") {
          context_parts <- c(context_parts, "\n=== PATHWAY-LEVEL INTEGRATION ===")
          context_parts <- c(context_parts, "Pathway enrichment analysis across multiple omics datasets identifying concordant biological processes")
          
          # Database and organism
          if (!is.null(result$database)) {
            context_parts <- c(context_parts, sprintf("Pathway database: %s", result$database))
          }
          if (!is.null(result$organism)) {
            context_parts <- c(context_parts, sprintf("Organism: %s", result$organism))
          }
          
          # Summary statistics
          if (!is.null(result$summary_stats)) {
            stats <- result$summary_stats
            context_parts <- c(context_parts, "\n=== ANALYSIS SUMMARY ===")
            context_parts <- c(context_parts, sprintf("Datasets analyzed: %d", stats$n_datasets %||% 0))
            context_parts <- c(context_parts, sprintf("Total pathways tested: %d", stats$total_pathways %||% 0))
            context_parts <- c(context_parts, sprintf("Pathways in ≥%d datasets: %d", stats$min_datasets %||% 2, stats$concordant_pathways %||% 0))
            context_parts <- c(context_parts, sprintf("Significant concordant (FDR < %.2f): %d", stats$pval_cutoff %||% 0.05, stats$significant_concordant %||% 0))
            context_parts <- c(context_parts, sprintf("P-value combination method: %s", stats$combine_method %||% "fisher"))
          }
          
          # Feature conversion results
          if (!is.null(result$conversion_results) && length(result$conversion_results) > 0) {
            context_parts <- c(context_parts, "\n=== FEATURE ID CONVERSION ===")
            for (ds_name in names(result$conversion_results)) {
              conv <- result$conversion_results[[ds_name]]
              if (!is.null(conv)) {
                success_pct <- round((conv$success_rate %||% 0) * 100, 1)
                context_parts <- c(context_parts, sprintf("%s: %d/%d features converted (%.1f%%) - ID type: %s", 
                                                          ds_name, conv$n_converted %||% 0, conv$n_original %||% 0, 
                                                          success_pct, conv$original_type %||% "unknown"))
              }
            }
          }
          
          # Top concordant pathways
          if (!is.null(result$significant_concordant) && nrow(result$significant_concordant) > 0) {
            top_pathways <- head(result$significant_concordant, 10)
            context_parts <- c(context_parts, "\n=== TOP CONCORDANT PATHWAYS ===")
            context_parts <- c(context_parts, "These pathways are significantly enriched across multiple datasets:")
            
            for (i in seq_len(nrow(top_pathways))) {
              pathway_desc <- top_pathways$Description[i]
              combined_p <- top_pathways$Combined_Padj[i]
              n_datasets <- top_pathways$N_Datasets[i]
              n_sig <- top_pathways$N_Significant[i]
              
              context_parts <- c(context_parts, sprintf("%d. %s", i, pathway_desc))
              context_parts <- c(context_parts, sprintf("   Combined FDR: %.2e | Present in %d datasets, significant in %d", 
                                                        combined_p, n_datasets, n_sig))
            }
          } else if (!is.null(result$concordant_pathways) && nrow(result$concordant_pathways) > 0) {
            # Fallback to concordant_pathways if significant_concordant doesn't exist
            top_pathways <- head(result$concordant_pathways, 10)
            context_parts <- c(context_parts, "\n=== TOP CONCORDANT PATHWAYS ===")
            for (i in seq_len(nrow(top_pathways))) {
              pathway_desc <- top_pathways$Description[i]
              combined_p <- top_pathways$Combined_Pvalue[i] %||% top_pathways$Combined_Padj[i]
              context_parts <- c(context_parts, sprintf("%d. %s (p=%.2e)", i, pathway_desc, combined_p))
            }
          }
          
          # Per-dataset enrichment summary
          if (!is.null(result$enrichment_results) && length(result$enrichment_results) > 0) {
            context_parts <- c(context_parts, "\n=== PER-DATASET ENRICHMENT ===")
            for (ds_name in names(result$enrichment_results)) {
              ds_result <- result$enrichment_results[[ds_name]]
              if (!is.null(ds_result) && nrow(ds_result) > 0) {
                n_sig <- sum(ds_result$pvalue < 0.05, na.rm = TRUE)
                n_total <- nrow(ds_result)
                context_parts <- c(context_parts, sprintf("%s: %d significant pathways (out of %d tested)", 
                                                          ds_name, n_sig, n_total))
              }
            }
          }
          
          # Interpretation guidance
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- Concordant pathways show consistent enrichment across multiple omics layers")
          context_parts <- c(context_parts, "- High concordance score indicates robust biological signal")
          context_parts <- c(context_parts, "- Dataset-specific pathways may indicate layer-specific biology")
          context_parts <- c(context_parts, "- Use the Enrichment Heatmap to visualize patterns across datasets")
          context_parts <- c(context_parts, "- UpSet/Venn plots show pathway overlap between datasets")
          context_parts <- c(context_parts, "- Check Feature Mapping tab to verify ID conversion quality")
          
          # Direction-aware analysis results (if available)
          if (!is.null(result$pathway_direction_matrix) && !is.null(result$summary_stats$direction_summary)) {
            dir_sum <- result$summary_stats$direction_summary
            context_parts <- c(context_parts, "\n=== DIRECTION-AWARE ANALYSIS ===")
            context_parts <- c(context_parts, "Pathway regulation direction based on feature fold-change signs:")
            context_parts <- c(context_parts, sprintf("- Up-regulated pathways: %d", dir_sum$up_regulated %||% 0))
            context_parts <- c(context_parts, sprintf("- Down-regulated pathways: %d", dir_sum$down_regulated %||% 0))
            context_parts <- c(context_parts, sprintf("- Mixed direction: %d", dir_sum$mixed %||% 0))
            context_parts <- c(context_parts, sprintf("- Consistent direction (≥75%%): %d pathways", dir_sum$consistent_direction %||% 0))
            
            # List top pathways by direction
            if (!is.null(result$concordant_pathways) && "Direction_Label" %in% colnames(result$concordant_pathways)) {
              top_up <- head(result$concordant_pathways[result$concordant_pathways$Direction_Label == "Up-regulated", ], 5)
              top_down <- head(result$concordant_pathways[result$concordant_pathways$Direction_Label == "Down-regulated", ], 5)
              
              if (nrow(top_up) > 0) {
                context_parts <- c(context_parts, "\nTop Up-regulated Pathways:")
                for (i in seq_len(nrow(top_up))) {
