        context_parts <- c(context_parts, "- Pathway Integration: Maps features to pathways, finds concordant biological processes")
      }
    }
    
    # ===== K-MEANS CLUSTERING TAB =====
    if (!is.null(input$navbar) && input$navbar == "K-Means Clustering") {
      context_parts <- c(context_parts, "\n=== K-MEANS CLUSTERING ===")
      context_parts <- c(context_parts, "You are viewing K-Means clustering analysis of differential features")
      
      tryCatch({
        km <- kmeans_result()
        if (!is.null(km) && !is.null(km$kmeans)) {
          context_parts <- c(context_parts, sprintf("Number of clusters: %d", input$kmeans_num_clusters %||% 3))
          context_parts <- c(context_parts, sprintf("Features clustered: %d", length(km$kmeans$cluster)))
          context_parts <- c(context_parts, sprintf("Data scaling: %s", if(input$kmeans_scale_data) "Enabled (z-score)" else "Disabled"))
          
          # Cluster sizes
          cluster_sizes <- table(km$kmeans$cluster)
          context_parts <- c(context_parts, "\n=== CLUSTER SIZES ===")
          for (i in seq_along(cluster_sizes)) {
            context_parts <- c(context_parts, sprintf("Cluster %d: %d features", i, cluster_sizes[i]))
          }
          
          # Cluster quality metrics
          context_parts <- c(context_parts, sprintf("Within-cluster sum of squares: %.2f", sum(km$kmeans$withinss)))
          context_parts <- c(context_parts, sprintf("Between-cluster sum of squares: %.2f", km$kmeans$betweenss))
          variance_explained <- km$kmeans$betweenss / km$kmeans$totss * 100
          context_parts <- c(context_parts, sprintf("Variance explained by clusters: %.1f%%", variance_explained))
          
          # Top features per cluster
          if (!is.null(km$cluster_assignments)) {
            context_parts <- c(context_parts, "\n=== TOP FEATURES PER CLUSTER ===")
            for (cl in sort(unique(km$kmeans$cluster))) {
              cluster_features <- names(km$kmeans$cluster)[km$kmeans$cluster == cl]
              top_feats <- head(cluster_features, 5)
              context_parts <- c(context_parts, sprintf("Cluster %d: %s%s", cl, 
                                                        paste(top_feats, collapse = ", "),
                                                        if(length(cluster_features) > 5) "..." else ""))
            }
          }
          
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- Features in the same cluster show similar expression patterns across conditions")
          context_parts <- c(context_parts, "- Use the cluster profile plot to identify up/down-regulated patterns")
          context_parts <- c(context_parts, "- Export cluster assignments for downstream analysis like enrichment")
        } else {
          context_parts <- c(context_parts, "K-Means clustering not yet run. Configure parameters and click 'Run Clustering'.")
        }
      }, error = function(e) {
        context_parts <- c(context_parts, "K-Means clustering not yet run or requires filtered data")
      })
    }
    
    # ===== FEATURE CORRELATION TAB =====
    if (!is.null(input$navbar) && input$navbar == "Feature Correlation") {
      context_parts <- c(context_parts, "\n=== FEATURE CORRELATION ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing pairwise correlation analysis of significant features")
      
      tryCatch({
        corr_data <- corr_filtered_data()
        if (!is.null(corr_data)) {
          context_parts <- c(context_parts, sprintf("Analysis type: %s", 
                                                    if(input$corr_analysis_type == "pairwise") "Pairwise comparison" else "All groups"))
          if (input$corr_analysis_type == "pairwise") {
            context_parts <- c(context_parts, sprintf("Comparing: %s vs %s", input$corr_group1, input$corr_group2))
          }
          
          context_parts <- c(context_parts, sprintf("Features analyzed: %d", nrow(corr_data$filtered_data)))
          context_parts <- c(context_parts, sprintf("Correlation method: %s", input$corr_method %||% "spearman"))
          context_parts <- c(context_parts, sprintf("P-value cutoff: %.2e", input$corr_pvalue_cutoff %||% 0.05))
          context_parts <- c(context_parts, sprintf("Minimum correlation: %.2f", input$corr_min_abs %||% 0.5))
          
          context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
          context_parts <- c(context_parts, "- Positive correlations (red) indicate co-expression/co-regulation")
          context_parts <- c(context_parts, "- Negative correlations (blue) indicate inverse relationships")
          context_parts <- c(context_parts, "- Strong correlations (|r| > 0.7) suggest functional relationships")
          context_parts <- c(context_parts, "- Use the interactive heatmap to explore specific feature pairs")
        } else {
          context_parts <- c(context_parts, "Feature correlation analysis not yet run. Select groups and run statistical analysis first.")
        }
      }, error = function(e) {
        context_parts <- c(context_parts, "Feature correlation analysis requires completed statistical analysis")
      })
    }
    
    # ===== METABOLOMICS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Metabolomics") {
      context_parts <- c(context_parts, "\n=== METABOLOMICS ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing metabolite classification and pathway enrichment analysis")
      
      # Data source information
      source_type <- input$metab_source %||% "pairwise"
      context_parts <- c(context_parts, sprintf("Data source: %s", 
                                                switch(source_type,
                                                       "pairwise" = "Pairwise comparison results",
                                                       "intersection" = "Intersection analysis results",
                                                       "manual" = "Manual input",
                                                       source_type)))
      
      # Classification results
      if (!is.null(metab_values$classification_data) && nrow(metab_values$classification_data) > 0) {
        context_parts <- c(context_parts, sprintf("Metabolites classified: %d", nrow(metab_values$classification_data)))
        
        # Class distribution if available
        if ("Class" %in% colnames(metab_values$classification_data)) {
          class_counts <- table(metab_values$classification_data$Class)
          context_parts <- c(context_parts, "\n=== TOP METABOLITE CLASSES ===")
          top_classes <- head(sort(class_counts, decreasing = TRUE), 5)
          for (i in seq_along(top_classes)) {
            context_parts <- c(context_parts, sprintf("%d. %s: %d metabolites", i, names(top_classes)[i], top_classes[i]))
          }
        }
      }
      
      # ID mapping results
      if (!is.null(metab_values$id_mapping_results) && nrow(metab_values$id_mapping_results) > 0) {
        context_parts <- c(context_parts, sprintf("\nID mapping results: %d metabolites mapped", nrow(metab_values$id_mapping_results)))
      }
      
      # Pathway enrichment results
      if (!is.null(metab_values$pathway_data) && nrow(metab_values$pathway_data) > 0) {
        context_parts <- c(context_parts, "\n=== PATHWAY ENRICHMENT ===")
        context_parts <- c(context_parts, sprintf("Pathways analyzed: %d", nrow(metab_values$pathway_data)))
        
        # Top enriched pathways
        pathway_df <- metab_values$pathway_data
        if ("p.value" %in% colnames(pathway_df) || "pval" %in% colnames(pathway_df)) {
          p_col <- if("p.value" %in% colnames(pathway_df)) "p.value" else "pval"
          sig_pathways <- pathway_df[pathway_df[[p_col]] < 0.05, ]
          context_parts <- c(context_parts, sprintf("Significant pathways (p < 0.05): %d", nrow(sig_pathways)))
          
          if (nrow(sig_pathways) > 0) {
            top_pathways <- head(sig_pathways[order(sig_pathways[[p_col]]), ], 5)
            context_parts <- c(context_parts, "\n=== TOP ENRICHED PATHWAYS ===")
            name_col <- intersect(c("Pathway", "pathway", "Name", "name", "Description"), colnames(top_pathways))[1]
            if (!is.na(name_col)) {
              for (i in seq_len(nrow(top_pathways))) {
                context_parts <- c(context_parts, sprintf("%d. %s (p = %.2e)", i, top_pathways[[name_col]][i], top_pathways[[p_col]][i]))
              }
            }
          }
        }
      }
      
      context_parts <- c(context_parts, "\n=== INTERPRETATION GUIDANCE ===")
      context_parts <- c(context_parts, "- Chemical taxonomy classifies metabolites by structure (ClassyFire)")
      context_parts <- c(context_parts, "- KEGG pathways show metabolic context of identified compounds")
      context_parts <- c(context_parts, "- Use the Sunburst plot for hierarchical class visualization")
      context_parts <- c(context_parts, "- Export pathway results for cross-study comparison")
    }
    
    # ===== POWER ANALYSIS TAB =====
    if (!is.null(input$navbar) && input$navbar == "Power Analysis") {
      context_parts <- c(context_parts, "\n=== POWER ANALYSIS ===")
      context_parts <- c(context_parts, "You are viewing statistical power analysis results")
      
      if (!is.null(values$power_results) && !is.null(values$power_summary)) {
        context_parts <- c(context_parts, sprintf("Power analysis completed for comparison: %s", values$power_comparison))
        context_parts <- c(context_parts, sprintf("Current sample size per group: %d", values$power_current_n))
        
        # Statistical method information
        if (!is.null(values$power_stat_method)) {
          method_text <- switch(values$power_stat_method,
                                "t.test" = "Parametric (t-test)",
                                "wilcox" = "Non-parametric (Mann-Whitney)",
                                "anova" = "Parametric (ANOVA - pairwise comparison)",
                                "kruskal" = "Non-parametric (Kruskal-Wallis - pairwise comparison)",
                                "rots" = "ROTS",
                                values$power_stat_method)
          context_parts <- c(context_parts, sprintf("Statistical method (from Data tab): %s", method_text))
          
          if (!is.null(values$power_is_anova_based) && values$power_is_anova_based) {
            context_parts <- c(context_parts, "Note: This is a pairwise power comparison within a multi-group study")
          }
        }
        
        # Effect sizes analyzed
        if (!is.null(values$power_effect_sizes)) {
          context_parts <- c(context_parts, sprintf("Effect sizes analyzed: %s", paste(values$power_effect_sizes, collapse = ", ")))
        }
        
        # Summary statistics by effect size
        if (nrow(values$power_current) > 0) {
          avg_power <- aggregate(CurrentPower ~ EffectSize, data = values$power_current, FUN = mean)
          target_power <- input$power_target / 100
          underpowered_counts <- aggregate(CurrentPower < target_power ~ EffectSize,
                                           data = values$power_current, FUN = sum)
          
          context_parts <- c(context_parts, "\n=== POWER SUMMARY BY EFFECT SIZE ===")
          for (i in 1:nrow(avg_power)) {
            es <- avg_power$EffectSize[i]
            avg_pwr <- avg_power$CurrentPower[i] * 100
            underpwr <- underpowered_counts[i, 2]
            context_parts <- c(context_parts,
                               sprintf("Effect Size %.2f: Average power = %.1f%%, Underpowered features = %d",
                                       es, avg_pwr, underpwr))
          }
        }
        
        # Top underpowered features
        if (nrow(values$power_current) > 0) {
          target_power <- input$power_target / 100
          underpowered <- values$power_current[values$power_current$CurrentPower < target_power, ]
          
          if (nrow(underpowered) > 0) {
            underpowered <- underpowered[order(underpowered$CurrentPower), ]
            top_underpowered <- head(underpowered, 5)
            
            context_parts <- c(context_parts, sprintf("\nTop 5 most UNDERPOWERED features (below %.0f%% power):", input$power_target))
            for (i in 1:min(5, nrow(top_underpowered))) {
              feat <- top_underpowered$Feature[i]
              es <- top_underpowered$EffectSize[i]
              pwr <- top_underpowered$CurrentPower[i] * 100
              context_parts <- c(context_parts,
                                 sprintf("  %d. %s (ES: %.2f) - Current power: %.1f%%", i, feat, es, pwr))
            }
          }
        }
        
        # Features meeting power target
        if (nrow(values$power_current) > 0) {
          target_power <- input$power_target / 100
          well_powered <- values$power_current[values$power_current$CurrentPower >= target_power, ]
          
          if (nrow(well_powered) > 0) {
            context_parts <- c(context_parts, sprintf("\nFeatures meeting %.0f%% power target: %d",
                                                      input$power_target, nrow(well_powered)))
          }
        }
      } else {
        context_parts <- c(context_parts, "Power analysis not yet run")
        context_parts <- c(context_parts, "Note: Power analysis requires prior statistical analysis in the Data tab")
      }
    }
    
    if (length(context_parts) > 0) {
      return(paste(context_parts, collapse = "\n"))
    }
    return(NULL)
  }
  
  # Function to convert markdown to HTML for chat messages
  format_markdown <- function(text) {
    # Escape HTML entities first
    text <- gsub("&", "&amp;", text)
    text <- gsub("<", "&lt;", text)
    text <- gsub(">", "&gt;", text)
    
    # Convert markdown formatting
    # Bold: **text** or __text__
    text <- gsub("\\*\\*([^*]+)\\*\\*", "<strong>\\1</strong>", text)
    text <- gsub("__([^_]+)__", "<strong>\\1</strong>", text)
    
    # Italic: *text* or _text_ (but not inside words)
    text <- gsub("(?<!\\*)\\*(?!\\*)([^*]+)\\*(?!\\*)", "<em>\\1</em>", text, perl = TRUE)
    text <- gsub("(?<!_)_(?!_)([^_]+)_(?!_)", "<em>\\1</em>", text, perl = TRUE)
    
    # Code: `code`
    text <- gsub("`([^`]+)`", "<code style='background: #f4f4f4; padding: 2px 6px; border-radius: 3px; font-family: monospace;'>\\1</code>", text)
    
    # Convert bullet points: - item or * item at start of line
    text <- gsub("^- (.+)$", "• \\1", text, perl = TRUE)
    text <- gsub("\n- (.+)$", "\n• \\1", text, perl = TRUE)
    text <- gsub("^\\* (.+)$", "• \\1", text, perl = TRUE)
    text <- gsub("\n\\* (.+)$", "\n• \\1", text, perl = TRUE)
    
    # Convert numbered lists
    text <- gsub("^(\\d+)\\. (.+)$", "<strong>\\1.</strong> \\2", text, perl = TRUE)
    text <- gsub("\n(\\d+)\\. (.+)$", "\n<strong>\\1.</strong> \\2", text, perl = TRUE)
    
    # Convert line breaks
    text <- gsub("\n", "<br>", text)
    
    return(text)
  }
  
  # Render chat messages
  output$jibosky_messages_ui <- renderUI({
    messages <- jibosky_messages()
    
    message_elements <- lapply(seq_along(messages), function(i) {
      msg <- messages[[i]]
      is_user <- msg$role == "user"
      is_typing <- identical(msg$type, "typing")
      
      # Format content
      if (is_typing) {
        bubble_html <- HTML(msg$content)
      } else {
        formatted_content <- format_markdown(msg$content)
        # Add provider badge if available (for bot messages)
        if (!is_user && !is.null(msg$provider)) {
          provider_badge <- sprintf(
            "<div style='font-size: 0.75em; color: #888; margin-top: 8px; padding-top: 6px; border-top: 1px solid #eee;'>%s <em>Powered by %s</em></div>",
            msg$provider$icon,
            msg$provider$name
          )
          formatted_content <- paste0(formatted_content, provider_badge)
        }
        bubble_html <- HTML(formatted_content)
      }
      
      bubble_class <- if (is_typing) "jibosky-message-bubble typing" else "jibosky-message-bubble"
      time_display <- if (!is_typing && !is.null(msg$time)) {
        tags$div(
          class = "jibosky-message-time",
          format(msg$time, "%I:%M %p")
        )
      } else {
        NULL
      }
      
      tags$div(
        class = if(is_user) "jibosky-message user" else "jibosky-message bot",
        tags$div(
          class = if(is_user) "jibosky-message-avatar user" else "jibosky-message-avatar bot",
          if(is_user) {
            "U"
          } else {
            tags$img(src = "jibosky_assets/jibosky.png", alt = "Jibosky", style = "width: 100%; height: 100%; object-fit: cover;")
          }
        ),
        tags$div(
          class = "jibosky-message-content",
          tags$div(
            class = bubble_class,
            bubble_html
          )
          ,
          time_display
        )
      )
    })
    
    tagList(message_elements)
  })
  
