  # Handle send message
  observeEvent(input$jibosky_send, {
    req(input$jibosky_send$message)
    user_message <- trimws(input$jibosky_send$message)
    
    if (user_message == "") return()
    
    # Disable input and change button to stop mode
    session$sendCustomMessage("jibosky_ui_state", list(
      action = "disable",
      placeholder = "Jibosky is thinking..."
    ))
    
    # Add user message
    current_messages <- jibosky_messages()
    current_messages[[length(current_messages) + 1]] <- list(
      role = "user",
      content = user_message,
      time = Sys.time()
    )
    jibosky_messages(current_messages)
    
    # Snapshot messages for API before adding typing indicator
    api_messages <- lapply(current_messages, function(msg) {
      list(role = msg$role, content = msg$content)
    })
    
    # Generate unique ID for typing indicator so we can remove the correct one later
    request_id <- paste0(
      "typing_",
      as.character(as.numeric(Sys.time()) * 1000),
      "_",
      paste0(sample(c(letters, 0:9), 4, replace = TRUE), collapse = "")
    )
    typing_html <- sprintf(
      '<div class="jibosky-typing" data-request="%s"><div class="jibosky-typing-dot"></div><div class="jibosky-typing-dot"></div><div class="jibosky-typing-dot"></div></div>',
      request_id
    )
    
    # Show typing indicator immediately
    messages_with_indicator <- current_messages
    messages_with_indicator[[length(messages_with_indicator) + 1]] <- list(
      role = "assistant",
      content = typing_html,
      time = Sys.time(),
      request_id = request_id,
      type = "typing"
    )
    jibosky_messages(messages_with_indicator)
    
    # Capture context snapshot for this request
    context_info <- isolate(get_context_info())
    
    # Flag to track if request was cancelled
    values$jibosky_cancelled <- FALSE
    
    # Defer API call so UI can render user message + typing indicator first
    later::later(function() {
      # Check if user cancelled before API call
      if (isolate(values$jibosky_cancelled)) {
        isolate({
          updated_messages <- jibosky_messages()
          typing_index <- which(vapply(updated_messages, function(msg) identical(msg$request_id, request_id), logical(1)))
          if (length(typing_index) > 0) {
            updated_messages <- updated_messages[-typing_index[1]]
          }
          # Add cancellation message
          updated_messages[[length(updated_messages) + 1]] <- list(
            role = "assistant",
            content = "Request cancelled by user.",
            time = Sys.time()
          )
          jibosky_messages(updated_messages)
        })
        return()
      }
      
      response <- tryCatch(
        call_ai_with_fallback(api_messages, context_info),
        error = function(e) list(success = FALSE, content = paste0("Unexpected error: ", e$message), provider = "none")
      )
      
      isolate({
        # Check again if cancelled during API call
        if (values$jibosky_cancelled) {
          updated_messages <- jibosky_messages()
          typing_index <- which(vapply(updated_messages, function(msg) identical(msg$request_id, request_id), logical(1)))
          if (length(typing_index) > 0) {
            updated_messages <- updated_messages[-typing_index[1]]
          }
          updated_messages[[length(updated_messages) + 1]] <- list(
            role = "assistant",
            content = "Request cancelled by user.",
            time = Sys.time()
          )
          jibosky_messages(updated_messages)
          return()
        }
        
        updated_messages <- jibosky_messages()
        typing_index <- which(vapply(updated_messages, function(msg) identical(msg$request_id, request_id), logical(1)))
        if (length(typing_index) > 0) {
          updated_messages <- updated_messages[-typing_index[1]]
        }
        
        # Prepare provider info (stored separately, not in content)
        provider_info <- NULL
        if (isTRUE(response$success) && !is.null(response$provider_name)) {
          provider_info <- list(
            name = response$provider_name,
            icon = switch(response$provider,
                          "claude" = "🤖",
                          "gemini" = "✨",
                          "openrouter" = "🔀",
                          "ℹ️"
            )
          )
        }
        
        updated_messages[[length(updated_messages) + 1]] <- list(
          role = "assistant",
          content = response$content,
          time = Sys.time(),
          provider = provider_info
        )
        jibosky_messages(updated_messages)
        
        # Re-enable input and reset button to send mode
        session$sendCustomMessage("jibosky_ui_state", list(
          action = "enable",
          placeholder = "Ask Jibosky anything..."
        ))
      })
    }, 0.05)
  })
  
  # Handle stop request
  observeEvent(input$jibosky_stop, {
    values$jibosky_cancelled <- TRUE
    
    # Immediately reset UI
    session$sendCustomMessage("jibosky_ui_state", list(
      action = "enable",
      placeholder = "Ask Jibosky anything..."
    ))
  })
  
  # Toggle chat window visibility
  observeEvent(input$jibosky_toggle, {
    # Just for reactivity - CSS handles the toggle
  })
  
  # ==============================================================================
  # JIBOSKY SUPERPOWER TRIGGER HANDLER
  # ==============================================================================
  observeEvent(input$jibosky_superpower, {
    sp_id <- input$jibosky_superpower$id
    if (is.null(sp_id) || sp_id == "") return()
    
    # Map superpower IDs to labels and helper functions
    sp_map <- list(
      data_quality       = list(label = "Data Quality Report",            fn = sp_data_quality_report,
                                prompt = "Analyze this data quality report. Flag critical issues, rank them by severity, and provide specific actionable recommendations for each issue found."),
      missing_data       = list(label = "Missing Data Analysis",          fn = sp_missing_data_analysis,
                                prompt = "Interpret this missing data analysis. Explain the missingness patterns (MCAR/MAR/MNAR), assess whether the imputation recommendation is appropriate, and provide step-by-step guidance."),
      outlier_detection  = list(label = "Outlier Detection",              fn = sp_outlier_detection,
                                prompt = "Review this outlier detection report. For each flagged sample/feature, explain whether it should be removed or kept, with scientific justification. Suggest the best approach to handle these outliers."),
      design_validation  = list(label = "Experimental Design Validation", fn = sp_design_validation,
                                prompt = "Evaluate this experimental design. Identify strengths and weaknesses. Flag any confounders, balance issues, or power limitations. Suggest improvements for future experiments."),
      stat_recommend     = list(label = "Statistical Method Suggestions", fn = sp_stat_recommendations,
                                prompt = "Review these statistical method recommendations. Explain why each suggested method is appropriate for this data. If you disagree with any recommendation, provide alternatives with reasoning."),
      power_check        = list(label = "Power / Sample Size Check",      fn = sp_power_check,
                                prompt = "Interpret this power/sample size assessment. Explain what the power estimates mean in practical terms. If the study is underpowered, suggest what effect sizes can still be reliably detected and recommend strategies."),
      transform_suggest  = list(label = "Data Transformation Suggestions", fn = sp_transform_suggestions,
                                prompt = "Review these data transformation recommendations. Explain the rationale for each suggestion. Provide specific R code examples for the recommended transformations."),
      comparison_recommend = list(label = "Comparison Recommendations",   fn = sp_comparison_recommendations,
                                prompt = "Based on the group structure, recommend the most scientifically meaningful comparisons. Explain the rationale for prioritizing certain comparisons. Suggest a complete comparison strategy."),
      result_summary     = list(label = "Automated Result Summary",       fn = sp_result_summary,
                                prompt = "Provide a comprehensive narrative interpretation of all analysis results. Synthesize findings across statistical testing, dimensionality reduction, machine learning, and enrichment analyses into a cohesive scientific story. Highlight the most important discoveries."),
      bio_context        = list(label = "Biological Context & Pathways",  fn = sp_bio_context,
                                prompt = "Provide biological context for the significant features. Suggest relevant biological pathways, known functions, and potential mechanisms. Recommend specific databases and tools for further investigation. Connect findings to broader biological knowledge."),
      multiple_testing   = list(label = "Multiple Testing Interpretation", fn = sp_multiple_testing,
                                prompt = "Explain this multiple testing analysis in accessible terms. Help the user understand what FDR means for their specific results, how many false positives to expect, and what threshold is most appropriate for their study goals."),
      pipeline_gen       = list(label = "Pipeline Code Generation",       fn = sp_pipeline_generation,
                                prompt = "Generate a complete, reproducible R analysis pipeline script based on the current analysis configuration. Include all steps: data loading, preprocessing, statistical testing, visualization, and any completed advanced analyses. Make the code well-commented, publication-ready, and runnable outside this application."),
      batch_processing   = list(label = "Batch Processing Scripts",       fn = sp_batch_processing,
                                prompt = "Generate a batch processing R script that can process multiple datasets using the same pipeline. Include error handling, progress reporting, and result aggregation. Make it flexible for different input file formats."),
      report_gen         = list(label = "Generate Analysis Report",       fn = sp_report_generation,
                                prompt = "Format these analysis results into a complete, publication-ready scientific report with sections: Abstract, Introduction, Materials & Methods, Results, Discussion, and Conclusions. Include interpretation of all statistical findings, biological significance, and study limitations.")
    )
    
    sp_info <- sp_map[[sp_id]]
    if (is.null(sp_info)) return()
    
    # Disable input
    session$sendCustomMessage("jibosky_ui_state", list(
      action = "disable",
      placeholder = paste0("Running ", sp_info$label, "...")
    ))
    
    # Add user message showing superpower request
    current_messages <- jibosky_messages()
    user_msg <- paste0("\u26A1 **Superpower: ", sp_info$label, "**")
    current_messages[[length(current_messages) + 1]] <- list(
      role = "user",
      content = user_msg,
      time = Sys.time()
    )
    jibosky_messages(current_messages)
    
    # Generate typing indicator
    request_id <- paste0("sp_", as.character(as.numeric(Sys.time()) * 1000), "_",
                         paste0(sample(c(letters, 0:9), 4, replace = TRUE), collapse = ""))
    typing_html <- sprintf(
      '<div class="jibosky-typing" data-request="%s"><div class="jibosky-typing-dot"></div><div class="jibosky-typing-dot"></div><div class="jibosky-typing-dot"></div></div>',
      request_id
    )
    messages_with_indicator <- jibosky_messages()
    messages_with_indicator[[length(messages_with_indicator) + 1]] <- list(
      role = "assistant", content = typing_html, time = Sys.time(),
      request_id = request_id, type = "typing"
    )
    jibosky_messages(messages_with_indicator)
    
    values$jibosky_cancelled <- FALSE
    
    later::later(function() {
      if (isolate(values$jibosky_cancelled)) {
        isolate({
          updated <- jibosky_messages()
          ti <- which(vapply(updated, function(m) identical(m$request_id, request_id), logical(1)))
          if (length(ti) > 0) updated <- updated[-ti[1]]
          updated[[length(updated) + 1]] <- list(role = "assistant", content = "Request cancelled.", time = Sys.time())
          jibosky_messages(updated)
          session$sendCustomMessage("jibosky_ui_state", list(action = "enable", placeholder = "Ask Jibosky anything..."))
        })
        return()
      }
      
      # Run the superpower helper function
      sp_context <- tryCatch(isolate(sp_info$fn()), error = function(e) paste0("Error running analysis: ", e$message))
      
      # Get general context too (selective - shorter)
      base_context <- isolate(get_context_info())
      
      # Build special message for the AI
      combined_context <- paste0(
        "=== SUPERPOWER ANALYSIS: ", sp_info$label, " ===\n",
        sp_context,
        "\n\n=== GENERAL ANALYSIS STATE ===\n",
        if (!is.null(base_context)) base_context else "No additional context."
      )
      
      # Build API messages including history + the superpower prompt
      api_messages <- isolate({
        msgs <- jibosky_messages()
        # Filter out typing indicators
        msgs <- msgs[!vapply(msgs, function(m) identical(m$type, "typing"), logical(1))]
        lapply(msgs, function(m) list(role = m$role, content = m$content))
      })
      # Add the superpower-specific instruction as the final user message
      api_messages[[length(api_messages) + 1]] <- list(
        role = "user",
        content = sp_info$prompt
      )
      
      response <- tryCatch(
        call_ai_with_fallback(api_messages, combined_context),
        error = function(e) list(success = FALSE, content = paste0("Error: ", e$message), provider = "none")
      )
      
      isolate({
        updated <- jibosky_messages()
        ti <- which(vapply(updated, function(m) identical(m$request_id, request_id), logical(1)))
        if (length(ti) > 0) updated <- updated[-ti[1]]
        
        provider_info <- NULL
        if (isTRUE(response$success) && !is.null(response$provider_name)) {
          provider_info <- list(
            name = response$provider_name,
            icon = switch(response$provider, "claude" = "\U0001F916", "gemini" = "\u2728", "openrouter" = "\U0001F500", "\u2139\uFE0F")
          )
        }
        
        updated[[length(updated) + 1]] <- list(
          role = "assistant",
          content = response$content,
          time = Sys.time(),
          provider = provider_info
        )
        jibosky_messages(updated)
        
        session$sendCustomMessage("jibosky_ui_state", list(action = "enable", placeholder = "Ask Jibosky anything..."))
      })
    }, 0.05)
  })
  
  # ==============================================================================
  # JIBOSKY REPORT DOWNLOAD HANDLER
  # ==============================================================================
  output$jibosky_download_report <- downloadHandler(
    filename = function() {
      paste0("OmicsStack_Analysis_Report_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".html")
    },
    content = function(file) {
      # Compile all superpower analyses into a single report
      sections <- list()
      
      tryCatch({
        sections[["Data Quality"]] <- sp_data_quality_report()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Missing Data"]] <- sp_missing_data_analysis()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Outlier Detection"]] <- sp_outlier_detection()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Experimental Design"]] <- sp_design_validation()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Statistical Recommendations"]] <- sp_stat_recommendations()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Power Analysis"]] <- sp_power_check()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Results Summary"]] <- sp_result_summary()
      }, error = function(e) NULL)
      
      tryCatch({
        sections[["Multiple Testing"]] <- sp_multiple_testing()
      }, error = function(e) NULL)
      
      # Build HTML report
      html_parts <- c(
        "<!DOCTYPE html><html><head><meta charset='utf-8'>",
        "<title>OmicsStack Analysis Report</title>",
        "<style>",
        "body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; max-width: 900px; margin: 40px auto; padding: 0 20px; color: #333; line-height: 1.6; }",
        "h1 { color: #667eea; border-bottom: 3px solid #667eea; padding-bottom: 10px; }",
        "h2 { color: #764ba2; margin-top: 30px; border-left: 4px solid #764ba2; padding-left: 12px; }",
        "pre { background: #f5f5f5; padding: 16px; border-radius: 6px; overflow-x: auto; font-size: 13px; border: 1px solid #ddd; white-space: pre-wrap; }",
        ".warning { background: #fff3cd; padding: 10px 16px; border-left: 4px solid #ffc107; border-radius: 4px; margin: 10px 0; }",
        ".critical { background: #f8d7da; padding: 10px 16px; border-left: 4px solid #dc3545; border-radius: 4px; margin: 10px 0; }",
        ".ok { background: #d4edda; padding: 10px 16px; border-left: 4px solid #28a745; border-radius: 4px; margin: 10px 0; }",
        ".footer { margin-top: 40px; padding-top: 20px; border-top: 1px solid #ddd; font-size: 12px; color: #888; text-align: center; }",
        "</style></head><body>",
        sprintf("<h1>OmicsStack Analysis Report</h1><p>Generated: %s</p>", format(Sys.time(), "%B %d, %Y at %H:%M:%S"))
      )
      
      for (sec_name in names(sections)) {
        sec_content <- sections[[sec_name]]
        if (!is.null(sec_content) && nzchar(sec_content) && !grepl("^No data|^No raw|^Run statistical", sec_content)) {
          # Highlight warnings
          sec_content <- gsub("WARNING:", "<span style='color:#e67e00;font-weight:bold;'>WARNING:</span>", sec_content)
          sec_content <- gsub("CRITICAL:", "<span style='color:#dc3545;font-weight:bold;'>CRITICAL:</span>", sec_content)
          sec_content <- gsub("CAUTION:", "<span style='color:#e67e00;font-weight:bold;'>CAUTION:</span>", sec_content)
          sec_content <- gsub("OK:", "<span style='color:#28a745;font-weight:bold;'>OK:</span>", sec_content)
          
          html_parts <- c(html_parts, sprintf("<h2>%s</h2><pre>%s</pre>", sec_name, sec_content))
        }
      }
      
      html_parts <- c(html_parts,
                       "<div class='footer'>Generated by OmicsStack &mdash; Powered by Jibosky AI Superpowers</div>",
                       "</body></html>")
      
      writeLines(paste(html_parts, collapse = "\n"), file)
    }
  )
  
  # ==============================================================================
  # POWER ANALYSIS SERVER LOGIC
  # ==============================================================================
  
  # Update group choices for power analysis
  observe({
    req(values$unique_groups)
    if (length(values$unique_groups) >= 2) {
      updateSelectInput(session, "power_group1",
                        choices = values$unique_groups,
                        selected = values$unique_groups[1])
      updateSelectInput(session, "power_group2",
                        choices = values$unique_groups,
                        selected = values$unique_groups[2])
    }
  })
  
  # Render ANOVA/Kruskal-Wallis power options
  output$power_anova_options_ui <- renderUI({
    req(values$unique_groups)
    
    # Need at least 3 groups for global test
    if (length(values$unique_groups) < 3) {
      return(NULL)
    }
    
    # Determine test type from stat_results if available
    stat_method <- NULL
    if (!is.null(input$sig_method)) {
      stat_method <- input$sig_method
    }
    
    # Only show if ANOVA or Kruskal-Wallis was used
    if (is.null(stat_method) || !stat_method %in% c("anova", "kruskal")) {
      return(NULL)
    }
    
    test_name <- if (stat_method == "anova") "ANOVA" else "Kruskal-Wallis"
    
    div(
      style = "margin-top: 15px; padding: 10px; background-color: #f8f9fa; border-radius: 5px; border-left: 4px solid #3498db;",
      checkboxInput("power_include_global",
                    HTML(paste0("<strong>Include Global ", test_name, " Power</strong>")),
                    value = FALSE),
      
      conditionalPanel(
        condition = "input.power_include_global",
        helpText(paste0("Calculate power for detecting differences among multiple groups using ", test_name, ".")),
        selectInput("power_global_groups",
                    "Select Groups for Global Test:",
                    choices = values$unique_groups,
                    selected = values$unique_groups,
                    multiple = TRUE,
                    width = "100%"),
        helpText(icon("info-circle"), " Minimum 3 groups required.", style = "color: #7f8c8d; font-size: 0.9em;")
      )
    )
  })
  
  # Reactive value to store power analysis results
  values$power_results <- NULL
  values$power_summary <- NULL
  values$power_current <- NULL
  values$power_feature_stats <- NULL
  values$power_global_results <- NULL
  values$power_global_summary <- NULL
  values$power_analysis_running <- FALSE
  values$power_analysis_abort <- FALSE
  
  # Run power analysis
  observeEvent(input$run_power_analysis, {
    if (isTRUE(values$power_analysis_running)) {
      values$power_analysis_abort <- TRUE
      showNotification("Stopping power analysis...", type = "warning", duration = 5)
      return()
    }
    
    req(values$normalized_data, input$power_group1, input$power_group2)
    
    # Validate different groups selected
    if (input$power_group1 == input$power_group2) {
      showNotification("Please select two different groups to compare.", type = "error")
      return()
    }
    
    # Check if statistical analysis has been run
    if (is.null(values$stat_results)) {
      showNotification("Please run statistical analysis in the Data tab first.", type = "error", duration = 10)
      return()
    }
    
    # Detect the statistical method used from Data tab
    if (is.null(input$sig_method)) {
      showNotification("No statistical method detected. Please run analysis in the Data tab.", type = "error", duration = 10)
      return()
    }
    
    stat_method <- input$sig_method
    
    # Determine if parametric or non-parametric based on Data tab settings
    is_parametric <- stat_method %in% c("t.test", "anova")
    is_anova_based <- stat_method %in% c("anova", "kruskal")
    
    # For other tests (limma, rots, deseq2, edger, etc), use non-parametric approach
    use_nonparametric_fallback <- FALSE
    if (!stat_method %in% c("t.test", "wilcox", "anova", "kruskal")) {
      is_parametric <- FALSE
      use_nonparametric_fallback <- TRUE
      showNotification(
        paste0("Statistical method '", stat_method, "' detected. ",
               "Power analysis will use non-parametric approximation for compatibility."),
        type = "warning",
        duration = 8
      )
    }
    
    # Show info about the method being used
    method_text <- switch(stat_method,
                          "t.test" = "Parametric (t-test)",
                          "wilcox" = "Non-parametric (Mann-Whitney)",
                          "anova" = "Parametric (ANOVA)",
                          "kruskal" = "Non-parametric (Kruskal-Wallis)",
                          "rots" = "ROTS",
                          "limma" = "Limma",
                          "limma_voom" = "Limma-voom",
                          "deseq2" = "DESeq2",
                          "edger" = "edgeR",
                          stat_method)
    
    if (use_nonparametric_fallback) {
      showNotification(
        paste0("Using statistical method from Data tab: ", method_text,
               " (power calculated with non-parametric approximation)"),
        type = "message",
        duration = 5
      )
    } else {
      showNotification(
        paste0("Using statistical method from Data tab: ", method_text,
               "\nThis matches your analysis workflow."),
        type = "message",
        duration = 5
      )
    }
    
    values$power_results <- NULL
    values$power_summary <- NULL
    values$power_current <- NULL
    values$power_feature_stats <- NULL
    values$power_global_results <- NULL
    values$power_global_summary <- NULL
    values$power_analysis_note <- NULL
    values$power_current_n <- NA_real_
    
    values$power_analysis_running <- TRUE
    values$power_analysis_abort <- FALSE
    session$sendCustomMessage('togglePowerAnalysisButton', list(state = 'stop'))
    
    alpha_val <- get_safe_power_alpha()
    target_fraction <- get_target_power_fraction()
    target_pct <- get_safe_target_power()
    
    on.exit({
      values$power_analysis_running <- FALSE
      values$power_analysis_abort <- FALSE
      session$sendCustomMessage('togglePowerAnalysisButton', list(state = 'run'))
      updateActionButton(session, "run_power_analysis", label = "Run Power Analysis", icon = icon("play-circle"))
    }, add = TRUE)
    
    analysis_aborted <- FALSE
    
    withProgress(message = "Running power analysis...", value = 0, {
      tryCatch({
        # Extract groups
        group1 <- input$power_group1
        group2 <- input$power_group2
        
        # Get group indices
        group1_idx <- which(values$unique_groups == group1)
        group2_idx <- which(values$unique_groups == group2)
        
        group1_cols <- values$group_column_indices[[group1_idx]]
        group2_cols <- values$group_column_indices[[group2_idx]]
        
        # Get current sample sizes
        current_n1 <- length(group1_cols)
        current_n2 <- length(group2_cols)
        current_n <- min(current_n1, current_n2)
        
        # === DEBUG ===
        cat("\n=== POWER ANALYSIS COMPUTATION DEBUG ===\n")
        cat("group1:", group1, "| group1_cols length:", current_n1, "\n")
        cat("group2:", group2, "| group2_cols length:", current_n2, "\n")
        cat("current_n (min of both):", class(current_n), "=", current_n, "\n")
        cat("input$power_include_global:", input$power_include_global, "\n")
        cat("=== END DEBUG ===\n\n")
        
        setProgress(0.1, detail = "Calculating group statistics...")
        
        # Calculate statistics for each feature
        group1_data <- values$normalized_data[, group1_cols, drop = FALSE]
        group2_data <- values$normalized_data[, group2_cols, drop = FALSE]
        
        group1_means <- rowMeans(group1_data, na.rm = TRUE)
        group1_sds <- apply(group1_data, 1, sd, na.rm = TRUE)
        group2_means <- rowMeans(group2_data, na.rm = TRUE)
        group2_sds <- apply(group2_data, 1, sd, na.rm = TRUE)
        
        # Get effect sizes
        effect_sizes <- as.numeric(input$power_effect_sizes[input$power_effect_sizes != "custom"])
        if ("custom" %in% input$power_effect_sizes) {
          effect_sizes <- c(effect_sizes, input$power_custom_es)
        }
        effect_sizes <- sort(unique(effect_sizes))
        
        # Define sample size range
        sample_sizes <- seq(input$power_sample_range[1], input$power_sample_range[2], by = 5)
        
        # Initialize results storage
        all_results <- data.frame()
        feature_power_summary <- data.frame()
        current_power_results <- data.frame()
        
        num_features <- nrow(values$normalized_data)
        feature_names <- values$cleaned_molecules
        
        setProgress(0.2, detail = paste("Analyzing", num_features, "features..."))
        
        # Calculate power for each feature
        for (feature_idx in 1:num_features) {
          if (isTRUE(values$power_analysis_abort)) {
            analysis_aborted <- TRUE
            stop("POWER_ANALYSIS_ABORT")
          }
          if (feature_idx %% 10 == 0) {
            setProgress(0.2 + (0.7 * feature_idx / num_features),
                        detail = paste("Feature", feature_idx, "of", num_features))
          }
          
          feature_name <- feature_names[feature_idx]
          mu1 <- group1_means[feature_idx]
          sd1 <- group1_sds[feature_idx]
          mu2 <- group2_means[feature_idx]
          sd2 <- group2_sds[feature_idx]
          
          # Skip if invalid
          if (is.na(mu1) || is.na(mu2) || is.na(sd1) || is.na(sd2) || sd1 == 0 || sd2 == 0) {
            next
          }
          
          # Calculate power for each effect size
          for (effect_size in effect_sizes) {
            if (isTRUE(values$power_analysis_abort)) {
              analysis_aborted <- TRUE
              stop("POWER_ANALYSIS_ABORT")
            }
            # Adjust mu2 based on effect size
            mu2_adjusted <- mu1 + effect_size * (mu2 - mu1)
            
            # Calculate power across sample sizes
            power_values <- sapply(sample_sizes, function(n) {
              tryCatch({
                if (!requireNamespace("pwrss", quietly = TRUE)) {
                  # Fallback to simpler calculation
                  pooled_sd <- sqrt((sd1^2 + sd2^2) / 2)
                  cohen_d <- abs(mu2_adjusted - mu1) / pooled_sd
                  ncp <- cohen_d * sqrt(n / 2)
                  power <- pnorm(qnorm(1 - alpha_val / 2) - ncp) +
                    pnorm(-qnorm(1 - alpha_val / 2) - ncp)
                  return(1 - power)
                } else {
                  # Use appropriate test based on Data tab method
                  if (is_parametric) {
                    # Parametric test (t-test or pairwise from ANOVA)
                    pwrss::pwrss.t.2means(
                      mu1 = mu1,
                      mu2 = mu2_adjusted,
                      sd1 = sd1,
                      sd2 = sd2,
                      alpha = alpha_val,
                      n2 = n,
                      alternative = "two.sided"
                    )$power
                  } else {
                    # Non-parametric test (Wilcoxon/Mann-Whitney or pairwise from Kruskal-Wallis)
                    # Use normal approximation for non-parametric tests
                    pwrss::pwrss.np.2groups(
                      mu1 = mu1,
                      mu2 = mu2_adjusted,
                      sd1 = sd1,
                      sd2 = sd2,
                      alpha = alpha_val,
                      power = NULL,
                      n2 = n,
                      distribution = "normal"
                    )$power
                  }
                }
              }, error = function(e) NA)
            })
            
            # Calculate current power
            current_power <- tryCatch({
              if (!requireNamespace("pwrss", quietly = TRUE)) {
                pooled_sd <- sqrt((sd1^2 + sd2^2) / 2)
                cohen_d <- abs(mu2_adjusted - mu1) / pooled_sd
                ncp <- cohen_d * sqrt(current_n / 2)
                power <- pnorm(qnorm(1 - alpha_val / 2) - ncp) +
                  pnorm(-qnorm(1 - alpha_val / 2) - ncp)
                1 - power
              } else {
                # Use appropriate test based on Data tab method
                if (is_parametric) {
                  # Parametric test (t-test or pairwise from ANOVA)
                  pwrss::pwrss.t.2means(
                    mu1 = mu1,
                    mu2 = mu2_adjusted,
                    sd1 = sd1,
                    sd2 = sd2,
                    alpha = alpha_val,
                    n2 = current_n,
                    alternative = "two.sided"
                  )$power
                } else {
                  # Non-parametric test (Wilcoxon/Mann-Whitney or pairwise from Kruskal-Wallis)
                  # Use normal approximation for non-parametric tests
                  pwrss::pwrss.np.2groups(
                    mu1 = mu1,
                    mu2 = mu2_adjusted,
                    sd1 = sd1,
                    sd2 = sd2,
                    alpha = alpha_val,
                    power = NULL,
                    n2 = current_n,
                    distribution = "normal"
                  )$power
                }
              }
            }, error = function(e) NA)
            
            # Store current power
            # Add ID column if available
            id_value <- if (!is.null(values$accession_ids) && length(values$accession_ids) >= feature_idx) {
              values$accession_ids[feature_idx]
            } else {
              NA
            }
            
            current_power_results <- rbind(current_power_results, data.frame(
              Feature = feature_name,
              ID = id_value,
              EffectSize = effect_size,
              CurrentSampleSize = current_n,
              CurrentPower = current_power,
              Group1_Mean = mu1,
              Group1_SD = sd1,
              Group2_Mean = mu2,
              Group2_SD = sd2,
              stringsAsFactors = FALSE
            ))
            
            # Store detailed results
            # Add ID column if available
            df <- data.frame(
              Feature = feature_name,
              ID = id_value,
              SampleSize = sample_sizes,
              Power = power_values,
              EffectSize = effect_size,
              stringsAsFactors = FALSE
            )
            all_results <- rbind(all_results, df)
            
            # Find minimum sample size for target power
            target_power <- target_fraction
            min_n_target <- sample_sizes[which.max(power_values >= target_power)]
            if (length(min_n_target) == 0 || is.na(min_n_target)) min_n_target <- NA
            
            feature_power_summary <- rbind(feature_power_summary, data.frame(
              Feature = feature_name,
              ID = id_value,
              EffectSize = effect_size,
              MinSampleSizeForTargetPower = min_n_target,
              CurrentSampleSize = current_n,
              CurrentPower = current_power,
              stringsAsFactors = FALSE
            ))
          }
        }
        
        setProgress(0.95, detail = "Finalizing results...")
        
        # ===== GLOBAL ANOVA/KRUSKAL-WALLIS POWER ANALYSIS =====
        global_power_results <- NULL
        global_power_summary <- NULL
        
        if (!is.null(input$power_include_global) && input$power_include_global && is_anova_based) {
          req(input$power_global_groups)
          
          if (length(input$power_global_groups) >= 3) {
            setProgress(0.95, detail = "Calculating global power...")
            
            # Get indices for selected groups
            selected_group_indices <- lapply(input$power_global_groups, function(grp) {
              idx <- which(values$unique_groups == grp)
              values$group_column_indices[[idx]]
            })
            
            # Get group sample sizes
            group_ns <- sapply(selected_group_indices, length)
            min_group_n <- min(group_ns)
            num_groups <- length(input$power_global_groups)
            
            # Calculate global power for each feature
            global_results_list <- list()
            global_current_list <- list()
            
            for (feature_idx in 1:num_features) {
              if (isTRUE(values$power_analysis_abort)) {
                analysis_aborted <- TRUE
                stop("POWER_ANALYSIS_ABORT")
              }
              feature_name <- feature_names[feature_idx]
              
              # Get ID for this feature if available
              id_value <- if (!is.null(values$accession_ids) && length(values$accession_ids) >= feature_idx) {
                values$accession_ids[feature_idx]
              } else {
                NA
              }
              
              # Get means and SDs for all selected groups
              group_means <- sapply(selected_group_indices, function(cols) {
                mean(values$normalized_data[feature_idx, cols], na.rm = TRUE)
              })
              
              group_sds <- sapply(selected_group_indices, function(cols) {
                sd(values$normalized_data[feature_idx, cols], na.rm = TRUE)
              })
              
              # Skip if any invalid values
              if (any(is.na(group_means)) || any(is.na(group_sds)) || any(group_sds == 0)) {
                next
              }
              
              # Calculate effect size (eta-squared or similar measure)
              # For simplicity, use the ratio of between-group variance to within-group variance
              grand_mean <- mean(group_means)
              between_var <- sum(group_ns * (group_means - grand_mean)^2) / (num_groups - 1)
              within_var <- sum((group_ns - 1) * group_sds^2) / (sum(group_ns) - num_groups)
              
              if (within_var == 0) next
              
              f_statistic <- between_var / within_var
              
              # Calculate power for different sample sizes
              for (effect_size in effect_sizes) {
                if (isTRUE(values$power_analysis_abort)) {
                  analysis_aborted <- TRUE
                  stop("POWER_ANALYSIS_ABORT")
                }
                # Scale the observed effect by the effect size multiplier
                scaled_f <- f_statistic * effect_size
                
                global_power_by_n <- sapply(sample_sizes, function(n_per_group) {
                  tryCatch({
                    if (!requireNamespace("pwrss", quietly = TRUE)) {
                      # Fallback: approximate F-test power
                      df1 <- num_groups - 1
                      df2 <- num_groups * n_per_group - num_groups
                      ncp <- scaled_f * df2
                      f_crit <- qf(1 - alpha_val, df1, df2)
                      1 - pf(f_crit, df1, df2, ncp = ncp)
                    } else {
                      # Use pwrss for ANOVA power
                      if (is_parametric) {
                        pwrss::pwrss.f.ancova(
                          eta2 = scaled_f / (scaled_f + 1),
                          alpha = alpha_val,
                          k = num_groups,
                          n = n_per_group
                        )$power
                      } else {
                        # For Kruskal-Wallis, use approximate normal-based calculation
                        # This is an approximation
                        df1 <- num_groups - 1
                        df2 <- num_groups * n_per_group - num_groups
                        ncp <- scaled_f * df2
                        f_crit <- qf(1 - alpha_val, df1, df2)
                        1 - pf(f_crit, df1, df2, ncp = ncp)
                      }
                    }
                  }, error = function(e) NA)
                })
                
                # Calculate current power
                current_global_power <- tryCatch({
                  if (!requireNamespace("pwrss", quietly = TRUE)) {
                    df1 <- num_groups - 1
                    df2 <- sum(group_ns) - num_groups
                    ncp <- scaled_f * df2
                    f_crit <- qf(1 - alpha_val, df1, df2)
                    1 - pf(f_crit, df1, df2, ncp = ncp)
                  } else {
                    if (is_parametric) {
                      pwrss::pwrss.f.ancova(
                        eta2 = scaled_f / (scaled_f + 1),
                        alpha = alpha_val,
                        k = num_groups,
                        n = min_group_n
                      )$power
                    } else {
                      df1 <- num_groups - 1
                      df2 <- sum(group_ns) - num_groups
                      ncp <- scaled_f * df2
                      f_crit <- qf(1 - alpha_val, df1, df2)
                      1 - pf(f_crit, df1, df2, ncp = ncp)
                    }
                  }
                }, error = function(e) NA)
                
                # Store results
                global_results_list[[length(global_results_list) + 1]] <- data.frame(
                  Feature = feature_name,
                  ID = id_value,
                  SampleSize = sample_sizes,
                  Power = global_power_by_n,
                  EffectSize = effect_size,
                  stringsAsFactors = FALSE
                )
                
                global_current_list[[length(global_current_list) + 1]] <- data.frame(
                  Feature = feature_name,
                  ID = id_value,
                  EffectSize = effect_size,
                  CurrentPower = current_global_power,
                  CurrentSampleSize = min_group_n,
                  NumGroups = num_groups,
                  stringsAsFactors = FALSE
                )
              }
            }
            
            if (length(global_results_list) > 0) {
              global_power_results <- do.call(rbind, global_results_list)
              global_power_summary <- do.call(rbind, global_current_list)
            }
          }
        }
        
        # Store results with statistical method information
        values$power_results <- all_results
        values$power_summary <- feature_power_summary
        values$power_current <- current_power_results
        
        # Add IDs to feature stats if available
        feature_ids <- if (!is.null(values$accession_ids) && length(values$accession_ids) == length(feature_names)) {
          values$accession_ids
        } else {
          rep(NA, length(feature_names))
        }
        
        values$power_feature_stats <- data.frame(
          Feature = feature_names,
          ID = feature_ids,
          Group1_Mean = group1_means,
          Group1_SD = group1_sds,
          Group2_Mean = group2_means,
          Group2_SD = group2_sds,
          stringsAsFactors = FALSE
        )
        values$power_comparison <- paste(group1, "vs", group2)
        values$power_current_n <- current_n
        values$power_effect_sizes <- effect_sizes
        values$power_stat_method <- stat_method
        values$power_is_parametric <- is_parametric
        values$power_is_anova_based <- is_anova_based
        values$power_global_results <- global_power_results
        values$power_global_summary <- global_power_summary
        
        # Add notation for ANOVA/Kruskal-Wallis cases
        analysis_note <- if (is_anova_based) {
          base_note <- paste0("Pairwise comparison: ", group1, " vs ", group2,
                              " | Method: ", ifelse(is_parametric, "ANOVA", "Kruskal-Wallis"))
          if (!is.null(global_power_results)) {
            paste0(base_note, " | Global ", ifelse(is_parametric, "ANOVA", "Kruskal-Wallis"),
                   " power calculated for ", length(input$power_global_groups), " groups")
          } else {
            base_note
          }
        } else {
          paste0("Power analysis based on ", method_text, " from Data tab.")
        }
        values$power_analysis_note <- analysis_note
        
        # Update feature choices for power curve plot
        # Show IDs or feature names based on power_label_type selection
        use_ids_for_dropdown <- !is.null(input$power_label_type) &&
          input$power_label_type == "ids" &&
          !is.null(values$accession_ids) &&
          length(values$accession_ids) == length(feature_names)
        
        dropdown_labels <- if (use_ids_for_dropdown) values$accession_ids else feature_names
        updateSelectInput(session, "power_curve_feature",
                          choices = dropdown_labels,
                          selected = dropdown_labels[1])
        
        # Update effect size choices for ranking
        updateSelectInput(session, "power_rank_effect_size",
                          choices = effect_sizes,
                          selected = effect_sizes[1])
        
        setProgress(1, detail = "Complete!")
        if (!analysis_aborted) {
          showNotification("Power analysis complete!", type = "message", duration = 3)
        }
        
      }, error = function(e) {
        if (identical(conditionMessage(e), "POWER_ANALYSIS_ABORT")) {
          analysis_aborted <- TRUE
        } else {
          showNotification(paste("Error in power analysis:", e$message), type = "error", duration = 10)
        }
      })
    })
    
    if (analysis_aborted) {
      showNotification("Power analysis aborted by user.", type = "warning", duration = 5)
    }
  })
  
  # Observer to update feature dropdowns when label type changes
  observeEvent(input$power_label_type, {
    req(values$power_results)
    
    # Determine if using IDs or feature names
    use_ids_for_dropdown <- !is.null(input$power_label_type) &&
      input$power_label_type == "ids" &&
      !is.null(values$power_results$ID) &&
      !all(is.na(values$power_results$ID))
    
    if (use_ids_for_dropdown) {
      # Use IDs
      feature_choices <- unique(values$power_results$ID)
      feature_choices <- feature_choices[!is.na(feature_choices)]
    } else {
      # Use feature names
      feature_choices <- unique(values$power_results$Feature)
    }
    
    # Update power curve feature dropdown
    current_selection <- input$power_curve_feature
    if (!is.null(current_selection) && current_selection %in% feature_choices) {
      updateSelectInput(session, "power_curve_feature",
                        choices = feature_choices,
                        selected = current_selection)
    } else {
      updateSelectInput(session, "power_curve_feature",
                        choices = feature_choices,
                        selected = feature_choices[1])
    }
    
    # Update global power feature dropdown if global results exist
    if (!is.null(values$power_global_results)) {
      if (use_ids_for_dropdown) {
        global_choices <- unique(values$power_global_results$ID)
        global_choices <- global_choices[!is.na(global_choices)]
      } else {
        global_choices <- unique(values$power_global_results$Feature)
      }
      
      current_global_selection <- input$power_global_feature
      if (!is.null(current_global_selection) && current_global_selection %in% global_choices) {
        updateSelectInput(session, "power_global_feature",
                          choices = global_choices,
                          selected = current_global_selection)
      } else {
        updateSelectInput(session, "power_global_feature",
                          choices = global_choices,
                          selected = global_choices[1])
      }
    }
  })
  
  # Current Study Power Summary Card
  output$power_current_summary_card_ui <- renderUI({
    req(values$power_current)
    
    # Validate that power_current has rows
    if (is.null(values$power_current) || nrow(values$power_current) == 0) {
      return(NULL)
    }
    
    # Calculate average power by effect size
    avg_power <- tryCatch({
      aggregate(CurrentPower ~ EffectSize, data = values$power_current, FUN = mean)
    }, error = function(e) {
      return(NULL)
    })
    
    if (is.null(avg_power) || nrow(avg_power) == 0) {
      return(NULL)
    }
    
    params <- get_power_params()
    current_n_display <- if (is.na(params$current_n)) "Not available" else params$current_n
    target_power <- params$target_fraction
    
    # Count underpowered features
    underpowered_counts <- tryCatch({
      aggregate(CurrentPower < target_power ~ EffectSize,
                data = values$power_current, FUN = sum)
    }, error = function(e) {
      return(NULL)
    })
    
    if (is.null(underpowered_counts)) {
      return(NULL)
    }
    
    # Get statistical method information
    stat_method_text <- if (!is.null(values$power_stat_method)) {
      switch(values$power_stat_method,
             "t.test" = "Parametric (t-test)",
             "wilcox" = "Non-parametric (Mann-Whitney)",
             "anova" = "Parametric (ANOVA)",
             "kruskal" = "Non-parametric (Kruskal-Wallis)",
             "rots" = "ROTS",
             values$power_stat_method)
    } else {
      "Not specified"
    }
    
    div(class = "dimred-card",
        div(class = "dimred-card-header",
            h4(icon("info-circle", class = "dimred-feature-icon"), "Current Study Power Summary"),
            shinyBS::tipify(icon("question-circle", class = "dimred-tooltip"),
                            "Summary of statistical power with your current sample size")
        ),
        p(strong("Comparison:"), values$power_comparison),
        p(strong("Current sample size:"), current_n_display),
        p(strong("Statistical method:"), stat_method_text,
          style = "color: #2ecc71; font-weight: 500;"),
        if (!is.null(values$power_analysis_note)) {
          p(em(values$power_analysis_note), style = "color: #7f8c8d; font-size: 0.9em;")
        },
        hr(),
        h5("Average Statistical Power by Effect Size:"),
        renderTable({
          # Validate data exists
          if (is.null(values$power_current) || nrow(values$power_current) == 0 ||
              is.null(avg_power) || nrow(avg_power) == 0) {
            return(data.frame(Message = "No power analysis results available"))
          }
          
          # Calculate median power by effect size
          median_power <- tryCatch({
            aggregate(CurrentPower ~ EffectSize, data = values$power_current, FUN = median)
          }, error = function(e) {
            return(NULL)
          })
          
          if (is.null(median_power) || nrow(median_power) == 0) {
            return(data.frame(Message = "Unable to calculate power statistics"))
          }
          
          # Merge average and median
          combined <- merge(avg_power, median_power, by = "EffectSize", suffixes = c("_avg", "_median"))
          
          data.frame(
            "Effect Size" = combined$EffectSize,
            "Average Power" = paste0(round(combined$CurrentPower_avg * 100, 1), "%"),
            "Median Power" = paste0(round(combined$CurrentPower_median * 100, 1), "%"),
            "Underpowered Features" = underpowered_counts[, 2],
            check.names = FALSE
          )
        }, striped = TRUE, hover = TRUE, bordered = TRUE, width = "100%", align = "c")
    )
  })
  
