  # Sample Size Requirements Plot (Average)
  output$power_requirement_plot <- renderPlot({ 
    req(values$power_summary, values$power_current_n)
    req(nrow(values$power_summary) > 0)  # Ensure data has rows to aggregate
    
    params <- get_power_params()
    req(!is.na(params$current_n))
    
    # Ensure scalar numeric for arithmetic and plotting
    current_n <- suppressWarnings(as.numeric(params$current_n[1]))
    target_pct <- params$target_pct
    
    # Get font sizes
    title_size <- input$power_title_size %||% 14
    axis_title_size <- input$power_axis_title_size %||% 12
    axis_text_size <- input$power_axis_text_size %||% 10
    legend_text_size <- input$power_legend_text_size %||% 12
    
    # Calculate average required sample size by effect size
    avg_req <- aggregate(MinSampleSizeForTargetPower ~ EffectSize,
                         data = values$power_summary,
                         FUN = function(x) ceiling(mean(x, na.rm = TRUE)))
    
    # Ensure numeric y column (defensive against any upstream type drift)
    avg_req$MinSampleSizeForTargetPower <- suppressWarnings(as.numeric(avg_req$MinSampleSizeForTargetPower))
    
    p <- ggplot(avg_req, aes(x = as.factor(EffectSize), y = MinSampleSizeForTargetPower)) +
      geom_col(fill = "steelblue", color = "black", width = 0.6) +
      geom_text(aes(label = MinSampleSizeForTargetPower), vjust = -0.5,
                size = 5, fontface = "bold") +
      labs(
        title = paste0("Average Sample Size Required for ", target_pct, "% Power"),
        x = "Effect Size",
        y = "Required Sample Size per Group"
      ) +
      scale_y_continuous(expand = expansion(mult = c(0, 0.15)), limits = c(0, NA)) +
      ggprism::theme_prism(base_size = 12) +
      theme(
        plot.title = element_text(size = title_size, face = "bold", hjust = 0.5),
        axis.text = element_text(size = axis_text_size, color = "black"),
        axis.title = element_text(size = axis_title_size, face = "bold", color = "black")
      )
    if (length(current_n) == 1 && is.finite(current_n) && !is.na(current_n)) {
      p <- p +
        geom_hline(yintercept = current_n, linetype = "dashed",
                   color = "red", linewidth = 1.2) +
        annotate("text", x = 0.7, y = current_n * 1.1,
                 label = paste("Current n =", current_n),
                 color = "red", size = 4, hjust = 0)
    }
    p
  })
  
  
