    target_pct <- params$target_pct
    
    ggplot(top_features, aes(x = reorder(Label, CurrentPower), y = CurrentPower)) +
      geom_col(aes(fill = CurrentPower >= target_fraction),
               color = "black", linewidth = 0.5) +
      geom_text(aes(label = paste0(round(CurrentPower * 100, 1), "%")),
                hjust = -0.1, size = 3.5, fontface = "bold") +
      geom_hline(yintercept = target_fraction, linetype = "dashed",
                 color = "red", linewidth = 1) +
      coord_flip() +
      scale_fill_manual(values = c("TRUE" = "darkgreen", "FALSE" = "orange"),
                        labels = c("Below Target", "Above Target"),
                        name = "Power Status") +
      scale_y_continuous(labels = scales::percent, limits = c(0, max(top_features$CurrentPower) * 1.15), expand = expansion(mult = c(0, 0))) +
      labs(
        title = paste0("Top 20 Features by Current Power (Effect Size = ",
                       input$power_rank_effect_size, ")"),
        x = x_axis_label,
        y = "Current Statistical Power"
      ) +
      ggprism::theme_prism(base_size = 12) +
      theme(
        plot.title = element_text(size = title_size, face = "bold", hjust = 0.5),
        axis.text.y = element_text(size = axis_text_size, color = "black"),
        axis.text.x = element_text(size = axis_text_size, color = "black"),
        axis.title = element_text(size = axis_title_size, face = "bold", color = "black"),
        legend.text = element_text(size = legend_text_size),
        legend.position = "bottom"
      )
  })
  
  # Power Ranking Table
  output$power_ranking_table <- DT::renderDataTable({
    req(values$power_current, input$power_rank_effect_size)
    
    # Determine if using IDs
    use_ids_for_table <- !is.null(input$power_label_type) &&
      input$power_label_type == "ids" &&
      !is.null(values$power_current$ID)
    
    params <- get_power_params()
    target_pct <- params$target_pct
    
    ranking_data <- values$power_current %>%
      filter(EffectSize == as.numeric(input$power_rank_effect_size)) %>%
      arrange(desc(CurrentPower)) %>%
      mutate(
        Rank = row_number(),
        CurrentPower = paste0(round(CurrentPower * 100, 1), "%"),
        PowerStatus = ifelse(as.numeric(sub("%", "", CurrentPower)) >= target_pct,
                             "✓ Adequate", "✗ Underpowered")
      )
    
    # Select columns based on label type preference
    if (use_ids_for_table) {
      ranking_data <- ranking_data %>% select(Rank, ID, CurrentPower, PowerStatus)
    } else {
      ranking_data <- ranking_data %>% select(Rank, Feature, CurrentPower, PowerStatus)
    }
    
    DT::datatable(ranking_data,
                  options = list(pageLength = 20, scrollX = TRUE),
                  rownames = FALSE)
  })
  
  # Power Distribution Plot
  output$power_distribution_plot <- renderPlot({ 
    req(values$power_current)
    
    # Get font sizes
    title_size <- input$power_title_size %||% 14
    axis_title_size <- input$power_axis_title_size %||% 12
    axis_text_size <- input$power_axis_text_size %||% 10
    legend_text_size <- input$power_legend_text_size %||% 12
    
    params <- get_power_params()
    req(!is.na(params$target_fraction))
    
    target_fraction <- params$target_fraction
    target_pct <- params$target_pct
    
    ggplot(values$power_current, aes(x = CurrentPower, fill = as.factor(EffectSize))) +
      geom_histogram(bins = 30, alpha = 0.7, position = "dodge",
                     color = "black", linewidth = 0.3) +
      geom_vline(xintercept = target_fraction, linetype = "dashed",
                 color = "red", linewidth = 1.2) +
      scale_x_continuous(labels = scales::percent) +
      scale_fill_brewer(palette = "Set2", name = "Effect Size") +
      labs(
        title = paste0("Distribution of Statistical Power Across Features (n = ",
                       as.character(values$power_current_n), ")"),
        x = "Current Statistical Power",
        y = "Number of Features",
        caption = paste("Red line: Target power =", target_pct, "%")
      ) +
      ggprism::theme_prism(base_size = 12) +
      theme(
        plot.title = element_text(size = title_size, face = "bold", hjust = 0.5),
