      summarise(
        Count = n(),
        MeanPower = paste0(round(mean(CurrentPower) * 100, 1), "%"),
        .groups = 'drop'
      ) %>%
      arrange(desc(Count))
    
    DT::datatable(cat_summary,
                  options = list(dom = 't'),
                  rownames = FALSE,
                  colnames = c("Category", "# Features", "Mean Power"))
  })
  
  # Detailed Results Table
  output$power_detailed_table <- DT::renderDataTable({
