    # Filter by the selected feature/ID
    if (use_ids_for_plot) {
      feature_data <- values$power_global_results %>%
        filter(ID == input$power_global_feature)
    } else {
      feature_data <- values$power_global_results %>%
        filter(Feature == input$power_global_feature)
    }
    
    if (nrow(feature_data) == 0) return(NULL)
    
    test_label <- if (values$power_is_parametric) "F-Test" else "H-Test"
    method_label <- if (values$power_is_parametric) "ANOVA" else "Kruskal-Wallis"
    
    params <- get_power_params()
    req(!is.na(params$target_fraction))
    
    target_fraction <- params$target_fraction
    target_pct <- params$target_pct
    
    current_global_n <- suppressWarnings(as.numeric(values$power_global_summary$CurrentSampleSize[1]))
    req(length(current_global_n) > 0, !is.na(current_global_n))
    
    # Use appropriate label in title
    plot_title <- paste0("Global ", test_label, " Power Curve: ", input$power_global_feature)
    
    ggplot(feature_data, aes(x = SampleSize, y = Power, color = as.factor(EffectSize))) +
