        arrange(desc(CurrentPower)) %>%
        head(20)
      
      p <- ggplot(top_features, aes(x = reorder(Feature, CurrentPower), y = CurrentPower)) +
        geom_col(aes(fill = CurrentPower >= params$target_fraction),
                 color = "black", linewidth = 0.5) +
        geom_text(aes(label = paste0(round(CurrentPower * 100, 1), "%")),
                  hjust = -0.1, size = 3.5, fontface = "bold") +
        geom_hline(yintercept = params$target_fraction, linetype = "dashed",
                   color = "red", linewidth = 1) +
        coord_flip() +
        scale_fill_manual(values = c("TRUE" = "darkgreen", "FALSE" = "orange"),
                          labels = c("Below Target", "Above Target"),
                          name = "Power Status") +
        scale_y_continuous(labels = scales::percent, limits = c(0, max(top_features$CurrentPower) * 1.15)) +
        labs(
          title = paste0("Top 20 Features by Current Power (Effect Size = ",
                         input$power_rank_effect_size, ")"),
          x = "Feature",
          y = "Current Statistical Power"
        ) +
        ggprism::theme_prism(base_size = 12) +
        theme(
          plot.title = element_text(size = 13, face = "bold", hjust = 0.5),
          axis.text.y = element_text(size = 9, color = "black"),
          axis.text.x = element_text(size = 11, color = "black"),
          axis.title = element_text(size = 12, face = "bold", color = "black"),
          legend.position = "bottom",
          plot.margin = margin(10, 10, 10, 10)
        )
      
      ggsave(file, plot = p, width = 10, height = 8, dpi = dpi, device = resolve_ggsave_device(image_format), bg = "white")
    }
  )
  
  # Download Ranking Table
  output$download_ranking_table <- downloadHandler(
    filename = function() {
      paste0("Feature_Ranking_Table_ES", input$power_rank_effect_size, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(values$power_current, input$power_rank_effect_size)
      
      params <- get_power_params()
      
      ranking_data <- values$power_current %>%
        filter(EffectSize == as.numeric(input$power_rank_effect_size)) %>%
        arrange(desc(CurrentPower)) %>%
        mutate(
          Rank = row_number(),
          CurrentPower = paste0(round(CurrentPower * 100, 1), "%"),
          PowerStatus = ifelse(as.numeric(sub("%", "", CurrentPower)) >= params$target_pct,
                               "✓ Adequate", "✗ Underpowered")
        ) %>%
        select(Rank, Feature, CurrentPower, PowerStatus)
      
      write.csv(ranking_data, file, row.names = FALSE)
    }
  )
  
  # Download Pie Chart
  output$download_pie_chart <- downloadHandler(
    filename = function() {
      paste0("Feature_Categorization_ES", input$power_rank_effect_size, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(values$power_current, input$power_rank_effect_size)
      
      dpi <- get_safe_global_dpi()
      image_format <- get_safe_global_image_format()
      
      categorize_power <- function(power, target) {
        if (power >= target) return("Adequate")
        else if (power >= target * 0.6) return("Moderate")
        else return("Low")
      }
      
      target_power <- input$power_target / 100
      
      cat_data <- values$power_current %>%
        filter(EffectSize == as.numeric(input$power_rank_effect_size)) %>%
        mutate(Category = sapply(CurrentPower, categorize_power, target = target_power)) %>%
        group_by(Category) %>%
        summarise(Count = n(), .groups = 'drop') %>%
        mutate(
          Percentage = Count / sum(Count) * 100,
          Label = paste0(Count, "\n(", round(Percentage, 1), "%)")
        )
      
      p <- ggplot(cat_data, aes(x = "", y = Count, fill = Category)) +
        geom_bar(stat = "identity", width = 1, color = NA) +
        coord_polar("y", start = 0) +
        geom_text(aes(label = Label), position = position_stack(vjust = 0.5),
                  size = 5, fontface = "bold", color = "white") +
        scale_fill_manual(values = c("Adequate" = "darkgreen",
                                     "Moderate" = "orange",
                                     "Low" = "red")) +
        labs(title = paste0("Feature Categorization (Effect Size = ",
                            input$power_rank_effect_size, ")")) +
        theme_void() +
        theme(
          plot.title = element_text(size = 13, face = "bold", hjust = 0.5),
          legend.position = "bottom"
        )
      
      ggsave(file, plot = p, width = 6, height = 6, dpi = dpi, device = resolve_ggsave_device(image_format), bg = "white")
    }
  )
  
  # Download Global Power Distribution
  output$download_global_dist <- downloadHandler(
    filename = function() {
      paste0("Global_Power_Distribution_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(values$power_global_summary)
      
      dpi <- get_safe_global_dpi()
      image_format <- get_safe_global_image_format()
      test_label <- if (values$power_is_parametric) "F-Test" else "H-Test"
      method_label <- if (values$power_is_parametric) "ANOVA" else "Kruskal-Wallis"
      
      p <- ggplot(values$power_global_summary, aes(x = CurrentPower, fill = as.factor(EffectSize))) +
        geom_histogram(bins = 25, alpha = 0.7, position = "dodge",
                       color = "black", linewidth = 0.3) +
        geom_vline(xintercept = input$power_target / 100, linetype = "dashed",
                   color = "red", linewidth = 1.2) +
        scale_x_continuous(labels = scales::percent, limits = c(0, 1)) +
        scale_fill_brewer(palette = "Set2", name = "Effect Size") +
        labs(
          title = paste0("Global ", test_label, " Power Distribution"),
          x = "Statistical Power",
          y = "Number of Features",
          caption = paste("Red line: Target power =", input$power_target, "% (", method_label, ")")
        ) +
        ggprism::theme_prism(base_size = 12) +
        theme(
          plot.title = element_text(size = 13, face = "bold", hjust = 0.5),
          axis.text = element_text(size = 11, color = "black"),
          axis.title = element_text(size = 12, face = "bold", color = "black"),
          legend.position = "bottom",
          plot.caption = element_text(size = 9, hjust = 0)
        )
      
      ggsave(file, plot = p, width = 8, height = 6, dpi = dpi, device = resolve_ggsave_device(image_format), bg = "white")
    }
  )
  
  # Download Global Power Curve
  output$download_global_curve <- downloadHandler(
    filename = function() {
      paste0("Global_Power_Curve_", input$power_global_feature, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(values$power_global_results, input$power_global_feature)
      
      dpi <- get_safe_global_dpi()
      image_format <- get_safe_global_image_format()
      
      # Determine if using IDs or feature names
      use_ids_for_plot <- !is.null(input$power_label_type) &&
        input$power_label_type == "ids" &&
        !is.null(values$power_global_results$ID)
      
      # Filter by the selected feature/ID
      if (use_ids_for_plot) {
        feature_data <- values$power_global_results %>%
          filter(ID == input$power_global_feature)
      } else {
        feature_data <- values$power_global_results %>%
          filter(Feature == input$power_global_feature)
      }
      
      test_label <- if (values$power_is_parametric) "F-Test" else "H-Test"
      method_label <- if (values$power_is_parametric) "ANOVA" else "Kruskal-Wallis"
      
      plot_title <- paste0("Global ", test_label, " Power Curve: ", input$power_global_feature)
      
      p <- ggplot(feature_data, aes(x = SampleSize, y = Power, color = as.factor(EffectSize))) +
        geom_line(linewidth = 1.5) +
        geom_vline(xintercept = values$power_global_summary$CurrentSampleSize[1],
                   linetype = "dashed", color = "red", linewidth = 1) +
        geom_hline(yintercept = input$power_target / 100, linetype = "dotted",
                   color = "gray50", linewidth = 1) +
        labs(
          title = plot_title,
          subtitle = paste0(method_label,
                            " | ", unique(values$power_global_summary$NumGroups)[1], " groups"),
          x = "Sample Size per Group",
          y = "Statistical Power",
          color = "Effect Size"
        ) +
        scale_y_continuous(labels = scales::percent, limits = c(0, 1)) +
        scale_color_brewer(palette = "Set1") +
        ggprism::theme_prism(base_size = 12) +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 11, hjust = 0.5),
          axis.text = element_text(size = 11, color = "black"),
          axis.title = element_text(size = 12, face = "bold", color = "black"),
          legend.position = "bottom"
        )
      
      ggsave(file, plot = p, width = 10, height = 6, dpi = dpi, device = resolve_ggsave_device(image_format), bg = "white")
    }
  )
  
