  # Save current analysis
  observeEvent(input$save_current_analysis, {
    req(input$analysis_name, input$analysis_omics_type)
    req(values$normalized_data)
    
    # Validate inputs
    if (input$analysis_name == "" || input$analysis_omics_type == "") {
      showNotification("Please provide analysis name and omics type", type = "error")
      return()
    }
    
    # Check for duplicate names
    if (input$analysis_name %in% names(saved_analyses$analyses_list)) {
      showModal(modalDialog(
        title = "Analysis Name Exists",
        "An analysis with this name already exists. Do you want to overwrite it?",
        footer = tagList(
          modalButton("Cancel"),
          actionButton("confirm_overwrite", "Overwrite", class = "btn-warning")
        )
      ))
      return()
    }
    
    # Create analysis object
    tryCatch({
      analysis_obj <- list(
        name = input$analysis_name,
        omics_type = input$analysis_omics_type,
        timestamp = Sys.time(),
        
        # Data matrices
        original_unfiltered_data = values$original_unfiltered_data,  # True raw data
        raw_data = values$raw_data,  # Processed but not normalized
        normalized_data = values$normalized_data,
        
        # Sample and feature information
        samples = colnames(values$normalized_data),
        features = rownames(values$normalized_data),
        cleaned_molecules = values$cleaned_molecules,
        n_samples = ncol(values$normalized_data),
        n_features = nrow(values$normalized_data),
        
        # Accession IDs (if available)
        accession_ids = values$accession_ids,
        accession_id_column = values$accession_id_column,
        
        # Group information
        # Create proper group assignment vector (one label per sample)
        groups = create_proper_group_labels(values$unique_groups, values$group_column_indices),
        group_indices = values$group_column_indices,
        
        # Statistical results (if available)
        stat_results = values$stat_results,
        comparison_results = values$comparison_results,
        significant_features = values$significant_features,
        
        # Bootstrap Analysis Results (if available)
        bootstrap_results = values$bootstrap_results,
        bootstrap_pvals_matrix = values$bootstrap_pvals_matrix,
        bootstrap_fcs_matrix = values$bootstrap_fcs_matrix,
        bootstrap_params = values$bootstrap_params,
        
        # PCA Results (if available)
        pca_result = values$pca_result,
        pca_data = values$pca_data,
        pca_labels = values$pca_labels,
        pca_top_features = values$pca_top_features,
