        # MOFA and Multi-Omics Results (if available)
        mofa_results = values$mofa_results,
        integration_results = values$integration_results,
        
        # Processing parameters
        normalization_method = input$norm_method,
        statistical_method = input$sig_method,
        imputation_method = input$impute_method,
        
        # Data Processing Settings
        ui_settings = list(
          # Data Input Settings
          data_samples_are_rows = input$data_samples_are_rows,
          data_treat_zeros_as_na = input$data_treat_zeros_as_na,
          enable_custom_na = input$enable_custom_na,
          custom_na_values = input$custom_na_values,
          clean_feature_ids = input$clean_feature_ids,
          
          # Missing Value Handling
          missing_value_strategy = input$missing_value_strategy,
          na_threshold = input$na_threshold,
          check_within_groups = input$check_within_groups,
          filter_before_impute = input$filter_before_impute,
          impute_na_threshold = input$impute_na_threshold,
          impute_check_within_groups = input$impute_check_within_groups,
          imputation_method = input$imputation_method,
          
          # Normalization Settings
          norm_method = input$norm_method,
          log2_norm_timing = input$log2_norm_timing,
          sum_norm_percentage = input$sum_norm_percentage,
          
          # Batch Correction Settings
          batch_correction_enabled = input$batch_correction_enabled,
          batch_correction_method = input$batch_correction_method,
          batch_column = input$batch_column,
          group_column = input$group_column,
          viz_batch_enable = input$viz_batch_enable,
          viz_batch_method = input$viz_batch_method,
          
          # Statistical Testing Settings
          sig_method = input$sig_method,
          rots_B = input$rots_B,
          rots_K = input$rots_K,
          rots_seed = input$rots_seed,
          rots_parallel = input$rots_parallel,
          rots_cores = input$rots_cores,
          deseq2_test = input$deseq2_test,
          deseq2_fitType = input$deseq2_fitType,
          deseq2_alpha = input$deseq2_alpha,
          deseq2_independent_filtering = input$deseq2_independent_filtering,
          deseq2_cooksCutoff = input$deseq2_cooksCutoff,
          deseq2_transform = input$deseq2_transform,
          limma_voom_norm_method = input$limma_voom_norm_method,
          limma_voom_trend = input$limma_voom_trend,
          limma_voom_robust = input$limma_voom_robust,
          
          # Bootstrap Analysis Settings (if enabled)
          bootstrap_enabled = isTRUE(input$enable_bootstrap),
          bootstrap_replicates = input$bootstrap_replicates,
          
          # PCA Settings (if used)
          pca_top_features = input$pca_top_features,
          pca_feature_ranking = input$pca_feature_ranking,
          pca_custom_colors = input$pca_custom_colors,
          use_pca_features = input$use_pca_features,
          
          # Feature Selection Settings (if used)
          feature_selection_method = input$feature_selection_method,
          enable_enhanced_stability = input$enable_enhanced_stability,
          stability_method = input$stability_method,
          stability_threshold = input$stability_threshold,
          
          # ML Settings
          feature_selection_alpha = input$feature_selection_alpha,
          feature_selection_lambda = input$feature_selection_lambda,
          feature_selection_ntree = input$feature_selection_ntree,
          feature_selection_mtry = input$feature_selection_mtry
        ),
        
        # Enhancement Results
        enhancement_data = list(
          # PCA Enhancement Settings
          pca_settings = list(
            top_features = input$pca_top_features,
            feature_ranking = input$pca_feature_ranking,
            custom_colors = input$pca_custom_colors,
            use_for_downstream = input$use_pca_features
          ),
          # Bootstrap Settings
          bootstrap_settings = if (!is.null(values$bootstrap_params)) {
