          } else {
            list(enabled = FALSE)
          },
          # ML Feature Selection Settings
          ml_settings = list(
            method = input$feature_selection_method,
            stability_enabled = input$enable_enhanced_stability,
            stability_method = input$stability_method
          )
        ),
        
        # Metadata
        metadata = list(
          upload_file = current_data_file()$name,
          processing_date = Sys.time()
        )
      )
      
      # Save to reactive values
      saved_analyses$analyses_list[[input$analysis_name]] <- analysis_obj
      saved_analyses$counter <- saved_analyses$counter + 1
      
      showNotification(
        paste0("Analysis '", input$analysis_name, "' saved successfully!"),
        type = "message",
        duration = 5
      )
      
      # Clear inputs
      updateTextInput(session, "analysis_name", value = "")
      updateSelectInput(session, "analysis_omics_type", selected = "")
      
    }, error = function(e) {
      showNotification(
        paste("Error saving analysis:", e$message),
        type = "error",
        duration = 10
      )
    })
  })
  
