        label = NULL,
        icon = icon("save"),
        title = "Save Enrichment Results",
        class = "btn-success mlfs-btn",
        style = "padding: 8px 16px; display: flex; align-items: center; gap: 6px; white-space: nowrap;"
      )
    } else {
      # Disabled state when no enrichment results
      tags$button(
        type = "button",
        class = "btn btn-secondary mlfs-btn",
        disabled = "disabled",
        title = "Run enrichment analysis first to save results",
        style = "padding: 8px 16px; display: flex; align-items: center; gap: 6px; white-space: nowrap; opacity: 0.5;",
        icon("save")
      )
    }
  })
  
  # Handle opening the Save Enrichment modal
  observeEvent(input$open_save_enrichment_modal, {
    req(proteomics_values$enrichment_results)
    
    showModal(modalDialog(
      title = "Save Enrichment Results",
      size = "m",
      easyClose = TRUE,
      
      div(class = "mlfs-card-body",
          textInput("enrichment_save_name", "Analysis Name:",
                    placeholder = "e.g., Proteomics_KEGG_Treatment",
                    width = "100%"),
          selectInput("enrichment_omics_type", "Omics Type:",
                      choices = c("Select type..." = "",
                                  "Proteomics" = "proteomics",
                                  "Transcriptomics" = "transcriptomics",
                                  "Metabolomics" = "metabolomics",
                                  "Lipidomics" = "lipidomics",
                                  "Glycomics" = "glycomics",
                                  "Other" = "other"),
                      width = "100%"),
          hr(),
          h6("Current Enrichment Summary", style = "font-weight: 600;"),
          verbatimTextOutput("enrichment_save_summary"),
          hr(),
          fluidRow(
            column(6,
                   actionButton("save_enrichment_to_session", "Save to Session",
                                icon = icon("memory"),
                                class = "btn-primary mlfs-btn",
                                width = "100%")
            ),
            column(6,
                   downloadButton("download_enrichment_oms", "Download .oms",
                                  class = "btn-success mlfs-btn",
                                  style = "width: 100%;")
            )
          ),
          hr(),
          h6("Saved Enrichments in Session", style = "font-weight: 600; margin-top: 15px;"),
          uiOutput("saved_enrichments_list"),
          helpText("Saved enrichments can be used for Pathway-Level Integration in the Multi-Omics Integration tab."),
          br()
      ),
      footer = modalButton("Close")
    ))
  })
  
  # Render enrichment summary for save modal
  output$enrichment_save_summary <- renderText({
    req(proteomics_values$enrichment_results)
    
    results <- proteomics_values$enrichment_results
    tool <- input$proteomics_tool %||% "unknown"
    
    # Get result count
    n_results <- tryCatch({
      if (!is.null(results$table) && (is.data.frame(results$table) || is.matrix(results$table))) {
        nrow(results$table)
      } else if (!is.null(results$result) && (is.data.frame(results$result) || is.matrix(results$result))) {
        nrow(results$result)
      } else if (!is.null(results$results) && (is.data.frame(results$results) || is.matrix(results$results))) {
        nrow(results$results)
      } else if (is.data.frame(results) || is.matrix(results)) {
        nrow(results)
      } else if (inherits(results, "enrichResult") || inherits(results, "gseaResult")) {
        nrow(as.data.frame(results))
      } else if (is.list(results)) {
        list_counts <- vapply(results, function(x) {
          if (is.data.frame(x) || is.matrix(x)) {
            nrow(x)
          } else if (inherits(x, "enrichResult") || inherits(x, "gseaResult")) {
            nrow(as.data.frame(x))
          } else if (!is.null(x$table) && (is.data.frame(x$table) || is.matrix(x$table))) {
            nrow(x$table)
          } else if (!is.null(x$result) && (is.data.frame(x$result) || is.matrix(x$result))) {
            nrow(x$result)
          } else if (!is.null(x$results) && (is.data.frame(x$results) || is.matrix(x$results))) {
            nrow(x$results)
          } else {
            0L
          }
        }, integer(1))
        sum(list_counts)
      } else {
        0L
      }
    }, error = function(e) 0L)
    
    # Get gene list size
    n_genes <- length(proteomics_values$gene_list %||% character(0))
    
    paste0(
      "Tool: ", tool, "\n",
      "Enrichment results: ", n_results, " terms\n",
      "Query genes: ", n_genes
    )
  })
  
  # Save enrichment to session
  observeEvent(input$save_enrichment_to_session, {
    req(proteomics_values$enrichment_results)
    req(input$enrichment_save_name)
    req(input$enrichment_omics_type)
    
    if (nchar(trimws(input$enrichment_save_name)) == 0) {
      showNotification("Please enter a name for the enrichment analysis.", type = "error")
      return()
    }
    
    if (input$enrichment_omics_type == "") {
      showNotification("Please select an omics type.", type = "error")
      return()
    }
    
    tryCatch({
      # Create enrichment object to save
      enrichment_obj <- list(
        type = "enrichment",
        name = input$enrichment_save_name,
        omics_type = input$enrichment_omics_type,
        tool = input$proteomics_tool,
        organism = input$proteomics_organism,
        id_type = input$proteomics_id_type,
        results = proteomics_values$enrichment_results,
        gene_list = proteomics_values$gene_list,
        background = proteomics_values$background,
        fold_change_data = proteomics_values$fold_change_data,
        analysis_params = list(
          source = input$proteomics_source,
          analysis_type = input$proteomics_analysis_type,
          pval_cutoff = input$proteomics_pairwise_pval,
          fc_cutoff = input$proteomics_pairwise_fc
        ),
        timestamp = Sys.time()
      )
      
      # Save to multiomics$loaded_enrichments
      multiomics$loaded_enrichments[[input$enrichment_save_name]] <- enrichment_obj
      
      showNotification(
        paste0("Enrichment '", input$enrichment_save_name, "' saved to session!"),
        type = "message",
        duration = 3
      )
      
      # Clear inputs
      updateTextInput(session, "enrichment_save_name", value = "")
      
    }, error = function(e) {
      showNotification(
        paste("Error saving enrichment:", e$message),
        type = "error",
        duration = 10
      )
    })
  })
  
  # Download enrichment as .oms file
  output$download_enrichment_oms <- downloadHandler(
    filename = function() {
      name <- if (nchar(trimws(input$enrichment_save_name %||% "")) > 0) {
        gsub("[^[:alnum:]]", "_", input$enrichment_save_name)
      } else {
        "enrichment_results"
      }
      omics_type <- input$enrichment_omics_type %||% "unknown"
      date_str <- format(Sys.Date(), "%Y-%m-%d")
      paste0(name, "_enrichment_", omics_type, "_", date_str, ".oms")
    },
    content = function(file) {
      req(proteomics_values$enrichment_results)
      
      tryCatch({
        # Create enrichment object
        enrichment_obj <- list(
          type = "enrichment",
          name = input$enrichment_save_name %||% "Unnamed Enrichment",
          omics_type = input$enrichment_omics_type %||% "unknown",
          tool = input$proteomics_tool,
          organism = input$proteomics_organism,
          id_type = input$proteomics_id_type,
          results = proteomics_values$enrichment_results,
          gene_list = proteomics_values$gene_list,
          background = proteomics_values$background,
          fold_change_data = proteomics_values$fold_change_data,
          analysis_params = list(
            source = input$proteomics_source,
            analysis_type = input$proteomics_analysis_type,
            pval_cutoff = input$proteomics_pairwise_pval,
            fc_cutoff = input$proteomics_pairwise_fc
          ),
          timestamp = Sys.time()
        )
        
        # Save as RDS
        saveRDS(enrichment_obj, file = file, compress = "xz")
        
        showNotification("Enrichment downloaded successfully!", type = "message", duration = 3)
        
      }, error = function(e) {
        showNotification(paste("Error downloading:", e$message), type = "error", duration = 10)
      })
    }
  )
  
  # Render list of saved enrichments in session
  output$saved_enrichments_list <- renderUI({
    enrichments <- multiomics$loaded_enrichments
    
    if (length(enrichments) == 0) {
      return(div(class = "text-muted", style = "padding: 10px; text-align: center;",
                 icon("inbox"), " No enrichments saved yet"))
    }
    
    # Create list items for each saved enrichment
    items <- lapply(names(enrichments), function(name) {
      enr <- enrichments[[name]]
      n_results <- tryCatch({
        if (!is.null(enr$results$table)) nrow(enr$results$table)
        else if (is.data.frame(enr$results)) nrow(enr$results)
        else "N/A"
      }, error = function(e) "N/A")
      
      div(class = "saved-analysis-item",
          style = "padding: 8px; margin: 5px 0; background: #f8f9fa; border-radius: 5px; border-left: 3px solid #28a745;",
          div(style = "display: flex; justify-content: space-between; align-items: center;",
              div(
                strong(name),
                br(),
                tags$small(class = "text-muted",
                           paste0(enr$omics_type, " | ", enr$tool, " | ", n_results, " terms"))
              ),
              actionButton(
                paste0("remove_enrichment_", gsub("[^[:alnum:]]", "_", name)),
                label = NULL,
                icon = icon("times"),
                class = "btn btn-sm btn-outline-danger",
                onclick = sprintf("Shiny.setInputValue('remove_enrichment_name', '%s', {priority: 'event'});", name)
              )
          )
      )
    })
    
    tagList(items)
  })
  
  # Handle removing enrichment from session
  observeEvent(input$remove_enrichment_name, {
    req(input$remove_enrichment_name)
    name <- input$remove_enrichment_name
    
    if (name %in% names(multiomics$loaded_enrichments)) {
      multiomics$loaded_enrichments[[name]] <- NULL
      showNotification(paste0("Removed '", name, "' from session."), type = "message", duration = 2)
    }
  })
  
  # ========== END ENRICHMENT SAVE FUNCTIONALITY ==========
  
  # Handle opening the Save Analysis modal from header button
  observeEvent(input$open_save_analysis_modal, {
    showModal(modalDialog(
      title = "Save Analysis",
      size = "m",
      easyClose = TRUE,
      
      # Modal content (same as sidebar card)
      div(class = "mlfs-card-body",
          textInput("analysis_name", "Analysis Name:",
                    placeholder = "e.g., Proteomics_Treatment_A",
                    width = "100%"),
          selectInput("analysis_omics_type", "Omics Type:",
                      choices = c("Select type..." = "",
                                  "Proteomics" = "proteomics",
                                  "Metabolomics" = "metabolomics",
                                  "Transcriptomics" = "transcriptomics",
                                  "Lipidomics" = "lipidomics",
                                  "Glycomics" = "glycomics",
                                  "Other" = "other"),
                      width = "100%"),
          actionButton("save_current_analysis", "Save Analysis",
                       icon = icon("save"),
                       class = "btn-success mlfs-btn",
                       width = "100%"),
          hr(),
          h5("Import Analysis from File", style = "font-weight: 600; margin-top: 10px;"),
          fileInput("load_analysis_file", "Choose a file to import (.oms, .csv, .xlsx):",
                    accept = c(".oms", ".csv", ".xlsx", ".xls"),
                    width = "100%"),
          actionButton("load_analysis_from_file_btn", "Load Analysis",
                       icon = icon("upload"),
                       class = "btn-info mlfs-btn",
                       width = "100%",
                       style = "margin-top: 8px;"),
          helpText("Load a previously exported analysis (.oms) or import a single omics table (CSV/XLSX)."),
          hr(),
          h5("Saved Analyses", style = "font-weight: 600; margin-top: 10px;"),
          uiOutput("saved_analyses_list"),
          helpText("Saved analyses can be downloaded as .oms files or loaded in the Multi-Omics Integration tab for N-integration with matching samples."),
          br(),
          footer = tagList(
            modalButton("Close")
          )
      )
    ))
  })
  
  # DOWNLOAD ANALYSIS AS .OMS FILE
  # Handle dynamic download buttons for each analysis
  observe({
    saved_analyses$counter  # Trigger when analyses list changes
    
    lapply(names(saved_analyses$analyses_list), function(name) {
      download_button_id <- paste0("download_analysis_", gsub("[^[:alnum:]]", "_", name))
      
      output[[download_button_id]] <- downloadHandler(
        filename = function() {
          # Create filename: AnalysisName_OmicsType_YYYY-MM-DD.oms
          analysis <- saved_analyses$analyses_list[[name]]
          clean_name <- gsub("[^[:alnum:]]", "_", name)
          date_str <- format(Sys.Date(), "%Y-%m-%d")
          paste0(clean_name, "_", analysis$omics_type, "_", date_str, ".oms")
        },
        content = function(file) {
          # Get the analysis object
          analysis <- saved_analyses$analyses_list[[name]]
          
          # Save as RDS (compressed binary format)
          # .oms = OmicsStack format
          tryCatch({
            saveRDS(analysis, file = file, compress = "xz")
            showNotification(
              paste0("Analysis '", name, "' downloaded successfully!"),
              type = "message",
              duration = 3
            )
          }, error = function(e) {
            showNotification(
              paste("Error downloading analysis:", e$message),
              type = "error",
              duration = 10
            )
          })
        }
      )
    })
  })
  
  # LOAD ANALYSIS FROM .OMS FILE
  # Handle Load button click after file selection
  observeEvent(input$load_analysis_from_file_btn, {
    req(input$load_analysis_file)

    tryCatch({
      fname <- input$load_analysis_file$name
      fpath <- input$load_analysis_file$datapath
      fext <- tolower(tools::file_ext(fname))

      # If not an .oms file, attempt to import a single omics table (CSV / XLSX)
      if (fext != "oms") {
        if (fext %in% c("xls", "xlsx")) {
          if (!requireNamespace("readxl", quietly = TRUE)) {
            showNotification("Package 'readxl' is required to import Excel files. Please install it and try again.", type = "error", duration = 10)
            return()
          }
          df <- as.data.frame(readxl::read_excel(fpath), stringsAsFactors = FALSE)
        } else {
          df <- tryCatch({ utils::read.csv(fpath, stringsAsFactors = FALSE, check.names = FALSE) }, error = function(e) { showNotification(paste("Failed to read", fname, ":", e$message), type = "error", duration = 10); NULL })
          if (is.null(df)) return()
        }

        # Interpret table: try to coerce to features x samples
        if (ncol(df) >= 2 && !all(sapply(df[[1]], function(x) !is.na(suppressWarnings(as.numeric(as.character(x)))))) && all(sapply(df[-1], function(col) all(!is.na(suppressWarnings(as.numeric(as.character(col)))))))) {
          rownames(df) <- df[[1]]
          df <- df[,-1, drop = FALSE]
        } else if (all(sapply(df, is.numeric))) {
          # columns are samples
          if (is.null(rownames(df)) || all(rownames(df) == "")) {
            rownames(df) <- paste0("Feature_", seq_len(nrow(df)))
          }
        } else if (!all(sapply(df, is.numeric)) && ncol(df) >= 2 && any(sapply(df[-1], function(col) all(!is.na(suppressWarnings(as.numeric(as.character(col)))))))) {
          # first column sample IDs -> transpose
          sample_ids <- as.character(df[[1]])
          numpart <- as.data.frame(df[,-1, drop = FALSE], stringsAsFactors = FALSE)
          numpart <- as.data.frame(lapply(numpart, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE)
          df_t <- as.data.frame(t(numpart), stringsAsFactors = FALSE)
          colnames(df_t) <- sample_ids
          df <- df_t
          if (is.null(rownames(df)) || all(rownames(df) == "")) rownames(df) <- paste0("Feature_", seq_len(nrow(df)))
        } else {
          showNotification("Could not interpret the imported file. Please supply a standard feature x sample table or an .oms file.", type = "error", duration = 10)
          return()
        }

        analysis_obj <- list(
          name = tools::file_path_sans_ext(fname),
          omics_type = input$analysis_omics_type %||% "imported",
          normalized_data = as.data.frame(lapply(df, function(x) as.numeric(as.character(x))), stringsAsFactors = FALSE, row.names = rownames(df)),
          samples = colnames(df),
          features = rownames(df),
          groups = NULL,
          group_indices = NULL
        )

      } else {
        # Read the .oms file (which is just RDS)
        analysis_obj <- readRDS(input$load_analysis_file$datapath)
      }
      
      # ===== CHECK IF THIS IS AN ENRICHMENT FILE =====
      # Enrichment files have type = "enrichment" and different required fields
      if (!is.null(analysis_obj$type) && analysis_obj$type == "enrichment") {
        # This is an enrichment results file - handle separately
        enr_name <- analysis_obj$name %||% tools::file_path_sans_ext(fname)
        
        # Store in loaded_enrichments for pathway integration
        multiomics$loaded_enrichments[[enr_name]] <- analysis_obj
        
        showNotification(
          paste0("Enrichment '", enr_name, "' loaded successfully! ",
                 "Available for Pathway-Level Integration."),
          type = "message",
          duration = 5
        )
        
        # Close modal if open
        removeModal()
        return()
      }

      # Validate it has required fields (for regular analysis files)
      req_fields <- c("name", "omics_type", "normalized_data", "samples", "features",
                      "groups", "group_indices")
      missing_fields <- setdiff(req_fields, names(analysis_obj))

      if (length(missing_fields) > 0) {
        showNotification(
          paste("Invalid analysis file. Missing fields:", paste(missing_fields, collapse = ", ")),
          type = "error",
          duration = 10
        )
        return()
      }
      
      # Clear current analysis to fully replace it
      values$analysis_has_run <- FALSE
      
      # Load data into values
      # Set original unfiltered data (this is the raw data before any processing)
      values$original_unfiltered_data <- analysis_obj$original_unfiltered_data %||% analysis_obj$raw_data
      values$raw_data <- analysis_obj$raw_data
      values$normalized_data <- analysis_obj$normalized_data
      
      # Set cleaned molecules (feature names from normalized data)
      values$cleaned_molecules <- analysis_obj$cleaned_molecules %||% rownames(analysis_obj$normalized_data)
      
      # Set corrected sample names from the loaded data's column names
      values$corrected_sample_names <- colnames(analysis_obj$normalized_data)
      
      # Restore accession IDs if available
      if (!is.null(analysis_obj$accession_ids)) {
        values$accession_ids <- analysis_obj$accession_ids
      }
      if (!is.null(analysis_obj$accession_id_column)) {
        values$accession_id_column <- analysis_obj$accession_id_column
      }
      
      # Restore group information
      # analysis_obj$groups is now a vector of group assignments (one per sample)
      # We need to extract unique groups and rebuild group_column_indices
      if (!is.null(analysis_obj$groups) && length(analysis_obj$groups) > 0) {
        # Handle case where groups might be saved as unique values (legacy) or as assignment vector (new)
        if (length(analysis_obj$groups) == length(colnames(analysis_obj$normalized_data))) {
          # New format: groups is assignment vector (one per sample)
          sample_names <- colnames(analysis_obj$normalized_data)
          values$unique_groups <- unique(analysis_obj$groups)
          
          # Rebuild group_column_indices from the assignment vector
          group_column_indices <- list()
          for (group_name in values$unique_groups) {
            indices <- which(analysis_obj$groups == group_name)
            group_column_indices[[group_name]] <- indices
          }
          values$group_column_indices <- group_column_indices
        } else {
          # Legacy format: groups is list of unique group names (for backward compatibility)
          values$unique_groups <- analysis_obj$groups
          values$group_column_indices <- analysis_obj$group_indices
        }
      }
      
      # Restore statistical results
      if (!is.null(analysis_obj$stat_results)) {
        values$stat_results <- analysis_obj$stat_results
      }
      if (!is.null(analysis_obj$comparison_results)) {
        values$comparison_results <- analysis_obj$comparison_results
      }
      if (!is.null(analysis_obj$significant_features)) {
        values$significant_features <- analysis_obj$significant_features
      }
      
      # Display raw and normalized data tables with fade transition from splash image
      shinyjs::delay(50, {
        shinyjs::addClass(id = "rawDataSplash", class = "fade-out")
        shinyjs::addClass(id = "rawDataTableWrapper", class = "fade-in")
      })
      
      # Force refresh of both data tables to display loaded data
      # Trigger reactive dependencies to force re-rendering of tables
      # This ensures tables update even on fresh app launch when no prior render exists
      shinyjs::delay(200, {
        # Update raw data table
        tryCatch({
          proxy_raw <- DT::dataTableProxy("rawDataTable")
          DT::reloadData(proxy_raw, resetPaging = TRUE)
        }, error = function(e) { NULL })
      })
      
      # Force normalized data table to re-render by triggering its reactive dependencies
      # The observe() block watching values$normalized_data will handle the actual update
      # This approach works both when table already exists and on fresh app launch
      shinyjs::delay(250, {
        # Trigger normalized data table reactive by invalidating/updating a dummy reactive
        isolate({
          # Force re-execution of the observe() that updates normalizedDataTable
          # by temporarily modifying and restoring a value
          temp_data <- values$normalized_data
          values$normalized_data <- NULL
          values$normalized_data <- temp_data
        })
      })
      
      # Mark that analysis has been loaded and run
      values$analysis_has_run <- TRUE
      
      # Update UI inputs from the saved parameters
      updateSelectInput(session, "norm_method", selected = analysis_obj$normalization_method)
      updateSelectInput(session, "sig_method", selected = analysis_obj$statistical_method)
      updateSelectInput(session, "impute_method", selected = analysis_obj$imputation_method)
      
      # Restore all UI settings if available
      if (!is.null(analysis_obj$ui_settings)) {
        settings <- analysis_obj$ui_settings
        
        # Data Input Settings
        if (!is.null(settings$data_samples_are_rows)) updateCheckboxInput(session, "data_samples_are_rows", value = settings$data_samples_are_rows)
        if (!is.null(settings$data_treat_zeros_as_na)) updateCheckboxInput(session, "data_treat_zeros_as_na", value = settings$data_treat_zeros_as_na)
        if (!is.null(settings$enable_custom_na)) updateCheckboxInput(session, "enable_custom_na", value = settings$enable_custom_na)
        if (!is.null(settings$custom_na_values)) updateTextInput(session, "custom_na_values", value = settings$custom_na_values)
        if (!is.null(settings$clean_feature_ids)) updateCheckboxInput(session, "clean_feature_ids", value = settings$clean_feature_ids)
        
        # Missing Value Handling
        if (!is.null(settings$missing_value_strategy)) updateRadioButtons(session, "missing_value_strategy", selected = settings$missing_value_strategy)
        if (!is.null(settings$na_threshold)) updateNumericInput(session, "na_threshold", value = settings$na_threshold)
        if (!is.null(settings$check_within_groups)) updateCheckboxInput(session, "check_within_groups", value = settings$check_within_groups)
        if (!is.null(settings$filter_before_impute)) updateCheckboxInput(session, "filter_before_impute", value = settings$filter_before_impute)
        if (!is.null(settings$impute_na_threshold)) updateNumericInput(session, "impute_na_threshold", value = settings$impute_na_threshold)
        if (!is.null(settings$impute_check_within_groups)) updateCheckboxInput(session, "impute_check_within_groups", value = settings$impute_check_within_groups)
        if (!is.null(settings$imputation_method)) updateSelectInput(session, "imputation_method", selected = settings$imputation_method)
        
        # Normalization Settings
        if (!is.null(settings$norm_method)) updateSelectInput(session, "norm_method", selected = settings$norm_method)
        if (!is.null(settings$log2_norm_timing)) {
          updateRadioButtons(session, "log2_norm_timing", selected = settings$log2_norm_timing)
        } else if (!is.null(settings$log2_before_norm) || !is.null(settings$log2_after_norm)) {
          legacy_timing <- if (isTRUE(settings$log2_before_norm)) "before" else if (isTRUE(settings$log2_after_norm)) "after" else "none"
          updateRadioButtons(session, "log2_norm_timing", selected = legacy_timing)
        }
        if (!is.null(settings$sum_norm_percentage)) updateCheckboxInput(session, "sum_norm_percentage", value = settings$sum_norm_percentage)
        
        # Batch Correction Settings
        if (!is.null(settings$batch_correction_enabled)) updateRadioButtons(session, "batch_correction_enabled", selected = settings$batch_correction_enabled)
        if (!is.null(settings$batch_correction_method)) updateSelectInput(session, "batch_correction_method", selected = settings$batch_correction_method)
        if (!is.null(settings$batch_column)) updateSelectInput(session, "batch_column", selected = settings$batch_column)
        if (!is.null(settings$group_column)) updateSelectInput(session, "group_column", selected = settings$group_column)
        if (!is.null(settings$viz_batch_enable)) updateCheckboxInput(session, "viz_batch_enable", value = settings$viz_batch_enable)
        if (!is.null(settings$viz_batch_method)) updateSelectInput(session, "viz_batch_method", selected = settings$viz_batch_method)
        
        # Statistical Testing Settings
        if (!is.null(settings$sig_method)) updateSelectInput(session, "sig_method", selected = settings$sig_method)
        if (!is.null(settings$rots_B)) updateNumericInput(session, "rots_B", value = settings$rots_B)
        if (!is.null(settings$rots_K)) updateNumericInput(session, "rots_K", value = settings$rots_K)
        if (!is.null(settings$rots_seed)) updateNumericInput(session, "rots_seed", value = settings$rots_seed)
        if (!is.null(settings$rots_parallel)) updateCheckboxInput(session, "rots_parallel", value = settings$rots_parallel)
        if (!is.null(settings$rots_cores)) updateNumericInput(session, "rots_cores", value = settings$rots_cores)
        if (!is.null(settings$deseq2_test)) updateSelectInput(session, "deseq2_test", selected = settings$deseq2_test)
        if (!is.null(settings$deseq2_fitType)) updateSelectInput(session, "deseq2_fitType", selected = settings$deseq2_fitType)
        if (!is.null(settings$deseq2_alpha)) updateNumericInput(session, "deseq2_alpha", value = settings$deseq2_alpha)
        if (!is.null(settings$deseq2_independent_filtering)) updateCheckboxInput(session, "deseq2_independent_filtering", value = settings$deseq2_independent_filtering)
        if (!is.null(settings$deseq2_cooksCutoff)) updateCheckboxInput(session, "deseq2_cooksCutoff", value = settings$deseq2_cooksCutoff)
        if (!is.null(settings$deseq2_transform)) updateSelectInput(session, "deseq2_transform", selected = settings$deseq2_transform)
        if (!is.null(settings$limma_voom_norm_method)) updateSelectInput(session, "limma_voom_norm_method", selected = settings$limma_voom_norm_method)
        if (!is.null(settings$limma_voom_trend)) updateCheckboxInput(session, "limma_voom_trend", value = settings$limma_voom_trend)
        if (!is.null(settings$limma_voom_robust)) updateCheckboxInput(session, "limma_voom_robust", value = settings$limma_voom_robust)
      }
      
      # Update group selection dropdowns for all tabs
      # PCA group selections
      updateSelectizeInput(session, "pcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
      updateSelectizeInput(session, "pcaGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # sPCA group selections
      updateSelectizeInput(session, "spcaGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
      updateSelectizeInput(session, "spcaGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Heatmap group selections (include lmROTS/lmeROTS variable names when present)
      g1_choices <- values$unique_groups
      tryCatch({
        av <- get_available_comparison_names()
        vv <- av[grepl("^(lmROTS|lmeROTS)_", av)]
        if (length(vv) > 0) g1_choices <- c(g1_choices, vv)
      }, error = function(e) NULL)
      updateSelectizeInput(session, "group1", choices = g1_choices, selected = g1_choices[1])
      updateSelectizeInput(session, "group2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Diff Analysis group selections
      updateSelectizeInput(session, "diffGroup1", choices = values$unique_groups, selected = values$unique_groups[1])
      updateSelectizeInput(session, "diffGroup2", choices = values$unique_groups,
                           selected = if(length(values$unique_groups) > 1) values$unique_groups[2] else values$unique_groups[1])
      
      # Invalidate caches to clear any previous analysis outputs
      values$pca_cache <- list()
      values$spca_cache <- list()
      values$processing_cache <- list()
      values$statistical_cache <- list()
      
      # Close the modal dialog
      removeModal()
      
      # Notify user
      showNotification(
        paste0("Analysis '", analysis_obj$name, "' loaded successfully! Omics type: ",
               analysis_obj$omics_type, " | ", analysis_obj$n_features, " features, ",
               analysis_obj$n_samples, " samples"),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(
        paste("Error loading analysis:", e$message),
        type = "error",
        duration = 10
      )
    })
  })
  
  # LOAD EXISTING ANALYSIS FROM SAVED LIST
  # Handle loading analysis from saved list
  observe({
    saved_analyses$counter  # Trigger when analyses list changes
    
    lapply(names(saved_analyses$analyses_list), function(name) {
      load_button_id <- paste0("load_analysis_", gsub("[^[:alnum:]]", "_", name))
      
      observeEvent(input[[load_button_id]], {
        tryCatch({
          # Get analysis from saved list
          analysis_obj <- saved_analyses$analyses_list[[name]]
          
          # Clear current analysis to fully replace it
          values$analysis_has_run <- FALSE
          
          # Load data into values
          # Set original unfiltered data (this is the raw data before any processing)
          values$original_unfiltered_data <- analysis_obj$original_unfiltered_data %||% analysis_obj$raw_data
          values$raw_data <- analysis_obj$raw_data
          values$normalized_data <- analysis_obj$normalized_data
          
          # Set cleaned molecules (feature names from normalized data)
          values$cleaned_molecules <- analysis_obj$cleaned_molecules %||% rownames(analysis_obj$normalized_data)
          
          # Set corrected sample names from the loaded data's column names
          values$corrected_sample_names <- colnames(analysis_obj$normalized_data)
          
          # Restore accession IDs if available
          if (!is.null(analysis_obj$accession_ids)) {
            values$accession_ids <- analysis_obj$accession_ids
          }
          if (!is.null(analysis_obj$accession_id_column)) {
            values$accession_id_column <- analysis_obj$accession_id_column
          }
          
          values$unique_groups <- analysis_obj$groups
          values$group_column_indices <- analysis_obj$group_indices
          
          # Restore statistical results
          if (!is.null(analysis_obj$stat_results)) {
            values$stat_results <- analysis_obj$stat_results
          }
          if (!is.null(analysis_obj$comparison_results)) {
            values$comparison_results <- analysis_obj$comparison_results
          }
          if (!is.null(analysis_obj$significant_features)) {
            values$significant_features <- analysis_obj$significant_features
          }
          
          # Display raw and normalized data tables with fade transition from splash image
          shinyjs::delay(50, {
            shinyjs::addClass(id = "rawDataSplash", class = "fade-out")
            shinyjs::addClass(id = "rawDataTableWrapper", class = "fade-in")
          })
          
          # Force refresh of both data tables to display loaded data
          # Trigger reactive dependencies to force re-rendering of tables
          shinyjs::delay(200, {
            tryCatch({
              proxy_raw <- DT::dataTableProxy("rawDataTable")
              DT::reloadData(proxy_raw, resetPaging = TRUE)
            }, error = function(e) { NULL })
          })
          
          # Force normalized data table to re-render by triggering its reactive dependencies
          shinyjs::delay(250, {
            isolate({
              # Force re-execution of the observe() that updates normalizedDataTable
              temp_data <- values$normalized_data
              values$normalized_data <- NULL
              values$normalized_data <- temp_data
            })
          })
          
          # Mark that analysis has been loaded and run
          values$analysis_has_run <- TRUE
          
          # Update UI inputs from saved parameters
          updateSelectInput(session, "norm_method", selected = analysis_obj$normalization_method)
          updateSelectInput(session, "sig_method", selected = analysis_obj$statistical_method)
          updateSelectInput(session, "impute_method", selected = analysis_obj$imputation_method)
          
          # Restore all UI settings if available
          if (!is.null(analysis_obj$ui_settings)) {
            settings <- analysis_obj$ui_settings
            
            # Data Input Settings
            if (!is.null(settings$data_samples_are_rows)) updateCheckboxInput(session, "data_samples_are_rows", value = settings$data_samples_are_rows)
            if (!is.null(settings$data_treat_zeros_as_na)) updateCheckboxInput(session, "data_treat_zeros_as_na", value = settings$data_treat_zeros_as_na)
            if (!is.null(settings$enable_custom_na)) updateCheckboxInput(session, "enable_custom_na", value = settings$enable_custom_na)
            if (!is.null(settings$custom_na_values)) updateTextInput(session, "custom_na_values", value = settings$custom_na_values)
            if (!is.null(settings$clean_feature_ids)) updateCheckboxInput(session, "clean_feature_ids", value = settings$clean_feature_ids)
            
            # Missing Value Handling
            if (!is.null(settings$missing_value_strategy)) updateRadioButtons(session, "missing_value_strategy", selected = settings$missing_value_strategy)
            if (!is.null(settings$na_threshold)) updateNumericInput(session, "na_threshold", value = settings$na_threshold)
            if (!is.null(settings$check_within_groups)) updateCheckboxInput(session, "check_within_groups", value = settings$check_within_groups)
            if (!is.null(settings$filter_before_impute)) updateCheckboxInput(session, "filter_before_impute", value = settings$filter_before_impute)
            if (!is.null(settings$impute_na_threshold)) updateNumericInput(session, "impute_na_threshold", value = settings$impute_na_threshold)
            if (!is.null(settings$impute_check_within_groups)) updateCheckboxInput(session, "impute_check_within_groups", value = settings$impute_check_within_groups)
            if (!is.null(settings$imputation_method)) updateSelectInput(session, "imputation_method", selected = settings$imputation_method)
            
            # Normalization Settings
            if (!is.null(settings$norm_method)) updateSelectInput(session, "norm_method", selected = settings$norm_method)
            if (!is.null(settings$log2_norm_timing)) {
              updateRadioButtons(session, "log2_norm_timing", selected = settings$log2_norm_timing)
            } else if (!is.null(settings$log2_before_norm) || !is.null(settings$log2_after_norm)) {
              legacy_timing <- if (isTRUE(settings$log2_before_norm)) "before" else if (isTRUE(settings$log2_after_norm)) "after" else "none"
              updateRadioButtons(session, "log2_norm_timing", selected = legacy_timing)
            }
            if (!is.null(settings$sum_norm_percentage)) updateCheckboxInput(session, "sum_norm_percentage", value = settings$sum_norm_percentage)
            
            # Batch Correction Settings
            if (!is.null(settings$batch_correction_enabled)) updateRadioButtons(session, "batch_correction_enabled", selected = settings$batch_correction_enabled)
            if (!is.null(settings$batch_correction_method)) updateSelectInput(session, "batch_correction_method", selected = settings$batch_correction_method)
            if (!is.null(settings$batch_column)) updateSelectInput(session, "batch_column", selected = settings$batch_column)
            if (!is.null(settings$group_column)) updateSelectInput(session, "group_column", selected = settings$group_column)
            if (!is.null(settings$viz_batch_enable)) updateCheckboxInput(session, "viz_batch_enable", value = settings$viz_batch_enable)
            if (!is.null(settings$viz_batch_method)) updateSelectInput(session, "viz_batch_method", selected = settings$viz_batch_method)
            
            # Statistical Testing Settings
            if (!is.null(settings$sig_method)) updateSelectInput(session, "sig_method", selected = settings$sig_method)
            if (!is.null(settings$rots_B)) updateNumericInput(session, "rots_B", value = settings$rots_B)
            if (!is.null(settings$rots_K)) updateNumericInput(session, "rots_K", value = settings$rots_K)
            if (!is.null(settings$rots_seed)) updateNumericInput(session, "rots_seed", value = settings$rots_seed)
            if (!is.null(settings$rots_parallel)) updateCheckboxInput(session, "rots_parallel", value = settings$rots_parallel)
            if (!is.null(settings$rots_cores)) updateNumericInput(session, "rots_cores", value = settings$rots_cores)
            if (!is.null(settings$deseq2_test)) updateSelectInput(session, "deseq2_test", selected = settings$deseq2_test)
            if (!is.null(settings$deseq2_fitType)) updateSelectInput(session, "deseq2_fitType", selected = settings$deseq2_fitType)
            if (!is.null(settings$deseq2_alpha)) updateNumericInput(session, "deseq2_alpha", value = settings$deseq2_alpha)
            if (!is.null(settings$deseq2_independent_filtering)) updateCheckboxInput(session, "deseq2_independent_filtering", value = settings$deseq2_independent_filtering)
            if (!is.null(settings$deseq2_cooksCutoff)) updateCheckboxInput(session, "deseq2_cooksCutoff", value = settings$deseq2_cooksCutoff)
            if (!is.null(settings$deseq2_transform)) updateSelectInput(session, "deseq2_transform", selected = settings$deseq2_transform)
            if (!is.null(settings$limma_voom_norm_method)) updateSelectInput(session, "limma_voom_norm_method", selected = settings$limma_voom_norm_method)
            if (!is.null(settings$limma_voom_trend)) updateCheckboxInput(session, "limma_voom_trend", value = settings$limma_voom_trend)
            if (!is.null(settings$limma_voom_robust)) updateCheckboxInput(session, "limma_voom_robust", value = settings$limma_voom_robust)
          }
          
          # Invalidate caches to clear any previous analysis outputs
          values$pca_cache <- list()
          values$spca_cache <- list()
          values$processing_cache <- list()
          values$statistical_cache <- list()
          
          # Close the save modal
          removeModal()
          
          # Notify user
          showNotification(
            paste0("Analysis '", analysis_obj$name, "' loaded successfully! Omics type: ",
                   analysis_obj$omics_type, " | ", analysis_obj$n_features, " features, ",
                   analysis_obj$n_samples, " samples"),
            type = "message",
            duration = 5
          )
          
        }, error = function(e) {
          showNotification(
            paste("Error loading analysis:", e$message),
            type = "error",
            duration = 10
          )
        })
      })
    })
  })
  
  # Render Save Analysis card UI - DEPRECATED: Now shown as modal via header button
  # Kept for backwards compatibility but returns NULL
  output$save_analysis_card_ui <- renderUI({
    return(NULL)
  })
  
  
  # Display saved analyses list in Data tab
  output$saved_analyses_list <- renderUI({
    # Trigger on counter change
    saved_analyses$counter
    
    if (length(saved_analyses$analyses_list) == 0) {
      return(div(style = "color: #6c757d; font-style: italic; padding: 10px;",
                 "No saved analyses yet."))
    }
    
    # Create list of saved analyses
    analyses_items <- lapply(names(saved_analyses$analyses_list), function(name) {
      analysis <- saved_analyses$analyses_list[[name]]
      safe_name <- gsub("[^[:alnum:]]", "_", name)
      
      div(
        style = "background: #f8f9fa; border-left: 3px solid #667eea; padding: 10px; margin-bottom: 10px; border-radius: 4px;",
        div(style = "display: flex; justify-content: space-between; align-items: flex-start; gap: 10px;",
            div(
              strong(name),
              br(),
              tags$small(
                style = "color: #6c757d;",
                icon("database"), " ", analysis$omics_type,
                " | ",
                icon("vial"), " ", analysis$n_features, " features",
                br(),
                icon("users"), " ", analysis$n_samples, " samples",
                " | ",
                format(analysis$timestamp, "%Y-%m-%d %H:%M")
              ),
              style = "flex: 1;"
            ),
            div(
              style = "display: flex; gap: 4px; flex-wrap: wrap; justify-content: flex-end;",
              downloadButton(
                paste0("download_analysis_", safe_name),
                label = NULL,
                icon = icon("download"),
                class = "btn-sm btn-info",
                title = "Download as .oms",
                style = "padding: 4px 8px; font-size: 12px;"
              ),
              actionButton(
                paste0("load_analysis_", safe_name),
                label = NULL,
                icon = icon("upload"),
                class = "btn-sm btn-primary",
                title = "Load analysis",
                style = "padding: 4px 8px; font-size: 12px;"
              ),
              actionButton(
                paste0("delete_analysis_", safe_name),
                label = NULL,
                icon = icon("trash"),
                class = "btn-sm btn-danger",
                style = "padding: 4px 8px; font-size: 12px;"
              )
            )
        )
      )
    })
    
    tagList(analyses_items)
  })
  
  # Handle delete analysis buttons
  observe({
    saved_analyses$counter  # Trigger on changes
    
    lapply(names(saved_analyses$analyses_list), function(name) {
      button_id <- paste0("delete_analysis_", gsub("[^[:alnum:]]", "_", name))
      
      observeEvent(input[[button_id]], {
        showModal(modalDialog(
          title = "Delete Analysis",
          p(paste0("Are you sure you want to delete '", name, "'?")),
          footer = tagList(
            modalButton("Cancel"),
            actionButton(paste0("confirm_delete_", gsub("[^[:alnum:]]", "_", name)),
                         "Delete",
                         class = "btn-danger")
          )
        ))
      })
      
      observeEvent(input[[paste0("confirm_delete_", gsub("[^[:alnum:]]", "_", name))]], {
        saved_analyses$analyses_list[[name]] <- NULL
        saved_analyses$counter <- saved_analyses$counter + 1
        removeModal()
        showNotification(paste0("Analysis '", name, "' deleted."), type = "message")
      })
    })
  })
  
  # Display available saved analyses in Multi-Omics tab
  output$available_saved_analyses_ui <- renderUI({
    # Trigger on counter change
    saved_analyses$counter
    
    if (length(saved_analyses$analyses_list) == 0) {
      return(div(
        style = "color: #6c757d; font-style: italic; padding: 10px; background: #f8f9fa; border-radius: 4px;",
        icon("info-circle"),
        " No saved analyses available. Save an analysis in the Data tab first."
      ))
    }
    
    # Create checkboxes for each saved analysis
    analyses_checkboxes <- lapply(names(saved_analyses$analyses_list), function(name) {
      analysis <- saved_analyses$analyses_list[[name]]
      
      div(
        style = "background: white; border: 1px solid #dee2e6; padding: 10px; margin-bottom: 8px; border-radius: 6px; border-left: 3px solid #667eea;",
        checkboxInput(
          paste0("select_analysis_", gsub("[^[:alnum:]]", "_", name)),
          label = div(
            strong(name),
            br(),
            tags$small(
              style = "color: #6c757d;",
              icon("database"), " ", analysis$omics_type,
              " | ",
              icon("vial"), " ", analysis$n_features, " features",
              " | ",
              icon("users"), " ", analysis$n_samples, " samples"
            )
          ),
          value = FALSE,
          width = "100%"
        )
      )
    })
    
    tagList(analyses_checkboxes)
  })
  
  # Load selected analyses into multi-omics integration
  observeEvent(input$load_selected_analyses, {
    # Get selected analyses
    selected <- c()
    
    for (name in names(saved_analyses$analyses_list)) {
      checkbox_id <- paste0("select_analysis_", gsub("[^[:alnum:]]", "_", name))
      if (!is.null(input[[checkbox_id]]) && input[[checkbox_id]]) {
        selected <- c(selected, name)
      }
    }
    
    if (length(selected) == 0) {
      showNotification("Please select at least one analysis to load", type = "warning")
      return()
    }

    # Allow mixing analyses already loaded from .oms with a single session analysis
    already_loaded <- names(multiomics$loaded_analyses)
    selected_new <- setdiff(selected, already_loaded)
    total_after <- length(already_loaded) + length(selected_new)
    if (total_after < 2) {
      showNotification(
        "Please have at least 2 total loaded analyses (session + file) for multi-omics integration",
        type = "warning"
      )
      return()
    }
    
    # Load selected analyses
    tryCatch({
      newly_loaded <- list()
      for (name in selected_new) {
        analysis <- saved_analyses$analyses_list[[name]]
        newly_loaded[[name]] <- list(
          data = analysis$normalized_data,
          samples = analysis$samples,
          features = analysis$features,
          cleaned_molecules = analysis$cleaned_molecules %||% NULL,
          accession_ids = analysis$accession_ids %||% NULL,
          omics_type = analysis$omics_type,
          groups = analysis$groups,
          group_indices = analysis$group_indices,
          metadata = analysis$metadata
        )
      }

      # Merge into existing loaded_analyses instead of overwriting
      if (length(newly_loaded) > 0) {
        multiomics$loaded_analyses <- c(multiomics$loaded_analyses, newly_loaded)
      }

      # Recompute common samples and metadata across ALL loaded analyses
      recompute_loaded_analyses_state()

      if (length(multiomics$loaded_analyses) > 1 && is.null(multiomics$common_samples)) {
        showNotification(
          "No common samples found across loaded analyses. N-integration requires matching sample IDs.",
          type = "error",
          duration = 10
        )
        return()
      }
      
      showNotification(
        paste0(length(selected_new), " analysis(analyses) added. Total loaded: ",
               length(multiomics$loaded_analyses),
               if (!is.null(multiomics$common_samples)) paste0(". ", length(multiomics$common_samples), " common samples identified.") else "."),
        type = "message",
        duration = 5
      )
      
    }, error = function(e) {
      showNotification(
        paste("Error loading analyses:", e$message),
        type = "error",
        duration = 10
      )
    })
  })
  
  # Load OMS / CSV / XLSX files from disk (supports multiple uploads and optional metadata files)
  observeEvent(input$oms_file_upload, {
    req(input$oms_file_upload)

    files <- input$oms_file_upload
    if (is.null(files) || nrow(files) == 0) return()

    # Ensure storage for any external metadata files
    if (is.null(multiomics$external_metadata)) multiomics$external_metadata <- list()

    tryCatch({
      files_processed <- 0
      files_added <- 0

      for (i in seq_len(nrow(files))) {
        fpath <- files$datapath[i]
        fname <- files$name[i]
        fext <- tolower(tools::file_ext(fname))

        # Handle .oms files (existing behavior)
        if (fext == "oms") {
          analysis_obj <- readRDS(fpath)
          
          # ===== CHECK IF THIS IS AN ENRICHMENT FILE =====
          if (!is.null(analysis_obj$type) && analysis_obj$type == "enrichment") {
            enr_name <- analysis_obj$name
            if (is.null(enr_name) || nchar(trimws(enr_name)) == 0) {
              enr_name <- tools::file_path_sans_ext(fname)
            }
            
            if (enr_name %in% names(multiomics$loaded_enrichments)) {
              showNotification(
                paste0("Enrichment '", enr_name, "' is already loaded."),
                type = "warning",
                duration = 5
              )
              next
            }
            
            # Store in loaded_enrichments for pathway integration
            analysis_obj$name <- enr_name
            multiomics$loaded_enrichments[[enr_name]] <- analysis_obj
            
            showNotification(
              paste0("Enrichment '", enr_name, "' loaded for Pathway Integration!"),
              type = "message",
              duration = 3
            )
            
            files_processed <- files_processed + 1
            files_added <- files_added + 1
            next
          }

          # Validate required fields for regular analysis files
          req_fields <- c("name", "omics_type", "normalized_data", "samples", "features",
                          "groups", "group_indices")
          missing_fields <- setdiff(req_fields, names(analysis_obj))

          if (length(missing_fields) > 0) {
            showNotification(
              paste("Invalid .oms file.", fname, "Missing fields:", paste(missing_fields, collapse = ", ")),
              type = "error",
              duration = 10
            )
            next
          }

          analysis_name <- analysis_obj$name
          if (is.null(analysis_name) || analysis_name == "") {
            analysis_name <- tools::file_path_sans_ext(fname)
          }

          if (analysis_name %in% names(multiomics$loaded_analyses)) {
            showNotification(
              paste0("Analysis '", analysis_name, "' is already loaded."),
              type = "warning",
              duration = 5
            )
            next
          }

          multiomics$loaded_analyses[[analysis_name]] <- list(
            data = analysis_obj$normalized_data,
            samples = analysis_obj$samples,
            features = analysis_obj$features,
            cleaned_molecules = analysis_obj$cleaned_molecules %||% NULL,
            accession_ids = analysis_obj$accession_ids %||% NULL,
            omics_type = analysis_obj$omics_type,
            groups = analysis_obj$groups,
            group_indices = analysis_obj$group_indices,
            metadata = analysis_obj$metadata %||% list()
          )

          files_processed <- files_processed + 1
          files_added <- files_added + 1
          next
        }

        # Handle table files (CSV/TSV/XLSX/XLS)
        if (fext %in% c("csv", "tsv", "txt", "xls", "xlsx")) {
          res <- tryCatch({ parse_table_file(fpath, fname) }, error = function(e) { showNotification(paste("Failed to parse", fname, ":", e$message), type = "error", duration = 10); NULL })
          if (is.null(res)) next

          if (isTRUE(res$is_metadata)) {
            # Store the external metadata by base filename
            meta_key <- tools::file_path_sans_ext(fname)
            multiomics$external_metadata[[meta_key]] <- res$metadata

            # Also create a lightweight 'loaded analysis' entry so the metadata file
            # appears in the Loaded Analyses list and can be designated as the metadata source
            # Use the base filename and ensure the name is unique
            analysis_base <- meta_key
            analysis_name <- analysis_base
            counter <- 1
            while (analysis_name %in% names(multiomics$loaded_analyses)) {
              analysis_name <- paste0(analysis_base, "_", counter)
              counter <- counter + 1
            }

            # Determine sample IDs from the parsed metadata (prefer explicit SampleID column)
            # Normalize: trim whitespace and ensure consistent naming
            samples_vec <- NULL
            if ("SampleID" %in% colnames(res$metadata)) {
              samples_vec <- trimws(as.character(res$metadata$SampleID))
            } else if (!is.null(rownames(res$metadata))) {
              samples_vec <- trimws(as.character(rownames(res$metadata)))
            } else {
              samples_vec <- character(0)
            }

            multiomics$loaded_analyses[[analysis_name]] <- list(
              data = NULL,
              samples = samples_vec,
              features = 0,
              cleaned_molecules = NULL,
              accession_ids = NULL,
              omics_type = "metadata",
              groups = NULL,
              group_indices = NULL,
              metadata = res$metadata
            )

            # Make this new entry the designated metadata by default (user can uncheck later)
            multiomics$designated_metadata <- analysis_name

            files_processed <- files_processed + 1
            files_added <- files_added + 1
            next
          }

          data_mat <- res$data
          samples <- trimws(res$samples)  # Normalize sample names from data files
          features <- res$features

          # Build analysis entry
          analysis_name <- tools::file_path_sans_ext(fname)
          # Ensure unique name
          base_name <- analysis_name
          counter <- 1
          while (analysis_name %in% names(multiomics$loaded_analyses)) {
            analysis_name <- paste0(base_name, "_", counter)
            counter <- counter + 1
          }

          multiomics$loaded_analyses[[analysis_name]] <- list(
            data = data_mat,
            samples = samples,
            features = features,
            cleaned_molecules = NULL,
            accession_ids = NULL,
            omics_type = analysis_name,
            groups = NULL,
            group_indices = NULL,
            metadata = list()
          )

          files_processed <- files_processed + 1
          files_added <- files_added + 1
          next
        }

        # Unsupported file type
        showNotification(paste("Unsupported file type:", fname), type = "warning", duration = 8)
      }

      # If any external metadata files were provided, merge them and apply to sample metadata
      if (length(multiomics$external_metadata) > 0) {
        meta_list <- multiomics$external_metadata
        combined_meta <- meta_list[[1]]
        if (length(meta_list) > 1) {
          for (j in 2:length(meta_list)) {
            combined_meta <- merge(combined_meta, meta_list[[j]], by = "SampleID", all = TRUE)
          }
        }

        # Keep combined external metadata available for merging
        multiomics$external_metadata_combined <- combined_meta
      }

      # Recompute sample overlap / combined metadata
      recompute_loaded_analyses_state()

      # If we have external metadata, make it available for MOFA regardless of loaded analyses
      if (!is.null(multiomics$external_metadata_combined)) {
        mm <- multiomics$external_metadata_combined
        if ("SampleID" %in% names(mm)) {
          rownames(mm) <- as.character(mm$SampleID)
          mm$SampleID <- NULL

          # If we have common samples from loaded analyses, filter to those
          if (!is.null(multiomics$common_samples)) {
            mm <- mm[intersect(rownames(mm), multiomics$common_samples), , drop = FALSE]
          }

          if (!is.null(multiomics$sample_metadata)) {
            # merge keeping existing sample metadata columns preserved
            ex_meta_df <- data.frame(SampleID = rownames(mm), mm, stringsAsFactors = FALSE)
            existing_df <- data.frame(SampleID = rownames(multiomics$sample_metadata), multiomics$sample_metadata, stringsAsFactors = FALSE)
            merged_df <- merge(existing_df, ex_meta_df, by = "SampleID", all = TRUE)
            rownames(merged_df) <- merged_df$SampleID; merged_df$SampleID <- NULL
            multiomics$sample_metadata <- merged_df
          } else {
            # No loaded analyses, but we have external metadata - use it directly
            multiomics$sample_metadata <- mm
          }
        }
      }

      if (files_added > 0) {
        showNotification(paste0(files_added, " file(s) imported."), type = "message", duration = 5)
      } else if (files_processed > 0) {
        showNotification("Files processed.", type = "message", duration = 4)
      }

      # Reset input
      shinyjs::reset("oms_file_upload")

    }, error = function(e) {
      showNotification(paste("Error loading files:", e$message), type = "error", duration = 10)
    })
  })
  
  # Display loaded analyses summary
  output$loaded_analyses_list <- renderUI({
    if (length(multiomics$loaded_analyses) == 0 && length(multiomics$loaded_enrichments) == 0) {
      return(div(
        style = "color: #6c757d; font-style: italic; padding: 10px;",
        "No analyses loaded yet."
      ))
    }
    
    # Create summary cards for loaded analyses
    loaded_items <- lapply(names(multiomics$loaded_analyses), function(name) {
      analysis <- multiomics$loaded_analyses[[name]]
      
      # Check if this analysis has mismatched samples
      is_mismatched <- !is.null(multiomics$common_samples) &&
        length(setdiff(analysis$samples, multiomics$common_samples)) > 0
      
      # Determine border color based on match status
      border_color <- if (is_mismatched) "#ef4444" else "#10b981"
      circle_color <- if (is_mismatched) "#dc2626" else "#10b981"
      circle_icon <- if (is_mismatched) "exclamation-triangle" else "check-circle"
      
      div(
        class = "loaded-analysis-card",
        style = paste0("background: linear-gradient(135deg, #f0f4ff 0%, white 100%); border-left: 3px solid ",
                       border_color, "; padding: 10px; margin-bottom: 8px; border-radius: 6px; position: relative;"),
        div(
          strong(icon(circle_icon, style = paste0("color: ", circle_color, ";")), " ", name),
          br(),
          tags$small(
            style = "color: #6c757d;",
            icon("database"), " ", analysis$omics_type,
            br(),
            icon("vial"), " ", length(analysis$features), " features",
            " | ",
            icon("users"), " ", length(analysis$samples), " samples",
            if (is_mismatched) {
              list(br(), tags$span(
                style = "color: #dc2626; font-weight: bold;",
                icon("warning"), " Sample mismatch detected"
              ))
            } else NULL,
            # Show metadata badge if this is the designated metadata file
            if (identical(multiomics$designated_metadata, name)) {
              list(br(), tags$span(
                style = "color: #059669; font-weight: 600;",
                icon("check-circle"), " Metadata source"
              ))
            } else NULL
          )
        ),
        # Delete button (positioned absolutely in top-right corner)
        tags$button(
          type = "button",
          title = "Delete this analysis",
          class = "loaded-analysis-delete-btn",
          onclick = sprintf(
            "Shiny.setInputValue('loaded_analysis_delete_request', %s, {priority: 'event'});",
            jsonlite::toJSON(name, auto_unbox = TRUE)
          ),
          icon("trash")
        )
      )
    })
    
    # Add common samples info
    if (!is.null(multiomics$common_samples)) {
      common_info <- div(
        style = "background: #d1fae5; border: 1px solid #10b981; padding: 10px; margin-top: 10px; border-radius: 6px;",
        strong(icon("link"), " Common Samples: ", length(multiomics$common_samples)),
        br(),
        tags$small(
          style = "color: #065f46;",
          "Ready for N-integration analysis"
        )
      )
      loaded_items <- c(loaded_items, list(common_info))
    }
    
    # Add enrichment files summary
    if (length(multiomics$loaded_enrichments) > 0) {
      count_enrichment_terms <- function(enr) {
        tryCatch({
          if (!is.null(enr$results$table) && (is.data.frame(enr$results$table) || is.matrix(enr$results$table))) {
            nrow(enr$results$table)
          } else if (!is.null(enr$results$result) && (is.data.frame(enr$results$result) || is.matrix(enr$results$result))) {
            nrow(enr$results$result)
          } else if (!is.null(enr$results$results) && (is.data.frame(enr$results$results) || is.matrix(enr$results$results))) {
            nrow(enr$results$results)
          } else if (!is.null(enr$results) && (is.data.frame(enr$results) || is.matrix(enr$results))) {
            nrow(enr$results)
          } else if (!is.null(enr$results) && (inherits(enr$results, "enrichResult") || inherits(enr$results, "gseaResult"))) {
            nrow(as.data.frame(enr$results))
          } else if (!is.null(enr$results) && is.list(enr$results)) {
            sum(vapply(enr$results, function(x) {
              if (is.data.frame(x) || is.matrix(x)) nrow(x)
              else if (inherits(x, "enrichResult") || inherits(x, "gseaResult")) nrow(as.data.frame(x))
              else if (!is.null(x$table) && (is.data.frame(x$table) || is.matrix(x$table))) nrow(x$table)
              else if (!is.null(x$result) && (is.data.frame(x$result) || is.matrix(x$result))) nrow(x$result)
              else if (!is.null(x$results) && (is.data.frame(x$results) || is.matrix(x$results))) nrow(x$results)
              else 0L
            }, integer(1)))
          } else {
            0L
          }
        }, error = function(e) 0L)
      }
      
      enrichment_header <- div(
        style = "margin-top: 10px; font-weight: 600; color: #374151;",
        icon("route"), " Loaded Enrichment Files"
      )
      
      enrichment_items <- lapply(names(multiomics$loaded_enrichments), function(name) {
        enr <- multiomics$loaded_enrichments[[name]]
        n_terms <- count_enrichment_terms(enr)
        div(
          class = "loaded-analysis-card",
          style = paste0("background: #f8f9fa; border-left: 3px solid #22c55e; padding: 10px; margin-bottom: 8px; border-radius: 6px; position: relative;"),
          div(
            strong(icon("check-circle", style = "color: #16a34a;"), " ", name),
            br(),
            tags$small(
              style = "color: #6c757d;",
              icon("vial"), " ", enr$omics_type %||% "unknown",
              " | ",
              icon("tools"), " ", enr$tool %||% "unknown",
              " | ",
              n_terms, " terms"
            )
          )
        )
      })
      
      loaded_items <- c(loaded_items, list(enrichment_header), enrichment_items)
    }
    
    tagList(loaded_items)
  })

  # NOTE: Metadata checkbox observer removed - metadata is now auto-detected by filename pattern
  # Files with 'metadata', 'meta_data', 'sample_info', etc. in the filename are automatically
  # designated as the metadata source

  # Loaded Analyses deletion (immediate upon delete icon click)
  observeEvent(input$loaded_analysis_delete_request, {
    req(input$loaded_analysis_delete_request)
    current_name <- input$loaded_analysis_delete_request
    if (is.null(current_name) || !nzchar(current_name) || !(current_name %in% names(multiomics$loaded_analyses))) {
      return(NULL)
    }

    # Remove the analysis from loaded_analyses
    multiomics$loaded_analyses[[current_name]] <- NULL

    # Also remove external metadata entries so recompute doesn't re-add them
    if (!is.null(multiomics$external_metadata) && current_name %in% names(multiomics$external_metadata)) {
      multiomics$external_metadata[[current_name]] <- NULL
    }

    # If it was designated as metadata, reset
    if (identical(multiomics$designated_metadata, current_name)) {
      multiomics$designated_metadata <- NULL
    }

    # Recompute common samples and metadata across ALL loaded analyses
    recompute_loaded_analyses_state()

    if (length(multiomics$loaded_analyses) == 0) {
      multiomics$loaded_analyses <- list()
    }

    showNotification(
      paste0("Analysis '", current_name, "' has been removed."),
      type = "message",
      duration = 5
    )
  }, ignoreInit = TRUE)
  
  
  # ==============================================================================
  # END SAVE/LOAD ANALYSIS FUNCTIONALITY
  # ==============================================================================
  
  # MULTI-OMICS INTEGRATION SERVER CODE
  # ==============================================================================
  
  # (multiomics/saved_analyses/mofa_metadata are initialized near top of server())
  
  # ============================================================================
  # MOFA METADATA FILE PARSING
  # ============================================================================
  # Helper: refresh groups/covariates based on selected columns
  refresh_mofa_metadata_from_selected_columns <- function() {
    req(mofa_metadata$full_metadata)

    md <- mofa_metadata$full_metadata
    sample_col_name <- input$mofa_sample_id_col %||% mofa_metadata$sample_col_name %||% "SampleID"
    if (!(sample_col_name %in% colnames(md))) {
      # Fallback: try to match case-insensitive sample column names
      candidate <- grep("sample", colnames(md), ignore.case = TRUE, value = TRUE)
      if (length(candidate) > 0) {
        sample_col_name <- candidate[1]
      }
    }

    sample_ids <- if (!is.null(sample_col_name) && sample_col_name %in% colnames(md)) {
      as.character(md[[sample_col_name]])
    } else if (!is.null(mofa_metadata$data) && nrow(mofa_metadata$data) > 0) {
      as.character(mofa_metadata$data$SampleID)
    } else if (!is.null(rownames(md))) {
      as.character(rownames(md))
    } else {
      character(0)
    }

    if (length(sample_ids) == 0) {
      showNotification("MOFA metadata: Unable to determine Sample IDs; please select a valid Sample ID column.", type = "error", duration = 8)
      return()
    }

    group_col <- input$mofa_group_col %||% ""
    if (identical(group_col, "")) group_col <- NA_character_
    group_values <- if (!is.na(group_col) && group_col %in% colnames(md)) as.character(md[[group_col]]) else NULL

    mofa_metadata$group_col_name <- if (!is.na(group_col)) group_col else NA_character_
    mofa_metadata$group_values <- group_values

    metadata_table <- data.frame(SampleID = sample_ids, stringsAsFactors = FALSE)
    if (!is.null(group_values) && length(group_values) == nrow(metadata_table) && !is.na(group_col)) {
      metadata_table[[group_col]] <- group_values
    }
    mofa_metadata$data <- metadata_table

    # Exclude SampleID and analysis-derived group columns ("*_Group") from covariates by default.
    # If the selected grouping column is a deduced analysis-derived column (ends with "_Group"),
    # do not include it as a covariate. If the selected grouping column is a non-deduced column
    # (e.g., from uploaded metadata), keep it among covariates so users can use it in association tests.
    excluded <- unique(c(sample_col_name))
    group_suffix_cols <- grep("_Group$", colnames(md), value = TRUE)
    if (!is.na(group_col) && group_col %in% colnames(md)) {
      # Keep selected group only if it is NOT an analysis-derived (_Group) column
      if (!grepl("_Group$", group_col)) {
        group_suffix_cols <- setdiff(group_suffix_cols, group_col)
      }
    }
    excluded <- unique(c(excluded, group_suffix_cols))
    excluded <- excluded[!is.na(excluded) & nzchar(excluded)]
    covariate_cols <- setdiff(colnames(md), excluded)

    covariate_types <- setNames(rep("unknown", length(covariate_cols)), covariate_cols)
    for (col in covariate_cols) {
      col_data <- md[[col]]
      numeric_test <- suppressWarnings(as.numeric(col_data))
      if (length(col_data) > 0 && sum(!is.na(numeric_test)) / length(col_data) > 0.8) {
        covariate_types[col] <- "numeric"
      } else {
        covariate_types[col] <- "categorical"
      }
    }

    mofa_metadata$covariates <- if (length(covariate_cols) > 0) md[covariate_cols] else NULL
    # Ensure covariates can be joined/indexed by sample ID (avoid tibbles + length mismatch)
    if (!is.null(mofa_metadata$covariates)) {
      sample_ids <- as.character(md[[sample_col_name]])
      cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)

      if (length(sample_ids) == nrow(cov_df)) {
        if (any(is.na(sample_ids) | !nzchar(sample_ids))) {
          showNotification("MOFA metadata: Some Sample IDs are missing/blank; covariate alignment may fail.", type = "warning", duration = 6)
        }
        if (any(duplicated(sample_ids))) {
          showNotification("MOFA metadata: Duplicate Sample IDs detected; covariate alignment uses first match.", type = "warning", duration = 6)
          # Leave duplicate sample IDs as-is; first match will be used when aligning covariates
        }
        rownames(cov_df) <- sample_ids
        mofa_metadata$covariates <- cov_df
      } else {
        showNotification(
          paste0("MOFA metadata: Cannot align covariates to SampleID (length mismatch: ",
                 length(sample_ids), " SampleIDs vs ", nrow(cov_df), " rows)."),
          type = "warning",
          duration = 8
        )
        mofa_metadata$covariates <- cov_df
      }
    }
    mofa_metadata$covariate_names <- covariate_cols
    mofa_metadata$covariate_types <- covariate_types

    if (length(covariate_cols) > 0) {
      # Keep the covariate picker clean: show original covariate values but display friendly labels (dots -> spaces)
      display_cov_names <- gsub("\\.", " ", covariate_cols)
      updateCheckboxGroupInput(session, "assoc_covariates",
                               choices = setNames(covariate_cols, display_cov_names),
                               selected = covariate_cols)
    }
  }



  observeEvent(list(input$mofa_sample_id_col, input$mofa_group_col), {
    req(mofa_metadata$full_metadata)
    refresh_mofa_metadata_from_selected_columns()
  }, ignoreInit = TRUE)

  output$mofa_metadata_column_select_ui <- renderUI({
    # Determine which metadata to display/use for column selection:
    # 1) MOFA-specific full_metadata
    # 2) Combined sample metadata from loaded analyses
    # 3) Combined external metadata uploads
    md <- NULL

    if (!is.null(mofa_metadata$full_metadata) && length(colnames(mofa_metadata$full_metadata)) > 0) {
      md <- mofa_metadata$full_metadata
    } else if (!is.null(multiomics$sample_metadata) && nrow(multiomics$sample_metadata) > 0) {
      md <- multiomics$sample_metadata
      # Ensure a SampleID column exists for consistent downstream handling
      if (!"SampleID" %in% colnames(md) && !is.null(rownames(md))) md$SampleID <- rownames(md)
    } else if (!is.null(multiomics$external_metadata_combined) && nrow(multiomics$external_metadata_combined) > 0) {
      md <- multiomics$external_metadata_combined
      if (!"SampleID" %in% colnames(md) && !is.null(rownames(md))) md$SampleID <- rownames(md)
    }

    # If no metadata is available from any of the sources, show informative message
    if (is.null(md) || length(colnames(md)) == 0) {
      return(
        div(style = "margin-top: 10px; padding: 10px; background: #fff3cd; border-radius: 6px; border-left: 3px solid #ffc107;",
            icon("exclamation-triangle", style = "color: #856404;"),
            span(style = "margin-left: 8px; color: #856404;",
                 "No sample metadata available. Load analyses from the Multi-Omics tab or upload metadata files to enable grouping for supervised MOFA analysis.")
        )
      )
    }

    cols <- colnames(md)

    # Smart auto-selection for Sample ID column
    # Look for columns that contain 'sample' or 'sample id' in various formats
    col_lower <- tolower(cols)
    sample_id_candidates <- which(grepl("sample[_[:space:]]*id|^sample$", col_lower, ignore.case = TRUE))
    # Also accept loose matches like 'id' if nothing else found
    if (length(sample_id_candidates) == 0) {
      sample_id_candidates <- which(col_lower %in% c("id"))
    }
    auto_sample_id <- if (length(sample_id_candidates) > 0) cols[sample_id_candidates[1]] else ""

    # Smart auto-selection for Grouping column
    # Look for common grouping column names
    grouping_keywords <- c("group", "condition", "treatment", "class", "type", "status", "category")
    grouping_candidates <- which(sapply(col_lower, function(x) any(sapply(grouping_keywords, function(kw) grepl(kw, x)))))
    # Also include deduced grouping columns (_Group suffix)
    deduced_group_cols <- cols[grepl("_Group$", cols)]
    all_grouping_candidates <- unique(c(grouping_candidates, which(cols %in% deduced_group_cols)))
    auto_grouping <- if (length(all_grouping_candidates) > 0) cols[all_grouping_candidates[1]] else ""

    # All columns available in both dropdowns. Use display labels with spaces (convert '.' -> ' ') while keeping underlying values intact
    display_names <- gsub("\\.", " ", cols)
    all_choices <- setNames(cols, display_names)

    tagList(
      div(class = "mofa-column-selection-card", style = "margin-top: 10px; padding: 10px; border-radius: 6px; border-left: 3px solid #667eea;",
          strong("Column selection:"),
          tags$div(style = "margin-top: 8px;",
                   selectInput("mofa_sample_id_col", "Sample ID column:",
                               choices = all_choices,
                               selected = auto_sample_id, width = "100%")),
          tags$div(style = "margin-top: 8px;",
                   selectInput("mofa_group_col", "Grouping column:",
                               choices = c("(None)" = "", all_choices),
                               selected = auto_grouping, width = "100%")),
          tags$small(id = "mofa_column_help_text", style = "color: #6c757d;",
                     "Columns are auto-selected based on naming. Sample ID detects 'sample', 'sampleid', etc. Grouping detects 'group', 'condition', 'treatment', etc. Leave grouping empty for unsupervised MOFA.")
      )
    )
  })
  
  # Observer to conditionally enable/disable Sample ID field based on Grouping selection
  observe({
    req(input$mofa_group_col)
    
    # Check if selected grouping column is a deduced grouping (ends with _Group)
    is_deduced_grouping <- grepl("_Group$", input$mofa_group_col)
    
    if (is_deduced_grouping) {
      # Grey out Sample ID field when deduced grouping is selected
      shinyjs::disable("mofa_sample_id_col")
      # Update help text
      shinyjs::html("mofa_column_help_text", 
                   "Deduced grouping selected - Sample ID is automatically determined from the grouping data.")
    } else {
      # Enable Sample ID field for other groupings
      shinyjs::enable("mofa_sample_id_col")
      # Reset help text
      shinyjs::html("mofa_column_help_text", 
                   "Columns are auto-selected based on naming. Sample ID detects 'sample', 'sampleid', etc. Grouping detects 'group', 'condition', 'treatment', etc. Leave grouping empty for unsupervised MOFA.")
    }
  })
  
  # ============================================================================
  # MOFA GROUPING VARIABLE UI - Choose between Biological and Experimental Groups
  # ============================================================================
  output$mofa_group_choice_ui <- renderUI({
    req(mofa_metadata$data)

    group_col <- mofa_metadata$group_col_name
    group_values <- mofa_metadata$group_values
    has_group <- !is.na(group_col) && !is.null(group_values) && !all(is.na(group_values))

    if (!has_group) {
      return(tagList(
        div(class = "mofa-grouping-info-card", style = "background: #eef2ff; border-left: 4px solid #667eea; padding: 10px; margin-top: 10px; border-radius: 4px;",
            icon("info-circle"),
            span(style = "margin-left: 8px; color: #3730a3; font-size: 0.9em;",
                 "No grouping column selected (optional). You can proceed with MOFA; metadata can be used as covariates where supported."))
      ))
    }

    available_levels <- unique(group_values[!is.na(group_values) & nzchar(group_values)])
    if (length(available_levels) == 0) {
      return(tagList(
        div(class = "mofa-grouping-info-card", style = "background: #fff3cd; border-left: 4px solid #f0ad4e; padding: 10px; margin-top: 10px; border-radius: 4px;",
            icon("exclamation-triangle"),
            span(style = "margin-left: 8px; color: #8a6d3b; font-size: 0.9em;",
                 "The selected grouping column doesn't contain usable values. Metadata can still be used for covariates."))
      ))
    }

    display_group_col <- if (!is.na(group_col)) gsub("\\.", " ", group_col) else group_col
    tagList(
      div(class = "mofa-grouping-info-card", style = "background: #eef2ff; border-left: 4px solid #667eea; padding: 10px; margin-top: 10px; border-radius: 4px;",
          strong("Grouping column:"),
          span(style = "margin-left: 8px; color: #3730a3; font-weight: 500;", display_group_col)
      ),
      div(style = "margin-bottom: 15px; margin-top: 12px;",
          checkboxInput("mofa_multi_group", "Enable Multi-Group Analysis",
                       value = FALSE, width = "100%"),
          helpText("Check to analyze selected group levels as separate columns for MOFA+. Leave unchecked to treat the grouping column as a single factor.")
      ),
      conditionalPanel(
        condition = "input.mofa_multi_group == true",
        div(class = "mofa-grouping-info-card", style = "background: #e8f4f8; border-left: 4px solid #2196f3; padding: 15px; border-radius: 4px; margin-top: 10px;",
            h5(icon("layer-group"), "Multi-Group MOFA Analysis", style = "color: #01579b; margin-top: 0;"),
            p("Select the group levels you want to add as individual columns (a typical MOFA+ multi-group setup).", style = "margin-bottom: 10px;"),
            checkboxGroupInput("mofa_selected_group_levels",
                               label = paste("Group levels (", display_group_col, ")"),
                               choices = available_levels,
                               selected = available_levels,
                               inline = TRUE),
            helpText("plot_data_overview will show views as rows and groups as columns, letting MOFA compare the selected conditions.")
        )
      )
    )
  })
  
  # ============================================================================
  # DIABLO GROUPING VARIABLE UI - Display biological and experimental groups
  # ============================================================================
  output$diablo_grouping_ui <- renderUI({
    # Check if we have sample metadata from loaded analyses
    if (is.null(multiomics$sample_metadata) || ncol(multiomics$sample_metadata) == 0) {
      # No metadata available
      return(tagList(
        selectInput("diablo_group_var", "Grouping Variable:", width = "100%",
                    choices = NULL),
        helpText("Select a grouping variable from sample metadata to enable supervised integration. When loaded analyses contain group information, it will be automatically extracted and made available here."),
        div(style = "background: #f0f8ff; border-left: 4px solid #3498db; padding: 10px; margin-top: 10px; border-radius: 4px;",
            icon("info-circle"),
            span(style = "margin-left: 8px; color: #0c5460; font-size: 0.9em;",
                 "Load analyses in the Multi-Omics tab to extract grouping variables"))
      ))
    }
    
    # Organize metadata columns into groups
    meta_cols <- colnames(multiomics$sample_metadata)
    
    # Categorize columns as Biological or Experimental Groups
    biological_cols <- meta_cols[grepl("Biological|biological|Group|group", meta_cols, ignore.case = TRUE) &
                                   !grepl("Experimental|experimental", meta_cols, ignore.case = TRUE)]
    experimental_cols <- meta_cols[grepl("Experimental|experimental", meta_cols, ignore.case = TRUE)]
    other_cols <- setdiff(meta_cols, c(biological_cols, experimental_cols))
    
    # If no clear categorization, treat all as biological
    if (length(biological_cols) == 0 && length(experimental_cols) == 0 && length(other_cols) > 0) {
      biological_cols <- other_cols
      other_cols <- character(0)
    }
    
    # Build the UI with organized grouping
    ui_content <- list()
    
    # Add selectInput for grouping variable with organized choices
    choices_list <- list()
    
    if (length(biological_cols) > 0) {
      display_names_bio <- gsub("\\.", " ", sub("_Group$|_group$", "", biological_cols))
      choices_list$`Biological Groups` <- setNames(biological_cols, display_names_bio)
    }

    if (length(experimental_cols) > 0) {
      display_names_exp <- gsub("\\.", " ", sub("_Group$|_group$", "", experimental_cols))
      choices_list$`Experimental Groups` <- setNames(experimental_cols, display_names_exp)
    }

    if (length(other_cols) > 0) {
      display_names_other <- gsub("\\.", " ", other_cols)
      choices_list$`Other Groupings` <- setNames(other_cols, display_names_other)
    }

    ui_content$select <- selectInput("diablo_group_var", "Grouping Variable:", width = "100%",
                                     choices = choices_list)
    
    # Add informational card showing available groups
    if (!is.null(multiomics$sample_metadata) && nrow(multiomics$sample_metadata) > 0) {
      # Get unique values for each column to show what categories are available
      info_text <- "Available categories from loaded analyses:\n\n"
      
      # Show biological groups
      if (length(biological_cols) > 0) {
        info_text <- paste0(info_text, "Biological Groups:\n")
        for (col in biological_cols) {
          unique_vals <- unique(multiomics$sample_metadata[[col]])
          unique_vals <- unique_vals[!is.na(unique_vals)]
          display_col <- gsub("\\.", " ", sub("_Group$|_group$", "", col))
          info_text <- paste0(info_text, "  • ", display_col, ": ",
                              paste(unique_vals, collapse = ", "), "\n")
        }
        info_text <- paste0(info_text, "\n")
      }
      
      # Show experimental groups
      if (length(experimental_cols) > 0) {
        info_text <- paste0(info_text, "Experimental Groups:\n")
        for (col in experimental_cols) {
          unique_vals <- unique(multiomics$sample_metadata[[col]])
          unique_vals <- unique_vals[!is.na(unique_vals)]
          display_col <- gsub("\\.", " ", sub("_Group$|_group$", "", col))
          info_text <- paste0(info_text, "  • ", display_col, ": ",
                              paste(unique_vals, collapse = ", "), "\n")
        }
      }
      
      ui_content$info <- div(
        style = "background: #e8f4f8; border-left: 4px solid #2196f3; padding: 12px; margin-top: 10px; border-radius: 4px;",
        div(style = "font-weight: 600; color: #01579b; margin-bottom: 8px;",
            icon("bookmark"), " Extracted Group Information"),
        div(style = "font-family: monospace; font-size: 0.85em; color: #0277bd; white-space: pre-wrap; word-wrap: break-word;",
            info_text)
      )
    }
    
    ui_content$help <- helpText("Select a grouping variable to enable supervised DIABLO integration. The available variables are automatically extracted from the loaded analyses.")
    
    tagList(ui_content)
  })
  # ============================================================================
  # END DIABLO GROUPING VARIABLE UI
  # ============================================================================
  
  # Helper function to read omics data
  read_omics_data <- function(file_path, sample_col, feature_col) {
    tryCatch({
      # Read file based on extension
      ext <- tools::file_ext(file_path)
      
      if (ext %in% c("xlsx", "xls")) {
        data <- readxl::read_excel(file_path)
      } else if (ext == "csv") {
        data <- read.csv(file_path, stringsAsFactors = FALSE)
      } else if (ext %in% c("tsv", "txt")) {
        data <- read.delim(file_path, stringsAsFactors = FALSE)
      } else {
        stop("Unsupported file format")
      }
      
      # Handle different data formats
      # Format 1: Traditional format with sample ID column
      # Format 2: Matrix format where sample IDs are column headers
      
      if (sample_col == "NONE") {
        # Format 2: Matrix format - sample IDs are column headers
        if (!feature_col %in% colnames(data)) {
          stop(paste("Feature column", feature_col, "not found in data"))
        }
        feature_ids <- data[[feature_col]]
        sample_cols <- setdiff(colnames(data), feature_col)
        
        # Create expression matrix
        expr_matrix <- as.matrix(data[, sample_cols])
        rownames(expr_matrix) <- make.unique(as.character(feature_ids))
        sample_names <- sample_cols  # Column headers are sample names
        
      } else if (sample_col %in% colnames(data) && feature_col %in% colnames(data)) {
        # Format 1: Traditional format
        feature_ids <- data[[feature_col]]
        sample_cols <- setdiff(colnames(data), c(sample_col, feature_col))
        
        # Create expression matrix
        expr_matrix <- as.matrix(data[, sample_cols])
        rownames(expr_matrix) <- make.unique(as.character(feature_ids))
        sample_names <- colnames(expr_matrix)
        
      } else if (!sample_col %in% colnames(data)) {
        stop(paste("Sample column", sample_col, "not found in data. If your data has sample IDs as column headers, leave Sample ID Column field empty"))
      } else {
        stop(paste("Feature column", feature_col, "not found in data"))
      }
      
      list(
        data = expr_matrix,
        feature_ids = feature_ids,
        samples = sample_names,
        n_features = nrow(expr_matrix),
        n_samples = ncol(expr_matrix)
      )
    }, error = function(e) {
      list(error = as.character(e$message))
    })
  }
  
  # Dataset 1 Upload
  observeEvent(input$dataset1_file, {
    req(input$dataset1_file, input$dataset1_feature_col)
    
    # Handle sample column based on checkbox
    sample_col <- if (!is.null(input$dataset1_use_sample_col) && input$dataset1_use_sample_col) {
      # Checkbox is checked, use the text input value
      if (is.null(input$dataset1_sample_col) || input$dataset1_sample_col == "") {
        "NONE"  # Fallback if text input is empty
      } else {
        input$dataset1_sample_col
      }
    } else {
      "NONE"  # Checkbox not checked, assume matrix format
    }
    
    result <- read_omics_data(
      input$dataset1_file$datapath,
      sample_col,
      input$dataset1_feature_col
    )
    
    if (!is.null(result$error)) {
      showNotification(paste("Dataset 1 Error:", result$error), type = "error")
      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset1", status = "error"))
    } else {
      multiomics$dataset1 <- result$data
      multiomics$dataset1_samples <- result$samples
      
      showNotification(
        paste0("Dataset 1 uploaded: ", result$n_features, " features × ",
               result$n_samples, " samples"),
        type = "message"
      )
      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset1", status = "uploaded"))
    }
  })
  
  # Dataset 2 Upload
  observeEvent(input$dataset2_file, {
    req(input$dataset2_file, input$dataset2_feature_col)
    
    # Handle sample column based on checkbox
    sample_col <- if (!is.null(input$dataset2_use_sample_col) && input$dataset2_use_sample_col) {
      # Checkbox is checked, use the text input value
