    )
    
    if (!is.null(result$error)) {
      showNotification(paste("Dataset 2 Error:", result$error), type = "error")
      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset2", status = "error"))
    } else {
      multiomics$dataset2 <- result$data
      multiomics$dataset2_samples <- result$samples
      
