      )
      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset2", status = "uploaded"))
    }
  })
  
  # Dataset 3 Upload
  observeEvent(input$dataset3_file, {
    req(input$enable_dataset3, input$dataset3_file, input$dataset3_feature_col)
    
    # Handle sample column based on checkbox
    sample_col <- if (!is.null(input$dataset3_use_sample_col) && input$dataset3_use_sample_col) {
      # Checkbox is checked, use the text input value
