      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset3", status = "error"))
    } else {
      multiomics$dataset3 <- result$data
      multiomics$dataset3_samples <- result$samples
      
      showNotification(
        paste0("Dataset 3 uploaded: ", result$n_features, " features × ",
