      )
      session$sendCustomMessage("updateDatasetStatus",
                                list(dataset = "dataset3", status = "uploaded"))
    }
  })
  
  # Dataset info outputs
  output$dataset1_info <- renderUI({
    req(multiomics$dataset1)
    div(style = "margin-top: 10px; padding: 10px; background: #f0fdf4; border-radius: 5px;",
        p(style = "margin: 0; font-size: 0.9em;",
          icon("check-circle", style = "color: #10b981;"),
          strong(paste(nrow(multiomics$dataset1), "features ×",
                       ncol(multiomics$dataset1), "samples"))
        )
    )
  })
  
  output$dataset2_info <- renderUI({
    req(multiomics$dataset2)
    div(style = "margin-top: 10px; padding: 10px; background: #f0fdf4; border-radius: 5px;",
        p(style = "margin: 0; font-size: 0.9em;",
          icon("check-circle", style = "color: #10b981;"),
          strong(paste(nrow(multiomics$dataset2), "features ×",
                       ncol(multiomics$dataset2), "samples"))
        )
    )
  })
  
  output$dataset3_info <- renderUI({
    req(multiomics$dataset3)
    div(style = "margin-top: 10px; padding: 10px; background: #f0fdf4; border-radius: 5px;",
        p(style = "margin: 0; font-size: 0.9em;",
          icon("check-circle", style = "color: #10b981;"),
          strong(paste(nrow(multiomics$dataset3), "features ×",
                       ncol(multiomics$dataset3), "samples"))
        )
    )
  })
  
  # Sample groups file upload
  observeEvent(input$sample_groups_file, {
    req(input$sample_groups_file)
    
    tryCatch({
      # Read groups file
      ext <- tools::file_ext(input$sample_groups_file$name)
      
      if (ext %in% c("xlsx", "xls")) {
        groups_data <- readxl::read_excel(input$sample_groups_file$datapath)
      } else if (ext == "csv") {
        groups_data <- read.csv(input$sample_groups_file$datapath, stringsAsFactors = FALSE)
      } else if (ext %in% c("tsv", "txt")) {
        groups_data <- read.delim(input$sample_groups_file$datapath, stringsAsFactors = FALSE)
      }
      
      # Validate columns
      if (!("SampleID" %in% colnames(groups_data) && "Group" %in% colnames(groups_data))) {
        showNotification("Groups file must have 'SampleID' and 'Group' columns",
                         type = "error")
        return(NULL)
      }
      
      # Create named factor
      sample_groups <- factor(groups_data$Group)
      names(sample_groups) <- groups_data$SampleID
      
      # Store in reactive values
      multiomics$sample_groups <- sample_groups
      multiomics$sample_metadata <- groups_data
      
      showNotification(
        paste("✓ Sample groups loaded:", length(unique(sample_groups)), "groups,",
              length(sample_groups), "samples"),
        type = "message"
      )
      
    }, error = function(e) {
      showNotification(paste("Error loading groups file:", e$message), type = "error")
    })
  })
  
  # Groups upload info
  output$groups_upload_info <- renderUI({
    req(multiomics$sample_groups)
    div(style = "margin-top: 10px; padding: 10px; background: #f0fdf4; border-radius: 5px;",
        p(style = "margin: 0; font-size: 0.9em;",
          icon("check-circle", style = "color: #10b981;"),
          strong(paste(length(unique(multiomics$sample_groups)), "groups,",
                       length(multiomics$sample_groups), "samples"))
        )
    )
  })
  
  # Sample matching summary
  output$sample_match_summary <- renderUI({
    req(multiomics$dataset1, multiomics$dataset2)
    
    samples1 <- multiomics$dataset1_samples
    samples2 <- multiomics$dataset2_samples
    
    common <- intersect(samples1, samples2)
    
    if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
      samples3 <- multiomics$dataset3_samples
      common <- intersect(common, samples3)
      
      only1 <- setdiff(samples1, union(samples2, samples3))
      only2 <- setdiff(samples2, union(samples1, samples3))
      only3 <- setdiff(samples3, union(samples1, samples2))
      
      div(class = "sample-match-matrix",
          h5(icon("info-circle"), " Sample Alignment Status"),
          p(strong("Common samples: "), span(style = "color: #10b981; font-size: 1.2em;", length(common))),
          p("Dataset 1 unique: ", span(style = "color: #f59e0b;", length(only1))),
          p("Dataset 2 unique: ", span(style = "color: #f59e0b;", length(only2))),
          p("Dataset 3 unique: ", span(style = "color: #f59e0b;", length(only3)))
      )
    } else {
      only1 <- setdiff(samples1, samples2)
      only2 <- setdiff(samples2, samples1)
      
      div(class = "sample-match-matrix",
          h5(icon("info-circle"), " Sample Alignment Status"),
          p(strong("Common samples: "), span(style = "color: #10b981; font-size: 1.2em;", length(common))),
          p("Dataset 1 unique: ", span(style = "color: #f59e0b;", length(only1))),
          p("Dataset 2 unique: ", span(style = "color: #f59e0b;", length(only2)))
      )
    }
  })
  
  # Validate sample alignment
  observeEvent(input$validate_samples, {
    
    req(multiomics$dataset1, multiomics$dataset2)
    
    samples1 <- multiomics$dataset1_samples
    samples2 <- multiomics$dataset2_samples
    
    common <- intersect(samples1, samples2)
    
    if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
      samples3 <- multiomics$dataset3_samples
      common <- intersect(common, samples3)
    }
    
    multiomics$common_samples <- common
    
    if (length(common) < 5) {
      showNotification(
        "Warning: Less than 5 common samples found. Integration may not be reliable.",
        type = "warning",
        duration = 10
      )
    } else if (length(common) < 15) {
      showNotification(
        paste(length(common), "common samples found. Recommended: ≥15 samples for robust analysis."),
        type = "warning",
        duration = 8
      )
    } else {
      showNotification(
        paste("✓ Sample alignment validated:", length(common), "common samples"),
        type = "message"
      )
    }
    
    # Try to infer groups from existing values$final_biological_groups
    if (!is.null(values$final_biological_groups) &&
        all(multiomics$common_samples %in% names(values$final_biological_groups))) {
      groups <- values$final_biological_groups[multiomics$common_samples]
      multiomics$sample_groups <- factor(groups)
      
      showNotification(
        paste("✓ Sample groups detected:", length(unique(groups)), "groups"),
        type = "message"
      )
    } else {
      # Create demo groups for testing
      n_samples <- length(common)
      n_groups <- min(3, floor(n_samples / 5))
      if (n_groups >= 2) {
        demo_groups <- factor(rep(paste0("Group_", 1:n_groups), length.out = n_samples))
        names(demo_groups) <- common
        multiomics$sample_groups <- demo_groups
        
        showNotification(
          "Note: Using demo groupings. Upload sample metadata or use Data Upload groups for real analysis.",
          type = "warning",
          duration = 8
        )
      }
    }
  })
  
  # Update DIABLO group variable choices
  observe({
    req(multiomics$common_samples)
    
    choices <- c("Use detected groups" = "auto")
    
    # Add metadata columns if available
    if (!is.null(multiomics$sample_metadata)) {
      meta_cols <- colnames(multiomics$sample_metadata)[
        sapply(multiomics$sample_metadata, function(x)
          is.factor(x) || is.character(x))
      ]
      if (length(meta_cols) > 0) {
        choices <- c(choices, setNames(meta_cols, paste("Metadata:", meta_cols)))
      }
    }
    
    updateSelectInput(session, "diablo_group_var", choices = choices, selected = "auto")
  })
  
  # Update MOFA group variable choices
  observe({
    req(multiomics$common_samples)
    
    choices <- c("None (Unsupervised)" = "")
    
    # Add metadata columns if available
    if (!is.null(multiomics$sample_metadata)) {
      # Filter for character/factor columns that can be used for grouping
      meta_cols <- colnames(multiomics$sample_metadata)[
        sapply(multiomics$sample_metadata, function(col) {
          is.factor(col) || is.character(col)
        })
      ]
      
      if (length(meta_cols) > 0) {
        # Create display labels that are cleaner - remove "_Group" suffix and replace underscores with spaces
        display_labels <- sub("_Group$", "", meta_cols)
        display_labels <- gsub("_", " ", display_labels)
        choices <- c(choices, setNames(meta_cols, display_labels))
      }
    }
    
    updateSelectInput(session, "mofa_group_var", choices = choices, selected = "")
  })
  
  # Sample match plot
  output$sample_match_plot <- renderPlot({ 
    # Only show if datasets are available (not MOFA-only analysis)
    if (is.null(multiomics$dataset1) || is.null(multiomics$dataset2)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Sample coverage data not available\n(requires multi-dataset integration)",
                        size = 5, color = "#667eea") +
               theme_void())
    }
    
    samples1 <- multiomics$dataset1_samples
    samples2 <- multiomics$dataset2_samples
    
    if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
      samples3 <- multiomics$dataset3_samples
      
      # Create presence/absence matrix
      all_samples <- unique(c(samples1, samples2, samples3))
      match_matrix <- data.frame(
        Sample = all_samples,
        Dataset1 = all_samples %in% samples1,
        Dataset2 = all_samples %in% samples2,
        Dataset3 = all_samples %in% samples3
      )
      
      # Reshape for ggplot
      match_long <- tidyr::pivot_longer(match_matrix,
                                        cols = starts_with("Dataset"),
                                        names_to = "Dataset",
                                        values_to = "Present")
      
      ggplot(match_long, aes(x = Dataset, y = Sample, fill = Present)) +
        geom_tile(color = "white", size = 0.5) +
        scale_fill_manual(values = c("TRUE" = "#10b981", "FALSE" = "#f3f4f6"),
                          labels = c("TRUE" = "Present", "FALSE" = "Absent")) +
        labs(title = "Sample Matching Across Datasets",
             x = NULL, y = NULL, fill = "Status") +
        ggprism::theme_prism() +
        theme(
          axis.text.x = element_text(angle = 0, hjust = 0.5),
          axis.text.y = element_text(size = 8),
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5)
        )
    } else {
      # Two datasets only
      all_samples <- unique(c(samples1, samples2))
      match_matrix <- data.frame(
        Sample = all_samples,
        Dataset1 = all_samples %in% samples1,
        Dataset2 = all_samples %in% samples2
      )
      
      match_long <- tidyr::pivot_longer(match_matrix,
                                        cols = starts_with("Dataset"),
                                        names_to = "Dataset",
                                        values_to = "Present")
      
      ggplot(match_long, aes(x = Dataset, y = Sample, fill = Present)) +
        geom_tile(color = "white", size = 0.5) +
        scale_fill_manual(values = c("TRUE" = "#10b981", "FALSE" = "#f3f4f6"),
                          labels = c("TRUE" = "Present", "FALSE" = "Absent")) +
        labs(title = "Sample Matching Across Datasets",
             x = NULL, y = NULL, fill = "Status") +
        ggprism::theme_prism() +
        theme(
          axis.text.x = element_text(angle = 0, hjust = 0.5),
          axis.text.y = element_text(size = 8),
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5)
        )
    }
  })
  
  # Sample match table
  output$sample_match_table <- DT::renderDT({
    # Only show if datasets are available (not MOFA-only analysis)
    if (is.null(multiomics$dataset1) || is.null(multiomics$dataset2)) {
      return(DT::datatable(data.frame(
        Message = "Sample coverage data not available (requires multi-dataset integration)"
      )))
    }
    
    samples1 <- multiomics$dataset1_samples
    samples2 <- multiomics$dataset2_samples
    
    if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
      samples3 <- multiomics$dataset3_samples
      all_samples <- unique(c(samples1, samples2, samples3))
      
      match_df <- data.frame(
        Sample = all_samples,
        Dataset1 = ifelse(all_samples %in% samples1, "✓", "✗"),
        Dataset2 = ifelse(all_samples %in% samples2, "✓", "✗"),
        Dataset3 = ifelse(all_samples %in% samples3, "✓", "✗"),
        Status = ifelse(
          all_samples %in% samples1 & all_samples %in% samples2 & all_samples %in% samples3,
          "Common", "Unique"
        )
      )
    } else {
      all_samples <- unique(c(samples1, samples2))
      match_df <- data.frame(
        Sample = all_samples,
        Dataset1 = ifelse(all_samples %in% samples1, "✓", "✗"),
        Dataset2 = ifelse(all_samples %in% samples2, "✓", "✗"),
        Status = ifelse(all_samples %in% samples1 & all_samples %in% samples2,
                        "Common", "Unique")
      )
    }
    
    DT::datatable(match_df,
                  options = list(
                    pageLength = 10,
                    scrollX = TRUE,
                    dom = 'Bfrtip'
                  ),
                  rownames = FALSE)
  })

  # Update correlation dataset pair choices
  observe({
    available <- character(0)

    # Loaded analyses with data
    if (length(multiomics$loaded_analyses) > 0) {
      loaded_valid <- names(multiomics$loaded_analyses)[sapply(multiomics$loaded_analyses, function(x) {
        !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data))
      })]
      available <- c(available, loaded_valid)
    }

    # Manually uploaded datasets
    if (!is.null(multiomics$dataset1)) available <- c(available, "Dataset1")
    if (!is.null(multiomics$dataset2)) available <- c(available, "Dataset2")
    if (!is.null(multiomics$dataset3) && isTRUE(input$enable_dataset3)) available <- c(available, "Dataset3")

    available <- unique(available)

    if (length(available) >= 2) {
      current_from <- if (!is.null(input$corr_dataset_from) && input$corr_dataset_from %in% available) {
        input$corr_dataset_from
      } else {
        available[1]
      }

      # Pick a different default for the second selector when possible
      default_to <- available[min(2, length(available))]
      if (!is.null(input$corr_dataset_to) && input$corr_dataset_to %in% available && input$corr_dataset_to != current_from) {
        current_to <- input$corr_dataset_to
      } else {
        alt <- setdiff(available, current_from)
        current_to <- if (length(alt) > 0) alt[1] else default_to
      }

      updateSelectInput(session, "corr_dataset_from", choices = available, selected = current_from)
      updateSelectInput(session, "corr_dataset_to", choices = available, selected = current_to)
    } else {
      updateSelectInput(session, "corr_dataset_from", choices = available)
      updateSelectInput(session, "corr_dataset_to", choices = available)
    }
  })
  
  # ========== HELPER FUNCTION: Standardize enrichment column names ==========
  # Different enrichment tools use different column names; this function normalizes them
  standardize_enrichment_columns <- function(df) {
    if (is.null(df) || nrow(df) == 0) return(df)
    
    # Create a copy to avoid modifying original
    result <- df
    
    # Standardize ID column
    if (!"ID" %in% colnames(result)) {
      id_cols <- c("term_id", "GO.ID", "Term", "pathway_id", "term_id", "native", "source_id")
      for (col in id_cols) {
        if (col %in% colnames(result)) {
          result$ID <- result[[col]]
          break
        }
      }
      if (!"ID" %in% colnames(result)) {
        result$ID <- rownames(result)
      }
    }
    
    # Standardize Description column
    if (!"Description" %in% colnames(result)) {
      desc_cols <- c("term_name", "Term", "Description", "pathway_name", "name")
      for (col in desc_cols) {
        if (col %in% colnames(result)) {
          result$Description <- result[[col]]
          break
        }
      }
      if (!"Description" %in% colnames(result)) {
        result$Description <- result$ID
      }
    }
    
    # Standardize p-value column
    if (!"pvalue" %in% colnames(result)) {
      pval_cols <- c("p_value", "PValue", "pval", "P.Value", "pvalueCutoff", "p.value")
      for (col in pval_cols) {
        if (col %in% colnames(result)) {
          result$pvalue <- as.numeric(result[[col]])
          break
        }
      }
      if (!"pvalue" %in% colnames(result) && "p.adjust" %in% colnames(result)) {
        result$pvalue <- as.numeric(result[["p.adjust"]])
      }
    }
    
    # Standardize adjusted p-value column
    if (!"p.adjust" %in% colnames(result)) {
      padj_cols <- c("p_adjusted", "padj", "FDR", "qvalue", "q.value", "BH")
      for (col in padj_cols) {
        if (col %in% colnames(result)) {
          result$p.adjust <- as.numeric(result[[col]])
          break
        }
      }
    }
    
    # Standardize gene ratio column
    if (!"GeneRatio" %in% colnames(result)) {
      ratio_cols <- c("gene_ratio", "intersection_size", "precision", "recall")
      for (col in ratio_cols) {
        if (col %in% colnames(result)) {
          result$GeneRatio <- result[[col]]
          break
        }
      }
    }
    
    # Standardize gene ID column  
    if (!"geneID" %in% colnames(result)) {
      gene_cols <- c("core_enrichment", "intersections", "genes", "gene_ids")
      for (col in gene_cols) {
        if (col %in% colnames(result)) {
          result$geneID <- result[[col]]
          break
        }
      }
    }
    
    result
  }
  
  # Run Integration Analysis
  observeEvent(input$run_integration, {
    # Reset integration results to start fresh
    multiomics$integration_results <- NULL
    multiomics$model_loaded_from_file <- FALSE
    
    req(input$integration_method)
    
    # Check if we have loaded analyses with actual data or manual uploads
    # Exclude the designated metadata file from dataset count
    designated_meta_name <- multiomics$designated_metadata
    data_loaded_count <- sum(as.numeric(sapply(names(multiomics$loaded_analyses), function(n) {
      x <- multiomics$loaded_analyses[[n]]
      # Skip if this is the designated metadata
      if (!is.null(designated_meta_name) && identical(n, designated_meta_name)) return(FALSE)
      !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data))
    })))
    has_loaded <- data_loaded_count >= 2
    has_manual <- !is.null(multiomics$dataset1) && !is.null(multiomics$dataset2)
    
    # Check enrichment availability for pathway integration
    session_enrichments <- names(multiomics$loaded_enrichments)
    loaded_enrichments <- names(multiomics$loaded_analyses)[
      sapply(multiomics$loaded_analyses, function(x) !is.null(x$type) && x$type == "enrichment")
    ]
    available_enrichments <- unique(c(session_enrichments, loaded_enrichments))
    has_enrichments <- length(available_enrichments) >= 2
    
    if (input$integration_method == "pathway") {
      if (!has_enrichments) {
        showNotification(
          "Please load or save at least 2 enrichment datasets for pathway concordance",
          type = "error"
        )
        return()
      }
    } else {
      if (!has_loaded && !has_manual) {
        showNotification(
          "Please load saved analyses or manually upload at least 2 datasets",
          type = "error"
        )
        return()
      }
    }
    
    # Show progress
    withProgress(message = 'Running integration analysis...', value = 0, {
      
      # Prepare data from loaded analyses or manual uploads
      if (has_loaded) {
        # Only require common samples for methods that need matched samples (MOFA, DIABLO)
        # Other methods (correlation, pathway) can work with different sample sets
        needs_common_samples <- input$integration_method %in% c("mofa", "diablo")
        
        if (needs_common_samples && (is.null(multiomics$common_samples) || length(multiomics$common_samples) == 0)) {
          # Attempt to derive common samples using available external/combined metadata
          derived_common <- NULL
          candidate_samples <- NULL

          if (!is.null(multiomics$sample_metadata) && nrow(multiomics$sample_metadata) > 0) {
            candidate_samples <- rownames(multiomics$sample_metadata)
          } else if (!is.null(multiomics$external_metadata_combined) && nrow(multiomics$external_metadata_combined) > 0) {
            candidate_samples <- rownames(multiomics$external_metadata_combined)
          }

          if (!is.null(candidate_samples)) {
            # Intersect candidate samples with loaded analyses sample lists
            loaded_lists <- lapply(multiomics$loaded_analyses, function(x) x$samples)
            if (length(loaded_lists) > 0) {
              # Normalize helper: trim whitespace and lowercase for matching
              normalize_samples <- function(x) trimws(tolower(as.character(x)))

              try({
                # Normalized lists for robust intersection
                normalized_lists <- lapply(loaded_lists, normalize_samples)
                common_normalized <- Reduce(intersect, normalized_lists)

                # Normalize candidate samples (from metadata)
                candidate_normalized <- normalize_samples(candidate_samples)

                # Intersection of normalized names
                derived_normalized <- intersect(common_normalized, candidate_normalized)

                # Map back to original names using the first loaded analysis's original naming
                if (length(derived_normalized) > 0) {
                  first_originals <- as.character(loaded_lists[[1]])
                  first_normalized <- normalize_samples(first_originals)
                  derived_common <- first_originals[match(derived_normalized, first_normalized)]
                } else {
                  derived_common <- character(0)
                }
              }, silent = TRUE)
            }

            # If derived common samples exist, use them and persist for later
            if (!is.null(derived_common) && length(derived_common) > 0) {
              multiomics$common_samples <- derived_common
              showNotification(paste0("Derived ", length(derived_common), " common sample(s) from uploaded metadata and loaded analyses. Proceeding with N-integration."),
                               type = "message", duration = 8)
            }
          }

          # Re-check final common_samples
          if (is.null(multiomics$common_samples) || length(multiomics$common_samples) == 0) {
            showNotification(
              "Loaded analyses do not share common sample IDs. Please load analyses with matching sample names for N-integration.",
              type = "error",
              duration = 10
            )
            return()
          }
        }
        # Use loaded saved analyses
        incProgress(0.1, detail = "Preparing loaded analyses...")
        
        # Only include loaded analyses that have numeric data frames/matrices (skip metadata-only entries)
        # Also exclude the designated metadata file
        data_list <- list()
        dataset_names <- names(multiomics$loaded_analyses)[sapply(names(multiomics$loaded_analyses), function(n) {
          x <- multiomics$loaded_analyses[[n]]
          # Skip if this is the designated metadata
          if (!is.null(designated_meta_name) && identical(n, designated_meta_name)) return(FALSE)
          !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data))
        })]
        if (length(dataset_names) < 2) {
          showNotification("Not enough loaded datasets with data available for integration. Load analyses with numeric data or use manual uploads.", type = "error", duration = 8)
          return()
        }
        
        if (needs_common_samples) {
          common_samples <- multiomics$common_samples
        } else {
          # For methods that don't require common samples, use all available samples
          # but warn user about mismatched sample sets
          all_samples <- lapply(multiomics$loaded_analyses, function(x) x$samples)
          common_samples <- unique(unlist(all_samples))
          
          if (length(all_samples) > 1) {
            showNotification(
              paste("Warning: Integration method", input$integration_method, "will use all available samples.",
                    "Some datasets may have missing values for samples not present in all datasets."),
              type = "warning",
              duration = 8
            )
          }
        }
        
        for (i in seq_along(dataset_names)) {
          name <- dataset_names[i]
          analysis <- multiomics$loaded_analyses[[name]]

          # Skip entries without data (shouldn't happen due to earlier filtering), but guard anyway
          if (is.null(analysis$data) || !(is.data.frame(analysis$data) || is.matrix(analysis$data))) {
            next
          }

          if (needs_common_samples) {
            # Filter to common samples and transpose for mixOmics (samples as rows)
            # Support both formats: samples as columns (common) or samples as rownames
            if (all(common_samples %in% colnames(analysis$data))) {
              data_filtered <- analysis$data[, common_samples, drop = FALSE]
              data_list[[name]] <- t(data_filtered)
            } else if (all(common_samples %in% rownames(analysis$data))) {
              # Data already has samples in rows; take rows and ensure features are columns
              data_filtered <- analysis$data[common_samples, , drop = FALSE]
              data_list[[name]] <- as.matrix(data_filtered)
            } else {
              showNotification(
                paste("Error: Dataset", name, "does not contain required sample IDs for integration."),
                type = "error"
              )
              return()
            }

          } else {
            # For methods that don't require common samples, handle missing samples
            available_samples <- intersect(common_samples, analysis$samples)
            if (length(available_samples) == 0) {
              showNotification(
                paste("Error: Dataset", name, "has no samples in common with the integration set."),
                type = "error"
              )
              return()
            }

            # Create matrix with all common_samples, filling missing ones with NA
            # Support data.frames where samples may be columns or rows
            if (all(available_samples %in% colnames(analysis$data))) {
              data_matrix <- matrix(NA, nrow = nrow(analysis$data), ncol = length(common_samples))
              colnames(data_matrix) <- common_samples
              rownames(data_matrix) <- rownames(analysis$data)
              available_idx <- match(available_samples, common_samples)
              data_matrix[, available_idx] <- as.matrix(analysis$data[, available_samples, drop = FALSE])
              data_list[[name]] <- t(data_matrix)
            } else if (all(available_samples %in% rownames(analysis$data))) {
              # samples are in rows; build with rows aligned to common_samples
              data_matrix <- matrix(NA, nrow = length(common_samples), ncol = ncol(analysis$data))
              rownames(data_matrix) <- common_samples
              colnames(data_matrix) <- colnames(analysis$data)
              available_idx <- match(available_samples, common_samples)
              data_matrix[available_idx, ] <- as.matrix(analysis$data[available_samples, , drop = FALSE])
              data_list[[name]] <- data_matrix # already samples x features
            } else {
              showNotification(
                paste("Error: Dataset", name, "does not contain required samples in any orientation."),
                type = "error"
              )
              return()
            }
          }
        }
        
      } else {
        # Use manual uploads
        incProgress(0.1, detail = "Preparing uploaded datasets...")
        
        req(multiomics$dataset1, multiomics$dataset2, multiomics$common_samples)
        
        # Filter datasets to common samples
        data1 <- multiomics$dataset1[, multiomics$common_samples]
        data2 <- multiomics$dataset2[, multiomics$common_samples]
        
        if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
          data3 <- multiomics$dataset3[, multiomics$common_samples]
          data_list <- list(Dataset1 = t(data1), Dataset2 = t(data2), Dataset3 = t(data3))
        } else {
          data_list <- list(Dataset1 = t(data1), Dataset2 = t(data2))
        }
        
        common_samples <- multiomics$common_samples
      }
      
      incProgress(0.2, detail = "Preparing data...")
      
      # Validate data is numeric for methods that require it
      if (input$integration_method %in% c("mofa", "diablo")) {
        data_validation <- sapply(data_list, function(x) {
          # x should be samples x features (numeric matrix)
          if (!is.matrix(x) && !is.data.frame(x)) {
            return(FALSE)
          }
          # Check if all columns are numeric
          return(all(sapply(x, function(col) is.numeric(col) || is.integer(col))))
        })
        
        if (!all(data_validation)) {
          non_numeric_datasets <- names(data_list)[!data_validation]
          showNotification(
            paste0("Error: Datasets must contain only numeric data for ",
                   input$integration_method, " analysis. Non-numeric data found in: ",
                   paste(non_numeric_datasets, collapse = ", "), ". ",
                   "Please ensure all features are numeric values."),
            type = "error",
            duration = 10
          )
          return()
        }
        
        # Convert data frames to matrices if needed
        data_list <- lapply(data_list, function(x) {
          if (is.data.frame(x)) {
            return(as.matrix(x))
          }
          return(x)
        })
      }
      
      # Run selected method
      result <- tryCatch({
        if (input$integration_method == "correlation") {
          # Cross-omics correlation analysis
          incProgress(0.3, detail = "Computing correlations...")

          available_names <- names(data_list)
          if (length(available_names) < 2) {
            showNotification("Need at least two datasets for correlation analysis.", type = "error", duration = 6)
            return(NULL)
          }

          # Choose dataset pair from UI selections
          pick_from <- if (!is.null(input$corr_dataset_from) && input$corr_dataset_from %in% available_names) input$corr_dataset_from else available_names[1]
          pick_to <- if (!is.null(input$corr_dataset_to) && input$corr_dataset_to %in% available_names && input$corr_dataset_to != pick_from) input$corr_dataset_to else {
            alt <- setdiff(available_names, pick_from)
            if (length(alt) > 0) alt[1] else available_names[1]
          }
          if (pick_from == pick_to) {
            showNotification("Select two different datasets for correlation network.", type = "error", duration = 6)
            return(NULL)
          }

          # Helper to generate display names for manual uploads
          pretty_dataset <- function(id) {
            if (identical(id, "Dataset1") && !is.null(input$dataset1_type) && nzchar(input$dataset1_type)) return(input$dataset1_type)
            if (identical(id, "Dataset2") && !is.null(input$dataset2_type) && nzchar(input$dataset2_type)) return(input$dataset2_type)
            if (identical(id, "Dataset3") && !is.null(input$dataset3_type) && nzchar(input$dataset3_type)) return(input$dataset3_type)
            id
          }
          dataset_labels <- c(from = pretty_dataset(pick_from), to = pretty_dataset(pick_to))
          
          # Extract matrices (samples x features) and ensure they have proper column names
          data1_orig <- data_list[[pick_from]]
          data2_orig <- data_list[[pick_to]]
          
          # Extract real feature names from loaded analyses (similar to MOFA approach)
          get_real_feature_names <- function(dataset_name, matrix_data) {
            if (!exists("multiomics") || is.null(multiomics$loaded_analyses) || 
                !(dataset_name %in% names(multiomics$loaded_analyses))) {
              return(colnames(matrix_data))
            }
            
            analysis_obj <- multiomics$loaded_analyses[[dataset_name]]
            
            # Try different sources for feature names
            if (!is.null(analysis_obj$cleaned_molecules) &&
                length(analysis_obj$cleaned_molecules) == ncol(matrix_data) &&
                !all(is.na(analysis_obj$cleaned_molecules))) {
              return(as.character(analysis_obj$cleaned_molecules))
            } else if (!is.null(analysis_obj$accession_ids) &&
                       length(analysis_obj$accession_ids) == ncol(matrix_data) &&
                       !all(is.na(analysis_obj$accession_ids))) {
              return(as.character(analysis_obj$accession_ids))
            } else if (!is.null(analysis_obj$features) &&
                       length(analysis_obj$features) == ncol(matrix_data) &&
                       !all(is.na(analysis_obj$features))) {
              return(as.character(analysis_obj$features))
            } else if (!is.null(analysis_obj$data) && !is.null(rownames(analysis_obj$data))) {
              return(as.character(rownames(analysis_obj$data)))
            }
            
            # If feature labels look like plain numeric indices, try to map them back
            current_names <- colnames(matrix_data)
            if (!is.null(current_names) && length(current_names) == ncol(matrix_data) &&
                all(grepl("^\\d+$", current_names))) {
              idx <- suppressWarnings(as.integer(current_names))
              if (!anyNA(idx) && min(idx) >= 1) {
                map_by_index <- function(vec) {
                  if (is.null(vec) || length(vec) == 0 || all(is.na(vec))) return(NULL)
                  if (max(idx) > length(vec)) return(NULL)
                  out <- as.character(vec[idx])
                  if (length(out) != length(idx) || all(is.na(out))) return(NULL)
                  out
                }
                
                mapped <- map_by_index(analysis_obj$cleaned_molecules)
                if (is.null(mapped)) mapped <- map_by_index(analysis_obj$accession_ids)
                if (is.null(mapped)) mapped <- map_by_index(analysis_obj$features)
                
                if (!is.null(mapped)) {
                  return(mapped)
                }
              }
            }
            
            # Fallback to current column names
            return(colnames(matrix_data))
          }
          
          # Set proper column names using real feature names
          real_names1 <- get_real_feature_names(pick_from, data1_orig)
          real_names2 <- get_real_feature_names(pick_to, data2_orig)
          
          if (!is.null(real_names1) && length(real_names1) == ncol(data1_orig)) {
            colnames(data1_orig) <- real_names1
          }
          if (!is.null(real_names2) && length(real_names2) == ncol(data2_orig)) {
            colnames(data2_orig) <- real_names2
          }
          
          # Extract matrices (features x samples)
          data1 <- t(data1_orig)
          data2 <- t(data2_orig)
          
          # Select top features from each dataset
          n_top <- input$corr_top_features
          vars1 <- apply(data1, 1, var, na.rm = TRUE)
          vars2 <- apply(data2, 1, var, na.rm = TRUE)
          
          top1 <- names(sort(vars1, decreasing = TRUE)[1:min(n_top, length(vars1))])
          top2 <- names(sort(vars2, decreasing = TRUE)[1:min(n_top, length(vars2))])
          
          data1_sub <- data1[top1, ]
          data2_sub <- data2[top2, ]
          
          # Compute correlation matrix
          cor_matrix <- cor(t(data1_sub), t(data2_sub),
                            method = input$corr_method, use = "pairwise.complete.obs")
          
          # Compute p-values for correlations
          incProgress(0.4, detail = "Computing p-values...")
          n_samples <- ncol(data1_sub)
          cor_pvals <- matrix(NA, nrow = nrow(cor_matrix), ncol = ncol(cor_matrix))
          
          for (i in 1:nrow(cor_matrix)) {
            for (j in 1:ncol(cor_matrix)) {
              # Correlation test
              if (!is.na(cor_matrix[i, j])) {
                cor_test <- cor.test(data1_sub[i, ], data2_sub[j, ],
                                     method = input$corr_method)
                cor_pvals[i, j] <- cor_test$p.value
              }
            }
          }

          # Optional multiple-testing adjustment (BH)
          cor_pvals_raw <- cor_pvals
          if (isTRUE(input$corr_adjust_p)) {
            adj_vec <- p.adjust(as.vector(cor_pvals), method = "BH")
            cor_pvals <- matrix(adj_vec, nrow = nrow(cor_matrix), ncol = ncol(cor_matrix))
            rownames(cor_pvals) <- rownames(cor_matrix)
            colnames(cor_pvals) <- colnames(cor_matrix)
          }
          
          incProgress(0.6, detail = "Building network...")
          
          # Find significant correlations
          cor_threshold <- input$corr_threshold
          pval_threshold <- input$corr_pval

          filter_mode <- input$corr_filter_mode %||% "absolute"
          sig_mask <- switch(filter_mode,
                             positive = cor_matrix >= cor_threshold & cor_pvals < pval_threshold,
                             negative = cor_matrix <= -cor_threshold & cor_pvals < pval_threshold,
                             cor_matrix <= -Inf)  # placeholder for default
          if (!filter_mode %in% c("positive", "negative")) {
            sig_mask <- abs(cor_matrix) >= cor_threshold & cor_pvals < pval_threshold
          }

          sig_idx <- which(sig_mask, arr.ind = TRUE)
          
          # Create edge list for network
          if (nrow(sig_idx) > 0) {
            edge_list_all <- data.frame(
              from = paste0(pick_from, "_", rownames(cor_matrix)[sig_idx[, 1]]),
              to = paste0(pick_to, "_", colnames(cor_matrix)[sig_idx[, 2]]),
              correlation = cor_matrix[sig_idx],
              pvalue = cor_pvals[sig_idx],
              pvalue_raw = cor_pvals_raw[sig_idx],
              from_dataset = pick_from,
              to_dataset = pick_to,
              stringsAsFactors = FALSE
            )

            edge_list_all$abs_cor <- abs(edge_list_all$correlation)
            edge_list_all <- edge_list_all[order(-edge_list_all$abs_cor), , drop = FALSE]
            edge_cap <- input$corr_max_edges %||% 100
            edge_list <- head(edge_list_all, edge_cap)
            edge_list$abs_cor <- NULL
          } else {
            edge_list_all <- data.frame(
              from = character(0), to = character(0),
              correlation = numeric(0), pvalue = numeric(0), pvalue_raw = numeric(0),
              from_dataset = character(0), to_dataset = character(0)
            )
            edge_list <- edge_list_all
          }
          
          # Create node list with unique vertex names
          node_list <- data.frame(
            id = c(paste0(pick_from, "_", rownames(cor_matrix)), 
                   paste0(pick_to, "_", colnames(cor_matrix))),
            name = c(rownames(cor_matrix), colnames(cor_matrix)),
            dataset = c(rep(pick_from, nrow(cor_matrix)),
                        rep(pick_to, ncol(cor_matrix))),
            degree = 0,
            stringsAsFactors = FALSE
          )
          
          # Calculate node degree (number of connections)
          if (nrow(edge_list) > 0) {
            from_counts <- table(edge_list$from)
            to_counts <- table(edge_list$to)
            node_list$degree <- sapply(node_list$id, function(x) {
              sum(from_counts[x], to_counts[x], na.rm = TRUE)
            })
          }
          
          list(
            method = "correlation",
            correlation_method = input$corr_method,
            cor_matrix = cor_matrix,
            cor_pvals = cor_pvals,
            cor_pvals_raw = cor_pvals_raw,
            sig_cors = sig_idx,
            n_sig_pairs = nrow(sig_idx),
            n_sig_pairs_capped = nrow(edge_list),
            threshold = cor_threshold,
            pval_threshold = pval_threshold,
            filter_mode = filter_mode,
            adjusted_p = isTRUE(input$corr_adjust_p),
            max_edges = input$corr_max_edges %||% 100,
            dataset_pair = c(pick_from, pick_to),
            dataset_labels = dataset_labels,
            edge_list = edge_list,
            edge_list_full = edge_list_all,
            node_list = node_list
          )
          
        } else if (input$integration_method == "mofa") {
          incProgress(0.3, detail = "Running MOFA...")
          
          # Check if MOFA2 is installed
          if (!requireNamespace("MOFA2", quietly = TRUE)) {
            showNotification("MOFA2 package not installed. Install with: BiocManager::install('MOFA2')",
                             type = "error", duration = 10)
            return(NULL)
          }
          
          # Prepare data for MOFA (features x samples)
          # data_list already contains properly filtered data (transposed to samples x features)
          # We need to convert it back to features x samples format for MOFA
          mofa_data <- list()
          feature_name_map <- list()
          
          for (i in seq_along(data_list)) {
            dataset_name <- names(data_list)[i]
            # data_list contains samples x features, MOFA needs features x samples
            mofa_matrix <- t(data_list[[i]])
            
            # Choose display feature names (what we want shown on plots)
            feature_display_names <- colnames(data_list[[i]])
            if (has_loaded && dataset_name %in% names(multiomics$loaded_analyses)) {
              analysis_obj <- multiomics$loaded_analyses[[dataset_name]]
              if (!is.null(analysis_obj$cleaned_molecules) &&
                  length(analysis_obj$cleaned_molecules) == nrow(mofa_matrix) &&
                  !all(is.na(analysis_obj$cleaned_molecules))) {
                feature_display_names <- analysis_obj$cleaned_molecules
              } else if (!is.null(analysis_obj$accession_ids) &&
                         length(analysis_obj$accession_ids) == nrow(mofa_matrix) &&
                         !all(is.na(analysis_obj$accession_ids))) {
                feature_display_names <- analysis_obj$accession_ids
              } else if (!is.null(analysis_obj$features) &&
                         length(analysis_obj$features) == nrow(mofa_matrix) &&
                         !all(is.na(analysis_obj$features))) {
                feature_display_names <- analysis_obj$features
              } else if (!is.null(analysis_obj$data) && !is.null(rownames(analysis_obj$data))) {
                feature_display_names <- rownames(analysis_obj$data)
              }

              # If feature labels look like plain numeric indices (e.g., "1", "2", ...),
              # attempt to map them back to the saved feature name vectors by index.
              # This commonly happens when the feature axis is stored as 1..p IDs.
              feature_display_names_chr <- as.character(feature_display_names)
              if (length(feature_display_names_chr) == nrow(mofa_matrix) &&
                  all(grepl("^\\d+$", feature_display_names_chr))) {
                idx <- suppressWarnings(as.integer(feature_display_names_chr))
                if (!anyNA(idx) && min(idx) >= 1) {
                  map_by_index <- function(vec) {
                    if (is.null(vec) || length(vec) == 0 || all(is.na(vec))) return(NULL)
                    if (max(idx) > length(vec)) return(NULL)
                    out <- as.character(vec[idx])
                    if (length(out) != length(idx) || all(is.na(out))) return(NULL)
                    out
                  }

                  mapped <- map_by_index(analysis_obj$cleaned_molecules)
                  if (is.null(mapped)) mapped <- map_by_index(analysis_obj$accession_ids)
                  if (is.null(mapped)) mapped <- map_by_index(analysis_obj$features)

                  if (!is.null(mapped)) {
                    feature_display_names <- mapped
                  }
                }
              }
            }

            # Sanitize + ensure unique feature IDs for MOFA
            feature_display_names <- as.character(feature_display_names)
            if (is.null(feature_display_names) || length(feature_display_names) == 0) {
              feature_display_names <- paste0("Feature_", seq_len(nrow(mofa_matrix)))
            }
            bad_idx <- is.na(feature_display_names) | feature_display_names == ""
            if (any(bad_idx)) {
              feature_display_names[bad_idx] <- paste0("Feature_", which(bad_idx))
            }

            # Strip any trailing view suffix from display names using the actual MOFA view names.
            # This is more stable than broad regex and handles cases like "_CSF GPs" or "_TBI Serum GPs".
            feature_display_names_clean <- strip_mofa_view_suffix(feature_display_names, names(data_list))

            feature_ids <- make.unique(feature_display_names_clean)
            rownames(mofa_matrix) <- feature_ids

            # Store mapping: MOFA feature IDs -> display names
            feature_name_map[[dataset_name]] <- data.frame(
              Feature_full = feature_ids,
              Feature = feature_display_names_clean,
              stringsAsFactors = FALSE
            )
            
            # Ensure sample names (column names) are properly set
            sample_names <- rownames(data_list[[i]])
            if (is.null(sample_names) || any(is.na(sample_names)) || length(sample_names) == 0) {
              sample_names <- common_samples
            }
            colnames(mofa_matrix) <- sample_names
            
            mofa_data[[dataset_name]] <- mofa_matrix
          }
          
          # Validate mofa_data before creating MOFA object
          mofa_validation_errors <- character(0)
          
          for (view_name in names(mofa_data)) {
            view_data <- mofa_data[[view_name]]
            
            # Check dimensions
            if (nrow(view_data) == 0) {
              mofa_validation_errors <- c(mofa_validation_errors, 
                paste0("View '", view_name, "' has no features"))
            }
            if (ncol(view_data) == 0) {
              mofa_validation_errors <- c(mofa_validation_errors, 
                paste0("View '", view_name, "' has no samples"))
            }
            
            # Note: MOFA naturally handles missing values (NaN/NA) by ignoring them from the likelihood
            # No imputation step is performed. Matrix factorisation models are robust to missing values.
            # Therefore, we do NOT validate for NAs - they are expected and handled by MOFA.
            
            if (any(is.infinite(view_data))) {
              inf_count <- sum(is.infinite(view_data))
              mofa_validation_errors <- c(mofa_validation_errors, 
                paste0("View '", view_name, "' contains ", inf_count, " infinite values"))
            }
            
            # Check if all values are the same (no variance)
            if (nrow(view_data) > 0 && ncol(view_data) > 0) {
              view_var <- var(as.vector(view_data), na.rm = TRUE)
              if (is.na(view_var) || view_var == 0) {
                mofa_validation_errors <- c(mofa_validation_errors, 
                  paste0("View '", view_name, "' has zero variance (all values may be identical)"))
              }
            }
            
            # Warn if dimensions are very small
            if (nrow(view_data) < 10) {
              mofa_validation_errors <- c(mofa_validation_errors, 
                paste0("View '", view_name, "' has only ", nrow(view_data), " features (recommended: >= 10)"))
            }
            if (ncol(view_data) < 10) {
              mofa_validation_errors <- c(mofa_validation_errors, 
                paste0("View '", view_name, "' has only ", ncol(view_data), " samples (recommended: >= 10)"))
            }
          }
          
          # Report validation errors if any
          if (length(mofa_validation_errors) > 0) {
            error_msg <- paste("Data validation issues found:\n",
                               paste("• ", mofa_validation_errors, collapse = "\n"))
            showNotification(HTML(error_msg),
                             type = "error",
                             duration = 12,
                             closeButton = TRUE)
            return(NULL)
          }
          
          # Create MOFA object
          mofa_object <- tryCatch({
            MOFA2::create_mofa(mofa_data)
          }, error = function(e) {
            showNotification(
              paste0("Failed to create MOFA object: ", e$message),
              type = "error",
              duration = 10
            )
            return(NULL)
          })
          
          if (is.null(mofa_object)) {
            return(NULL)
          }

          # MOFA2 v1.20.0 does not export add_samples_metadata(); use samples_metadata<- instead
          merge_mofa_samples_metadata <- function(object, new_metadata_df, sample_order) {
            if (is.null(new_metadata_df) || nrow(new_metadata_df) == 0) return(object)

            current <- tryCatch(MOFA2::samples_metadata(object), error = function(e) NULL)
            if (is.null(current) || nrow(current) == 0) {
              current <- data.frame(sample = sample_order, stringsAsFactors = FALSE)
            }

            if (!"sample" %in% colnames(current)) {
              current$sample <- if (!is.null(rownames(current)) && all(nzchar(rownames(current)))) rownames(current) else sample_order
            }

            if (!"sample" %in% colnames(new_metadata_df)) {
              stop("Sample metadata must include a 'sample' column")
            }

            # Update/append columns without changing row count/order.
            # This avoids dimension mismatches when the model already has an internal samples table.
            new_metadata_df <- as.data.frame(new_metadata_df, stringsAsFactors = FALSE)
            new_metadata_df <- new_metadata_df[!is.na(new_metadata_df$sample) & nzchar(new_metadata_df$sample), , drop = FALSE]
            if (any(duplicated(new_metadata_df$sample))) {
              new_metadata_df <- new_metadata_df[!duplicated(new_metadata_df$sample), , drop = FALSE]
            }

            match_idx <- match(current$sample, new_metadata_df$sample)
            cols_to_add <- setdiff(colnames(new_metadata_df), c("sample"))
            for (col_name in cols_to_add) {
              current[[col_name]] <- new_metadata_df[[col_name]][match_idx]
            }

            MOFA2::samples_metadata(object) <- current
            object
          }
          
          # Verify that feature names and view names are properly set
          cat("MOFA object created with views:", paste(MOFA2::views_names(mofa_object), collapse = ", "), "\n")
          feature_names_check <- MOFA2::features_names(mofa_object)
          for (view in names(feature_names_check)) {
            cat("View:", view, "- Number of features:", length(feature_names_check[[view]]),
                "- First 5 features:", paste(head(feature_names_check[[view]], 5), collapse = ", "), "\n")
          }
          
          # Add samples metadata (groups/covariates) if metadata was uploaded
          if (!is.null(mofa_metadata$data)) {
            selected_group_col <- mofa_metadata$group_col_name %||% ""
            group_values <- if (!is.na(mofa_metadata$group_col_name) &&
                                  mofa_metadata$group_col_name %in% colnames(mofa_metadata$data)) {
              mofa_metadata$data[[mofa_metadata$group_col_name]]
            } else {
              NULL
            }

            if (nzchar(selected_group_col) && !is.null(group_values)) {
              incProgress(0.35, detail = "Adding group information...")

              sample_names <- colnames(mofa_data[[1]])
              metadata_samples <- mofa_metadata$data$SampleID
              sample_align_idx <- match(sample_names, metadata_samples)
              if (any(is.na(sample_align_idx))) {
                showNotification("MOFA metadata: Some samples were not found in the metadata; grouping labels align only to matches.",
                                 type = "warning", duration = 6)
              }
              aligned_groups <- group_values[sample_align_idx]

              if (!is.null(input$mofa_multi_group) && input$mofa_multi_group) {
                usable_levels <- unique(aligned_groups[!is.na(aligned_groups) & nzchar(aligned_groups)])
                selected_levels <- input$mofa_selected_group_levels %||% usable_levels
                selected_levels <- intersect(usable_levels, selected_levels)
                if (length(selected_levels) == 0) {
                  selected_levels <- usable_levels
                }
                if (length(selected_levels) > 0) {
                  metadata_df <- data.frame(sample = sample_names, stringsAsFactors = FALSE)
                  for (group_val in selected_levels) {
                    suffix <- gsub("[^A-Za-z0-9_]+", "_", as.character(group_val))
                    suffix <- gsub("_+", "_", suffix)
                    suffix <- gsub("^_+|_+$", "", suffix)
                    if (suffix == "") suffix <- "level"
                    col_name <- paste0(selected_group_col, "_", suffix)
                    metadata_df[[col_name]] <- ifelse(aligned_groups == group_val, group_val, "Other")
                  }
                  if (ncol(metadata_df) > 1) {
                    mofa_object <- merge_mofa_samples_metadata(mofa_object, metadata_df, colnames(mofa_data[[1]]))
                    showNotification("Multi-group MOFA: Added selected group levels as columns", type = "message", duration = 4)
                  }
                }
              } else {
                if (!is.null(aligned_groups) && length(aligned_groups) == length(sample_names)) {
                  metadata_df <- data.frame(
                    sample = sample_names,
                    group = aligned_groups,
                    stringsAsFactors = FALSE
                  )
                  colnames(metadata_df)[2] <- selected_group_col
                  mofa_object <- merge_mofa_samples_metadata(mofa_object, metadata_df, colnames(mofa_data[[1]]))
                }
              }
            }

            # Always add covariates if present (so MOFA2::correlate_factors_with_covariates can use them)
            if (!is.null(mofa_metadata$covariates) && ncol(mofa_metadata$covariates) > 0) {
              sample_ids <- colnames(mofa_data[[1]])
              cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
              cov_df$sample <- mofa_metadata$data$SampleID
              cov_df <- cov_df[match(sample_ids, cov_df$sample), , drop = FALSE]
              cov_df$sample <- sample_ids
              mofa_object <- merge_mofa_samples_metadata(mofa_object, cov_df, colnames(mofa_data[[1]]))
            }
          }
          
          # Get and set data options (following Bioconductor example)
          incProgress(0.4, detail = "Setting MOFA data options...")
          data_opts <- MOFA2::get_default_data_options(mofa_object)
          # Apply scaling setting if specified - use scale_views not scale_features
          if (!is.null(input$mofa_scale_views) && input$mofa_scale_views) {
            data_opts$scale_views <- TRUE
          } else {
            data_opts$scale_views <- FALSE
          }
          # Set center_groups if needed (default is FALSE for single group)
          data_opts$center_groups <- FALSE
          
          # Get and set model options
          model_opts <- MOFA2::get_default_model_options(mofa_object)
          model_opts$num_factors <- input$mofa_nfactors
          
          # Set sparsity options (only set if explicitly provided)
          if (!is.null(input$mofa_spikeslab_weights)) {
            model_opts$spikeslab_weights <- input$mofa_spikeslab_weights
          }
          
          # Set ARD (Automatic Relevance Determination) options (only set if explicitly provided)
          if (!is.null(input$mofa_ard_factors)) {
            model_opts$ard_factors <- input$mofa_ard_factors
          }
          
          if (!is.null(input$mofa_ard_weights)) {
            model_opts$ard_weights <- input$mofa_ard_weights
          }
          
          # Set likelihoods option (only override defaults if user specifies)
          if (!is.null(input$mofa_likelihoods) && input$mofa_likelihoods != "auto") {
            # Create a named character vector for likelihoods per view
            view_names <- MOFA2::views_names(mofa_object)
            model_opts$likelihoods <- setNames(
              rep(input$mofa_likelihoods, length(view_names)),
              view_names
            )
          }
          
          # Get and set training options with user inputs
          incProgress(0.5, detail = "Setting training parameters...")
          train_opts <- MOFA2::get_default_training_options(mofa_object)
          train_opts$maxiter <- input$mofa_maxiter
          train_opts$convergence_mode <- "fast"  # Use "fast" convergence mode
          train_opts$verbose <- FALSE
          # Use seed from advanced options if available, otherwise default to 42
          train_opts$seed <- if (!is.null(input$mofa_seed)) input$mofa_seed else 42
          
          # Apply drop non-informative factors setting
          if (!is.null(input$mofa_drop_factors) && input$mofa_drop_factors) {
            # Use the drop_factor_threshold value
            threshold_val <- if (!is.null(input$mofa_drop_factor_threshold)) {
              input$mofa_drop_factor_threshold
            } else {
              0.05  # Default threshold
            }
            train_opts$drop_factor_threshold <- threshold_val
          } else {
            train_opts$drop_factor_threshold <- -1  # Disable dropping
          }
          
          # Prepare MOFA object with all options and capture warnings
          incProgress(0.55, detail = "Preparing MOFA model...")
          
          # Capture warnings during prepare_mofa
          prepare_warnings <- character(0)
          prepare_error_msg <- NULL
          
          mofa_object <- tryCatch({
            withCallingHandlers(
              MOFA2::prepare_mofa(
                object = mofa_object,
                data_options = data_opts,
                model_options = model_opts,
                training_options = train_opts
              ),
              warning = function(w) {
                prepare_warnings <<- c(prepare_warnings, conditionMessage(w))
                invokeRestart("muffleWarning")
              }
            )
          }, error = function(e) {
            prepare_error_msg <<- e$message
            message("MOFA preparation error: ", e$message)
            return(NULL)
          })
          
          # Check for preparation errors
          if (is.null(mofa_object)) {
            if (!is.null(prepare_error_msg)) {
              showNotification(
                paste0("MOFA model preparation failed: ", prepare_error_msg),
                type = "error",
                duration = 10
              )
            } else {
              showNotification("MOFA model preparation failed. Check your data and settings.", type = "error")
            }
            return(NULL)
          }
          
          # Show prepare warnings if any
          if (length(prepare_warnings) > 0) {
            warning_msg <- paste("MOFA Model Preparation Warnings:\n",
                                 paste("• ", prepare_warnings, collapse = "\n"))
            showNotification(HTML(warning_msg),
                             type = "warning",
                             duration = 8,
                             closeButton = TRUE)
          }
          
          incProgress(0.6, detail = "Training MOFA model...")
          
          # Before training, ensure mofapy2 is available in Python
          incProgress(0.65, detail = "Checking Python dependencies...")
          python_check_msg <- NULL
          mofapy2_installed <- FALSE
          
          tryCatch({
            # Check if reticulate and required packages are available
            if (!requireNamespace("reticulate", quietly = TRUE)) {
              python_check_msg <- "reticulate package not found. Cannot configure Python."
            } else {
              # Try to detect and configure Python
              tryCatch({
                reticulate::py_config()  # Get current Python config
              }, error = function(e) {
                cat("Python config check: ", e$message, "\n")
              })
              
              # Check if mofapy2 is available - only install if NOT found
              mofapy2_available <- tryCatch({
                reticulate::py_module_available("mofapy2")
              }, error = function(e) {
                FALSE  # If check fails, assume not available
              })
              
              if (mofapy2_available) {
                cat("mofapy2 is available in Python, skipping installation.\n")
                mofapy2_installed <<- TRUE
              } else {
                # mofapy2 not found, attempt installation
                cat("mofapy2 not detected, attempting installation...\n")
                incProgress(0.67, detail = "Installing Python package mofapy2...")
                
                # Try to install mofapy2 using pip
                tryCatch({
                  cat("Attempting to install mofapy2==0.7.2 via pip...\n")
                  reticulate::py_install("mofapy2==0.7.2", pip = TRUE, ignore_installed = FALSE)
                  cat("mofapy2 installed successfully\n")
                  mofapy2_installed <<- TRUE
                }, error = function(e2) {
                  python_check_msg <<- paste0("Could not install mofapy2: ", e2$message)
                  cat(python_check_msg, "\n")
                })
              }
            }
          }, error = function(e) {
            cat("Python dependency check error: ", e$message, "\n")
          })
          
          # Prepare output filename for MOFA model
          output_file <- NULL
          if (!is.null(input$mofa_output_filename) && nchar(input$mofa_output_filename) > 0) {
            # User provided a filename
            output_file <- input$mofa_output_filename
            # Ensure it has .hdf5 extension
            if (!grepl("\\.hdf5$", output_file)) {
              output_file <- paste0(output_file, ".hdf5")
            }
          }
          
          # Capture warnings during run_mofa
          training_warnings <- character(0)
          training_error_msg <- NULL
          basilisk_failed <- FALSE
          
          mofa_model <- withCallingHandlers(
            tryCatch({
              # First, try with basilisk (isolated Python environment)
              cat("Attempting MOFA training with basilisk...\n")
              if (!is.null(output_file)) {
                MOFA2::run_mofa(mofa_object, outfile = output_file, use_basilisk = TRUE)
              } else {
                MOFA2::run_mofa(mofa_object, use_basilisk = TRUE)
              }
            }, error = function(e) {
              # If basilisk fails, try without it (use system Python)
              cat("Basilisk failed, attempting MOFA training without basilisk...\n")
              training_error_msg <<- e$message
              basilisk_failed <<- TRUE
              
              tryCatch({
                if (!is.null(output_file)) {
                  MOFA2::run_mofa(mofa_object, outfile = output_file, use_basilisk = FALSE)
                } else {
                  MOFA2::run_mofa(mofa_object, use_basilisk = FALSE)
                }
              }, error = function(e2) {
                training_error_msg <<- paste0(
                  "Failed with basilisk: ", e$message, "\n",
                  "Failed without basilisk: ", e2$message
                )
                message("MOFA training error: ", training_error_msg)
                return(NULL)
              })
            }),
            warning = function(w) {
              training_warnings <<- c(training_warnings, conditionMessage(w))
              invokeRestart("muffleWarning")
            }
          )
          
          # Show training warnings if any
          if (length(training_warnings) > 0) {
            warning_msg <- paste("MOFA Training Warnings:\n",
                                 paste("• ", training_warnings, collapse = "\n"))
            showNotification(HTML(warning_msg),
                             type = "warning",
                             duration = 8,
                             closeButton = TRUE)
          }
          
          # If basilisk was used successfully, show info message
          if (!is.null(mofa_model) && !basilisk_failed) {
            showNotification(
              "MOFA model trained successfully using isolated Python environment (basilisk).",
              type = "message",
              duration = 5
            )
          } else if (!is.null(mofa_model) && basilisk_failed) {
            showNotification(
              HTML("MOFA model trained successfully using system Python.<br/>Note: Basilisk environment setup failed, but system Python is working fine."),
              type = "message",
              duration = 6
            )
          }
          
          if (is.null(mofa_model)) {
            if (!is.null(training_error_msg)) {
              # Check if error is about missing mofapy2 and provide helpful guidance
              if (grepl("mofapy2", training_error_msg, ignore.case = TRUE)) {
                error_detail <- paste0(
                  "Python dependency 'mofapy2' is not available.<br/><br/>",
                  "<strong>To fix this:</strong><br/>",
                  "1. In R console, run: <code>reticulate::py_install('mofapy2==0.7.2')</code><br/>",
                  "2. Or install via command line: <code>pip install mofapy2==0.7.2</code><br/>",
                  "3. Then try MOFA training again.<br/><br/>",
                  "<strong>Error details:</strong><br/>", training_error_msg
                )
              } else {
                error_detail <- paste0("MOFA model training failed:<br/>", training_error_msg)
              }
              
              showNotification(
                HTML(error_detail),
                type = "error",
                duration = 15,
                closeButton = TRUE
              )
            } else {
              showNotification("MOFA model training failed. Please check your input data.", type = "error")
            }
            return(NULL)
          }
          
          # Verify and restore feature names and view names after training
          cat("Verifying feature names and view names after training...\n")
          trained_views <- MOFA2::views_names(mofa_model)
          cat("Trained model views:", paste(trained_views, collapse = ", "), "\n")
          
          trained_features <- MOFA2::features_names(mofa_model)
          for (view in names(trained_features)) {
            cat("View:", view, "- Features:", length(trained_features[[view]]),
                "- First 5:", paste(head(trained_features[[view]], 5), collapse = ", "), "\n")
          }
          
          # If feature names are missing or generic, restore them from mofa_data
          needs_restoration <- FALSE
          for (view in names(trained_features)) {
            if (is.null(trained_features[[view]]) ||
                all(grepl("^feature_[0-9]+$", trained_features[[view]], ignore.case = TRUE))) {
              needs_restoration <- TRUE
              break
            }
          }
          
          if (needs_restoration) {
            cat("Restoring feature names from original data...\n")
            # Restore feature names from mofa_data
            restored_features <- lapply(names(mofa_data), function(view) {
              rownames(mofa_data[[view]])
            })
            names(restored_features) <- names(mofa_data)
            MOFA2::features_names(mofa_model) <- restored_features
            cat("Feature names restored successfully.\n")
          }
          
          incProgress(0.8, detail = "Extracting results...")
          
          # Extract factors (samples x factors)
          factors <- MOFA2::get_factors(mofa_model, factors = "all")
          if (is.null(factors) || length(factors) == 0) {
            showNotification("Failed to extract factors from MOFA model.", type = "error")
            return(NULL)
          }
          
          factors_df <- as.data.frame(factors[[1]])
          colnames(factors_df) <- paste0("Factor", 1:ncol(factors_df))
          factors_df$Sample <- rownames(factors_df)
          
          # Extract weights (features x factors for each view)
          weights_list <- list()
          views <- names(mofa_data)
          for (view in views) {
            weights <- MOFA2::get_weights(mofa_model, views = view, factors = "all")
            if (!is.null(weights) && length(weights) > 0) {
              # MOFA2::get_weights returns a list of matrices (D x K). With views=view it is typically a
              # length-1 list; indexing a matrix with [[ ]] collapses to a scalar.
              weights_mat <- if (is.list(weights)) weights[[1]] else weights
              weights_df <- as.data.frame(weights_mat)
              colnames(weights_df) <- paste0("Factor", 1:ncol(weights_df))
              feature_ids <- rownames(weights_df)
              if (is.null(feature_ids) || length(feature_ids) != nrow(weights_df)) {
                feature_ids <- rownames(mofa_data[[view]])
              }

              display_feature_names <- feature_ids
              if (!is.null(feature_name_map[[view]])) {
                map_df <- feature_name_map[[view]]
                idx <- match(feature_ids, map_df$Feature_full)
                display_feature_names <- ifelse(!is.na(idx), map_df$Feature[idx], feature_ids)
              }

              weights_df$Feature_full <- feature_ids
              weights_df$Feature <- display_feature_names
              weights_df$View <- view
              weights_list[[view]] <- weights_df
            }
          }
          
          # Calculate variance explained with error handling
          incProgress(0.85, detail = "Calculating variance explained...")
          r2_total <- tryCatch({
            MOFA2::calculate_variance_explained(mofa_model)
          }, error = function(e) {
            message("Variance explained calculation error: ", e$message)
            return(NULL)
          })
          
          r2_per_factor <- NULL
          if (!is.null(r2_total) && !is.null(r2_total$r2_per_factor)) {
            r2_per_factor <- r2_total$r2_per_factor[[1]]
          }

          r2_per_view <- NULL
          if (!is.null(r2_total) && !is.null(r2_total$r2_per_view)) {
            r2_per_view <- if (is.list(r2_total$r2_per_view)) r2_total$r2_per_view[[1]] else r2_total$r2_per_view
          } else if (!is.null(r2_total) && !is.null(r2_total$r2_total)) {
            # Some MOFA2 versions expose totals under a different name
            r2_per_view <- if (is.list(r2_total$r2_total)) r2_total$r2_total[[1]] else r2_total$r2_total
          }
          
          # Get top features per factor
          top_features_list <- list()
          n_factors <- min(input$mofa_nfactors, ncol(factors_df) - 1)
          for (factor_idx in 1:n_factors) {
            top_features <- list()
            for (view in views) {
              if (view %in% names(weights_list)) {
                weights_view <- weights_list[[view]]
                factor_col <- paste0("Factor", factor_idx)
                
                if (factor_col %in% colnames(weights_view)) {
                  top_view <- weights_view %>%
                    arrange(desc(abs(.data[[factor_col]]))) %>%
                    head(20) %>%
                    dplyr::select(Feature_full, Feature, Weight = all_of(factor_col), View)
                  
                  top_features[[view]] <- top_view
                }
              }
            }
            if (length(top_features) > 0) {
              top_features_list[[paste0("Factor", factor_idx)]] <- top_features
            }
          }
          
          incProgress(0.95, detail = "Finalizing results...")
          
          list(
            method = "mofa",
            mofa_model = mofa_model,
            model = mofa_model,
            factors = factors_df,
            weights = weights_list,
            feature_name_map = feature_name_map,
            variance_explained = r2_per_factor,
            variance_explained_total_view = r2_per_view,
            variance_explained_details = r2_total,
            top_features = top_features_list,
            views = views,
            common_samples = common_samples,
            data_options = data_opts,
            model_options = model_opts,
            training_options = train_opts
          )
          
        } else if (input$integration_method == "diablo") {
          incProgress(0.3, detail = "Running DIABLO...")
          
          # Validate group variable - check if metadata has the selected column
          if (!is.null(input$diablo_group_var) && input$diablo_group_var != "") {
            if (is.null(multiomics$sample_metadata) ||
                !input$diablo_group_var %in% colnames(multiomics$sample_metadata)) {
              available_vars <- if (!is.null(multiomics$sample_metadata)) {
                paste(colnames(multiomics$sample_metadata), collapse = ", ")
              } else {
                "No metadata available"
              }
              showNotification(
                paste0("Grouping variable '", input$diablo_group_var, "' not found in metadata. ",
                       "Available variables: ", available_vars),
                type = "error", duration = 10
              )
              return(NULL)
            }
            
            # Extract group vector from metadata
            group_col_idx <- match(input$diablo_group_var, colnames(multiomics$sample_metadata))
            Y <- factor(multiomics$sample_metadata[, group_col_idx])
            names(Y) <- rownames(multiomics$sample_metadata)
          } else {
            # No group variable selected - create dummy groups
            n_samples <- length(multiomics$common_samples)
            n_groups <- min(3, n_samples / 2)  # Ensure at least 2 samples per group
            if (n_groups < 2) n_groups <- 2
            Y <- factor(rep(paste0("Group_", 1:n_groups), length.out = n_samples))
            names(Y) <- multiomics$common_samples
            
            showNotification(
              "No grouping variable selected. Using demo groupings for illustration.",
              type = "warning", duration = 5
            )
          }
          
          # Validate that Y has the right length
          if (is.null(Y) || length(Y) != length(multiomics$common_samples)) {
            showNotification(
              "Error: Group vector length does not match number of samples",
              type = "error", duration = 10
            )
            return(NULL)
          }
          
          incProgress(0.4, detail = "Preparing data blocks...")
          
          # Prepare data blocks (samples in rows, features in columns)
          X_list <- data_list
          
          # Ensure all samples match Y (by rowname)
          for (i in seq_along(X_list)) {
            sample_order <- match(names(Y), rownames(X_list[[i]]))
            if (any(is.na(sample_order))) {
              showNotification(
                "Error: Sample names don't match between groups and data",
                type = "error", duration = 10
              )
              return(NULL)
            }
            X_list[[i]] <- X_list[[i]][sample_order, , drop = FALSE]
          }
          
          incProgress(0.5, detail = "Setting up DIABLO tutorial framework...")
          
          # Instead of running full DIABLO, use the tutorial framework
          # For real data, keep tutorial mode off and store results under integration_results
          diablo_tutorial$active <- FALSE
          diablo_tutorial$data <- NULL
          diablo_tutorial$Y <- NULL
          
          # Create default design matrix for real data
          n_blocks <- length(X_list)
          design <- matrix(1, ncol = n_blocks, nrow = n_blocks, dimnames = list(names(X_list), names(X_list)))
          diag(design) <- 0
          
          incProgress(0.8, detail = "Computing pairwise correlations...")
          
          # The pairwise PLS correlations will be computed in the diablo_tutorial reactive
          
          list(
            method = "diablo",
            data = X_list,
            Y = Y,
            design = design,
            message = "DIABLO integration completed using pairwise PLS correlations"
          )
          
        } else if (input$integration_method == "pathway") {
          # ===== PATHWAY-LEVEL INTEGRATION (Using Saved Enrichments) =====
          incProgress(0.1, detail = "Loading saved enrichment results...")
          
          # Get concordance parameters from UI
          pathway_pval <- input$pathway_pval %||% 0.05
          pathway_concordance <- input$pathway_concordance %||% TRUE
          pathway_min_datasets <- input$pathway_min_datasets %||% 2
          pathway_combine_method <- input$pathway_combine_method %||% "fisher"
          pathway_direction_aware <- input$pathway_direction_aware %||% FALSE
          
          # Get selected enrichment datasets
          selected_enrichments <- input$pathway_selected_enrichments
          
          if (is.null(selected_enrichments) || length(selected_enrichments) < 2) {
            showNotification("Please select at least 2 enrichment datasets for pathway integration.", type = "error")
            return(list(method = "pathway", error = "Insufficient enrichment datasets selected"))
          }
          
          # Helper function to calculate combined p-value (concordance)
          combine_pvalues <- function(pvals, method = "fisher") {
            pvals <- pvals[!is.na(pvals) & pvals > 0 & pvals <= 1]
            if (length(pvals) == 0) return(NA)
            if (length(pvals) == 1) return(pvals)
            
            switch(method,
              "fisher" = {
                # Fisher's combined probability test
                chi_stat <- -2 * sum(log(pvals))
                df <- 2 * length(pvals)
                1 - pchisq(chi_stat, df)
              },
              "stouffer" = {
                # Stouffer's Z-score method
                z_scores <- qnorm(1 - pvals)
                combined_z <- sum(z_scores) / sqrt(length(z_scores))
                1 - pnorm(combined_z)
              },
              "min_p" = {
                # Minimum p-value (most conservative)
                min(pvals)
              },
              min(pvals)  # Default to min
            )
          }
          
          incProgress(0.2, detail = "Extracting enrichment results...")
          
          # Collect enrichment results from selected datasets
          enrichment_results <- list()
          fold_change_data <- list()
          
          for (enr_name in selected_enrichments) {
            # Try session enrichments first, then loaded analyses
            enr_obj <- multiomics$loaded_enrichments[[enr_name]] %||% multiomics$loaded_analyses[[enr_name]]
            
            if (is.null(enr_obj)) {
              showNotification(paste0("Enrichment '", enr_name, "' not found."), type = "warning")
              next
            }
            
            # Extract the results table
            results_table <- NULL
            if (!is.null(enr_obj$results)) {
              if (!is.null(enr_obj$results$table)) {
                results_table <- enr_obj$results$table
              } else if (is.data.frame(enr_obj$results)) {
                results_table <- enr_obj$results
              } else if (inherits(enr_obj$results, "enrichResult")) {
                results_table <- as.data.frame(enr_obj$results)
              }
            }
            
            if (is.null(results_table) || nrow(results_table) == 0) {
              showNotification(paste0("Enrichment '", enr_name, "' has no results."), type = "warning")
              next
            }
            
            # Standardize column names for different enrichment tools
            results_table <- standardize_enrichment_columns(results_table)
            
            # Add dataset identifier
            results_table$Dataset <- enr_name
            enrichment_results[[enr_name]] <- results_table
            
            # Store fold change data if available
            if (!is.null(enr_obj$fold_change_data)) {
              fold_change_data[[enr_name]] <- enr_obj$fold_change_data
            }
          }
          
          # Check if we have enough results
          valid_results <- enrichment_results[!sapply(enrichment_results, is.null)]
          
          if (length(valid_results) < 2) {
            showNotification("Need at least 2 valid enrichment datasets for concordance analysis.", 
                             type = "error", duration = 8)
            return(list(
              method = "pathway",
              enrichment_results = list(),
              error = "Insufficient valid enrichment results"
            ))
          }
          
          incProgress(0.5, detail = "Calculating pathway concordance...")
          
          # Combine all enrichment results
          all_enrichments <- do.call(rbind, lapply(valid_results, function(x) {
            # Ensure required columns exist
            if (!"ID" %in% colnames(x)) {
              if ("term_id" %in% colnames(x)) x$ID <- x$term_id
              else if ("GO.ID" %in% colnames(x)) x$ID <- x$GO.ID
              else if ("Term" %in% colnames(x)) x$ID <- x$Term
              else x$ID <- rownames(x)
            }
            if (!"Description" %in% colnames(x)) {
              if ("term_name" %in% colnames(x)) x$Description <- x$term_name
              else if ("Term" %in% colnames(x)) x$Description <- x$Term
              else x$Description <- x$ID
            }
            if (!"pvalue" %in% colnames(x)) {
              if ("p_value" %in% colnames(x)) x$pvalue <- x$p_value
              else if ("PValue" %in% colnames(x)) x$pvalue <- x$PValue
              else if ("p.adjust" %in% colnames(x)) x$pvalue <- x$p.adjust
              else x$pvalue <- 0.05  # fallback
            }
            x
          }))
          
          # Get unique pathways/terms
          all_pathways <- unique(all_enrichments$ID)
          
          # Create pathway matrix (pathways x datasets)
          pathway_pval_matrix <- matrix(NA, nrow = length(all_pathways), ncol = length(valid_results),
                                   dimnames = list(all_pathways, names(valid_results)))
          
          for (ds_name in names(valid_results)) {
            ds_result <- valid_results[[ds_name]]
            for (i in seq_len(nrow(ds_result))) {
              pathway_id <- ds_result$ID[i]
              if (pathway_id %in% rownames(pathway_pval_matrix)) {
                pathway_pval_matrix[pathway_id, ds_name] <- ds_result$pvalue[i]
              }
            }
          }
          
          # ===== DIRECTION-AWARE ANALYSIS =====
          pathway_direction_matrix <- NULL
          direction_stats <- NULL
          
          if (pathway_direction_aware && length(fold_change_data) > 0) {
            incProgress(0.6, detail = "Calculating pathway direction scores...")
            
            # Create direction matrix (pathways x datasets)
            pathway_direction_matrix <- matrix(NA, nrow = length(all_pathways), ncol = length(valid_results),
                                               dimnames = list(all_pathways, names(valid_results)))
            
            # For each dataset and pathway, calculate the predominant direction
            for (ds_name in names(valid_results)) {
              ds_result <- valid_results[[ds_name]]
              ds_fc <- fold_change_data[[ds_name]]
              
              if (is.null(ds_fc)) next
              
              for (i in seq_len(nrow(ds_result))) {
                pathway_id <- ds_result$ID[i]
                
                # Get genes in this pathway
                pathway_genes <- NULL
                if ("geneID" %in% colnames(ds_result)) {
                  pathway_genes <- unlist(strsplit(as.character(ds_result$geneID[i]), "/"))
                } else if ("core_enrichment" %in% colnames(ds_result)) {
                  pathway_genes <- unlist(strsplit(as.character(ds_result$core_enrichment[i]), "/"))
                }
                
                if (!is.null(pathway_genes) && length(pathway_genes) > 0) {
                  # Get fold change values for pathway genes
                  gene_fcs <- ds_fc[names(ds_fc) %in% pathway_genes]
                  
                  if (length(gene_fcs) > 0) {
                    dir_score <- mean(sign(gene_fcs), na.rm = TRUE)
                    pathway_direction_matrix[pathway_id, ds_name] <- dir_score
                  }
                }
              }
            }
            
            # Calculate direction concordance statistics
            direction_stats <- data.frame(
              Pathway_ID = all_pathways,
              stringsAsFactors = FALSE
            )
            
            direction_stats$Mean_Direction <- apply(pathway_direction_matrix, 1, function(x) {
              vals <- x[!is.na(x)]
              if (length(vals) == 0) return(NA)
              mean(vals)
            })
            
            direction_stats$Direction_Consistency <- apply(pathway_direction_matrix, 1, function(x) {
              vals <- x[!is.na(x)]
              if (length(vals) < 2) return(NA)
              signs <- sign(vals)
              n_pos <- sum(signs > 0)
              n_neg <- sum(signs < 0)
              max(n_pos, n_neg) / length(vals)
            })
            
            direction_stats$Direction_Label <- sapply(direction_stats$Mean_Direction, function(x) {
              if (is.na(x)) return("Unknown")
              if (x > 0.3) return("Up-regulated")
              if (x < -0.3) return("Down-regulated")
              return("Mixed")
            })
          }
          
          incProgress(0.7, detail = "Computing concordance statistics...")
          
          # Calculate concordance scores
          concordance_results <- data.frame(
            Pathway_ID = all_pathways,
            stringsAsFactors = FALSE
          )
          
          # Add pathway descriptions
          desc_map <- setNames(all_enrichments$Description, all_enrichments$ID)
          concordance_results$Description <- desc_map[concordance_results$Pathway_ID]
          
          # Calculate statistics for each pathway
          concordance_results$N_Datasets <- apply(pathway_pval_matrix, 1, function(x) sum(!is.na(x)))
          concordance_results$N_Significant <- apply(pathway_pval_matrix, 1, function(x) sum(x < pathway_pval, na.rm = TRUE))
          
          # Combined p-values
          concordance_results$Combined_Pvalue <- apply(pathway_pval_matrix, 1, function(x) {
            combine_pvalues(x[!is.na(x)], method = pathway_combine_method)
          })
          
          # Min and max p-values
          concordance_results$Min_Pvalue <- apply(pathway_pval_matrix, 1, function(x) min(x, na.rm = TRUE))
          concordance_results$Max_Pvalue <- apply(pathway_pval_matrix, 1, function(x) max(x, na.rm = TRUE))
          
          # Add direction information if available
          if (!is.null(direction_stats)) {
            concordance_results$Mean_Direction <- direction_stats$Mean_Direction
            concordance_results$Direction_Consistency <- direction_stats$Direction_Consistency
            concordance_results$Direction_Label <- direction_stats$Direction_Label
          }
          
          # Add individual dataset p-values as columns
          for (ds_name in names(valid_results)) {
            col_name <- paste0("Pval_", ds_name)
            concordance_results[[col_name]] <- pathway_pval_matrix[, ds_name]
          }
          
          # Filter for concordant pathways
          concordant_pathways <- concordance_results %>%
            dplyr::filter(N_Datasets >= pathway_min_datasets) %>%
            dplyr::arrange(Combined_Pvalue)
          
          # Adjust combined p-values
          concordant_pathways$Combined_Padj <- p.adjust(concordant_pathways$Combined_Pvalue, method = "BH")
          
          incProgress(0.9, detail = "Preparing results...")
          
          # Get significant concordant pathways
          sig_concordant <- concordant_pathways %>%
            dplyr::filter(Combined_Padj < pathway_pval)
          
          # Prepare summary statistics
          summary_stats <- list(
            total_pathways = length(all_pathways),
            concordant_pathways = nrow(concordant_pathways),
            significant_concordant = nrow(sig_concordant),
            n_datasets = length(valid_results),
            dataset_names = names(valid_results),
            pval_cutoff = pathway_pval,
            min_datasets = pathway_min_datasets,
            combine_method = pathway_combine_method,
            direction_aware = pathway_direction_aware
          )
          
          # Add direction-specific summary if available
          if (pathway_direction_aware && !is.null(direction_stats)) {
            n_up <- sum(sig_concordant$Direction_Label == "Up-regulated", na.rm = TRUE)
            n_down <- sum(sig_concordant$Direction_Label == "Down-regulated", na.rm = TRUE)
            n_mixed <- sum(sig_concordant$Direction_Label == "Mixed", na.rm = TRUE)
            
            summary_stats$direction_summary <- list(
              up_regulated = n_up,
              down_regulated = n_down,
              mixed = n_mixed,
              consistent_direction = n_up + n_down
            )
          }
          
          showNotification(
            paste0("Pathway integration complete: ", summary_stats$significant_concordant,
                   " concordant pathways found across ", summary_stats$n_datasets, " datasets."),
            type = "message", duration = 5
          )
          
          list(
            method = "pathway",
            database = pathway_database,
            organism = pathway_organism,
            conversion_results = conversion_results,
            enrichment_results = valid_results,
            all_enrichments = all_enrichments,
            pathway_pval_matrix = pathway_pval_matrix,
            pathway_direction_matrix = pathway_direction_matrix,
            concordance_results = concordance_results,
            concordant_pathways = concordant_pathways,
            significant_concordant = sig_concordant,
            summary_stats = summary_stats,
            parameters = list(
              pval_cutoff = pathway_pval,
              padj_method = pathway_padj_method,
              min_geneset = pathway_min_gs,
              max_geneset = pathway_max_gs,
              min_datasets = pathway_min_datasets,
              combine_method = pathway_combine_method,
              direction_aware = pathway_direction_aware
            )
          )
        }
      }, error = function(e) {
        showNotification(paste("Integration error:", e$message), type = "error")
        NULL
      })
      
      incProgress(0.9, detail = "Finalizing results...")
      multiomics$integration_results <- result

      # New integration result loaded => require dimred recompute
      multiomics$mofa_dimred_ready <- FALSE
      multiomics$view_dimred <- NULL
      multiomics$mofa_model_dimred <- NULL
      
      incProgress(1, detail = "Complete!")
    })
  })
  
  # ========== INTEGRATION METHOD CARDS UI (Dynamic) ==========
  # Renders method cards with appropriate enabling/disabling based on loaded data
  output$integration_method_cards <- renderUI({
    # Check what types of data are loaded
    n_analyses <- length(multiomics$loaded_analyses)
    n_enrichments <- length(multiomics$loaded_enrichments)
    has_manual <- !is.null(multiomics$dataset1) && !is.null(multiomics$dataset2)
    
    # Count analyses with actual matrix data (for MOFA/DIABLO/Correlation)
    n_data_analyses <- if (length(multiomics$loaded_analyses) > 0) {
      sum(vapply(multiomics$loaded_analyses, function(x) {
        tryCatch({
          !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data))
        }, error = function(e) FALSE)
      }, logical(1)))
    } else {
      0
    }
    
    # Determine if we have data for each method type
    has_matrix_data <- n_data_analyses >= 2 || has_manual
    has_enrichment_data <- n_enrichments >= 2
    
    # Build the method cards
    tagList(
      # MOFA Card
      div(
        class = "integration-method-card",
        id = "method_mofa",
        onclick = "Shiny.setInputValue('integration_method', 'mofa', {priority: 'event'}); scrollToParams();",
        div(class = "method-title",
            icon("project-diagram"), " MOFA - Multi-Omics Factor Analysis"
        ),
        div(class = "method-description",
            "Identifies shared and dataset-specific sources of variation through latent factor analysis. Excellent for exploratory analysis and understanding data structure.",
            if (!has_matrix_data) tags$small(class = "text-danger", tags$br(), icon("exclamation-circle"), " Requires matrix data (load omics datasets)")
        ),
        div(
          span(class = "method-badge badge-unsupervised", "Unsupervised"),
          span(class = "method-badge badge-recommended", "⭐ Recommended")
        )
      ),
      
      # DIABLO Card
      div(
        class = "integration-method-card",
        id = "method_diablo",
        onclick = "Shiny.setInputValue('integration_method', 'diablo', {priority: 'event'}); scrollToParams();",
        div(class = "method-title",
            icon("bullseye"), " DIABLO - Multi-Block PLS-DA"
        ),
        div(class = "method-description",
            "Supervised integration for biomarker discovery. Identifies features that discriminate between groups across multiple datasets simultaneously.",
            if (!has_matrix_data) tags$small(class = "text-danger", tags$br(), icon("exclamation-circle"), " Requires matrix data (load omics datasets)")
        ),
        div(
          span(class = "method-badge badge-supervised", "Supervised"),
          span(class = "method-badge badge-recommended", "⭐ Recommended")
        )
      ),
      
      # Correlation Analysis Card
      div(
        class = "integration-method-card",
        id = "method_correlation",
        onclick = "Shiny.setInputValue('integration_method', 'correlation', {priority: 'event'}); scrollToParams();",
        div(class = "method-title",
            icon("network-wired"), " Cross-Omics Correlation Network"
        ),
        div(class = "method-description",
            "Computes correlations between features across datasets. Creates network visualizations showing inter-layer relationships and identifies highly correlated feature pairs.",
            if (!has_matrix_data) tags$small(class = "text-danger", tags$br(), icon("exclamation-circle"), " Requires matrix data (load omics datasets)")
        ),
        div(
          span(class = "method-badge badge-network", "Network-based"),
          span(class = "method-badge badge-unsupervised", "Unsupervised")
        )
      ),
      
      # Pathway Integration Card
      div(
        class = "integration-method-card",
        id = "method_pathway",
        onclick = "Shiny.setInputValue('integration_method', 'pathway', {priority: 'event'}); scrollToParams();",
        div(class = "method-title",
            icon("route"), " Pathway-Level Integration"
        ),
        div(class = "method-description",
            "Integrates enrichment analysis results from multiple omics datasets. Identifies concordant pathway/term enrichments across datasets.",
            if (n_enrichments >= 2) tags$small(class = "text-success", tags$br(), icon("check-circle"), paste(" ", n_enrichments, " enrichments available")),
            if (n_enrichments < 2) tags$small(class = "text-warning", tags$br(), icon("info-circle"), " Requires saved enrichment results from Enrichment Analysis tab")
        ),
        div(
          span(class = "method-badge badge-network", "Network-based"),
          span(class = "method-badge badge-unsupervised", "Unsupervised")
        )
      )
    )
  })

  outputOptions(output, "integration_method_cards", suspendWhenHidden = FALSE)
  
  # Integration method parameters UI
  output$integration_method_params <- renderUI({
    req(input$integration_method)
    
    switch(input$integration_method,
           "mofa" = {
             tagList(
               h5("MOFA Parameters", style = "font-weight: 600; margin-top: 15px;"),
               
               # Essential parameters
               sliderInput("mofa_nfactors", "Number of Factors:",
                           min = 2, max = 20, value = 10, step = 1, width = "100%"),
               
               numericInput("mofa_maxiter", "Max Iterations:",
                            value = 1000, min = 100, max = 5000, step = 100, width = "100%"),
               
               # Sample metadata for grouping (Optional, for supervised analysis)
               helpText("Sample metadata is loaded from the Multi-Omics tab. Upload metadata files there to enable grouping and covariates for supervised MOFA analysis."),

               # Optional manual column selection (auto-detected defaults will be preselected)
               uiOutput("mofa_metadata_column_select_ui"),
               
               # Choose which grouping to use
               uiOutput("mofa_group_choice_ui"),
               
               br(),

               # Output filename for MOFA model
               textInput("mofa_output_filename", "Output Filename for MOFA Model (Optional):",
                         placeholder = "e.g., mofa_analysis_results.hdf5",
                         width = "100%"),
               helpText("Specify a filename to save the trained MOFA model. If left blank, a temporary file will be used."),
               
               hr(),
               
               # Advanced Options Toggle
               tags$div(
                 style = "margin: 15px 0;",
                 tags$button(
                   id = "mofa_advanced_toggle",
                   class = "btn btn-sm btn-secondary",
                   style = "width: 100%;",
                   HTML("<i class='fa fa-chevron-right'></i> Advanced Options"),
                   onclick = "toggleElement('mofa_advanced_options'); toggleButtonIcon('mofa_advanced_toggle');"
                 )
               ),
               
               # Advanced Options Panel (Hidden by default)
               tags$div(
                 id = "mofa_advanced_options",
                 style = "display: none; padding: 15px; background: #f8f9fa; border-radius: 6px; margin-top: 10px; border-left: 3px solid #667eea;",
                 
                 h6("Data Options", style = "font-weight: 600; margin-bottom: 12px;"),
                 
                 checkboxInput("mofa_scale_views", "Scale views", value = TRUE),
                 helpText("Standardize each omics layer (view) to the same total variance. Prevents high-variance views from dominating the analysis."),
                 
                 br(),
                 br(),
                 
                 checkboxInput("mofa_scale_groups", "Scale groups", value = FALSE),
                 helpText("Scale each biological group to the same total variance. Useful when comparing groups with different variance magnitudes."),
                 
                 br(),
                 br(),
                 
                 h6("Model Options", style = "font-weight: 600; margin-bottom: 12px; margin-top: 15px;"),
                 
                 checkboxInput("mofa_spikeslab_factors", "Spike-slab sparsity on factors", value = FALSE),
                 helpText("Encourages factors to be sparse (load on subset of features). Improves interpretability but can increase training time."),
                 
                 br(),
                 br(),
                 
                 checkboxInput("mofa_spikeslab_weights", "Spike-slab sparsity on weights", value = TRUE),
                 helpText("Encourages each factor to load on few features per view. RECOMMENDED to keep enabled for better interpretability."),
                 
                 br(),
                 br(),
                 
                 checkboxInput("mofa_ard_factors", "ARD prior on factors", value = FALSE),
                 helpText("Use Automatic Relevance Determination (ARD) prior in the factors. Default TRUE when using multiple groups - encourages sparsity in factor loadings."),
                 
                 br(),
                 br(),
                 
                 checkboxInput("mofa_ard_weights", "ARD prior on weights", value = TRUE),
                 helpText("Use Automatic Relevance Determination (ARD) prior in the weights. Default TRUE when using multiple views - encourages sparsity in feature weights."),
                 
                 br(),
                 br(),
                 
                 selectInput("mofa_likelihoods", "Likelihood per view:",
                             choices = c("Auto (recommended)" = "auto",
                                         "Gaussian" = "gaussian",
                                         "Poisson" = "poisson", 
                                         "Bernoulli" = "bernoulli"),
                             selected = "auto",
                             multiple = FALSE,
                             width = "100%"),
                 helpText("Likelihood model per view. 'Auto' infers automatically from data. Override for specific data types (Gaussian: continuous, Poisson: counts, Bernoulli: binary)."),
                 
                 br(),
                 br(),
                 
                 h6("Training Options", style = "font-weight: 600; margin-bottom: 12px; margin-top: 15px;"),
                 
                 selectInput("mofa_convergence_mode", "Convergence Mode:",
                             choices = c("Fast (exploratory)" = "fast", 
                                         "Medium (balanced, default)" = "medium",
                                         "Slow (high precision)" = "slow"),
                             selected = "medium",
                             width = "100%"),
                 helpText("Speed-accuracy tradeoff. Fast: exploratory analysis, Medium: balanced, Slow: publication-quality results."),
                 
                 br(),
                 br(),
                 
                 numericInput("mofa_seed", "Random Seed:",
                              value = 42, min = 1, max = 1000000, step = 1, width = "100%"),
                 helpText("Set seed for reproducible results."),
                 
                 br(),
                 br(),
                 
                 checkboxInput("mofa_drop_factors", "Drop non-informative factors", value = FALSE),
                 helpText("Automatically remove factors with relative variance below threshold during training."),
                 
                 br(),
                 br(),
                 
                 conditionalPanel(
                   condition = "input.mofa_drop_factors == true",
                   sliderInput("mofa_drop_factor_threshold", "Factor Drop Threshold:",
                               min = 0.0001, max = 0.1, value = 0.05, step = 0.001),
                   helpText("Threshold for dropping factors (relative variance explained). Default 0.05 = 5%.")
                 )
               )
             )
           },
           "diablo" = {
             tagList(
               h5("DIABLO Parameters", style = "font-weight: 600; margin-top: 15px;"),
               uiOutput("diablo_grouping_ui")
             )
           },
           "correlation" = {
             tagList(
               h5("Correlation Parameters", style = "font-weight: 600; margin-top: 15px;"),
               selectInput("corr_dataset_from", "Dataset A:", choices = c(), width = "100%"),
               selectInput("corr_dataset_to", "Dataset B:", choices = c(), width = "100%"),
               selectInput("corr_method", "Correlation Method:",
                           choices = c("Pearson" = "pearson",
                                       "Spearman" = "spearman",
                                       "Kendall" = "kendall"),
                           width = "100%"),
               radioButtons("corr_filter_mode", "Edge Direction:",
                            choices = c("Absolute (|r|)" = "absolute",
                                        "Positive only" = "positive",
                                        "Negative only" = "negative"),
                            selected = "absolute", inline = TRUE, width = "100%"),
               sliderInput("corr_threshold", "Correlation Threshold:",
                           min = 0, max = 1, value = 0.7, step = 0.05, width = "100%"),
               sliderInput("corr_pval", "P-value Cutoff:",
                           min = 0.001, max = 0.1, value = 0.05, step = 0.001, width = "100%"),
               checkboxInput("corr_adjust_p", "Adjust p-values (BH/FDR)", value = TRUE, width = "100%"),
               numericInput("corr_top_features", "Top Features per Dataset:",
                            value = 50, min = 10, max = 500, step = 10, width = "100%"),
               sliderInput("corr_max_edges", "Max edges to plot/download:",
                           min = 10, max = 1000, value = 150, step = 10, width = "100%")
             )
           },
           "pathway" = {
             tagList(
               h5("Pathway Integration Settings", style = "font-weight: 600; margin-top: 15px;"),
               
               # Enrichment Data Source section
               div(class = "alert alert-info", style = "padding: 10px; margin-bottom: 15px;",
                   icon("info-circle"), " ",
                   "Pathway integration uses enrichment results saved from the Enrichment Analysis tab."
               ),
               
               h6("Enrichment Data Source", style = "margin-top: 10px; font-weight: 600;"),
               
               # Select enrichment results to use
               uiOutput("pathway_enrichment_source_ui"),
               
               hr(),
               h6("Concordance Settings", style = "margin-top: 10px; font-weight: 600;"),
               
               # Concordance analysis options
               checkboxInput("pathway_concordance", 
                             "Show only concordant pathways", value = TRUE,
                             width = "100%"),
               
               # Minimum datasets for concordance
               conditionalPanel(
                 condition = "input.pathway_concordance",
                 sliderInput("pathway_min_datasets", "Min Datasets for Concordance:",
                             min = 2, max = 5, value = 2, step = 1,
                             width = "100%")
               ),
               
               # Concordance method
               selectInput("pathway_combine_method", "P-value Combination Method:",
                           choices = c("Fisher's Method" = "fisher",
                                       "Stouffer's Method" = "stouffer",
                                       "Minimum P-value" = "min_p"),
                           selected = "fisher",
                           width = "100%"),
               
               # P-value cutoff for significance
               sliderInput("pathway_pval", "Concordance P-value Cutoff:",
                           min = 0.001, max = 0.1, value = 0.05, step = 0.001,
                           width = "100%"),
               
               # Use fold change direction
               checkboxInput("pathway_direction_aware", 
                             "Consider fold-change direction (if available)", 
                             value = FALSE, width = "100%"),
               
               helpText("Direction-aware concordance identifies pathways with coordinated up/down regulation across datasets.",
                        style = "font-size: 0.85em; color: #666;")
             )
           }
    )
  })
  
  # ========== PATHWAY ENRICHMENT SOURCE UI ==========
  # Render the enrichment data source selection for pathway integration
  output$pathway_enrichment_source_ui <- renderUI({
    # Get available enrichment sources
    session_enrichments <- names(multiomics$loaded_enrichments)
    loaded_enrichments <- names(multiomics$loaded_analyses)[
      sapply(multiomics$loaded_analyses, function(x) !is.null(x$type) && x$type == "enrichment")
    ]
    
    all_enrichments <- unique(c(session_enrichments, loaded_enrichments))
    
    if (length(all_enrichments) == 0) {
      # No enrichments available
      tagList(
        div(class = "alert alert-warning", style = "padding: 10px;",
            icon("exclamation-triangle"), " ",
            strong("No enrichment data available."),
            br(), br(),
            "Please either:",
            tags$ul(
              tags$li("Run enrichment analysis in the ", strong("Enrichment Analysis"), " tab and save the results"),
              tags$li("Load an enrichment .oms file in the ", strong("Multi-Omics Data Source"), " section")
            )
        )
      )
    } else {
      # Enrichments available - show selection
      enrichment_choices <- setNames(all_enrichments, sapply(all_enrichments, function(name) {
        # Get details for display
        enr <- multiomics$loaded_enrichments[[name]] %||% multiomics$loaded_analyses[[name]]
        if (!is.null(enr)) {
          omics_type <- enr$omics_type %||% "Unknown"
          tool <- enr$tool %||% "Unknown"
          paste0(name, " (", omics_type, " - ", tool, ")")
        } else {
          name
        }
      }))
      
      tagList(
        checkboxGroupInput("pathway_selected_enrichments", 
                          "Select Enrichment Results to Compare:",
                          choices = enrichment_choices,
                          selected = if (length(all_enrichments) >= 2) all_enrichments[1:min(2, length(all_enrichments))] else all_enrichments,
                          width = "100%"),
        
        # Show summary of selected enrichments
        uiOutput("pathway_selected_enrichments_summary"),
        
        # Validation message
        if (length(all_enrichments) < 2) {
          div(class = "alert alert-warning", style = "padding: 8px; margin-top: 10px;",
              icon("exclamation-triangle"), " ",
              "At least 2 enrichment datasets are required for concordance analysis."
          )
        }
      )
    }
  })
  
  # Render summary of selected enrichments
  output$pathway_selected_enrichments_summary <- renderUI({
    req(input$pathway_selected_enrichments)
    
    if (length(input$pathway_selected_enrichments) < 2) {
      return(div(class = "text-warning", style = "font-size: 0.85em; margin-top: 5px;",
                 icon("info-circle"), " Select at least 2 enrichment datasets for comparison"))
    }
    
    count_enrichment_terms <- function(enr) {
      tryCatch({
        if (!is.null(enr$results$table) && (is.data.frame(enr$results$table) || is.matrix(enr$results$table))) {
          nrow(enr$results$table)
        } else if (!is.null(enr$results$result) && (is.data.frame(enr$results$result) || is.matrix(enr$results$result))) {
          nrow(enr$results$result)
        } else if (!is.null(enr$results$results) && (is.data.frame(enr$results$results) || is.matrix(enr$results$results))) {
          nrow(enr$results$results)
        } else if (!is.null(enr$results) && (is.data.frame(enr$results) || is.matrix(enr$results))) {
          nrow(enr$results)
        } else if (!is.null(enr$results) && (inherits(enr$results, "enrichResult") || inherits(enr$results, "gseaResult"))) {
          nrow(as.data.frame(enr$results))
        } else if (!is.null(enr$results) && is.list(enr$results)) {
          sum(vapply(enr$results, function(x) {
            if (is.data.frame(x) || is.matrix(x)) nrow(x)
            else if (inherits(x, "enrichResult") || inherits(x, "gseaResult")) nrow(as.data.frame(x))
            else if (!is.null(x$table) && (is.data.frame(x$table) || is.matrix(x$table))) nrow(x$table)
            else if (!is.null(x$result) && (is.data.frame(x$result) || is.matrix(x$result))) nrow(x$result)
            else if (!is.null(x$results) && (is.data.frame(x$results) || is.matrix(x$results))) nrow(x$results)
            else 0L
          }, integer(1)))
        } else {
          0L
        }
      }, error = function(e) 0L)
    }
    
    # Build summary
    summary_items <- lapply(input$pathway_selected_enrichments, function(name) {
      enr <- multiomics$loaded_enrichments[[name]] %||% multiomics$loaded_analyses[[name]]
      if (!is.null(enr)) {
        n_terms <- count_enrichment_terms(enr)
        tags$li(paste0(name, ": ", n_terms, " enriched terms"))
      }
    })
    
    div(style = "font-size: 0.85em; margin-top: 10px; padding: 8px; background: #f8f9fa; border-radius: 5px;",
        strong("Selected for comparison:"),
        tags$ul(style = "margin-bottom: 0; padding-left: 20px;", summary_items)
    )
  })
  
  # ========== END PATHWAY ENRICHMENT SOURCE UI ==========
  
  # MOFA Max R2 UI - Dynamic default value based on variance explained
  output$mofa_max_r2_ui <- renderUI({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$variance_explained)) {
      # Use the maximum variance explained of any single factor in any view
      max_variance <- max(result$variance_explained, na.rm = TRUE)
      max_variance_pct <- if (is.finite(max_variance) && max_variance <= 1) max_variance * 100 else max_variance
      default_value <- min(100, round(max_variance_pct, 1))
      
      sliderInput("mofa_max_r2", "Max Variance % (for scaling):",
                  min = 0, max = 100, value = default_value, step = 0.1,
                  helpText("Values exceeding this threshold will be capped for visualization"))
    } else {
      # Fallback if no MOFA results available
      sliderInput("mofa_max_r2", "Max Variance % (for scaling):",
                  min = 0, max = 100, value = 15, step = 0.1,
                  helpText("Values exceeding this threshold will be capped for visualization"))
    }
  })
  
  # Integration summary
  output$integration_summary <- renderPrint({
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    cat(paste(rep("=", 50), collapse = ""), "\n")
    cat("MULTI-OMICS INTEGRATION SUMMARY\n")
    cat(paste(rep("=", 50), collapse = ""), "\n\n")
    
    cat("Method:", toupper(result$method), "\n")
    cat("Datasets:", length(multiomics$common_samples), "common samples\n\n")
    
    if (result$method == "correlation") {
      cat("Cross-Omics Correlations:\n")
      pair_labels <- result$dataset_labels %||% c(from = result$dataset_pair[1], to = result$dataset_pair[2])
      cat("  Dataset pair:", pair_labels[1], "vs", pair_labels[2], "\n")
      cat("  Total feature pairs tested:", nrow(result$cor_matrix) * ncol(result$cor_matrix), "\n")
      cat("  Significant pairs (filter:", result$filter_mode, "|r| ≥", result$threshold,
          "& p", if (isTRUE(result$adjusted_p)) " (FDR)" else "", " <", result$pval_threshold, "):",
          result$n_sig_pairs, " (showing", result$n_sig_pairs_capped, "after cap)\n")
      cat("  Correlation method:", input$corr_method, "\n")
      cat("  Edge cap:", result$max_edges, "\n\n")
      
      if (!is.null(result$edge_list) && nrow(result$edge_list) > 0) {
        cat("Network Statistics:\n")
        cat("  Number of nodes:", nrow(result$node_list), "\n")
        cat("  Number of edges:", nrow(result$edge_list), "\n")
        
        # Calculate network metrics
        pos_cors <- sum(result$edge_list$correlation > 0)
        neg_cors <- sum(result$edge_list$correlation < 0)
        avg_cor <- mean(abs(result$edge_list$correlation))
        
        cat("  Positive correlations:", pos_cors, "(",
            round(pos_cors/nrow(result$edge_list)*100, 1), "%)\n")
        cat("  Negative correlations:", neg_cors, "(",
            round(neg_cors/nrow(result$edge_list)*100, 1), "%)\n")
        cat("  Average |correlation|:", round(avg_cor, 3), "\n\n")
        
        # Top connected features
        top_nodes <- result$node_list %>%
          arrange(desc(degree)) %>%
          head(5)
        
        if (nrow(top_nodes) > 0) {
          cat("Most connected features:\n")
          for (i in 1:nrow(top_nodes)) {
            cat("  ", i, ". ", top_nodes$id[i], " (", top_nodes$dataset[i],
                "): ", top_nodes$degree[i], " connections\n", sep = "")
          }
        }
      }
      
    } else if (result$method == "mofa") {
      cat("MOFA (Multi-Omics Factor Analysis):\n")
      cat("  Approach: Unsupervised factor decomposition\n\n")
      
      cat("Datasets Integrated:\n")
      if (!is.null(result$views)) {
        for (view in result$views) {
          cat("  -", view, "\n")
        }
      } else if (!is.null(result$mofa_model)) {
        views_from_model <- tryCatch(MOFA2::views_names(result$mofa_model), error = function(e) NULL)
        if (!is.null(views_from_model)) {
          for (view in views_from_model) {
            cat("  -", view, "\n")
          }
        }
      }
      cat("\n")
      
      cat("Analysis Parameters:\n")
      # Get number of factors from variance_explained or mofa_model
      n_factors <- if (!is.null(result$variance_explained)) {
        if (is.matrix(result$variance_explained) || is.data.frame(result$variance_explained)) {
          nrow(result$variance_explained)
        } else {
          length(result$variance_explained)
        }
      } else if (!is.null(result$mofa_model)) {
        tryCatch(MOFA2::get_dimensions(result$mofa_model)$K, error = function(e) NA)
      } else {
        NA
      }
      cat("  Number of factors:", n_factors, "\n")
      cat("  Number of samples:", length(result$common_samples), "\n\n")
      
      # Per-factor variance explained is defined per view; avoid summing across views (can exceed 100%).
      if (!is.null(result$variance_explained) && 
          (is.matrix(result$variance_explained) || is.data.frame(result$variance_explained) || length(result$variance_explained) > 0)) {
        cat("Variance Explained per Factor (by view):\n")
        var_df <- tryCatch({
          as.data.frame(result$variance_explained)
        }, error = function(e) NULL)
        
        if (!is.null(var_df) && nrow(var_df) > 0 && ncol(var_df) > 0) {
          multiplier <- if (max(result$variance_explained, na.rm = TRUE) > 1) 1 else 100
          for (i in seq_len(nrow(var_df))) {
            cat("  Factor", i, ":\n")
            for (view in colnames(var_df)) {
              val <- var_df[i, view]
              if (is.na(val)) next
              cat("    ", view, ": ", sprintf("%.2f%%", val * multiplier), "\n", sep = "")
            }
          }
          cat("\n")
          
          cat("Total Variance Explained per View (all factors):\n")
          if (!is.null(result$variance_explained_total_view)) {
            v <- result$variance_explained_total_view
            v_mult <- if (max(v, na.rm = TRUE) > 1) 1 else 100
            for (view in names(v)) {
              cat("  ", view, ":", sprintf("%.2f%%", v[[view]] * v_mult), "\n")
            }
          } else {
            # Fallback: best-effort summary from the per-factor matrix
            for (view in colnames(var_df)) {
              total_view <- sum(var_df[[view]], na.rm = TRUE)
              cat("  ", view, ":", sprintf("%.2f%%", total_view * multiplier), "\n")
            }
          }
        } else {
          cat("  (Variance data not available in expected format)\n")
        }
      } else if (!is.null(result$mofa_model)) {
        # Try to get variance explained from the model directly
        cat("Variance Explained:\n")
        var_from_model <- tryCatch({
          MOFA2::calculate_variance_explained(result$mofa_model)
        }, error = function(e) NULL)
        
        if (!is.null(var_from_model) && !is.null(var_from_model$r2_per_factor)) {
          r2 <- var_from_model$r2_per_factor[[1]]
          var_df <- as.data.frame(r2)
          multiplier <- if (max(r2, na.rm = TRUE) > 1) 1 else 100
          for (i in seq_len(nrow(var_df))) {
            cat("  Factor", i, ":\n")
            for (view in colnames(var_df)) {
              val <- var_df[i, view]
              if (is.na(val)) next
              cat("    ", view, ": ", sprintf("%.2f%%", val * multiplier), "\n", sep = "")
            }
          }
        } else {
          cat("  (Unable to retrieve variance explained data)\n")
        }
      } else {
        cat("Variance Explained:\n  (Data not available)\n")
      }
      cat("\n")
      
      cat("Factor Interpretation:\n")
      cat("  - Factors with high variance in multiple views = shared patterns\n")
      cat("  - Factors with high variance in one view = dataset-specific patterns\n")
      cat("  - Check Feature Importance tab for top contributing features\n\n")
      
      if (!is.null(result$top_features) && length(result$top_features) > 0) {
        cat("Top Contributing Features (per Factor):\n")
        for (factor_name in names(result$top_features)[1:min(3, length(result$top_features))]) {
          cat("\n  ", factor_name, ":\n")
          factor_features <- result$top_features[[factor_name]]
          if (!is.null(factor_features)) {
            for (view in names(factor_features)) {
              top_3 <- factor_features[[view]] %>% head(3)
              if (!is.null(top_3) && "Feature" %in% colnames(top_3)) {
                cat("    ", view, ": ", paste(top_3$Feature, collapse = ", "), "\n")
              }
            }
          }
        }
      }
      
    } else if (result$method == "diablo") {
      cat("DIABLO Multi-Block PLS-DA:\n")
      cat("  Number of blocks:", length(result$sample_coords), "\n")
      cat("  Number of components:", result$ncomp, "\n")
      cat("  Number of groups:", length(unique(result$Y)), "\n")
      cat("  Group sizes:\n")
      for (grp in names(table(result$Y))) {
        cat("    ", grp, ": ", table(result$Y)[grp], " samples\n", sep = "")
      }
      cat("\n")
      
      cat("Features selected per block:\n")
      for (block_name in names(result$keepX)) {
        cat("  ", block_name, ": ", sum(result$keepX[[block_name]]), " features\n", sep = "")
      }
      cat("\n")
      
      if (!is.null(result$performance)) {
        cat("Classification Performance:\n")
        cat("  (based on cross-validation)\n")
        # Performance summary would go here if available
      }
      
    } else if (result$method == "pathway") {
      # Pathway integration summary
      cat("PATHWAY-LEVEL INTEGRATION:\n")
      cat("  Database:", result$database, "\n")
      cat("  Organism:", result$organism, "\n\n")
      
      if (!is.null(result$summary_stats)) {
        stats <- result$summary_stats
        cat("Enrichment Results:\n")
        cat("  Total pathways tested:", stats$total_pathways, "\n")
        cat("  Pathways in ≥", stats$min_datasets, " datasets:", stats$concordant_pathways, "\n")
        cat("  Significant concordant (p <", stats$pval_cutoff, "):", stats$significant_concordant, "\n\n")
        
        cat("Parameters:\n")
        cat("  P-value cutoff:", stats$pval_cutoff, "\n")
        cat("  Combination method:", stats$combine_method, "\n")
        cat("  Min datasets required:", stats$min_datasets, "\n")
      }
      
      if (!is.null(result$conversion_results)) {
        cat("\nFeature ID Conversion:\n")
        for (ds_name in names(result$conversion_results)) {
          conv <- result$conversion_results[[ds_name]]
          cat("  ", ds_name, ":\n", sep = "")
          cat("    Original type:", conv$original_type %||% "unknown", "\n")
          cat("    Features:", conv$n_original %||% 0, "->", conv$n_converted %||% 0, "converted\n")
          cat("    Success rate:", round((conv$success_rate %||% 0) * 100, 1), "%\n")
        }
      }
      
      if (!is.null(result$significant_concordant) && nrow(result$significant_concordant) > 0) {
        cat("\nTop 10 Concordant Pathways:\n")
        top_pathways <- head(result$significant_concordant, 10)
        for (i in seq_len(nrow(top_pathways))) {
          cat("  ", i, ". ", top_pathways$Description[i],
              " (p=", format(top_pathways$Combined_Padj[i], digits = 3), ", ",
              "in ", top_pathways$N_Datasets[i], " datasets)\n", sep = "")
        }
      }
      
    } else {
      cat(result$message, "\n")
    }
  })
  
  # ========== PATHWAY INTEGRATION OUTPUT RENDERERS ==========
  
  # Pathway Overview Cards
  output$pathway_overview_cards <- renderUI({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$summary_stats)) {
      return(div(class = "alert alert-info", "Run pathway integration to see results."))
    }
    
    stats <- result$summary_stats
    
    fluidRow(
      column(3,
             div(class = "glyco-card", style = "padding: 15px; text-align: center; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white;",
                 h2(stats$total_pathways %||% 0, style = "margin: 0; font-size: 2.5em;"),
                 p("Total Pathways", style = "margin: 0; opacity: 0.9;")
             )
      ),
      column(3,
             div(class = "glyco-card", style = "padding: 15px; text-align: center; background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); color: white;",
                 h2(stats$concordant_pathways %||% 0, style = "margin: 0; font-size: 2.5em;"),
                 p(paste0("In ≥", stats$min_datasets, " Datasets"), style = "margin: 0; opacity: 0.9;")
             )
      ),
      column(3,
             div(class = "glyco-card", style = "padding: 15px; text-align: center; background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); color: white;",
                 h2(stats$significant_concordant %||% 0, style = "margin: 0; font-size: 2.5em;"),
                 p("Significant Concordant", style = "margin: 0; opacity: 0.9;")
             )
      ),
      column(3,
             div(class = "glyco-card", style = "padding: 15px; text-align: center; background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); color: white;",
                 h2(stats$n_datasets %||% 0, style = "margin: 0; font-size: 2.5em;"),
                 p("Datasets Analyzed", style = "margin: 0; opacity: 0.9;")
             )
      )
    )
  })
  
  # Pathway Concordant Table
  output$pathway_concordant_table <- DT::renderDT({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$concordant_pathways)) {
      return(NULL)
    }
    
    # Check if direction info is available
    has_direction <- "Direction_Label" %in% colnames(result$concordant_pathways)
    
    # Prepare display table
    if (has_direction) {
      display_df <- result$concordant_pathways %>%
        dplyr::select(
          Pathway_ID, Description, N_Datasets, N_Significant,
          Combined_Pvalue, Combined_Padj, Direction_Label, Direction_Consistency,
          Min_Pvalue, Max_Pvalue
        ) %>%
        mutate(
          Combined_Pvalue = formatC(Combined_Pvalue, format = "e", digits = 2),
          Combined_Padj = formatC(Combined_Padj, format = "e", digits = 2),
          Min_Pvalue = formatC(Min_Pvalue, format = "e", digits = 2),
          Max_Pvalue = formatC(Max_Pvalue, format = "e", digits = 2),
          Direction_Consistency = ifelse(is.na(Direction_Consistency), "-", 
                                         paste0(round(Direction_Consistency * 100, 0), "%"))
        ) %>%
        rename(
          `Pathway ID` = Pathway_ID,
          `# Datasets` = N_Datasets,
          `# Significant` = N_Significant,
          `Combined P` = Combined_Pvalue,
          `Combined FDR` = Combined_Padj,
          `Direction` = Direction_Label,
          `Consistency` = Direction_Consistency,
          `Min P` = Min_Pvalue,
          `Max P` = Max_Pvalue
        )
    } else {
      display_df <- result$concordant_pathways %>%
        dplyr::select(
          Pathway_ID, Description, N_Datasets, N_Significant,
          Combined_Pvalue, Combined_Padj, Min_Pvalue, Max_Pvalue
        ) %>%
        mutate(
          Combined_Pvalue = formatC(Combined_Pvalue, format = "e", digits = 2),
          Combined_Padj = formatC(Combined_Padj, format = "e", digits = 2),
          Min_Pvalue = formatC(Min_Pvalue, format = "e", digits = 2),
          Max_Pvalue = formatC(Max_Pvalue, format = "e", digits = 2)
        ) %>%
        rename(
          `Pathway ID` = Pathway_ID,
          `# Datasets` = N_Datasets,
          `# Significant` = N_Significant,
          `Combined P` = Combined_Pvalue,
          `Combined FDR` = Combined_Padj,
          `Min P` = Min_Pvalue,
          `Max P` = Max_Pvalue
        )
    }
    
    dt <- DT::datatable(
      display_df,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        dom = 'Bfrtip',
        buttons = c('copy', 'csv', 'excel')
      ),
      rownames = FALSE,
      class = 'cell-border stripe hover',
      filter = 'top'
    )
    
    # Add color formatting for direction column if present
    if (has_direction && "Direction" %in% colnames(display_df)) {
      dt <- dt %>%
        DT::formatStyle(
          "Direction",
          backgroundColor = DT::styleEqual(
            c("Up-regulated", "Down-regulated", "Mixed", "Unknown"),
            c("#d4edda", "#f8d7da", "#fff3cd", "#f8f9fa")
          )
        )
    }
    
    dt
  })
  
  # Pathway Enrichment Heatmap
  output$pathway_enrichment_heatmap <- renderPlot({ 
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$pathway_pval_matrix)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Run pathway integration to see heatmap",
                        size = 6, color = "#667eea") +
               theme_void())
    }
    
    pval_matrix <- result$pathway_pval_matrix
    top_n <- input$pathway_heatmap_top_n %||% 30
    color_scheme <- input$pathway_heatmap_color %||% "viridis"
    do_cluster <- isTRUE(input$pathway_heatmap_cluster)
    
    # Convert to -log10 scale
    log_pval_matrix <- -log10(pval_matrix + 1e-300)
    log_pval_matrix[is.infinite(log_pval_matrix)] <- 300
    log_pval_matrix[is.na(log_pval_matrix)] <- 0
    
    # Get pathway descriptions for row names
    desc_map <- setNames(result$all_enrichments$Description, result$all_enrichments$ID)
    
    # Select top pathways by combined significance
    if (!is.null(result$concordant_pathways)) {
      top_pathway_ids <- head(result$concordant_pathways$Pathway_ID, top_n)
      log_pval_matrix <- log_pval_matrix[top_pathway_ids[top_pathway_ids %in% rownames(log_pval_matrix)], , drop = FALSE]
    } else {
      row_max <- apply(log_pval_matrix, 1, max, na.rm = TRUE)
      top_pathway_ids <- names(sort(row_max, decreasing = TRUE))[1:min(top_n, nrow(log_pval_matrix))]
      log_pval_matrix <- log_pval_matrix[top_pathway_ids, , drop = FALSE]
    }
    
    # Replace row names with descriptions (truncated)
    row_labels <- sapply(rownames(log_pval_matrix), function(id) {
      desc <- desc_map[id]
      if (is.na(desc) || is.null(desc)) return(id)
      if (nchar(desc) > 50) return(paste0(substr(desc, 1, 47), "..."))
      return(desc)
    }, res = UI_PLOT_RES)
    rownames(log_pval_matrix) <- row_labels
    
    # Color palette
    colors <- switch(color_scheme,
                     "viridis" = viridisLite::viridis(100),
                     "plasma" = viridisLite::plasma(100),
                     "Blues" = colorRampPalette(c("white", "#08306b"))(100),
                     "Reds" = colorRampPalette(c("white", "#67000d"))(100),
                     "YlOrRd" = colorRampPalette(c("#ffffcc", "#ffeda0", "#fed976", "#feb24c", "#fd8d3c", "#fc4e2a", "#e31a1c", "#b10026"))(100),
                     viridisLite::viridis(100))
    
    if (!requireNamespace("pheatmap", quietly = TRUE)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "pheatmap package required for heatmap",
                        size = 5, color = "#f59e0b") +
               theme_void())
    }
    
    pheatmap::pheatmap(
      log_pval_matrix,
      color = colors,
      cluster_rows = do_cluster,
      cluster_cols = FALSE,
      show_rownames = TRUE,
      show_colnames = TRUE,
      fontsize_row = 8,
      fontsize_col = 10,
      angle_col = 45,
      main = paste("Pathway Enrichment (-log10 P-value)\nDatabase:", result$database),
      na_col = "grey90"
    )
  })
  
  # Output flag for direction heatmap conditional panel
  output$pathway_has_direction <- reactive({
    result <- multiomics$integration_results
    if (is.null(result) || result$method != "pathway") return(FALSE)
    !is.null(result$pathway_direction_matrix)
  })
  outputOptions(output, "pathway_has_direction", suspendWhenHidden = FALSE)
  
  # Pathway Direction Heatmap
  output$pathway_direction_heatmap <- renderPlot({ 
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$pathway_direction_matrix)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Direction-aware analysis not available",
                        size = 6, color = "#667eea") +
               theme_void())
    }
    
    dir_matrix <- result$pathway_direction_matrix
    top_n <- input$pathway_heatmap_top_n %||% 30
    do_cluster <- isTRUE(input$pathway_heatmap_cluster)
    
    # Get pathway descriptions for row names
    desc_map <- setNames(result$all_enrichments$Description, result$all_enrichments$ID)
    
    # Select top pathways by concordance
    if (!is.null(result$concordant_pathways)) {
      top_pathway_ids <- head(result$concordant_pathways$Pathway_ID, top_n)
      dir_matrix <- dir_matrix[top_pathway_ids[top_pathway_ids %in% rownames(dir_matrix)], , drop = FALSE]
    } else {
      # Use pathways with highest absolute direction
      row_mean_abs <- apply(abs(dir_matrix), 1, mean, na.rm = TRUE)
      top_pathway_ids <- names(sort(row_mean_abs, decreasing = TRUE))[1:min(top_n, nrow(dir_matrix))]
      dir_matrix <- dir_matrix[top_pathway_ids, , drop = FALSE]
    }
    
    if (nrow(dir_matrix) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "No direction data available for selected pathways",
                        size = 5, color = "#f59e0b") +
               theme_void())
    }
    
    # Replace row names with descriptions (truncated)
    row_labels <- sapply(rownames(dir_matrix), function(id) {
      desc <- desc_map[id]
      if (is.na(desc) || is.null(desc)) return(id)
      if (nchar(desc) > 50) return(paste0(substr(desc, 1, 47), "..."))
      return(desc)
    }, res = UI_PLOT_RES)
    rownames(dir_matrix) <- row_labels
    
    # Red-White-Blue diverging palette for direction
    # Blue = down-regulated (negative), White = mixed (0), Red = up-regulated (positive)
    colors <- colorRampPalette(c("#2166ac", "#67a9cf", "#d1e5f0", "#f7f7f7", 
                                  "#fddbc7", "#ef8a62", "#b2182b"))(100)
    
    if (!requireNamespace("pheatmap", quietly = TRUE)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "pheatmap package required for heatmap",
                        size = 5, color = "#f59e0b") +
               theme_void())
    }
    
    # Set symmetric breaks for diverging color scale
    max_abs <- max(abs(dir_matrix), na.rm = TRUE)
    if (max_abs < 0.1) max_abs <- 1  # Ensure reasonable scale
    breaks <- seq(-max_abs, max_abs, length.out = 101)
    
    pheatmap::pheatmap(
      dir_matrix,
      color = colors,
      breaks = breaks,
      cluster_rows = do_cluster,
      cluster_cols = FALSE,
      show_rownames = TRUE,
      show_colnames = TRUE,
      fontsize_row = 8,
      fontsize_col = 10,
      angle_col = 45,
      main = paste("Pathway Direction Scores\nBlue = Down, Red = Up"),
      na_col = "grey90"
    )
  })
  
  # Pathway Overlap Plot
  output$pathway_overlap_plot <- renderPlot({ 
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$enrichment_results)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Run pathway integration to see overlap",
                        size = 6, color = "#667eea") +
               theme_void())
    }
    
    plot_type <- input$pathway_overlap_type %||% "upset"
    pval_thresh <- input$pathway_overlap_pval %||% 0.05
    
    # Get significant pathways per dataset
    sig_pathway_lists <- lapply(result$enrichment_results, function(df) {
      if (is.null(df)) return(character(0))
      df$ID[df$pvalue < pval_thresh]
    }, res = UI_PLOT_RES)
    sig_pathway_lists <- sig_pathway_lists[sapply(sig_pathway_lists, length) > 0]
    
    if (length(sig_pathway_lists) < 2) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Need ≥2 datasets with significant pathways\nTry increasing p-value threshold",
                        size = 5, color = "#f59e0b") +
               theme_void())
    }
    
    if (plot_type == "upset" && requireNamespace("UpSetR", quietly = TRUE)) {
      # UpSet plot
      UpSetR::upset(
        UpSetR::fromList(sig_pathway_lists),
        order.by = "freq",
        nsets = length(sig_pathway_lists),
        point.size = 3.5,
        line.size = 2,
        mainbar.y.label = "Shared Pathways",
        sets.x.label = "Significant Pathways",
        text.scale = c(1.3, 1.3, 1, 1, 1.5, 1.2)
      )
    } else if (plot_type == "venn" && length(sig_pathway_lists) <= 4) {
      # Venn diagram (for up to 4 sets)
      if (requireNamespace("VennDiagram", quietly = TRUE)) {
        # Use ggVennDiagram for ggplot-compatible output
        if (requireNamespace("ggVennDiagram", quietly = TRUE)) {
          ggVennDiagram::ggVennDiagram(sig_pathway_lists, label = "count") +
            scale_fill_gradient(low = "white", high = "#667eea") +
            labs(title = "Pathway Overlap Across Datasets",
                 subtitle = paste("Significant at p <", pval_thresh)) +
            theme(plot.title = element_text(hjust = 0.5, face = "bold"),
                  plot.subtitle = element_text(hjust = 0.5))
        } else {
          # Fallback to basic visualization
          all_pathways <- unique(unlist(sig_pathway_lists))
          overlap_matrix <- sapply(sig_pathway_lists, function(x) all_pathways %in% x)
          rownames(overlap_matrix) <- all_pathways
          
          overlap_counts <- colSums(overlap_matrix)
          
          ggplot(data.frame(Dataset = names(overlap_counts), Count = overlap_counts),
                 aes(x = Dataset, y = Count, fill = Dataset)) +
            geom_col() +
            scale_fill_brewer(palette = "Set2") +
            labs(title = "Significant Pathways per Dataset",
                 subtitle = paste("p <", pval_thresh),
                 x = NULL, y = "Number of Pathways") +
            ggprism::theme_prism() +
            theme(legend.position = "none")
        }
      } else {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "VennDiagram package required",
                   size = 5, color = "#f59e0b") +
          theme_void()
      }
    } else {
      # Fallback bar plot
      all_pathways <- unique(unlist(sig_pathway_lists))
      overlap_counts <- sapply(all_pathways, function(p) {
        sum(sapply(sig_pathway_lists, function(x) p %in% x))
      }, res = UI_PLOT_RES)
      
      overlap_df <- data.frame(
        Overlap = factor(overlap_counts),
        stringsAsFactors = FALSE
      ) %>%
        count(Overlap, name = "Count")
      
      ggplot(overlap_df, aes(x = Overlap, y = Count, fill = Overlap)) +
        geom_col() +
        scale_fill_brewer(palette = "Blues") +
        labs(title = "Pathway Overlap Distribution",
             subtitle = paste("How many datasets share each pathway (p <", pval_thresh, ")"),
             x = "Number of Datasets", y = "Number of Pathways") +
        ggprism::theme_prism() +
        theme(legend.position = "none")
    }
  })
  
  # Pathway Overlap Statistics
  output$pathway_overlap_stats <- renderPrint({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$enrichment_results)) {
      cat("Run pathway integration to see statistics.\n")
      return()
    }
    
    pval_thresh <- input$pathway_overlap_pval %||% 0.05
    
    sig_pathway_lists <- lapply(result$enrichment_results, function(df) {
      if (is.null(df)) return(character(0))
      df$ID[df$pvalue < pval_thresh]
    })
    
    cat("Overlap Statistics (p <", pval_thresh, "):\n")
    cat(paste(rep("-", 40), collapse = ""), "\n")
    
    for (ds in names(sig_pathway_lists)) {
      cat(ds, ":", length(sig_pathway_lists[[ds]]), "significant pathways\n")
    }
    
    # Calculate overlaps
    all_pathways <- unique(unlist(sig_pathway_lists))
    if (length(all_pathways) > 0) {
      overlap_counts <- sapply(all_pathways, function(p) {
        sum(sapply(sig_pathway_lists, function(x) p %in% x))
      })
      
      cat("\n")
      cat("Total unique pathways:", length(all_pathways), "\n")
      cat("In all datasets:", sum(overlap_counts == length(sig_pathway_lists)), "\n")
      cat("In majority (>50%):", sum(overlap_counts > length(sig_pathway_lists)/2), "\n")
      cat("Dataset-specific:", sum(overlap_counts == 1), "\n")
    }
  })
  
  # Update pathway dataset selector
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "pathway" && !is.null(result$enrichment_results)) {
      dataset_choices <- names(result$enrichment_results)
      updateSelectInput(session, "pathway_dataset_select",
                        choices = dataset_choices,
                        selected = dataset_choices[1])
      updateSelectInput(session, "pathway_mapping_dataset",
                        choices = dataset_choices,
                        selected = dataset_choices[1])
    }
  })
  
  # Per-Dataset Dotplot
  output$pathway_dataset_dotplot <- renderPlot({ 
    req(multiomics$integration_results)
    req(input$pathway_dataset_select)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$enrichment_results)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Run pathway integration first",
                        size = 6, color = "#667eea") +
               theme_void())
    }
    
    ds_name <- input$pathway_dataset_select
    ds_result <- result$enrichment_results[[ds_name]]
    
    if (is.null(ds_result) || nrow(ds_result) == 0) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = paste("No enrichment results for", ds_name),
                        size = 5, color = "#f59e0b") +
               theme_void())
    }
    
    top_n <- input$pathway_dataset_top_n %||% 20
    
    plot_df <- ds_result %>%
      arrange(pvalue) %>%
      head(top_n) %>%
      mutate(
        Description = ifelse(nchar(Description) > 40,
                             paste0(substr(Description, 1, 37), "..."),
                             Description),
        Description = factor(Description, levels = rev(Description)),
        GeneRatio = Count / as.numeric(sub("/.*", "", BgRatio)),
        negLog10P = -log10(pvalue)
      )
    
    ggplot(plot_df, aes(x = GeneRatio, y = Description)) +
      geom_point(aes(size = Count, color = negLog10P)) +
      scale_color_gradient(low = "#fee0d2", high = "#de2d26", name = "-log10(p)") +
      scale_size_continuous(range = c(3, 10), name = "Gene Count") +
      labs(title = paste("Top", top_n, "Enriched Pathways -", ds_name),
           subtitle = paste("Database:", result$database),
           x = "Gene Ratio", y = NULL) +
      ggprism::theme_prism() +
      theme(
        plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
        plot.subtitle = element_text(size = 11, hjust = 0.5),
        axis.text.y = element_text(size = 9)
      )
  })
  
  # Per-Dataset Table
  output$pathway_dataset_table <- DT::renderDT({
    req(multiomics$integration_results)
    req(input$pathway_dataset_select)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$enrichment_results)) {
      return(NULL)
    }
    
    ds_name <- input$pathway_dataset_select
    ds_result <- result$enrichment_results[[ds_name]]
    
    if (is.null(ds_result)) return(NULL)
    
    display_df <- ds_result %>%
      dplyr::select(ID, Description, GeneRatio, BgRatio, pvalue, p.adjust, Count) %>%
      mutate(
        pvalue = formatC(pvalue, format = "e", digits = 2),
        p.adjust = formatC(p.adjust, format = "e", digits = 2)
      ) %>%
      rename(
        `Pathway ID` = ID,
        `Gene Ratio` = GeneRatio,
        `Background` = BgRatio,
        `P-value` = pvalue,
        `FDR` = p.adjust,
        `# Genes` = Count
      )
    
    DT::datatable(
      display_df,
      options = list(
        pageLength = 15,
        scrollX = TRUE
      ),
      rownames = FALSE,
      class = 'cell-border stripe hover',
      filter = 'top'
    )
  })
  
  # Feature Mapping Summary
  output$pathway_mapping_summary <- renderUI({
    req(multiomics$integration_results)
    req(input$pathway_mapping_dataset)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$conversion_results)) {
      return(div(class = "alert alert-info", "Run pathway integration to see mapping results."))
    }
    
    ds_name <- input$pathway_mapping_dataset
    conv <- result$conversion_results[[ds_name]]
    
    if (is.null(conv)) {
      return(div(class = "alert alert-warning", "No conversion data available for this dataset."))
    }
    
    success_pct <- round((conv$success_rate %||% 0) * 100, 1)
    success_class <- if (success_pct >= 70) "success" else if (success_pct >= 40) "warning" else "danger"
    
    div(class = "glyco-card", style = "padding: 15px;",
        fluidRow(
          column(4,
                 div(style = "text-align: center;",
                     h4(conv$n_original %||% 0, style = "margin: 0; color: #667eea;"),
                     p("Original Features", style = "margin: 0; font-size: 0.9em;")
                 )
          ),
          column(4,
                 div(style = "text-align: center;",
                     h4(conv$n_converted %||% 0, style = "margin: 0; color: #10b981;"),
                     p("Successfully Converted", style = "margin: 0; font-size: 0.9em;")
                 )
          ),
          column(4,
                 div(style = "text-align: center;",
                     h4(paste0(success_pct, "%"), style = paste0("margin: 0; color: ", 
                        if (success_class == "success") "#10b981" else if (success_class == "warning") "#f59e0b" else "#ef4444", ";")),
                     p("Conversion Rate", style = "margin: 0; font-size: 0.9em;")
                 )
          )
        ),
        hr(),
        p(paste("Original ID Type:", conv$original_type %||% "Unknown"), style = "margin: 5px 0;"),
        p(paste("Target ID Type: ENTREZID"), style = "margin: 5px 0;"),
        if (success_pct < 50) {
          div(class = "alert alert-warning", style = "margin-top: 10px;",
              icon("exclamation-triangle"), " ",
              "Low conversion rate. Consider checking if the correct organism and ID type were selected."
          )
        }
    )
  })
  
  # Feature Mapping Table
  output$pathway_mapping_table <- DT::renderDT({
    req(multiomics$integration_results)
    req(input$pathway_mapping_dataset)
    result <- multiomics$integration_results
    
    if (result$method != "pathway" || is.null(result$conversion_results)) {
      return(NULL)
    }
    
    ds_name <- input$pathway_mapping_dataset
    conv <- result$conversion_results[[ds_name]]
    
    if (is.null(conv) || is.null(conv$mapping)) return(NULL)
    
    mapping_df <- conv$mapping %>%
      mutate(
        Status = ifelse(is.na(ENTREZID), "Failed", "Success")
      )
    
    DT::datatable(
      mapping_df,
      options = list(
        pageLength = 20,
        scrollX = TRUE
      ),
      rownames = FALSE,
      class = 'cell-border stripe hover',
      filter = 'top'
    ) %>%
      DT::formatStyle(
        "Status",
        backgroundColor = DT::styleEqual(c("Success", "Failed"), c("#d4edda", "#f8d7da"))
      )
  })
  
  # Pathway Integration Summary
  output$pathway_integration_summary <- renderPrint({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "pathway") {
      cat("Run pathway integration to see summary.\n")
      return()
    }
    
    cat(paste(rep("=", 60), collapse = ""), "\n")
    cat("PATHWAY INTEGRATION ANALYSIS SUMMARY\n")
    cat(paste(rep("=", 60), collapse = ""), "\n\n")
    
    cat("Database:", result$database, "\n")
    cat("Organism:", result$organism, "\n")
    cat("Analysis Date:", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "\n\n")
    
    if (!is.null(result$parameters)) {
      cat("Parameters:\n")
      cat("  P-value cutoff:", result$parameters$pval_cutoff, "\n")
      cat("  P-value adjustment:", result$parameters$padj_method, "\n")
      cat("  Min gene set size:", result$parameters$min_geneset, "\n")
      cat("  Max gene set size:", result$parameters$max_geneset, "\n")
      cat("  Min datasets for concordance:", result$parameters$min_datasets, "\n")
      cat("  P-value combination:", result$parameters$combine_method, "\n")
      cat("  Direction-aware:", result$parameters$direction_aware, "\n\n")
    }
    
    if (!is.null(result$summary_stats)) {
      stats <- result$summary_stats
      cat("Results Summary:\n")
      cat("  Datasets analyzed:", stats$n_datasets, "\n")
      cat("  Total pathways tested:", stats$total_pathways, "\n")
      cat("  Pathways in ≥", stats$min_datasets, " datasets:", stats$concordant_pathways, "\n")
      cat("  Significant concordant:", stats$significant_concordant, "\n\n")
    }
    
    if (!is.null(result$conversion_results)) {
      cat("Feature Conversion Summary:\n")
      for (ds in names(result$conversion_results)) {
        conv <- result$conversion_results[[ds]]
        cat("  ", ds, ": ", conv$n_converted, "/", conv$n_original,
            " (", round(conv$success_rate * 100, 1), "%)\n", sep = "")
      }
      cat("\n")
    }
    
    if (!is.null(result$significant_concordant) && nrow(result$significant_concordant) > 0) {
      cat("Top 20 Concordant Pathways:\n")
      cat(paste(rep("-", 60), collapse = ""), "\n")
      top <- head(result$significant_concordant, 20)
      for (i in seq_len(nrow(top))) {
        cat(sprintf("%2d. %s\n    Combined FDR: %.2e, Datasets: %d/%d\n",
                    i, top$Description[i], top$Combined_Padj[i],
                    top$N_Significant[i], top$N_Datasets[i]))
      }
    }
  })
  
  # ========== PATHWAY DOWNLOAD HANDLERS ==========
  
  # Download concordant pathways table
  output$download_concordant_pathways <- downloadHandler(
    filename = function() {
      paste0("Concordant_Pathways_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method == "pathway" && !is.null(result$concordant_pathways)) {
        write.csv(result$concordant_pathways, file, row.names = FALSE)
      }
    }
  )
  
  # Download pathway heatmap
  output$download_pathway_heatmap <- downloadHandler(
    filename = function() {
      paste0("Pathway_Heatmap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "pathway" && !is.null(result$pathway_pval_matrix)) {
        # Recreate heatmap for saving
        pval_matrix <- result$pathway_pval_matrix
        top_n <- input$pathway_heatmap_top_n %||% 30
        
        log_pval_matrix <- -log10(pval_matrix + 1e-300)
        log_pval_matrix[is.infinite(log_pval_matrix)] <- 300
        log_pval_matrix[is.na(log_pval_matrix)] <- 0
        
        desc_map <- setNames(result$all_enrichments$Description, result$all_enrichments$ID)
        
        if (!is.null(result$concordant_pathways)) {
          top_pathway_ids <- head(result$concordant_pathways$Pathway_ID, top_n)
          log_pval_matrix <- log_pval_matrix[top_pathway_ids[top_pathway_ids %in% rownames(log_pval_matrix)], , drop = FALSE]
        }
        
        row_labels <- sapply(rownames(log_pval_matrix), function(id) {
          desc <- desc_map[id]
          if (is.na(desc) || is.null(desc)) return(id)
          if (nchar(desc) > 50) return(paste0(substr(desc, 1, 47), "..."))
          return(desc)
        })
        rownames(log_pval_matrix) <- row_labels
        
        colors <- viridisLite::viridis(100)
        
        dpi <- get_safe_global_dpi()
        fmt <- get_safe_global_image_format()
        
        if (fmt == "pdf") {
          pdf(file, width = 12, height = 10)
        } else {
          png(file, width = 12, height = 10, units = "in", res = dpi)
        }
        
        pheatmap::pheatmap(
          log_pval_matrix,
          color = colors,
          cluster_rows = TRUE,
          cluster_cols = FALSE,
          show_rownames = TRUE,
          show_colnames = TRUE,
          fontsize_row = 8,
          fontsize_col = 10,
          angle_col = 45,
          main = paste("Pathway Enrichment (-log10 P-value)\nDatabase:", result$database)
        )
        
        dev.off()
      }
    }
  )
  
  # Download pathway direction heatmap
  output$download_pathway_direction_heatmap <- downloadHandler(
    filename = function() {
      paste0("Pathway_Direction_Heatmap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "pathway" && !is.null(result$pathway_direction_matrix)) {
        dir_matrix <- result$pathway_direction_matrix
        top_n <- input$pathway_heatmap_top_n %||% 30
        
        desc_map <- setNames(result$all_enrichments$Description, result$all_enrichments$ID)
        
        if (!is.null(result$concordant_pathways)) {
          top_pathway_ids <- head(result$concordant_pathways$Pathway_ID, top_n)
          dir_matrix <- dir_matrix[top_pathway_ids[top_pathway_ids %in% rownames(dir_matrix)], , drop = FALSE]
        }
        
        if (nrow(dir_matrix) > 0) {
          row_labels <- sapply(rownames(dir_matrix), function(id) {
            desc <- desc_map[id]
            if (is.na(desc) || is.null(desc)) return(id)
            if (nchar(desc) > 50) return(paste0(substr(desc, 1, 47), "..."))
            return(desc)
          })
          rownames(dir_matrix) <- row_labels
          
          # Red-White-Blue diverging palette
          colors <- colorRampPalette(c("#2166ac", "#67a9cf", "#d1e5f0", "#f7f7f7", 
                                        "#fddbc7", "#ef8a62", "#b2182b"))(100)
          
          max_abs <- max(abs(dir_matrix), na.rm = TRUE)
          if (max_abs < 0.1) max_abs <- 1
          breaks <- seq(-max_abs, max_abs, length.out = 101)
          
          dpi <- get_safe_global_dpi()
          fmt <- get_safe_global_image_format()
          
          if (fmt == "pdf") {
            pdf(file, width = 12, height = 10)
          } else {
            png(file, width = 12, height = 10, units = "in", res = dpi)
          }
          
          pheatmap::pheatmap(
            dir_matrix,
            color = colors,
            breaks = breaks,
            cluster_rows = TRUE,
            cluster_cols = FALSE,
            show_rownames = TRUE,
            show_colnames = TRUE,
            fontsize_row = 8,
            fontsize_col = 10,
            angle_col = 45,
            main = "Pathway Direction Scores\nBlue = Down, Red = Up"
          )
          
          dev.off()
        }
      }
    }
  )
  
  # Download pathway overlap plot
  output$download_pathway_overlap <- downloadHandler(
    filename = function() {
      paste0("Pathway_Overlap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
