  # Download per-dataset table
  output$download_pathway_dataset_table <- downloadHandler(
    filename = function() {
      ds_name <- input$pathway_dataset_select %||% "Dataset"
      paste0("Pathway_Results_", ds_name, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
