      result <- multiomics$integration_results
      
      if (result$method == "pathway" && !is.null(result$enrichment_results)) {
        ds_result <- result$enrichment_results[[input$pathway_dataset_select]]
        if (!is.null(ds_result)) {
          write.csv(ds_result, file, row.names = FALSE)
        }
      }
    }
  )
  
  # Download feature mapping
  output$download_pathway_mapping <- downloadHandler(
    filename = function() {
      ds_name <- input$pathway_mapping_dataset %||% "Dataset"
      paste0("Feature_Mapping_", ds_name, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
      req(input$pathway_mapping_dataset)
      result <- multiomics$integration_results
      
      if (result$method == "pathway" && !is.null(result$conversion_results)) {
        conv <- result$conversion_results[[input$pathway_mapping_dataset]]
        if (!is.null(conv) && !is.null(conv$mapping)) {
          write.csv(conv$mapping, file, row.names = FALSE)
        }
      }
    }
  )
  
  # Download all pathway results as Excel
  output$download_pathway_all_results <- downloadHandler(
    filename = function() {
      paste0("Pathway_Integration_Results_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "pathway") {
        if (!requireNamespace("openxlsx", quietly = TRUE)) {
          showNotification("openxlsx package required for Excel export", type = "error")
          return()
        }
        
        wb <- openxlsx::createWorkbook()
        
        # Concordant pathways sheet
        if (!is.null(result$concordant_pathways)) {
          openxlsx::addWorksheet(wb, "Concordant_Pathways")
          openxlsx::writeData(wb, "Concordant_Pathways", result$concordant_pathways)
        }
        
        # Per-dataset results
        for (ds_name in names(result$enrichment_results)) {
          ds_result <- result$enrichment_results[[ds_name]]
          if (!is.null(ds_result)) {
            sheet_name <- substr(gsub("[^A-Za-z0-9]", "_", ds_name), 1, 31)
            openxlsx::addWorksheet(wb, sheet_name)
            openxlsx::writeData(wb, sheet_name, ds_result)
          }
        }
        
        # Feature mapping
        for (ds_name in names(result$conversion_results)) {
          conv <- result$conversion_results[[ds_name]]
          if (!is.null(conv) && !is.null(conv$mapping)) {
            sheet_name <- paste0("Map_", substr(gsub("[^A-Za-z0-9]", "_", ds_name), 1, 27))
            openxlsx::addWorksheet(wb, sheet_name)
            openxlsx::writeData(wb, sheet_name, conv$mapping)
          }
        }
        
        # Summary sheet
        openxlsx::addWorksheet(wb, "Summary")
        summary_df <- data.frame(
          Parameter = c("Database", "Organism", "P-value Cutoff", "Min Datasets", 
                        "Total Pathways", "Concordant Pathways", "Significant Concordant"),
          Value = c(result$database, result$organism,
                    result$parameters$pval_cutoff, result$parameters$min_datasets,
                    result$summary_stats$total_pathways, result$summary_stats$concordant_pathways,
                    result$summary_stats$significant_concordant)
        )
        openxlsx::writeData(wb, "Summary", summary_df)
        
        openxlsx::saveWorkbook(wb, file, overwrite = TRUE)
      }
    }
  )
  
  # Download as RDS
  output$download_pathway_rds <- downloadHandler(
    filename = function() {
      paste0("Pathway_Integration_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "pathway") {
        saveRDS(result, file)
      }
    }
  )
  
  # ========== END PATHWAY INTEGRATION OUTPUTS ==========
  
  # Multi-Omics Feature importance plot - Variance per Factor
  output$multiomics_feature_importance_plot_factor <- renderPlot({ 
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$mofa_model)) {
      # Use MOFA2's native plot_variance_explained function with plot_total = TRUE
      tryCatch({
        # Check if groups are available for enhanced plotting
        groups <- NULL
        if (!is.null(multiomics$sample_groups)) {
          groups <- multiomics$sample_groups
        }
        
        # Call MOFA2::plot_variance_explained with plot_total = TRUE to get both plots
        plots <- MOFA2::plot_variance_explained(result$mofa_model,
                                                max_r2 = input$mofa_max_r2,
                                                plot_total = TRUE,  # Enable dual plot display
                                                groups = groups)
        
        # Apply consistent theming to the factor plot (plots[[1]])
        plots[[1]] <- plots[[1]] + ggprism::theme_prism() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 11, hjust = 0.5),
            legend.position = "right",
            axis.line.x = element_blank(),
            axis.line.y = element_blank(),
            axis.ticks.x = element_blank(),
            axis.ticks.y = element_blank(),
            axis.text.x = element_text(margin = margin(t = 5)),
            axis.text.y = element_text(margin = margin(r = -10))
          ) +
          labs(fill = "Var. (%)")
        
        # Return the factor plot
        plots[[1]]
        
      }, error = function(e) {
        # Fallback to custom implementation if MOFA2 function fails
        if (!is.null(result$variance_explained)) {
          # MOFA: Variance explained per factor per view
          var_df <- as.data.frame(result$variance_explained)
          var_df$Factor <- rownames(var_df)
          
          # Reshape to long format
          var_long <- var_df %>%
            pivot_longer(cols = -Factor, names_to = "View", values_to = "R2") %>%
            mutate(
              # Check if values are proportions (0-1) or percentages (0-100)
              R2_percent = if (max(R2, na.rm = TRUE) > 1) R2 else R2 * 100,
              Factor = factor(Factor, levels = unique(Factor))
            )
          
          # Calculate y-axis limit
          y_limit <- max(var_long$R2_percent, na.rm = TRUE) * 1.1
          
          p <- ggplot(var_long, aes(x = Factor, y = R2_percent, fill = View)) +
            geom_col(position = "dodge") +
            scale_fill_brewer(palette = "Set2") +
            scale_y_continuous(limits = c(0, y_limit)) +
            labs(title = "MOFA: Variance Explained per Factor",
                 subtitle = "How much each factor explains variation in each dataset",
                 x = "Latent Factor", y = "Variance Explained (%)") +
            ggprism::theme_prism() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 11, hjust = 0.5),
              legend.position = "right",
              axis.text.x = element_text(angle = 45, hjust = 1)
            )
          
          # Return single plot
          p
        } else {
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "Variance explained data unavailable",
                     size = 6, color = "#f59e0b") +
            theme_void()
          
          list(p)
        }
      }, res = UI_PLOT_RES)
      
    } else if (result$method == "diablo" && !is.null(result$var_importance)) {
      # Combine importance from all blocks
      importance_df <- do.call(rbind, result$var_importance)
      
      # Take top features from each block
      top_n <- 15
      plot_df <- importance_df %>%
        group_by(Block) %>%
        slice_head(n = top_n) %>%
        ungroup() %>%
        mutate(Feature = reorder(Feature, Importance))
      
      p <- ggplot(plot_df, aes(x = Importance, y = Feature, fill = Block)) +
        geom_col() +
        facet_wrap(~Block, scales = "free_y", ncol = 1) +
        scale_fill_brewer(palette = "Set2") +
        labs(title = "Top Features by Importance (DIABLO)",
             subtitle = paste("Top", top_n, "features per block"),
             x = "Importance Score", y = NULL) +
        ggprism::theme_prism() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 11, hjust = 0.5),
          legend.position = "none",
          strip.text = element_text(face = "bold", size = 11)
        )
      
      list(p)
      
    } else if (result$method == "correlation" && !is.null(result$node_list) && nrow(result$node_list) > 0) {
      # Node degree plot for correlation network
      top_nodes <- result$node_list %>%
        filter(degree > 0) %>%
        arrange(desc(degree)) %>%
        head(30) %>%
        mutate(id = reorder(id, degree))
      
      if (nrow(top_nodes) > 0) {
        dataset_labels <- result$dataset_labels %||% c(from = "Dataset1", to = "Dataset2")
        dataset_ids <- unique(top_nodes$dataset)
        palette_vals <- c("#667eea", "#f093fb", "#10b981")
        color_map <- setNames(palette_vals[seq_along(dataset_ids)], dataset_ids)
        pair_ids <- result$dataset_pair %||% dataset_ids
        label_map <- setNames(c(dataset_labels[1], dataset_labels[2])[seq_along(pair_ids)], pair_ids)
        p <- ggplot(top_nodes, aes(x = degree, y = id, fill = dataset)) +
          geom_col() +
          scale_fill_manual(values = color_map,
                            labels = label_map) +
          labs(title = "Most Connected Features",
               subtitle = paste("Top 30 features by network degree"),
               x = "Number of Connections", y = NULL,
               fill = "Dataset") +
          ggprism::theme_prism() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 11, hjust = 0.5),
            legend.position = "right"
          )
        
        list(p)
      } else {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "No connected features found",
                   size = 6, color = "#f59e0b") +
          theme_void()
        
        list(p)
      }
      
    } else {
      p <- ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Feature importance visualization\n(available after running analysis)",
                 size = 6, color = "#667eea") +
        theme_void()
      
      list(p)
    }
  })
  
  # Multi-Omics Feature importance plot - Total Variance per View
  output$multiomics_feature_importance_plot_total <- renderPlot({ 
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$mofa_model)) {
