            axis.ticks.y = element_blank(),
            axis.text.x = element_text(margin = margin(t = 5)),
            axis.text.y = element_text(margin = margin(r = -10))
          ) +
          labs(fill = "Var. (%)")

        # Save with the same size as the UI plotOutput
        save_plot_like_ui(plots[[1]], file, session, "multiomics_feature_importance_plot_factor")
      }
    }
  )
  
