  output$network_plot <- renderPlot({ 
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    if (result$method == "correlation" && !is.null(result$edge_list) && nrow(result$edge_list) > 0) {
      # Create network graph from edge list
      edge_list <- result$edge_list
      node_list <- result$node_list

      dataset_labels <- result$dataset_labels %||% c(from = "Dataset1", to = "Dataset2")
      dataset_ids <- unique(node_list$dataset)
      palette_vals <- c("#667eea", "#f093fb", "#10b981")
      color_map <- setNames(palette_vals[seq_along(dataset_ids)], dataset_ids)
      # Ensure labels and names are aligned even if datasets repeat or lengths differ
      label_map <- setNames(rep(dataset_labels, length.out = length(dataset_ids)), dataset_ids)
      
      # Create igraph object
      if (requireNamespace("igraph", quietly = TRUE)) {
        # Ensure vertex names are unique by using id column
        vertices_df <- node_list
        vertices_df$name <- vertices_df$id
        g <- igraph::graph_from_data_frame(edge_list, directed = FALSE, vertices = vertices_df)
        
        # Layout selection
        set.seed(42)
        layout_func <- switch(input$network_layout %||% "fr",
                              "fr" = igraph::layout_with_fr,
                              "kk" = igraph::layout_with_kk,
                              "circle" = igraph::layout_in_circle,
                              "random" = igraph::layout_randomly)
        layout <- layout_func(g)
        
        # Node attributes
        node_df <- data.frame(
          x = layout[, 1],
          y = layout[, 2],
          id = igraph::V(g)$name,
          name = igraph::V(g)$name,  # Will be updated below
          dataset = igraph::V(g)$dataset,
          degree = igraph::degree(g)
        )
        
        # Map back to original names for display
        name_map <- setNames(node_list$name, node_list$id)
        node_df$name <- name_map[node_df$id]
        
        # Edge attributes for plotting - use edge_list directly for robustness
        # Create a mapping from vertex names to layout positions
        vertex_pos <- data.frame(x = layout[, 1], y = layout[, 2])
        rownames(vertex_pos) <- igraph::V(g)$name
        
        edge_coords <- data.frame(
          x = vertex_pos[edge_list$from, "x"],
          y = vertex_pos[edge_list$from, "y"],
          xend = vertex_pos[edge_list$to, "x"],
          yend = vertex_pos[edge_list$to, "y"],
          correlation = edge_list$correlation
        )
        
        # Node size scaling
        node_size_scale <- input$network_node_size %||% 12
        edge_width_scale <- input$network_edge_width %||% 2
        
        # Color by degree option
        if (isTRUE(input$network_color_by_degree)) {
          node_color_var <- "degree"
          node_color_name <- "Connectivity"
          node_color_values <- scales::viridis_pal()(100)
        } else {
          node_color_var <- "dataset"
          node_color_name <- "Dataset"
          node_color_values <- color_map
        }
        
        # Base plot
        p <- ggplot() +
          # Edges
          geom_segment(data = edge_coords,
                       aes(x = x, y = y, xend = xend, yend = yend,
                           color = correlation, alpha = abs(correlation)),
                       linewidth = edge_width_scale * 0.1) +
          # Nodes
          geom_point(data = node_df,
                     aes(x = x, y = y, fill = .data[[node_color_var]], size = degree),
                     shape = 21, color = "white", stroke = 1)
        
        # Apply color scale based on selection
        if (isTRUE(input$network_color_by_degree)) {
          p <- p + scale_fill_viridis_c(name = node_color_name)
        } else {
          p <- p + scale_fill_manual(values = node_color_values, labels = label_map, name = node_color_name)
        }
        
        # Add labels if requested
        if (isTRUE(input$network_show_labels)) {
          p <- p + geom_text(data = node_df,
                            aes(x = x, y = y, label = name),
                            size = 3, vjust = -1, hjust = 0.5,
                            check_overlap = TRUE)
        }
        
        # Complete the plot
        p <- p +
          scale_color_gradient2(low = "#3b82f6", mid = "gray80", high = "#ef4444",
                                midpoint = 0, limits = c(-1, 1),
                                name = "Correlation") +
          scale_size_continuous(range = c(node_size_scale * 0.25, node_size_scale), name = "Connections") +
          scale_alpha_continuous(range = c(0.3, 0.8), guide = "none") +
          labs(title = "Cross-Omics Correlation Network",
            subtitle = paste(nrow(edge_list), "correlations (cap:", result$max_edges, "| filter:", result$filter_mode, ")")) +
          theme_void() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 11, hjust = 0.5),
            legend.position = "right",
            plot.background = element_rect(fill = "white", color = NA)
          )
        
        p
        
      } else {
        # Fallback: Simple bipartite plot without igraph
        edge_sample <- edge_list %>%
          arrange(desc(abs(correlation))) %>%
          head(50)
        
        # Create positions for bipartite layout
        nodes1 <- unique(edge_sample$from)
        nodes2 <- unique(edge_sample$to)
        
        node_df <- data.frame(
          id = c(nodes1, nodes2),
          x = c(rep(0, length(nodes1)), rep(1, length(nodes2))),
          y = c(seq_along(nodes1), seq_along(nodes2)),
          dataset = c(rep(result$dataset_pair[1], length(nodes1)), rep(result$dataset_pair[2], length(nodes2)))
        )
        
        edge_coords <- edge_sample %>%
          left_join(node_df %>% select(id, x, y), by = c("from" = "id")) %>%
          rename(x_from = x, y_from = y) %>%
          left_join(node_df %>% select(id, x, y), by = c("to" = "id")) %>%
          rename(x_to = x, y_to = y)
        
        # Node size scaling
        node_size_scale <- input$network_node_size %||% 12
        edge_width_scale <- input$network_edge_width %||% 2
        
        # Color by degree option
        if (isTRUE(input$network_color_by_degree)) {
          node_color_var <- "degree"
          node_color_name <- "Connectivity"
          node_color_values <- scales::viridis_pal()(100)
        } else {
          node_color_var <- "dataset"
          node_color_name <- "Dataset"
          node_color_values <- color_map
        }
        
        # Base plot
        p <- ggplot() +
          geom_segment(data = edge_coords,
                       aes(x = x_from, y = y_from, xend = x_to, yend = y_to,
                           color = correlation, alpha = abs(correlation)),
                       linewidth = edge_width_scale * 0.1) +
          geom_point(data = node_df,
                     aes(x = x, y = y, fill = .data[[node_color_var]]),
                     size = node_size_scale * 0.33, shape = 21, color = "white", stroke = 1)
        
        # Apply color scale based on selection
        if (isTRUE(input$network_color_by_degree)) {
          p <- p + scale_fill_viridis_c(name = node_color_name)
        } else {
          p <- p + scale_fill_manual(values = node_color_values, labels = label_map, name = node_color_name)
        }
        
        # Add labels if requested
        if (isTRUE(input$network_show_labels)) {
          p <- p + geom_text(data = node_df,
                            aes(x = x, y = y, label = id),
                            size = 3, vjust = -1, hjust = 0.5,
                            check_overlap = TRUE)
        }
        
        # Complete the plot
        p <- p +
          scale_color_gradient2(low = "#3b82f6", mid = "gray80", high = "#ef4444",
                                midpoint = 0, limits = c(-1, 1),
                                name = "Correlation") +
          scale_alpha_continuous(range = c(0.3, 0.8), guide = "none") +
          labs(title = "Cross-Omics Correlation Network (Bipartite)",
            subtitle = paste("Top", nrow(edge_sample), "correlations (cap:", result$max_edges, ")")) +
          theme_void() +
          theme(
            plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 11, hjust = 0.5),
            legend.position = "right"
          )
        
        p
      }
      
    } else if (result$method == "diablo" && !is.null(result$model)) {
      # Circos plot showing correlations between selected features across blocks
      tryCatch({
        # Use mixOmics circosPlot if available
        mixOmics::circosPlot(result$model,
                             cutoff = 0.5,
                             line = TRUE,
                             color.blocks = RColorBrewer::brewer.pal(
                               length(result$sample_coords), "Set2"
                             ),
                             color.cor = c("#3b82f6", "#ef4444"),
                             size.labels = 1.2)
      }, error = function(e) {
        # Fallback: Simple network representation
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Circos plot requires mixOmics package\nwith graphical capabilities",
                   size = 5, color = "#667eea") +
          theme_void()
      })
      
    } else if (result$method == "correlation" && (is.null(result$edge_list) || nrow(result$edge_list) == 0)) {
      # No significant correlations found
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "No significant correlations found\nTry lowering the threshold or p-value cutoff",
                 size = 5, color = "#f59e0b") +
        theme_void()
      
    } else {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Network visualization coming soon!",
                 size = 6, color = "#667eea") +
        theme_void()
    }
  })
  
  # Correlation Heatmap Plot
  output$correlation_heatmap_plot <- renderPlot({ 
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    if (result$method == "correlation" && !is.null(result$cor_matrix)) {
      # Load required packages
      if (!requireNamespace("pheatmap", quietly = TRUE)) {
        if (exists("load_package_group")) {
          load_package_group("visualization")
        }
      }
      
      if (!requireNamespace("pheatmap", quietly = TRUE)) {
        return(ggplot() +
                 annotate("text", x = 0.5, y = 0.5,
                          label = "pheatmap package not available",
                          size = 5, color = "#f59e0b") +
                 theme_void())
      }
      
      # Get correlation matrix
      cor_matrix <- result$cor_matrix
      
      # Apply threshold filter
      threshold <- input$heatmap_correlation_threshold %||% 0.3
      cor_matrix_filtered <- cor_matrix
      cor_matrix_filtered[abs(cor_matrix_filtered) < threshold] <- 0
      
      # Create annotation for rows/columns (dataset origin)
      dataset1_name <- result$dataset_labels["from"] %||% "Dataset1"
      dataset2_name <- result$dataset_labels["to"] %||% "Dataset2"

      # Create row/column annotations (features from dataset1 on rows, dataset2 on columns)
      row_annot <- data.frame(
        Dataset = rep(dataset1_name, nrow(cor_matrix_filtered)),
        stringsAsFactors = FALSE
      )
      rownames(row_annot) <- rownames(cor_matrix_filtered)

      col_annot <- data.frame(
        Dataset = rep(dataset2_name, ncol(cor_matrix_filtered)),
        stringsAsFactors = FALSE
      )
      rownames(col_annot) <- colnames(cor_matrix_filtered)

      # Build consistent annotation colors to match factor levels
      dataset_levels <- unique(c(row_annot$Dataset, col_annot$Dataset))
      dataset_colors <- setNames(c("#667eea", "#f093fb", "#10b981")[seq_along(dataset_levels)], dataset_levels)
      
      # Color scheme selection
      color_scheme <- input$heatmap_color_scheme %||% "RdBu"
      if (color_scheme == "RdBu") {
        colors <- grDevices::colorRampPalette(c("#3b82f6", "white", "#ef4444"))(100)
      } else if (color_scheme == "RdYlBu") {
        colors <- grDevices::colorRampPalette(c("#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"))(100)
      } else if (color_scheme == "Blues") {
        colors <- grDevices::colorRampPalette(c("white", "#08306b"))(100)
      } else { # Viridis
        colors <- viridisLite::viridis(100)
      }
      
      # Create breaks for color scale
      max_abs <- max(abs(cor_matrix_filtered), na.rm = TRUE)
      if (!is.finite(max_abs) || max_abs <= 0) max_abs <- 1
      breaks <- seq(-max_abs, max_abs, length.out = 101)
      
      # Create the heatmap
      pheatmap::pheatmap(
        cor_matrix_filtered,
        color = colors,
        breaks = breaks,
        cluster_rows = isTRUE(input$heatmap_cluster_features),
        cluster_cols = isTRUE(input$heatmap_cluster_features),
        show_rownames = TRUE,
        show_colnames = TRUE,
        display_numbers = isTRUE(input$heatmap_show_values),
        fontsize_number = 6,
        fontsize_row = 8,
        fontsize_col = 8,
        angle_col = 45,
        annotation_row = row_annot,
        annotation_col = col_annot,
        annotation_colors = list(
          Dataset = dataset_colors
        ),
        main = paste("Cross-Omics Correlation Heatmap\nMethod:", result$correlation_method %||% "Pearson", "| Threshold:", threshold),
        fontsize = 10
      )
      
    } else {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = "Correlation heatmap requires\ncorrelation analysis results",
                 size = 5, color = "#667eea") +
        theme_void()
    }
  })
  
  # Download handler for Correlation Heatmap
  output$download_correlation_heatmap <- downloadHandler(
    filename = function() {
      paste0("Correlation_Heatmap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      tryCatch({
        req(multiomics$integration_results)
        result <- multiomics$integration_results
        
        if (result$method != "correlation" || is.null(result$cor_matrix)) {
          stop("Correlation heatmap requires correlation analysis results")
        }
        
        {
          # Load required packages
          if (!requireNamespace("pheatmap", quietly = TRUE)) {
            if (exists("load_package_group")) {
              load_package_group("visualization")
            }
          }
          
          if (!requireNamespace("pheatmap", quietly = TRUE)) {
            stop("pheatmap package not available")
          }
          
          # Get correlation matrix
          cor_matrix <- result$cor_matrix
          
          # Apply threshold filter
          threshold <- input$heatmap_correlation_threshold %||% 0.3
          cor_matrix_filtered <- cor_matrix
          cor_matrix_filtered[abs(cor_matrix_filtered) < threshold] <- 0
          
          # Create annotation for rows/columns (dataset origin)
          dataset1_name <- result$dataset_labels["from"] %||% "Dataset1"
          dataset2_name <- result$dataset_labels["to"] %||% "Dataset2"
          
          # Create row/column annotations (features from dataset1 on rows, dataset2 on columns)
          row_annot <- data.frame(
            Dataset = rep(dataset1_name, nrow(cor_matrix_filtered)),
            stringsAsFactors = FALSE
          )
          rownames(row_annot) <- rownames(cor_matrix_filtered)
          
          col_annot <- data.frame(
            Dataset = rep(dataset2_name, ncol(cor_matrix_filtered)),
            stringsAsFactors = FALSE
          )
          rownames(col_annot) <- colnames(cor_matrix_filtered)

          # Build consistent annotation colors to match factor levels
          dataset_levels <- unique(c(row_annot$Dataset, col_annot$Dataset))
          dataset_colors <- setNames(c("#667eea", "#f093fb", "#10b981")[seq_along(dataset_levels)], dataset_levels)
          
          # Color scheme selection
          color_scheme <- input$heatmap_color_scheme %||% "RdBu"
          if (color_scheme == "RdBu") {
            colors <- grDevices::colorRampPalette(c("#3b82f6", "white", "#ef4444"))(100)
          } else if (color_scheme == "RdYlBu") {
            colors <- grDevices::colorRampPalette(c("#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"))(100)
          } else if (color_scheme == "Blues") {
            colors <- grDevices::colorRampPalette(c("white", "#08306b"))(100)
          } else { # Viridis
            colors <- viridisLite::viridis(100)
          }
          
          # Create breaks for color scale
          max_abs <- max(abs(cor_matrix_filtered), na.rm = TRUE)
          if (!is.finite(max_abs) || max_abs <= 0) max_abs <- 1
          breaks <- seq(-max_abs, max_abs, length.out = 101)
          
          # Save as PDF/PNG/SVG
          fmt <- get_safe_global_image_format()
          dpi <- get_safe_global_dpi()
          
          # Open graphics device
          if (identical(fmt, "pdf")) {
            grDevices::pdf(file, width = 12, height = 10)
          } else if (identical(fmt, "svg") && requireNamespace("svglite", quietly = TRUE)) {
            svglite::svglite(file, width = 12, height = 10)
          } else {
            # Default to PNG
            grDevices::png(file, width = 12 * dpi, height = 10 * dpi, res = dpi)
          }
          
          # Ensure device cleanup
          on.exit({
            try(grDevices::dev.off(), silent = TRUE)
          }, add = TRUE)
          
          # Create the heatmap
          pheatmap::pheatmap(
            cor_matrix_filtered,
            color = colors,
            breaks = breaks,
            cluster_rows = isTRUE(input$heatmap_cluster_features),
            cluster_cols = isTRUE(input$heatmap_cluster_features),
            show_rownames = TRUE,
            show_colnames = TRUE,
            display_numbers = isTRUE(input$heatmap_show_values),
            fontsize_number = 6,
            fontsize_row = 8,
            fontsize_col = 8,
            angle_col = 45,
            annotation_row = row_annot,
            annotation_col = col_annot,
            annotation_colors = list(
              Dataset = dataset_colors
            ),
            main = paste("Cross-Omics Correlation Heatmap\nMethod:", result$correlation_method %||% "Pearson", "| Threshold:", threshold),
            fontsize = 10
          )
        }
        
      }, error = function(e) {
        # Close any open device
        try(grDevices::dev.off(), silent = TRUE)
        
        # Create fallback plot
        fmt <- get_safe_global_image_format()
        dpi <- get_safe_global_dpi()
        
        if (identical(fmt, "pdf")) {
          grDevices::pdf(file, width = 12, height = 10)
        } else if (identical(fmt, "svg") && requireNamespace("svglite", quietly = TRUE)) {
          svglite::svglite(file, width = 12, height = 10)
        } else {
          grDevices::png(file, width = 12 * dpi, height = 10 * dpi, res = dpi)
        }
        
        graphics::plot.new()
        graphics::text(0.5, 0.5, paste("Error:", e$message), cex = 1.2)
        grDevices::dev.off()
      })
    }
  )
  
  # Download handler for Data Overview plot
  output$download_data_overview <- downloadHandler(
    filename = function() {
      paste0("MOFA_Data_Overview_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "mofa" && !is.null(result$mofa_model)) {
        tryCatch({
          model_metadata <- MOFA2::samples_metadata(result$mofa_model)
          has_groups <- !is.null(model_metadata) && ncol(model_metadata) > 1
          
          if (has_groups) {
            p <- MOFA2::plot_data_overview(result$mofa_model)
            p <- p + ggprism::theme_prism() +
              theme(
                plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
                plot.subtitle = element_text(size = 11, hjust = 0.5),
                legend.position = "right",
                axis.text.x = element_blank(),
                axis.title.x = element_blank(),
                axis.title.y = element_blank(),
                axis.ticks = element_blank(),
                axis.line = element_blank(),
                panel.spacing = unit(1, "lines")
              )
          } else {
            if (!is.null(result$views) && !is.null(result$common_samples)) {
              n_samples <- length(result$common_samples)
              feature_counts <- sapply(result$weights, function(w) {
                if (!is.null(w) && nrow(w) > 0) nrow(w) else 0
              })
              
              overview_df <- data.frame(
                View = names(feature_counts),
                Samples = n_samples,
                Features = as.numeric(feature_counts),
                stringsAsFactors = FALSE
              )
              
              overview_long <- tidyr::pivot_longer(overview_df,
                                                   cols = -View,
                                                   names_to = "Metric",
                                                   values_to = "Value")
              
              overview_long$Value_display <- with(overview_long, {
                ifelse(Metric == "Features",
                       Value / max(Value[Metric == "Features"], na.rm = TRUE) * max(Value[Metric == "Samples"], na.rm = TRUE),
                       Value)
              })
              
              p <- ggplot(overview_long, aes(x = Metric, y = View, fill = Value_display)) +
                geom_tile(color = "white", linewidth = 2) +
                geom_text(aes(label = Value), color = "white", fontface = "bold", size = 5) +
                scale_fill_gradient(low = "#fecaca", high = "#dc2626", name = "Value") +
                labs(title = "MOFA Data Overview",
                     subtitle = "Samples and features per view (no groups available)",
                     x = NULL, y = "View") +
                ggprism::theme_prism() +
                theme(
                  plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
                  plot.subtitle = element_text(size = 11, hjust = 0.5),
                  axis.text.y = element_text(size = 11, face = "bold"),
                  axis.text.x = element_blank(),
                  axis.title.x = element_blank(),
                  axis.title.y = element_blank(),
                  axis.ticks = element_blank(),
                  legend.position = "right"
                )
            }
          }
          
          # Save the plot
          dpi <- get_safe_global_dpi()
          image_format <- get_safe_global_image_format()
          ggsave(file, plot = p, dpi = dpi, width = 10, height = 8, units = "in")
        }, error = function(e) {
          # Fallback plot
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "Data overview unavailable",
                     size = 5, color = "#667eea") +
            theme_void()
          ggsave(file, plot = p, dpi = get_safe_global_dpi(), width = 10, height = 8, units = "in")
        })
      }
    }
  )
  
  # Download handler for Factor Correlations plot
  output$download_factor_correlations <- downloadHandler(
    filename = function() {
      paste0("MOFA_Factor_Correlations_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "mofa" && !is.null(result$mofa_model)) {
        tryCatch({
          # Use MOFA2's native plot_factor_cor function - same as UI render
          cor_method <- tolower(if (!is.null(input$mofa_cor_method)) input$mofa_cor_method else "pearson")

          fmt <- get_safe_global_image_format()
          dpi <- get_safe_global_dpi()

          if (identical(fmt, "pdf")) {
            grDevices::pdf(file, width = 10, height = 8)
          } else if (identical(fmt, "svg") && requireNamespace("svglite", quietly = TRUE)) {
            svglite::svglite(file, width = 10, height = 8)
          } else {
            grDevices::png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
          }
          on.exit({
            try(grDevices::dev.off(), silent = TRUE)
          }, add = TRUE)

          # Call MOFA2::plot_factor_cor with the model (draws on current device)
          p <- MOFA2::plot_factor_cor(result$mofa_model, method = cor_method)

          if (inherits(p, "ggplot")) {
            # Apply consistent theming - match UI render
            p <- p + ggprism::theme_prism() +
              theme(
                plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
                plot.subtitle = element_text(size = 11, hjust = 0.5),
                legend.position = "right"
              )

            p <- apply_mofa_text_fix(p)
            print(p)
          } else if (inherits(p, "Heatmap") && requireNamespace("ComplexHeatmap", quietly = TRUE)) {
            ComplexHeatmap::draw(p)
          } else if (!is.null(p)) {
            print(p)
          } else {
            # Some MOFA2 versions draw directly and return NULL
          }
        }, error = function(e) {
          # Fallback plot
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Factor correlations unavailable:", e$message),
                     size = 5, color = "#667eea") +
            theme_void()
          ggsave(file, plot = p, dpi = get_safe_global_dpi(), width = 10, height = 8, units = "in")
        })
      }
    }
  )
  
  # Download handler for Associations heatmap
  output$download_assoc_heatmap <- downloadHandler(
    filename = function() {
      paste0("MOFA_Associations_Heatmap_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(assoc_results())

      tryCatch({
        req(multiomics$integration_results)
        result <- multiomics$integration_results
        if (is.null(result) || result$method != "mofa" || is.null(result$mofa_model)) {
          stop("MOFA analysis required with a trained model")
        }

        selected_covs <- assoc_results()$covariates
        alpha <- assoc_results()$alpha
        plot_mode <- assoc_results()$plot %||% "log_pval"
        model <- assoc_results()$model
        req(model)

        fmt <- get_safe_global_image_format()
        dpi <- get_safe_global_dpi()

        if (identical(fmt, "pdf")) {
          grDevices::pdf(file, width = 10, height = 8)
        } else if (identical(fmt, "svg") && requireNamespace("svglite", quietly = TRUE)) {
          svglite::svglite(file, width = 10, height = 8)
        } else {
          # Default to PNG
          grDevices::png(file, width = 10 * dpi, height = 8 * dpi, res = dpi)
        }
        on.exit({
          try(grDevices::dev.off(), silent = TRUE)
        }, add = TRUE)

        p <- MOFA2::correlate_factors_with_covariates(
          model,
          covariates = selected_covs,
          plot = plot_mode,
          alpha = alpha
        )
        if (inherits(p, "ggplot")) {
          p <- p + scale_y_discrete(labels = function(x) gsub("\\.", " ", x)) + scale_x_discrete(labels = function(x) gsub("\\.", " ", x))
          print(p)
        } else {
          # Rely on MOFA2 to draw directly if no ggplot returned
        }
      }, error = function(e) {
        p <- ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Associations heatmap unavailable",
                   size = 5, color = "#667eea") +
          theme_void()
        ggsave(file, plot = p, dpi = get_safe_global_dpi(), width = 10, height = 8, units = "in")
      })
    }
  )
  
  # MODEL DOWNLOAD HANDLERS
  
  # ============================================================================
  # MOFA ADVANCED VISUALIZATIONS
  # ============================================================================
  
