        has_groups <- !is.null(model_metadata) && ncol(model_metadata) > 1
        
        if (has_groups) {
          # Use MOFA2's plot_data_overview which shows views as rows and groups as columns
          p <- MOFA2::plot_data_overview(result$mofa_model)
          
          # Apply consistent theming with clean styling
          p <- p + ggprism::theme_prism() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 11, hjust = 0.5),
              legend.position = "right",
              axis.text.x = element_blank(),  # Remove x-axis text (sample names)
              axis.title.x = element_blank(), # Remove x-axis title
              axis.title.y = element_blank(), # Remove y-axis title
              axis.ticks = element_blank(),   # Remove axis ticks
              axis.line = element_blank(),  # Remove axis lines
              panel.spacing = unit(1, "lines")  # Add spacing between groups
            )

          p <- apply_mofa_text_fix(p)
          p
        } else {
          # No groups available, use custom overview
          if (!is.null(result$views) && !is.null(result$common_samples)) {
            # Get data dimensions
            views <- result$views
            n_samples <- length(result$common_samples)
            
            # Get feature counts from the weights
            feature_counts <- sapply(result$weights, function(w) {
              if (!is.null(w) && nrow(w) > 0) nrow(w) else 0
            }, res = UI_PLOT_RES)
            
            # Create overview dataframe
            overview_df <- data.frame(
              View = names(feature_counts),
              Samples = n_samples,
              Features = as.numeric(feature_counts),
              stringsAsFactors = FALSE
            )
            
            # Convert to long format for visualization
            overview_long <- tidyr::pivot_longer(overview_df,
                                                 cols = -View,
                                                 names_to = "Metric",
                                                 values_to = "Value")
            
            # Normalize features for visualization
            overview_long$Value_display <- with(overview_long, {
              ifelse(Metric == "Features",
                     Value / max(Value[Metric == "Features"], na.rm = TRUE) * max(Value[Metric == "Samples"], na.rm = TRUE),
                     Value)
            }, res = UI_PLOT_RES)
            
            ggplot(overview_long, aes(x = Metric, y = View, fill = Value_display)) +
              geom_tile(color = "white", linewidth = 2) +
              geom_text(aes(label = Value), color = "white", fontface = "bold", size = 5) +
              scale_fill_gradient(low = "#fecaca", high = "#dc2626", name = "Value") +
              labs(title = "MOFA Data Overview",
