  # Initialize feature scatter inputs based on MOFA results
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa") {
      # Update view choices
      view_choices <- result$views
      updateSelectInput(session, "feature_scatter_view",
                        choices = view_choices,
                        selected = view_choices[1])
      
      # Update feature weights view choices
      updateSelectInput(session, "feature_weights_view",
                        choices = view_choices,
                        selected = view_choices[1])
      
      # Update factor choices
      if (!is.null(result$factors)) {
        factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
        # Sort factors numerically
        factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]
        updateSelectInput(session, "feature_scatter_factor",
                          choices = factor_cols,
                          selected = factor_cols[1])
        
        # Update feature weights factor choices
        updateSelectInput(session, "feature_weights_factor",
                          choices = factor_cols,
                          selected = factor_cols[1])
        
        # Update factor values factor choices (allow multiple selections)
        updateSelectizeInput(session, "factor_values_factor",
                             choices = factor_cols,
                             selected = factor_cols[1],
                             server = TRUE)
      }
      
      # Update weight view choices for factor values coloring
      if (!is.null(result$weights)) {
        weight_view_choices <- names(result$weights)
        updateSelectInput(session, "factor_values_weight_view",
                          choices = weight_view_choices,
                          selected = weight_view_choices[1])
        
        # Update feature view choices for factor values coloring
        updateSelectInput(session, "factor_values_feature_view",
                          choices = weight_view_choices,
                          selected = weight_view_choices[1])
        
        # Populate feature choices from first view
        if (length(weight_view_choices) > 0) {
          first_view <- weight_view_choices[1]
          feature_choices <- character(0)

          # Prefer feature_name_map for dropdown labels (clean names), but store Feature_full as the value.
          if (!is.null(result$feature_name_map) && !is.null(result$feature_name_map[[first_view]]) &&
              all(c("Feature_full", "Feature") %in% colnames(result$feature_name_map[[first_view]]))) {
            map_df <- result$feature_name_map[[first_view]]
            map_df$Feature_full <- as.character(map_df$Feature_full)
            map_df$Feature <- as.character(map_df$Feature)
            map_df <- map_df[!is.na(map_df$Feature_full) & nzchar(map_df$Feature_full) & !is.na(map_df$Feature) & nzchar(map_df$Feature), , drop = FALSE]
            if (nrow(map_df) > 0) {
              labels <- make.unique(map_df$Feature)
              values <- map_df$Feature_full
              feature_choices <- stats::setNames(values, labels)
            }
          } else if (!is.null(result$weights[[first_view]])) {
            weights_df <- result$weights[[first_view]]
            if (is.data.frame(weights_df)) {
              if (!"Feature_full" %in% colnames(weights_df) && !is.null(rownames(weights_df)) && length(rownames(weights_df)) == nrow(weights_df)) {
                weights_df$Feature_full <- rownames(weights_df)
              }
              if (all(c("Feature_full", "Feature") %in% colnames(weights_df))) {
                weights_df$Feature_full <- as.character(weights_df$Feature_full)
                weights_df$Feature <- as.character(weights_df$Feature)
                weights_df <- weights_df[!is.na(weights_df$Feature_full) & nzchar(weights_df$Feature_full) & !is.na(weights_df$Feature) & nzchar(weights_df$Feature), , drop = FALSE]
                if (nrow(weights_df) > 0) {
                  labels <- make.unique(weights_df$Feature)
                  values <- weights_df$Feature_full
                  feature_choices <- stats::setNames(values, labels)
                }
              }
            }
          }
          updateSelectInput(session, "factor_values_feature",
                            choices = feature_choices,
                            selected = if (length(feature_choices) > 0) unname(feature_choices[[1]]) else "")
        }
      }
      
      # Update dimred color choices
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]

      # Factor selectors for dimred
      updateSelectizeInput(session, "dimred_factors",
                           choices = factor_cols,
                           selected = factor_cols,
                           server = TRUE)
      updateSelectizeInput(session, "dimred_exclude_factors",
                           choices = factor_cols,
                           selected = character(0),
                           server = TRUE)

      # View selector for view-based dimred
      if (!is.null(result$views) && length(result$views) > 0) {
        updateSelectInput(session, "dimred_view_source",
                          choices = result$views,
                          selected = result$views[1])
      }

      update_mofa_dimred_color_choices()
    }
  })

  # Update dimensionality reduction color choices when covariates change
  observeEvent(mofa_metadata$covariates, {
    update_mofa_dimred_color_choices()
  })
  
  # Update feature scatter color factor choices
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$factors)) {
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      updateSelectInput(session, "feature_scatter_color_factor",
                        choices = factor_cols,
                        selected = factor_cols[1])
    }
  })
  
  # Update feature choices when feature view changes (for factor values coloring)
  observeEvent(input$factor_values_feature_view, {
