        # Prefer feature_name_map for dropdown labels (clean names), but store Feature_full as the value.
        if (!is.null(result$feature_name_map) && !is.null(result$feature_name_map[[feature_view]]) &&
            all(c("Feature_full", "Feature") %in% colnames(result$feature_name_map[[feature_view]]))) {
          map_df <- result$feature_name_map[[feature_view]]
          map_df$Feature_full <- as.character(map_df$Feature_full)
          map_df$Feature <- as.character(map_df$Feature)
          map_df <- map_df[!is.na(map_df$Feature_full) & nzchar(map_df$Feature_full) & !is.na(map_df$Feature) & nzchar(map_df$Feature), , drop = FALSE]
          if (nrow(map_df) > 0) {
            labels <- make.unique(map_df$Feature)
            values <- map_df$Feature_full
            feature_choices <- stats::setNames(values, labels)
          }
        } else if (!is.null(result$weights[[feature_view]])) {
          weights_df <- result$weights[[feature_view]]
          if (is.data.frame(weights_df)) {
            if (!"Feature_full" %in% colnames(weights_df) && !is.null(rownames(weights_df)) && length(rownames(weights_df)) == nrow(weights_df)) {
              weights_df$Feature_full <- rownames(weights_df)
            }
            if (all(c("Feature_full", "Feature") %in% colnames(weights_df))) {
              weights_df$Feature_full <- as.character(weights_df$Feature_full)
              weights_df$Feature <- as.character(weights_df$Feature)
              weights_df <- weights_df[!is.na(weights_df$Feature_full) & nzchar(weights_df$Feature_full) & !is.na(weights_df$Feature) & nzchar(weights_df$Feature), , drop = FALSE]
              if (nrow(weights_df) > 0) {
                labels <- make.unique(weights_df$Feature)
                values <- weights_df$Feature_full
                feature_choices <- stats::setNames(values, labels)
              }
            }
          }
        }
        updateSelectInput(session, "factor_values_feature",
                          choices = feature_choices,
                          selected = if (length(feature_choices) > 0) unname(feature_choices[[1]]) else "")
      }
    }
  })

  output$download_network <- downloadHandler(
    filename = function() {
      req(multiomics$integration_results)
      paste0("Cross_Omics_Correlation_Network_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results

      if (result$method == "correlation" && !is.null(result$edge_list) && nrow(result$edge_list) > 0) {
        # Generate the correlation network plot for download
        edge_list <- result$edge_list
        node_list <- result$node_list

        dataset_labels <- result$dataset_labels %||% c(from = "Dataset1", to = "Dataset2")
        dataset_ids <- unique(node_list$dataset)
        palette_vals <- c("#667eea", "#f093fb", "#10b981")
        color_map <- setNames(palette_vals[seq_along(dataset_ids)], dataset_ids)
        pair_ids <- result$dataset_pair %||% dataset_ids
        label_map <- setNames(c(dataset_labels[1], dataset_labels[2])[seq_along(pair_ids)], pair_ids)
        
        # Create igraph object
        if (requireNamespace("igraph", quietly = TRUE)) {
          g <- igraph::graph_from_data_frame(edge_list, directed = FALSE, vertices = node_list)
          
          # Layout selection
          set.seed(42)
          layout_func <- switch(input$network_layout %||% "fr",
                                "fr" = igraph::layout_with_fr,
                                "kk" = igraph::layout_with_kk,
                                "circle" = igraph::layout_in_circle,
                                "random" = igraph::layout_randomly)
          layout <- layout_func(g)
          
          # Node attributes
          node_df <- data.frame(
            x = layout[, 1],
            y = layout[, 2],
            id = igraph::V(g)$name,
            dataset = igraph::V(g)$dataset,
            degree = igraph::degree(g)
          )
          
          # Edge attributes for plotting
          edge_coords <- data.frame(
            x = layout[igraph::get.edgelist(g)[, 1], 1],
            y = layout[igraph::get.edgelist(g)[, 1], 2],
            xend = layout[igraph::get.edgelist(g)[, 2], 1],
            yend = layout[igraph::get.edgelist(g)[, 2], 2],
            correlation = edge_list$correlation
          )
          
          # Node size scaling
          node_size_scale <- input$network_node_size %||% 12
          edge_width_scale <- input$network_edge_width %||% 2
          
          # Color by degree option
          if (isTRUE(input$network_color_by_degree)) {
            node_color_var <- "degree"
            node_color_name <- "Connectivity"
            node_color_values <- scales::viridis_pal()(100)
          } else {
            node_color_var <- "dataset"
            node_color_name <- "Dataset"
            node_color_values <- color_map
          }
          
          # Base plot
          p <- ggplot() +
            # Edges
            geom_segment(data = edge_coords,
                         aes(x = x, y = y, xend = xend, yend = yend,
                             color = correlation, alpha = abs(correlation)),
                         linewidth = edge_width_scale * 0.1) +
            # Nodes
            geom_point(data = node_df,
                       aes(x = x, y = y, fill = .data[[node_color_var]], size = degree),
                       shape = 21, color = "white", stroke = 1)
          
          # Apply color scale based on selection
          if (isTRUE(input$network_color_by_degree)) {
            p <- p + scale_fill_viridis_c(name = node_color_name)
          } else {
            p <- p + scale_fill_manual(values = node_color_values, labels = label_map, name = node_color_name)
          }
          
          # Add labels if requested
          if (isTRUE(input$network_show_labels)) {
            p <- p + geom_text(data = node_df,
                              aes(x = x, y = y, label = id),
                              size = 3, vjust = -1, hjust = 0.5,
                              check_overlap = TRUE)
          }
          
          # Complete the plot
          p <- p +
            scale_color_gradient2(low = "#3b82f6", mid = "gray80", high = "#ef4444",
                                  midpoint = 0, limits = c(-1, 1),
                                  name = "Correlation") +
            scale_size_continuous(range = c(node_size_scale * 0.25, node_size_scale), name = "Connections") +
            scale_alpha_continuous(range = c(0.3, 0.8), guide = "none") +
            labs(title = "Cross-Omics Correlation Network",
              subtitle = paste(nrow(edge_list), "correlations (cap:", result$max_edges, "| filter:", result$filter_mode, ")")) +
            theme_void() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 11, hjust = 0.5),
              legend.position = "right",
              plot.background = element_rect(fill = "white", color = NA)
            )
          
          # Save the plot
          dpi <- get_safe_global_dpi()
          image_format <- get_safe_global_image_format()
          ggsave(file, plot = p, dpi = dpi, width = 12, height = 8, units = "in")
          
        } else {
          # Fallback: Simple bipartite plot without igraph
          edge_sample <- edge_list %>%
            arrange(desc(abs(correlation))) %>%
            head(50)
          
          # Create positions for bipartite layout
          nodes1 <- unique(edge_sample$from)
          nodes2 <- unique(edge_sample$to)
          
          node_df <- data.frame(
            id = c(nodes1, nodes2),
            x = c(rep(0, length(nodes1)), rep(1, length(nodes2))),
            y = c(seq_along(nodes1), seq_along(nodes2)),
            dataset = c(rep(result$dataset_pair[1], length(nodes1)), rep(result$dataset_pair[2], length(nodes2)))
          )
          
          edge_coords <- edge_sample %>%
            left_join(node_df %>% select(id, x, y), by = c("from" = "id")) %>%
            rename(x_from = x, y_from = y) %>%
            left_join(node_df %>% select(id, x, y), by = c("to" = "id")) %>%
            rename(x_to = x, y_to = y)
          
          # Node size scaling
          node_size_scale <- input$network_node_size %||% 12
          edge_width_scale <- input$network_edge_width %||% 2
          
          # Color by degree option
          if (isTRUE(input$network_color_by_degree)) {
            node_color_var <- "degree"
            node_color_name <- "Connectivity"
            node_color_values <- scales::viridis_pal()(100)
          } else {
            node_color_var <- "dataset"
            node_color_name <- "Dataset"
            node_color_values <- color_map
          }
          
          # Base plot
          p <- ggplot() +
            geom_segment(data = edge_coords,
                         aes(x = x_from, y = y_from, xend = x_to, yend = y_to,
                             color = correlation, alpha = abs(correlation)),
                         linewidth = edge_width_scale * 0.1) +
            geom_point(data = node_df,
                       aes(x = x, y = y, fill = .data[[node_color_var]]),
                       size = node_size_scale * 0.33, shape = 21, color = "white", stroke = 1)
          
          # Apply color scale based on selection
          if (isTRUE(input$network_color_by_degree)) {
            p <- p + scale_fill_viridis_c(name = node_color_name)
          } else {
            p <- p + scale_fill_manual(values = node_color_values, labels = label_map, name = node_color_name)
          }
          
          # Add labels if requested
          if (isTRUE(input$network_show_labels)) {
            p <- p + geom_text(data = node_df,
                              aes(x = x, y = y, label = id),
                              size = 3, vjust = -1, hjust = 0.5,
                              check_overlap = TRUE)
          }
          
          # Complete the plot
          p <- p +
            scale_color_gradient2(low = "#3b82f6", mid = "gray80", high = "#ef4444",
                                  midpoint = 0, limits = c(-1, 1),
                                  name = "Correlation") +
            scale_alpha_continuous(range = c(0.3, 0.8), guide = "none") +
            labs(title = "Cross-Omics Correlation Network (Bipartite)",
              subtitle = paste("Top", nrow(edge_sample), "correlations (cap:", result$max_edges, ")")) +
            theme_void() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 11, hjust = 0.5),
              legend.position = "right"
            )
          
          # Save the plot
          dpi <- get_safe_global_dpi()
          image_format <- get_safe_global_image_format()
          ggsave(file, plot = p, dpi = dpi, width = 12, height = 8, units = "in")
        }
      }
    }
  )
  
  # Track the user's current grouping selection so it can be restored after UI updates
  group_by_selection <- reactiveVal("")
  observeEvent(input$factor_values_group_by, {
    group_by_selection(input$factor_values_group_by %||% "")
  }, ignoreInit = TRUE)

  update_mofa_covariate_ui <- function() {
    if (is.null(mofa_metadata$covariates)) return()

    covariate_choices <- colnames(mofa_metadata$covariates)
    display_cov_choices <- gsub("\\.", " ", covariate_choices)
    updateSelectInput(session, "factor_values_covariate",
                      choices = setNames(covariate_choices, display_cov_choices),
                      selected = if (length(covariate_choices) > 0) covariate_choices[1] else "")

    prev_group <- group_by_selection()
    if (!prev_group %in% c("", covariate_choices)) {
      prev_group <- ""
      group_by_selection("")
    }

    # Build choices, ensuring "None" is always available and not conflicted with covariate names
    choices <- c("None" = "")
    if (length(covariate_choices) > 0) {
      # Filter out any covariate named "None" to avoid conflicts
      valid_covariates <- covariate_choices[covariate_choices != "None"]
      if (length(valid_covariates) > 0) {
        choices <- c(choices, setNames(valid_covariates, gsub("\\.", " ", valid_covariates)))
      }
    }

    updateSelectInput(session, "factor_values_group_by",
                      choices = choices,
                      selected = if (prev_group == "") "" else prev_group)

    # Update shape-by choices to mirror group-by choices
    updateSelectInput(session, "factor_values_shape_by",
                      choices = choices,
                      selected = "")

    updateSelectInput(session, "mol_sig_annotation_samples",
                      choices = c("None" = "", stats::setNames(covariate_choices, display_cov_choices)),
                      selected = "")
  }

  update_mofa_mol_sig_color_choices <- function() {
    color_choices <- c("Factor value" = "factor_value")
    if (!is.null(multiomics$sample_groups)) {
      color_choices <- c(color_choices, "Group/Condition" = "group")
    }
    if (!is.null(mofa_metadata$covariates)) {
      covariate_choices <- colnames(mofa_metadata$covariates)
      display_cov_choices <- gsub("\\.", " ", covariate_choices)
      color_choices <- c(color_choices, setNames(covariate_choices, display_cov_choices))
    }
    updateSelectInput(session, "mol_sig_color_by",
                      choices = color_choices,
                      selected = "factor_value")
  }

  update_mofa_factor_pair_choices <- function() {
    if (is.null(multiomics$integration_results)) return()
    result <- multiomics$integration_results
    if (result$method != "mofa" || is.null(result$factors)) return()

    factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
    color_choices <- c("Factor 1" = "Factor1")
    if (length(factor_cols) > 1) {
      for (i in 2:length(factor_cols)) {
        color_choices <- c(color_choices, setNames(factor_cols[i], factor_cols[i]))
      }
    }
    if (!is.null(multiomics$sample_groups)) {
      color_choices <- c(color_choices, "Group/Condition" = "group")
    }
    if (!is.null(mofa_metadata$covariates)) {
      cov_choices <- colnames(mofa_metadata$covariates)
      display_cov_choices <- gsub("\\.", " ", cov_choices)
      color_choices <- c(color_choices, setNames(cov_choices, display_cov_choices))
    }

    updateSelectInput(session, "factor_pair_color",
                      choices = color_choices,
                      selected = "group")

    shape_choices <- c("None" = "none")
    if (!is.null(mofa_metadata$covariates)) {
      cov_choices <- colnames(mofa_metadata$covariates)
      display_cov_choices <- gsub("\\.", " ", cov_choices)
      shape_choices <- c(shape_choices, setNames(cov_choices, display_cov_choices))
    }

    updateSelectInput(session, "factor_pair_shape",
                      choices = shape_choices,
                      selected = "none")
  }

  update_mofa_dimred_color_choices <- function() {
    if (is.null(multiomics$integration_results)) return()
    result <- multiomics$integration_results
    if (result$method != "mofa" || is.null(result$factors)) return()

    factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
    color_choices <- c()
    if (!is.null(multiomics$sample_groups)) {
      color_choices <- c(color_choices, "Group/Condition" = "group")
    }
    if (!is.null(mofa_metadata$covariates)) {
      covariate_choices <- colnames(mofa_metadata$covariates)
      if (length(covariate_choices) > 0) {
        display_cov_choices <- gsub("\\.", " ", covariate_choices)
        color_choices <- c(color_choices, setNames(covariate_choices, display_cov_choices))
      }
    }
    if (length(factor_cols) > 0) {
      names(factor_cols) <- factor_cols
      color_choices <- c(color_choices, factor_cols)
    }
    if (length(color_choices) == 0) {
      color_choices <- c("Group/Condition" = "group")
    }
    updateSelectInput(session, "dimred_color",
                      choices = color_choices,
                      selected = unname(color_choices[[1]]))
  }

  # Update covariate choices when MOFA results loaded
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    update_mofa_covariate_ui()
  })

  # Update covariate choices whenever metadata covariates change (tutorial + real data)
  observeEvent(mofa_metadata$covariates, {
    update_mofa_covariate_ui()
  })
  
  # Update molecular signatures choices when MOFA results loaded
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$factors) && !is.null(result$weights)) {
      # Update view choices
      view_choices <- result$views
      updateSelectInput(session, "mol_sig_view",
                        choices = view_choices,
                        selected = view_choices[1])
      
      # Update factor choices
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]
      updateSelectInput(session, "mol_sig_factor",
                        choices = factor_cols,
                        selected = factor_cols[1])
    }
  })
  
  # Update color by choices for molecular signatures
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    update_mofa_mol_sig_color_choices()
  })

  # Update molecular signature color choices when covariates change
  observeEvent(mofa_metadata$covariates, {
    update_mofa_mol_sig_color_choices()
  })
  
  # Update top weights choices
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$factors) && !is.null(result$weights)) {
      # Update view choices
      view_choices <- result$views
      updateSelectInput(session, "top_weights_view",
                        choices = view_choices,
                        selected = view_choices[1])
      
      # Update factor choices
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]
      updateSelectInput(session, "top_weights_factor",
                        choices = factor_cols,
                        selected = factor_cols[1])
    }
  })

  # Update MOFA GSEA UI controls when MOFA results load
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    if (result$method == "mofa" && !is.null(result$factors) && !is.null(result$weights)) {
      view_choices <- NULL
      if (!is.null(result$views)) {
        view_choices <- result$views
      } else if (is.list(result$weights)) {
        view_choices <- names(result$weights)
      }
      if (!is.null(view_choices) && length(view_choices) > 0) {
        updateSelectInput(session, "mofa_enrich_view", choices = view_choices, selected = view_choices[1])
      }
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]
      if (length(factor_cols) > 0) {
        updateSelectInput(session, "mofa_enrich_factor", choices = factor_cols, selected = factor_cols[1])
      }
    }
  })
  
  # Update factor pair choices
  observeEvent(multiomics$integration_results, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "mofa" && !is.null(result$factors)) {
      factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      factor_cols <- factor_cols[order(as.numeric(sub("Factor", "", factor_cols)))]
      
      # Allow selecting multiple factors for pairwise plotting
      updateSelectizeInput(session, "factor_pair_factors",
                           choices = factor_cols,
                           selected = if (length(factor_cols) > 1) factor_cols[1:min(3, length(factor_cols))] else factor_cols[1],
                           server = TRUE)

      # Ensure X/Y selectors exist and populate them for the conditional single-pair mode
      updateSelectInput(session, "factor_pair_x_selected",
                        choices = factor_cols,
                        selected = if (length(factor_cols) > 0) factor_cols[1] else NULL)
      updateSelectInput(session, "factor_pair_y_selected",
                        choices = factor_cols,
                        selected = if (length(factor_cols) > 1) factor_cols[2] else if (length(factor_cols) == 1) factor_cols[1] else NULL)

      # Keep X/Y selectors in sync with the selected factor list and pairwise toggle
      observeEvent(list(input$factor_pair_factors, input$factor_pair_combinations), {
        fs <- input$factor_pair_factors %||% character(0)
        # update choices to reflect available factors
        updateSelectInput(session, "factor_pair_x_selected", choices = fs, selected = if (!is.null(input$factor_pair_x_selected) && input$factor_pair_x_selected %in% fs) input$factor_pair_x_selected else if (length(fs) >= 1) fs[1] else NULL)
        updateSelectInput(session, "factor_pair_y_selected", choices = fs, selected = if (!is.null(input$factor_pair_y_selected) && input$factor_pair_y_selected %in% fs) input$factor_pair_y_selected else if (length(fs) >= 2) fs[2] else if (length(fs) == 1) fs[1] else NULL)
      }, ignoreInit = TRUE)

      # Swap axes button
      observeEvent(input$factor_pair_swap_axes, {
        oldx <- input$factor_pair_x_selected
        oldy <- input$factor_pair_y_selected
        if (!is.null(oldx) || !is.null(oldy)) {
          updateSelectInput(session, "factor_pair_x_selected", selected = if (!is.null(oldy) && nzchar(oldy)) oldy else oldx)
          updateSelectInput(session, "factor_pair_y_selected", selected = if (!is.null(oldx) && nzchar(oldx)) oldx else oldy)
        }
      })
      
      # Update color/shape choices
      update_mofa_factor_pair_choices()
    }
  })

  # Update factor pair color/shape choices when covariates change
  observeEvent(mofa_metadata$covariates, {
    update_mofa_factor_pair_choices()
  })
  
  # Feature Scatter Plot
  output$mofa_feature_scatter_plot <- renderPlot({ 
    req(multiomics$integration_results, input$feature_scatter_view, input$feature_scatter_factor)
    result <- multiomics$integration_results
    
    if (result$method != "mofa") {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "Feature scatter plots available for MOFA analysis",
                                 size = 5, color = "#667eea") + theme_void())
    }
    
    tryCatch({
      # Get the weights for selected view and factor
      weights_list <- result$weights
      view_name <- input$feature_scatter_view
      factor_name <- input$feature_scatter_factor
      
      if (!view_name %in% names(weights_list)) {
        return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                   label = "View not found",
                                   size = 5, color = "#f59e0b") + theme_void())
      }
      
      weights_df <- weights_list[[view_name]]
      
      # Get top features by weight
      top_features <- weights_df %>%
        arrange(desc(abs(.data[[factor_name]]))) %>%
        head(input$feature_scatter_n) %>%
        pull(Feature)
      
      # Prepare plot data (would ideally use actual data)
      plot_data <- data.frame(
        Factor = rep(result$factors[[factor_name]], length(top_features)),
        Feature = rep(top_features, each = nrow(result$factors)),
        Sample = rep(result$factors$Sample, length(top_features))
      )
      
      # Add coloring data based on selection
      color_by <- if (!is.null(input$feature_scatter_color)) input$feature_scatter_color else "factor"
      
      if (color_by == "factor" && !is.null(input$feature_scatter_color_factor)) {
        # Color by another factor
        color_factor <- input$feature_scatter_color_factor
        if (color_factor %in% colnames(result$factors)) {
          plot_data$ColorFactor <- rep(result$factors[[color_factor]], length(top_features))
        }
      } else if (color_by == "group" && !is.null(multiomics$sample_groups)) {
        # Color by group/condition
        plot_data$ColorGroup <- rep(multiomics$sample_groups[plot_data$Sample], nrow(plot_data))
      }
      
      # Create scatter plot
      if (color_by == "factor" && "ColorFactor" %in% colnames(plot_data)) {
        # Continuous color scale by factor
        use_continuous_scale <- if (!is.null(input$feature_scatter_color_scale)) input$feature_scatter_color_scale else TRUE
        
        p <- ggplot(plot_data, aes(x = Factor, y = Feature, color = ColorFactor)) +
          geom_point(size = 3, alpha = 0.7) +
          facet_wrap(~Feature, scales = "free_y", nrow = 2)
        
        if (use_continuous_scale) {
          p <- p + scale_color_viridis_c(name = input$feature_scatter_color_factor, option = "turbo")
        } else {
          p <- p + scale_color_gradientn(colors = c("#3b82f6", "#667eea", "#a855f7", "#ec4899", "#f43f5e"),
                                         name = input$feature_scatter_color_factor)
        }
      } else if (color_by == "group" && "ColorGroup" %in% colnames(plot_data)) {
        # Categorical color scale by group
        p <- ggplot(plot_data, aes(x = Factor, y = Feature, color = ColorGroup)) +
          geom_point(size = 3, alpha = 0.7) +
          facet_wrap(~Feature, scales = "free_y", nrow = 2) +
          scale_color_brewer(palette = "Set2", name = "Group")
      } else {
        # Default coloring
        p <- ggplot(plot_data, aes(x = Factor, y = Feature)) +
          geom_point(size = 3, alpha = 0.6, color = "#667eea") +
          facet_wrap(~Feature, scales = "free_y", nrow = 2)
      }
      
      if (input$feature_scatter_lm) {
        p <- p + geom_smooth(method = "lm", se = TRUE, color = "#ef4444", alpha = 0.2)
      }
      
      p <- p +
        labs(title = paste0("Feature Scatter - ", view_name, " vs ", factor_name),
             subtitle = "Top features by weight",
             x = factor_name, y = "Feature Value (illustrative)") +
        ggprism::theme_prism() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 11, hjust = 0.5),
          strip.text = element_text(face = "bold", size = 9),
          legend.position = "right"
        )

      p <- apply_mofa_text_fix(p)
      p
    }, error = function(e) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = paste("Error:", e$message),
                 size = 4, color = "#ef4444") +
        theme_void()
    })
  })

  outputOptions(output, "integration_method_params", suspendWhenHidden = FALSE)
  
  # Compute dimensionality reduction (UMAP/t-SNE)
  observeEvent(input$compute_dimred, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results

    if (result$method != "mofa" || is.null(result$factors)) {
      showNotification("Dimensionality reduction only available for MOFA analysis", type = "warning")
      return()
    }

    dimred_space <- input$dimred_space %||% "mofa"
    
    tryCatch({
      if (identical(dimred_space, "mofa")) {
        if (is.null(result$mofa_model)) {
          showNotification("MOFA model not available", type = "warning")
          return()
        }

        model <- result$mofa_model

        # Ensure covariates are present in the model metadata so plot_dimred() can color by them
        if (!is.null(mofa_metadata$covariates) && is.data.frame(mofa_metadata$covariates) && nrow(mofa_metadata$covariates) > 0) {
          md <- tryCatch(MOFA2::samples_metadata(model), error = function(e) NULL)
          if (is.null(md) || nrow(md) == 0) {
            md <- data.frame(sample = result$factors$Sample, stringsAsFactors = FALSE)
          }
          if (!"sample" %in% colnames(md)) {
            md$sample <- if (!is.null(rownames(md)) && all(nzchar(rownames(md)))) rownames(md) else result$factors$Sample
          }

          cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
          if (!"sample" %in% colnames(cov_df)) {
            cov_df$sample <- rownames(cov_df)
          }
          cov_df <- cov_df[!is.na(cov_df$sample) & nzchar(cov_df$sample), , drop = FALSE]
          if (any(duplicated(cov_df$sample))) cov_df <- cov_df[!duplicated(cov_df$sample), , drop = FALSE]

          match_idx <- match(md$sample, cov_df$sample)
          cols_to_add <- setdiff(colnames(cov_df), "sample")
          for (col_name in cols_to_add) {
            md[[col_name]] <- cov_df[[col_name]][match_idx]
          }

          tryCatch({
            MOFA2::samples_metadata(model) <- md
          }, error = function(e) NULL)
        }

        all_factor_names <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
        selected_factors <- input$dimred_factors
        if (is.null(selected_factors) || length(selected_factors) == 0 || identical(selected_factors, "Loading...")) {
          selected_factors <- all_factor_names
        }
        selected_factors <- intersect(selected_factors, all_factor_names)
        factor_idx <- suppressWarnings(as.integer(sub("Factor", "", selected_factors)))
        factor_idx <- factor_idx[!is.na(factor_idx) & factor_idx > 0]

        if (length(factor_idx) == 0) {
          showNotification("No factors selected for dimensionality reduction", type = "warning")
          return()
        }

        if (input$dimred_method == "UMAP") {
          showNotification("Computing UMAP (MOFA2)...", type = "message", duration = NULL, id = "dimred_progress")
          model <- MOFA2::run_umap(
            model,
            factors = factor_idx,
            n_neighbors = input$dimred_umap_n_neighbors,
            min_dist = input$dimred_umap_min_dist
          )
        } else if (input$dimred_method == "t-SNE") {
          showNotification("Computing t-SNE (MOFA2)...", type = "message", duration = NULL, id = "dimred_progress")
          model <- MOFA2::run_tsne(
            model,
            factors = factor_idx,
            perplexity = input$dimred_perplexity
          )
        }

        # Store dimred-computed model separately to avoid retriggering
        # integration_results observers (which can reset the ready flag).
        multiomics$mofa_model_dimred <- model
        multiomics$view_dimred <- NULL
        multiomics$mofa_dimred_ready <- TRUE

        removeNotification(id = "dimred_progress")
        showNotification(paste0(input$dimred_method, " computed successfully!"), type = "message", duration = 3)
      } else {
        # View-based dimred: PCA/SVD on a single view matrix (samples x features), then UMAP/t-SNE
        view_name <- input$dimred_view_source
        if (is.null(view_name) || identical(view_name, "Loading...") || !nzchar(view_name)) {
          showNotification("Select a view first", type = "warning")
          return()
        }

        if (is.null(multiomics$loaded_analyses) || is.null(multiomics$loaded_analyses[[view_name]]) ||
            is.null(multiomics$loaded_analyses[[view_name]]$data)) {
          showNotification("Selected view data not available", type = "warning")
          return()
        }

        mat <- multiomics$loaded_analyses[[view_name]]$data
        if (!is.matrix(mat) && !is.data.frame(mat)) {
          showNotification("View data matrix not in a supported format", type = "warning")
          return()
        }

        sample_ids <- as.character(result$factors$Sample)
        if (is.null(colnames(mat))) {
          showNotification("View matrix has no sample column names", type = "warning")
          return()
        }

        common_samples <- intersect(sample_ids, colnames(mat))
        if (length(common_samples) < 3) {
          showNotification("Not enough overlapping samples for view-based dimred", type = "warning")
          return()
        }

        # samples x features
        X <- t(as.matrix(mat[, common_samples, drop = FALSE]))
        X[!is.finite(X)] <- 0

        preprocess <- input$dimred_view_preprocess %||% "pca"
        k <- as.integer(input$dimred_view_k %||% 10)
        max_k <- min(nrow(X) - 1L, ncol(X))
        if (!is.finite(max_k) || max_k < 2L) {
          showNotification("View matrix too small for dimred (need >=2 usable dimensions)", type = "warning")
          return()
        }
        k <- max(2L, min(k, max_k))

        embedding <- NULL
        if (identical(preprocess, "pca")) {
          pr <- stats::prcomp(X, center = TRUE, scale. = isTRUE(input$dimred_view_scale), rank. = k)
          embedding <- pr$x
        } else if (identical(preprocess, "svd")) {
          if (!requireNamespace("RSpectra", quietly = TRUE)) {
            showNotification("RSpectra is required for SVD preprocessing", type = "warning")
            return()
          }
          X2 <- log1p(pmax(X, 0))
          sv <- RSpectra::svds(X2, k = k)
          embedding <- sv$u %*% diag(sv$d, nrow = k, ncol = k)
          rownames(embedding) <- rownames(X)
        } else {
          # None: use a light, stable feature subset + centering
          feat_vars <- apply(X, 2, stats::var, na.rm = TRUE)
          feat_vars[!is.finite(feat_vars)] <- 0
          top_n <- min(2000, ncol(X))
          keep_idx <- order(feat_vars, decreasing = TRUE)[seq_len(top_n)]
          embedding <- scale(X[, keep_idx, drop = FALSE], center = TRUE, scale = FALSE)
        }

        # Ensure k dims present
        if (ncol(embedding) > k) embedding <- embedding[, seq_len(k), drop = FALSE]
        if (ncol(embedding) < 2) {
          showNotification("Preprocessing produced <2 dimensions", type = "warning")
          return()
        }

        if (input$dimred_method == "UMAP") {
          if (!requireNamespace("umap", quietly = TRUE)) {
            showNotification("umap package is required for view-based UMAP", type = "warning")
            return()
          }
          showNotification("Computing UMAP (view-based)...", type = "message", duration = NULL, id = "dimred_progress")
          cfg <- umap::umap.defaults
          cfg$n_neighbors <- input$dimred_umap_n_neighbors
          cfg$min_dist <- input$dimred_umap_min_dist
          um <- umap::umap(embedding, config = cfg)
          coords <- um$layout
          colnames(coords) <- c("UMAP1", "UMAP2")
        } else {
          if (!requireNamespace("Rtsne", quietly = TRUE)) {
            showNotification("Rtsne package is required for view-based t-SNE", type = "warning")
            return()
          }
          showNotification("Computing t-SNE (view-based)...", type = "message", duration = NULL, id = "dimred_progress")
          set.seed(42)
          ts <- Rtsne::Rtsne(embedding, dims = 2, perplexity = input$dimred_perplexity, check_duplicates = FALSE)
          coords <- ts$Y
          colnames(coords) <- c("tSNE1", "tSNE2")
        }

        removeNotification(id = "dimred_progress")

        df <- data.frame(
          Sample = rownames(embedding),
          stringsAsFactors = FALSE
        )
        df <- cbind(df, as.data.frame(coords, stringsAsFactors = FALSE))

        # Attach group/covariates/factors for coloring
        if (!is.null(multiomics$sample_groups)) {
          df$group <- as.character(multiomics$sample_groups[df$Sample])
        }
        if (!is.null(mofa_metadata$covariates) && is.data.frame(mofa_metadata$covariates)) {
          cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
          if (!"sample" %in% colnames(cov_df)) cov_df$sample <- rownames(cov_df)
          cov_df <- cov_df[!is.na(cov_df$sample) & nzchar(cov_df$sample), , drop = FALSE]
          if (any(duplicated(cov_df$sample))) cov_df <- cov_df[!duplicated(cov_df$sample), , drop = FALSE]
          m_idx <- match(df$Sample, cov_df$sample)
          for (cn in setdiff(colnames(cov_df), "sample")) {
            df[[cn]] <- cov_df[[cn]][m_idx]
          }
        }
        factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
        factor_df <- result$factors[, c("Sample", factor_cols), drop = FALSE]
        m_idx2 <- match(df$Sample, factor_df$Sample)
        for (cn in factor_cols) {
          df[[cn]] <- factor_df[[cn]][m_idx2]
        }

        multiomics$view_dimred <- df
        multiomics$mofa_dimred_ready <- TRUE
        showNotification(paste0(input$dimred_method, " computed successfully!"), type = "message", duration = 3)
      }
    }, error = function(e) {
      removeNotification(id = "dimred_progress")
      showNotification(paste("Error computing reduction:", e$message), type = "error")
    })
  })

  # Any change to computation-relevant inputs should require recompute
  observeEvent(
    list(
      input$dimred_space,
      input$dimred_method,
      input$dimred_factors,
      input$dimred_view_source,
      input$dimred_view_preprocess,
      input$dimred_view_k,
      input$dimred_view_scale,
      input$dimred_umap_n_neighbors,
      input$dimred_umap_min_dist,
      input$dimred_perplexity
    ),
    {
      multiomics$mofa_dimred_ready <- FALSE
    },
    ignoreInit = TRUE
  )
  
  # Dimensionality Reduction Plot
  output$mofa_dimred_plot <- renderPlot({ 
    req(multiomics$integration_results)
    result <- multiomics$integration_results

    dimred_space <- input$dimred_space %||% "mofa"

    req(multiomics$mofa_dimred_ready)

    if (identical(dimred_space, "view")) {
      req(multiomics$view_dimred)
      df <- multiomics$view_dimred

      x_col <- if (input$dimred_method == "UMAP") "UMAP1" else "tSNE1"
      y_col <- if (input$dimred_method == "UMAP") "UMAP2" else "tSNE2"

      color_by <- input$dimred_color
      if (is.null(color_by) || identical(color_by, "Loading...")) color_by <- "group"

      color_vals <- NULL
      if (identical(color_by, "group")) {
        color_vals <- df$group
      } else if (color_by %in% colnames(df)) {
        color_vals <- df[[color_by]]
      }

      if (is.null(color_vals)) {
        color_vals <- rep("", nrow(df))
      }

      is_cont <- is.numeric(color_vals) || (suppressWarnings(!all(is.na(as.numeric(color_vals)))) && length(unique(color_vals)) > 5)
      if (!is_cont) {
        color_vals <- as.factor(color_vals)
      } else {
        color_vals <- suppressWarnings(as.numeric(color_vals))
      }
      df$ColorVar <- color_vals

      if (is_cont) {
        p <- ggplot(df, aes_string(x = x_col, y = y_col, color = "ColorVar")) +
          geom_point(size = input$dimred_dot_size, alpha = 0.9)
        p <- p + scale_color_viridis_c(option = "D", na.value = "grey70")
      } else {
        p <- ggplot(df, aes_string(x = x_col, y = y_col, fill = "ColorVar")) +
          geom_point(shape = 21, color = "black", stroke = input$dimred_stroke, size = input$dimred_dot_size, alpha = 0.9)
        p <- p + scale_fill_brewer(palette = "Set2", na.value = "grey70")
      }

      if (isTRUE(input$dimred_label) && requireNamespace("ggrepel", quietly = TRUE)) {
        p <- p + ggrepel::geom_text_repel(aes(label = Sample), size = 2, max.overlaps = 30)
      }

      p <- p +
        labs(
          title = paste0(input$dimred_method, " (Single view): ", input$dimred_view_source %||% ""),
          x = x_col,
          y = y_col
        ) +
        ggprism::theme_prism() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          legend.position = if (isTRUE(input$dimred_legend)) "right" else "none"
        )

      p <- apply_mofa_text_fix(p)
      return(p)
    }

    if (result$method != "mofa" || is.null(result$mofa_model)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                label = "MOFA model not available",
                                size = 5, color = "#667eea") + theme_void())
    }

    method_arg <- if (input$dimred_method == "UMAP") "UMAP" else "TSNE"
    color_by <- input$dimred_color

    model_to_plot <- multiomics$mofa_model_dimred %||% result$mofa_model

    p <- MOFA2::plot_dimred(
      model_to_plot,
      method = method_arg,
      color_by = color_by,
      label = isTRUE(input$dimred_label),
      stroke = input$dimred_stroke,
      dot_size = input$dimred_dot_size,
      legend = isTRUE(input$dimred_legend)
    )

    p + ggprism::theme_prism() +
      theme(
        plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
        plot.subtitle = element_text(size = 11, hjust = 0.5),
        legend.position = "right"
      ) %>%
      apply_mofa_text_fix()
  })
  
  # Factor Correlation Plot
  output$mofa_factor_cor_plot <- renderPlot({ 
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "mofa" || is.null(result$mofa_model)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Factor correlation analysis available for MOFA",
                        size = 5, color = "#667eea") +
               theme_void())
    }
    
    tryCatch({
      # Use MOFA2's native plot_factor_cor function
      cor_method <- tolower(if (!is.null(input$mofa_cor_method)) input$mofa_cor_method else "pearson")
      
      # Call MOFA2::plot_factor_cor with the model
      p <- MOFA2::plot_factor_cor(result$mofa_model, method = cor_method)
      
      # Apply consistent theming
      p <- p + ggprism::theme_prism() +
        theme(
          plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 11, hjust = 0.5),
          legend.position = "right"
        )

      p <- apply_mofa_text_fix(p)
      p
      
    }, error = function(e) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = paste("Error:", e$message),
                 size = 4, color = "#ef4444") +
        theme_void()
    })
  })
  
  # Download handler for factor correlation plot
  output$download_factor_cor <- downloadHandler(
    filename = function() {
      paste0("MOFA_Factor_Correlation_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".", get_safe_global_image_format())
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "mofa" && !is.null(result$mofa_model)) {
        tryCatch({
          # Use MOFA2's native plot_factor_cor function
          cor_method <- tolower(if (!is.null(input$mofa_cor_method)) input$mofa_cor_method else "pearson")
          
          # Call MOFA2::plot_factor_cor with the model
          p <- MOFA2::plot_factor_cor(result$mofa_model, method = cor_method)
          
          # Apply consistent theming - match UI render
          p <- p + ggprism::theme_prism() +
            theme(
              plot.title = element_text(size = 14, face = "bold", hjust = 0.5),
              plot.subtitle = element_text(size = 11, hjust = 0.5),
              legend.position = "right"
            )

          # Save with the same size as the UI plotOutput
          save_plot_like_ui(p, file, session, "mofa_factor_cor_plot")
        }, error = function(e) {
          # Fallback plot
          p <- ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = "Factor correlation unavailable",
                     size = 5, color = "#667eea") +
            theme_void()
          save_plot_like_ui(p, file, session, "mofa_factor_cor_plot")
        })
      }
    }
  )
  
  # Feature Weights Plot
  output$mofa_feature_weights_plot <- renderPlot({ 
    req(multiomics$integration_results, input$feature_weights_view, input$feature_weights_factor)
    result <- multiomics$integration_results
    
    if (result$method != "mofa" || is.null(result$mofa_model)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Feature weights available for MOFA analysis",
                        size = 5, color = "#667eea") +
               theme_void())
    }
    
    tryCatch({
      # Get the selected parameters
      view_name <- input$feature_weights_view
      factor_name <- input$feature_weights_factor
      n_features <- if (!is.null(input$feature_weights_n)) input$feature_weights_n else 10
      
      # Create top weights plot
      p_top <- MOFA2::plot_top_weights(
        object = result$mofa_model,
        view = view_name,
        factor = factor_name,
        nfeatures = n_features,
        scale = input$feature_weights_scale,
        abs = TRUE
      )
      
      # Modify the top weights plot
      if (!is.null(p_top)) {
        weights_df <- result$weights[[view_name]]
        if (!is.null(weights_df) && all(c("Feature", "Feature_full") %in% colnames(weights_df))) {
          mapping <- setNames(as.character(weights_df$Feature), as.character(weights_df$Feature_full))
          views_all <- names(result$weights)
          if (is.null(views_all) || length(views_all) == 0) {
            views_all <- tryCatch(MOFA2::views_names(result$mofa_model), error = function(e) NULL)
          }
          p_top <- p_top +
            scale_x_discrete(
              labels = function(x) strip_mofa_view_suffix(x, views_all),
              expand = expansion(add = c(0.5, 0.5))
            )
        }
        # MOFA2 weight plots use coord_flip(); x-label would appear as y-axis title.
        # Keep Weight on the horizontal axis and remove the vertical axis title.
        p_top <- p_top + labs(x = NULL, y = "Weight") + geom_point(size = 3)
      }
      
      # Create all weights plot
      p_all <- MOFA2::plot_weights(
        object = result$mofa_model,
        view = view_name,
        factor = factor_name,
        nfeatures = n_features,
        scale = input$feature_weights_scale
      )
      
      # Modify the all weights plot
      if (!is.null(p_all)) {
        weights_df <- result$weights[[view_name]]
        if (!is.null(weights_df) && all(c("Feature", "Feature_full") %in% colnames(weights_df))) {
          mapping <- setNames(as.character(weights_df$Feature), as.character(weights_df$Feature_full))
          views_all <- names(result$weights)
          if (is.null(views_all) || length(views_all) == 0) {
            views_all <- tryCatch(MOFA2::views_names(result$mofa_model), error = function(e) NULL)
          }
          p_all <- p_all +
            scale_y_discrete(
              labels = function(x) strip_mofa_view_suffix(x, views_all),
              expand = expansion(add = c(0.5, 0.5))
            )
          # Also clean up ggrepel text labels (e.g., feature names on the right plot)
          p_all <- strip_ggrepel_text_labels(p_all, views_all, mapping = mapping)
        }
        p_all <- p_all + labs(y = "Rank") + geom_point(size = 1.5)
      }
      
      # Apply consistent theming to each plot (avoid relying on patchwork operators)
      p_top <- p_top + ggprism::theme_prism() +
        theme(
          legend.position = "right",
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          axis.text.x = element_text(),
          axis.ticks.x = element_line(),
          axis.ticks.length.x = unit(0.2, "cm")
        )

      p_all <- p_all + ggprism::theme_prism() +
        theme(
          legend.position = "right",
          panel.border = element_rect(color = "black", fill = NA, size = 1),
          # coord_flip() in MOFA2 means the weight axis is the (rendered) x-axis.
          axis.line.x = element_line(),
          axis.text.x = element_text(),
          axis.text.x.bottom = element_text(),
          axis.text.x.top = element_text(),
          axis.ticks.x = element_line(),
          axis.ticks.x.bottom = element_line(),
          axis.ticks.x.top = element_line(),
          axis.ticks.length.x = unit(0.2, "cm"),
          # Keep the feature label axis clean (labels are drawn via ggrepel)
          axis.text.y = element_blank(),
          axis.ticks.y = element_blank()
        )

      # Combine plots side by side using patchwork explicitly
      combined_plot <- patchwork::wrap_plots(p_top, p_all, ncol = 2)

      combined_plot <- apply_mofa_text_fix(combined_plot)
      combined_plot
      
    }, error = function(e) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = paste("Error:", e$message),
                 size = 4, color = "#ef4444") +
        theme_void()
    })
  })
  
  # Download handler for Top Weights plot
  output$download_feature_weights_top <- downloadHandler(
