          }

          # Apply consistent theming
          p_all <- p_all + ggprism::theme_prism() +
            theme(
              legend.position = "right",
              panel.border = element_rect(color = "black", fill = NA, size = 1),
              # coord_flip() in MOFA2 means the weight axis is the (rendered) x-axis.
              axis.line.x = element_line(),
              axis.text.x = element_text(),
              axis.text.x.bottom = element_text(),
              axis.text.x.top = element_text(),
              axis.ticks.x = element_line(),
              axis.ticks.x.bottom = element_line(),
              axis.ticks.x.top = element_line(),
              axis.ticks.length.x = unit(0.2, "cm"),
              # Keep the feature label axis clean (labels are drawn via ggrepel)
              axis.text.y = element_blank(),
              axis.ticks.y = element_blank()
            )

          p_all
        }, error = function(e) ggplot())
      )
      dev.off()
    }
  )
  
  # Observer to show/hide Top Features slider based on plot type
  observeEvent(input$feature_weights_plot_type, {
    if (is.null(input$feature_weights_plot_type)) return()
    if (input$feature_weights_plot_type == "all") {
      # Hide the Top Features slider when "All Weights" is selected
      shinyjs::hide("feature_weights_n")
    } else {
      # Show the Top Features slider when "Top Weights" is selected
      shinyjs::show("feature_weights_n")
    }
  })
  
  # Individual Factor Values Plot Container
  output$factor_values_plot_container <- renderUI({
    height_px <- if (!is.null(input$factor_values_plot_customization) && 
                     input$factor_values_plot_customization && 
                     !is.null(input$factor_values_plot_height)) {
      paste0(input$factor_values_plot_height * 100, "px")
    } else {
      "550px"
    }
    
    plotOutput("mofa_factor_values_plot", height = height_px, width = "100%")
  })
  
  # Individual Factor Values Plot - MOFA Tutorial-style beeswarm/jitter plots
  # This implementation matches MOFA2::plot_factor() behavior from the CLL tutorial:
  # - When colored by categorical covariate: samples grouped on X by category, factor value on Y
  # - Beeswarm/jitter distribution within groups
  # - Optional violin/boxplot overlays
  output$mofa_factor_values_plot <- renderPlot({ 
    req(multiomics$integration_results, input$factor_values_factor)
    result <- multiomics$integration_results
    
    if (result$method != "mofa" || is.null(result$factors)) {
      return(ggplot() +
               annotate("text", x = 0.5, y = 0.5,
                        label = "Factor values available for MOFA analysis",
                        size = 5, color = "#667eea") +
               theme_void())
    }
    
    tryCatch({
      factor_sel <- input$factor_values_factor %||% character(0)
      color_by <- if (!is.null(input$factor_values_colorby)) input$factor_values_colorby else "value"
      add_violin <- if (!is.null(input$factor_values_violin) && color_by == "covariate") input$factor_values_violin else FALSE
      dodge <- if (!is.null(input$factor_values_dodge)) input$factor_values_dodge else TRUE
      alpha_val <- if (!is.null(input$factor_values_alpha)) input$factor_values_alpha else 0.7
      group_by <- if (!is.null(input$factor_values_group_by)) input$factor_values_group_by else ""
      if (!nzchar(group_by)) group_by <- NULL
      shape_by <- if (!is.null(input$factor_values_shape_by)) input$factor_values_shape_by else ""
      if (!nzchar(shape_by)) shape_by <- NULL

      # Ensure at least one factor is selected
      if (length(factor_sel) == 0) stop("No factors selected")

      # Gather factor data: support single or multiple factors (long format)
      available_factors <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
      chosen_factors <- intersect(factor_sel, available_factors)
      if (length(chosen_factors) == 0) stop("Selected factors are not available in the MOFA result")

      # Keep the original sample order from MOFA model
      sample_order <- as.character(result$factors$Sample)

      if (length(chosen_factors) == 1) {
        factor_name <- chosen_factors[1]
        factor_data <- result$factors %>%
          dplyr::select(Sample, all_of(factor_name)) %>%
          dplyr::rename(FactorValue = all_of(factor_name)) %>%
          dplyr::mutate(Factor = factor_name)
      } else {
        # Pivot to long format for faceting
        factor_data <- result$factors %>%
          dplyr::select(Sample, dplyr::any_of(chosen_factors)) %>%
          tidyr::pivot_longer(cols = -Sample, names_to = "Factor", values_to = "FactorValue")
        # preserve factor order
        factor_data$Factor <- factor(factor_data$Factor, levels = chosen_factors)
      }
      
      # Initialize color variable
      color_label <- "Value"
      # Flag to track if we're using categorical covariate (MOFA tutorial style)
      is_categorical_covariate <- FALSE
      
      # Add color, group, and shape variables based on selection
      if (color_by == "covariate") {
        covariate_name <- input$factor_values_covariate

        if (!is.null(mofa_metadata$covariates) && covariate_name %in% colnames(mofa_metadata$covariates)) {
          # FIX: Properly map covariates using rownames (sample IDs) from the covariate data frame
          # When extracting a column from a data frame, R doesn't preserve rownames as element names
          # So we must explicitly set names using rownames to ensure correct sample-to-covariate mapping
          cov_df <- mofa_metadata$covariates
          cov_vec <- setNames(cov_df[[covariate_name]], rownames(cov_df))

          # Map covariate values to factor_data rows by sample
          sample_cov_map <- cov_vec[as.character(factor_data$Sample)]
          names(sample_cov_map) <- NULL

          # Detect numeric covariates (continuous) - use stricter threshold for categorical detection
          cov_numeric_try <- suppressWarnings(as.numeric(as.character(sample_cov_map)))
          num_non_na <- sum(!is.na(cov_numeric_try))
          unique_vals <- length(unique(cov_numeric_try[!is.na(cov_numeric_try)]))
          # More aggressive categorical detection: if <=10 unique values, treat as categorical
          is_cov_numeric <- (num_non_na / max(1, length(cov_numeric_try)) >= 0.8) && (unique_vals > 10)

          if (is_cov_numeric) {
            factor_data <- factor_data %>% mutate(ColorValue = cov_numeric_try)
            is_categorical_covariate <- FALSE
          } else {
            # Categorical covariate - this triggers MOFA tutorial-style beeswarm plot
            factor_data <- factor_data %>% mutate(ColorValue = as.character(sample_cov_map))
            is_categorical_covariate <- TRUE
          }
          color_label <- covariate_name

          # Map grouping (for violin/box displays and group_by axis)
          if (!is.null(group_by) && !is.null(mofa_metadata$covariates) && group_by %in% colnames(mofa_metadata$covariates)) {
            grp_vec <- setNames(cov_df[[group_by]], rownames(cov_df))
            factor_data <- factor_data %>% mutate(GroupValue = as.character(grp_vec[as.character(Sample)]))
          }

          # Map shape aesthetic if requested
          if (!is.null(shape_by) && shape_by %in% colnames(mofa_metadata$covariates)) {
            shp_vec <- setNames(cov_df[[shape_by]], rownames(cov_df))
            factor_data <- factor_data %>% mutate(ShapeValue = as.character(shp_vec[as.character(Sample)]))
          }
        } else {
          factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
        }
      } else if (color_by == "weight") {
        # Feature weight coloring is only supported for a single selected factor; for
        # multi-factor selection we fall back to coloring by factor value.
        if (length(chosen_factors) == 1) {
          feature_name <- input$factor_values_feature
          weights_view <- input$factor_values_weight_view
          if (!is.null(result$weights) && weights_view %in% names(result$weights)) {
            weights_df <- result$weights[[weights_view]]
            if (feature_name %in% weights_df$Feature) {
              feature_weight <- weights_df %>%
                filter(Feature == feature_name) %>%
                pull(all_of(chosen_factors[1])) %>%
                dplyr::first()
              factor_data <- factor_data %>% mutate(ColorValue = feature_weight)
              color_label <- paste0(feature_name, " Weight")
            } else {
              factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
            }
          } else {
            factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
          }
        } else {
          factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
        }
      } else if (color_by == "feature") {
        # Feature-based coloring is only supported for a single factor selection; otherwise fallback
        if (length(chosen_factors) == 1) {
          feature_name <- input$factor_values_feature
          feature_view <- input$factor_values_feature_view
          if (!is.null(multiomics$loaded_analyses) && feature_view %in% names(multiomics$loaded_analyses)) {
            feature_data <- multiomics$loaded_analyses[[feature_view]]$data
            if (feature_name %in% rownames(feature_data)) {
              feature_values <- feature_data[feature_name, ]
              factor_data <- factor_data %>% mutate(ColorValue = feature_values[match(Sample, colnames(feature_data))])
              color_label <- feature_name
            } else {
              factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
            }
          } else {
            factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
          }
        } else {
          factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
        }
      } else {
        factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
      }
      
      # Prepare plot data
      plot_data <- factor_data
      
      # Add shape aesthetic flag (preserve NA as explicit level)
      if ("ShapeValue" %in% colnames(plot_data)) {
        plot_data$ShapeValue <- as.character(plot_data$ShapeValue)
        plot_data$ShapeValue[is.na(plot_data$ShapeValue) | plot_data$ShapeValue == ""] <- "(Missing)"
        plot_data$ShapeValue <- factor(plot_data$ShapeValue)
      }
      has_shape <- "ShapeValue" %in% colnames(plot_data) && !all(is.na(plot_data$ShapeValue))
      
      # ========================================================================
      # MOFA Tutorial-style plotting logic
      # The MOFA2::plot_factor() function creates beeswarm/jitter plots where:
      # - Categorical covariate: X-axis = covariate categories, Y-axis = factor value
      # - Samples are jittered within each category (beeswarm distribution)
      # - Optional violin/boxplot overlays
      # ========================================================================
      
      if (color_by == "covariate" && is_categorical_covariate) {
        # MOFA Tutorial-style: Categorical covariate beeswarm plot
        # X-axis = covariate categories, Y-axis = factor values
        plot_data$ColorValue <- as.character(plot_data$ColorValue)
        plot_data$ColorValue[is.na(plot_data$ColorValue) | plot_data$ColorValue == ""] <- "(Missing)"
        plot_data$ColorValue <- factor(plot_data$ColorValue)

        if ("GroupValue" %in% colnames(plot_data)) {
          plot_data$GroupValue <- as.character(plot_data$GroupValue)
          plot_data$GroupValue[is.na(plot_data$GroupValue) | plot_data$GroupValue == ""] <- "(Missing)"
          plot_data$GroupValue <- factor(plot_data$GroupValue)
        }

        x_var <- if ("GroupValue" %in% colnames(plot_data)) "GroupValue" else "ColorValue"

        # Avoid violin warnings when a group has < 2 samples
        add_violin_effective <- add_violin
        add_boxplot_effective <- isTRUE(input$factor_values_box)
        group_counts <- dplyr::count(plot_data, .data[[x_var]])
        if (isTRUE(add_violin) && any(group_counts$n < 2)) {
          add_violin_effective <- FALSE
          add_boxplot_effective <- TRUE
        }
        
        if (add_violin_effective) {
          # Violin + jitter (MOFA tutorial style: add_violin = TRUE, dodge = TRUE)
          p <- ggplot(plot_data, aes(x = .data[[x_var]], y = FactorValue, fill = ColorValue))
          
          # Add violin first (background)
          p <- p + geom_violin(alpha = 0.5, scale = "width", color = "black", linewidth = 0.3, trim = TRUE)
          
          # Add boxplot if requested
          if (isTRUE(add_boxplot_effective)) {
            p <- p + geom_boxplot(width = 0.15, outlier.shape = NA, fill = "white", 
                                   color = "black", alpha = 0.7)
          }
          
          # Add jittered points on top
          if (has_shape) {
            if (isTRUE(dodge)) {
              p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            } else {
              p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            }
          } else {
            if (isTRUE(dodge)) {
              p <- p + geom_jitter(aes(color = ColorValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            } else {
              p <- p + geom_jitter(aes(color = ColorValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            }
          }
          
        } else {
          # Jitter only (no violin) - classic MOFA beeswarm style
          p <- ggplot(plot_data, aes(x = .data[[x_var]], y = FactorValue, fill = ColorValue))
          
          # Add boxplot if requested (without violin)
          if (isTRUE(add_boxplot_effective)) {
            p <- p + geom_boxplot(alpha = 0.4, outlier.shape = NA, color = "black")
          }
          
          # Add jittered points
          if (has_shape) {
            p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                  width = 0.25, alpha = alpha_val, size = 2.5, stroke = 0.5)
          } else {
            p <- p + geom_jitter(aes(color = ColorValue), 
                                  width = 0.25, alpha = alpha_val, size = 2.5, stroke = 0.5)
          }
        }
        
        # Apply color scales - use ggplot2's default hue scale to match MOFA2 tutorial style
        # (MOFA2 uses ggplot2 defaults: red/green/blue hue progression)
        n_levels <- nlevels(plot_data$ColorValue)
        if (!is.na(n_levels) && n_levels > 12) {
          # Fallback to rainbow for many levels
          pal <- grDevices::rainbow(n_levels)
          p <- p + scale_fill_manual(values = pal, name = color_label, drop = FALSE) +
            scale_color_manual(values = pal, name = color_label, drop = FALSE)
        } else {
          # Use ggplot2's default hue scale (matches MOFA2 tutorial)
          p <- p + scale_fill_hue(name = color_label, na.value = "grey80") +
            scale_color_hue(name = color_label, na.value = "grey80")
        }

        if (!is.null(group_by) && nzchar(group_by)) {
          p <- p + theme(axis.text.x = element_text(color = "black", angle = 40, vjust = 1, hjust = 1))
        }

        # Add vertical separators between groups when requested
        if (isTRUE(input$factor_values_show_separators)) {
          sep_levels <- if ("GroupValue" %in% colnames(plot_data)) nlevels(plot_data$GroupValue) else nlevels(plot_data$ColorValue)
          if (!is.null(sep_levels) && sep_levels > 1) {
            sep_pos <- seq_len(sep_levels - 1) + 0.5
            p <- p + geom_vline(xintercept = sep_pos, color = "grey80", linetype = "solid", size = 0.4)
          }
        }
        
        # Add horizontal line at y=0 (MOFA tutorial style)
        p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
        
      } else if (color_by == "covariate" && !is_categorical_covariate) {
        # Continuous covariate: scatter plot with color gradient
        # If group_by is provided, use it for the x-axis grouping (MOFA style)
        if ("GroupValue" %in% colnames(plot_data)) {
          plot_data$GroupValue <- as.character(plot_data$GroupValue)
          plot_data$GroupValue[is.na(plot_data$GroupValue) | plot_data$GroupValue == ""] <- "(Missing)"
          plot_data$GroupValue <- factor(plot_data$GroupValue)

          # Split NA vs non-NA to avoid dropping points
          na_points <- plot_data[is.na(plot_data$ColorValue), , drop = FALSE]
          non_na_points <- plot_data[!is.na(plot_data$ColorValue), , drop = FALSE]

          if (has_shape) {
            p <- ggplot(non_na_points, aes(x = GroupValue, y = FactorValue, color = ColorValue, shape = ShapeValue)) +
              geom_jitter(width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
          } else {
            p <- ggplot(non_na_points, aes(x = GroupValue, y = FactorValue, color = ColorValue)) +
              geom_jitter(width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
          }

          if (nrow(na_points) > 0) {
            p <- p + geom_jitter(data = na_points, aes(x = GroupValue, y = FactorValue),
                                 width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5, color = "grey80")
          }
        } else {
          sample_levels <- unique(result$factors$Sample)
          sample_index_map <- setNames(seq_along(sample_levels), sample_levels)
          plot_data$SampleIndex <- sample_index_map[as.character(plot_data$Sample)]

          na_points <- plot_data[is.na(plot_data$ColorValue), , drop = FALSE]
          non_na_points <- plot_data[!is.na(plot_data$ColorValue), , drop = FALSE]

          if (has_shape) {
            p <- ggplot(non_na_points, aes(x = SampleIndex, y = FactorValue, color = ColorValue, shape = ShapeValue)) +
              geom_point(size = 3, alpha = alpha_val)
          } else {
            p <- ggplot(non_na_points, aes(x = SampleIndex, y = FactorValue, color = ColorValue)) +
              geom_point(size = 3, alpha = alpha_val)
          }

          if (nrow(na_points) > 0) {
            p <- p + geom_point(data = na_points, aes(x = SampleIndex, y = FactorValue),
                                 size = 3, alpha = alpha_val, color = "grey80")
          }
        }
        p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label, na.value = "grey80")
        if (!is.null(group_by) && nzchar(group_by) && "GroupValue" %in% colnames(plot_data)) {
          p <- p + theme(axis.text.x = element_text(color = "black", angle = 40, vjust = 1, hjust = 1))
        }

        # Add vertical separators between groups when requested
        if (isTRUE(input$factor_values_show_separators) && "GroupValue" %in% colnames(plot_data)) {
          sep_levels <- nlevels(plot_data$GroupValue)
          if (!is.null(sep_levels) && sep_levels > 1) {
            sep_pos <- seq_len(sep_levels - 1) + 0.5
            p <- p + geom_vline(xintercept = sep_pos, color = "grey80", linetype = "solid", size = 0.4)
          }
        }
        p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
        
      } else if (color_by == "value") {
        # Color by factor value itself - keep original order (do not sort)
        plot_data$SampleIndex <- seq_len(nrow(plot_data))
        
        p <- ggplot(plot_data, aes(x = SampleIndex, y = FactorValue, color = FactorValue)) +
          geom_point(size = 3, alpha = alpha_val) +
          scale_color_gradient2(
            low = "#3b82f6", mid = "#fbbf24", high = "#ef4444",
            midpoint = 0, name = "Factor Value"
          ) +
          geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
        
      } else {
        # Default: scatter plot with sample index, colored by ColorValue
        sample_levels <- unique(result$factors$Sample)
        sample_index_map <- setNames(seq_along(sample_levels), sample_levels)
        plot_data$SampleIndex <- sample_index_map[as.character(plot_data$Sample)]
        
        p <- ggplot(plot_data, aes(x = SampleIndex, y = FactorValue, color = ColorValue)) +
          geom_point(size = 3, alpha = alpha_val)
        
        if (is.numeric(plot_data$ColorValue)) {
          p <- p + scale_color_gradient2(
            low = "#3b82f6", mid = "#fbbf24", high = "#ef4444",
            midpoint = median(plot_data$ColorValue, na.rm = TRUE),
            name = color_label
          )
        } else {
          p <- p + scale_color_brewer(palette = "Set2", name = color_label)
        }
        p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
      }
      
      # Faceting: when multiple factors are selected, arrange side-by-side in a grid
      # - Use a shared y-axis (fixed scales)
      # - Show each factor as a facet with its own strip title
      # - Keep a shared legend
      # - Draw borders around panels so all four borders show
      if (length(chosen_factors) > 1) {
        # Compute number of columns for the facet grid: prefer up to 3 columns for readability
        n_cols <- min(3, length(chosen_factors))

        # Shared y limits across facets
        y_limits <- range(plot_data$FactorValue, na.rm = TRUE)

        p <- p +
          facet_wrap(~ Factor, ncol = n_cols, scales = "fixed", strip.position = "top", labeller = labeller(Factor = label_value)) +
          coord_cartesian(ylim = y_limits)

        # Ensure strip title is visible per panel and add borders; draw borders on top of geoms
        p <- p + theme(
          strip.background = element_rect(fill = "#f0f0f0", color = "black", linewidth = 0.5),
          strip.text = element_text(face = "bold", size = rel(0.9)),
          panel.border = element_rect(color = "black", fill = NA, linewidth = 0.5),
          panel.spacing = unit(0.6, "lines"),
          panel.background = element_rect(fill = "white"),
          panel.ontop = TRUE,
          plot.background = element_rect(fill = NA, color = "black")
        )
      }

      # Add labels and theme
      custom_title <- if (!is.null(input$factor_values_plot_customization) && 
                          input$factor_values_plot_customization && 
                          !is.null(input$factor_values_plot_title) && 
                          nzchar(input$factor_values_plot_title)) {
        input$factor_values_plot_title
      } else {
        # If multiple factors are plotted, rely on facet strip titles and use a generic main title
        if (length(chosen_factors) == 1) paste0("Factor Values - ", chosen_factors) else "Factor Values"
      }
      
      custom_y_title <- if (!is.null(input$factor_values_plot_customization) && 
                            input$factor_values_plot_customization && 
                            !is.null(input$factor_values_axis_title) && 
                            nzchar(input$factor_values_axis_title)) {
        input$factor_values_axis_title
      } else {
        if (length(chosen_factors) == 1) chosen_factors[1] else "Factor value"
      }
      
      title_size <- if (!is.null(input$factor_values_plot_customization) && 
                        input$factor_values_plot_customization && 
                        !is.null(input$factor_values_title_size)) {
        input$factor_values_title_size
      } else {
        14
      }
      
      axis_text_size <- if (!is.null(input$factor_values_plot_customization) && 
                            input$factor_values_plot_customization && 
                            !is.null(input$factor_values_axis_text_size)) {
        input$factor_values_axis_text_size
      } else {
        10
      }
      
      p <- p +
        labs(
          title = custom_title,
          subtitle = paste0("Color: ", color_label, ifelse(add_violin, " (with distribution)", "")),
          y = custom_y_title
        ) +
        theme_classic() +
        theme(
          plot.title = element_text(size = title_size, face = "bold", hjust = 0.5),
          plot.subtitle = element_text(size = 11, hjust = 0.5),
          legend.position = "right",
          axis.text = element_text(size = axis_text_size, color = "black"),
          axis.title = element_text(size = axis_text_size),
          panel.border = element_rect(color = "black", linewidth = 0.1, fill = NA),
          axis.line = element_line(color = "black", linewidth = 0.25),
          axis.ticks = element_line(color = "black")
        )
      
      # Handle x-axis labels based on plot type (MOFA tutorial style)
      if (color_by == "covariate" && is_categorical_covariate) {
        # Categorical covariate: show category labels on x-axis (group_by if provided)
        x_label <- if (!is.null(group_by) && nzchar(group_by)) group_by else color_label
        p <- p + labs(x = x_label)
      } else if (color_by == "covariate" && !is_categorical_covariate) {
        # Continuous covariate: show group_by on x-axis if provided; otherwise hide sample index
        if (!is.null(group_by) && nzchar(group_by)) {
          p <- p + labs(x = group_by)
        } else {
          p <- p + theme(
            axis.title.x = element_blank(),
            axis.text.x = element_blank(),
            axis.ticks.x = element_blank()
          )
        }
      } else if (color_by == "value") {
        # Factor value: hide sample index
        p <- p + theme(
          axis.title.x = element_blank(),
          axis.text.x = element_blank(),
          axis.ticks.x = element_blank()
        )
      } else {
        # Default: hide x-axis for scatter plots
        p <- p + theme(
          axis.title.x = element_blank(),
          axis.text.x = element_blank(),
          axis.ticks.x = element_blank()
        )
      }

      # Add horizontal reference line at y=0 if enabled (in addition to default)
      if (isTRUE(input$factor_values_show_zero)) {
        # Already added in the plotting logic above, but keep for backwards compatibility
      }

      p <- apply_mofa_text_fix(p)
      p
      
    }, error = function(e) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = paste("Error:", e$message),
                 size = 4, color = "#ef4444") +
        theme_void()
    })
  }, height = reactive({
    # Use custom height if customization is enabled, otherwise use default
    if (!is.null(input$factor_values_plot_customization) && 
        input$factor_values_plot_customization && 
        !is.null(input$factor_values_plot_height)) {
      # Convert inches to pixels (96 DPI is Shiny default)
      input$factor_values_plot_height * 96
    } else {
      5.5 * 96  # Default 5.5 inches
    }
  }), width = reactive({
    # Use custom width if customization is enabled, otherwise use default
    if (!is.null(input$factor_values_plot_customization) && 
        input$factor_values_plot_customization && 
        !is.null(input$factor_values_plot_width)) {
      # Convert inches to pixels (96 DPI is Shiny default)
      input$factor_values_plot_width * 96
    } else {
      8 * 96  # Default 8 inches
    }
  }), res = UI_PLOT_RES)
  

  
  # Dimension Naming - Factor Name Inputs
  output$mofa_factor_rename_inputs <- renderUI({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method != "mofa" || is.null(result$factors)) {
      return(p("No factors available"))
    }
    
    factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
    
    lapply(factor_cols, function(factor_col) {
      textInput(paste0("factor_name_", factor_col),
                label = factor_col,
                value = multiomics$factor_names[[factor_col]] %||% factor_col,
                width = "100%")
    })
  })
  
  # Molecular Signatures - Data Scatter and Heatmap Plot
  output$mol_sig_plot <- renderPlot({ 
    req(multiomics$integration_results, input$mol_sig_view, input$mol_sig_factor, input$mol_sig_plot_type)
    result <- multiomics$integration_results
    
    if (result$method != "mofa" || is.null(result$weights)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "Molecular signature analysis available for MOFA",
                                 size = 5, color = "#667eea") + theme_void())
    }
    
    views_all <- names(result$weights)
    if (is.null(views_all) || length(views_all) == 0) {
      views_all <- tryCatch(MOFA2::views_names(result$mofa_model), error = function(e) NULL)
    }
    
    # Ensure covariates are present in the model metadata so plot_data_scatter() can color by them
    if (!is.null(mofa_metadata$covariates) && is.data.frame(mofa_metadata$covariates) && nrow(mofa_metadata$covariates) > 0) {
      md <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
      if (is.null(md) || nrow(md) == 0) {
        md <- data.frame(sample = result$factors$Sample, stringsAsFactors = FALSE)
      }
      if (!"sample" %in% colnames(md)) {
        md$sample <- if (!is.null(rownames(md)) && all(nzchar(rownames(md)))) rownames(md) else result$factors$Sample
      }

      cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
      if (!"sample" %in% colnames(cov_df)) {
        cov_df$sample <- rownames(cov_df)
      }
      cov_df <- cov_df[!is.na(cov_df$sample) & nzchar(cov_df$sample), , drop = FALSE]
      if (any(duplicated(cov_df$sample))) cov_df <- cov_df[!duplicated(cov_df$sample), , drop = FALSE]

      match_idx <- match(md$sample, cov_df$sample)
      cols_to_add <- setdiff(colnames(cov_df), "sample")
      for (col_name in cols_to_add) {
        md[[col_name]] <- cov_df[[col_name]][match_idx]
      }

      tryCatch({
        MOFA2::samples_metadata(result$mofa_model) <- md
      }, error = function(e) NULL)
    }
    
    tryCatch({
      view_name <- input$mol_sig_view
      factor_name <- input$mol_sig_factor
      plot_type <- input$mol_sig_plot_type
      n_features <- input$mol_sig_n_features
      
      weights_df <- result$weights[[view_name]]
      
      # Determine which features to select
      if (plot_type == "scatter_pos") {
        top_features <- weights_df %>%
          filter(.data[[factor_name]] > 0) %>%
          arrange(desc(.data[[factor_name]])) %>%
          head(n_features) %>%
          pull(Feature)
        subtitle_text <- "Top features by positive weight"
      } else if (plot_type == "scatter_neg") {
        top_features <- weights_df %>%
          filter(.data[[factor_name]] < 0) %>%
          arrange(.data[[factor_name]]) %>%
          head(n_features) %>%
          pull(Feature)
        subtitle_text <- "Top features by negative weight"
      } else {
        pos_features <- weights_df %>%
          filter(.data[[factor_name]] > 0) %>%
          arrange(desc(.data[[factor_name]])) %>%
          head(ceiling(n_features/2)) %>%
          pull(Feature)
        neg_features <- weights_df %>%
          filter(.data[[factor_name]] < 0) %>%
          arrange(.data[[factor_name]]) %>%
          head(floor(n_features/2)) %>%
          pull(Feature)
        top_features <- c(pos_features, neg_features)
        subtitle_text <- "Top features (positive + negative weights)"
      }
      
      if (length(top_features) == 0) {
        return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                   label = "No features found",
                                   size = 4, color = "#f59e0b") + theme_void())
      }
      
      if (grepl("scatter", plot_type)) {
        if (is.null(result$mofa_model)) {
          return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                     label = "MOFA model not available for tutorial scatter plot",
                                     size = 4, color = "#f59e0b") + theme_void())
        }

        factor_idx <- suppressWarnings(as.numeric(sub("Factor", "", factor_name)))
        if (is.na(factor_idx) || factor_idx < 1) factor_idx <- 1

        sign_arg <- if (plot_type == "scatter_pos") {
          "positive"
        } else if (plot_type == "scatter_neg") {
          "negative"
        } else {
          "all"
        }

        color_by_choice <- input$mol_sig_color_by
        color_by_arg <- if (is.null(color_by_choice) || identical(color_by_choice, "factor_value")) {
          "group"
        } else {
          color_by_choice
        }

        y_lab <- if (grepl("rna", view_name, ignore.case = TRUE)) "RNA expression" else paste0(view_name, " value")

        p <- tryCatch({
          MOFA2::plot_data_scatter(
            result$mofa_model,
            view = view_name,
            factor = factor_idx,
            features = n_features,
            sign = sign_arg,
            color_by = color_by_arg
          ) + labs(y = y_lab)
        }, error = function(e) {
          # Fallback: if selected color_by is not available, retry with default group
          MOFA2::plot_data_scatter(
            result$mofa_model,
            view = view_name,
            factor = factor_idx,
            features = n_features,
            sign = sign_arg,
            color_by = "group"
          ) + labs(y = y_lab)
        }, res = UI_PLOT_RES)
        p <- strip_ggrepel_text_labels(p, views_all)
        if (!is.null(color_by_choice) && color_by_choice != "factor_value") {
          p <- p + labs(color = gsub("\\.", " ", color_by_choice))
        }
      } else {
        if (is.null(result$mofa_model)) {
          return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                     label = "MOFA model not available for tutorial heatmap",
                                     size = 4, color = "#f59e0b") + theme_void())
        }

        factor_idx <- suppressWarnings(as.numeric(sub("Factor", "", factor_name)))
        if (is.na(factor_idx) || factor_idx < 1) factor_idx <- 1

        denoise_flag <- identical(plot_type, "heatmap_denoised")

        annotation_samples <- if (!is.null(input$mol_sig_annotation_samples)) input$mol_sig_annotation_samples else ""
        if (!nzchar(annotation_samples)) annotation_samples <- NULL

        # If the selected annotation is not present in the MOFA model metadata, try to add it from mofa_metadata
        if (!is.null(annotation_samples)) {
          mm <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
          if (is.null(mm) || !annotation_samples %in% colnames(mm)) {
            # Try to source it from mofa_metadata$covariates
            if (!is.null(mofa_metadata$covariates) && annotation_samples %in% colnames(mofa_metadata$covariates)) {
              cov_df <- as.data.frame(mofa_metadata$covariates[, annotation_samples, drop = FALSE], stringsAsFactors = FALSE)
              cov_df$sample <- mofa_metadata$data$SampleID
              # Align to MOFA sample order if possible
              sample_names <- tryCatch({ result$factors$Sample }, error = function(e) NULL)
              if (!is.null(sample_names)) {
                cov_df <- cov_df[match(sample_names, cov_df$sample), , drop = FALSE]
                cov_df$sample <- sample_names
              }
              # Merge into the model
              result$mofa_model <- safe_merge_samples_metadata(result$mofa_model, cov_df)
              # Persist updated model back to shared results
              multiomics$integration_results <- result
            } else {
              showNotification(paste0("Annotation column '", annotation_samples, "' not found in MOFA metadata and could not be auto-added."), type = "error", duration = 6)
              annotation_samples <- NULL
            }
          }
        }

        p <- MOFA2::plot_data_heatmap(
          result$mofa_model,
          view = view_name,
          factor = factor_idx,
          features = n_features,
          denoise = denoise_flag,
          cluster_rows = isTRUE(input$mol_sig_cluster_rows),
          cluster_cols = isTRUE(input$mol_sig_cluster_cols),
          show_rownames = isTRUE(input$mol_sig_show_rownames),
          show_colnames = isTRUE(input$mol_sig_show_colnames),
          annotation_samples = annotation_samples,
          scale = input$mol_sig_scale
        )
      }
      
      p
    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5, label = paste("Error:", e$message), size = 4, color = "#ef4444") +
        theme_void()
    })
  })
  
  # Download handler for molecular signatures
  output$download_mol_sig <- downloadHandler(
    filename = function() {
      paste0("molecular_signatures_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      png(file, width = round(1200 * scale), height = round(700 * scale), res = dpi)
      on.exit(try(dev.off(), silent = TRUE), add = TRUE)
      plot_obj <- tryCatch({
        result <- multiomics$integration_results
        
        views_all <- names(result$weights)
        if (is.null(views_all) || length(views_all) == 0) {
          views_all <- tryCatch(MOFA2::views_names(result$mofa_model), error = function(e) NULL)
        }
        
        # Ensure covariates are present in the model metadata
        if (!is.null(mofa_metadata$covariates) && is.data.frame(mofa_metadata$covariates) && nrow(mofa_metadata$covariates) > 0) {
          md <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
          if (is.null(md) || nrow(md) == 0) {
            md <- data.frame(sample = result$factors$Sample, stringsAsFactors = FALSE)
          }
          if (!"sample" %in% colnames(md)) {
            md$sample <- if (!is.null(rownames(md)) && all(nzchar(rownames(md)))) rownames(md) else result$factors$Sample
          }

          cov_df <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
          if (!"sample" %in% colnames(cov_df)) {
            cov_df$sample <- rownames(cov_df)
          }
          cov_df <- cov_df[!is.na(cov_df$sample) & nzchar(cov_df$sample), , drop = FALSE]
          if (any(duplicated(cov_df$sample))) cov_df <- cov_df[!duplicated(cov_df$sample), , drop = FALSE]

          match_idx <- match(md$sample, cov_df$sample)
          cols_to_add <- setdiff(colnames(cov_df), "sample")
          for (col_name in cols_to_add) {
            md[[col_name]] <- cov_df[[col_name]][match_idx]
          }

          tryCatch({
            MOFA2::samples_metadata(result$mofa_model) <- md
          }, error = function(e) NULL)
        }
        
        view_name <- input$mol_sig_view
        factor_name <- input$mol_sig_factor
        plot_type <- input$mol_sig_plot_type
        n_features <- input$mol_sig_n_features
        weights_df <- result$weights[[view_name]]
        
        if (plot_type == "scatter_pos") {
          top_features <- weights_df %>%
            filter(.data[[factor_name]] > 0) %>%
            arrange(desc(.data[[factor_name]])) %>%
            head(n_features) %>%
            pull(Feature)
        } else if (plot_type == "scatter_neg") {
          top_features <- weights_df %>%
            filter(.data[[factor_name]] < 0) %>%
            arrange(.data[[factor_name]]) %>%
            head(n_features) %>%
            pull(Feature)
        } else {
          pos_features <- weights_df %>%
            filter(.data[[factor_name]] > 0) %>%
            arrange(desc(.data[[factor_name]])) %>%
            head(ceiling(n_features/2)) %>%
            pull(Feature)
          neg_features <- weights_df %>%
            filter(.data[[factor_name]] < 0) %>%
            arrange(.data[[factor_name]]) %>%
            head(floor(n_features/2)) %>%
            pull(Feature)
          top_features <- c(pos_features, neg_features)
        }
        
        if (grepl("scatter", plot_type)) {
          if (is.null(result$mofa_model)) {
            ggplot() + annotate("text", x = 0.5, y = 0.5,
                                label = "MOFA model not available",
                                size = 5, color = "#f59e0b") + theme_void()
          } else {
            factor_idx <- suppressWarnings(as.numeric(sub("Factor", "", factor_name)))
            if (is.na(factor_idx) || factor_idx < 1) factor_idx <- 1

            sign_arg <- if (plot_type == "scatter_pos") {
              "positive"
            } else if (plot_type == "scatter_neg") {
              "negative"
            } else {
              "all"
            }

            color_by_choice <- input$mol_sig_color_by
            color_by_arg <- if (is.null(color_by_choice) || identical(color_by_choice, "factor_value")) {
              "group"
            } else {
              color_by_choice
            }

            y_lab <- if (grepl("rna", view_name, ignore.case = TRUE)) "RNA expression" else paste0(view_name, " value")

            p <- tryCatch({
              MOFA2::plot_data_scatter(
                result$mofa_model,
                view = view_name,
                factor = factor_idx,
                features = n_features,
                sign = sign_arg,
                color_by = color_by_arg
              ) + labs(y = y_lab)
            }, error = function(e) {
              MOFA2::plot_data_scatter(
                result$mofa_model,
                view = view_name,
                factor = factor_idx,
                features = n_features,
                sign = sign_arg,
                color_by = "group"
              ) + labs(y = y_lab)
            })
            p <- strip_ggrepel_text_labels(p, views_all)
            if (!is.null(color_by_choice) && color_by_choice != "factor_value") {
              p <- p + labs(color = gsub("\\.", " ", color_by_choice))
            }
            p
          }
        } else {
          if (is.null(result$mofa_model)) {
            ggplot() + annotate("text", x = 0.5, y = 0.5,
                                label = "MOFA model not available",
                                size = 5, color = "#f59e0b") + theme_void()
          } else {
            factor_idx <- suppressWarnings(as.numeric(sub("Factor", "", factor_name)))
            if (is.na(factor_idx) || factor_idx < 1) factor_idx <- 1
            denoise_flag <- identical(plot_type, "heatmap_denoised")

            annotation_samples <- if (!is.null(input$mol_sig_annotation_samples)) input$mol_sig_annotation_samples else ""
            if (!nzchar(annotation_samples)) annotation_samples <- NULL

            # If the selected annotation is not present in the MOFA model metadata, try to add it from mofa_metadata
            if (!is.null(annotation_samples)) {
              mm <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
              if (is.null(mm) || !annotation_samples %in% colnames(mm)) {
                # Try to source it from mofa_metadata$covariates
                if (!is.null(mofa_metadata$covariates) && annotation_samples %in% colnames(mofa_metadata$covariates)) {
                  cov_df <- as.data.frame(mofa_metadata$covariates[, annotation_samples, drop = FALSE], stringsAsFactors = FALSE)
                  cov_df$sample <- mofa_metadata$data$SampleID
                  # Align to MOFA sample order if possible
                  sample_names <- tryCatch({ result$factors$Sample }, error = function(e) NULL)
                  if (!is.null(sample_names)) {
                    cov_df <- cov_df[match(sample_names, cov_df$sample), , drop = FALSE]
                    cov_df$sample <- sample_names
                  }
                  # Merge into the model
                  result$mofa_model <- safe_merge_samples_metadata(result$mofa_model, cov_df)
                  # Persist updated model back to shared results
                  multiomics$integration_results <- result
                } else {
                  showNotification(paste0("Annotation column '", annotation_samples, "' not found in MOFA metadata and could not be auto-added."), type = "error", duration = 6)
                  annotation_samples <- NULL
                }
              }
            }

            p <- MOFA2::plot_data_heatmap(
              result$mofa_model,
              view = view_name,
              factor = factor_idx,
              features = n_features,
              denoise = denoise_flag,
              cluster_rows = isTRUE(input$mol_sig_cluster_rows),
              cluster_cols = isTRUE(input$mol_sig_cluster_cols),
              show_rownames = isTRUE(input$mol_sig_show_rownames),
              show_colnames = isTRUE(input$mol_sig_show_colnames),
              annotation_samples = annotation_samples,
              scale = input$mol_sig_scale
            )
            # Safely modify S4 slots for row name labels
            tryCatch({
              if (inherits(p, "Heatmap") && !is.null(p@row_names_param) && !is.null(p@row_names_param$labels)) {
                p@row_names_param$labels <- strip_mofa_view_suffix(p@row_names_param$labels, views_all)
              }
            }, error = function(e) NULL)
            # Safely modify annotation names
            tryCatch({
              if (!is.null(annotation_samples) && inherits(p, "Heatmap")) {
                if (!is.null(p@top_annotation) && length(p@top_annotation@anno_list) > 0) {
                  for (i in seq_along(p@top_annotation@anno_list)) {
                    anno <- p@top_annotation@anno_list[[i]]
                    if (!is.null(anno@name) && anno@name == annotation_samples) {
                      anno@name <- gsub("\\.", " ", annotation_samples)
                      p@top_annotation@anno_list[[i]] <- anno
                    }
                  }
                }
              }
            }, error = function(e) NULL)
            p
          }
        }
      }, error = function(e) {
        # Return an error ggplot with helpful message
        ggplot() + annotate("text", x = 0.5, y = 0.5, 
                            label = paste("Download Error:", e$message), 
                            size = 4, color = "#ef4444") + theme_void()
      })
      # Draw the plot to the device
      if (inherits(plot_obj, "Heatmap") && requireNamespace("ComplexHeatmap", quietly = TRUE)) {
        grid::grid.newpage()
        ComplexHeatmap::draw(plot_obj)
      } else {
        print(plot_obj)
      }
    }
  )
  
  # Dimension Naming - View Name Inputs
  output$mofa_view_rename_inputs <- renderUI({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (is.null(result$views)) {
      return(p("No views available"))
    }
    
    lapply(result$views, function(view) {
      textInput(paste0("view_name_", view),
                label = view,
                value = multiomics$view_names[[view]] %||% view,
                width = "100%")
    })
  })
  
  # Factor Pair Plot Container (dynamic sizing)
  output$factor_pair_plot_container <- renderUI({
    height_px <- if (!is.null(input$factor_pair_plot_height)) {
      paste0(input$factor_pair_plot_height, "px")
    } else {
      "600px"
    }
    
    width_pct <- if (!is.null(input$factor_pair_plot_width)) {
      paste0(input$factor_pair_plot_width, "%")
    } else {
      "100%"
    }
    
    plotOutput("mofa_factor_pair_plot", height = height_px, width = width_pct)
  })
  
  # Top Weights Plot (Lollipop)
  # Factor Pair Plot (2D scatter)
  output$mofa_factor_pair_plot <- renderPlot({ 
    req(multiomics$integration_results, input$factor_pair_factors)
    result <- multiomics$integration_results

    if (result$method != "mofa" || is.null(result$factors)) {
      return(ggplot() + annotate("text", x = 0.5, y = 0.5,
                                 label = "Factor pair plots available for MOFA",
                                 size = 5, color = "#667eea") + theme_void())
    }

    tryCatch({
      factors_sel <- input$factor_pair_factors %||% character(0)
      if (length(factors_sel) == 0) stop("No factors selected")
      pairwise <- isTRUE(input$factor_pair_combinations)
      color_by <- input$factor_pair_color
      shape_by <- input$factor_pair_shape
      size_val <- input$factor_pair_size %||% 2.5

      # Prepare a mapping for color and shape across samples
      samples <- as.character(result$factors$Sample)
      color_map <- rep(NA, length(samples))
      names(color_map) <- samples
      color_label <- ""
      color_is_discrete <- FALSE

      if (color_by == "group" && !is.null(multiomics$sample_groups)) {
        color_map[names(multiomics$sample_groups)] <- multiomics$sample_groups
        color_label <- "Group"
        color_is_discrete <- TRUE
      } else if (!is.null(mofa_metadata$covariates) && color_by %in% colnames(mofa_metadata$covariates)) {
        cov_df <- mofa_metadata$covariates
        if (!"sample" %in% colnames(cov_df)) rownames(cov_df) <- rownames(cov_df) # no-op but clarify
        cov_vals <- cov_df[[color_by]]
        names(cov_vals) <- rownames(cov_df)
        color_map[names(cov_vals)] <- cov_vals
        color_label <- color_by
        color_is_discrete <- !is.numeric(suppressWarnings(as.numeric(as.character(color_map[!is.na(color_map)]))))
      } else if (color_by %in% colnames(result$factors)) {
        vals <- result$factors[[color_by]]
        color_map[as.character(result$factors$Sample)] <- vals
        color_label <- color_by
        color_is_discrete <- FALSE
      }

      shape_map <- rep(NA, length(samples))
      names(shape_map) <- samples
      if (!is.null(shape_by) && nzchar(shape_by) && shape_by %in% colnames(mofa_metadata$covariates)) {
        shp_vals <- mofa_metadata$covariates[[shape_by]]
        names(shp_vals) <- rownames(mofa_metadata$covariates)
        shape_map[names(shp_vals)] <- shp_vals
      }

      # Helper to create a single pair plot between fx and fy
      make_pair_plot <- function(fx, fy) {
        df <- result$factors %>% dplyr::select(Sample, all_of(c(fx, fy))) %>%
          dplyr::rename(FX = all_of(fx), FY = all_of(fy))
        df$ColorVar <- color_map[as.character(df$Sample)]
        df$ShapeVar <- shape_map[as.character(df$Sample)]

        # Optionally hide missing
        if (!isTRUE(input$factor_pair_show_missing)) {
          keep <- is.finite(df$FX) & is.finite(df$FY)
          if (!all(is.na(df$ColorVar))) keep <- keep & !is.na(df$ColorVar)
          if (!all(is.na(df$ShapeVar))) keep <- keep & !is.na(df$ShapeVar)
          df <- df[keep, , drop = FALSE]
        }

        # Detect continuous color
        col_num_try <- suppressWarnings(as.numeric(as.character(df$ColorVar)))
        is_cont <- sum(!is.na(col_num_try)) / max(1, nrow(df)) >= 0.5 && length(unique(col_num_try[!is.na(col_num_try)])) >= 6

        aes_map <- aes(x = FX, y = FY)
        if (is_cont) aes_map <- aes(x = FX, y = FY, color = col_num_try)
        else if (!all(is.na(df$ColorVar))) aes_map <- aes(x = FX, y = FY, color = as.factor(ColorVar))
        if (!all(is.na(df$ShapeVar))) aes_map <- modifyList(as.list(aes_map), list(shape = as.factor(df$ShapeVar)))

        p <- ggplot(df, aes(x = FX, y = FY)) + geom_point(size = size_val, alpha = 0.8, color = "#667eea")

        # Apply color/shape mapping
        if (!all(is.na(df$ShapeVar)) && (is_cont || !all(is.na(df$ColorVar)))) {
          if (is_cont) {
            p <- ggplot(df, aes(x = FX, y = FY, color = col_num_try, shape = as.factor(ShapeVar))) + geom_point(size = size_val, alpha = 0.8)
            p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label)
            p <- p + scale_shape_discrete(name = shape_by)
          } else {
            p <- ggplot(df, aes(x = FX, y = FY, color = as.factor(ColorVar), shape = as.factor(ShapeVar))) + geom_point(size = size_val, alpha = 0.8)
            p <- p + scale_color_brewer(palette = "Set2", name = color_label)
            p <- p + scale_shape_discrete(name = shape_by)
          }
        } else if (!all(is.na(df$ColorVar))) {
          if (is_cont) {
            p <- ggplot(df, aes(x = FX, y = FY, color = col_num_try)) + geom_point(size = size_val, alpha = 0.8)
            p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label)
          } else {
            p <- ggplot(df, aes(x = FX, y = FY, color = as.factor(ColorVar))) + geom_point(size = size_val, alpha = 0.8)
            p <- p + scale_color_brewer(palette = "Set2", name = color_label)
          }
        }

        if (isTRUE(input$factor_pair_add_lines)) {
          p <- p + geom_hline(yintercept = median(df$FY, na.rm = TRUE), linetype = "dashed", color = "gray50") +
            geom_vline(xintercept = median(df$FX, na.rm = TRUE), linetype = "dashed", color = "gray50")
        }

        # Axis labels including variance explained when available
        xlab <- fx
        ylab <- fy
        if (!is.null(result$variance_explained)) {
          if (fx %in% names(result$variance_explained)) xlab <- paste0(fx, " (", round(result$variance_explained[fx] * 100, 1), "%)")
          if (fy %in% names(result$variance_explained)) ylab <- paste0(fy, " (", round(result$variance_explained[fy] * 100, 1), "%)")
        }
        p <- p + labs(title = paste0(fx, " vs ", fy), x = xlab, y = ylab) + ggprism::theme_prism()
        p <- apply_mofa_text_fix(p)
        p
      }

      # Single pair: two factors and no pairwise grid requested
      if (!pairwise || (length(factors_sel) == 2 && !pairwise)) {
        if (length(factors_sel) < 2) stop("Select two factors to plot against each other")
        fx <- factors_sel[1]
        fy <- factors_sel[2]
        # honor explicit X/Y selections when visible (pairwise == FALSE)
        if (!is.null(input$factor_pair_x_selected) && nzchar(input$factor_pair_x_selected)) fx <- input$factor_pair_x_selected
        if (!is.null(input$factor_pair_y_selected) && nzchar(input$factor_pair_y_selected)) fy <- input$factor_pair_y_selected
        p <- make_pair_plot(fx, fy)
        return(p)
      }

      # Pairwise grid for all combinations
      combos <- combn(factors_sel, 2, simplify = FALSE)
      plots <- lapply(combos, function(pr) make_pair_plot(pr[1], pr[2]))

      # Arrange plots in a grid, prefer patchwork, fallback to cowplot or gridExtra
      n <- length(plots)
      ncol <- if (n <= 3) n else ceiling(sqrt(n))
      if (requireNamespace("patchwork", quietly = TRUE)) {
        combined <- patchwork::wrap_plots(plots, ncol = ncol)
        combined <- apply_mofa_text_fix(combined)
        return(combined)
      } else if (requireNamespace("cowplot", quietly = TRUE)) {
        combined <- cowplot::plot_grid(plotlist = plots, ncol = ncol)
        return(combined)
      } else if (requireNamespace("gridExtra", quietly = TRUE)) {
        combined <- gridExtra::grid.arrange(grobs = plots, ncol = ncol)
        return(combined)
      } else {
        stop("Install 'patchwork', 'cowplot', or 'gridExtra' to view pairwise factor grids")
      }

    }, error = function(e) {
      ggplot() + annotate("text", x = 0.5, y = 0.5,
                          label = paste("Error:", e$message),
                          size = 4, color = "#ef4444") + theme_void()
    })
  })
  
  # Download Top Weights
  # Download Factor Pair
  output$download_factor_pair <- downloadHandler(
    filename = function() {
      paste0("factor_pair_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      height_px <- input$factor_pair_plot_height %||% 600
      width_pct <- input$factor_pair_plot_width %||% 100
      width_px <- round(1000 * (width_pct / 100) * scale)
      png(file, width = width_px, height = round(height_px * scale), res = dpi)
      print(tryCatch({
        result <- multiomics$integration_results
        factors_sel <- input$factor_pair_factors %||% character(0)
        pairwise <- isTRUE(input$factor_pair_combinations)
        color_by <- input$factor_pair_color
        shape_by <- input$factor_pair_shape
        size_val <- input$factor_pair_size %||% 2.5

        if (length(factors_sel) == 0) stop("No factors selected")

        # Prepare sample-level color and shape maps as in the UI plotting logic
        samples <- as.character(result$factors$Sample)
        color_map <- rep(NA, length(samples)); names(color_map) <- samples
        color_label <- ""
        if (color_by == "group" && !is.null(multiomics$sample_groups)) {
          color_map[names(multiomics$sample_groups)] <- multiomics$sample_groups
          color_label <- "Group"
        } else if (!is.null(mofa_metadata$covariates) && color_by %in% colnames(mofa_metadata$covariates)) {
          cov_vals <- mofa_metadata$covariates[[color_by]]; names(cov_vals) <- rownames(mofa_metadata$covariates)
          color_map[names(cov_vals)] <- cov_vals
          color_label <- color_by
        } else if (color_by %in% colnames(result$factors)) {
          vals <- result$factors[[color_by]]
          color_map[as.character(result$factors$Sample)] <- vals
          color_label <- color_by
        }

        shape_map <- rep(NA, length(samples)); names(shape_map) <- samples
        if (!is.null(shape_by) && nzchar(shape_by) && shape_by %in% colnames(mofa_metadata$covariates)) {
          shp_vals <- mofa_metadata$covariates[[shape_by]]; names(shp_vals) <- rownames(mofa_metadata$covariates)
          shape_map[names(shp_vals)] <- shp_vals
        }

        make_pair_plot_local <- function(fx, fy) {
          df <- result$factors %>% dplyr::select(Sample, all_of(c(fx, fy))) %>% dplyr::rename(FX = all_of(fx), FY = all_of(fy))
          df$ColorVar <- color_map[as.character(df$Sample)]
          df$ShapeVar <- shape_map[as.character(df$Sample)]

          if (!isTRUE(input$factor_pair_show_missing)) {
            keep <- is.finite(df$FX) & is.finite(df$FY)
            if (!all(is.na(df$ColorVar))) keep <- keep & !is.na(df$ColorVar)
            if (!all(is.na(df$ShapeVar))) keep <- keep & !is.na(df$ShapeVar)
            df <- df[keep, , drop = FALSE]
          }

          col_num_try <- suppressWarnings(as.numeric(as.character(df$ColorVar)))
          is_cont <- sum(!is.na(col_num_try)) / max(1, nrow(df)) >= 0.5 && length(unique(col_num_try[!is.na(col_num_try)])) >= 6

          p <- ggplot(df, aes(x = FX, y = FY)) + geom_point(size = size_val, alpha = 0.8, color = "#667eea")

          if (!all(is.na(df$ShapeVar)) && (is_cont || !all(is.na(df$ColorVar)))) {
            if (is_cont) {
              p <- ggplot(df, aes(x = FX, y = FY, color = col_num_try, shape = as.factor(ShapeVar))) + geom_point(size = size_val, alpha = 0.8)
              p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label)
              p <- p + scale_shape_discrete(name = shape_by)
            } else {
              p <- ggplot(df, aes(x = FX, y = FY, color = as.factor(ColorVar), shape = as.factor(ShapeVar))) + geom_point(size = size_val, alpha = 0.8)
              p <- p + scale_color_brewer(palette = "Set2", name = color_label)
              p <- p + scale_shape_discrete(name = shape_by)
            }
          } else if (!all(is.na(df$ColorVar))) {
            if (is_cont) {
              p <- ggplot(df, aes(x = FX, y = FY, color = col_num_try)) + geom_point(size = size_val, alpha = 0.8)
              p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label)
            } else {
              p <- ggplot(df, aes(x = FX, y = FY, color = as.factor(ColorVar))) + geom_point(size = size_val, alpha = 0.8)
              p <- p + scale_color_brewer(palette = "Set2", name = color_label)
            }
          }

          if (input$factor_pair_add_lines) {
            p <- p + geom_hline(yintercept = median(df$FY, na.rm = TRUE), linetype = "dashed", color = "gray50") +
              geom_vline(xintercept = median(df$FX, na.rm = TRUE), linetype = "dashed", color = "gray50")
          }

          xlab <- fx; ylab <- fy
          if (!is.null(result$variance_explained)) {
            if (fx %in% names(result$variance_explained)) xlab <- paste0(fx, " (", round(result$variance_explained[fx] * 100, 1), "% )")
            if (fy %in% names(result$variance_explained)) ylab <- paste0(fy, " (", round(result$variance_explained[fy] * 100, 1), "% )")
          }
          p <- p + labs(title = paste0(fx, " vs ", fy), x = xlab, y = ylab) + ggprism::theme_prism()
          p
        }

        if (!pairwise || (length(factors_sel) == 2 && !pairwise)) {
          if (length(factors_sel) < 2) stop("Select two factors to plot")
          fx <- factors_sel[1]
          fy <- factors_sel[2]
          if (!is.null(input$factor_pair_x_selected) && nzchar(input$factor_pair_x_selected)) fx <- input$factor_pair_x_selected
          if (!is.null(input$factor_pair_y_selected) && nzchar(input$factor_pair_y_selected)) fy <- input$factor_pair_y_selected
          p <- make_pair_plot_local(fx, fy)
          p <- apply_mofa_text_fix(p)
          print(p)
        } else {
          combos <- combn(factors_sel, 2, simplify = FALSE)
          plots <- lapply(combos, function(pr) make_pair_plot_local(pr[1], pr[2]))
          n <- length(plots); ncol <- if (n <= 3) n else ceiling(sqrt(n))
          if (requireNamespace("patchwork", quietly = TRUE)) {
            combined <- patchwork::wrap_plots(plots, ncol = ncol)
            combined <- apply_mofa_text_fix(combined)
            print(combined)
          } else if (requireNamespace("cowplot", quietly = TRUE)) {
            print(cowplot::plot_grid(plotlist = plots, ncol = ncol))
          } else if (requireNamespace("gridExtra", quietly = TRUE)) {
            gridExtra::grid.arrange(grobs = plots, ncol = ncol)
          } else {
            stop("Install 'patchwork', 'cowplot', or 'gridExtra' to enable pairwise factor grids")
          }
        }
      }, error = function(e) ggplot()))
      dev.off()
    }
  )
  
  # Apply dimension names
  observeEvent(input$apply_dimnames, {
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    # Collect factor names
    factor_cols <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
    factor_names_list <- setNames(
      lapply(factor_cols, function(fc) input[[paste0("factor_name_", fc)]]),
      factor_cols
    )
    multiomics$factor_names <- factor_names_list
    
    # Collect view names
    view_names_list <- setNames(
      lapply(result$views, function(v) input[[paste0("view_name_", v)]]),
      result$views
    )
    multiomics$view_names <- view_names_list
    
    # Update MOFA model with custom names if available
    if (result$method == "mofa" && !is.null(result$mofa_model)) {
      tryCatch({
        # Update factor names in the model
        if (!is.null(multiomics$factor_names) && length(multiomics$factor_names) > 0) {
          # Get current factor names from model
          current_factor_names <- MOFA2::get_factors(result$mofa_model, as.data.frame = TRUE) %>%
            dplyr::select(starts_with("Factor")) %>% colnames()
          
          # Create mapping from current to custom names
          custom_factor_names <- sapply(current_factor_names, function(fn) {
            multiomics$factor_names[[fn]] %||% fn
          })
          
          # Apply custom factor names to model
          result$mofa_model <- MOFA2::set_names(result$mofa_model,
                                                factor_names = custom_factor_names)
        }
        
        # Update view names in the model
        if (!is.null(multiomics$view_names) && length(multiomics$view_names) > 0) {
          custom_view_names <- sapply(result$views, function(vn) {
            multiomics$view_names[[vn]] %||% vn
          })
          
          # Apply custom view names to model
          result$mofa_model <- MOFA2::set_names(result$mofa_model,
                                                view_names = custom_view_names)
        }
        
        # Update the stored result with the modified model
        multiomics$integration_results$mofa_model <- result$mofa_model
        
      }, error = function(e) {
        warning("Could not update MOFA model names: ", e$message)
      })
    }
    
    showNotification("Dimension names updated! Visualizations will use custom names.",
                     type = "message", duration = 3)
  })
  
  # Download handlers for new visualizations
  output$download_feature_scatter <- downloadHandler(
    filename = function() {
      paste0("feature_scatter_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      png(file, width = round(1000 * scale), height = round(700 * scale), res = dpi)
      print(
        tryCatch({
          result <- multiomics$integration_results
          weights_list <- result$weights
          view_name <- input$feature_scatter_view
          factor_name <- input$feature_scatter_factor
          weights_df <- weights_list[[view_name]]
          top_features <- weights_df %>%
            arrange(desc(abs(.data[[factor_name]]))) %>%
            head(input$feature_scatter_n) %>%
            pull(Feature)
          plot_data <- data.frame(
            Factor = rep(result$factors[[factor_name]], length(top_features)),
            Feature = rep(top_features, each = nrow(result$factors)),
            Sample = rep(result$factors$Sample, length(top_features))
          )
          p <- ggplot(plot_data, aes(x = Factor, y = Feature)) +
            geom_point(size = 3, alpha = 0.6, color = "#667eea")
          if (input$feature_scatter_lm) {
            p <- p + geom_smooth(method = "lm", se = TRUE, color = "#ef4444", alpha = 0.2)
          }
          p + facet_wrap(~Feature, scales = "free_y", nrow = 2) +
            ggprism::theme_prism()
        }, error = function(e) ggplot())
      )
      dev.off()
    }
  )
  
  output$download_dimred <- downloadHandler(
    filename = function() {
      paste0("dimred_", input$dimred_method, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      png(file, width = round(1000 * scale), height = round(700 * scale), res = dpi)
      print(
        tryCatch({
          req(multiomics$integration_results, multiomics$mofa_dimred_ready)
          result <- multiomics$integration_results
          dimred_space <- input$dimred_space %||% "mofa"

          if (identical(dimred_space, "view")) {
            req(multiomics$view_dimred)
            df <- multiomics$view_dimred
            x_col <- if (input$dimred_method == "UMAP") "UMAP1" else "tSNE1"
            y_col <- if (input$dimred_method == "UMAP") "UMAP2" else "tSNE2"
            color_by <- input$dimred_color
            if (is.null(color_by) || identical(color_by, "Loading...")) color_by <- "group"

            color_vals <- NULL
            if (identical(color_by, "group")) {
              color_vals <- df$group
            } else if (color_by %in% colnames(df)) {
              color_vals <- df[[color_by]]
            }
            if (is.null(color_vals)) color_vals <- rep("", nrow(df))

            is_cont <- is.numeric(color_vals) || (suppressWarnings(!all(is.na(as.numeric(color_vals)))) && length(unique(color_vals)) > 5)
            if (!is_cont) {
              color_vals <- as.factor(color_vals)
            } else {
              color_vals <- suppressWarnings(as.numeric(color_vals))
            }
            df$ColorVar <- color_vals

            if (is_cont) {
              p <- ggplot(df, aes_string(x = x_col, y = y_col, color = "ColorVar")) +
                geom_point(size = input$dimred_dot_size, alpha = 0.9) +
                scale_color_viridis_c(option = "D", na.value = "grey70")
            } else {
              p <- ggplot(df, aes_string(x = x_col, y = y_col, fill = "ColorVar")) +
                geom_point(shape = 21, color = "black", stroke = input$dimred_stroke, size = input$dimred_dot_size, alpha = 0.9) +
                scale_fill_brewer(palette = "Set2", na.value = "grey70")
            }

            if (isTRUE(input$dimred_label) && requireNamespace("ggrepel", quietly = TRUE)) {
              p <- p + ggrepel::geom_text_repel(aes(label = Sample), size = 2, max.overlaps = 30)
            }

            p + ggprism::theme_prism() +
              theme(legend.position = if (isTRUE(input$dimred_legend)) "right" else "none")
          } else if (result$method != "mofa" || is.null(result$mofa_model)) {
            ggplot() + annotate("text", x = 0.5, y = 0.5,
                                label = "MOFA model not available",
                                size = 5, color = "#667eea") + theme_void()
          } else {
            method_arg <- if (input$dimred_method == "UMAP") "UMAP" else "TSNE"
            model_to_plot <- multiomics$mofa_model_dimred %||% result$mofa_model
            p <- MOFA2::plot_dimred(
              model_to_plot,
              method = method_arg,
              color_by = input$dimred_color,
              label = isTRUE(input$dimred_label),
              stroke = input$dimred_stroke,
              dot_size = input$dimred_dot_size,
              legend = isTRUE(input$dimred_legend)
            )
            p + ggprism::theme_prism()
          }
        }, error = function(e) ggplot())
      )
      dev.off()
    }
  )
  
  # ============================================================================
  # DATA EXPORT HANDLERS (Section 9.2 - Extract data for downstream analysis)
  # ============================================================================
  
  # Export Factors as CSV
  output$export_factors_csv <- downloadHandler(
    filename = function() {
      paste0("mofa_factors_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$factors)) {
        write.csv(result$factors, file, row.names = FALSE)
      }
    }
  )
  
  # Export Factors as RDS
  output$export_factors_rds <- downloadHandler(
    filename = function() {
      paste0("mofa_factors_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$factors)) {
        saveRDS(result$factors, file)
      }
    }
  )
  
  # Export Weights as CSV (using MOFA get_weights function)
  output$export_weights_csv <- downloadHandler(
    filename = function() {
      paste0("mofa_weights_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$mofa_model)) {
        # Use MOFA2::get_weights to extract weights directly from the model
        tryCatch({
          weights_data <- MOFA2::get_weights(result$mofa_model, factors = "all")
          if (!is.null(weights_data)) {
            # Combine weights from all views
            weights_combined <- do.call(rbind, weights_data)
            write.csv(weights_combined, file)
          }
        }, error = function(e) {
          # Fallback to stored weights if direct extraction fails
          if (!is.null(result$weights)) {
            weights_combined <- do.call(rbind, result$weights)
            write.csv(weights_combined, file)
          }
        })
      } else if (!is.null(result$weights)) {
        # Fallback for non-MOFA methods
        weights_combined <- do.call(rbind, result$weights)
        write.csv(weights_combined, file)
      }
    }
  )
  
  # Export Weights as RDS (using MOFA get_weights function)
  output$export_weights_rds <- downloadHandler(
    filename = function() {
      paste0("mofa_weights_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$mofa_model)) {
        # Use MOFA2::get_weights to extract weights directly from the model
        tryCatch({
          weights_data <- MOFA2::get_weights(result$mofa_model, factors = "all")
          if (!is.null(weights_data)) {
            saveRDS(weights_data, file)
          }
        }, error = function(e) {
          # Fallback to stored weights if direct extraction fails
          if (!is.null(result$weights)) {
            saveRDS(result$weights, file)
          }
        })
      } else if (!is.null(result$weights)) {
        # Fallback for non-MOFA methods
        saveRDS(result$weights, file)
      }
    }
  )
  
  # Export Variance Explained as CSV
  output$export_variance_csv <- downloadHandler(
    filename = function() {
      paste0("mofa_variance_explained_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$variance_explained)) {
        var_df <- as.data.frame(result$variance_explained)
        var_df$Factor <- rownames(var_df)
        var_df <- var_df[, c("Factor", setdiff(names(var_df), "Factor"))]
        write.csv(var_df, file, row.names = FALSE)
      }
    }
  )
  
  # Export Variance Explained as RDS
  output$export_variance_rds <- downloadHandler(
    filename = function() {
      paste0("mofa_variance_explained_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$variance_explained)) {
        saveRDS(result$variance_explained, file)
      }
    }
  )
  
  # Export All Results as comprehensive RDS bundle
  output$export_all_results <- downloadHandler(
    filename = function() {
      paste0("mofa_complete_results_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      # Create comprehensive export list
      export_list <- list(
        # Model metadata
        metadata = list(
          method = result$method,
          timestamp = Sys.time(),
          samples = length(result$common_samples),
          views = result$views
        ),
        # Main results
        results = list(
          factors = result$factors,
          weights = result$weights,
          variance_explained = result$variance_explained,
          top_features = result$top_features
        ),
        # Sample information
        sample_info = list(
          common_samples = result$common_samples,
          sample_groups = multiomics$sample_groups
        ),
        # Dimensionality reductions (if computed)
        dimred = list(
          umap = multiomics$mofa_umap,
          tsne = multiomics$mofa_tsne
        ),
        # Custom names (if provided)
        custom_names = list(
          factor_names = multiomics$factor_names,
          view_names = multiomics$view_names
        )
      )
      
      saveRDS(export_list, file)
      showNotification("Complete results exported successfully!", type = "message", duration = 3)
    }
  )
  
  # Download integration model as RDS
  output$download_model_rds <- downloadHandler(
    filename = function() {
      req(multiomics$integration_results)
      model_name <- if (!is.null(input$mofa_model_save_name) && input$mofa_model_save_name != "") {
        input$mofa_model_save_name
      } else {
        paste0(multiomics$integration_results$method, "_model_", format(Sys.time(), "%Y%m%d_%H%M%S"))
      }
      paste0(model_name, ".rds")
    },
    content = function(file) {
      req(multiomics$integration_results)
      
      result <- multiomics$integration_results
      
      # Prepare model object for saving
      model_obj <- list(
        method = result$method,
        model = result$model,
        metadata = list(
          name = input$mofa_model_save_name,
          description = input$model_save_description,
          created_date = Sys.time(),
          method_name = if (result$method == "mofa") "MOFA2" else if (result$method == "diablo") "DIABLO" else result$method
        ),
        # Include key results for quick reference
        results = list(
          factors = if (!is.null(result$factors)) result$factors else NULL,
          variance_explained = if (!is.null(result$variance_explained)) result$variance_explained else NULL,
          top_features = if (!is.null(result$top_features)) result$top_features else NULL
        ),
        data_info = list(
          views = result$views,
          n_samples = length(result$common_samples),
          common_samples = result$common_samples
        )
      )
      
      # Save as RDS
      saveRDS(model_obj, file)
      
      # Show success notification
      showNotification(
        paste("✓ Model saved as", basename(file)),
        type = "message",
        duration = 5
      )
    }
  )
  
  # Download integration model as HDF5 (MOFA only)
  output$download_model_hdf5 <- downloadHandler(
    filename = function() {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method != "mofa") {
        showNotification("HDF5 format is only available for MOFA models", type = "warning")
        return(NULL)
      }
      model_name <- if (!is.null(input$mofa_model_save_name) && input$mofa_model_save_name != "") {
        input$mofa_model_save_name
      } else {
        paste0("mofa_model_", format(Sys.time(), "%Y%m%d_%H%M%S"))
      }
      paste0(model_name, ".hdf5")
    },
    content = function(file) {
      req(multiomics$integration_results)
      
      result <- multiomics$integration_results
      
      # Only save MOFA models as HDF5
      if (result$method == "mofa" && !is.null(result$model)) {
        tryCatch({
          # Check if MOFA2 package is available
          if (!requireNamespace("MOFA2", quietly = TRUE)) {
            showNotification("MOFA2 package required for HDF5 export", type = "error")
            return(NULL)
          }
          
          # Save MOFA model to HDF5
          MOFA2::export_model(result$model, file)
          
          showNotification(
            paste("✓ MOFA model saved as", basename(file)),
            type = "message",
            duration = 5
          )
        }, error = function(e) {
          showNotification(
            paste("Error saving HDF5:", e$message),
            type = "error"
          )
        })
      } else {
        showNotification("HDF5 export is only available for MOFA models", type = "warning")
      }
    }
  )
  
  # Show model save status
