    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    status_text <- switch(result$method,
                          mofa = "✓ MOFA model loaded. Both RDS and HDF5 formats available.",
                          diablo = "✓ DIABLO model loaded. RDS format available.",
                          correlation = "✓ Correlation analysis complete. RDS format available.",
                          "Analysis complete. Model can be saved."
    )
    
    div(style = "padding: 10px; background-color: var(--success-light); border-left: 4px solid var(--success-color); border-radius: 4px;",
        p(status_text, style = "margin: 0; color: var(--success-color); font-weight: 500;"))
  })
  
