      as.character(1:diablo_tutorial$ncomp)
    } else {
      # Check normal integration results
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method == "diablo" && !is.null(result$ncomp)) {
        as.character(1:result$ncomp)
      } else {
        character(0)
      }
    }
  })
  
  diablo_block_choices <- reactive({
    # Check tutorial mode first
    if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model) && !is.null(diablo_tutorial$final_model$loadings)) {
      names(diablo_tutorial$final_model$loadings)
    } else {
