      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method == "diablo" && !is.null(result$model$loadings)) {
        names(result$model$loadings)
      } else {
        character(0)
      }
    }
  })
  
  diablo_pls_pair_choices <- reactive({
    # Check if tutorial is active
    if (diablo_tutorial$active && !is.null(diablo_tutorial$data)) {
      blocks <- names(diablo_tutorial$data)
    } else if (!is.null(multiomics$integration_results)) {
      result <- multiomics$integration_results
      if (result$method == "diablo" && !is.null(result$model$loadings)) {
        blocks <- names(result$model$loadings)
      } else {
        return(character(0))
      }
    } else {
      return(character(0))
    }
    
    # Generate all possible pairs
    if (length(blocks) >= 2) {
      pairs <- combn(blocks, 2, function(x) paste(x[1], "vs", x[2]))
      return(pairs)
    } else {
      return(character(0))
    }
  })
  
