          p <- p + geom_point(data = centroids, 
                             aes(x = Group, y = Centroid), 
                             color = "red", size = 4, shape = 18)
        }
        
        p
      }, error = function(e) {
        ggplot() + 
          annotate("text", x = 0.5, y = 0.5, 
                   label = paste("Error creating component scores plot:", e$message),
                   size = 4, color = "red") + 
          theme_void()
      }, res = UI_PLOT_RES)
    } else {
      # Normal mode - show user's DIABLO results
      req(multiomics$integration_results, input$diablo_comp_score_comp)
      result <- multiomics$integration_results
      
      if (result$method == "diablo" && !is.null(result$final_model)) {
        tryCatch({
          comp <- as.numeric(input$diablo_comp_score_comp)
          
          # Get component scores from final model
          scores <- result$final_model$variates$Y[, comp, drop = FALSE]
          if (is.null(scores) || nrow(scores) == 0) return(NULL)
          
          # Create dataframe
          plot_df <- data.frame(
            Sample = rownames(scores),
            Component_Score = scores[, 1],
            Group = result$Y
          )
          
          # Create plot
          p <- ggplot(plot_df, aes(x = Group, y = Component_Score, fill = Group)) +
            geom_boxplot(alpha = 0.7, outlier.shape = NA) +
            geom_jitter(width = 0.2, alpha = 0.6, size = 2) +
            labs(title = paste("DIABLO Component", comp, "Scores"),
                 x = "Group",
                 y = paste("Component", comp, "Score")) +
            theme_minimal() +
            theme(axis.text.x = element_text(angle = 45, hjust = 1),
                  plot.title = element_text(hjust = 0.5, face = "bold"),
                  legend.position = "none")
          
          if (isTRUE(input$diablo_comp_score_show_centroid)) {
            # Add group centroids
            centroids <- plot_df %>%
              group_by(Group) %>%
              summarise(Centroid = mean(Component_Score, na.rm = TRUE))
            
            p <- p + geom_point(data = centroids, 
                               aes(x = Group, y = Centroid), 
