  # Helper: Custom ggplot2-based DIABLO loadings plot with full control over styling
  # This replaces the native mixOmics::plotLoadings which ignores font/margin settings
  create_diablo_loadings_ggplot <- function(model, comp, contrib, method, font_size) {
    require(ggplot2)
    
    # Get block names (omics types)
    block_names <- names(model$loadings)
    block_names <- block_names[block_names != "Y"]  # Exclude outcome block
    
    # Get class/group information from Y
    Y <- model$Y
    classes <- levels(Y)
    n_classes <- length(classes)
    
    # Determine group colors - use mixOmics-like palette
    group_colors <- if (n_classes <= 3) {
      c("#388ECC", "#F68B33", "#C2C2C2")[1:n_classes]  # Blue, Orange, Grey
    } else if (n_classes <= 9) {
      c("#388ECC", "#F68B33", "#C2C2C2", "#009E73", "#CC79A7", 
        "#E69F00", "#56B4E9", "#D55E00", "#0072B2")[1:n_classes]
    } else {
      scales::hue_pal()(n_classes)
    }
    names(group_colors) <- classes
    
    # Extract loadings for each block and determine contributing class
    all_loadings <- list()
    
    for (block in block_names) {
      # Get loadings matrix for this block
      loadings_mat <- model$loadings[[block]]
      
      # Check if component exists
      if (comp > ncol(loadings_mat)) next
      
      # Get loadings for this component
      loadings_vec <- loadings_mat[, comp]
      
      # Filter to non-zero loadings (selected variables)
      selected <- loadings_vec[loadings_vec != 0]
      if (length(selected) == 0) next
      
      # Get expression data for this block
      X_block <- model$X[[block]]
      
      # Calculate contribution to each class
      for (var_name in names(selected)) {
        loading_value <- selected[var_name]
        
        # Calculate mean/median expression per class
        class_values <- sapply(classes, function(cl) {
          samples <- which(Y == cl)
          if (method == "median") {
            median(X_block[samples, var_name], na.rm = TRUE)
          } else {
            mean(X_block[samples, var_name], na.rm = TRUE)
          }
        })
        
        # Determine contributing class based on contrib parameter
        if (contrib == "max") {
          contrib_class <- classes[which.max(class_values)]
        } else {
          contrib_class <- classes[which.min(class_values)]
        }
        
        all_loadings[[length(all_loadings) + 1]] <- data.frame(
          Variable = var_name,
          Loading = loading_value,
          Block = block,
          ContribClass = contrib_class,
          stringsAsFactors = FALSE
        )
      }
    }
    
    if (length(all_loadings) == 0) {
      # Return empty plot with message
      return(ggplot() + 
               annotate("text", x = 0.5, y = 0.5, 
                        label = paste("No variables selected on component", comp),
                        size = 5) +
               theme_void())
    }
    
    # Combine all loadings
    df <- do.call(rbind, all_loadings)
    
    # Order by absolute loading within each block
    df <- df[order(df$Block, abs(df$Loading)), ]
    
    # Create ordered factor for y-axis (within each block, least to most important)
    df$Variable <- factor(df$Variable, levels = unique(df$Variable))
    df$Block <- factor(df$Block, levels = block_names)
    
    # Calculate text size from font_size parameter (scale appropriately)
    text_size <- font_size * 8  # Convert from cex-like to ggplot pts
    axis_text_size <- font_size * 7
    
    # Create the plot
    n_blocks <- length(levels(df$Block))
    facet_cols <- if (n_blocks <= 2) n_blocks else 2
    p <- ggplot(df, aes(x = Loading, y = Variable, fill = ContribClass)) +
      geom_col(width = 0.7) +
      geom_vline(xintercept = 0, color = "grey30", linewidth = 0.5) +
      facet_wrap(~ Block, scales = "free_y", ncol = facet_cols) +
      scale_fill_manual(values = group_colors, name = "Contribution") +
      labs(
        x = paste("Loadings on Component", comp),
        y = NULL,
        title = NULL
      ) +
      theme_bw(base_size = text_size) +
      theme(
        axis.text.y = element_text(size = axis_text_size, hjust = 1, color = "black"),
        axis.text.x = element_text(size = axis_text_size, color = "black"),
        axis.title.x = element_text(size = text_size),
        strip.text = element_text(size = text_size, face = "bold"),
        strip.background = element_rect(fill = "grey90"),
        legend.position = "bottom",
        legend.title = element_text(size = text_size * 0.9),
        legend.text = element_text(size = text_size * 0.8, color = "black"),
        panel.grid.major.y = element_blank(),
        panel.grid.minor = element_blank(),
        plot.margin = margin(t = 10, r = 10, b = 10, l = 10, unit = "pt")
      )
    
    return(p)
  }

  # Helper: safe png device (avoid cairo issues on Windows)
  open_png_device_safe <- function(file, width_px, height_px, dpi) {
    if (capabilities("cairo")) {
      ok <- tryCatch({
        grDevices::png(file, width = width_px, height = height_px, res = dpi, type = "cairo")
        TRUE
      }, error = function(e) FALSE)
      if (isTRUE(ok)) return(invisible(TRUE))
    }

    grDevices::png(file, width = width_px, height = height_px, res = dpi)
    invisible(TRUE)
  }
  
