  # DIABLO Performance Plot
  output$diablo_performance_plot <- renderPlot({ 
    if (diablo_tutorial$active) {
      # Tutorial mode - show tutorial performance plot
      req(diablo_tutorial$perf_final)
      
      plot(diablo_tutorial$perf_final)
    } else {
      # Normal mode - show user's DIABLO results
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "diablo" && (!is.null(result$performance) || !is.null(result$perf_result))) {
        tryCatch({
          # Prefer a mixOmics perf object if available (perf_result), otherwise fall back to stored performance structure
          perf_obj <- result$perf_result %||% result$performance

          # If it's a mixOmics perf object, use its plot method directly
          if (inherits(perf_obj, "perf")) {
            plot(perf_obj)
          } else {
            perf <- perf_obj
            # Extract performance metrics
            if (!is.null(perf$features) && "comp" %in% colnames(perf$features)) {
              perf_df <- perf$features

              # Plot balanced error rate or overall error rate
              if ("BER" %in% colnames(perf_df)) {
                p <- ggplot(perf_df, aes(x = comp, y = BER.mean)) +
                  geom_line(color = "#667eea", size = 1) +
                geom_point(color = "#667eea", size = 3) +
                geom_errorbar(aes(ymin = BER.mean - BER.sd, ymax = BER.mean + BER.sd), 
                             width = 0.2, color = "#667eea") +
                labs(title = "DIABLO Performance - Balanced Error Rate",
                     x = "Number of Components",
                     y = "BER (mean ± sd)") +
                theme_minimal() +
                theme(plot.title = element_text(hjust = 0.5, face = "bold"))
            } else if ("overall" %in% colnames(perf_df)) {
              p <- ggplot(perf_df, aes(x = comp, y = overall.mean)) +
                geom_line(color = "#667eea", size = 1) +
                geom_point(color = "#667eea", size = 3) +
                geom_errorbar(aes(ymin = overall.mean - overall.sd, ymax = overall.mean + overall.sd), 
                             width = 0.2, color = "#667eea") +
                labs(title = "DIABLO Performance - Overall Error Rate",
                     x = "Number of Components",
                     y = "Error Rate (mean ± sd)") +
                theme_minimal() +
                theme(plot.title = element_text(hjust = 0.5, face = "bold"))
            } else {
              p <- ggplot() + 
                annotate("text", x = 0.5, y = 0.5, 
                         label = "Performance metrics available but not in expected format",
                         size = 4, color = "#667eea") + 
                theme_void()
            }
            
            p
          } else {
            ggplot() + 
              annotate("text", x = 0.5, y = 0.5, 
                       label = "Performance data not available in expected format",
                       size = 4, color = "#667eea") + 
              theme_void()
          }
        }
        }, error = function(e) {
          ggplot() + 
            annotate("text", x = 0.5, y = 0.5, 
                     label = paste("Error creating performance plot:", e$message),
                     size = 4, color = "red") + 
            theme_void()
        }, res = UI_PLOT_RES)
      }
    }
  })
  
  # DIABLO Performance Plot (Tutorial or Real Data)
  output$diablo_perf_plot <- renderPlot({ 
    # Prefer tutorial perf result in tutorial mode; otherwise use integration perf or performance
    if (diablo_tutorial$active) {
      perf_obj <- diablo_tutorial$perf_result
    } else {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      perf_obj <- result$perf_result %||% result$performance
    }
    req(perf_obj)

    tryCatch({
      # Try to plot the perf object directly using mixOmics plot method
      if (inherits(perf_obj, "perf")) {
        # Use mixOmics plot method for perf objects
        plot(perf_obj)
      } else if (is.list(perf_obj) && (!is.null(perf_obj$choice.ncomp) || !is.null(perf_obj$features))) {
        # Manually set class and try plotting
        class(perf_obj) <- c("perf", class(perf_obj))
        plot(perf_obj)
      } else {
        # Not a recognized perf format, show error with details
        available_components <- if (is.list(perf_obj)) paste(names(perf_obj), collapse = ", ") else "none"
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("Performance data not in expected format.\nAvailable components:", available_components),
                   size = 3.5, color = "#667eea") +
          theme_void()
      }
    }, error = function(e) {
      # If plotting fails, try to extract and plot manually
      tryCatch({
        perf <- perf_obj
        if (!is.null(perf$features) && "comp" %in% colnames(perf$features)) {
          perf_df <- perf$features

          if ("BER" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = BER.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = BER.mean - BER.sd, ymax = BER.mean + BER.sd),
                            width = 0.2, color = "#667eea") +
              labs(title = "DIABLO Performance - Balanced Error Rate",
                   x = "Number of Components",
                   y = "BER (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          } else if ("overall" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = overall.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = overall.mean - overall.sd, ymax = overall.mean + overall.sd),
                            width = 0.2, color = "#667eea") +
              labs(title = "DIABLO Performance - Overall Error Rate",
                   x = "Number of Components",
                   y = "Error Rate (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          } else {
            p <- ggplot() +
              annotate("text", x = 0.5, y = 0.5,
                       label = "Performance metrics available but not in expected format",
                       size = 4, color = "#667eea") +
              theme_void()
          }
          p
        } else {
          ggplot() +
            annotate("text", x = 0.5, y = 0.5,
                     label = paste("Error creating performance plot:", e$message),
                     size = 4, color = "red") +
            theme_void()
        }
      }, error = function(e2) {
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = paste("Error creating performance plot:", e$message),
                   size = 4, color = "red") +
          theme_void()
      })
    })
  })
  
  # DIABLO Performance Summary (Tutorial Mode)
  output$diablo_perf_summary <- renderPrint({
    perf <- diablo_tutorial$perf_result %||% (multiomics$integration_results$perf_result %||% NULL)
    req(perf)

    tryCatch({
      summary(perf)
    }, error = function(e) {
      cat("Error creating performance summary:", e$message)
    })
  })
  
  # DIABLO Has Performance Results (for conditional panel)
  output$diablo_has_perf_results <- reactive({
    !is.null(diablo_tutorial$perf_result) || !is.null(multiomics$integration_results$perf_result)
  })
  outputOptions(output, "diablo_has_perf_results", suspendWhenHidden = FALSE)
  
  # Clear selected cell when performance results change
  observeEvent({
    diablo_tutorial$perf_result
    multiomics$integration_results$perf_result
  }, {
    diablo_tutorial$selected_cell <- NULL
  })
  
  # DIABLO Design Matrix Display
  output$diablo_design_matrix <- renderPrint({
    # Show design matrix for both tutorial and real data; prefer the active mode
    design <- NULL
    if (isTRUE(diablo_tutorial$active) && !is.null(diablo_tutorial$design)) {
      design <- diablo_tutorial$design
    } else if (!is.null(multiomics$integration_results$design)) {
      design <- multiomics$integration_results$design
    } else if (!is.null(diablo_tutorial$design)) {
      design <- diablo_tutorial$design
    }
    
    req(design)
    
    tryCatch({
      print(design)
    }, error = function(e) {
      cat("Error displaying design matrix:", e$message)
    })
  })
  
  output$diablo_optimal_ncomp_text <- renderUI({
    perf <- diablo_tutorial$perf_result %||% (multiomics$integration_results$perf_result %||% NULL)
    req(perf)
    tryCatch({
      # Prefer stored ncomp from tutorial/integration results when available
      ncomp <- diablo_tutorial$ncomp %||% multiomics$integration_results$ncomp
      last_metric <- diablo_tutorial$last_choice_metric %||% multiomics$integration_results$last_choice_metric
      last_dist <- diablo_tutorial$last_choice_dist
      
      if (is.null(ncomp)) {
        HTML("<strong>ncomp:</strong> <em>Not set</em>")
      } else {
        if (!is.null(last_metric) && !is.null(last_dist)) {
          HTML(paste0("<strong>ncomp:</strong> ", ncomp, " (selected from ", last_metric, " × ", last_dist, ")"))
        } else {
          HTML(paste0("<strong>ncomp:</strong> ", ncomp, " (manually set)"))
        }
      }
    }, error = function(e) {
      HTML(paste0("<span style='color:red;'>Error displaying optimal ncomp: ", e$message, "</span>"))
    })
  })

  # DIABLO Optimal Ncomp Table (click a cell to set ncomp)
  output$diablo_optimal_ncomp_table <- DT::renderDT({
    perf <- diablo_tutorial$perf_result %||% (multiomics$integration_results$perf_result %||% NULL)
    req(perf)
    
    # Force re-render when selected cell changes
    selected_cell <- diablo_tutorial$selected_cell
    
    tryCatch({
      choice_table <- perf$choice.ncomp$WeightedVote
      df <- as.data.frame(choice_table)
      df <- cbind(Criterion = rownames(df), df)
      rownames(df) <- NULL

      # JS callback: send clicked cell (row/col/value) to Shiny
      callback_js <- htmlwidgets::JS(
        "table.on('click', 'tbody td', function() {",
        "  var cell = table.cell(this);",
        "  var idx = cell.index();",
        "  var row = idx.row;",
        "  var col = idx.column;",
        "  var val = cell.data();",
        "  // send to Shiny (zero-based indices)",
        "  Shiny.setInputValue('diablo_choice_cell', {row: row, col: col, value: val}, {priority: 'event'});",
        "});",
        "// Double-click: set ncomp and trigger feature tuning",
        "table.on('dblclick', 'tbody td', function() {",
        "  var cell = table.cell(this);",
        "  var idx = cell.index();",
        "  var row = idx.row;",
        "  var col = idx.column;",
        "  var val = cell.data();",
        "  Shiny.setInputValue('diablo_choice_cell_dbl', {row: row, col: col, value: val}, {priority: 'event'});",
        "});"
      )

      DT::datatable(
        df,
        options = list(
          pageLength = 5,
          dom = 't',
          scrollX = TRUE,
          rowCallback = htmlwidgets::JS(
            sprintf(
              "function(row, data, displayNum, displayIndex, dataIndex) {
                var selectedCell = %s;
                if (selectedCell && selectedCell.row === dataIndex && selectedCell.col !== undefined) {
                  $(row).find('td').eq(selectedCell.col).addClass('dt-cell-selected');
                }
              }",
              jsonlite::toJSON(selected_cell, auto_unbox = TRUE, null = "null")
            )
          )
        ),
        rownames = FALSE,
        callback = callback_js,
        selection = 'none'
      )
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error displaying choice.ncomp:", e$message)), options = list(dom = 't'))
    })
  })

  # Apply click selection from the choice.ncomp table
  observeEvent(input$diablo_choice_cell, {
    perf <- diablo_tutorial$perf_result %||% (multiomics$integration_results$perf_result %||% NULL)
    req(perf)
    tryCatch({
      cell <- input$diablo_choice_cell
      # DataTables uses zero-based indices
      row_idx <- as.integer(cell$row)
      col_idx <- as.integer(cell$col)
      val_raw <- cell$value

      choice_table <- perf$choice.ncomp$WeightedVote
      if (is.null(choice_table) || length(choice_table) == 0) stop('choice.ncomp table not available')

      # Our displayed df has a leading 'Criterion' column, so data columns start at DT col index 1
      if (col_idx == 0) {
        showNotification('Click a numeric cell (not the row label).', type = 'warning')
        return()
      }

      metrics <- rownames(choice_table)
      dists <- colnames(choice_table)

      if (row_idx + 1 > length(metrics) || col_idx > length(dists)) {
        stop('Clicked cell out of range')
      }

      metric_name <- metrics[row_idx + 1]
      dist_name <- dists[col_idx]  # col_idx is already 1-based for data columns

      val_num <- suppressWarnings(as.numeric(val_raw))
      if (is.na(val_num)) stop('Selected cell value is not numeric')

      # Store the selected cell for highlighting
      diablo_tutorial$selected_cell <- list(row = row_idx, col = col_idx, value = val_num)

      # Store selection in tutorial store or integration_results depending on active mode
      if (diablo_tutorial$active) {
        diablo_tutorial$ncomp <- as.integer(val_num)
        diablo_tutorial$last_choice_metric <- metric_name
        diablo_tutorial$last_choice_dist <- dist_name
        updateSliderInput(session, 'diablo_ncomp', value = diablo_tutorial$ncomp)
        showNotification(paste('ncomp set to', diablo_tutorial$ncomp, 'from', metric_name, 'and', dist_name), type = 'message', duration = 3)
      } else {
        req(multiomics$integration_results)
        multiomics$integration_results$ncomp <- as.integer(val_num)
        multiomics$integration_results$last_choice_metric <- metric_name
        multiomics$integration_results$last_choice_dist <- dist_name
        updateSliderInput(session, 'diablo_ncomp', value = multiomics$integration_results$ncomp)
        showNotification(paste('ncomp set to', multiomics$integration_results$ncomp, 'from', metric_name, 'and', dist_name), type = 'message', duration = 3)
      }
    }, error = function(e) {
      showNotification(paste('Error applying selection:', e$message), type = 'error')
    })
  })

  # Double-click: set ncomp AND start feature tuning automatically
  observeEvent(input$diablo_choice_cell_dbl, {
    perf <- diablo_tutorial$perf_result %||% (multiomics$integration_results$perf_result %||% NULL)
    req(perf)
    tryCatch({
      cell <- input$diablo_choice_cell_dbl
      row_idx <- as.integer(cell$row)
      col_idx <- as.integer(cell$col)
      val_raw <- cell$value

      choice_table <- perf$choice.ncomp$WeightedVote
      if (is.null(choice_table) || length(choice_table) == 0) stop('choice.ncomp table not available')
      if (col_idx == 0) {
        showNotification('Double-click a numeric cell (not the row label).', type = 'warning')
        return()
      }

      metrics <- rownames(choice_table)
      dists <- colnames(choice_table)
      if (row_idx + 1 > length(metrics) || col_idx > length(dists)) stop('Clicked cell out of range')

      metric_name <- metrics[row_idx + 1]
      dist_name <- dists[col_idx]  # col_idx is already 1-based for data columns
      val_num <- suppressWarnings(as.numeric(val_raw))
      if (is.na(val_num)) stop('Selected cell value is not numeric')

      # Set ncomp and update selectors/slider
      if (diablo_tutorial$active) {
        diablo_tutorial$ncomp <- as.integer(val_num)
        diablo_tutorial$last_choice_metric <- metric_name
        diablo_tutorial$last_choice_dist <- dist_name
        updateSliderInput(session, 'diablo_ncomp', value = diablo_tutorial$ncomp)
        showNotification(paste('ncomp set to', diablo_tutorial$ncomp, '— starting feature tuning...'), type = 'message', duration = 3)
      } else {
        req(multiomics$integration_results)
        multiomics$integration_results$ncomp <- as.integer(val_num)
        multiomics$integration_results$last_choice_metric <- metric_name
        multiomics$integration_results$last_choice_dist <- dist_name
        updateSliderInput(session, 'diablo_ncomp', value = multiomics$integration_results$ncomp)
        showNotification(paste('ncomp set to', multiomics$integration_results$ncomp, '— starting feature tuning...'), type = 'message', duration = 3)
      }

      # Programmatically click the Run Feature Tuning button to reuse existing logic
      try({
        shinyjs::click('run_feature_tuning')
      }, silent = TRUE)

    }, error = function(e) {
      showNotification(paste('Error on double-click selection:', e$message), type = 'error')
    })
  })
  
  # DIABLO Has Tune Results (for conditional panel)
  output$diablo_has_tune_results <- reactive({
    has_tutorial_tune <- !is.null(diablo_tutorial$tune_result) || !is.null(diablo_tutorial$keepX)
    has_real_tune <- !is.null(multiomics$integration_results) && !is.null(multiomics$integration_results$keepX)
    has_tutorial_tune || has_real_tune
  })
  outputOptions(output, "diablo_has_tune_results", suspendWhenHidden = FALSE)

  # Apply manual ncomp from numeric input
  observeEvent(input$apply_diablo_ncomp_manual, {
    req(input$diablo_ncomp_manual)
    tryCatch({
      val <- as.integer(input$diablo_ncomp_manual)
      
      # Apply to appropriate location
      if (diablo_tutorial$active) {
        diablo_tutorial$ncomp <- val
      } else {
        req(multiomics$integration_results)
        multiomics$integration_results$ncomp <- val
      }
      
      updateSliderInput(session, "diablo_ncomp", value = val)
      showNotification(paste("ncomp manually set to", val), type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error setting manual ncomp:", e$message), type = "error")
    })
  })  
  # DIABLO Optimal KeepX Display (present as table)
  output$diablo_optimal_keepx <- DT::renderDT({
    if (diablo_tutorial$active) {
      req(diablo_tutorial$keepX)
      keepX <- diablo_tutorial$keepX
    } else {
      req(multiomics$integration_results$keepX)
      keepX <- multiomics$integration_results$keepX
    }

    tryCatch({
      # Use extracted keepX
      # Convert list of vectors to a data.frame with columns for components
      blocks <- names(keepX)
      ncomp_vals <- unique(sapply(keepX, length))
      max_comp <- max(sapply(keepX, length))

      df <- data.frame(Block = blocks, stringsAsFactors = FALSE)
      for (i in seq_len(max_comp)) {
        df[[paste0('Comp', i)]] <- sapply(keepX, function(x) if (length(x) >= i) x[i] else NA)
      }

      DT::datatable(df, options = list(pageLength = 10, dom = 't'), rownames = FALSE) %>%
        DT::formatRound(columns = grep('Comp', colnames(df), value = TRUE), digits = 0)
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error displaying keepX:", e$message)), options = list(dom = 't'))
    })
  })
  
  # DIABLO Has Final Model (for conditional panel)
  output$diablo_has_final_model <- reactive({
    # Check both tutorial and real data models
    has_tutorial_model <- !is.null(diablo_tutorial$final_model)
    has_real_model <- !is.null(multiomics$integration_results) && 
                      multiomics$integration_results$method == "diablo" && 
                      (!is.null(multiomics$integration_results$final_model) || 
                       !is.null(multiomics$integration_results$model))
    has_tutorial_model || has_real_model
  })
  outputOptions(output, "diablo_has_final_model", suspendWhenHidden = FALSE)
  
  # DIABLO Show Selected Variables (for conditional panel)
  output$diablo_show_selected_vars <- reactive({
    !is.null(input$show_selected_vars) && input$show_selected_vars > 0
  })
  outputOptions(output, "diablo_show_selected_vars", suspendWhenHidden = FALSE)
  
  # DIABLO Selected Variables Display
  output$diablo_selected_variables <- DT::renderDT({
    # Check if we have either tutorial or real data model
    model <- NULL
    mode <- NULL

    if (!is.null(diablo_tutorial$final_model)) {
      model <- diablo_tutorial$final_model
      mode <- "tutorial"
    } else if (!is.null(multiomics$integration_results) &&
               multiomics$integration_results$method == "diablo") {
      # Check for both final_model and model
      model <- multiomics$integration_results$final_model %||% multiomics$integration_results$model
      mode <- "real"
    }

    req(model, input$diablo_selected_block, input$diablo_selected_comp)

    tryCatch({
      # Validate inputs
      if (!input$diablo_selected_block %in% names(model$loadings)) {
        return(DT::datatable(data.frame(
          Error = paste("Selected block '", input$diablo_selected_block, "' not found in model."),
          Available_Blocks = paste(names(model$loadings), collapse = ", ")
        ), options = list(dom = 't'), rownames = FALSE))
      }

      comp_num <- as.numeric(input$diablo_selected_comp)
      max_ncomp <- max(model$ncomp)
      if (is.na(comp_num) || comp_num < 1 || comp_num > max_ncomp) {
        return(DT::datatable(data.frame(
          Error = paste("Invalid component number '", input$diablo_selected_comp, "'. Must be between 1 and ", max_ncomp, ".")
        ), options = list(dom = 't'), rownames = FALSE))
      }

      # Get selected variables for the specified block and component
      selected_vars <- mixOmics::selectVar(model,
                                block = input$diablo_selected_block,
                                comp = comp_num)

      # Extract variable names and (if available) loadings
      block_entry <- selected_vars[[input$diablo_selected_block]]
      if (is.null(block_entry)) {
        return(DT::datatable(data.frame(
          Error = paste("No data found for block '", input$diablo_selected_block, "' in selectVar result.")
        ), options = list(dom = 't'), rownames = FALSE))
      }

      var_names <- block_entry$name
      loadings <- if (!is.null(block_entry$value)) round(block_entry$value$value.var, 6) else rep(NA, length(var_names))

      # Limit to max variables to show
      n_show <- min(input$diablo_selected_nvars, length(var_names))
      var_names <- var_names[1:n_show]
      loadings <- loadings[1:n_show]

      # Create data.frame for DataTable
      df <- data.frame(
        Rank = 1:n_show,
        Variable = var_names,
        Loading = loadings,
        stringsAsFactors = FALSE
      )

      # Set table title as caption
      table_title <- paste("Selected variables for", input$diablo_selected_block, "Component", input$diablo_selected_comp,
                          "(Top", n_show, "variables)")

      DT::datatable(df,
                   options = list(dom = 't', scrollX = TRUE, scrollY = "400px", paging = FALSE),
                   rownames = FALSE,
                   caption = table_title) %>%
        DT::formatRound(columns = "Loading", digits = 6)

    }, error = function(e) {
      DT::datatable(data.frame(
        Error = paste("Error displaying selected variables:", e$message)
      ), options = list(dom = 't'), rownames = FALSE)
    })
  })

  # Download selected variables as CSV
  output$download_diablo_selected_vars <- downloadHandler(
    filename = function() {
      paste0("diablo_selected_vars_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      # Determine which model to use
      if (diablo_tutorial$active) {
        req(diablo_tutorial$final_model, input$diablo_selected_block, input$diablo_selected_comp)
        model <- diablo_tutorial$final_model
      } else {
        req(multiomics$integration_results, 
            isTRUE(multiomics$integration_results$method == "diablo"),
            input$diablo_selected_block, input$diablo_selected_comp)
        model <- multiomics$integration_results$final_model %||% multiomics$integration_results$model
      }
      
      tryCatch({
        # Validate inputs
        comp_num <- as.numeric(input$diablo_selected_comp)
        max_ncomp <- max(model$ncomp)
        if (is.na(comp_num) || comp_num < 1 || comp_num > max_ncomp) {
          stop("Invalid component number")
        }
        
        # Get selected variables for ALL blocks
        all_blocks <- names(model$loadings)
        all_selected_vars <- list()
        
        for (block_name in all_blocks) {
          selected_vars <- mixOmics::selectVar(model, 
                                     block = block_name, 
                                     comp = comp_num)
          block_entry <- selected_vars[[block_name]]
          
          if (!is.null(block_entry)) {
            block_df <- data.frame(
              Block = block_name,
              Variable = block_entry$name, 
              Loading = if (!is.null(block_entry$value)) block_entry$value$value.var else NA,
              Rank = seq_along(block_entry$name),
              stringsAsFactors = FALSE
            )
            all_selected_vars[[block_name]] <- block_df
          }
        }
        
        # Combine all blocks into one data frame
        if (length(all_selected_vars) > 0) {
          combined_df <- do.call(rbind, all_selected_vars)
          # Sort by absolute loading value (descending) to show most important variables first
          combined_df <- combined_df[order(abs(combined_df$Loading), decreasing = TRUE), ]
          # Reset row names
          rownames(combined_df) <- NULL
        } else {
          combined_df <- data.frame(
            Block = character(0),
            Variable = character(0),
            Loading = numeric(0),
            Rank = integer(0),
            stringsAsFactors = FALSE
          )
        }
        
        write.csv(combined_df, file, row.names = FALSE)
      }, error = function(e) {
        # Create error CSV
        df <- data.frame(Error = paste("Error downloading selected variables:", e$message), 
                        stringsAsFactors = FALSE)
        write.csv(df, file, row.names = FALSE)
      })
    }
  )
  
  # ============================================
  # DIABLO Selected Variables Tab - Server Logic
  # ============================================
  
  # Observer to update block and component choices when final model is available
  observe({
    # Get the final model from either tutorial or real data mode
    model <- NULL
    ncomp_val <- 1
    
    if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model)) {
      model <- diablo_tutorial$final_model
      ncomp_val <- diablo_tutorial$ncomp %||% max(model$ncomp)
    } else if (!is.null(multiomics$integration_results) && 
               !is.null(multiomics$integration_results$final_model) &&
               isTRUE(multiomics$integration_results$method == "diablo")) {
      model <- multiomics$integration_results$final_model
      ncomp_val <- multiomics$integration_results$ncomp %||% max(model$ncomp)
    } else if (!is.null(multiomics$integration_results) && 
               !is.null(multiomics$integration_results$model) &&
               isTRUE(multiomics$integration_results$method == "diablo")) {
      model <- multiomics$integration_results$model
      ncomp_val <- multiomics$integration_results$ncomp %||% max(model$ncomp)
    }
    
    if (!is.null(model)) {
      # Update block choices
      blocks <- names(model$loadings)
      updateSelectInput(session, "diablo_selected_block_tab",
                        choices = blocks,
                        selected = blocks[1])
      
      # Update component choices
      comp_choices <- as.character(seq_len(ncomp_val))
      updateSelectInput(session, "diablo_selected_comp_tab",
                        choices = comp_choices,
                        selected = comp_choices[1])
    }
  })
  
  # Render selected variables table for the tab
  output$diablo_selected_variables_tab <- DT::renderDT({
    # Check if we have either tutorial or real data model
    model <- NULL
    
    if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model)) {
      model <- diablo_tutorial$final_model
    } else if (!is.null(multiomics$integration_results) && 
               isTRUE(multiomics$integration_results$method == "diablo")) {
      model <- multiomics$integration_results$final_model %||% multiomics$integration_results$model
    }
    
    req(model, input$diablo_selected_block_tab, input$diablo_selected_comp_tab)
    
    tryCatch({
      # Validate block selection
      if (!input$diablo_selected_block_tab %in% names(model$loadings)) {
        return(DT::datatable(data.frame(
          Message = paste("Selected block '", input$diablo_selected_block_tab, "' not found in model."),
          Available_Blocks = paste(names(model$loadings), collapse = ", ")
        ), options = list(dom = 't'), rownames = FALSE))
      }
      
      comp_num <- as.numeric(input$diablo_selected_comp_tab)
      max_ncomp <- max(model$ncomp)
      if (is.na(comp_num) || comp_num < 1 || comp_num > max_ncomp) {
        return(DT::datatable(data.frame(
          Message = paste("Invalid component number. Must be between 1 and", max_ncomp)
        ), options = list(dom = 't'), rownames = FALSE))
      }
      
      # Get selected variables for the specified block and component
      selected_vars <- mixOmics::selectVar(model,
                                           block = input$diablo_selected_block_tab,
                                           comp = comp_num)
      
      # Extract variable names and loadings
      block_entry <- selected_vars[[input$diablo_selected_block_tab]]
      if (is.null(block_entry) || length(block_entry$name) == 0) {
        return(DT::datatable(data.frame(
          Message = "No selected variables found for this block and component."
        ), options = list(dom = 't'), rownames = FALSE))
      }
      
      var_names <- block_entry$name
      loadings <- if (!is.null(block_entry$value)) round(block_entry$value$value.var, 6) else rep(NA, length(var_names))
      
      # Limit to max variables to show
      n_show <- min(input$diablo_selected_nvars_tab %||% 20, length(var_names))
      var_names <- var_names[1:n_show]
      loadings <- loadings[1:n_show]
      
      # Create data.frame for DataTable
      df <- data.frame(
        Rank = 1:n_show,
        Variable = var_names,
        Loading = loadings,
        stringsAsFactors = FALSE
      )
      
      # Set table title as caption
      table_title <- paste("Selected Variables for", input$diablo_selected_block_tab, 
                           "- Component", input$diablo_selected_comp_tab,
                           "(Showing Top", n_show, "of", length(block_entry$name), "variables)")
      
      DT::datatable(df,
                    options = list(
                      dom = 'Bfrtip',
                      scrollX = TRUE, 
                      scrollY = "500px", 
                      paging = TRUE,
                      pageLength = 25,
                      buttons = c('copy', 'csv', 'excel')
                    ),
                    rownames = FALSE,
                    caption = htmltools::tags$caption(
                      style = 'caption-side: top; text-align: left; font-weight: bold; font-size: 14px; margin-bottom: 10px;',
                      table_title
                    ),
                    extensions = 'Buttons') %>%
        DT::formatRound(columns = "Loading", digits = 6)
      
    }, error = function(e) {
      DT::datatable(data.frame(
        Error = paste("Error displaying selected variables:", e$message)
      ), options = list(dom = 't'), rownames = FALSE)
    })
  })
  
  # Download handler for Selected Variables tab
  output$download_diablo_selected_vars_tab <- downloadHandler(
    filename = function() {
      paste0("diablo_selected_vars_", input$diablo_selected_block_tab, "_comp", 
             input$diablo_selected_comp_tab, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      # Determine which model to use
      model <- NULL
      if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model)) {
        model <- diablo_tutorial$final_model
      } else if (!is.null(multiomics$integration_results) && 
                 isTRUE(multiomics$integration_results$method == "diablo")) {
        model <- multiomics$integration_results$final_model %||% multiomics$integration_results$model
      }
      
      req(model, input$diablo_selected_block_tab, input$diablo_selected_comp_tab)
      
      tryCatch({
        comp_num <- as.numeric(input$diablo_selected_comp_tab)
        
        # Get selected variables for ALL blocks for comprehensive download
        all_blocks <- names(model$loadings)
        all_selected_vars <- list()
        
        for (block_name in all_blocks) {
          selected_vars <- mixOmics::selectVar(model, 
                                               block = block_name, 
                                               comp = comp_num)
          block_entry <- selected_vars[[block_name]]
          
          if (!is.null(block_entry) && length(block_entry$name) > 0) {
            block_df <- data.frame(
              Block = block_name,
              Rank = seq_along(block_entry$name),
              Variable = block_entry$name, 
              Loading = if (!is.null(block_entry$value)) round(block_entry$value$value.var, 6) else NA,
              Component = comp_num,
              stringsAsFactors = FALSE
            )
            all_selected_vars[[block_name]] <- block_df
          }
        }
        
        # Combine all blocks into one data frame
        if (length(all_selected_vars) > 0) {
          combined_df <- do.call(rbind, all_selected_vars)
          rownames(combined_df) <- NULL
        } else {
          combined_df <- data.frame(
            Block = character(0),
            Rank = integer(0),
            Variable = character(0),
            Loading = numeric(0),
            Component = integer(0),
            stringsAsFactors = FALSE
          )
        }
        
        write.csv(combined_df, file, row.names = FALSE)
      }, error = function(e) {
        df <- data.frame(Error = paste("Error downloading selected variables:", e$message), 
                         stringsAsFactors = FALSE)
        write.csv(df, file, row.names = FALSE)
      })
    }
  )
  
  # DIABLO Performance Table - Majority Vote
  output$diablo_performance_table <- DT::renderDT({
    if (diablo_tutorial$active) {
      # Tutorial mode
      req(diablo_tutorial$perf_final)
      perf <- diablo_tutorial$perf_final
    } else {
      # Real data mode
      req(multiomics$integration_results)
      perf <- multiomics$integration_results$perf_final
    }
    
    req(perf)
    
    tryCatch({
      # Extract MajorityVote error rates
      if (!is.null(perf$MajorityVote.error.rate)) {
        maj_vote <- perf$MajorityVote.error.rate
        
        if (is.list(maj_vote) && length(maj_vote) > 0) {
          # Get the distance method results (first element)
          dist_results <- maj_vote[[1]]
          
          if (is.matrix(dist_results) || is.data.frame(dist_results)) {
            df <- as.data.frame(dist_results)
            df <- cbind(Metric = rownames(df), df)
            rownames(df) <- NULL
            
            DT::datatable(df,
                         caption = "MajorityVote Error Rates by Component",
                         options = list(pageLength = 10, scrollX = TRUE, dom = 't'),
                         rownames = FALSE) %>%
              DT::formatRound(columns = 2:ncol(df), digits = 4)
          } else {
            DT::datatable(data.frame(Message = "Error rate data not in expected format"),
                         options = list(dom = 't'), rownames = FALSE)
          }
        } else {
          DT::datatable(data.frame(Message = "No MajorityVote error rates available"),
                       options = list(dom = 't'), rownames = FALSE)
        }
      } else {
        DT::datatable(data.frame(Message = "Performance evaluation not completed"),
                     options = list(dom = 't'), rownames = FALSE)
      }
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error displaying performance:", e$message)),
                   options = list(dom = 't'), rownames = FALSE)
    })
  })
  
  # DIABLO Performance Table - Weighted Vote
  output$diablo_performance_weighted_table <- DT::renderDT({
    if (diablo_tutorial$active) {
      # Tutorial mode
      req(diablo_tutorial$perf_final)
      perf <- diablo_tutorial$perf_final
    } else {
