  # Update AUROC block choices based on available model blocks
  observe({
    if (diablo_tutorial$active) {
      req(diablo_tutorial$final_model)
      if (!is.null(diablo_tutorial$final_model$loadings)) {
        block_names <- names(diablo_tutorial$final_model$loadings)
        updateSelectInput(session, "diablo_auroc_block", 
                         choices = block_names,
                         selected = if (length(block_names) > 0) block_names[1] else NULL)
        
        # Update component choices
        ncomp <- max(diablo_tutorial$final_model$ncomp)
        comp_choices <- 1:ncomp
        updateSelectInput(session, "diablo_auroc_comp", 
                         choices = comp_choices,
                         selected = min(2, ncomp))
      }
    } else {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method == "diablo" && !is.null(result$model$loadings)) {
        block_names <- names(result$model$loadings)
        updateSelectInput(session, "diablo_auroc_block", 
                         choices = block_names,
                         selected = if (length(block_names) > 0) block_names[1] else NULL)
        
        # Update component choices
        ncomp <- max(result$model$ncomp)
        comp_choices <- 1:ncomp
        updateSelectInput(session, "diablo_auroc_comp", 
                         choices = comp_choices,
                         selected = min(2, ncomp))
      }
    }
  })
  
  # Performance Tuning - Run component number tuning
  observeEvent(input$run_diablo_tuning, {
    req(input$diablo_perf_type == "tuning")
    
    withProgress(message = "Running DIABLO Performance Tuning", value = 0, {
      
      if (diablo_tutorial$active) {
        # Tutorial mode
        setProgress(0.1, "Setting up tutorial data")
        
        # Use the final model for performance tuning
        req(diablo_tutorial$final_model)
        
        setProgress(0.3, "Running performance evaluation")
        
        # Run performance evaluation with the selected distance
        perf_result <- mixOmics::perf(
          diablo_tutorial$final_model,
          validation = input$diablo_perf_validation,
          folds = input$diablo_perf_folds,
          nrepeat = input$diablo_perf_nrepeat,
          dist = input$diablo_perf_dist
        )
        
        # Store results
        diablo_tutorial$perf_tuning_result <- perf_result
        
        setProgress(1.0, "Performance tuning completed")
        
        showNotification("Performance tuning completed successfully!", type = "message", duration = 3)
        
      } else {
        # Normal mode - user data
        req(multiomics$integration_results)
        result <- multiomics$integration_results
        
        if (result$method == "diablo" && !is.null(result$model)) {
          setProgress(0.3, "Running performance evaluation on user model")
          
          # Run performance evaluation with the selected distance
          perf_result <- mixOmics::perf(
            result$model,
            validation = input$diablo_perf_validation,
            folds = input$diablo_perf_folds,
            nrepeat = input$diablo_perf_nrepeat,
            dist = input$diablo_perf_dist
          )
          
      # Store results in multiomics (both locations for compatibility)
      multiomics$perf_tuning_result <- perf_result
      multiomics$integration_results$perf_final <- perf_result
      
      # Extract detailed error rate table with per-group information
      error_rate_df <- NULL
      if (!is.null(perf_result$MajorityVote.error.rate)) {
        maj_vote <- perf_result$MajorityVote.error.rate
        if (is.list(maj_vote) && length(maj_vote) > 0) {
          # Get the distance method results
          dist_results <- maj_vote[[1]]
          if (is.matrix(dist_results) || is.data.frame(dist_results)) {
            error_rate_df <- as.data.frame(dist_results)
            error_rate_df <- cbind(Component = rownames(error_rate_df), error_rate_df)
            rownames(error_rate_df) <- NULL
          }
        }
      }
      
      # Also get WeightedVote error rates
      weighted_error_df <- NULL
      if (!is.null(perf_result$WeightedVote.error.rate)) {
        weighted_vote <- perf_result$WeightedVote.error.rate
        if (is.list(weighted_vote) && length(weighted_vote) > 0) {
          dist_results <- weighted_vote[[1]]
          if (is.matrix(dist_results) || is.data.frame(dist_results)) {
            weighted_error_df <- as.data.frame(dist_results)
            weighted_error_df <- cbind(Component = rownames(weighted_error_df), weighted_error_df)
            rownames(weighted_error_df) <- NULL
          }
        }
      }
      
      # Store the formatted tables
      multiomics$integration_results$perf_majority_vote <- error_rate_df
      multiomics$integration_results$perf_weighted_vote <- weighted_error_df
          
          setProgress(1.0, "Performance tuning completed")
          
          showNotification("Performance tuning completed successfully!", type = "message", duration = 3)
        } else {
          showNotification("No DIABLO model available for performance tuning", type = "error")
        }
      }
    })
  })
  
  # DIABLO Performance Tuning Plot
  output$diablo_perf_tuning_plot <- renderPlot({ 
    if (diablo_tutorial$active) {
      req(diablo_tutorial$perf_tuning_result)
      
      tryCatch({
        perf <- diablo_tutorial$perf_tuning_result
        
        # Plot performance vs number of components
        if (!is.null(perf$features) && "comp" %in% colnames(perf$features)) {
          perf_df <- perf$features
          
          # Plot balanced error rate or overall error rate
          if ("BER" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = BER.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = BER.mean - BER.sd, ymax = BER.mean + BER.sd), 
                           width = 0.2, color = "#667eea") +
              labs(title = paste("DIABLO Performance Tuning -", input$diablo_perf_dist),
                   x = "Number of Components",
                   y = "BER (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          } else if ("overall" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = overall.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = overall.mean - overall.sd, ymax = overall.mean + overall.sd), 
                           width = 0.2, color = "#667eea") +
              labs(title = paste("DIABLO Performance Tuning -", input$diablo_perf_dist),
                   x = "Number of Components",
                   y = "Error Rate (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          } else {
            p <- ggplot() + 
              annotate("text", x = 0.5, y = 0.5, 
                       label = "Performance tuning data available but not in expected format",
                       size = 4, color = "#667eea") + 
              theme_void()
          }
          
          p
        } else {
          ggplot() + 
            annotate("text", x = 0.5, y = 0.5, 
                     label = "Performance tuning data not available",
                     size = 4, color = "#667eea") + 
