        }
        
        # Plot performance vs number of components
        if (!is.null(perf$features) && "comp" %in% colnames(perf$features)) {
          perf_df <- perf$features
          
          # Plot balanced error rate or overall error rate
          if ("BER" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = BER.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = BER.mean - BER.sd, ymax = BER.mean + BER.sd), 
                           width = 0.2, color = "#667eea") +
              labs(title = paste("DIABLO Performance Tuning -", input$diablo_perf_dist),
                   x = "Number of Components",
                   y = "BER (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          } else if ("overall" %in% colnames(perf_df)) {
            p <- ggplot(perf_df, aes(x = comp, y = overall.mean)) +
              geom_line(color = "#667eea", size = 1) +
              geom_point(color = "#667eea", size = 3) +
              geom_errorbar(aes(ymin = overall.mean - overall.sd, ymax = overall.mean + overall.sd), 
                           width = 0.2, color = "#667eea") +
              labs(title = paste("DIABLO Performance Tuning -", input$diablo_perf_dist),
                   x = "Number of Components",
                   y = "Error Rate (mean ± sd)") +
              theme_minimal() +
              theme(plot.title = element_text(hjust = 0.5, face = "bold"))
          }
          
          print(p)
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error creating performance tuning plot:", e$message))
      })
      dev.off()
    }
  )
  
  # Observe AUROC parameter changes and compute AUROC
  observeEvent(c(input$diablo_perf_type, input$diablo_auroc_comp, input$diablo_auroc_block), {
    req(input$diablo_perf_type == "auroc")
    
    # Only compute if we have a model and valid inputs
    if (diablo_tutorial$active) {
      req(diablo_tutorial$final_model, input$diablo_auroc_block, input$diablo_auroc_comp)
      
      # Check if the selected block exists in the model
      if (!is.null(diablo_tutorial$final_model$loadings) && 
          input$diablo_auroc_block %in% names(diablo_tutorial$final_model$loadings)) {
        
        tryCatch({
          # Compute AUROC for the selected block and component
          auroc_result <- mixOmics::auroc(
            diablo_tutorial$final_model,
            roc.block = input$diablo_auroc_block,
            roc.comp = as.numeric(input$diablo_auroc_comp),
            print = FALSE
          )
          
          # Store the result
          diablo_tutorial$auroc_result <- auroc_result
          
        }, error = function(e) {
          diablo_tutorial$auroc_result <- NULL
          showNotification(paste("Error computing AUROC:", e$message), type = "error")
        })
      }
    } else {
      # Normal mode - user data
      req(multiomics$integration_results, input$diablo_auroc_block, input$diablo_auroc_comp)
      result <- multiomics$integration_results
      
      if (result$method == "diablo" && !is.null(result$model) &&
          !is.null(result$model$loadings) && 
          input$diablo_auroc_block %in% names(result$model$loadings)) {
        
        tryCatch({
          # Compute AUROC for the selected block and component
          auroc_result <- mixOmics::auroc(
            result$model,
            roc.block = input$diablo_auroc_block,
            roc.comp = as.numeric(input$diablo_auroc_comp),
            print = FALSE
          )
          
          # Store the result
          multiomics$auroc_result <- auroc_result
          
        }, error = function(e) {
          multiomics$auroc_result <- NULL
          showNotification(paste("Error computing AUROC:", e$message), type = "error")
        })
      }
    }
  })
  
  # DIABLO AUROC Plot
  output$diablo_auroc_plot <- renderPlot({ 
    if (diablo_tutorial$active) {
      req(diablo_tutorial$auroc_result, diablo_tutorial$final_model)
      
      tryCatch({
        # Re-run auroc with print = TRUE to generate the plot
        mixOmics::auroc(
          diablo_tutorial$final_model,
          roc.block = input$diablo_auroc_block,
          roc.comp = as.numeric(input$diablo_auroc_comp),
          print = TRUE
        )
        
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error creating AUROC plot:", e$message), col = "red")
      }, res = UI_PLOT_RES)
      
    } else {
      # Normal mode
      req(multiomics$auroc_result, multiomics$integration_results)
      result <- multiomics$integration_results
      
      if (result$method == "diablo" && !is.null(result$model)) {
        tryCatch({
          # Re-run auroc with print = TRUE to generate the plot
          mixOmics::auroc(
            result$model,
            roc.block = input$diablo_auroc_block,
            roc.comp = as.numeric(input$diablo_auroc_comp),
            print = TRUE
          )
          
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, paste("Error creating AUROC plot:", e$message), col = "red")
        }, res = UI_PLOT_RES)
      } else {
        plot.new()
        text(0.5, 0.5, "No DIABLO model available for AUROC analysis")
      }
    }
  })
  
  # Download handler for DIABLO AUROC Plot
  output$download_diablo_auroc <- downloadHandler(
    filename = function() {
      paste0("diablo_auroc_", input$diablo_auroc_block, "_comp", input$diablo_auroc_comp, "_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      png(file, width = round(800 * scale), height = round(600 * scale), res = dpi)
      tryCatch({
        if (diablo_tutorial$active) {
          req(diablo_tutorial$final_model)
          mixOmics::auroc(
            diablo_tutorial$final_model,
            roc.block = input$diablo_auroc_block,
            roc.comp = as.numeric(input$diablo_auroc_comp),
            print = TRUE
          )
        } else {
          req(multiomics$integration_results)
          result <- multiomics$integration_results
          if (result$method == "diablo" && !is.null(result$model)) {
            mixOmics::auroc(
              result$model,
              roc.block = input$diablo_auroc_block,
              roc.comp = as.numeric(input$diablo_auroc_comp),
              print = TRUE
            )
          }
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error creating AUROC plot:", e$message))
      })
      dev.off()
    }
  )
  
  # DIABLO PLS Plot
  output$diablo_pls_plot <- renderPlot({ 
    # Check if PLS models exist (persists even after switching tabs)
    if (!is.null(diablo_tutorial$pls_models) && length(diablo_tutorial$pls_models) > 0) {
      req(diablo_tutorial$pls_models)
      
      if (input$diablo_pls_grid) {
        # Build pairs dynamically from pls_pair_map
        pair_map <- diablo_tutorial$pls_pair_map %||% character(0)
        pairs <- list()
        if (length(pair_map) > 0) {
          for (display_name in names(pair_map)) {
            model_key <- pair_map[[display_name]]
            model <- diablo_tutorial$pls_models[[model_key]]
            parts <- strsplit(display_name, " vs ")[[1]]
            len1 <- if (!is.null(diablo_tutorial$data[[parts[1]]])) ncol(diablo_tutorial$data[[parts[1]]]) else 0
            len2 <- if (!is.null(diablo_tutorial$data[[parts[2]]])) ncol(diablo_tutorial$data[[parts[2]]]) else 0
            pairs[[length(pairs) + 1]] <- list(model = model, name = display_name, len1 = len1, len2 = len2)
          }
        }
        
        if (input$diablo_pls_style == 'ggplot2') {
          # Try to build ggplot objects and arrange them
          plots <- list()
          for (i in seq_along(pairs)) {
            p <- pairs[[i]]
            pair_parts <- strsplit(p$name, " vs ")[[1]]
            legend_param <- if (input$diablo_pls_legend) pair_parts else FALSE
            cex_param <- list(rep(input$diablo_pls_cex, p$len1), rep(input$diablo_pls_cex, p$len2))
            pch_param <- list(rep(16, p$len1), rep(17, p$len2))

            # plotVar with style = 'ggplot2' should return a ggplot object
            gp <- tryCatch({
              ggobj <- mixOmics::plotVar(p$model,
                      comp = 1:2,
                      var.names = rep(input$diablo_pls_var_names, 2),
                      legend = legend_param,
                      title = p$name,
                      style = 'ggplot2',
                      cutoff = input$diablo_pls_cutoff,
                      col = c(input$diablo_pls_col1, input$diablo_pls_col2),
                      cex = cex_param,
                      pch = pch_param)
              if (inherits(ggobj, 'ggplot')) {
                # ensure legend keys use the shapes specified
                n_blocks_local <- 2
                pch_local <- c(16, 17)
                override_size_local <- 4
                ggobj <- ggobj + ggplot2::guides(
                  shape = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local)),
                  colour = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local)),
                  fill = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local))
                )
              }
              ggobj
            }, error = function(e) {
              NULL
            }, res = UI_PLOT_RES)
            plots[[i]] <- gp
          }

          # Arrange ggplots: prefer patchwork, then gridExtra, then sequential print
          if (requireNamespace("patchwork", quietly = TRUE) && all(sapply(plots, inherits, what = "gg"))) {
            combined <- Reduce(function(a, b) a + b, plots)
            print(combined)
          } else if (requireNamespace("gridExtra", quietly = TRUE) && all(sapply(plots, inherits, what = "gg"))) {
            gridExtra::grid.arrange(grobs = plots, ncol = 3)
          } else {
            # Fallback: print sequentially (will show stacked or multiple pages depending on device)
            for (gp in plots) {
              if (!is.null(gp)) print(gp)
            }
          }
        } else {
          # Graphics style: use base graphics in a 1x3 panel
          oldpar <- par(no.readonly = TRUE)
          on.exit(par(oldpar), add = TRUE)
          par(mfrow = c(1, 3))

          for (p in pairs) {
            # If no model available for this pair, show placeholder
            if (is.null(p$model)) {
              plot.new()
              text(0.5, 0.5, paste0("No PLS model for ", p$name), col = "#667eea")
              next
            }

            pair_parts <- strsplit(p$name, " vs ")[[1]]
            legend_param <- if (input$diablo_pls_legend) pair_parts else FALSE

            # Safe lengths for cex/pch (fallback to 1)
            len1 <- if (!is.null(p$len1) && is.finite(p$len1) && p$len1 > 0) p$len1 else 1
            len2 <- if (!is.null(p$len2) && is.finite(p$len2) && p$len2 > 0) p$len2 else 1

            cex_param <- list(rep(input$diablo_pls_cex, len1), rep(input$diablo_pls_cex, len2))
            pch_param <- list(rep(16, len1), rep(17, len2))

            tryCatch({
              mixOmics::plotVar(p$model, 
                      comp = 1:2, 
                      var.names = rep(input$diablo_pls_var_names, 2), 
                      legend = legend_param, 
                      title = p$name,
                      style = 'graphics',
                      cutoff = input$diablo_pls_cutoff,
                      col = c(input$diablo_pls_col1, input$diablo_pls_col2),
                      cex = cex_param,
                      pch = pch_param)
            }, error = function(e) {
              plot.new()
              text(0.5, 0.5, paste0("Error plotting ", p$name, ": ", e$message), col = "#d9534f")
            }, res = UI_PLOT_RES)
          }
        }
      } else {
        # Show single selected pair
        req(input$diablo_pls_pair)
        
        # Map pair name to model key (dynamic)
        pair_map <- diablo_tutorial$pls_pair_map %||% character(0)
        # Use unname to handle cases where pair_map might return multiple values
        model_key <- unname(pair_map[input$diablo_pls_pair])[1]
        
        if (!is.null(model_key) && !is.null(diablo_tutorial$pls_models[[model_key]])) {
          model <- diablo_tutorial$pls_models[[model_key]]

          # Validate model and sample data
          pair_parts <- strsplit(input$diablo_pls_pair, " vs ")[[1]]
          # If the referenced blocks don't exist in diablo_tutorial$data, show message
          if (is.null(diablo_tutorial$data[[pair_parts[1]]]) || is.null(diablo_tutorial$data[[pair_parts[2]]]) || is.null(model)) {
            plot.new()
            text(0.5, 0.5, "No PLS model or data available for selected pair", col = "#667eea")
          } else {
            legend_param <- if (input$diablo_pls_legend) pair_parts else FALSE

            # Safe lengths for cex/pch
            len1 <- ncol(diablo_tutorial$data[[pair_parts[1]]])
            len2 <- ncol(diablo_tutorial$data[[pair_parts[2]]])
            len1 <- ifelse(is.na(len1) || len1 < 1, 1, len1)
            len2 <- ifelse(is.na(len2) || len2 < 1, 1, len2)

            cex_param <- list(rep(input$diablo_pls_cex, len1), rep(input$diablo_pls_cex, len2))
            pch_param <- list(rep(16, len1), rep(17, len2))

            # Custom title
            plot_title <- if (nzchar(input$diablo_pls_title)) input$diablo_pls_title else paste('PLS Correlation Circle:', input$diablo_pls_pair)

            tryCatch({
              ggobj <- mixOmics::plotVar(model, 
                      comp = 1:2, 
                      var.names = rep(input$diablo_pls_var_names, 2), 
                      legend = legend_param, 
                      title = plot_title,
                      style = input$diablo_pls_style,
                      cutoff = input$diablo_pls_cutoff,
                      col = c(input$diablo_pls_col1, input$diablo_pls_col2),
                      cex = cex_param,
                      pch = pch_param)
              if (inherits(ggobj, 'ggplot')) {
                # For single pair ggplot2, ensure legend keys use the shapes specified
                pch_local <- pch_param[[1]]
                override_size_local <- tryCatch({ median(unlist(cex_param)) * 3 }, error = function(e) 4)
                ggobj <- ggobj + ggplot2::guides(
                  shape = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local)),
                  colour = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local)),
                  fill = ggplot2::guide_legend(override.aes = list(shape = pch_local, size = override_size_local))
                )
                print(ggobj)
              } else {
                # graphics style already handled by mixOmics
                NULL
              }
            }, error = function(e) {
              plot.new()
              if (grepl("NA/NaN", e$message)) {
                text(0.5, 0.5, "No correlations meet the current cutoff threshold.\nTry lowering the Correlation Cutoff slider.", col = "#d9534f")
              } else {
                text(0.5, 0.5, paste0("Error plotting selected pair: ", e$message), col = "#d9534f")
              }
            }, res = UI_PLOT_RES)
          }
        } else {
          plot.new()
          text(0.5, 0.5, "No PLS model available for selected pair", col = "#667eea")
        }
      }
    } else {
      # No PLS models available - show informative message
      plot.new()
      text(0.5, 0.5, "Run pairwise PLS analysis first", col = "#667eea")
    }
  })
  
  # DIABLO PLS Correlations Table
  output$diablo_pls_correlations <- DT::renderDT({
    # Check for PLS models existence (persists even after switching tabs)
    if (!is.null(diablo_tutorial$pls_models) && length(diablo_tutorial$pls_models) > 0) {
      req(diablo_tutorial$pls_models)
      
      # Calculate correlations for first and second components using dynamic pair map
      pair_map <- diablo_tutorial$pls_pair_map %||% character(0)
      correlations <- data.frame()

      if (length(pair_map) > 0) {
        for (display_name in names(pair_map)) {
          model_key <- pair_map[[display_name]]
          model <- diablo_tutorial$pls_models[[model_key]]
          if (!is.null(model) && !is.null(model$variates$X) && !is.null(model$variates$Y) && ncol(model$variates$X) >= 2) {
            cor1 <- cor(model$variates$X[,1], model$variates$Y[,1])
            cor2 <- cor(model$variates$X[,2], model$variates$Y[,2])

            correlations <- rbind(correlations, data.frame(
              Pair = display_name,
              Comp1 = round(cor1, 4),
              Comp2 = round(cor2, 4)
            ))
          }
        }
      }
      
      if (nrow(correlations) > 0) {
        DT::datatable(correlations, 
                      options = list(dom = 't', paging = FALSE, searching = FALSE, info = FALSE),
                      rownames = FALSE) %>%
          DT::formatStyle(columns = c('Pair'), `text-align` = 'left') %>%
          DT::formatStyle(columns = c('Comp1', 'Comp2'), 
                          backgroundColor = DT::styleInterval(c(0.8, 0.9), 
                                                             c('white', 'lightyellow', 'lightgreen')))
      } else {
        DT::datatable(data.frame(Pair = character(0), Comp1 = numeric(0), Comp2 = numeric(0)), 
                      options = list(dom = 't'), rownames = FALSE)
      }
    } else {
      DT::datatable(data.frame(Pair = character(0), Comp1 = numeric(0), Comp2 = numeric(0)), 
                    options = list(dom = 't'), rownames = FALSE)
    }
  })
  
  # DIABLO Integration Summary
  output$diablo_integration_summary <- renderPrint({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (result$method == "diablo") {
      cat("DIABLO MULTI-OMICS INTEGRATION SUMMARY\n")
      cat("=====================================\n\n")
      
      cat("Method: DIABLO (Data Integration using Latent variable models for Blocks of variables)\n")
      cat("Number of components:", result$ncomp, "\n")
      cat("Number of data blocks:", length(result$model$loadings), "\n")
      cat("Block names:", paste(names(result$model$loadings), collapse = ", "), "\n")
      cat("Sample size:", length(result$Y), "\n")
      cat("Number of groups:", length(unique(result$Y)), "\n")
      cat("Groups:", paste(unique(result$Y), collapse = ", "), "\n\n")
      
      if (!is.null(result$performance)) {
        cat("PERFORMANCE METRICS:\n")
        cat("-------------------\n")
        if (!is.null(result$performance$features)) {
          perf_df <- result$performance$features
          if ("BER" %in% colnames(perf_df)) {
            best_comp <- which.min(perf_df$BER.mean)
            cat("Best balanced error rate:", round(perf_df$BER.mean[best_comp], 4), 
                "±", round(perf_df$BER.sd[best_comp], 4), 
                "at", perf_df$comp[best_comp], "components\n")
          }
          if ("overall" %in% colnames(perf_df)) {
            best_comp <- which.min(perf_df$overall.mean)
            cat("Best overall error rate:", round(perf_df$overall.mean[best_comp], 4), 
                "±", round(perf_df$overall.sd[best_comp], 4), 
                "at", perf_df$comp[best_comp], "components\n")
          }
        }
        cat("\n")
      }
      
      cat("FEATURE SELECTION:\n")
      cat("------------------\n")
      for (block in names(result$model$loadings)) {
        loadings <- result$model$loadings[[block]]
        selected_features <- sum(apply(abs(loadings), 1, max) > 0)
        total_features <- nrow(loadings)
        cat(block, ":", selected_features, "selected out of", total_features, 
            paste0("(", round(selected_features/total_features * 100, 1), "%)"), "\n")
      }
    }
  })
  
  # DIABLO Has Performance Check
  output$diablo_has_performance <- reactive({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    result$method == "diablo" && !is.null(result$performance)
  })
  outputOptions(output, "diablo_has_performance", suspendWhenHidden = FALSE)
  
  # ============================================================================
  # DIABLO DOWNLOAD HANDLERS
  # ============================================================================
  
  # Download DIABLO Component Scores
  output$download_diablo_comp_scores <- downloadHandler(
    filename = function() {
      paste0("diablo_comp_scores_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      png(file, width = round(800 * scale), height = round(600 * scale), res = dpi)
      print(diablo_component_scores_plot())
      dev.off()
    }
  )
  
  # Download DIABLO Correlations
  output$download_diablo_correlations <- downloadHandler(
    filename = function() {
      paste0("diablo_component_correlations_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      if (diablo_tutorial$active) {
        # Tutorial mode
        req(diablo_tutorial$final_model)
        dpi <- get_safe_global_dpi()
        scale <- dpi / 100
        png(file, width = round(800 * scale), height = round(600 * scale), res = dpi)
        tryCatch({
          mixOmics::plotVar(diablo_tutorial$final_model, comp = 1:2, 
                           var.names = c(TRUE, TRUE, TRUE), 
                           legend = TRUE, 
                           title = 'DIABLO Correlation Circle Plot')
        }, error = function(e) {
          plot.new()
          text(0.5, 0.5, "plotVar visualization")
        })
        dev.off()
      } else {
        # Normal mode
        req(multiomics$integration_results)
        result <- multiomics$integration_results
        
        if (result$method == "diablo" && !is.null(result$sample_coords) && length(result$sample_coords) > 1) {
          dpi <- get_safe_global_dpi()
          scale <- dpi / 100
          png(file, width = round(800 * scale), height = round(600 * scale), res = dpi)
          
          # Get component scores for all components
          comp_scores <- do.call(cbind, lapply(result$sample_coords, function(x) x[, 1]))
          colnames(comp_scores) <- paste0("Comp", 1:ncol(comp_scores))
          
          # Calculate correlations
          cor_matrix <- cor(comp_scores, use = "pairwise.complete.obs", method = input$diablo_cor_method)
          
          # Apply threshold
          cor_matrix[abs(cor_matrix) < input$diablo_cor_threshold] <- 0
          
          # Create correlation plot
          if (requireNamespace("corrplot", quietly = TRUE)) {
            corrplot::corrplot(cor_matrix, 
                              method = "color",
                              type = "upper",
                              addCoef.col = if (isTRUE(input$diablo_show_cor_labels)) "black" else NULL,
                              tl.col = "black",
                              tl.srt = 45,
                              title = "DIABLO Component Correlations",
                              mar = c(0,0,2,0))
          } else {
            # Fallback to basic correlation plot using base R
            image(cor_matrix, col = heat.colors(12), axes = FALSE)
            axis(1, at = seq(0, 1, length.out = ncol(cor_matrix)), labels = colnames(cor_matrix))
            axis(2, at = seq(0, 1, length.out = nrow(cor_matrix)), labels = rownames(cor_matrix))
            title("DIABLO Component Correlations")
          }
          
          dev.off()
        }
      }
    }
  )
  
  # Download DIABLO Loadings
  output$download_diablo_loadings <- downloadHandler(
    filename = function() {
      paste0("diablo_loadings_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      tryCatch({
        font_size <- if (!is.null(input$diablo_loadings_font_size)) input$diablo_loadings_font_size else 1.5
        
        p <- NULL
        if (diablo_tutorial$active) {
          # Tutorial mode
          req(diablo_tutorial$final_model, input$diablo_loadings_comp, input$diablo_loadings_contrib, input$diablo_loadings_method)
          comp <- as.numeric(input$diablo_loadings_comp)
          contrib <- input$diablo_loadings_contrib
          method <- input$diablo_loadings_method
          p <- create_diablo_loadings_ggplot(diablo_tutorial$final_model, comp, contrib, method, font_size)
        } else {
          # Normal mode
          req(multiomics$integration_results, input$diablo_loadings_comp, input$diablo_loadings_contrib, input$diablo_loadings_method)
          result <- multiomics$integration_results
          model <- result$final_model %||% result$model
          if (result$method == "diablo" && !is.null(model)) {
            comp <- as.numeric(input$diablo_loadings_comp)
            contrib <- input$diablo_loadings_contrib
            method <- input$diablo_loadings_method
            p <- create_diablo_loadings_ggplot(model, comp, contrib, method, font_size)
          }
        }
        
        width_px <- round(1000 * scale)
        height_px <- round(700 * scale)
        open_png_device_safe(file, width_px, height_px, dpi)
        on.exit(grDevices::dev.off(), add = TRUE)
        if (!is.null(p)) {
          print(p)
        } else {
          plot.new()
          text(0.5, 0.5, "No DIABLO model available")
        }
      }, error = function(e) {
        open_png_device_safe(file, round(1000 * scale), round(700 * scale), dpi)
        plot.new()
        text(0.5, 0.5, paste("Error:", e$message))
        grDevices::dev.off()
      })
    }
  )
  
