  # Download choice.ncomp WeightedVote table as CSV
  output$download_diablo_choice_ncomp <- downloadHandler(
    filename = function() {
      paste0("diablo_choice_ncomp_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      if (diablo_tutorial$active) {
        req(diablo_tutorial$perf_result)
        choice_tab <- diablo_tutorial$perf_result$choice.ncomp$WeightedVote
      } else {
        # Support perf_result (mixOmics perf object) or legacy performance structure
        req(multiomics$integration_results)
        result <- multiomics$integration_results
        if (!is.null(result$perf_result) && !is.null(result$perf_result$choice.ncomp)) {
          choice_tab <- result$perf_result$choice.ncomp$WeightedVote
        } else if (!is.null(result$performance) && !is.null(result$performance$choice.ncomp)) {
          choice_tab <- result$performance$choice.ncomp$WeightedVote
        } else {
          choice_tab <- NULL
        }
      }
      if (is.null(choice_tab) || length(choice_tab) == 0) stop("No choice.ncomp available to export")
      df <- as.data.frame(choice_tab)
      df <- cbind(Criterion = rownames(df), df)
      rownames(df) <- NULL
      write.csv(df, file, row.names = FALSE)
    }
  )

  # Download keepX (optimal feature counts) as CSV
  output$download_diablo_keepx <- downloadHandler(
    filename = function() {
      paste0("diablo_keepX_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      if (diablo_tutorial$active) {
        req(diablo_tutorial$keepX)
        keepX <- diablo_tutorial$keepX
      } else {
        req(multiomics$integration_results$keepX)
        keepX <- multiomics$integration_results$keepX
      }
      blocks <- names(keepX)
      max_comp <- max(sapply(keepX, length))
      df <- data.frame(Block = blocks, stringsAsFactors = FALSE)
      for (i in seq_len(max_comp)) df[[paste0('Comp', i)]] <- sapply(keepX, function(x) if (length(x) >= i) x[i] else NA)
      write.csv(df, file, row.names = FALSE)
    }
  )
  
  # Download DIABLO Model
  output$download_diablo_model_rds <- downloadHandler(
    filename = function() {
      req(multiomics$integration_results)
      model_name <- if (!is.null(input$diablo_model_save_name) && input$diablo_model_save_name != "") {
