      # Prepare model object for saving
      model_obj <- list(
        method = result$method,
        model = result$model,
        metadata = list(
          name = input$diablo_model_save_name,
          description = input$diablo_model_save_description,
          created_date = Sys.time(),
          method_name = "DIABLO"
        ),
        results = list(
          var_importance = result$var_importance,
          sample_coords = result$sample_coords,
          performance = result$performance,
          Y = result$Y,
          ncomp = result$ncomp
        ),
        data_info = list(
          blocks = names(result$model$loadings),
          n_samples = length(result$Y),
          groups = levels(result$Y)
        )
      )
      
      # Save as RDS
      saveRDS(model_obj, file)
      
      # Show success notification
      showNotification(
        paste("✓ DIABLO model saved as", basename(file)),
        type = "message",
        duration = 5
      )
    }
  )
  
