  # ============================================================================
  # MOFA CLL TUTORIAL INTEGRATION SERVER CODE
  # ============================================================================
  
  # Load CLL multi-omics data for MOFA tutorial
  observeEvent(input$load_mofa_cll_tutorial, {
    withProgress(message = "Loading CLL Tutorial Data...", value = 0, {
      tryCatch({
        incProgress(0.1, detail = "Checking required packages...")
        
        # Ensure MOFA2 and MOFAdata packages are loaded
        if (!requireNamespace("MOFA2", quietly = TRUE)) {
          stop("MOFA2 package is not installed. Please install from Bioconductor: BiocManager::install('MOFA2')")
        }
        if (!requireNamespace("MOFAdata", quietly = TRUE)) {
          stop("MOFAdata package is not installed. Please install from Bioconductor: BiocManager::install('MOFAdata')")
        }
        
        incProgress(0.2, detail = "Loading CLL data...")
        
        # Load the CLL data from MOFAdata package
        data("CLL_data", package = "MOFAdata", envir = environment())
        
        # Verify data loaded correctly
        if (!exists("CLL_data", envir = environment())) {
          stop("Failed to load CLL_data from MOFAdata package")
        }
        
        incProgress(0.3, detail = "Loading sample metadata...")
        
        # Try to load sample metadata from MOFA tutorial FTP
        # Expected columns: sample, Gender (m/f), Age, TTT (time to treatment), 
        # TTD (time to death), treatedAfter, Died, IGHV, trisomy12
        CLL_metadata <- tryCatch({
          meta <- data.table::fread("ftp://ftp.ebi.ac.uk/pub/databases/mofa/cll_vignette/sample_metadata.txt")
          meta <- as.data.frame(meta)
          
          # Log available columns for debugging
          message("CLL metadata loaded with columns: ", paste(colnames(meta), collapse = ", "))
          message("Metadata has ", nrow(meta), " samples")
          
          # Report columns with missing values (useful for prediction targets)
          for (col in colnames(meta)) {
            n_missing <- sum(is.na(meta[[col]]))
            if (n_missing > 0) {
              message("  - ", col, ": ", n_missing, " missing values (", 
                      round(n_missing / nrow(meta) * 100, 1), "%)")
            }
          }
          
          meta
        }, error = function(e) {
          # If FTP fails, create basic metadata from sample names
          message("Could not fetch metadata from FTP: ", e$message)
          message("Creating basic metadata from sample names")
          samples <- colnames(CLL_data[[1]])
          data.frame(sample = samples, stringsAsFactors = FALSE)
        })
        
        incProgress(0.4, detail = "Creating MOFA object...")
        
        # Create the MOFA object
        mofa_object <- MOFA2::create_mofa(CLL_data)
        
        incProgress(0.5, detail = "Setting data options...")
        
        # Get and set data options
        data_opts <- MOFA2::get_default_data_options(mofa_object)
        data_opts$scale_views <- FALSE
        data_opts$scale_groups <- FALSE
        
        incProgress(0.55, detail = "Setting model options...")
        
        # Get and set model options (following tutorial: 15 factors)
        model_opts <- MOFA2::get_default_model_options(mofa_object)
        model_opts$num_factors <- 15
        
        incProgress(0.6, detail = "Setting training options...")
        
        # Get and set training options (following tutorial: seed = 42, slow convergence)
        train_opts <- MOFA2::get_default_training_options(mofa_object)
        train_opts$convergence_mode <- "slow"
        train_opts$seed <- 42  # Tutorial seed
        train_opts$maxiter <- 1000
        train_opts$verbose <- FALSE
        
        incProgress(0.65, detail = "Preparing MOFA model...")
        
        # Prepare the MOFA object
        mofa_object <- MOFA2::prepare_mofa(mofa_object,
                                           data_options = data_opts,
                                           model_options = model_opts,
                                           training_options = train_opts)
        
        incProgress(0.7, detail = "Training MOFA model (this may take ~2 minutes)...")
        
        # Train the MOFA model
        trained_model <- tryCatch({
          # Try with basilisk first
          MOFA2::run_mofa(mofa_object, use_basilisk = TRUE)
        }, error = function(e) {
          message("Basilisk failed, trying without basilisk...")
          tryCatch({
            MOFA2::run_mofa(mofa_object, use_basilisk = FALSE)
          }, error = function(e2) {
            # If training fails, try to load pre-computed model
            message("Training failed, attempting to load pre-computed model...")
            tryCatch({
              readRDS(url("http://ftp.ebi.ac.uk/pub/databases/mofa/cll_vignette/MOFA2_CLL.rds"))
            }, error = function(e3) {
              stop(paste("MOFA training failed and could not load pre-computed model:", e2$message))
            })
          })
        })
        
        incProgress(0.85, detail = "Adding sample metadata...")
        
        # Add sample metadata to the model
        if (!is.null(CLL_metadata) && nrow(CLL_metadata) > 0) {
          tryCatch({
            MOFA2::samples_metadata(trained_model) <- CLL_metadata
          }, error = function(e) {
            message("Could not add metadata to model: ", e$message)
          })
        }
        
        incProgress(0.9, detail = "Extracting results...")
        
        # Extract factors
        factors <- MOFA2::get_factors(trained_model, factors = "all")[[1]]
        factors_df <- as.data.frame(factors)
        colnames(factors_df) <- paste0("Factor", 1:ncol(factors_df))
        factors_df$Sample <- rownames(factors_df)
        
        # Extract weights
        views <- MOFA2::views_names(trained_model)
        weights_list <- list()
        for (view in views) {
          weights <- MOFA2::get_weights(trained_model, views = view, factors = "all")
          if (!is.null(weights) && length(weights) > 0) {
            weights_mat <- if (is.list(weights)) weights[[1]] else weights
            weights_df <- as.data.frame(weights_mat)
            colnames(weights_df) <- paste0("Factor", 1:ncol(weights_df))
            weights_df$Feature <- rownames(weights_df)
            weights_df$View <- view
            weights_list[[view]] <- weights_df
          }
        }
        
        # Calculate variance explained
        r2_total <- tryCatch({
          MOFA2::calculate_variance_explained(trained_model)
        }, error = function(e) {
          MOFA2::get_variance_explained(trained_model)
        })
        
        r2_per_factor <- NULL
        if (!is.null(r2_total) && !is.null(r2_total$r2_per_factor)) {
          r2_per_factor <- r2_total$r2_per_factor[[1]]
        }
        
        r2_per_view <- NULL
        if (!is.null(r2_total) && !is.null(r2_total$r2_per_view)) {
          r2_per_view <- if (is.list(r2_total$r2_per_view)) r2_total$r2_per_view[[1]] else r2_total$r2_per_view
        } else if (!is.null(r2_total) && !is.null(r2_total$r2_total)) {
          r2_per_view <- if (is.list(r2_total$r2_total)) r2_total$r2_total[[1]] else r2_total$r2_total
        }
        
        incProgress(0.95, detail = "Storing results...")
        
        # Store in mofa_tutorial reactive values
        mofa_tutorial$active <- TRUE
        mofa_tutorial$is_tutorial <- TRUE
        mofa_tutorial$data <- CLL_data
        mofa_tutorial$metadata <- CLL_metadata
        mofa_tutorial$mofa_object <- mofa_object
        mofa_tutorial$trained_model <- trained_model
        mofa_tutorial$factors <- factors_df
        mofa_tutorial$weights <- weights_list
        mofa_tutorial$variance_explained <- r2_per_factor
        mofa_tutorial$variance_explained_total <- r2_per_view
        mofa_tutorial$views <- views
        mofa_tutorial$common_samples <- rownames(factors)

        # Propagate tutorial metadata to MOFA metadata so covariates are available across tabs
        if (!is.null(CLL_metadata) && nrow(CLL_metadata) > 0) {
          md <- as.data.frame(CLL_metadata, stringsAsFactors = FALSE)
          sample_col <- NULL
          if ("SampleID" %in% colnames(md)) {
            sample_col <- "SampleID"
          } else {
            candidate <- grep("sample", colnames(md), ignore.case = TRUE, value = TRUE)
            if (length(candidate) > 0) sample_col <- candidate[1]
          }

          if (!is.null(sample_col) && sample_col != "SampleID") {
            colnames(md)[colnames(md) == sample_col] <- "SampleID"
            sample_col <- "SampleID"
          }

          if (is.null(sample_col) && !is.null(rownames(md))) {
            md$SampleID <- rownames(md)
            sample_col <- "SampleID"
          }

          if (!is.null(sample_col) && sample_col %in% colnames(md)) {
            rownames(md) <- as.character(md[[sample_col]])
          }

          mofa_metadata$full_metadata <- md
          mofa_metadata$sample_col_name <- "SampleID"
          mofa_metadata$data <- data.frame(SampleID = rownames(md), stringsAsFactors = FALSE)

          # Ensure covariate pickers update immediately for tutorial metadata
          tryCatch({
            updateSelectInput(session, "mofa_sample_id_col", selected = "SampleID")
          }, error = function(e) NULL)
          tryCatch({
            refresh_mofa_metadata_from_selected_columns()
          }, error = function(e) NULL)
        }
        
        # Also store in multiomics$integration_results for plot rendering
        multiomics$integration_results <- list(
          method = "mofa",
          mofa_model = trained_model,
          model = trained_model,
          factors = factors_df,
          weights = weights_list,
          variance_explained = r2_per_factor,
          variance_explained_total_view = r2_per_view,
          variance_explained_details = r2_total,
          views = views,
          common_samples = rownames(factors),
          is_tutorial = TRUE
        )
        
        # Store views in multiomics
        multiomics$view_names <- views
        multiomics$factor_names <- colnames(factors_df)[colnames(factors_df) != "Sample"]
        
        incProgress(1.0, detail = "Complete!")
        
        # Build metadata summary for notification
        meta_cols <- if (!is.null(CLL_metadata) && ncol(CLL_metadata) > 1) {
          paste0("• Metadata: ", paste(setdiff(colnames(CLL_metadata), "sample"), collapse = ", "), "<br/>")
        } else ""
        
        showNotification(
          HTML(paste0(
            "CLL multi-omics tutorial data loaded successfully!<br/>",
            "• 4 omics views: Drugs, Methylation, mRNA, Mutations<br/>",
            "• N=200 CLL patients<br/>",
            "• 15 factors extracted with seed=42<br/>",
            meta_cols,
            "Try the <b>Clinical Prediction</b> tab to impute missing IGHV/trisomy12 status!"
          )),
          type = "message",
          duration = 10
        )
        
      }, error = function(e) {
        showNotification(
          paste("Error loading CLL tutorial data:", e$message,
                ". Please ensure MOFA2 and MOFAdata packages are installed:",
                "BiocManager::install(c('MOFA2', 'MOFAdata'))"),
          type = "error",
          duration = 15
        )
      })
    })
  })
  
  # ============================================================================
  # DIABLO TCGA TUTORIAL INTEGRATION SERVER CODE
  # ============================================================================
  
  # Reactive values for tutorial state
  diablo_tutorial <- reactiveValues(
    active = FALSE,
    data = NULL,
    Y = NULL,
    is_tutorial = FALSE,
    design = NULL,
    basic_model = NULL,
    perf_result = NULL,
    ncomp = NULL,
    tune_result = NULL,
    keepX = NULL,
    final_model = NULL,
    perf_final = NULL,
    auroc_result = NULL,
    predictions = NULL,
    pls_models = NULL,
    selected_cell = NULL  # Store selected cell for table highlighting
  )
  
  # Load TCGA breast cancer data for tutorial
  observeEvent(input$load_tcga_tutorial, {
    tryCatch({
      # Ensure mixOmics package is loaded (required for breast.TCGA dataset)
      if (!require(mixOmics, quietly = TRUE)) {
        stop("mixOmics package is not installed. Please install from Bioconductor: BiocManager::install('mixOmics')")
      }
      
      # Load the TCGA breast cancer data (following the tutorial approach)
      data(breast.TCGA, envir = environment())

      # Prepare data list
      diablo_tutorial$data <- list(
        miRNA = breast.TCGA$data.train$mirna,
        mRNA = breast.TCGA$data.train$mrna,
        proteomics = breast.TCGA$data.train$protein
      )

      diablo_tutorial$Y <- breast.TCGA$data.train$subtype
      diablo_tutorial$active <- TRUE
      diablo_tutorial$is_tutorial <- TRUE

      # Create design matrix for tutorial (full integration design)
      diablo_tutorial$design <- matrix(1, nrow = 3, ncol = 3, 
                                       dimnames = list(names(diablo_tutorial$data), 
                                                       names(diablo_tutorial$data)))
      diag(diablo_tutorial$design) <- 0

      # Create basic DIABLO model automatically for tutorial
      tryCatch({
        diablo_tutorial$basic_model <- mixOmics::block.splsda(
          X = diablo_tutorial$data, 
          Y = diablo_tutorial$Y, 
          ncomp = 2,  # Default 2 components for tutorial
          design = diablo_tutorial$design
        )
        showNotification("Basic DIABLO model created for tutorial!", type = "message", duration = 3)
      }, error = function(e) {
        showNotification(paste("Error creating basic model for tutorial:", e$message), type = "error")
        diablo_tutorial$basic_model <- NULL
      })

      # Set sensible defaults for tutorial mode: use Overall.BER and centroids.dist
      tryCatch({
        updateSelectInput(session, "diablo_ncomp_metric", selected = "Overall.BER")
        updateSelectInput(session, "diablo_ncomp_dist", selected = "centroids.dist")
        updateSelectInput(session, "diablo_tune_validation", selected = "Mfold")
        updateSliderInput(session, "diablo_tune_folds", value = 10)
        updateSliderInput(session, "diablo_tune_nrepeat", value = 1)
        updateSelectInput(session, "diablo_tune_dist", selected = "centroids.dist")
      }, error = function(e) {})

      showNotification("TCGA breast cancer tutorial data loaded!", type = "message", duration = 4)
    }, error = function(e) {
      showNotification(
        paste("Error loading TCGA data:", e$message,
              ". The breast.TCGA dataset is available in the mixOmics package.",
              "Please ensure mixOmics is properly installed from Bioconductor: BiocManager::install('mixOmics')"),
        type = "error",
        duration = 10
      )
    })
  })
  
  # Step 1: Pairwise PLS analysis
  observeEvent(input$run_diablo_pls, {
    # Allow running PLS even if tutorial data not loaded: assemble data from uploaded analyses or manual datasets
    tryCatch({
      # Memory management: increase R memory limit on Windows and perform garbage collection
      if (.Platform$OS.type == "windows") {
        tryCatch({
          # Get current memory limit
          current_limit <- memory.limit()
          # Try to increase to 8GB if current is lower
          if (current_limit < 8000) {
            memory.limit(size = 8000)
            showNotification("Memory limit increased to 8GB for pairwise PLS computation.", type = "message", duration = 3)
          }
        }, error = function(e) {
          # memory.limit() may not work in all R versions, continue anyway
          cat("Could not adjust memory limit:", e$message, "\n")
        })
      }
      
      # Force garbage collection before starting heavy computation
      gc()
      
      # If tutorial data missing, try assembling from multiomics loaded analyses or manual uploads
      if (is.null(diablo_tutorial$data) || is.null(diablo_tutorial$Y)) {
        data_list <- list()
        sample_names_list <- list()

        # Prefer loaded analyses (saved analyses loaded into session)
        if (!is.null(multiomics$loaded_analyses) && length(multiomics$loaded_analyses) > 0) {
          # Use common_samples from previous processing when available
          preset_common <- multiomics$common_samples %||% NULL
          for (analysis_name in names(multiomics$loaded_analyses)) {
            analysis <- multiomics$loaded_analyses[[analysis_name]]
            raw_data <- analysis$data
            if (!is.null(raw_data) && (is.data.frame(raw_data) || is.matrix(raw_data))) {
              # Decide sample orientation: samples typically in columns for OMS inputs
              candidate_common <- preset_common %||% intersect(colnames(raw_data), rownames(raw_data))
              samples_in_cols <- length(candidate_common) > 0 && all(candidate_common %in% colnames(raw_data))
              samples_in_rows <- length(candidate_common) > 0 && all(candidate_common %in% rownames(raw_data))

              if (samples_in_cols) {
                common_samples <- candidate_common
                data_filtered <- raw_data[, common_samples, drop = FALSE]
                feature_names <- rownames(data_filtered)
                if (!is.null(analysis$cleaned_molecules) && length(analysis$cleaned_molecules) == nrow(data_filtered)) {
                  feature_names <- analysis$cleaned_molecules
                } else if (!is.null(analysis$accession_ids) && length(analysis$accession_ids) == nrow(data_filtered)) {
                  feature_names <- analysis$accession_ids
                } else if (!is.null(analysis$features) && length(analysis$features) == nrow(data_filtered)) {
                  feature_names <- analysis$features
                }
                data_matrix <- t(as.matrix(data_filtered))
                # Ensure feature names are unique (DIABLO requires unique column identifiers)
                colnames(data_matrix) <- make.unique(feature_names, sep = "_")
                rownames(data_matrix) <- common_samples
                data_list[[analysis_name]] <- data_matrix
                sample_names_list[[analysis_name]] <- common_samples
              } else if (samples_in_rows) {
                common_samples <- candidate_common
                data_filtered <- raw_data[common_samples, , drop = FALSE]
                data_matrix <- as.matrix(data_filtered)
                # Ensure feature names are unique (DIABLO requires unique column identifiers)
                if (any(duplicated(colnames(data_matrix)))) {
                  colnames(data_matrix) <- make.unique(colnames(data_matrix), sep = "_")
                }
                data_list[[analysis_name]] <- data_matrix
                sample_names_list[[analysis_name]] <- rownames(data_matrix)
              } else {
                # Fallback: treat rows as samples if no preset common samples
                data_matrix <- as.matrix(raw_data)
                data_list[[analysis_name]] <- data_matrix
                sample_names_list[[analysis_name]] <- rownames(data_matrix)
              }
            }
          }
        }

        # Fallback: use manual uploads if available
        if (length(data_list) < 2 && !is.null(multiomics$dataset1) && !is.null(multiomics$dataset2)) {
          req(multiomics$common_samples)
          common_samples <- multiomics$common_samples
          data1 <- multiomics$dataset1[, common_samples, drop = FALSE]
          data2 <- multiomics$dataset2[, common_samples, drop = FALSE]
          # Transpose and ensure unique feature names for DIABLO
          data1_t <- t(as.matrix(data1))
          colnames(data1_t) <- make.unique(rownames(multiomics$dataset1), sep = "_")
          data2_t <- t(as.matrix(data2))
          colnames(data2_t) <- make.unique(rownames(multiomics$dataset2), sep = "_")
          data_list <- list(
            Dataset1 = data1_t,
            Dataset2 = data2_t
          )
          if (!is.null(multiomics$dataset3)) {
            data3 <- multiomics$dataset3[, common_samples, drop = FALSE]
            data3_t <- t(as.matrix(data3))
            colnames(data3_t) <- make.unique(rownames(multiomics$dataset3), sep = "_")
            data_list$Dataset3 <- data3_t
          }
          sample_names_list <- lapply(data_list, rownames)
        }

        if (length(data_list) < 2) {
          showNotification("Need at least two datasets to run pairwise PLS. Please load or upload data.", type = "error")
          return(NULL)
        }

        # Determine common samples across prepared matrices
        common_samples <- Reduce(intersect, sample_names_list)
        if (length(common_samples) < 2) {
          showNotification(paste("Only", length(common_samples), "common samples found. Need at least 2."), type = "error")
          return(NULL)
        }

        # Subset data to common samples and ensure order
        for (i in seq_along(data_list)) {
          sample_order <- match(common_samples, rownames(data_list[[i]]))
          data_list[[i]] <- as.data.frame(data_list[[i]][sample_order, , drop = FALSE])
        }

        diablo_tutorial$data <- data_list
        diablo_tutorial$active <- TRUE
        diablo_tutorial$is_tutorial <- FALSE

        # Try to get grouping from sample metadata if available
        if (!is.null(input$diablo_group_var) && input$diablo_group_var != "" && !is.null(multiomics$sample_metadata) && input$diablo_group_var %in% colnames(multiomics$sample_metadata)) {
          group_col_idx <- match(input$diablo_group_var, colnames(multiomics$sample_metadata))
          Y <- factor(multiomics$sample_metadata[common_samples, group_col_idx])
          names(Y) <- common_samples
          diablo_tutorial$Y <- Y
        } else {
          # Create demo groups if no metadata grouping available
          n_samples <- length(common_samples)
          n_groups <- min(3, floor(n_samples / 2))
          if (n_groups < 2) n_groups <- 2
          Y <- factor(rep(paste0("Group_", 1:n_groups), length.out = n_samples))
          names(Y) <- common_samples
          diablo_tutorial$Y <- Y
          showNotification("No grouping variable found; using demo groupings.", type = "warning", duration = 4)
        }
      }

      # Set default design matrix for integration (can be modified later)
      diablo_tutorial$design <- matrix(1, ncol = length(diablo_tutorial$data), nrow = length(diablo_tutorial$data))

      # Set seed for reproducible results in tutorial or real-data manual run
      if (isTRUE(diablo_tutorial$active)) set.seed(123)

      # Use UI controls for pairwise PLS (features to keep)
      keepX_val <- as.integer(input$diablo_pls_keepX %||% 25)
      keepY_val <- as.integer(input$diablo_pls_keepY %||% 25)

      # Default number of components: use global DIABLO ncomp slider if present, otherwise 2
      ncomp_default <- as.integer(input$diablo_ncomp %||% 2)

      # Helper to safely run spls with bounds checking on ncomp and memory management
      run_safe_spls <- function(X, Y) {
        max_comp <- min(ncol(X), ncol(Y))
        ncomp_pair <- max(1, min(ncomp_default, max_comp))
        list.keepX <- rep(keepX_val, ncomp_pair)
        list.keepY <- rep(keepY_val, ncomp_pair)
        
        # Force garbage collection before SPLS computation
        gc()
        
        result <- mixOmics::spls(X, Y, keepX = list.keepX, keepY = list.keepY, ncomp = ncomp_pair)
        
        # Clean up and garbage collect after computation
        gc()
        
        return(result)
      }

      # Run pairwise PLS models dynamically from available block names
      data_names <- names(diablo_tutorial$data)
      pairs <- combn(data_names, 2, simplify = FALSE)
      pls_models <- list()
      pair_map <- character(0)

      for (i in seq_along(pairs)) {
        pair <- pairs[[i]]
        # sanitized key: lowercase alnum with underscore
        sanitize <- function(x) gsub("[^[:alnum:]]", "", tolower(x))
        model_key <- paste0(sanitize(pair[1]), "_", sanitize(pair[2]))
        pls_models[[model_key]] <- run_safe_spls(diablo_tutorial$data[[pair[1]]], diablo_tutorial$data[[pair[2]]])
        display_name <- paste(pair[1], "vs", pair[2])
        pair_map[display_name] <- model_key
      }

      diablo_tutorial$pls_models <- pls_models
      diablo_tutorial$pls_pair_map <- pair_map

      # Update pair selector with available pairs
      pair_choices <- names(pair_map)
      updateSelectInput(session, "diablo_pls_pair", 
                        choices = pair_choices,
                        selected = pair_choices[1])

      # Set pairs for downloads (use the underlying model keys)
      keys <- unname(pair_map)
      diablo_tutorial$pls_results <- list(
        pair1 = keys[1],
        pair2 = keys[min(2, length(keys))]
      )

      # Set integration results so the Integration Results tab can use them
      multiomics$integration_results <- list(
        method = "diablo",
        message = "DIABLO integration completed using pairwise PLS correlations",
        pls_models = diablo_tutorial$pls_models
      )

      # Final garbage collection
      gc()
      
      showNotification("Pairwise PLS models computed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in pairwise PLS:", e$message), type = "error")
    })
  })
  
  # Automatic pairwise PLS for real data integration
  observe({
    req(diablo_tutorial$data, diablo_tutorial$Y)
    
    # Skip if already processed or if this is tutorial data
    if (is.null(diablo_tutorial$pls_models) && !diablo_tutorial$is_tutorial) {
      # Set flags for real data
      diablo_tutorial$active <- TRUE
      diablo_tutorial$is_tutorial <- FALSE
      
      # Set default design matrix if not already set
      if (is.null(diablo_tutorial$design)) {
        diablo_tutorial$design <- matrix(1, ncol = length(diablo_tutorial$data), nrow = length(diablo_tutorial$data))
      }
      
      tryCatch({
        # Set seed for reproducible results
        set.seed(123)
        
        # Use UI controls for pairwise PLS (features to keep)
        keepX_val <- as.integer(input$diablo_pls_keepX %||% 25)
        keepY_val <- as.integer(input$diablo_pls_keepY %||% 25)
        
        # Default number of components: use global DIABLO ncomp slider if present, otherwise 2
        ncomp_default <- as.integer(input$diablo_ncomp %||% 2)
        
        # Helper to safely run spls with bounds checking on ncomp
        run_safe_spls <- function(X, Y) {
          max_comp <- min(ncol(X), ncol(Y))
          ncomp_pair <- max(1, min(ncomp_default, max_comp))
          list.keepX <- rep(keepX_val, ncomp_pair)
          list.keepY <- rep(keepY_val, ncomp_pair)
          mixOmics::spls(X, Y, keepX = list.keepX, keepY = list.keepY, ncomp = ncomp_pair)
        }
        
        # Get all pairs of datasets
        data_names <- names(diablo_tutorial$data)
        if (length(data_names) >= 2) {
          pairs <- combn(data_names, 2, simplify = FALSE)
          
          pls_models <- list()
          pair_map <- character(0)
          sanitize <- function(x) gsub("[^[:alnum:]]", "", tolower(x))

          for (i in seq_along(pairs)) {
            pair <- pairs[[i]]
            model_key <- paste0(sanitize(pair[1]), "_", sanitize(pair[2]))
            pls_models[[model_key]] <- run_safe_spls(diablo_tutorial$data[[pair[1]]], diablo_tutorial$data[[pair[2]]])
            display_name <- paste(pair[1], "vs", pair[2])
            pair_map[display_name] <- model_key
          }
          
          diablo_tutorial$pls_models <- pls_models
          diablo_tutorial$pls_pair_map <- pair_map
          
          # Update pair selector with available pairs
          pair_choices <- names(pair_map)
          updateSelectInput(session, "diablo_pls_pair", 
                            choices = pair_choices,
                            selected = pair_choices[1])

          # Set pairs for downloads
          keys <- unname(pair_map)
          diablo_tutorial$pls_results <- list(pair1 = keys[1], pair2 = keys[min(2, length(keys))])

          # Set integration results for the Integration Results tab
          multiomics$integration_results <- list(
            method = "diablo",
            message = "DIABLO integration completed using pairwise PLS correlations",
            pls_models = pls_models
          )
          
          showNotification("Pairwise PLS models computed for real data!", type = "message", duration = 3)
        }
      }, error = function(e) {
        showNotification(paste("Error in pairwise PLS for real data:", e$message), type = "error")
      })
    }
  })
  
  # Step 2: Create design matrix (and run basic DIABLO model for real data)
  observeEvent(input$create_diablo_design, {
    # Work for both tutorial and real data
    # Check if user has real data loaded - if so, prioritize real data over tutorial
    data_loaded_count <- sum(as.numeric(sapply(multiomics$loaded_analyses, function(x) !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data)))))
    has_loaded <- data_loaded_count >= 2
    has_manual <- !is.null(multiomics$dataset1) && !is.null(multiomics$dataset2)
    
    # If user has real data loaded, automatically switch out of tutorial mode
    if ((has_loaded || has_manual) && diablo_tutorial$active) {
      cat("[create_diablo_design] User has real data loaded - switching from tutorial mode to real data mode\n")
      diablo_tutorial$active <- FALSE
      showNotification("Switching from tutorial mode to real data mode.", type = "message", duration = 3)
    }
    
    if (diablo_tutorial$active) {
      req(diablo_tutorial$data)
      data_blocks <- diablo_tutorial$data
      is_tutorial <- TRUE
      Y_vec <- diablo_tutorial$Y
      ncomp_val <- input$diablo_perf_ncomp %||% 2
    } else {
      # Real data mode - set up data if not already done
      cat("[create_diablo_design] Real data mode\n")
      cat("  Loaded analyses with data:", data_loaded_count, "\n")
      cat("  has_loaded (>=2):", has_loaded, ", has_manual:", has_manual, "\n")
      
      if (!has_loaded && !has_manual) {
        showNotification(
          "Please load saved analyses or manually upload at least 2 datasets",
          type = "error"
        )
        return()
      }
      
      # Helper function to ensure unique feature names in a data block
      ensure_unique_features <- function(data_matrix, block_name) {
        if (any(duplicated(colnames(data_matrix)))) {
          n_dups <- sum(duplicated(colnames(data_matrix)))
          cat("  [DIABLO] Making", n_dups, "duplicate feature names unique in", block_name, "\n")
          colnames(data_matrix) <- make.unique(colnames(data_matrix), sep = "_")
        }
        return(data_matrix)
      }
      
      # Prepare data from loaded analyses or manual uploads
      if (has_loaded) {
        # Require common samples for DIABLO
        if (is.null(multiomics$common_samples) || length(multiomics$common_samples) == 0) {
          showNotification(
            "Common samples not found. Please ensure loaded analyses share sample IDs.",
            type = "error",
            duration = 10
          )
          return()
        }
        
        # Use loaded saved analyses
        data_list <- list()
        dataset_names <- names(multiomics$loaded_analyses)[sapply(multiomics$loaded_analyses, function(x) !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data)))]
        if (length(dataset_names) < 2) {
          showNotification("Not enough loaded datasets with data available for integration.", type = "error", duration = 8)
          return()
        }
        
        common_samples <- multiomics$common_samples
        
        for (i in seq_along(dataset_names)) {
          name <- dataset_names[i]
          analysis <- multiomics$loaded_analyses[[name]]
          raw_data <- analysis$data
          
          # Determine data orientation: OMS files typically store features in rows, samples in columns
          samples_in_cols <- all(common_samples %in% colnames(raw_data))
          samples_in_rows <- all(common_samples %in% rownames(raw_data))
          
          if (samples_in_cols) {
            # Features are rows, samples are columns (typical OMS format)
            data_filtered <- raw_data[, common_samples, drop = FALSE]
            # Get feature names
            feature_names <- rownames(data_filtered)
            if (!is.null(analysis$cleaned_molecules) && length(analysis$cleaned_molecules) == nrow(data_filtered)) {
              feature_names <- analysis$cleaned_molecules
            } else if (!is.null(analysis$accession_ids) && length(analysis$accession_ids) == nrow(data_filtered)) {
              feature_names <- analysis$accession_ids
            } else if (!is.null(analysis$features) && length(analysis$features) == nrow(data_filtered)) {
              feature_names <- analysis$features
            }
            # Transpose to samples × features format for DIABLO
            data_matrix <- t(as.matrix(data_filtered))
            # Ensure feature names are unique (DIABLO requires unique column identifiers)
            colnames(data_matrix) <- make.unique(feature_names, sep = "_")
            rownames(data_matrix) <- common_samples
            data_list[[name]] <- data_matrix
          } else if (samples_in_rows) {
            # Samples are rows, features are columns (already in DIABLO format)
            data_filtered <- raw_data[common_samples, , drop = FALSE]
            data_matrix <- as.matrix(data_filtered)
            # Ensure feature names are unique (DIABLO requires unique column identifiers)
            if (any(duplicated(colnames(data_matrix)))) {
              colnames(data_matrix) <- make.unique(colnames(data_matrix), sep = "_")
            }
            data_list[[name]] <- data_matrix
          } else {
            showNotification(
              paste("Error: Dataset", name, "does not contain required sample IDs."),
              type = "error"
            )
            return()
          }
        }
        
      } else {
        # Use manual uploads (features in rows, samples in columns)
        req(multiomics$dataset1, multiomics$dataset2, multiomics$common_samples)
        common_samples <- multiomics$common_samples
        
        # Filter datasets to common samples and transpose to samples × features
        data1 <- multiomics$dataset1[, common_samples, drop = FALSE]
        data1_t <- t(as.matrix(data1))
        rownames(data1_t) <- common_samples
        data1_t <- ensure_unique_features(data1_t, "Dataset1")
        if (is.null(colnames(data1_t))) colnames(data1_t) <- make.unique(rownames(multiomics$dataset1), sep = "_")
        
        data2 <- multiomics$dataset2[, common_samples, drop = FALSE]
        data2_t <- t(as.matrix(data2))
        rownames(data2_t) <- common_samples
        data2_t <- ensure_unique_features(data2_t, "Dataset2")
        if (is.null(colnames(data2_t))) colnames(data2_t) <- make.unique(rownames(multiomics$dataset2), sep = "_")
        
        if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
          data3 <- multiomics$dataset3[, common_samples, drop = FALSE]
          data3_t <- t(as.matrix(data3))
          rownames(data3_t) <- common_samples
          data3_t <- ensure_unique_features(data3_t, "Dataset3")
          if (is.null(colnames(data3_t))) colnames(data3_t) <- make.unique(rownames(multiomics$dataset3), sep = "_")
          data_list <- list(Dataset1 = data1_t, Dataset2 = data2_t, Dataset3 = data3_t)
        } else {
          data_list <- list(Dataset1 = data1_t, Dataset2 = data2_t)
        }
      }
      
      # Validate data is numeric
      data_validation <- sapply(data_list, function(x) {
        if (!is.matrix(x) && !is.data.frame(x)) return(FALSE)
        return(all(sapply(x, function(col) is.numeric(col) || is.integer(col))))
      })
      
      if (!all(data_validation)) {
        non_numeric_datasets <- names(data_list)[!data_validation]
        showNotification(
          paste0("Error: Datasets must contain only numeric data. Non-numeric data found in: ",
                 paste(non_numeric_datasets, collapse = ", ")),
          type = "error",
          duration = 10
        )
        return()
      }
      
      # Convert data frames to matrices if needed
      data_list <- lapply(data_list, function(x) {
        if (is.data.frame(x)) return(as.matrix(x))
        return(x)
      })
      
      # Get Y vector from group variable
      if (is.null(input$diablo_group_var) || input$diablo_group_var == "") {
        showNotification("Please select a group variable for DIABLO analysis.", type = "error")
        return()
      }
      
      # Get sample metadata and align Y vector with common_samples order
      group_var <- input$diablo_group_var
      
      # Get the sample ID column from metadata
      sample_id_col <- NULL
      metadata_sample_ids <- NULL
      
      if (!is.null(multiomics$sample_metadata)) {
        if ("SampleID" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "SampleID"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if ("Sample_ID" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "Sample_ID"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if ("sample" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "sample"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if (!is.null(rownames(multiomics$sample_metadata)) && 
                   !all(rownames(multiomics$sample_metadata) == as.character(seq_len(nrow(multiomics$sample_metadata))))) {
          metadata_sample_ids <- rownames(multiomics$sample_metadata)
        } else {
          sample_id_col <- colnames(multiomics$sample_metadata)[1]
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        }
      }
      
      if (group_var == "auto") {
        if (!is.null(multiomics$sample_groups) && length(unique(multiomics$sample_groups)) > 1) {
          if (!is.null(names(multiomics$sample_groups))) {
            Y_vec <- factor(multiomics$sample_groups[common_samples])
          } else {
            Y_vec <- factor(multiomics$sample_groups)
          }
        } else {
          showNotification("No suitable grouping variable found. Please upload sample metadata with group information.", type = "error")
          return()
        }
      } else {
        if (!is.null(multiomics$sample_metadata) && group_var %in% colnames(multiomics$sample_metadata)) {
          group_values <- multiomics$sample_metadata[[group_var]]
          
          if (!is.null(metadata_sample_ids)) {
            group_mapping <- setNames(as.character(group_values), as.character(metadata_sample_ids))
            aligned_groups <- group_mapping[common_samples]
            
            if (any(is.na(aligned_groups))) {
              n_unmatched <- sum(is.na(aligned_groups))
              showNotification(
                paste("Warning:", n_unmatched, "samples not found in metadata. Check sample ID matching."),
                type = "warning",
                duration = 8
              )
            }
            
            Y_vec <- factor(aligned_groups)
          } else {
            Y_vec <- factor(group_values)
          }
        } else {
          showNotification("Selected group variable not found in metadata.", type = "error")
          return()
        }
      }
      
      # Validate Y vector length
      n_samples <- nrow(data_list[[1]])
      if (length(Y_vec) != n_samples) {
        showNotification(
          paste("Error: Y vector length (", length(Y_vec), ") does not match number of samples (", n_samples, ")"),
          type = "error"
        )
        return()
      }
      
      data_blocks <- data_list
      ncomp_val <- input$diablo_perf_ncomp %||% 2
      is_tutorial <- FALSE
      
      # Debug output
      cat("DIABLO Create Design - data preparation:\n")
      cat("  Common samples:", length(common_samples), "\n")
      cat("  Y vector levels:", paste(levels(Y_vec), collapse = ", "), "\n")
      for (nm in names(data_blocks)) {
        cat("  Block", nm, ":", nrow(data_blocks[[nm]]), "samples x", ncol(data_blocks[[nm]]), "features\n")
        cat("    First 5 features:", paste(head(colnames(data_blocks[[nm]]), 5), collapse = ", "), "\n")
      }
    }
    
    tryCatch({
      design <- matrix(input$diablo_design_value, ncol = length(data_blocks), 
                      nrow = length(data_blocks),
                      dimnames = list(names(data_blocks), names(data_blocks)))
      
      if (input$diablo_design_diagonal_zero) {
        diag(design) <- 0
      }
      
      if (is_tutorial) {
        diablo_tutorial$design <- design
        # Clear cached models so perf() rebuilds with the updated design
        diablo_tutorial$basic_model <- NULL
        diablo_tutorial$perf_result <- NULL
        diablo_tutorial$perf_final <- NULL
        showNotification("Design matrix created successfully!", type = "message", duration = 3)
      } else {
        # Real data mode: store data, Y, design and run basic DIABLO model
        # Initialize or update integration_results
        multiomics$integration_results <- list(
          method = "diablo",
          data = data_blocks,
          Y = Y_vec,
          design = design,
          ncomp = ncomp_val,
          basic_model = NULL,
          perf_result = NULL,
          perf_final = NULL
        )
        
        # Automatically create basic DIABLO model with updated design
        showNotification("Design matrix created. Building basic DIABLO model...", type = "message", duration = 2)
        
        tryCatch({
          basic_model <- mixOmics::block.splsda(
            X = data_blocks,
            Y = Y_vec,
            ncomp = ncomp_val,
            design = design
          )
          
          if (is.null(basic_model) || length(basic_model) == 0) {
            showNotification("Failed to create DIABLO model", type = "error")
            return()
          }
          
          multiomics$integration_results$basic_model <- basic_model
          showNotification("Design matrix created and basic DIABLO model built successfully! You can now run performance evaluation.", type = "message", duration = 4)
        }, error = function(e) {
          showNotification(paste("Error creating basic DIABLO model:", e$message), type = "error")
        })
      }
    }, error = function(e) {
      showNotification(paste("Error creating design matrix:", e$message), type = "error")
    })
  })
  
  # Step 3: Run basic DIABLO model
  observeEvent(input$run_basic_diablo, {
    req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design)
    
    tryCatch({
      diablo_tutorial$basic_model <- mixOmics::block.splsda(
        X = diablo_tutorial$data, 
        Y = diablo_tutorial$Y, 
        ncomp = input$basic_ncomp, 
        design = diablo_tutorial$design
      )
      
      showNotification("Basic DIABLO model created successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in basic DIABLO model:", e$message), type = "error")
    })
  })
  
  # Initial Model: Run performance evaluation
  observeEvent(input$run_diablo_perf, {
    cat("\n========== [run_diablo_perf] Button clicked ==========\n")
    cat("  diablo_tutorial$active:", isTRUE(diablo_tutorial$active), "\n")
    
    # Support both tutorial and real data
    # Check if user has real data loaded - if so, prioritize real data over tutorial
    data_loaded_count <- sum(as.numeric(sapply(multiomics$loaded_analyses, function(x) !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data)))))
    has_loaded <- data_loaded_count >= 2
    has_manual <- !is.null(multiomics$dataset1) && !is.null(multiomics$dataset2)
    
    # If user has real data loaded, automatically switch out of tutorial mode
    if ((has_loaded || has_manual) && diablo_tutorial$active) {
      cat("  User has real data loaded - switching from tutorial mode to real data mode\n")
      diablo_tutorial$active <- FALSE
      showNotification("Switching from tutorial mode to real data mode.", type = "message", duration = 3)
    }
    
    if (diablo_tutorial$active) {
      cat("  Mode: TUTORIAL\n")
      req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design)
      data_list <- diablo_tutorial$data
      Y_vec <- diablo_tutorial$Y
      design_mat <- diablo_tutorial$design
      ncomp_val <- input$diablo_perf_ncomp
      is_tutorial_mode <- TRUE
      basic_model <- diablo_tutorial$basic_model
    } else {
      cat("  Mode: REAL DATA\n")
      # Real data mode - set up data if not already done
      cat("  Loaded analyses with data:", data_loaded_count, "\n")
      cat("  has_loaded (>=2):", has_loaded, ", has_manual:", has_manual, "\n")
      
      if (!has_loaded && !has_manual) {
        cat("  ERROR: No datasets available - exiting\n")
        showNotification(
          "Please load saved analyses or manually upload at least 2 datasets",
          type = "error"
        )
        return()
      }
      
      # Helper function to ensure unique feature names in a data block
      ensure_unique_features <- function(data_matrix, block_name) {
        if (any(duplicated(colnames(data_matrix)))) {
          n_dups <- sum(duplicated(colnames(data_matrix)))
          cat("  [DIABLO PERF] Making", n_dups, "duplicate feature names unique in", block_name, "\n")
          colnames(data_matrix) <- make.unique(colnames(data_matrix), sep = "_")
        }
        return(data_matrix)
      }
      
      # Prepare data from loaded analyses or manual uploads
      if (has_loaded) {
        cat("  Using LOADED analyses path\n")
        # Require common samples for DIABLO
        if (is.null(multiomics$common_samples) || length(multiomics$common_samples) == 0) {
          showNotification(
            "Common samples not found. Please ensure loaded analyses share sample IDs.",
            type = "error",
            duration = 10
          )
          return()
        }
        
        # Use loaded saved analyses
        data_list <- list()
        dataset_names <- names(multiomics$loaded_analyses)[sapply(multiomics$loaded_analyses, function(x) !is.null(x$data) && (is.data.frame(x$data) || is.matrix(x$data)))]
        if (length(dataset_names) < 2) {
          showNotification("Not enough loaded datasets with data available for integration.", type = "error", duration = 8)
          return()
        }
        
        common_samples <- multiomics$common_samples
        
        for (i in seq_along(dataset_names)) {
          name <- dataset_names[i]
          analysis <- multiomics$loaded_analyses[[name]]
          raw_data <- analysis$data
          
          # Determine data orientation: OMS files typically store features in rows, samples in columns
          # We need to identify which dimension represents samples
          samples_in_cols <- all(common_samples %in% colnames(raw_data))
          samples_in_rows <- all(common_samples %in% rownames(raw_data))
          
          if (samples_in_cols) {
            # Features are rows, samples are columns (typical OMS format)
            # Filter to common samples and transpose to get samples × features
            data_filtered <- raw_data[, common_samples, drop = FALSE]
            # Get feature names from original row names or cleaned_molecules/accession_ids
            feature_names <- rownames(data_filtered)
            if (!is.null(analysis$cleaned_molecules) && length(analysis$cleaned_molecules) == nrow(data_filtered)) {
              feature_names <- analysis$cleaned_molecules
            } else if (!is.null(analysis$accession_ids) && length(analysis$accession_ids) == nrow(data_filtered)) {
              feature_names <- analysis$accession_ids
            } else if (!is.null(analysis$features) && length(analysis$features) == nrow(data_filtered)) {
              feature_names <- analysis$features
            }
            # Transpose to samples × features format for DIABLO
            data_matrix <- t(as.matrix(data_filtered))
            # Ensure feature names are unique (DIABLO requires unique column identifiers)
            colnames(data_matrix) <- make.unique(feature_names, sep = "_")
            rownames(data_matrix) <- common_samples
            data_list[[name]] <- data_matrix
          } else if (samples_in_rows) {
            # Samples are rows, features are columns (already in DIABLO format)
            data_filtered <- raw_data[common_samples, , drop = FALSE]
            data_matrix <- as.matrix(data_filtered)
            # Ensure feature names are unique (DIABLO requires unique column identifiers)
            if (any(duplicated(colnames(data_matrix)))) {
              colnames(data_matrix) <- make.unique(colnames(data_matrix), sep = "_")
            }
            data_list[[name]] <- data_matrix
          } else {
            showNotification(
              paste("Error: Dataset", name, "does not contain required sample IDs in rows or columns."),
              type = "error"
            )
            return()
          }
        }
        
      } else {
        # Use manual uploads (features in rows, samples in columns)
        req(multiomics$dataset1, multiomics$dataset2, multiomics$common_samples)
        common_samples <- multiomics$common_samples
        
        # Filter datasets to common samples and transpose to samples × features
        data1 <- multiomics$dataset1[, common_samples, drop = FALSE]
        data1_t <- t(as.matrix(data1))
        rownames(data1_t) <- common_samples
        # Ensure unique feature names (DIABLO requires unique column identifiers)
        colnames(data1_t) <- make.unique(rownames(multiomics$dataset1), sep = "_")
        data1_t <- ensure_unique_features(data1_t, "Dataset1")
        
        data2 <- multiomics$dataset2[, common_samples, drop = FALSE]
        data2_t <- t(as.matrix(data2))
        rownames(data2_t) <- common_samples
        # Ensure unique feature names (DIABLO requires unique column identifiers)
        colnames(data2_t) <- make.unique(rownames(multiomics$dataset2), sep = "_")
        data2_t <- ensure_unique_features(data2_t, "Dataset2")
        
        if (!is.null(multiomics$dataset3) && input$enable_dataset3) {
          data3 <- multiomics$dataset3[, common_samples, drop = FALSE]
          data3_t <- t(as.matrix(data3))
          rownames(data3_t) <- common_samples
          # Ensure unique feature names (DIABLO requires unique column identifiers)
          colnames(data3_t) <- make.unique(rownames(multiomics$dataset3), sep = "_")
          data3_t <- ensure_unique_features(data3_t, "Dataset3")
          data_list <- list(Dataset1 = data1_t, Dataset2 = data2_t, Dataset3 = data3_t)
        } else {
          data_list <- list(Dataset1 = data1_t, Dataset2 = data2_t)
        }
      }
      
      # Validate data is numeric
      data_validation <- sapply(data_list, function(x) {
        if (!is.matrix(x) && !is.data.frame(x)) return(FALSE)
        return(all(sapply(x, function(col) is.numeric(col) || is.integer(col))))
      })
      
      if (!all(data_validation)) {
        non_numeric_datasets <- names(data_list)[!data_validation]
        showNotification(
          paste0("Error: Datasets must contain only numeric data. Non-numeric data found in: ",
                 paste(non_numeric_datasets, collapse = ", ")),
          type = "error",
          duration = 10
        )
        return()
      }
      
      # Convert data frames to matrices if needed
      data_list <- lapply(data_list, function(x) {
        if (is.data.frame(x)) return(as.matrix(x))
        return(x)
      })
      
      # Get Y vector from group variable
      if (is.null(input$diablo_group_var) || input$diablo_group_var == "") {
        showNotification("Please select a group variable for DIABLO analysis.", type = "error")
        return()
      }
      
      # Get sample metadata and align Y vector with common_samples order
      group_var <- input$diablo_group_var
      cat("  Selected group variable:", group_var, "\n")
      cat("  Has sample_metadata:", !is.null(multiomics$sample_metadata), "\n")
      
      # Get the sample ID column from metadata (typically 'SampleID' or first column or rownames)
      sample_id_col <- NULL
      metadata_sample_ids <- NULL
      
      if (!is.null(multiomics$sample_metadata)) {
        cat("  sample_metadata columns:", paste(colnames(multiomics$sample_metadata), collapse = ", "), "\n")
        # Try different methods to get sample IDs from metadata
        if ("SampleID" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "SampleID"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if ("Sample_ID" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "Sample_ID"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if ("sample" %in% colnames(multiomics$sample_metadata)) {
          sample_id_col <- "sample"
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        } else if (!is.null(rownames(multiomics$sample_metadata)) && 
                   !all(rownames(multiomics$sample_metadata) == as.character(seq_len(nrow(multiomics$sample_metadata))))) {
          # Use row names if they're not just row numbers
          metadata_sample_ids <- rownames(multiomics$sample_metadata)
        } else {
          # Use first column as sample ID
          sample_id_col <- colnames(multiomics$sample_metadata)[1]
          metadata_sample_ids <- multiomics$sample_metadata[[sample_id_col]]
        }
        cat("  Using sample_id_col:", sample_id_col %||% "(rownames)", "\n")
        cat("  First 5 metadata sample IDs:", paste(head(metadata_sample_ids, 5), collapse = ", "), "\n")
      }
      
      if (group_var == "auto") {
        cat("  Using AUTO group detection\n")
        # Try to find a suitable grouping variable
        if (!is.null(multiomics$sample_groups) && length(unique(multiomics$sample_groups)) > 1) {
          # sample_groups should be named vector or aligned with samples
          if (!is.null(names(multiomics$sample_groups))) {
            # Named vector - align to common_samples order
            Y_vec <- factor(multiomics$sample_groups[common_samples])
          } else {
            # Assume already aligned
            Y_vec <- factor(multiomics$sample_groups)
          }
        } else {
          showNotification("No suitable grouping variable found. Please upload sample metadata with group information.", type = "error")
          return()
        }
      } else {
        # Use selected group variable from metadata
        if (!is.null(multiomics$sample_metadata) && group_var %in% colnames(multiomics$sample_metadata)) {
          # Create a mapping from sample IDs to group values
          group_values <- multiomics$sample_metadata[[group_var]]
          
          if (!is.null(metadata_sample_ids)) {
            # Create named vector for alignment
            group_mapping <- setNames(as.character(group_values), as.character(metadata_sample_ids))
            
            # Align Y vector to common_samples order
            aligned_groups <- group_mapping[common_samples]
            
            # Check for unmatched samples
            if (any(is.na(aligned_groups))) {
              n_unmatched <- sum(is.na(aligned_groups))
              showNotification(
                paste("Warning:", n_unmatched, "samples not found in metadata. Please check sample ID matching."),
                type = "warning",
                duration = 8
              )
            }
            
            Y_vec <- factor(aligned_groups)
          } else {
            # Fallback - assume metadata rows are in same order as samples
            Y_vec <- factor(group_values)
          }
        } else {
          showNotification("Selected group variable not found in metadata.", type = "error")
          return()
        }
      }
      
      # Validate Y vector length matches sample count
      n_samples <- nrow(data_list[[1]])
      if (length(Y_vec) != n_samples) {
        showNotification(
          paste("Error: Y vector length (", length(Y_vec), ") does not match number of samples (", n_samples, ")"),
          type = "error"
        )
        return()
      }
      
      # Debug output
      cat("DIABLO data preparation:\n")
      cat("  Common samples:", length(common_samples), "\n")
      cat("  Y vector levels:", paste(levels(Y_vec), collapse = ", "), "\n")
      cat("  Y vector length:", length(Y_vec), "\n")
      for (nm in names(data_list)) {
        cat("  Block", nm, "dimensions:", nrow(data_list[[nm]]), "samples x", ncol(data_list[[nm]]), "features\n")
        cat("    First 5 features:", paste(head(colnames(data_list[[nm]]), 5), collapse = ", "), "\n")
      }
      
      # Get design matrix
      design_mat <- NULL
      if (!is.null(multiomics$integration_results) && !is.null(multiomics$integration_results$design)) {
        design_mat <- multiomics$integration_results$design
      }
      
      # If no design is present, create a safe default
      if (is.null(design_mat)) {
        n_blocks <- length(data_list)
        if (n_blocks < 2) {
          showNotification("DIABLO design requires at least two data blocks.", type = "error")
          return(NULL)
        }
        design_mat <- matrix(1, nrow = n_blocks, ncol = n_blocks, dimnames = list(names(data_list), names(data_list)))
        diag(design_mat) <- 0
        showNotification("No design matrix found. Using default (off-diagonal = 1, diagonal = 0). Use 'Create Design Matrix' to override.", type = "warning", duration = 8)
      }
      
      ncomp_val <- input$diablo_perf_ncomp
      is_tutorial_mode <- FALSE
      basic_model <- if (!is.null(multiomics$integration_results)) multiomics$integration_results$basic_model else NULL
    }

    tryCatch({
      # Scoped logger writes to console and a debug file for Shiny sessions where console is hidden
      log_file <- "diablo_perf_debug.log"
      log_msg <- function(...) {
        msg <- paste0("[", format(Sys.time(), "%Y-%m-%d %H:%M:%S"), "] [DIABLO PERF] ", paste(..., collapse = ""), "\n")
        cat(msg)
        flush.console()
        try(write(msg, file = log_file, append = TRUE), silent = TRUE)
      }

      # Debug: log inputs before model/perf
      log_msg("mode=", if (is_tutorial_mode) "tutorial" else "real")
      log_msg("data blocks=", paste(names(data_list), collapse = ","))
      log_msg("data dims=", paste(sapply(data_list, function(x) paste(dim(x), collapse = "x")), collapse = ";"))
      log_msg("Y length=", length(Y_vec), " levels=", length(levels(Y_vec)))
      log_msg("design dim=", paste(dim(design_mat), collapse = "x"), " diag sum=", sum(diag(design_mat)))
      log_msg("ncomp=", ncomp_val)

      withProgress(message = 'Creating initial DIABLO model and evaluating performance...', {
        # First create basic DIABLO model if not exists
        if (is.null(basic_model)) {
          showNotification("Creating DIABLO model...", type = "message", duration = 2)
          basic_model <- mixOmics::block.splsda(
            X = data_list,
            Y = Y_vec,
            ncomp = ncomp_val,
            design = design_mat
          )
          
          if (is.null(basic_model) || length(basic_model) == 0) {
            showNotification("Failed to create DIABLO model", type = "error")
            return(NULL)
          }
          
          showNotification("DIABLO model created successfully", type = "message", duration = 2)
          log_msg("basic_model class=", paste(class(basic_model), collapse = ","), " names=", paste(names(basic_model), collapse = ","))
        }

        # Store basic model back to the appropriate place
        if (is_tutorial_mode) {
          diablo_tutorial$basic_model <- basic_model
        } else {
          # Initialize integration_results if it doesn't exist
          if (is.null(multiomics$integration_results)) {
            multiomics$integration_results <- list(
              method = "diablo",
              data = data_list,
              Y = Y_vec,
              design = design_mat,
              ncomp = ncomp_val
            )
          }
          multiomics$integration_results$basic_model <- basic_model
        }

        # Capture reactive values in main thread before parallel processing
        perf_validation <- input$diablo_perf_validation
        perf_folds <- input$diablo_perf_folds
        perf_nrepeat <- input$diablo_perf_nrepeat

        showNotification("Running performance evaluation...", type = "message", duration = 2)
        log_msg("perf args: validation=", perf_validation, " folds=", perf_folds, " nrepeat=", perf_nrepeat)
        # Run performance evaluation
        if (isTRUE(diablo_tutorial$is_tutorial)) {
          set.seed(123)
          BPPARAM <- BiocParallel::SnowParam(workers = max(1, parallel::detectCores() - 1), stop.on.error = FALSE)
          perf_result <- mixOmics::perf(
            basic_model,
            validation = perf_validation,
            folds = perf_folds,
            nrepeat = perf_nrepeat,
            BPPARAM = BPPARAM
          )
        } else {
          # For real data, run without parallel processing to avoid potential issues
          perf_result <- mixOmics::perf(
            basic_model,
            validation = perf_validation,
            folds = perf_folds,
            nrepeat = perf_nrepeat
          )
        }

        # Check if perf_result is valid
        if (is.null(perf_result) || length(perf_result) == 0) {
          showNotification("Performance evaluation failed - no results returned", type = "error")
          return(NULL)
        }

        # Ensure perf_result has the correct class for plotting
        if (!inherits(perf_result, "perf")) {
          class(perf_result) <- c("perf", class(perf_result))
        }

        # Debug: log perf_result structure
        log_msg("perf_result class=", paste(class(perf_result), collapse = ","), " names=", paste(names(perf_result), collapse = ","))
        if (!is.null(perf_result$choice.ncomp)) {
          log_msg("choice.ncomp blocks=", paste(names(perf_result$choice.ncomp), collapse = ","))
        }
        if (!is.null(perf_result$error.rate)) {
          log_msg("error.rate slots=", paste(names(perf_result$error.rate), collapse = ","))
        }

        # Debug: check perf_result structure
        if (!is.null(perf_result$choice.ncomp)) {
          showNotification("Performance evaluation successful - found choice.ncomp", type = "message", duration = 2)
        } else {
          showNotification(paste("Performance evaluation completed but missing choice.ncomp. Available components:", paste(names(perf_result), collapse = ", ")), type = "warning", duration = 10)
        }

        # Store perf results
        if (is_tutorial_mode) {
          diablo_tutorial$perf_result <- perf_result
        } else {
          multiomics$integration_results$perf_result <- perf_result
        }
      })

      showNotification("Initial model performance evaluation completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in performance evaluation:", e$message), type = "error")
    })
  })
  

  
  # Run Feature Selection Tuning
  observeEvent(input$run_feature_tuning, {
    # Support both tutorial and real data
    if (diablo_tutorial$active) {
      req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design, diablo_tutorial$ncomp)
      data_list <- diablo_tutorial$data
      Y_vec <- diablo_tutorial$Y
      design_mat <- diablo_tutorial$design
      ncomp_val <- diablo_tutorial$ncomp
      is_tutorial_mode <- TRUE
    } else {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method != "diablo" || is.null(result$data) || is.null(result$Y) || is.null(result$design) || is.null(result$ncomp)) {
        showNotification("DIABLO data not ready. Please run design matrix and performance evaluation first.", type = "error")
        return(NULL)
      }
      data_list <- result$data
      Y_vec <- result$Y
      design_mat <- result$design
      ncomp_val <- result$ncomp
      is_tutorial_mode <- FALSE
    }

    tryCatch({
      withProgress(message = 'Tuning feature selection... This may take a while depending on the number of models being fitted for each component and each nrepeat.', {
        # Set grid of values for each component to test (kept conservative by default)
        test.keepX <- setNames(rep(list(c(5:9, seq(10, 18, 2), seq(20, 30, 5))), length(data_list)), names(data_list))

        # Use tuning parameters from UI - capture outside parallel context
        validation_method <- input$diablo_tune_validation %||% 'Mfold'
        folds <- as.integer(input$diablo_tune_folds %||% 10)
        nrepeat <- as.integer(input$diablo_tune_nrepeat %||% 1)
        dist_choice <- input$diablo_tune_dist %||% 'centroids.dist'

        # Run the feature selection tuning with parallel processing
        if (is_tutorial_mode && isTRUE(diablo_tutorial$is_tutorial)) set.seed(123)
        BPPARAM <- BiocParallel::SnowParam(workers = max(1, parallel::detectCores() - 1), stop.on.error = FALSE)
        tune_result <- mixOmics::tune.block.splsda(
          X = data_list, 
          Y = Y_vec, 
          ncomp = ncomp_val,
          test.keepX = test.keepX, 
          design = design_mat,
          validation = validation_method, 
          folds = folds, 
          nrepeat = nrepeat,
          dist = dist_choice,
          BPPARAM = BPPARAM
        )

        # Store results in appropriate location
        if (is_tutorial_mode) {
          diablo_tutorial$tune_result <- tune_result
          diablo_tutorial$keepX <- tune_result$choice.keepX
        } else {
          multiomics$integration_results$tune_result <- tune_result
          multiomics$integration_results$keepX <- tune_result$choice.keepX
          
          # For real data, automatically create the final model after tuning
          showNotification("Tuning complete. Building final optimized DIABLO model...", type = "message", duration = 2)
          
          final_model <- mixOmics::block.splsda(
            X = data_list, 
            Y = Y_vec, 
            ncomp = ncomp_val,
            keepX = tune_result$choice.keepX, 
            design = design_mat
          )
          
          multiomics$integration_results$final_model <- final_model
          multiomics$integration_results$model <- final_model  # Also store as 'model' for compatibility
          multiomics$integration_results$method <- "diablo"  # Ensure method is set for real data
          
          cat("DIABLO final model created after feature tuning:\n")
          cat("  Blocks:", paste(names(final_model$loadings), collapse = ", "), "\n")
          for (blk in names(final_model$loadings)) {
            cat("  Block", blk, "loadings dim:", nrow(final_model$loadings[[blk]]), "x", ncol(final_model$loadings[[blk]]), "\n")
          }
        }
      })

      if (is_tutorial_mode) {
        showNotification("Feature selection tuning completed successfully! Click 'Create Final Model' to build the optimized model.", type = "message", duration = 4)
      } else {
        showNotification("Feature selection tuning and final model creation completed successfully! Plots are now available.", type = "message", duration = 4)
      }
    }, error = function(e) {
      showNotification(paste("Error in feature tuning:", e$message), type = "error")
    })
  })
  
  # Create Final Model
  observeEvent(input$create_final_model, {
    # Support both tutorial and real data
    if (diablo_tutorial$active) {
      req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design, 
          diablo_tutorial$ncomp, diablo_tutorial$keepX)
      data_list <- diablo_tutorial$data
      Y_vec <- diablo_tutorial$Y
      design_mat <- diablo_tutorial$design
      ncomp_val <- diablo_tutorial$ncomp
      keepX_val <- diablo_tutorial$keepX
      is_tutorial_mode <- TRUE
    } else {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (result$method != "diablo" || is.null(result$data) || is.null(result$Y) || is.null(result$design) || 
          is.null(result$ncomp) || is.null(result$keepX)) {
        showNotification("DIABLO data not ready. Please run feature tuning first.", type = "error")
        return(NULL)
      }
      data_list <- result$data
      Y_vec <- result$Y
      design_mat <- result$design
      ncomp_val <- result$ncomp
      keepX_val <- result$keepX
      is_tutorial_mode <- FALSE
    }
    
    tryCatch({
      # Store method FIRST to ensure conditional panels update
      if (!is_tutorial_mode) {
        if (is.null(multiomics$integration_results)) {
          multiomics$integration_results <- list()
        }
        multiomics$integration_results$method <- "diablo"
      }
      
      # Set the optimised DIABLO model
      final_model <- mixOmics::block.splsda(
        X = data_list, 
        Y = Y_vec, 
        ncomp = ncomp_val,
        keepX = keepX_val, 
        design = design_mat
      )
      
      # Store in appropriate location
      if (is_tutorial_mode) {
        diablo_tutorial$final_model <- final_model
      } else {
        multiomics$integration_results$final_model <- final_model
        multiomics$integration_results$model <- final_model  # Also store as 'model' for compatibility
        multiomics$integration_results$ncomp <- ncomp_val
      }
      
      # Update network block choices with actual block names from model
      block_names <- names(final_model$X)
      updateSelectizeInput(session, "diablo_network_blocks",
                          choices = block_names,
                          selected = block_names[1:min(3, length(block_names))])
      
      showNotification("Final optimized DIABLO model created successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in final model:", e$message), type = "error")
    })
  })
  
  # Show Selected Variables Toggle
  observeEvent(input$show_selected_vars, {
    # Support both tutorial and real data
    final_model <- NULL
    ncomp_val <- 1
    
    if (diablo_tutorial$active) {
      req(diablo_tutorial$final_model)
      final_model <- diablo_tutorial$final_model
      ncomp_val <- diablo_tutorial$ncomp %||% 1
    } else {
      req(multiomics$integration_results)
      result <- multiomics$integration_results
      if (!is.null(result$final_model)) {
        final_model <- result$final_model
      } else if (!is.null(result$model)) {
        final_model <- result$model
      }
      ncomp_val <- result$ncomp %||% 1
    }
    
    req(final_model)

    # Build block and component choices from final model
    blocks <- names(final_model$loadings)
    comp_choices <- as.character(seq_len(ncomp_val))

    showModal(modalDialog(
      title = "Selected Variables",
      fluidRow(
        column(4,
               selectInput("diablo_selected_block", "Block", choices = blocks, selected = blocks[1], width = "100%")
        ),
        column(4,
               selectInput("diablo_selected_comp", "Component", choices = comp_choices, selected = comp_choices[1], width = "100%")
        ),
        column(4,
               numericInput("diablo_selected_nvars", "Number to show", value = 10, min = 1, step = 1, width = "100%")
        )
      ),
      br(),
      div(style = "display: flex; justify-content: center;",
          DT::DTOutput("diablo_selected_variables")
      ),
      br(),
      div(style = "display:flex; justify-content: flex-end; gap: 8px;",
          downloadButton("download_diablo_selected_vars", "Download Selected Variables", class = "btn btn-sm btn-outline-secondary"),
          modalButton("Close")
      ),
      size = "l"
    ))
  })
  
  # Back to Top button for DIABLO Feature Selection Tuning
  observeEvent(input$diablo_back_to_top, {
    shinyjs::runjs("window.scrollTo({top: 0, behavior: 'smooth'});")
  })
  
  # Step 4: Performance tuning for ncomp
  observeEvent(input$tune_components, {
    req(diablo_tutorial$basic_model)
    
    tryCatch({
      withProgress(message = 'Tuning number of components...', {
        # Capture reactive values in main thread before parallel processing
        perf_folds <- input$perf_folds
        perf_repeats <- input$perf_repeats

        if (isTRUE(diablo_tutorial$is_tutorial)) set.seed(123)
        
        BPPARAM <- BiocParallel::SnowParam(workers = max(1, parallel::detectCores() - 1), stop.on.error = FALSE)
        diablo_tutorial$perf_result <- mixOmics::perf(
          diablo_tutorial$basic_model, 
          validation = 'Mfold', 
          folds = perf_folds, 
          nrepeat = perf_repeats,
          BPPARAM = BPPARAM
        )
      })
      
      showNotification("Component tuning completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in component tuning:", e$message), type = "error")
    })
  })
  
  # Step 5: Feature selection tuning
  observeEvent(input$tune_features, {
    req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design, diablo_tutorial$ncomp)
    
    tryCatch({
      withProgress(message = 'Tuning feature selection...', {
        # Create test.keepX grid - use dynamic names based on data blocks
        test.keepX <- setNames(rep(list(input$tune_keepx_range), length(diablo_tutorial$data)), names(diablo_tutorial$data))
        
        # Capture reactive values in main thread before parallel processing
        tune_folds <- input$tune_folds
        tune_repeats <- input$tune_repeats
        tune_distance <- input$tune_distance
        
        # Parallel processing for feature tuning
        BPPARAM <- BiocParallel::SnowParam(workers = max(1, parallel::detectCores() - 1), stop.on.error = FALSE)
        diablo_tutorial$tune_result <- mixOmics::tune.block.splsda(
          X = diablo_tutorial$data, 
          Y = diablo_tutorial$Y, 
          ncomp = diablo_tutorial$ncomp,
          test.keepX = test.keepX, 
          design = diablo_tutorial$design,
          validation = 'Mfold', 
          folds = tune_folds, 
          nrepeat = tune_repeats,
          dist = tune_distance,
          BPPARAM = BPPARAM
        )
      })
      
      diablo_tutorial$keepX <- diablo_tutorial$tune_result$choice.keepX
      
      showNotification("Feature selection tuning completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in feature tuning:", e$message), type = "error")
    })
  })
  
  # Step 6: Final optimized model
  observeEvent(input$run_final_model, {
    req(diablo_tutorial$data, diablo_tutorial$Y, diablo_tutorial$design, 
        diablo_tutorial$ncomp, diablo_tutorial$keepX)
    
    tryCatch({
      diablo_tutorial$final_model <- mixOmics::block.splsda(
        X = diablo_tutorial$data, 
        Y = diablo_tutorial$Y, 
        ncomp = diablo_tutorial$ncomp,
        keepX = diablo_tutorial$keepX, 
        design = diablo_tutorial$design
      )
      
      showNotification("Final optimized DIABLO model created successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in final model:", e$message), type = "error")
    })
  })
  
  # Step 7: Final model performance
  observeEvent(input$evaluate_final_perf, {
    req(diablo_tutorial$final_model)
    
    tryCatch({
      withProgress(message = 'Evaluating final model performance...', {
        # Capture reactive values in main thread before parallel processing
        final_perf_folds <- input$final_perf_folds
        final_perf_repeats <- input$final_perf_repeats
        final_perf_distance <- input$final_perf_distance

        if (isTRUE(diablo_tutorial$is_tutorial)) set.seed(123)
        
        BPPARAM <- BiocParallel::SnowParam(workers = max(1, parallel::detectCores() - 1), stop.on.error = FALSE)
        perf_result <- mixOmics::perf(
          diablo_tutorial$final_model, 
          validation = 'Mfold', 
          folds = final_perf_folds, 
          nrepeat = final_perf_repeats, 
          dist = final_perf_distance,
          BPPARAM = BPPARAM
        )
        
        # Store the performance result
        diablo_tutorial$perf_final <- perf_result
        
        # Extract detailed error rate tables for tutorial mode
        if (!is.null(perf_result$MajorityVote.error.rate)) {
          maj_vote <- perf_result$MajorityVote.error.rate
          if (is.list(maj_vote) && length(maj_vote) > 0) {
            dist_results <- maj_vote[[1]]
            if (is.matrix(dist_results) || is.data.frame(dist_results)) {
              diablo_tutorial$perf_majority_vote <- as.data.frame(dist_results)
            }
          }
        }
        
        if (!is.null(perf_result$WeightedVote.error.rate)) {
          weighted_vote <- perf_result$WeightedVote.error.rate
          if (is.list(weighted_vote) && length(weighted_vote) > 0) {
            dist_results <- weighted_vote[[1]]
            if (is.matrix(dist_results) || is.data.frame(dist_results)) {
              diablo_tutorial$perf_weighted_vote <- as.data.frame(dist_results)
            }
          }
        }
      })
      
      showNotification("Final model performance evaluation completed!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in final performance evaluation:", e$message), type = "error")
    })
  })
  
  # Step 8: AUROC analysis
  observeEvent(input$compute_auroc, {
    req(diablo_tutorial$final_model)
    
    tryCatch({
      diablo_tutorial$auroc_result <- mixOmics::auroc(
        diablo_tutorial$final_model, 
        roc.block = input$auroc_block, 
        roc.comp = input$auroc_comp, 
        print = FALSE
      )
      
      showNotification("AUROC analysis completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in AUROC analysis:", e$message), type = "error")
    })
  })
  
  # Step 9: Prediction on test data
  observeEvent(input$predict_test_data, {
    req(diablo_tutorial$final_model)
    
    tryCatch({
      # Load test data (following tutorial approach)
      data(breast.TCGA)
      data.test.TCGA <- list(
        mRNA = breast.TCGA$data.test$mrna,
        miRNA = breast.TCGA$data.test$mirna,
        proteomics = breast.TCGA$data.test$protein
      )
      
      diablo_tutorial$predictions <- predict(diablo_tutorial$final_model, newdata = data.test.TCGA)
      
      showNotification("Test data predictions completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in test predictions:", e$message), type = "error")
    })
  })
  
  # =============================================================================
  # DIABLO PREDICTION ON EXTERNAL TEST SET - COMPREHENSIVE IMPLEMENTATION
  # =============================================================================
  
  # Reactive values for storing prediction results
  diablo_predictions <- reactiveValues(
    predictions = NULL,
    confusion_matrix = NULL,
    ber = NULL,
    true_labels = NULL,
    test_data = NULL
  )
  
  # Output: Check if tutorial mode is active
  output$diablo_tutorial_active <- reactive({
    isTRUE(diablo_tutorial$active)
  })
  outputOptions(output, "diablo_tutorial_active", suspendWhenHidden = FALSE)
  
  # Output: Check if predictions exist
  output$diablo_has_predictions <- reactive({
    if (diablo_tutorial$active) {
      !is.null(diablo_tutorial$predictions) || !is.null(diablo_predictions$predictions)
    } else {
      !is.null(diablo_predictions$predictions)
    }
  })
  outputOptions(output, "diablo_has_predictions", suspendWhenHidden = FALSE)
  
  # Output: Check if true labels are available
  output$diablo_has_true_labels <- reactive({
    if (diablo_tutorial$active) {
      # Tutorial always has true labels from breast.TCGA
      !is.null(diablo_tutorial$predictions) || !is.null(diablo_predictions$predictions)
    } else {
      !is.null(diablo_predictions$true_labels)
    }
  })
  outputOptions(output, "diablo_has_true_labels", suspendWhenHidden = FALSE)
  
  # Dynamic UI for test data file uploads based on model blocks
  output$diablo_test_data_upload_ui <- renderUI({
    # Get block names from the model
    final_model <- NULL
    if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model)) {
      final_model <- diablo_tutorial$final_model
    } else if (!is.null(multiomics$integration_results$final_model)) {
      final_model <- multiomics$integration_results$final_model
    } else if (!is.null(multiomics$integration_results$model)) {
      final_model <- multiomics$integration_results$model
    }
    
    if (is.null(final_model)) {
      return(div(class = "alert alert-warning", 
                 icon("exclamation-triangle"), " No DIABLO model found. Please train a model first."))
    }
    
    block_names <- names(final_model$X)
    
    # Create file inputs for each block
    file_inputs <- lapply(seq_along(block_names), function(i) {
      block_name <- block_names[i]
      column(4,
             fileInput(paste0("diablo_test_", gsub("[^a-zA-Z0-9]", "_", block_name)),
                       paste0(block_name, " Test Data"),
                       accept = c(".csv", ".txt", ".tsv", ".xlsx"),
                       width = "100%"),
             helpText(paste0("Upload test data for ", block_name, " block (optional)"),
                      style = "font-size: 0.8em; color: var(--text-secondary);")
      )
    })
    
    do.call(fluidRow, file_inputs)
  })
  
  # Tutorial mode prediction button handler
  observeEvent(input$run_diablo_prediction_tutorial, {
    req(diablo_tutorial$final_model)
    
    tryCatch({
      withProgress(message = 'Running prediction on TCGA test data...', {
        # Load TCGA test data
        data(breast.TCGA, envir = environment())
        
        # Prepare test data - note proteomics is missing in test set to demonstrate missing block handling
        data.test.TCGA <- list(
          mRNA = breast.TCGA$data.test$mrna,
          miRNA = breast.TCGA$data.test$mirna
        )
        
        # Get true labels
        true_labels <- breast.TCGA$data.test$subtype
        
        # Run prediction
        pred_result <- predict(diablo_tutorial$final_model, newdata = data.test.TCGA)
        
        # Store results
        diablo_predictions$predictions <- pred_result
        diablo_predictions$true_labels <- true_labels
        diablo_predictions$test_data <- data.test.TCGA
        
        # Also update diablo_tutorial for compatibility
        diablo_tutorial$predictions <- pred_result
        
        # Calculate confusion matrix using optimal component
        ncomp_use <- diablo_tutorial$ncomp %||% 2
        pred_classes <- pred_result$WeightedVote$centroids.dist[, ncomp_use]
        
        confusion.mat <- mixOmics::get.confusion_matrix(
          truth = true_labels,
          predicted = pred_classes
        )
        diablo_predictions$confusion_matrix <- confusion.mat
        
        # Calculate BER
        diablo_predictions$ber <- mixOmics::get.BER(confusion.mat)
        
        setProgress(1)
      })
      
      showNotification("Prediction on TCGA test data completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in prediction:", e$message), type = "error")
    })
  })
  
  # Real data prediction button handler
  observeEvent(input$run_diablo_prediction_real, {
    # Get the model
    final_model <- NULL
    if (!is.null(multiomics$integration_results$final_model)) {
      final_model <- multiomics$integration_results$final_model
    } else if (!is.null(multiomics$integration_results$model)) {
      final_model <- multiomics$integration_results$model
    }
    
    req(final_model)
    
    tryCatch({
      withProgress(message = 'Running prediction on test data...', {
        block_names <- names(final_model$X)
        
        # Collect uploaded test data for each block
        test_data_list <- list()
        
        for (block_name in block_names) {
          input_id <- paste0("diablo_test_", gsub("[^a-zA-Z0-9]", "_", block_name))
          file_input <- input[[input_id]]
          
          if (!is.null(file_input)) {
            # Read the uploaded file
            file_ext <- tools::file_ext(file_input$name)
            
            if (file_ext %in% c("csv", "txt", "tsv")) {
              test_data <- read.csv(file_input$datapath, row.names = 1, header = TRUE, check.names = FALSE)
            } else if (file_ext == "xlsx") {
              test_data <- openxlsx::read.xlsx(file_input$datapath, rowNames = TRUE)
            } else {
              showNotification(paste("Unsupported file format for", block_name), type = "warning")
              next
            }
            
            test_data_list[[block_name]] <- as.matrix(test_data)
          }
        }
        
        if (length(test_data_list) == 0) {
          showNotification("Please upload at least one test data file.", type = "error")
          return(NULL)
        }
        
        # Run prediction
        pred_result <- predict(final_model, newdata = test_data_list)
        
        # Store results
        diablo_predictions$predictions <- pred_result
        diablo_predictions$test_data <- test_data_list
        
        # Handle true labels if provided
        if (!is.null(input$diablo_test_labels_file)) {
          labels_file <- input$diablo_test_labels_file
          file_ext <- tools::file_ext(labels_file$name)
          
          if (file_ext %in% c("csv", "txt", "tsv")) {
            labels_df <- read.csv(labels_file$datapath, header = TRUE, stringsAsFactors = TRUE)
          } else {
            labels_df <- openxlsx::read.xlsx(labels_file$datapath)
          }
          
          # Assume first column is sample IDs, second is labels
          if (ncol(labels_df) >= 2) {
            true_labels <- as.factor(labels_df[, 2])
            names(true_labels) <- labels_df[, 1]
          } else {
            true_labels <- as.factor(labels_df[, 1])
          }
          
          diablo_predictions$true_labels <- true_labels
          
          # Calculate confusion matrix
          ncomp_use <- multiomics$integration_results$ncomp %||% 2
          dist_use <- input$diablo_prediction_distance %||% "centroids.dist"
          
          pred_classes <- pred_result$WeightedVote[[dist_use]][, ncomp_use]
          
          confusion.mat <- mixOmics::get.confusion_matrix(
            truth = true_labels,
            predicted = pred_classes
          )
          diablo_predictions$confusion_matrix <- confusion.mat
          diablo_predictions$ber <- mixOmics::get.BER(confusion.mat)
        } else {
          diablo_predictions$true_labels <- NULL
          diablo_predictions$confusion_matrix <- NULL
          diablo_predictions$ber <- NULL
        }
        
        setProgress(1)
      })
      
      showNotification("Prediction completed successfully!", type = "message", duration = 3)
    }, error = function(e) {
      showNotification(paste("Error in prediction:", e$message), type = "error")
    })
  })
  
  # Update component selector based on model
  observe({
    final_model <- NULL
    ncomp_val <- 2
    
    if (diablo_tutorial$active && !is.null(diablo_tutorial$final_model)) {
      final_model <- diablo_tutorial$final_model
      ncomp_val <- diablo_tutorial$ncomp %||% 2
    } else if (!is.null(multiomics$integration_results$final_model)) {
      final_model <- multiomics$integration_results$final_model
      ncomp_val <- multiomics$integration_results$ncomp %||% 2
    }
    
    if (!is.null(final_model)) {
      updateSelectInput(session, "diablo_pred_comp",
                        choices = as.character(seq_len(ncomp_val)),
                        selected = as.character(ncomp_val))
    }
  })
  
  # Render predictions table
  output$diablo_predictions_table <- DT::renderDT({
    pred_result <- diablo_predictions$predictions
    if (is.null(pred_result) && diablo_tutorial$active) {
      pred_result <- diablo_tutorial$predictions
    }
    req(pred_result)
    
    tryCatch({
      vote_type <- input$diablo_pred_vote_type %||% "WeightedVote"
      dist_type <- input$diablo_pred_distance_display %||% "centroids.dist"
      comp <- as.integer(input$diablo_pred_comp %||% 2)
      
      # Extract predictions
      vote_data <- pred_result[[vote_type]]
      if (!is.null(vote_data) && !is.null(vote_data[[dist_type]])) {
        pred_matrix <- vote_data[[dist_type]]
        
        # Handle case where comp exceeds available components
        if (comp > ncol(pred_matrix)) comp <- ncol(pred_matrix)
        
        pred_df <- data.frame(
          Sample = rownames(pred_matrix),
          Predicted_Class = pred_matrix[, comp],
          stringsAsFactors = FALSE
        )
        
        # Add true labels if available
        if (diablo_tutorial$active) {
          data(breast.TCGA, envir = environment())
          true_labels <- breast.TCGA$data.test$subtype
          pred_df$True_Class <- as.character(true_labels)
          pred_df$Correct <- pred_df$Predicted_Class == pred_df$True_Class
        } else if (!is.null(diablo_predictions$true_labels)) {
          pred_df$True_Class <- as.character(diablo_predictions$true_labels)
          pred_df$Correct <- pred_df$Predicted_Class == pred_df$True_Class
        }
        
        DT::datatable(pred_df,
                      options = list(pageLength = 15, scrollX = TRUE, dom = 'frtip'),
                      rownames = FALSE,
                      class = 'cell-border stripe') %>%
          DT::formatStyle('Correct',
                          backgroundColor = DT::styleEqual(c(TRUE, FALSE), c('#d4edda', '#f8d7da')))
      } else {
        DT::datatable(data.frame(Message = "Prediction results not available."),
                      options = list(pageLength = 1, dom = 't'), rownames = FALSE)
      }
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error:", e$message)),
                    options = list(pageLength = 1, dom = 't'), rownames = FALSE)
    })
  })
  
  # Render confusion matrix table
  output$diablo_confusion_matrix_table <- DT::renderDT({
    tryCatch({
      confusion_mat <- diablo_predictions$confusion_matrix
      
      # For tutorial mode, recalculate with current settings
      if (is.null(confusion_mat) && diablo_tutorial$active) {
        pred_result <- diablo_tutorial$predictions %||% diablo_predictions$predictions
        req(pred_result)
        
        data(breast.TCGA, envir = environment())
        true_labels <- breast.TCGA$data.test$subtype
        
        vote_type <- input$diablo_pred_vote_type %||% "WeightedVote"
        dist_type <- input$diablo_pred_distance_display %||% "centroids.dist"
        comp <- as.integer(input$diablo_pred_comp %||% 2)
        
        pred_classes <- pred_result[[vote_type]][[dist_type]][, comp]
        
        confusion_mat <- mixOmics::get.confusion_matrix(
          truth = true_labels,
          predicted = pred_classes
        )
      }
      
      req(confusion_mat)
      
      # Convert to data frame for display
      cm_df <- as.data.frame.matrix(confusion_mat)
      cm_df <- cbind(True_Class = rownames(cm_df), cm_df)
      rownames(cm_df) <- NULL
      
      DT::datatable(cm_df,
                    options = list(pageLength = 10, scrollX = TRUE, dom = 't'),
                    rownames = FALSE,
                    class = 'cell-border stripe')
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error:", e$message)),
                    options = list(pageLength = 1, dom = 't'), rownames = FALSE)
    })
  })
  
  # Render BER value
  output$diablo_ber_value <- renderText({
    tryCatch({
      ber_val <- diablo_predictions$ber
      
      # For tutorial mode, recalculate
      if (is.null(ber_val) && diablo_tutorial$active) {
        pred_result <- diablo_tutorial$predictions %||% diablo_predictions$predictions
        req(pred_result)
        
        data(breast.TCGA, envir = environment())
        true_labels <- breast.TCGA$data.test$subtype
        
        vote_type <- input$diablo_pred_vote_type %||% "WeightedVote"
        dist_type <- input$diablo_pred_distance_display %||% "centroids.dist"
        comp <- as.integer(input$diablo_pred_comp %||% 2)
        
        pred_classes <- pred_result[[vote_type]][[dist_type]][, comp]
        
        confusion_mat <- mixOmics::get.confusion_matrix(
          truth = true_labels,
          predicted = pred_classes
        )
        ber_val <- mixOmics::get.BER(confusion_mat)
      }
      
      req(ber_val)
      sprintf("%.4f", ber_val)
    }, error = function(e) {
      "N/A"
    })
  })
  
  # Render prediction summary statistics
  output$diablo_prediction_summary_stats <- renderPrint({
    tryCatch({
      confusion_mat <- diablo_predictions$confusion_matrix
      
      # For tutorial mode, recalculate
      if (is.null(confusion_mat) && diablo_tutorial$active) {
        pred_result <- diablo_tutorial$predictions %||% diablo_predictions$predictions
        req(pred_result)
        
        data(breast.TCGA, envir = environment())
        true_labels <- breast.TCGA$data.test$subtype
        
        vote_type <- input$diablo_pred_vote_type %||% "WeightedVote"
        dist_type <- input$diablo_pred_distance_display %||% "centroids.dist"
        comp <- as.integer(input$diablo_pred_comp %||% 2)
        
        pred_classes <- pred_result[[vote_type]][[dist_type]][, comp]
        
        confusion_mat <- mixOmics::get.confusion_matrix(
          truth = true_labels,
          predicted = pred_classes
        )
      }
      
      req(confusion_mat)
      
      # Calculate additional metrics
      cm <- as.matrix(confusion_mat)
      total_samples <- sum(cm)
      correct <- sum(diag(cm))
      accuracy <- correct / total_samples
      
      # Per-class metrics
      classes <- rownames(cm)
      per_class_accuracy <- diag(cm) / rowSums(cm)
      
      cat("Overall Accuracy:", sprintf("%.2f%%", accuracy * 100), "\n")
      cat("Total Samples:", total_samples, "\n")
      cat("Correctly Classified:", correct, "\n")
      cat("Misclassified:", total_samples - correct, "\n\n")
      cat("Per-Class Accuracy:\n")
      for (i in seq_along(classes)) {
        cat(sprintf("  %s: %.2f%%\n", classes[i], per_class_accuracy[i] * 100))
      }
    }, error = function(e) {
      cat("Statistics not available")
    })
  })
  
