  # DIABLO Performance Tuning Results - Majority Vote Table
  output$diablo_majority_vote_table <- DT::renderDT({
    build_full_table <- function(perf, dist_choice) {
      # Extract full matrix with per-group error rates (like tutorial output)
      if (!is.null(perf$MajorityVote.error.rate)) {
        er <- perf$MajorityVote.error.rate
        # er is typically a list by distance, then matrix [class x comp]
        dist_use <- dist_choice %||% names(er)[1]
        dist_use <- dist_use[!is.na(dist_use)][1]
        er_dist <- if (is.list(er)) (er[[dist_use]] %||% er[[1]]) else er
        
        if (!is.null(er_dist) && (is.matrix(er_dist) || is.data.frame(er_dist))) {
          # Convert to data frame with Metric column (row names become Metric)
          df <- as.data.frame(er_dist)
          df <- cbind(Metric = rownames(df), df)
          rownames(df) <- NULL
          return(df)
        }
      }
      NULL
    }

    tryCatch({
      if (diablo_tutorial$active) {
        req(diablo_tutorial$perf_tuning_result)
        perf <- diablo_tutorial$perf_tuning_result
      } else {
        req(multiomics$perf_tuning_result)
        perf <- multiomics$perf_tuning_result
      }

      dist_choice <- input$diablo_perf_dist %||% NULL
      table_df <- build_full_table(perf, dist_choice)

      if (!is.null(table_df)) {
        DT::datatable(table_df,
                      caption = paste("MajorityVote Error Rates (", dist_choice %||% "default distance", ")"),
                      options = list(pageLength = 10, scrollX = TRUE, dom = 't'),
                      rownames = FALSE) %>%
          DT::formatRound(columns = setdiff(colnames(table_df), "Metric"), digits = 4)
      } else {
        DT::datatable(data.frame(Message = "Majority Vote results not available. Run performance evaluation first."),
                      options = list(pageLength = 1, dom = 't'), rownames = FALSE)
      }
    }, error = function(e) {
      DT::datatable(data.frame(Error = paste("Error loading Majority Vote results:", e$message)),
                    options = list(pageLength = 1, dom = 't'), rownames = FALSE)
    })
  })
  
