  # ============================================================================
  # COVARIATE ASSOCIATION ANALYSIS
  # ============================================================================
  
  # Reactive for storing association results
  assoc_results <- reactiveVal(NULL)
  
  # Update preview text when covariate selection or mode changes
  observeEvent(list(input$assoc_covariates, input$assoc_cov_mode), {
    selected_orig <- input$assoc_covariates %||% mofa_metadata$covariate_names
    if (is.null(selected_orig)) selected_orig <- character(0)
    cov_mode <- input$assoc_cov_mode %||% "expanded"
    cov_map2 <- mofa_metadata$covariate_expansion_map %||% list()

    preview_vars <- if (cov_mode == "expanded") {
      unique(unlist(lapply(selected_orig, function(x) {
        if (!is.null(cov_map2[[x]]) && length(cov_map2[[x]]) > 0) cov_map2[[x]] else x
      })))
    } else {
      selected_orig
    }
    # Display-friendly names for preview (dots -> spaces)
    display_preview_vars <- gsub("\\.", " ", preview_vars)
    preview_text <- if (length(display_preview_vars) == 0) "No covariates selected" else paste0("Using: ", paste(display_preview_vars[seq_len(min(6, length(display_preview_vars)))], collapse = ", "), if (length(display_preview_vars) > 6) paste0(" ... (", length(display_preview_vars), " total)" ) else "")
    output$assoc_selected_preview <- renderText({ preview_text })
  })

  # Observe "Compute Associations" button
  observeEvent(input$compute_assoc, {
    req(multiomics$integration_results)
    
    result <- multiomics$integration_results
    
    # Check for MOFA model
    if (result$method != "mofa" || is.null(result$mofa_model)) {
      showNotification("MOFA analysis required with a trained model", type = "error")
      return()
    }
    
    # Check for covariates
    if (is.null(mofa_metadata$covariate_names) || length(mofa_metadata$covariate_names) == 0) {
      showNotification("No covariates available. Upload metadata with additional columns.", type = "error")
      return()
    }

    if (!requireNamespace("MOFA2", quietly = TRUE)) {
      showNotification("MOFA2 package not available; cannot compute covariate associations.", type = "error")
      return()
    }
    
    tryCatch({
      plot_mode <- input$assoc_plot %||% "log_pval"

      # Attach ALL metadata columns (including grouping columns) into the MOFA model sample metadata.
      # Then call correlate_factors_with_covariates() using covariate NAMES (stable, tutorial-aligned).
      model <- result$mofa_model

      sample_ids <- NULL
      sn <- tryCatch(MOFA2::samples_names(model), error = function(e) NULL)
      if (is.list(sn)) sn <- unlist(sn, use.names = FALSE)
      sample_ids <- as.character(sn)
      if (is.null(sample_ids) || length(sample_ids) == 0) {
        if (!is.null(result$factors) && "Sample" %in% colnames(result$factors)) {
          sample_ids <- as.character(result$factors$Sample)
        }
      }
      sample_ids <- sample_ids[!is.na(sample_ids) & nzchar(sample_ids)]
      if (length(sample_ids) == 0) stop("Could not determine MOFA model sample names")

      md <- tryCatch(MOFA2::samples_metadata(model), error = function(e) NULL)
      md_df <- data.frame(sample = sample_ids, stringsAsFactors = FALSE)
      if (!is.null(md) && is.data.frame(md) && nrow(md) > 0) {
        existing_md <- as.data.frame(md, stringsAsFactors = FALSE)
        sample_col <- intersect(c("sample", "Sample"), colnames(existing_md))
        sample_vals <- NULL
        if (length(sample_col) > 0) {
          sample_vals <- as.character(existing_md[[sample_col[1]]])
        } else if (!is.null(rownames(existing_md)) && all(nzchar(rownames(existing_md)))) {
          sample_vals <- rownames(existing_md)
        }
        if (!is.null(sample_vals)) {
          existing_md$sample <- sample_vals
          extra_cols <- setdiff(colnames(existing_md), "sample")
          for (col_name in extra_cols) {
            md_df[[col_name]] <- existing_md[[col_name]][match(sample_ids, existing_md$sample)]
          }
        }
      }

      if (is.null(mofa_metadata$covariates) || !is.data.frame(mofa_metadata$covariates) || nrow(mofa_metadata$covariates) == 0) {
        stop("No uploaded metadata covariates available to attach to the MOFA model")
      }

      cov_all <- as.data.frame(mofa_metadata$covariates, stringsAsFactors = FALSE)
      cov_sample <- NULL
      if ("sample" %in% colnames(cov_all)) cov_sample <- as.character(cov_all$sample)
      if (is.null(cov_sample) && "Sample" %in% colnames(cov_all)) cov_sample <- as.character(cov_all$Sample)
      if (is.null(cov_sample) && !is.null(rownames(cov_all)) && all(nzchar(rownames(cov_all)))) cov_sample <- rownames(cov_all)
      if (is.null(cov_sample)) stop("Metadata must contain a sample identifier column (sample/Sample) or rownames")

      keep <- !is.na(cov_sample) & nzchar(cov_sample)
      cov_all <- cov_all[keep, , drop = FALSE]
      cov_sample <- cov_sample[keep]
      if (any(duplicated(cov_sample))) {
        keep2 <- !duplicated(cov_sample)
        cov_all <- cov_all[keep2, , drop = FALSE]
        cov_sample <- cov_sample[keep2]
      }

      # Use all non-sample-id columns from uploaded metadata as covariates
      exclude_cols <- c("sample", "Sample", "sample_id", "sampleID", "SampleID", "id", "ID")
      cov_cols_all <- setdiff(colnames(cov_all), exclude_cols)
      if (length(cov_cols_all) == 0) stop("No covariate columns found in metadata")

      mi <- match(md_df$sample, cov_sample)
      # Align covariate values to model sample order
      aligned_cov <- list()
      for (cn in cov_cols_all) {
        # If mi is all NA (no overlap), aligned vector will be all NA of correct length
        if (length(mi) == 0) {
          aligned_cov[[cn]] <- rep(NA, nrow(md_df))
        } else {
          aligned_cov[[cn]] <- cov_all[[cn]][mi]
        }
      }

      # Check overlap between MOFA samples and metadata samples
      overlap_count <- sum(!is.na(mi))
      if (overlap_count == 0) {
        stop(paste0("No overlapping sample IDs found between MOFA model (", length(md_df$sample),
                    ") and uploaded metadata (", length(cov_sample), "). Check SampleID column for mismatches."))
      }

      # Attach uploaded covariates to model metadata (original columns only).
      # Expansion/one-hot encoding is handled later in the sanitization step so the UI can
      # cleanly switch between "Original" and "Expanded" modes without duplicated columns.
      for (cn in names(aligned_cov)) {
        v <- aligned_cov[[cn]]
        if (length(v) != nrow(md_df)) {
          v <- if (length(v) < nrow(md_df)) c(v, rep(NA, nrow(md_df) - length(v))) else v[seq_len(nrow(md_df))]
        }
        md_df[[cn]] <- v
      }

      # Write back to the model
      tryCatch({
        MOFA2::samples_metadata(model) <- md_df
      }, error = function(e) {
        stop(paste0("Failed to attach metadata to MOFA model: ", e$message))
      })

      # Covariate names to use in association: all newly attached non-id columns
      cov_cols_all <- setdiff(colnames(md_df), exclude_cols)
      cov_cols_all <- setdiff(cov_cols_all, "sample")
      if (length(cov_cols_all) == 0) stop("No covariates available after processing metadata")

      # Sanitize covariates: keep originals and create numeric dummy columns for categorical variables.
      # Also detect numeric-like character columns (e.g., Age) to avoid exploding into one-hot columns.
      md_cov_subset <- md_df[, cov_cols_all, drop = FALSE]
      removed_covs <- character(0)
      kept_covs <- character(0)
      auto_converted_covs <- character(0)
      expanded_covs <- character(0)
      cov_map <- list()

      sanitized <- data.frame(matrix(ncol = 0, nrow = nrow(md_df)), stringsAsFactors = FALSE)

      for (cn in colnames(md_cov_subset)) {
        v <- md_cov_subset[[cn]]

        if (is.logical(v)) {
          v_num <- as.numeric(v)
          v_num[is.infinite(v_num)] <- NA_real_

          nonna_idx <- which(!is.na(v_num))
          if (length(nonna_idx) <= 2 || length(unique(v_num[nonna_idx])) <= 1) {
            removed_covs <- c(removed_covs, cn)
            next
          }

          sanitized[[cn]] <- v_num
          kept_covs <- c(kept_covs, cn)
          next
        }

        if (is.numeric(v) || is.integer(v)) {
          v_num <- as.numeric(v)
          v_num[is.infinite(v_num)] <- NA_real_

          nonna_idx <- which(!is.na(v_num))
          if (length(nonna_idx) <= 2 || length(unique(v_num[nonna_idx])) <= 1) {
            removed_covs <- c(removed_covs, cn)
            next
          }

          sanitized[[cn]] <- v_num
          kept_covs <- c(kept_covs, cn)
          next
        }

        # Handle factor/character columns
        v_chr <- as.character(v)
        v_chr_nonna <- v_chr[!is.na(v_chr) & nzchar(v_chr)]
        v_num_try <- suppressWarnings(as.numeric(v_chr))
        frac_numeric <- if (length(v_chr_nonna) == 0) 0 else (sum(!is.na(v_num_try) & !is.infinite(v_num_try)) / length(v_chr_nonna))

        # If mostly numeric-like, treat as numeric (prevents Age/PMI from being one-hot encoded)
        if (frac_numeric >= 0.8) {
          v_num <- as.numeric(v_num_try)
          v_num[is.infinite(v_num)] <- NA_real_

          nonna_idx <- which(!is.na(v_num))
          if (length(nonna_idx) <= 2 || length(unique(v_num[nonna_idx])) <= 1) {
            removed_covs <- c(removed_covs, cn)
            next
          }

          sanitized[[cn]] <- v_num
          kept_covs <- c(kept_covs, cn)
          cov_map[[cn]] <- cn
          next
        }

        # Preserve observed level order (do not sort) so encoding is stable and intuitive.
        lvls <- unique(stats::na.omit(v_chr))

        # Choose a reference level for dummy encoding.
        # Preference: use a "Control"-like level as reference when present; otherwise use the
        # first-observed level (preserve factor order).
        ref_idx <- NA_integer_
        if (length(lvls) > 0) {
          lvls_lc <- tolower(trimws(lvls))
          control_hits <- which(grepl("^control$|^ctrl$|control|^baseline$|^healthy$|^normal$|^wt$", lvls_lc))
          if (length(control_hits) > 0) {
            ref_idx <- control_hits[1]
          } else {
            ref_idx <- 1L
          }
        }
        ref_lvl <- if (!is.na(ref_idx) && ref_idx >= 1 && ref_idx <= length(lvls)) lvls[ref_idx] else lvls[1]

        if (length(lvls) == 0 || length(lvls) == 1) {
          removed_covs <- c(removed_covs, cn)
          next
        }

        if (length(lvls) == 2) {
          # Binary categorical: keep original column and create one dummy per level
          # so Expanded mode shows both levels (e.g., Sex_M and Sex_F).
          sanitized[[cn]] <- v_chr
          kept_covs <- c(kept_covs, cn)

          # ensure we have a map entry
          if (is.null(cov_map[[cn]])) cov_map[[cn]] <- character(0)

          for (lvl in lvls) {
            new_cn <- paste0(cn, "_", make.names(lvl))
            x <- as.integer(v_chr == lvl)
            x[is.na(v_chr)] <- NA_integer_
            x_num <- as.numeric(x)

            nonna_idx <- which(!is.na(x_num))
            if (length(nonna_idx) <= 2 || length(unique(x_num[nonna_idx])) <= 1) {
              removed_covs <- c(removed_covs, new_cn)
              next
            }

            sanitized[[new_cn]] <- x_num
            expanded_covs <- c(expanded_covs, new_cn)
            kept_covs <- c(kept_covs, new_cn)
            cov_map[[cn]] <- c(cov_map[[cn]], new_cn)
          }

          auto_converted_covs <- c(auto_converted_covs, cn)
          next
        }

        # Multi-level categorical: keep original column and create k dummy columns (one per level)
        if (length(lvls) > 2 && length(lvls) <= 25) {
          # keep original values as a categorical column so 'original' covariate mode works
          sanitized[[cn]] <- v_chr
          kept_covs <- c(kept_covs, cn)

          # ensure we have a map entry
          if (is.null(cov_map[[cn]])) cov_map[[cn]] <- character(0)

          for (lvl in lvls) {
            new_cn <- paste0(cn, "_", make.names(lvl))
            x <- as.integer(v_chr == lvl)
            x[is.na(v_chr)] <- NA_integer_
            x_num <- as.numeric(x)

            nonna_idx <- which(!is.na(x_num))
            if (length(nonna_idx) <= 2 || length(unique(x_num[nonna_idx])) <= 1) {
              # skip adding this level if insufficient data
              removed_covs <- c(removed_covs, new_cn)
              next
            }

            sanitized[[new_cn]] <- x_num
            expanded_covs <- c(expanded_covs, new_cn)
            kept_covs <- c(kept_covs, new_cn)
            cov_map[[cn]] <- c(cov_map[[cn]], new_cn)
          }
          next
        }

        # Too many levels: drop the covariate
        removed_covs <- c(removed_covs, cn)
      }

      if (length(kept_covs) == 0) stop("No suitable covariates available after sanitization (all were constant, insufficient, or non-numeric)")
      # Show summary of covariate processing
      processing_msgs <- character(0)
      if (length(removed_covs) > 0) {
        processing_msgs <- c(processing_msgs, paste0("Dropped ", length(unique(removed_covs)), " covariates (constant/invalid)"))
      }
      if (length(auto_converted_covs) > 0) {
        processing_msgs <- c(processing_msgs, paste0("Auto-encoded ", length(auto_converted_covs), " binary covariates"))
      }
      if (length(expanded_covs) > 0) {
        processing_msgs <- c(processing_msgs, paste0("One-hot encoded ", length(unique(expanded_covs)), " levels from multi-level covariates"))
      }
      if (length(processing_msgs) > 0) {
        showNotification(paste(processing_msgs, collapse = "; "), type = "message", duration = 6)
      }

      # Store expansion mapping for UI choices and selection mapping
      mofa_metadata$covariate_expansion_map <- cov_map

      # Attach sanitized columns back to the metadata and update covariate list
      for (cn in colnames(sanitized)) {
        md_df[[cn]] <- sanitized[[cn]]
      }
      cov_cols_all <- colnames(sanitized)

      # Update MOFA model's sample metadata so the model contains sanitized covariates
      tryCatch({
        MOFA2::samples_metadata(model) <- md_df
      }, error = function(e) {
        showNotification(paste("Failed to update MOFA model metadata:", conditionMessage(e)), type = "error", duration = 8)
        stop(paste("Failed to update MOFA model metadata:", conditionMessage(e)))
      })

      # Sanity check: ensure the covariate names are present in the model metadata
      model_md <- tryCatch(MOFA2::samples_metadata(model), error = function(e) NULL)
      if (is.null(model_md) || !all(cov_cols_all %in% colnames(model_md))) {
        missing <- setdiff(cov_cols_all, colnames(model_md))
        showNotification(paste("Sanitized covariates missing from model metadata:", paste(missing, collapse = ", ")), type = "error", duration = 8)
        stop(paste("Sanitized covariates not present in model metadata:", paste(missing, collapse = ", ")))
      }

      # Map the user's selected original covariates to the columns actually used by MOFA2
      selected_orig <- input$assoc_covariates
      if (is.null(selected_orig) || length(selected_orig) == 0) {
        showNotification("Select at least one covariate to compute associations.", type = "error", duration = 6)
        return()
      }

      cov_mode <- input$assoc_cov_mode %||% "expanded"
      cov_map2 <- mofa_metadata$covariate_expansion_map %||% list()

      effective_covs <- if (cov_mode == "expanded") {
        unique(unlist(lapply(selected_orig, function(x) {
          if (!is.null(cov_map2[[x]]) && length(cov_map2[[x]]) > 0) cov_map2[[x]] else x
        })))
      } else {
        unique(selected_orig)
      }

      # Keep only covariates that exist in the model metadata
      effective_covs <- effective_covs[effective_covs %in% colnames(md_df)]
      if (length(effective_covs) == 0) stop("No selected covariates are present in the model metadata")

      # Show which covariates will be used (brief)
      showNotification(paste0("Using ", length(effective_covs), " covariates for association analysis"), type = "message", duration = 4)

      # Retrieve association data. MOFA2 expects plot to be one of c("log_pval", "r").
      # In Shiny, MOFA2's internal plotting can fail if no device is available (this
      # observer runs outside renderPlot); open a temporary null device so the call is robust.
      opened_device <- FALSE
      try({
        grDevices::pdf(NULL)
        opened_device <- TRUE
      }, silent = TRUE)
      on.exit({
        if (opened_device) try(grDevices::dev.off(), silent = TRUE)
      }, add = TRUE)

      assoc_data <- MOFA2::correlate_factors_with_covariates(
        model,
        covariates = effective_covs,
        plot = plot_mode,
        alpha = input$assoc_pthresh,
        return_data = TRUE
      )

      assoc_df <- assoc_data
      if (is.list(assoc_data) && !is.data.frame(assoc_data)) {
        if (!is.null(assoc_data$data) && is.data.frame(assoc_data$data)) {
          assoc_df <- assoc_data$data
        } else if (!is.null(assoc_data$correlations) && is.data.frame(assoc_data$correlations)) {
          assoc_df <- assoc_data$correlations
        }
      }

      if (is.data.frame(assoc_df) && nrow(assoc_df) == 0) {
        stop("Association analysis returned no results. Check metadata overlap and that selected covariates are not constant.")
      }

      assoc_results(list(
        data = assoc_df,
        covariates = effective_covs,
        model = model,
        alpha = input$assoc_pthresh,
        plot = plot_mode
      ))

      showNotification(
        paste0("✓ Computed associations for ", length(effective_covs), " covariates"),
        type = "message", duration = 4
      )
    }, error = function(e) {
      showNotification(paste("Error in association analysis:", e$message), type = "error")
    })
  })
  
  # Render covariate association heatmap
  output$mofa_assoc_heatmap <- renderPlot({ 
    req(assoc_results(), multiomics$integration_results)

    result <- multiomics$integration_results
    if (is.null(result) || result$method != "mofa" || is.null(result$mofa_model)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "MOFA analysis required with a trained model",
                   size = 4, color = "#ef4444") +
          theme_void()
      )
    }

    selected_covs <- assoc_results()$covariates
    alpha <- assoc_results()$alpha
    plot_mode <- assoc_results()$plot %||% "log_pval"
    model <- assoc_results()$model
    req(model)

    tryCatch({
      # Try to get the plot object from MOFA2 and post-process the labels to be display-friendly
      p <- tryCatch({
        MOFA2::correlate_factors_with_covariates(
          model,
          covariates = selected_covs,
          plot = plot_mode,
          alpha = alpha
        )
      }, error = function(e) {
        stop(e)
      }, res = UI_PLOT_RES)

      # If we received a ggplot object, relabel axes to replace dots with spaces for readability
      if (inherits(p, "ggplot")) {
        p <- p +
          scale_y_discrete(labels = function(x) gsub("\\.", " ", x)) +
          scale_x_discrete(labels = function(x) gsub("\\.", " ", x))
        p <- apply_mofa_text_fix(p)
        print(p)
      } else {
        # Otherwise, try printing the object as-is (some MOFA2 versions draw directly)
        tryCatch({ print(p) }, error = function(e) { NULL })
      }
    }, error = function(e) {
      ggplot() +
        annotate("text", x = 0.5, y = 0.5,
                 label = paste("Error:", e$message),
                 size = 4, color = "#ef4444") +
        theme_void()
    })
  })
  
  # Download association results
  output$download_assoc_results <- downloadHandler(
    filename = function() {
      paste0("covariate_associations_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(assoc_results())
      
      assoc_data <- assoc_results()$data
      if (is.null(assoc_data)) {
        stop("No association data available")
      }

      if (is.data.frame(assoc_data)) {
        write.csv(assoc_data, file, row.names = FALSE)
      } else {
        write.csv(as.data.frame(assoc_data), file, row.names = FALSE)
      }
      
      showNotification(paste("✓ Results saved to", basename(file)),
                       type = "message", duration = 3)
    }
  )
  
  # ============================================================================
  # MOFA CLINICAL PREDICTION FUNCTIONALITY
  # ============================================================================
  
  # Update target variable dropdown based on available metadata columns
  observe({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (is.null(result) || result$method != "mofa") return()
    
    # Get metadata from the MOFA model or tutorial
    metadata <- NULL
    if (!is.null(result$mofa_model)) {
      metadata <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
    }
    if (is.null(metadata) && !is.null(mofa_tutorial$metadata)) {
      metadata <- mofa_tutorial$metadata
    }
    
    if (is.null(metadata) || nrow(metadata) == 0) {
      updateSelectInput(session, "mofa_pred_target", choices = c("No metadata available" = ""))
      return()
    }
    
    # Find categorical columns that could be prediction targets (have some NA values or are factors)
    categorical_cols <- sapply(metadata, function(col) {
      is.factor(col) || is.character(col) || (is.numeric(col) && length(unique(na.omit(col))) <= 10)
    })
    
    potential_targets <- names(metadata)[categorical_cols]
    # Exclude sample ID columns
    potential_targets <- potential_targets[!tolower(potential_targets) %in% c("sample", "sampleid", "sample_id")]
    
    if (length(potential_targets) == 0) {
      updateSelectInput(session, "mofa_pred_target", choices = c("No suitable target columns" = ""))
    } else {
      # Mark columns with missing values
      target_choices <- setNames(potential_targets, sapply(potential_targets, function(col) {
        n_missing <- sum(is.na(metadata[[col]]))
        n_total <- nrow(metadata)
        if (n_missing > 0) {
          paste0(col, " (", n_missing, "/", n_total, " missing)")
        } else {
          paste0(col, " (no missing)")
        }
      }))
      updateSelectInput(session, "mofa_pred_target", choices = target_choices)
    }
  })
  
  # Update factor selection dropdowns
  observe({
    req(multiomics$integration_results)
    result <- multiomics$integration_results
    
    if (is.null(result) || result$method != "mofa" || is.null(result$factors)) return()
    
    factor_names <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
    
    updateSelectizeInput(session, "mofa_pred_factors", choices = factor_names, selected = factor_names[1:min(2, length(factor_names))])
    updateSelectInput(session, "mofa_pred_factor_x", choices = factor_names, selected = factor_names[1])
    updateSelectInput(session, "mofa_pred_factor_y", choices = factor_names, selected = factor_names[min(2, length(factor_names))])
  })
  
  # Run prediction when button is clicked
  observeEvent(input$mofa_run_prediction, {
    req(multiomics$integration_results, input$mofa_pred_target)
    
    result <- multiomics$integration_results
    if (is.null(result) || result$method != "mofa") {
      showNotification("MOFA analysis required", type = "error")
      return()
    }
    
    target_var <- input$mofa_pred_target
    if (!nzchar(target_var)) {
      showNotification("Please select a target variable to predict", type = "warning")
      return()
    }
    
    # Get metadata
    metadata <- NULL
    if (!is.null(result$mofa_model)) {
      metadata <- tryCatch(MOFA2::samples_metadata(result$mofa_model), error = function(e) NULL)
    }
    if (is.null(metadata) && !is.null(mofa_tutorial$metadata)) {
      metadata <- as.data.frame(mofa_tutorial$metadata)
    }
    
    if (is.null(metadata) || !target_var %in% colnames(metadata)) {
      showNotification("Target variable not found in metadata", type = "error")
      return()
    }
    
    withProgress(message = "Training prediction model...", value = 0, {
      tryCatch({
        # Ensure randomForest is available
        if (!requireNamespace("randomForest", quietly = TRUE)) {
          stop("randomForest package required. Install with: install.packages('randomForest')")
        }
        
        incProgress(0.2, detail = "Preparing factor data...")
        
        # Get selected factors (or default to Factor1, Factor2)
        selected_factors <- input$mofa_pred_factors
        if (is.null(selected_factors) || length(selected_factors) == 0) {
          factor_names <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
          selected_factors <- factor_names[1:min(2, length(factor_names))]
        }
        
        # Prepare factor data for prediction
        factors_df <- result$factors
        
        # Match samples between factors and metadata
        sample_col <- if ("sample" %in% colnames(metadata)) "sample" else if ("Sample" %in% colnames(metadata)) "Sample" else NULL
        
        if (is.null(sample_col)) {
          # Try to match by rownames or index
          if (!is.null(rownames(metadata)) && all(nzchar(rownames(metadata)))) {
            metadata$sample <- rownames(metadata)
            sample_col <- "sample"
          } else {
            metadata$sample <- seq_len(nrow(metadata))
            sample_col <- "sample"
          }
        }
        
        # Identify sample column in factors
        factor_sample_col <- if ("Sample" %in% colnames(factors_df)) "Sample" else if ("sample" %in% colnames(factors_df)) "sample" else NULL
        
        if (is.null(factor_sample_col)) {
          factors_df$Sample <- rownames(factors_df)
          factor_sample_col <- "Sample"
        }
        
        # Merge factors with metadata
        df <- as.data.frame(factors_df[, c(factor_sample_col, selected_factors), drop = FALSE])
        colnames(df)[1] <- "sample"
        
        # Add target variable
        metadata_sub <- metadata[, c(sample_col, target_var), drop = FALSE]
        colnames(metadata_sub) <- c("sample", "target")
        
        df <- merge(df, metadata_sub, by = "sample", all.x = TRUE)
        
        incProgress(0.4, detail = "Training Random Forest model...")
        
        # Prepare training data (only samples with known target)
        train_df <- df[!is.na(df$target), ]
        predict_df <- df  # All samples for prediction
        
        if (nrow(train_df) < 5) {
          stop("Not enough samples with known labels to train model (need at least 5)")
        }
        
        # Convert target to factor
        train_df$target <- as.factor(train_df$target)
        
        # Set seed for reproducibility
        set.seed(input$mofa_pred_seed %||% 42)
        
        # Train Random Forest
        ntree <- input$mofa_pred_ntree %||% 100
        formula <- as.formula(paste("target ~", paste(selected_factors, collapse = " + ")))
        
        rf_model <- randomForest::randomForest(
          formula,
          data = train_df,
          ntree = ntree,
          importance = TRUE
        )
        
        incProgress(0.7, detail = "Making predictions...")
        
        # Predict for all samples
        predict_features <- predict_df[, selected_factors, drop = FALSE]
        predicted_values <- stats::predict(rf_model, predict_features)
        
        # Determine which predictions are "True" (known) vs "Predicted" (imputed)
        prediction_source <- ifelse(is.na(df$target), "Predicted", "True")
        
        # Create results dataframe
        results_df <- data.frame(
          Sample = df$sample,
          Original = as.character(ifelse(is.na(df$target), NA, df$target)),
          Predicted = as.character(predicted_values),
          Source = prediction_source,
          stringsAsFactors = FALSE
        )
        
        # Add factor values to results
        for (f in selected_factors) {
          results_df[[f]] <- df[[f]]
        }
        
        incProgress(0.9, detail = "Storing results...")
        
        # Store results in reactive values
        mofa_predictions$rf_model <- rf_model
        mofa_predictions$target_variable <- target_var
        mofa_predictions$predicted_values <- predicted_values
        mofa_predictions$prediction_source <- prediction_source
        mofa_predictions$factors_used <- selected_factors
        mofa_predictions$results_df <- results_df
        
        # Generate model summary
        confusion_matrix <- rf_model$confusion
        oob_error <- rf_model$err.rate[nrow(rf_model$err.rate), "OOB"]
        
        model_summary <- paste0(
          "Random Forest Model Summary\n",
          "===========================\n",
          "Target variable: ", target_var, "\n",
          "Factors used: ", paste(selected_factors, collapse = ", "), "\n",
          "Number of trees: ", ntree, "\n",
          "OOB Error Rate: ", round(oob_error * 100, 2), "%\n",
          "\nConfusion Matrix (Training Data):\n"
        )
        
        mofa_predictions$model_summary <- model_summary
        
        incProgress(1.0, detail = "Complete!")
        
        # Summary of predictions
        n_true <- sum(prediction_source == "True")
        n_predicted <- sum(prediction_source == "Predicted")
        
        showNotification(
          HTML(paste0(
            "✓ Prediction complete!<br/>",
            "• ", n_true, " samples with known labels<br/>",
            "• ", n_predicted, " samples with imputed labels<br/>",
            "• OOB Error: ", round(oob_error * 100, 2), "%"
          )),
          type = "message",
          duration = 8
        )
        
      }, error = function(e) {
        showNotification(paste("Prediction error:", e$message), type = "error", duration = 10)
      })
    })
  })
  
  # Clear predictions
  observeEvent(input$mofa_clear_predictions, {
    mofa_predictions$rf_model <- NULL
    mofa_predictions$target_variable <- NULL
    mofa_predictions$predicted_values <- NULL
    mofa_predictions$prediction_source <- NULL
    mofa_predictions$factors_used <- NULL
    mofa_predictions$model_summary <- NULL
    mofa_predictions$results_df <- NULL
    
    showNotification("Predictions cleared", type = "message", duration = 3)
  })
  
  # Render model summary
  output$mofa_pred_model_summary <- renderText({
    if (is.null(mofa_predictions$rf_model)) {
      return("No model trained yet. Select a target variable and click 'Train Model & Predict'.")
    }
    
    rf_model <- mofa_predictions$rf_model
    target_var <- mofa_predictions$target_variable
    factors_used <- mofa_predictions$factors_used
    
    oob_error <- rf_model$err.rate[nrow(rf_model$err.rate), "OOB"]
    
    paste0(
      "Target: ", target_var, "\n",
      "Factors: ", paste(factors_used, collapse = ", "), "\n",
      "Trees: ", rf_model$ntree, "\n",
      "OOB Error Rate: ", round(oob_error * 100, 2), "%\n\n",
      "Confusion Matrix (Training):\n",
      paste(capture.output(print(rf_model$confusion)), collapse = "\n")
    )
  })
  
  # Render prediction summary
  output$mofa_pred_summary <- renderText({
    req(mofa_predictions$results_df)
    
    results <- mofa_predictions$results_df
    target_var <- mofa_predictions$target_variable
    
    n_true <- sum(results$Source == "True")
    n_predicted <- sum(results$Source == "Predicted")
    
    pred_counts <- table(results$Predicted[results$Source == "Predicted"])
    pred_summary <- paste(names(pred_counts), ":", pred_counts, collapse = ", ")
    
    paste0(
      "Samples with known ", target_var, ": ", n_true, "\n",
      "Samples with predicted ", target_var, ": ", n_predicted, "\n\n",
      "Predicted class distribution:\n", pred_summary
    )
  })
  
  # Render prediction plot
  output$mofa_pred_plot <- renderPlot({
    req(mofa_predictions$results_df, multiomics$integration_results)
    
    results <- mofa_predictions$results_df
    factor_x <- input$mofa_pred_factor_x %||% mofa_predictions$factors_used[1]
    factor_y <- input$mofa_pred_factor_y %||% mofa_predictions$factors_used[min(2, length(mofa_predictions$factors_used))]
    point_size <- input$mofa_pred_point_size %||% 2.5
    show_missing <- input$mofa_pred_show_missing %||% TRUE
    add_lines <- input$mofa_pred_add_lines %||% TRUE
    line_x <- input$mofa_pred_line_x %||% -0.5
    line_y <- input$mofa_pred_line_y %||% -1
    
    # Check if selected factors are available
    if (!factor_x %in% colnames(results) || !factor_y %in% colnames(results)) {
      return(
        ggplot() +
          annotate("text", x = 0.5, y = 0.5,
                   label = "Selected factors not available in results.\nRun prediction first.",
                   size = 4, color = "#ef4444") +
          theme_void()
      )
    }
    
    # Prepare plot data
    plot_df <- results
    plot_df$Prediction <- plot_df$Predicted
    plot_df$PredictionSource <- factor(plot_df$Source, levels = c("True", "Predicted"))
    
    # Create the plot
    p <- ggplot(plot_df, aes_string(x = factor_x, y = factor_y)) +
      geom_point(aes(color = Prediction, shape = PredictionSource), 
                 size = point_size, alpha = 0.8) +
      scale_shape_manual(values = c("True" = 16, "Predicted" = 17),
                         name = "Label Source") +
      labs(
        x = factor_x,
        y = factor_y,
        color = mofa_predictions$target_variable,
        title = paste("MOFA Factor Plot with", mofa_predictions$target_variable, "Predictions"),
        subtitle = paste("Samples with missing labels predicted using Random Forest on factors:", 
                         paste(mofa_predictions$factors_used, collapse = ", "))
      ) +
      theme_bw() +
      theme(
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 10, color = "gray50"),
        legend.position = "right"
      )
    
    # Add reference lines if requested
    if (add_lines) {
      p <- p +
        geom_hline(yintercept = line_y, linetype = "dashed", color = "gray40", alpha = 0.7) +
        geom_vline(xintercept = line_x, linetype = "dashed", color = "gray40", alpha = 0.7)
    }
    
    print(p)
  }, res = UI_PLOT_RES)
  
  # Render prediction results table
  output$mofa_pred_results_table <- DT::renderDataTable({
    req(mofa_predictions$results_df)
    
    DT::datatable(
      mofa_predictions$results_df,
      options = list(
        pageLength = 15,
        scrollX = TRUE,
        order = list(list(3, 'desc'))  # Sort by Source to show Predicted first
      ),
      rownames = FALSE,
      filter = 'top'
    ) %>%
      DT::formatStyle(
        'Source',
        backgroundColor = DT::styleEqual(c('True', 'Predicted'), c('#e8f5e9', '#fff3e0'))
      )
  })
  
  # Download prediction plot
  output$download_mofa_pred_plot <- downloadHandler(
    filename = function() {
      paste0("mofa_clinical_prediction_", mofa_predictions$target_variable, "_", 
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      req(mofa_predictions$results_df)
      
      dpi <- get_safe_global_dpi()
      results <- mofa_predictions$results_df
      factor_x <- input$mofa_pred_factor_x %||% mofa_predictions$factors_used[1]
      factor_y <- input$mofa_pred_factor_y %||% mofa_predictions$factors_used[min(2, length(mofa_predictions$factors_used))]
      point_size <- input$mofa_pred_point_size %||% 2.5
      add_lines <- input$mofa_pred_add_lines %||% TRUE
      line_x <- input$mofa_pred_line_x %||% -0.5
      line_y <- input$mofa_pred_line_y %||% -1
      
      plot_df <- results
      plot_df$Prediction <- plot_df$Predicted
      plot_df$PredictionSource <- factor(plot_df$Source, levels = c("True", "Predicted"))
      
      p <- ggplot(plot_df, aes_string(x = factor_x, y = factor_y)) +
        geom_point(aes(color = Prediction, shape = PredictionSource), 
                   size = point_size, alpha = 0.8) +
        scale_shape_manual(values = c("True" = 16, "Predicted" = 17),
                           name = "Label Source") +
        labs(
          x = factor_x,
          y = factor_y,
          color = mofa_predictions$target_variable,
          title = paste("MOFA Factor Plot with", mofa_predictions$target_variable, "Predictions")
        ) +
        theme_bw() +
        theme(
          plot.title = element_text(size = 14, face = "bold"),
          legend.position = "right"
        )
      
      if (add_lines) {
        p <- p +
          geom_hline(yintercept = line_y, linetype = "dashed", color = "gray40") +
          geom_vline(xintercept = line_x, linetype = "dashed", color = "gray40")
      }
      
      ggsave(file, plot = p, width = 10, height = 8, dpi = dpi)
    }
  )
  
  # Download prediction results
  output$download_mofa_pred_results <- downloadHandler(
    filename = function() {
      paste0("mofa_clinical_predictions_", mofa_predictions$target_variable, "_",
             format(Sys.time(), "%Y%m%d_%H%M%S"), ".csv")
    },
    content = function(file) {
      req(mofa_predictions$results_df)
      write.csv(mofa_predictions$results_df, file, row.names = FALSE)
      showNotification("Predictions exported successfully", type = "message", duration = 3)
    }
  )
  
  # ============================================================================
  # END MOFA CLINICAL PREDICTION FUNCTIONALITY
  # ============================================================================
  
  # Download handler for factor values plot
  output$download_factor_values <- downloadHandler(
    filename = function() {
      paste0("factor_values_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      dpi <- get_safe_global_dpi()
      scale <- dpi / 100
      
      # Use custom dimensions if enabled
      custom_width <- if (!is.null(input$factor_values_plot_customization) && 
                          input$factor_values_plot_customization && 
                          !is.null(input$factor_values_plot_width)) {
        input$factor_values_plot_width
      } else {
        8  # default width in inches
      }
      
      custom_height <- if (!is.null(input$factor_values_plot_customization) && 
                           input$factor_values_plot_customization && 
                           !is.null(input$factor_values_plot_height)) {
        input$factor_values_plot_height
      } else {
        5.5  # default height in inches
      }
      
      png(file, width = round(custom_width * dpi), height = round(custom_height * dpi), res = dpi)
      print(tryCatch({
        req(multiomics$integration_results, input$factor_values_factor)
        result <- multiomics$integration_results
        
        if (result$method != "mofa" || is.null(result$factors)) {
          return(ggplot() +
                   annotate("text", x = 0.5, y = 0.5,
                            label = "Factor values available for MOFA analysis",
                            size = 5, color = "#667eea") +
                   theme_void())
        }
        
        factor_sel <- input$factor_values_factor %||% character(0)
        color_by <- if (!is.null(input$factor_values_colorby)) input$factor_values_colorby else "value"
        add_violin <- if (!is.null(input$factor_values_violin) && color_by == "covariate") input$factor_values_violin else FALSE
        dodge <- if (!is.null(input$factor_values_dodge)) input$factor_values_dodge else TRUE
        alpha_val <- if (!is.null(input$factor_values_alpha)) input$factor_values_alpha else 0.7
        group_by <- if (!is.null(input$factor_values_group_by)) input$factor_values_group_by else ""
        if (!nzchar(group_by)) group_by <- NULL
        shape_by <- if (!is.null(input$factor_values_shape_by)) input$factor_values_shape_by else ""
        if (!nzchar(shape_by)) shape_by <- NULL

        # Ensure at least one factor is selected
        if (length(factor_sel) == 0) stop("No factors selected")

        # Gather factor data: support single or multiple factors (long format)
        available_factors <- colnames(result$factors)[grepl("^Factor", colnames(result$factors))]
        chosen_factors <- intersect(factor_sel, available_factors)
        if (length(chosen_factors) == 0) stop("Selected factors are not available in the MOFA result")

        # Keep the original sample order from MOFA model
        sample_order <- as.character(result$factors$Sample)

        if (length(chosen_factors) == 1) {
          factor_name <- chosen_factors[1]
          factor_data <- result$factors %>%
            dplyr::select(Sample, all_of(factor_name)) %>%
            dplyr::rename(FactorValue = all_of(factor_name)) %>%
            dplyr::mutate(Factor = factor_name)
        } else {
          # Pivot to long format for faceting
          factor_data <- result$factors %>%
            dplyr::select(Sample, dplyr::any_of(chosen_factors)) %>%
            tidyr::pivot_longer(cols = -Sample, names_to = "Factor", values_to = "FactorValue")
          # preserve factor order
          factor_data$Factor <- factor(factor_data$Factor, levels = chosen_factors)
        }
        
        # Initialize color variable
        color_label <- "Value"
        # Flag to track if we're using categorical covariate (MOFA tutorial style)
        is_categorical_covariate <- FALSE
        
        # Add color, group, and shape variables based on selection
        if (color_by == "covariate") {
          covariate_name <- input$factor_values_covariate

          if (!is.null(mofa_metadata$covariates) && covariate_name %in% colnames(mofa_metadata$covariates)) {
            # FIX: Properly map covariates using rownames (sample IDs) from the covariate data frame
            # When extracting a column from a data frame, R doesn't preserve rownames as element names
            # So we must explicitly set names using rownames to ensure correct sample-to-covariate mapping
            cov_df <- mofa_metadata$covariates
            cov_vec <- setNames(cov_df[[covariate_name]], rownames(cov_df))

            # Map covariate values to factor_data rows by sample
            sample_cov_map <- cov_vec[as.character(factor_data$Sample)]
            names(sample_cov_map) <- NULL

            # Detect numeric covariates (continuous) - use stricter threshold for categorical detection
            cov_numeric_try <- suppressWarnings(as.numeric(as.character(sample_cov_map)))
            num_non_na <- sum(!is.na(cov_numeric_try))
            unique_vals <- length(unique(cov_numeric_try[!is.na(cov_numeric_try)]))
            # More aggressive categorical detection: if <=10 unique values, treat as categorical
            is_cov_numeric <- (num_non_na / max(1, length(cov_numeric_try)) >= 0.8) && (unique_vals > 10)

            if (is_cov_numeric) {
              factor_data <- factor_data %>% mutate(ColorValue = cov_numeric_try)
              is_categorical_covariate <- FALSE
            } else {
              # Categorical covariate - this triggers MOFA tutorial-style beeswarm plot
              factor_data <- factor_data %>% mutate(ColorValue = as.character(sample_cov_map))
              is_categorical_covariate <- TRUE
            }
            color_label <- covariate_name

            # Map grouping (for violin/box displays and group_by axis)
            if (!is.null(group_by) && !is.null(mofa_metadata$covariates) && group_by %in% colnames(mofa_metadata$covariates)) {
              grp_vec <- setNames(cov_df[[group_by]], rownames(cov_df))
              factor_data <- factor_data %>% mutate(GroupValue = as.character(grp_vec[as.character(Sample)]))
            }

            # Map shape aesthetic if requested
            if (!is.null(shape_by) && shape_by %in% colnames(mofa_metadata$covariates)) {
              shp_vec <- setNames(cov_df[[shape_by]], rownames(cov_df))
              factor_data <- factor_data %>% mutate(ShapeValue = as.character(shp_vec[as.character(Sample)]))
            }
          } else {
            factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
          }
        } else if (color_by == "weight") {
          # Feature weight coloring is only supported for a single selected factor; for
          # multi-factor selection we fall back to coloring by factor value.
          if (length(chosen_factors) == 1) {
            feature_name <- input$factor_values_feature
            weights_view <- input$factor_values_weight_view
            if (!is.null(result$weights) && weights_view %in% names(result$weights)) {
              weights_df <- result$weights[[weights_view]]
              if (feature_name %in% weights_df$Feature) {
                feature_weight <- weights_df %>%
                  filter(Feature == feature_name) %>%
                  pull(all_of(chosen_factors[1])) %>%
                  dplyr::first()
                factor_data <- factor_data %>% mutate(ColorValue = feature_weight)
                color_label <- paste0(feature_name, " Weight")
              } else {
                factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
              }
            } else {
              factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
            }
          } else {
            factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
          }
        } else if (color_by == "feature") {
          # Feature-based coloring is only supported for a single factor selection; otherwise fallback
          if (length(chosen_factors) == 1) {
            feature_name <- input$factor_values_feature
            feature_view <- input$factor_values_feature_view
            if (!is.null(multiomics$loaded_analyses) && feature_view %in% names(multiomics$loaded_analyses)) {
              feature_data <- multiomics$loaded_analyses[[feature_view]]$data
              if (feature_name %in% rownames(feature_data)) {
                feature_values <- feature_data[feature_name, ]
                factor_data <- factor_data %>% mutate(ColorValue = feature_values[match(Sample, colnames(feature_data))])
                color_label <- feature_name
              } else {
                factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
              }
            } else {
              factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
            }
          } else {
            factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
          }
        } else {
          factor_data <- factor_data %>% mutate(ColorValue = FactorValue)
        }
        
        # Prepare plot data
        plot_data <- factor_data
        
        # Add shape aesthetic flag (preserve NA as explicit level)
        if ("ShapeValue" %in% colnames(plot_data)) {
          plot_data$ShapeValue <- as.character(plot_data$ShapeValue)
          plot_data$ShapeValue[is.na(plot_data$ShapeValue) | plot_data$ShapeValue == ""] <- "(Missing)"
          plot_data$ShapeValue <- factor(plot_data$ShapeValue)
        }
        has_shape <- "ShapeValue" %in% colnames(plot_data) && !all(is.na(plot_data$ShapeValue))
        
        # ========================================================================
        # MOFA Tutorial-style plotting logic
        # The MOFA2::plot_factor() function creates beeswarm/jitter plots where:
        # - Categorical covariate: X-axis = covariate categories, Y-axis = factor value
        # - Samples are jittered within each category (beeswarm distribution)
        # - Optional violin/boxplot overlays
        # ========================================================================
        
        if (color_by == "covariate" && is_categorical_covariate) {
          # MOFA Tutorial-style: Categorical covariate beeswarm plot
          # X-axis = covariate categories, Y-axis = factor values
          plot_data$ColorValue <- as.character(plot_data$ColorValue)
          plot_data$ColorValue[is.na(plot_data$ColorValue) | plot_data$ColorValue == ""] <- "(Missing)"
          plot_data$ColorValue <- factor(plot_data$ColorValue)

          if ("GroupValue" %in% colnames(plot_data)) {
            plot_data$GroupValue <- as.character(plot_data$GroupValue)
            plot_data$GroupValue[is.na(plot_data$GroupValue) | plot_data$GroupValue == ""] <- "(Missing)"
            plot_data$GroupValue <- factor(plot_data$GroupValue)
          }

          x_var <- if ("GroupValue" %in% colnames(plot_data)) "GroupValue" else "ColorValue"

          # Avoid violin warnings when a group has < 2 samples
          add_violin_effective <- add_violin
          add_boxplot_effective <- isTRUE(input$factor_values_box)
          group_counts <- dplyr::count(plot_data, .data[[x_var]])
          if (isTRUE(add_violin) && any(group_counts$n < 2)) {
            add_violin_effective <- FALSE
            add_boxplot_effective <- TRUE
          }
          
          if (add_violin_effective) {
            # Violin + jitter (MOFA tutorial style: add_violin = TRUE, dodge = TRUE)
            p <- ggplot(plot_data, aes(x = .data[[x_var]], y = FactorValue, fill = ColorValue))
            
            # Add violin first (background)
            p <- p + geom_violin(alpha = 0.5, scale = "width", color = "black", linewidth = 0.3, trim = TRUE)
            
            # Add boxplot if requested
            if (isTRUE(add_boxplot_effective)) {
              p <- p + geom_boxplot(width = 0.15, outlier.shape = NA, fill = "white", 
                                   color = "black", alpha = 0.7)
            }
            
            # Add jittered points on top
            if (has_shape) {
              if (isTRUE(dodge)) {
                p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
              } else {
                p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
              }
            } else {
              if (isTRUE(dodge)) {
                p <- p + geom_jitter(aes(color = ColorValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
              } else {
                p <- p + geom_jitter(aes(color = ColorValue), 
                                    width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
              }
            }
            
          } else {
            # Jitter only (no violin) - classic MOFA beeswarm style
            p <- ggplot(plot_data, aes(x = .data[[x_var]], y = FactorValue, fill = ColorValue))
            
            # Add boxplot if requested (without violin)
            if (isTRUE(add_boxplot_effective)) {
              p <- p + geom_boxplot(alpha = 0.4, outlier.shape = NA, color = "black")
            }
            
            # Add jittered points
            if (has_shape) {
              p <- p + geom_jitter(aes(color = ColorValue, shape = ShapeValue), 
                                  width = 0.25, alpha = alpha_val, size = 2.5, stroke = 0.5)
            } else {
              p <- p + geom_jitter(aes(color = ColorValue), 
                                  width = 0.25, alpha = alpha_val, size = 2.5, stroke = 0.5)
            }
          }
          
          # Apply color scales - use ggplot2's default hue scale to match MOFA2 tutorial style
          # (MOFA2 uses ggplot2 defaults: red/green/blue hue progression)
          n_levels <- nlevels(plot_data$ColorValue)
          if (!is.na(n_levels) && n_levels > 12) {
            # Fallback to rainbow for many levels
            pal <- grDevices::rainbow(n_levels)
            p <- p + scale_fill_manual(values = pal, name = color_label, drop = FALSE) +
              scale_color_manual(values = pal, name = color_label, drop = FALSE)
          } else {
            # Use ggplot2's default hue scale (matches MOFA2 tutorial)
            p <- p + scale_fill_hue(name = color_label, na.value = "grey80") +
              scale_color_hue(name = color_label, na.value = "grey80")
          }

          if (!is.null(group_by) && nzchar(group_by)) {
            p <- p + theme(axis.text.x = element_text(color = "black", angle = 40, vjust = 1, hjust = 1))
          }

          # Add vertical separators between groups when requested
          if (isTRUE(input$factor_values_show_separators)) {
            sep_levels <- if ("GroupValue" %in% colnames(plot_data)) nlevels(plot_data$GroupValue) else nlevels(plot_data$ColorValue)
            if (!is.null(sep_levels) && sep_levels > 1) {
              sep_pos <- seq_len(sep_levels - 1) + 0.5
              p <- p + geom_vline(xintercept = sep_pos, color = "grey80", linetype = "solid", size = 0.4)
            }
          }
          
          # Add horizontal line at y=0 (MOFA tutorial style)
          p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
          
        } else if (color_by == "covariate" && !is_categorical_covariate) {
          # Continuous covariate: scatter plot with color gradient
          # If group_by is provided, use it for the x-axis grouping (MOFA style)
          if ("GroupValue" %in% colnames(plot_data)) {
            plot_data$GroupValue <- as.character(plot_data$GroupValue)
            plot_data$GroupValue[is.na(plot_data$GroupValue) | plot_data$GroupValue == ""] <- "(Missing)"
            plot_data$GroupValue <- factor(plot_data$GroupValue)

            # Split NA vs non-NA to avoid dropping points
            na_points <- plot_data[is.na(plot_data$ColorValue), , drop = FALSE]
            non_na_points <- plot_data[!is.na(plot_data$ColorValue), , drop = FALSE]

            if (has_shape) {
              p <- ggplot(non_na_points, aes(x = GroupValue, y = FactorValue, color = ColorValue, shape = ShapeValue)) +
                geom_jitter(width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            } else {
              p <- ggplot(non_na_points, aes(x = GroupValue, y = FactorValue, color = ColorValue)) +
                geom_jitter(width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5)
            }

            if (nrow(na_points) > 0) {
              p <- p + geom_jitter(data = na_points, aes(x = GroupValue, y = FactorValue),
                                 width = 0.2, alpha = alpha_val, size = 2.5, stroke = 0.5, color = "grey80")
            }
          } else {
            sample_levels <- unique(result$factors$Sample)
            sample_index_map <- setNames(seq_along(sample_levels), sample_levels)
            plot_data$SampleIndex <- sample_index_map[as.character(plot_data$Sample)]

            na_points <- plot_data[is.na(plot_data$ColorValue), , drop = FALSE]
            non_na_points <- plot_data[!is.na(plot_data$ColorValue), , drop = FALSE]

            if (has_shape) {
              p <- ggplot(non_na_points, aes(x = SampleIndex, y = FactorValue, color = ColorValue, shape = ShapeValue)) +
                geom_point(size = 3, alpha = alpha_val)
            } else {
              p <- ggplot(non_na_points, aes(x = SampleIndex, y = FactorValue, color = ColorValue)) +
                geom_point(size = 3, alpha = alpha_val)
            }

            if (nrow(na_points) > 0) {
              p <- p + geom_point(data = na_points, aes(x = SampleIndex, y = FactorValue),
                                 size = 3, alpha = alpha_val, color = "grey80")
            }
          }
          p <- p + scale_color_gradientn(colors = c("#3b82f6", "#fbbf24", "#ef4444"), name = color_label, na.value = "grey80")
          if (!is.null(group_by) && nzchar(group_by) && "GroupValue" %in% colnames(plot_data)) {
            p <- p + theme(axis.text.x = element_text(color = "black", angle = 40, vjust = 1, hjust = 1))
          }

          # Add vertical separators between groups when requested
          if (isTRUE(input$factor_values_show_separators) && "GroupValue" %in% colnames(plot_data)) {
            sep_levels <- nlevels(plot_data$GroupValue)
            if (!is.null(sep_levels) && sep_levels > 1) {
              sep_pos <- seq_len(sep_levels - 1) + 0.5
              p <- p + geom_vline(xintercept = sep_pos, color = "grey80", linetype = "solid", size = 0.4)
            }
          }
          p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
          
        } else if (color_by == "value") {
          # Color by factor value itself - keep original order (do not sort)
          plot_data$SampleIndex <- seq_len(nrow(plot_data))
          
          p <- ggplot(plot_data, aes(x = SampleIndex, y = FactorValue, color = FactorValue)) +
            geom_point(size = 3, alpha = alpha_val) +
            scale_color_gradient2(
              low = "#3b82f6", mid = "#fbbf24", high = "#ef4444",
              midpoint = 0, name = "Factor Value"
            ) +
            geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
          
        } else {
          # Default: scatter plot with sample index, colored by ColorValue
          sample_levels <- unique(result$factors$Sample)
          sample_index_map <- setNames(seq_along(sample_levels), sample_levels)
          plot_data$SampleIndex <- sample_index_map[as.character(plot_data$Sample)]
          
          p <- ggplot(plot_data, aes(x = SampleIndex, y = FactorValue, color = ColorValue)) +
            geom_point(size = 3, alpha = alpha_val)
          
          if (is.numeric(plot_data$ColorValue)) {
            p <- p + scale_color_gradient2(
              low = "#3b82f6", mid = "#fbbf24", high = "#ef4444",
              midpoint = median(plot_data$ColorValue, na.rm = TRUE),
              name = color_label
            )
          } else {
            p <- p + scale_color_brewer(palette = "Set2", name = color_label)
          }
          p <- p + geom_hline(yintercept = 0, linetype = "dashed", linewidth = 0.3, alpha = 0.5)
        }
        
        # Faceting: when multiple factors are selected, arrange side-by-side in a grid
        # - Use a shared y-axis (fixed scales)
        # - Show each factor as a facet with its own strip title
        # - Keep a shared legend
        # - Draw borders around panels so all four borders show
        if (length(chosen_factors) > 1) {
          # Compute number of columns for the facet grid: prefer up to 3 columns for readability
          n_cols <- min(3, length(chosen_factors))

          # Shared y limits across facets
          y_limits <- range(plot_data$FactorValue, na.rm = TRUE)

          p <- p +
            facet_wrap(~ Factor, ncol = n_cols, scales = "fixed", strip.position = "top", labeller = labeller(Factor = label_value)) +
            coord_cartesian(ylim = y_limits)

          # Ensure strip title is visible per panel and add borders; draw borders on top of geoms
          p <- p + theme(
            strip.background = element_rect(fill = "#f0f0f0", color = "black", linewidth = 0.5),
            strip.text = element_text(face = "bold", size = rel(0.9)),
            panel.border = element_rect(color = "black", fill = NA, linewidth = 0.5),
            panel.spacing = unit(0.6, "lines"),
            panel.background = element_rect(fill = "white"),
            panel.ontop = TRUE,
            plot.background = element_rect(fill = NA, color = "black")
          )
        }

        # Add labels and theme
        custom_title <- if (!is.null(input$factor_values_plot_customization) && 
                            input$factor_values_plot_customization && 
                            !is.null(input$factor_values_plot_title) && 
                            nzchar(input$factor_values_plot_title)) {
          input$factor_values_plot_title
        } else {
          # If multiple factors are plotted, rely on facet strip titles and use a generic main title
          if (length(chosen_factors) == 1) paste0("Factor Values - ", chosen_factors) else "Factor Values"
        }
        
        custom_y_title <- if (!is.null(input$factor_values_plot_customization) && 
                              input$factor_values_plot_customization && 
                              !is.null(input$factor_values_axis_title) && 
                              nzchar(input$factor_values_axis_title)) {
          input$factor_values_axis_title
        } else {
          if (length(chosen_factors) == 1) chosen_factors[1] else "Factor value"
        }
        
        title_size <- if (!is.null(input$factor_values_plot_customization) && 
                          input$factor_values_plot_customization && 
                          !is.null(input$factor_values_title_size)) {
          input$factor_values_title_size
        } else {
          14
        }
        
        axis_text_size <- if (!is.null(input$factor_values_plot_customization) && 
                              input$factor_values_plot_customization && 
                              !is.null(input$factor_values_axis_text_size)) {
          input$factor_values_axis_text_size
        } else {
          10
        }
        
        p <- p +
          labs(
            title = custom_title,
            subtitle = paste0("Color: ", color_label, ifelse(add_violin, " (with distribution)", "")),
            y = custom_y_title
          ) +
          theme_classic() +
          theme(
            plot.title = element_text(size = title_size, face = "bold", hjust = 0.5),
            plot.subtitle = element_text(size = 11, hjust = 0.5),
            legend.position = "right",
            axis.text = element_text(size = axis_text_size, color = "black"),
            axis.title = element_text(size = axis_text_size),
            panel.border = element_rect(color = "black", linewidth = 0.1, fill = NA),
            axis.line = element_line(color = "black", linewidth = 0.25),
            axis.ticks = element_line(color = "black")
          )
        
        # Handle x-axis labels based on plot type (MOFA tutorial style)
        if (color_by == "covariate" && is_categorical_covariate) {
          # Categorical covariate: show category labels on x-axis (group_by if provided)
          x_label <- if (!is.null(group_by) && nzchar(group_by)) group_by else color_label
          p <- p + labs(x = x_label)
        } else if (color_by == "covariate" && !is_categorical_covariate) {
          # Continuous covariate: show group_by on x-axis if provided; otherwise hide sample index
          if (!is.null(group_by) && nzchar(group_by)) {
            p <- p + labs(x = group_by)
          } else {
            p <- p + theme(
              axis.title.x = element_blank(),
              axis.text.x = element_blank(),
              axis.ticks.x = element_blank()
            )
          }
        } else if (color_by == "value") {
          # Factor value: hide sample index
          p <- p + theme(
            axis.title.x = element_blank(),
            axis.text.x = element_blank(),
            axis.ticks.x = element_blank()
          )
        } else {
          # Default: hide x-axis for scatter plots
          p <- p + theme(
            axis.title.x = element_blank(),
            axis.text.x = element_blank(),
            axis.ticks.x = element_blank()
          )
        }

        # Add horizontal reference line at y=0 if enabled (in addition to default)
        if (isTRUE(input$factor_values_show_zero)) {
          # Already added in the plotting logic above, but keep for backwards compatibility
        }

        p <- apply_mofa_text_fix(p)
        p
        
      }, error = function(e) ggplot()))
      dev.off()
    }
  )
  
