  # Keep diablo plotVar color selector in sync with model block count
  observe({
    model <- NULL
    if (!is.null(diablo_tutorial$final_model)) {
      model <- diablo_tutorial$final_model
    } else if (!is.null(multiomics$integration_results)) {
      res <- multiomics$integration_results
      # Only process if it's a DIABLO model (not MOFA or other S4 objects)
      if (!is.null(res$method) && res$method == "diablo") {
        model <- res$final_model %||% res$model
      }
    }
    if (!is.null(model) && !is.null(model$X)) {
      n_blocks <- length(model$X)
      default_colors <- c('darkorchid','brown1','lightgreen','dodgerblue','firebrick','gold','darkgreen','purple','orange','pink')
      current_sel <- isolate(input$diablo_plotvar_col)
      # Update only when selection is empty, mismatched length, or still the original default triple
      if (is.null(current_sel) || length(current_sel) == 0 || length(current_sel) != n_blocks ||
          (length(current_sel) == 3 && all(current_sel == c('darkorchid','brown1','lightgreen')))) {
        updateSelectizeInput(session, 'diablo_plotvar_col', selected = head(default_colors, n_blocks))
      }
    }
  })

  # DIABLO plotVar output
  output$diablo_plotvar <- renderPlot({ 
    req(input$diablo_final_plot_type == "plotvar")
    generate_pch <- function(n_blocks) {
      pch_options <- c(16, 17, 15, 18, 19, 20, 21, 22, 23, 24)
      rep_len(pch_options, n_blocks)
    }
    
    # Helper function to generate cex values dynamically based on number of blocks and variables per block
    generate_cex <- function(model, cex_value = 2) {
      n_vars_per_block <- sapply(model$X, ncol)
      lapply(n_vars_per_block, function(n_vars) rep(cex_value, n_vars))
    }
    
    if (diablo_tutorial$active) {
      # Tutorial mode - show tutorial plotVar
      req(diablo_tutorial$final_model)
      tryCatch({
        # Get number of blocks from model
        n_blocks <- length(diablo_tutorial$final_model$X)
        
        # Generate pch and cex dynamically
        pch_vec <- generate_pch(n_blocks)
        cex_vec <- generate_cex(diablo_tutorial$final_model, input$diablo_plotvar_cex)
        
        # Get colors from input or use defaults
        col_input <- if (!is.null(input$diablo_plotvar_col) && length(input$diablo_plotvar_col) > 0) {
          input$diablo_plotvar_col
        } else {
          c('darkorchid', 'brown1', 'lightgreen')  # default list
        }

        # Normalize to exactly n_blocks colors (take first n_blocks, or repeat if fewer)
        col_input <- rep_len(col_input, n_blocks)[seq_len(n_blocks)]

        # Build a list of colors matching number of variables per block (plotVar accepts per-block colors)
        n_vars_per_block <- sapply(diablo_tutorial$final_model$X, ncol)
        col_list <- lapply(seq_len(n_blocks), function(i) rep(col_input[i], n_vars_per_block[i]))

        # Call plotVar with all parameters; capture ggplot object when using ggplot2 style so we can fix legend keys
        p <- mixOmics::plotVar(diablo_tutorial$final_model,
                          comp = 1:2,
                          cutoff = input$diablo_plotvar_cutoff,
                          var.names = input$diablo_plotvar_names,
                          style = input$diablo_plotvar_style,
                          legend = input$diablo_plotvar_legend,
                          pch = pch_vec,
                          cex = cex_vec,
                          col = col_list)
        if (inherits(p, "ggplot")) {
          # Ensure legend keys reflect the shapes used in the plot
          override_size <- tryCatch({ median(unlist(cex_vec)) * 3 }, error = function(e) 4)
          p <- p + ggplot2::guides(
            shape = ggplot2::guide_legend(override.aes = list(shape = pch_vec, size = override_size)),
            colour = ggplot2::guide_legend(override.aes = list(shape = pch_vec, size = override_size)),
            fill = ggplot2::guide_legend(override.aes = list(shape = pch_vec, size = override_size))
          )
          print(p)
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, paste("Error in plotVar:", e$message))
      }, res = UI_PLOT_RES)
    } else {
      # Normal mode - show user's DIABLO results
      req(multiomics$integration_results, input$diablo_plotvar_col)
      result <- multiomics$integration_results
      
      # Check for final_model or model
      model <- result$final_model %||% result$model
      
      if (result$method == "diablo" && !is.null(model)) {
        tryCatch({
          # Get number of blocks from model
          n_blocks <- length(model$X)
          
          # Generate pch and cex dynamically
          pch_vec <- generate_pch(n_blocks)
          cex_vec <- generate_cex(model, input$diablo_plotvar_cex)
          
            # Get colors from input or use defaults
          col_input <- if (!is.null(input$diablo_plotvar_col) && length(input$diablo_plotvar_col) > 0) {
            input$diablo_plotvar_col
          } else {
            c('darkorchid', 'brown1', 'lightgreen')  # default list
          }

          # Normalize to exactly n_blocks colors
          col_input <- rep_len(col_input, n_blocks)[seq_len(n_blocks)]

          # Build per-block color list
          n_vars_per_block <- sapply(model$X, ncol)
          col_list <- lapply(seq_len(n_blocks), function(i) rep(col_input[i], n_vars_per_block[i]))
          
          # Call plotVar with all parameters
          mixOmics::plotVar(model,
                            comp = 1:2,
                            cutoff = input$diablo_plotvar_cutoff,
                            var.names = input$diablo_plotvar_names,
                            style = input$diablo_plotvar_style,
                            legend = input$diablo_plotvar_legend,
                            pch = pch_vec,
                            cex = cex_vec,
