                               size.labels = input$diablo_circos_size_labels)
        } else {
          # Normal mode
          req(multiomics$integration_results)
          result <- multiomics$integration_results
          if (result$method == "diablo" && !is.null(result$model)) {
            # Use the input vectors directly
            color_blocks_vec <- input$diablo_circos_color_blocks
            if (is.null(color_blocks_vec) || length(color_blocks_vec) == 0) {
              # Default colors for blocks - circosPlot expects exactly 3 colors
              color_blocks_vec <- c('darkorchid', 'brown1', 'lightgreen')
            } else {
              # Ensure exactly 3 colors for circosPlot
              if (length(color_blocks_vec) > 3) {
                color_blocks_vec <- color_blocks_vec[1:3]
              } else if (length(color_blocks_vec) < 3) {
                # Pad with defaults if needed
                default_colors <- c('darkorchid', 'brown1', 'lightgreen')
                color_blocks_vec <- c(color_blocks_vec, default_colors)[1:3]
              }
            }
            
            color_cor_vec <- input$diablo_circos_color_cor
            if (is.null(color_cor_vec) || length(color_cor_vec) == 0) {
              color_cor_vec <- c("chocolate3", "grey20")  # default
            }
            # Ensure exactly 2 colors for correlations
            if (length(color_cor_vec) < 2) {
              color_cor_vec <- c(color_cor_vec, c("chocolate3", "grey20"))[1:2]
            }
            
            # Call circosPlot with all parameters
            mixOmics::circosPlot(result$model,
                                 cutoff = input$diablo_circos_cutoff,
                                 line = input$diablo_circos_line,
                                 color.blocks = color_blocks_vec,
                                 color.cor = color_cor_vec,
                                 size.labels = input$diablo_circos_size_labels)
          } else {
            plot.new()
            text(0.5, 0.5, "No DIABLO model available")
          }
        }
      }, error = function(e) {
        plot.new()
        text(0.5, 0.5, "circosPlot visualization")
      })
      dev.off()
    }
  )

