  # GML download handler for Cytoscape compatibility
  output$download_diablo_network_gml <- downloadHandler(
    filename = function() {
      paste0("diablo_network_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".gml")
    },
    content = function(file) {
      tryCatch({
        # Ensure igraph is available
        if (!requireNamespace("igraph", quietly = TRUE)) {
          stop("igraph package is required for GML export")
        }
        
        # Parse the input vectors
        blocks_vec <- tryCatch({
          as.numeric(strsplit(input$diablo_network_blocks, ",")[[1]])
        }, error = function(e) {
          c(1, 2, 3)  # default
        })
        
        color_node_vec <- input$diablo_network_color_node
        if (is.null(color_node_vec) || length(color_node_vec) == 0) {
          color_node_vec <- c('darkorchid', 'brown1', 'lightgreen')  # default
        }
        
        # Extract data from DIABLO model to create network
        model <- diablo_tutorial$final_model
        block_names <- names(model$names$blocks)
        selected_blocks <- block_names[blocks_vec]
        
        # Create nodes from selected blocks
        nodes <- data.frame()
        node_id <- 1
        
        for (i in seq_along(selected_blocks)) {
          block <- selected_blocks[i]
          loadings <- model$loadings[[block]]
          
          if (!is.null(loadings) && nrow(loadings) > 0) {
            # Take top variables by absolute loading value
            top_vars <- order(abs(loadings[,1]), decreasing = TRUE)[1:min(50, nrow(loadings))]
            var_names <- rownames(loadings)[top_vars]
            
            block_nodes <- data.frame(
              id = node_id:(node_id + length(var_names) - 1),
              label = var_names,
              block = block,
              color = color_node_vec[i],
              loading = abs(loadings[var_names, 1]),
              stringsAsFactors = FALSE
            )
            nodes <- rbind(nodes, block_nodes)
            node_id <- node_id + length(var_names)
          }
        }
        
        # Create edges based on correlations between variables from different blocks
        edges <- data.frame()
        edge_id <- 1
        
        # Get the original data matrices
        X_data <- model$X
        
        if (length(selected_blocks) >= 2 && !is.null(X_data)) {
          for (i in 1:(length(selected_blocks) - 1)) {
            for (j in (i + 1):length(selected_blocks)) {
              block1 <- selected_blocks[i]
              block2 <- selected_blocks[j]
              
              # Get variables from each block
              vars1 <- nodes$label[nodes$block == block1]
              vars2 <- nodes$label[nodes$block == block2]
              
              # Calculate correlations between variables from different blocks
              if (length(vars1) > 0 && length(vars2) > 0 && 
                  all(vars1 %in% colnames(X_data[[block1]])) && 
                  all(vars2 %in% colnames(X_data[[block2]]))) {
                
                data1 <- X_data[[block1]][, vars1, drop = FALSE]
                data2 <- X_data[[block2]][, vars2, drop = FALSE]
                
                # Calculate correlation matrix
                cor_mat <- cor(data1, data2, use = "pairwise.complete.obs")
                
                # Create edges for correlations above cutoff
                high_cor <- which(abs(cor_mat) > input$diablo_network_cutoff, arr.ind = TRUE)
                
                if (nrow(high_cor) > 0) {
                  for (k in 1:nrow(high_cor)) {
                    var1 <- vars1[high_cor[k, 1]]
                    var2 <- vars2[high_cor[k, 2]]
                    
                    source_id <- nodes$id[nodes$label == var1 & nodes$block == block1]
                    target_id <- nodes$id[nodes$label == var2 & nodes$block == block2]
                    
                    if (length(source_id) > 0 && length(target_id) > 0) {
                      edges <- rbind(edges, data.frame(
                        id = edge_id,
                        source = source_id[1],
                        target = target_id[1],
                        weight = cor_mat[high_cor[k, 1], high_cor[k, 2]],
                        correlation = cor_mat[high_cor[k, 1], high_cor[k, 2]],
                        stringsAsFactors = FALSE
                      ))
                      edge_id <- edge_id + 1
                    }
                  }
                }
              }
            }
          }
        }
        
        # Create igraph object and save as GML
        if (nrow(nodes) > 0) {
          if (nrow(edges) > 0) {
            g <- igraph::graph_from_data_frame(edges, directed = FALSE, vertices = nodes)
          } else {
            # No edges found, create graph with isolated nodes
            g <- igraph::graph_from_data_frame(data.frame(), directed = FALSE, vertices = nodes)
          }
          
          # Add node attributes
          igraph::V(g)$block <- nodes$block
          igraph::V(g)$color <- nodes$color
          igraph::V(g)$loading <- nodes$loading
          
          # Add edge attributes if edges exist
          if (nrow(edges) > 0) {
            igraph::E(g)$correlation <- edges$correlation
            igraph::E(g)$weight <- abs(edges$weight)
          }
          
          igraph::write.graph(g, file, format = "gml")
        } else {
          stop("No variable data available for GML export")
        }
        
      }, error = function(e) {
        # Create a minimal GML file as fallback
        warning("Error creating GML file: ", e$message, ". Creating minimal GML file.")
        nodes <- data.frame(id = 1, label = "error_node", block = "error", color = "gray", loading = 0)
        edges <- data.frame(source = integer(0), target = integer(0), weight = numeric(0))
        g <- igraph::graph_from_data_frame(edges, directed = FALSE, vertices = nodes)
        igraph::write.graph(g, file, format = "gml")
      })
    }
  )

  # ===== METABOLOMICS ID MAPPING FUNCTIONS =====
  
  # Helper function to clean molecule names
  clean_molecule_name <- function(name) {
    if (is.na(name) || name == "") return("")
    name <- gsub("β", "beta", name)
    name <- gsub("α", "alpha", name)
    name <- sub("^\\(([^)]*)\\)-+", "", name)
    name <- sub("^\\(([^)]*)\\)-+", "", name)
    str_trim(name)
  }
  
  # Function to get KEGG ID
  
  # ============================================================================
  # K-MEANS CLUSTERING ANALYSIS
  # ============================================================================
  
  # Reactive to update K-Means group selections
  observe({
    req(values$unique_groups)
    groups <- values$unique_groups
    updateSelectizeInput(session, "kmeans_group1", choices = groups, selected = groups[1])
    updateSelectizeInput(session, "kmeans_group2", choices = groups, selected = if(length(groups) > 1) groups[2] else groups[1])
  })
  
  # Toggle pairwise options visibility for K-Means
  observe({
    if (input$kmeans_analysis_type == "pairwise") {
      shinyjs::show("kmeansPairwiseOptions")
    } else {
      shinyjs::hide("kmeansPairwiseOptions")
    }
  })
  
  # Grouping toggle UI for K-Means
  output$kmeans_grouping_toggle_ui <- renderUI({
    req(values$has_dual_grouping)
    if (!values$has_dual_grouping) return(NULL)
    
    div(class = "grouping-toggle-container",
