        tags$span("View Results By:", style = "font-weight: 500; color: #495057;"),
        radioButtons("kmeans_grouping_level", NULL,
                     choices = c("Biological Groups" = "biological",
                                 "Experimental Groups" = "experimental"),
                     selected = values$active_grouping_level,
                     inline = TRUE)
    )
  })
  
  # K-Means feature set status
  output$kmeans_feature_set_status <- renderUI({
    source <- input$kmeans_feature_source
    if (is.null(source) || source == "all") return(NULL)
    
    if (source == "pca" && !is.null(values$selected_features$features) && values$selected_features$source == "pca") {
      n <- length(values$selected_features$features)
      tags$span(paste0("Using ", n, " PCA-selected features"), style = "color: #28a745; font-size: 0.85em;")
    } else if (source == "ml" && !is.null(values$selected_features$features) && values$selected_features$source == "ml") {
      n <- length(values$selected_features$features)
      tags$span(paste0("Using ", n, " ML-selected features"), style = "color: #28a745; font-size: 0.85em;")
    } else {
      tags$span("No features selected. Run PCA/ML first.", style = "color: #dc3545; font-size: 0.85em;")
    }
  })
  
  # Reactive for K-Means filtered data
  kmeans_filtered_data <- reactive({
    req(values$normalized_data, values$stat_results)
    
    # Load visualization packages if needed
    load_package_group("visualization")
    
    stat_results <- get_active_stat_results()
    req(stat_results)
    
    normalized_data <- values$normalized_data
    
    # Determine which comparison to use
    if (input$kmeans_analysis_type == "pairwise") {
      req(input$kmeans_group1, input$kmeans_group2)
      comparison_name <- paste(input$kmeans_group1, "vs", input$kmeans_group2)
      
      # Use helper functions to find p-value and fold change columns
      pval_col <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Check if columns were found
      if (is.null(pval_col) || is.null(fc_column_result)) {
        showNotification("Could not find statistics for selected comparison.", type = "error")
        return(NULL)
      }
      
      # Handle reversed fold change columns
      is_reversed <- FALSE
      if (grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_col <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_col <- fc_column_result
      }
      
      # Verify columns exist in stat_results
      if (!pval_col %in% colnames(stat_results) || !fc_col %in% colnames(stat_results)) {
        showNotification("Could not find statistics for selected comparison.", type = "error")
        return(NULL)
      }
      
      p_values <- stat_results[[pval_col]]
      log2_fc <- stat_results[[fc_col]]
      
      # Negate fold change if reversed
      if (is_reversed) {
        log2_fc <- -log2_fc
      }
      
      # Find FDR column if ROTS
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        fdr_col <- paste0(comparison_name, "_FDR")
        alt_comparison_name <- paste(input$kmeans_group2, "vs", input$kmeans_group1)
        alt_fdr_col <- paste0(alt_comparison_name, "_FDR")
        
        if (fdr_col %in% colnames(stat_results)) {
          fdr_values <- stat_results[[fdr_col]]
        } else if (alt_fdr_col %in% colnames(stat_results)) {
          fdr_values <- stat_results[[alt_fdr_col]]
        }
      }
      
    } else {
      # All groups - use helper function for global p-value
      pval_col <- get_appropriate_pvalue_column("Global")
      
      if (is.null(pval_col) || !pval_col %in% colnames(stat_results)) {
        showNotification("No statistical results found. Run analysis first.", type = "error")
        return(NULL)
      }
      
      p_values <- stat_results[[pval_col]]
      
      # Find all Log2FC columns for max calculation
      fc_col <- grep("_Log2FC$|Max_Log2FC", colnames(stat_results), value = TRUE)
      
      # Use maximum absolute log2FC
      if (length(fc_col) > 0) {
        log2_fc <- apply(abs(stat_results[, fc_col, drop = FALSE]), 1, max, na.rm = TRUE)
      } else {
        log2_fc <- rep(Inf, nrow(stat_results))  # No FC filter if not available
      }
      
      # Find FDR columns if ROTS
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        fdr_col <- grep("_FDR$", colnames(stat_results), value = TRUE)
        if (length(fdr_col) > 0) {
          fdr_values <- apply(stat_results[, fdr_col, drop = FALSE], 1, min, na.rm = TRUE)
        }
      }
    }
    
    # Apply filters
    filter_idx <- !is.na(p_values) & p_values < input$kmeans_pvalue_cutoff & 
                  !is.na(log2_fc) & abs(log2_fc) >= input$kmeans_fc_cutoff
    
    # Apply FDR filter if ROTS
    if (input$sig_method == "rots" && !is.null(fdr_values)) {
      fdr_cutoff <- input$kmeans_fdr_cutoff %||% 0.05
      filter_idx <- filter_idx & !is.na(fdr_values) & fdr_values < fdr_cutoff
    }
    
    # Apply feature source filter
    if (input$kmeans_feature_source != "all" && !is.null(values$selected_features$features)) {
      if (input$kmeans_feature_source == values$selected_features$source) {
        feature_idx <- which(values$cleaned_molecules %in% values$selected_features$features)
        filter_idx <- filter_idx & (seq_along(filter_idx) %in% feature_idx)
      }
    }
    
    significant_idx <- which(filter_idx)
    
    if (length(significant_idx) < 3) {
      showNotification("Not enough significant features for clustering (need at least 3).", type = "warning")
      return(NULL)
    }
    
    # Get data for significant features
    filtered_data <- normalized_data[significant_idx, , drop = FALSE]
    
    # Use cleaned molecule names as row names
    if (!is.null(values$cleaned_molecules)) {
      rownames(filtered_data) <- make.unique(values$cleaned_molecules[significant_idx])
    }
    
    # Use only numeric columns (avoid colMeans/scale errors from character columns)
    num_cols <- which(sapply(seq_len(ncol(filtered_data)), function(j) is.numeric(filtered_data[, j])))
    if (length(num_cols) == 0) {
      showNotification("No numeric columns in data for k-means.", type = "error")
      return(NULL)
    }
    
    # Get group means for each condition (only from numeric columns)
    group_indices <- values$group_column_indices
    group_names <- names(group_indices)
    
    group_means <- sapply(group_names, function(g) {
      cols <- group_indices[[g]]
      cols <- intersect(cols, num_cols)
      if (length(cols) == 0) return(rep(NA_real_, nrow(filtered_data)))
      part <- filtered_data[, cols, drop = FALSE]
      if (ncol(part) > 1) rowMeans(part, na.rm = TRUE) else as.numeric(part[, 1])
    })
    
    if (!is.matrix(group_means)) {
      group_means <- matrix(group_means, nrow = nrow(filtered_data), dimnames = list(rownames(filtered_data), group_names))
    } else {
      rownames(group_means) <- rownames(filtered_data)
    }
    # Ensure numeric matrix for scale()/kmeans()
    storage.mode(group_means) <- "double"
    # Drop rows that are all NA (e.g. group had no numeric cols)
    if (anyNA(group_means)) {
      ok <- rowSums(!is.finite(group_means)) < ncol(group_means)
      if (!all(ok)) group_means <- group_means[ok, , drop = FALSE]
    }
    if (nrow(group_means) < 3) {
      showNotification("Not enough numeric features for clustering (need at least 3).", type = "warning")
      return(NULL)
    }
    
    list(
      data = filtered_data,
      group_means = group_means,
      significant_idx = significant_idx,
      n_features = length(significant_idx)
    )
  })
  
  # Reactive for K-Means clustering result
  kmeans_result <- reactive({
    req(kmeans_filtered_data())
    
    data_list <- kmeans_filtered_data()
    group_means <- as.matrix(data_list$group_means)
    if (!is.numeric(group_means)) {
      group_means <- matrix(as.numeric(as.character(group_means)), nrow = nrow(group_means), ncol = ncol(group_means), dimnames = dimnames(group_means))
    }
    if (any(!is.finite(group_means))) group_means[!is.finite(group_means)] <- NA
    if (nrow(group_means) < input$kmeans_num_clusters) {
      showNotification(paste("Not enough features for", input$kmeans_num_clusters, "clusters."), type = "warning")
      return(NULL)
    }
    
    # Scale data if requested
    if (input$kmeans_scale_data) {
      scaled_data <- t(scale(t(group_means)))
      # Handle cases where variance is 0
      scaled_data[is.nan(scaled_data)] <- 0
    } else {
      scaled_data <- group_means
    }
    
    # Check for distinct data points
    # Remove duplicate rows (identical features)
    unique_data <- unique(scaled_data)
    n_unique <- nrow(unique_data)
    
    if (n_unique < input$kmeans_num_clusters) {
      showNotification(
        paste0("Cannot create ", input$kmeans_num_clusters, " clusters from ", n_unique, 
               " distinct data points. Please reduce the number of clusters or adjust filtering criteria."), 
        type = "error", duration = 8)
      return(NULL)
    }
    
    # Perform K-Means clustering
    set.seed(123)  # For reproducibility
    km_result <- tryCatch({
      kmeans(scaled_data, centers = input$kmeans_num_clusters, 
             nstart = input$kmeans_nstart, iter.max = input$kmeans_max_iter)
    }, error = function(e) {
      # Provide more helpful error message
      if (grepl("more cluster centers than distinct data points", e$message, ignore.case = TRUE)) {
        showNotification(
          paste0("Error: Cannot create ", input$kmeans_num_clusters, " clusters. ",
                 "You have ", n_unique, " distinct data points. ",
                 "Please reduce the number of clusters or adjust filtering criteria."), 
          type = "error", duration = 8)
      } else {
        showNotification(paste("K-Means error:", e$message), type = "error", duration = 8)
      }
      return(NULL)
    })
    
    if (is.null(km_result)) return(NULL)
    
    list(
      kmeans = km_result,
      scaled_data = scaled_data,
      original_data = group_means,
      cluster_assignments = km_result$cluster,
      feature_names = rownames(group_means)
    )
  })
  
  # Elbow plot data
  kmeans_elbow_data <- reactive({
    req(kmeans_filtered_data())
    
    data_list <- kmeans_filtered_data()
    group_means <- as.matrix(data_list$group_means)
    if (!is.numeric(group_means)) {
      group_means <- matrix(as.numeric(as.character(group_means)), nrow = nrow(group_means), ncol = ncol(group_means), dimnames = dimnames(group_means))
    }
    if (any(!is.finite(group_means))) group_means[!is.finite(group_means)] <- NA
    if (nrow(group_means) < 3) return(NULL)
    
    # Scale data
    if (input$kmeans_scale_data) {
      scaled_data <- t(scale(t(group_means)))
      scaled_data[is.nan(scaled_data)] <- 0
    } else {
      scaled_data <- group_means
    }
    
    # Check for distinct data points after scaling
    # This is critical because scaling can make identical patterns collapse to identical rows
    n_distinct <- nrow(unique(scaled_data))
    
    if (n_distinct < 2) {
      showNotification(
        paste0("Only ", n_distinct, " distinct data point(s) after scaling. ",
               "All features may have identical expression patterns. ",
               "Try disabling 'Scale Data' or adjusting filters."),
        type = "warning", duration = 8
      )
      return(NULL)
    }
    
    # Calculate WSS for different k values
    # max_k must be less than n_distinct to avoid kmeans error
    max_k <- min(15, nrow(scaled_data) - 1, n_distinct - 1)
    
    if (max_k < 1) {
      showNotification("Not enough distinct data points for elbow analysis.", type = "warning")
      return(NULL)
    }
    
    wss <- tryCatch({
      sapply(1:max_k, function(k) {
        set.seed(123)
        km <- kmeans(scaled_data, centers = k, nstart = 10, iter.max = 50)
        km$tot.withinss
      })
    }, error = function(e) {
      showNotification(paste("Elbow calculation error:", e$message), type = "error")
      return(NULL)
    })
    
    if (is.null(wss)) return(NULL)
    
    data.frame(k = 1:max_k, wss = wss)
  })
  
  # Cluster info display
  output$kmeans_cluster_info <- renderUI({
    req(kmeans_result())
    km <- kmeans_result()
    n_features <- length(km$cluster_assignments)
    n_clusters <- input$kmeans_num_clusters
    
    tags$span(
      paste0(n_features, " features in ", n_clusters, " clusters"),
      style = "color: #6c757d; font-size: 0.9em;"
    )
  })
  
  # K-Means cluster plot
  output$kmeans_cluster_plot <- renderPlot({
    req(kmeans_result())
    
    km <- kmeans_result()
    scaled_data <- km$scaled_data
    clusters <- km$cluster_assignments
    n_clusters <- input$kmeans_num_clusters
    group_names <- colnames(scaled_data)
    
    # Set up plot grid
    ncol_plot <- input$kmeans_ncol
    nrow_plot <- ceiling(n_clusters / ncol_plot)
    
    par(mfrow = c(nrow_plot, ncol_plot), mar = c(5, 4, 3, 1), oma = c(0, 0, 2, 0))
    
    for (i in 1:n_clusters) {
      cluster_idx <- which(clusters == i)
      cluster_data <- scaled_data[cluster_idx, , drop = FALSE]
      n_in_cluster <- length(cluster_idx)
      
      # Determine y-axis range
      yrange <- range(cluster_data, na.rm = TRUE)
      yrange <- yrange + c(-0.5, 0.5) * diff(yrange) * 0.1
      
      # Initialize empty plot
      plot(1:length(group_names), rep(NA, length(group_names)), 
           type = "n", xlim = c(0.5, length(group_names) + 0.5), ylim = yrange,
           xlab = "", ylab = "log2(ratio)", xaxt = "n",
           main = paste0("subcluster_", i, ", ", n_in_cluster, " metabolites"),
           cex.main = input$kmeans_title_size / 12,
           cex.axis = input$kmeans_axis_text_size / 10)
      
      # Add x-axis labels
      axis(1, at = 1:length(group_names), labels = group_names, 
           las = 2, cex.axis = input$kmeans_axis_text_size / 10)
      
      # Draw baseline if requested
      if (input$kmeans_show_baseline) {
        abline(h = 0, col = input$kmeans_baseline_color, lwd = 1.5)
      }
      
      # Draw individual feature lines
      for (j in 1:nrow(cluster_data)) {
        lines(1:length(group_names), cluster_data[j, ], 
              col = adjustcolor(input$kmeans_line_color, alpha.f = input$kmeans_line_alpha), 
              lwd = 0.8)
      }
      
      # Draw cluster mean line if requested
      if (input$kmeans_show_mean && nrow(cluster_data) > 0) {
        cluster_mean <- colMeans(cluster_data, na.rm = TRUE)
        lines(1:length(group_names), cluster_mean, 
              col = input$kmeans_mean_color, lwd = 2.5)
        points(1:length(group_names), cluster_mean, 
               col = input$kmeans_mean_color, pch = 19, cex = 1.2)
      }
    }
    
    # Add overall title
    mtext("K-Means Clustering of Differential Features", outer = TRUE, cex = 1.2, font = 2)
    
  }, height = function() { input$kmeans_plot_height })
  
  # Elbow plot
  output$kmeans_elbow_plot <- renderPlot({
    req(kmeans_elbow_data())
    
    elbow_data <- kmeans_elbow_data()
    
    par(mar = c(5, 5, 4, 2))
    plot(elbow_data$k, elbow_data$wss, type = "b", pch = 19, 
         col = "steelblue", lwd = 2,
         xlab = "Number of Clusters (k)", 
         ylab = "Total Within-Cluster Sum of Squares",
         main = "Elbow Method for Optimal k",
         cex.main = 1.3, cex.lab = 1.1, cex.axis = 1)
    
    # Highlight current k
    current_k <- input$kmeans_num_clusters
    if (current_k <= max(elbow_data$k)) {
      points(current_k, elbow_data$wss[current_k], col = "red", pch = 19, cex = 2)
      text(current_k, elbow_data$wss[current_k], labels = paste("k =", current_k), 
           pos = 4, col = "red", font = 2)
    }
    
    grid(col = "gray90")
  })
  
  # Suggest optimal k button
  observeEvent(input$kmeans_suggest_k, {
    elbow_data <- kmeans_elbow_data()
    
    if (is.null(elbow_data)) {
      showNotification(
        "Cannot suggest k: not enough distinct data points. Try disabling 'Scale Data' or adjusting filters.",
        type = "warning", duration = 6
      )
      return()
    }
    
    wss <- elbow_data$wss
    
    # Use second derivative to find elbow (needs at least 3 points)
    if (length(wss) >= 3) {
      second_deriv <- diff(diff(wss))
      optimal_k <- which.max(second_deriv) + 1
      optimal_k <- max(2, min(optimal_k, length(wss)))
      
      updateNumericInput(session, "kmeans_num_clusters", value = optimal_k)
      showNotification(paste("Suggested optimal k =", optimal_k), type = "message")
    } else if (length(wss) == 2) {
      updateNumericInput(session, "kmeans_num_clusters", value = 2)
      showNotification("Only 2 distinct patterns available, setting k = 2", type = "message")
    } else {
      showNotification("Not enough distinct data points to suggest k.", type = "warning")
    }
  })
  
  # K-Means cluster table
  output$kmeans_cluster_table <- DT::renderDT({
    req(kmeans_result())
    
    km <- kmeans_result()
    
    df <- data.frame(
      Feature = km$feature_names,
      Cluster = km$cluster_assignments,
      stringsAsFactors = FALSE
    )
    
    # Add mean expression values per group
    for (col_name in colnames(km$original_data)) {
      df[[col_name]] <- round(km$original_data[, col_name], 4)
    }
    
    # Sort by cluster
    df <- df[order(df$Cluster), ]
    
    DT::datatable(df, 
                  options = list(pageLength = 25, scrollX = TRUE),
                  filter = "top",
                  rownames = FALSE) %>%
      DT::formatStyle("Cluster", 
                      backgroundColor = DT::styleEqual(
                        1:input$kmeans_num_clusters,
                        RColorBrewer::brewer.pal(min(input$kmeans_num_clusters, 9), "Set1")[1:min(input$kmeans_num_clusters, 9)]
                      ))
  })
  
  # K-Means summary table
  output$kmeans_summary_table <- DT::renderDT({
    req(kmeans_result())
    
    km <- kmeans_result()
    
    # Calculate cluster statistics
    cluster_stats <- lapply(1:input$kmeans_num_clusters, function(i) {
      idx <- which(km$cluster_assignments == i)
      cluster_data <- km$original_data[idx, , drop = FALSE]
      
      data.frame(
        Cluster = i,
        N_Features = length(idx),
        Mean_Expression = round(mean(cluster_data, na.rm = TRUE), 4),
        SD_Expression = round(sd(as.vector(cluster_data), na.rm = TRUE), 4),
        Min_Expression = round(min(cluster_data, na.rm = TRUE), 4),
        Max_Expression = round(max(cluster_data, na.rm = TRUE), 4)
      )
    })
    
    summary_df <- do.call(rbind, cluster_stats)
    
    DT::datatable(summary_df, 
                  options = list(pageLength = 20, dom = 't'),
                  rownames = FALSE)
  })
  
  # K-Means quality metrics
  output$kmeans_quality_metrics <- renderPrint({
    req(kmeans_result())
    
    km <- kmeans_result()$kmeans
    
    cat("K-Means Clustering Quality Metrics\n")
    cat("===================================\n\n")
    cat("Total Sum of Squares (TSS):", round(km$totss, 2), "\n")
    cat("Total Within-Cluster SS (WSS):", round(km$tot.withinss, 2), "\n")
    cat("Between-Cluster SS (BSS):", round(km$betweenss, 2), "\n")
    cat("BSS / TSS Ratio:", round(km$betweenss / km$totss * 100, 2), "%\n\n")
    cat("(Higher BSS/TSS ratio indicates better clustering)\n")
  })
  
  # Download K-Means plot
  output$download_kmeans_plot <- downloadHandler(
    filename = function() {
      paste0("kmeans_clusters_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      req(kmeans_result())
      
      km <- kmeans_result()
      scaled_data <- km$scaled_data
      clusters <- km$cluster_assignments
      n_clusters <- input$kmeans_num_clusters
      group_names <- colnames(scaled_data)
      
      ncol_plot <- input$kmeans_ncol
      nrow_plot <- ceiling(n_clusters / ncol_plot)

      dpi <- get_safe_global_dpi()
      scale <- dpi / 150
      png(file, width = round(400 * ncol_plot * scale), height = round(350 * nrow_plot * scale), res = dpi)
      
      par(mfrow = c(nrow_plot, ncol_plot), mar = c(5, 4, 3, 1), oma = c(0, 0, 2, 0))
      
      for (i in 1:n_clusters) {
        cluster_idx <- which(clusters == i)
        cluster_data <- scaled_data[cluster_idx, , drop = FALSE]
        n_in_cluster <- length(cluster_idx)
        
        yrange <- range(cluster_data, na.rm = TRUE)
        yrange <- yrange + c(-0.5, 0.5) * diff(yrange) * 0.1
        
        plot(1:length(group_names), rep(NA, length(group_names)), 
             type = "n", xlim = c(0.5, length(group_names) + 0.5), ylim = yrange,
             xlab = "", ylab = "log2(ratio)", xaxt = "n",
             main = paste0("subcluster_", i, ", ", n_in_cluster, " metabolites"))
        
        axis(1, at = 1:length(group_names), labels = group_names, las = 2)
        
        if (input$kmeans_show_baseline) {
          abline(h = 0, col = input$kmeans_baseline_color, lwd = 1.5)
        }
        
        for (j in 1:nrow(cluster_data)) {
          lines(1:length(group_names), cluster_data[j, ], 
                col = adjustcolor(input$kmeans_line_color, alpha.f = input$kmeans_line_alpha), lwd = 0.8)
        }
        
        if (input$kmeans_show_mean && nrow(cluster_data) > 0) {
          cluster_mean <- colMeans(cluster_data, na.rm = TRUE)
          lines(1:length(group_names), cluster_mean, col = input$kmeans_mean_color, lwd = 2.5)
          points(1:length(group_names), cluster_mean, col = input$kmeans_mean_color, pch = 19, cex = 1.2)
        }
      }
      
      mtext("K-Means Clustering of Differential Features", outer = TRUE, cex = 1.2, font = 2)
      
      dev.off()
    }
  )
  
  # Download K-Means table
  output$download_kmeans_table <- downloadHandler(
    filename = function() {
      paste0("kmeans_cluster_assignments_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(kmeans_result())
      
      km <- kmeans_result()
      
      df <- data.frame(
        Feature = km$feature_names,
        Cluster = km$cluster_assignments,
        stringsAsFactors = FALSE
      )
      
      for (col_name in colnames(km$original_data)) {
        df[[col_name]] <- round(km$original_data[, col_name], 4)
      }
      
      df <- df[order(df$Cluster), ]
      
      openxlsx::write.xlsx(df, file, rowNames = FALSE)
    }
  )
  
  # ============================================================================
  # END K-MEANS CLUSTERING ANALYSIS
  # ============================================================================
  
  # ============================================================================
  # FEATURE CORRELATION ANALYSIS
  # ============================================================================
  
  # Reactive to update correlation group selections
  observe({
    req(values$unique_groups)
    groups <- values$unique_groups
    updateSelectizeInput(session, "corr_group1", choices = groups, selected = groups[1])
    updateSelectizeInput(session, "corr_group2", choices = groups, selected = if(length(groups) > 1) groups[2] else groups[1])
  })
  
  # Toggle pairwise options visibility for correlation
  observe({
    if (input$corr_analysis_type == "pairwise") {
      shinyjs::show("corrPairwiseOptions")
    } else {
      shinyjs::hide("corrPairwiseOptions")
    }
  })
  
  # Grouping toggle UI for correlation
  output$corr_grouping_toggle_ui <- renderUI({
    req(values$has_dual_grouping)
    if (!values$has_dual_grouping) return(NULL)
    
    div(class = "grouping-toggle-container",
        style = "display: flex; align-items: center; gap: 10px; margin-bottom: 15px; padding: 10px; background: #f8f9fa; border-radius: 8px;",
        tags$span("View Results By:", style = "font-weight: 500; color: #495057;"),
        radioButtons("corr_grouping_level", NULL,
                     choices = c("Biological Groups" = "biological",
                                 "Experimental Groups" = "experimental"),
                     selected = values$active_grouping_level,
                     inline = TRUE)
    )
  })
  
  # Correlation feature set status
  output$corr_feature_set_status <- renderUI({
    source <- input$corr_feature_source
    if (is.null(source) || source == "all") return(NULL)
    
    if (source == "pca" && !is.null(values$selected_features$features) && values$selected_features$source == "pca") {
      n <- length(values$selected_features$features)
      tags$span(paste0("Using ", n, " PCA-selected features"), style = "color: #28a745; font-size: 0.85em;")
    } else if (source == "ml" && !is.null(values$selected_features$features) && values$selected_features$source == "ml") {
      n <- length(values$selected_features$features)
      tags$span(paste0("Using ", n, " ML-selected features"), style = "color: #28a745; font-size: 0.85em;")
    } else {
      tags$span("No features selected. Run PCA/ML first.", style = "color: #dc3545; font-size: 0.85em;")
    }
  })
  
  # Reactive for correlation filtered data
  corr_filtered_data <- reactive({
    req(values$normalized_data, values$stat_results)
    
    # Load visualization packages if needed
    load_package_group("visualization")
    
    stat_results <- get_active_stat_results()
    req(stat_results)
    
    normalized_data <- values$normalized_data
    
    # Determine which comparison to use
    if (input$corr_analysis_type == "pairwise") {
      req(input$corr_group1, input$corr_group2)
      comparison_name <- paste(input$corr_group1, "vs", input$corr_group2)
      
      # Use helper functions to find p-value and fold change columns
      pval_col <- get_appropriate_pvalue_column(comparison_name)
      fc_column_result <- get_foldchange_column(comparison_name)
      
      # Check if columns were found
      if (is.null(pval_col) || is.null(fc_column_result)) {
        showNotification("Could not find statistics for selected comparison.", type = "error")
        return(NULL)
      }
      
      # Handle reversed fold change columns
      is_reversed <- FALSE
      if (grepl("^REVERSED:", fc_column_result)) {
        is_reversed <- TRUE
        fc_col <- sub("^REVERSED:", "", fc_column_result)
      } else {
        fc_col <- fc_column_result
      }
      
      # Verify columns exist in stat_results
      if (!pval_col %in% colnames(stat_results) || !fc_col %in% colnames(stat_results)) {
        showNotification("Could not find statistics for selected comparison.", type = "error")
        return(NULL)
      }
      
      p_values <- stat_results[[pval_col]]
      log2_fc <- stat_results[[fc_col]]
      
      # Negate fold change if reversed
      if (is_reversed) {
        log2_fc <- -log2_fc
      }
      
      # Find FDR column if ROTS
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        fdr_col <- paste0(comparison_name, "_FDR")
        alt_comparison_name <- paste(input$corr_group2, "vs", input$corr_group1)
        alt_fdr_col <- paste0(alt_comparison_name, "_FDR")
        
        if (fdr_col %in% colnames(stat_results)) {
          fdr_values <- stat_results[[fdr_col]]
        } else if (alt_fdr_col %in% colnames(stat_results)) {
          fdr_values <- stat_results[[alt_fdr_col]]
        }
      }
      
      title <- paste0(input$corr_group1, " vs ", input$corr_group2)
      
    } else {
      # All groups - use helper function for global p-value
      pval_col <- get_appropriate_pvalue_column("Global")
      
      if (is.null(pval_col) || !pval_col %in% colnames(stat_results)) {
        showNotification("No statistical results found. Run analysis first.", type = "error")
        return(NULL)
      }
      
      p_values <- stat_results[[pval_col]]
      
      # Find all Log2FC columns for max calculation
      fc_col <- grep("_Log2FC$|Max_Log2FC", colnames(stat_results), value = TRUE)
      
      # Use maximum absolute log2FC
      if (length(fc_col) > 0) {
        log2_fc <- apply(abs(stat_results[, fc_col, drop = FALSE]), 1, max, na.rm = TRUE)
      } else {
        log2_fc <- rep(Inf, nrow(stat_results))  # No FC filter if not available
      }
      
      # Find FDR columns if ROTS
      fdr_values <- NULL
      if (input$sig_method == "rots") {
        fdr_col <- grep("_FDR$", colnames(stat_results), value = TRUE)
        if (length(fdr_col) > 0) {
          fdr_values <- apply(stat_results[, fdr_col, drop = FALSE], 1, min, na.rm = TRUE)
        }
      }
      
      title <- "All Groups"
    }
    
    # Apply filters
    filter_idx <- !is.na(p_values) & p_values < input$corr_pvalue_cutoff & 
                  !is.na(log2_fc) & abs(log2_fc) >= input$corr_fc_cutoff
    
    # Apply FDR filter if ROTS
    if (input$sig_method == "rots" && !is.null(fdr_values)) {
      fdr_cutoff <- input$corr_fdr_cutoff %||% 0.05
      filter_idx <- filter_idx & !is.na(fdr_values) & fdr_values < fdr_cutoff
    }
    
    # Apply feature source filter
    if (input$corr_feature_source != "all" && !is.null(values$selected_features$features)) {
      if (input$corr_feature_source == values$selected_features$source) {
        feature_idx <- which(values$cleaned_molecules %in% values$selected_features$features)
        filter_idx <- filter_idx & (seq_along(filter_idx) %in% feature_idx)
      }
    }
    
    significant_idx <- which(filter_idx)
    
    # Limit to max features, sorted by p-value
    if (length(significant_idx) > input$corr_max_features) {
      sorted_idx <- significant_idx[order(p_values[significant_idx])]
      significant_idx <- sorted_idx[1:input$corr_max_features]
    }
    
    if (length(significant_idx) < 3) {
      showNotification("Not enough significant features for correlation (need at least 3).", type = "warning")
      return(NULL)
    }
    
    # Get data for significant features
    filtered_data <- normalized_data[significant_idx, , drop = FALSE]
    
    # Use cleaned molecule names as row names
    if (!is.null(values$cleaned_molecules)) {
      rownames(filtered_data) <- make.unique(values$cleaned_molecules[significant_idx])
    }
    
    # Keep only numeric columns for correlation
    num_cols <- which(sapply(seq_len(ncol(filtered_data)), function(j) is.numeric(filtered_data[, j])))
    if (length(num_cols) == 0) {
      showNotification("No numeric columns in data for correlation.", type = "error")
      return(NULL)
    }
    filtered_data <- filtered_data[, num_cols, drop = FALSE]
    
    list(
      data = filtered_data,
      significant_idx = significant_idx,
      n_features = length(significant_idx),
      title = title
    )
  })
  
  # Reactive for correlation matrix
  corr_matrix_data <- reactive({
    req(corr_filtered_data())
    
    data_list <- corr_filtered_data()
    filtered_data <- data_list$data
    # Ensure numeric matrix for cor()
    if (!is.numeric(as.matrix(filtered_data))) {
      filtered_data <- as.matrix(filtered_data)
      storage.mode(filtered_data) <- "double"
    }
    
    # Calculate correlation matrix
    cor_matrix <- cor(t(filtered_data), method = input$corr_method, use = "pairwise.complete.obs")
    
    # Calculate p-values for correlations
    n <- ncol(filtered_data)
    p_matrix <- matrix(NA, nrow = nrow(cor_matrix), ncol = ncol(cor_matrix))
    
    for (i in 1:(nrow(cor_matrix) - 1)) {
      for (j in (i + 1):ncol(cor_matrix)) {
        test <- tryCatch({
          cor.test(filtered_data[i, ], filtered_data[j, ], method = input$corr_method)
        }, error = function(e) NULL)
        
        if (!is.null(test)) {
          p_matrix[i, j] <- test$p.value
          p_matrix[j, i] <- test$p.value
        }
      }
    }
    
    list(
      cor_matrix = cor_matrix,
      p_matrix = p_matrix,
      feature_names = rownames(filtered_data),
      title = data_list$title,
      n_features = data_list$n_features
    )
  })
  
  # Correlation plot info
  output$corr_plot_info <- renderUI({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    
    tags$span(
      paste0(data$n_features, " features | ", data$title),
      style = "color: #6c757d; font-size: 0.9em;"
    )
  })
  
  # Correlation matrix plot
  output$corr_matrix_plot <- renderPlot({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    p_matrix <- data$p_matrix
    
    if (nrow(cor_matrix) < 2 || ncol(cor_matrix) < 2) {
      plot.new()
      title(main = data$title)
      text(0.5, 0.5, "Need at least 2 features to plot correlation matrix.", cex = 1.2)
      return(invisible(NULL))
    }
    
    # Replace NA for plotting (avoid corrplot coordinate errors)
    cor_matrix[!is.finite(cor_matrix)] <- 0
    
    # Apply threshold
    if (input$corr_threshold > 0) {
      cor_matrix[abs(cor_matrix) < input$corr_threshold] <- 0
    }
    
    # Set up color palette
    col_palette <- colorRampPalette(rev(RColorBrewer::brewer.pal(11, input$corr_color_scheme)))(200)
    
    # Determine plot type
    plot_type <- switch(input$corr_plot_type,
                        "lower" = "lower",
                        "upper" = "upper",
                        "full" = "full")
    
    # Build plot args; avoid addCoef + sig labelling on very small matrices to prevent "no coordinates" errors
    n <- nrow(cor_matrix)
    show_vals <- input$corr_show_values && n <= 50
    show_sig <- input$corr_show_sig && n <= 80
    
    plot_call <- function(add_coef = show_vals, pmat = if (show_sig) p_matrix else NULL) {
      corrplot::corrplot(
        cor_matrix,
        method = input$corr_shape,
        type = plot_type,
        col = col_palette,
        tl.col = "black",
        tl.srt = 45,
        tl.cex = input$corr_label_size / 10,
        addCoef.col = if (add_coef) "black" else NULL,
        number.cex = input$corr_value_size / 10,
        p.mat = pmat,
        sig.level = 0.05,
        insig = if (!is.null(pmat)) "label_sig" else "n",
        pch.cex = 0.8,
        title = data$title,
        mar = c(0, 0, 2, 0),
        diag = FALSE
      )
    }
    
    tryCatch(plot_call(), error = function(e) {
      # Fallback: no coefficients to avoid place_points "no coordinates" error
      tryCatch(plot_call(add_coef = FALSE, pmat = NULL), error = function(e2) {
        plot.new()
        title(main = data$title)
        text(0.5, 0.5, paste0("Could not draw corrplot: ", e2$message), cex = 0.9)
      })
    })
  }, height = function() { input$corr_plot_height }, width = function() { input$corr_plot_height })
  
  # Correlation pairwise table
  output$corr_pairwise_table <- DT::renderDT({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    p_matrix <- data$p_matrix
    feature_names <- data$feature_names
    
    # Convert to pairwise data frame
    pairs_list <- list()
    idx <- 1
    
    for (i in 1:(nrow(cor_matrix) - 1)) {
      for (j in (i + 1):ncol(cor_matrix)) {
        pairs_list[[idx]] <- data.frame(
          Feature_1 = feature_names[i],
          Feature_2 = feature_names[j],
          Correlation = round(cor_matrix[i, j], 4),
          P_Value = if (!is.na(p_matrix[i, j])) signif(p_matrix[i, j], 4) else NA,
          stringsAsFactors = FALSE
        )
        idx <- idx + 1
      }
    }
    
    pairs_df <- do.call(rbind, pairs_list)
    pairs_df <- pairs_df[order(abs(pairs_df$Correlation), decreasing = TRUE), ]
    
    # Apply threshold filter
    if (input$corr_threshold > 0) {
      pairs_df <- pairs_df[abs(pairs_df$Correlation) >= input$corr_threshold, ]
    }
    
    DT::datatable(pairs_df, 
                  options = list(pageLength = 25, scrollX = TRUE),
                  filter = "top",
                  rownames = FALSE) %>%
      DT::formatStyle("Correlation",
                      background = DT::styleColorBar(range(pairs_df$Correlation), "steelblue"),
                      backgroundSize = "98% 88%",
                      backgroundRepeat = "no-repeat",
                      backgroundPosition = "center")
  })
  
  # Correlation histogram
  output$corr_histogram <- renderPlot({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    
    # Get lower triangle values (excluding diagonal)
    lower_tri <- cor_matrix[lower.tri(cor_matrix)]
    
    hist(lower_tri, breaks = 30, col = "steelblue", border = "white",
         main = "Distribution of Correlations",
         xlab = "Correlation Coefficient", ylab = "Frequency",
         xlim = c(-1, 1))
    abline(v = 0, col = "red", lwd = 2, lty = 2)
    abline(v = c(-input$corr_threshold, input$corr_threshold), 
           col = "orange", lwd = 1.5, lty = 2)
  })
  
  # Correlation summary stats
  output$corr_summary_stats <- renderPrint({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    
    lower_tri <- cor_matrix[lower.tri(cor_matrix)]
    
    cat("Correlation Summary Statistics\n")
    cat("==============================\n\n")
    cat("Number of feature pairs:", length(lower_tri), "\n")
    cat("Mean correlation:", round(mean(lower_tri, na.rm = TRUE), 4), "\n")
    cat("Median correlation:", round(median(lower_tri, na.rm = TRUE), 4), "\n")
    cat("SD of correlations:", round(sd(lower_tri, na.rm = TRUE), 4), "\n")
    cat("Range:", round(min(lower_tri, na.rm = TRUE), 4), "to", round(max(lower_tri, na.rm = TRUE), 4), "\n\n")
    cat("Strong positive (r > 0.7):", sum(lower_tri > 0.7, na.rm = TRUE), "\n")
    cat("Strong negative (r < -0.7):", sum(lower_tri < -0.7, na.rm = TRUE), "\n")
    cat("Moderate (|r| 0.4-0.7):", sum(abs(lower_tri) >= 0.4 & abs(lower_tri) <= 0.7, na.rm = TRUE), "\n")
    cat("Weak (|r| < 0.4):", sum(abs(lower_tri) < 0.4, na.rm = TRUE), "\n")
  })
  
  # Top positive correlations
  output$corr_top_positive <- DT::renderDT({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    feature_names <- data$feature_names
    
    pairs_list <- list()
    idx <- 1
    
    for (i in 1:(nrow(cor_matrix) - 1)) {
      for (j in (i + 1):ncol(cor_matrix)) {
        if (!is.na(cor_matrix[i, j]) && cor_matrix[i, j] > 0) {
          pairs_list[[idx]] <- data.frame(
            Feature_1 = feature_names[i],
            Feature_2 = feature_names[j],
            Correlation = round(cor_matrix[i, j], 4),
            stringsAsFactors = FALSE
          )
          idx <- idx + 1
        }
      }
    }
    
    if (length(pairs_list) == 0) return(NULL)
    
    pairs_df <- do.call(rbind, pairs_list)
    pairs_df <- head(pairs_df[order(pairs_df$Correlation, decreasing = TRUE), ], 10)
    
    DT::datatable(pairs_df, options = list(pageLength = 10, dom = 't'), rownames = FALSE)
  })
  
  # Top negative correlations
  output$corr_top_negative <- DT::renderDT({
    req(corr_matrix_data())
    
    data <- corr_matrix_data()
    cor_matrix <- data$cor_matrix
    feature_names <- data$feature_names
    
    pairs_list <- list()
    idx <- 1
    
    for (i in 1:(nrow(cor_matrix) - 1)) {
      for (j in (i + 1):ncol(cor_matrix)) {
        if (!is.na(cor_matrix[i, j]) && cor_matrix[i, j] < 0) {
          pairs_list[[idx]] <- data.frame(
            Feature_1 = feature_names[i],
            Feature_2 = feature_names[j],
            Correlation = round(cor_matrix[i, j], 4),
            stringsAsFactors = FALSE
          )
          idx <- idx + 1
        }
      }
    }
    
    if (length(pairs_list) == 0) return(NULL)
    
    pairs_df <- do.call(rbind, pairs_list)
    pairs_df <- head(pairs_df[order(pairs_df$Correlation), ], 10)
    
    DT::datatable(pairs_df, options = list(pageLength = 10, dom = 't'), rownames = FALSE)
  })
  
  # Download correlation plot
  output$download_corr_plot <- downloadHandler(
    filename = function() {
      paste0("feature_correlation_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".png")
    },
    content = function(file) {
      req(corr_matrix_data())
      
      data <- corr_matrix_data()
      cor_matrix <- data$cor_matrix
      p_matrix <- data$p_matrix
      
      if (nrow(cor_matrix) < 2 || ncol(cor_matrix) < 2) {
        showNotification("Need at least 2 features to download correlation plot.", type = "warning")
        return(NULL)
      }
      
      if (input$corr_threshold > 0) {
        cor_matrix[abs(cor_matrix) < input$corr_threshold] <- 0
      }
      
      col_palette <- colorRampPalette(rev(RColorBrewer::brewer.pal(11, input$corr_color_scheme)))(200)
      
      plot_type <- switch(input$corr_plot_type,
                          "lower" = "lower",
                          "upper" = "upper",
                          "full" = "full")

      dpi <- get_safe_global_dpi()
      
      # Convert UI plot height (pixels) to inches for PNG export
      # UI uses 72 DPI for screen display, so convert to inches then scale by actual DPI
      height_inches <- input$corr_plot_height / 72
      # For square corrplot, width equals height
      width_inches <- height_inches
      
      # Replace NA for plotting (avoid corrplot coordinate errors)
      cor_matrix[!is.finite(cor_matrix)] <- 0
      
      # Determine if we should show values and significance
      n <- nrow(cor_matrix)
      show_vals <- input$corr_show_values && n <= 50
      show_sig <- input$corr_show_sig && n <= 80
      
      # Adjust label size if too large
      label_cex <- min(input$corr_label_size / 10, 1.2)
      value_cex <- min(input$corr_value_size / 10, 0.8)
      
      png(file, width = width_inches, height = height_inches, units = "in", res = dpi)
      
      # Clear any existing plot state
      plot.new()
      
      tryCatch({
        corrplot::corrplot(
          cor_matrix,
          method = input$corr_shape,
          type = plot_type,
          col = col_palette,
          tl.col = "black",
          tl.srt = 45,
          tl.cex = label_cex,
          addCoef.col = if (show_vals) "black" else NULL,
          number.cex = value_cex,
          p.mat = if (show_sig) p_matrix else NULL,
          sig.level = 0.05,
          insig = if (show_sig && !is.null(p_matrix)) "label_sig" else "n",
          pch.cex = 0.8,
          title = data$title,
          mar = c(0, 0, 2, 0),
          diag = FALSE
        )
      }, error = function(e) {
        # Fallback: try without coefficients and significance
        tryCatch({
          corrplot::corrplot(
            cor_matrix,
            method = input$corr_shape,
            type = plot_type,
            col = col_palette,
            tl.col = "black",
            tl.srt = 45,
            tl.cex = label_cex,
            addCoef.col = NULL,
            p.mat = NULL,
            title = data$title,
            mar = c(0, 0, 2, 0),
            diag = FALSE
          )
        }, error = function(e2) {
          # Final fallback: simple plot
          plot.new()
          title(main = data$title)
          text(0.5, 0.5, paste0("Could not draw corrplot: ", e2$message), cex = 0.9)
        })
      })
      
      dev.off()
    }
  )
  
  # Download correlation table
  output$download_corr_table <- downloadHandler(
    filename = function() {
      paste0("feature_correlations_", format(Sys.time(), "%Y%m%d_%H%M%S"), ".xlsx")
    },
    content = function(file) {
      req(corr_matrix_data())
      
      data <- corr_matrix_data()
      cor_matrix <- data$cor_matrix
      p_matrix <- data$p_matrix
      feature_names <- data$feature_names
      
      pairs_list <- list()
      idx <- 1
      
      for (i in 1:(nrow(cor_matrix) - 1)) {
        for (j in (i + 1):ncol(cor_matrix)) {
          pairs_list[[idx]] <- data.frame(
            Feature_1 = feature_names[i],
            Feature_2 = feature_names[j],
            Correlation = round(cor_matrix[i, j], 4),
            P_Value = if (!is.na(p_matrix[i, j])) signif(p_matrix[i, j], 4) else NA,
            stringsAsFactors = FALSE
          )
          idx <- idx + 1
        }
      }
      
      pairs_df <- do.call(rbind, pairs_list)
      pairs_df <- pairs_df[order(abs(pairs_df$Correlation), decreasing = TRUE), ]
      
      openxlsx::write.xlsx(pairs_df, file, rowNames = FALSE)
    }
  )
  
  # ============================================================================
  # END FEATURE CORRELATION ANALYSIS
  # ============================================================================
  
  # ============================================================================
  # WGCNA NETWORK ANALYSIS
  # ============================================================================
  
  # Reactive values for WGCNA
  wgcna_vals <- reactiveValues(
    expression_data = NULL,   # Transposed expression matrix (samples x features)
    sample_tree = NULL,       # Sample clustering dendrogram
    sft = NULL,               # Soft threshold results
    chosen_power = NULL,      # Selected soft threshold power
    adjacency = NULL,         # Adjacency matrix
    tom = NULL,               # Topological Overlap Matrix
    gene_tree = NULL,         # Gene dendrogram
    module_colors = NULL,     # Original module color assignments
    merged_colors = NULL,     # Merged module color assignments
    merged_MEs = NULL,        # Merged module eigengenes
    module_trait_cor = NULL,   # Module-trait correlation matrix
    module_trait_pval = NULL,  # Module-trait p-value matrix
    trait_data = NULL,         # Numeric trait data frame
    gene_module_membership = NULL,   # Gene module membership values
    gene_trait_significance = NULL,  # Gene trait significance values
    hub_genes = NULL,         # Hub genes per module
    all_genes_modules = NULL, # All gene-module assignments
    status = NULL             # Status message
  )
  
  # Dynamic UI: trait column selector (when metadata is chosen)
  output$wgcna_trait_columns_ui <- renderUI({
    req(values$normalized_data)
    # Try to get metadata columns from the data
    meta_cols <- character(0)
    if (!is.null(values$uploaded_data)) {
      # Look for non-numeric columns or known metadata columns
      all_cols <- colnames(values$uploaded_data)
      meta_cols <- all_cols[1:min(5, length(all_cols))]
    }
    selectizeInput("wgcna_trait_columns", "Select Trait Columns:",
                   choices = meta_cols, multiple = TRUE, width = "100%",
                   options = list(placeholder = "Select trait columns..."))
  })
  
  # ---- Main WGCNA computation ----
  observeEvent(input$run_wgcna, {
    req(values$normalized_data)
    
    # Load network packages on demand
    load_package_group("network")
    load_package_group("visualization")
    
    showNotification("Starting WGCNA analysis...", type = "message", duration = 3)
    
    tryCatch({
      # ------------------------------------------------------------------
      # 1. Prepare expression data (samples as rows, features as columns)
      # ------------------------------------------------------------------
      norm_data <- values$normalized_data
      
      if (is.null(norm_data) || ncol(norm_data) == 0 || nrow(norm_data) == 0) {
        showNotification("No normalized data available. Please process data first.", type = "error")
        return()
      }
      
      # Transpose: WGCNA expects samples in rows, genes/features in columns
      expr_data <- as.data.frame(t(norm_data))
      
      # Variance filter: keep top N% most variable features
      var_pct <- input$wgcna_variance_filter %||% 75
      if (var_pct < 100) {
        feature_vars <- apply(norm_data, 1, var, na.rm = TRUE)
        keep_n <- max(10, ceiling(length(feature_vars) * var_pct / 100))
        top_features <- names(sort(feature_vars, decreasing = TRUE))[1:min(keep_n, length(feature_vars))]
        expr_data <- expr_data[, top_features, drop = FALSE]
      }
      
      # Check sample count
      if (nrow(expr_data) < 6) {
        showNotification("WGCNA requires at least 6 samples. Your dataset has fewer.", type = "error")
        return()
      }
      
      # Remove features with too many missing values using WGCNA's goodSamplesGenes
      gsg <- WGCNA::goodSamplesGenes(expr_data, verbose = 0)
      if (!gsg$allOK) {
        expr_data <- expr_data[gsg$goodSamples, gsg$goodGenes, drop = FALSE]
        showNotification(paste("Removed", sum(!gsg$goodGenes), "features and", 
                               sum(!gsg$goodSamples), "samples with too many missing values."),
                         type = "warning", duration = 5)
      }
      
      wgcna_vals$expression_data <- expr_data
      
      # ------------------------------------------------------------------
      # 2. Sample clustering to detect outliers
      # ------------------------------------------------------------------
      sample_tree <- hclust(dist(expr_data), method = "average")
      wgcna_vals$sample_tree <- sample_tree
      
      # ------------------------------------------------------------------
      # 3. Soft threshold power selection
      # ------------------------------------------------------------------
      withProgress(message = "Picking soft threshold...", value = 0.2, {
        
        # Determine network type
        net_type <- input$wgcna_network_type %||% "signed"
        
        powers <- c(seq(1, 10, by = 1), seq(12, 20, by = 2))
        sft <- WGCNA::pickSoftThreshold(expr_data, powerVector = powers,
                                         networkType = net_type, verbose = 0)
        wgcna_vals$sft <- sft
        
        # Auto-detect or use user-specified power
        user_power <- input$wgcna_soft_power %||% 0
        if (user_power > 0) {
          chosen_power <- user_power
        } else {
          # Use WGCNA's estimate, fallback to 6
          chosen_power <- if (!is.na(sft$powerEstimate)) sft$powerEstimate else 6
        }
        wgcna_vals$chosen_power <- chosen_power
        
        setProgress(0.3, detail = paste("Using power =", chosen_power))
      })
      
      # ------------------------------------------------------------------
      # 4. Network construction and module detection (blockwise for memory efficiency)
      # ------------------------------------------------------------------
      withProgress(message = "Building network & detecting modules...", value = 0.4, {
        
        net_type <- input$wgcna_network_type %||% "signed"
        tom_type <- input$wgcna_tom_type %||% "unsigned"
        min_mod_size <- input$wgcna_min_module_size %||% 30
        merge_height <- input$wgcna_merge_cut_height %||% 0.25
        deep_split <- input$wgcna_deep_split %||% 2
        power <- wgcna_vals$chosen_power
        
        # Use blockwiseModules for memory-efficient computation
        net <- WGCNA::blockwiseModules(
          expr_data,
          power = power,
          networkType = net_type,
          TOMType = tom_type,
          minModuleSize = min_mod_size,
          mergeCutHeight = merge_height,
          deepSplit = deep_split,
          reassignThreshold = 0,
          pamRespectsDendro = FALSE,
          numericLabels = TRUE,
          verbose = 0,
          maxBlockSize = ncol(expr_data)  # Process all at once if possible
        )
        
        setProgress(0.7, detail = "Processing modules...")
        
        # Convert numeric labels to colors
        merged_colors <- WGCNA::labels2colors(net$colors)
        wgcna_vals$merged_colors <- merged_colors
        
        # Store gene dendrogram (from first block)
        wgcna_vals$gene_tree <- net$dendrograms[[1]]
        
        # Module colors before merging (for comparison)
        wgcna_vals$module_colors <- WGCNA::labels2colors(net$unmergedColors)
        
        # Module eigengenes
        wgcna_vals$merged_MEs <- net$MEs
      })
      
      # ------------------------------------------------------------------
      # 5. Module-trait correlation
      # ------------------------------------------------------------------
      withProgress(message = "Computing trait associations...", value = 0.8, {
        
        merged_MEs <- WGCNA::orderMEs(wgcna_vals$merged_MEs)
        wgcna_vals$merged_MEs <- merged_MEs
        
        # Build trait data
        trait_source <- input$wgcna_trait_source %||% "groups"
        
        if (trait_source == "groups" && !is.null(values$unique_groups)) {
          # Create binary trait matrix from group assignments
          groups <- character(nrow(expr_data))
          sample_names <- rownames(expr_data)
          
          if (!is.null(values$group_column_indices)) {
            for (g in names(values$group_column_indices)) {
              col_names <- colnames(values$normalized_data)[values$group_column_indices[[g]]]
              groups[sample_names %in% col_names] <- g
            }
          }
          
          unique_grps <- unique(groups[groups != ""])
          if (length(unique_grps) >= 2) {
            trait_df <- data.frame(row.names = sample_names)
            for (g in unique_grps) {
              trait_df[[g]] <- as.numeric(groups == g)
            }
            wgcna_vals$trait_data <- trait_df
          }
        }
        
        if (!is.null(wgcna_vals$trait_data) && nrow(wgcna_vals$trait_data) > 0) {
          n_samples <- nrow(expr_data)
          cor_method <- input$wgcna_correlation_method %||% "pearson"
          
          if (cor_method == "spearman") {
            module_trait_cor <- cor(merged_MEs, wgcna_vals$trait_data, 
                                    use = "p", method = "spearman")
          } else {
            module_trait_cor <- cor(merged_MEs, wgcna_vals$trait_data, use = "p")
          }
          module_trait_pval <- WGCNA::corPvalueStudent(module_trait_cor, n_samples)
          
          wgcna_vals$module_trait_cor <- module_trait_cor
          wgcna_vals$module_trait_pval <- module_trait_pval
        }
        
        setProgress(0.9, detail = "Computing module membership...")
      })
      
      # ------------------------------------------------------------------
      # 6. Module membership & hub gene identification
      # ------------------------------------------------------------------
      withProgress(message = "Identifying hub genes...", value = 0.9, {
        
        merged_MEs <- wgcna_vals$merged_MEs
        merged_colors <- wgcna_vals$merged_colors
        
        # Gene module membership (correlation of each gene with each ME)
        gene_MM <- as.data.frame(cor(expr_data, merged_MEs, use = "p"))
        MM_pval <- as.data.frame(WGCNA::corPvalueStudent(as.matrix(gene_MM), nrow(expr_data)))
        
        mod_names <- gsub("^ME", "", colnames(merged_MEs))
        colnames(gene_MM) <- paste0("MM.", mod_names)
        colnames(MM_pval) <- paste0("p.MM.", mod_names)
        
        wgcna_vals$gene_module_membership <- gene_MM
        
        # Gene-trait significance (if traits available)
        if (!is.null(wgcna_vals$trait_data)) {
          gene_TS <- as.data.frame(cor(expr_data, wgcna_vals$trait_data, use = "p"))
          TS_pval <- as.data.frame(WGCNA::corPvalueStudent(as.matrix(gene_TS), nrow(expr_data)))
          colnames(gene_TS) <- paste0("GS.", colnames(wgcna_vals$trait_data))
          colnames(TS_pval) <- paste0("p.GS.", colnames(wgcna_vals$trait_data))
          wgcna_vals$gene_trait_significance <- gene_TS
        }
        
        # Build comprehensive gene-module table
        all_genes_df <- data.frame(
          Feature = colnames(expr_data),
          Module = merged_colors,
          stringsAsFactors = FALSE
        )
        
        # Add module membership for assigned module
        for (i in seq_len(nrow(all_genes_df))) {
          mod <- all_genes_df$Module[i]
          mm_col <- paste0("MM.", mod)
          if (mm_col %in% colnames(gene_MM)) {
            all_genes_df$ModuleMembership[i] <- gene_MM[i, mm_col]
          } else {
            all_genes_df$ModuleMembership[i] <- NA
          }
        }
        
        wgcna_vals$all_genes_modules <- all_genes_df
        
        # Identify hub genes per module
        top_n <- input$wgcna_hub_top_n %||% 10
        unique_mods <- unique(merged_colors[merged_colors != "grey"])
        
        hub_list <- list()
        for (mod in unique_mods) {
          mod_genes <- which(merged_colors == mod)
          mm_col <- paste0("MM.", mod)
          if (mm_col %in% colnames(gene_MM)) {
            mm_vals <- gene_MM[mod_genes, mm_col]
            names(mm_vals) <- colnames(expr_data)[mod_genes]
            top_idx <- head(order(abs(mm_vals), decreasing = TRUE), top_n)
            
            hub_df <- data.frame(
              Feature = names(mm_vals)[top_idx],
              Module = mod,
              ModuleMembership = round(mm_vals[top_idx], 4),
              stringsAsFactors = FALSE
            )
            
            # Add trait significance if available
            if (!is.null(wgcna_vals$gene_trait_significance)) {
              for (tc in colnames(wgcna_vals$gene_trait_significance)) {
                hub_df[[tc]] <- round(wgcna_vals$gene_trait_significance[colnames(expr_data)[mod_genes[top_idx]], tc], 4)
              }
            }
            
            hub_list[[mod]] <- hub_df
          }
        }
        
        wgcna_vals$hub_genes <- do.call(rbind, hub_list)
        
        # Update module selector
        updateSelectInput(session, "wgcna_hub_module_select",
                          choices = unique_mods,
                          selected = unique_mods[1])
        
        setProgress(1.0, detail = "Done!")
      })
      
      wgcna_vals$status <- "complete"
      showNotification("WGCNA analysis complete!", type = "message", duration = 5)
      
    }, error = function(e) {
      showNotification(paste("WGCNA Error:", e$message), type = "error", duration = 10)
      wgcna_vals$status <- paste("Error:", e$message)
    })
  })
  
  # ---- Render: Soft Threshold Plots ----
  output$wgcna_sft_r2_plot <- renderPlot({
    req(wgcna_vals$sft)
    sft <- wgcna_vals$sft
    fi <- sft$fitIndices
    title_size <- input$wgcna_title_size %||% 14
    text_size <- input$wgcna_axis_text_size %||% 10
    
    par(mar = c(5, 5, 3, 1))
    plot(fi[, 1], -sign(fi[, 3]) * fi[, 2],
         xlab = "Soft Threshold (power)",
         ylab = expression(paste("Scale Free Topology Model Fit, signed ", R^2)),
         type = "n",
         main = "Scale Independence",
         cex.main = title_size / 12, cex.lab = text_size / 10, cex.axis = text_size / 10)
    text(fi[, 1], -sign(fi[, 3]) * fi[, 2], labels = fi[, 1], col = "red",
         cex = text_size / 10)
    abline(h = 0.80, col = "red", lty = 2)
    
    # Mark chosen power
    if (!is.null(wgcna_vals$chosen_power)) {
      cp <- wgcna_vals$chosen_power
      idx <- which(fi[, 1] == cp)
      if (length(idx) > 0) {
        points(fi[idx, 1], -sign(fi[idx, 3]) * fi[idx, 2], 
               pch = 19, cex = 2, col = "blue")
      }
    }
  }, res = 120)
  
  output$wgcna_sft_connectivity_plot <- renderPlot({
    req(wgcna_vals$sft)
    sft <- wgcna_vals$sft
    fi <- sft$fitIndices
    title_size <- input$wgcna_title_size %||% 14
    text_size <- input$wgcna_axis_text_size %||% 10
    
    par(mar = c(5, 5, 3, 1))
    plot(fi[, 1], fi[, 5],
         xlab = "Soft Threshold (power)",
         ylab = "Mean Connectivity",
         type = "n",
         main = "Mean Connectivity",
         cex.main = title_size / 12, cex.lab = text_size / 10, cex.axis = text_size / 10)
    text(fi[, 1], fi[, 5], labels = fi[, 1], col = "red",
         cex = text_size / 10)
    
    if (!is.null(wgcna_vals$chosen_power)) {
      cp <- wgcna_vals$chosen_power
      idx <- which(fi[, 1] == cp)
      if (length(idx) > 0) {
        points(fi[idx, 1], fi[idx, 5], pch = 19, cex = 2, col = "blue")
      }
    }
  }, res = 120)
  
  output$wgcna_sft_summary <- renderPrint({
    req(wgcna_vals$sft, wgcna_vals$chosen_power)
    cat("Selected soft threshold power:", wgcna_vals$chosen_power, "\n")
    if (!is.na(wgcna_vals$sft$powerEstimate)) {
      cat("WGCNA auto-estimated power:", wgcna_vals$sft$powerEstimate, "\n")
    } else {
      cat("WGCNA could not auto-estimate power (no R^2 > 0.80). Using fallback.\n")
    }
    cat("\nFit indices:\n")
    print(wgcna_vals$sft$fitIndices[, c(1, 2, 5)])
  })
  
  # ---- Render: Sample Dendrogram ----
  output$wgcna_sample_dendrogram <- renderPlot({
    req(wgcna_vals$sample_tree)
    title_size <- input$wgcna_title_size %||% 14
    text_size <- input$wgcna_axis_text_size %||% 10
    
    par(cex = 0.6, mar = c(0, 4, 2, 0))
    plot(wgcna_vals$sample_tree,
         main = "Sample Clustering to Detect Outliers",
         sub = "", xlab = "",
         cex.lab = text_size / 10, cex.axis = text_size / 10,
         cex.main = title_size / 12)
  }, res = 120)
  
  output$wgcna_outlier_info <- renderPrint({
    req(wgcna_vals$expression_data)
    cat("Samples in WGCNA analysis:", nrow(wgcna_vals$expression_data), "\n")
    cat("Features in WGCNA analysis:", ncol(wgcna_vals$expression_data), "\n")
    cat("\nSample names:\n")
    cat(paste(rownames(wgcna_vals$expression_data), collapse = ", "), "\n")
  })
  
  # ---- Render: Gene Dendrogram with Module Colors ----
  output$wgcna_gene_dendrogram <- renderPlot({
    req(wgcna_vals$gene_tree, wgcna_vals$merged_colors)
    
    # blockwiseModules returns dendrograms for blocks; plot first block
    dendro <- wgcna_vals$gene_tree
    merged_cols <- wgcna_vals$merged_colors
    module_cols <- wgcna_vals$module_colors
    
    # Only use genes from the first block's dendrogram
    block_genes <- dendro$order
    if (length(block_genes) < length(merged_cols)) {
      merged_sub <- merged_cols[block_genes]
      module_sub <- module_cols[block_genes]
    } else {
      merged_sub <- merged_cols
      module_sub <- module_cols
    }
    
    WGCNA::plotDendroAndColors(dendro, 
                               cbind(module_sub, merged_sub),
                               c("Original", "Merged"),
                               dendroLabels = FALSE, hang = 0.03,
                               addGuide = TRUE, guideHang = 0.05,
                               main = "Gene Dendrogram and Module Colors")
  }, res = 120, height = 500)
  
  # Module summary table
  output$wgcna_module_summary_table <- DT::renderDataTable({
    req(wgcna_vals$merged_colors)
    
    mod_table <- as.data.frame(table(Module = wgcna_vals$merged_colors))
    colnames(mod_table) <- c("Module", "Gene_Count")
    mod_table <- mod_table[order(-mod_table$Gene_Count), ]
    
    DT::datatable(mod_table, rownames = FALSE,
                  options = list(pageLength = 25, dom = "tip"),
                  caption = "Number of features assigned to each module")
  })
  
  # ---- Render: Module-Trait Heatmap ----
  output$wgcna_module_trait_heatmap <- renderPlot({
    req(wgcna_vals$module_trait_cor, wgcna_vals$module_trait_pval)
    
    cor_mat <- wgcna_vals$module_trait_cor
    pval_mat <- wgcna_vals$module_trait_pval
    title_size <- input$wgcna_title_size %||% 14
    label_size <- input$wgcna_label_size %||% 8
    
    # Build text matrix with correlation and p-value
    text_matrix <- paste(signif(cor_mat, 2), "\n(",
                          signif(pval_mat, 1), ")", sep = "")
    dim(text_matrix) <- dim(cor_mat)
    
    par(mar = c(8, 10, 3, 2))
    WGCNA::labeledHeatmap(
      Matrix = cor_mat,
      xLabels = colnames(cor_mat),
      yLabels = rownames(cor_mat),
      ySymbols = rownames(cor_mat),
      colorLabels = FALSE,
      colors = WGCNA::blueWhiteRed(50),
      textMatrix = text_matrix,
      setStdMargins = FALSE,
      cex.text = label_size / 12,
      zlim = c(-1, 1),
      main = "Module-Trait Relationships",
      cex.main = title_size / 12
    )
  }, res = 120, height = 600)
  
  # ---- Render: Eigengene Network ----
  output$wgcna_eigengene_dendrogram <- renderPlot({
    req(wgcna_vals$merged_MEs)
    
    MEs <- wgcna_vals$merged_MEs
    # Add traits if available
    if (!is.null(wgcna_vals$trait_data)) {
      MET <- WGCNA::orderMEs(cbind(MEs, wgcna_vals$trait_data))
    } else {
      MET <- WGCNA::orderMEs(MEs)
    }
    
    par(cex = 0.9)
    WGCNA::plotEigengeneNetworks(MET, "Eigengene Dendrogram",
                                 marDendro = c(0, 4, 2, 0),
                                 plotHeatmaps = FALSE)
  }, res = 120, height = 400)
  
  output$wgcna_eigengene_heatmap <- renderPlot({
    req(wgcna_vals$merged_MEs)
    
    MEs <- wgcna_vals$merged_MEs
    if (!is.null(wgcna_vals$trait_data)) {
      MET <- WGCNA::orderMEs(cbind(MEs, wgcna_vals$trait_data))
    } else {
      MET <- WGCNA::orderMEs(MEs)
    }
    
    par(cex = 0.9, mar = c(6, 6, 2, 2))
    WGCNA::plotEigengeneNetworks(MET, "Eigengene Adjacency Heatmap",
                                 marHeatmap = c(6, 6, 2, 2),
                                 plotDendrograms = FALSE,
                                 xLabelsAngle = 90)
  }, res = 120, height = 400)
  
  # ---- Render: Hub Genes ----
  output$wgcna_module_membership_plot <- renderPlot({
    req(wgcna_vals$gene_module_membership, wgcna_vals$merged_colors,
        input$wgcna_hub_module_select)
    
    module <- input$wgcna_hub_module_select
    gene_MM <- wgcna_vals$gene_module_membership
    merged_colors <- wgcna_vals$merged_colors
    expr_data <- wgcna_vals$expression_data
    
    mm_col <- paste0("MM.", module)
    module_genes <- which(merged_colors == module)
    
    if (length(module_genes) < 2 || !(mm_col %in% colnames(gene_MM))) {
      plot.new()
      text(0.5, 0.5, "Not enough genes in this module", cex = 1.5)
      return()
    }
    
    mm_vals <- abs(gene_MM[module_genes, mm_col])
    
    # If trait significance available, plot MM vs GS
    if (!is.null(wgcna_vals$gene_trait_significance)) {
      gs_cols <- colnames(wgcna_vals$gene_trait_significance)
      gs_col <- gs_cols[1]  # Use first trait
      gs_vals <- abs(wgcna_vals$gene_trait_significance[module_genes, gs_col])
      
      title_size <- input$wgcna_title_size %||% 14
      text_size <- input$wgcna_axis_text_size %||% 10
      
      par(mar = c(5, 5, 3, 1))
      WGCNA::verboseScatterplot(
        mm_vals, gs_vals,
        xlab = paste("Module Membership in", module),
        ylab = paste("Gene Significance for", gsub("^GS\\.", "", gs_col)),
        main = paste("Module Membership vs. Gene Significance\n"),
        cex.main = title_size / 12,
        cex.lab = text_size / 10,
        cex.axis = text_size / 10,
        col = module
      )
    } else {
      # Just plot sorted module membership
      par(mar = c(5, 5, 3, 1))
      barplot(sort(mm_vals, decreasing = TRUE)[1:min(30, length(mm_vals))],
              main = paste("Top Module Membership -", module, "module"),
              ylab = "Module Membership (|kME|)",
              col = module, las = 2, cex.names = 0.7)
    }
  }, res = 120, height = 450)
  
  output$wgcna_hub_genes_table <- DT::renderDataTable({
    req(wgcna_vals$hub_genes, input$wgcna_hub_module_select)
    
    module <- input$wgcna_hub_module_select
    hub_df <- wgcna_vals$hub_genes
    hub_filtered <- hub_df[hub_df$Module == module, , drop = FALSE]
    hub_filtered <- hub_filtered[order(abs(hub_filtered$ModuleMembership), decreasing = TRUE), ]
    
    DT::datatable(hub_filtered, rownames = FALSE,
                  options = list(pageLength = 20, dom = "tip"),
                  caption = paste("Hub genes in the", module, "module"))
  })
  
  # ---- Render: All Module Assignments ----
  output$wgcna_all_modules_table <- DT::renderDataTable({
    req(wgcna_vals$all_genes_modules)
    
    df <- wgcna_vals$all_genes_modules
    df$ModuleMembership <- round(df$ModuleMembership, 4)
    df <- df[order(df$Module, -abs(df$ModuleMembership)), ]
    
    DT::datatable(df, rownames = FALSE,
                  options = list(pageLength = 50, dom = "lftipr",
                                 searchHighlight = TRUE),
                  filter = "top",
                  caption = "All features with module assignments and membership values")
  })
  
  # ---- Download Handlers ----
  output$download_wgcna_sft_plot <- downloadHandler(
    filename = function() paste0("WGCNA_soft_threshold_", Sys.Date(), ".pdf"),
    content = function(file) {
      req(wgcna_vals$sft)
      sft <- wgcna_vals$sft
      fi <- sft$fitIndices
      
      pdf(file, width = 12, height = 5)
      par(mfrow = c(1, 2), mar = c(5, 5, 3, 1))
      
      plot(fi[, 1], -sign(fi[, 3]) * fi[, 2],
           xlab = "Soft Threshold (power)", ylab = "Scale Free Topology Model Fit, signed R^2",
           type = "n", main = "Scale Independence")
      text(fi[, 1], -sign(fi[, 3]) * fi[, 2], labels = fi[, 1], col = "red")
      abline(h = 0.80, col = "red", lty = 2)
      
      plot(fi[, 1], fi[, 5],
           xlab = "Soft Threshold (power)", ylab = "Mean Connectivity",
           type = "n", main = "Mean Connectivity")
      text(fi[, 1], fi[, 5], labels = fi[, 1], col = "red")
      
      dev.off()
    }
  )
  
  output$download_wgcna_sample_dendro <- downloadHandler(
    filename = function() paste0("WGCNA_sample_dendrogram_", Sys.Date(), ".pdf"),
    content = function(file) {
      req(wgcna_vals$sample_tree)
      pdf(file, width = 12, height = 6)
      par(cex = 0.6, mar = c(0, 4, 2, 0))
      plot(wgcna_vals$sample_tree, main = "Sample Clustering to Detect Outliers",
           sub = "", xlab = "")
      dev.off()
    }
  )
  
  output$download_wgcna_dendro_colors <- downloadHandler(
    filename = function() paste0("WGCNA_module_dendrogram_", Sys.Date(), ".pdf"),
    content = function(file) {
      req(wgcna_vals$gene_tree, wgcna_vals$merged_colors)
      pdf(file, width = 14, height = 7)
      dendro <- wgcna_vals$gene_tree
      merged_cols <- wgcna_vals$merged_colors
      module_cols <- wgcna_vals$module_colors
      block_genes <- dendro$order
      if (length(block_genes) < length(merged_cols)) {
        merged_sub <- merged_cols[block_genes]
        module_sub <- module_cols[block_genes]
      } else {
        merged_sub <- merged_cols
        module_sub <- module_cols
      }
      WGCNA::plotDendroAndColors(dendro, cbind(module_sub, merged_sub),
                                  c("Original", "Merged"),
                                  dendroLabels = FALSE, hang = 0.03,
                                  addGuide = TRUE, guideHang = 0.05,
                                  main = "Gene Dendrogram and Module Colors")
      dev.off()
    }
  )
  
  output$download_wgcna_trait_heatmap <- downloadHandler(
    filename = function() paste0("WGCNA_module_trait_heatmap_", Sys.Date(), ".pdf"),
    content = function(file) {
      req(wgcna_vals$module_trait_cor, wgcna_vals$module_trait_pval)
      cor_mat <- wgcna_vals$module_trait_cor
      pval_mat <- wgcna_vals$module_trait_pval
      text_matrix <- paste(signif(cor_mat, 2), "\n(", signif(pval_mat, 1), ")", sep = "")
      dim(text_matrix) <- dim(cor_mat)
      
      pdf(file, width = 10, height = 8)
      par(mar = c(8, 10, 3, 2))
      WGCNA::labeledHeatmap(Matrix = cor_mat,
                             xLabels = colnames(cor_mat), yLabels = rownames(cor_mat),
                             ySymbols = rownames(cor_mat), colorLabels = FALSE,
                             colors = WGCNA::blueWhiteRed(50),
                             textMatrix = text_matrix, setStdMargins = FALSE,
                             cex.text = 0.5, zlim = c(-1, 1),
                             main = "Module-Trait Relationships")
      dev.off()
    }
  )
  
  output$download_wgcna_eigengene_net <- downloadHandler(
    filename = function() paste0("WGCNA_eigengene_network_", Sys.Date(), ".pdf"),
    content = function(file) {
      req(wgcna_vals$merged_MEs)
      MEs <- wgcna_vals$merged_MEs
      if (!is.null(wgcna_vals$trait_data)) {
        MET <- WGCNA::orderMEs(cbind(MEs, wgcna_vals$trait_data))
      } else {
        MET <- WGCNA::orderMEs(MEs)
      }
      pdf(file, width = 12, height = 6)
      par(cex = 0.9)
      WGCNA::plotEigengeneNetworks(MET, "",
                                    marDendro = c(0, 4, 1, 2),
                                    marHeatmap = c(5, 4, 1, 2),
                                    cex.lab = 0.8, xLabelsAngle = 90)
      dev.off()
    }
  )
  
  output$download_wgcna_hub_genes <- downloadHandler(
    filename = function() paste0("WGCNA_hub_genes_", Sys.Date(), ".xlsx"),
    content = function(file) {
      req(wgcna_vals$hub_genes)
      openxlsx::write.xlsx(wgcna_vals$hub_genes, file, rowNames = FALSE)
    }
  )
  
  output$download_wgcna_all_modules <- downloadHandler(
    filename = function() paste0("WGCNA_all_module_assignments_", Sys.Date(), ".xlsx"),
    content = function(file) {
      req(wgcna_vals$all_genes_modules)
      openxlsx::write.xlsx(wgcna_vals$all_genes_modules, file, rowNames = FALSE)
    }
  )
  
  # ============================================================================
  # END WGCNA NETWORK ANALYSIS
  # ============================================================================
  
} # Close the server function
